-- Sources: data/i18n/deDE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["npc:demisette-cloyce"] = {n="Demisette Cloyce",s="Demisette Cloyce ist eine menschliche Hexenmeisterlehrerin, die in den unterirdischen Krypten unterhalb von Zum Geschlachteten Lamm im Magierviertel von Sturmwind verborgen lebt. Sie operiert im Verborgenen unter der Stadt, unterrichtet Praktizierende der Teufelsmagie und lenkt vielversprechende Akolythen auf den Pfad zu tieferen, gefährlicheren arkanen Mysterien.",h="Demisette Cloyce ist eine menschliche Hexenmeisterlehrerin, die in den unterirdischen Krypten unterhalb von...",kw={"cloyce","demisette","das magierviertel","menara leerbringer","slaughtered lamb","sturmwind","hexenmeisterlehrer"},ang={["class:Warlock"]="Demisette ist eine wichtige Kontaktperson während der Ausbildung eines Akolythen in Sturmwind; sie bietet grundlegenden Unterricht in Zauberkunde und sendet Hexenmeister später auf den Pfad, ihre Teufelsrösser zu beanspruchen und dämonische Sphären zu binden.",["race:Human"]="Versteckt unter der Hauptstadt der menschlichen Zivilisation verkörpert Cloyce den stillen, gefährlichen Rand der Menschheit, der das Heilige Licht aufgibt, um dämonische Macht auszuüben."},sec={{t="Die Krypten von Zum Geschlachteten Lamm",b="Während die Autoritäten von Sturmwind nach außen hin den Anschein von Ordnung und heiliger Rechtschaffenheit wahren, versammeln sich Praktizierende der Teufelsmagie in den feuchten Kellern unterhalb von Zum Geschlachteten Lamm im Magierviertel. Demisette Cloyce hat ihren Wohnsitz in diesen Katakomben und unterrichtet Hexenmeister, die bereit sind, sich den verbotenen Künsten zu widmen. Sie hat wenig Geduld für Unausgebildete oder Uneingeweihte und rät ihren Schülern, dass die dunklen Energien nur diejenigen verderben, denen die Disziplin fehlt, sie zu meistern."},{t="Verbindung der Zirkel",b="Demisette ist weit mehr als eine einfache Zauberlehrerin; sie dient als essenzieller Knotenpunkt für die Operationen von Hexenmeistern in ganz Azeroth. Sobald ein Akolyth ausreichende Meisterschaft erreicht, schickt sie ihn weit über die Mauern von Sturmwind hinaus – sie verbindet ihn mit mächtigen Beschwörern wie Menara Leerbringer im Brachland, damit er dort mächtige Artefakte nutzen und furchteinflößende Teufelsrösser binden kann."}},faq={{q="Wer ist Demisette Cloyce?",a="Demisette Cloyce ist eine menschliche Hexenmeisterlehrerin, die im Keller unterhalb der Taverne Zum Geschlachteten Lamm im Magierviertel von Sturmwind ansässig ist. Sie unterrichtet aufstrebende Hexenmeister in dämonischer Beschwörung und dunklen Zaubern.",al={"wer ist demisette","demisette cloyce hintergrundgeschichte","wer ist demisette cloyce"}},{q="Warum versteckt sie sich in einem Tavernenkeller?",a="Der Hexenmeisterzirkel versammelt sich im unterirdischen Keller von Zum Geschlachteten Lamm, fernab der Öffentlichkeit. Ihre dunklen Praktiken machen die Taverne zu einem diskreten Treffpunkt.",al={"warum ist sie im keller","warum zum geschlachteten lamm","keller von zum geschlachteten lamm"}},{q="Was ist ihre Verbindung zum Brachland?",a="Demisette schickt erfahrene Hexenmeister über das Meer, um Menara Leerbringer aufzusuchen, eine mächtige Beschwörerin, die in Ratschet an der Küste des Brachlands stationiert ist, um dort fortgeschrittene Rituale, mächtige Sphären und Bindungsriten zu verfolgen.",al={"demisette brachland","auf der suche nach menara leerbringer","verbindung zu menara leerbringer"}},{q="Wie reagiert sie auf Nicht-Hexenmeister?",a="Demisette hegt völlige Verachtung für Außenstehende. Sofern Ihr nicht den Pfad eines Hexenmeisters beschreitet, warnt sie Euch, dass die Dunkelheit Euch nicht willkommen heißt, und befiehlt Euch, Euer Geschwätz zu beenden und ihre Gegenwart zu verlassen.",al={"demisette dialog","gespräch mit demisette"}}},fx={["9bf7bbcc"]={q="Auf wessen Seite steht Demisette Cloyce?",a="Demisette Cloyce ist der Allianz treu ergeben und hält sich sicher in Sturmwind auf. Obwohl sie zusammen mit anderen Hexenmeistern in den Katakomben unter The Slaughtered Lamb im Verborgenen arbeitet, gilt ihre Loyalität der Ausbildung und Stärkung von Praktizierenden, die Sturmwind ergeben sind, anstatt feindseligen Kulten oder der Burning Blade.",al={"fraktion von demisette cloyce","gehört demisette cloyce zur allianz","wem dient demisette"}},["5142027a"]={q="Was will Demisette Cloyce?",a="Demisette möchte vielversprechende Hexenmeister dabei anleiten, gefährliche Teufelsmagie zu beherrschen, ohne der Verderbnis zu erliegen. Sie verweist Praktizierende auf uralte Artefakte und mächtige Lehrmeister in aller Welt – bis hin nach Kalimdor – in der Überzeugung, dass nur willensstarke Schüler dunkle Hexerei effektiv nutzen können, ohne ein vorzeitiges, ruinöses Ende zu finden.",al={"beweggründe von demisette cloyce","ziel von demisette cloyce","was will demisette"}}},fp="16,311,34.482.0,21.353.0,24.211.0,37.167.0,38.214.0,35.198.0"}
P.entries["npc:denalan"] = {n="Denalan",s="Denalan ist ein versierter Nachtelfen-Kräuterkundiger und Botaniker, der ein ruhiges Grundstück am Ostufer des Al'Amethsees pflegt. Unter einem einfachen Sonnensegel widmet er seine Tage dem Studium der Pflanzenwelt der Insel und der Suche nach botanischen Heilmitteln gegen die seltsame Verderbnis, die Teldrassil befällt. Häufig bittet er junge Abenteurer darum, Proben zu sammeln, aggressive Bäumlinge zu erforschen und verzauberte Erden zu testen.",h="Denalan ist ein versierter Nachtelfen-Kräuterkundiger und Botaniker, der ein ruhiges Grundstück am Ostufer...",kw={"schwarzmoos","botanik","denalan","kräuterkundiger","kaldorei","al'amethsee","grimmeiche","pflanzkasten","teldrassil","bäumlinge"},ang={["class:Druid"]="Druiden werden viel Gemeinsames mit Denalans Experimenten am Seeufer entdecken, da seine Arbeit direkt die Bemühungen des Zirkels des Cenarius unterstützt, den Makel aufzuspüren und zu beseitigen, der sich durch Teldrassils Wurzeln ausbreitet.",["profession:Herbalism"]="Denalan veranschaulicht die Tradition der botanischen Studien der Kaldorei und zeigt, wie das Sammeln und Kultivieren wilder Pflanzen tiefere Leiden in der Natur diagnostizieren kann.",["race:NightElf"]="Denalans Forschungen am Al'Amethsee spiegeln die frühen Versuche der Kaldorei wider, die unerwarteten Makel und Wachstumsschmerzen ihrer neuen Heimat Teldrassil zu verstehen."},sec={{t="Ein Botaniker am Al'Amethsee",b="Während viele Kaldorei sich auf kriegerische Wachsamkeit oder hohe druidische Riten konzentrieren, widmet sich Denalan dem geduldigen, akribischen Handwerk der Kräuterkunde. An den ruhigen Ostufern des Al'Amethsees hat er ein bescheidenes Forschungslager errichtet, bestehend aus einem Stoffsegel, einfachen Feldwerkzeugen und ordentlichen Reihen kultivierter Pflanzkästen. Statt sich in die erhabenen Grabhügel von Darnassus zurückzuziehen, zieht er es vor, nahe am Erdboden zu bleiben und die ungewöhnliche Flora direkt zu untersuchen, die seit der Pflanzung des neuen Weltenbaums sprießt."},{t="Die Erforschung von Teldrassils Makeln",b="Denalans Forschungen sind weit mehr als akademische Neugier; sie befassen sich mit der wachsenden Unruhe unter Teldrassils einheimischer Tier- und Pflanzenwelt. Die Bäumlinge, normalerweise friedfertige Waldwesen aus Holz und Sprösslingen, sind zunehmend aggressiv geworden. Denalan verzaubert spezielle Erde, um wilde Samen in Gefangenschaft aufzuziehen und zu analysieren, wie bösartige Mächte in die Wurzelsysteme einsickern. Indem er seltsame Exemplare wie schimmernde Wedel, Leuchtende Früchte und moosumschlungene Wucherungen untersucht, versucht er, den finsteren Makel zu isolieren, der das Geäst des Waldes heimsucht."}},faq={{q="Wo kann ich Denalan finden?",a="Denalan befindet sich am Ostufer des Al'Amethsees im südlichen Teldrassil, südlich von Dolanaar. Er unterhält ein kleines Lager mit einem Sonnensegel und mehreren kultivierten Pflanzbeeten direkt am Wasser.",al={"denalan aufenthaltsort","wo ist denalan","denalan karte"}},{q="Was erforscht Denalan in seinem Lager?",a="Denalan ist ein Kräuterkundiger, der die ungewöhnliche Flora von Teldrassil und das aggressive Verhalten lokaler Waldgeister erforscht. Er nutzt verzauberte Pflanzkästen, um Bäumlingssamenkörner zu ziehen, merkwürdige wilde Pflanzenproben zu analysieren und Wege zu finden, die Verderbnis zu reinigen, die in das Ökosystem des neuen Weltenbaums sickert.",al={"was macht denalan","denalan zweck","warum ist denalan am see"}},{q="Warum greifen die Bäumlinge die Bewohner an?",a="Bäumlinge sind pflanzenartige Naturgeister, die im Geäst von Teldrassil heimisch sind. Als normalerweise friedliche Bestandteile des Waldökosystems sind sie durch eine unnatürliche Verderbnis, die sich durch den Boden und die Wurzeln des Weltenbaums ausbreitet, gewalttätig und unberechenbar geworden, was Forscher wie Denalan dazu veranlasst hat, ihre Samen zu untersuchen.",al={"warum sind bäumlinge aggressiv","bäumling lore","verderbte bäumlinge"}},{q="Wofür werden Denalans Pflanzkästen verwendet?",a="Denalan führt speziell vorbereitete Pflanzbeete, die mit verzauberter Erde gefüllt sind. Er nutzt sie, um wilde Samen und seltsame botanische Stecklinge zu kultivieren, was es ihm ermöglicht, fernab von Verunreinigungen in der Wildnis sicher zu beobachten, wie die Flora des Waldes auf gereinigten Boden reagiert.",al={"denalan pflanzkasten","denalans erde","denalan erdkästen"}},{q="Mit wem arbeitet Denalan zusammen?",a="Denalan hat eng mit befreundeten Kräuterkundigen wie Sylvia Whisperbloom zusammengearbeitet und steht in regelmäßigem Austausch mit druidischen Forschern und Gelehrten in ganz Teldrassil, darunter Rellian Grünwipfel in Darnassus.",al={"denalan verbündete","wem erstattet denalan bericht"}},{q="Was ist das Moosumschlungene Herz, das Denalan untersucht?",a="Das Moosumschlungene Herz ist ein verdorbener pflanzlicher Kern, der von Schwarzmoos dem Übelriechenden erbeutet wurde, einem verderbten Bäumling auf Teldrassil. Denalan untersucht ihn in seiner verzauberten Erde, um die unnatürliche Seuche zu verstehen, die die Pflanzenwelt der Insel verzerrt.",al={"moosumschlungenes herz","das moosumschlungene herz quest","schwarzmoos herz"}}},fx={["6481fcca"]={q="Wer ist Denalan?",a="Denalan ist ein angesehener Nachtelf-Kräuterkundiger und Forscher, der an den Ufern des Al'Amethsee lebt. Bekannt für sein tiefes Verständnis der Pflanzenwelt von Kalimdor, widmet er seine Arbeit dem Studium der Flora von Teldrassil und der Suche nach natürlichen Heilmitteln für die ökologischen Nöte, die den Weltenbaum plagen.",al={"wer ist denalan","denalan lore","über denalan"}},["6f0f42ae"]={q="Auf wessen Seite steht Denalan?",a="Denalan ist den Nachtelfen von Darnassus treu und mit der Allianz verbündet. Er arbeitet offen mit seinen Kräuterkundigen- und Druidenkollegen unter den Kaldorei zusammen und unterstützt jeden Reisenden, der Teldrassil vor Verderbnis und Schaden bewahren möchte.",al={"denalan fraktion","ist denalan allianz","wem dient denalan"}},["11aaa3f4"]={q="Was will Denalan?",a="Denalan möchte Teldrassil von der sich ausbreitenden Verderbnis reinigen, die den Boden und die Tierwelt infiziert. Er sammelt Samen und seltene Pflanzenexemplare aus dem umliegenden Wald und nutzt speziell verzauberte Erde, um gesundes Wachstum zu fördern und ein Heilmittel für die wahnsinnigen Holzlinge zu finden.",al={"was will denalan","denalan ziel","denalan aufgabe"}},["38f45ee1"]={q="Warum ist Denalan hier am Al'Amethsee?",a="Denalan errichtete sein Lager am See, um die einheimische Vegetation von Teldrassil aus nächster Nähe zu studieren. Die Ufer bieten ein ideales Freiluftlabor für seine Pflanzkästen und verzauberte Erde, was ihn in die Nähe des Epizentrums der aufgebrachten Holzlingspopulation bringt, die er verstehen möchte.",al={"warum ist denalan hier","warum al'amethsee denalan","sinn des denalan-lagers"}},["3bcd2be5"]={q="Warum ist Denalan berühmt?",a="Denalan ist unter den Nachtelfen als berühmter Kräuterkundiger weithin respektiert. Sein lebenslanges Studium der Botanik in Kalimdor und seine Expertise bei der Reinigung von infizierten Samen und Böden haben ihm den Ruf als eine der führenden Autoritäten des Reiches für Pflanzenkunde eingebracht.",al={"warum ist denalan berühmt","denalan kräuterkundigen-ruhm","ist denalan bekannt"}}},fp="7,412,27.520.0,36.526.0,25.205.0,44.296.0,41.311.0,42.250.0,27.212.0,52.236.0"}
P.entries["npc:dendrite-starblaze"] = {n="Dendrite Sternenschauer",s="Dendrite Sternenschauer ist ein Nachtelfendruide, der im heiligen Dorf Nachthafen in Mondlichtung weilt. Im Dienste des Zirkels des Cenarius fungiert er als unverzichtbarer Mentor und Wegweiser für angehende Druiden sowohl der Nachtelfen als auch der Tauren. Durch ihn werden Adepten in den heiligen Hain berufen, um grundlegende Riten wie das Heilen von Giften und die Zwiesprache mit den Formen der Natur zu meistern.",h="Dendrite Sternenschauer ist ein Nachtelfendruide, der im heiligen Dorf Nachthafen in Mondlichtung weilt.",kw={"wassergestalt","zirkel des cenarius","heilung der kranken","dendrite sternenschauer","druide","neue lektionen","mondlichtung","nachtelf","nachthafen"},ang={["class:Druid"]="Dendrite Sternenschauer ist einer Eurer wichtigsten Wegweiser, wenn Ihr Euch zum ersten Mal nach Mondlichtung teleportiert; er weist Euch in das Heilen von Krankheiten und das Streben nach der Wassergestalt ein.",["race:NightElf"]="Dendrite bewahrt die klassischen Riten der kaldoreischen Naturhege und heißt Kaldorei-Initianden in Nachthafen im Orden des Cenarius willkommen.",["race:Tauren"]="Für Druiden der Shu'halo, die Mondlichtung aus Mulgore besuchen, dient Dendrite als lebender Beweis dafür, dass das Band des Zirkels des Cenarius über der Fehde zwischen der Horde und der Allianz steht."},sec={{t="Ein Wegweiser in der heiligen Zuflucht",b="In Nachthafen verkörpert Dendrite Sternenschauer den unparteiischen, beständigen Geist des Zirkels des Cenarius. Wenn Druidenneulinge lernen, ihren Geist auf 'Teleportieren: Mondlichtung' einzustimmen, gehört Dendrite zu den Ersten, die sie nach ihrer Ankunft willkommen heißen. Er schlägt eine Brücke zwischen der uralten Tradition der Kaldorei und dem aufstrebenden Pfad der Tauren und behandelt alle, die dem Ruf der Wildnis folgen, unter den Wipfeln der heiligen Zuflucht wie Verwandte."},{t="Prüfungen der Wildnis",b="Dendrites Hauptaufgabe besteht darin, Druidenlehrlinge in die tieferen Geheimnisse der Natur einzuweihen. Er leitet Novizen durch die Prüfungen, die erforderlich sind, um Gift und Pestilenz zu verstehen, und schickt sie aus, um verdorbene Gewässer zu untersuchen und pflanzliche Heilmittel zu entdecken. Zudem überwacht er die Schritte, die Druiden zu den Wasserprüfungen führen, und prüft ihre Geduld und Ausdauer unter der Wasseroberfläche, bevor er ihnen die Zwiesprache mit der Wassergestalt gewährt."}},faq={{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein Nachtelfendruide und Mentor des Zirkels des Cenarius in Nachthafen in Mondlichtung. Er leitet heranwachsende Druiden durch grundlegende Klassenprüfungen und die Ausbildung.",al={"dendrite sternenschauer","wer ist dendrite","starblaze mondlichtung"}},{q="Warum bildet ein Nachtelf Horde-Tauren aus?",a="Der Zirkel des Cenarius steht außerhalb der politischen Fraktionen von Allianz und Horde. In Mondlichtung praktizieren Nachtelfen und Tauren gemeinsam die druidischen Künste unter uralten Eiden der Brüderlichkeit und lassen weltliche Konflikte jenseits der Gebirgspässe zurück.",al={"warum bildet dendrite horde aus","dendrite tauren druide","fraktionsübergreifender druidenmentor"}},{q="Welche Quests bietet Dendrite Sternenschauer an?",a="Dendrite überwacht mehrere grundlegende Klassenprüfungen der Druiden. Dazu gehören Quests zur Meisterung der Heilung von Gift und Krankheiten sowie Prüfungen, die zur für die Wassergestalt erforderlichen Zwiesprache führen.",al={"dendrite quests","starblaze questliste"}},{q="Wo ist Dendrite Sternenschauer zu finden?",a="Er befindet sich in Nachthafen, der Siedlung am nördlichen Ufer des Elune'ara Sees in Mondlichtung.",al={"dendrite aufenthaltsort","wo ist starblaze","dendrite sternenschauer karte"}},{q="Wie erreichen junge Druiden Dendrite zum ersten Mal?",a="Druidenneulinge erlernen den Zauber 'Teleportieren: Mondlichtung' von ihren Volkslehrern etwa mit ihrem zehnten Ausbildungszirkel. Das Wirken dieses Zaubers bringt sie direkt nach Mondlichtung, wo Dendrite auf ihre Ankunft wartet.",al={"weg zu dendrite","teleport nach mondlichtung quest"}},{q="Können Nicht-Druiden-Abenteurer mit ihm interagieren?",a="Nicht-Druiden können Nachthafen besuchen und mit Dendrite sprechen, doch bietet er jenen außerhalb der druidischen Traditionen des Zirkels des Cenarius keine Ausbildung, Prüfungen oder Quests an.",al={"nicht-druide dendrite","kann krieger mit starblaze sprechen"}}},fx={["3038adca"]={q="Was will Dendrite Sternenschauer?",a="Dendrite führt Druidennovizen auf dem Pfad der Natur und des Gleichgewichts. Durch Prüfungen, die die Geister der Wildnis ehren – wie die Verbindung mit dem Großen Bärengeist und die Meisterung von Kräften über Gift und Wasser –, stellt er sicher, dass alle Novizen, ungeachtet ihrer Herkunft, die Verantwortlichkeiten und alten Disziplinen des Zirkel des Cenarius erlernen.",al={"dendrite sternenschauer ziel","was will dendrite","dendrite sternenschauer motiv"}},ef589fff={q="Warum ist Dendrite Sternenschauer in Mondlichtung?",a="Mondlichtung ist heiliger, neutraler Boden, auf dem der Zirkel des Cenarius fernab von weltlichen Fraktionskonflikten zusammenkommt. Stationiert in Nachthafen, dient Dendrite als einladender Mentor für angehende Druiden, die zum Hafen gerufen werden, und vermittelt grundlegende Lektionen und Prüfungen, die für ihr spirituelles Wachstum wesentlich sind.",al={"warum ist dendrite hier","dendrite sternenschauer standort mondlichtung","warum ist dendrite in nachthafen"}},["7aee8496"]={q="Mit wem ist Dendrite Sternenschauer verbunden?",a="Dendrite ist ein Abgesandter und Mentor innerhalb des Zirkel des Cenarius. Er arbeitet eng mit seinen Druidenkollegen sowohl nachtelfischer als auch taurischer Abstammung zusammen und folgt dem Ruf der wilden Geister sowie den Lehren des Cenarius anstatt den politischen Bannern von Darnassus oder der Horde.",al={"dendrite sternenschauer fraktion","dendrite sternenschauer zirkel des cenarius","wem dient dendrite"}}},fp="18,368,27.425.0,18.422.0,26.175.0,40.246.0,42.189.0,38.107.0,54.202.0,44.165.0"}
P.entries["npc:deputy-feldon"] = {n="Stellvertreter Feldon",s="Stellvertreter Feldon ist ein Mitglied der Stadtwache des Rotkammgebirges, das direkt südlich der Großen Brücke von Seenhain stationiert ist. Mit der Bewachung der Hauptstraße nach Seenhain betraut, hält er eine nervöse Wache gegen die aggressiven Gnollrudel, die auf die Stadtgrenze vorrücken.",h="Stellvertreter Feldon ist ein Mitglied der Stadtwache des Rotkammgebirges, das direkt südlich der Großen...",kw={"brücke","stellvertreter feldon","feldon","gnolle","wache","seenhain","rotkamm"},ang={["faction:Alliance"]="Feldon verkörpert die verzweifelte Lage der äußeren Territorien von Sturmwind, in denen örtliche Wachleute vorbeiziehende Recken um Hilfe bitten müssen, um den Frieden des Königs aufrechtzuerhalten."},sec={{t="Eine Wache am Rande der Verzweiflung",b="Stellvertreter Feldon hält in der Nähe des südlichen Zugangs zur Brücke von Seenhain Wache und verkörpert eine überforderte Stadtwache, die darum kämpft, die grundlegenden Handels- und Reiserouten offen zu halten. Da die Blackrockorcs aus dem Norden drängen und Gnollrudel die südlichen Hügel überrennen, sind Wachleute wie Feldon an ihren Grenzen angelangt. Da er seinen Posten nicht verlassen kann, ohne die Stadtgrenze zu gefährden, verlässt er sich auf vorbeiziehende Abenteurer, um die Gnolle zu dezimieren, die auf die Straße vordringen, bevor sie Seenhain gänzlich abschneiden können."}},faq={{q="Wer ist Stellvertreter Feldon?",a="Stellvertreter Feldon ist ein Offizier der Stadtwache von Seenhain, der direkt südlich der Brücke stationiert ist, die die Stadt mit der südlichen Hauptstraße im Rotkammgebirge verbindet.",al={"feldon","wer ist feldon","rolle von stellvertreter feldon"}},{q="Warum macht sich Stellvertreter Feldon Sorgen wegen Gnollen?",a="Gnollrudel sind zunehmend dreister geworden, schleichen nahe an den südlichen Stadtrand heran und belästigen Reisende. Feldon befürchtet, dass sie die südliche Straße nach Seenhain vollständig abschneiden werden, wenn ihre Zahl nicht eingedämmt wird.",al={"warum gnolle","feldon gnollproblem","eindringende gnolle"}},{q="Warum kümmert sich Feldon nicht selbst um die Gnolle?",a="Die Wache von Seenhain ist stark unterbesetzt und sieht sich gleichzeitigen Bedrohungen durch Orcs und Gnolle gegenüber. Feldon kann seinen Wachposten an der Brücke nicht verlassen, ohne den Zugang zur Stadt unbewacht zu lassen.",al={"warum kämpft feldon nicht","feldons pflicht"}},{q="Wo ist Stellvertreter Feldon zu finden?",a="Er hält auf der Straße direkt südlich der Großen Brücke von Seenhain Wache und behält die südlichen Zugänge zur Stadt im Auge.",al={"feldon aufenthaltsort","wo ist feldon"}}},fx={["1b9b43bf"]={q="Auf wessen Seite steht Stellvertreter Feldon?",a="Stellvertreter Feldon ist ein treuer Gesetzeshüter der Allianz, der im Rotkammgebirge unter der Autorität der Stadtwache von Seenhain und Magistrat Solomon dient. Er arbeitet daran, die Bürger des Königreichs zu schützen und die Straßen zur Stadt vor eindringenden Bedrohungen sicher zu halten.",al={"stellvertreter feldon fraktion","wem dient feldon","stellvertreter feldon allianz"}},dc2592f9={q="Warum ist Stellvertreter Feldon in der Nähe der Brücke stationiert?",a="Stellvertreter Feldon ist direkt südlich der Brücke von Seenhain stationiert, um die südlichen Zugänge zu beobachten. Da Gnollrudel gefährlich nahe an die Stadt herandrängen, überwacht er die Straße, um den Reiseverkehr offen zu halten und fähige Reisende zu rekrutieren, damit die Invasion eingedämmt wird, bevor die Brücke selbst überrannt wird.",al={"warum ist feldon hier","stellvertreter feldon standort grund","was tut feldon hier"}},["5e39d198"]={q="Mit wem ist Stellvertreter Feldon verbunden?",a="Feldon untersteht Magistrat Solomon und den örtlichen Friedenssicherungskräften, deren Aufgabe die Bewachung von Seenhain ist. Er ist Teil der spärlichen örtlichen Wache, die das Rotkammgebirge in Abwesenheit nennenswerter militärischer Verstärkung aus Sturmwind verteidigt.",al={"stellvertreter feldon verbindungen","wem untersteht feldon","stellvertreter feldon sheriff"}}},fp="13,254,15.511.0,21.159.0,42.231.0,48.202.0,33.125.0"}
P.entries["npc:deputy-rainer"] = {n="Stellvertreter Rainer",s="Stellvertreter Rainer ist ein Offizier der Armee von Sturmwind, der vor der Weststromgarnison an der westlichen Grenze des Walds von Elwynn stationiert ist. Er hat die Aufgabe, die Linie gegen vordringende Gnollrudel und aus Westfall herüberschwappende Banditen zu halten, und koordiniert die örtlichen Verteidigungsbemühungen, wenn offizielle militärische Verstärkung ausbleibt.",h="Stellvertreter Rainer ist ein Offizier der Armee von Sturmwind, der vor der Weststromgarnison an der...",kw={"stellvertreter rainer","wald von elwynn","gryan starkmantel","hogger","marschall dughan","riverpaw","weststromgarnison","westfall"},ang={["faction:Alliance"]="Stellvertreter Rainer steht für die bröckelnden Ränder der militärischen Reichweite von Sturmwind und bietet Helden der Allianz einen direkten Einblick darin, wie sich lokale Garnisonen anpassen müssen, um ohne regelmäßige königliche Unterstützung zu überleben."},sec={{t="Das Halten der Westgrenze",b="Die Weststromgarnison dient als westlichstes Bollwerk des Walds von Elwynn und liegt direkt an der Grenzstraße, die nach Westfall führt. Da die politische Lähmung in Sturmwind den Großteil der Armee im Ausland gebunden hält oder in der Bürokratie verstrickt, bleiben Grenzposten wie Weststrom stark unterbesetzt. Stellvertreter Rainer steht vor dem Turm, um die wenige Verteidigung zu organisieren, die die Garnison aufbringen kann. Da die örtlichen Straßen ständig von aggressiven Flusspfotengnollen und umherziehenden Dieben bedroht werden, ist Rainer gezwungen, sich auf durchreisende Reisende und abenteuerlustige Söldner statt auf offizielle Regimenter der Krone zu verlassen, um die Waldwege sicher zu halten."},{t="Der Weg nach Westfall",b="Über die Bewältigung der unmittelbaren Bedrohung durch das Flusspfotenrudel und die Warnung von Reisenden vor dem berüchtigten Gnollhäuptling Hogger hinaus dient Rainer als wichtiges Verbindungsglied zu den unruhigen Ländereien jenseits des Flusses. Da er weiß, dass das Chaos an den Grenzen von Elwynn seinen Ursprung im gesetzlosen Ackerland im Westen hat, schickt er fähige Freiwillige über die Grenze nach Westfall und verweist sie an Gryan Starkmantel und die kämpfende Volksmiliz."}},faq={{q="Wer ist Stellvertreter Rainer?",a="Stellvertreter Rainer ist ein Offizier der Armee von Sturmwind, der an der Weststromgarnison am westlichen Rand des Walds von Elwynn stationiert ist. Er überwacht die örtliche Straßensicherheit und heuert Abenteurer an, um die umliegenden Bedrohungen zu bekämpfen.",al={"rainer elwynn","wer ist rainer","weststromgarnison offizier"}},{q="Warum ist die Weststromgarnison unterbesetzt?",a="Die Armee von Sturmwind hat den Großteil ihrer Streitkräfte andernorts im Einsatz, und politische Unruhen in der Hauptstadt verhindern, dass regelmäßige Verstärkung die abgelegenen Regionen erreicht. Infolgedessen muss sich Marschall Dughan in Goldhain auf unabhängige Abenteurer verlassen, um Rainer zu unterstützen.",al={"warum keine wachen bei weststrom","warum hat die garnison probleme","weststrom braucht hilfe"}},{q="Welche Bedrohungen versucht Rainer abzuwehren?",a="Rainer konzentriert sich in erster Linie auf die Eindämmung des Flusspfoten-Gnollrudels, das die Wälder südlich der Garnison heimsucht, auf umherziehende Diebe und auf den berüchtigten Gnollhäuptling Hogger, der Reisenden entlang der Grenze auflauert.",al={"welche feinde sind nahe weststrom","flusspfotengnolle weststrom","weststrom gnolle"}},{q="Wohin schickt Rainer Abenteurer, nachdem die Gnolle besiegt sind?",a="Sobald die Gnollbedrohung in der Nähe der Garnison eingedämmt ist, leitet Rainer erfahrene Abenteurer über die westliche Grenze nach Westfall weiter, um Gryan Starkmantel und der Volksmiliz auf der Späherkuppe beizustehen.",al={"wohin nach rainer","rainer quest westfall","nach weststromgarnison"}}},fx={["8453208a"]={q="Auf wessen Seite steht Stellvertreter Rainer?",a="Rainer ist ein treuer Offizier der Armee von Sturmwind und dient dem Königreich Sturmwind sowie der Allianz. Er ist in der Weststromgarnison stationiert, untersteht Marschall Dughan in Goldhain und bemüht sich, die westlichen Märsche von Wald von Elwynn vor dem eindringenden Chaos zu schützen.",al={"stellvertreter rainer fraktion","wem dient rainer","ist rainer allianz"}},b0214c4a={q="Was will Stellvertreter Rainer?",a="Rainer sucht fähige Freiwillige, um die westliche Grenze von Wald von Elwynn zu verteidigen. Da die Armee überlastet ist, möchte er das aggressive Flusspfotengnollrudel im Süden dezimieren, die Handelsstraßen vor Dieben sichern und der Bedrohung durch Hogger ein Ende setzen.",al={"was will rainer","stellvertreter rainer ziele","was fordert rainer"}},["5835f036"]={q="Warum ist Stellvertreter Rainer hier?",a="Rainer ist in der Weststromgarnison stationiert, um die Grenze zwischen Wald von Elwynn und Westfall zu bewachen. Da Bestien und Banditen sich ostwärts über den Fluss ausbreiten, hält er vor dem Wachturm Wache, koordiniert Patrouillen und rekrutiert Reisende, um die Grenze zu halten.",al={"warum ist rainer in weststromgarnison","warum ist stellvertreter rainer hier"}},b3def1b5={q="Mit wem ist Stellvertreter Rainer verbunden?",a="Rainer berichtet an Marschall Dughan, den Kommandanten der Garnisonstruppen in Goldhain. Er arbeitet auch grenzüberschreitend mit Gryan Starkmantel und der The People's Militia in Westfall zusammen und leitet geprüfte Kämpfer nach Westen, um sie bei ihrem Kampf gegen die The Defias Brotherhood zu unterstützen.",al={"mit wem ist rainer verbunden","rainer verbindungen","wem untersteht rainer"}}},fp="13,311,26.631.0,20.452.0,21.207.0,38.263.0,41.208.0,61.201.0"}
P.entries["npc:devrak"] = {n="Devrak",s="Devrak ist ein orkischer Windreitermeister, der im Wegekreuz im Brachland stationiert ist. Als primärer Luftknotenpunkt des zentralen Kalimdor überwacht er das Wyvern-Netzwerk der Horde, das Vorräte und Kuriere zwischen Durotar, Mulgore und Außenposten an der Grenze transportiert. Zudem stellt er sicher, dass entscheidende Logistikgüter wie Wildbret und bearbeitete Felle reibungslos zu den Hauptstädten der Horde gelangen.",h="Devrak ist ein orkischer Windreitermeister, der im Wegekreuz im Brachland stationiert ist.",kw={"brachland","das wegekreuz","devrak","flugmeister","orgrimmar","donnerfels","windreiter","wyvern"},ang={["faction:Horde"]="Devrak ist ein unverzichtbarer Verbündeter für jeden Hordenabenteurer, der Kalimdor bereist, da er als zentraler Knotenpunkt dient, der die Gebiete der Orks, Trolle und Tauren miteinander verbindet.",["race:Orc"]="Im trockenen Herzen des Brachlands stationiert, beweist Devrak das orkische Talent für den Umgang mit Kalimdors Windreitern und schließt Bande mit den wilden Bestien, um die Vorherrschaft in den Lüften zu sichern."},sec={{t="Hüter der Nistplätze vom Wegekreuz",b="An der Kreuzung der wichtigsten Handelsrouten Kalimdors gelegen, kümmert sich Devrak um die Wyvern, die den Zusammenhalt der Horde über weite Distanzen sichern. Das Wegekreuz liegt schutzlos unter der brennenden Sonne, gleichermaßen anfällig für Borstennacken, Zentauren und Späher der Allianz, was einen schnellen Lufttransport unerlässlich macht. Devrak betreut sowohl erfahrene Reisende als auch unerprobte Boten und teilt ihnen ausgebildete Windreiter zu, die fähig sind, die Savanne zu überqueren und die Berghöhen von Mulgore oder die Felsschluchten von Durotar zu erreichen."},{t="Nachschub für den Kriegshäuptling und den Oberhäuptling",b="Über die Beförderung von Reisenden hinaus spielt Devrak eine entscheidende Rolle in der Grenzlogistik. Die Jäger des Brachlands erbeuten Fleisch und Pelze in Hülle und Fülle, die Devrak direkt zu den Kochfeuern von Orgrimmar und den Gerbern von Donnerfels weiterleitet. Indem er angehende Kuriere an Flugmeister auf dem gesamten Kontinent vermittelt, festigt er die Lebensader aus der Luft, die die Kerngebiete der Horde versorgt."},{t="Ein tödlicher Horst",b="Flugmeister in umkämpften Grenzgebieten können es sich nicht leisten, wehrlos zu sein. Devrak ist weit mehr als ein einfacher Bestienhüter; wenn Das Wegekreuz angegriffen wird, ruft er wütende Wyvern herbei, die feindliche Eindringlinge mit giftigen Stacheln und Krallen zerfleischen, was seinen Horst zu einem gefährlichen Ziel für jeden macht, der kühn genug ist, die Siedlung anzugreifen."}},faq={{q="Welche Rolle hat Devrak im Wegekreuz?",a="Devrak ist der Flugmeister der Horde im Wegekreuz im Brachland. Er kümmert sich um die Windreiter des Außenpostens, gewährt Flugrouten zu angebundenen Siedlungen in ganz Kalimdor und koordiniert den Transport von Kurieren, Soldaten und lebenswichtigen Handelsgütern.",al={"wer ist devrak","was macht devrak","devrak aufgabe","das wegekreuz flugmeister"}},{q="Wohin kann Devrak mich fliegen?",a="Von seinem Horst im Wegekreuz aus verbindet Devrak die großen Hauptstädte wie Orgrimmar und Donnerfels sowie Grenzaußenposten in Eschental, dem Steinkrallengebirge, den Düstermarschen, Tausend Nadeln und den südlichen Grenzlanden – vorausgesetzt, Ihr habt zuvor mit diesen Flugmeistern gesprochen.",al={"devrak flugrouten","wohin fliegen ab das wegekreuz","das wegekreuz flugwege"}},{q="Welche Quests bietet Devrak an?",a="Devrak hilft bei Kurieraufgaben, die jungen Hordenabenteurern die Nutzung des Flugnetzes beibringen, darunter das Versenden von frischem Fleisch an Gryshka in Orgrimmar und von Fellbündeln nach Donnerfels.",al={"devrak quests","das wegekreuz flugquest"}},{q="Wie verteidigt sich Devrak, wenn Das Wegekreuz angegriffen wird?",a="Devrak wird von seinem Horst beschützt. Bei Angriffen von Angreifern der Allianz oder feindlichen Bestien kann er wilde, wütende Wyvern herbeirufen, die ihm im Kampf beistehen und Angreifer mit Zähnen und Klauen vertreiben.",al={"kann devrak kaempfen","devrak toeten","devrak verteidigung"}},{q="Warum ist ein Flugmeister im Wegekreuz so wichtig?",a="Das Brachland ist das verbindende Rückgrat von Zentral-Kalimdor. Da Das Wegekreuz Durotar, Mulgore, Eschental und das Steinkrallengebirge miteinander verknüpft, ermöglicht Devraks Horst der Horde, Truppen schnell zu verlegen und Nachschub zu koordinieren, ohne auf tagelange Fußmärsche angewiesen zu sein.",al={"warum ist der flugmeister in das wegekreuz wichtig","bedeutung von das wegekreuz"}},{q="Mit welchen Kreaturen arbeitet Devrak?",a="Devrak betreut Windreiter, die auch als Wyvern bekannt sind. Diese drakonischen, geflügelten Raubtiere, die auf den Gipfeln und Mesas von Kalimdor heimisch sind, wurden von der Horde gezähmt, um als verlässliche Flugtiere in unwegsamem Gelände zu dienen.",al={"welche reittiere hat devrak","das wegekreuz reittiere"}}},fx={a0427f27={q="Auf wessen Seite steht Devrak?",a="Devrak ist ein stolzes Mitglied der Horde. Stationiert im Herzen von Kalimdor am Das Wegekreuz, dient er dem Kriegshäuptling, indem er die lebenswichtigen Luftversorgungsrouten zwischen orcischen und taurischen Gebieten offen hält und Kuriere, Vorräte sowie Krieger durch das Brachland und darüber hinaus transportiert.",al={"ist devrak horde","devrak fraktion","wem dient devrak"}},bd507e24={q="Was will Devrak?",a="Devrak konzentriert sich darauf, die lebenswichtigen Versorgungswege der Horde durch das zentrale Kalimdor aufrechtzuerhalten. Er verlässt sich darauf, dass Reisende wichtige Güter – wie gegerbte Felle und haltbar gemachtes Fleisch – an bedeutende Hauptstädte wie Orgrimmar und Donnerfels liefern, um sicherzustellen, dass die Windreiter der Siedlung bereit bleiben und die Kriegsanstrengungen gut unterstützt werden.",al={"was ist devraks ziel","devrak aufgabe","was braucht devrak"}}},fp="6,381,31.509.0,43.382.0,14.350.0,40.258.0,24.282.0,30.189.0,61.189.0,60.262.0,34.211.0"}
P.entries["npc:dextren-ward"] = {n="Dextren Ward",s="Dextren Ward ist ein berüchtigter Verbrecher und Grabräuber, der im Verlies von Sturmwind eingesperrt ist. Vor seiner Gefangennahme profitierte er davon, Leichen vom Friedhof von Rabenflucht im Dämmerwald zu exhumieren und sie an den Nekromanten Morbent Teufel zu liefern. Nun, da er mitten im blutigen Aufstand des Gefängnisses gefangen ist, steht er weiterhin auf der Todesliste des Stadtrats von Dunkelhain.",h="Dextren Ward ist ein berüchtigter Verbrecher und Grabräuber, der im Verlies von Sturmwind eingesperrt ist.",kw={"ratsherr mühlenstein","verbrechen und strafe","dextren ward","dämmerwald","grabräuber","morbent teufel","friedhof von rabenflucht","sturmwind","das verlies"},ang={["class:Paladin"]="Wards Zusammenarbeit mit Nekromanten zur Beschaffung frischer Leichen stellt einen abscheulichen Frevel gegen die Heiligkeit des Lichts und die friedliche Ruhe der Dahingeschiedenen dar.",["class:Priest"]="Die Schändung heiliger Ruhestätten in Rabenflucht macht Wards Schicksal zu einem Gebot moralischer und spiritueller Vergeltung.",["faction:Alliance"]="Für Champions der Allianz, die Dunkelhain beistehen, ist die Ausschaltung von Dextren Ward ein Akt der Gerechtigkeit für die geschändeten Familien des Dämmerwalds und eine essenzielle Aufgabe bei der Rückeroberung des aufständischen Verlieses."},sec={{t="Grabräuberei im Dämmerwald",b="Bevor er unter den Straßen von Sturmwind in Ketten landete, betrieb Dextren Ward ein düsteres und lukratives Geschäft in den nebelverhangenen Wäldern des Dämmerwalds. Der Friedhof von Rabenflucht war ohnehin schon ein Ort der Trauer und des wachsenden Grauens, doch Ward nutzte seine Grabstätten als privaten Steinbruch. Statt bloß nach Schmuckstücken und Erbstücken zu suchen, die den Toten mitgegeben wurden, handelte Ward mit Fleisch und hob frische Gräber aus, um lokale dunkle Zauberkundige zu beliefern."},{t="Handlanger des Nekromanten",b="Wards wichtigster Kunde war Morbent Teufel, ein Nekromant, dessen dunkle Rituale den Dämmerwald heimsuchen und die Reihen der Untoten anwachsen ließen. Indem er Fel mit Leichen versorgte, trug Ward aktiv zum Schrecken bei, der Dunkelhain im Griff hält. Obwohl er schließlich von den Behörden Sturmwinds gefasst und ins Verlies geschleppt wurde, brachten ihm seine Verbrechen die ewige Feindschaft der Menschen des Dämmerwalds ein, was Ratsherr Mühlenstein dazu veranlasste, Wards Hand als Beweis für die vollstreckte Gerechtigkeit zu fordern."},{t="Chaos im Verlies",b="Als im Verlies eine großangelegte Rebellion ausbrach, wurde Ward nicht von Verbündeten befreit, sondern vielmehr aus seiner Zelle entlassen, um sich dem Chaos in dem abgeriegelten Verlies anzuschließen. Bewaffnet und bösartig beherrscht er seine eigene Ecke des Gefängnisses und schlägt Eindringlinge mit Schrecken in die Flucht. Dies macht ihn zu einem der vorrangigen Ziele, die Streitkräfte der Allianz eliminieren wollen, während sie die Ordnung wiederherstellen."}},faq={{q="Wer ist Dextren Ward?",a="Dextren Ward ist ein berüchtigter Verbrecher, der im Verlies von Sturmwind inhaftiert ist. Er ist ein Elite-Mensch und Gefangener, der dafür verantwortlich ist, die Toten im Dämmerwald ausgeraubt zu haben, um dunkle Rituale zu nähren.",al={"wer ist dextren ward","dextren ward geschichte","verlies dextren"}},{q="Warum befindet sich Dextren Ward im Verlies?",a="Ward wurde wegen Grabräuberei auf dem Friedhof von Rabenflucht im Dämmerwald gefasst und eingesperrt. Anstatt Wertsachen zu stehlen, exhumierte er frische Leichen, um sie direkt an den Nekromanten Morbent Teufel zu verkaufen.",al={"warum wurde er verhaftet","dextren ward verbrechen","was hat dextren getan"}},{q="Wer will Dextren Wards Tod?",a="Ratsherr Mühlenstein aus Dunkelhain will Wards Tod. Millstipe sinnt auf Vergeltung für die Schändung der Gräber des Dämmerwalds und fordert Wards abgetrennte Hand als Beweis für sein Ableben.",al={"wer will dextren tot sehen","kopfgeld dextren ward","verbrechen und strafe questgeber"}},{q="Welche Verbindung besteht zwischen Ward und Morbent Teufel?",a="Ward fungierte als Leichenbeschaffer für Morbent Teufel. Indem er die frisch begrabenen Toten des Friedhofs von Rabenflucht ausgrub, lieferte Ward das Rohmaterial, das Fel für seine nekromantischen Experimente und untoten Schöpfungen benötigte.",al={"morbent teufel verbindung","dextren ward morbent teufel","wer kaufte die leichen"}},{q="Wo ist Dextren Ward zu finden?",a="Er befindet sich im Verlies von Sturmwind, dem Hochsicherheitsgefängnis in den Kanälen von Sturmwind. Während des anhaltenden Gefängnisaufstands lauert er in einem der Zellentrakte.",al={"dextren ward standort","wo ist dextren ward","wo finde ich dextren"}},{q="Warum verlangt die Quest Dextrens Hand?",a="Ratsherr Mühlenstein verlangt ausdrücklich Wards kalte, tote Hand als unwiderlegbaren physischen Beweis dafür, dass der Grabräuber nicht länger die Gräber des Dämmerwalds schänden oder von Nekromantie profitieren kann.",al={"warum hand abtrennen","dextren ward hand","todesbeweis dextren"}}},fx={["87b921a6"]={q="Auf wessen Seite steht Dextren Ward?",a="Ward sorgt nur für sich selbst, obwohl er Geschäfte mit den dunklen Mächten machte, die den Dämmerwald plagen. Anstatt für eine organisierte Fraktion wie die The Defias Brotherhood zu kämpfen, agierte er als krimineller Opportunist und ging eine üble Partnerschaft ein, um frisch ausgegrabene Leichen vom Friedhof von Rabenflucht an den Nekromanten Morbent Fel zu liefern.",al={"dextren ward fraktion","für wen arbeitet dextren ward","ist dextren ward defias"}},["371c7358"]={q="Warum wird Dextren Ward gefürchtet?",a="Neben seinem grauenhaften Handel als Grabräuber ist bekannt, dass Ward bei jedem, der ihm gegenübersteht, Panik auslöst. In den engen, gewalttätigen Hallen vom Das Verlies macht ihn seine Fähigkeit, übernatürlichen Schrecken zu verbreiten, außerordentlich tödlich, da ein fliehender Kämpfer schnell direkt in die Klingen anderer randalierender Insassen läuft.",al={"warum ist dextren ward gefährlich","dextren ward gefürchtet","was macht dextren ward gefährlich"}}},fp="12,354,25.431.0,23.452.0,21.368.0,20.169.0,36.190.0,28.175.0,41.206.0,32.182.0,42.186.0"}
P.entries["npc:dirania-silvershine"] = {n="Dirania Silberschein",s="Dirania Silberschein ist eine Nachtelfe und Bewohnerin des Laubschattentals auf Teldrassil. Sie ist zutiefst loyal sowie aufmerksam, wacht über den friedvollen Hain und gibt auf ihren Gefährten Iverron Acht, wenn dessen leichtsinnige Unternehmungen ihn in Gefahr bringen.",h="Dirania Silberschein ist eine Nachtelfe und Bewohnerin des Laubschattentals auf Teldrassil.",kw={"gegengift","dirania","iverron","laubschattental","silvershine","teldrassil","webwood"},ang={["race:NightElf"]="Für junge Nachtelfen, die ihre ersten Schritte im Laubschattental wagen, dient Dirania als frühe Mahnung an den Wert von Freundschaft und die lauernden Gefahren, die selbst die neuesten Zufluchtsorte des Weltenbaums bedrohen."},sec={{t="Eine Wächterin im Laubschattental",b="Dirania verweilt unter den friedvollen Zweigen des Laubschattentals, jenem abgeschiedenen Tal, in dem junge Nachtelfen ihren Dienst für Kalimdor und die Allianz beginnen. Während viele in den Grabhügeln und Heiligtümern weitreichenden spirituellen Pflichten nachgehen, behält Dirania diejenigen im Blick, die ihr am nächsten stehen, und achtet auf die leisen Gefahren, die sich selbst im Herzen von Teldrassil regen."},{t="Die Not eines Freundes",b="Diranias größte Sorge gilt ihrem Gefährten Iverron. Übereifrig und unvorsichtig im Umgang mit den giftigen Waldkreaturen, die durch den Hain streifen, gerät Iverron immer wieder in Schwierigkeiten. Als er dem giftigen Biss der hiesigen Webwood-Spinnen erliegt, nimmt Dirania es auf sich, hilfsbereite Hände zu suchen, um Zutaten zu beschaffen und ein Heilmittel zuzubereiten, ehe das Gift dauerhaften Schaden anrichtet."}},faq={{q="Wer ist Dirania Silberschein?",a="Dirania Silberschein ist eine Nachtelfe, die im Laubschattental auf Teldrassil anzutreffen ist. Sie fungiert als Questgeberin und sorgt sich vor allem um die Rettung und Heilung ihres Freundes Iverron, nachdem dieser mit der giftigen Tierwelt vor Ort in Konflikt geraten ist.",al={"dirania","wer ist dirania","dirania silberschein lore"}},{q="Wo kann ich Dirania Silberschein finden?",a="Dirania befindet sich im Laubschattental, dem Startgebiet auf Teldrassil, unweit des Hauptpfades nahe Aldrassil.",al={"dirania aufenthaltsort","wo ist dirania","dirania silberschein finden"}},{q="In welcher Beziehung steht Dirania zu Iverron?",a="Dirania und Iverron sind enge Freunde. Dirania ist die vernünftigere und wachsamere von beiden und greift ein, um ein Gegengift zu beschaffen, wann immer Iverron unbesonnen handelt und einen giftigen Biss von der hiesigen Fauna erleidet.",al={"ist dirania mit iverron verwandt","iverron und dirania","diranias freund"}},{q="Welche Quests bietet Dirania an?",a="Sie bietet Quests an, die sich darum drehen, ihrem Gefährten zu helfen – insbesondere „Ein Freund in der Not“ und „Iverrons Gegengift“ –, bei denen Abenteurer beauftragt werden, Zutaten zur Herstellung eines Heilmittels gegen Iverrons Spinnengift zu beschaffen.",al={"dirania quests","quests von dirania silberschein","iverron quest"}},{q="Warum macht sich Dirania Sorgen wegen Spinnen im Laubschattental?",a="Die Webwood-Spinnen im Geäst des Laubschattentals tragen ein starkes Gift in sich. Während erfahrene Schildwachen mit ihnen zurechtkommen, unterschätzen unerfahrene Elfen wie Iverron häufig die Gefahr und laufen Gefahr, ihren Bissen zu erliegen.",al={"laubschattental spinnen","warum spinnen auf teldrassil","webwood gefahr"}},{q="Gehört Dirania einem offiziellen Orden oder einer Fraktion an?",a="Dirania ist eine Nachtelfe der Allianz, die friedlich auf Teldrassil lebt. Sie wird nicht als aktives Mitglied der Schwesternschaft von Elune oder des Zirkels des Cenarius dargestellt, sondern vielmehr als fürsorgliche Zivilistin, die sich um ihr Volk kümmert.",al={"dirania fraktion","ist dirania ein druide","ist dirania eine schildwache"}}},fx={f156932e={q="Was möchte Dirania Silberschein?",a="Dirania sucht verzweifelt Hilfe für ihren engen Freund Iverron. Er wagte sich hinaus ins Laubschattental und wurde von den dort heimischen Webholzspinnen schwer vergiftet, was ihn handlungsunfähig gemacht hat. Sie benötigt jemanden, der schnell die notwendigen Zutaten im gesamten Tal sammelt, damit ein Gegengift gebraut werden kann, um sein Leben zu retten.",al={"dirania silberschein ziel","was braucht dirania","dirania silberschein wünsche"}},e30a1bf8={q="Warum ist Dirania Silberschein hier?",a="Dirania wohnt im Laubschattental und hat ihr Zuhause zusammen mit ihren Nachtelfen-Gefährten in den schützenden Zweigen von Aldrassil gefunden. Sie harrt hier in ihrer Not aus, nachdem ihr Freund Iverron in der Nähe dem Spinnengift zum Opfer fiel, und wartet auf fähige Reisende, die ihm zu Hilfe kommen.",al={"warum ist dirania im laubschattental","grund für dirania silberschein standort","warum ist dirania hier"}}},fp="19,222,23.348.0,16.388.0,27.209.0,37.119.0,42.211.0,31.194.0,51.221.0,51.217.0"}
P.entries["npc:dirge-quikcleave"] = {n="Dirge Schnetzelhack",s="Dirge Schnetzelhack ist ein Meister der Kochkunst und Händler der Goblins, der im Gasthaus von Gadgetzan Hof hält. Bekannt in ganz Azeroth für seine einfallsreichen Gerichte, bildet er erfahrene Köche aus, die die Kochkunst als Fachmann meistern wollen.",h="Dirge Schnetzelhack ist ein Meister der Kochkunst und Händler der Goblins, der im Gasthaus von Gadgetzan Hof...",kw={"fachmann kochkunst","muschelette surprise","kochkunstlehrer","dirge schnetzelhack","gadgetzan","goblin-koch","tanaris"},ang={["profession:Cooking"]="Dirge Schnetzelhack ist der führende Fachmann-Ausbilder für ehrgeizige Köche, der ihr Können mit seinen typischen Muschelette-Rezepten auf die Probe stellt, bevor er den Meisterstatus verleiht.",["race:Orc"]="Lehrer in Orgrimmar schicken angehende Feinschmecker der Horde direkt hinaus in die Wüste von Tanaris, um Dirges kulinarische Unterweisung zu suchen."},sec={{t="Meister des Fleischerbeils",b="Dirge Schnetzelhack lebt im staubigen Wüstenaußenposten Gadgetzan und serviert Getränke sowie Fleisch an durstige Reisende, die den Sand von Tanaris durchqueren. Obwohl er aus einer Grenztaverne heraus arbeitet, beansprucht er für sich den Titel des größten lebenden Kochkünstlers in Azeroth. Kochkunstlehrer in den Städten der ganzen Welt schicken ihre vielversprechendsten Schüler zu Dirge, sobald sie die gewöhnlichen Lektionen ausgeschöpft haben. Seine Kochkünste sind für anspruchsvolle, ungewöhnliche Zutaten bekannt – von riesigem Muschelfleisch und Eiern für seine Muschelette-Kreationen bis hin zu den exotischen Bestien ferner Küsten."},{t="Exotische Aromen und zwielichtige Gefälligkeiten",b="Hinter seinem Auftreten als Feinschmecker bewahrt sich Dirge den unternehmerischen Scharfsinn, der für jeden Goblin in der Wüste typisch ist. Er pflegt Kontakte zu exzentrischen Gestalten in ganz Kalimdor und hat ein Auge für gefährliche kulinarische Unternehmungen. Diejenigen, die bereit sind, Fleischstücke wilder Bestien zu beschaffen – wie etwa von den monströsen Chimaeroks, die auf der Insel des Schreckens in Feralas heimisch sind –, stellen fest, dass Dirge herzhafte Rezepte kreieren kann, die Champions auf gefahrvollen Reisen stärken – vorausgesetzt, man stellt nicht zu viele Fragen über seine privaten Geschäfte."}},faq={{q="Wer ist Dirge Schnetzelhack?",a="Dirge Schnetzelhack ist ein meisterhafter Goblin-Koch und Versorger im Gasthaus in Gadgetzan in Tanaris. Er gilt als einer der besten kulinarischen Könner Azeroths und bringt aufstrebenden Köchen bei, ihr Handwerk bis zur Fachmann-Stufe zu verfeinern.",al={"dirge schnetzelhack lore","wer ist dirge","gadgetzan koch"}},{q="Wo ist Dirge Schnetzelhack zu finden?",a="Er befindet sich in der Taverne der Boomtown Gadgetzan des Steamwheedle-Kartells, in den nördlichen Dünen von Tanaris.",al={"dirge aufenthaltsort","wo ist dirge schnetzelhack","dirge gasthaus"}},{q="Warum schicken Kochkunstlehrer Abenteurer zu ihm?",a="Die Kochkunstlehrer der Hauptstädte können die Fertigkeiten eines Lehrlings nur bis zu einem gewissen Punkt fördern. Sobald ein Koch die Expertenstufe erreicht, schicken ihn die Lehrer über die Quest 'Auf nach Gadgetzan!' zu Dirge nach Gadgetzan, damit er seinen Wert beweist und die Fachmann-Kochkunst freischaltet.",al={"warum dirge besuchen","fachmann kochkunst quest","auf nach gadgetzan"}},{q="Für welche Gerichte ist Dirge berühmt?",a="Dirge wird für seine Muschelette Surprise gefeiert, ein herzhaftes Omelett aus riesigem Muschelfleisch und Eiern, ebenso wie für deftige Wolfsteaks und seine wirkungsvollen Dirges abgefahrene Chimaerokkoteletts.",al={"dirge rezepte","muschelette surprise","was kocht dirge"}}},fx={["882c7cf6"]={q="Auf welcher Seite steht Dirge Schnetzelhack?",a="Dirge Schnetzelhack ist vollkommen neutral und arbeitet von der Wüstenaußenposten Gadgetzan des Steamwheedle Cartel aus. Wie die meisten Goblins der Handelskartelle dient er jedem, dessen Gold gut ist, und teilt bereitwillig seine kulinarische Meisterschaft, während er sowohl Kunden der Allianz als auch der Horde mit Essen versorgt.",al={"fraktion von dirge schnetzelhack","ist dirge horde oder allianz","wem dient dirge schnetzelhack"}},["6a938a01"]={q="Was möchte Dirge Schnetzelhack?",a="Dirge wird von einer Leidenschaft für extreme und exotische Kochkunst angetrieben. Er sucht nach seltenem, ungewöhnlichem Fleisch und frischen Zutaten aus den gefährlichen Ecken der Welt, um Meisterwerke wie seine berühmten Muschelsnacks und Chimärenkoteletts zu kreieren, stets bereit, gewagte Beute in kulinarische Brillanz zu verwandeln.",al={"dirge schnetzelhack ziele","was braucht dirge schnetzelhack","warum möchte dirge zutaten"}},["97163837"]={q="Warum ist Dirge Schnetzelhack in Gadgetzan?",a="Die Arbeit vom geschäftigen Gasthaus in Gadgetzan aus versetzt Dirge direkt an einen wichtigen Kreuzungspunkt für wagemutige Entdecker, Monsterjäger und Wüstenreisende. Es bietet dem Goblin-Koch einen stetigen Strom an Kunden, die nach herzhaften Proviant suchen, sowie wagemutigen Köchen, die nach seiner handwerklichen Anleitung streben.",al={"warum ist dirge in gadgetzan","dirge schnetzelhack tanaris warum","warum ist dirge hier"}},["60da7b2e"]={q="Mit wem ist Dirge Schnetzelhack verbunden?",a="Dirge hat sein Zuhause unter den Goblins des Steamwheedle Cartel in Gadgetzan gefunden und bedient Reisende und Wüstenwanderer aller Art. Er unterhält auch Verbindungen zu exzentrischen Persönlichkeiten wie Narain Pfauentraum, der weiß, an wen man sich wenden muss, wenn exotische High-End-Gerichte gefragt sind.",al={"dirge schnetzelhack verbündete","wen kennt dirge","dirge verbindungen"}}},fp="16,214,21.555.0,31.506.0,24.244.0,36.115.0,48.245.0,32.177.0"}
P.entries["npc:doan-karhan"] = {n="Doan Karhan",s="Doan Karhan ist ein menschlicher Gelehrter und Praktizierender der dunklen Künste, der isoliert im südlichen Brachland weilt. Er hat sein Leben der Erforschung der dämonischen Artefakte der Brennenden Legion gewidmet, insbesondere der rätselhaften Kugel von Soran'ruk.",h="Doan Karhan ist ein menschlicher Gelehrter und Praktizierender der dunklen Künste, der isoliert im südlichen...",kw={"brachland","doan karhan","kugel von soran'ruk","orb of zargain","hexenmeister"},ang={["class:Warlock"]="Doan Karhan ist eine unschätzbare Ressource für erfahrene Hexenmeister, da er über das arkane Wissen verfügt, das erforderlich ist, um legendäre dämonische Kugeln aufzudecken, instand zu setzen und zu führen.",["faction:Alliance"]="Obwohl er ein Mensch ist, agiert Doan fernab von Sturmwind oder Theramore und zieht das einsame Exil im Herzen von Kalimdor den Beschränkungen der Großen Allianz vor."},sec={{t="Der Einsiedler des Brachlands",b="Versteckt in einem einsamen Lager in der wilden Savanne des südlichen Brachlands lebt Doan Karhan fernab der zivilisierten Bastionen der Allianz. Statt gewöhnliche Einsamkeit zu suchen, zog er sich in die Wildnis zurück, um ungestört gefährliche dämonische Relikte zu studieren. Doan besitzt tiefes Wissen über mächtige Teufelsgefäße, ist im Besitz der Orb of Zargain und besessen von der legendären Kugel von Soran'ruk. Praktizierende Hexenmeister suchen ihn oft auf, wenn sie sich mit Artefaktherstellung und dunklen Ritualen befassen."}},faq={{q="Wo befindet sich Doan Karhan?",a="Doan Karhan hat sein Lager im südlichen Brachland aufgeschlagen, versteckt östlich von Camp Taurajo und der Hauptstraße. Er haust allein auf einer kleinen, leicht zu übersehenden Lichtung.",al={"doan karhan aufenthaltsort","wo ist doan karhan","doan karhan südliches brachland"}},{q="Warum lebt ein Mensch allein im Brachland?",a="Doan Karhan wählte das Exil in der feindseligen Wildnis, um Forschungen an den magischen Relikten der Brennenden Legion nachzugehen. Solch dunkle Studien über dämonische Kugeln sind in zivilisierten Allianzgebieten verboten oder werden streng überwacht.",al={"warum ist doan hier","warum ist ein mensch im brachland","doan karhan geschichte"}},{q="Was ist die Kugel von Soran'ruk?",a="Die Kugel von Soran'ruk ist ein uraltes, mächtiges Legionsrelikt, das von dunkler Macht erfüllt ist. Doan Karhan besitzt umfassendes Wissen über ihren Aufbau sowie über die ähnliche Orb of Zargain und leitet Hexenmeister an, die sie rekonstruieren wollen.",al={"kugel von soranruk","kugel von soran'ruk","was ist die kugel von soran'ruk"}}},fp="11,236,25.487.0,29.160.0,43.214.0,29.224.0"}
P.entries["npc:doctor-gregory-victor"] = {n="Doktor Gregory Victor",s="Doktor Gregory Victor ist ein Chirurg der Verlassenen, der im Horde-Außenposten Hammerfall im Arathihochland stationiert ist. Als führender Traumamediziner innerhalb der Horde bekannt, beurteilt er angehende Sanitäter, die fortgeschrittene Triage und Erste Hilfe auf dem Schlachtfeld meistern wollen. Seine kalte, klinische Effizienz hält die Krieger an der Front inmitten erbitterter regionaler Konflikte zusammengeflickt.",h="Doktor Gregory Victor ist ein Chirurg der Verlassenen, der im Horde-Außenposten Hammerfall im Arathihochland...",kw={"arathihochland","doktor gregory victor","erste hilfe","gregory victor","hammerfall","traumachirurg der horde","chirurg","triage"},ang={["faction:Horde"]="Doktor Victor leistet entscheidende Schlachtfeldmedizin in einem der prekärsten Außenposten der Horde und stellt sicher, dass die Krieger an der Arathifront wieder kampffähig werden.",["race:Undead"]="Im Gegensatz zu den giftigen Gebräuen der Königlichen Apothekervereinigung demonstriert Doktor Victor die Meisterschaft der Verlassenen über die gewöhnliche sterbliche Anatomie und wiederherstellende Chirurgie."},sec={{t="Chirurg von Hammerfall",b="Während viele die Apotheker der Verlassenen mit Argwohn betrachten, dient Doktor Gregory Victor der Horde durch praktische Schlachtfeldchirurgie statt durch alchemistische Seuchenmittel. Tief im umkämpften Arathihochland in Hammerfall stationiert, operiert er Soldaten, die von Banditen des Syndikats, Ogern der Felsfäuste und Streitkräften der Allianz verwundet wurden. Seine Station dient zugleich als wichtigstes Prüfungsfeld für Feldsanitäter der Horde und verlangt unter großem Druck unerbittliche Effizienz und die Priorisierung kritischer Patienten."}},faq={{q="Wer ist Doktor Gregory Victor?",a="Doktor Gregory Victor ist ein Arzt der Verlassenen, der in Hammerfall im Arathihochland stationiert ist. Er ist der oberste Traumachirurg der Horde und dafür verantwortlich, Triage-Einsätze zu beaufsichtigen und fortgeschrittene Feldsanitäter auszubilden.",al={"doktor victor","gregory victor","wer ist gregory victor"}},{q="Wo kann ich Doktor Gregory Victor finden?",a="Er befindet sich innerhalb der Festung von Hammerfall im nordöstlichen Arathihochland.",al={"gregory victor aufenthaltsort","wo ist victor","doktor victor wo"}},{q="Welche Rolle spielt er für die Horde?",a="Doktor Victor prüft vielversprechende Feldsanitäter durch ein rigoroses Examen in Schlachtfeld-Triage und bringt ihnen bei, wie man Sterbende stabilisiert und fortschrittliche Stoffverbände für den Fronteinsatz herstellt.",al={"was macht gregory victor","gregory victor erste hilfe","horde traumachirurg"}},{q="Wer ist sein Gegenstück bei der Allianz?",a="Doktor Gustav van Howzen, stationiert auf der Insel Theramore in den Düstermarschen, leitet die fortgeschrittene Trauma- und Triage-Ausbildung für die Allianz.",al={"allianz äquivalent doktor victor","allianz triage arzt"}}},fx={d46fa605={q="Auf welcher Seite steht Doktor Gregory Victor?",a="Doktor Gregory Victor ist der Horde und den Verlassenen treu ergeben. Er ist in Hammerfall im Arathihochland stationiert und fungiert als erfahrener Chirurg, der sich um die Verwundeten der Fraktion kümmert und fortgeschrittenes Wissen in der Triage an diejenigen weitergibt, die bereit sind zu lernen.",al={"welcher fraktion gehört gregory victor an","ist doktor victor horde","doktor victor loyalität"}},["5e053b25"]={q="Was möchte Doktor Gregory Victor?",a="Doktor Victor widmet sich der Feldmedizin und Chirurgie. Er sucht fähige Sanitäter für das Schlachtfeld, die mit Triage unter hohem Druck umgehen können, und testet angehende Heiler, um sicherzustellen, dass sie Prioritäten bei der Behandlung setzen und inmitten des Kriegswirrwarrs Leben retten können.",al={"was möchte doktor victor","doktor gregory victor ziele","was macht victor"}},["3e1305a9"]={q="Warum ist Doktor Gregory Victor hier?",a="Doktor Victor ist in Hammerfall stationiert, um die Frontlinien der Horde im umkämpften Arathihochland zu unterstützen. Bei ständigen Scharmützeln gegen die Allianz und lokalen Bedrohungen ist ein erfahrener Traumachirurg unerlässlich, um Soldaten am Leben zu erhalten.",al={"warum ist gregory victor hier","warum ist doktor victor in hammerfall","grund für victors anwesenheit"}}},fp="21,369,21.487.0,29.225.0,39.93.0,37.191.0,32.136.0"}
P.entries["npc:doctor-gustaf-vanhowzen"] = {n="Doktor Gustav van Howzen",s="Doktor Gustav van Howzen dient als Traumachirurg und Chefarzt der Traumachirurgen der Allianz auf der Insel Theramore. Er ist in der Foothold-Zitadelle stationiert, bildet die Heiler der Insel aus und beurteilt Sanitäter, welche die höchsten Stufen der Feldtriage und Verbandskunst meistern wollen.",h="Doktor Gustav van Howzen dient als Traumachirurg und Chefarzt der Traumachirurgen der Allianz auf der Insel...",kw={"traumachirurg der allianz","erste hilfe fachmann","erste hilfe","foothold-zitadelle","gustaf van howzen","theramore","triage","vanhowzen"},ang={["faction:Alliance"]="Jeder Sanitäter der Allianz, der die Feldchirurgie meistern möchte, muss nach Theramore reisen und seine Triagefähigkeiten unter den wachsamen Augen von Doktor Van Howzen unter Beweis stellen."},sec={{t="Chefarzt von Theramore",b="Doktor Gustav van Howzen befindet sich im Erdgeschoss der Foothold-Zitadelle auf der Insel Theramore, überwacht die medizinische Versorgung der Truppen von Lady Jaina Prachtmeer und bildet die Frontheiler des Außenpostens aus. Angesichts der rauen Bedingungen in den Düstermarschen besteht Van Howzen auf rigorose Feldkompetenz und unterzieht erfahrene Sanitäter persönlich einem intensiven Triagetest, um sicherzustellen, dass sie unter starkem Druck kritische Wunden priorisieren können."}},faq={{q="Wo ist Doktor Gustav van Howzen zu finden?",a="Doktor Van Howzen ist im Erdgeschoss der Foothold-Zitadelle stationiert, der Hauptfestung auf der Insel Theramore in den Düstermarschen.",al={"vanhowzen aufenthaltsort","wo ist gustaf vanhowzen","gustaf vanhowzen standort"}},{q="Welche Rolle übernimmt Van Howzen für die Allianz?",a="Er ist der Chefarzt der Traumachirurgen der Allianz und der führende Traumachirurg in Theramore. Neben der Aufsicht über die Krankenstation der Garnison dient er als Erste-Hilfe-Fachmann-Lehrer für erfahrene Feldsanitäter der Allianz.",al={"was macht vanhowzen","rolle von vanhowzen","wer ist doktor vanhowzen"}},{q="Was lehrt Doktor Van Howzen die Spieler?",a="Er bietet die Triage-Prüfung für Erste-Hilfe-Fachmänner an, wodurch erfahrene Sanitäter ihre Fertigkeitsobergrenze erhöhen können, und unterweist qualifizierte Anwender in der Herstellung fortschrittlicher Verbände wie schwerer Magiestoff- und Runenstoffverbände.",al={"was lernt man bei vanhowzen","vanhowzen ausbildung","erste hilfe von vanhowzen"}},{q="Hat die Horde ein Gegenstück zu Doktor Van Howzen?",a="Ja. Der entsprechende Traumaspezialist der Horde ist Doktor Gregory Victor, der in Hammerfall im Arathihochland Feldsanitäter ausbildet und Triageprüfungen abnimmt.",al={"horde triagelehrer","horde vanhowzen gegenstück","wer ist erste hilfe meister der horde"}}},fx={["5f514c39"]={q="Wer ist Doktor Gustav van Howzen?",a="Doktor Gustav van Howzen ist der leitende Arzt der Alliance Trauma und ein Meister der Traumachirurgie, der auf der Insel Theramore stationiert ist. In der gesamten Allianz für seine schlachtfeldmedizinische Expertise bekannt, ist er für die Überwachung der Ausbildung der Heiler von Theramore und das Lehren fortgeschrittener Triage-Techniken für Feldsanitäter verantwortlich.",al={"wer ist vanhowzen","gustav vanhowzen","wer ist doktor gustav vanhowzen"}},d768860b={q="Auf welcher Seite steht Doktor Gustav van Howzen?",a="Doktor van Howzen ist der Allianz vollkommen loyal ergeben. Er leitet das medizinische Korps, bekannt als Alliance Trauma, und dient unter dem Banner von Lady Jaina Prachtmeer, um sicherzustellen, dass Soldaten und Abenteurer an der Front durch rigorose Feldmedizin am Leben erhalten werden.",al={"vanhowzen fraktion","ist vanhowzen allianz","loyalität von doktor gustav vanhowzen"}},c346cbcd={q="Was möchte Doktor Gustav van Howzen?",a="Doktor van Howzen möchte die höchsten Standards der Traumabehandlung bei den Streitkräften der Allianz aufrechterhalten. Auf dem Schlachtfeld kostet Zögern Leben, daher versucht er, kompetente Feldsanitäter in Triage-Methoden zu testen und auszubilden, um mit schweren Kampfverletzungen unter extremem Druck umgehen zu können.",al={"was möchte vanhowzen","vanhowzen motiv","doktor vanhowzen ziel"}},["12e0bbc2"]={q="Warum ist Doktor Gustav van Howzen hier?",a="Doktor van Howzen ist in der Foothold-Zitadelle auf der Insel Theramore stationiert, kümmert sich um die Verletzten der militärischen Bastion und bildet die Heiler der lokalen Garnison aus. Von hier aus testet er angehende Traumasanitäter, die durch Kalimdor reisen und Meisterschaft in Erster Hilfe beweisen.",al={"warum ist vanhowzen in theramore","warum ist doktor vanhowzen hier","wo arbeitet vanhowzen"}},["9903e76f"]={q="Mit wem ist Doktor Gustav van Howzen verbunden?",a="Doktor van Howzen dient der Garnison der Allianz auf der Insel Theramore und arbeitet unter den regionalen Streitkräften von Lady Jaina Prachtmeer. Er koordiniert sich direkt mit den militärischen Heilern der Allianz und befehligt den medizinischen Flügel der Alliance Trauma.",al={"vanhowzen zugehörigkeiten","wem dient vanhowzen","verbindungen von doktor gustav vanhowzen"}}},fp="23,268,28.425.0,43.136.0,48.222.0,41.216.0,54.167.0"}
P.entries["npc:donova-snowden"] = {n="Donova Schneeweh",s="Donova Schneeweh ist eine unerschrockene Zwergenforscherin, die an den Thermalquellen nahe den Frostfeuerquellen in Winterquell ihr Lager aufgeschlagen hat. Trotz der bitteren Kälte und der feindseligen Tierwelt studiert sie die seltsame thermische Aktivität der Region und überwacht die zunehmend verdorbenen Furbolgs der Winterfall.",h="Donova Schneeweh ist eine unerschrockene Zwergenforscherin, die an den Thermalquellen nahe den...",kw={"donova schneeweh","feuerwasser","die frostfeuerquellen","furbolg","forscherin","winterfall","winterquell"},ang={["faction:Horde"]="Trotz ihres zwergischen Erbes ist Donova bereit, über Fraktionszugehörigkeiten hinwegzusehen, um fähige Kundschafter gegen die wilden Bestien und verdorbenen Furbolgs von Winterquell zu gewinnen.",["race:Dwarf"]="Eine Zwergenschwester zu treffen, die den gefrorenen Gipfeln allein trotzt, wirkt vertraut und zeigt den unermüdlichen Tatendrang der Zwerge bei der Feldforschung und Erkundung fernab von Khaz Modan."},sec={{t="Eine einsame Forscherin im Schnee",b="Während die meisten Reisenden in der Sicherheit von Ewige Warte bleiben, hat sich Donova Schneeweh entschieden, in der eisigen Wildnis nahe den Frostfeuerquellen zu lagern. Sie verbringt ihre Tage damit, die sonderbaren geothermischen Anomalien zu untersuchen, die durch den Permafrostboden emporblubbern, sowie die dunklen Einflüsse zu erforschen, die auf die heimische Tierwelt von Winterquell übergreifen. Praktisch veranlagt und entschlossen wirbt sie vorbeikommende Abenteurer der Allianz und der Horde an, um Proben zu sammeln und lokale Bedrohungen einzudämmen."},{t="Untersuchung der Winterfall",b="Ein Großteil von Donovas Aufmerksamkeit gilt den Furbolgs der Winterfall, deren Verhalten sich zu unberechenbarer Aggression gewandelt hat. Durch die Untersuchung potenter Gebräue wie dem Feuerwasser der Winterfelle und merkwürdiger giftiger Substanzen, die unter den Stämmen zirkulieren, versucht sie, die eigentliche Ursache für ihren plötzlichen Verfall in den Wahnsinn aufzudecken. Ihre Feldforschung macht sie zu einer unverzichtbaren Ansprechpartnerin für jeden, der die Verderbnis verstehen will, die sich in den nördlichen Bergen ausbreitet."}},faq={{q="Wo finde ich Donova Schneeweh?",a="Donova Schneeweh lagert an einer kleinen heißen Quelle südwestlich direkt gegenüber der Hauptstraße bei den Frostfeuerquellen in Winterquell.",al={"donova schneeweh aufenthaltsort","wo ist donova","donova schneeweh karte"}},{q="Warum ist Donova hier draußen in der eisigen Kälte?",a="Sie betreibt Umweltforschung an den ungewöhnlichen heißen Quellen von Winterquell und untersucht die Verderbnis, die den örtlichen Stamm der Winterfall-Furbolgs befallen hat.",al={"warum ist donova in winterquell","donova schneeweh zweck"}},{q="Arbeitet Donova mit Hordespielern zusammen?",a="Ja. Obwohl sie eine Zwergin ist, agiert Donova als unabhängige Forscherin und vergibt Aufgaben an Abenteurer der Allianz und der Horde gleichermaßen.",al={"ist donova nur allianz","kann horde mit donova sprechen","donova schneeweh fraktion"}},{q="Was untersucht Donova bezüglich der Winterfall-Furbolgs?",a="Sie studiert die mysteriöse Verderbnis, die den Stamm der Winterfall in den Wahnsinn treibt, und untersucht dabei insbesondere deren sonderbare Gebräue wie das Feuerwasser der Winterfelle und üble, giftige Substanzen bei ihren Läufern.",al={"donova furbolg quest","feuerwasser der winterfelle forschung"}}},fp="14,292,29.469.0,28.457.1,32.130.0,44.159.0,36.128.0,63.214.0"}
P.entries["npc:donyal-tovald"] = {n="Donyal Tovald",s="Donyal Tovald ist ein menschlicher Verwalter, der in der Royal Library innerhalb von Burg Sturmwind dient. Im Rahmen einer Initiative des jungen Königs Anduin Wrynn beaufsichtigt er die Pflege der Bücher des Königreichs und setzt sich dafür ein, Kopien historischer Texte an die breitere Öffentlichkeit zu verteilen.",h="Donyal Tovald ist ein menschlicher Verwalter, der in der Royal Library innerhalb von Burg Sturmwind dient.",kw={"anduin wrynn","bücher","donyal tovald","geschichte","bibliothekar","royal library","burg sturmwind"},ang={["class:Mage"]="Magier, die Burg Sturmwind besuchen, wissen Tovalds Hingabe zur Bewahrung des geschriebenen Wissens vielleicht zu schätzen, auch wenn die Texte eher historischer als arkaner Natur sind.",["race:Human"]="Für die Menschen von Sturmwind repräsentiert Tovald das Bestreben, ihre Kultur und aufgezeichnete Geschichte nach dem Ersten Krieg und dem Wiederaufbau der Hauptstadt neu aufzubauen und zu bewahren."},sec={{t="Verwalter von Sturmwinds Geschichte",b="In den ruhigen Nischen des Flügels der Royal Library in Burg Sturmwind kümmert sich Donyal Tovald um die umfangreiche Sammlung historischer Berichte, Schriftrollen und wissenschaftlicher Bände des Königreichs. Während die Bibliothek in erster Linie dem Adel und dem königlichen Hof dient, hat der junge König Anduin Wrynn eine Initiative gefördert, um das Wissen für gewöhnliche Bürger zugänglicher zu machen. Tovald kümmert sich um die Bewahrung und Vervielfältigung dieser Texte und trägt dazu bei, dass die Lehren und Triumphe der Allianz im turbulenten politischen Klima des Königreichs nicht in Vergessenheit geraten."}},faq={{q="Wer ist Donyal Tovald?",a="Donyal Tovald ist ein menschlicher Bibliothekar, der in der Royal Library von Burg Sturmwind stationiert ist. Er pflegt die Archive des Königreichs und leitet eine von König Anduin Wrynn unterstützte Initiative zur Verteilung von Kopien historischer Bücher an die Öffentlichkeit.",al={"wer ist tovald","königlicher bibliothekar","donyal tovald lore"}},{q="Wo kann ich Donyal Tovald finden?",a="Er ist im Flügel der Royal Library auf der Ostseite von Burg Sturmwind zu finden, umgeben von Bücherregalen und historischen Schriftrollen.",al={"donyal tovald standort","wo ist tovald","wie man tovald findet"}},{q="Warum verteilt er Bücher an die Bürger?",a="Der junge König Anduin Wrynn förderte ein königliches Projekt zur Bildung der Öffentlichkeit und zur Weitergabe von Wissen. Donyal Tovald fungiert als Verwalter, der die Vervielfältigung und Verteilung dieser königlichen Manuskripte überwacht.",al={"anduin buchinitiative","sturmwind bibliotheksprojekt","warum verteilt er bücher"}},{q="Gehört er dem Haus der Adligen oder dem Klerus an?",a="Tovald untersteht als Hüter der königlichen Archive in Burg Sturmwind direkt der Krone und konzentriert sich eher auf historische und wissenschaftliche Texte als auf kirchliche oder politische Doktrinen.",al={"gehört tovald zur kirche des lichts","tovald fraktion"}}},fx={["18ed48d6"]={q="Auf welcher Seite steht Donyal Tovald?",a="Tovald ist ein loyaler Diener des Königreichs Sturmwind und der Allianz. Er ist direkt in der Burg Sturmwind stationiert, untersteht der königlichen Verwaltung und unterstützt direkt die Bildungsbemühungen, die der junge König Anduin Wrynn fördert.",al={"loyalität von donyal tovald","fraktion von donyal tovald","wem dient donyal"}},["6c9214b5"]={q="Was möchte Donyal Tovald?",a="Tovald möchte die Geschichte des Königreichs bewahren und die Lese- und Schreibfähigkeit unter seinem Volk fördern. Er betreut die Archive innerhalb der Royal Library und arbeitet daran, Bildungsexemplare in die Hände normaler Bürger in ganz Sturmwind zu geben.",al={"donyal tovald ziel","was versucht donyal zu tun","donyal tovald zweck"}},["715728b5"]={q="Warum ist Donyal Tovald hier in der Royal Library?",a="Tovald ist im Flügel der Royal Library in der Burg Sturmwind stationiert, um als einer ihrer Verwalter zu dienen. Von diesem Posten aus bewahrt er das angesammelte Wissen des Reiches und verwaltet die Verteilung von Texten, die von der Krone autorisiert wurden.",al={"warum ist donyal tovald in der burg sturmwind","pflichten von donyal tovald in der bibliothek","warum ist donyal hier"}}},fp="13,260,30.548.0,21.230.0,31.134.0,40.201.0,56.186.0"}
P.entries["npc:doomsayer-wiserunner"] = {n="Seher Wiserunner",s="Dieser angesehene Taurenälteste ist bekannt als Seher Wiserunner und dient seinem Volk treu in den sanften Hügeln von Mulgore. Von einer Höhle in den Hügeln nordwestlich vom Dorf der Bluthufe aus unterstützt er junge Taurenmutige, während sie die traditionellen Übergangsriten absolvieren, die sie in das geistige Erwachsenenalter führen.",h="Dieser angesehene Taurenälteste ist bekannt als Seher Wiserunner und dient seinem Volk treu in den sanften...",kw={"camp narache","doomsayer wiserunner","mulgore","ritus der vision","ritus der weisheit","seher wiserunner","taurenältester"},ang={["class:Shaman"]="Schamanen werden Wiserunner als Bewahrer alter Traditionen anerkennen, der die Botschaften versteht, die durch Erde und Himmel gewebt sind.",["race:Tauren"]="Für junge Shu'halo, die sich über die Hochwolkenebene hinauswagen, ist Seher Wiserunner ein wesentlicher Mentor auf der Reise der Ahnen in Richtung geistiger Reife."},sec={{t="Ein Führer auf dem heiligen Pfad",b="Seher Wiserunner steht inmitten der sanften Klippen von Mulgore als Ältester und Mystiker der Shu'halo. Wenn junge Jäger und Schamanen ihre ersten Prüfungen der Stärke und Sicht abschließen, werden sie zu ihm gesandt, um während ihrer Ahnenriten seinen Rat zu suchen. Er interpretiert Visionen der Erdenmutter und leitet die Jugend an, ihre Vorfahren zu ehren, wobei er die beständige Weisheit anbietet, die die verstreuten nomadischen Stämme zu einer vereinten Gemeinschaft zusammenschließt."}},faq={{q="Warum wird dieser NPC mit dem Namen 'Doomsayer Wiserunner' in Verbindung gebracht?",a="Er ist bekannt als Seher Wiserunner, ein geehrter Taurenältester, der bei den Stämmen von Mulgore in hohem Ansehen steht. Er hat nichts mit Untergangsprophezeiungen zu tun; seine Aufgabe ist es, junge Initianden durch heilige Riten zu führen.",al={"doomsayer wiserunner name","warum doomsayer","seer gegen doomsayer"}},{q="Welche Rolle spielt er in Mulgore?",a="Seher Wiserunner dient als geistiger Mentor für junge Tauren. Nachdem Mutige ihre ersten Visionsquests begonnen haben, empfängt er sie, um den traditionellen Ritus der Weisheit zu vollenden und ihre Bereitschaft zu prüfen, sowohl dem Stamm als auch der Erdenmutter zu dienen.",al={"was macht wiserunner","zweck von seer wiserunner","rolle von wiserunner"}},{q="Wo ist Seher Wiserunner zu finden?",a="Er ist in einer Höhle in den Hügeln nordwestlich des Dorfes der Bluthufe zu finden, wohin die Vision aus dem Ritus der Sicht die Taurenjugend führt. Von dort aus entsendet er sie östlich von Donnerfels zu den Ahnengeistern von Teufelsfelsen.",al={"wo ist wiserunner","standort von seer wiserunner","wiserunner koordinaten"}}},fx={f44673b7={q="Auf welcher Seite steht Seher Wiserunner?",a="Er ist den Stämmen der Tauren und der Horde treu ergeben. Seher Wiserunner ist in Mulgore stationiert und führt junge Tauren durch ihre heiligen Prüfungen der Ahnen, wobei er die ehrwürdigen spirituellen Traditionen seines Volkes hochhält und die Weisheit der Erdenmutter ehrt.",al={"fraktion von seher wiserunner","wiserunner seite","ist seher wiserunner horde"}},fbd19081={q="Was möchte Seher Wiserunner?",a="Er versucht, junge Tauren durch ihre heiligen spirituellen Meilensteine zu leiten. Indem er Prüfungen wie die Rite of Wisdom leitet, stellt er sicher, dass die nächste Generation die Führung der Ahnen ehrt und ihre Würdigkeit vor den Geistern beweist.",al={"seher wiserunner ziel","was möchte wiserunner","seher wiserunner motiv"}},bf3ce735={q="Warum ist Seher Wiserunner hier?",a="Er residiert in den sanften Hügeln von Mulgore, um als spiritueller Mentor zu dienen. Wenn Tauren-Jugendliche ihre heiligen Riten des Übergangs unternehmen, wartet er auf sie, um ihre Einsicht zu prüfen und denjenigen, die ihre Pilgerreise vollenden, die Weisheit der Ahnen zu verleihen.",al={"warum ist seher wiserunner in mulgore","grund für standort von seher wiserunner","warum ist wiserunner hier"}}},fp="15,293,26.435.0,64.196.0,34.235.0,35.217.0"}
P.entries["npc:doras"] = {n="Doras",s="Doras ist der oberste Windreitermeister der Horde in Orgrimmar und befindet sich hoch oben auf dem Holzturm über dem Tal der Stärke. Er beaufsichtigt die Wyvern der Hauptstadt und entsendet Kuriere, Späher und Reisende durch ganz Kalimdor.",h="Doras ist der oberste Windreitermeister der Horde in Orgrimmar und befindet sich hoch oben auf dem Holzturm...",kw={"doras","flugmeister","orgrimmar","tal der stärke","windreitermeister","wyvern"},ang={["faction:Horde"]="Für jeden Abenteurer der Horde stellt Doras die wichtigste Flugverbindung aus der Hauptstadt dar und ermöglicht rasches Reisen zu verbündeten Siedlungen in ganz Kalimdor."},sec={{t="Meister der Luftwege",b="Auf der hölzernen Plattform über dem Tal der Stärke versorgt Doras die geflügelten Raubtiere, die als Windreiter oder Wyvern bekannt sind. Seit die Horde sich in Durotar niedergelassen hat, sind diese gerissenen Bestien mit ihren ledernen Schwingen zum Rückgrat der Kommunikation und des Transports der Horde in Kalimdor geworden. Doras leitet ihre Pflege, teilt ausgeruhte Reittiere den Reitern zu und sorgt dafür, dass wichtige Botschaften und Verstärkungen abgelegene Vorposten wie das Wegekreuz, Donnerfels und Siedlungen tief in Eschental oder den Düstermarschen erreichen."}},faq={{q="Wo kann ich Doras finden?",a="Doras ist auf der Spitze des Flugturms direkt über dem Tal der Stärke in Orgrimmar stationiert. Reisende können seinen Hochsitz über die gewundenen Rampen der zentralen Holzkonstruktionen nahe dem Stadteingang erreichen.",al={"doras standort","wo ist der flugmeister von orgrimmar","orgrimmar wyvernmeister"}},{q="Welche Kreaturen bildet Doras aus?",a="Doras betreut Windreiter, die gemeinhin auch als Wyvern bezeichnet werden. Diese intelligenten, giftigen geflügelten Raubtiere, die in den kargen Felsen und Savannen von Kalimdor heimisch sind, wurden von der Horde gezähmt und dienen als verlässliche Flugreittiere über weite Strecken.",al={"orgrimmar reittiere","was fliegt doras","was sind windreiter"}},{q="Wohin kann Doras Reisende schicken?",a="Von seinem Hochsitz in Orgrimmar aus verbindet Doras Reisende mit etablierten Vorposten der Horde im gesamten zentralen und nördlichen Kalimdor, einschließlich des Wegekreuzes im Brachland, Donnerfels in Mulgore sowie Militärlagern in Eschental und darüber hinaus.",al={"doras flugrouten","wohin kann ich von orgrimmar fliegen","orgrimmar flugwege"}}},fx={["65cae112"]={q="Wer ist Doras?",a="Doras ist der wichtigste Flugmeister der Horde in Orgrimmar. Hoch über der Stadt stationiert, kümmert er sich um die Wyvern der Hauptstadt und koordiniert den Lufttransport für Kuriere, Soldaten und Abenteurer, die durch Kalimdor reisen.",al={"wer ist doras","doras identität","doras orgrimmar"}},fb843279={q="Auf wessen Seite steht Doras?",a="Doras ist der Horde treu ergeben und dient in Orgrimmar direkt unter dem Kommando von Kriegshäuptling Thrall. Er stellt sicher, dass nur vertrauenswürdige Verbündete der Horde das Luftverkehrsnetz der Stadt nutzen.",al={"doras fraktion","ist doras horde","doras loyalität"}},["54873cb0"]={q="Warum ist Doras hier?",a="Als Flugmeister der Hauptstadt der Horde beaufsichtigt Doras den zentralen Knotenpunkt ihres Wyvern-Netzwerks. Er bleibt in Orgrimmar stationiert, um lebenswichtige Transportverbindungen zwischen dem Sitz des Kriegshäuptlings und den Außenposten in ganz Durotar, dem Brachland und darüber hinaus bereitzustellen.",al={"warum ist doras in orgrimmar","doras rolle","doras zweck hier"}},f6504325={q="Was will Doras?",a="Doras konzentriert sich auf die Pflege seiner Wyvern und die Aufrechterhaltung zuverlässiger Kurier- und Reiserouten durch ganz Kalimdor. Er möchte dafür sorgen, dass Kommunikation und Verstärkung schnell dorthin gelangen, wo die Interessen der Horde umkämpft sind.",al={"was will doras","doras motive","doras ziel"}}},fp="5,225,20.498.0,23.213.0,32.246.0,31.232.0"}
P.entries["npc:doren"] = {n="Doren",s="Lieutenant Doren befehligt das Rebellenlager im nördlichen Schlingendorntal. Einst ein Offizier unter Colonel Kurzen, führte Doren eine Meuterei an, nachdem sein Vorgesetzter und die übrigen Expeditionsteilnehmer dem Wahnsinn verfallen waren. Nun leitet er einen Guerillawiderstand, der entschlossen ist, die Quelle dieses Leidens aufzudecken und Kurzen zu beseitigen.",h="Lieutenant Doren befehligt das Rebellenlager im nördlichen Schlingendorntal.",kw={"buchmacher herod","colonel kurzen","doren","kurzen","kurzens truppenlager","lieutenant doren","rebellenlager","schlingendorntal","thorsen"},ang={["faction:Alliance"]="Für Soldaten der Allianz verkörpert Doren die tragischen Nachwirkungen von Sturmwinds Dschungelexpedition und bietet die Chance, Kurzens Verfehlungen wiedergutzumachen und die Ordnung an der wilden Grenze wiederherzustellen.",["race:Human"]="Menschliche Reisende werden Dorens militärische Disziplin wiedererkennen – eine Mahnung an den Tribut, den ein isolierter Dienst fernab des Königreichs Sturmwind Geist und Moral abverlangen kann."},sec={{t="Eine Meuterei im Dschungel",b="Lieutenant Doren wurde ursprünglich unter dem Banner von Sturmwind und dem Kommando von Colonel Kurzen ins Schlingendorntal entsandt. Die Expedition sollte einen Stützpunkt im wilden südlichen Dschungel errichten, doch die Lage verschlechterte sich rasch, als Kurzen und sein engster Kreis einem unberechenbaren, gewalttätigen Wahnsinn erlagen. Da sie sich weigerten, ihren Verstand oder ihre Ehre aufzugeben, verließen Doren und ein Kader von Loyalisten die Formation. Sie flohen nach Norden und errichteten das Rebellenlager entlang der Straße, wobei sie den Übertritt der Knechtschaft unter einem Verrückten vorzogen."},{t="Aufdeckung der Wahrheit",b="Von ihrem prekären Außenposten aus überwacht Doren Operationen gegen Kurzens Truppenlager. Er unterhält Nachschublinien zu neutralen Parteien, darunter Goblin-Kontakte wie Krazek unten in Beutebucht, um seine schwindenden Truppen mit Nahrung und Waffen zu versorgen. Neben dem bloßen Überleben sucht Doren nach Antworten: Er setzt Spione wie Private Thorsen hinter den feindlichen Linien ein, um herauszufinden, was den Colonel verflucht hat, und um Verräter sowie Kollaborateure wie Buchmacher Herod aufzuspüren. Letztlich glaubt Doren, dass der einzige Weg, die verbliebene Ehre ihrer Expedition zu retten, darin besteht, Kurzen selbst den Garaus zu machen."}},faq={{q="Wer ist Lieutenant Doren?",a="Lieutenant Doren ist der Anführer des Rebellenlagers im nördlichen Schlingendorntal. Ehemals der Stellvertreter von Colonel Kurzen auf einer Expedition aus Sturmwind, führte Doren eine abtrünnige Fraktion von Soldaten an, die sich weigerten, dem Colonel zu folgen, nachdem dieser den Verstand verloren hatte.",al={"wer ist doren","doren lore","rebellenlager anführer"}},{q="Warum gilt Doren als Rebell?",a="Doren und seine Truppen meuterten gegen ihren kommandierenden Offizier, Colonel Kurzen. Da Kurzen der offiziell beauftragte Leiter der Expedition war, machten die Abspaltung und der bewaffnete Widerstand gegen ihn Doren und seine Gefolgsleute formal zu Rebellen – auch wenn sie überliefen, um ihren Verstand zu bewahren und sich Kurzens Tyrannei zu widersetzen.",al={"warum heisst es rebellenlager","warum rebellierte doren","kurzen meuterei"}},{q="Was trieb Colonel Kurzen in den Wahnsinn?",a="Die genaue Ursache des Wahnsinns, der Kurzen und seinen engsten Kreis befiel, bleibt ein Mysterium, das Doren aktiv zu lösen versucht. Doren nutzt Aufklärung und Infiltratoren, um herauszufinden, was seinen früheren Kommandanten tief im Dschungel verdorben hat.",al={"warum wurde kurzen verrückt","kurzens wahnsinn"}},{q="Wie hält Doren den Nachschub des Rebellenlagers aufrecht?",a="Abgeschnitten von der offiziellen Unterstützung aus Sturmwind verlässt sich Doren auf verdeckte Nachschubtransporte und Handelsabkommen mit Dritten. Insbesondere stimmt er sich mit Goblin-Händlern wie Krazek im südlichen Piratenhafen Beutebucht ab, um seine Truppen auszurüsten.",al={"rebellenlager nachschub","doren vorräte"}},{q="Wer ist Buchmacher Herod und welche Verbindung hat er zu Doren?",a="Buchmacher Herod ist ein Verbündeter innerhalb von Kurzens Streitkräften. Doren vermutet, dass Herod daran beteiligt war, die wahren Loyalitäten von Dorens verdecktem Ermittler, Private Thorsen, aufzudecken, während Thorsen das Lager infiltrierte.",al={"buchmacher herod","herod rebellenlager"}},{q="Untersteht Doren Sturmwind?",a="Doren bleibt den Idealen der Allianz treu, agiert jedoch autonom, da er im Felde die Befehlskette gegen einen kommandierenden Offizier gebrochen hat. Er heißt Abenteurer der Allianz willkommen, die dabei helfen, das Desaster der Expedition zu bereinigen.",al={"doren allianz","doren sturmwind loyalitaet"}}},fp="5,319,22.497.0,20.558.1,24.242.0,32.324.0,30.242.0,44.251.0,56.210.0,31.223.0"}
P.entries["npc:dorn-plainstalker"] = {n="Dorn Ebenenpirscher",s="Dorn Ebenenpirscher ist ein einsam lebender Taurenältester, der im Wetterwinkel über den Schluchten von Tausend Nadeln verweilt. Er fungiert als Aufseher traditioneller Übergangsriten und fordert Abenteurer der Horde heraus, ihren Charakter und ihre Seelenstärke unter Beweis zu stellen. Durch Prüfungen des Glaubens, der Ausdauer, der Stärke und des Wissens prüft er, ob Reisende würdige Diener der Erdenmutter und ihres Volkes sind.",h="Dorn Ebenenpirscher ist ein einsam lebender Taurenältester, der im Wetterwinkel über den Schluchten von...",kw={"dorn ebenenpirscher","freiwindposten","taurenprüfung","test der belastbarkeit","test des glaubens","test der lehre","test der kraft","tausend nadeln","der wetterwinkel"},ang={["faction:Horde"]="Dorn heißt alle Champions der Horde willkommen, die bereit sind, sich seinen Prüfungen zu stellen, und stellt sicher, dass Krieger, Jäger und Schamanen jedes Volkes ihren Mut in Kalimdors unbarmherziger Wildnis beweisen.",["race:Tauren"]="Für Tauren, die durch Tausend Nadeln wandern, verkörpert Dorn die Fortführung nomadischer Ahnentraditionen und spiritueller Riten, die den eigenen Einklang mit der Erdenmutter auf die Probe stellen."},sec={{t="Einsiedler der Hohen Klippen",b="Abgeschieden in einer flachen Höhle hoch oben auf den Schluchtgraten des Wetterwinkels lebt Dorn Ebenenpirscher abseits des Trubels von Freiwindposten. Um seine Zuflucht in den Bergen zu erreichen, muss man sich an den steilen nördlichen Klippen entlangschlängeln, die die hoch aufragenden Mesas darunter überblicken. Von diesem ruhigen Aussichtspunkt aus pflegt Dorn alte Bräuche und richtet über jene, die in den rauen südlichen Ödländern nach Führung suchen."},{t="Die vier Prüfungen",b="Dorn Ebenenpirscher leitet Pilger durch eine anspruchsvolle Reihe von Prüfungen, die dazu bestimmt sind, die Kerntugenden eines Taurenchampions zu messen: Glaube, Ausdauer, Stärke und Wissen. Statt bloßer Übungen roher Gewalt zwingen diese Prüfungen die Anwärter dazu, sich ihrer Furcht zu stellen, blind ins Unbekannte zu springen, gerissene Raubtiere der Wildnis zu überdauern und über die heilige Geschichte von Kalimdor nachzudenken, bevor sie ihren endgültigen Übergang vollziehen."}},faq={{q="Wer ist Dorn Ebenenpirscher?",a="Dorn Ebenenpirscher ist ein Taureneinsiedler und Ältester, der im Wetterwinkel verweilt, einem abgeschiedenen Felsunterstand hoch über Tausend Nadeln. Er nimmt aufstrebenden Champions der Horde traditionelle Übergangsprüfungen ab.",al={"wer ist dorn","dorn geschichte","dorn ebenenpirscher"}},{q="Wo finde ich Dorn Ebenenpirscher?",a="Er befindet sich in einer Höhle im Wetterwinkel. Reist von Freiwindposten aus nach Norden zu den hohen Klippenwänden, die die Schlucht säumen, und folgt dann dem Grat nach Osten, bis Ihr eine Rampe entdeckt, die zu seinem Bergrefugium hinaufführt.",al={"wo ist dorn","wie man dorn ebenenpirscher erreicht","standort wetterwinkel"}},{q="Welche Prüfungen nimmt Dorn ab?",a="Dorn beaufsichtigt vier heilige Prüfungen: den Test des Glaubens, den Test der Belastbarkeit, den Test der Kraft und den Test der Lehre. Ihr Bestehen beweist den Mut, die körperliche Entschlossenheit, das Kampfgeschick und den Respekt eines Reisenden vor der Tradition.",al={"dorn ebenenpirscher quests","test des glaubens","übergangsprüfungen tausend nadeln"}},{q="Was ist der Test des Glaubens?",a="Der Test des Glaubens verlangt vom Pilger, von einer schwindelerregenden Klippenplanke in den Abgrund hinabzuspringen, um absolutes Vertrauen zu beweisen und die Urangst zu überwinden.",al={"glaubenssprung tausend nadeln","test des glaubens dorn"}},{q="Warum lebt Dorn allein in einer Höhle?",a="Dorn folgt asketischen spirituellen Traditionen der Tauren. Indem er allein in den Höhen des Wetterwinkels wohnt, fernab des alltäglichen Handels und der Verteidigung von Freiwindposten, bewahrt er einen ungestörten Ort der Besinnung und Prüfung für Suchende.",al={"warum lebt dorn isoliert","hintergrund dorn ebenenpirscher"}},{q="Gehört Dorn zu Freiwindposten?",a="Obwohl er außerhalb von Freiwindposten selbst lebt, ist Dorn ein loyales Mitglied der Horde und der Taurenstämme und steht tapferen Reisenden bei, die durch die windgepeitschten Schluchten ziehen.",al={"ältester von freiwindposten","gehört dorn zur horde"}}},fx={["4250a0db"]={q="Auf wessen Seite steht Dorn Ebenenpirscher?",a="Dorn Ebenenpirscher ist der Horde und seinen Tauren-Brüdern treu ergeben. Er heißt Reisende der Horde in seiner Zuflucht im Wetterwinkel willkommen, um ihre Stärke zu erproben, und führt sie durch traditionelle Riten, um sicherzustellen, dass sie über die Stärke, den Glauben und die Weisheit verfügen, die erforderlich sind, um den Stämmen und der gesamten Horde zu dienen.",al={"ist dorn horde","dorn ebenenpirscher fraktion","wem dient dorn"}},a0eea52d={q="Was will Dorn Ebenenpirscher?",a="Dorn Ebenenpirscher möchte den Charakter, die Ausdauer und den Geist von Champions testen, die durch das Tausend Nadeln reisen. Indem er die Prüfungen des Glaubens, der Ausdauer, der Stärke und des Wissens überwacht, versucht er, würdige Abenteurer auf die harten Herausforderungen der Welt vorzubereiten und sicherzustellen, dass sie die Traditionen der Erde ehren.",al={"dorn ziele","was will dorn","dorn ebenenpirscher zweck"}}},fp="17,395,25.386.0,15.401.0,25.212.0,35.215.0,37.210.0,26.152.0,35.237.0,38.171.0"}
P.entries["npc:drum-fel"] = {n="Drum Teufel",s="Drum Teufel ist ein Ork-Kommandant, der im Horde-Außenposten Hammerfall im Arathihochland stationiert ist. Zusammen mit seiner Frau Korin leitet er die militärischen Bemühungen, die Zuflucht gegen herandrängende Trolle, Oger und menschliche Überreste zu sichern. Sein strategischer Vorstoß ist entscheidend dafür, der Horde im Arathihochland einen dauerhaften Stützpunkt zu sichern.",h="Drum Teufel ist ein Ork-Kommandant, der im Horde-Außenposten Hammerfall im Arathihochland stationiert ist.",kw={"arathihochland","felsfäuste","drum teufel","hammerfall","korin fel","orkalar","witherbark"},ang={["faction:Horde"]="Für Krieger der Horde, die durch die Östlichen Königreiche ziehen, dient Drum Teufel als zentraler militärischer Koordinator, der die fragile Verbindungslinie zwischen Unterstadt und den südlichen Territorien sichert.",["race:Orc"]="Drum Teufel verkörpert die praktische militärische Entschlossenheit, die erforderlich ist, um das Leben der Orks in den Östlichen Königreichen neu aufzubauen – und hält standhaft die Stellung auf ebenjenem Boden, auf dem einst die Internierungslager standen."},sec={{t="Wächter von Hammerfall",b="Inmitten der befestigten Zuflucht von Hammerfall überwacht Drum Teufel die Verteidigung und die territoriale Ausdehnung der Horde im Arathihochland. Umgeben von verfeindeten Gruppierungen koordiniert er militärische Angriffe gegen die Waldtrolle der Witherbark und den Ogerclan der Felsfäuste, der Fels'gor und die Halle der Felsfäuste besetzt hält. Drum ist sich bewusst, dass Hammerfall nicht bloß durch Isolation überleben kann; es muss die Stärke seiner Nachbarn brechen, um zu gedeihen. Zu diesem Zweck schickt er regelmäßig erfahrene Champions in feindliches Gebiet, um regionale Bedrohungen zu stören, bevor sie einen Angriff auf das Lager der Horde starten können."},{t="Die Bedrohung in Stromgarde",b="Drum Teufels Feldzug erstreckt sich bis in die Ruinen von Burg Stromgarde, wo sich Felsfaustoger inmitten des gefallenen Menschenreichs verschanzt haben. Vor Jahren besiegte Drum den Oger-Hitzkopf Or'Kalar, was ihm dessen dauerhaften Groll einbrachte. Ohne dass Drum davon weiß, wartet Or'Kalar in Stromgarde auf Rache. Um ihren Gemahl davor zu bewahren, in einen durch diese Rivalität angefachten Hinterhalt zu geraten, ergreift seine Frau Korin heimlich Maßnahmen, um Or'Kalars Anwesenheit zu verschleiern, und verlässt sich auf auswärtige Abenteurer, die Bedrohung zu beseitigen, ehe Drum selbst vorstürmt."}},faq={{q="Wer ist Drum Teufel?",a="Drum Teufel ist ein orkischer Anführer in Hammerfall im Arathihochland. Er koordiniert die militärischen Feldzüge der Festung gegen verfeindete Fraktionen in der Region.",al={"drum teufel","wer ist drum teufel","hammerfall drum"}},{q="Wo ist Drum Teufel zu finden?",a="Er befindet sich in der Hordesiedlung Hammerfall im nordöstlichen Arathihochland, direkt östlich der Hauptstraße, die nach Norden ins Hinterland führt.",al={"drum teufel aufenthaltsort","wo ist drum teufel","drum teufel finden"}},{q="Wer ist Korin Fel?",a="Korin Fel ist Drums Frau. Sie hält sich ebenfalls in Hammerfall auf.",al={"korin fel","drum teufel ehefrau"}},{q="Warum will der Oger Or'Kalar Drum Teufel tot sehen?",a="Vor Jahren besiegte Drum Teufel Or'Kalar im Kampf. Zutiefst gedemütigt lauert der Oger nun in den Ruinen von Burg Stromgarde und schmiedet Rachepläne gegen den Ork-Kommandanten.",al={"orkalar groll","warum hasst orkalar drum teufel","or'kalar drum teufel"}},{q="Welche Bedrohungen nimmt Drum Teufel ins Visier?",a="Drum Teufel leitet Angriffe gegen die Felsfaustoger in Fels'gor, der Halle der Felsfäuste und Burg Stromgarde sowie gegen den nahegelegenen Trollstamm der Witherbark.",al={"drum teufel quests","drum teufel feinde","gegen wen kämpft drum teufel"}}},fx={["51d7fbcd"]={q="Auf wessen Seite steht Drum Teufel?",a="Drum Teufel ist ein standhafter Anführer innerhalb der Horde. Vom Außenposten Hammerfall aus leitet er militärische Bemühungen, um die Sicherheit und Vorherrschaft der Horde im Arathihochland zu sichern.",al={"drum teufel fraktion","wem dient drum teufel","drum teufel horde"}},["828c27d6"]={q="Was will Drum Teufel?",a="Drum Teufel möchte sicherstellen, dass Hammerfall in feindlichem Gebiet überlebt und gedeiht. Um die Siedlung zu schützen, ordnet er entschlossene Feldzüge gegen rivalisierende Streitkräfte an, die die Region bedrohen, darunter die Boulderfist-Oger, die Witherbark-Trolle und feindliche Bewohner innerhalb der Ruinen von Burg Stromgarde.",al={"drum teufel ziele","was braucht drum teufel","drum teufel motiv"}},def003ab={q="Warum ist Drum Teufel in Hammerfall?",a="Drum Teufel beaufsichtigt von Hammerfall aus militärische Operationen, um den Stützpunkt der Horde im Arathihochland zu sichern. Von dieser Bastion aus koordiniert er die Verteidigung seines Volkes gegen umliegende Bedrohungen, die die Siedlung auslöschen wollen.",al={"warum ist drum teufel hier","drum teufel arathi","drum teufel zweck arathi"}}},fp="8,316,20.585.0,24.525.1,16.161.0,28.161.0,17.57.0,46.169.0,34.155.0"}
P.entries["npc:drusilla-la-salle"] = {n="Drusilla La Salle",s="Drusilla La Salle ist eine Ausbilderin für Hexenmeister der Menschen, die auf dem schattigen Friedhof vor der Abtei von Nordhain weilt. Am Rande des Heiligen Ordens von Nordhain unterweist sie angehende Zauberwirker in den dunklen Künsten der Beschwörung und der Schatten. Wenn verbotenes Wissen die Klostermauern verlässt, zögert sie nicht, Opportunismus und dunkle Magie einzusetzen, um es in ihren Besitz zu bringen.",h="Drusilla La Salle ist eine Ausbilderin für Hexenmeister der Menschen, die auf dem schattigen Friedhof vor der...",kw={"abtei","drusilla la salle","friedhof","nordhain","macht der leere","gestohlener foliant","hexenmeisterlehrer"},ang={["class:Priest"]="Vor den heiligen Hallen von Nordhain stehend, verkörpert Drusilla das dunkle Gegenstück zu Eurer Berufung, indem sie direkt neben dem geweihten Friedhof mit Schatten und dämonischen Pakten hantiert.",["class:Warlock"]="Drusilla dient Euch als erste Mentorin in den dunklen Künsten. Sie leitet Euch zur praktischen Beherrschung von Flüchen sowie Teufelsbeschwörungen an und lehrt Euch, Euren Ehrgeiz vor aller Augen verborgen zu halten."},sec={{t="Schatten auf heiligem Boden",b="Während Paladine und Priester unter den Buntglasfenstern der Abtei von Nordhain trainieren, bleibt Drusilla La Salle draußen zwischen den Grabsteinen des Friedhofs. Die Ausübung von Dämonologie und Teufelsmagie ist im Königreich Sturmwind zutiefst tabuisiert, was Hexenmeister dazu zwingt, am Rande der Gesellschaft zu verweilen. Drusilla erteilt Neulingen unter den Hexenmeistern, die verdorbene Korrespondenz erhalten haben, erste Unterweisungen und lehrt sie, die Macht der Schatten zu nutzen, ohne den sofortigen Zorn der Klosterobrigkeit auf sich zu ziehen."},{t="Macht der Leere",b="Der Bibliotheksflügel der Abtei von Nordhain bewahrt heimlich mehrere gefährliche und verbotene Folianten auf, darunter 'Macht der Leere'. Drusilla begehrt die Schrift schon lange, doch ein Hexenmeister, der sich in den gesicherten Archiven herumtreibt, würde sofortigen Argwohn wecken. Ihre Chance kommt, als ein abtrünniger Novize aus der Abtei flieht, um sich der Bruderschaft der Defias anzuschließen, und den Text mit sich nimmt. Drusilla nutzt den Diebstahl aus und schickt ihre Lehrlinge aus, um den Überläufer zur Strecke zu bringen und ihr das Grimoire unter dem Vorwand zu beschaffen, Klostergut zurückzuholen."}},faq={{q="Warum wird ein Hexenmeister in der Nähe der Abtei von Nordhain geduldet?",a="Hexenmeister begegnen bei der Kirche des Heiligen Lichts und der Führung von Sturmwind tiefem Misstrauen. Drusilla La Salle hält sich außerhalb der eigentlichen Abtei auf, abgelegen auf dem nahegelegenen Friedhof, wo sie ihre Unterweisungen fernab der frommen Priester und Kleriker durchführt, die im Inneren lernen.",al={"warum ist drusilla bei der abtei","hexenmeister in heiliger abtei","warum ist sie auf dem friedhof"}},{q="Welches Buch versucht Drusilla zu erlangen?",a="Sie sucht ein Grimoire namens 'Macht der Leere'. Es war ursprünglich in einem geschützten Bereich des Bibliotheksflügels der Abtei von Nordhain weggeschlossen – unerreichbar für offene Nachforschungen von Hexenmeistern, bis ein Überläufer der Defias es stahl.",al={"welches buch will sie","buch macht der leere","der gestohlene foliant questbuch"}},{q="Wer stahl das Buch aus der Bibliothek?",a="Ein Novize, der in der Abtei von Nordhain lernte, brach seine Gelübde, verbündete sich mit der Bruderschaft der Defias und entwendete den Folianten, bevor er in ein nahes Lager im Nordhaintal floh.",al={"wer hat den folianten gestohlen","defias buchdieb","wer stahl macht der leere"}},{q="Welche Rolle spielt sie für neue Hexenmeister der Menschen?",a="Drusilla fungiert als die allererste Ausbilderin für Hexenmeister der Menschen. Sie nimmt an Rekruten gerichtete verdorbene Briefe entgegen und unterweist sie in grundlegenden Flüchen und beschworenen Dienern.",al={"menschen hexenmeisterlehrer nordhain","wer bildet hexenmeister in nordhain aus"}}},fx={fe9579dd={q="Wer ist Drusilla La Salle?",a="Drusilla La Salle ist eine menschliche Hexenmeisterin, die auf dem Friedhof der Abtei von Nordhain stationiert ist. Während innerhalb der Mauern der Abtei heilige Kleriker und Paladine ausgebildet werden, unterrichtet sie stillschweigend menschliche Novizen, die eine Affinität für dunklere Künste besitzen, und lehrt sie, Teufels- und Schattenenergien ihrem Willen zu unterwerfen.",al={"wer ist drusilla","drusilla la salle hintergrund","drusilla identität"}},["89e305f6"]={q="Auf wessen Seite steht Drusilla La Salle?",a="Sie ist dem Königreich Sturmwind und der Allianz verbunden. Obwohl die dem Licht zugewandte Geistlichkeit der Abtei von Nordhain Hexenmeister mit Misstrauen betrachtet, dient Drusilla dem Reich, indem sie angehende Praktizierende darin schult, ihre gefährlichen Talente gegen die Feinde Sturmwinds zu richten.",al={"ist drusilla böse","drusilla allianz","drusilla fraktion"}}},fp="17,364,22.500.0,18.541.1,47.274.0,39.219.0,36.166.0,47.163.0"}
P.entries["npc:duke-hydraxis"] = {n="Fürst Hydraxis",s="Fürst Hydraxis ist ein edler Wasserelementar, der die Hydraxianer von einer abgelegenen, wellenumtosten kleinen Insel vor der Küste von Azshara aus befehligt. Neptulon the Tidehunter verpflichtet, versammelt er sterbliche Abenteurer um sich, um gegen seine uralten elementaren Rivalen vorzugehen, allen voran Ragnaros the Firelord.",h="Fürst Hydraxis ist ein edler Wasserelementar, der die Hydraxianer von einer abgelegenen, wellenumtosten...",kw={"azshara","fürst hydraxis","hydraxianer","hydraxis","geschmolzener kern","neptulon","ragnaros","wasserelementar"},ang={["class:Shaman"]="Für Schamanen, die direkt mit den Urelementen kommunizieren, bietet die Begegnung mit einem Elementar von Fürst Hydraxis' Statur seltene Einblicke in die uralte Hierarchie von Neptulon und die ewigen Rivalitäten zwischen den Elementarebenen."},sec={{t="Fürst der Hydraxianer",b="Auf einem einsamen Felsen nordöstlich von Rabenkrones Monument in Azshara dient Fürst Hydraxis als oberster Gesandter der Hydraxianer. Während die meisten an Azeroth gebundenen Elementare feindselig und chaotisch sind, agiert Hydraxis mit wohlüberlegter Absicht. Als ergebener Vasall von Neptulon the Tidehunter betrachtet er das Wasser als die reinste und essenziellste der Urkräfte. Er beobachtet die wachsenden Unruhen auf ganz Azeroth mit kühler Skepsis, stets auf der Suche nach Champions, die das Gleichgewicht des Elementarkrieges verschieben können."},{t="Der Krieg gegen das Feuer",b="Hydraxis' wichtigster Feldzug richtet sich gegen die lodernden Heerscharen des Feuerfürsten Ragnaros. Er betrachtet das Vordringen feuriger Elementare als eine Plage der Welt, die ausgelöscht werden muss. Ehe er Sterblichen sein Vertrauen oder die nötigen Werkzeuge schenkt, um Ragnaros' feurige Festung im Geschmolzenen Kern herauszufordern, verlangt Fürst Hydraxis, dass sie ihre Stärke, Widerstandskraft und Loyalität unter Beweis stellen, indem sie feindselige Elementare auf den Kontinenten erschlagen. Jene, die ihren Wert beweisen, verdienen sich die Segen des Meeres sowie die Mittel, um die heiligen Flammen zu löschen, die das Reich des Feuerfürsten bewachen."}},faq={{q="Wo ist Fürst Hydraxis zu finden?",a="Fürst Hydraxis befindet sich auf einer winzigen, abgelegenen Insel vor der Ostküste von Azshara, direkt nordöstlich von Rabenkrones Monument.",al={"wo ist hydraxis","fürst hydraxis aufenthaltsort","fürst hydraxis finden","hydraxis kartenpunkt"}},{q="Wem ist Fürst Hydraxis verbunden?",a="Er führt die Hydraxianer an und dient Neptulon the Tidehunter, dem Herrscher des Wasserelements.",al={"wem dient hydraxis","hydraxis fraktion","diener von neptulon"}},{q="Warum interessiert sich Fürst Hydraxis für sterbliche Champions?",a="Er sucht nach verlässlichen sterblichen Verbündeten, um Krieg gegen die rivalisierenden Elementarfraktionen zu führen, insbesondere gegen die feurigen Streitkräfte von Ragnaros, die im Schwarzfels lauern.",al={"warum braucht hydraxis uns","was will hydraxis","hydraxis absicht"}},{q="Welche Verbindung hat Fürst Hydraxis zum Geschmolzenen Kern?",a="Fürst Hydraxis weist Champions an, Ragnaros the Firelord zu schwächen, und stellt die elementaren Hilfsmittel bereit, die nötig sind, um die Runen und Bosse zu überwinden, die den Geschmolzenen Kern bewachen.",al={"hydraxis geschmolzener kern","hydraxis ragnaros","mc hydraxis"}}},fp="13,287,22.506.0,20.552.0,33.133.0,34.99.0,52.158.0,54.169.0"}
P.entries["npc:durnan-furcutter"] = {n="Durnan Pelznaht",s="Durnan Pelznaht ist ein zwergischer Schneider und Lederhändler, der von Ambossar im Coldridgetal aus tätig ist. Er steht direkt vor der örtlichen Schankstube und stattet frisch ausgebildete Zwergen- und Gnomenabenteurer mit leichter Kleidung aus, die der beißenden Kälte der Berge standhält.",h="Durnan Pelznaht ist ein zwergischer Schneider und Lederhändler, der von Ambossar im Coldridgetal aus tätig...",kw={"ambossar","stoffhändler","das coldridgetal","dun morogh","durnan pelznaht","lederhändler","scalding mornbrew"},ang={["profession:Tailoring"]="Für angehende Schneider stehen Händler wie Durnan für die einfachen Gewänder, die Späher und Lehrlinge in den verschneiten Pässen am Leben halten, bevor meisterhafte Stoffe übernehmen.",["race:Dwarf"]="Durnan verkörpert die praktische Seite des zwergischen Lebens im Coldridgetal: robuste Handwerkskunst, die Wertschätzung für ein heißes Gebräu und freundliche Gespräche im Schnee."},sec={{t="Ein warmer Stich in der Kälte",b="Ambossar dient als erstes Übungsgelände für junge Zwerge und verbannte Gnome, und nicht jeder Krieger zieht in schwerem Eisen gewandet aus. Durnan Pelznaht versorgt Späher, Schurken und Zauberwirker, die leichte, biegsame Kleidungsschichten benötigen, um beweglich zu bleiben, ohne den bitteren Winden von Dun Morogh zu erliegen. Direkt in der Nähe der Herdstelle von Ambossar verkauft er alltägliche Schneiderarbeiten und genähtes Leder und behauptet, seine Waren seien die feinsten im gesamten Tal."},{t="Ein Krug in der Hand",b="Wie jeder echte Zwerg, der in den verschneiten Ausläufern stationiert ist, schätzt Durnan einen kräftigen Schluck fast genauso sehr wie ein ehrliches Geschäft. Er verkehrt regelmäßig in der Taverne von Ambossar und genießt einen dampfenden Krug Scalding Mornbrew, um die frostige Zugluft abzuwehren. Abenteurer, die Botengänge im Lager erledigen, bringen oft frisches Gebräu direkt in seine dankbaren Hände oder bringen sein Leergut zum Wirt zurück."}},faq={{q="Wer ist Durnan Pelznaht?",a="Durnan Pelznaht ist ein zwergischer Rüstungshändler, der in Ambossar im Coldridgetal stationiert ist. Er verkauft einfache Stoff- und Lederausrüstung an angehende Abenteurer, die ihre Reise in Dun Morogh beginnen.",al={"durnan","furcutter","wer ist durnan pelznaht"}},{q="Wo finde ich Durnan Pelznaht?",a="Er steht draußen nahe dem Eingang zur Haupthalle von Ambossar im Coldridgetal, in der Nähe der Ausbilder und der örtlichen Handwerker.",al={"durnan standort","wo ist durnan","ambossar stoffhändler"}},{q="Was verkauft Durnan?",a="Er bietet eine Auswahl an grundlegender Rüstung aus Tuch und aus Leder für Klassen an, die eher auf Beweglichkeit oder Zauberei als auf schwere Kette angewiesen sind.",al={"durnan waren","was verkauft durnan"}},{q="Warum hat er mit den Lieferungen von Scalding Mornbrew zu tun?",a="Durnan arbeitet viele Stunden in den eisigen Winden des Coldridgetals und verlässt sich auf warme Krüge Scalding Mornbrew aus dem nahegelegenen Gasthaus, um munter und warm zu bleiben.",al={"durnan bier quest","scalding mornbrew durnan","durnan getränk"}}},fx={d97cf4a2={q="Auf wessen Seite steht Durnan Pelznaht?",a="Durnan steht fest an der Seite von Eisenschmiede und der Allianz. In Ambossar stationiert, rüstet er die jungen Zwergen- und Gnomenrekruten aus, die ihre Reise im Das Coldridgetal beginnen.",al={"durnan fraktion","durnan pelznaht allianz","wem dient durnan"}},afaf309b={q="Was will Durnan Pelznaht?",a="In erster Linie möchte Durnan seinem Handwerk nachgehen und prahlt damit, dass er die feinste Stoff- und Lederkleidung diesseits des Tals anbietet. Jenseits des Geschäfts lehnt er niemals einen Becher dampfenden Scalding Mornbrew ab, um der beißenden Kälte im Das Coldridgetal zu trotzen.",al={"was will durnan","durnan pelznaht ziele","durnan zweck"}},["9750ade9"]={q="Warum ist Durnan Pelznaht in Ambossar?",a="Ambossar dient als Ausbildungshalle und Treffpunkt für Novizen, die im Das Coldridgetal beginnen. Durnan bleibt hier, um neue Abenteurer mit essentieller Kleidung und einfacher Rüstung zu versorgen, bevor sie sich in die verschneite Wildnis wagen.",al={"warum ist durnan hier","warum ist durnan im coldridgetal","durnan standort grund"}}},fp="16,273,25.456.0,13.397.0,24.190.0,34.147.0,22.152.0,53.140.0"}
P.entries["npc:duthorian-rall"] = {n="Duthorian Rall",s="Duthorian Rall ist ein angesehener menschlicher Ritter der Silbernen Hand, der in Sturmwinds Kathedrale des Lichts stationiert ist. Bekannt als einer der einflussreichsten Paladine der Allianz, überwacht er die Ausbildung und die spirituellen Prüfungen angehender heiliger Krieger. Er leitet Rekruten durch feierliche Gelübde der Nächstenliebe, Tapferkeit und Hingabe, um Azeroth gegen die Geißel und lauernde innere Bedrohungen zu verteidigen.",h="Duthorian Rall ist ein angesehener menschlicher Ritter der Silbernen Hand, der in Sturmwinds Kathedrale des...",kw={"kathedrale des lichts","daphne stillbrunn","duthorian rall","jordan stillbrunn","paladinlehrer","silberne hand","sturmwind","symbol des lebens","foliant der offenbarung","foliant der ehre"},ang={["class:Paladin"]="Duthorian Rall ist einer Eurer primären spirituellen Mentoren in Sturmwind, der Euer Mitgefühl und Eure Ehre durch grundlegende Prüfungen testet, die die Macht der Wiederbelebung, göttliche Sinne und Euer Streitross freischalten.",["faction:Alliance"]="Als einflussreicher Anführer innerhalb der Silbernen Hand stellt Duthorian sicher, dass die Verteidiger der Allianz moralisch rechtschaffen und fähig bleiben, das Reich gleichermaßen gegen Banditen wie gegen Untote zu verteidigen.",["race:Human"]="Verankert in Sturmwinds Kathedrale des Lichts verkörpert Duthorian die beständige Hingabe und ritterliche Disziplin, die den Kern des menschlichen Glaubens und der Gesellschaft bilden."},sec={{t="Eine Säule der Silbernen Hand",b="Im gewölbten Querschiff der Kathedrale des Lichts stehend, repräsentiert Duthorian Rall die ehrwürdigen Traditionen der Ritter der Silbernen Hand. Während das Königreich durch innere Unruhen und das Verschwinden von König Varian Wrynn erschüttert wird, schultert Duthorian die wichtige Pflicht, neuen Initianden rechtschaffene Disziplin einzuflößen. Angesehene Paladine im Feld, darunter Bruder Wilhelm in Nordhain und Brandur Eisenhammer in Eisenschmiede, leiten vielversprechende Rekruten zu seiner Unterweisung weiter, damit sie ihre heiligen Prüfungen beginnen."},{t="Prüfungen des Mitgefühls und des Lebens",b="Duthorian lehrt, dass kriegerische Macht ohne moralisches Fundament hohl ist. Durch den Folianten der Offenbarung prüft er die Fähigkeit eines Paladins zur Empathie und verlangt Taten der Barmherzigkeit sowie selbstlosen Dienst in ganz Sturmwind, bevor er ihnen tiefere Geheimnisse anvertraut. Seine Prüfungen gipfeln darin, die Kandidaten mit dem Symbol des Lebens nahe der Heldenwache auf die Probe zu stellen: Er schickt sie aus, um verwundeten Verbündeten zu helfen, und lehrt sie, die wundersame Macht des Lichts zu kanalisieren, um gefallene Kameraden vom Tod zurückzuholen."},{t="Der Preis der Ehre",b="Über spirituelle Kontemplation hinaus verlangt Duthorian entschlossenen Mut im Angesicht der Gefahr. Bei seinen Prüfungen der Ehre mahnt er die Aspiranten, dass ihre Gelübde ihr Leben fordern könnten. Er stellt diese Entschlossenheit auf die Probe, indem er Initianden in gefährliches Gebiet schickt – etwa zur Verteidigung von Daphne Stillbrunn gegen abtrünnige Defias in Westfall –, bevor er sie weiter zu Meisterschmied Jordan Stillbrunn vor Eisenschmiede leitet und ihnen heilige Schlachtrösser gewährt, die ihres Standes würdig sind."}},faq={{q="Wer ist Duthorian Rall?",a="Duthorian Rall ist ein prominenter Ritter der Silbernen Hand, der in der Kathedrale des Lichts in Sturmwind weilt. Er dient als Ausbilder und spiritueller Mentor für neue Paladine und prüft im Namen der Kirche des Heiligen Lichts deren Hingabe und Mut.",al={"duthorian rall lore","wer ist duthorian","kathedralenpaladin duthorian"}},{q="Wo ist Duthorian Rall zu finden?",a="Er steht im östlichen Flügel der Kathedrale des Lichts im Herzen des Kathedralenplatz in Sturmwind.",al={"wo ist duthorian rall","duthorian rall standort","duthorian finden"}},{q="Was ist seine Verbindung zum Folianten der Offenbarung?",a="Duthorian händigt Paladinen den Folianten der Offenbarung aus und führt sie durch Prüfungen der Demut, des Mitgefühls und der Rettung. Das Bestehen seiner Prüfungen beweist, dass ein Initiand würdig ist, die Macht des Lichts zur Wiederbelebung zu führen.",al={"foliant der offenbarung duthorian","erlösung quest duthorian","symbol des lebens quest"}},{q="Warum schickt Duthorian Paladine nach Westfall?",a="Während der Prüfung für den Folianten der Ehre schickt Duthorian Paladine aus, um Daphne Stillbrunn auf ihrem Hof in Westfall vor Defias-Banditen zu beschützen, womit sie ihre Bereitschaft beweisen, sich zur Verteidigung der Unschuldigen zu opfern.",al={"daphne stillbrunn quest","foliant der ehre westfall","westfall paladin quest"}},{q="Welche Belohnungen gewährt Duthorian Paladinen, die seine Prüfungen bestehen?",a="Erfolgreiche Paladine erlangen durch seine Führung entscheidende heilige Fähigkeiten, darunter die heilige Gabe der Wiederbelebung, die Fähigkeit, Untote aufzuspüren, schützende Rüstungsteile wie die Bastion von Sturmwind und schließlich ihr beschworenes Streitross.",al={"duthorian questbelohnungen","was bekommt man von duthorian"}},{q="Wer schickt Abenteurer ursprünglich zu Duthorian?",a="Aspiranten werden ihm typischerweise von Paladinlehrern zugewiesen, darunter Bruder Wilhelm im Nordhaintal und Brandur Eisenhammer in Eisenschmiede.",al={"wer schickt einen zu duthorian","duthorian hinweisquest"}}},fx={adc9c2ec={q="Auf wessen Seite steht Duthorian Rall?",a="Duthorian Rall ist der Große Allianz, dem Königreich Sturmwind und den Rittern der Silbernen Hand fest ergeben. Er arbeitet in der Kathedrale des Lichts, dient dem Heiligen Licht und arbeitet mit der Führung und dem Priestertum des Königreichs zusammen, um Paladine auszubilden, die sich dem Schutz von Azeroth vor Gefahren wie der Geißel und der Bruderschaft der Defias widmen.",al={"duthorian rall fraktion","wem dient duthorian","ist duthorian rall allianz"}},["5fa6dad6"]={q="Was will Duthorian Rall?",a="Duthorian versucht, angehende Paladine zu testen, zu stählen und zu leiten, damit sie wahre Tugend, Mitgefühl und Tapferkeit verkörpern. Durch Prüfungen der Wohltätigkeit, Buße und kriegerischen Pflicht stellt er sicher, dass neue heilige Krieger bereit sind, die größten Gaben des Lichts – wie die Wiederbelebung – einzusetzen, um das Reich gegen wachsende Bedrohungen zu verteidigen.",al={"was ist das ziel von duthorian rall","was will duthorian","duthorian rall motive"}},["091b91cc"]={q="Warum ist Duthorian Rall hier?",a="In der Kathedrale des Lichts von Sturmwind stationiert, dient Duthorian als leitender Mentor der Silbernen Hand in den südlichen Königreichen. Ausbilder im ganzen Reich leiten vielversprechende Initianden an ihn weiter, damit er ihre spirituelle Hingabe beaufsichtigen, ihre Entschlossenheit im Feld testen und sie offiziell in höhere Ränge einweihen kann.",al={"warum ist duthorian in sturmwind","duthorian rall rolle kathedrale","warum ist duthorian rall hier"}},["8b7d8aea"]={q="Mit wem ist Duthorian Rall verbunden?",a="Duthorian arbeitet eng mit regionalen Mentoren wie Bruder Wilhelm in Nordhain und Brandur Eisenhammer in Dun Morogh zusammen, die angehende Paladine an ihn verweisen. Er pflegt auch enge Kontakte zu Freunden in Not in ganz Elwynn, wie Gazin Tenorm, und koordiniert sich mit Verbündeten wie den Stilwells in Westfall.",al={"duthorian rall verbündete","duthorian rall verbindungen","wen kennt duthorian"}},["46aa8798"]={q="Warum ist Duthorian Rall berühmt?",a="Duthorian ist als einer der einflussreichsten Paladine der Allianz bekannt. Innerhalb der Silbernen Hand genießt er tiefen Respekt für seine unerschütterliche Frömmigkeit, seine Rolle bei der Formung der nächsten Generation heiliger Champions und seine Autorität, würdigen Rittern große heilige Ehren zu verleihen.",al={"ist duthorian rall berühmt","duthorian rall ruf","wie bekannt ist duthorian rall"}}},fp="14,388,27.502.0,29.469.0,18.450.1,22.257.0,34.135.0,47.216.0,45.216.0,66.235.0,45.144.0"}
P.entries["npc:ebru"] = {n="Ebru",s="Ebru ist eine Nachtelfendruidin, die in den Felsen über den Höhlen des Wehklagens Zuflucht gesucht hat. Als eine der wenigen verbliebenen, unverdorbenen Jünger von Erz Druide Naralex muss sie hilflos mitansehen, wie der Traum ihres Meisters, das Brachland wiederherzustellen, zu einem Albtraum gerinnt. Von ihrem Aussichtspunkt aus wirbt sie Reisende an, die mutig genug sind, in die unterirdischen Tiefen vorzudringen, um die vom Albtraum hervorgebrachten mutierten Schrecken auszudünnen.",h="Ebru ist eine Nachtelfendruidin, die in den Felsen über den Höhlen des Wehklagens Zuflucht gesucht hat.",kw={"brachland","zirkel des cenarius","deviat","druide","ebru","naralex","die höhlen des wehklagens"},ang={["class:Druid"]="Für Druiden des Zirkels des Cenarius ist die Begegnung mit Ebru eine deutliche Mahnung an die schrecklichen Gefahren, die das Beschreiten des Smaragdgrünen Traums birgt, und an die katastrophalen Folgen eines Kontrollverlusts.",["race:NightElf"]="Ebru verkörpert die kleine, isolierte Enklave von Nachtelfen, die tief im trockenen Herzen von Kalimdor agiert, weit entfernt von den uralten Wipfeln von Eschental und Teldrassil."},sec={{t="Wache über dem Abstieg",b="Während die meisten Anhänger von Erz Druide Naralex der smaragdgrünen Verderbnis erlagen, die durch die Höhlen kriecht, gelang es Ebru, den Fängen des Albtraums zu entkommen. Sie hat ihr Lager in der höhlenartigen Schädelformation über dem Eingang zu den Höhlen des Wehklagens aufgeschlagen und hält Wache über dem Abstieg. Sie weiß, dass Naralex' edler Plan – unterirdische Quellen anzuzapfen und das dürre Brachland in üppige Wälder zu verwandeln – schrecklich schiefgelaufen ist, und leitet verzweifelt hilfsbereite Abenteurer an, die aufkeimenden Deviatbestien zu beseitigen, die die umliegenden Ebenen zu überwuchern drohen."},{t="Der Preis der Verderbnis",b="Der Albtraum verzerrte nicht nur das Ökosystem der Höhlen, sondern auch Ebrus Mitjünger und verwandelte sie in die fanatischen Druids of the Fang. Beraubt ihrer Gefährten und angesichts des Ruins ihres Zirkels konzentriert sich Ebru auf die Eindämmung."}},faq={{q="Wer ist Ebru?",a="Ebru ist eine Nachtelfendruidin und eine unverworfene Jüngerin von Erz Druide Naralex. Sie haust in einer Höhle hoch über dem Eingang zu den Höhlen des Wehklagens, überwacht den Ort und koordiniert die Bemühungen, die Verderbnis einzudämmen, die in das Brachland strömt.",al={"wer ist ebru","ebru geschichte","über ebru"}},{q="Warum befindet sich Ebru über den Höhlen des Wehklagens?",a="Sie floh nach oben, als Naralex' Ritual in den Emerald Nightmare stürzte und ihre Mitjünger in feindselige Fanatiker verwandelte. Ihr Hochsitz im Felsen über dem Höhleneingang ermöglicht es ihr, die Höhlen zu überwachen, während sie vor den wilden Schrecken im Inneren sicher ist.",al={"wo ist ebru","warum ist ebru hier oben","ebru höhle aufenthaltsort"}},{q="Was geschah mit Naralex und seinen anderen Jüngern?",a="Naralex begab sich in eine tiefe Trance, um die unterirdischen Quellen anzuzapfen, doch sein Geist wurde im Emerald Nightmare gefangen. Die daraus resultierende Verderbnis entstellte die Flora und Fauna der Höhle und trieb die meisten seiner Jünger in den Wahnsinn, was sie in die Druids of the Fang verwandelte.",al={"was geschah mit den jüngern","naralex schicksal","ursprung der druids of the fang"}},{q="Worum bittet Ebru Reisende?",a="Ebru drängt Abenteurer dazu, in die Tiefen der Höhlen des Wehklagens vorzudringen, um die Deviatbestien auszudünnen und gegen die mutierten Monstrositäten zurückzuschlagen, die den gequälten Träumen ihres Meisters entsprungen sind.",al={"ebru quests","ausrottung der deviat","säuberung der höhlen"}}},fx={["5ace5551"]={q="Auf wessen Seite steht Ebru?",a="Ebru dient dem Zirkel des Cenarius und bleibt ihrem Mentor, dem Druiden Naralex, treu. Im Gegensatz zu vielen ihrer Gefährten, die dem Albtraum zum Opfer fielen, der die Höhlen heimsuchte, ist sie nicht feindselig geworden oder der Verderbnis erlegen. Obwohl sie eine Nachtelfin ist, heißt sie jeden fähigen Reisenden willkommen – egal ob Allianz oder Horde –, der bereit ist, sich in die Tiefen zu wagen, um die Oase zu reinigen und ihren Meister zu retten.",al={"ebru fraktion","ist ebru allianz oder horde","wem dient ebru"}}},fp="4,377,25.562.0,23.238.1,12.247.0,46.256.0,49.263.0,35.188.0"}
P.entries["npc:edwin-vancleef"] = {n="Edwin van Cleef",s="Edwin van Cleef war der brillante Gildenmeister der Steinmetze, die Sturmwind nach dem Zweiten Krieg wiederaufbauten. Nachdem er vom Haus der Adligen um seine Bezahlung betrogen worden war, führte er einen gewaltsamen Arbeiteraufstand an und gründete die gesetzlose Bruderschaft der Defias. Aus den Tiefen der Todesminen in Westfall heraus sinnt er auf Rache an dem Königreich, das er einst mit aufzubauen half.",h="Edwin van Cleef war der brillante Gildenmeister der Steinmetze, die Sturmwind nach dem Zweiten Krieg...",kw={"bruderschaft","die todesminen","defias","mondbruch","steinmetze","sturmwind","vancleef","westfall"},ang={["class:Rogue"]="Van Cleef wurde vom Anführer des SI:7, Mathias Shaw, persönlich ausgebildet, was ihn zu einem der fähigsten Schurken auf ganz Azeroth macht, der formelle Gildenführung mit meisterhaften Attentatstechniken verbindet.",["faction:Alliance"]="Kommandeure der Allianz betrachten van Cleef als die größte interne Sicherheitsbedrohung für die südlichen Länder der Menschen, da er Westfall und die Grenzen vom Wald von Elwynn lahmlegt.",["race:Human"]="Für die Menschen von Sturmwind verkörpert van Cleef die Tragödie des Wiederaufbaus des Königreichs nach dem Krieg: ein loyaler Held, dessen verweigerte Existenzgrundlage ihn zum tödlichsten Aufständischen des Reiches machte."},sec={{t="Architekt des Königreichs",b="Nach den Verheerungen des Ersten Krieges wurde Edwin van Cleef auserwählt, die Steinmetzgilde bei der monumentalen Aufgabe des Wiederaufbaus von Sturmwind anzuführen. Als unvergleichlicher Handwerker und Idealist leitete van Cleef den Bau der gewaltigen Wehrmauern und hoch aufragenden Kathedralen der Hauptstadt und überwachte sogar die Errichtung von Burg Nethergarde, um das Dunkle Portal zu bewachen. Neben seiner Meisterschaft in der Architektur war van Cleef ein bemerkenswert tödlicher Agent; er war von seinem Jugendfreund Mathias Shaw in Heimlichkeit, Täuschung und Klingenkunst ausgebildet worden."},{t="Der Aufruhr und die Bruderschaft",b="Als die Jahre der Mühsal endeten, häufte das Haus der Adligen durch Feldzüge gewaltige Schulden an und weigerte sich, den Steinmetzen ihre versprochene Entlohnung auszuzahlen. Außer sich vor Wut forderte van Cleef Entschädigung, woraufhin die Adligen die Gilde offiziell auflösten. Die Handwerker probten den Aufstand, was zu chaotischen Straßenunruhen in Sturmwind führte, bei denen König Varian Wrynns Gemahlin, Königin Tiffin, getötet wurde. Durch die Vergeltungsmaßnahmen der Krone aus der Hauptstadt vertrieben, sammelte van Cleef seine verbannten Arbeiter und verbündete Ausgestoßene in Westfall und vereinte sie unter dem Banner der Bruderschaft der Defias."},{t="Vergeltung aus den Schatten",b="Die Defias nutzten die Vernachlässigung des Umlands durch die Krone aus, vertrieben die Bauern Westfalls und beanspruchten die reichen Goldvorkommen für sich. In den Tiefen der Todesminen von Mondbruch überwachte van Cleef den Bau eines gewaltigen Moloch-Kriegsschiffs und bereitete einen bewaffneten Angriff auf Sturmwind selbst vor. Während das Haus der Adligen die Diebe als unorganisierte Banditen abtat, schmiedete van Cleef Bündnisse mit Flussgaunern, Gnollen und den Blutsegelbukanieren und verwandelte so eine verbitterte Gewerkschaft in eine Armee, die bereit war, die Monarchie zu zerschlagen."}},faq={{q="Wer ist Edwin van Cleef?",a="Er ist der Drahtzieher hinter der Bruderschaft der Defias und der ehemalige Gildenmeister der Steinmetze. Er ist der Meisterarchitekt, der Sturmwind wiederaufbaute, nachdem die Horde die Stadt im Ersten Krieg zerstört hatte.",al={"wer ist vancleef","edwin van cleef lore","vancleef identität"}},{q="Warum rebellierten die Steinmetze gegen Sturmwind?",a="Nach dem Wiederaufbau von Sturmwind weigerte sich das Haus der Adligen aufgrund immenser Staatsschulden, der Steinmetzgilde ihren vereinbarten Lohn zu zahlen. Als van Cleef und die Arbeiter protestierten, lösten die Adligen die Gilde auf, was gewaltsame Unruhen auf den Straßen entfachte.",al={"warum rebellierten die defias","warum probten die steinmetze den aufstand","grund für den aufstand der defias"}},{q="Wo versteckt sich Edwin van Cleef?",a="Er befehligt die Bruderschaft der Defias aus dem innersten Heiligtum der Todesminen in Westfall, deren Eingang Gerüchten zufolge durch das ruhige Dorf Mondbruch führt.",al={"wo ist vancleef","aufenthaltsort von vancleef","todesminen boss aufenthaltsort"}},{q="Was ist seine Verbindung zu Mathias Shaw?",a="Mathias Shaw war ein Jugendfreund von Edwin. Shaw bildete van Cleef persönlich in den Künsten der Heimlichkeit, des Diebstahls und des Kampfes aus, in der ursprünglichen Hoffnung, dass van Cleef sich ihm beim königlichen Geheimdienst Der SI:7 anschließen würde.",al={"vancleef und shaw","ist vancleef mit shaw verwandt","freund von mathias shaw"}},{q="Was geschah während des Aufruhrs mit Königin Tiffin?",a="Während der chaotischen Straßenunruhen, die von den unbezahlten Steinmetzen entfacht wurden, traf ein geschleuderter Stein König Varians junge Gemahlin, Königin Tiffin Wrynn, tödlich. Ihr Tod trieb König Varian zu einem unbarmherzigen Vorgehen, das van Cleef und seine Männer zur Flucht aus der Stadt zwang.",al={"wie starb tiffin","wer tötete tiffin wrynn","königin tiffins tod"}},{q="Was baut er in den Todesminen?",a="Gerüchten zufolge haben die Defias geschickte Goblins zwangsrekrutiert, um ihnen am Grunde der Todesminen beim Bau von etwas Schrecklichem zu helfen, doch was genau es sein mag, ist noch ungewiss.",al={"todesminen schiff","was ist in den todesminen","vancleef kriegsschiff"}}},fx={["7e824b42"]={q="Auf wessen Seite steht Edwin van Cleef?",a="Edwin van Cleef steht einzig und allein auf der Seite von The Defias Brotherhood, dem rebellischen Syndikat, das er aus den Ausgestoßenen der ehemaligen Stonemasons Guild gründete. Er stellt sich sowohl gegen das Haus der Adligen als auch gegen die Krone von Sturmwind und macht das gesamte Königreich für den Vertrauensbruch gegenüber seinen Handwerkern verantwortlich. Er schuldet der Allianz oder der Horde keine Loyalität und agiert als krimineller Drahtzieher, der seinen eigenen erbitterten Rachefeldzug verfolgt.",al={"loyalität von edwin van cleef","für wen kämpft edwin van cleef","gehört van cleef zur allianz oder horde"}},["01cc4ddf"]={q="Was will Edwin van Cleef?",a="Van Cleef sucht die vollkommene Vergeltung gegen das Königreich Sturmwind. Nachdem er jahrelang den Wiederaufbau der Hauptstadt geleitet hatte, nur damit das korrupte Haus der Adligen ihm die Bezahlung verweigerte und der Stonemasons Guild ihre Lebensgrundlage entzog, schwor er, dass das gesamte Königreich für ihren Verrat bezahlen würde. Er zielt darauf ab, die Verteidigung der Stadt zu durchbrechen, die Aristokratie zu zerschlagen und durch bewaffneten Aufstand und offene Verwüstung Rache für seine verbannten Handwerker zu nehmen.",al={"vancleefs ziel","was ist das ziel von edwin van cleef","warum greift van cleef sturmwind an"}},["5f8574b7"]={q="Warum wird Edwin van Cleef so gefürchtet?",a="Sturmwind betrachtet van Cleef als eine der größten Bedrohungen für seine Sicherheit, da er brillantes architektonisches Wissen mit einer tödlichen Ausbildung als Schurke verbindet. Da er die Befestigungsanlagen der Hauptstadt entworfen hat, kennt er jede Schwachstelle in der Verteidigung des Königreichs. Unterstützt von einem riesigen, mörderischen kriminellen Netzwerk und stark befestigt in den Todesminen, befehligt er genug Feuerkraft, Arbeitskräfte und List, um das Reich des jungen Königs in die Knie zu zwingen.",al={"warum ist van cleef berühmt","warum wird edwin van cleef gefürchtet","bedrohung durch edwin van cleef"}}},fp="14,354,24.539.0,28.580.0,28.533.1,22.202.0,49.258.0,31.164.1,39.205.0,46.246.0,37.169.1"}
P.entries["npc:einar-stonegrip"] = {n="Einar Steingriff",s="Einar Steingriff ist ein zwergischer Fallensteller, der an der Hauptkreuzung des Sumpflands stationiert ist. Anstatt ein unangenehmes Wiedersehen mit seiner entfremdeten Frau im Hafen von Menethil zu riskieren, verlässt er sich auf vorbeikommende Abenteurer, um seine Krokiliskenhäute in die Stadt zu transportieren.",h="Einar Steingriff ist ein zwergischer Fallensteller, der an der Hauptkreuzung des Sumpflands stationiert ist.",kw={"krokilisk","einar steingriff","james halloran","der hafen von menethil","sida","häute","fallensteller","sumpfland"},ang={["faction:Alliance"]="Reisende, die zwischen Eisenschmiede und dem Hafen von Menethil unterwegs sind, passieren oft Einars Posten am Straßenrand, was einfache Kurierarbeiten entlang der Versorgungsrouten der Allianz ermöglicht.",["race:Dwarf"]="Einar spiegelt die robuste Selbstständigkeit wider, die unter zwergischen Bergbewohnern üblich ist, auch wenn seine Eheprobleme ihn dazu treiben, in den sumpfigen Marschen statt in einer warmen Taverne zu schlafen."},sec={{t="Ein Fallensteller am Wegekreuz",b="An der zentralen Kreuzung, die Dun Algaz, Dun Modr und den Hafen von Menethil verbindet, verdient Einar Steingriff seinen Lebensunterhalt, indem er den durchnässten Marschen des Sumpflands trotzt. Er jagt die einheimischen Krokilisken wegen ihrer robusten Häute und versorgt damit Lederer sowie Händler entlang der Küste. Obwohl er abgehärtet genug ist, um Reptilien aus dem Schlamm zu ringen, wird er von häuslichem Streit völlig eingeschüchtert. Verwickelt in ein bitteres Zerwürfnis mit seiner Frau Sida bleibt Einar draußen auf der Straße und heuert Reisende an, um seine Hautbündel zu seinem Handelspartner James Halloran zu bringen, anstatt selbst einen Fuß in den Hafen von Menethil zu setzen."}},faq={{q="Wer ist Einar Steingriff?",a="Einar Steingriff ist ein zwergischer Kürschner und Jäger, der an der Kreuzung im Sumpfland stationiert ist. Seinen Lebensunterhalt verdient er mit dem Sammeln von Krokiliskenhäuten, um sie im Hafen von Menethil zu verkaufen.",al={"wer ist einar","einar steingriff geschichte","sumpfland zwerg kreuzung"}},{q="Warum liefert Einar seine Waren nicht selbst im Hafen von Menethil ab?",a="Einar steht auf furchtbar schlechtem Fuß mit seiner Frau Sida, die im Hafen von Menethil wohnt. Um ihrem Zorn zu entgehen, zieht er es vor, draußen im Sumpfland zu bleiben und vorbeikommende Kuriere dafür zu bezahlen, seine Handelsgüter abzuliefern.",al={"warum geht einar nicht in die stadt","einar steingriff frau","warum abenteurer anheuern"}},{q="Mit wem arbeitet Einar im Hafen von Menethil zusammen?",a="Einar sammelt Krokiliskenhäute im Auftrag von James Halloran, einem Händler im Hafen von Menethil, der sich um den Vertrieb und Verkauf von Lederwaren kümmert.",al={"einar geschäftspartner","wer kauft einars häute","james halloran verbindung"}}},fx={["2e6b6b46"]={q="Auf wessen Seite steht Einar Steingriff?",a="Einar ist der Eisenschmiede und der Allianz gegenüber loyal. Er ist an den Kreuzungen im Sumpfland stationiert, wo er mit seinen Kameraden, den Bergsteigern, zusammenarbeitet und Handelswaren für die Hafensiedlung Hafen von Menethil bereitstellt.",al={"fraktion von einar steingriff","wem dient einar steingriff","gehört einar zur allianz oder horde"}},["61290d18"]={q="Was will Einar Steingriff?",a="Einar möchte sein Geschäft mit der Lieferung von Krokoliskhäuten an James Halloran im Hafen von Menethil aufrechterhalten, ohne selbst dorthin reisen zu müssen. Er sucht eifrig nach vorbeiziehenden Reisenden, die bereit sind, die Bündel in seinem Namen abzuliefern, damit er die Begegnung mit seiner Frau, Sida, hinauszögern kann.",al={"was will einar","ziel von einar steingriff","quest-motiv von einar steingriff"}}},fp="15,245,27.596.0,23.165.0,57.206.0,44.147.0"}
P.entries["npc:eitrigg"] = {n="Etrigg",s="Etrigg ist ein erfahrener Veteran des Ersten und Zweiten Krieges, der Kriegshäuptling Thrall als geschätzter Berater in Orgrimmar zur Seite steht. Einst ein hochrangiger Leutnant des Blackrockclans, verlor er den Glauben an die alte dämonische Horde und lebte im Exil, bis eine außergewöhnliche Freundschaft mit einem menschlichen Paladin sein Schicksal veränderte. Heute hilft er dabei, die Neue Horde zu ihren Wurzeln von Ehre und Schamanismus zurückzuführen.",h="Etrigg ist ein erfahrener Veteran des Ersten und Zweiten Krieges, der Kriegshäuptling Thrall als geschätzter...",kw={"blackrockclan","blut und ehre","etrigg","grommash hold","herdweiler","orgrim schicksalshammer","orgrimmar","stratholme","thrall","tirion fordring"},ang={["class:Paladin"]="Die Geschichte von Etrigg und Tirion Fordring ist unter Paladinen als die ultimative Prüfung von Pflichtgefühl gegenüber wahrer Ehre bekannt.",["class:Warrior"]="Etrigg verkörpert kriegerische Ehre, die über Jahrzehnte voller Tragödien hinweg bewahrt wurde, nachdem er zwei Kriege durch bloße Stärke und ungebrochene Disziplin überlebt hat.",["faction:Horde"]="Etrigg dient als lebendiges institutionelles Gedächtnis der Horde und steht Thrall zur Seite, um sicherzustellen, dass die Fehler der von Dämonen verdorbenen Vergangenheit niemals wiederholt werden.",["race:Orc"]="Für die Orcs von Durotar ist Etrigg ein verehrter Ältester, dessen Blackrock-Erbe beweist, dass jeder Orc Ehre annehmen und das Erbe seines Volkes wiedergutmachen kann."},sec={{t="Ein Veteran der Alten Horde",b="Geboren auf Draenor im Blackrockclan, war Etrigg einst neben Orgrim Schicksalshammer und Varok Saurfang einer der primären Leutnante von Kriegshäuptling Schwarzfaust. Als Doomhammer die Führung der Horde übernahm, blieb Etrigg ein vertrauter Offizier und bewachte die gefangene Halborc-Attentäterin Garona. Obwohl er ihre Enthüllungen über Gul'dan und das dämonische Verderben des Schattenrats zunächst abtat, zwangen ihn die schrecklichen Schlachten und die letztendliche Niederlage der Horde im Zweiten Krieg, der dunklen Realität ins Auge zu blicken. Angewidert von der Erkenntnis, wie sein Volk manipuliert worden war, wandte sich Etrigg von den verstreuten Überresten ab und zog sich in ein selbstgewähltes Exil zurück, wo er in der Wildnis von Lordaeron nur Einsamkeit suchte."},{t="Blut und Ehre",b="Jahre nach Beginn seines Exils in der Wildnis wurde Etrigg in einem verlassenen Turm nahe Herdweiler von dem menschlichen Paladin Tirion Fordring entdeckt. Ihr anfänglicher Kampf brachte die Ruinen zum Einsturz, doch anstatt den bewusstlosen Menschen zu töten, zog Etrigg ihn aus den Trümmern in Sicherheit. Bewegt von diesem Beweis reiner kriegerischer Ehre schwor Tirion einen Eid der Freundschaft und weigerte sich, den Aufenthaltsort des Einsiedlers zu verraten. Als die örtlichen Behörden der Allianz Etrigg schließlich gefangen nahmen und ihn zum Tode durch den Strang in Stratholme verurteilten, gab Tirion seine eigene Ritterschaft, seine Ländereien und seine Freiheit bei einem Angriff auf, um den verurteilten Orc zu retten. Dieses legendäre Band bewies beiden Kriegern, dass Ehre über dem bitteren Hass zwischen ihren Völkern stand."},{t="Berater des Kriegshäuptlings",b="Während Tirions verzweifeltem Versuch, Etrigg in Stratholme zu befreien, griff Thralls neu vereinte Horde die Stadt an und rettete den alternden Krieger. Die Begegnung mit Thrall überzeugte Etrigg davon, dass die Orcs das dämonische Verderben abschüttelten und ihr angestammtes schamanistisches Erbe wiederentdeckten. Nach seiner Rückkehr mit Thrall über das große Meer nach Kalimdor übernahm Etrigg einen angesehenen Posten im Tal der Weisheit in Orgrimmar. Er steht nun als Berater des jungen Kriegshäuptlings in Grommash Hold, hilft bei der Beurteilung neuer Rekruten und gibt seine hart erarbeitete Weisheit weiter, damit die Neue Horde die Tragödien der Vergangenheit niemals wiederholt."}},faq={{q="Wer ist Etrigg?",a="Etrigg ist ein älterer Krieger des Blackrockclans, der während des Ersten und Zweiten Krieges als Leutnant unter Schwarzfaust und Orgrim Schicksalshammer diente. Heute weilt er in Grommash Hold in Orgrimmar als vertrauter Ratgeber und Berater von Kriegshäuptling Thrall.",al={"wer ist etrigg","etrigg lore","orc der neben thrall steht"}},{q="Warum betrachtet Etrigg einen Menschen als seinen Bruder?",a="Während seines Exils in Lordaeron rettete Etrigg dem Paladin Tirion Fordring das Leben, als bei einem Duell ein Steinturm einstürzte. Im Gegenzug verriet Tirion Etriggs Versteck nicht und kämpfte später in Stratholme gegen sein eigenes Volk, um Etriggs Hinrichtung zu verhindern, wobei er seinen Titel und seine Ländereien verlor. Verbunden durch gegenseitige Ehre betrachtet Etrigg Tirion als seinen Bruder.",al={"etrigg und tirion","etriggs menschlicher freund","blut und ehre"}},{q="Zu welchem Clan gehört Etrigg?",a="Etrigg gehört zum Blackrockclan. Er war ein hochrangiger Kommandant während der alten Kriege, verließ jedoch die verdorbenen Überreste des Clans, nachdem er die Wahrheit über das dämonische Verderben erfahren hatte, das sie leitete.",al={"etrigg clan","ist etrigg vom blackrockclan"}},{q="Warum verließ Etrigg die alte Horde?",a="Während des Zweiten Krieges bewachte Etrigg die Attentäterin Garona, welche die Dämonenanbetung und Manipulationen von Gul'dan und dem Schattenrat enthüllte. Nach der Niederlage der Horde erkannte Etrigg, dass ihre Behauptungen wahr waren, und ging voller Abscheu fort, um lieber einen friedlichen Ort zum Sterben zu suchen, als einer verdorbenen Kriegsmaschinerie zu dienen.",al={"warum etrigg die horde verließ","etrigg exil"}},{q="Wie gelangte Etrigg nach Orgrimmar?",a="Als Streitkräfte der Allianz Etrigg gefangen nahmen und sich anschickten, ihn in Stratholme hinzurichten, griffen Thrall und seine Truppen die Stadt an und befreiten ihn. Da er Thralls Hingabe an die Ehre und die Wiederentdeckung des Schamanismus sah, entschied sich Etrigg, dem jungen Kriegshäuptling nach Kalimdor zu folgen.",al={"wie etrigg thrall traf","etrigg gerettet"}},{q="Welche Rolle spielt Etrigg derzeit in Orgrimmar?",a="Etrigg berät Thrall direkt in Grommash Hold und hilft bei der Prüfung und Beurteilung neuer Rekruten, die der Neuen Horde die Treue schwören.",al={"etrigg quest","was macht etrigg"}}},fx={["71b6cd10"]={q="Auf wessen Seite steht Etrigg?",a="Etrigg ist voll und ganz der neuen Horde von Thrall gewidmet. Obwohl er einst der alten, blutrünstigen Horde unter Schwarzfaust und Orgrim Schicksalshammer diente, verließ er sie, nachdem er die Korruption hinter ihrem dämonischen Kreuzzug entdeckt hatte. Heute steht er Thrall in Grommash Hold als loyaler Berater und Wächter zur Seite und glaubt an diese neue schamanistische Vision von Ehre und Erlösung für das orkische Volk.",al={"fraktion von etrigg","wem dient etrigg","ist etrigg thrall gegenüber loyal"}},f3c80f4d={q="Was will Etrigg?",a="Etrigg möchte, dass sich die orkische Rasse von Ehre leiten lässt, anstatt die dunklen Fehler ihrer Vergangenheit zu wiederholen. Nachdem er die Täuschung des Schattenrats miterlebt und im Exil gelebt hat, widmet er nun seine verbleibenden Jahre der Beratung von Kriegshäuptling Thrall und der Ausbildung einer disziplinierten, prinzipientreuen neuen Generation von Horde-Kriegern, um ihre Heimat zu schützen.",al={"was sind die ziele von etrigg","motiv von etrigg","worauf hofft etrigg"}},["5abef9ad"]={q="Warum ist Etrigg berühmt?",a="Etrigg ist unter Veteranen als geschätzter Leutnant des Blackrock-Clans bekannt, der sowohl im Ersten als auch im Zweiten Krieg an der Seite von Legenden wie Orgrim Schicksalshammer und Varok Saurfang gekämpft hat. Sein Überleben, seine dramatische Rettung vor der Hinrichtung in Stratholme und sein tiefes Ehrenband mit dem menschlichen Paladin Tirion Fordring haben ihn in die Legenden eingehen lassen.",al={"warum ist etrigg bekannt","was machte etrigg berühmt","etriggs geschichte krieg"}}},fp="7,404,26.720.0,15.714.0,25.608.0,15.245.0,46.363.0,33.208.0,36.302.0,36.259.0,51.139.0"}
P.entries["npc:elanaria"] = {n="Elanaria",s="Elanaria ist eine Nachtelfen-Kriegerausbilderin und Koordinatorin, die auf der Terrasse der Krieger in Darnassus stationiert ist. Sie leitet aufstrebende Kämpfer in ganz Kalimdor an und stellt ihr Können gegen gefährliche Bedrohungen wie den Satyr Vorlus Elendshuf und geistige Wesen wie Eluras Schemen auf die Probe. Ihre Anleitung dient als entscheidende Brücke für Soldaten der Großen Allianz, die in der Hauptstadt der Nachtelfen ihre kriegerischen Fähigkeiten verfeinern.",h="Elanaria ist eine Nachtelfen-Kriegerausbilderin und Koordinatorin, die auf der Terrasse der Krieger in...",kw={"darnassus","elanaria","eluras schemen","schmied mathiel","teldrassil","vorlus elendshuf","krieger quests","die terrasse der krieger"},ang={["class:Warrior"]="Elanaria ist eine wichtige Kontaktperson auf der Terrasse der Krieger, die stufenangemessene Kampfprüfungen vergibt, welche mit robuster Ausrüstung belohnt werden und taktische Kampffertigkeiten verfeinern.",["faction:Alliance"]="Von der Hauptstadt Teldrassil aus hilft Elanaria dabei, die militärische Bereitschaft aufrechtzuerhalten und Soldaten auszurüsten, die die Interessen der Allianz in Nord-Kalimdor verteidigen.",["race:NightElf"]="Als Vertreterin der kriegerischen Traditionen von Darnassus arbeitet Elanaria daran, korrumpierte Wesen wie Satyrn und rastlose Schemen aus den angestammten Ländern der Kaldorei zu vertreiben."},sec={{t="Eine Sentinel der Terrasse",b="Elanaria steht stolz auf der Terrasse der Krieger inmitten der Äste von Darnassus und fungiert als Ausbilderin und Kontaktperson für kriegerische Champions. In einer Ära, in der sich die Nachtelfen offiziell der Großen Allianz angeschlossen haben, reicht ihre Aufgabe weit über das Mentoring lokaler Sentinels hinaus: Sie bereitet Krieger aller Hintergründe auf die harten Herausforderungen vor, denen ihre Länder gegenüberstehen."},{t="Prüfungen von Eisen und Geist",b="Elanaria ist nicht leicht mit Lob bei der Hand; sie erwartet Disziplin, Widerstandsfähigkeit und bewiesene Stärke. Sie weist erfahrene Abenteurer an, furchterregende Gegner zur Strecke zu bringen, die Eschental und Dunkelküste heimsuchen, darunter den korrupten Satyr Vorlus Elendshuf und gequälte Geister wie Eluras Schemen. Sie arbeitet außerdem mit erfahrenen Handwerkern wie Schmied Mathiel zusammen, um sicherzustellen, dass würdige Krieger angemessen für den Krieg bewaffnet sind."}},faq={{q="Wer ist Elanaria?",a="Elanaria ist eine Nachtelfe, die sich auf der Terrasse der Krieger in Darnassus befindet. Sie dient als Auftraggeberin für Kriegerquests und stellt aufstrebende Krieger vor Kampfprüfungen in ganz Nord-Kalimdor.",al={"elanaria darnassus","wer ist elanaria","elanaria npc"}},{q="Wo finde ich Elanaria?",a="Sie befindet sich auf der Terrasse der Krieger, dem erhöhten nördlichen Distrikt von Darnassus, der dem militärischen Trainingsgelände und den Verteidigungsanlagen der Stadt gewidmet ist.",al={"standort elanaria","wo ist elanaria","elanaria ort"}},{q="Welche Quests bietet Elanaria an?",a="Elanaria ist eine Schlüsselfigur in der mittleren Kriegerfortschrittsphase und bietet Aufgaben wie die Jagd auf den Satyr Vorlus Elendshuf, die Konfrontation mit Eluras Schemen und die Koordination mit lokalen Rüstungsschmieden wie Schmied Mathiel an.",al={"elanaria quests","quests von elanaria","elanaria krieger quest"}},{q="Warum schickt Elanaria Kämpfer gegen Vorlus Elendshuf?",a="Vorlus Elendshuf ist ein gefährlicher Satyr, dessen dämonische Verderbnis die nördlichen Wildnisgebiete bedroht. Elanaria beauftragt fähige Krieger mit seiner Vernichtung, um sowohl die Wälder zu schützen als auch ihr Können auf dem Schlachtfeld unter Beweis zu stellen.",al={"elanaria vorlus","vorlus elendshuf quest","warum vorlus elendshuf töten"}},{q="Wer ist Schmied Mathiel?",a="Schmied Mathiel ist ein Meister der Rüstungsschmiedekunst, der in Darnassus stationiert ist. Elanaria verweist Krieger an Mathiel, damit diese spezialisierte kriegerische Ausrüstung anfertigen oder erhalten können, die für den Einsatz an der Front geeignet ist.",al={"verbindung zu mathiel","schmied mathiel krieger","elanaria und mathiel"}},{q="Interagiert Elanaria auch mit Nicht-Nachtelfen?",a="Ja. Als Teil der Allianz unterstützt Elanaria alle berechtigten Krieger der Allianz, die auf der Terrasse der Krieger eintreffen und Rat sowie spezialisiertes Training suchen.",al={"können menschen mit elanaria sprechen","allianz krieger elanaria"}}},fx={de8f39db={q="Auf wessen Seite steht Elanaria?",a="Elanaria steht fest auf der Seite der Nachtelfen von Darnassus und der weiteren Allianz. Sie wohnt auf der Terrasse der Krieger in der Hauptstadt und dient ihrem Volk, indem sie fähige Krieger anleitet und anweist, ihre Länder gegen drohende Gefahren zu verteidigen.",al={"fraktion von elanaria","wem dient elanaria","loyalität von elanaria"}},d7c0e558={q="Was will Elanaria?",a="Elanaria sucht erfahrene Kämpfer, die bereit sind, Kalimdor zu beschützen und korrumpierende Übel zu beseitigen. Sie entsendet mutige Krieger, um gefährliche Feinde wie den Satyr Vorlus Vilehoof zu erschlagen, und weist vielversprechende Rekruten an geschickte Handwerker wie Smith Mathiel weiter, um sicherzustellen, dass sie für den Kampf richtig ausgerüstet sind.",al={"was braucht elanaria","zweck von elanaria","motiv von elanaria"}},["16a563e6"]={q="Warum ist Elanaria in Darnassus?",a="Elanaria ist auf der Terrasse der Krieger in Darnassus stationiert, um als Mentorin und Koordinatorin für Kämpfer in der Hauptstadt der Nachtelfen zu fungieren. Von diesem militärischen Zentrum aus kann sie leicht die Stärke besuchender Abenteurer einschätzen und sie dorthin entsenden, wo ihre Klingen am meisten gebraucht werden.",al={"warum ist elanaria hier","warum ist elanaria auf der terrasse der krieger","grund für elanarias standort"}}},fp="8,400,25.365.0,25.409.0,16.181.0,26.148.0,32.219.0,56.207.0,21.184.0,44.156.0"}
P.entries["npc:elder-bloodhoof"] = {n="Urahne Bluthuf",s="Urahne Bluthuf ist ein Vorfahrengeist, der knapp nördlich des Dorfes der Bluthufe in Mulgore ruht. Er zeigt sich Reisenden vor allem während des Mondfests und gilt als verehrter Schutzgeist des Stammes der Bluthufe.",h="Urahne Bluthuf ist ein Vorfahrengeist, der knapp nördlich des Dorfes der Bluthufe in Mulgore ruht.",kw={"ahn","bloodhoof","urahne bluthuf","mondfest","mulgore","teufelsfelsen","taurengeist"},ang={["class:Shaman"]="Schamanen verehren Urahne Bluthuf als Manifestation des Ahnenkults, die verdeutlicht, wie Vorfahrengeister ihre Nachkommen im irdischen Reich leiten und beschützen.",["race:Tauren"]="Für Pilger der Tauren ist es ein direkter Austausch mit den Wurzeln ihres Stammes, Urahne Bluthuf ihren Respekt zu erweisen – eine Ehrung der Opfer jener, die lange vor der Gründung von Donnerfels durch Mulgore zogen."},sec={{t="Geist der Ahnen",b="Urahne Bluthuf verkörpert das tiefe spirituelle Band, das die Tauren mit ihrer Abstammungslinie verbindet. Nahe dem Dorf der Bluthufe manifestiert sich dieser geisterhafte Älteste, um über sein Volk zu wachen und respektvolle Reisende zu belohnen, die während des Mondfests nach Weisheit suchen. Seine Anwesenheit bekräftigt die beständige Führung verstorbener Häuptlinge und Stammesahnen, deren Geister eng mit den Ebenen von Mulgore verbunden bleiben."}},faq={{q="Wer ist Urahne Bluthuf?",a="Urahne Bluthuf ist ein geisterhafter Taurengeist, der knapp nördlich des Dorfes der Bluthufe in Mulgore erscheint. Er vertritt die geehrten Ahnen des Stammes der Bluthufe und gewährt Reisenden, die ihn im Rahmen jahreszeitlicher Bräuche wie dem Mondfest aufsuchen, Segen und uralte Weisheit.",al={"urahne bloodhoof lore","wer ist der geist vor bloodhoof","identität von urahne bloodhoof"}},{q="Wann kann man Urahne Bluthuf sehen?",a="Urahne Bluthuf manifestiert sich vor allem während des alljährlichen Mondfests, wo er als Ältestengeist Festsegen spendet.",al={"wo ist urahne bloodhoof","urahne bloodhoof verschwunden","urahne bloodhoof finden"}},{q="Welche Verbindung hat er zum Dorf der Bluthufe?",a="Als geehrter Ahn, der den Namen des Klans trägt, wacht Urahne Bluthuf über die Ahnenstätte des Dorfes der Bluthufe. In der Tradition der Tauren ist es von tiefer Bedeutung, dass Vorfahrengeister in der Nähe der Orte verweilen, an denen ihre Nachkommen leben und zusammenkommen.",al={"warum ist er bei bloodhoof","verwandtschaft urahne bloodhoof cairne"}}},fx={["376494a8"]={q="Auf wessen Seite steht Urahne Bluthuf?",a="Urahne Bluthuf ist ein verehrter Vorfahre der Tauren des Dorfes der Bluthufe und mit der Horde verbündet. Als einer der Vorfahrengeister, die während des Mondfests geehrt werden, bietet er Reisenden, die sein Andenken und die heiligen Traditionen seines Volkes ehren, Segen und Weisheit an.",al={"fraktion von urahne bluthuf","gehört urahne bluthuf zur horde","wem dient urahne bluthuf"}},f5643df0={q="Was will Urahne Bluthuf?",a="Urahne Bluthuf möchte von den Lebenden erinnert und geehrt werden. Wenn Reisende während des Mondfests die alten Geister von Kalimdor aufsuchen, gewährt er im Austausch für Euren Respekt und die Anerkennung der Vergangenheit seinen Segen, Münzen der Urahnen und Worte der Weisheit.",al={"ziel von urahne bluthuf","was will urahne bluthuf","warum mit urahne bluthuf sprechen"}},["2e395d43"]={q="Warum ist Urahne Bluthuf hier in Mulgore?",a="Sein Geist verweilt direkt nördlich des Dorfes der Bluthufe, da diese grasbewachsenen Ebenen die angestammte Heimat seines Stammes sind. Er wacht von jenseits des Schleiers des Todes über seine Nachkommen und kehrt jedes Jahr in das Land zurück, in dem das Volk von Bluthuf lebt und seine Herden weidet.",al={"warum ist urahne bluthuf hier","warum ist urahne bluthuf außerhalb von bloodhoof","grund für standort von urahne bluthuf"}}},fp="15,221,23.396.0,23.275.0,33.131.0,44.246.0"}
P.entries["npc:elder-bronzebeard"] = {n="Urahne Bronzebart",s="Urahne Bronzebart ist ein uralter Geist der Irdenen, der während des Mondfests im Mystic Ward von Eisenschmiede erscheint. Er trägt den Namen des Clans, der die Stadt beherrscht, und seine spektrale Präsenz dient als Brücke zwischen den modernen Zwergen und ihren aus Stein gehauenen Vorfahren.",h="Urahne Bronzebart ist ein uralter Geist der Irdenen, der während des Mondfests im Mystic Ward von...",kw={"vorfahr","irdene","urahne bronzebart","eisenschmiede","mondfest","magni","mystic ward"},ang={["faction:Alliance"]="Allianz-Pilger, die Eisenschmiede während des Mondfests besuchen, finden einen Urahnen vor, der die Grundfesten des Zwergenreichs verkörpert.",["race:Dwarf"]="Für Zwerge bietet die Begegnung mit Urahne Bronzebart einen seltenen, direkten Einblick in ihre irdene Abstammung und bestätigt die historischen Erkenntnisse, die von der Forscherliga ans Licht gebracht werden."},sec={{t="Ein Urvater im Mystic Ward",b="Urahne Bronzebart, der in der Nähe des Teichs im Mystic Ward von Eisenschmiede erscheint, trägt nicht das Fleisch der modernen Zwerge; stattdessen hat seine geisterhafte Gestalt die Form eines Irdenen, jener uralten Rasse, die von den Titanen aus lebendigem Stein geschmiedet wurde. Zwergische Gelehrte und Forscher beginnen gerade erst, ihre Ursprünge durch Ausgrabungen in ganz Khaz Modan und darüber hinaus aufzudecken, was die Präsenz dieses Geistes zu einem bemerkenswerten lebendigen Relikt macht. Schon sein Name und sein Antlitz deuten darauf hin, dass er ein direkter Vorfahre des Bronzebeard-Clans ist und stummer Zeuge dessen bleibt, wie weit sich seine steingeborenen Nachkommen entwickelt haben."}},faq={{q="Warum sieht Urahne Bronzebart wie ein Irdischer statt wie ein normaler Zwerg aus?",a="Zwerge sind die Nachkommen der Irdenen, uralten Wesen, die von den Titanen aus Stein geschaffen wurden und später dem Fluch des Fleisches erlagen. Da Urahne Bronzebart in der fernen Vergangenheit lebte, bevor diese Transformation vollständig einsetzte, behält sein Geist die steinerne Gestalt seiner irdenen Ära bei.",al={"warum ist urahne bronzebeard aus stein","ist urahne bronzebeard ein irdener","urahne bronzebeard volk"}},{q="Ist er mit König Magni Bronzebart verwandt?",a="Obwohl die genauen Verzweigungen alter Stammbäume in der Geschichte verloren gegangen sind, deuten sein Name und seine Anwesenheit in der Zwergenhauptstadt stark darauf hin, dass er ein verehrter Urvater des Bronzebeard-Clans ist – jener Blutlinie, die Eisenschmiede derzeit unter König Magni regiert.",al={"ist er magnis vorfahr","verwandter von magni bronzebart","stammbaum der bronzebeards"}},{q="Warum ist Urahne Bronzebart in Eisenschmiede?",a="Während des Mondfests materialisieren sich Geister der Urahnen in ganz Azeroth, um Reisenden Weisheit und Segen zu spenden. Urahne Bronzebart manifestiert sich im Mystic Ward von Eisenschmiede und ruht nahe dem ruhigen Teich, wo sich zwergische Magier und Gelehrte versammeln.",al={"was macht urahne bronzebeard hier","wo ist urahne bronzebeard","mystic ward geist"}}},fx={f31842b8={q="Wer ist Urahne Bronzebart?",a="Urahne Bronzebart ist ein alter irdener Geist, der im Mystic Ward von Eisenschmiede verweilt. Er erscheint in der steinernen Form seiner titanengeschmiedeten Vorfahren statt in Fleisch und Blut und repräsentiert die tiefen, angestammten Wurzeln des Zwergenvolkes und ihre fortdauernde Abstammungslinie.",al={"wer ist urahne bronzebart","identität von urahne bronzebart","was ist urahne bronzebart"}},c14d37b0={q="Auf wessen Seite steht Urahne Bronzebart?",a="Als geehrter Vorfahre, der im Herzen von Eisenschmiede steht, wacht Urahne Bronzebart friedlich über die Hauptstadt der Zwerge und steht auf der Seite seiner Sippe und der Allianz. Er bietet Reisenden und Pilgern, die sich ihm nähern, Grüße an.",al={"fraktion von urahne bronzebart","auf wessen seite steht urahne bronzebart","ist urahne bronzebart allianz"}},a81f3e52={q="Was will Urahne Bronzebart?",a="Urahne Bronzebart sucht nichts weiter, als eine Gemeinschaft mit denen zu teilen, die den alten Wegen huldigen. Als wandernder Geist der Vergangenheit begrüßt er Pilger und schenkt respektvollen Besuchern seine Anwesenheit.",al={"was will urahne bronzebart","motiv von urahne bronzebart","warum möchte urahne bronzebart sprechen"}}},fp="17,276,31.551.0,75.284.0,40.247.0,38.259.0"}
P.entries["npc:elder-darkcore"] = {n="Urahne Dunkelherz",s="Urahne Dunkelherz ist ein uralter Geist, der während des Mondfests im Thronsaal der Ruinen von Lordaeron über Unterstadt erscheint. Als Vertreter der geehrten Ahnen der Welt bietet er Reisenden, die ihn aufsuchen, seinen Segen und festliche Zeichen an. Seine Anwesenheit markiert einen friedvollen, nachdenklichen Moment inmitten der Ruinen eines gefallenen Menschenreichs.",h="Urahne Dunkelherz ist ein uralter Geist, der während des Mondfests im Thronsaal der Ruinen von Lordaeron über...",kw={"ahne","münze der urahnen","darkcore","urahne dunkelherz","mondfest","ruinen von lordaeron","thronsaal","unterstadt"},ang={["faction:Alliance"]="Ein Besuch bei Urahne Dunkelherz erfordert es, an hochstufigen Wachtposten der Verlassenen und königlichen Wachen vorbeizuschlüpfen, die um die Ruinen von Capital City herum stationiert sind, was ihn zu einer der gefährlichsten Stationen des Festes für die Allianz macht.",["race:Undead"]="Urahne Dunkelherz verweilt nur wenige Schritte von den Oberflächenaufzügen von Unterstadt entfernt und steht genau auf jenen Steinen, auf denen das Königreich Lordaeron zerstört wurde."},sec={{t="Ein Geist im Thronsaal",b="Während des jährlichen Mondfests manifestieren sich die Geister uralter Urahnen in ganz Azeroth, um ihre Weisheit mit Abenteurern zu teilen. Urahne Dunkelherz hält an einem der düstersten Orte der Welt Wache: im königlichen Thronsaal in den Ruinen von Lordaeron, direkt über dem Eingang nach Unterstadt. Umgeben von dem blutbefleckten Boden, auf dem König Terenas Menethil II fiel, bietet dieser geisterhafte Ahne jenen, die mutig genug sind, das Herz des Territoriums der Verlassenen zu betreten, um ihm ihren Respekt zu zollen, eine Münze der Urahnen und seinen Segen an."}},faq={{q="Wer ist Urahne Dunkelherz?",a="Urahne Dunkelherz ist einer der geehrten geisterhaften Ahnen, die sich während des saisonalen Mondfests manifestieren. Er erscheint im Thronsaal über Unterstadt, um Besuchern Segen und Münzen der Urahnen zu verleihen.",al={"urahne dunkelherz","darkcore","wer ist darkcore"}},{q="Wo kann ich Urahne Dunkelherz finden?",a="Er befindet sich im zerstörten Thronsaal von Capital City in den Ruinen von Lordaeron, direkt über dem Abgang, der hinab nach Unterstadt führt.",al={"wo ist darkcore","darkcore standort","unterstadt urahne"}},{q="Ist Urahne Dunkelherz der Allianz gegenüber feindlich gesinnt?",a="Urahne Dunkelherz selbst ist neutral und heißt alle Reisenden willkommen, die kommen, um ihn zu ehren. Da er jedoch inmitten der Festung der Verlassenen in den Ruinen von Lordaeron steht, müssen Allianzabenteurer den in der Nähe patrouillierenden feindlichen Wachen vorsichtig ausweichen.",al={"kann allianz mit darkcore sprechen","ist darkcore horde","unterstadt mondfest allianz"}},{q="Was bringt es, Urahne Dunkelherz zu ehren?",a="Ihm Eure Ehrerbietung zu erweisen schließt die Festtagsquest ab, um sein Andenken zu ehren, und belohnt Euch mit einer Münze der Urahnen sowie einem roten Glücksumschlag, der festliche Leckereien enthält.",al={"darkcore belohnung","darkcore quest"}}},fx={["3a0e846b"]={q="Auf wessen Seite steht Urahne Dunkelherz?",a="Urahne Dunkelherz schließt sich nicht den modernen Konflikten der Horde oder Allianz an. Als geehrter Vorfahrengeist, der am Mondfest teilnimmt, steht er friedlich über sterblichen Streitigkeiten und heißt jeden Reisenden willkommen, der ihm mit Respekt begegnet, egal unter welcher Flagge er marschiert.",al={"fraktion von urahne dunkelherz","ist urahne dunkelherz horde oder allianz","loyalität von dunkelherz"}},["32c6e8a4"]={q="Was will Urahne Dunkelherz?",a="Urahne Dunkelherz möchte während des Mondfests die alte Weisheit und den Segen der Vorfahren teilen. Er wartet darauf, dass Reisende der Vergangenheit ihren Respekt erweisen, und bietet denjenigen, die sein lang andauerndes Gedächtnis ehren, seinen Segen und Zeichen des Erbes der Urahnen an.",al={"was will urahne dunkelherz","zweck von urahne dunkelherz","warum urahne dunkelherz besuchen"}},e5445cfd={q="Warum ist Urahne Dunkelherz in den Ruinen von Lordaeron?",a="Urahne Dunkelherz erscheint im zerstörten Thronsaal über der Unterstadt als Teil der weltweiten Beobachtung des Mondfests. Die Geister der Uralten manifestieren sich an Orten, die in ganz Azeroth von tiefer Geschichte und Leid durchdrungen sind, und ermöglichen es Sterblichen, selbst inmitten gefallener Königreiche mit den Erinnerungen der Vorfahren zu kommunizieren.",al={"warum ist urahne dunkelherz in der unterstadt","warum urahne dunkelherz in ruinen von lordaeron","lore zum standort von urahne dunkelherz"}}},fp="14,358,27.525.0,22.210.0,32.148.0,42.248.0,43.151.0"}
P.entries["npc:elder-goldwell"] = {n="Urahne Goldbrunn",s="Urahne Goldbrunn ist ein uralter irdener Geist, der nahe der Zwergensiedlung Kharanos in Dun Morogh verweilt. Dieser verehrte Urahne erscheint während des Mondfests und repräsentiert die vergessenen Ursprünge der modernen Zwergenzivilisation.",h="Urahne Goldbrunn ist ein uralter irdener Geist, der nahe der Zwergensiedlung Kharanos in Dun Morogh verweilt.",kw={"ahne","dun morogh","irdener","urahne goldbrunn","goldbrunn","kharanos","mondfest"},ang={["faction:Alliance"]="Reisende der Allianz, die Kharanos durchqueren, suchen Goldbrunn oft auf, um ihm ihren Respekt zu erweisen und traditionellen Segen des Glücks zu empfangen.",["race:Dwarf"]="Für Zwerge bietet die Begegnung mit Urahne Goldbrunn einen seltenen, direkten Einblick in ihr uraltes, aus Stein geformtes Erbe und die Abstammungslinie, die das moderne Eisenschmiede mit den Irdenen verbindet."},sec={{t="Ein Geist der Irdenen",b="Urahne Goldbrunn manifestiert sich als durchscheinender irdener Geist, der über die verschneiten Hänge von Kharanos wacht. Im Gegensatz zu modernen sterblichen Zwergen aus Fleisch und Blut spiegelt seine steinerne Gestalt das uralte titanengeschmiedete Volk wider, von dem der Bronzebeard-Clan abstammt. Seine Anwesenheit während der Ahnenfeiern bietet Reisenden die Gelegenheit, dieses uralte Erbe zu ehren."}},faq={{q="Wer ist Urahne Goldbrunn?",a="Urahne Goldbrunn ist ein irdener Ahnengeist, der in Dun Morogh zu finden ist. Er besucht Kharanos während der saisonalen Ahnenfeierlichkeiten, damit moderne Reisende den Vorfahren der Zwerge ihren Respekt erweisen können.",al={"urahne goldbrunn identität","wer ist goldbrunn","goldbrunn lore"}},{q="Wo befindet sich Urahne Goldbrunn?",a="Er steht vor der Zwergenstadt Kharanos in Dun Morogh, für gewöhnlich in der Nähe des örtlichen Gasthauses und der Versammlungsplätze.",al={"urahne goldbrunn aufenthaltsort","wo man urahne goldbrunn findet","goldbrunn finden"}},{q="Warum sieht Urahne Goldbrunn wie ein Irdener und nicht wie ein Zwerg aus?",a="Zwerge führen ihre Abstammung auf die von den Titanen erschaffenen Irdenen mit ihrer Steinhaut zurück. Als einer der ältesten Geister, die vergangene Generationen ehren, behält Goldbrunn das ursprüngliche irdene Antlitz statt des sterblichen Fleisches lebender Zwerge bei.",al={"warum ist goldbrunn ein irdener","ist goldbrunn ein irdener","goldbrunn felsenzwerg"}}},fp="14,232,23.344.0,22.202.0,32.124.0,65.240.0"}
P.entries["npc:elder-graveborn"] = {n="Urahne Grufthauch",s="Urahne Grufthauch ist ein Vorfahrengeist, der sich während des Mondfests südöstlich von Brill manifestiert. Er erscheint als geisterhafter irdener Urahne, ehrt Reisende und leitet Pilger an, die nach weiteren uralten Geistern im nördlichen Lordaeron suchen.",h="Urahne Grufthauch ist ein Vorfahrengeist, der sich während des Mondfests südöstlich von Brill manifestiert.",kw={"ahne","brill","irdener","urahne grufthauch","graveborn","mondfest","tirisfal"},ang={["faction:Alliance"]="Allianzpilger müssen die Außenbezirke von Brill vorsichtig umgehen, um Graveborn ihren Respekt zu erweisen, ohne den Zorn der Stadtwachen und Patrouillen der Verlassenen auf sich zu ziehen.",["race:Undead"]="Für die Verlassenen, die die Straße zwischen Brill und Unterstadt bereisen, dient Graveborn als friedvolle Erinnerung an die uralte Vergangenheit Azeroths, unberührt von der Geißel oder der Seuche."},sec={{t="Ein Geist in Tirisfal",b="Urahne Grufthauch erscheint dicht hinter der Siedlung Brill der Verlassenen und steht im Rahmen des weltweiten Mondfests in den heimgesuchten Wäldern von Tirisfal. Trotz der verseuchten Umgebung und des zerrütteten Zustands des Königreichs begrüßt der geisterhafte Urahne Reisende friedvoll, die den traditionellen Segen des Festes suchen. Neben der Weitergabe seiner eigenen Weisheit der Ahnen teilt Graveborn Neuigkeiten über andere Urahnen mit, die in der Nähe verweilen – und weist Pilgern den Weg zu Geistern in Unterstadt, dem Grabmal sowie in den Pestländern."}},faq={{q="Wer ist Urahne Grufthauch?",a="Urahne Grufthauch ist ein verehrter Vorfahrengeist, der während des Mondfests erscheint. Er materialisiert sich in Tirisfal südöstlich von Brill, um vorüberziehenden Abenteurern Festtagssegen zu gewähren.",al={"urahne graveborn lore","wer ist graveborn","brill geisterurahne"}},{q="Warum befindet er sich in Tirisfal?",a="Während des Mondfests erscheinen Vorfahrengeister auf ganz Azeroth, um vergangene Helden und das gemeinsame Erbe zu ehren. Urahne Grufthauch wacht über die Ländereien vor Brill und bewahrt eine uralte Präsenz inmitten des gefallenen Königreichs Lordaeron.",al={"warum brill","wo ist urahne graveborn"}},{q="Können Abenteurer der Allianz mit ihm sprechen?",a="Ja. Die Urahnen des Festes heißen Reisende beider Fraktionen unabhängig vom Territorium willkommen. Allerdings müssen Allianzcharaktere Vorsicht walten lassen, wenn sie sich seiner Ruhestätte nähern, da er sich in unmittelbarer Nähe zum Stützpunkt Brill der Verlassenen befindet.",al={"kann allianz mit graveborn sprechen","allianz urahne brill"}},{q="Welche Informationen bietet er Reisenden?",a="Urahne Grufthauch leitet Pilger zu anderen lokalen Ahnen und teilt Kunde über Geister, die in Unterstadt, dem Grabmal im Silberwald, der Kapelle des hoffnungsvollen Lichts, der weinenden Höhle und in Scholomance verweilen.",al={"urahne graveborn wegführung","graveborn zitate"}}},fx={a72aed3e={q="Was will Urahne Grufthauch?",a="Urahne Grufthauch möchte seine uralten Segnungen und die Weisheit seiner Vorfahren mit denjenigen teilen, die während des Mondfestes durch die Lande ziehen. Als Erdgeist, der zurückgekehrt ist, um das Erbe der Welt zu ehren, bittet er Reisende, dem Vergangenen Respekt zu zollen, gewährt ihnen seinen Segen und weist ihnen den Weg zu anderen geehrten Urahnen, die über den Kontinent verstreut sind.",al={"ziel von urahne grufthauch","warum urahne grufthauch besuchen","was will grufthauch"}},["066af8bb"]={q="Mit wem ist Urahne Grufthauch verbunden?",a="Grufthauch weiß, wo mehrere andere Ahnengeister zu finden sind. Er weist Reisende auf Urahne Dunkelherz in der Unterstadt, Urahne Obsidian nahe dem Grabmal, Snowcrown bei der Kapelle des Hoffnungsvollen Lichts, Meadowrun in der weinenden Höhle und Moonstrike in Scholomance hin.",al={"beziehungen von urahne grufthauch","wen kennt urahne grufthauch","kontakte von grufthauch"}}},fp="15,259,20.543.0,23.194.0,29.240.0,38.230.0,41.194.0"}
P.entries["npc:elder-morningdew"] = {n="Urahnin Morgentau",s="Urahnin Morgentau ist ein uralter Geist einer Nachtelfe, der während des Mondfests in Tausend Nadeln erscheint. Sie schenkt Reisenden, die sie inmitten der trockenen Schluchten und ausgetrockneten Salzebenen der Schimmernden Ebene aufsuchen, Weisheit und den Segen der Vorfahren.",h="Urahnin Morgentau ist ein uralter Geist einer Nachtelfe, der während des Mondfests in Tausend Nadeln...",kw={"vorfahre","urahn","urahnin morgentau","geist","mondfest","morningdew","nachtelf","tausend nadeln"},ang={["race:NightElf"]="Für die Kaldorei ist das Aufsuchen uralter Vorfahren wie Morningdew eine heilige Pflicht der Ehrerbietung, die die heutigen Nachtelfen mit den verehrten Geistern verbindet, die vor ihnen wandelten.",["race:Tauren"]="Tauren verehren Vorfahrengeister zutiefst, was Begegnungen mit Urahnen in ganz Kalimdor zu einer natürlichen Fortführung ihres kulturellen Respekts vor vergangener Weisheit macht."},sec={{t="Ein geehrter Geist des Festes",b="Während des Mondfests manifestieren sich die Geister verehrter Vorfahren der Nachtelfen und Tauren in ganz Kalimdor und den Östlichen Königreichen, um Weisheit, ihr Erbe und den Frieden zu feiern. Urahnin Morgentau ist eine solche Erscheinung, die Tausend Nadeln besucht, um Pilger zu begrüßen, die ihr die Ehre erweisen. Weder an eine Fraktion noch an sterbliche Konflikte gebunden, verleiht sie ihre Münze der Urahnen jedem Abenteurer, der respektvoll genug ist, ihren Rat zu suchen und ihren Segen zu empfangen."}},faq={{q="Wer ist Urahnin Morgentau?",a="Urahnin Morgentau ist ein Vorfahrengeist der Nachtelfen, der sich während des jährlichen Mondfests manifestiert. Sie wartet in Tausend Nadeln darauf, von Reisenden der Allianz wie auch der Horde geehrt zu werden.",al={"urahnin morningdew lore","wer ist morningdew","morningdew identität"}},{q="Was ist der Zweck, sie aufzusuchen?",a="Abenteurer suchen sie während des Mondfests auf, um den Ahnen ihren Respekt zu erweisen, und erhalten im Gegenzug für die Ehrung ihres Geistes eine Münze der Urahnen sowie einen Segen der Weisheit.",al={"warum urahnin morningdew finden","morningdew zweck","mondfest urahne"}},{q="Gehört sie zur Allianz oder zur Horde?",a="Wie alle Urahnen des Mondfests steht Urahnin Morgentau den weltlichen Konflikten neutral gegenüber. Sowohl Abenteurer der Allianz als auch der Horde können sich ihr friedlich nähern, um ihr die Ehre zu erweisen.",al={"ist morningdew feindlich","urahnin morningdew fraktion","kann horde mit morningdew sprechen"}}},fp="16,246,33.432.0,24.191.0,39.181.0,41.170.0"}
P.entries["npc:elder-obsidian"] = {n="Urahne Obsidian",s="Urahne Obsidian ist ein irdener Ahnengeist, der sich während des alljährlichen Mondfests beim Grabmal im Silberwald manifestiert. Inmitten der von den Verlassenen beanspruchten Gräber bietet er Reisenden, die das Fest ehren, die Weisheit und den Segen der uralten Welt an.",h="Urahne Obsidian ist ein irdener Ahnengeist, der sich während des alljährlichen Mondfests beim Grabmal im...",kw={"vorfahre","münze der urahnen","irdene","urahne obsidian","mondfest","das grabmal","silberwald"},ang={["faction:Alliance"]="Pilger der Allianz, die Urahne Obsidian aufsuchen möchten, müssen vorsichtig vorgehen, da seine gewählte Ruhestätte im Herzen der Siedlung Das Grabmal der Verlassenen liegt.",["race:Dwarf"]="Für Zwerge, die neugierig auf ihre titanengeschmiedete Herkunft sind, bietet das Gespräch mit einem irdenen Geist wie Urahne Obsidian einen seltenen Einblick in die Urzeit ihrer aus Stein gehauenen Vorfahren."},sec={{t="Ein Geist am Grabmal",b="Inmitten der düsteren Grüfte des Grabmals bildet Urahne Obsidian einen bemerkenswerten Kontrast zu den finsteren Weiten des Silberwalds. Als ätherischer irdener Urahne manifestiert sich sein Geist während des Mondfests, um das uralte Erbe von Azeroth zu feiern. Während die umliegenden Krypten von den Verlassenen gehalten und von wilden Worgen bedroht werden, empfängt Obsidian Reisende aller Gesinnungen in Frieden und verleiht Münzen der Urahnen sowie uralte Segen an jene, die sich die Zeit nehmen, seine Weisheit zu suchen."}},faq={{q="Wer ist Urahne Obsidian?",a="Urahne Obsidian ist ein uralter irdener Geist, der im Silberwald erscheint. Er taucht ausschließlich während des Mondfests auf und begrüßt Reisende, die das irdene Erbe der Welt ehren.",al={"urahne obsidian geschichte","wer ist obsidian","urahne am grabmal"}},{q="Wo ist Urahne Obsidian zu finden?",a="Er verweilt auf dem Friedhofsgelände des Grabmals, einem von den Verlassenen kontrollierten Dorf an der Straße im zentralen Silberwald.",al={"urahne obsidian standort","wo ist obsidian","urahne obsidian finden"}},{q="Warum erscheint ein irdener Urahne im Silberwald?",a="Während des Mondfests manifestieren sich die Geister alter Urahnen in ganz Azeroth, um ihre uralte Weisheit zu teilen. Obsidians spirituelle Gegenwart übersteigt lokale Territorialkonflikte, sodass er in aller Ruhe inmitten der alten Gräber verweilen kann.",al={"warum ist obsidian im silberwald","irdene im silberwald"}},{q="Können Abenteurer der Allianz mit Urahne Obsidian sprechen?",a="Ja. Die Urahnen des Festes verhalten sich gegenüber allen Reisenden unabhängig von ihrer Fraktion neutral. Da er jedoch im Grabmal weilt, müssen sich Allianzabenteurer vorsichtig an den feindseligen Wachen der Verlassenen vorbeibewegen, die in der Nähe stationiert sind, um ihn zu erreichen.",al={"kann allianz urahne obsidian besuchen","urahne obsidian allianzfreundlich"}}},fx={cd669d85={q="Auf wessen Seite steht Urahne Obsidian?",a="Urahne Obsidian hält sich aus den sterblichen Konflikten zwischen der Allianz und der Horde heraus. Als uralter Erdgeist, der zum Mondfest zurückgekehrt ist, bietet er jedem Abenteurer, der kommt, um die Urahnen zu ehren, seine Weisheit und den Segen seiner Ahnen an, ungeachtet der Loyalität, auch wenn er sich nahe der Siedlung der Verlassenen, dem Grabmal, manifestiert.",al={"ist urahne obsidian allianz oder horde","fraktion von urahne obsidian","seite von urahne obsidian"}},["5cd08f2c"]={q="Was will Urahne Obsidian?",a="Urahne Obsidian möchte von den Sterblichen Azeroths erinnert und geehrt werden. Während der Feierlichkeiten des Mondfestes heißt er Reisende willkommen, die seine uralte Präsenz aufsuchen, und gewährt denjenigen, die dem Vergangenen ihren Respekt zollen, seinen Segen sowie ein Zeichen des Ahnen-Glücks.",al={"was braucht urahne obsidian","ziel von urahne obsidian","warum urahne obsidian besuchen"}}},fp="14,275,25.494.0,22.188.0,34.153.0,54.251.0,51.227.0"}
P.entries["npc:elder-runetotem"] = {n="Urahnin Runentotem",s="Urahnin Runentotem ist ein uralter Taurengeist, der während des Mondfests außerhalb von Klingenhügel in Durotar erscheint. Als eine der verehrten Urahnen der Horde schenkt sie Reisenden, die sie in den roten Canyons aufsuchen, ihre Weisheit und ihren Segen.",h="Urahnin Runentotem ist ein uralter Taurengeist, der während des Mondfests außerhalb von Klingenhügel in...",kw={"münze der urahnen","durotar","urahnin runentotem","mondfest","klingenhügel","runetotem","taurengeist"},ang={["faction:Horde"]="Vor der stark befestigten Siedlung Klingenhügel stehend, verkörpert ihre Anwesenheit das spirituelle Bündnis zwischen den Orcs von Durotar und den Tauren von Mulgore.",["race:Tauren"]="Eine ehrwürdige Urahnin des Stammes der Runetotem so weit von Mulgore entfernt vorzufinden, ist eine besinnliche Mahnung daran, dass die Geister der Shu'halo über ihre Verbündeten in allen Ländern wachen."},sec={{t="Ein Geist in Durotar",b="Obwohl uralte Taurengeister gewöhnlich an die grasbewachsenen Ebenen und heiligen Grabstätten von Mulgore gebunden sind, verweilt Urahnin Runentotem weit entfernt von den Weidegründen ihres Volkes. Sie manifestiert sich neben der staubigen Siedlung Klingenhügel in Durotar. Für junge Orcs und wandernde Abenteurer dient ihre ätherische Präsenz als Brücke zwischen den uralten Traditionen der Shu'halo und der rauen neuen Heimat, die sich die Horde entlang des Großen Meeres geschaffen hat."},{t="Ehrungen der Urahnen",b="Während des Mondfests manifestieren sich die Geister großer Anführer, Schamanen und Helden auf der ganzen Welt, um mit den Lebenden Zwiesprache zu halten. Urahnin Runentotem repräsentiert die Linie der Runetotem – eine Abstammungslinie, die für ihre tiefe Ehrfurcht vor der Erdenmutter und ihre spirituelle Verbundenheit bekannt ist. Reisenden, die ihre Anwesenheit ehren, werden Urahnenzeichen und ihr spiritueller Segen zuteil."}},faq={{q="Wer ist Urahnin Runentotem?",a="Urahnin Runentotem ist eine geisterhafte Tauren-Urahnin, die sich in der Nähe von Klingenhügel in Durotar manifestiert. Sie ist eine der geehrten Urahnen, die während des Mondfests zurückkehren, um Reisende zu begrüßen und den Segen der Urahnen zu gewähren.",al={"urahnin runetotem lore","wer ist der taurengeist in klingenhügel","runetotem geist"}},{q="Warum befindet sich ein Taurengeist in Durotar?",a="Während die meisten uralten Taurengeister in Mulgore verwurzelt sind, wandern die Geister des Mondfests weit über Kalimdor und die Östlichen Königreiche hinaus. Ihre Anwesenheit in Klingenhügel ermöglicht es Reisenden der Horde, die Durotar durchqueren, der Weisheit der Kinder der Erdenmutter ihren Respekt zu zollen.",al={"warum ist runetotem in klingenhügel","taurengeist durotar"}},{q="Welche Verbindung hat sie zum Stamm der Runetotem?",a="Sie trägt den Namen des Clans der Runetotem, einer der prominenten Tauren-Blutlinien, die für ihre Schamanen, spirituellen Führer und Verbindungen zur Natur bekannt sind.",al={"urahnin des stammes der runetotem","familie runetotem"}},{q="Was bringt es, mit ihr zu sprechen?",a="Ein Gespräch mit Urahnin Runentotem ehrt ihr Andenken während des Mondfests und belohnt Abenteurer mit einer Münze der Urahnen sowie einem temporären Segen der Geister.",al={"was gibt urahnin runetotem","runetotem belohnung"}}},fx={["9c81a0c0"]={q="Auf wessen Seite steht Urahnin Runentotem?",a="Urahnin Runentotem steht auf der Seite der Horde und ihrer taurenischen Verwandten. Als geehrter Ahnengeist bietet sie Abenteurern, die die Wege der Ahnen respektieren und durch die Ländereien der Horde wandern, ihre uralte Weisheit und Segnungen an.",al={"ist urahnin runentotem horde","fraktion von urahnin runentotem","seite von urahnin runentotem"}},["021a9c1d"]={q="Was will Urahnin Runentotem?",a="Sie möchte die Erinnerung und Ehrfurcht des Volkes der Tauren mit Reisenden teilen, die durch Klingenhügel ziehen. Indem sie die Lebenden erreicht, erinnert sie Reisende an die Ahnengeister, die über die Länder wachen und uralte Traditionen lebendig erhalten.",al={"was sucht urahnin runentotem","warum mit urahnin runentotem sprechen","ziel von urahnin runentotem"}}},fp="15,244,19.432.0,16.352.0,23.207.0,42.296.0,53.162.0,34.163.0"}
P.entries["npc:elder-skyseer"] = {n="Urahne Himmelsdeuter",s="Urahne Himmelsdeuter ist der Geist eines Taurenvorfahren, der auf den hoch aufragenden Klippen des Freiwindpostens in Tausend Nadeln weilt. Als geehrter Ältester, der aus der Geisterwelt zurückgekehrt ist, beobachtet er die fortwährenden Reisen der Horde und bleibt tief mit den Ruhestätten seines Volkes verbunden.",h="Urahne Himmelsdeuter ist der Geist eines Taurenvorfahren, der auf den hoch aufragenden Klippen des...",kw={"ahne","urahne himmelsdeuter","freiwindposten","teufelsfelsen","taurengeist","tausend nadeln"},ang={["class:Shaman"]="Als spirituelle Vermittler, die mit den Elementen und Geistern sprechen, erkennen Schamanen in Urahne Himmelsdeuter die beständige Weisheit der Ahnen, die weiterhin über die Lebenden wachen.",["race:Tauren"]="Für die Tauren ist die Begegnung mit Urahne Himmelsdeuter ein unmittelbares Zwiegespräch mit einem Ahnen und verkörpert die spirituelle Ehrfurcht, wie sie an den Teufelsfelsen und in den gesamten Ebenen von Mulgore gelehrt wird."},sec={{t="Ein Geist des Freiwindpostens",b="Hoch über den Salzschluchten von Tausend Nadeln verweilt Urahne Himmelsdeuter in der windgepeitschten Plateausiedlung des Freiwindpostens. Während das geschäftige Treiben der Tauren des Freiwindpostens die gefährlichen Brücken und Holzplattformen des Außenpostens erfüllt, wacht Skyseer als ein Vorfahre über das Land, der den sterblichen Schleier durchschritten hat. Er dient Reisenden, die nach der Weisheit vergangener Generationen suchen, als spirituelles Leuchtfeuer und spendet jenen seinen Segen, die die alten Traditionen ehren."},{t="Bande zu den Ländern der Ahnen",b="Obwohl sich sein Geist für gewöhnlich zwischen den windgepeitschten Nadeln manifestiert, gehört Skyseer zur langen Reihe der Taurenvorfahren, deren Volk den heiligen Boden von Mulgore ehrt, wo die Ahnengeister der Teufelsfelsen über die Stämme wachen. Geister wie Skyseer zeigen, wie dünn der Schleier zwischen dem irdischen Reich und den Geistern der Vorfahren für die Tauren bleibt, und leiten künftige Generationen durch Erinnerung und Rituale an."}},faq={{q="Wer ist Urahne Himmelsdeuter?",a="Urahne Himmelsdeuter ist der Geist eines Taurenvorfahren, der am Freiwindposten in Tausend Nadeln erscheint. Er ist einer der verehrten Ältesten, deren Geister über die Reisenden von heute wachen und jenen spirituelle Führung bieten, die ihn aufsuchen.",al={"urahne skyseer lore","wer ist skyseer","skyseer nsc"}},{q="Warum ist Urahne Himmelsdeuter ein Geist?",a="Er ist ein uralter Vorfahre, der aus der sterblichen Welt geschieden ist. Die Kultur der Tauren pflegt eine tiefe spirituelle Verbindung zu ihren Ahnen, und bestimmte bedeutende Älteste verweilen oder kehren in Geistergestalt zurück, um die Lebenden zu leiten.",al={"warum ist skyseer tot","ist urahne skyseer tot","taurengeist freiwind"}},{q="Was ist seine Verbindung zu Mulgore?",a="Wie alle Ahnen der Tauren wird Skyseer von einem Volk geehrt, dessen Heimat Mulgore ist, wo die Ahnengeister der Teufelsfelsen über die Stämme wachen. Sein eigener Geist erscheint jedoch am Freiwindposten in Tausend Nadeln.",al={"skyseer teufelsfelsen","skyseer verbindung mulgore"}},{q="Wo kann ich Urahne Himmelsdeuter finden?",a="Urahne Himmelsdeuter befindet sich am Freiwindposten in Tausend Nadeln, hoch über dem Grund der Schlucht auf der befestigten Plateausiedlung.",al={"urahne skyseer aufenthaltsort","skyseer finden","wo ist skyseer"}}},fx={ab776b5a={q="Auf wessen Seite steht Urahne Himmelsdeuter?",a="Urahne Himmelsdeuter steht auf der Seite der Horde und der Stämme der Tauren. Als Ahnengeist über den windgepeitschten Plateaus des Freiwindpostens verweilend, wacht er über seine lebenden Verwandten und Reisenden, die der Horde treu ergeben sind, und bietet ahnenhafte Führung und Weisheit aus dem Jenseits an.",al={"fraktion von himmelsdeuter","ist urahne himmelsdeuter horde","loyalitäten von himmelsdeuter"}}},fp="13,283,25.461.0,27.413.0,21.223.0,29.221.0,34.219.0,31.136.0"}
P.entries["npc:elder-starweave"] = {n="Urahnin Sternenweber",s="Urahnin Sternenweber ist ein ehrwürdiger Vorfahrengeist der Nachtelfen, der während des Mondfests geehrt wird. Sie verweilt in der Hafenstadt Auberdine an der nebligen Küste der Dunkelküste und teilt die Weisheit alter Zeitalter mit vorbeireisenden Pilgern.",h="Urahnin Sternenweber ist ein ehrwürdiger Vorfahrengeist der Nachtelfen, der während des Mondfests geehrt wird.",kw={"vorfahr","auberdine","münze der urahnen","dunkelküste","urahnin sternenweber","mondfest","starweave"},ang={["class:Druid"]="Druiden, die das Fest begehen, sehen in Starweaves himmlischen Betrachtungen einen Einklang mit den Lehren des Cenarius über Erneuerung, Erinnerung und Harmonie mit der Natur.",["race:NightElf"]="Die Begegnung mit Urahnin Sternenweber an der Dunkelküste verbindet Kaldorei-Abenteurer direkt mit ihrer langen Ahnenreihe, die während uralter Kataklysmen zu Elune und den Sternen aufblickte."},sec={{t="Ein Leuchtfeuer in Auberdine",b="Urahnin Sternenweber erscheint als ätherischer Schemen zwischen den Küstenbehausungen von Auberdine und gehört zu den verehrten Ahnen, die vom Zirkel des Cenarius und den Völkern von Kalimdor geehrt werden. Während viele Reisende durch den Hafen eilen, um ins Landesinnere oder über das Meer zu gelangen, erhalten jene, die vor ihr innehalten, einen uralten Segen. Starweave spricht von den Bewegungen der Himmelskörper und bemerkt, dass die Sterne der modernen Ära ungewohnte Bahnen ziehen, die künftigen Generationen als Leuchtfeuer der Hoffnung und Seelenstärke dienen."}},faq={{q="Wer ist Urahnin Sternenweber?",a="Urahnin Sternenweber ist ein Vorfahrengeist der Nachtelfen, der während des Mondfests in Auberdine erscheint, um Reisende zu grüßen, ihnen uralte Weisheit zu schenken und Münzen der Urahnen zu überreichen.",al={"gaw urahnin starweave lore","wer ist starweave","urahnin sternenweber"}},{q="Wo ist Urahnin Sternenweber zu finden?",a="Sie hält sich nahe der Siedlung Auberdine entlang der Küstenlinie der Dunkelküste auf.",al={"wo ist urahnin starweave","urahnin starweave standort","starweave ort"}},{q="Warum erscheint sie als Geist?",a="Sie ist eine verehrte Ahnin, die während des Mondfests herbeigerufen wird und in geistlicher Gestalt erscheint, damit die Lebenden jenen ihren Respekt erweisen können, die die ferne Vergangenheit der Nachtelfen geprägt haben.",al={"warum ist starweave ein geist","ist starweave tot","warum geist"}},{q="Können Horde-Spieler mit ihr sprechen?",a="Ja. Die während des Mondfests geehrten Urahnen heißen Reisende jeglicher Zugehörigkeit willkommen, auch wenn Abenteurer der Horde den der Allianz wohlgesonnenen Hafen von Auberdine mit Vorsicht betreten müssen.",al={"kann horde starweave besuchen","horde urahnin starweave"}}},fx={["9514c67d"]={q="Auf wessen Seite steht Urahnin Sternenweber?",a="Urahnin Sternenweber ist mit den Nachtelfen und der Allianz verbündet. Als geehrte Urahnin, die in der Dunkelküste ruht, wacht sie über ihr Volk und bietet Reisenden, die der Allianz treu ergeben sind und sie aufsuchen, ihre himmlischen Segnungen und Weisheit an.",al={"ist urahnin sternenweber allianz","fraktion von urahnin sternenweber","wem dient urahnin sternenweber"}},d8911fea={q="Warum ist Urahnin Sternenweber hier in der Dunkelküste?",a="Urahnin Sternenweber verweilt in der Dunkelküste als Ahnengeist, um die Welt zu beobachten und jüngere Generationen zu leiten. Sie beobachtet die sich verschiebenden Sternbilder und liest die Zeichen des Himmels als Leuchtfeuer der Hoffnung und Stärke für die Prüfungen der kommenden Zeitalter.",al={"warum ist urahnin sternenweber in der dunkelküste","warum ist sternenweber hier","zweck von urahnin sternenweber"}}},fp="15,224,21.495.0,23.170.0,35.93.0,32.177.0,31.187.0"}
P.entries["npc:eleanor-shackleton"] = {n="Eleanor Shackleton",s="Eleanor Shackleton ist eine naturverbundene Verlassene, die südwestlich von Brill in Tirisfal lagert. Anstatt sich in der Stadt oder in Unterstadt aufzuhalten, hilft sie umherziehenden Reisenden dabei, das Überleben in der Wildnis und das Handwerk im Freien zu erlernen. Sie teilt ihren Nachnamen mit anderen Verlassenen, die in der Region überleben, was auf verbliebene Bindungen aus dem Leben vor der Seuche hindeutet.",h="Eleanor Shackleton ist eine naturverbundene Verlassene, die südwestlich von Brill in Tirisfal lagert.",kw={"brill","camping grundlagen","eleanor shackleton","shackleton","stöcke und knochen","der abenteurer","die große weite welt","tirisfal"},ang={["profession:Cooking"]="Eleanors Unterweisung umfasst das Entfachen eines Lagerfeuers und das Zubereiten von Mahlzeiten abseits zivilisierter Herde, was ihr Lager zu einer wichtigen Station für reisende Köche macht.",["race:Undead"]="Für die Verlassenen ist es lebenswichtig zu lernen, in der Wildnis ohne lebendige Annehmlichkeiten zu überleben, und Eleanor sorgt dafür, dass sich neu auferstandene Brüder und Schwestern schnell daran anpassen, sich in Tirisfal durchzuschlagen."},sec={{t="Ein Leitfaden für die Lichtungen",b="Während viele neu erwachte Verlassene direkt nach Brill ziehen oder in Unterstadt hinabsteigen, schlägt Eleanor Shackleton ihr Lager in den verwunschenen Wäldern im Südwesten auf. Das Überleben draußen in Tirisfal erfordert pragmatische Selbstständigkeit, und Eleanor fungiert als Ausbilderin für frischgebackene Abenteurer, die vom verseuchten Land leben wollen. Durch ihre verschiedenen Lektionen im Feld leitet sie Reisende dabei an, Lagerplätze zu errichten, Feuerholz zu sammeln und Handwerksfertigkeiten auszuüben, während sie fernab der Schmiedefeuer und Küchen der Zivilisation umherstreifen."},{t="Bande aus einem früheren Leben",b="In den zerschlagenen Überresten von Lordaeron dienen Familiennamen oft als einziges überdauerndes Band zur sterblichen Vergangenheit eines Untoten. Eleanor trägt den Nachnamen Shackleton, den sie mit Pierce Shackleton in Brill und Samantha Shackleton an einem anderen Ort in Tirisfal teilt. Ob die drei enge Bindungen pflegen oder lediglich eine gemeinsame Abstammung aus ihren sterblichen Tagen teilen: Jeder von ihnen hat sich eine eigene Rolle im Dienst der Verlassenen im gesamten verseuchten Königreich erarbeitet."}},faq={{q="Wo kann ich Eleanor Shackleton finden?",a="Eleanor Shackleton schlägt ihr Lager südwestlich von Brill auf, verborgen in den Wäldern von Tirisfal abseits der befestigten Hauptstraße.",al={"eleanor shackleton aufenthaltsort","wo ist eleanor","shackleton standort"}},{q="Was bringt Eleanor Shackleton Abenteurern bei?",a="Eleanor weist Reisende in die Grundlagen des Überlebens in der Wildnis ein und bietet Anleitung zum Lagern, Sammeln und Ausüben von Berufen in der freien Natur.",al={"eleanor quests","was macht eleanor","lagerquests tirisfal"}},{q="Ist Eleanor mit anderen Shackletons in Lordaeron verwandt?",a="Sie teilt ihren Familiennamen mit Pierce Shackleton in Brill und Samantha Shackleton, was auf eine mögliche Verwandtschaft aus der Zeit hinweist, bevor das Königreich an die Geißel fiel.",al={"pierce shackleton verwandte","samantha shackleton","familie shackleton geschichte"}},{q="Warum zeltet sie außerhalb von Brill, anstatt in der Stadt zu bleiben?",a="Eleanors Schwerpunkt liegt auf der Wildniskunde und dem Überleben im Freien. Wenn sie ihr Lager in den Wäldern aufschlägt, kann sie Reisende treffen und sie direkt dort ausbilden, wo diese Fähigkeiten benötigt werden.",al={"warum außerhalb von brill lagern","eleanor shackleton lager"}}},fx={a3327cab={q="Wer ist Eleanor Shackleton?",a="Eleanor Shackleton ist eine Waldläuferin der Verlassenen, die ihr Lager in den Wäldern südwestlich von Brill aufgeschlagen hat. Anstatt in der Stadt zu verweilen, widmet sie sich dem Überleben in der Wildnis von Tirisfal und führt angehende Untote in die Grundlagen des Überlebens in der freien Natur ein und darin, einfache Handwerksberufe im Feld auszuüben.",al={"wer ist eleanor shackleton","identität von eleanor shackleton","informationen zu eleanor shackleton"}},afc076fe={q="Auf wessen Seite steht Eleanor Shackleton?",a="Eleanor ist den Verlassenen und der Dunklen Fürstin treu ergeben. Sie operiert direkt außerhalb von Brill und hilft neu auferstandenen Mitgliedern ihres Volkes, sich an ihr Untod-Dasein anzupassen, indem sie ihnen beibringt, wie man überlebt, Materialien erntet und nützliche Handwerke in den heimgesuchten Lichtungen von Lordaeron verfeinert.",al={"fraktion von eleanor shackleton","ist eleanor shackleton horde","loyalitäten von eleanor shackleton"}},["48da77ca"]={q="Was will Eleanor Shackleton?",a="Eleanor möchte, dass Abenteurer grundlegende Überlebensfertigkeiten und Handwerksberufe in der Wildnis erlernen. Indem sie Reisende aussendet, um Berufe wie Kräuterkunde, Kürschnerei und Kochen unter freiem Himmel auszuüben, stellt sie sicher, dass Verlassene, die sich über die Sicherheit der Siedlungen hinauswagen, angemessen ausgerüstet sind, um sich zu versorgen.",al={"was will eleanor","ziele von eleanor shackleton","motive von eleanor shackleton"}}},fp="18,356,21.516.0,21.435.0,36.125.0,47.154.0,53.169.0,60.171.0"}
P.entries["npc:electrocutioner-6000"] = {n="Elektrokutor 6000",s="Der Elektrokutor 6000 ist ein tödlicher, aufgeladener Spinnenpanzer, der dazu eingesetzt wird, die Launch Bay in den verstrahlten Hallen von Gnomeregan zu verteidigen. Er wird von dem berüchtigten Lepragnom Lieutenant Tom 'Sizzlepants' Crankle pilotiert und steht sinnbildlich für Mekgineer Thermapluggs rücksichtslosen Ehrgeiz, Hochspannungselektrizität als Waffe einzusetzen.",h="Der Elektrokutor 6000 ist ein tödlicher, aufgeladener Spinnenpanzer, der dazu eingesetzt wird, die Launch Bay...",kw={"crankle","elektrokutionator","gnomeregan","launch bay","sizzlepants","spinnenpanzer","thermaplugg","werkstattschlüssel"},ang={["faction:Alliance"]="Das Durchbrechen der Launch Bay und die Ausschaltung von Crankle ist entscheidend, um den Werkstattschlüssel zu sichern und bei Befreiungsversuchen in Gnomeregan gefährliche vordere Korridore zu umgehen.",["profession:Engineering"]="Ingenieure bestaunen die rohe Hochspannungsleistung, die innerhalb des Fahrgestells gebändigt wird, auch wenn Thermapluggs rücksichtsloser Mangel an Erdung sie zu einer tödlichen Gefahr für die eigene Besatzung macht.",["race:Gnome"]="Für die verbannten Gnome von Eisenschmiede ist der Elektrokutor 6000 eine Beleidigung ihres Handwerks: eine gefährliche, ungetestete Monstrosität, die Thermapluggs verdrehte Missachtung gegenüber ordnungsgemäßer Ingenieursethik und dem Leben von Gnomen widerspiegelt."},sec={{t="Thermapluggs schockierender Prototyp",b="Mekgineer Thermaplugg war noch nie für gründliche Sicherheitstests bekannt. Angetrieben von Größenwahn und Hast schickt er regelmäßig ungetestete Kriegsmaschinen direkt vom Reißbrett in den aktiven Kampf. Der Elektrokutor 6000 war sein erster Versuch, rohe elektrische Ströme als offensives System an einem gepanzerten Spinnenpanzerfahrgestell zu nutzen. Anstatt tödliche Spannungsspitzen in einem Labor zu beheben, schickte Thermaplugg ihn sofort zur Bewachung der oberen Ebenen der Launch Bay von Gnomeregan."},{t="Lieutenant 'Sizzlepants'",b="Das Bedienen experimenteller Maschinen ist oft ein Todesurteil, insbesondere wenn tödliche Spannung im Spiel ist. Frühe Testpiloten kamen bei qualvollen Unfällen ums Leben, aber Lieutenant Tom Crankle schaffte es, den tödlichen Stromschlägen zu widerstehen, und überlebte am Steuer. Er erwarb sich den grimmigen Spitznamen 'Sizzlepants' und wurde zu einem Idol der Widerstandsfähigkeit unter den verstrahlten Lepragnomen, die Thermaplugg treu ergeben sind, während er verbissen den Weg zu den inneren Werkstätten bewacht."}},faq={{q="Wo kann der Elektrokutor 6000 gefunden werden?",a="Der Elektrokutor 6000 befindet sich auf einer erhöhten Laufstegplattform, die die Launch Bay in der gefallenen Stadt Gnomeregan überblickt.",al={"standort elektrokutionator 6000","wo ist der elektrokutionator","elektrokutionator 6000 finden"}},{q="Wer pilotiert den Elektrokutor 6000?",a="Er wird von Lieutenant Tom Crankle pilotiert, besser bekannt als 'Sizzlepants'. Er ist ein wahnsinniger Lepragnom-Offizier, der unter Thermapluggs Streitkräften als einziger Pilot Ruhm erlangte, der die gefährlichen internen elektrischen Entladungen des Panzers überlebte.",al={"wer steuert elektrokutionator 6000","sizzlepants","tom sizzlepants crankle","pilot des elektrokutionators"}},{q="Warum ist die Maschine so instabil?",a="Mekgineer Thermaplugg weigert sich, Zeit für ordnungsgemäße Sicherheitsbewertungen aufzuwenden, und zieht es vor, Erfindungen sofort in den Dienst zu stellen. Der Elektrokutor 6000 war sein erster Versuch mit einem unter Strom stehenden Spinnenpanzer, was seine tödlichen Stromzufuhrleitungen selbst für den eigenen Bediener unbeständig und gefährlich machte.",al={"warum schockt die maschine","elektrokutionator prototyp","thermaplugg design"}},{q="Warum ist das Besiegen des Elektrokutionators 6000 wichtig für Abenteurer?",a="Der Pilot besitzt den Werkstattschlüssel, ein wichtiges Gerät, das den Hintereingang zu den tieferen technischen Bereichen von Gnomeregan öffnet und Einsatzteams einen schnelleren Weg durch die zurückeroberten Einrichtungen ermöglicht.",al={"werkstattschlüssel","warum elektrokutionator besiegen","beute elektrokutionator 6000"}},{q="Ist der Elektrokutionator ein Automat oder ein Fahrzeug?",a="Es handelt sich um einen modifizierten Spinnenpanzer, der als gepanzertes Mechano-Fahrzeug fungiert und von seinem Piloten manuell aus einem internen Cockpit gesteuert wird, und nicht um eine autonome robotische Konstruktion.",al={"ist der elektrokutionator ein roboter","typ spinnenpanzer elektrokutionator"}}},fx={["71f538b6"]={q="Was ist der Elektrokutor 6000?",a="Der Elektrokutor 6000 ist ein experimenteller, aufgeladener Spinnenpanzer, der von Mekgineer Sicco Thermaplugg konstruiert wurde. Dieses flüchtige Gerät wurde entwickelt, um rohe elektrische Energie als verheerende Feldwaffe zu nutzen, und wird von Lieutenant Tom „Sizzlepants“ Crankle gesteuert, einem wahnsinnigen Gnom-Aussätzigen, der unter seinen seinesgleichen Berühmtheit erlangte, bloß weil er hinter dessen Kontrollen überlebte.",al={"wer ist elektrokutor 6000","was ist elektrokutor 6000","geschichte von elektrokutor 6000"}},["48c81a6d"]={q="Auf wessen Seite steht der Elektrokutor 6000?",a="Die Kriegsmaschine kämpft vollständig im Dienste von Mekgineer Thermaplugg und seiner Fraktion wahnsinniger Gnom-Aussätziger. Sie verteidigt fanatisch Thermapluggs Anspruch auf Gnomeregan und vernichtet jegliche Troggs, Agenten der Allianz oder Eindringlinge der Horde, die sich in die Nähe der Launch Bay wagen.",al={"fraktion von elektrokutor 6000","wem dient elektrokutor 6000","loyalität von elektrokutor 6000"}},["43526838"]={q="Was will der Elektrokutor 6000?",a="Angetrieben von dem unberechenbaren Geist von Lieutenant Crankle und der Megalomanie von Mekgineer Thermaplugg, ist es der Zweck des Panzers, alle Eindringlinge, die es wagen, in die tieferen Sektoren von Gnomeregan einzudringen, zu elektrocutieren und auszurotten.",al={"ziel von elektrokutor 6000","was will elektrokutor 6000","motiv von elektrokutor 6000"}},["0207499d"]={q="Warum ist der Elektrokutor 6000 in der Launch Bay?",a="Hoch oben auf den oberen Laufstegen der Launch Bay stationiert, bewacht der Panzer die erhöhten Gehwege und versperrt den Zugang tiefer in den Komplex. Sein Pilot trägt den Werkstattschlüssel und dient als schwer bewaffneter Kontrollpunkt gegen jeden, der versucht, in das Herz von Thermapluggs Festung einzudringen.",al={"warum ist elektrokutor 6000 hier","warum ist elektrokutor 6000 in der launch bay","zweck von elektrokutor 6000"}},e00292e3={q="Warum wird der Elektrokutor 6000 gefürchtet?",a="Die Maschine ist berüchtigt für ihre schiere Unberechenbarkeit und tödliche Leistung. Mekgineer Thermaplugg übersprang alle Sicherheitstests und brachte den aufgeladenen Prototyp direkt ins Feld, was eine Vorrichtung hinterließ, die so gefährlich instabil ist, dass Tom Crankle unter den Gnom-Aussätzigen zur Legende wurde, nur weil er innerhalb ihres elektrifizierten Fahrgestells überlebte.",al={"warum wird elektrokutor 6000 gefürchtet","ruf von elektrokutor 6000","warum ist elektrokutor 6000 berühmt"}}},fp="20,310,32.492.0,24.433.0,44.135.0,36.234.0,31.294.0,66.206.0,49.171.0"}
P.entries["npc:elling-trias"] = {n="Elling Trias",s="Elling Trias leitet Trias' Cheese, einen kleinen Laden im geschäftigen Handelsdistrikt von Sturmwind. Während er sich als jovialer und leidenschaftlicher Händler von Molkereiprodukten präsentiert, agiert er im Verborgenen als einer der bestvernetzten Informationsmakler des Königreichs. Hinter Käselaiben und herzlichem Geplänkel hat Trias stets sein Ohr am Boden, mit Verbindungen über ganze Kontinente hinweg.",h="Elling Trias leitet Trias' Cheese, einen kleinen Laden im geschäftigen Handelsdistrikt von Sturmwind.",kw={"elaine trias","elling trias","mathias shaw","der vermisste diplomat","der si:7","sturmwind","der handelsdistrikt","trias cheese","tyrion"},ang={["class:Rogue"]="Jeder Meister der Heimlichkeit erkennt sofort, dass Ellings Käseladen ein idealer toter Briefkasten ist. Seine Nähe zur Altstadt und seine engen Verbindungen zu Mathias Shaw machen ihn zu einer festen Größe in der Unterwelt von Sturmwind.",["faction:Alliance"]="Elling dient als unbesungene Säule des Geheimdienstes der Allianz und filtert still Gerüchte von Theramore bis Herdweiler, um das Reich vor innerer Zerrüttung zu bewahren."},sec={{t="Der Meisterkäser",b="Für den gewöhnlichen Kunden, der durch den Handelsdistrikt schlendert, ist Elling Trias lediglich ein Handwerker, der sich feinem Bruch widmet und seinen Laden gemeinsam mit seiner Frau Elaine und seinem Sohn Ben führt. Mit Begeisterung preist er Käselaiber an und plaudert freundlich mit den Stadtbewohnern. Eingeweihte wissen jedoch, dass Trias' Cheese eine der verlässlichsten Tarnungen in ganz Sturmwind darstellt. Das stetige Treiben des städtischen Handels bietet die perfekte Deckung für Agenten, Höflinge und Abenteurer, die diskrete Worte wechseln müssen, ohne die Aufmerksamkeit der Stadtwache zu erregen."},{t="Ein Netz aus Geflüster",b="Ellings Netzwerk aus Informanten und Verbündeten ist für einen Ladenbesitzer erstaunlich weit verzweigt. Er pflegt Verbindungen zu Meister Mathias Shaw vom SI:7, stimmt sich mit Kontakten der Kirche wie Bischof DeLavey ab und korrespondiert mit Agenten bis nach Dunkelhain, zur Insel Theramore und in die fernen Pestländer nahe Herdweiler. Wenn merkwürdige Gerüchte aufkommen – seien es Straßenräuber oder unauffällige Bewegungen auf dem Land –, setzt Trias das Puzzle oft schon zusammen, lange bevor der königliche Hof davon erfährt."},{t="Der vermisste Diplomat",b="Als ein hochrangiger Diplomat auf einer Reise nach Theramore verschwindet, wird Elling Trias zu einer entscheidenden Schlüsselfigur bei der Aufdeckung der Verschwörung. Indem er Ermittler an seine Kontakte verweist – darunter einen distanzierten Agenten namens Jorgen und seinen alten Freund Tyrion –, hilft Trias dabei, die Beteiligung der Bruderschaft der Defias an der Entführung aufzudecken. Trotz seines scharfen Verstandes und seiner zynischen Art erkennt Elling, dass das Komplott tief in das Herz der Aristokratie von Sturmwind reicht."}},faq={{q="Wer ist Elling Trias?",a="Elling Trias ist vordergründig ein Käsehändler, der zusammen mit seiner Familie Trias' Cheese im Handelsdistrikt von Sturmwind betreibt. Hinter dieser Fassade verbirgt sich ein erfahrener Informationsmakler mit Verbindungen zum SI:7, der Kirche und fernen Außenposten in ganz Azeroth.",al={"wer ist elling","elling trias identität","trias cheese käsemann"}},{q="Wo befindet sich sein Käseladen?",a="Ihr findet Trias' Cheese im Handelsdistrikt von Sturmwind, eingebettet in die Ladenzeile entlang der äußeren Kanalmauer, nahe der Grenze zur Altstadt.",al={"trias cheese standort","wo ist elling trias","trias laden sturmwind"}},{q="Welche Verbindung hat er zur Bruderschaft der Defias?",a="Trias ist kein Mitglied der Bruderschaft der Defias; stattdessen verfolgt er deren Bewegungen über sein Informantennetzwerk. Er hilft Abenteurern der Allianz dabei, Verwicklungen der Defias in subversive Machenschaften nachzuweisen, einschließlich der Entführung eines königlichen Diplomaten.",al={"trias defias","gehört trias zu den defias"}},{q="Woher kennt er Mathias Shaw?",a="Elling arbeitet eng mit Meister Mathias Shaw und dem Nachrichtendienst des SI:7 zusammen. Sein Laden dient als informeller Horchposten, von dem aus diskrete Nachforschungen abseits offizieller königlicher Kanäle eingeleitet werden können.",al={"trias und shaw","trias der si:7","gehört trias zum si:7"}},{q="Wer führt den Laden mit ihm?",a="Elling führt Trias' Cheese gemeinsam mit seiner Frau Elaine Trias und seinem Sohn Ben Trias. Zusammen wahren sie den Anschein eines geschäftigen, gewöhnlichen Familienbetriebs.",al={"trias familie","elling trias frau"}},{q="Welche Rolle spielt er bei den Ermittlungen um den vermissten Diplomaten?",a="Von Bischof DeLavey zu Trias geschickt, nutzen Ermittler Ellings weitverzweigtes Kontaktnetz – darunter seine alten Weggefährten Jorgen und Tyrion –, um die Schritte der Defias nachzuverfolgen und herauszufinden, wer den nach Theramore reisenden Diplomaten entführt hat.",al={"der vermisste diplomat trias","warum trias cheese besuchen"}}},fx={f0ad15b5={q="Auf wessen Seite steht Elling Trias?",a="Elling steht fest zu Sturmwind und der Allianz, obwohl er aus dem Schatten heraus operiert. Obwohl er seine Aktivitäten oft hinter der bescheidenen Fassade eines Käsehändlers im Handelsdistrikt verbirgt, verbinden ihn seine verdeckten Verbindungen direkt mit Meister Mathias Shaw und SI:7. Er arbeitet aktiv gegen Subversive wie The Defias Brotherhood, um das Reich sicher zu halten.",al={"ist elling trias sturmwind treu","für wen arbeitet elling trias","ist elling trias allianz"}},fc385e9b={q="Was will Elling Trias?",a="Öffentlich strebt Elling nach nichts anderem, als gemeinsam mit seiner Familie feinen Käse zu verkaufen. In Wahrheit möchte er die Sicherheit von Sturmwind wahren, indem er Informationen sammelt und Bedrohungen für die Krone ausmerzt. Wenn Krisen entstehen, nutzt er sein weitreichendes Kontaktnetzwerk, um Verschwörungen leise zu entwirren, ohne öffentliche Panik zu verursachen.",al={"motiv von elling trias","was ist das ziel von elling trias","warum hilft elling trias"}},e76b2a1d={q="Warum ist Elling Trias hier in Sturmwind?",a="Elling operiert aus dem geschäftigen Handelsdistrikt von Sturmwind, da ein beliebter Käseladen die perfekte Tarnung für Spionage bietet. Von hinter seinem Tresen aus kann er nahtlos Flüstern austauschen, Kuriere empfangen und sich mit Geheimdienstagenten im gesamten Königreich koordinieren, während er wie ein gewöhnlicher Händler erscheint, der mit seiner Frau und seinem Sohn den Laden führt.",al={"warum ist elling trias in sturmwind","warum bleibt elling in sturmwind","zweck von elling trias in der stadt"}}},fp="12,377,23.523.0,17.478.0,20.442.1,20.243.0,33.161.0,49.235.1,30.211.0,27.163.0,62.220.1"}
P.entries["npc:elu"] = {n="Elu",s="Elu ist ein Windreiterlehrling, der oben auf dem Freiwindposten in Tausend Nadeln stationiert ist. Begierig darauf, seine formelle Ausbildung zu beginnen und sich in die Lüfte zu erheben, beauftragt er Reisende der Horde damit, wilde Wyverneier aus nahegelegenen Nestern zu beschaffen.",h="Elu ist ein Windreiterlehrling, der oben auf dem Freiwindposten in Tausend Nadeln stationiert ist.",kw={"elu","freiwindposten","der steilhang","tausend nadeln","windreiter","wyvern","wyverneier"},ang={["faction:Horde"]="Das Sammeln von Wyverneiern für Elu stärkt direkt das Kurier- und Transportnetzwerk der Horde und sorgt dafür, dass abgelegene Außenposten in ganz Kalimdor über den Luftweg verbunden bleiben.",["race:Tauren"]="Für Tauren-Abenteurer bedeutet die Unterstützung von Elu, einem Stammesgenossen beizustehen, der danach strebt, die uralte und überlebenswichtige Kunst der Wyvernhaltung hoch über den angestammten Schluchten ihrer Heimat zu meistern."},sec={{t="Ein eifriger Lehrling",b="Hoch über den Salzpfannen und dem Grund des Canyons auf dem Freiwindposten verbringt Elu seine Tage damit, die Flugreittiere der Siedlung zu versorgen, während er von seinem eigenen Flug träumt. Als junger Taurenlehrling sehnt er sich danach, sich den Reihen der meisterhaften Windreiter anzuschließen, die die hoch aufragenden Mesas von Kalimdor patrouillieren. Bevor er jedoch mit dem eigentlichen Flugtraining beginnen kann, muss er seine Fähigkeiten unter Beweis stellen, indem er den Horst mit neuem Wyvernnachwuchs versorgt; dazu schickt er fähige Abenteurer los, um unversehrte Eier von den wilden Wyvern zu erbeuten, die auf dem Steilhang nisten."}},faq={{q="Wer ist Elu?",a="Elu ist ein Tauren-Windreiterlehrling, der auf dem Freiwindposten in Tausend Nadeln stationiert ist und dabei hilft, neue Reittiere für das Flugnetzwerk der Horde zu sichern und aufzuziehen.",al={"elu freiwindposten","wer ist elu","taurenlehrling elu"}},{q="Warum braucht Elu Wyverneier?",a="Elu hat die Aufgabe, die Wyvernställe für die meisterhaften Windreiter wieder aufzufüllen. Die Aufzucht der Bestien aus frisch gesammelten Eiern stellt sicher, dass sie ordnungsgemäß abgerichtet und als verlässliche Reittiere an die Horde gebunden werden können.",al={"warum wyverneier","elu wyvern quest","elu questziel"}},{q="Wohin schickt Elu Abenteurer, um Eier zu finden?",a="Er schickt Abenteurer zum Steilhang, einer gefährlichen Mesa im Westen von Tausend Nadeln, auf der Kolonien wilder Wyvern ihre Nester erbittert verteidigen.",al={"wo gibt es wyverneier","wo ist der steilhang","elu eier fundort"}}},fx={["74f15e75"]={q="Auf wessen Seite steht Elu?",a="Elu ist der Horde und seinen Tauren-Gefährten treu ergeben. Er ist hoch oben auf den Klippen des Freiwindpostens stationiert und arbeitet gemeinsam mit den Meister-Windreitern der Horde daran, die fliegenden Reittiere auszubilden und zu versorgen, die für Reisen durch Kalimdor unerlässlich sind.",al={"fraktion von elu","ist elu bei der horde","wem dient elu"}},["3d25520c"]={q="Warum ist Elu am Freiwindposten?",a="Elu dient als Windreiter-Lehrling am Freiwindposten. Er bleibt hier, um den Flugmeistern zu helfen und sich seinen Platz am Himmel zu verdienen. Seine Aufgabe besteht darin, frische Wyvern von den hohen Vorsprüngen der Tausend Nadeln zu sichern, damit sie für die Reiter der Horde ausgebildet werden können.",al={"warum ist elu in den tausend nadeln","elu freiwindposten","elu aufgabe"}},c552be8c={q="An wen ist Elu gebunden?",a="Elu ist ein Lehrling der Meister-Windreiter der Horde. Er untersteht den Ausbildern und Tierführern, die die geflügelten Wyvern Kalimdors aufziehen, und arbeitet unter deren Anleitung in der Hoffnung, seine eigene formelle Ausbildung als Windreiter beginnen zu können.",al={"elu meister","für wen arbeitet elu","elu windreiter"}}},fp="3,217,19.520.0,11.169.0,30.209.0,45.140.0"}
P.entries["npc:eva-sarkhoff"] = {n="Eva Sarkhoff",s="Eva Sarkhoff ist das spektrale Überbleibsel der ehemaligen Obermagd des Hauses Barov, die zusammen mit ihrem Ehemann Lucien unmittelbar vor den Schrecken von Scholomance verweilt. Während des Falls von Darrowehr vom Schlächter gefoltert und ermordet, sucht ihr Geist nach mutigen Sterblichen, um ihren Tod zu rächen und ihre verfluchten sterblichen Überreste zu vernichten.",h="Eva Sarkhoff ist das spektrale Überbleibsel der ehemaligen Obermagd des Hauses Barov, die zusammen mit ihrem...",kw={"barov","darrowehr","kult der verdammten","eva sarkhoff","krastinov","lucien sarkhoff","scholomance","der schlächter"},ang={["class:Priest"]="Die anhaltende Pein von Eva und Lucien mitzuerleben, ist eine deutliche Mahnung an die Grausamkeit der Geißel, die heilige Praktizierende dazu aufruft, ihren rastlosen Seelen Frieden zu schenken und die üble Magie zu läutern, die sie bindet.",["race:Human"]="Eva und ihr Ehemann repräsentieren die einfachen Bediensteten von Lordaeron, die von ihrer eigenen korrupten Aristokratie verraten wurden, als das Haus Barov Darrowehr an Kel'Thuzad verkaufte."},sec={{t="Der Fall des Hauses Barov",b="Eva diente der wohlhabenden Familie Barov jahrzehntelang als Obermagd und kümmerte sich zusammen mit ihrem Ehemann Lucien, dem Butler der Familie, um die weitläufige Festung Darrowehr. Als die Barovs von zunehmender Paranoia über ihre sterbliche Vergänglichkeit und ihren immensen Reichtum erfasst wurden, schlossen sie einen verhängnisvollen Pakt mit Kel'Thuzad. Das Anwesen wurde nach und nach dem aufkeimenden Kult der Verdammten überlassen, wodurch der prächtige Wohnsitz in Scholomance verwandelt wurde – eine geheime Akademie der Nekromantie. Eva und Lucien versteckten sich sechs Monate lang in den Gängen der Festung, suchten nach Nahrung und sahen mit an, wie Kultisten und Monstrositäten unaufhaltsam ihre Heimat übernahmen."},{t="Das Skalpell des Schlächters",b="Unweigerlich von der Geißel entdeckt, wurden Eva und Lucien in die Obhut von Doctor Theolen Krastinov übergeben, bekannt als der Schlächter. Krastinov unterzog die beiden wochenlangen, qualvollen Experimenten und nutzte dunkle Magie, um ihr Leben weit über die Grenze der sterblichen Belastbarkeit hinaus zu verlängern. Selbst nach ihrem Tod wurden ihre Leichen an Ghule verfüttert, während ihre rastlosen Geister an Darrowehr gekettet blieben, wo Eva nun vorbeiziehende Abenteurer anfleht, Krastinov zu erschlagen und ihre sterblichen Überreste zu verbrennen."}},faq={{q="Wer war Eva Sarkhoff vor ihrem Tod?",a="Eva Sarkhoff war die Obermagd der Adelsfamilie Barov und lebte sowie arbeitete jahrzehntelang in der Festung Darrowehr, an der Seite ihres Ehemanns Lucien, der als Butler diente.",al={"eva sarkhoff hintergrundgeschichte","wer ist eva sarkhoff","eva lore"}},{q="Wie ist Eva gestorben?",a="Nachdem sie sich monatelang vor dem Kult der Verdammten versteckt hatten, wurden Eva und Lucien entdeckt und Doctor Theolen Krastinov übergeben. Krastinov folterte sie wochenlang unbarmherzig und hielt sie mit dunkler Magie am Leben, bis sie schließlich starben und ihre Leichen an Ghule verfüttert wurden.",al={"wie ist eva sarkhoff gestorben","eva sarkhoff tod","wer tötete eva"}},{q="Warum ist Evas Geist noch immer in Darrowehr?",a="Evas Qualen waren so schrecklich und unnatürlich, dass ihr Geist an die sterbliche Ebene gebunden bleibt. Sie kann nicht in die Ewigkeit übergehen, bis Doctor Krastinov getötet und ihre physischen Überreste in Scholomance verbrannt sind.",al={"warum ist eva ein geist","eva geist","warum verweilt eva"}}},fp="12,310,23.585.0,21.483.1,37.171.0,16.272.0,40.211.0"}
P.entries["npc:executor-arren"] = {n="Exekutor Arren",s="Exekutor Arren ist ein hochrangiger Offizier der Verlassenen, der in Todesend stationiert ist. Er überwacht die unmittelbare Verteidigung und Konsolidierung der Siedlung, während neu erwachte Untote ihren Gräbern entsteigen. Arren koordiniert die örtlichen Feldzüge gegen geistlose Zombies der Geißel, wilde Bestien und die vordringenden Fanatiker des Scharlachroten Kreuzzugs.",h="Exekutor Arren ist ein hochrangiger Offizier der Verlassenen, der in Todesend stationiert ist.",kw={"todesend","exekutor arren","verlassene","nachtwebergrund","scharlachroter kreuzzug","sylvanas","tirisfal"},ang={["faction:Horde"]="Arrens Frontbefehle in Todesend begründen den ersten Stützpunkt der Horde im nördlichen Lordaeron und sichern das Überleben inmitten einer feindseligen Umgebung.",["race:Undead"]="Exekutor Arren ist einer der ersten Befehlshaber, denen Verlassene nach ihrem Erwachen in Tirisfal begegnen, und er vermittelt ihnen die ersten Eindrücke ihrer Pflichten unter der Dunklen Fürstin."},sec={{t="Kommandant von Todesend",b="Entschlossen vor der Kapelle in Todesend stehend, dient Exekutor Arren als wichtigste militärische Stimme für die heranwachsenden Verlassenen an ihrer Erweckungsstätte. Während die Verwalter in den Grüften die neu erweckten Untoten durch ihre Desorientierung leiten, richtet Arren deren Fokus nach außen auf das Überleben. Unter dem Banner von Königin Sylvanas Windläufer organisiert er örtliche Einsätze, um geistlose Zombies zu beseitigen, die die Dorfgrenzen bedrohen, und sichert so ein Territorium im Schatten des Falls von Lordaeron."},{t="Sicherung der Grenzlande",b="Todesend ist von Gefahren umgeben, die weitaus tödlicher sind als verwirrte Neulinge. Auf Arrens Befehl hin schlagen Kundschafter und Initianden gegen die bösartigen Spinnentiere zu, die den Nachtwebergrund bewohnen, und eliminieren gefährliche Raubtiere, die an den Waldrändern lauern. Indem er von jeder fähigen Hand entschlossenes Handeln fordert, prüft Arren die Standhaftigkeit der Neuankömmlinge und stellt sicher, dass nur diejenigen im Dienst der Dunklen Fürstin bleiben, die ihre zweite Chance auf eine Existenz verteidigen können."},{t="Die scharlachrote Bedrohung",b="Arrens größte strategische Sorge gilt dem Scharlachroten Kreuzzug. Die Fanatiker betrachten alle Untoten als Monstrositäten, die völlig ausgelöscht werden müssen, da sie nicht zwischen der Geißel und den Verlassenen mit freiem Willen unterscheiden können oder wollen. Arren organisiert gezielte Angriffe gegen Patrouillen des Scharlachroten Kreuzzugs, die in der Wildnis von Tirisfal lagern, fängt Kuriere ab und analysiert erbeutete Depeschen, um Todesend davor zu bewahren, im heiligen Feuer geläutert zu werden."}},faq={{q="Wer ist Exekutor Arren?",a="Exekutor Arren ist der kommandierende Militäroffizier, der Todesend in Tirisfal beaufsichtigt. Er formt die neu auferstandenen Verlassenen zu einer schlagkräftigen Streitmacht, um das Dorf zu verteidigen und das Umland zu sichern.",al={"arren aufgabe","wer ist arren","todesend exekutor"}},{q="Welchen Rang hat ein Exekutor bei den Verlassenen?",a="Exekutoren sind angesehene militärische und administrative Befehlshaber innerhalb der Hierarchie der Verlassenen. Sie leiten örtliche Garnisonen, führen Einsätze im Feld und setzen den Willen und das Gesetz von Königin Sylvanas Windläufer durch.",al={"exekutor titel","was ist ein exekutor","verlassene rang exekutor"}},{q="Warum schickt Arren Rekruten gegen die Zombies?",a="Die Zombies, die in der Nähe von Todesend herumstreunen, sind geistlose Überreste der Geißel, die zurückblieben, nachdem die Seuche Lordaeron verwüstet hatte. Arren lässt sie beseitigen, damit neu erwachte Untote beim Verlassen der Grüfte nicht zerrissen werden.",al={"warum zombies toeten","quest die verdammten","geistlose geissel"}},{q="Warum befindet sich der Scharlachrote Kreuzzug in Tirisfal?",a="Der Scharlachrote Kreuzzug ist eine radikale Menschenfraktion, die sich der Ausrottung aller Untoten verschrieben hat. Sie halten Außenposten in den Ruinen von Lordaeron und versuchen aktiv, die Verlassenen zu vernichten, da sie sie mit der Geißel gleichsetzen.",al={"scharlachroter kreuzzug tirisfal","warum kreuzzug hier","kreuzfahrer in todesend"}},{q="Was ist der Nachtwebergrund?",a="Der Nachtwebergrund ist eine von Spinnen verseuchte Höhle nördlich von Todesend. Arren weist Rekruten an, die aggressiven Spinnentiere zu beseitigen, um eine erhebliche lokale Gefahr auszuschalten und ihr kriegerisches Können unter Beweis zu stellen.",al={"spinnenhoehle todesend","nachtwebergrund","arren spinnenquest"}},{q="Wohin schickt Arren Rekruten, sobald sie seine Aufgaben erfüllt haben?",a="Sobald die unmittelbaren Bedrohungen für Todesend gebannt sind, schickt Arren fähige Rekruten nach Brill, damit sie sich bei Exekutor Zygand melden und die umfassenderen Bemühungen der Verlassenen in ganz Tirisfal unterstützen.",al={"nach todesend","wohin nach arren","der exekutor im feld"}}},fx={["610ddc26"]={q="Auf wessen Seite steht Exekutor Arren?",a="Exekutor Arren ist den Verlassenen und der Dunklen Fürstin, Lady Sylvanas Windläufer, absolut treu ergeben. Als örtlicher Militärkommandant in Todesend ist es seine Pflicht, das Startgebiet für seine neu erweckten Brüder und Schwestern zu sichern und jegliche Bedrohung für ihre junge Nation zu eliminieren, seien es hirnlose Zombies der Geißel, örtliche Bestien oder die Eiferer des Scharlachroten Kreuzzugs.",al={"arren loyalität","wem dient exekutor arren","arren fraktion"}},["25e599ca"]={q="Was will Exekutor Arren?",a="Arren strebt danach, die Kontrolle der Verlassenen über Todesend zu festigen und die Entschlossenheit der Neuauferstandenen zu prüfen. Er will, dass die hirnlosen Untoten vom Friedhof geräumt, die vordringenden Arachniden vernichtet und die nahe gelegenen Lager des Scharlachroten Kreuzzugs zerschlagen werden, damit frische Rekruten sicher nach Brill aufbrechen und sich der umfassenderen Verteidigung von Tirisfal anschließen können.",al={"was will arren","arren ziele","exekutor arren aufgabe"}},["3c8717b4"]={q="Warum ist Exekutor Arren in Todesend?",a="Arren ist in Todesend stationiert, um die anfängliche Verteidigung zu befehligen, wenn die neu befreiten Verlassenen zum ersten Mal aus ihren Gräbern treten. Ohne militärische Aufsicht könnten verwirrte Rekruten leicht von der hirnlosen Geißel überrannt werden, die durch die Hügel streift, oder Kundschaftern des Scharlachroten Kreuzzugs zum Opfer fallen, die den Umfang der Siedlung ausspähen.",al={"warum ist arren in todesend","arren ortsgrund","warum ist exekutor arren hier"}}},fp="14,332,23.510.0,24.454.0,18.435.1,22.220.0,44.211.0,49.217.0,46.218.0,27.196.0,58.189.0"}
P.entries["npc:executor-zygand"] = {n="Exekutor Zygand",s="Exekutor Zygand ist ein hochrangiger Kommandant der Verlassenen, der im Rathaus von Brill stationiert ist und die defensiven sowie militärischen Operationen im gesamten zentralen Tirisfal beaufsichtigt. Er untersteht direkt dem Oberkommando von Unterstadt und koordiniert die Säuberung von Streitkräften des Scharlachroten Kreuzzugs, die in das Territorium der Verlassenen vordringen.",h="Exekutor Zygand ist ein hochrangiger Kommandant der Verlassenen, der im Rathaus von Brill stationiert ist und...",kw={"arren","brill","todeswache","exekutor","maggot eye","scharlachroter kreuzzug","tirisfal","zygand"},ang={["faction:Horde"]="Reisende aus Kalimdor, die Tirisfal besuchen, sehen in Zygand die strukturierte, disziplinierte militärische Führung, die den Kampf der Verlassenen um die Sicherung Lordaerons vorantreibt.",["race:Undead"]="Für Verlassene, die Todesend verlassen, repräsentiert Exekutor Zygand die übergeordnete militärische Autorität von Unterstadt, die neue Bürger im aktiven Dienst gegen ihre erbittertsten Feinde willkommen heißt."},sec={{t="Kommando in Brill",b="Im administrativen Herzen von Brill koordiniert Exekutor Zygand die regionale Verteidigung für die Verlassenen nach ihrem anfänglichen Erwachen in Todesend. Als direkter Vorgesetzter von regionalen Offizieren wie Exekutor Arren und Feldposten wie Todeswache Linnea bündelt Zygand die Berichte der Späher und entsendet fähige Rekruten, um die Grenzen von Lordaeron vor Übergriffen zu schützen."},{t="Der Krieg gegen den Kreuzzug",b="Zygands militärisches Hauptaugenmerk gilt der fanatischen Präsenz des Scharlachroten Kreuzzugs, der Außenposten in ganz Tirisfal heimsucht. Unter seiner Führung werden Agenten systematisch entsandt, um Späher, Lager und Vorposten des Kreuzzugs anzugreifen, damit die Eiferer niemals genügend Stärke sammeln können, um die Zugänge nach Unterstadt zu bedrohen."}},faq={{q="Wer ist Exekutor Zygand?",a="Exekutor Zygand ist ein hochrangiger Offizier der Verlassenen, der von Brill in Tirisfal aus operiert. Er befehligt lokale Garnisonen der Todeswache, empfängt taktische Berichte von rangniederen Offizieren und leitet militärische Kampagnen gegen örtliche Bedrohungen.",al={"zygand","wer ist exekutor zygand","zygand rolle"}},{q="Wo finde ich Exekutor Zygand?",a="Er befindet sich im oder nahe dem Hauptrathaus von Brill, der zentralen Siedlung der Verlassenen in Tirisfal direkt nördlich von Unterstadt.",al={"zygand standort","wo ist zygand","exekutor zygand karte"}},{q="Was ist Zygands Hauptziel in Tirisfal?",a="Sein Hauptaugenmerk liegt auf der Organisation des regionalen Kriegs gegen den Scharlachroten Kreuzzug. Er überwacht die Bewegungen der Eiferer in ganz Tirisfal und erteilt Befehle, ihre Lager und ihre Führung zu zerschlagen, bevor sie gegen Unterstadt marschieren können.",al={"zygand questziel","warum kreuzzug bekämpfen","zygand aufgabe"}},{q="Wer untersteht Exekutor Zygand?",a="Zygand fungiert als Vorgesetzter von Exekutor Arren, der die ersten Rekruten in Todesend anleitet, sowie von Feldposten wie Todeswache Linnea, die die Hauptkreuzung von Tirisfal patrouilliert.",al={"zygand untergebene","wer dient zygand","arren vorgesetzter"}},{q="Befasst sich Exekutor Zygand mit Bedrohungen durch abtrünnige Untote?",a="Ja. Neben dem Kampf gegen den Scharlachroten Kreuzzug setzt Zygand regionale Kopfgelder aus, um wilde Untote und gefährliche abtrünnige Aasfresser wie den leichenstehlenden Gnoll Maggot Eye zu eliminieren, die das Reisen durch die Lichtungen gefährden.",al={"maggot eye","zygand kopfgelder","gesucht-quests"}},{q="Welchen Rang bekleidet ein „Exekutor“ bei den Verlassenen?",a="Ein Exekutor dient als regionaler Verwalter und militärischer Befehlshaber innerhalb der Hierarchie der Verlassenen. Sie verwalten Siedlungen, befehligen lokale Einheiten der Todeswache und setzen die Herrschaft von Königin Sylvanas in den umkämpften Regionen Lordaerons durch.",al={"was ist ein exekutor","rang exekutor","verlassene exekutor"}}},fx={["1dc7a0d0"]={q="Auf wessen Seite steht Exekutor Zygand?",a="Exekutor Zygand ist den Verlassenen und Lady Sylvanas Windläufer vollkommen ergeben. Als Militäroffizier in Brill dient er der Unterstadt, indem er die örtliche Verteidigung koordiniert, Todeswachen dirigiert und strategische Angriffe organisiert, um Tirisfal gegen die unerbittlichen Feinde der Verlassenen zu sichern.",al={"zygand fraktion","wem dient zygand","exekutor zygand seite"}},["673b7cce"]={q="Warum ist Exekutor Zygand in Brill stationiert?",a="Zygand ist in Brill stationiert, weil die Siedlung als wichtigste militärische Bastion der Verlassenen direkt nördlich der Unterstadt dient. Von hier aus überwacht er kritische Bedrohungen in ganz Tirisfal, leitet Frontpatrouillen und setzt erfahrene Kämpfer ein, um lebenswichtige Versorgungswege und Grenzen zu sichern.",al={"warum ist zygand hier","zygand brill aufgabe","warum ist exekutor zygand in brill"}}},fp="15,297,16.392.0,22.341.0,23.236.0,33.146.0,46.239.0,31.198.0,49.226.0,53.231.0"}
P.entries["npc:falfindel-waywarder"] = {n="Falfindel Wegeshut",s="Falfindel Wegeshut ist ein Nachtelfendruide, der in Thalanaar stationiert ist, dem Außenposten, der die Grenze zwischen Feralas und den Tausend Nadeln bewacht. Von diesem Grenzwachposten aus arbeitet er daran, verdorbene Länder zu heilen und die südliche Wildnis von Kalimdor zu schützen. Reisende, die aus dem Steinkrallengebirge oder dem Brachland herabwandern, treffen ihn oft auf der Suche nach Hilfe an, um das Gleichgewicht der Natur wiederherzustellen.",h="Falfindel Wegeshut ist ein Nachtelfendruide, der in Thalanaar stationiert ist, dem Außenposten, der die...",kw={"das verbrannte tal","falfindel","feralas","steinkrallengebirge","thalanaar","tausend nadeln","wegeshut","irrwische"},ang={["class:Druid"]="Seine Bemühungen, Waldgeister und Irrwische auszusenden, um die verbrannte Erde des Steinkrallengebirges zu heilen, spiegeln die heilige druidische Mission der Wiederherstellung wider.",["faction:Alliance"]="Für Reisende der Allianz, die den weiten Weg aus dem Brachland oder dem Steinkrallengebirge nach Süden antreten, bieten Falfindel und die Wache von Thalanaar eine einladende Zuflucht.",["race:NightElf"]="Falfindel verkörpert die Wachsamkeit Eures Volkes an den Grenzen von Kalimdor, stets bestrebt, die Narben der Natur zu heilen und vor den eindringenden Gefahren der Wildnis zu schützen."},sec={{t="Wache an der Südgrenze",b="Thalanaar markiert das Tor, an dem die üppigen Wälder von Feralas in die hoch aufragenden Mesas und trockenen Salzebenen von Tausend Nadeln abfallen. Falfindel Wegeshut hält Wache an diesem abgelegenen Außenposten und begrüßt müde Reisende, die sich weit über den Kontinent gewagt haben. Umgeben von natürlicher Pracht und lauernden Gefahren dient er als Ansprechpartner für die Nachtelfen, die sowohl lokale Bedrohungen als auch weiter reichende Umweltkatastrophen in ganz Kalimdor überwachen wollen."},{t="Heilung des Verbrannten Tals",b="Trotz seines südlichen Postens sorgt sich Falfindel nach wie vor zutiefst um die Verwüstung weit im Norden im Steinkrallengebirge. Das verbrannte Tal, ruiniert durch dunkle Zauberei und feurige Zerstörung, steht wie eine schmerzhafte Narbe in der Wildnis von Kalimdor. Wenn Abenteurer Falfindel Hilfe bringen, um bei dessen Genesung zu helfen, ruft er die Geister des Waldes an. Er beschwört Schwärme von Irrwischen herbei und weist sie an, nach Norden ins Steinkrallengebirge zu eilen, um mit der Heilung der verbrannten Erde zu beginnen."},{t="Ein wachsames Auge auf die Borstennacken und das Ödland",b="Neben der Koordination der Wiederherstellungsbemühungen behält Falfindel die umliegende Region genau im Auge, einschließlich der Bauten der Borstennacken im Kral der Klingenhauer. Durch das Prüfen geborgener Tagebücher und das Sammeln von Informationen über die Anführer der Borstennacken stellt Falfindel sicher, dass die Allianz die wachsenden Gefahren versteht, die die Pässe zwischen Feralas und den zentralen Wüsten bedrohen."}},faq={{q="Wo befindet sich Falfindel Wegeshut?",a="Falfindel ist in Thalanaar stationiert, dem Außenposten der Nachtelfen an der Grenze zwischen Feralas und Tausend Nadeln.",al={"falfindel standort","wo ist falfindel","falfindel wegeshut karte"}},{q="Welche Rolle hat Falfindel in Thalanaar?",a="Er dient als Druide und Führer am Außenposten, überwacht regionale Bedrohungen wie die Borstennacken in Tausend Nadeln und koordiniert die Wiederherstellungsbemühungen für zerstörte Länder wie Das verbrannte Tal.",al={"was macht falfindel","falfindel zweck","falfindel quests"}},{q="Wie hilft Falfindel dem Verbrannten Tal?",a="Wenn Abenteurer bei den Bemühungen helfen, das Verbrannte Tal zurückzugewinnen, kanalisiert Falfindel eine Beschwörung, um Waldirrwische herbeizurufen, und entsendet sie nach Norden ins Steinkrallengebirge, um das verseuchte Land zu heilen.",al={"falfindel steinkrallengebirge","falfindel das verbrannte tal","reclaiming the charred vale falfindel"}},{q="Warum interessiert sich Falfindel für den Kral der Klingenhauer?",a="Er studiert die Bedrohung, die von den Borstennacken des Krals ausgeht, und untersucht Gegenstände wie Einbraues Tagebuch, um den Einfluss ihrer Anführer wie The Crone of the Kraul zu verfolgen.",al={"the crone of the kraul falfindel","einbraues tagebuch falfindel","falfindel borstennacken"}},{q="Ist Falfindel der Allianz angeschlossen oder neutral?",a="Falfindel ist ein Nachtelfendruide, der mit Darnassus und der Allianz verbündet ist. Reisende der Horde, die sich Thalanaar nähern, werden den Außenposten feindselig vorfinden.",al={"ist falfindel allianz","falfindel fraktion"}},{q="Was sagt Falfindel zu Reisenden?",a="Er begrüßt freundliche Besucher herzlich, indem er ihre lange Reise anerkennt und bemerkt: 'Ihr seht aus, als wärt Ihr von weit her gereist.'",al={"falfindel begruessungstext","falfindel zitat"}}},fx={["444437e8"]={q="Wer ist Falfindel Wegeshut?",a="Falfindel Wegeshut ist ein Nachtelf, der am Außenposten Thalanaar stationiert ist, der an Feralas und die Tausend Nadeln grenzt. Im Einklang mit der Gesundheit des Landes und den Gefahren, denen die südlichen Regionen Kalimdors ausgesetzt sind, wacht er über Reisende und arbeitet eng mit anderen Nachtelfen zusammen, um aufkommenden Bedrohungen für die Wildnis entgegenzuwirken.",al={"wer ist falfindel","falfindel wegeshut lore","wer ist falfindel wegeshut"}},e0cb4d91={q="Was will Falfindel Wegeshut?",a="Falfindel möchte die fragile Wildnis schützen und bei der Heilung verwüsteter Landstriche helfen. Er weist Verbündete an, Waldgeister zu beschwören, um das verbrannte Tal wiederzubeleben, koordiniert Lieferungen, um die örtlichen Außenposten versorgt zu halten, und versucht, die korrumpierte Stacheleber-Matriarchin zu eliminieren, die im Kral der Klingenhauer lauert.",al={"was will falfindel","falfindel ziele","falfindel quest aufgabe"}},["2bf92e29"]={q="Warum ist Falfindel Wegeshut hier?",a="Falfindel dient als Druide und Führer in Thalanaar und bewacht den Übergang zwischen den Tausend Nadeln und Feralas. Von diesem abgelegenen Außenposten aus überwacht er die wachsende Bedrohung durch die Stacheleber, die aus dem Brachland vordringen, und koordiniert die Bemühungen, das Gleichgewicht in den verseuchten Wäldern in ganz Zentral- und Südkalimdor wiederherzustellen.",al={"warum ist falfindel hier","warum ist falfindel in thalanaar","falfindel aufgabe"}}},fp="19,367,28.456.0,24.471.0,36.366.0,37.119.0,38.192.0,41.185.0,46.172.0,50.139.0,37.132.0"}
P.entries["npc:falla-sagewind"] = {n="Falla Weisenwind",s="Falla Weisenwind ist eine zurückgezogen lebende Mystikerin der Tauren, die hoch auf einer felsigen Spitze über dem zentralen Brachland weilt. Zwischen dem Wegekreuz und Der blühenden Oase stationiert, erforscht sie die natürlichen und mystischen Anomalien, die das umliegende Land plagen. Abenteurer, die der verdorbenen Verderbnis nachgehen, die aus den nahegelegenen Höhlen des Wehklagens sickert, suchen oft ihren Rat.",h="Falla Weisenwind ist eine zurückgezogen lebende Mystikerin der Tauren, die hoch auf einer felsigen Spitze...",kw={"brachland","das wegekreuz","falla","leuchtender splitter","die blühende oase","nightmares","weisenwind","tauren","die höhlen des wehklagens"},ang={["class:Druid"]="Druiden werden Falla als eine entscheidende Verbündete erkennen, wenn es darum geht, dem tragischen Abstieg von Naralex und den Druids of the Fang in den Höhlen des Wehklagens nachzugehen.",["faction:Horde"]="Falla steht der Horde bei, indem sie seltsame Omen und verderbte Relikte deutet, die von Spähern aus den umkämpften Savannen des Brachlands zurückgebracht werden.",["race:Tauren"]="Falla Weisenwind verkörpert die Pflicht der Tauren zur stillen Behütung der Erde, indem sie von hohen Orten aus über spirituelle Fäulnis wacht, während ihre Brüder die Straßen darunter verteidigen."},sec={{t="Wächterin der Hohen Klippe",b="Falla Weisenwind schlägt ihr Lager weit über dem Staub und dem Treiben der Pfade des Brachlands auf, gelegen auf einem abgelegenen Gipfel direkt südwestlich des Wegekreuzes. Von diesem Aussichtspunkt aus wacht sie feierlich über die empfindlichen Savannen unter ihr und beobachtet die plötzlichen Verhaltensänderungen der Tierwelt sowie die vordringende Verderbnis, die aus den unterirdischen Klüften der Höhlen des Wehklagens aufsteigt. Ihre einsame Wacht trennt sie vom alltäglichen Handel des Wegekreuzes und macht sie zu einer aufmerksamen Einsiedlerin, die auf die Geister und die stummen Wunden des Landes eingestimmt ist."},{t="Der erwachende Albtraum",b="Wenn den mutierten Bestien des Brachlands seltsame, pulsierende Splitter entrissen werden, weist man weise Reisende an, die Felsen zu Falla hinaufzusteigen. Sie hilft bei der Deutung der verdrehten Magien, die die natürliche Ordnung der Oasen auflösen. Da sie die düsteren Zeichen erkennt, dass sich Der Smaragdgrüne Traum unter der Erde zum Schlechten wendet, schickt sie Helden zu den weisen Druiden des Zirkels des Cenarius, um tiefere Antworten über den Albtraum zu erhalten, der in der Region Wurzeln schlägt."}},faq={{q="Wer ist Falla Weisenwind?",a="Falla Weisenwind ist eine einsame Mystikerin der Tauren, die auf einer hohen Klippe südwestlich des Wegekreuzes im Brachland lebt. Sie wacht über das Land und hilft Reisenden, die die seltsamen magischen Leiden verstehen wollen, die sich in der Region ausbreiten.",al={"wer ist falla weisenwind","wer ist falla","falla weisenwind lore"}},{q="Wo kann ich Falla Weisenwind finden?",a="Sie befindet sich auf einer steilen Bergspitze direkt südwestlich des Wegekreuzes und nördlich Der blühenden Oase. Um ihr Lager zu erreichen, muss man sich über die felsigen Pfade hinaufwinden, die von der umliegenden Savanne aufsteigen.",al={"falla weisenwind standort","wo ist falla","wie man zu falla weisenwind gelangt"}},{q="Warum interessiert sich Falla Weisenwind für die Höhlen des Wehklagens?",a="Falla hilft dabei, die seltsame Magie eines Leuchtenden Splitters zu untersuchen, der aus den Höhlen des Wehklagens geborgen wurde. Sie verweist Reisende für weiteren Rat an erfahrene Druiden.",al={"falla die höhlen des wehklagens","warum kümmert sich falla um die oase","falla leuchtender splitter"}},{q="Gehört Falla Weisenwind einem Clan oder einer Familie an?",a="Sie teilt den Nachnamen Weisenwind mit anderen Tauren, aber eine familiäre Verbindung ist nicht bestätigt.",al={"weisenwind-familie","wer sind die weisenwinds","ist falla mit tahu verwandt"}},{q="Welche Quests beinhalten Falla Weisenwind?",a="Falla ist an den Untersuchungen rund um die Höhlen des Wehklagens beteiligt, insbesondere beim Abgeben oder Fortführen von Quests wie The Glowing Shard und In Nightmares, die sich mit dem finsteren Traum befassen, der die örtlichen Oasen verdirbt.",al={"falla weisenwind quests","quests von falla","in nightmares quest"}},{q="Können Spieler der Allianz mit Falla Weisenwind interagieren?",a="Ja. Falla hilft Reisenden beider Fraktionen mit dem Leuchtenden Splitter, indem sie Abenteurer der Allianz zu Mathrengyl Bärenfährte in Darnassus und Abenteurer der Horde zu Hamuul Runetotem in Donnerfels schickt.",al={"ist falla weisenwind feindselig","falla allianzfreundlich"}}},fx={["53e3505a"]={q="Auf wessen Seite steht Falla Weisenwind?",a="Falla Weisenwind ist eine Tauren, die kein Banner einer Fraktion trägt. In den rauen Höhen des Brachlands stationiert, hilft sie Reisenden sowohl der Horde als auch der Allianz, die die unnatürlichen Verderbnisse untersuchen, die sich von den Höhlen des Wehklagens aus ausbreiten, und unterstützt diejenigen, die daran arbeiten, das Land zu reinigen.",al={"falla weisenwind fraktion","ist falla weisenwind bei der horde","wem dient falla weisenwind"}},["709098cb"]={q="Was will Falla Weisenwind?",a="Falla Weisenwind versucht, die wachsende Verderbnis zu verstehen und zu bekämpfen, die aus den Höhlen des Wehklagens sickert. Wenn Abenteurer ihr seltsame Relikte bringen, wie etwa glühende Scherben, die von den Kreaturen im Inneren stammen, arbeitet sie daran, den Albtraum aufzudecken, der in den unterirdischen Quellen Wurzeln schlägt.",al={"falla weisenwind ziele","was will falla","falla weisenwind aufgabe"}},["26262d64"]={q="Warum ist Falla Weisenwind hier?",a="Falla Weisenwind hält Wache auf einem Bergrücken südwestlich des Wegekreuzes, von wo aus sie die blühende Oase und den nahe gelegenen Eingang zu den Höhlen des Wehklagens überblickt. Von diesem erhöhten Aussichtspunkt aus überwacht sie die Verderbnis des Landes und leitet Reisende an, die dunkle Relikte finden, die mit den gestörten Träumern in der Tiefe in Verbindung stehen.",al={"warum ist falla weisenwind im brachland","warum ist falla auf dem berg"}}},fp="14,352,24.528.0,20.438.1,22.242.0,32.209.0,56.171.0,53.89.0,35.214.0,50.194.0"}
P.entries["npc:fallen-hero-of-the-horde"] = {n="Gefallener Held der Horde",s="Der Gefallene Held der Horde ist der verweilende Geist eines Orc-Kriegers, der an der südlichen Straße aus den Sümpfen des Elends Wache hält. Gebunden an Reue und Schande, warnt er vorbeiziehende Reisende vor den Schrecken, die sie in den Verwüsteten Landen erwarten, und sucht nach Helden, die bereit sind, seine gequälten Soldaten aus dämonischer Knechtschaft zu befreien.",h="Der Gefallene Held der Horde ist der verweilende Geist eines Orc-Kriegers, der an der südlichen Straße aus...",kw={"allistarj","gefallener held der horde","grol the destroyer","lieutenant kirith","razelikh the defiler","sevine","steine der bindung","swamp talker"},ang={["class:Warrior"]="Als gefallener Krieger von hohem Ansehen berührt seine spektrale Verbundenheit besonders kämpferische Abenteurer, die den Schmerz verstehen, zu überleben, während die eigenen Kameraden gefallen sind.",["faction:Horde"]="Der Held verkörpert die Qual eines Kriegers, dessen Ehre durch dämonische Grausamkeit geraubt wurde, und appelliert an Abenteurer der Horde, seine verlorene Truppe zu rächen und den Makel der Niederlage von ihrem Erbe zu tilgen."},sec={{t="Ein tragisches Kommando",b="Zu Lebzeiten war dieser Krieger ein gefeierter Champion, der mit einem handverlesenen Regiment von Soldaten entsandt wurde, um die Verwüsteten Lande zu erkunden und über die Präsenz der Brennenden Legion zu berichten. Seine Depesche kam nie an; der nach Norden gen Steinard geschickte Bote geriet in einen Hinterhalt und wurde vom Swamp Talker und seinen Murlocs erschlagen. Ohne Befehle oder Verstärkung gestrandet, marschierte der Kommandant mit seinen Soldaten schließlich nach Süden in die zerrütteten Einöden, um sich der wachsenden Finsternis zu stellen. Es war eine verhängnisvolle Fehleinschätzung. Von dämonischen Kräften überwältigt, wurde seine Armee zersprengt, gefangen genommen und durch die Hand des Schreckenslords Razelikh the Defiler grauenhafter Folter ausgesetzt."},{t="Der Preis des Versagens",b="Gemeinsam mit seinem Leutnant Kirith gefangen genommen, ertrug der Kommandant brutale Folter in der Schlangenschlinge, während ihre Peiniger seinen überlebenden Männern die Seelen entrissen. Nachdem er entkommen war, nur um seinen tödlichen Wunden nahe der Sumpfgrenze zu erliegen, bleibt der Geist des Helden an die Schwelle der Verwüsteten Lande gefesselt. Seine Soldaten erlitten ein noch finstereres Schicksal: Ihre seelenlosen Hüllen wurden an mystische Steine gebunden und dienten als unsterbliche Knechte, aufgeteilt zwischen Razelikh und seinen Leutnants – Archmage Allistarj, Lady Sevine und Grol the Destroyer. Bis ihre seelenbindenden Steine zerschlagen und ihre Qualen beendet sind, kann sein rastloser Geist keinen Frieden finden."}},faq={{q="Wer war der Gefallene Held zu Lebzeiten?",a="Er war ein erfahrener Orc-Krieger, der auserwählt wurde, eine Aufklärungstruppe in die Verwüsteten Lande zu führen, um die dämonische Bedrohung einzuschätzen. Er starb an schweren Wunden, nachdem er der Folter durch Razelikh the Defiler entkommen war, wodurch sein Geist an der Straße gestrandet blieb, die aus den Sümpfen des Elends führt.",al={"identität des gefallenen helden","name des gefallenen helden","wer ist der gefallene held"}},{q="Warum spukt er an der Grenze der Verwüsteten Lande?",a="Er ist an die Schande gebunden, sein Regiment verloren und seinen Auftrag verfehlt zu haben. Er weigert sich weiterzuziehen, bis mutige Abenteurer nach Süden vordringen, um die Steine der Bindung zu zerstören, die seine Soldaten in ewiger Knechtschaft der Brennenden Legion halten.",al={"warum ist er ein geist","gefallener held geist","warum ist er hier"}},{q="Was geschah mit den Befehlen, die er nach Steinard sandte?",a="Der Späher, der seinen dringenden Bericht zurück zum Außenposten Steinard tragen sollte, wurde im Sumpf von Murlocs unter der Führung des Swamp Talkers überfallen und getötet. Da der Bericht verloren ging, traf nie Verstärkung ein, was den Helden dazu veranlasste, allein in die Verwüsteten Lande vorzurücken.",al={"verlorene befehle","was geschah mit seinen befehlen","swamp talker bote"}},{q="Was geschah mit seinem Leutnant Kirith?",a="Leutnant Kirith erlitt dämonische Experimente in der Schlangenschlinge. Seine Seele wurde verzerrt und verdreht, was seine physische Gestalt in einen monströsen Teufelsjäger verwandelte, der in den Tiefen der Höhle lauert.",al={"leutnant kirith","wer ist kirith","was geschah mit kirith"}},{q="Warum sind seine Soldaten unverwundbar?",a="Razelikh und seine Leutnants trennten die Seelen der gefangenen Soldaten von ihrem Fleisch. Ohne Seele können ihre physischen Körper nicht wahrhaftig sterben. Sie können nur befreit werden, wenn ihre Körper bis kurz vor den Zerfall geschlagen werden, wodurch die seelenbindenden Steine in der Nähe kurzzeitig anfällig für die Zerstörung werden.",al={"unverwundbare soldaten","steine der bindung","diener von razelikh"}}},fp="24,325,16.645.0,20.641.1,32.284.0,51.232.0,47.259.0,40.194.1,34.293.1"}
P.entries["npc:fandral-staghelm"] = {n="Fandral Hirschhaupt",s="Erzdruide Fandral Hirschhaupt führt die Druiden des Zirkels des Cenarius von der Enklave des Cenarius in Darnassus aus an. Nachdem er an die Macht gelangte, als Malfurion Sturmgrimm im Smaragdgrünen Traum verschwand, setzte er sich für die Pflanzung des neuen Weltenbaums Teldrassil ein. Stolz, schroff und unerbittlich ehrgeizig tritt Fandral für ein aggressives Wiedererstarken der Kaldorei ein, was ihn regelmäßig in Konflikt mit Hohepriesterin Tyrande Wisperwind bringt.",h="Erzdruide Fandral Hirschhaupt führt die Druiden des Zirkels des Cenarius von der Enklave des Cenarius in...",kw={"zirkel des cenarius","darnassus","fandral","malfurion","rajaxx","treibsand","staghelm","teldrassil","valstann"},ang={["class:Druid"]="Staghelm befehligt die Darnassischen Druiden und drängt den Zirkel des Cenarius zu direkter weltlicher Autorität, während er mit den traditionellen Lehren des schlafenden Malfurion Sturmgrimm im Konflikt steht.",["faction:Alliance"]="Obwohl Teldrassil als Bastion der Allianz im nördlichen Kalimdor dient, betrachtet Staghelm die jüngeren Völker mit kaum verhohlener Verachtung und duldet ihre Anwesenheit nur, soweit politische Zweckmäßigkeit es verlangt.",["race:NightElf"]="Als einer der primären Anführer von Darnassus verkörpert Fandral den Stolz und den Zorn der Kaldorei und treibt die Besiedlung von Teldrassil voran, während gewöhnliche Bürger die Kluft zwischen seiner Enklave und dem Tempel des Mondes spüren."},sec={{t="Architekt von Teldrassil",b="Nach dem Dritten Krieg und dem Opfer von Nordrassil auf dem Gipfel des Hyjal verloren die Nachtelfen ihre Unsterblichkeit und ihr heiliges Refugium. Während Malfurion Sturmgrimm zu Geduld mahnte und vor Eitelkeit warnte, setzte sich Fandral für die kühne Erschaffung eines neuen Weltenbaums vor der Küste von Kalimdor ein. Als Malfurion daraufhin im Smaragdgrünen Traum ins Koma fiel, ergriff Fandral die Initiative und führte die Druiden dabei an, Teldrassil emporwachsen zu lassen. Er sah in dem kolossalen Geäst ein Monument der Ausdauer der Kaldorei und ein Gefäß zur Wiederherstellung ihrer verlorenen Vormachtstellung, obwohl die Drachenaspekte dem ungenehmigten Unterfangen ausdrücklich ihren Segen verweigerten."},{t="Tragödie im Treibsand",b="Ein Jahrtausend vor dem Ersten Krieg diente Fandral während des Krieges der Sandstürme als Feldkommandant der Kaldorei in Silithus. Bei den insektoiden Qiraji als „Kar'sis“ – die Hand der Erde – bekannt, hielt er an der Seite seines geliebten einzigen Sohnes Valstann die Frontlinie. Die Hingabe Fandrals ausnutzend, inszenierte der Qiraji-General Rajaxx ein Scheinmanöver gegen den Südwindposten, nahm Valstann gefangen und richtete ihn grausam direkt vor den Augen des entsetzten Erzdruiden hin. Dieser Verlust brach Fandrals Geist, löste einen verheerenden Rückzug aus und zementierte einen tiefen, bitteren Hass auf den Schwarm, der bis heute in sein hochmütiges Auftreten eingebrannt ist."},{t="Rivalität und Hybris",b="Inmitten der marmornen Äste von Darnassus lenkt Fandral die Belange der Kaldorei mit hochmütiger, unnachgiebiger Hand. Anders als Hohepriesterin Tyrande Wisperwind, die spirituelle Bewahrung und vorsichtige Diplomatie bevorzugt, betrachtet Fandral militärische Expansion und entschlossene Stärke als unverzichtbar für das Überleben ihres Volkes."}},faq={{q="Wer ist Fandral Hirschhaupt?",a="Fandral Hirschhaupt ist der amtierende Erzdruide des Zirkels des Cenarius in Darnassus, der die Druiden der Kaldorei in der Abwesenheit von Malfurion Sturmgrimm leitet. Bekannt für sein feuriges Temperament und seine imperialen Ambitionen, ist er der maßgebliche Visionär hinter der Erschaffung von Teldrassil.",al={"fandral lore","wer ist der erzdruide","erzdruide von darnassus"}},{q="Warum versteht sich Fandral nicht mit Tyrande?",a="Fandral tritt für ein militärisches Wiedererstarken der Kaldorei, aggressive Expansion und die Rückerlangung der verlorenen Unsterblichkeit ein. Tyrande Wisperwind verfolgt eine besonnene spirituelle Führung durch Elune. Ihre konkurrierenden Visionen für die Zukunft der Nachtelfen nach dem Hyjal sorgen in Darnassus für heftige politische Reibungen.",al={"fandral und tyrande","warum sind druiden und priesterinnen uneins","staghelm gegen whisperwind"}},{q="Warum wurde Teldrassil gegen Malfurions Willen gepflanzt?",a="Malfurion glaubte, dass das Pflanzen eines Ersatzes für Nordrassil ein Akt der Hybris sei, den die Natur nicht dulden würde. Als Malfurion in sein Koma fiel, scharte Fandral die verbliebenen Druiden um sich, um Teldrassil dennoch zu pflanzen, mit dem Ziel, die Macht der Kaldorei wiederherzustellen und ihre verlorene Unsterblichkeit zurückzuerlangen.",al={"wer erschuf teldrassil","warum pflanzte fandral teldrassil","ursprung von teldrassil"}},{q="Was geschah mit Fandrals Sohn?",a="Während des Krieges der Sandstürme in Silithus wurde Fandrals Sohn Valstann in einen Hinterhalt am Südwindposten gelockt. Der Qiraji-General Rajaxx nahm Valstann gefangen und tötete ihn vor den Augen von Fandral, was den Erzdruiden von Trauer gebrochen und dauerhaft verbittert zurückließ.",al={"fandral sohn","wer war valstann","valstann staghelm"}},{q="Wo ist Fandral Hirschhaupt zu finden?",a="Fandral steht auf den Höhen der Enklave des Cenarius in Darnassus, umgeben von seinen loyalen Druiden und den zu beaufsichtigenden Angelegenheiten der Hauptstadt der Kaldorei.",al={"wo ist fandral","fandral aufenthaltsort","anführer der enklave des cenarius"}}},fx={d5bab569={q="Auf wessen Seite steht Fandral Hirschhaupt?",a="Fandral ist der Erz-Druide von Darnassus und ein Anführer innerhalb des Zirkels des Cenarius, der sich für die Kaldorei und die Allianz einsetzt. Seine Loyalität ist jedoch stark nationalistisch geprägt. Anstatt sich demütig der traditionellen Vorsicht der Ältesten des Zirkels oder der Priesterschaft von Elune zu unterwerfen, handelt Fandral streng nach dem, was er als kühnes, militaristisches Interesse des Volkes der Nachtelfen wahrnimmt.",al={"fandral hirschhaupt fraktion","wem dient fandral","fandral loyalität"}},adee2909={q="Was will Fandral Hirschhaupt?",a="Fandral wünscht sich die Wiederherstellung der Macht, der Unsterblichkeit und der territorialen Vorherrschaft der Nachtelfen. Frustriert von jahrhundertelanger passiver Isolation drängte er darauf, den Weltenbaum Teldrassil als Ersatz für Nordrassil zu pflanzen. Er stellt sich eine aggressive Nation der Kaldorei vor, die bereit ist, ihre Grenzen zu erobern, kühn durch Kalimdor zu expandieren und den verlorenen Ruhm und die Kraft ihrer alten Vergangenheit zurückzugewinnen.",al={"was ist das ziel von fandral hirschhaupt","fandral ambitionen","was will erz-druide hirschhaupt"}},["6d220bca"]={q="Warum ist Fandral Hirschhaupt in Darnassus?",a="Da Malfurion Sturmgrimm im Smaragdgrünen Traum gefangen und handlungsunfähig ist, trat Fandral als Erz-Druide an seine Stelle. Er regiert die Druiden des Zirkels des Cenarius von den Höhen der Enklave des Cenarius in Darnassus aus, herrscht an der Seite der Hohepriesterin Tyrande Wisperwind und lenkt aktiv die politische und magische Zukunft von Teldrassil.",al={"warum ist fandral in darnassus","fandral hirschhaupt standort grund","warum ist fandral hier"}},["53c16312"]={q="Warum ist Fandral Hirschhaupt berühmt?",a="Lange bevor er die Pflanzung von Teldrassil leitete, diente Fandral während des Krieges der wandelnden Dünen in Silithus als brillanter Feldkommandant der Kaldorei. Sein verheerendes taktisches Kommando gegen den insektenartigen Schwarm brachte ihm bei den Qiraji den Titel Kar'sis – die Hand der Erde – ein, die seine Wut auf dem Schlachtfeld fürchteten, bis sie die tragische Hinrichtung seines Sohnes orchestrierten.",al={"fandral berühmt","warum wird fandral gefürchtet","hand der erde fandral"}}},fp="16,417,23.647.0,29.638.0,18.306.0,24.261.0,43.290.0,54.286.0,31.269.0,36.135.0"}
P.entries["npc:farmer-furlbrow"] = {n="Bauer Brauenwirbel",s="Bauer Theodore Furlbrow ist ein vertriebener Kürbisbauer aus Westfall, der zusammen mit seiner Frau Verna auf der Straße nahe Jansens Hof gestrandet ist. Von der Bruderschaft der Defias aus ihrer Heimat vertrieben, versucht das Paar, seinen kaputten Wagen zu reparieren und in den Wald von Elwynn zu fliehen.",h="Bauer Theodore Furlbrow ist ein vertriebener Kürbisbauer aus Westfall, der zusammen mit seiner Frau Verna auf...",kw={"blanchy","defias","furlbrow","erbstück","jansen","kürbis","theodore","verna","wagen","uhr"},ang={["faction:Alliance"]="Theodore Furlbrows Notlage steht sinnbildlich für den vollständigen Zusammenbruch der zivilen Ordnung in Westfall, wo loyale Bürger des Königreichs ihre Heimat aufgeben müssen, da keine königlichen Soldaten zu ihrer Verteidigung bereitstehen."},sec={{t="Ein Leben auf einen Wagen gepackt",b="Theodore Furlbrow bewirtschaftete einst ein Kürbisfeld im nördlichen Westfall, doch die wachsende Welle des Verbrechens zwang ihn und seine Frau Verna dazu, alles aufzugeben, was sie besaßen. Sie rafften zusammen, was sie retten konnten, und brachen in Richtung der Sicherheit des Walds von Elwynn auf, wobei sie Nachbarn wie Bauer Saldean drängten, es ihnen gleichzutun. Auf der Straße nahe Jansens Hof brach jedoch das Unheil über sie herein, als ihr Wagen liegenblieb und sie schutzlos im Blickfeld von Banditen und wilden Bestien zurückließ. Während Verna sich um ihr geliebtes Pferd, die Grauschimmelstute Blanchy, kümmert, blickt Theodore mit wachsender Verzweiflung auf die Straße – verzweifelt bemüht, geschätzte Besitztümer wie die Taschenuhr wiederzuerlangen, die ihm Vernas Vater an ihrem Hochzeitstag schenkte, und in der Hoffnung, die Späherkuppe vor den herannahenden Banditen zu warnen."},{t="Beweise der Landenteignung",b="Als Furlbrow von seinem Hof floh, ließ er wichtige juristische Dokumente zurück, darunter die Besitzurkunde für sein Anwesen. Abenteurer, die die überrannten Höfe erkunden, entdecken diese zurückgelassenen Papiere oft und liefern damit handfeste Beweise dafür, wie die Bruderschaft der Defias ehrliche Arbeiter von ihrem Land vertrieb. Gryan Starkmantel und die Volksmiliz stützen sich auf solche Beweise, um das gesamte Ausmaß des Aufstands der Diebe in der Provinz zu erfassen."}},faq={{q="Wer ist Bauer Brauenwirbel?",a="Theodore Furlbrow ist ein vertriebener Kürbisbauer aus dem nördlichen Westfall. Er und seine Frau Verna wurden von der Bruderschaft der Defias von ihrem Hof vertrieben und sitzen derzeit neben ihrem kaputten Wagen nahe Jansens Hof fest.",al={"bauer brauenwirbel","theodore furlbrow","wer ist furlbrow"}},{q="Warum sitzt Bauer Brauenwirbel auf der Straße fest?",a="Auf der Flucht aus Westfall in die Sicherheit des Walds von Elwynn erlitt sein Wagen einen Achsbruch. Bis er den Wagen reparieren kann oder Hilfe findet, harrt er mit seiner Frau und ihrem alten Pferd Blanchy am Straßenrand aus.",al={"warum ist sein wagen kaputt","warum ist furlbrow auf der straße","kaputter karren westfall"}},{q="Welches Erbstück hat Bauer Brauenwirbel verloren?",a="Während ihrer überstürzten Flucht vom Hof ließ Theodore eine geschätzte Taschenuhr zurück, die ihm Vernas Vater an ihrem Hochzeitstag geschenkt hatte. Er bittet Reisende, die mutig genug sind, die von Banditen heimgesuchten Höfe zu betreten, sie ihm zurückzubringen.",al={"vergessene erbstück-uhr","furlbrow uhr","taschenuhr"}},{q="Hat Bauer Brauenwirbel Familie außerhalb von Westfall?",a="Theodore hat einen Bruder, der weit im Norden in Tarrens Mühle im Vorgebirge des Hügellands als Pferdeknecht arbeitet.",al={"furlbrow familie","furlbrow bruder"}}},fx={d2bcffbc={q="Auf wessen Seite steht Bauer Brauenwirbel?",a="Bauer Brauenwirbel ist ein gewöhnlicher Bauer aus Westfall, der dem Königreich Sturmwind und der Allianz treu ergeben ist. Er empfindet keine Liebe für The Defias Brotherhood, die sein Land beschlagnahmt und ihn vertrieben hat. Obwohl er verbittert über den Mangel an königlichem Schutz ist, wendet er sich dennoch an mitreisende Mitglieder der Allianz und die People's Militia, um Hilfe zu erhalten.",al={"bauer brauenwirbel fraktion","wen unterstützt brauenwirbel","ist brauenwirbel bei der allianz"}},["81475819"]={q="Was will Bauer Brauenwirbel?",a="Bauer Brauenwirbel möchte nichts weiter, als seinen kaputten Wagen zu reparieren und mit seiner Frau Verna und ihrem alten Pferd Blanchy aus Westfall zu entkommen. Da ihre Kürbisfarm von Banditen der Defias überrannt wurde, ist es seine Priorität, Vorräte zu sammeln, sein verlorenes Familienerbstück zurückzuerlangen und die gesetzlose Grenze hinter sich zu lassen.",al={"was braucht brauenwirbel","bauer brauenwirbel ziel","brauenwirbel absichten"}}},fp="15,260,24.743.0,24.424.1,23.227.0,44.214.0,39.239.0,54.108.0"}
P.entries["npc:farmer-saldean"] = {n="Bauer Saldean",s="Bauer Saldean ist ein widerstandsfähiger menschlicher Siedler, der zusammen mit seiner Frau Salma auf Saldeans Farm im Herzen von Westfall lebt. Anders als viele benachbarte Bauern, die flohen oder aufgaben, bestellt Saldean trotz durchgedrehter Erntegolems und zunehmendem Banditentum beharrlich seine geplagten Felder.",h="Bauer Saldean ist ein widerstandsfähiger menschlicher Siedler, der zusammen mit seiner Frau Salma auf...",kw={"hühnerfutter","bauer saldean","erntewächter","saldean","saldeans farm","salma","tod auf den feldern","westfall"},ang={["faction:Alliance"]="Saldean verkörpert die sture Entschlossenheit der verbliebenen Loyalisten Westfalls, die am Boden des Königreichs festhalten, selbst wenn die Soldaten der Krone nirgends zu sehen sind.",["profession:Cooking"]="Bauern wie Saldean sind das bröckelnde Rückgrat der Nahrungsmittelversorgung von Sturmwind; die Sicherung seiner Ernte sorgt dafür, dass überall im Königreich einfaches Brot auf den Tischen steht."},sec={{t="Am Pflug festhalten",b="Bauer Saldean erinnert sich noch an die Zeit, als Westfall als die üppigste Kornkammer diesseits des Schlingendorntals galt. Diese wohlhabenden Jahre sind zu Staub zerfallen. Umgeben von überwucherten Feldern, randalierenden mechanischen Erntewächtern und räuberischen Banditen weigert sich Saldean, sein Land aufzugeben. Während andere Siedler ihre Ländereien verließen oder sich der Dieberei zuwandten, bleiben er und seine Frau Salma entschlossen, das wenige Getreide zu ernten, das sie können. Getrieben von praktischer Verzweiflung rekrutiert er wandernde Abenteurer, um die durchgedrehten Erntegolems zu zerlegen, die seine Felder heimsuchen, damit er ihre Teile bergen und seinen Boden für die Aussaat vorbereiten kann."},{t="Die Sense von Westfall",b="Saldeans starrköpfige Verteidigung seines Hofes macht ihn zu einem der wenigen verbliebenen Anker zivilen Lebens zwischen der Späherkuppe und der nördlichen Brücke. Trotz seiner harten Umstände pflegt er Verbindungen zur Volksmiliz und schickt wehrhafte Reisende zu Gryan Starkmantel weiter, sobald seine eigenen unmittelbaren Sorgen gelöst sind. Saldean weiß nur allzu gut, dass die Beseitigung der wilden Ernteschnitter seinem Hof nur eine vorübergehende Atempause verschafft, solange der allgemeinen Gesetzlosigkeit, die das Land erdrosselt, kein Einhalt geboten wird."}},faq={{q="Wer ist Bauer Saldean?",a="Saldean ist ein erfahrener menschlicher Bauer, der zusammen mit seiner Frau Salma auf Saldeans Farm in Westfall lebt. Er ist einer der wenigen einheimischen Siedler, die sich trotz Hungersnot, durchgedrehter Erntegolems und des ausufernden Banditentums in der Region starrköpfig weigern, ihr Land aufzugeben.",al={"saldean","wer ist saldean","saldean nsc"}},{q="Warum ist Bauer Saldeans Farm in Schwierigkeiten?",a="Westfalls automatisierte Erntegolems sind fehlerhaft geworden und durchgedreht; sie streifen über das Ackerland und greifen jeden in Sichtweite an. Saldean benötigt Abenteurer, die die mechanischen Wächter zur Strecke bringen und deren Teile erbeuten, damit er seine Weizenfelder zurückgewinnen kann.",al={"warum greifen erntegolems an","saldeans farm problem"}},{q="Wo ist Bauer Saldean zu finden?",a="Er befindet sich vor seinem Bauernhaus auf Saldeans Farm, direkt an der Hauptstraße im Herzen von Westfall, knapp nördlich der Späherkuppe.",al={"saldean standort","wo ist saldean","saldeans farm standort"}},{q="Unterstützt Saldean die Volksmiliz?",a="Ja. Während sich Saldean ganz darauf konzentriert, seine Ernte und sein Heim zu verteidigen, schickt er fähige Abenteurer die Straße hinab zu Gryan Starkmantel an der Späherkuppe, um die Volksmiliz bei der Verteidigung der Region zu unterstützen.",al={"saldean gryan starkmantel","saldean miliz"}},{q="Welche einzigartigen Waren verkauft Saldean?",a="Saldean verkauft Grundnahrungsmittel wie Brot und ist der Hauptanbieter von Spezial-Hühnerfutter, einem sonderbaren Getreide, das von Reisenden begehrt wird, die sich mit dem in Westfall umherstreifenden Federvieh anfreunden wollen.",al={"saldean händler","spezial-hühnerfutter händler"}}},fx={b644bbfd={q="Was möchte Bauer Saldean?",a="Saldean wünscht sich nichts sehnlicher, als sein Gehöft zu beschützen, seine Ernte einzubringen und sich gemeinsam mit seiner Frau, Salma, ein Leben aufzubauen. Da Westfall von Gesetzlosigkeit geprägt ist und von Sturmwind vernachlässigt wird, ist er darauf angewiesen, dass reisende Abenteurer die durchgedrehten mechanischen Erntemaschinen beseitigen, die auf seinen Feldern ihr Unwesen treiben, und die örtliche Volksmiliz dabei unterstützen, die Sicherheit in der Region wiederherzustellen.",al={"was möchte saldean","saldeans ziel","was möchte bauer saldean"}},["4c04765a"]={q="Warum ist Bauer Saldean hier?",a="Saldean hat sein ganzes Leben in Westfall verbracht und erinnert sich noch an die Zeit, als die Region zu den fruchtbarsten Ackerländern der Östliche Königreiche gehörte. Selbst als die benachbarten Anwesen verfielen und Banditen das Land überrannten, weigerte er sich, sein Land aufzugeben. Er blieb auf Saldeans Farm, um seinen Boden zu bestellen und trotz der drohenden Gefahren an seinem Zuhause festzuhalten.",al={"warum ist saldean in westfall","warum bleibt saldean","herkunft bauer saldean"}},["4625baa0"]={q="Mit wem ist Bauer Saldean verbunden?",a="Bauer Saldean führt sein Gehöft gemeinsam mit seiner Frau, Salma Saldean, die sich um den Haushalt und das Kochen kümmert. Er arbeitet außerdem mit Gryan Starkmantel und der Volksmiliz auf der Späherkuppe zusammen und weist fähige Recken an, ihren Kampf gegen die Gesetzlosen zu unterstützen, die die Kornkammer des Königreichs bedrohen.",al={"familie bauer saldean","mit wem ist saldean verheiratet","beziehung salma saldean"}}},fp="14,278,16.624.0,22.511.0,22.249.0,40.242.0,34.137.0,42.207.0,36.175.0"}
P.entries["npc:farthing"] = {n="Heller",s="Bischof Heller ist ein menschlicher Geistlicher, der in der Kathedrale des Lichts in Sturmwind residiert. Besuchern und Gläubigen präsentiert er sich als ergebener Diener des Heiligen Lichts, der die Gemeindemitglieder anleitet und Hilfe in bedrängte Siedlungen im gesamten Königreich entsendet.",h="Bischof Heller ist ein menschlicher Geistlicher, der in der Kathedrale des Lichts in Sturmwind residiert.",kw={"benedictus","bischof heller","kathedrale des lichts","farthing","morbent teufel","auf der suche nach weisheit","sturmwind"},ang={["class:Priest"]="Für Priester, die die Kathedrale des Lichts besuchen, verkörpert Heller die etablierte Hierarchie und die gelehrte Weisheit des menschlichen Klerus in Sturmwind.",["faction:Alliance"]="Abenteurer, die gegen die schleichende Verderbnis in den südlichen Gebieten der Allianz wie dem Dämmerwald kämpfen, blicken auf Heller und seine Amtsbrüder, um göttliche Einsicht und spirituelle Entschlossenheit zu erlangen."},sec={{t="Ein Bischof in Sturmwind",b="In den ruhigen Marmorhallen der Kathedrale des Lichts ist Bischof Heller eine der herausragenden Persönlichkeiten, die sich um die spirituellen Bedürfnisse von Sturmwind kümmern. An der Seite von Erzbischof Benedictus und der versammelten Geistlichkeit berät er Reisende, unterstützt jene, die die heiligen Künste erlernen, und widmet sich den bürgerlichen wie auch pastoralen Pflichten der Kirche des Heiligen Lichts."},{t="Hilfe für das Verseuchte Land",b="Obwohl er in der Hauptstadt verweilt, weist Heller entschlossene Reisende in dunklere Winkel des Königreichs ein, die dringend heiligen Beistand benötigen. Als besorgniserregende Berichte über den Totenbeschwörer Morbent Teufel und die schleichende Untotenplage eintreffen, die den Dämmerwald heimsucht, dient Heller als Ratgeber bei der Suche nach Wegen, dunkle Zaubereien zu überwinden und die heimgesuchte Grenzregion zu reinigen."}},faq={{q="Wo ist Bischof Heller zu finden?",a="Bischof Heller residiert im Inneren der Kathedrale des Lichts, die sich im Zentrum des Kathedralenplatzes in Sturmwind befindet.",al={"farthing aufenthaltsort","wo ist farthing","farthing karte"}},{q="Welche Rolle spielt Heller in der Kathedrale?",a="Er dient als geweihter Bischof innerhalb der Kirche des Heiligen Lichts und steht besuchenden Gläubigen, Priestern in Ausbildung und Abenteurern zur Seite, die im Namen ferner Siedlungen nach heiliger Weisheit suchen.",al={"was macht farthing","wer ist farthing"}},{q="Wie ist Heller in die Geschehnisse im Dämmerwald verwickelt?",a="Heller wird von Abenteurern aufgesucht, die sich der Bedrohung durch die Untoten im Dämmerwald stellen; er berät über die dunklen Künste, die den Totenbeschwörer Morbent Teufel nähren, und weist Seelen den Weg zur Läuterung.",al={"farthing dämmerwald","farthing morbent teufel"}},{q="Ist Heller mit anderen Bürgern gleichen Namens verwandt?",a="Mehrere andere Personen in den Ländern der Menschen tragen den Nachnamen Heller, darunter Coleman Heller und Yvette Heller, wenngleich er nicht aktiv über direkte familiäre Bindungen spricht.",al={"coleman heller verwandter","familie farthing"}}},fx={e8954fc9={q="Wer ist Bischof Heller?",a="Bischof Heller ist ein menschlicher Priester der Kirche des Heiligen Lichts, der in der Kathedrale des Lichts in Sturmwind dient. Äußerlich fromm und respektabel, kümmert er sich um die Angelegenheiten der Kathedrale und bietet den Gläubigen Orientierung.",al={"wer ist farthing","bischof farthing","farthing hintergrund"}},f4152aa6={q="Auf wessen Seite steht Bischof Heller?",a="Dem Anschein nach steht Heller fest an der Seite der Großen Allianz und der Kirche des Heiligen Lichts unter Erzbischof Benedictus. Er vertritt den Priesterstand innerhalb des heiligen Heiligtums von Sturmwind, leitet Bittsteller an und kümmert sich um Fragen des Glaubens.",al={"farthing zugehörigkeit","wem dient farthing","ist farthing bei der allianz"}},["1ec473be"]={q="Was möchte Bischof Heller?",a="Oberflächlich betrachtet möchte Heller Reisenden helfen und die Tugenden des Lichts aufrechterhalten. Er zeigt besondere Sorge für Ländereien, die von Dunkelheit bedroht sind, indem er beispielsweise Abenteurer berät, wie sie dem bedrängten Volk des Dämmerwalds gegen dunkle Nekromantie helfen können.",al={"farthings beweggrund","was möchte farthing","farthings ziel"}},["1783acb6"]={q="Warum ist Bischof Heller in der Kathedrale des Lichts?",a="Heller ist in der Kathedrale des Lichts in Sturmwind stationiert, um seine klerikalen Pflichten als Bischof zu erfüllen, Besucher zu beraten, den Priesterstand zu unterstützen und bei der Leitung kirchlicher Angelegenheiten im Auftrag der hohen Geistlichkeit zu helfen.",al={"warum ist farthing hier","warum ist farthing in sturmwind","farthings aufgabe kathedrale"}}},fp="8,272,21.374.0,24.390.0,35.119.0,46.199.0,39.187.0,60.172.0"}
P.entries["npc:feegly-the-exiled"] = {n="Feegly der Verbannte",s="Feegly der Verbannte ist ein verstoßener Zwerg, der in der Nähe der Zwergenausgrabung bei Bael Modan im südlichen Brachland lauert. Einst als einer der besten Ausgräber der Expedition gerühmt, führte seine Obsession mit einem freigelegten Relikt dazu, dass General Twinbraid ihn verjagte.",h="Feegly der Verbannte ist ein verstoßener Zwerg, der in der Nähe der Zwergenausgrabung bei Bael Modan im...",kw={"bael modan","brachland","ausgräber","ausgrabung","verbannt","feegly","träne der monde","trogg"},ang={["faction:Horde"]="Feeglys bitterer Groll gegen die Ausgräber von Bael Modan macht ihn zu einem unerwarteten Verbündeten für Wanderer der Horde, die die Zwergenexpedition im Brachland sabotieren wollen.",["race:Dwarf"]="Für Zwerge ist Feegly eine tragische und furchterregende Warnung: ein fähiger Ausgräber, dessen Obsession mit einem ausgegrabenen Relikt ihn seinen Platz unter seinesgleichen kostete."},sec={{t="Der Ruin eines Ausgräbers",b="Vor seinem Exil galt Feegly als einer der führenden Ausgräber in Bael Modan. Die Träne der Monde war die erste große Entdeckung bei der Grabung, und Feegly beanspruchte ihre Macht für sich selbst. General Twinbraid bezeichnete den Edelstein als verflucht, sperrte ihn in Burg Bael'dun weg und vertrieb Feegly. Nun brütet er einsam vor sich hin, verzweifelt darauf bedacht, genau jenen Edelstein zurückzuerlangen, der sein Verderben besiegelt: Als er ihn schließlich wieder in Händen hält, zerbricht die Träne und er verwandelt sich in einen scheußlichen, buckligen Trogg."}},faq={{q="Wer ist Feegly der Verbannte?",a="Feegly ist ein Zwerg, ein verbannter Ausgräber der Grabungsstätte Bael Modan, der ein als die Träne der Monde bekanntes Relikt begehrt.",al={"wer ist feegly","feegly geschichte","feegly der verbannte"}},{q="Warum wurde Feegly aus Bael Modan verbannt?",a="Feegly verfiel einer Obsession für die Träne der Monde, der ersten großen Entdeckung in Bael Modan. General Twinbraid bezeichnete den Edelstein als verflucht, sperrte ihn in Burg Bael'dun weg und vertrieb Feegly.",al={"warum verbannt","was hat feegly getan","feegly verbannung"}},{q="Warum ist Feegly bereit, mit Abenteurern der Horde zu sprechen?",a="Von seinen Zwergenbrüdern verraten und verstoßen, hegt Feegly keinerlei Loyalität gegenüber der Expedition der Allianz. Er ist verzweifelt genug, um Reisende der Horde um Hilfe zu bitten, damit er das von ihm begehrte Relikt wiedererlangt.",al={"warum ist feegly freundlich zur horde","feegly horde freundlich"}},{q="Was ist die Träne der Monde?",a="Die Träne der Monde ist ein Edelstein, den die Ausgräber in Bael Modan freigelegt haben – ihre erste große Entdeckung dort. Feegly behauptet, sie habe ihm Macht verliehen, doch General Twinbraid hielt sie für verflucht und schloss sie in Burg Bael'dun ein.",al={"träne der monde","feegly edelstein","feegly artefakt"}}},fx={["21513985"]={q="Wer ist Feegly der Verbannte?",a="Feegly ist ein verbannter Zwergengräber von der Ausgrabungsstätte Bael Modan im südlichen Brachland. Er hält sich außerhalb der Ausgrabungsstätte auf und ist besessen davon, ein Relikt namens The Tear of the Moons zu bergen.",al={"wer ist feegly","feeglys identität","feeglys hintergrund"}},ed9ce58e={q="Was möchte Feegly der Verbannte?",a="Feegly sucht nach The Tear of the Moons, einem Relikt, das er wegen seiner seltsamen Macht begehrt. Er rekrutiert willige Wanderer, um es aus Burg Bael'dun zu bergen, damit er es wieder in seinen Besitz bringen kann.",al={"was möchte feegly","feeglys beweggrund","warum braucht feegly die träne"}},["7eaaafaa"]={q="Warum ist Feegly der Verbannte im Brachland?",a="Feegly hält sich in den Hügeln außerhalb von Bael Modan auf, weil General Twinbraid ihn vertrieben und The Tear of the Moons weggeschlossen hat. Verzweifelt versucht er, den Edelstein zurückzugewinnen, und bleibt daher in der Nähe seiner ehemaligen Ausgrabungsstätte.",al={"warum ist feegly hier","wo bleibt feegly","warum ist feegly außerhalb von bael modan"}},["0b854105"]={q="Mit wem ist Feegly der Verbannte verbunden?",a="Feegly ist mit der Zwergenexpedition von Bael Modan verbunden, wo er früher einer ihrer wichtigsten Gräber war, bevor er verbannt wurde. Nun von seinen Verwandten entfremdet, ist er darauf angewiesen, dass vorbeiziehende Wanderer der Horde sein Gebot gegen die Ausgrabung ausführen.",al={"feeglys verbindungen","mit wem arbeitet feegly zusammen","feeglys beziehungen"}}},fp="17,252,15.460.1,25.113.0,38.184.0,51.189.0,30.214.0"}
P.entries["npc:feero-ironhand"] = {n="Feero Eisenhand",s="Feero Eisenhand ist ein menschlicher Kämpfer, der an Maestras Posten in den westlichen Weiten von Eschental stationiert ist. Er hält Wache an der Grenze zwischen Dunkelküste und dem Wald und arbeitet eng mit Delgren dem Läuterer zusammen, um den finsteren Cult of the Dark Strand zu bekämpfen.",h="Feero Eisenhand ist ein menschlicher Kämpfer, der an Maestras Posten in den westlichen Weiten von Eschental...",kw={"eschental","auberdine","cult of the dark strand","delgren der läuterer","feero eisenhand","maestras posten"},ang={["faction:Alliance"]="Feero bietet Reisenden der Allianz, die von der Dunkelküste in die gefährliche, umkämpfte Wildnis von Eschental ziehen, einen wichtigen Stützpunkt.",["race:Human"]="Einen anderen Menschen in den uralten Elfenwäldern von Eschental Wache stehen zu sehen, ist ein willkommenes Zeichen der weitreichenden Zusammenarbeit der Allianz."},sec={{t="Ein Bollwerk an Maestras Posten",b="An der Straße gelegen, die von Dunkelküste nach Süden nach Eschental führt, dient Maestras Posten als entscheidender Wachposten für Reisende und Verteidiger der Allianz gleichermaßen. Feero Eisenhand operiert von diesem Außenposten aus, hält Kommunikations- und Handelswege nach Auberdine aufrecht und wacht wachsam über die umliegenden Wälder. Gemeinsam mit Delgren dem Läuterer konzentriert Feero seine Bemühungen gegen den bösartigen Cult of the Dark Strand und stellt sicher, dass die Kultisten und Waldraubtiere den Pfad zwischen den Versorgungslinien von Darnassus und den Frontlinien von Eschental nicht abschneiden."}},faq={{q="Wer ist Feero Eisenhand?",a="Feero Eisenhand ist ein menschlicher Krieger der Allianz, der an Maestras Posten im westlichen Eschental stationiert ist. Er hilft Reisenden, die zwischen Dunkelküste und Eschental unterwegs sind, und koordiniert die Logistik zurück nach Auberdine.",al={"feero eisenhand","wer ist feero","feero nsc"}},{q="Welche Aufgabe hat Feero an Maestras Posten?",a="Feero hilft dabei, den Außenposten gegen lokale Bedrohungen zu halten, und unterstützt Delgren den Läuterer im Kampf gegen den Cult of the Dark Strand, während er wichtige Kurier- und Versorgungsrouten nach Dunkelküste aufrechterhält.",al={"warum ist feero hier","feero rolle","maestras posten mensch"}},{q="Was ist der Cult of the Dark Strand?",a="Der Cult of the Dark Strand ist eine finstere Gemeinschaft, die im nördlichen Eschental operiert und sich mit dunkler Magie und üblen Ritualen befasst. Allianzstreitkräfte an Maestras Posten arbeiten aktiv daran, ihre Operationen zu stören und zu zerschlagen.",al={"dark strand kult","kult of dark strand","dark strand"}},{q="Hat Feero Verbindungen zur Argentumdämmerung?",a="Ja. Feero ist mit der Argentumdämmerung verbunden und arbeitet eng mit Delgren dem Läuterer zusammen, einem Paladin der Argentumdämmerung, der die dunklen Mächte im Wald bekämpft.",al={"feero argentumdämmerung","gehört feero zur argentumdämmerung"}}},fx={["996da789"]={q="Auf wessen Seite steht Feero Eisenhand?",a="Feero Eisenhand steht fest auf der Seite der Allianz. Er ist in Maestras Posten stationiert, einem wichtigen Nachtelfen-Außenposten entlang der westlichen Grenze des Eschentals, und unterstützt Reisende und lokale Streitkräfte gegen die Bedrohungen, die über dem uralten Wald schweben.",al={"feero eisenhand fraktion","ist feero bei der allianz","seite feero eisenhand"}},bf9a9ed2={q="Was möchte Feero Eisenhand?",a="Feero zielt darauf ab, die Verteidiger von Maestras Posten zu unterstützen und den finsteren Kult des Dunklen Strangs zu vereiteln. Gemeinsam mit Delgren der Läuterer versucht er, deren verderblichen Einfluss aus dem nördlichen Kalimdor zu tilgen und die Versorgungswege zwischen dem Eschental und der Dunkelküste aufrechtzuerhalten.",al={"ziel feero eisenhand","was möchte feero","feeros beweggrund"}}},fp="14,254,27.562.0,22.199.0,42.193.0,36.216.0,47.160.0"}
P.entries["npc:fel-zerul"] = {n="Fel'zerul",s="Fel'zerul ist ein Hexenmeister der Orcs, der in Steinard in den trüben Tiefen der Sümpfe des Elends stationiert ist. Auf direkten Befehl von Kriegshäuptling Thrall untersucht er die unheilvolle Präsenz, die im versunkenen Tempel von Atal'Hakkar lauert.",h="Fel'zerul ist ein Hexenmeister der Orcs, der in Steinard in den trüben Tiefen der Sümpfe des Elends...",kw={"atal'hakkar","fel'zerul","felzerul","steinard","sümpfe des elends","thrall","hexenmeister"},ang={["class:Warlock"]="Fel'zerul steht für die offizielle Beauftragung eines Hexenmeisters durch Thrall und verdeutlicht, dass Die neue Horde gelegentlich auf Ausüber der dunklen Künste zurückgreift, um obskuren, esoterischen Bedrohungen zu begegnen.",["faction:Horde"]="In Steinard stationiert, fungiert Fel'zerul als Frühwarnspäher und stellt sicher, dass die finstere Magie, die im Sumpf schwelt, den Stützpunkt der Horde in der Region nicht unvorbereitet trifft."},sec={{t="Ein wachsames Auge auf den Versunkenen Tempel",b="Während Thralls Horde die dunklen Künste im Allgemeinen mit Misstrauen betrachtet, erkennt der Kriegshäuptling an, dass das Verständnis finsterer Mächte jene erfordert, die sie studieren. Fel'zerul wurde eigens nach Steinard entsandt, um das Verderben rund um den Tränenteich und den untergetauchten Tempel von Atal'Hakkar aufzudecken. Indem er Abenteurer anweist, Artefakte zu bergen und die verbannten Atal'ai-Trolle zu untersuchen, versucht der Hexenmeister herauszufinden, welches Unheil sich unter den trüben Wassern regt, bevor es den südlichen Außenposten der Horde bedroht."}},faq={{q="Wer ist Fel'zerul?",a="Fel'zerul ist ein Hexenmeister der Orcs, der in Steinard weilt, der Festung der Horde in den Sümpfen des Elends. Er fungiert als Ermittler, der die dunklen Rituale analysiert, die sich im nahe gelegenen Tempel von Atal'Hakkar abspielen.",al={"felzerul","wer ist fel'zerul","steinard hexenmeister"}},{q="Warum schickte Thrall einen Hexenmeister nach Steinard?",a="Kriegshäuptling Thrall entsandte Fel'zerul, weil der Umgang mit uralten Flüchen und Blutritualen Fachwissen in dunklerer Zauberei erfordert. Fel'zeruls Auftrag ist es, die beunruhigenden Entwicklungen rund um den versunkenen Tempel zu überwachen und die Interessen der Horde im Sumpf zu schützen.",al={"thrall felzerul","warum ist felzerul hier","felzerul mission"}},{q="Was untersucht Fel'zerul?",a="Fel'zerul untersucht die Atal'ai-Trolle und ihre unheiligen Riten im Tempel von Atal'Hakkar am Tränenteich. Er spannt Späher und Abenteurer ein, um Artefakte zu heben und verbannte Priester aufzuspüren, die über entscheidendes Wissen verfügen könnten.",al={"felzerul quest lore","was will felzerul","tränenteich untersuchung"}}},fp="9,228,25.509.0,17.203.0,41.259.0,32.240.0"}
P.entries["npc:felgur-twocuts"] = {n="Felgur Zweischneid",s="Felgur Zweischneid ist ein barscher orkischer Späher, der am Geistwandlerposten in Desolace stationiert ist. Er koordiniert die Bemühungen der Horde gegen die regionalen Zentaurenklans.",h="Felgur Zweischneid ist ein barscher orkischer Späher, der am Geistwandlerposten in Desolace stationiert ist.",kw={"zentaurenkopfgeld","desolace","felgur zweischneid","geistwandlerposten","horde","kolkar","ork"},ang={["faction:Horde"]="Felgur fungiert als wichtige Einsatzverbindung am Geistwandlerposten und hilft der Horde, die aggressiven Zentaurenstämme in Desolace zurückzudrängen.",["race:Orc"]="Getreu dem orkischen Pragmatismus in gefährlichen Grenzgebieten schätzt Felgur Stärke, Schnelligkeit und unmittelbare Ergebnisse mehr als müßige Konversation."},sec={{t="Ein grober Außenpostenspäher",b="Felgur Zweischneid hält inmitten der trostlosen Weiten des Geistwandlerpostens im zentralen Desolace Wache und hat wenig Geduld für Höflichkeiten. Als Vorpostenspäher der Horde beurteilt er die Bedrohungen für Reisende und Siedler, die sich westwärts durch die Berge wagen, insbesondere die lokalen Kolkar-Zentauren."},{t="Krieg gegen die Zentauren",b="Felgur weist Champions der Horde an, die lokalen Zentaurenhäuptlinge auszuschalten und Kopfgelder auf die kriegerischen Stämme auszusetzen, die drohen, die Region zu überrennen. Er ist ein zentraler Kontakt für jeden, der den Stützpunkt der Horde in Desolace sichern möchte."}},faq={{q="Wer ist Felgur Zweischneid?",a="Felgur Zweischneid ist ein orkischer Späher und Questgeber, der am Geistwandlerposten stationiert ist, dem Vorposten der Horde in Desolace.",al={"wer ist felgur zweischneid","wer ist felgur"}},{q="Wo finde ich Felgur Zweischneid?",a="Er befindet sich am Geistwandlerposten, direkt nördlich der zentralen Straße, die durch Desolace führt.",al={"ort von felgur zweischneid","wo ist felgur","wo ist felgur zweischneid"}},{q="Welche Aufgaben gibt Felgur Zweischneid?",a="Felgur rekrutiert Abenteurer der Horde, um die lokalen Kolkar-Zentauren anzugreifen, Khan Dez'hepah zu jagen und Kopfgelder auf feindselige Zentauren zu sammeln.",al={"felgur quests","was will felgur"}},{q="Warum ist Felgur so schroff zu Besuchern?",a="Desolace ist ein gefährliches und unerbittliches Ödland, das von feindseligen Zentaurenklans umgeben ist. An einem isolierten Posten stationiert, hat Felgur keine Zeit für untätiges Geplänkel und konzentriert sich lieber streng auf das Überleben und seine militärische Pflicht.",al={"warum ist felgur unhöflich","fass dich kurz felgur"}}},fx={f5a09a6e={q="Auf wessen Seite steht Felgur Zweischneid?",a="Felgur ist ein stolzes Mitglied der Horde, das weit draußen an der Grenze stationiert ist, um ihre Interessen voranzubringen und ihre Lager gegen regionale Bedrohungen zu verteidigen.",al={"felgur zweischneid fraktion","ist felgur bei der horde","wem dient felgur"}},["8c623583"]={q="Was möchte Felgur Zweischneid?",a="Felgur versucht, die feindseligen Zentaurenclans einzudämmen, die die Horde in Desolace bedrohen. Er wirbt fähige Recken an, um Kopfgelder zu sammeln und sich Khan Dez'hepah entgegenzustellen.",al={"ziel felgur zweischneid","was versucht felgur zu tun","was braucht felgur"}},a5d710fc={q="Warum ist Felgur Zweischneid hier stationiert?",a="Felgur ist im Geistwandlerposten stationiert, um die örtlichen Zentaurenstämme zu beobachten und Maßnahmen gegen Bedrohungen für den Stützpunkt der Horde in Desolace zu leiten.",al={"warum ist felgur zweischneid im geistwandlerposten","felgurs zweck hier","warum ist felgur hier draußen"}}},fp="14,144,21.297.0,18.233.0,22.122.0,32.92.0,36.138.0,36.213.0"}
P.entries["npc:felix-whindlebolt"] = {n="Felix Windenbolz",s="Felix Windenbolz ist ein vertriebener Gnomenflüchtling, der in Ambossar im Coldridgetal Zuflucht sucht. In seiner Eile, vor der radioaktiven Strahlung zu fliehen, die Gnomeregan überflutete, verlor er seine persönlichen Habseligkeiten, und feindselige Frostmane-Trolle machten sich damit davon.",h="Felix Windenbolz ist ein vertriebener Gnomenflüchtling, der in Ambossar im Coldridgetal Zuflucht sucht.",kw={"ambossar","das coldridgetal","felix windenbolz","frostmane","gnomeregan","flüchtling","weißbarts lager"},ang={["race:Dwarf"]="Die einheimischen Frostmane-Trolle sind im gesamten Coldridgetal dreister geworden und greifen verletzliche Gnomenflüchtlinge an, die in der Nähe von Ambossar umherwandern.",["race:Gnome"]="Felix verkörpert die anhaltende Not Eurer vertriebenen Artgenossen, die nach der Katastrophe in Gnomeregan in die unbarmherzige Kälte von Dun Morogh getrieben wurden."},sec={{t="Ein heimatloser Reisender",b="Nach dem tragischen Fall von Gnomeregan irrten Tausende von Gnomen auf der Suche nach Sicherheit durch die eisigen Weiten von Dun Morogh. Felix Windenbolz floh in solcher Eile aus der verstrahlten Stadt, dass er all seine persönlichen Habseligkeiten und Werkzeuge verlor. Zu allem Überfluss verschleppten Frostmane-Eistrolle seine Kiste, seinen Kasten und seinen Eimer voll Bolzen in ihre Lager südwestlich von Ambossar, sodass er mittellos und gestrandet zurückblieb und auf mitfühlende Wanderer angewiesen ist, um seine gestohlene Ausrüstung zurückzuerlangen."}},faq={{q="Wer ist Felix Windenbolz?",a="Felix Windenbolz ist ein Gnomenflüchtling, der derzeit in Ambossar im Coldridgetal Unterschlupf gefunden hat. Er verlor seine Habseligkeiten bei der Flucht aus Gnomeregan, und die einheimischen Frostmane-Trolle stahlen sie.",al={"wer ist felix","felix windenbolz lore","gnom im weißbartlager"}},{q="Wohin wollte Felix fliehen?",a="Felix floh vor der Strahlung, die Gnomeregan überrollte, nachdem der Versuch der Gnome, die Troggs zu vertreiben, schrecklich schiefgegangen war. Er landete in Ambossar, dem Zwergenaußenposten im Coldridgetal, auch wenn er den Ort für einen Gnomen als denkbar ungeeignet empfindet.",al={"wohin wollte felix","felix ziel","warum ist felix im coldridgetal"}},{q="Was ist mit seinen Besitztümern geschehen?",a="In seiner Hast, aus Gnomeregan zu entkommen, verlor Felix seine Kiste, seinen Kasten und seinen Eimer voll Bolzen. Die Frostmane-Eistrolle verschleppten sie in ihre Lager südwestlich von Ambossar, sodass er ohne Vorräte gestrandet ist.",al={"wer hat felix' sachen gestohlen","felix gestohlene ausrüstung","frostmane trolle felix"}},{q="Was verkauft Felix an Abenteurer?",a="Nichts. Felix ist kein Händler: Er hat bei seiner Flucht aus Gnomeregan all seine Habseligkeiten verloren, und alles, was er in Ambossar anbieten kann, ist sein Dank an jeden, der seine Kiste, seinen Kasten und seinen Eimer voll Bolzen wiederbeschafft.",al={"felix händlerwaren","was bietet felix an","felix inventar"}}},fx={b1540142={q="Auf wessen Seite steht Felix Windenbolz?",a="Felix gehört zu den Gnomeregangnome und der Großen Allianz. Wie viele vertriebene Gnome floh er aus den verstrahlten Ruinen von Gnomeregan und findet nun Zuflucht in Ambossar im Coldridgetal, in der Hoffnung, wieder zu seinem Volk zurückkehren zu können.",al={"felix fraktion","ist felix bei der allianz","für wen arbeitet felix"}}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:fenrus-the-devourer"] = {n="Fenrus der Verschlinger",s="Fenrus der Verschlinger ist ein gewaltiger Worg, der durch das obere Sanktum von Burg Shadowfang streift. Von Erzmagier Arugal als persönliches Haustier und Wächter gehalten, ist die unersättliche Bestie durch unnatürliche Magie aufgedunsen. Jeder, der es wagt, in das persönliche Arbeitszimmer des Erzmagiers einzudringen, muss sich diesem wilden Schrecken und dem Meister stellen, der über ihn wacht.",h="Fenrus der Verschlinger ist ein gewaltiger Worg, der durch das obere Sanktum von Burg Shadowfang streift.",kw={"arugal","fenrus","fenrus der verschlinger","burg shadowfang","silberwald","worg"},ang={["class:Hunter"]="Verschwendet keine Zeit mit dem Versuch, Fenrus zu bezaubern. Der Geist der Bestie ist durch die dunklen Künste von Shadowfang unwiderruflich verdreht und kann nicht an die Wildnis gebunden werden.",["class:Mage"]="Fenrus dient als düstere Mahnung daran, wie tief Erzmagier Arugal gefallen ist, indem er arkane Künste nutzt, um wilde Bestien in groteske Wächter zu verwandeln.",["class:Warlock"]="Erzmagier Arugals Fähigkeit, Leerwandler zur Unterstützung seines Hundes herbeizurufen, offenbart, wie tief der einstige Magier aus Dalaran in schattenhafte, verbotene Beschwörungen eingetaucht ist."},sec={{t="Eine Bestie im Arbeitszimmer des Meisters",b="Tief in Burg Shadowfang, unmittelbar vor den Gemächern von Erzmagier Arugal, lauert der monströse Worg namens Fenrus der Verschlinger. Anders als die wolfsartigen Worgen, die die Zinnen durchstreifen, ist Fenrus ein echter Worg, der zu gigantischen Ausmaßen herangewachsen ist. Während er zwischen den Regalen, Schriftrollen und arkanen Apparaturen von Arugals privatem Arbeitszimmer umherstreift, dient die Bestie sowohl als Haustier als auch als unbarmherzige Vorhut gegen jeden Eindringling, der den Kopf des verrückten Magiers fordert."},{t="Verderbte Macht",b="Fenrus' unnatürliche Masse legt nahe, dass er den dunklen Magien ausgesetzt war, die die Burg seit dem Fall von Baron Silberlein durchdringen. Erzmagier Arugal oder seine entfesselten Worgen haben die Kreatur zweifellos durch arkane oder schattenhafte Experimente verändert und so ein heimisches Raubtier in einen unersättlichen Koloss verwandelt. Fenrus ist so wild und magisch gebunden, dass kein Jäger seinen Geist bezaubern oder zähmen kann."},{t="Arugals wachsames Auge",b="Fenrus aufzuschrecken, bedeutet für Unvorsichtige das sofortige Todesurteil. Erblickt die Bestie einen Eindringling, stößt sie ein ohrenbetäubendes Heulen aus, das durch die gesamte Festung hallt und die unmittelbare Aufmerksamkeit von Arugal selbst auf sich zieht. Anstatt sein Haustier unverteidigt zu lassen, projiziert der Erzmagier seinen finsteren Willen in die Kammer und beschwört Leerwandler herbei, die Fenrus dabei helfen sollen, die Eindringlinge zu überwältigen und zu verschlingen."}},faq={{q="Was für eine Kreatur ist Fenrus?",a="Fenrus ist ein außergewöhnlich großer Worg – ein natürliches, wolfsähnliches Raubtier, das in Lordaeron heimisch ist – und kein zweibeiniger Worgen. Seine unnatürliche Masse und bösartige Wildheit sind das direkte Ergebnis anhaltender Einwirkung der dunklen Magie, die in Burg Shadowfang gewirkt wird.",al={"ist fenrus ein worgen","fenrus kreaturtyp","fenrus wolf"}},{q="Wo ist Fenrus zu finden?",a="Fenrus streift durch das Arbeitszimmer hoch oben in Burg Shadowfang im Silberwald. Sein Bau liegt direkt auf dem Weg zu Erzmagier Arugals innerem Refugium.",al={"wo ist fenrus","fenrus standort","fenrus raum"}},{q="Können Jäger Fenrus als Begleiter zähmen?",a="Nein. Obwohl er als gewöhnliches Wildtier eingestuft ist, kann Fenrus nicht gezähmt werden. Sein Geist ist völlig gebrochen, verwildert und an Erzmagier Arugals finsteren Willen gebunden.",al={"kann ich fenrus zähmen","ist fenrus zähmbar","fenrus zähmen"}},{q="Warum beschwört Arugal Dämonen, wenn Fenrus angegriffen wird?",a="Arugal betrachtet Fenrus als sein geschätztes Haustier und als letzte Verteidigungslinie vor seinem Sanktum. Wenn Fenrus beim Eintritt in den Kampf aufbrüllt, greift Arugal direkt ein und beschwört Leerwandler in die Kammer, um jeden zu überwältigen, der seine Bestie bedroht.",al={"arugal leerwandler","warum hilft arugal fenrus","fenrus leerwandler diener"}},{q="Warum ist Fenrus so viel größer als normale Worge?",a="Fenrus' gewaltige Größe gilt als Folge der dunklen magischen Experimente von Erzmagier Arugal oder als magische Nachwirkung des Worgenbefalls, der die Burg heimsucht.",al={"warum ist fenrus riesig","fenrus größe hintergrund","riesenworg"}},{q="Was geschieht im gesamten Dungeon, wenn Fenrus angegriffen wird?",a="Tritt Fenrus in den Kampf ein, stößt er ein donnerndes Gebrüll aus, das so laut ist, dass man es überall in Burg Shadowfang hören kann, wodurch jeder auf den Kampf vor Arugals Tür aufmerksam gemacht wird.",al={"fenrus gebrüll","fenrus heulen im dungeon","lautes brüllen bsf"}}},fx={b2b015f0={q="Auf wessen Seite steht Fenrus?",a="Fenrus ist Erzmagier Arugal treu ergeben. Als persönliches Biest und Wächter des Zauberers dient er jedem verdrehten Willen, der den Meister von Burg Shadowfang antreibt, und greift jeden Eindringling an, der das obere Sanktum ohne Zögern betritt.",al={"fenrus fraktion","wem dient fenrus","fenrus loyalitäten"}},["01e73d00"]={q="Warum ist Fenrus in Burg Shadowfang?",a="Fenrus streift durch das Hauptarbeitszimmer direkt neben Arugals privaten Gemächern. Er fungiert sowohl als Haustier als auch als monströser Wachhund, der dort platziert wurde, um jeden zu zerfleischen, der versucht, in das innere Sanktum des Erzmagiers einzudringen.",al={"warum ist fenrus hier","fenrus standort zweck","warum bewacht fenrus das arbeitszimmer"}}},fp="19,322,29.436.0,15.369.0,21.397.1,32.260.0,26.167.0,33.157.0,54.234.0,47.174.0,55.191.0"}
P.entries["npc:field-marshal-snowfall"] = {n="Feldmarschall Schneefall",s="Feldmarschall Schneefall ist ein zwergischer Militäroffizier, der im Military Ward von Eisenschmiede stationiert ist, um die Kriegsanstrengungen der Allianz gegen die erstarkende Bedrohung durch die Silithiden zu koordinieren. Angesichts eines uralten Übels, das sich im südlichen Sand von Silithus regt, überwacht er die gewaltigen logistischen Maßnahmen, die zur Ausrüstung der verbündeten Armeen erforderlich sind. Snowfall erfasst gespendete Rohstoffe und belohnt jene, die den Vorbereitungen des Reiches auf den Krieg beistehen.",h="Feldmarschall Schneefall ist ein zwergischer Militäroffizier, der im Military Ward von Eisenschmiede...",kw={"ahn'qiraj","feldmarschall schneefall","eisenschmiede","military ward","abzeichen","silithus","snowfall","kriegsanstrengungen"},ang={["faction:Alliance"]="Snowfall verkörpert den geeinten industriellen und militärischen Willen der Allianz und ruft jedes Volk von Sturmwind bis Darnassus dazu auf, seine Lagerhäuser zu leeren und sich auf die bevorstehende Schlacht vorzubereiten.",["race:Dwarf"]="Im Kriegsviertel der Großen Schmiede stationiert, spricht Snowfall voller Stolz davon, die Schöpfungen der Titanen gegen eine uralte, tief sitzende Verderbnis zu verteidigen."},sec={{t="Rüstmeister der Kriegsanstrengungen von Ahn'Qiraj",b="Feldmarschall Schneefall hält im Military Ward von Eisenschmiede Wache und fungiert als zentraler Koordinator für die Mobilmachung der Allianz gegen Ahn'Qiraj. Er betrachtet den heraufziehenden Konflikt nicht bloß als Grenzplänkelei, sondern als entscheidenden Kampf gegen einen uralten Feind, der allen Schöpfungen der Titanen feindselig gegenübersteht. Snowfall überwacht atemberaubende Vorratslager – Millionen von Verbänden, Tonnen von Metallbarren, Leder, Kräutern und Rationen, die von Abenteurern gesammelt wurden –, um sicherzustellen, dass die Streitkräfte der Allianz bewaffnet, gerüstet und versorgt sind, wenn der Marsch gen Süden nach Silithus beginnt."},{t="Der Weg nach Silithus",b="Die Mobilmachung einer ganzen Fraktion erfordert die Abstimmung zwischen Schmieden, Sammlern, Köchen und Soldaten in jedem Territorium der Allianz. Snowfall überwacht jede Phase dieser gewaltigen Unternehmung, nimmt Belobigungsabzeichen entgegen und händigt Freiwilligen Nachschubanforderungen aus. Sobald die benötigten Kriegsvorräte fraktionsübergreifend vollständig gesammelt sind, werden die Vorräte verpackt und nach Süden zur Burg Cenarius geschafft, um den Großangriff gegen die insektoiden Schwärme und den Alten Gott vorzubereiten, der hinter dem Skarabäuswall lauert."}},faq={{q="Wer ist Feldmarschall Schneefall?",a="Feldmarschall Schneefall ist ein hochrangiger zwergischer Kommandant mit Sitz im Military Ward von Eisenschmiede. Er ist damit beauftragt, die umfassende Vorratssammlung der Allianz für den bevorstehenden Krieg gegen die Qiraji in Silithus zu überwachen und zu bilanzieren.",al={"snowfall rolle","wer ist snowfall","feldmarschall snowfall lore"}},{q="Warum sammelt die Allianz so viele Vorräte?",a="Eine uralte Macht jenseits der Tore von Ahn'Qiraj bedroht Kalimdor. Um einen erfolgreichen Feldzug durch die unbarmherzigen Wüsten von Silithus zu führen, muss die Allianz gewaltige Reserven an Rüstungen, Metallbarren, medizinischen Verbänden, Nahrungsmitteln und Kräutern anhäufen, bevor ihre Armeen ausrücken können.",al={"warum stoff spenden","zweck der kriegsanstrengungen","warum kriegsmaterial"}},{q="Wohin gelangen die gesammelten Materialien, sobald alles abgeschlossen ist?",a="Sobald sowohl die Allianz als auch die Horde ihre gesamten Sammelkontingente erfüllt haben, transportieren Karawanen und Nachschubschiffe die riesigen Vorräte zur Burg Cenarius in Silithus, wo die vereinten Streitkräfte ihr vorgeschobenes Aufmarschgebiet errichten.",al={"wohin kommen die vorräte","was geschieht mit den vorräten"}},{q="Wofür werden die Abzeichen für Kriegsmaterial verwendet?",a="Abzeichen werden an Unterstützer verliehen, die benötigte Waffen und Materialien für die Kriegsanstrengungen spenden. Feldmarschall Schneefall nimmt diese Abzeichen bündelweise entgegen und belohnt pflichtbewusste Bürger der Allianz für ihre Dienste mit Nachschubkisten und Ausrüstung.",al={"abzeichen abgeben","wofür sind abzeichen"}}},fx={ec7ab6f1={q="Auf wessen Seite steht Feldmarschall Schneefall?",a="Feldmarschall Schneefall ist ein loyaler Kommandant der Allianz. Stationiert im Military Ward der Eisenschmiede, beaufsichtigt er die fraktionsweite Logistik und Materialbeschaffung, die erforderlich ist, um eine gemeinsame Offensive in Kalimdor aufzustellen. Obwohl dieser Feldzug eine schwierige parallele Zusammenarbeit mit der Horde erfordert, um genügend Vorräte anzuhäufen, liegt Schneefalls Loyalität fest bei den Königreichen der Großen Allianz.",al={"feldmarschall schneefall allianz oder horde","schneefall fraktion","wem dient schneefall"}},e1b72348={q="Was will Feldmarschall Schneefall?",a="Schneefall möchte atemberaubende Mengen an Rohstoffen, Verbänden, Metallbarren, Kräutern und Nahrungsvorräten aus den gesamten Landen der Allianz anhäufen. Sein Ziel ist es sicherzustellen, dass die stehende Armee, die in der rauen Wüste von Silithus eintrifft, bei der Öffnung der Tore von Ahn'Qiraj über jede Waffe, jeden Trank und jede Ration verfügt, die nötig ist, um C'Thuns Legionen standzuhalten, ohne durch Erschöpfung zusammenzubrechen.",al={"ziel von feldmarschall schneefall","was benötigt schneefall","objektive von schneefall"}},a597c3d5={q="Warum ist Feldmarschall Schneefall in Eisenschmiede?",a="Schneefall hat sein Kommando im Military Ward von Eisenschmiede aufgeschlagen, da die Zwergenstadt im Gebirge als zentraler Knotenpunkt für Industrie und Handel der Allianz dient. Von hier aus kann er Frachtlisten verfolgen, eingehende Materialien koordinieren, die von Bürgersoldaten gesammelt wurden, und den Berg an Vorräten zusammenstellen, bevor sie über das Meer zu den Bereitstellungsgebieten in Silithus verschifft werden.",al={"warum ist schneefall in eisenschmiede","schneefall military ward","warum ist feldmarschall schneefall hier"}}},fp="22,407,37.558.0,20.505.0,30.238.0,48.269.0,49.224.0,47.239.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="Feldmarschall Steinsteg",s="Feldmarschall Steinsteg ist eine hochrangige Offizierin der Allianz, die nahe dem Eingang von Sturmwind stationiert ist. Neben den Toren von Sturmwind im Tal der Helden postiert, überwacht sie gemeinsam mit General Marcus Jonathan die Verteidigung der Stadt und dient als Anlaufstelle für bedeutende kriegerische Triumphe.",h="Feldmarschall Steinsteg ist eine hochrangige Offizierin der Allianz, die nahe dem Eingang von Sturmwind...",kw={"feldmarschall","tore","der herrscher von blackrock","marcus jonathan","nefarian","steinsteg","sturmwind","das tal der helden"},ang={["class:Warrior"]="Als eine der obersten militärischen Befehlshaberinnen an den Stadttoren genießt Feldmarschall Steinsteg den Respekt der Frontsoldaten, die nach hohem kriegerischem Ansehen innerhalb der Allianz streben.",["faction:Alliance"]="Schulter an Schulter mit General Marcus Jonathan verkörpert Steinsteg die unerschütterliche Wachsamkeit des Allianz-Militärs, das Sturmwind vor Invasionen von außen beschützt."},sec={{t="Ein Bollwerk an den Toren",b="Gleich hinter dem hoch aufragenden Eingang des Tals der Helden hält Feldmarschall Steinsteg unter dem östlichen Torbogen nahe den Haupttoren Wache. Ihr hoher Rang innerhalb des Militärs der Großen Allianz stellt sie in die obersten Riegen der strategischen Führung Sturmwinds, wo sie in enger Abstimmung mit General Marcus Jonathan agiert. Von diesem markanten Aussichtspunkt aus beobachtet sie den Strom von Verteidigern, Reisenden und heimkehrenden Champions, die in die Hauptstadt ziehen, stets bereit, die Garnison zu formieren, sollten Bedrohungen den äußeren Verteidigungsring durchbrechen."},{t="Überbringerin von Trophäen",b="Über ihre zeremoniellen und defensiven Pflichten am Stadttor hinaus nimmt Feldmarschall Steinsteg entscheidende Berichte und Beutestücke aus Feldzügen gegen die größten Widersacher des Königreichs entgegen. Hochrangige Befehlshaber verlassen sich auf Offiziere wie Steinsteg, um wichtige Informationen zu überprüfen und monumentale Siege auf dem Schlachtfeld zu würdigen, darunter die Niederlage von Kriegsherren und Ungeheuern, die in den Klüften des Schwarzfels nisten."}},faq={{q="Wo befindet sich Feldmarschall Steinsteg?",a="Sie steht unter einem Torbogen im nordöstlichen Teil des Tals der Helden in Sturmwind, direkt rechts von General Marcus Jonathan, wenn Ihr durch die Stadttore eintretet.",al={"steinsteg aufenthaltsort","wo ist feldmarschall steinsteg","steinsteg finden"}},{q="Welche Rolle spielt Feldmarschall Steinsteg in Sturmwind?",a="Sie ist eine hochrangige Militäroffizierin der Allianz, die General Marcus Jonathan bei der Verteidigung von Sturmwinds Haupttor unterstützt und als Empfangsoffizierin für bemerkenswerte militärische Berichte sowie bedeutende Siegestrophäen dient, die von Champions der Allianz zurückgebracht werden.",al={"was macht steinsteg","steinsteg funktion","wer ist feldmarschall steinsteg"}},{q="Welcher Rang ist ein Feldmarschall in der Allianz?",a="Feldmarschall ist einer der höchsten Offiziersränge in der militärischen Kommandostruktur der Großen Allianz, direkt unter dem Großmarschall angesiedelt. Offiziere dieses Ranges beaufsichtigen bedeutende taktische Einsätze, Stadtverteidigungssektoren und strategische Garnisonen.",al={"allianz feldmarschall rang","welchen rang hat steinsteg"}},{q="An welchen bedeutenden Quests ist Feldmarschall Steinsteg beteiligt?",a="Sie ist die Offizierin, die den Bericht und die Trophäe für „Der Herrscher des Schwarzfels“ entgegennimmt und damit Nefarians Fall bestätigt, wenn Abenteurer der Allianz den Kopf des Drachen zu den Toren von Sturmwind schleppen.",al={"steinsteg quests","der herrscher von blackrock questabgabe"}}},fx={["63c0e4ac"]={q="Wer ist Feldmarschall Steinsteg?",a="Feldmarschall Steinsteg ist eine hochrangige menschliche Kommandantin des Militärs der Allianz, die an den Toren von Sturmwind stationiert ist. An der Seite der Führung der Stadt im Tal der Helden überwacht sie kritische Verteidigungsmaßnahmen und fungiert als eine der militärischen Autoritäten des Königreichs.",al={"wer ist steinsteg","identität von feldmarschall steinsteg","hintergrund von steinsteg"}},["05caa28c"]={q="Auf wessen Seite steht Feldmarschall Steinsteg?",a="Feldmarschall Steinsteg ist dem Königreich Sturmwind und der Großen Allianz vollkommen loyal. Sie dient direkt unter den obersten Kommandanten des Königreichs und hilft dabei, die Hauptstadt vor äußeren Bedrohungen zu schützen.",al={"fraktion von steinsteg","loyalität von steinsteg","wem dient steinsteg"}},d0356b7c={q="Warum ist Feldmarschall Steinsteg hier?",a="Sie ist im Tal der Helden stationiert, um am Haupteingang der Hauptstadt Wache zu halten, General Marcus Jonathan bei der Koordination der Streitkräfte von Sturmwind zu unterstützen und militärische Berichte mit hoher Priorität sowie Trophäen, die von Champions der Allianz mitgebracht werden, entgegenzunehmen.",al={"warum ist steinsteg in sturmwind","warum ist steinsteg an den toren","steinsteg tal der helden"}},a46f624c={q="Was will Feldmarschall Steinsteg?",a="Steinsteg strebt die vollständige Verteidigung von Sturmwind und den Sieg über die größten Widersacher des Reiches an. Sie verifiziert eifrig Beweise für bedeutende Siege, die von Abenteurern gebracht werden, um die Sicherheit des Königreichs zu gewährleisten.",al={"ziele von steinsteg","was will feldmarschall steinsteg","beweggründe von steinsteg"}},af024441={q="Mit wem ist Feldmarschall Steinsteg verbunden?",a="Sie arbeitet eng mit General Marcus Jonathan zusammen, dem Kommandanten der Stadtverteidigung von Sturmwind, und ist Teil des umfassenderen militärischen Apparats von Hochlord Bolvar Fordragon, der das Reich des jungen Königs Anduin Wrynn schützt.",al={"verbindungen von steinsteg","mit wem arbeitet steinsteg zusammen","steinsteg marcus jonathan"}}},fp="25,285,22.552.0,18.432.0,43.180.0,54.251.0,45.239.0,52.195.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="Erster Maat Fitzsimmons",s="Erster Maat Fitzsimmons ist ein zerlumpter, stinkender Seemann, der seine Tage mit Trinken vor der Tiefenwassertaverne im Hafen von Menethil verbringt. Einst Erster Maat an Bord der Wave Mistress aus der Dritten Flotte von Kul Tiras, ist er der einzig bekannte lebende Überlebende der Zerstörung der Flotte während des Zweiten Krieges. Von der Tragödie heimgesucht, sucht er nach willigen Abenteurern, die sich den rastlosen Geistern seiner ertrunkenen Kameraden stellen.",h="Erster Maat Fitzsimmons ist ein zerlumpter, stinkender Seemann, der seine Tage mit Trinken vor der...",kw={"tiefenwassertaverne","auge von paleth","erster maat fitzsimmons","fitzsimmons","kul tiras","die verlorene flotte","der hafen von menethil","die dritte flotte","wave mistress"},ang={["faction:Alliance"]="Fitzsimmons steht für ein tragisches Kapitel in der Marinegeschichte der Allianz und erinnert Helden an die verheerenden Verluste, die sie gegen die versklavte Drachenarmada der Horde erlitten haben.",["race:Human"]="Als Veteran von Kul Tiras teilt Fitzsimmons tiefe kulturelle Bande mit dem seefahrenden Menschenkönigreich, das während des Zweiten Krieges große Opfer brachte, um Lordaeron zu verteidigen."},sec={{t="Ein gebrochener Seemann",b="Erster Maat Fitzsimmons lümmelt in der feuchten Salzluft des Hafens von Menethil vor der Tiefenwassertaverne herum und ist ein Mann, den man leicht übersieht – oder angesichts seines ungewaschenen Gestanks gänzlich meidet. Für die meisten Gäste ist er nur ein weiterer gebrochener alter Seebär, der seine Erinnerungen im Alkohol ertränkt. Doch wer bereit ist, sich zu ihm zu setzen und zuzuhören, erfährt erschütternde Geschichten von einer stolzen Flotte, die durch Feuer und Klauen zu Fall gebracht wurde."},{t="Der Fall der Dritten Flotte",b="Während des Zweiten Krieges diente Fitzsimmons als Erster Maat an Bord der Wave Mistress, die Teil der zur Bekämpfung der Horde entsandten Dritten Flotte von Kul Tiras war. Vor der Küste des Sumpflands geriet die Flotte in einen Hinterhalt und wurde von versklavten roten Drachen verbrannt, die von Dragonmaw-Orcs geflogen wurden. Die Schiffe wurden zerschmettert und versenkt, sodass Fitzsimmons als einziger Mann lebend an Land kroch."},{t="Der fortwährende Fluch",b="Das Überleben des Drachenfeuers brachte Fitzsimmons keinen Frieden. Die Überreste der Schiffe, die heute als Die verlorene Flotte bekannt sind, werden von seinen ehemaligen Schiffskameraden heimgesucht, die als verfluchte Untote auferstanden und in ihren wässrigen Gräbern keine Ruhe finden. Getrieben von Schuldgefühlen und Schrecken wirbt Fitzsimmons Reisende an, um die untoten Seeleute zu erlösen und uralte Relikte zu bergen, die das Böse, das ihre Seelen bindet, endlich aufheben könnten."}},faq={{q="Wer ist Erster Maat Fitzsimmons?",a="Er ist ein alter Seemann aus Kul Tiras und ehemaliger Erster Maat der Wave Mistress. Er überlebte den katastrophalen Untergang der Dritten Flotte von Kul Tiras während des Zweiten Krieges und vertrinkt nun seine Tage vor der Tiefenwassertaverne im Hafen von Menethil.",al={"fitzsimmons lore","wer ist fitzsimmons","erster maat fitzsimmons"}},{q="Was geschah mit seinem Schiff?",a="Die Wave Mistress und der Rest der Dritten Flotte gerieten während des Zweiten Krieges in einen Hinterhalt versklavter roter Drachen, die von Angehörigen des Dragonmaw-Klans geritten wurden. Die Schiffe verbrannten und zerschellten am Riff vor der Küste des Sumpflands.",al={"was geschah mit wave mistress","dritte flotte zerstoerung","warum sank sein schiff"}},{q="Wo befindet sich Die verlorene Flotte?",a="Die zerschmetterten Rümpfe der Flotte liegen vor der felsigen Küste nördlich des Hafens von Menethil im Sumpfland unter Wasser und werden nun von Murlocs und den rastlosen Geistern ertrunkener Seeleute bewacht.",al={"die verlorene flotte standort","wo liegen die versunkenen schiffe","fitzsimmons schiff standort"}},{q="Warum möchte er, dass Abenteurer gegen seine alte Mannschaft kämpfen?",a="Die ertrunkenen Seeleute der Dritten Flotte starben nicht einfach, sondern kehrten als verfluchte, gepeinigte Untote zurück. Fitzsimmons sucht mutige Reisende, um ihnen Frieden zu schenken und die Artefakte zu bergen, die ihre Seelen gefangen halten.",al={"verfluchte besatzung quest lore","warum seine besatzung toeten"}},{q="Was ist das Auge von Paleth?",a="Es ist ein uraltes, mächtiges Artefakt, das an Bord der Dritten Flotte mitgeführt wurde. Seine dunkle Macht ist an den Fluch gebunden, der auf den versunkenen Seeleuten lastet, sodass seine Bergung entscheidend dafür ist, der ertrunkenen Flotte Frieden zu schenken.",al={"auge von paleth","paleth relikt"}},{q="Warum riecht Fitzsimmons so streng?",a="Nachdem er beim Untergang seiner Flotte alles verloren hatte, lebt Fitzsimmons seit Jahren in betrunkener Verwahrlosung vor der Tiefenwassertaverne, trägt meerwassergetränkte Lumpen und wäscht sich nur selten.",al={"warum riecht fitzsimmons","fitzsimmons gestank"}}},fx={c1574e2a={q="Auf wessen Seite steht Erster Maat Fitzsimmons?",a="Fitzsimmons fühlt sich durch seine früheren Loyalitäten zu Kul Tiras und The Third Fleet der Allianz verbunden. Heute dient er jedoch keiner Nation und keinem Herrn mehr. Er ist lediglich ein gebrochener Seemann, der seine Tage außerhalb der Tiefenwassertaverne im Hafen von Menethil vertrinkt und sich darauf verlässt, dass vorbeiziehende Abenteurer der Allianz die verfluchten Überreste seiner Vergangenheit beseitigen.",al={"fraktion von fitzsimmons","wem dient fitzsimmons","gehört fitzsimmons zur allianz"}},["468babc7"]={q="Warum ist Erster Maat Fitzsimmons im Hafen von Menethil?",a="Fitzsimmons landete im Hafen von Menethil, weil er der einzige Überlebende der The Third Fleet von Kul Tiras ist, die während des Zweiten Krieges von Orc-Drachenreitern entlang der Küste des Sumpflands vernichtet wurde. Geplagt vom grausamen Schicksal seiner Kameraden hat er sich auf die Stufen vor der Tiefenwassertaverne zurückgezogen, um sein Trauma in Alkohol zu ertränken.",al={"warum ist fitzsimmons hier","grund für fitzsimmons im hafen von menethil","warum ist fitzsimmons vor der taverne"}},["786aa53e"]={q="Mit wem ist Erster Maat Fitzsimmons verbunden?",a="Fitzsimmons war der erste Maat an Bord der Wave Mistress, einem Schiff von Kul Tiras, das in der The Third Fleet diente. Er bleibt eng mit seinem alten Kapitän und seinen Schiffskameraden verbunden, die nun als verfluchte Untote, gebunden durch dunkle Relikte wie The Eye of Paleth, die Schiffswracks vor der Küste heimsuchen.",al={"verbindungen von fitzsimmons","schiff von fitzsimmons","crew von fitzsimmons"}}},fp="22,397,15.367.0,27.366.0,19.390.1,30.232.0,26.212.0,32.182.0,51.206.0,26.197.0,34.173.0"}
P.entries["npc:fizzle-brassbolts"] = {n="Fizzel Kupferbolz",s="Fizzel Kupferbolz ist ein angesehener gnomischer Ingenieur, der auf den heißen Salzebenen der Illusionenrennbahn in Tausend Nadeln stationiert ist. Zusammen mit seinem Rivalen, dem Goblin Pozzik, gründete Fizzle die Rennbahn mit, um gnomische Präzisionstechnik gegen leichtsinnigen Goblin-Einfallsreichtum in Hochgeschwindigkeitsrennen mit Raketenautos antreten zu lassen. Er ist ständig auf der Suche nach Teilen, Treibstoff und seltsamen Wüstenreagenzien, um sein Rennteam am Laufen zu halten.",h="Fizzel Kupferbolz ist ein angesehener gnomischer Ingenieur, der auf den heißen Salzebenen der...",kw={"brassbolts","fizzle","mega","illusionenrennbahn","pozzik","raketenauto","die schimmernde ebene","tausend nadeln"},ang={["faction:Alliance"]="Obwohl er in einer neutralen Geschwindigkeitszone operiert, bietet Fizzle Reisenden der Allianz, die nach Süden in Richtung Tanaris ziehen, ein freundliches Gesicht und mechanische Arbeit.",["profession:Engineering"]="Ingenieurkollegen werden Fizzles Engagement bei der Optimierung des Raketenantriebs und dem Entwurf modernster Automobildesigns unter rauen Wüstenbedingungen zu schätzen wissen.",["race:Gnome"]="Fizzle trägt die Ehre von ganz Gnomeregan in die Wüste, fest entschlossen zu beweisen, dass gnomische Präzision den Goblin-Leichtsinn übertrifft."},sec={{t="Eine Frage von Prinzipien und Kolben",b="Draußen in der flirrenden Hitze der schimmernden Ebene weichen politische Bündnisse und alte Fehden dem Dröhnen motorisierter Triebwerke. Fizzel Kupferbolz kam mit einem Ziel hierher: ein für alle Mal zu beweisen, dass gnomische Handwerkskunst der plumpen Goblin-Bastelei weit überlegen ist. Zusammen mit seinem Goblin-Gegenpart Pozzik half er dabei, die Illusionenrennbahn anzulegen und brachte Rennwagen, Boxencrews und Zuschauer in das ansonsten trostlose Becken."},{t="Basteln auf der Ebene",b="Über trockene Salzpfannen bei halsbrecherischer Geschwindigkeit zu rasen, erfordert ständige Improvisation. Als begeistertes Mitglied der Mechanical Engineers' Guild of Azeroth (MEGA) schreckt Fizzle nicht vor unorthodoxen Experimenten zurück. Egal ob er flüchtige Mischungen testet, die aus dem Gift der lokalen Kreaturen gebraut wurden, oder Reisende damit beauftragt, mechanische Ersatzteile zu besorgen – Fizzle ist entschlossen, die Räder seines Fahrers schneller drehen zu lassen als jedes explosive Goblin-Gerät."}},faq={{q="Wer ist Fizzel Kupferbolz?",a="Fizzel Kupferbolz ist ein gnomischer Meisteringenieur und leitender Organisator für das gnomische Rennteam, das auf der Illusionenrennbahn in Tausend Nadeln stationiert ist.",al={"wer ist fizzle","fizzel kupferbolz hintergrundgeschichte","gnom auf der rennbahn"}},{q="Warum kam Fizzle auf die schimmernde Ebene?",a="Er kam, um eine technische Debatte mit dem Goblin-Ingenieur Pozzik darüber beizulegen, wessen Rennen sich mit überlegener Technik brüsten kann. Gemeinsam gründeten sie die Illusionenrennbahn, um ihre Raketenautos auf dem flachen Salzbecken im direkten Duell zu testen.",al={"warum ist fizzle hier","zweck der rennbahn","warum wurde die rennbahn gebaut"}},{q="Was ist die MEGA?",a="MEGA steht für die Mechanical Engineers' Guild of Azeroth. Fizzle ist ein engagiertes Mitglied und vertritt das Engagement der Gilde für akribisches Design und technische Verfeinerung.",al={"fizzles gilde","gilde der maschinenbauingenieure","was ist die mega"}},{q="Warum benötigt Fizzle Kreaturengift für Rennwagen?",a="Fizzle experimentiert ständig mit lokalen Reagenzien, um leistungsstarke Motorenflüssigkeiten, Additive und Beschleuniger zu formulieren, die seinen Raketenautos einen Vorteil gegenüber Pozziks Maschinen verschaffen können.",al={"quest salziges gift","gift als renntreibstoff","warum braucht er gift"}},{q="Kämpft Fizzle gegen die Goblins?",a="Nicht mit Waffen. Obwohl eine tiefe berufliche Eifersucht zwischen ihnen herrscht, wahren Fizzle und Pozzik einen unangenehmen, neutralen Waffenstillstand auf der Rennbahn, um sich rein auf den Hochgeschwindigkeitswettbewerb zu konzentrieren.",al={"ist fizzle goblins gegenüber feindselig","streit zwischen fizzle und pozzik"}},{q="Wer ist Pilot Langbart?",a="Pilot Langbart ist ein zwergischer Flieger und ein persönlicher Freund der Familie Brassbolts, der eine Vorliebe für gefährliche Maschinen und Wüstenstrecken teilt.",al={"verbindung zu pilot langbart","fizzles freund, der pilot"}}},fx={["5c8328af"]={q="Auf wessen Seite steht Fizzel Kupferbolz?",a="Fizzel Kupferbolz vertritt die Gnome und die Mechanical Engineers' Guild of Azeroth (MEGA). Er ist gegenüber Reisenden der Allianz und der Horde neutral und unterhält hier in der schimmernden Ebene eine funktionierende Arbeitsbeziehung zu Goblin-Ingenieuren wie Pozzik. Während er leidenschaftlich loyal dazu ist, die Überlegenheit gnomischer Technik gegenüber der der Goblins zu beweisen, konzentriert sich ihre Rivalität auf die Illusionenrennbahn und nicht auf offene Kriegsführung.",al={"gehört fizzel zur allianz","fraktion von fizzel kupferbolz","für wen arbeitet fizzel"}},["4ec804ad"]={q="Was will Fizzel Kupferbolz?",a="Fizzel will nichts weiter, als die absolute technische Überlegenheit der Gnome gegenüber der Goblin-Technologie zu beweisen. Zu diesem Zweck hat er zusammen mit seinem Goblin-Rivalen Pozzik die Illusionenrennbahn mitbegründet. Er konzentriert sich voll und ganz auf die Entwicklung schnellerer Raketenautos, die Beschaffung exotischer Treibstoffzutaten wie das salzige Gift der Skorpide der schimmernden Ebene und darauf, das Goblin-Team über die Salzwüste zu schlagen.",al={"was will fizzel","ziel von fizzel kupferbolz","warum nimmt fizzel am rennen teil"}}},fp="17,397,33.444.0,22.443.0,25.146.0,44.222.0,13.172.0,50.179.0,38.181.0,23.146.0"}
P.entries["npc:fleet-master-seahorn"] = {n="Flottenmeister Seehorn",s="Flottenmeister Seehorn ist ein erfahrener Tauren-Seefahrer, der als Marinekommandant der Blackwater Raiders in Beutebucht dient. Stationiert auf dem oberen Balkon der Salty Sailor Tavern an der Seite von Baron Revilgaz, überwacht er die maritime Verteidigung des Goblin-Hafens. Seine Hauptaufgabe besteht darin, den Hafen vor der drohenden Gefahr durch ihre geschworenen Feinde, die Blutsegelbukaniere, zu schützen.",h="Flottenmeister Seehorn ist ein erfahrener Tauren-Seefahrer, der als Marinekommandant der Blackwater Raiders...",kw={"blackwater raiders","blutsegel","beutebucht","die faldirbucht","firallon","flottenmeister seehorn","revilgaz","salty sailor tavern","seehorn","die wilden ufer"},ang={["class:Rogue"]="Schurken, die in Beutebucht operieren, finden in Seehorn das Zentrum der Küstenspionage, der verdeckte Überfälle auf die Kriegsschiffe der Blutsegel organisiert und feindliche Befehle abfängt.",["faction:Horde"]="Obwohl Seehorn ein Taure ist, gilt seine Loyalität uneingeschränkt dem Steamwheedle-Kartell und den Blackwater Raiders, und er verhält sich gegenüber Reisenden der Horde und der Allianz gleichermaßen neutral.",["race:Tauren"]="Seehorn ist einer der äußerst seltenen Tauren, welche die Ebenen im Landesinneren von Kalimdor hinter sich gelassen haben, um das offene Meer zu beherrschen und als Flottenmeister für einen neutralen Goblin-Hafen zu dienen."},sec={{t="Ein Bulle auf hoher See",b="Während Tauren in ganz Kalimdor als Ebenenbewohner bekannt sind, wählte Flottenmeister Seehorn ein völlig anderes Leben auf dem Meer. In Piratengewänder gekleidet, befehligt er die Flotte der Blackwater Raiders, den privaten Marinezweig der Operationen des Steamwheedle-Kartells im Schlingendorntal. Hoch oben auf der Salty Sailor Tavern arbeitet Seehorn Schulter an Schulter mit Baron Revilgaz und koordiniert Schifffahrtsrouten, Mannschaftseinsätze sowie die Küstenverteidigung für den gesetzlosen, aber streng verwalteten Hafen von Beutebucht."},{t="Verteidigung der Bucht",b="Seehorns größte anhaltende Sorge gilt den Blutsegelbukanieren, die befestigte Lager entlang der südlichen Wilden Ufer errichtet und Kriegsschiffe vor der Küste vor Anker gelegt haben. Als Berichte enthüllen, dass Flottenmeister Firallon und die Führung der Blutsegel einen direkten Angriff zur Plünderung von Beutebucht planen, ergreift Seehorn offensive Maßnahmen. Indem er Söldner entsendet, um feindliche Korrespondenz abzufangen und Firallon, Keelhaul sowie Stillwater an Bord ihres Flaggschiffs auszuschalten, bewahrt Seehorn den Hafen erfolgreich vor der völligen Zerstörung."},{t="Ein wachsames Auge über die Meere",b="Neben der Abwehr von Piratenüberfällen leitet Seehorn verschiedene Handels- und Bergungsunternehmungen in den Östlichen Königreichen. Er koordiniert die Bergung verlorener, versunkener Schätze vor der Küste von Arathi nahe der Faldirbucht und arbeitet mit Bergungstauchern zusammen, um Elfenrelikte zu sichern. Zudem hält er Revilgaz über lukrative Gelegenheiten in der Stadt auf dem Laufenden, wie etwa Angelwettbewerbe und den örtlichen Handel, um sicherzustellen, dass die Flotte der Blackwater Raiders stets gut finanziert bleibt und rivalisierenden Unternehmungen einen Schritt voraus ist."}},faq={{q="Wo befindet sich Flottenmeister Seehorn?",a="Er befindet sich im obersten Stockwerk und auf dem Balkon der Salty Sailor Tavern in Beutebucht, direkt neben Baron Revilgaz mit Blick auf die Docks.",al={"wo ist seehorn","seehorn aufenthaltsort","seehorn finden"}},{q="Warum dient ein Taure als Flottenmeister der Piraten?",a="Obwohl die meisten Tauren eng mit den Ebenen und spirituellen Traditionen von Mulgore verbunden bleiben, verschrieb sich Seehorn der Seefahrt und dem Leben als Marinesöldner. Sein seemännisches Können und sein gebieterisches Auftreten brachten ihm die Führung der Blackwater Raiders unter Baron Revilgaz ein.",al={"tauren pirat","warum ist seehorn ein pirat","tauren in beutebucht"}},{q="In welcher Beziehung steht Seehorn zu Baron Revilgaz?",a="Seehorn ist Baron Revilgaz' Stellvertreter und der Flottenkommandant seiner Blackwater Raiders. Während Revilgaz Politik, Handel und Finanzen leitet, überwacht Seehorn die Flotte, taktische Aufklärung und defensive Militäroperationen für Beutebucht.",al={"seehorn und revilgaz","ist seehorn revilgaz leibwaechter","wer arbeitet fuer revilgaz"}},{q="Wer sind die Blackwater Raiders?",a="Die Blackwater Raiders sind eine private Korsarenflotte im Dienste des Steamwheedle-Kartells mit Stützpunkt in Beutebucht. Anders als gesetzlose Räuber, die wahllos plündern, fungieren sie als sanktionierte Seestreitmacht, die Goblin-Handelsinteressen schützt und die Ordnung in den südlichen Meeren aufrechterhält.",al={"blackwater raiders","welcher fraktion gehoert seehorn an","beutebucht piraten"}},{q="Warum will Seehorn die Blutsegelbukaniere aufhalten?",a="Die Blutsegelbukaniere sind die bitteren Rivalen der Blackwater Raiders. Angeführt von Flottenmeister Firallon haben die Blutsegel Lager entlang der Wilden Ufer errichtet und beabsichtigen, Beutebucht selbst zu erobern. Seehorn arbeitet unentwegt daran, ihren Invasionsplänen zuvorzukommen.",al={"seehorn gegen blutsegel","blutsegel konflikt","warum gegen blutsegel kaempfen"}},{q="Hat Seehorn geschäftliche Beziehungen außerhalb des Schlingendorntals?",a="Ja. Seehorn arbeitet mit Bergungsagenten wie Doktor Draxlegauge und Shakes O'Breen zusammen, um verlorene Fracht und Elfenschätze zu bergen, die nahe der Faldirbucht vor dem Arathihochland gesunken sind, und lässt wertvolle Artefakte zu seinem Posten in Beutebucht bringen.",al={"faldirbucht seehorn","seehorn versunkener schatz","arathi quests seehorn"}}},fp="20,378,23.506.0,17.524.1,20.470.0,38.143.0,49.254.0,51.250.0,31.277.0,55.254.0,57.242.0"}
P.entries["npc:foggy-mackreel"] = {n="Dunst MacKreel",s="Dunst MacKreel ist ein unerschrockener Zwerg, der sich in misslicher Lage auf dem zerstörten unteren Mauerwerk des Thandol-Übergangs befindet. Trotz des zertrümmerten Steinwerks unter seinen Füßen und des schwindelerregenden Abgrunds darunter gilt seine einzige wirkliche Sorge der Zustellung seiner Schwarzbrand-Lieferung nach Norden nach Süderstade.",h="Dunst MacKreel ist ein unerschrockener Zwerg, der sich in misslicher Lage auf dem zerstörten unteren...",kw={"arathi","foggy","mackreel","schwarzbrand","süderstade","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Kuriere der Allianz, die zwischen Eisenschmiede und dem nördlichen Außenposten Süderstade reisen, kreuzen oft Foggys Weg und nehmen seine gestrandete Fracht an sich, um einem Mitstreiter der Allianz zu helfen.",["race:Dwarf"]="MacKreel verkörpert die sture Entschlossenheit – und die eigentümlichen Prioritäten – der Zwerge, indem er die pünktliche Lieferung starken Alkohols weit über belanglose Kleinigkeiten wie das Stranden über einem tödlichen Abgrund stellt."},sec={{t="Gestrandet auf dem Übergang",b="Auf den zerbrochenen Pfeilern unter dem zerstörten Thandol-Übergang sitzend, scheint Dunst MacKreel von seiner gefährlichen Lage völlig unbeeindruckt zu sein. Während die Sabotage der Dunkeleisenzwerge und Kriegsschäden die gewaltige Brücke zwischen dem Sumpfland und dem Arathihochland zerrüttet zurückgelassen haben, betrachtet MacKreel seinen prekären Standplatz als bloße Unannehmlichkeit. Sein Hauptgedanke gilt nicht seiner Rettung, sondern einer ungelieferten Fuhre starken Schwarzbrands, die für die Gäste von Süderstade im Vorgebirge des Hügellands bestimmt ist. Bereitwillig heuert er vorbeikommende Abenteurer an, die geschickt genug sind, seinen Sims zu erreichen, um den Kurierdienst an seiner Statt zu vollenden."}},faq={{q="Wer ist Dunst MacKreel?",a="Dunst MacKreel ist ein exzentrischer Zwergenkurier, der auf den zerstörten Steinpfeilern unter der zerbrochenen Brücke des Thandol-Übergangs festsitzt. Trotz des tiefen Abgrunds bleibt er vollkommen ruhig und konzentriert sich darauf, seinen Schwarzbrand zustellen zu lassen.",al={"dunst mackreel","wer ist foggy","mackreel nsc"}},{q="Wo finde ich Dunst MacKreel?",a="Er befindet sich auf einer Steinplattform auf halber Höhe des zerbrochenen Mittelabschnitts des Thandol-Übergangs, die durch vorsichtiges Herabspringen vom Brückenbauwerk auf der Seite des Arathihochlands erreichbar ist.",al={"wo ist dunst mackreel","dunst mackreel standort","wie man mackreel findet"}},{q="Warum ist Dunst MacKreel dort unten?",a="Foggy landete während seiner Reisen inmitten der Trümmer des Thandol-Übergangs. Doch statt nach Rettung zu suchen, gilt seine Hauptsorge der Suche nach jemandem, der bereit ist, seine Schwarzbrandladung den restlichen Weg nach Süderstade zu bringen.",al={"warum foggy gestrandet ist","wie kam mackreel dorthin","warum er auf der brücke ist"}},{q="Welche Quest bietet Dunst MacKreel an?",a="Er bietet 'MacKreels Schwarzgebranntes' an und bittet Reisende, einen Krug seines starken Gebräus zur Taverne in Süderstade jenseits des Arathihochlands zu bringen.",al={"foggy quest","mackreel schwarzbrand quest","welche quest gibt foggy"}}},fx={["28a25d1f"]={q="Auf wessen Seite steht Dunst MacKreel?",a="Dunst MacKreel ist ein der Allianz zugewandter Zwerg. Selbst als er gefährlich auf den beschädigten Ruinen von The Thandol Span festsaß, lagen seine Loyalitäten und Geschäfte bei seinem Volk und anderen Siedlungen der Allianz, mit dem Ziel, sein starkes Gebräu in den Norden in die Hände der Leute zu bringen, die Süderstade im Vorgebirge des Hügellands halten.",al={"fraktion von dunst mackreel","gehört dunst mackreel zur allianz","seite von dunst mackreel"}},c1253653={q="Was will Dunst MacKreel?",a="Dunst MacKreel möchte, dass seine spezielle Charge selbstgebrannten Schnapses sicher nach Süderstade gebracht wird. Obwohl er auf einem zertrümmerten Pfeiler unter der Brücke gefangen ist, zeigt er erstaunlich wenig Sorge um seine eigene gefährliche Lage und ist voll und ganz damit beschäftigt, sicherzustellen, dass sein Gebräu sein Ziel im Hügelland erreicht, anstatt eine sofortige Rettung zu planen.",al={"motiv von dunst mackreel","was will dunst","ziel von dunst mackreel"}}},fp="14,264,20.583.0,22.226.0,32.183.0,33.217.0,37.143.0"}
P.entries["npc:foreman-oslow"] = {n="Großknecht Oslow",s="Großknecht Oslow ist Seenhains bedrängter Baumeister, der den Auftrag hat, die zerstörte Immerruhbrücke im Herzen des Rotkammgebirges zu reparieren. Bedrängt von der Artillerie der Schwarzfelsorcs und Gnollräubern sind seine Wiederaufbaubemühungen aufgrund verlorener Lieferungen und versunkener Ausrüstung ins Stocken geraten. Er verlässt sich stark auf reisende Abenteurer, um seine Ausrüstung zu bergen und Materialien zu beschaffen, damit Seenhain seine lebenswichtige Handelsroute wiederherstellen kann.",h="Großknecht Oslow ist Seenhains bedrängter Baumeister, der den Auftrag hat, die zerstörte Immerruhbrücke im...",kw={"schwarzfels","immerruhbrücke","großknecht oslow","goldhain","seenhain","oslow","rotkammgebirge","werkzeugkasten"},ang={["faction:Alliance"]="Seenhains durchtrennte Brücke lässt die östliche Grenze ungeschützt, weshalb Oslows Wiederherstellungsbemühungen eine strategische Notwendigkeit zur Sicherung der Allianzgrenze darstellen.",["profession:Mining"]="Oslow ist auf Rohmaterialien, Metallarbeiten und Steinbruchlieferungen angewiesen, um geborstenes Mauerwerk wieder aufzubauen, was ihn eng an lokale Mineralienlieferungen bindet."},sec={{t="Eine zweigeteilte Stadt",b="Großknecht Oslow steht am geborstenen Mauerwerk der Immerruhbrücke vor einer gewaltigen Aufgabe. Die Brücke ist die Lebensader von Seenhain; sie überspannt die Weite des Immerruhsees und verbindet die westlichen Straßen nach Elwynn mit den östlichen Ufern. Schwarzfelsorcs, die von den Felsen von Steinwacht herabstießen, zielten auf den Übergang ab, um die Logistik und die Truppenbewegungen der Stadt zu lähmen, wodurch die Siedlung zersplittert und verwundbar zurückblieb."},{t="Versunkener Stahl und gestohlener Stein",b="Jeder Versuch Oslows, den Wiederaufbau voranzutreiben, scheint vom Unglück verfolgt zu sein. Als die Brücke fiel, wurden seine Ersatzwerkzeuge auf dem Landweg von Goldhain transportiert und auf eine Seefähre verladen. Orcische Katapultbesatzungen nahmen das Schiff ins Visier und beförderten seinen schweren Eisenwerkzeugkasten direkt auf den schlammigen Grund des Immerruhsees. Zu allem Überfluss überfielen einheimische Rotkammgnolle seine Versorgungswagen und erbeuteten Bauholz und Mörtelstifte, die für die Errichtung der Bögen notwendig waren."}},faq={{q="Wer ist Großknecht Oslow?",a="Großknecht Oslow ist ein menschlicher Steinmetz und Baumeister, der in Seenhain stationiert ist. Er ist der leitende Handwerker, der für die Instandhaltung und den Wiederaufbau der Immerruhbrücke verantwortlich ist.",al={"großknecht oslow","wer ist oslow","baumeister seenhain"}},{q="Warum ist die Immerruhbrücke zerstört?",a="Die Immerruhbrücke wurde von den Schwarzfelsorcs des Rotkammgebirges zerstört. Die Zerstörung des Bauwerks trennte Seenhains Hauptverkehrsader ab, schwächte die Verteidigung der Stadt empfindlich und unterbrach den einfachen Übergang zwischen dem östlichen und dem westlichen Ufer.",al={"warum ist die brücke zerstört","wer zerstörte brücke von seenhain","immerruhbrücke zerstört"}},{q="Wo sind Oslows verlorene Werkzeuge?",a="Oslows schwerer Werkzeugkasten liegt auf dem Grund des Immerruhsees. Das Boot, das ihn von Goldhain transportierte, wurde von einem Katapultbeschuss der Schwarzfelsorcs getroffen und versenkt.",al={"wo sind die werkzeuge","fundort verlorene werkzeuge","oslows werkzeugkasten"}},{q="Warum wurde die Brücke noch nicht repariert?",a="Da Katapultfeuer der Orcs seine Werkzeuge im See versenkt hat und Gnolle Baumaterialien aus eingehenden Lieferungen stehlen, fehlen Oslow die nötigen Materialien und Ausrüstungen, um die Bauarbeiten ohne Hilfe von außen wieder aufzunehmen.",al={"warum brücke nicht repariert","verzögerung brücke seenhain"}},{q="Woher stammten Oslows Vorräte ursprünglich?",a="Seine Ersatzwerkzeuge wurden ursprünglich auf einem Karren von Goldhain im Wald von Elwynn herantransportiert, bevor sie auf eine Seefähre verladen wurden, um den eingestürzten Übergang zu umgehen.",al={"herkunft nachschubwagen","woher kamen werkzeuge"}},{q="Mit welchen Bedrohungen hat Oslow zu kämpfen?",a="Oslow sieht sich ständigen Nachstellungen von zwei Seiten ausgesetzt: den Orcs des Schwarzfelsclans, die sich in den nahen Höhen verschanzt haben und deren Belagerungsmaschinen den See bombardieren, sowie umherstreifenden Gnollen, die Nachschubkonvois abfangen.",al={"feinde von oslow","wer greift die brücke an"}}},fx={cf681f3e={q="Auf wessen Seite steht Großknecht Oslow?",a="Großknecht Oslow dient dem Königreich Sturmwind und der örtlichen Gemeinde Seenhain. Als Chefbaumeister und Großknecht der Stadt liegt seine Pflicht darin, die lebenswichtige Infrastruktur des Rotkammgebirges aufrechtzuerhalten und seinen Bewohnern zu helfen, trotz der unerbittlichen Angriffe durch umliegende Blackrock-Orcs und feindselige Gnolle zu überleben.",al={"fraktion von oslow","wem dient großknecht oslow","gehört oslow zur allianz"}},["1a3f577b"]={q="Was will Großknecht Oslow?",a="Oslows Hauptziel ist es, die zerstörte The Everstill Bridge wieder aufzubauen und Seenhain mit dem Rest des Königreichs verbunden zu halten. Um dies zu erreichen, muss er verzweifelt seinen versunkenen Werkzeugkasten aus dem Der Immerruhsee bergen lassen und die Baumaterialien zurückgewinnen, die von örtlichen Gnollen in einem Hinterhalt gestohlen wurden.",al={"was will oslow","ziel von großknecht oslow","warum braucht oslow hilfe"}},["765147a2"]={q="Warum ist Großknecht Oslow in Seenhain?",a="Oslow ist am See stationiert, um öffentliche Arbeiten zu beaufsichtigen und den Wiederaufbau der The Everstill Bridge zu leiten. Die Brücke ist die Lebensader von Seenhain, doch unerbittliche feindliche Angriffe und verheerende Materialverluste lassen ihn direkt am Wasser festsitzen, wo er auf Hilfe wartet, um seine Arbeit fortzusetzen.",al={"warum ist oslow hier","zweck von oslow in seenhain","beruf von großknecht oslow"}}},fp="13,413,17.430.0,29.449.0,21.172.0,35.246.0,29.155.0,40.213.0,48.158.0,35.193.0"}
P.entries["npc:foreman-stonebrow"] = {n="Großknecht Steinbraue",s="Großknecht Steinbraue ist ein zwergischer Vorarbeiter, der die Miners' League am Gol'bolar Steinbruch im östlichen Dun Morogh vertritt. Nachdem aggressive Troggs aus dem Fels hervorbrachen und die Ausgrabungsstätte überrannten, sah er sich gezwungen, eine Verteidigung zu organisieren und Abenteurer anzuheuern, um die Gruben zu säubern.",h="Großknecht Steinbraue ist ein zwergischer Vorarbeiter, der die Miners' League am Gol'bolar Steinbruch im...",kw={"dun morogh","großknecht steinbraue","gol bolar","steinbruch gol'bolar","miners' league","stonebrow","troggs"},ang={["profession:Mining"]="Bergleute haben ein berufliches Interesse daran, Stonebrow zu helfen, da die Rückgewinnung der reichen Stein- und Erzvorkommen des Steinbruchs für die Gildenoperationen von Khaz Modan von entscheidender Bedeutung ist.",["race:Dwarf"]="Für Zwerge ist die Trogg-Invasion am Gol'bolar Steinbruch ein direkter Schlag gegen die Steinindustrie von Eisenschmiede und eine finstere Erinnerung an die uralten Bedrohungen, die unter ihrer uralten Heimat lauern."},sec={{t="Die Krise bei Gol'Bolar",b="Großknecht Steinbraue war damit beauftragt, die Arbeiten am Gol'bolar Steinbruch zu leiten, einer wichtigen Zwergenausgrabung in den Bergen östlich von Kharanos. Als tiefe Grabungen verborgene Trogg-Höhlen freilegten, strömten unterirdische Bestien in die Gruben und vertrieben die Bergleute von ihrer Ausrüstung. Da er sich weigert, den Ort vollständig aufzugeben, verharrt Stonebrow am Rand des Steinbruchs, um jeden wehrfähigen Reisenden anzuwerben, der gewillt ist, die Troggs zurückzudrängen."}},faq={{q="Wer ist Großknecht Steinbraue?",a="Großknecht Steinbraue ist ein Zwerg der Miners' League, der die Arbeiten am Gol'bolar Steinbruch in Dun Morogh beaufsichtigt. Er koordiniert die Arbeitsabläufe und versucht, den Steinbruch zu sichern.",al={"stonebrow","wer ist stonebrow","großknecht stonebrow lore"}},{q="Warum bittet Großknecht Steinbraue um Hilfe?",a="Ausgrabungen am Gol'bolar Steinbruch brachen versehentlich in unterirdische Trogg-Höhlen ein. Troggs überrannten die unteren Terrassen, töteten Arbeiter und zwangen die überlebenden Bergleute zum Rückzug in das Lager am oberen Rand.",al={"gol bolar trogg-problem","warum hilfe benötigt wird","steinbruch-quest"}},{q="Was ist die Miners' League?",a="Die Miners' League ist eine Zwergengilde und Handelsorganisation mit Sitz in Eisenschmiede, die Bergbau-Expeditionen, Rohstoffabbau und Steinbruchbetriebe in ganz Khaz Modan überwacht.",al={"miners league","was ist die miners league"}},{q="Wo ist Großknecht Steinbraue zu finden?",a="Er ist im Lager am Rand mit Blick auf den Gol'bolar Steinbruch stationiert, das in den östlichen Hügeln von Dun Morogh direkt an der Straße nach Loch Modan liegt.",al={"stonebrow aufenthaltsort","wo ist großknecht stonebrow"}}},fx={["2635f3c5"]={q="Auf wessen Seite steht Großknecht Steinbraue?",a="Großknecht Steinbraue ist der Miners' League und dem Zwergenkönigreich Eisenschmiede loyal, was ihn fest auf die Seite der Allianz stellt. Er beaufsichtigt zivile Ausgrabungsarbeiten in Dun Morogh und sucht nach Abenteurern der Allianz, um Bedrohungen von den Bergbauaktivitäten in Eisenschmiede zu beseitigen.",al={"fraktion von steinbraue","wem dient steinbraue","gehört steinbraue zur allianz"}},c868fd05={q="Warum ist Großknecht Steinbraue im Steinbruch Gol'Bolar?",a="Großknecht Steinbraue wurde in den Steinbruch Gol'Bolar geschickt, um die Ausgrabung und Rohstoffgewinnung im Namen der Miners' League zu beaufsichtigen. Er bleibt in der Nähe der Grube stationiert, um Unterstützung zu sammeln und Anstrengungen zu koordinieren, den Ort zurückzuerobern, nachdem ein plötzlicher Trogg-Befall die Belegschaft überwältigt hat.",al={"warum ist steinbraue hier","steinbraue golbolar","was macht steinbraue hier"}}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="Großknecht Thazz'ril",s="Großknecht Thazz'ril ist ein Vorarbeiter der Orcs, der im Tal der Prüfungen in Durotar stationiert ist. Betraut mit der Aufgabe, die Peons im Zeitplan zu halten und die grundlegende Infrastruktur für junge Krieger instand zu halten, ist er fortwährend von faulen Arbeitern und den nahegelegenen Aktivitäten von Kultisten frustriert.",h="Großknecht Thazz'ril ist ein Vorarbeiter der Orcs, der im Tal der Prüfungen in Durotar stationiert ist.",kw={"knüppel","burning blade","durotar","großknecht","lazy peons","thazzril","das tal der prüfungen"},ang={["profession:Mining"]="Thazz'ril schätzt hochwertige Bergbauausrüstung, wie seine Verzweiflung zeigt, seine verzauberte Spitzhacke aus den finsteren Winkeln des Kovens der Brennenden Klinge wiederzuerlangen.",["race:Orc"]="Jungen Orcs, die heranwachsen, erteilt Thazz'ril eine frühe Lektion über die Gesellschaft der Horde: Stärke auf dem Schlachtfeld ist nur möglich, wenn sie durch unscheinbare, disziplinierte Arbeit gestützt wird."},sec={{t="Die Peons im Zaum halten",b="Der Aufbau einer neuen Heimat im rauen roten Fels von Durotar erfordert unaufhörliche körperliche Arbeit. Im Tal der Prüfungen beaufsichtigt Großknecht Thazz'ril die Peons, die Holz fällen und Materialien sammeln, um sowohl das Lager als auch die größeren Kriegsanstrengungen der Horde zu unterstützen. Zu Thazz'rils Bedauern neigen Peons notorisch dazu, die Arbeit zu vernachlässigen und unter der Wüstensonne Nickerchen zu machen. Um den Baufortschritt zu sichern, heuert er regelmäßig neu eingetroffene Rekruten an, um den schlummernden Arbeitern mit seinem treuen Knüppel einen kräftigen Hieb zu verpassen und ihnen durch stumpfe Überzeugungskraft Gehorsam beizubringen."},{t="Eine verlorene Spitzhacke in gefährlichen Händen",b="Zu Thazz'rils Pflichten gehört auch die Erkundung der Bodenschätze des Tals, was jedoch zu einem peinlichen Fehltritt führte. Bei der Erkundung der als Koven der Brennenden Klinge bekannten Höhle musste er vor den finsteren Kultisten fliehen, die im Inneren lauerten, und ließ dabei versehentlich seine geschätzte verzauberte Spitzhacke zurück. Zu vorsichtig, um sie inmitten der sich sammelnden Hexenmeister und ihrer dämonischen Schergen selbst zurückzuholen, verlässt er sich auf junge Hordenanwärter, die in die Tiefen vordringen und sein Werkzeug zurückbringen."}},faq={{q="Wer ist Großknecht Thazz'ril?",a="Großknecht Thazz'ril ist ein Arbeitsaufseher der Orcs im Tal der Prüfungen in Durotar. Er ist für die Verwaltung der Arbeitstrupps, das Holzfällen und die Erkundung der Region nach nützlichen Ressourcen zur Unterstützung der Siedlung der Horde verantwortlich.",al={"wer ist thazzril","thazzril tal der prüfungen","großknecht thazzril lore"}},{q="Warum gibt Thazz'ril Spielern einen Knüppel?",a="Die Peons unter seiner Aufsicht schlafen häufig unter Bäumen ein, anstatt Holz zu hacken. Thazz'ril stellt einen verzauberten Holzknüppel zur Verfügung, um ihnen etwas Disziplin einzubläuen und sie eilig zurück an die Arbeit zu schicken.",al={"warum faule peons schlagen","thazzril knüppel","lazy peons quest lore"}},{q="Warum befindet sich Thazz'rils Spitzhacke in der Höhle der Burning Blade?",a="Beim Erkunden der örtlichen Höhlen nach Mineraladern stolperte Thazz'ril in den Koven der Brennenden Klinge. Aufgeschreckt von den in den Schatten lauernden Kultisten trat er einen hastigen Rückzug an und ließ seine wertvolle verzauberte Spitzhacke zurück.",al={"thazzril spitzhacke","warum ist spitzhacke im koven","burning blade spitzhacke"}},{q="Welche Rolle spielt er in der Horde?",a="Thazz'ril ist kein Soldat an vorderster Front oder Schamane, sondern ein ziviler Aufseher. Seine Pflichten drehen sich um das logistische Rückgrat von Durotar: die Beaufsichtigung manueller Arbeit, die Instandhaltung von Baumaterialien und das Sichern der Produktivität der Peons.",al={"ist thazzril ein soldat","thazzril rang"}}},fx={["607050fc"]={q="Auf wessen Seite steht Großknecht Thazz'ril?",a="Thazz'ril ist Thralls Horde gegenüber loyal. Stationiert im Das Tal der Prüfungen beaufsichtigt er die grundlegende Arbeit und Rohstoffbeschaffung, die dabei hilft, Durotar aufzubauen und die Trainingsgelände für ankommende Rekruten der Orcs und Trolle zu erhalten.",al={"loyalität von großknecht thazz'ril","thazz'ril horde","fraktion von thazz'ril"}},f77b2dd2={q="Was will Großknecht Thazz'ril?",a="Großknecht Thazz'ril will in erster Linie, dass seine Arbeiter auch wirklich arbeiten. Genervt von faulen Peons, die im Tal herumlungern, rekrutiert er junge Abenteurer, um sie aufzuwecken. Er möchte außerdem seine geschätzte verzauberte Spitzhacke zurückerhalten, die er unglücklicherweise in der Nähe des Zirkels der Burning Blade zurückgelassen hat.",al={"thazzrils ziele","was braucht thazzril","thazzrils motivationsgrund"}},ee1167cb={q="Warum ist Großknecht Thazz'ril hier?",a="Er wurde dem Tal der Prüfungen zugewiesen, um die Arbeit der Peons zu leiten und die örtlichen Bergbau- und Holzfällerarbeiten zu verwalten. Die Instandhaltung der Siedlung und der stetige Fluss an Rohstoffen sind entscheidend für die Vorbereitung junger Krieger, bevor sie sich in die weitläufigeren Ländereien von Durotar wagen.",al={"warum ist thazzril im tal der prüfungen","grund für thazzrils standort"}}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:foreman-thistlenettle"] = {n="Großknecht Distelklette",s="Großknecht Distelklette war einst ein zwergischer Vorarbeiter, der sowohl die Miners' League als auch die Explorers' League in den Tiefen von Westfall vertrat. Nachdem ein katastrophaler Einsturz seine Mannschaft in den unterirdischen Tunneln der Todesminen gefangen hatte, kam er an der Seite seiner Arbeiter um und erhob sich erneut als untoter Ghul. Er streift nun durch die finsteren, eingestürzten Gänge, für jedermann unkenntlich, bis auf das Gildenabzeichen, das er noch immer bei sich trägt.",h="Großknecht Distelklette war einst ein zwergischer Vorarbeiter, der sowohl die Miners' League als auch die...",kw={"abzeichen","einsturz","die todesminen","großknecht","ghul","miners' league","thistlenettle","wilder"},ang={["profession:Mining"]="Thistlenettles Schicksal ist eine düstere Mahnung an alle Bergleute bezüglich der allgegenwärtigen Gefahr von Tunneleinstürzen und feindseligen unterirdischen Tiefen.",["race:Dwarf"]="Der tragische Verlust eines Großknechts der Explorers' League und einer gesamten zwergischen Mannschaft verdeutlicht die schwelenden Gefahren, die unter den Königreichen der Menschen lauern."},sec={{t="Tragödie in den Todesminen",b="Bevor die Bruderschaft der Defias die vollständige Kontrolle über die Todesminen übernahm, drangen rechtmäßige Bergbauexpeditionen tief in deren reiche Adern vor. Großknecht Distelklette beaufsichtigte ein solches Unterfangen im Auftrag der Miners' League und der Explorers' League. Tief in den Tunneln unter Mondbruch schlug das Unglück zu, als ein gewaltiger Einsturz seine Gruppe von der Oberfläche abschnitt. Die eingeschlossenen Bergleute starben in der Dunkelheit, doch ihre Ruhe währte nicht lange; ein unheilvoller, nekrotischer Makel erweckte Thistlenettle und seine Mannschaft als unersättliche Ghule wieder zum Leben, damit sie die schattigen Passagen durchstreifen."},{t="Die Trauer eines Bruders",b="Zurück in Sturmwind verbrachte sein Bruder Wilder Distelklette rastlose Monate damit, über das Schicksal der vermissten Bergbaugruppe zu grübeln. Da kein Wort aus den besetzten Tunneln nach außen drang, kamen schließlich Gerüchte auf, dass der gefallene Vorarbeiter noch immer unter den Toten wandelte. Abenteurer, die den Außenbereich der Todesminen wagen, werden darum gebeten, den untoten Großknecht ausfindig zu machen, seine Qualen zu beenden und sein Abzeichen zu bergen, um seinen trauernden Angehörigen Gewissheit zu verschaffen."}},faq={{q="Wer war Großknecht Distelklette, bevor er starb?",a="Er war ein zwergischer Großknecht, der sowohl mit der Miners' League als auch mit der Explorers' League in Verbindung stand. Er führte eine Mannschaft von Bergleuten in die Todesminen, bevor diese von Gesetzlosen vollständig befestigt wurden, um die unterirdischen Adern abzubauen und zu vermessen.",al={"thistlenettle lore","wer ist großknecht thistlenettle","thistlenettle hintergrund"}},{q="Warum ist Großknecht Distelklette ein untoter Ghul?",a="Ein katastrophaler Einsturz verschüttete die Tunnel um Thistlenettle und seine Bergbaugruppe und tötete sie. Dunkle unterirdische Energien oder verweilende Nekromantie innerhalb der labyrinthischen Minen belebten ihre Überreste in der Folgezeit wieder und machten aus den Zwergen rastlose Ghule.",al={"warum ist er ein ghul","wie starb thistlenettle","thistlenettle untoter"}},{q="Wo befindet sich Großknecht Distelklette?",a="Er spukt in einem eingestürzten Sackgassentunnel im äußeren Labyrinth der Todesminen, der vor dem Portal zur eigentlichen Instanz liegt, umgeben von seinen wiederbelebten ehemaligen Bergleuten.",al={"wo findet man thistlenettle","thistlenettle aufenthaltsort","standort großknecht todesminen"}},{q="Wer sucht nach Großknecht Distelklette?",a="Sein Bruder Wilder Distelklette, der im Zwergendistrikt von Sturmwind verweilt. Wilder sucht nach einem Beweis für das Schicksal seines Bruders und bittet Reisende darum, Distelklettes Abzeichen zurückzubringen.",al={"wer will thistlenettles tod","wilders bruder","thistlenettle questgeber"}}},fx={["81248170"]={q="Auf wessen Seite steht Großknecht Distelklette?",a="Großknecht Distelklette gehört keiner Fraktion oder Sache mehr an. Als gehirnloser, gefräßiger Ghul greift er zusammen mit seiner wiederbelebten Mannschaft jeden an, der töricht genug ist, sich in ihren eingestürzten Winkel der Todesminen zu wagen, egal ob Defias, Allianz oder umherstreifende Schatzsucher.",al={"thistlenettles fraktion","ist großknecht distelklette feindselig","wem dient distelklette"}},a595eadc={q="Was will Großknecht Distelklette?",a="Welche zwergischen Ambitionen er zu Lebzeiten auch besaß, sie starben mit dem Einsturz. Im Untod hat Großknecht Distelklette keine großen Pläne oder Intrigen – nur den blinden, rastlosen Hunger, den alle Ghule teilen, während er im dunklen Geröll nach allem Lebendigen sucht, das sich nähert.",al={"was will distelklette","distelklettes beweggrund","distelklettes ziel"}},["194368c4"]={q="Warum ist Großknecht Distelklette hier in den Todesminen?",a="Er wagte sich ursprünglich tief in die Todesminen, um eine Expedition im Auftrag der Bergbau-Liga und der Forscherliga zu beaufsichtigen. Als die Katastrophe eintrat und ein unterirdischer Einsturz seine Mannschaft unter sich begrub, waren sie unter dem Gestein gefangen und konnten niemals entkommen, selbst nach ihrem Tod nicht.",al={"warum ist distelklette in den todesminen","wie kam distelklette hierher","warum ist großknecht distelklette hier"}}},fp="21,416,24.530.0,17.419.1,45.237.0,45.261.0,39.181.0,41.186.0"}
P.entries["npc:frahun-shadewhisper"] = {n="Frahun Schattenflüsterer",s="Frahun Schattenflüsterer ist ein Nachtelf-Schurkenlehrer, der in Aldrassil im Laubschattental stationiert ist. Er bringt neu eingeweihten Nachtelfenspähern und -schurken die grundlegenden Techniken der Heimlichkeit, Beweglichkeit und verdeckten Angriffe bei. Er teilt seinen Nachnamen mit Erion Schattenflüsterer, einem weiteren Ausbilder seines Handwerks in Darnassus.",h="Frahun Schattenflüsterer ist ein Nachtelf-Schurkenlehrer, der in Aldrassil im Laubschattental stationiert ist.",kw={"aldrassil","verschlüsseltes siegelzeichen","erion","frahun","schurkenlehrer","shadewhisper","laubschattental","teldrassil"},ang={["class:Rogue"]="Frahun Schattenflüsterer dient als allererster Klassenlehrer für Nachtelfenschurken und vermittelt ihnen die erste Einführung in Heimlichkeit, Hinterhaltstaktiken und Waffenbeherrschung.",["race:NightElf"]="Frahun veranschaulicht, wie Nachtelfen ihre natürliche nächtliche Verbundenheit und Flüchtigkeit in tödliche, praktische Kampffertigkeiten umwandeln, um Teldrassil zu beschützen."},sec={{t="Ein Mentor in den Schatten",b="In der sicheren Zuflucht von Aldrassil im Herzen von Teldrassil unterweist Frahun Schattenflüsterer aufstrebende Schurken in den stillen Künsten der Verborgenheit und Klingenführung. Während die Gesellschaft der Nachtelfen oft Priester, Schildwachen und Druiden ehrt, bleibt das spezialisierte Handwerk der Späher und Infiltratoren unerlässlich, um das Geäst des Weltenbaums zu schützen. Frahun heißt Rekruten willkommen, die mit einem Verschlüsselten Siegelzeichen eintreffen, beurteilt ihr Potenzial und leitet ihre anfängliche Ausbildung an."}},faq={{q="Wer ist Frahun Schattenflüsterer?",a="Frahun Schattenflüsterer ist ein Nachtelf-Schurkenlehrer, der in Aldrassil auf Teldrassil stationiert ist. Er lehrt angehende Schurken die Grundlagen der Heimlichkeit, des Präzisionskampfes und verdeckter Taktiken.",al={"frahun lore","wer ist frahun","frahun schattenflüsterer rolle"}},{q="Wo ist Frahun Schattenflüsterer zu finden?",a="Er befindet sich in Aldrassil, der zentralen Festung des Startgebiets Laubschattental auf Teldrassil.",al={"frahun standort","wo ist frahun","frahun schattenflüsterer finden"}},{q="Ist Frahun mit Erion Schattenflüsterer verwandt?",a="Aufgrund ihres gemeinsamen Nachnamens und ihrer beiderseitigen Hingabe zur Ausbildung von Schurken auf Teldrassil wird weithin angenommen, dass Frahun mit Erion Schattenflüsterer verwandt ist, der Schurken in Darnassus ausbildet.",al={"erion schattenflüsterer bruder","frahun erion verwandt","shadewhisper familie"}},{q="Welche Rolle spielen die Verschlüsselten Siegelzeichen bei ihm?",a="Angehende Nachtelfenschurken beginnen ihre Reise, indem sie Verschlüsselte Siegelzeichen direkt zu Frahun bringen, was sie als Kandidaten ausweist, die für die formelle Unterweisung im Handwerk des Schurken bereit sind.",al={"verschlüsselte siegelzeichen abgabe","frahun siegelzeichen","schurken startquest"}}},fx={a27f02ba={q="Auf wessen Seite steht Frahun Schattenflüsterer?",a="Frahun steht fest an der Seite von Darnassus und der Allianz. Stationiert inmitten der uralten Äste von Aldrassil im Laubschattental, dient er seinen Mit-Kaldorei, indem er sicherstellt, dass diejenigen mit einem Talent für Heimlichkeit und List ihre Fähigkeiten verfeinern können, um die Ländereien der Nachtelfen zu schützen.",al={"frahuns fraktion","frahuns loyalität","gehört frahun zur allianz"}},["025c0171"]={q="Was will Frahun Schattenflüsterer?",a="Frahun möchte aufstrebende Nachtelf-Schurken in der Kunst der Schatten, des Schlösserknackens und des verstohlenen Kampfes unterrichten. Er stellt sicher, dass neue Späher und Agenten ihre Disziplin gründlich beherrschen, bevor sie sich über die geschützten Grenzen des Laubschattentals hinaus in das weitere Teldrassil wagen.",al={"frahuns beweggrund","frahuns ziel","was tut frahun"}},["72dec556"]={q="Warum ist Frahun Schattenflüsterer hier in Aldrassil?",a="Frahun ist in Aldrassil stationiert, um neu erwachte oder unerfahrene Nachtelfen anzuleiten, die den Pfad des Schurken beschreiten. Im sicheren Hafen des Laubschattentals bietet er grundlegende Ausbildung, um sicherzustellen, dass junge Praktizierende nicht den Gefahren erliegen, die im Wald lauern.",al={"warum ist frahun in aldrassil","warum ist frahun im laubschattental","zweck von frahuns standort"}}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furen-longbeard"] = {n="Furen Langbart",s="Furen Langbart ist ein meisterhafter Zwergenrüstschmied, der im geschäftigen Zwergendistrikt von Sturmwind stationiert ist. Als Lehrling des renommierten Schmieds Grimand Elmore hat er sich auf die Herstellung schwerer Schutzausrüstung und robuster Kettenrüstungen für erfahrene Verteidiger der Allianz spezialisiert. Krieger im ganzen Königreich suchen sein metallurgisches Fachwissen auf, um spezialisierte, kampfbereite Rüstungen schmieden zu lassen.",h="Furen Langbart ist ein meisterhafter Zwergenrüstschmied, der im geschäftigen Zwergendistrikt von Sturmwind...",kw={"rüstschmied","schmied","der zwergendistrikt","feuergehärteter panzer","furen langbart","grimand elmore","sturmwind","krieger"},ang={["class:Warrior"]="Für heranwachsende Krieger der Allianz ist Furen Langbart ein entscheidender Ansprechpartner, der rohe Entschlossenheit und gesammelte Reagenzien in lebenswichtige, feuergehärtete Schutzrüstungen verwandelt.",["profession:Blacksmithing"]="Furen verkörpert die hohen Standards der Zwergenschmiedekunst in Sturmwind und präsentiert fortschrittliche Techniken, die von Grimand Elmore weitergegeben wurden.",["race:Dwarf"]="Selbst fernab von Eisenschmiede hält Furen Langbart die metallurgischen Traditionen der Zwerge im Herzen der menschlichen Hauptstadt lebendig."},sec={{t="Ein Zwergenschmied in der Menschenhauptstadt",b="Furen Langbart übt sein Handwerk fernab der großen Schmieden von Eisenschmiede aus und hat stattdessen sein Zuhause zwischen dem Kopfsteinpflaster und dem Ruß des Zwergendistrikts von Sturmwind gefunden. Wie viele seines Volkes brachte Furen traditionelle zwergische Metallurgie nach Süden, um den Wiederaufbau und die Verteidigung des Königreichs zu unterstützen. Inmitten lodernder Feuerstellen und klirrender Ambosse pflegt er enge Beziehungen zu anderen Handwerkern in der ganzen Stadt und darüber hinaus."},{t="Meisterschaft im feuergehärteten Panzer",b="Von dem ehrwürdigen Handwerker Grimand Elmore ausgebildet, hat Furen Techniken perfektioniert, um schwere Ketten- und Plattenrüstungen so zu behandeln, dass sie extremen Belastungen auf dem Schlachtfeld standhalten. Vielversprechende junge Krieger auf der Suche nach dauerhaftem Schutz wenden sich oft an Furen, der seltene Erze, spezielle Bauteile und exotische Reagenzien aus fernen Winkeln der Welt benötigt, um seine unverwechselbare feuergehärtete Rüstung herzustellen."}},faq={{q="Wer ist Furen Langbart?",a="Furen Langbart ist ein Zwergenrüstschmied, der im Zwergendistrikt von Sturmwind tätig ist. Er dient als unverzichtbarer Ansprechpartner und Mentor für Krieger der Allianz, die meisterhaft gefertigte Kettenrüstungen erwerben möchten.",al={"wer ist furen","furen langbart lore","zwergenrüstschmied sturmwind"}},{q="Wo ist Furen Langbart zu finden?",a="Er befindet sich im Zwergendistrikt von Sturmwind, nahe den geschäftigen Schmieden und Werkstätten, die das Viertel prägen.",al={"wo ist furen langbart","furen langbart standort","furen sturmwind"}},{q="Wer lehrte Furen sein Schmiedehandwerk?",a="Furen erlernte das Rüstungshandwerk und die Metallurgie von Grimand Elmore, einem angesehenen Handwerksveteranen, der ebenfalls im Zwergendistrikt lebt.",al={"furen lehrer","furen mentor","wer hat furen ausgebildet"}},{q="Für welche Rüstung ist Furen berühmt?",a="Er ist berühmt für die Herstellung des Feuergehärteten Panzers, einer widerstandsfähigen Rüstung, die durch anspruchsvolle metallurgische Verfahren entsteht und seltene, auf dem gesamten Kontinent gesammelte Komponenten erfordert.",al={"feuergehärteter panzer","furen rüstungsquest","krieger kettenrüstung quest sturmwind"}},{q="Ist Furen Langbart mit anderen Langbärten verwandt?",a="Er teilt seinen Clannamen mit mehreren anderen prominenten Zwergen in den Östlichen Königreichen, wie dem erfahrenen Gebirgsjäger Pilot Langbart, konzentriert sich selbst jedoch vollkommen auf das Schmieden.",al={"furen familie","longbeard clan","pilot langbart verwandter"}},{q="Warum suchen Krieger Furen Langbart auf?",a="Krieger, die ihr grundlegendes Kampfgeschick unter Beweis gestellt haben, werden an Furen verwiesen, um schwere, langlebige Rüstungen zu erhalten, die dem Fronteinsatz gegen tödlichere Bedrohungen standhalten können.",al={"warum krieger furen aufsuchen","kriegerquest der zwergendistrikt","furen kriegerausbilder"}}},fx={["269e0799"]={q="Auf wessen Seite steht Furen Langbart?",a="Furen Langbart ist ein treues Mitglied der Allianz und geht seinem Handwerk im geschäftigen Zwergendistrikt in Sturmwind nach. Er arbeitet eng mit Verwandten aus Eisenschmiede, anderen Schmieden und dem Stormpike-Clan zusammen und widmet sein Können der Ausrüstung der Verteidiger der Allianz.",al={"furen langbarts fraktion","gehört furen langbart zur allianz","wem dient furen langbart"}},d8add91c={q="Was will Furen Langbart?",a="Furen sucht nach seltenen Materialien und fähigen Verbündeten, um außergewöhnliche Rüstungen herzustellen, insbesondere für vielversprechende Krieger, die robuste Ausrüstung wie feuergehärtete Kettenrüstung suchen. Er arbeitet auch daran, wichtige militärische Aufträge zu erfüllen, einschließlich spezialisierter Bestellungen für die Stormpikegarde.",al={"was will furen","furen langbarts beweggrund","furen langbarts ziele"}},["316ead5d"]={q="Warum ist Furen Langbart in Sturmwind?",a="Furen arbeitet vom Zwergendistrikt in Sturmwind aus und dient als lebenswichtiges Bindeglied zwischen zwergischem Handwerk und den militärischen Bedürfnissen der Hauptstadt der Menschen. Hier, in der Nähe der großen Schmieden der Stadt, kann er mit Lehrlingen, Meisterschmieden und gnomischen Ingenieuren zusammenarbeiten, während er Frontverteidiger mit schwerer Rüstung versorgt.",al={"warum ist furen langbart hier","warum ist furen in sturmwind","hintergrund zu furen langbarts standort"}}},fp="15,369,36.416.0,29.380.0,23.205.0,35.145.0,36.130.0,40.180.0,47.179.0,41.169.0"}
P.entries["npc:furl-scornbrow"] = {n="Furl Hohnbraue",s="Furl Hohnbraue ist ein alternder Orc-Späher, der im Wachturm nordwestlich von Klingenhügel stationiert ist. Da er aufgrund seines fortgeschrittenen Alters nicht mehr an vorderster Front kämpfen kann, hält er über den roten Schluchten von Durotar Wache und fertigt robuste Taschen für junge Reisende, die ins Land aufbrechen.",h="Furl Hohnbraue ist ein alternder Orc-Späher, der im Wachturm nordwestlich von Klingenhügel stationiert ist.",kw={"akzeptiert euer schicksal","durotar","furl hohnbraue","späher","orc","klingenhügel","wachturm"},ang={["faction:Horde"]="Stationiert entlang der Bergrücken außerhalb von Klingenhügel, verkörpert Furl die Wachsamkeit, die nötig ist, um Durotars junge Siedlungen vor anhaltenden Bedrohungen zu schützen.",["race:Orc"]="Furl verkörpert den Glauben der Orcs, dass ein ehrenhaftes Leben bedeutet, einen anderen Weg zu finden, um dem Clan und der Horde zu dienen, selbst wenn das Alter einen Krieger seiner kriegerischen Stärke beraubt."},sec={{t="Wächter des Kamms",b="Hoch oben im hölzernen Wachturm direkt nordwestlich von Klingenhügel hält Furl Hohnbraue eine ruhige Wacht über die zentralen Ebenen von Durotar. In den angespannten frühen Tagen nach der Gründung von Orgrimmar waren Posten wie Furl unerlässlich, um Signalhörner gegen feindselige Borstennacken, Zentauren und Eindringlinge aus Kul Tiras ertönen zu lassen. Da sich Durotar stabilisiert hat und Klingenhügel über festere Grenzen verfügt, sind Notfälle seltener geworden, was Furl viele ruhige Stunden auf seinem Posten beschert."},{t="Ein nützliches Paar Hände",b="Furl gibt freimütig zu, dass seine alten Knochen und schwindenden Kräfte ihn im Kampf unbrauchbar machen, doch ein Orc gibt seine Bestimmung nicht so leicht auf. Anstatt untätig herumzusitzen, macht er sich nützlich, indem er Segeltuchsäcke und Taschen für neue Rekruten herstellt, die ihre Vorräte tragen müssen. Im Austausch gegen groben Faden und praktische Materialien rüstet er unerfahrene Abenteurer aus, die ausziehen, um ihren Wert für die Horde zu beweisen."}},faq={{q="Wer ist Furl Hohnbraue?",a="Furl Hohnbraue ist ein älterer Orc-Wächter, der im Aussichtsturm auf den Klippen nordwestlich von Klingenhügel stationiert ist. Da er aufgrund seines Alters nicht mehr als Krieger an vorderster Front dienen kann, hält er am Horizont nach Gefahren Ausschau und fertigt Taschen für junge Reisende.",al={"wer ist furl","furl hohnbraue lore","furl in klingenhügel"}},{q="Welche Rolle spielt Furl in Durotar?",a="Er besetzt den Signalhornturm und hält Ausschau nach Angreifern, die sich Klingenhügel nähern. Da Durotar unter der Kontrolle der Horde immer sicherer geworden ist, schlägt er weit seltener Alarm und nutzt seine freie Zeit, um ankommenden Rekruten bei der Organisation ihrer Ausrüstung zu helfen.",al={"was macht furl","furls bestimmung"}},{q="Warum bittet Furl Reisende um Materialien?",a="Furl glaubt daran, dass jedes Mitglied der Horde seinen Beitrag leisten muss, ungeachtet der Umstände. Da er nicht mehr kämpfen kann, näht er praktische Reisetaschen, um neueren Kriegern zu helfen, und verlangt dafür lediglich grundlegende Materialien wie groben Faden, um die Arbeit fertigzustellen.",al={"akzeptiert euer schicksal quest lore","warum furl faden will"}}},fx={["1ce1cc0b"]={q="Auf wessen Seite steht Furl Hohnbraue?",a="Furl steht fest an der Seite der Horde. Hoch über Klingenhügel positioniert, hält er Wache über Durotar, um das junge Orc-Reich vor potenziellen Eindringlingen zu schützen, und unterstützt Reisende, die dem Kriegshäuptling dienen.",al={"furl hohnbraues fraktion","gehört furl hohnbraue zur horde","ist furl bei der horde"}}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="Gaerolas Talvethren",s="Gaerolas Talvethren ist eine Schildwache der Nachtelfen, die über die Ruinen von Sternenhauch in Teldrassil wacht. Als Beschützer der Schlafenden Druiden ernannt, sucht er Unterstützung beim Kampf gegen die aggressiven Furbolgs und die dunkle Verderbnis, die das Geäst heimsucht.",h="Gaerolas Talvethren ist eine Schildwache der Nachtelfen, die über die Ruinen von Sternenhauch in Teldrassil...",kw={"ein beunruhigender wind","gaerolas talvethren","die verderbnis der knarzklauen","starbreeze","teldrassil","die schlafenden"},ang={["class:Druid"]="Gaerolas' Pflicht als Wächter der schlafenden Druiden macht die Unterstützung seiner Bestrebungen zu einer persönlichen Angelegenheit zum Schutz von Mitstreitern des Zirkels des Cenarius.",["race:NightElf"]="Für junge Nachtelfen, die Dolanaar verlassen, bietet die Unterstützung von Gaerolas einen ernüchternden Einblick darin, wie tief die Verderbnis bereits in Teldrassils heiliges Geäst eingedrungen ist."},sec={{t="Wächter der Schlafenden",b="Inmitten der unruhigen Siedlung Sternenhauch trägt Gaerolas Talvethren die feierliche Pflicht, die Schlafenden Druiden zu beschützen, die im Einklang mit dem Smaragdgrünen Traum ruhen. Seine Wachsamkeit wird immer mühsamer, da unnatürliche Verderbnis durch den Wald kriecht und das Gleichgewicht von Teldrassil stört."},{t="Die Bedrohung der Gnarlpine",b="Gaerolas weist Reisende an, den Stamm der Gnarlpine-Furbolgs zurückzudrängen, deren Verstand dem Wahnsinn und der Wildheit anheimgefallen ist. Indem er das Verderben untersucht, das von ihren Schamanen ausgeht, und die Wurzeln ihrer Pein ergründet, hofft er, die verbliebene Unversehrtheit des östlichen Teldrassil zu bewahren."}},faq={{q="Wer ist Gaerolas Talvethren?",a="Er ist ein Verteidiger der Nachtelfen, der in Sternenhauch stationiert ist, um die schlafenden Druiden zu beschützen und der seltsamen Verderbnis nachzugehen, die dieses Gebiet heimsucht.",al={"gaerolas","wer ist gaerolas","gaerolas rolle"}},{q="Wo finde Ich Gaerolas Talvethren?",a="Er befindet sich in Sternenhauch, im östlichen Geäst von Teldrassil, östlich von Dolanaar.",al={"gaerolas aufenthaltsort","wo ist gaerolas talvethren","gaerolas finden"}},{q="Wer sind „die Schlafenden“, die Gaerolas beschützt?",a="Die Schlafenden bezieht sich auf die Nachtelfendruiden, die sich in Grabhügeln und Zufluchten in einen langen Schlaf begaben, um den Smaragdgrünen Traum zu durchwandern, wodurch ihre physischen Körper ungeschützt vor weltlicher Gefahr blieben.",al={"die schlafenden","wer sind die schlafenden","schlafende druiden"}},{q="Welche Bedrohungen beunruhigen Gaerolas?",a="Er ist zutiefst besorgt über die Verderbnis, die die einheimische Tierwelt befällt, und die plötzliche, von Wahnsinn erfüllte Feindseligkeit des Stammes der Gnarlpine-Furbolgs.",al={"starbreeze bedrohungen","gaerolas quests","gnarlpine probleme"}}},fx={["52ffd6bd"]={q="Auf wessen Seite steht Gaerolas Talvethren?",a="Gaerolas steht fest an der Seite der Nachtelfen von Darnassus und der Allianz. Als geschworener Wächter der schlummernden Druiden, die in Sternenhauch ruhen, liegt seine Loyalität beim Zirkel des Cenarius, seinem Volk und der Verteidigung von Teldrassil.",al={"gaerolas fraktion","wem dient gaerolas","gaerolas loyalität"}},["436c9e7a"]={q="Was will Gaerolas Talvethren?",a="Gaerolas möchte die schlummernden Druiden vor den korrumpierenden Kräften schützen, die in Sternenhauch eindringen. Er bittet Euch um Hilfe bei der Untersuchung der beunruhigenden Fäulnis, die sich in der Gegend ausbreitet, und bei der Ausrottung der Aggression der korrumpierten Gnarlpine-Furbolgs.",al={"gaerolas ziel","was versucht gaerolas","gaerolas zweck"}},["9c3b08f8"]={q="Warum ist Gaerolas Talvethren hier?",a="Gaerolas bleibt in Sternenhauch stationiert, da er der designierte Beschützer der Schlafenden ist. Während die Druiden im Smaragdgrünen Traum kommunizieren, sind sie physischen Gefahren völlig schutzlos ausgeliefert, weshalb Gaerolas Wache gegen jegliche äußere Bedrohung hält.",al={"warum ist gaerolas in sternenhauch","grund für gaerolas anwesenheit","warum ist gaerolas talvethren hier"}}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="Gakin der Dunkelbinder",s="Gakin der Dunkelbinder ist ein Hexenmeistermeister, der im Verborgenen tief unter der Taverne „Zum Geschlachteten Lamm“ im Magierviertel von Sturmwind operiert. Er unterweist aufstrebende Praktizierende der Allianz in den dunklen Künsten und prüft ihre Entschlossenheit, bevor er Rituale einleitet, um jenseitige Dämonen zu beschwören und an ihren Dienst zu binden.",h="Gakin der Dunkelbinder ist ein Hexenmeistermeister, der im Verborgenen tief unter der Taverne „Zum...",kw={"dunkelbinder","gakin","das magierviertel","slaughtered lamb","sukkubus","surena caledon","leerwandler","hexenmeister"},ang={["class:Warlock"]="Gakin ist ein lebenswichtiger Mentor für Menschen- und Gnomen-Hexenmeister, der entscheidende Klassenquests anbietet, um die Rituale für Leerwandler und Sukkuben in den Krypten von Sturmwind zu meistern.",["faction:Alliance"]="Gakins Zirkel, der heimlich unter der Hauptstadt operiert, verdeutlicht die pragmatischen, schattendurchtränkten Kompromisse, die im Herzen der Allianz eingegangen werden."},sec={{t="Ein geheimer Versammlungsort",b="Während Sturmwinds Magier offen in ihren hoch aufragenden Heiligtümern praktizieren, müssen die Anwender von Schatten und Teufelsmagie dort verweilen, wo neugierige Blicke sie nicht erreichen können. Verborgen unter der Schankstube von „Zum Geschlachteten Lamm“ liegt ein feuchter, kryptaartiger Keller, der mit Beschwörungskreisen und düsteren Folianten ausgestattet ist. Gakin dient als Anker dieses verborgenen Konklaves und stellt sicher, dass junge Hexenmeister Disziplin und Zurückhaltung lernen, bevor sie Schrecken entfesseln, die sie nicht kontrollieren können."},{t="Meister der Dämonen",b="Gakins Fachwissen liegt in der Dämonologie und in Bindungsritualen. Initianden, die seine Aufmerksamkeit erlangen, werden durch das gesamte Königreich geschickt, um seltene Relikte und Zutaten zu beschaffen – von gestohlenen Blutsteintalismanen bis hin zu verderbtem Holz aus den dunklen Wäldern. Sobald die Reagenzien versammelt sind, beaufsichtigt Gakin die Rituale im Beschwörungskreis der Krypta und zwingt die Novizen dazu, Leerwandler und Sukkuben in Willensprüfungen auf Leben und Tod zu unterwerfen."},{t="Verrat und lose Fäden",b="Nicht alle Schüler Gakins bleiben gehorsam. Eine ehemalige Schülerin, Surena Caledon, machte sich mit einem wertvollen Blutsteinhalsreif davon und floh in die Wildnis. Ein solcher interner Verrat droht den Zirkel der Hexenmeister vor den Stadtwachen zu enttarnen, was Gakin dazu veranlasst, treue Anhänger auszusenden, um verlorene Artefakte wiederzubeschaffen und lose Fäden zum Schweigen zu bringen, bevor die Behörden Verdacht schöpfen."}},faq={{q="Wo kann ich Gakin den Dunkelbinder finden?",a="Gakin befindet sich tief unter der Taverne „Zum Geschlachteten Lamm“ im Magierviertel von Sturmwind. Geht in die Taverne hinein, sucht die Rampe nach unten im hinteren Bereich und steigt durch die Steintunnel hinab, bis Ihr den Beschwörungskreis in der untersten Krypta erreicht.",al={"wo ist gakin","gakin aufenthaltsort","zum geschlachteten lamm keller"}},{q="Was tut Gakin der Dunkelbinder?",a="Er dient als prominenter Questgeber und Mentor für Hexenmeister-Charaktere der Allianz. Er prüft Novizen, indem er sie auf Prüfungen quer durch Azeroth schickt und ihnen beibringt, wie man Dämonen wie den Leerwandler und die Sukkubus beschwört und bindet.",al={"was macht gakin","gakin rolle","gakin quests"}},{q="Warum werden Hexenmeister unter „Zum Geschlachteten Lamm“ geduldet?",a="Dämonische Magie ist in Sturmwind verboten und stößt auf tiefes Misstrauen. Die Praktizierenden unter „Zum Geschlachteten Lamm“ agieren in strenger Geheimhaltung und werden nur als gefährlicher, verdeckter Vorposten geduldet – verborgen vor den Wachen und Bürgern der Stadt.",al={"warum hexenmeister erlaubt sind","sind hexenmeister in sturmwind legal","zum geschlachteten lamm lore"}},{q="Wer ist Surena Caledon?",a="Surena Caledon war eine ehemalige Schülerin von Gakin, die ihm einen mächtigen Blutsteinhalsreif stahl. Ihr Verrat stellt eine Gefahr für ihren verborgenen Orden dar, weshalb Gakin Hexenmeister damit beauftragt, sie aufzuspüren.",al={"surena caledon","gakin schüler","wer bestahl gakin"}},{q="Welche Dämonen hilft Gakin zu beschwören?",a="Gakin überwacht die Bindungsrituale für Leerwandler und Sukkuben und leitet Hexenmeister an, die Kreaturen in den unterirdischen Kreis zu rufen und sie zu unterwerfen.",al={"gakin dämonen","gakin leerwandler","gakin sukkubus"}},{q="Wer ist Strahad und warum erwähnt Gakin ihn?",a="Strahad Farsan ist ein erfahrener Hexenmeister, der in den Hügeln von Ratschet auf Kalimdor weilt. Sobald ein Schüler Gakins grundlegende Bindungsrituale gemeistert hat, schickt Gakin ihn über das Meer, um seine finstere Ausbildung bei Strahad fortzusetzen.",al={"strahad","die suche nach strahad","wohin schickt mich gakin als nächstes"}}},fx={["5c1d997e"]={q="Wer ist Gakin der Dunkelbinder?",a="Gakin der Dunkelbinder ist ein mächtiger menschlicher Hexenmeister, der sich tief in den Krypten unterhalb von The Slaughtered Lamb im Das Magierviertel von Sturmwind verbirgt. Fernab der neugierigen Blicke der Stadtwache und der Kirin Tor leitet er junge Praktizierende der Teufelsmagie an und weist sie in die gefährlichen Riten ein, die erforderlich sind, um jenseitige Dämonen ihrem Willen zu unterwerfen.",al={"wer ist gakin","identität gakin","gakin hintergrundgeschichte"}},a5302178={q="Auf wessen Seite steht Gakin der Dunkelbinder?",a="Gakin arbeitet in loser Verbindung im Dienste der Allianz und bildet menschliche und gnomische Praktizierende darin aus, dämonische Kräfte für ihr eigenes Überleben als Waffe einzusetzen. Doch wie bei den meisten Meistern der dunklen Künste bleibt seine endgültige Loyalität verborgen, gehüllt in Schatten, Geheimnisse und das Streben nach verbotenem Wissen, fernab der Kontrolle der Herrscher von Sturmwind.",al={"ist gakin bei der allianz","loyalität gakin","wem dient gakin"}},["503bf85b"]={q="Was will Gakin der Dunkelbinder?",a="Gakin möchte seine Meisterschaft über die Teufelsmagie erweitern und sicherstellen, dass aufstrebende Hexenmeister die Entschlossenheit besitzen, größere Dämonen zu binden, anstatt von ihnen verschlungen zu werden. Er arbeitet zudem im Stillen daran, gestohlene Machtartefakte wiederzuerlangen, wie etwa einen geraubten Blutsteinhalsreif, der von seinem abtrünnigen ehemaligen Schüler gestohlen wurde.",al={"was will gakin","gakin ziele","gakin motive"}}},fp="20,297,24.429.0,16.411.0,24.365.1,38.247.0,34.223.0,52.230.0,22.201.0,36.153.0,46.232.0"}
P.entries["npc:galgar"] = {n="Galgar",s="Galgar ist ein Orc-Koch, der im Tal der Prüfungen in Durotar stationiert ist. Er bereitet Vorräte für junge Rekruten zu, die ihre ersten Schritte im Dienst der Horde machen. Um Neulingen die Grundlagen der Nahrungssuche in der rauen Wüste beizubringen, beauftragt er sie damit, wilde Kaktusäpfel für sein Spezialgericht zu sammeln.",h="Galgar ist ein Orc-Koch, der im Tal der Prüfungen in Durotar stationiert ist.",kw={"kaktusapfel surprise","kaktusäpfel","koch","durotar","galgar","horde rekrut","das tal der prüfungen"},ang={["profession:Cooking"]="Galgar verkörpert die praktische, rustikale Küche der Horde, die Durotars karge natürliche Ressourcen nutzt, um Rekruten satt und kampfbereit zu halten.",["race:Orc"]="Für junge Orcs, die ihre ersten Schritte im Tal der Prüfungen machen, ist eine Besorgung für Galgar ein vertrauter Übergangsritus, bevor sie sich gefährlicheren Bedrohungen in der Wildnis stellen."},sec={{t="Ein Koch im Tal",b="In der Nähe der Feuerstelle beim Höhlenbau im Tal der Prüfungen versorgt Galgar junge Orcs und Trolle, die ihre ersten Übergangsriten durchlaufen, mit Nahrung. Durotar ist ein trockenes, unbarmherziges rotes Ödland, in dem jeder Bissen Nahrung der Landschaft abgerungen werden muss. Indem er unerfahrene Krieger damit beauftragt, reife Kaktusfrüchte zu sammeln, stellt Galgar ihre Aufmerksamkeit und Zähigkeit auf die Probe und hält gleichzeitig seine Küche gefüllt."},{t="Kaktusapfel Surprise",b="Galgars Spezialrezept ist als Kaktusapfel Surprise bekannt. Obwohl er offen zugibt, dass die Suche nach stacheligen Wüstenfrüchten eine bewusst einfache Aufgabe ist, die neuen Rekruten den Einstieg in das Leben als Abenteurer erleichtern soll, bleibt das Endprodukt eine unverzichtbare Ration für hungrige Auszubildende. Selbst der abgehärtetste Krieger der Horde muss irgendwo anfangen, und unter Galgars wachsamen Augen beginnt diese Reise mit der Nahrungssuche in der Wüste."}},faq={{q="Wo kann ich Galgar finden?",a="Galgar befindet sich im Tal der Prüfungen, dem Startgebiet für Orcs und Trolle im südwestlichen Durotar. Er steht nahe dem zentralen Lagerfeuer und dem Kochbereich vor dem Höhlenbau.",al={"galgar aufenthaltsort","wo ist galgar","galgar koordinaten"}},{q="Worum bittet Galgar Abenteurer?",a="Er bittet neue Abenteurer darum, reife Kaktusäpfel von den wilden Kakteen zu sammeln, die im Tal der Prüfungen verstreut sind, damit er seine Kaktusapfel Surprise zubereiten kann.",al={"galgar quest","was will galgar"}},{q="Warum schickt Galgar neue Rekruten los, um Früchte zu pflücken?",a="Galgar gibt zu, dass die Aufgabe bewusst einfach gehalten ist. Sie dient frischgebackenen Kämpfern als leichte Einstiegsaufgabe, um sich im Tal zurechtzufinden und Selbstversorgung in der rauen Wildnis von Durotar zu üben.",al={"warum kaktusäpfel","galgar prüfung"}},{q="Was ist Kaktusapfel Surprise?",a="Es ist Galgars Spezialrezept, hergestellt aus frischen Kaktusäpfeln, die aus der einheimischen Wüstenflora Durotars gesammelt wurden, um neue Rekruten zu stärken.",al={"was ist kaktusapfel surprise","galgar essen"}}},fx={["115dfff8"]={q="Wer ist Galgar?",a="Galgar ist ein Orc-Koch, der im Tal der Prüfungen in Durotar stationiert ist. Anstatt Krieger im brutalen Kampf auszubilden, unterstützt er die Siedlung durch die Zubereitung herzhafter Proviante, vor allem seiner wohlbekannten Kaktusapfel Surprise.",al={"wer ist galgar","galgar hintergrund","wer galgar"}},["7f3ad096"]={q="Auf wessen Seite steht Galgar?",a="Galgar ist der Horde von Thrall treu ergeben. Er dient im Tal der Prüfungen und kümmert sich direkt um die jungen Orcs und Trolle, die ihre ersten Schritte im Dienste Durotars machen.",al={"galgars fraktion","gehört galgar zur horde","galgars loyalität"}},d4d57a6c={q="Was will Galgar?",a="Galgar will frische Zutaten – hauptsächlich die reifen Kaktusäpfel, die im gesamten trockenen Tal wachsen –, damit er Portionen seiner Kaktusapfel Surprise zubereiten kann, um die jungen Rekruten satt und energiegeladen zu halten.",al={"was braucht galgar","galgars ziel","galgar möchte"}},["50f967f0"]={q="Warum ist Galgar hier im Tal der Prüfungen?",a="Galgar ist im Tal der Prüfungen stationiert, um die Küche des Lagers zu unterstützen. Während Ausbilder die Anwärter in der Kunst des Krieges unterrichten, stellt Galgar sicher, dass das Gelände mit Nahrung versorgt bleibt, und führt Neuankömmlinge in grundlegende Feldarbeit ein.",al={"warum ist galgar hier","grund für galgars anwesenheit im tal der prüfungen","warum ist galgar in durotar"}},["2e1d8215"]={q="Warum ist Galgar berühmt?",a="Galgar ist im gesamten Tal der Prüfungen für sein berühmtes Rezept, Kaktusapfel Surprise, bekannt. Fast jeder junge Rekrut, der durch The Den zieht, probiert seine Kochkünste, während er erste kleine Aufgaben für ihn erledigt.",al={"ist galgar berühmt","wofür ist galgar bekannt","galgars bekanntheit"}}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="Gan'rul Blutauge",s="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterausbilder der Orcs, der tief in der dunklen Kaverne von der Kluft der Schatten in Orgrimmar residiert. Vor den wachsamen Augen der Stadt über ihm verborgen, führt er Hexenmeister der Horde in dunklere dämonische Riten ein. Unter seiner Anleitung lernen die Initianden, jenseitige Wesen wie Leerwandler und Sukkubi ihrem Willen zu unterwerfen.",h="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterausbilder der Orcs, der tief in der dunklen Kaverne von der...",kw={"bloodeye","die kluft der schatten","gan'rul","orgrimmar","sukkubus","ausbilder","leerwandler","hexenmeister"},ang={["class:Warlock"]="Für Hexenmeister, die nach verbotenem Wissen suchen, ist Gan'rul ein wichtiger Mentor in Kalimdor, der das Wissen und die Prüfungen bereitstellt, die erforderlich sind, um Leerwandler und Sukkubi zu binden.",["faction:Horde"]="Gan'rul verkörpert die prekäre Stellung der Teufelsmagie in Thralls Horde – sie wird für militärische Stärke genutzt, ist aber in die unterirdischen Winkel der Hauptstadt verbannt."},sec={{t="Ein Meister in den Schatten",b="Während Kriegshäuptling Thrall die Anwesenheit von Hexenmeistern in der neuen Horde toleriert, sind ihre dunklen Künste im offenen Sonnenlicht von Durotar nicht willkommen. Gan'rul Blutauge hat sein Zuhause in der Kluft der Schatten, einem unterirdischen Zufluchtsort unter Orgrimmar, wo Schattenweber, Schurken und Teufelswirker ungestört studieren können. Von diesem unterirdischen Stützpunkt aus fungiert Gan'rul als primärer Lehrmeister für aufstrebende Praktizierende der Teufelsmagie."},{t="Die Bindung des Nether",b="Gan'ruls Hauptaufgabe ist die Überwachung der gefährlichen Beschwörungsrituale, die von ehrgeizigen Hexenmeistern verlangt werden. Praktizierende, die größere Dämonen – wie den widerstandsfähigen Leerwandler oder den verführerischen Sukkubus – binden wollen, müssen Gan'rul konsultieren, um sich Ritualkomponenten zu sichern und die präzisen Beschwörungsformeln zu erlernen, die nötig sind, um die beschworenen Kreaturen zu beherrschen, bevor sie ihren Meister verzehren."}},faq={{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein Hexenmeisterausbilder der Orcs, der in Orgrimmar stationiert ist. Er betreut Hexenmeister-Novizen und Fortgeschrittene der Horde und lehrt sie, wie man Dämonen aus dem Wirbelnden Nether beschwört und bindet.",al={"gan'rul blutauge","wer ist ganrul","rolle von ganrul bloodeye"}},{q="Wo kann ich Gan'rul Blutauge finden?",a="Er befindet sich in der Kluft der Schatten, dem unterirdischen Höhlensystem, das unter Orgrimmar verborgen liegt. Er steht dort zusammen mit anderen dunklen Praktizierenden, abseits der Hauptverkehrswege der Stadt.",al={"standort von ganrul","wo ist gan'rul blutauge","wo ist der ausbilder in die kluft der schatten"}},{q="Warum sind Hexenmeister in der Kluft der Schatten verborgen?",a="Kriegshäuptling Thrall und die schamanistische Gesellschaft der neuen Horde misstrauen der Teufelsmagie und der dämonischen Verderbnis aufgrund der vergangenen Versklavung der Orcs zutiefst. Hexenmeister sind innerhalb der Horde lediglich aufgrund ihres Nutzens geduldet, doch ihre Praxis ist in die Schatten verbannt, um zivile Unruhen zu vermeiden.",al={"warum in höhlen","warum werden hexenmeister versteckt","hintergrundwissen zu die kluft der schatten"}},{q="Welche Dämonen hilft Gan'rul zu beschwören?",a="Gan'rul leitet Hexenmeister durch die Rituale, die erforderlich sind, um sowohl den Leerwandler als auch den Sukkubus zu beschwören und zu unterwerfen. Das Abschließen seiner Aufgaben beweist, dass der Beschwörer über die notwendige Willenskraft verfügt, um diese Unholde zu kontrollieren.",al={"dämonen die ganrul lehrt","dämonenquests von ganrul","ausbilder für leerwandler und sukkubus"}},{q="Hat Gan'rul bekannte Verwandte?",a="Er teilt sich einen Nachnamen mit Halga Bloodeye, wenngleich ihre genaue Verwandtschaftsbeziehung nicht offiziell dokumentiert ist.",al={"verwandte von gan'rul","verwandter halga bloodeye"}},{q="Wer ist Strahad, den Gan'rul erwähnt?",a="Strahad Farsan ist ein versierter Hexenmeister, der im Brachland in der Nähe der Hügel bei Ratschet lebt. Gan'rul schickt vielversprechende Schüler schließlich zu Strahad für fortgeschrittenere Unterweisungen und größere Herausforderungen.",al={"die suche nach strahad","wer ist strahad","strahad quest"}}},fx={["11e29292"]={q="Auf wessen Seite steht Gan'rul Blutauge?",a="Gan'rul Blutauge dient der Horde und bildet Praktizierende der dunklen Magie unter Thralls Hauptstadt aus. Obwohl Hexenmeister von der schamanistischen Führung mit tiefem Misstrauen betrachtet werden, stellt Gan'rul seine arkanen Künste in den Dienst des Überlebens und der Stärke der Horde und unterweist jene, die bereit sind, Teufelsenergien zu ihrer Verteidigung zu nutzen.",al={"fraktion von gan'rul blutauge","loyalität von gan'rul","wem dient gan'rul"}},["67b7b1ae"]={q="Was will Gan'rul Blutauge?",a="Gan'rul will die Reihen fähiger Hexenmeister der Horde erweitern, indem er Initianden prüft und sie in der Beherrschung des Wirbelnden Nether unterweist. Er fordert Disziplin und okkulten Fokus und leitet Lehrlinge dazu an, gefährliche dämonische Entitäten wie Leerwandler und Sukkubi zu binden, damit die dunkle Magie als gehorsame Waffe dient und keine alles verzehrende Bedrohung darstellt.",al={"ziele von gan'rul","was will gan'rul","zweck von gan'rul"}}},fp="16,344,23.407.0,18.364.0,24.187.0,34.188.0,47.285.0,37.219.0,35.100.0,38.198.0"}
P.entries["npc:gann-stonespire"] = {n="Gann Steinkeil",s="Gann Steinkeil ist ein gekränkter Taurennomade, der auf den Straßen des Südlichen Brachlands nahe Bael Modan umherzieht. Von den Ausgräbern der Zwerge aus den angestammten Jagdgründen seines Stammes vertrieben, sinnt er auf Vergeltung gegen die vordringende Ausgrabungsstätte.",h="Gann Steinkeil ist ein gekränkter Taurennomade, der auf den Straßen des Südlichen Brachlands nahe Bael Modan...",kw={"bael modan","bael'dun","gann steinkeil","prospector khazgorm","südliches brachland","stonespire"},ang={["faction:Horde"]="Gann beizustehen bietet der Horde eine wichtige taktische Gelegenheit, den Expansionsdrang der im Südlichen Brachland verschanzten Allianz einzudämmen.",["race:Tauren"]="Ganns Not steht sinnbildlich für den größeren Kampf der nomadischen Tauren, deren angestammte Weiten und heilige Erde wiederholt von fremden Allianz-Expeditionen geschändet werden."},sec={{t="Vertrieben aus Bael Modan",b="Bevor die Zwergenexpedition aus Eisenschmiede eintraf, um die Festung Bael Modan zu errichten, diente das umliegende Land als angestammtes Territorium und Jagdgebiet für den Stamm von Gann Steinkeil. Die Zwergenbergarbeiter vertrieben die einheimischen Tauren mit Spitzhacken, Schusswaffen und schwerem Gerät von ihrem Boden und wiesen friedliche Annäherungsversuche zurück. Nun lagert Gann an der staubigen Straße des Südlichen Brachlands und weigert sich, sein Erbe kampflos aufzugeben, während er Reisende dazu bewegt, gegen die Ausgräber zurückzuschlagen."},{t="Rückforderung und Sabotage",b="In der Erkenntnis, dass friedliche Diplomatie völlig gescheitert ist, weist Gann Agenten der Horde an, den Zwergen die Kontrolle über die Ausgrabungsstätte zu entreißen. Seine Vergeltung zielt auf die Schlüsselfiguren der Expeditionsführung ab, insbesondere Prospector Khazgorm, bevor er zwergisches Sprengpulver und Munition zu einem Sprengsatz umfunktioniert. Indem er die Vorrichtung direkt unter der Zwergenflugmaschine zündet, will Gann deren technologischen Vorteil zunichtemachen und die Ehre seines vertriebenen Volkes wiederherstellen."}},faq={{q="Wer ist Gann Steinkeil?",a="Gann Steinkeil ist ein Taurenkrieger, dessen Stamm einst die Ländereien bewohnte, die heute von der Zwergenfestung Bael Modan besetzt sind. Nachdem er vertrieben wurde, als die Zwerge ihre Ausgrabungsstätte errichteten, wartet er nun am Straßenrand im Südlichen Brachland und sucht nach Rache sowie der Rückforderung der Heimat seines Volkes.",al={"wer ist gann","gann steinkeil lore","tauren vor bael modan"}},{q="Warum kämpft Gann gegen die Zwerge von Bael Modan?",a="Die Zwergenexpedition von Bael'dun traf im Südlichen Brachland ein und vertrieb die ansässigen Tauren gewaltsam aus ihren angestammten Jagdgründen, um ihre Ausgrabungsfestung zu errichten. Nachdem die Zwerge alle diplomatischen Bemühungen abgelehnt hatten, beschloss Gann, ihr Vorhaben mit Gewalt zu zerschlagen.",al={"warum hasst gann zwerge","warum bael modan angreifen","gann bael modan konflikt"}},{q="Was ist Ganns Plan gegen die Ausgrabung?",a="Gann fordert zunächst den Tod zwergischer Aufseher, darunter Prospector Khazgorm, um Ausgrabungsaufzeichnungen an sich zu bringen. Mithilfe gestohlener Zwergenmunition und Sprengvorräten veranlasst er anschließend den Bau einer Bombe, um die Flugmaschine der Expedition zu zerstören und deren technologische Vormachtstellung zu brechen.",al={"ganns racheplan","was macht gann","bael modan bombe"}},{q="Wo schlägt Gann Steinkeil sein Lager auf?",a="Er zieht auf der Straße knapp westlich von Bael Modan im Südlichen Brachland umher, direkt vor den Grenzen der Ausgrabungsstätte.",al={"wo ist gann","gann steinkeil standort"}}},fx={["60933082"]={q="Auf wessen Seite steht Gann Steinkeil?",a="Gann steht auf der Seite der Horde und seiner taurenischer Mitbrüder. Er bittet Horde-Champions, die das Südliche Brachland durchqueren, um Hilfe, um gegen die Bael'dun-Zwerge zurückzuschlagen, die in die heiligen Stätten seines Volkes eindringen.",al={"gehört gann steinkeil zur horde","fraktion von gann steinkeil","für wen kämpft gann"}},["59c620b8"]={q="Mit wem ist Gann Steinkeil verbunden?",a="Gann gehört einem Taurenstamm an, dessen angestammte Heimat die Ländereien umfasste, die nun von Bael Modan besetzt sind. Er handelt im Namen seines vertriebenen Volkes, das durch den Beginn der zwergischen Ausgrabungen vertrieben wurde.",al={"stamm von gann steinkeil","wer sind ganns leute","clan von gann steinkeil"}}},fp="15,239,25.485.0,24.466.1,23.308.0,47.289.0,43.297.1,41.134.0"}
P.entries["npc:gar-thok"] = {n="Gar'Thok",s="Gar'Thok ist ein erfahrener Orc-Krieger und Außenpostenkommandant, der in Klingenhügel in Durotar stationiert ist. Nachdem er am Hyjal gekämpft und die ersten Landungen von Kul Tiras an Durotars Küste überlebt hatte, koordiniert er nun die örtliche Verteidigung gegen menschliche Eindringlinge und einheimische Bedrohungen. Er weist junge Horde-Rekruten an, die das Tal der Prüfungen verlassen, um die roten Weiten der neuen Heimat zu sichern.",h="Gar'Thok ist ein erfahrener Orc-Krieger und Außenpostenkommandant, der in Klingenhügel in Durotar stationiert...",kw={"daelin","durotar","gar'thok","garthok","kul tiras","nazgrel","klingenhügel","rexxar","tiragarde"},ang={["class:Warrior"]="Als Frontkommandant, der sowohl dämonische Legionen als auch brutale Hinterhalte von Seeleuten überlebt hat, erwartet Gar'Thok von seinen Kriegskameraden soldatische Härte und unbedingten Gehorsam.",["faction:Horde"]="Gar'Thok sorgt dafür, dass frische Rekruten aller Horde-Völker die unsichere Lage ihres neuen Territoriums verstehen, und weist sie an, eindringende Überreste der Allianz zurückzuschlagen.",["race:Orc"]="Für junge Orcs, die das Tal der Prüfungen verlassen, verkörpert Gar'Thok die strenge, unnachgiebige Disziplin jener Veteranengeneration, die am Hyjal blutete, um Durotar zu erstreiten."},sec={{t="Ein Veteran der roten Weiten",b="Bevor er sich in Klingenhügel niederließ, verteidigte Gar'Thok das Orc-Lager während der apokalyptischen Schlacht um den Hyjal. Nach dem Dritten Krieg marschierte er unter Kriegshäuptling Thrall nach Durotar und diente in den ersten Tagen des Aufbaus der neuen Heimat als Leutnant unter Nazgrel. Als der Mok'Nathal-Wanderer Rexxar zum ersten Mal in Durotar eintraf, war es Gar'Thok, der ihn auf die aggressiven Stacheleber aufmerksam machte, die ihre Außenbezirke überfielen, und den Bestienmeister anwarb, um die zerbrechliche neue Siedlung zu beschützen."},{t="Das Überleben der Invasion des Admirals",b="Gar'Thoks Entschlossenheit wurde auf die Probe gestellt, als Großadmiral Daelin Prachtmeers Flotte aus Kul Tiras an den östlichen Küsten von Durotar landete. An einem abgelegenen Wachposten stationiert, musste Gar'Thok miterleben, wie seine Garnison überwältigt und von Marinesoldaten brutal niedergemetzelt wurde. Obwohl seine Streitkräfte dezimiert wurden, überlebte Gar'Thok den Ansturm. Die Erinnerung an diesen Überraschungsangriff festigte seine Wachsamkeit gegenüber den überlebenden Marinesoldaten, die noch immer Burg Tiragarde und die Schiffswracks an der Küste besetzt halten."},{t="Verteidigung von Klingenhügel",b="Heute überwacht Gar'Thok von den Kasernen in Klingenhügel aus die kriegerische Verteidigung von Zentral-Durotar. Er verliert keine Zeit mit Höflichkeiten und beauftragt aufstrebende Krieger, Schamanen und Späher der Horde umgehend damit, feindselige Überreste aus Kul Tiras zu beseitigen, geborgene Vorräte zurückzuholen und in den Küstenruinen zurückgelassene Militärbefehle zu sichern. Für ihn ist die Sicherheit von Durotar keineswegs garantiert, was ständigen Druck auf jeden erfordert, der das Recht der Horde auf diesen Boden infrage stellt."}},faq={{q="Wer ist Gar'Thok?",a="Gar'Thok ist ein in Klingenhügel stationierter Orc-Offizier, der die örtliche militärische Reaktion gegen feindliche Kräfte in Durotar organisiert. Er ist ein Veteran des Dritten Krieges, der während der Gründung von Orgrimmar unter Nazgrel diente.",al={"garthok lore","wer ist garthok","kommandant von klingenhügel"}},{q="Wo kämpfte Gar'Thok, bevor er nach Klingenhügel kam?",a="Er kämpfte in der Schlacht um den Hyjal und bewachte die Befestigungen der Orcs gegen die Brennende Legion und die Geißel. Später diente er an einem Grenzaußenposten in Durotar und arbeitete mit Rexxar zusammen, um frühe Angriffe der Stacheleber abzuwehren.",al={"garthok vergangenheit","garthok hyjal","garthok geschichte"}},{q="Warum hasst Gar'Thok die Menschen in Durotar so sehr?",a="Während der von Großadmiral Daelin Prachtmeer angeführten Invasion überfielen Seeleute aus Kul Tiras Gar'Thoks Außenposten an der Küste und schlachteten seine Männer ab. Er überlebte den Angriff und widmet sich seither unermüdlich der Vernichtung der verbliebenen Lager der Soldaten.",al={"warum garthok kul tiras hasst","garthok menschen","burg tiragarde garthok"}},{q="Gegen welche Bedrohungen schickt Gar'Thok Abenteurer in den Kampf?",a="Gar'Thok schickt Rekruten aus, um die feindseligen Kul Tiraner zu bekämpfen, die sich in Burg Tiragarde verschanzt haben, Vorräte aus den Schiffswracks an der Küste zurückzuholen, eindringende Stacheleber zurückzudrängen und alle von menschlichen Befehlshabern zurückgelassenen Befehle aufzudecken.",al={"garthok quests","was will garthok","klingenhügel quests"}},{q="Wie ist seine Beziehung zu Nazgrel und Thrall?",a="Gar'Thok diente während der ersten Kolonialisierungsexpeditionen in Durotar als vertrauter Leutnant unter Nazgrel und handelte direkt unter der Autorität von Kriegshäuptling Thrall, um die Grenzen des neu beanspruchten Gebiets zu sichern.",al={"garthok nazgrel","garthok thrall","garthok rang"}},{q="Wo ist Gar'Thok zu finden?",a="Gar'Thok steht vor dem Hauptwachturm und den Kasernen in Klingenhügel, der zentralen Siedlung von Durotar südlich von Orgrimmar.",al={"garthok standort","wo ist garthok","garthok finden"}}},fx={["61b8b646"]={q="Auf wessen Seite steht Gar'Thok?",a="Gar'Thok ist der Horde und Kriegshäuptling Thrall voll und ganz loyal. Er ist in Durotar unter dem Kommando von Nazgrel stationiert und arbeitet unermüdlich daran, die entstehende Heimat der Orcs zu verteidigen und sicherzustellen, dass neu eingetroffene Krieger bereit sind, die Grenzen der Horde zu schützen.",al={"fraktion von gar'thok","gehört gar'thok zur horde","wem dient gar'thok"}},["7b499593"]={q="Was will Gar'Thok?",a="Gar'Thok will Durotar fest gegen alle Bedrohungen gesichert sehen. Nachdem er mit ansehen musste, wie sein Außenposten von Invasoren aus Kul Tiras niedergemetzelt wurde, sinnt er auf Rache an den verbliebenen menschlichen Seeleuten an der Küste und fordert die Unterdrückung der eindringenden Stacheleber, die die Siedlung bedrängen.",al={"ziel von gar'thok","was will gar'thok","motive von gar'thok"}},["007248aa"]={q="Warum ist Gar'Thok hier?",a="Nach der Verwüstung seines Küstenaußenpostens durch Streitkräfte aus Kul Tiras bezog Gar'Thok einen Posten in Klingenhügel. Von dieser zentralen Siedlung aus organisiert er die Verteidigung von Durotar und leitet angehende Horde-Champions gegen feindliche Übergriffe.",al={"warum ist gar'thok in klingenhügel","warum ist gar'thok hier","aufgabe von gar'thok in klingenhügel"}}},fp="8,378,27.491.0,32.468.0,21.473.0,16.219.0,53.217.0,53.239.0,53.219.0,49.219.0,28.133.0"}
P.entries["npc:gart-mistrunner"] = {n="Gart Nebelläufer",s="Gart Nebelläufer ist der ansässige Druidenlehrer in Camp Narache auf der Hochwolkenebene. Er heißt Tauren-Neulinge willkommen, die von der Erdenmutter gerufen wurden, und leitet sie durch ihre ersten Riten der Naturmagie.",h="Gart Nebelläufer ist der ansässige Druidenlehrer in Camp Narache auf der Hochwolkenebene.",kw={"camp narache","druidenlehrer","gart nebelläufer","mistrunner","mulgore","die hochwolkenebene","taurendruide"},ang={["class:Druid"]="Für Taurendruiden ist Gart Nebelläufer der allererste Lehrmeister, der ihren Bund mit der Wildnis und die Gaben der Erdenmutter prägt.",["race:Tauren"]="Gart verkörpert das Wiederaufleben der uralten druidischen Traditionen der Shu'halo und gibt das Wissen der Ahnen an die Jugend von Camp Narache weiter."},sec={{t="Mentor der Hochwolkenebene",b="Gart Nebelläufer wacht über Camp Narache und verkörpert den uralten druidischen Pfad, der unter den Shu'halo neu entfacht wurde. Neue Taurendruiden werden bei ihren ersten Schritten auf der Hochwolkenebene direkt zu Gart geschickt, oft mit einer Tiefgrünen Notiz, die sie seiner Obhut anvertraut. Durch seine geduldige Führung lernen junge Praktizierende, mit der natürlichen Welt in Einklang zu treten, und schöpfen aus den wiederherstellenden Kräften der Natur und dem Mondglanz von Mu'sha, um ihre Verbündeten zu heilen und Bedrohungen des Landes niederzustrecken."}},faq={{q="Wer ist Gart Nebelläufer?",a="Gart Nebelläufer ist ein Tauren-Druidenlehrer in Camp Narache auf der Hochwolkenebene in Mulgore. Er unterweist angehende Taurendruiden in ihren ersten Zaubern und Riten.",al={"wer ist gart","gart nebelläufer hintergrundgeschichte","gart nebelläufer"}},{q="Welche Zauber lehrt er neu erwachten Druiden?",a="Gart führt Anfänger an grundlegende Naturfähigkeiten heran und lehrt frühe Heilzauber wie Heilende Berührung sowie offensive Naturmagie wie Mondfeuer.",al={"was lehrt gart","gart nebelläufer ausbildung","druidenzauber camp narache"}},{q="Was ist seine Verbindung zum Mistrunner-Clan?",a="Mistrunner ist schlicht Garts Familienname. Es gibt keine Überlieferungen, die einen Mistrunner-Stamm beschreiben oder mehr über seine Verwandtschaft verraten; er ist lediglich als Druidenlehrer von Camp Narache bekannt.",al={"mistrunner clan","wer sind die mistrunner"}}},fx={fd7992e7={q="Auf wessen Seite steht Gart Nebelläufer?",a="Gart Nebelläufer ist den Taurenstämmen ergeben und steht auf der Seite der Horde. Stationiert im Herzen der Hochwolkenebene in Camp Narache, arbeitet er in seiner angestammten Heimat daran, die Traditionen der Tauren zu bewahren, und fördert junge Praktizierende, die die Gaben der Natur nutzen, um das Land zu schützen und ihrem Volk zu dienen.",al={"fraktion von gart nebelläufer","wem dient gart","gart nebelläufer horde"}},["4b2be6b9"]={q="Warum ist Gart Nebelläufer hier?",a="Gart lebt in Camp Narache, um angehende Tauren zu unterweisen, die den Ruf der Wildnis hören. Als Druidenausbilder auf der Hochwolkenebene führt er neu erwachte Initianden in die Lehren der Natur ein und leitet ihre frühe spirituelle und kämpferische Entwicklung, bevor sie sich in die weiteren Ebenen von Mulgore hinauswagen.",al={"warum ist gart in camp narache","zweck von gart nebelläufer","was macht gart nebelläufer hier"}},["8def0ffd"]={q="Was will Gart Nebelläufer?",a="Gart will die Harmonie zwischen den Tauren und der Erdenmutter fördern, indem er neue Druiden im natürlichen Gleichgewicht ausbildet. Er möchte, dass junge Initianden frühe Riten wie verjüngende Heilung und Gleichgewichtszauber meistern, um sie darauf vorzubereiten, das Land zu heilen und ihren Stamm gegen eindringende Bedrohungen zu verteidigen.",al={"ziele von gart nebelläufer","was will gart","motive von gart nebelläufer"}}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gath-ilzogg"] = {n="Gath'Ilzogg",s="Gath'Ilzogg ist der furchterregende Kriegsfürst der Schwarzfelsorks, der die Invasionsstreitmacht anführt, die Burg Steinwacht im Rotkammgebirge besetzt hält. Unter seiner brutalen Führung eroberten die Orks die Festung und starteten verheerende Überfälle auf die Stadt Seenhain, was ihm ein dringendes Kopfgeld des verzweifelten Magistrats der Stadt einbrachte.",h="Gath'Ilzogg ist der furchterregende Kriegsfürst der Schwarzfelsorks, der die Invasionsstreitmacht anführt...",kw={"schwarzfels","gath'ilzogg","gathilzogg","seenhain","morganth","singe","solomon","steinwacht","burg steinwacht"},ang={["faction:Alliance"]="Gath'Ilzogg zur Strecke zu bringen bricht das Rückgrat der Schwarzfelsoffensive, die Seenhain bedroht, und folgt dem verzweifelten Ruf von Magistrat Solomon.",["race:Orc"]="Gath'Ilzogg verkörpert die alten, kriegerischen Pfade des Schwarzfelsclans unter der Dunklen Horde, völlig getrennt von Thralls neuer Horde in Kalimdor."},sec={{t="Die Geißel von Steinwacht",b="Gath'Ilzogg marschierte auf Befehl, das Rotkammgebirge für den Schwarzfelsclan zu sichern, aus der Brennenden Steppe nach Norden. Unterstützt von der finsteren Hexerei des abtrünnigen menschlichen Hexenmeisters Morganth überwältigte Gath'Ilzoggs Kriegsschar die Verteidiger von Burg Steinwacht und sicherte sich die Anhöhe, die die gesamte Region überblickt. Aus dieser verschanzten Redoute leitet er aggressive Angriffe in die Täler und hinab zur Brücke von Seenhain, wodurch die menschliche Siedlung zusehends eingeschnürt wird. Er kämpft selten allein und hält elitäre Schwarzfelswachen sowie einen bösartigen schwarzen Drachenwelpen namens Singe stets an seiner Seite."},{t="Ein brüchiger Halt",b="Trotz seiner Eroberung von Steinwacht brachte Gath'Ilzoggs Sieg neue Komplikationen mit sich. Morganth wandte sich rasch gegen seine einstigen orkischen Verbündeten und stellte eine Armee von Schattenfellgnollen unter Leutnant Fangore auf, die gleichermaßen Jagd auf Schwarzfelspatrouillen und menschliche Reisende macht. Gleichzeitig setzte Magistrat Solomon ein offenes Kopfgeld auf den Kopf des Kriegsfürsten aus und bat alle Söldner oder Abenteurer der Allianz inständig darum, die Zinnen von Burg Steinwacht zu erklimmen und Gath'Ilzoggs Schrecken zu beenden, bevor die Stadt gänzlich fällt."}},faq={{q="Wer ist Gath'Ilzogg?",a="Gath'Ilzogg ist ein Kriegsfürst der Orks, der dem Schwarzfelsclan angehört. Er führt die Vorhut an, die in das Rotkammgebirge einfiel und Burg Steinwacht erfolgreich der Allianz entriss.",al={"gath'ilzogg geschichte","wer ist gathilzogg","schwarzfels boss rotkammgebirge"}},{q="Wo ist Gath'Ilzogg zu finden?",a="Er hat sich ganz oben auf Burg Steinwacht verschanzt, die in den östlichen Klippen des Rotkammgebirges liegt.",al={"gath'ilzogg aufenthaltsort","wo ist gathilzogg","gathilzogg finden"}},{q="Warum hat Gath'Ilzogg einen Drachenwelpen?",a="Gath'Ilzogg wird von einem schwarzen Drachenwelpen namens Singe begleitet, von dem weithin angenommen wird, dass er ein Geschenk von Lord Victor Nefarius war, um den Kriegsfürsten für die erfolgreiche Einnahme von Burg Steinwacht zu belohnen.",al={"warum welpe bei gathilzogg","singe drache","schwarzer drachenwelpe gathilzogg"}},{q="Warum ist ein Kopfgeld auf ihn ausgesetzt?",a="Magistrat Solomon von Seenhain setzte ein hochdotiertes Kopfgeld auf Gath'Ilzoggs Kopf aus, weil die ständigen Überfälle des Kriegsfürsten und die Besetzung von Steinwacht Seenhain unmittelbar mit der völligen Zerstörung bedrohen.",al={"gesucht gath'ilzogg","wer will gathilzogg tot sehen","magistrat solomon kopfgeld"}},{q="Was geschah zwischen Gath'Ilzogg und Morganth?",a="Der menschliche Hexenmeister Morganth half Gath'Ilzogg anfangs mit dunkler Magie bei der Eroberung von Steinwacht. Doch sobald die Festung gefallen war, verriet Morganth die Orks und stellte eine Armee von Schattenfellgnollen auf, um sowohl die Menschheit als auch den Schwarzfelsclan anzugreifen.",al={"morganth gathilzogg allianz","warum greifen gnolle orks an","morganth verrat"}}},fx={["9f2c44f6"]={q="Auf wessen Seite steht Gath'Ilzogg?",a="Gath'Ilzogg ist ein Kriegsfürst des Schwarzfelsclans, loyal zur Dunklen Horde, die im Schwarzfels verwurzelt ist. Er und seine Streitkräfte führen aktiv Krieg gegen das Königreich Sturmwind und zeigen äußerste Feindseligkeit gegenüber der Allianz und jedem, der ihr erobertes Gebiet betritt.",al={"fraktion von gath'ilzogg","wem dient gath'ilzogg","gehört gath'ilzogg zum schwarzfelsclan"}},["56c8e0ec"]={q="Was will Gath'Ilzogg?",a="Von seiner Festung in Burg Steinwacht aus plant Gath'Ilzogg die Zerstörung von Seenhain und die vollständige Eroberung des Rotkammgebirges. Er leitet Überfälle auf menschliche Siedlungen und arbeitet daran, die Herrschaft des Schwarzfelsclans über die umliegenden Ländereien auszuweiten.",al={"was ist gath'ilzoggs ziel","plan von gath'ilzogg","warum greift gath'ilzogg an"}},d3a450f6={q="Warum ist Gath'Ilzogg hier?",a="Gath'Ilzogg führte den Angriff an, der die Verteidiger der Allianz in Burg Steinwacht überwältigte. Nachdem er die Festung eingenommen hat, nutzt er sie nun als befestigte Operationsbasis, um tiefer in das Rotkammgebirge vorzustoßen und Überfälle auf Seenhain zu organisieren.",al={"warum ist gath'ilzogg im rotkammgebirge","warum ist gath'ilzogg in burg steinwacht","gath'ilzogg burg steinwacht"}},d6829113={q="Mit wem ist Gath'Ilzogg verbunden?",a="Über das Kommando über die örtlichen Schwarzfels-Orcs hinaus ging Gath'Ilzogg einst ein tückisches Bündnis mit dem abtrünnigen menschlichen Hexenmeister Morganth ein, um Burg Steinwacht einzunehmen. Er befehligt außerdem den Welpen Seng, eine Kreatur, die ihm wahrscheinlich von Lord Victor Nefarius als Belohnung für seinen Sieg überlassen wurde.",al={"verbündete von gath'ilzogg","wer arbeitet mit gath'ilzogg zusammen","verbindungen von gath'ilzogg"}},b07f2498={q="Warum wird Gath'Ilzogg gefürchtet?",a="Gath'Ilzogg bewies seine Gefährlichkeit, indem er den Fall von Burg Steinwacht erfolgreich orchestrierte und die örtliche Garnison der Allianz zerschmetterte. Magistrat Solomon betrachtet ihn als die größte militärische Bedrohung für das Überleben von Seenhain, was ein hohes Kopfgeld auf den Kriegsfürsten ausgesetzt hat.",al={"warum ist gath'ilzogg gefährlich","ist gath'ilzogg bekannt","ruf von gath'ilzogg"}}},fp="11,321,25.571.0,14.490.1,19.167.0,31.108.0,41.182.0,34.205.0,47.241.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="Gaxim Rostknirsch",s="Gaxim Rostknirsch ist ein ehrgeiziger Gnomengelehrter und Tüftler, der in einem kleinen Lager der Allianz am Weberpass im Steinkrallengebirge stationiert ist. Als Vertreter der Erleuchteten Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften möchte er skeptischen Nachtelfen beweisen, dass fortschrittliche Handwerkskunst und Alchemie ihr Waldreich bewahren können. Seine wissenschaftliche Neugier wird nur von einer erbitterten Fehde gegen die zerstörerischen Machenschaften der Venture Company übertroffen.",h="Gaxim Rostknirsch ist ein ehrgeiziger Gnomengelehrter und Tüftler, der in einem kleinen Lager der Allianz am...",kw={"versammlung","gaxim","gnom","kaela","rustfizzle","steinkrallengebirge","venture company","weberpass","scherwindklippe"},ang={["faction:Alliance"]="Am gefährlichen Weberpass gelegen, übernimmt Gaxim wichtige Aufklärungs-, Spionage- und Sabotagemissionen, um die aggressiven industriellen Vorstöße im Steinkrallengebirge einzudämmen.",["profession:Engineering"]="Gaxim setzt ingenieurwissenschaftliche Prinzipien im Feld um, indem er verdeckte Operationen und taktische Geräte entwirft, die speziell darauf ausgelegt sind, die primitive Maschinerie der Venture Company zu stören.",["race:Gnome"]="Gaxim verkörpert den akademischen Stolz der Gnome von seiner besten Seite und beweist den alten Kulturen Kalimdors, dass Zahnräder und Reagenzien einen Wald ebenso gut retten können wie Naturmagie.",["race:NightElf"]="Auch wenn Traditionalisten über seine surrenden Apparaturen und blubbernden Phiolen spotten mögen, ist Gaxim ein treuer Verbündeter, der die Grenzen von Eschental und dem Steinkrallengebirge aktiv vor der Goblinindustrie verteidigt."},sec={{t="Ein wissenschaftlicher Gesandter",b="Während Nachtelfen traditionell auf uraltes Druidentum und Naturmagie vertrauen, kam Gaxim Rostknirsch in die zerklüfteten Pässe des Steinkrallengebirges, um eine grundlegend andere Perspektive aufzuzeigen. Als Vertreter der Erleuchteten Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften glaubt er aufrichtig daran, dass berechnete Mechanismen und chemische Lösungen die Wildnis von Kalimdor genauso effektiv verteidigen und wiederherstellen können wie Gebete zu Elune. An der Seite der Schildwache Kaela Schattenspeer am Weberpass rastend, arbeitet er unermüdlich daran, seine hochgewachsenen, zurückgezogen lebenden Verbündeten von den ökologischen Vorzügen der Ingenieurskunst zu überzeugen."},{t="Sabotage an den Sägen",b="Einen Großteil seiner Energie wendet Gaxim gegen die Venture Company auf, deren Kahlschlag und industrielle Gier die nahe gelegene Scherwindklippe entweihen. In der Überzeugung, dass plumpe Goblinmaschinerie weder Respekt noch Gnade verdient, koordiniert Gaxim verdeckte Operationen und volatile chemische Sabotageakte gegen deren Abholzungsaktivitäten. Das Lahmlegen ihrer Schredder und der Diebstahl ihrer Baupläne ist für ihn nicht bloß taktische Kriegsführung – es ist ein praktischer Beweis dafür, dass überlegener Gnomengeist stets über rücksichtslose Ausbeutung durch Konzerne triumphiert."}},faq={{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein Gnomengelehrter und Erfinder, der an einem Ausguck der Allianz am Weberpass im Steinkrallengebirge stationiert ist. Er dient als Gesandter der Erleuchteten Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften.",al={"wer ist gaxim","gaxim rostknirsch lore","gnom im steinkrallengebirge"}},{q="Was ist die Erleuchtete Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften?",a="Es ist eine akademische und wissenschaftliche Gesellschaft von Gnomen, die sich der Verschmelzung der Disziplinen Arkanmagie, alchemistische Gemische und Maschinenbau verschrieben hat. Gaxim vertritt ihre Ideale in der Ferne Kalimdors.",al={"erleuchtete versammlung","gaxim fraktion","gaxim gruppe"}},{q="Warum arbeitet Gaxim mit den Nachtelfen zusammen?",a="Gaxim möchte den Nachtelfen beweisen, dass gnomische Wissenschaft und Alchemie natürliche Wälder aktiv schützen und heilen können, und bietet so neben dem traditionellen Druidentum eine moderne Antwort der Allianz auf den Waldschutz.",al={"warum ist gaxim hier","gaxim nachtelfen","gaxim aufgabe"}},{q="Warum hasst Gaxim die Venture Company?",a="Die Venture Company betreibt an der Scherwindklippe mit plumpen Maschinen und giftiger Verschmutzung rücksichtslosen Kahlschlag. Gaxim verachtet ihre skrupellose Ausbeutung und genießt es, flüchtige Chemikalien und Sabotage gegen ihre Unternehmungen einzusetzen.",al={"gaxim venture co","gaxim gegen venture company","warum venture co bekämpfen"}},{q="Wer lagert mit Gaxim am Weberpass?",a="Er teilt sich seinen kleinen Außenposten mit Kaela Schattenspeer, einer Nachtelfenschildwache, die über die Pfade zur Scherwindklippe wacht.",al={"gaxim begleiter","wer ist bei gaxim","gaxim und kaela"}},{q="Wo ist Gaxim Rostknirsch zu finden?",a="Er befindet sich in einem bescheidenen Lager der Allianz am Weberpass, direkt südwestlich der industriellen Holzfällergruben der Scherwindklippe im Steinkrallengebirge.",al={"gaxim aufenthaltsort","wo ist gaxim","gaxim rostknirsch karte"}}},fx={d5f6878f={q="Auf wessen Seite steht Gaxim Rostknirsch?",a="Gaxim ist der Allianz loyal und arbeitet direkt an der Seite der Nachtelfen im Steinkrallengebirge. Als Vertreter der Erleuchteten Versammlung für Arkanologie, Alchemie und Ingenieurswissenschaften fungiert er als Gesandter gnomischer Erfindungsgabe und will skeptischen Kaldorei-Verbündeten beweisen, dass die Kombination von arkanem Wissen, chemischen Mischungen und mechanischer Handwerkskunst die Natur bewahren statt zerstören kann.",al={"fraktion von gaxim rostknirsch","gehört gaxim zur allianz","für wen arbeitet gaxim"}}},fp="16,465,21.595.0,19.523.0,24.238.0,81.204.0,42.216.0,40.225.0,43.126.0,36.158.0"}
P.entries["npc:gazin-tenorm"] = {n="Gazin Tenorm",s="Gazin Tenorm ist ein Zwerg, der nahe dem Altar in der Kathedrale des Lichts in Sturmwind stationiert ist. Zusammen mit seinem Kameraden Henze Faulk unternahm er eine gefährliche Spähmission, um Beweise für die Aktivitäten der Bruderschaft der Defias für die Berater des Königs zu sammeln.",h="Gazin Tenorm ist ein Zwerg, der nahe dem Altar in der Kathedrale des Lichts in Sturmwind stationiert ist.",kw={"kathedrale des lichts","defias","duthorian rall","gazin tenorm","henze faulk","paladin","tome of divinity"},ang={["class:Paladin"]="Initianden, die die Pfade des Mitgefühls und der Erlösung erlernen, treffen Gazin in der Kathedrale des Lichts, um seinem gefallenen Waffenbruder Henze Faulk zu helfen.",["race:Dwarf"]="Gazin repräsentiert die beständige Solidarität zwischen Eisenschmiede und Sturmwind und dient als zwergischer Champion, der bereit ist, sich im Namen der Berater des Königreichs den Wegelagerern von Elwynn zu stellen."},sec={{t="Ein Späher in der Kathedrale",b="Während Gazin Tenorm seine Tage in den friedlichen Hallen der Kathedrale des Lichts verbringt, sind seine Gedanken immer noch draußen in der Wildnis des Waldes von Elwynn. Gazin und sein enger Freund Henze Faulk brachen zu einer dringenden Mission in die Wälder auf: Sie sollten stichhaltige Beweise für die Bewegungen der Bruderschaft der Defias sammeln, um diese dem königlichen Hof zu präsentieren. Die Expedition lief schief, als sie von Kräften der Defias überfallen wurden. Gazin konnte mit knapper Not in die Sicherheit von Sturmwind entkommen, aber Henze blieb in tödlicher Gefahr zurück, was Gazin dazu veranlasste, einen standhaften Helden des Lichts zu suchen, der seinem Gefährten zu Hilfe eilt."}},faq={{q="Wo finde ich Gazin Tenorm?",a="Gazin Tenorm befindet sich in der Kathedrale des Lichts in Sturmwind, wo er nahe dem hinteren Altar bei hochrangigen Klerikern und Paladin-Mentoren steht.",al={"gazin standort","wo ist gazin tenorm","wo ist gazin"}},{q="Was ist Gazin Tenorm im Wald von Elwynn zugestoßen?",a="Während er mit seinem Gefährten Henze Faulk die Bruderschaft der Defias untersuchte, geriet Gazin in einen Hinterhalt der Gesetzlosen. Er schaffte es, sich freizukämpfen und zurück nach Sturmwind zu fliehen, doch durch die Ereignisse blieb sein Freund draußen im Wald zurück.",al={"gazins geschichte","was passierte mit gazin","warum ist gazin verletzt"}},{q="Warum untersuchte Gazin die Bruderschaft der Defias?",a="Gazin und Henze Faulk begaben sich in den Wald von Elwynn, um unwiderlegbare Beweise für die illegalen Aktivitäten der Bruderschaft der Defias zu sammeln, mit der Absicht, diese stichhaltigen Beweise direkt den Beratern des Königs in Sturmwind vorzulegen.",al={"warum defias untersuchen","gazins mission","gazin henze defias"}},{q="Welche Verbindung hat Gazin zu den Prüfungen der Paladine?",a="Duthorian Rall verweist angehende menschliche Paladine, die das Tome of Divinity anstreben, an Gazin. Gazin bietet dann die Mittel und Anweisungen zur Rettung seines gefallenen Partners Henze Faulk an, was den Mut und die Barmherzigkeit des Initianden auf die Probe stellt.",al={"gazin tome of divinity","paladin-quest gazin","henze faulk quest"}}},fx={["2ec8b348"]={q="Mit wem ist Gazin Tenorm verbunden?",a="Gazin arbeitet eng mit seinem Kollegen, dem Ermittler Henze Faulk, zusammen. Er teilt außerdem ein starkes Vertrauensverhältnis mit Duthorian Rall, der vielversprechende junge Paladine zur Unterstützung zu Gazin schickt, damit sie gemeinsam ihre Pflicht erfüllen können, das Reich zu schützen.",al={"gazin tenorm verbündete","gazin verbindungen","mit wem arbeitet gazin zusammen"}},d8d56684={q="Wer ist Gazin Tenorm?",a="Gazin Tenorm ist ein zwergischer Ermittler, der derzeit Zuflucht in der Kathedrale des Lichts in Sturmwind sucht. In Abstimmung mit königlichen Kontakten suchten er und sein Partner nach Beweisen, um die wachsende Bedrohung durch die Defias zu bestätigen, die sich direkt vor den Toren der Hauptstadt regt.",al={"wer ist gazin","wer ist gazin tenorm","identität von gazin tenorm"}},e9ee1d11={q="Auf wessen Seite steht Gazin Tenorm?",a="Gazin ist der Allianz und dem Königreich Sturmwind vollkommen loyal. Er arbeitet an der Seite der Priesterschaft und der Paladine der Kathedrale des Lichts und bemüht sich, für den Hof des Königs stichhaltige Informationen über die subversive Tätigkeit der Rebellen im Wald von Elwynn zu sammeln.",al={"fraktion von gazin tenorm","gehört gazin zur allianz","wem dient gazin"}},["22d0c57e"]={q="Was will Gazin Tenorm?",a="Nachdem er einen Hinterhalt von Defias-Schlägern nur knapp überlebt hat, will Gazin verzweifelt, dass sein Begleiter Henze Faulk aus dem Wald von Elwynn gerettet wird. Darüber hinaus will er die Machenschaften der The Defias Brotherhood den Beratern des Königs offenlegen, bevor ihr Aufstand weiter an Boden gewinnt.",al={"was will gazin","ziel von gazin tenorm","wonach sucht gazin"}},["6cef862e"]={q="Warum ist Gazin Tenorm in der Kathedrale des Lichts?",a="Nach einer gewaltsamen Konfrontation mit den Defias, die ihn erschüttert und zur Flucht gezwungen hatte, suchte Gazin die heilige Zuflucht der Kathedrale des Lichts auf. Hier, nahe dem Altar, erholt er sich unter dem wachsamen Schutz von Duthorian Rall und der Silbernen Hand.",al={"warum ist gazin in der kathedrale","warum ist gazin tenorm hier","gazin kathedrale des lichts"}}},fp="12,235,24.580.0,30.154.0,47.242.0,51.213.0,45.212.0"}
P.entries["npc:gazrog"] = {n="Gazrog",s="Gazrog ist ein Orc-Krieger, der im Wegekreuz im Herzen des Brachlands stationiert ist. Betraut mit der Aufrechterhaltung der Logistik und Sicherheit entlang der gefährlichen Straßen der Savanne, rekrutiert er fähige Reisende der Horde, um sich regionaler Bedrohungen anzunehmen und verschollene Patrouillen aufzuspüren.",h="Gazrog ist ein Orc-Krieger, der im Wegekreuz im Herzen des Brachlands stationiert ist.",kw={"brachland","das wegekreuz","dogran","gazrog","hordenaußenposten","raptorendiebe","gestohlenes silber"},ang={["faction:Horde"]="Gazrog ist eine frühe Anlaufstelle für Horden-Abenteurer, die Durotar oder Mulgore verlassen, und bietet entscheidende Aufgaben zur Errichtung sicherer Reisewege quer durch Kalimdor.",["race:Orc"]="Als Orc-Veteran, der das Wegekreuz hütet, verkörpert Gazrog die unerschrockene, kompromisslose Entschlossenheit, die nötig ist, um das unbarmherzige Grenzland von Kalimdor zu zähmen."},sec={{t="Ein Wachposten des Wegekreuzes",b="Das Wegekreuz dient als lebenswichtiger Knotenpunkt für den gesamten Transit der Horde durch Kalimdor, doch durch seine isolierte Lage sind die Nachschubwege gleichermaßen anfällig für Plünderer wie für Bestien. Gazrog hält an der Seite der Verteidiger der Siedlung Wache und sorgt dafür, dass Fracht, Münzen und Kuriere ihr Ziel erreichen. Die Ordnung in einer weitläufigen Wildnis aufrechtzuerhalten erfordert ständige Wachsamkeit, und Gazrog verlässt sich stark auf vorbeikommende Abenteurer, um Krisen zu bewältigen, die sich jenseits der Palisaden des Außenpostens anbahnen."},{t="Gefahren der Savanne",b="Zwischen räuberischen Raptoren, die Pfade heimsuchen, und aggressiven Borstennacken-Klans, die Späher überfallen, nehmen Gazrogs Pflichten kein Ende. Häufig koordiniert er Maßnahmen gegen Straßenräuberei – wie etwa die Wiederbeschaffung gestohlener Horden-Lieferungen – und verfolgt das Schicksal vermisster Soldaten wie Grunzer Dogran, der verletzt in Gefangenschaft der Stacheleber geriet."}},faq={{q="Wo ist Gazrog zu finden?",a="Gazrog befindet sich im Wegekreuz, der zentralen Siedlung, die die nördlichen, südlichen und östlichen Routen des Brachlands verbindet.",al={"gazrog standort","wo ist gazrog","gazrog das wegekreuz"}},{q="Welche Rolle spielt Gazrog für die Horde?",a="Er agiert als Einsatzkoordinator und Wache im Wegekreuz und vergibt Aufgaben zur Sicherung regionaler Versorgungswege, zur Bergung abgefangener Lieferungen und zum Auffinden vermisster Hordenmitglieder.",al={"gazrog aufgabe","wer ist gazrog","was macht gazrog"}},{q="Was geschah mit dem gestohlenen Silber, nach dem Gazrog fragt?",a="Münztransporte der Horde geraten häufig ins Visier gewiefter Savannenraptoren und von Opportunisten, die die Pfade des Brachlands durchstreifen. Dies veranlasst Gazrog dazu, Recken auszusenden, um die Bestien zur Strecke zu bringen und die Fracht zu bergen.",al={"gestohlenes silber quest","wer hat das silber gestohlen","brachland gestohlene lieferung"}},{q="Wer ist Dogran?",a="Dogran ist ein Grunzer der Horde, der zum Wegekreuz abkommandiert wurde, um mit Gazrog zusammenzuarbeiten. Er kehrte nie vom Dienst zurück: Gazrog hat gehört, dass er noch am Leben, aber verletzt und Gefangener der Stacheleber ist – eine Nachricht, die er Dograns Gefährtin Zankaja lieber vorenthalten möchte.",al={"neuigkeiten von dogran","wo ist dogran","gazrog dogran"}},{q="Gehört Gazrog zu Ratschet oder den Goblins?",a="Nein. Gazrog dient der Horde direkt vom Wegekreuz aus und sichert die Interessen der Orcs, Tauren und Trolle im gesamten zentralen Brachland.",al={"ist gazrog ratschet","gazrog fraktion","gazrog goblin"}},{q="Warum stehlen Raptoren Vorräte im Brachland?",a="Niemand ist sich ganz sicher. Die Raptoren versteckten das gestohlene Silber in ihren Nestern in den Raptorgründen südlich von Ratschet, und Gazrog fragt sich, ob an den Geschichten über ihre Intelligenz nicht doch mehr Wahres dran ist, als er vermutet hatte.",al={"raptorendiebe warum","stehlen raptoren dinge","raptoren glitzernd"}}},fx={fdfa6042={q="Was will Gazrog?",a="Gazrog möchte für die Horde wichtige Vorräte sichern und im Brachland für Ordnung sorgen. Er beauftragt Abenteurer damit, die von einheimischen Raptoren gestohlene Silberlieferung zurückzuholen, und sucht zudem nach Informationen über das Schicksal seines vermissten Kameraden Dogran.",al={"was will gazrog","was braucht gazrog","gazrog ziele"}},d6aec43d={q="Warum ist Gazrog hier am Wegekreuz?",a="Gazrog ist am strategischen Außenposten des Wegekreuzes stationiert und überwacht dort Operationen, die für den Stützpunkt der Horde im zentralen Kalimdor von entscheidender Bedeutung sind. Er ist hier, um lokale Bedrohungen abzuwehren, die Karawanen angreifen, vermisste Späher der Horde aufzuspüren und gestohlene Ressourcen zurückzuholen, die für die Verteidigung des Außenpostens unerlässlich sind.",al={"warum ist gazrog hier","zweck von gazrog am wegekreuz","warum ist gazrog im brachland"}}},fp="6,258,28.475.0,16.330.0,26.129.0,41.187.0,53.196.0,14.237.0,49.145.0,49.211.0"}
P.entries["npc:gelbin-mekkatorque"] = {n="Gelbin Mekkadrill",s="Gelbin Mekkadrill ist der Hochtüftler der Gnome, der derzeit im Exil in Tüftlerstadt in Eisenschmiede lebt. Bekannt als visionärer Ingenieur, zu dessen Erfindungen der Roboschreiter und Die Tiefenbahn gehören, trägt er nun die schwere Last des Falls von Gnomeregan und beaufsichtigt die Bemühungen, die angestammte Heimat seines Volkes zurückzuerobern.",h="Gelbin Mekkadrill ist der Hochtüftler der Gnome, der derzeit im Exil in Tüftlerstadt in Eisenschmiede lebt.",kw={"die tiefenbahn","gelbin","gnom","gnomeregan","hochtüftler","eisenschmiede","roboschreiter","mekkatorque","thermaplugg","tüftlerstadt"},ang={["profession:Engineering"]="Vor dem Hochtüftler zu stehen, bedeutet, vor dem Schöpfer des Roboschreiters, des gyromatischen Mikrojustierers und der Tiefenbahn zu stehen. Seine Werkstatt in Tüftlerstadt repräsentiert die Spitze der technologischen Innovation.",["race:Gnome"]="Mekkatorque ist das Herz Eures Volkes im Exil. Obwohl die Schuld an der Verseuchung von Gnomeregan auf ihm lastet, gebieten seine Brillanz und seine Hingabe, die angestammte Heimat zu befreien, absolute Loyalität in Tüftlerstadt."},sec={{t="Der Hochtüftler und Meistererfinder",b="Die Führung der Gnome wird durch Intellekt und Verdienste erworben und nicht durch Abstammung. Gelbin Mekkadrills Aufstieg zum Hochtüftler wurde durch reines Erfindungsgenie vorangetrieben. Als Absolvent der Gearshaft University revolutionierte Mekkatorque die persönliche Fortbewegung mit der Erschaffung des ersten funktionierenden Roboschreiters. Über Jahrzehnte der Innovation entwarf er den gyromatischen Mikrojustierer, automatisierte Reparaturroboter und arbeitete mit den Zwergen von Eisenschmiede zusammen, um deren beeindruckende Belagerungsmaschinen zu entwickeln. Als Sturmwind nach dem Zweiten Krieg eine schnelle Verbindung nach Eisenschmiede benötigte, wandte sich König Magni Bronzebart an Mekkatorque, der persönlich die Baupläne zeichnete und den Bau der unterirdischen Tiefenbahn beaufsichtigte."},{t="Verrat und Exil in Eisenschmiede",b="Mekkatorques größte Tragödie ereignete sich, als Troggs tief aus dem Untergrund in Gnomeregan eindrangen. Auf Anraten seines vertrauten Freundes und Chefberaters Sicco Thermaplugg befahl Mekkatorque, radioaktive Abfälle in die unteren Korridore abzulassen, um die Angreifer zu vernichten. Stattdessen tötete das giftige Gas Tausende unschuldiger Gnome und mutierte die Überlebenden, während Thermaplugg die zerstörte Stadt an sich riss. Von Schuldgefühlen erdrückt, aber entschlossen, seinen Fehler wiedergutzumachen, führte Mekkatorque die überlebenden Flüchtlinge durch Dun Morogh nach Eisenschmiede. Von Tüftlerstadt aus, unter der Gastfreundschaft von König Magni, leitet der Hochtüftler die militärischen und wissenschaftlichen Energien des Gnomenvolkes auf ein einziges, unerschütterliches Ziel: die Befreiung von Gnomeregan."}},faq={{q="Wer ist Gelbin Mekkadrill?",a="Gelbin Mekkadrill ist der gewählte Hochtüftler und Anführer der Gnome. Er ist ein Meisteringenieur, der entscheidende Gnomentechnologien entwarf, darunter den Roboschreiter, Reparaturroboter und Die Tiefenbahn.",al={"hochtüftler","gnomenanführer","wer ist der gnomenkönig"}},{q="Warum ist Mekkatorque in Eisenschmiede und nicht in Gnomeregan?",a="Gnomeregan wurde von einer brutalen Trogg-Invasion überrannt, gefolgt von einem katastrophalen radioaktiven Fallout. Mekkatorque führte die Evakuierung seines Volkes durch Dun Morogh nach Eisenschmiede, wo König Magni Bronzebart ihnen in Tüftlerstadt Zuflucht gewährte, während Pläne für die Rückeroberung der Stadt geschmiedet werden.",al={"warum ist mekkatorque in eisenschmiede","warum sind gnome in eisenschmiede","gnomeregan fall"}},{q="Was verursachte die Katastrophe in Gnomeregan?",a="Angesichts endloser Wellen von Troggs wurde Mekkatorque von einem vertrauten Berater dazu überredet, giftiges, radioaktives Kühlmittel in die unteren Kammern abzulassen, um die Bestien aufzuhalten. Tragischerweise konnte das Gas die Troggs nicht aufhalten, sondern verstrahlte stattdessen die Stadt und tötete Tausende von Gnomen.",al={"was passierte mit gnomeregan","warum ist gnomeregan verstrahlt","thermaplugg verrat"}},{q="Was hat Mekkatorque vor seiner Zeit als Hochtüftler erfunden?",a="Mekkatorque erfand den Roboschreiter und gab den Gnomen damit ihr eigenes wendiges Reittier. Er entwarf außerdem den gyromatischen Mikrojustierer, Reparaturroboter, die Baupläne für die Tiefenbahn zwischen Eisenschmiede und Sturmwind und entwickelte die zwergische Belagerungsmaschine mit.",al={"mekkatorque erfindungen","was hat gelbin gebaut"}},{q="Ist Mekkatorque ein wirklicher König?",a="Die Gnome haben keine Erbmonarchie; ihr Anführer ist ein gewählter Hochtüftler, der aufgrund von Verdiensten und intellektuellen Leistungen gewählt wird. Sein Titel und seine Autorität leiten sich aus seiner Wahl zum Hochtüftler ab.",al={"ist mekkatorque ein könig","könig der gnome"}}},fx={db25d752={q="Auf wessen Seite steht Gelbin Mekkadrill?",a="Gelbin Mekkadrill steht fest an der Seite der Allianz. Als Anführer der Gnome pflegt er eine unzerbrechliche Bindung zu König Magni Bronzebeard und den Zwergen von Eisenschmiede, die ihre Tore öffneten, um seinem vertriebenen Volk Zuflucht zu gewähren. Mekkadrill hat die gnomische Technik, seinen Erfindergeist und militärische Ressourcen zugesagt, um ihre Verbündeten der Allianz in ganz Azeroth zu unterstützen.",al={"mekkadrill fraktion","gelbin allianz","wem dient mekkadrill"}},["0e3721be"]={q="Was will Gelbin Mekkadrill?",a="Mekkadrills einziges Ziel ist die Rückeroberung von Gnomeregan. Der Verlust seiner Heimat und der tragische Tod zahlloser Gnome lasten schwer auf ihm und treiben ihn dazu an, einen Weg zu finden, die Troggs und die Strahlung, die ihre Hallen vergiftet, zu beseitigen. Von der Tüftlerstadt aus leitet er Aufklärungsarbeiten und organisiert Einsatzgruppen, um die Grundlage für die Rückeroberung der Stadt zu schaffen.",al={"mekkadrill ziel","was versucht gelbin zu tun","gelbins plan"}},["39ae11c6"]={q="Mit wem ist Gelbin Mekkadrill verbunden?",a="Mekkadrill arbeitet eng mit König Magni Bronzebeard zusammen, seinem großzügigen Gastgeber in Eisenschmiede, und koordiniert sich mit der Führung der Allianz in Sturmwind. Auf persönlicher Ebene verfolgt ihn der Verlust von Gnomeregan und der tausenden Gnome, die starben, nachdem er auf den Rat eines vertrauten Beraters hin die Entlüftung der radioaktiven Stoffe angeordnet hatte.",al={"mekkadrill verbündete","gelbin beziehungen","mit wem arbeitet mekkadrill zusammen"}},["22002310"]={q="Warum ist Gelbin Mekkadrill berühmt?",a="Mekkadrill ist in ganz Azeroth als eines der größten Ingenieursgenies der Geschichte bekannt. Er erfand den ersten funktionierenden Mechanostreiter, entwickelte den gyromatischen Mikrojustierer, half beim Entwurf der Belagerungsmaschine der Zwerge und entwarf die großartigen Pläne für die Tiefenbahn, die Eisenschmiede mit Sturmwind verbindet.",al={"warum ist mekkadrill berühmt","wofür ist gelbin bekannt","mekkadrill erfindungen"}}},fp="18,326,35.716.0,31.706.1,26.203.0,54.282.0,42.264.0,56.249.0,30.191.0"}
P.entries["npc:gelihast"] = {n="Gelihast",s="Gelihast ist ein wilder, zwei Klingen schwingender Murloc-Häuptling, der im Pool of Ask'ar in der Tiefschwarzen Grotte haust. Angelockt von den finsteren Einflüsterungen der Alten Götter, schlachtete er sich seinen Weg in die Ruinen des versunkenen Tempels, bevor er sich den widerwilligen Respekt der Kultisten des Schattenhammers verdiente.",h="Gelihast ist ein wilder, zwei Klingen schwingender Murloc-Häuptling, der im Pool of Ask'ar in der...",kw={"tiefschwarze grotte","blindlight","gelihast","murloc","alte götter","pool of ask'ar","schattenhammer"},ang={["class:Warrior"]="Gelihast greift mit blendender Schwertgeschwindigkeit an; geübte Krieger, die sich wappnen, können seinen frenetischen beidhändigen Angriff vollständig gegen ihn wenden.",["faction:Alliance"]="Für Streitkräfte der Allianz, die das nach Eschental dringende Verderben tilgen wollen, ist die Beseitigung Gelihasts unerlässlich, um die nördlichen Passagen des versunkenen Tempels zu sichern.",["faction:Horde"]="Abenteurer der Horde, die entsandt wurden, um die Tiefschwarze Grotte zu säubern, müssen Gelihast eliminieren, um das unter dem Zoramstrand schwelende Bündnis der Kultisten zu zerschlagen."},sec={{t="Ein tödlicher Ruf",b="Während die meisten Murlocs in der Nähe seichter Küstengewässer bleiben, spürte Gelihast tief unter Eschental das finstere, unheilvolle Ziehen der Alten Götter. Angetrieben von diesen uralten Einflüsterungen drang er gewaltsam in den versunkenen Tempel der Tiefschwarzen Grotte ein. Als Kultisten des Schattenhammers versuchten, ihm den Weg zu versperren, schlachtete er im Alleingang fast ein Dutzend von ihnen mit seinen Zwillingsschwertern ab."},{t="Meister der Blindlight",b="Statt Rache zu suchen, bewunderten die Kultisten Gelihasts rohe Grausamkeit und gewährten ihm die Herrschaft über den Pool of Ask'ar. Dort, umgeben von seiner Blindlight-Brut, errichtete der blutrünstige Murloc einen primitiven Altar. Darauf bringt er düstere Opfer dar und empfängt finstere Gaben direkt von der abscheulichen Präsenz, die im Abgrund schlummert."}},faq={{q="Wer ist Gelihast?",a="Gelihast ist ein bösartiger Murloc-Häuptling, der den Blindlight-Stamm im Pool of Ask'ar in der Tiefschwarzen Grotte befehligt. Er kämpft mit Zwillingsklingen und dient der finsteren Präsenz, die in den Ruinen weilt.",al={"wer ist gelihast","gelihast lore","gelihast hintergrund"}},{q="Warum ist Gelihast in der Tiefschwarzen Grotte?",a="Er wurde von den Einflüsterungen der Alten Götter angelockt. In dem Wunsch, den Ursprung des finsteren Rufs zu erreichen, drang er in die Ruinen ein und bahnte sich einen blutigen Pfad durch die ansässigen Kultisten, um sein eigenes Territorium zu beanspruchen.",al={"warum ist ein murloc in bfd","warum ist gelihast im tempel"}},{q="Wie reagierte der Schattenhammer auf ihn?",a="Obwohl Gelihast beim Betreten des Tempels fast ein Dutzend Kultisten des Schattenhammers niedermetzelte, waren die Überlebenden von seiner Wildheit und Grausamkeit so beeindruckt, dass sie ihm gestatteten zu bleiben und an ihrer Seite anzubeten.",al={"gelihast und schattenhammer","mögen kultisten gelihast"}},{q="Was ist der Altar hinter Gelihast?",a="Gelihast errichtete den Schrein, um der unheilvollen Präsenz in den Ruinen blutige Opfer darzubringen. Reisende, die ihn bezwingen, können den Altar berühren, um den Segen von Blackfathom zu erhalten.",al={"altar der tiefen","gelihast altar","segen von blackfathom altar"}},{q="Welchen Murloc-Stamm führt er an?",a="Er führt die Blindlight-Murlocs an, einen aggressiven Stamm, der den Pool of Ask'ar in den Höhlen heimsucht.",al={"gelihast stamm","welche murlocs sind in bfd"}},{q="Was geschieht mit Gelihast, wenn er unbehelligt bleibt?",a="Er opfert weiterhin Opfer an seinem Altar im Pool of Ask'ar und dient als grausamer Vollstrecker und fanatischer Diener der schattenhaften Schrecken, die die Ruinen befallen.",al={"gelihast schicksal","wer tötet gelihast"}}},fx={f976ed5d={q="Was will Gelihast?",a="Gelihast möchte die Alten Götter ehren und ihnen dienen, deren dunkle Flüstern ihn in den Versunkenen Tempel zogen. Nachdem er durch pures Blutvergießen einen Teil der Ruinen für sich beansprucht hat, wünscht er sich nichts sehnlicher, als an seinem persönlichen Schrein Blutopfer darzubringen und sich in den dunklen Segnungen zu aalen, die von den uralten Schrecken gewährt werden, die tief unter den Wassern lauern.",al={"gelihast ziel","was will gelihast","gelihast beweggründe"}}},fp="8,284,16.355.0,24.334.0,16.204.0,41.193.0,43.217.0,34.177.0,35.104.0,49.163.0"}
P.entries["npc:gelkak-gyromast"] = {n="Gelkak Gyromast",s="Gelkak Gyromast ist ein Gnom, der wie ein Piratenkapitän spricht und an der nebligen Küstenlinie von Nebelrand an der nördlichen Dunkelküste gestrandet ist. Sein Schiff wurde vor der Küste von Dreschadon versenkt, und er möchte seinen mechanischen Ersten Maat, den Threshwackonator 4100, wieder funktionstüchtig machen.",h="Gelkak Gyromast ist ein Gnom, der wie ein Piratenkapitän spricht und an der nebligen Küstenlinie von...",kw={"dunkelküste","gelkak gyromast","gnomerfinder","mathystra","nebelrand","threshwackonator 4100"},ang={["profession:Engineering"]="Gelkaks Notlage ist die klassische Geschichte eines Gnoms fern der Heimat, der seine Hoffnungen auf Rache an ein so eindrucksvolles Gerät wie den Threshwackonator 4100 knüpft.",["race:Gnome"]="Einen Gnomkollegen am Rande von Kalimdor gestrandet zu sehen, führt einem deutlich vor Augen, wie weit weg von zu Hause die Abenteuer einen Gnom tragen können."},sec={{t="Gestrandet am Nebelrand",b="An der einsamen Nordküste von Dunkelküste, direkt westlich der uralten Ruinen von Mathystra, bietet Gelkak Gyromast einen sonderbaren Anblick an den düsteren Ufern der Nachtelfen. Wie ein alter Seebär redend, verlor der selbsternannte Kapitän sein Schiff dicht vor der Küste an die Dreschadon. Als er an den nebligen Strand gespült wurde, zerbrach der Schlüssel zu seinem mechanischen Ersten Maat, dem Threshwackonator 4100, an den Felsen, und seine Teile wurden von den Kriechern, Waldschreitern und Murlocs fortgeschleppt, die das Wrack durchstöberten."},{t="Die Fehlfunktion des Threshwackonators",b="Sobald Abenteurer den Schlüssel geborgen haben, schickt Gyromast sie los, um seinen Ersten Maat einzuschalten und zu ihm zurückzuführen, begierig darauf, ihn auf die Murlocs und Bestien der Küste loszulassen. Der Threshwackonator 4100 folgt gehorsam, nur um in dem Moment eine Fehlfunktion zu erleiden und feindselig zu werden, als er seinen Kapitän erreicht, sodass den Abenteurern nichts anderes übrig bleibt, als ihn zu zerstören."}},faq={{q="Wer ist Gelkak Gyromast?",a="Gelkak Gyromast ist ein exzentrischer Gnom, der wie ein Piratenkapitän spricht und am nördlichen Strand von Dunkelküste namens Nebelrand gestrandet ist, direkt westlich der Ruinen von Mathystra.",al={"gelkak","wer ist gelkak","gyromast"}},{q="Warum ist Gelkak in Dunkelküste gestrandet?",a="Sein Schiff wurde dicht vor der Küste von Dreschadon versenkt, und er wurde mit dem zerbrochenen Schlüssel zu seinem mechanischen Ersten Maat an die einsame Nordküste gespült.",al={"warum ist gelkak hier","gelkak dunkelküste"}},{q="Was ist der Threshwackonator 4100?",a="Der Threshwackonator 4100 ist Gelkaks mechanische Schöpfung und sein selbsternannter Erster Maat. Er möchte ihn wieder funktionstüchtig machen, damit er an den Murlocs und Bestien der Küste Rache nehmen kann.",al={"threshwackonator","gelkak maschine","roboter"}},{q="Welche Hilfe benötigt Gelkak von Reisenden?",a="Gelkak bittet fähige Abenteurer darum, die drei Teile seines zerbrochenen Schlüssels von den Kriechern, Waldschreitern und Murlocs der Küste zu bergen, ihn anschließend zu benutzen, um den Threshwackonator 4100 zu starten, und diesen zu ihm zurückzuführen.",al={"gelkak quests","gyromast quests"}}},fx={["77810e79"]={q="Auf wessen Seite steht Gelkak Gyromast?",a="Gelkak ist ein Gnom, der zur Allianz gehört, obwohl er hier an den einsamen Stränden der Dunkelküste streng auf eigene Faust handelt. Er ist weit abseits jeder größeren Siedlung gestrandet und heißt jeden freundlichen Reisenden der Allianz willkommen, der bereit ist, ihm bei seinen mechanischen Missgeschicken zu helfen.",al={"gelkak gyromast fraktion","gehört gelkak zur allianz","wem dient gelkak"}}},fp="15,271,23.509.0,32.325.1,23.173.0,36.145.0,34.186.0,42.209.0"}
P.entries["npc:general-marcus-jonathan"] = {n="General Marcus Jonathan",s="General Marcus Jonathan ist der Oberkommandant der Verteidigung von Sturmwind und direkt am Tor im Tal der Helden stationiert. Als Veteran des Zweiten Krieges beaufsichtigt er die Garnison, die die Hauptstadt schützt, und verwaltet militärische Anfragen aus den Grenzsiedlungen des Königreichs.",h="General Marcus Jonathan ist der Oberkommandant der Verteidigung von Sturmwind und direkt am Tor im Tal der...",kw={"general jonathan","seenhain","magistrat solomon","marcus jonathan","reginald windsor","armee von sturmwind","verteidigung von sturmwind","das tal der helden"},ang={["class:Warrior"]="Als Oberbefehlshaber der Tore von Sturmwind und Veteran des Zweiten Krieges repräsentiert Jonathan den Gipfel der regulären militärischen Pflicht innerhalb der Infanterieränge des Königreichs.",["faction:Alliance"]="Marcus Jonathan verkörpert den militärischen Stolz Sturmwinds am Tor der Hauptstadt."},sec={{t="Kommandant der Tore",b="Auf seinem Ross im Tal der Helden sitzend, bildet General Marcus Jonathan die erste Verteidigungslinie und ist der ranghöchste Militäroffizier, der die Stadttore überwacht. Er kämpfte im Zweiten Krieg an der Seite berühmter Soldaten wie Reginald Windsor unter dem Kommando von General Turalyon. In dieser Zeit wachsender Spannungen muss Jonathan die unmittelbare Sicherheit der Hauptstadt mit den immer verzweifelteren Hilferufen aus Grenzstädten wie Seenhain in Einklang bringen."},{t="Ein angespanntes Kommando",b="Während Städte wie Seenhain um Soldaten aus Sturmwind bitten, um Blackrock-Orcs und Gnolle abzuwehren, versichert Jonathan den lokalen Magistraten sein Engagement für Hilfe, vertraut jedoch privat an, dass der Hof distanziert geworden ist und die Regentschaft des jungen Königs sich seltsam verhält."}},faq={{q="Wo kann ich General Marcus Jonathan finden?",a="Er ist hoch zu Ross direkt innerhalb der Haupttore von Sturmwind stationiert und überblickt die Eingangsbrücke im Tal der Helden.",al={"standort marcus jonathan","wo ist general jonathan","kommandant des tores von sturmwind"}},{q="Was ist die militärische Geschichte von Marcus Jonathan?",a="Marcus Jonathan ist ein Veteran, der während des Zweiten Krieges unter General Turalyon diente. Er kämpfte an der Seite von Kameraden wie Reginald Windsor, bevor er schließlich zum Oberkommandanten der Verteidigung von Sturmwind aufstieg.",al={"vergangenheit von marcus jonathan","hintergrundgeschichte marcus jonathan","hat marcus im zweiten krieg gekämpft"}}},fx={d649e9ed={q="Wer ist General Marcus Jonathan?",a="General Marcus Jonathan ist der Oberkommandierende der Verteidigung von Sturmwind. Als erfahrener Veteran, der während des Zweiten Krieges unter General Turalyon diente, beaufsichtigt er nun die Streitkräfte, die die Hauptstadt und die umliegenden Gebiete schützen.",al={"wer ist marcus jonathan","identität von marcus jonathan","wer ist general jonathan"}},["59fdae30"]={q="Auf wessen Seite steht General Marcus Jonathan?",a="Er ist dem Königreich Sturmwind und der Großen Allianz voll und ganz ergeben. Er nimmt seine Pflicht, das Reich zu verteidigen und seine Bürger zu schützen, mit absolutem Ernst und ist der Krone sowie der hohen Führung von Sturmwind direkt unterstellt.",al={"loyalität von marcus jonathan","wem dient marcus jonathan","fraktion von marcus jonathan"}},["5549e5c1"]={q="Was will General Marcus Jonathan?",a="Jonathan möchte Sturmwind schützen und sicherstellen, dass die abgelegenen Siedlungen wie Seenhain die militärische Unterstützung erhalten, die sie dringend benötigen. Da jedoch König Varian Wrynn vermisst wird und sich der königliche Hof seltsam verhält, ist seine Fähigkeit, Truppen nach Belieben zu mobilisieren, stark eingeschränkt.",al={"ziel von marcus jonathan","was braucht marcus jonathan","beweggründe von marcus jonathan"}},b8230eb1={q="Warum ist General Marcus Jonathan für das Rotkammgebirge relevant?",a="Magistrat Solomon von Seenhain richtet Bitten um militärische Hilfe direkt an General Jonathan, da er weiß, dass dessen Wort in Sturmwind ein erhebliches Gewicht hat. Als Befehlshaber der Armee ist Jonathan der Beamte, der die Befugnis hat, die Krone um Verstärkung zur Verteidigung des Rotkammgebirges zu bitten.",al={"warum ist marcus jonathan im rotkammgebirge relevant","marcus jonathan seenhain","warum nachricht an marcus jonathan senden"}},ab66a8e6={q="Mit wem ist General Marcus Jonathan verbunden?",a="Er verbindet eine lange Geschichte mit Marschall Reginald Windsor, da er während des Zweiten Krieges unter General Turalyon an seiner Seite gekämpft hat. In Sturmwind koordiniert er sich regelmäßig mit der Krone und antwortet auf dringende Appelle von regionalen Anführern wie Magistrat Solomon.",al={"verbindungen von marcus jonathan","wer kennt marcus jonathan","verbündete von marcus jonathan"}}},fp="23,272,22.465.0,18.256.1,41.132.0,43.215.0"}
P.entries["npc:gerard-tiller"] = {n="Gerard Tiller",s="Gerard Tiller ist ein durstiger menschlicher Landarbeiter, der vor der Scheune auf den Weinbergen der Maclures im Wald von Elwynn arbeitet. Während er die Weinberge unter der warmen Sonne pflegt, ist er stets begierig darauf, jedem Reisenden, der einen Schlauch erfrischendes Quellwasser erübrigen kann, einen knackigen, glänzenden roten Apfel einzutauschen.",h="Gerard Tiller ist ein durstiger menschlicher Landarbeiter, der vor der Scheune auf den Weinbergen der...",kw={"wald von elwynn","gerard tiller","etwas zu trinken für gerard","weinberge der maclures","erfrischendes quellwasser","glänzender roter apfel"},ang={["profession:Cooking"]="Gerards Bereitschaft, frische Äpfel gegen einfaches Quellwasser einzutauschen, macht ihn zu einer praktischen Obstquelle für wandernde Köche, die nach einfachen Zutaten suchen."},sec={{t="Ein durstiger Landarbeiter",b="Gerard Tiller verbringt seine Tage damit, auf den Feldern zu schuften und das Gelände vor der Scheune auf den Weinbergen der Maclures zu bestellen. Südlich von Goldhain gelegen, bringt der Weinberg einige der bekanntesten Trauben von Elwynn hervor, doch die Aufrechterhaltung der Ernte ist harte Arbeit. Tiller ist von seinen Pflichten ständig ausgedörrt, weshalb er gern mit vorbeikommenden Abenteurern tauscht. Wenn ihm jemand einen frischen Schlauch kühles Quellwasser anbietet, erwidert er diesen Gefallen mit Freuden durch frische, glänzende rote Äpfel, die direkt von den hiesigen Obstgärten geerntet wurden."}},faq={{q="Wer ist Gerard Tiller?",a="Gerard Tiller ist ein menschlicher Landarbeiter, der vor der Scheune auf den Weinbergen der Maclures im südlichen Wald von Elwynn steht.",al={"gerard tiller identität","wer ist gerard","tiller elwynn"}},{q="Wo kann ich Gerard Tiller finden?",a="Er steht direkt vor der großen Holzscheune auf den Weinbergen der Maclures, südlich von Goldhain und östlich vom Hof der Steinfelds.",al={"gerard tiller aufenthaltsort","wo ist gerard","gerard elwynn finden"}},{q="Was tauscht Gerard Tiller?",a="Gerard tauscht einen Glänzenden roten Apfel gegen einen Schlauch Erfrischendes Quellwasser für jeden Reisenden ein, der seinen Durst löscht.",al={"gerard apfeltour tausch","gerard tiller wasser","was will gerard"}},{q="Mischt sich Gerard in die Fehde zwischen den Maclures und Steinfelds ein?",a="Nein. Obwohl er auf den Weinbergen der Maclures arbeitet, konzentriert sich Gerard lieber auf seine Pflichten und darauf, seinen Durst zu stillen, anstatt sich in die Familienrivalität zwischen den Maclures und Steinfelds einzumischen.",al={"gerard tiller fehde","maclure fehde gerard"}}},fx={["467277ed"]={q="Was will Gerard Tiller?",a="Die Arbeit unter der heißen Sonne in den Weinbergen der Maclures ist durstig machend, und Gerard will kaum mehr als einen einfachen Schlauch mit Erfrischendem Quellwasser, um seinen Durst zu stillen. Wenn Ihr ihm ein Getränk bringt, tauscht er gerne einen knackigen, Glänzenden roten Apfel aus dem Obstgarten dagegen ein.",al={"was braucht gerard tiller","handel mit gerard tiller","was will gerard"}},["9aadf23d"]={q="Warum ist Gerard Tiller hier?",a="Gerard Tiller verdient seinen Lebensunterhalt als Arbeiter, der das Gelände vor der Scheune in den Weinbergen der Maclures pflegt. Während die umliegenden Lande von Elwynn von Unruhen bedroht sind, konzentriert sich Gerard weiterhin auf die tägliche Farmarbeit und die Pflege der Ernte.",al={"warum ist gerard tiller in den weinbergen","grund für gerard tillers aufenthaltsort","was macht gerard tiller"}},["9f9d4e60"]={q="Mit wem ist Gerard Tiller verbunden?",a="Gerard ist mit der Familie Maclure verbunden und arbeitet auf ihren Weinbergen südlich von Sturmwind. Obwohl er direkt auf ihrem Land neben ihren Scheunen arbeitet, kümmert er sich um seine eigenen Angelegenheiten und meidet die erbitterte Fehde, die zwischen den Maclures und ihren benachbarten Rivalen, den Steinfelds, tobt.",al={"verbindungen von gerard tiller","für wen arbeitet gerard tiller","verbündete von gerard tiller"}}},fp="13,272,18.515.0,21.112.0,31.131.0,30.118.0,60.175.0"}
P.entries["npc:gerrig-bonegrip"] = {n="Gerrig Knochengriff",s="Gerrig Knochengriff ist ein unscheinbarer Zwergenladner, der in den schattigen Gängen von Eisenschmiedes Forlorn Cavern untergebracht ist. Hinter dem Tresen von Bonegrip's Runes and Dooms kauft und verkauft er im Stillen esoterische Texte über dunkle Rituale und vergessene uralte Mächte.",h="Gerrig Knochengriff ist ein unscheinbarer Zwergenladner, der in den schattigen Gängen von Eisenschmiedes...",kw={"tiefschwarze grotte","knochengriff","forlorn cavern","gerrig","eisenschmiede","manuskript von lorgalis","runes and dooms"},ang={["class:Warlock"]="Für Hexenmeister, die die schattigen Ecken der Forlorn Cavern aufsuchen, bietet Knochengriffs Sammlung esoterischer Rituale und dunkler Folianten eine willkommene Quelle gefährlichen Wissens.",["race:Dwarf"]="Für zwergische Besucher wirft Knochengriffs Handel mit verbotenem Wissen einen beunruhigenden Schatten auf das Gelehrtenleben Eisenschmiedes."},sec={{t="Bonegrip's Runes and Dooms",b="Gerrig Knochengriff, der in den schmuddeligen Winkeln der Forlorn Cavern tätig ist, erscheint den meisten Bürgern lediglich als exzentrischer Verkäufer bizarren Relikten und verbotenen Wissens. Sein bescheidener Laden erfüllt jedoch einen weitaus dunkleren Zweck. Knochengriff ist ein aktives Mitglied des nihilistischen Schattenhammerkults und nutzt seine Ladenfront, um gefährliche Manuskripte und obskure Texte über die Alten Götter direkt vor den Augen des Senats von Eisenschmiede und des High Seat zu sammeln."},{t="Sammeln verbotenen Wissens",b="Gerrig wirbt aktiv ahnungslose Abenteurer der Allianz an, um uralte Artefakte wie das Manuskript von Lorgalis zu bergen, das tief in der Tiefschwarzen Grotte verloren ging. Sobald diese Relikte in seinen Händen sind, transkribiert und verbreitet er das profane Wissen direkt an seine Kultbrüder in ganz Azeroth. Über subtile Verbindungen zu zwielichtigen Verbündeten wie Skuerto und Gestalten, die mit uralten, ursprünglichen Wesenheiten wie Myzrael zu tun haben, arbeitet Knochengriff unermüdlich daran, die apokalyptischen Pläne des Kults voranzutreiben."}},faq={{q="Wer ist Gerrig Knochengriff?",a="Gerrig Knochengriff ist ein Zwerg, der Bonegrip's Runes and Dooms in Eisenschmiedes Forlorn Cavern betreibt. Er handelt mit exzentrischen Kuriositäten und obskuren Texten über uralte Rituale.",al={"wer ist knochengriff","gerrig knochengriff lore","knochengriff eisenschmiede"}},{q="Was macht er mit dem Manuskript von Lorgalis?",a="Er sucht das Manuskript von Lorgalis aus der Tiefschwarzen Grotte für seine Sammlung seltener Texte. Weitere Nachforschungen können mehr über seine Verwendung dessen enthüllen.",al={"warum will knochengriff das manuskript von lorgalis","knowledge in the deeps abgabe","verwendung des manuskripts von lorgalis"}},{q="Wie geht Gerrig in Eisenschmiede vor?",a="Gerrig hält sich als exzentrischer Gelehrter und Händler in der Forlorn Cavern bedeckt, wo er obskure Texte kauft und verkauft.",al={"weiß eisenschmiede dass knochengriff ein kultist ist","warum wird knochengriff in eisenschmiede geduldet"}},{q="Was ist seine Verbindung zu Myzrael?",a="Gerrig ist ein alter Gefährte des Zwergs Skuerto, der das versiegelte Erdelementar Myzrael im Arathihochland untersucht. Durch diese Verbindungen hilft Gerrig dabei, Aufgaben zu koordinieren, die an uralte Binde-Rituale und ursprüngliche Mächte geknüpft sind.",al={"gerrig knochengriff und myzrael","skuerto und gerrig"}}},fx={["177aea82"]={q="Auf wessen Seite steht Gerrig Knochengriff?",a="Gerrig dient heimlich dem Schattenhammer-Kult, der sich den Alten Göttern und apokalyptischen Ritualen verschrieben hat. Obwohl er im Herzen von Eisenschmiede unter dem Deckmantel eines exzentrischen Händlers agiert, der Bonegrip's Runes and Dooms betreibt, gilt seine wahre Loyalität seinen Kultbrüdern und -schwestern.",al={"gerrig knochengriff fraktion","für wen arbeitet gerrig","ist gerrig knochengriff böse"}},["6941d2cb"]={q="Warum ist Gerrig Knochengriff in Eisenschmiede?",a="Gerrig operiert aus der schattenhaften Forlorn Cavern, um direkt unter der Nase des Bergkönigs dunkles Wissen, Artefakte und okkulte Manuskripte zu sammeln. Das Betreiben eines Ladens für Kuriositäten und Reagenzien bietet ihm die perfekte Tarnung, um verbotenes Wissen zu kaufen, zu kopieren und an seine Kultgefährten im ganzen Reich zu verbreiten.",al={"warum ist gerrig in eisenschmiede","was macht gerrig knochengriff hier","warum ist gerrig knochengriff in der forlorn cavern"}}},fp="15,264,26.449.1,30.487.1,23.172.2,45.149.1,37.129.2,34.238.0"}
P.entries["npc:gershala-nightwhisper"] = {n="Gershala Nachtraunen",s="Gershala Nachtraunen ist ein Forscher der Nachtelfen, der in der Küstensiedlung Auberdine an der Dunkelküste lebt. Angetrieben von tiefer Sorge über den Weg der Hochelfen von Quel'Thalas untersucht er Proben verfluchter aquatischer und dämonischer Kreaturen, um zu verstehen, wie magische Verderbnis Geist und Körper verzerrt.",h="Gershala Nachtraunen ist ein Forscher der Nachtelfen, der in der Küstensiedlung Auberdine an der Dunkelküste...",kw={"auberdine","blackfathom","verderbnis","dunkelküste","gershala","naga","nightwhisper","satyr"},ang={["faction:Alliance"]="Gershala dient als wichtiger Förderer, der Allianzexpeditionen in die Gefahren der Tiefschwarzen Grotte entsendet und dafür sorgt, dass ihre Vorstöße wertvolles arkanes Wissen einbringen.",["race:NightElf"]="Für Nachtelfen sind Gershalas düstere Nachforschungen eine ergreifende Mahnung an die uralte Zerschlagung und den schrecklichen Preis magischer Sucht, die einst ihre eigenen Brüder und Schwestern in Schrecken verwandelte."},sec={{t="Studium der Verwandlung",b="Friedlich in Auberdine stationiert, blickt Gershala Nachtraunen über die unmittelbaren Sorgen an der Küste der Dunkelküste hinaus auf eine größere, schleichende Gefahr. Bestürzt darüber, wie die verbliebenen Hochelfen gefährliche arkane Praktiken annehmen und sich Blutelfen nennen, versucht Gershala den biologischen und spirituellen Niedergang zu begreifen, der ungezügelter Magie folgt. Um diese Geheimnisse zu lüften, schickt er erfahrene Abenteurer der Allianz in die überfluteten Hallen der Tiefschwarzen Grotte, um verdorbene Hirnstämme von den dort hausenden Naga und Satyren zu erbeuten."},{t="Ein Gegenmittel zum Untergang",b="Gershalas düstere Konzentration auf die Hirnstämme von Naga und Satyren rührt von ihrer gemeinsamen Abstammung her: Beide Völker waren einst Nachtelfen, bevor sie Königin Azshara und dämonischen Pakten erlagen. Indem er die physischen Spuren seziert, die Jahrtausende dämonischer und abyssischer Energien auf ihren Nervensystemen hinterlassen haben, hofft er, Warnzeichen oder Schutzmaßnahmen aufzudecken, die andere elfische Verwandte vor einem ähnlichen Abstieg in monströse Missbildungen bewahren könnten."}},faq={{q="Wo ist Gershala Nachtraunen zu finden?",a="Gershala Nachtraunen befindet sich in Auberdine, der wichtigsten Hafenstadt der Allianz an der Küste der Dunkelküste.",al={"gershala standort","wo ist gershala","gershala nachtraunen finden"}},{q="Warum möchte Gershala Hirnstämme von Naga und Satyren?",a="Gershala untersucht verdorbene Hirnstämme, um zu erforschen, wie tiefgreifende magische und dämonische Verwandlung die Anatomie ehemaliger Nachtelfen verändert. Sowohl Naga als auch Satyrn waren einst Elfen, und er versucht, die physischen Mechanismen hinter ihrer Verderbnis zu verstehen.",al={"warum hirnstämme","erforschung der verderbnis lore","was erforscht gershala"}},{q="Was hofft Gershala mit seinen Nachforschungen zu erreichen?",a="Gershala hofft, dass seine Forschungen entscheidende Erkenntnisse liefern, um zu verhindern, dass die Blutelfen durch ihre gefährliche Abhängigkeit von Teufelsmagie und ungezügelter arkaner Macht dem Bösen und monströsen Missbildungen anheimfallen.",al={"gershala ziel","warum blutelfen helfen","gershala forschungszweck"}},{q="Wo befinden sich die Proben, die Gershala benötigt?",a="Er schickt Abenteurer in die Tiefschwarze Grotte, eine uralte, überflutete Tempelruine an der Küste von Eschental, die von Naga und Satyren heimgesucht wird.",al={"wo sind die hirnstämme","blackfathom-tiefe hirnstämme","gershala gegenstände finden"}}},fx={["087b63f5"]={q="Auf wessen Seite steht Gershala Nachtraunen?",a="Gershala ist mit den Nachtelfen von Darnassus verbündet und dient Mitgliedern der Allianz als freundlicher Gelehrter. Seine Forschungen finden in Auberdine statt, wo er daran arbeitet, Kalimdor und die sterblichen Völker im Allgemeinen vor den schleichenden Bedrohungen durch dämonische und magische Verderbnis zu schützen.",al={"gershala fraktion","ist gershala allianz","gershala zugehörigkeit"}},aee12c2d={q="Warum ist Gershala Nachtraunen hier?",a="Gershala hat sein Zuhause in Auberdine, da die Dunkelküste direkt an Orte grenzt, die tief von uraltem Übel befallen sind, wie zum Beispiel die Tiefschwarze Grotte. Von diesem Zufluchtsort an der Küste aus kann er Reisende und Abenteurer rekrutieren, die sich nach Süden wagen, um verderbte Exemplare für seine laufenden Forschungen zu sammeln.",al={"warum ist gershala in auberdine","gershala zweck dunkelküste"}},["19945428"]={q="Wer ist Gershala Nachtraunen?",a="Gershala Nachtraunen ist ein Nachtelfengelehrter, der in der Küstensiedlung Auberdine in der Dunkelküste lebt. Angetrieben von wissenschaftlicher Neugier und Sorge um die weitere Welt widmet er sich dem Verständnis magischer und biologischer Verderbnis. Er studiert die veränderte Anatomie von Kreaturen, die durch dunkle Mächte verzerrt wurden, in der Hoffnung, dass sorgfältige Studien ähnliche Untergänge bei anderen Völkern verhindern können.",al={"wer ist gershala","gershala nachtraunen hintergrundwissen","gershala hintergrund"}}},fp="21,311,23.550.0,19.411.0,37.111.0,50.251.0,56.201.0,47.138.0"}
P.entries["npc:ghamoo-ra-classic"] = {n="Ghamoo-ra",s="Ghamoo-ra ist eine uralte, riesige Meeresschildkröte, die im Pool of Ask'ar in der Tiefschwarzen Grotte lebt. Einst ein friedlicher Bewohner von Elunes versunkenem Tempel, wurde er vom Kult des Schattenhammer gefangen genommen, gefoltert und in den Wahnsinn getrieben, um als bösartiger Wächter zu dienen.",h="Ghamoo-ra ist eine uralte, riesige Meeresschildkröte, die im Pool of Ask'ar in der Tiefschwarzen Grotte lebt.",kw={"tiefschwarze grotte","elune","ghamoo-ra","pool of ask'ar","zähmen","schildkröte","schattenhammer"},ang={["class:Druid"]="Druiden betrachten Ghamoo-ras Qualen und erzwungene Aggression als eine tragische Verderbnis der natürlichen Tierwelt durch die Diener der Alten Götter.",["class:Hunter"]="Jäger, die sich in die Tiefschwarze Grotte wagen, mögen Mitleid mit Ghamoo-ra haben, einem edlen, uralten Tier, das durch dunkle Gefangenschaft gebrochen wurde, doch ein geduldiger Jäger könnte ihn vielleicht noch zähmen.",["race:NightElf"]="Für Nachtelfen ist Ghamoo-ras Schicksal eine bittere Erinnerung an die Entweihung von Elunes heiligem Tempel durch den abscheulichen Schattenhammer."},sec={{t="Ein gepeinigtes sanftes Tier",b="Vor der Entweihung der Tiefschwarzen Grotte war Ghamoo-ra einer der letzten friedlichen, natürlichen Bewohner, die zwischen den überfluteten Ruinen des den Nachtelfen heiligen Tempels von Elune lebten. Als der nihilistische Kult des Schattenhammer die Kontrolle über das Heiligtum übernahm, rissen sie die uralte Schildkröte aus ihrem stillen Leben und sperrten sie ein. Anstatt ihn zu töten, wurde er über Jahre hinweg systematisch gepeinigt und litt unter der geistigen und körperlichen Folter durch die Kultisten."},{t="Wächter der Tiefe",b="Gebrochen durch die anhaltende Grausamkeit, erlag die große Schildkröte schließlich dem Wahnsinn. Die Kultisten gaben der zerstörten Kreatur den Namen Ghamoo-ra und bildeten ihn zu einem grausamen Verteidigungstier aus. Heute patrouilliert Ghamoo-ra auf einer kleinen Insel im Pool of Ask'ar, umgeben von kleineren Schildkröten, und greift blindlings jeden Eindringling an, der die Höhlen betritt, womit er dem Kult dient, der seinen Verstand zerrüttet hat."}},faq={{q="Wer ist Ghamoo-ra?",a="Ghamoo-ra ist eine riesige Schildkröte, die im Pool of Ask'ar innerhalb der Tiefschwarzen Grotte zu finden ist. Ursprünglich ein friedlicher Bewohner des Tempels von Elune, wurde er vom Kult des Schattenhammer gefangen genommen, gefoltert und zu einem grausamen Wachtier gebrochen.",al={"ghamoo-ra hintergrundgeschichte","riesenschildkröte bfd","wer ist ghamoo ra"}},{q="Warum ist Ghamoo-ra Fremden gegenüber feindselig?",a="Der Kult des Schattenhammer sperrte die Schildkröte ein und folterte sie über mehrere Jahre hinweg, was seinen Geist brach und ihn in den totalen Wahnsinn trieb. Sie konditionierten ihn darauf, auf jeden Fremden loszugehen, der sich den inneren Schreinen nähert.",al={"warum ist die schildkröte wütend","warum greift die schildkröte an","ghamoo-ra wahnsinn"}},{q="Kann ein Jäger Ghamoo-ra zähmen?",a="Ja. Trotz seiner Größe und jahrelanger Qualen kann Ghamoo-ra von einem geschickten Jäger gezähmt werden.",al={"zähmen ghamoo-ra","kann jäger bfd schildkröte zähmen"}},{q="Was ist der Pool of Ask'ar?",a="Der Pool of Ask'ar ist eine überflutete unterirdische Höhle in der Tiefschwarzen Grotte. Ghamoo-ra durchstreift dort die Mitte einer kleinen Insel, die von zahmen, einheimischen Schildkröten umgeben ist.",al={"pool of ask'ar","wo ist ghamoo ra"}},{q="Welche Verbindung hat er zu den Alten Göttern?",a="Obwohl er nicht von Natur aus eine Kreatur der Leere ist, wurde Ghamoo-ras Verstand von Kultisten des Schattenhammer, die die Alten Götter verehren, verzerrt. Sie verwandelten die uralte Kreatur in einen unwissenden Beschützer ihrer dunklen Ritualstätten.",al={"ghamoo-ra alte götter","ist die schildkröte verderbt"}}},fx={["9fc00ca4"]={q="Auf wessen Seite steht Ghamoo-ra?",a="Ghamoo-ra dient den Kultisten des Schattenhammers, die die Tiefschwarze Grotte besetzt halten, wenn auch nicht freiwillig. Einst ein friedlicher Bewohner des Tempels, wurde er über Jahre hinweg durch unerbittliche Grausamkeit gebrochen und konditioniert, um das Heiligtum der Alten Götter zu bewachen und jeden Eindringling zu beseitigen, der sich in die Nähe wagt.",al={"ghamoo-ra fraktion","wem dient ghamoo-ra","ist ghamoo-ra schattenhammer"}},b771cdb8={q="Was will Ghamoo-ra?",a="Ghamoo-ra hat keine eigenen großen Ambitionen. Völlig wahnsinnig geworden durch die dunklen Rituale und die Qualen, die ihm der Schattenhammer zugefügt hat, ist die riesige Schildkröte von Schmerz und Verwirrung erfüllt und schlägt blindlings um sich, um Eindringlinge zu zerschmettern und die Höhle zu verteidigen, in der er gefangen gehalten wird.",al={"ghamoo-ra ziel","was will die schildkröte","ghamoo-ra motiv"}},a7b82d70={q="Warum ist Ghamoo-ra hier?",a="Ghamoo-ra bewohnte ursprünglich den versunkenen Tempel, als dieser noch ein friedliches Heiligtum für die Mondgöttin Elune war. Als der Schattenhammer in die Tiefschwarze Grotte einzog, fingen sie ihn ein und ketteten ihn im Pool of Ask'ar an, um ihn als monströse, lebende Waffe zu benutzen, die ihren Pfad bewacht.",al={"warum ist ghamoo-ra in der tiefschwarzen grotte","ghamoo-ra pool of ask'ar warum","warum ist hier eine riesige schildkröte"}}},fp="9,251,24.464.0,21.379.0,17.233.0,38.222.0,28.87.0,27.161.0,45.220.0"}
P.entries["npc:gilnid"] = {n="Gilnid",s="Gilnid, bekannt als der Schmelzer, ist der meisterhafte Ingenieur der Goblins, der die Schmieden in den Tiefen der Todesminen betreibt. Er beaufsichtigt das Schmelzen von Roherz zu veredeltem Metall und Munition für Edwin van Cleefs verborgenes gepanzertes Schlachtschiff. Ohne seine feurigen Operationen würde der Bruderschaft der Defias die schwere Artillerie fehlen, die für einen Angriff auf Sturmwind erforderlich ist.",h="Gilnid, bekannt als der Schmelzer, ist der meisterhafte Ingenieur der Goblins, der die Schmieden in den...",kw={"kanonen","die todesminen","defias","schmiede","giesserei","gilnid","goblin","schlachtschiff","schmelzer","vancleef"},ang={["faction:Alliance"]="Das Ausschalten von Gilnid legt die Waffenfertigung der Defias lahm und verhindert, dass VanCleefs Kriegsschiff vollständig bewaffnet werden kann, bevor es den Hafen von Sturmwind bedrohen kann.",["profession:Engineering"]="Gilnids Gießerei ist ein Paradebeispiel für die Schwerindustrie der Goblins, in der unter extremen Bedingungen standardisierte Schiffskanonen, Munition und Strukturpanzerungen hergestellt werden.",["profession:Mining"]="Die gewaltigen Hochöfen und Schmelztiegel in Gilnids Werkstatt zeigen, wie die Bruderschaft der Defias die unberührten Bodenschätze von Westfall in raffiniertes Eisen und Rüstungsgüter verwandelt."},sec={{t="Meister der Gießerei",b="Tief in den Todesminen verlässt sich die Bruderschaft der Defias auf industrielles Fachwissen, um Kriegswaffen zu schmieden. Gilnid dient als VanCleefs oberster Schmelzer und befehligt eine kleine Armee aus Goblin-Arbeitern, Tüftlern und Schmieden in der zentralen Gießerei. Er überragt die meisten seiner Artgenossen und treibt seine Mannschaft unerbittlich durch Rauch und Schlacke, bellt Befehle und verweigert Pausen, um sicherzustellen, dass Roheisenerz zu schweren Panzerplatten und tödlicher Munition verarbeitet wird."},{t="Bewaffnung des Schlachtschiffs",b="Die Schmelzhütte ist von entscheidender Bedeutung für die ehrgeizigen Pläne der Bruderschaft. Gilnid ist direkt für das Schmieden der schweren Kanonen und der Munition verantwortlich, die für das gewaltige eiserne Kriegsschiff bestimmt sind, das in der unterirdischen Bucht jenseits seiner Werkstatt vor Anker liegt. Bis seine Gießerei jedes Geschütz, jedes Rohr und jede Kugel produziert hat, bleibt das Schiff der Defias unvollendet für seinen geplanten Angriff auf Sturmwind."}},faq={{q="Wer ist Gilnid?",a="Gilnid ist ein Goblin-Ingenieur und der oberste Schmelzer von Edwin van Cleef in den Todesminen. Er beaufsichtigt die Schmieden der Bruderschaft und leitet die industriellen Bemühungen, Kanonen und Munition für ihre Kriegsmaschinerie zu gießen.",al={"gilnid todesminen","wer ist gilnid","der schmelzer"}},{q="Warum befindet sich Gilnid in den Todesminen?",a="Die Bruderschaft der Defias heuerte Goblin-Söldneringenieure an, um ihr verborgenes Kriegsschiff zu bauen und auszurüsten. Gilnid wurde mit der Leitung der Schmelzhütte betraut, wo abgebautes Eisenerz in veredelte Teile, Panzerungen und Artillerie verwandelt wird.",al={"warum ist ein goblin in den todesminen","gilnid defias lore","was macht gilnid"}},{q="Woran arbeitet Gilnid?",a="Gilnid ist für die Herstellung der massiven Kanonen, Schiffsteile und Kugeln verantwortlich, die zur Bewaffnung des Kriegsschiffs benötigt werden, das in den Docks tiefer im Inneren der Minen versteckt ist.",al={"gilnid kanone","was baut gilnid","todesminen schmiede zweck"}},{q="Warum muss Gilnid besiegt werden?",a="Gilnid kontrolliert die industrielle Gießerei, die den Weg zur Bucht versperrt. Die schweren Panzertüren, die tiefer zum Schiff der Defias führen, bleiben versiegelt, bis der Schmelzraum gesichert ist.",al={"warum gilnid toeten","tuer nach gilnid"}},{q="Arbeitet Gilnid direkt für Edwin van Cleef?",a="Ja. Er ist kein Mitglied der ursprünglichen Steinmetzgilde, sondern ein angeheuerter Goblin-Spezialist, der direkt unter VanCleef dient, um die schwere Metallurgie und Waffenproduktion zu leiten.",al={"vancleef und gilnid","ist gilnid anfuehrer der defias"}},{q="Warum sind so viele Goblins um ihn herum?",a="Gilnid leitet eine spezialisierte Goblin-Ingenieurmannschaft in der Gießerei. Sie betreiben die Hochöfen, gießen flüssiges Eisen und montieren Artillerie unter seiner strengen, unerbittlichen Aufsicht.",al={"gilnid goblins","todesminen schmiedemannschaft"}}},fx={["1c6d7566"]={q="Auf wessen Seite steht Gilnid?",a="Gilnid steht fest auf der Seite der Bruderschaft der Defias. Während Goblins normalerweise für ihre unabhängigen Söldnerverträge und ihre Neutralität bekannt sind, hat Gilnid seine beachtlichen metallurgischen Talente der rebellischen Sache von Edwin van Cleef gewidmet und dient als leitender Aufseher tief im unterirdischen Stützpunkt der Bruderschaft.",al={"gilnid fraktion","gilnid bruderschaft der defias","für wen kämpft gilnid"}},["88f08ccf"]={q="Was will Gilnid?",a="Gilnid möchte nichts lieber, als das Juggernaut der Defias vollständig ausgerüstet und einsatzbereit zu sehen. Als leitender Schmelzer ist sein oberstes Ziel sicherzustellen, dass jede Kanone, jedes Gehäuse und jede Ladung schwerer Munition perfekt geschmiedet wird, und er treibt seine Goblin-Arbeiter unbarmherzig ohne Pause an, bis das gewaltige Kriegsschiff bereit zum Auslaufen ist.",al={"gilnid ziel","was versucht gilnid zu tun","gilnid motivation"}}},fp="6,339,21.433.0,21.374.1,14.208.0,31.218.0,26.155.0,28.179.0,45.177.0,41.182.0"}
P.entries["npc:gilshalan-windwalker"] = {n="Gilshalan Windspäher",s="Gilshalan Windspäher ist ein Nachtelfenforscher, der am Fuße des großen Baumes Aldrassil in Laubschattental weilt. Besorgt über das plötzliche Verderben, das in Teldrassil Wurzeln schlägt, studiert er die einheimische Tierwelt, um die unnatürliche Aggression zu verstehen, welche die Äste heimsucht. Seine Nachforschungen über die Waldweberspinnen liefern frühe Hinweise auf die Fäulnis, die den Weltenbaum befällt.",h="Gilshalan Windspäher ist ein Nachtelfenforscher, der am Fuße des großen Baumes Aldrassil in Laubschattental...",kw={"aldrassil","gilshalan","laubschattental","spinne","tenaron","gift","waldweber","windwalker"},ang={["class:Druid"]="Seine Forschung unterstützt direkt die Versuche des Zirkels des Cenarius, das ökologische Ungleichgewicht zu ergründen, das in den Ästen von Laubschattental schwelt.",["race:NightElf"]="Gilshalan verkörpert die frühen Bemühungen Eures Volkes, zu begreifen, warum der neu gewachsene Weltenbaum bereits von Fäulnis geplagte, gewalttätige Bestien hervorbringt."},sec={{t="Ein Gelehrter an den Wurzeln",b="Ruhig auf den Steinstufen sitzend, die nach Aldrassil hinaufführen, blickt Gilshalan Windspäher mit wachsendem Unbehagen auf das friedliche Blätterdach von Laubschattental. Teldrassil wurde gepflanzt, um den Nachtelfen ihre verlorene Zuflucht und die Harmonie mit der Natur zurückzugeben, doch traten fast augenblicklich Anzeichen eines tiefen spirituellen Unbehagens zutage. Gilshalan widmet sich der Erforschung dessen, wie sich dieses Verderben in den örtlichen Bestien manifestiert, beginnend bei den giftigen Spinnentieren, die in der Nähe ihre Netze weben."},{t="Die Waldweberbedrohung",b="Gilshalans Hauptaugenmerk liegt auf den Waldweberspinnen, die im Norden in der Schattenweberhöhle lauern. Diese Kreaturen, einst ein ausgewogener Teil des Waldökosystems, sind unnatürlich feindselig und verdorben geworden. Indem er junge Novizen aussendet, um Giftbeutel und unversehrte Spinneneier zu sammeln, arbeitet Gilshalan daran, die veränderte Wirksamkeit des Gifts zu analysieren und festzustellen, ob das Verderben über Generationen weitergegeben wird oder sich von außen über den Boden von Teldrassil ausbreitet."},{t="Nachricht an den Erzdruiden",b="Mit dem Gift und einem Ei in den Händen glaubt Gilshalan, dass das Gift der Spinnen Eigenschaften aufweisen wird, die mit dem jüngsten Wachstum des neuen Weltenbaums verknüpft sind. Er veranlasst, dass die Exemplare nach Darnassus geschickt werden, wo er seine Studien fortsetzen wird. Zudem lässt er vielversprechenden Beschützern ausrichten, dass Tenaron Sturmgewalt im obersten Gemach von Aldrassil, wo die Führung der Druiden über den jungen Weltenbaum wacht, nach ihnen verlangt hat."}},faq={{q="Wer ist Gilshalan Windspäher?",a="Gilshalan Windspäher ist ein Nachtelfengelehrter, der am Fuße von Aldrassil in Laubschattental sitzt. Er untersucht das mysteriöse Verderben, das sich in die Tierwelt von Teldrassil einschleicht.",al={"gilshalan","wer ist gilshalan","windwalker nachtelf"}},{q="Warum möchte Gilshalan Waldwebergift?",a="Gilshalan versucht, die chemischen und spirituellen Eigenschaften des Gifts zu erforschen, um zu verstehen, warum die Spinnen des Waldes so aggressiv und mutiert geworden sind.",al={"warum waldwebergift","waldwebergift quest","spinnengift gilshalan"}},{q="Was macht er mit dem Waldweberei?",a="Er möchte lebende Exemplare studieren, doch eine ausgewachsene Riesenspinne einzufangen ist zu gefährlich. Ein ungebrütetes Ei lässt sich weitaus leichter transportieren, daher lässt er es zusammen mit dem Gift nach Darnassus senden, wo die Schlüpflinge eingesperrt und studiert werden können.",al={"waldweberei quest","warum spinneneier","waldweberei"}},{q="Wohin schickt Gilshalan Abenteurer als Nächstes?",a="Nachdem das Ei abgeliefert wurde, teilt er Abenteurern mit, dass Tenaron Sturmgewalt nach ihnen verlangt hat, und schickt sie hinauf in die oberste Kammer auf der Spitze von Aldrassil.",al={"tenaron ruft","wen aufsuchen nach gilshalan","nach waldweberei"}},{q="Wo befindet sich Gilshalan Windspäher?",a="Er sitzt auf dem Steinpfad am nördlichen Fuß von Aldrassil, direkt vor dem hohlen Eingang des zentralen Baumes in Laubschattental.",al={"gilshalan standort","wo ist windwalker","gilshalan finden"}},{q="Warum ist die Tierwelt in Teldrassil aggressiv?",a="Eine unbekannte Fäulnis hat begonnen, durch die Wurzeln und den Boden von Teldrassil zu sickern, was den Geist und das Wesen seiner Kreaturen verdirbt und Gelehrte wie Gilshalan beunruhigt.",al={"warum sind spinnen wütend","teldrassil verderbnis","verdorbene bestien laubschattental"}}},fx={["4b23360a"]={q="Auf wessen Seite steht Gilshalan Windspäher?",a="Gilshalan steht fest an der Seite seiner Mitstreiter, der Nachtelfen und der Allianz. Er ist an den Wurzeln von Aldrassil innerhalb des Laubschattentals stationiert und hilft jungen Abenteurern dabei, die seltsamen, verderbenden Kräfte zu verstehen und zu bekämpfen, die die lokale Tierwelt von Teldrassil befallen.",al={"gilshalan fraktion","wem dient gilshalan","gilshalan windspäher allianz"}},["61ec761c"]={q="Warum ist Gilshalan Windspäher hier?",a="Er sitzt an der Basis von Aldrassil, um die aufkommende Verderbnis im Laubschattental zu überwachen. Durch die Untersuchung von Giftproben und ungeöffneten Eiern der aufgewühlten Webwaldspinnen versucht Gilshalan herauszufinden, was die natürliche Harmonie des großen Weltenbaums vergiftet.",al={"warum ist gilshalan im laubschattental","gilshalan windspäher aldrassil zweck"}},ba2e5485={q="An wen ist Gilshalan Windspäher gebunden?",a="Gilshalan berichtet an Tenaron Sturmgewalt, einen der älteren Druiden, die hoch oben in den Ästen von Aldrassil stationiert sind. Sobald seine ersten Untersuchungen zu den Webwaldspinnen abgeschlossen sind, verweist er vielversprechende Rekruten an Tenaron, um weiterhin bei der Verteidigung von Teldrassil zu helfen.",al={"an wen berichtet gilshalan","gilshalan tenaron","gilshalan verbindungen"}}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:gilthares-firebough"] = {n="Feuerzweig",s="Feuerzweig ist ein elfischer Deckhelfer, der in einem Turm innerhalb der Feste Northwatch gefangen gehalten wird. Er stand früher in Diensten der Thalo'dan Privateers und arbeitete auf einem Mondscheintransport zwischen Ratschet und Beutebucht. Er sucht nach jeder Gelegenheit, seinen Entführern aus Theramore zu entkommen.",h="Feuerzweig ist ein elfischer Deckhelfer, der in einem Turm innerhalb der Feste Northwatch gefangen gehalten...",kw={"beutebucht","free from the hold","feuerzweig","die feste northwatch","ratschet","thalo'dan privateers"},ang={["faction:Alliance"]="Während er Passanten gegenüber anfangs gleichgültig ist, hegt Feuerzweig intensive Feindseligkeit gegenüber den Matrosen der Allianz, die sein Schiff zerstörten und ihn in eine Zelle sperrten.",["faction:Horde"]="Feuerzweig aus Northwatch zu eskortieren, versetzt der Aggression von Theramore entlang der Küste vom Brachland einen leichten Schlag."},sec={{t="Ein Schmuggler hinter Gittern",b="Während er illegale Fracht zwischen Ratschet und Beutebucht transportierte, musste Feuerzweig mit ansehen, wie sein Schiff von Seestreitkräften aus Theramore in Stücke geschossen wurde. Als einziger Überlebender des Angriffs wurde der Freibeuter in Ketten an Land geschleift und in einem Turm innerhalb der Feste Northwatch eingesperrt. Obwohl er in leuchtendes Rot gekleidet ist und wenig Zuneigung für die Eiferer der Allianz hegt, die seine Mannschaft niedergemetzelt haben, ist Feuerzweig nicht wählerisch, wer ihm bei seinem Ausbruch hilft – solange sie sich nur den Weg von den Wehrgängen freikämpfen können."}},faq={{q="Wer ist Feuerzweig?",a="Feuerzweig ist ein elfischer Deckhelfer, der mit den Thalo'dan Privateers in Verbindung steht. Er wurde gefangen genommen, als die Streitkräfte von Northwatch sein Handelsschiff vor der Küste vom Brachland abfingen und versenkten.",al={"wer ist feuerzweig","feuerzweig hintergrundgeschichte","wer ist dieser elf"}},{q="Warum ist er in der Feste Northwatch inhaftiert?",a="Feuerzweig diente auf einem Transporter, der Mondschein zwischen Ratschet und Beutebucht beförderte. Soldaten aus Theramore versenkten das Schiff, töteten den Rest der Besatzung und inhaftierten Feuerzweig als Schmuggelware und Kriegsgefangenen in der Feste Northwatch.",al={"warum sitzt er im gefängnis","warum in einem käfig","gefangener in northwatch"}},{q="Ist Feuerzweig ein Hochelf oder ein Blutelf?",a="Feuerzweig ist ein Elf aus Quel'Thalas, der als unabhängiger Seemann arbeitet, anstatt der Allianz oder den Herrschern von Silbermond zu dienen. Obwohl seine rote Kleidung oft mit den Sin'dorei assoziiert wird, dient er Freibeutern und keiner nationalen Fraktion.",al={"was für ein elf ist feuerzweig","hochelf oder blutelf","volk von feuerzweig"}},{q="Wer sind die Thalo'dan Privateers?",a="Die Thalo'dan Privateers sind eine unabhängige maritime Organisation, die in Schmuggeloperationen über das große Meer verwickelt ist, einschließlich der lukrativen Mondscheinroute, die Ratschet und Beutebucht verbindet.",al={"thalodan privateers","für wen arbeitet er","feuerzweigs mannschaft"}}},fx={["4d14e07a"]={q="Auf wessen Seite steht Gilthares Feuerzweig?",a="Gilthares steht weder auf der Seite der Horde noch auf der der Allianz. Er ist ein unabhängiger Seemann, der den Freibeutern von Thalo'dan angehört, einer Gruppe von Freibeutern, die auf den Handelsrouten zwischen Ratschet und Beutebucht operiert. Obwohl er keine besondere Liebe für die Horde hegt, haben ihn seine gewaltsame Gefangennahme und harte Versklavung durch Theramore-Eiferer offen feindselig gegenüber den Allianzstreitkräften gemacht, die die Feste Northwatch besetzt halten.",al={"gilthares feuerzweig fraktion","ist gilthares horde oder allianz","gilthares zugehörigkeit"}},["84aa2a4b"]={q="Was will Gilthares Feuerzweig?",a="Gilthares will nichts weiter, als aus seinem Käfig in der Feste Northwatch auszubrechen und den Eiferern zu entkommen, die ihn gefangen genommen haben. Nachdem er die gewaltsame Zerstörung seines Schnapstransports überlebt hat und nun in einem Küstenturm eingesperrt ist, ist er verzweifelt auf der Suche nach jemandem, der in der Lage ist, ihm einen Weg durch die Garnison freizukämpfen, damit er ihrer Gefangenschaft entfliehen kann.",al={"gilthares feuerzweig ziel","was will gilthares","gilthares feuerzweig zielsetzung"}}},fp="19,254,22.498.0,27.182.0,40.239.0,39.256.0,33.187.0"}
P.entries["npc:glorin-steelbrow"] = {n="Glorin Stahlbraue",s="Glorin Stahlbraue ist ein zwergischer Agent, den man beim Trinken in der Tiefenwassertaverne im Hafen von Menethil antrifft. Als Vertrauter von Bischof Heller aus Sturmwinds Kathedrale des Lichts hilft er Abenteurern, Die Dritte Flotte zu untersuchen und heilige Relikte sowie Materialien zu bergen, die an der Küste des Sumpflands verstreut liegen. Seine Bemühungen verbinden die heimgesuchte Wildnis des Dämmerwalds direkt mit den versunkenen Schiffswracks des Nordens.",h="Glorin Stahlbraue ist ein zwergischer Agent, den man beim Trinken in der Tiefenwassertaverne im Hafen von...",kw={"bischof heller","tiefenwassertaverne","die verlorene flotte","dämmerwald","auge von paleth","glorin stahlbraue","lichtgeschmiedetes eisen","der hafen von menethil","sumpfland"},ang={["class:Paladin"]="Paladine, die Hellers Befehlen folgen, werden Glorin als unverzichtbar erachten, um lichtgeschmiedetes Eisen zu bergen – ein heiliges Metall, das für das Schmieden von durch das Heilige Licht gesegneten Waffen unerlässlich ist.",["faction:Alliance"]="Glorin spielt eine Schlüsselrolle bei der Bergung wichtiger militärischer Allianzrelikte und geweihter Materialien, die bei den maritimen Katastrophen im Sumpfland verloren gingen.",["race:Dwarf"]="Glorin verkörpert zwergische Tatkraft und Solidarität, indem er vom maritimen Knotenpunkt im Hafen von Menethil aus Verbündete in ganz Khaz Modan und den südlichen Menschenkönigreichen unterstützt."},sec={{t="Eine Verbindung im Hafen",b="Während Bischof Heller den Menschen im Dämmerwald von Sturmwinds Kathedrale des Lichts aus gegen die schleichenden Schrecken beisteht, unterhält er weit im Norden im Hafen von Menethil Verbindungen. In der geschäftigen Tiefenwassertaverne stationiert, fungiert Glorin Stahlbraue als Hellers Augen und Ohren an der Küste. Er bietet Reisenden, die auf der Suche nach heiligen Metallen und vergessenen Relikten nach Norden geschickt werden, Hilfe und Führung und schlägt so eine entscheidende Brücke zwischen den Nöten des südlichen Waldes und den versunkenen Trümmern des Sumpflands."},{t="Die verlorene Flotte und verlorene Relikte",b="Steelbrow ist mit der Tragödie der Dritten Flotte bestens vertraut, deren Schiffe an der Küste des Sumpflands zerschmettert und in die Tiefe gerissen wurden. Er leitet Abenteurer an, die heimgesuchten Wracks nach verlorenen Barren aus lichtgeschmiedetem Eisen und dem mächtigen, verfluchten Artefakt abzusuchen, das als das Auge von Paleth bekannt ist. Glorin weiß, dass die Bergung solch heiliger Rüstgüter unerlässlich ist, um Waffen zu schmieden, die den finsteren Mächten Einhalt gebieten können, welche die Allianz bedrohen."}},faq={{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwerg, der in der Tiefenwassertaverne im Hafen von Menethil stationiert ist. Er arbeitet mit Bischof Heller aus Sturmwind zusammen und unterstützt Abenteurer, die nach Norden reisen, um versunkene Fracht und Relikte vor der Küste des Sumpflands zu bergen.",al={"wer ist glorin","glorin stahlbraue lore","was macht glorin"}},{q="Wo finde ich Glorin Stahlbraue?",a="Glorin befindet sich im Erdgeschoss der Tiefenwassertaverne im Hafen von Menethil an der Westküste des Sumpflands.",al={"glorin aufenthaltsort","wo ist glorin stahlbraue","glorin deepwater taverne"}},{q="Warum hat ein Zwerg im Hafen von Menethil mit dem Dämmerwald zu tun?",a="Bischof Heller aus Sturmwinds Kathedrale des Lichts sucht nach mächtigen heiligen Relikten und geweihten Metallen, um die Dunkelheit zu bekämpfen, die den Dämmerwald bedroht. Er entsendet vertrauenswürdige Abgesandte zu Glorin Stahlbraue, der die Küste des Sumpflands kennt und Bergungstrupps zu den versunkenen Überresten der Dritten Flotte leiten kann.",al={"warum dämmerwald quest im sumpfland","verbindung zu farthing","warum ins sumpfland geschickt"}},{q="Was ist die Dritte Flotte, von der Glorin spricht?",a="Die Dritte Flotte war eine Marineexpedition der Allianz, die vor der Küste des Sumpflands in eine Katastrophe geriet. Ihre zerschellten Rümpfe liegen nun auf dem Meeresgrund, heimgesucht von ertrunkenen Seeleuten, und verbergen wertvolle Fracht wie lichtgeschmiedetes Eisen und uralte Artefakte.",al={"was ist die verlorene flotte","dritte flotte sumpfland","die verlorene flotte quest"}},{q="Was ist das Auge von Paleth?",a="Das Auge von Paleth ist ein uraltes religiöses Relikt, das an Bord der versunkenen Flotte transportiert wurde. Sobald es mit Glorins Führung vom Meeresgrund geborgen wurde, muss es von der Priesterschaft gereinigt werden, da das Schiffswrack von finsterer Verderbnis umgeben ist.",al={"auge von paleth","paleth relikt","was ist das auge von paleth"}},{q="Wofür wird lichtgeschmiedetes Eisen verwendet?",a="Lichtgeschmiedetes Eisen ist ein seltenes, geweihtes Metall, aus dem gesegnete Waffen geschmiedet werden, die mächtige Untote und dämonische Streitkräfte niederstrecken können. Glorin hilft dabei, verlorene Barren aus den Schiffswracks zu bergen, um die Verteidiger des Dämmerwalds zu unterstützen.",al={"lichtgeschmiedetes eisen","verlorene barren","gesegnete waffe"}}},fx={["65727266"]={q="Auf wessen Seite steht Glorin Stahlbraue?",a="Glorin steht fest auf der Seite der Allianz und der Kirche des Heiligen Lichts. Er ist im Hafen von Menethil stationiert und arbeitet in Abstimmung mit Anführern wie Bischof Heller von Sturmwind, um von vertrauenswürdigen Abenteurern der Allianz Unterstützung bei der Bergung verlorener, geweihter Relikte und Materialien zu erhalten, die entlang der tückischen Küsten verloren gingen.",al={"glorin stahlbraue fraktion","wem dient glorin stahlbraue","glorin stahlbraue allianz"}},cbae8fd4={q="Was will Glorin Stahlbraue?",a="Glorin möchte verlorene heilige Fracht bergen, die vom Meer beansprucht wurde, insbesondere Lieferungen, die von der versunkenen Dritten Flotte transportiert wurden. Seine Bemühungen konzentrieren sich darauf, Abenteurer anzuheuern, um seltene Lightforge Iron-Barren und heilige Relikte wie The Eye of Paleth zu bergen, um sicherzustellen, dass sie gereinigt und der Kirche zurückgegeben werden.",al={"was braucht glorin stahlbraue","glorin stahlbraue ziel","wonach sucht glorin stahlbraue"}},["72c86ba2"]={q="An wen ist Glorin Stahlbraue gebunden?",a="Glorin ist ein Mitarbeiter von Bischof Heller aus der Kathedrale des Lichts in Sturmwind. Er koordiniert sich direkt mit der Geistlichkeit von Sturmwind, um verlorene heilige Relikte zu sichern, und fungiert als deren Verbindungsperson im Hafen des Sumpflands, um Lieferungen zu bergen, die für die Bemühungen der Kirche bestimmt oder von diesen verloren gegangen sind.",al={"glorin stahlbraue verbindungen","wen kennt glorin stahlbraue","glorin stahlbraue bischof farthing"}}},fp="16,405,19.496.0,32.444.1,24.239.0,34.128.0,57.294.0,48.240.0,26.243.0,33.221.0"}
P.entries["npc:gnoarn"] = {n="Gnoarn",s="Gnoarn ist ein im Exil lebender Gnom, der sich in Tüftlerstadt in der Zwergen-Bergstadt Eisenschmiede aufhält. Nach dem verheerenden Fall von Gnomeregan vertrieben, unterstützt er sein verstreutes Volk, indem er Abenteurer aussendet, um befreundeten gnomischen Ingenieuren und Überlebenden zu helfen.",h="Gnoarn ist ein im Exil lebender Gnom, der sich in Tüftlerstadt in der Zwergen-Bergstadt Eisenschmiede aufhält.",kw={"bingles","gnoarn","gnomfro","gnomeregan","eisenschmiede","shoni die schtille","tüftlerstadt"},ang={["faction:Alliance"]="Helden der Allianz, die durch Eisenschmiede reisen, können mit Gnoarn sprechen, um Hinweise auf wichtige gnomische Ingenieurbestrebungen in Dun Morogh, Loch Modan und Sturmwind zu erhalten.",["race:Gnome"]="Für andere Gnome verkörpert Gnoarn die Widerstandskraft der Flüchtlingsgemeinschaft in Tüftlerstadt und sorgt dafür, dass vertriebene Ingenieure in den Östlichen Königreichen miteinander in Verbindung bleiben."},sec={{t="Ein vertriebener Bürger von Gnomeregan",b="Wie der Großteil seiner Brüder war Gnoarn gezwungen, aus den Tiefen von Gnomeregan zu fliehen, als Troggs einfielen und katastrophale Strahlung die große unterirdische Metropole unbewohnbar machte. In Tüftlerstadt in Eisenschmiede fand er unter der Gastfreundschaft der Bronzebeard-Zwerge Zuflucht und verbringt nun seine Tage damit, den Überblick über andere Überlebende zu behalten. Er fungiert als informeller Koordinator unter den Flüchtlingen und weist fähige Reisende auf Gnome in der Ferne hin, die dringend Hilfe benötigen, wie etwa den gestrandeten Piloten Bingles Blastenheimer in Loch Modan oder die ehrgeizige Ingenieurin Shoni die Schtille in Sturmwind."}},faq={{q="Wer ist Gnoarn?",a="Gnoarn ist ein gnomischer Überlebender, der unter der Flüchtlingsbevölkerung in Tüftlerstadt lebt, dem Gnomviertel von Eisenschmiede. Er schickt Reisende aus, um befreundeten verbannten Gnomen zu helfen, die in den Gebieten der Allianz an verschiedenen Projekten arbeiten.",al={"wer ist dieser gnom","gnoarn lore","gnoarn nsc"}},{q="Wo ist Gnoarn zu finden?",a="Er ist in Tüftlerstadt im nordöstlichen Teil von Eisenschmiede zu finden, umgeben von surrenden Maschinen, Zahnrädern und Werkbänken seiner im Exil lebenden Verwandten.",al={"gnoarn aufenthaltsort","wo ist gnoarn","gnoarn finden"}},{q="Welche Aufgaben vergibt Gnoarn?",a="Gnoarn weist Abenteurer an, anderen verstreuten Gnomen beizustehen. Insbesondere schickt er Abenteurer nach Loch Modan, um nach dem vermissten Piloten Bingles Blastenheimer zu sehen, und entsendet Reisende nach Sturmwind, um mit der Erfinderin Shoni die Schtille über ihre Gyrobohrmatische Exkavation zu sprechen.",al={"gnoarn quests","was will gnoarn"}},{q="Was ist mit Gnoarns Haaren geschehen?",a="Vor dem Fall von Gnomeregan war Gnoarn dafür bekannt, eine exzentrische „Gnomfro“-Frisur zu tragen. Tragischerweise verlor er seine markante Haarpracht nach dem katastrophalen Niederschlag und der Entlüftung radioaktiver Gase, die seine Heimatstadt verwüsteten.",al={"gnoarn gnomfro","gnoarn haare"}}},fx={["38923b37"]={q="Auf wessen Seite steht Gnoarn?",a="Gnoarn ist seinen Mitgnomen aus Gnomeregan und der Großen Allianz treu ergeben. Er lebt unter der vertriebenen Gnombevölkerung in der Tüftlerstadt und arbeitet daran, seine Gemeinschaft organisiert und in Verbindung mit ihren Verbündeten in Eisenschmiede zu halten.",al={"gnoarn fraktion","ist gnoarn allianz","wem dient gnoarn"}},ce7102b3={q="Warum ist Gnoarn in Eisenschmiede?",a="Wie Tausende anderer Gnome wurde Gnoarn nach dem Fall von Gnomeregan aus seiner Heimat vertrieben. Als Troggs das unterirdische technologische Wunderwerk überrannten und giftige Strahlung die Gänge verseuchte, flohen die Überlebenden nach oben, um Zuflucht bei ihren Zwergenvettern in Eisenschmiede zu suchen, wo sie sich in der Tüftlerstadt ein neues Zuhause schufen.",al={"warum ist gnoarn hier","warum kam gnoarn nach eisenschmiede","was brachte gnoarn nach eisenschmiede"}},["82a3a1ba"]={q="Was will Gnoarn?",a="Gnoarn sorgt sich um die Sicherheit und den Verbleib seiner vertriebenen Verwandten. In der Unordnung nach der Evakuierung von Gnomeregan sucht er nach vermissten Kameraden wie Bingles und leitet fähige Abenteurer an, bedeutenden Erfindern und Spezialisten wie Shoni die Schtille zu helfen.",al={"was versucht gnoarn zu tun","gnoarn ziele","was braucht gnoarn"}},efead32c={q="An wen ist Gnoarn gebunden?",a="Gnoarn unterhält enge Beziehungen zu anderen Überlebenden aus Gnomeregan in Eisenschmiede, insbesondere durch seine Verbindung zu der bekannten Erfinderin Shoni die Schtille und seine Koordinierungsbemühungen, um geflüchtete Kameraden wie Bingles Blastenheimer ausfindig zu machen.",al={"gnoarn verbündete","wen kennt gnoarn","gnoarn verbindungen"}}},fp="6,259,33.597.0,14.214.0,26.161.0,32.286.0,31.230.0"}
P.entries["npc:godrick-farsan"] = {n="Godrick Farsan",s="Godrick Farsan ist ein untoter Hexenmeisterassistent in Unterstadt, der an der Seite von Carendin Halgar im Magieviertel dient. Obwohl er vollkommen blind ist, sagt er, dass er auf andere Weise sehe.",h="Godrick Farsan ist ein untoter Hexenmeisterassistent in Unterstadt, der an der Seite von Carendin Halgar im...",kw={"carendin halgar","godrick farsan","hearts of the pure","strahad farsan","succubus","unterstadt","hexenmeister"},ang={["class:Warlock"]="Hexenmeister der Verlassenen, die die Kunst erlernen wollen, einen Succubus zu beschwören, müssen Godrick konsultieren, um die notwendigen Lockmittel vorzubereiten und die verschlingende Natur dämonischer Diener zu verstehen.",["race:Undead"]="Godrick verkörpert die Philosophie der Hexenmeister der Verlassenen, indem er den körperlichen Verfall und die Blindheit annimmt, während er eine dunkle magische Wahrnehmung schärft, um sterbliche Schwächen zu ersetzen."},sec={{t="Augen im Dunkeln",b="Inmitten der Beschwörungskreise des Magieviertels unterstützt Godrick Farsan Meister Carendin Halgar dabei, angehende Hexenmeister der Verlassenen anzuleiten. Obwohl ihm das physische Augenlicht fehlt, sagt Godrick, dass er dennoch auf andere Weise sehen könne, ohne die Mittel dazu zu erklären. Er prüft Praktizierende, die mächtigere dämonische Wesenheiten binden wollen, und schickt sie los, um Reine Herzen und Essenzen zu sammeln, die für komplizierte Beschwörungsrituale benötigt werden."}},faq={{q="Wer ist Godrick Farsan?",a="Godrick Farsan ist ein Hexenmeister der Verlassenen, der im Magieviertel von Unterstadt stationiert ist. Er dient als Assistent von Meister Carendin Halgar und hilft bei der Ausbildung und den Ritualen angehender Hexenmeister.",al={"godrick farsan","wer ist godrick"}},{q="Wie kann Godrick sehen, wenn er blind ist?",a="Godrick sagt, dass er trotz seiner Blindheit auf andere Weise sehe. Die genauen Mittel werden nicht erklärt.",al={"ist godrick blind","wie sieht godrick"}},{q="Ist Godrick mit Strahad Farsan verwandt?",a="Sie teilen denselben Nachnamen, aber eine familiäre Verbindung ist nicht bestätigt.",al={"beziehung zu strahad farsan","strahad farsan bruder","sind godrick und strahad verwandt"}},{q="Welche Rolle spielt er bei der Ausbildung von Hexenmeistern?",a="Godrick hilft bei der Beaufsichtigung der Bindungsriten für Hexenmeister und leitet sie insbesondere durch Aufgaben wie die Beschaffung Reiner Herzen an, um einen Succubus anzulocken und zu binden.",al={"godrick hexenmeisterquests","quest hearts of the pure"}}},fx={["5d2f41c4"]={q="Auf wessen Seite steht Godrick Farsan?",a="Godrick ist den Verlassenen und der Dunklen Fürstin treu ergeben und lebt tief in der Unterstadt. Er dient an der Seite von Carendin Halgar, unterstützt Praktizierende der dunklen Künste und leitet Hexenmeister der Horde an, die dämonische Mächte meistern wollen.",al={"godrick farsan zugehörigkeit","wem dient godrick","godrick farsan fraktion"}},f8f4201c={q="Warum ist Godrick Farsan hier?",a="Ihr findet Godrick in den schattigen Quartieren der Unterstadt, wo er als ergebener Assistent von Carendin Halgar fungiert. Er bleibt hier stationiert, um Prüfungen für angehende Hexenmeister zu beaufsichtigen und ihnen dabei zu helfen, mächtige dämonische Wesen wie die Sukkubus zu binden.",al={"warum ist godrick in der unterstadt","godrick farsan zweck unterstadt","was macht godrick farsan hier"}},["57b226ed"]={q="Was will Godrick Farsan?",a="Godrick möchte die dunklen Studien der Hexenmeister der Unterstadt voranbringen. Durch zermürbende Prüfungen, die rituelle Komponenten wie die Hearts of the Pure und der Unschuldigen beinhalten, testet er Eure Entschlossenheit und Eure Fähigkeit, gefährliche Dämonen des Wirbelnden Nether zu befehligen.",al={"godrick farsan ziel","was will godrick","godrick farsan motive"}}},fp="14,198,16.410.0,22.199.0,35.104.0,37.60.0,43.152.0"}
P.entries["npc:golnir-bouldertoe"] = {n="Golnir Geröllzeh",s="Golnir Geröllzeh ist ein zwergischer Bergbauhändler, der neben der geschäftigen Großen Schmiede in Eisenschmiede stationiert ist. Er stellt grundlegende Vorräte für Bergleute und Prospektoren bereit und kümmert sich um Depeschen für örtliche Kuriere und Reisende.",h="Golnir Geröllzeh ist ein zwergischer Bergbauhändler, der neben der geschäftigen Großen Schmiede in...",kw={"bouldertoe","kohle","flussmittel","golnir","die große schmiede","eisenschmiede","bergbauzulieferer"},ang={["profession:Mining"]="Bergleute, die die Große Schmiede besuchen, verlassen sich auf Golnir, wenn es um wichtige Werkzeuge für ihr Handwerk geht, einschließlich Ersatzhacken und Flussmitteln, die zum Schmelzen von Roherz zu veredelten Barren benötigt werden.",["race:Dwarf"]="Für Zwerge, die von ihren ersten Reisen aus Coldridge oder Kharanos zurückkehren, dient Golnir als früher Kontaktpunkt in der Hauptstadt und heißt Reisende direkt neben dem feurigen Herzen des Berges willkommen."},sec={{t="Händler der Großen Schmiede",b="Inmitten der dröhnenden Hitze der Großen Schmiede von Eisenschmiede rüstet Golnir Geröllzeh Prospektoren und Handwerker mit dem Notwendigen für ihr Gewerbe aus. Von robusten Bergbauhacken bis hin zu Flussmitteln und Kohle befeuern seine Waren die unermüdlichen Schmelzöfen und Schmieden, die die zwergische Hauptstadt prägen. Als Verwandter von Geofram Bouldertoe ist Golnir ein zuverlässiger Ansprechpartner für Arbeiter, die in der Stadt ankommen; oft weist er neue Arbeitskräfte ein oder nimmt Versorgungsdepeschen entgegen, die von nahegelegenen Außenposten herbeigeschafft werden."}},faq={{q="Wo finde ich Golnir Geröllzeh?",a="Golnir Geröllzeh befindet sich in der Großen Schmiede in Eisenschmiede und steht dort zusammen mit anderen Handelsleuten in der Nähe der zentralen Schmelz- und Schmiedebereiche.",al={"golnir standort","wo ist golnir","golnir geröllzeh eisenschmiede"}},{q="Welche Waren verkauft Golnir?",a="Er fungiert als Bergbauzulieferer und verkauft wichtige Handelsausrüstung wie Bergbauhacken, Kohle und Flussmittel, um Prospektoren beim Graben und Veredeln von Roherz zu unterstützen.",al={"golnir händlerwaren","was verkauft golnir","golnir inventar"}},{q="Ist Golnir Geröllzeh an Quests beteiligt?",a="Ja. Kurierquests, die umliegende zwergische Siedlungen mit der Hauptstadt verbinden, wie zum Beispiel Botengänge, die Gryth Thurden und eintreffende Flüge von Außenposten wie Thelsamar betreffen, weisen Reisende an, Nachrichten direkt Golnir zu überbringen.",al={"golnir quests","flug nach eisenschmiede golnir"}},{q="Ist Golnir mit jemand anderem in Dun Morogh verwandt?",a="Golnir teilt seinen Clannamen mit Geofram Bouldertoe, dem Bergbaulehrer, der neben ihm in der Großen Schmiede von Eisenschmiede arbeitet.",al={"bouldertoe familie","geofram bouldertoe verwandter"}}},fx={["5f6dd933"]={q="Wer ist Golnir Geröllzeh?",a="Golnir Geröllzeh ist ein Zwergenhändler, der als Bergbauausstatter innerhalb der Großen Schmiede von Eisenschmiede arbeitet. Er versorgt die Prospektoren und Schmiede, die am geschmolzenen Herzen der Stadt arbeiten, mit wichtigen Vorräten, Spitzhacken und Schmelzbedarf.",al={"wer ist golnir","golnir geröllzeh hintergrundgeschichte","golnir identität"}},b602f757={q="Auf wessen Seite steht Golnir Geröllzeh?",a="Golnir ist ein loyaler Untertan von Eisenschmiede und des Clans Bronzebart und steht fest an der Seite der Großen Allianz. Er betreibt seinen Handel im geschäftigen Zentrum des Königreichs und dient sowohl seinen Zwergenbrüdern als auch reisenden Besuchern der Allianz.",al={"golnir fraktion","golnir loyalität","golnir seite"}},["7131f874"]={q="Warum ist Golnir Geröllzeh hier?",a="Golnir bleibt in der Nähe der Großen Schmiede, wo die Hitze nie erlischt und ständig Erz geschmolzen wird. Da Bergleute und Schmiede aus ganz Dun Morogh und darüber hinaus ihre Funde direkt zur zentralen Esse von Eisenschmiede bringen, hält Golnir seinen Laden in der Nähe, um sie mit der notwendigen Ausrüstung zu versorgen.",al={"warum ist golnir in eisenschmiede","golnir rolle große schmiede","warum ist golnir hier"}}},fp="17,218,27.473.0,35.154.0,28.154.0,44.236.0,47.125.0"}
P.entries["npc:gorbold-steelhand"] = {n="Gorbold Stahlhand",s="Gorbold Stahlhand ist ein Zwergenhändler, der in Auberdine an der nebligen Küste der Dunkelküste stationiert ist. Weit entfernt von den verschneiten Hallen von Khaz Modan versorgt er Reisende, Handwerker und einheimische Nachtelfen mit allgemeinen Waren und Handwerkswaren.",h="Gorbold Stahlhand ist ein Zwergenhändler, der in Auberdine an der nebligen Küste der Dunkelküste stationiert...",kw={"auberdine","dunkelküste","deep ocean vast sea","gorbold","eisenschmiede","händler","steelhand","warenhändler"},ang={["faction:Alliance"]="Gorbold veranschaulicht die praktische Zusammenarbeit zwischen den östlichen Völkern der Allianz und den Nachtelfen und sorgt dafür, dass der Handel über das große Meer hinweg floriert.",["race:Dwarf"]="Ein vertrautes Gesicht aus Eisenschmiede wie Gorbold in der nebligen, nächtlichen Umgebung der Dunkelküste zu erblicken, bietet reisenden Zwergen eine willkommene Erinnerung an die Heimat."},sec={{t="Ein Zwergenhändler in Kalimdor",b="Während der Großteil der nördlichen Weiten Kalimdors von den zurückgezogen lebenden Nachtelfen bewohnt wird, sind Außenposten der Allianz wie Auberdine auf Händler von jenseits des großen Meeres angewiesen, um den Handel aufrechtzuerhalten. Gorbold Stahlhand repräsentiert die weitreichende Präsenz des Handels aus Eisenschmiede in dieser Region. Seite an Seite mit den Kaldorei verkauft er Handwerkswaren, Reagenzien, Herstellungsbedarf und Werkzeuge an Abenteurer, die sich auf Erkundungen der tückischen Küsten und Wälder der Dunkelküste vorbereiten."},{t="Maritime Unternehmungen",b="Neben dem Verkauf alltäglicher Waren behält Gorbold auch die gefährlichen Küstengewässer vor Auberdine aufmerksam im Auge. Die von Riffen durchzogenen Gewässer der Dunkelküste sind berüchtigt dafür, Schiffe der Allianz zu verschlingen, und Händler wie Gorbold haben ein direktes Interesse an den unter den Wellen verlorenen Frachten. Reisende, die bereit sind, in die Tiefen des Ozeans hinabzutauchen, stoßen bei ihm oft auf Interesse an Bergungsgut und verschollenen Logbüchern aus versunkenen Wracks."}},faq={{q="Wer ist Gorbold Stahlhand?",a="Gorbold Stahlhand ist ein Zwerg und Händler für allgemeinen Handwerksbedarf, der im Küstenhafen Auberdine an der Dunkelküste ansässig ist.",al={"gorbold","wer ist gorbold stahlhand","zwerg in auberdine"}},{q="Was verkauft Gorbold Stahlhand?",a="Er führt allgemeinen Handwerksbedarf, Handwerkszutaten, Sammelwerkzeuge sowie Reagenzien wie Phiolen und Fäden, die von durch Auberdine reisenden Handwerkern benötigt werden.",al={"was verkauft gorbold","gorbold handwerkswaren","gorbold händlerliste"}},{q="Warum lebt ein Zwerg aus Eisenschmiede an der Dunkelküste?",a="Auberdine dient als zentraler Umschlagplatz der Allianz, der Kalimdor mit den Östlichen Königreichen verbindet. Zwerge reisen häufig hierher, um Handel zu treiben, Erkundungen durchzuführen und verbündete Operationen der Nachtelfen zu unterstützen.",al={"warum ist hier ein zwerg","warum ist gorbold an der dunkelküste","eisenschmiede in auberdine"}},{q="Bietet Gorbold Quests an?",a="Ja, in der Quest 'Tiefer Ozean, weites Meer' schickt er Abenteurer zu versunkenen Schiffswracks vor der Küste der Dunkelküste, um verlorene Schiffsladung zu bergen.",al={"gorbold quest","deep ocean vast sea questgeber"}}},fx={["59afaf53"]={q="Auf wessen Seite steht Gorbold Stahlhand?",a="Gorbold Stahlhand ist fest mit der Allianz verbündet. Als Zwerg aus Eisenschmiede, der im Nachtelfen-Zufluchtsort Auberdine Geschäfte macht, unterhält er freundschaftliche Beziehungen zu den dortigen Kaldorei und heißt Reisende, die der Allianz treu sind und die Dunkelküste durchqueren, willkommen.",al={"gorbold stahlhand fraktion","ist gorbold stahlhand allianz","gorbold loyalität"}}},fp="17,242,28.454.0,17.401.0,25.106.0,33.157.0,46.193.0,30.141.0"}
P.entries["npc:gordon-wendham"] = {n="Gordon Wendheim",s="Gordon Wendheim ist ein Waffenschmied und Händler der Verlassenen, der im geschäftigen Handwerksviertel von Unterstadt tätig ist. Er rüstet neu eingetroffene Champions und örtliche Verteidiger der Dunklen Fürstin mit verlässlichem Stahl, Klingen und stumpfen Waffen aus. Neben dem Feilbieten einfacher Rüstgüter dient er häufig als lokaler Ansprechpartner für Kuriere, die von der Oberfläche eintreffen.",h="Gordon Wendheim ist ein Waffenschmied und Händler der Verlassenen, der im geschäftigen Handwerksviertel von...",kw={"verlassene","gordon wendheim","michael garrett","handwerksviertel","unterstadt","waffenhändler"},ang={["class:Warrior"]="Gordon bietet verlässliche Grundklingen und Hiebwaffen für Frontkämpfer, die ihre Waffenfertigkeiten in der Hauptstadt ausbauen möchten.",["race:Undead"]="Für frisch befreite Verlassene, die Todesend verlassen, stellen Händler wie Gordon Wendheim im Handwerksviertel das praktische Rückgrat der Kriegsanstrengungen ihres noch jungen Volkes dar."},sec={{t="Rüstungsgüter des Handwerksviertel",b="Inmitten des feuchten Mauerwerks und der chemischen Kanäle im Handwerksviertel von Unterstadt versorgt Gordon Wendheim jene mit grundlegenden Waffen, die für die Verlassenen zu den Waffen greifen. Von einfachen Dolchen und Handäxten bis hin zu robusten Breitschwertern und Streitkolben richtet sich sein Sortiment an angehende Kämpfer, die verlässliches Eisen benötigen, bevor sie sich in die umkämpften Weiten von Lordaeron wagen."},{t="Ziel eines Kuriers",b="Über seinen Warenhandel hinaus ist Wendham in das rege Logistiknetzwerk der Hauptstadt eingebunden. Reisende, die von Flugmeistern und Kurieren auf Botengänge geschickt werden – wie etwa jene in Verbindung mit den Fledermausführern über den Ruinen –, werden oft direkt zu seinem Stand gewiesen. Seine zentrale Lage im Handwerksviertel macht ihn zu einer leicht erreichbaren und vertrauten Anlaufstelle für die Koordination grundlegender Vorräte und Depeschen in der gesamten unterirdischen Stadt."}},faq={{q="Wer ist Gordon Wendheim?",a="Gordon Wendheim ist ein untoter Händler, der im Handwerksviertel von Unterstadt stationiert ist. Er verkauft standardmäßige Kriegswaffen und dient als Ansprechpartner für Kuriere, die in der Hauptstadt eintreffen.",al={"gordon wendheim lore","wer ist wendham","unterstadt gordon"}},{q="Wo befindet sich Gordon Wendheim?",a="Ihr findet ihn an seinem Waffenstand im Handwerksviertel, dem Handelsring in den unterirdischen Hallen von Unterstadt.",al={"gordon wendheim aufenthaltsort","wo ist gordon unterstadt","handwerksviertel waffenhändler"}},{q="Was verkauft er?",a="Er bietet eine breite Palette grundlegender Standardwaffen an, darunter Schwerter, Dolche, Streitkolben, Stäbe, Äxte und verschiedene Wurfwaffen, die für aufstrebende Abenteurer geeignet sind.",al={"wendhams waren","was verkauft gordon","gordon wendheim waffen"}},{q="Welche Quests schließen ihn ein?",a="Er ist in einführende Lieferungen eingebunden, die die Fledermaushorste an der Oberfläche mit dem Inneren von Unterstadt verbinden, darunter Lieferungen zwischen ihm und dem Fledermausführer Michael Garrett.",al={"gordon wendheim quests","flug nach unterstadt","michael garrett quest"}}},fx={["84654bd5"]={q="Auf wessen Seite steht Gordon Wendheim?",a="Gordon Wendheim ist treu ergeben gegenüber Fürstin Sylvanas Windläufer und den Verlassenen und steht im Einklang mit der größeren Horde. Von seinem Laden in der Unterstadt aus unterstützt er seine untoten Verwandten, indem er Reisende und Soldaten ausstattet, die ihr zurückerobertes Königreich unter den Ruinen von Lordaeron verteidigen.",al={"fraktion gordon wendheim","wem dient gordon wendheim","ist gordon wendheim horde"}},d70aab3f={q="Warum ist Gordon Wendheim in der Unterstadt?",a="Gordon Wendheim geht seinem Handwerk als Waffenschmied im belebten Handwerksviertel der Unterstadt nach. Umgeben von den unterirdischen Hallen der Hauptstadt der Verlassenen steht er bereit, um jedem, der sich in die feindseligen Lande darüber begeben will, Klingen, Äxte und Streitkolben zu liefern.",al={"warum ist gordon wendheim hier","zweck gordon wendheim unterstadt","was führt gordon wendheim hierher"}}},fp="14,351,30.365.0,23.429.0,22.181.0,32.140.0,18.166.0,24.173.0"}
P.entries["npc:gornek"] = {n="Gornek",s="Gornek ist ein Orc-Vorarbeiter, der im Tal der Prüfungen in Durotar stationiert ist. Er dient als primäre Anlaufstelle für neue Rekruten der Orcs und Dunkelspeer, die sich darauf vorbereiten, ihren Wert für die neue Horde unter Beweis zu stellen.",h="Gornek ist ein Orc-Vorarbeiter, der im Tal der Prüfungen in Durotar stationiert ist.",kw={"der höhlenbau","durotar","gornek","pergament","die neue horde","das tal der prüfungen"},ang={["race:Orc"]="Für junge Orcs ist die Meldung bei Gornek der allererste Schritt, um die Kindheit hinter sich zu lassen und sich einen ehrenhaften Platz in Durotar zu verdienen.",["race:Troll"]="Als von Thrall aufgenommene Verbündete legen die Dunkelspeer Gornek ihre Papiere vor, um zu beweisen, dass sie als fähige Gleichgestellte an der Seite ihrer Orc-Brüder stehen."},sec={{t="Empfang der Unbewährten",b="Direkt im Herzen des Tals der Prüfungen stehend, stellt Gornek die erste Disziplinprüfung für angehende Krieger, Späher und Zauberwirker der Horde dar. Auf Befehl von Kriegshäuptling Thrall muss sich jeder Jugendliche und Neuling seinen Platz durch Härte und Ausdauer verdienen, anstatt durch bloßen Anspruch. Gornek mustert jene, die das Tal betreten, liest ihre Einführungsschreiben und verweist sie an die Lehrer auf dem Gelände. Ganz gleich, ob ein Initiant ein verschlüsseltes Gekritzel, ein Glyphenpergament oder eine einfache Tafel bei sich trägt – Gornek ist es, der ihre Empfehlungsschreiben entgegennimmt und sie auf ihren harten Pfad des Überlebens schickt."},{t="Ein Leben im Dienst von Durotar",b="Die kargen Schluchten des Tals prüfen mehr als nur das kriegerische Können; sie prägen das Gemeinschaftsgefühl der neuen Horde. Gornek sorgt dafür, dass Novizen nicht ziellos herumlungern, und weist ihnen den Weg zu den Prüfungen in den nahegelegenen Skorpionbauten, den Höhlen der wilden Eber und unter die wachsamen Augen erfahrener Ausbilder. Jene, die das Übungsgelände überleben und die Gefahren in den roten Felsenschluchten bezwingen, erhalten von Gornek die letzte Anerkennung, bevor er sie hinaus in die weite, gefährliche Wildnis von Durotar schickt."}},faq={{q="Wer ist Gornek?",a="Gornek ist ein Orc-Einweiser und Vorarbeiter im Tal der Prüfungen. Er beaufsichtigt neue Rekruten der Horde, liest ihre Einführungsschreiben und leitet sie zu ihren jeweiligen Klassenlehrern weiter.",al={"gornek","wer ist dieser orc","wer ist gornek"}},{q="Wo kann ich Gornek finden?",a="Er steht nahe dem Zentrum des Tals der Prüfungen im südwestlichen Durotar, direkt vor dem Höhlenbau, wo junge Orcs und Dunkelspeer ihre Reise beginnen.",al={"gornek aufenthaltsort","wo ist gornek","gornek karte"}},{q="Warum melden sich neue Rekruten bei ihm?",a="Neuankömmlinge tragen Schriftrollen und Tafeln bei sich, die ihre gewählte Disziplin angeben. Gornek prüft diese Empfehlungsschreiben, bestätigt ihre Eignung und schickt sie zu den entsprechenden Mentoren innerhalb des Tals.",al={"warum zu gornek","pergament quest","tafel quest"}},{q="Welche Rolle spielt er in der neuen Horde?",a="Er fungiert als Eintrittskoordinator für Thralls neue Horde. Seine Pflicht ist es, sicherzustellen, dass kein Rekrut die weiteren Lande von Durotar betritt, ohne zuvor die grundlegenden Grundsätze von Ehre, Überleben und Kampfbereitschaft erlernt zu haben.",al={"gornek rolle horde","was macht gornek"}}},fx={a3ac85eb={q="Auf wessen Seite steht Gornek?",a="Gornek ist Thralls Neuer Horde gegenüber loyal. Er ist in Durotar stationiert und dient als Aufseher im Tal der Prüfungen, wo er sicherstellt, dass jeder neu erwachte Orc und jeder Troll-Rekrut die Disziplin, Stärke und Überlebensmentalität annimmt, die notwendig sind, um ihre junge Nation zu verteidigen.",al={"gornek fraktion","wem dient gornek","gornek horde oder allianz"}},e623e91b={q="Was will Gornek?",a="Gornek möchte, dass Ihr Euch der Horde als würdig erweist. Durotar ist ein raues Land, das vor Raubtieren und feindlichen Infiltratoren wimmelt, und er weigert sich, Ressourcen an undisziplinierte Rekruten zu verschwenden. Er beauftragt junge Krieger damit, gefährliche Bestien zu jagen und lokale Bedrohungen auszuschalten, um sie zu fähigen Kämpfern zu formen.",al={"gornek ziel","was braucht gornek","gornek quest motive"}},a6376a9f={q="Warum ist Gornek im Tal der Prüfungen?",a="Das Tal der Prüfungen ist das ausgewiesene Übungsgelände für das neueste Blut der Horde. Gornek ist hier stationiert, um Neuankömmlinge anzuleiten, ihre ersten Fähigkeiten zu bewerten und sie mit den Ausbildern und Prüfungen bekannt zu machen, die sie auf die Herausforderungen von Durotar und darüber hinaus vorbereiten werden.",al={"warum ist gornek hier","gornek rolle tal der prüfungen","warum ist gornek in durotar"}}},fp="6,204,22.613.0,28.513.0,14.190.0,24.155.0,34.221.0,34.207.0"}
P.entries["npc:gramma-stonefield"] = {n="Oma Steinfeld",s="Oma Steinfeld, deren Vorname Mildred lautet, ist die betagte Matriarchin der Steinfeld-Familie, die auf ihrem Bauernhof im Wald von Elwynn lebt. Im Gegensatz zu ihrer streitsüchtigen Verwandtschaft ist sie der bitteren, generationenlangen Fehde mit den benachbarten Maclures überdrüssig geworden. Im Stillen hinter dem Rücken ihrer Familie tut sie alles in ihrer Macht Stehende, um ihrem Enkel Tommy Joe bei seiner verbotenen Romanze mit Maybell Maclure zu helfen.",h="Oma Steinfeld, deren Vorname Mildred lautet, ist die betagte Matriarchin der Steinfeld-Familie, die auf ihrem...",kw={"elwynn","oma steinfeld","maclure","maybell","mildred","hof der steinfelds","tommy joe","william pestle"},ang={["faction:Alliance"]="Oma Steinfeld ist eine sanfte Erinnerung daran, dass selbst im Kernland der Allianz lokale Konflikte oft eher leise Diplomatie und schlichtes Mitgefühl als blanken Stahl erfordern."},sec={{t="Eine heimliche Friedensstifterin",b="Als ältestes lebendes Mitglied der Steinfeld-Sippe hat Mildred Steinfeld jahrzehntelange kleinliche Streitigkeiten zwischen ihrem Hof und den Maclures auf der anderen Straßenseite miterlebt. Anstatt das böse Blut noch weiter anzufachen, betrachtet sie die anhaltende Rivalität als sinnlos und zerstörerisch. Als sich ihr Enkel Tommy Joe Steinfeld in Maybell Maclure verliebt, entscheidet sich Oma für Mitgefühl statt Sippentreue. Gestützt auf eine alte Freundschaft mit William Pestle in Goldhain schmiedet sie im Stillen Pläne, um den unglücklich Liebenden heimliche Treffen zu ermöglichen und so die sture Feindseligkeit zu untergraben, die die beiden Höfe trennt."}},faq={{q="Wer ist Oma Steinfeld?",a="Oma Steinfeld, mit Vornamen Mildred, ist die betagte Matriarchin der Steinfeld-Familie, die auf ihrem Bauernhof im zentralen Wald von Elwynn lebt. Sie ist die Großmutter von Tommy Joe Steinfeld.",al={"wer ist oma","mildred stonefield","stonefield oma"}},{q="Was hält sie von der Fehde mit den Maclures?",a="Mildred hat kein Interesse daran, die Fehde aufrechtzuerhalten. Anders als die meisten Mitglieder beider Familien hält sie den Groll für töricht und schädlich und wünscht sich Harmonie zwischen den Höfen statt endloser Zankereien.",al={"stonefield maclure fehde","hasst sie die maclures"}},{q="Warum hilft sie Tommy Joe und Maybell?",a="Sie liebt ihren Enkel Tommy Joe und möchte, dass er glücklich ist. Da sie die Familienfehde ablehnt, unterstützt sie tatkräftig seine verbotene Romanze mit Maybell Maclure, indem sie ihren alten Freund William Pestle bittet, eine Lösung für das Paar zu brauen.",al={"warum tommy joe helfen","oma liebestrank","verliebten helfen"}},{q="In welcher Beziehung steht William Pestle zu ihr?",a="William Pestle, der im Gasthaus \"Zur Höhle des Löwen\" in Goldhain lebende Alchemist, ist ein alter und vertrauter Freund von Oma Steinfeld. Sie wendet sich über vertrauenswürdige Boten an ihn, um feinsinnige Mittelchen und Hilfen für Tommy Joe zubereiten zu lassen.",al={"william pestle verbindung","william pestle oma"}}},fx={d471da09={q="Warum ist Oma Steinfeld hier?",a="Diese Hütte ist ihr Zuhause, in dem sie ihr Leben lang gelebt hat. Als Matriarchin und ältestes lebendes Mitglied des Clans Steinfeld wohnt Mildred direkt hier auf dem Hof der Steinfelds im Wald von Elwynn und wacht still über ihre Verwandten, während sie versucht, ihre kleinen Rivalitäten davon abzuhalten, junge Leben zu zerstören.",al={"warum ist oma steinfeld auf dem hof","hof der stonefields oma standort","warum ist mildred steinfeld hier"}}},fp="17,404,19.576.0,25.178.0,51.211.0,41.239.0,29.226.0"}
P.entries["npc:grand-mason-marblesten"] = {n="Großsteinmetz Marmorstein",s="Großsteinmetz Marmorstein ist ein hochangesehener Zwergensteinmetz, der im belebten Platzviertel von Eisenschmiede stationiert ist. Zutiefst dem königlichen Erbe von Khaz Modan verpflichtet, wurde er von König Magni Bronzebart damit beauftragt, eine Gedenkstätte für Sully Balloo zu errichten – einen Zwergensoldaten, der bei der Tragödie am Thandol-Übergang fiel. Abenteurer begegnen ihm oft, wenn sie bei der Beschaffung der für dieses feierliche Denkmal benötigten Materialien behilflich sind.",h="Großsteinmetz Marmorstein ist ein hochangesehener Zwergensteinmetz, der im belebten Platzviertel von...",kw={"ehrerbietung von einem könig","bronzebeard","platzviertel","großsteinmetz","eisenschmiede","magni","marblesten","steinmetz","sully balloo"},ang={["faction:Alliance"]="Das Opfer von Sully Balloo zu ehren, erinnert die Allianz an jeden Soldaten, den sie in ihren Kriegen verloren hat.",["profession:Mining"]="Bergleute, die intensiv mit dem Gestein von Dun Morogh und darüber hinaus vertraut sind, werden Marblestens anspruchsvolle Maßstäbe an die Rohstoffqualität zu schätzen wissen.",["race:Dwarf"]="Für Zwerge ist die Steinkunst ein Erbe der Ahnen; Marblesten zu helfen, erweist sowohl dem Handwerk von Khaz Modan als auch dem Andenken an den gefallenen Soldaten Sully Balloo die Ehre."},sec={{t="Meister des Steins",b="Die Zwergensteinmetzkunst ist nicht bloß ein Handwerk; sie ist eine beständige Kunstform, die die Seele von Eisenschmiede prägt. Großsteinmetz Marmorstein gehört zu den herausragendsten Meißelmeistern der Stadt und repräsentiert die jahrhundertealte Tradition, Hallen, Säulen und gewaltige Bildnisse direkt aus dem lebendigen Fels zu hauen. Vom Platzviertel aus leitet er städtische Bauvorhaben und Denkmäler, die die Geschichte der Bronzebeard verewigen."},{t="Ehrerbietung von einem König",b="Marblestens ergreifendste Aufgabe ist ein Mahnmal, das König Magni für Sully Balloo in Auftrag gab – einen Soldaten, der bei der Tragödie am Thandol-Übergang starb –, als Ehrung für dessen trauernde Witwe. Da er ein wahrhaft beständiges Werk schaffen will, besteht der Großsteinmetz auf einem der edelsten Steine überhaupt: Alteracgranit von Darrow Hill in Hillsbrad."}},faq={{q="Wer ist Großsteinmetz Marmorstein?",a="Großsteinmetz Marmorstein ist ein erfahrener Zwergensteinmetz im Platzviertel von Eisenschmiede. Ihm sind städtische und königliche Bildhauerprojekte anvertraut, allen voran eine Gedenkstätte für den gefallenen Soldaten Sully Balloo im Auftrag von König Magni Bronzebart.",al={"wer ist marblesten","marblestens rolle","großsteinmetz nsc"}},{q="Wo kann ich Großsteinmetz Marmorstein finden?",a="Er hält sich im Platzviertel von Eisenschmiede auf, umgeben von Steinblöcken und architektonischen Arbeiten, unweit der geschäftigen Läden und Banken der Stadt.",al={"marblesten standort","wo ist marblesten","eisenschmiede marblesten"}},{q="An welchem Denkmal arbeitet Marblesten?",a="Er errichtet eine Gedenkstätte für Sully Balloo, einen Zwergensoldaten, der bei der Tragödie am Thandol-Übergang starb. König Magni Bronzebart gab sie als Würdigung für Balloo und seine trauernde Witwe in Auftrag.",al={"was baut er","quest ehrerbietung von einem könig","marblestenteinstatue"}},{q="Warum benötigt Marblesten Abenteurer, um Materialien zu beschaffen?",a="Marblesten möchte ein wahrhaft monumentales und dauerhaftes Werk schaffen, weshalb er nur mit einem der edelsten Steine arbeiten will. Er schickt Reisende nach Darrow Hill in Hillsbrad, um Alteracgranit zu sammeln.",al={"marblesten quests","warum steine nötig","materialien für denkmal"}},{q="Was bedeutet der Titel „Großsteinmetz“ in der Zwergengesellschaft?",a="Unter Zwergen wird die Steinbearbeitung neben der Schmiedekunst gleichermaßen verehrt. Ein „Großsteinmetz“ ist ein meisterhafter Vollender der Steinkunst, dem bedeutende staatliche Vorhaben, königliche Architekturentwürfe und zeremonielle Denkmäler anvertraut werden.",al={"was ist ein großsteinmetz","zwergensteinmetz rang"}},{q="Ist Marblesten ein Beamter der Allianz oder ein privater Auftragnehmer?",a="Marblesten agiert direkt innerhalb von Eisenschmiede und dient dem Königreich Eisenschmiede sowie der Allianz, wobei er eng mit dem Hof von König Magni Bronzebart bei königlichen Aufträgen zusammenarbeitet.",al={"für wen arbeitet marblesten","marblestens fraktion"}}},fx={a77cb24b={q="Auf wessen Seite steht Großsteinmetz Marmorstein?",a="Marmorstein ist Eisenschmiede und der Allianz gegenüber absolut loyal. Er ist direkt im Herzen des Stadtviertels der Commons stationiert, dient König Magni Bronzebeard und dem Zwergenkönigreich und widmet sein Handwerk und seine Steinmetzkunst der Ehrung des Zwergenerbes und des Throns.",al={"marmorstein fraktion","wem dient marmorstein","marmorstein allianz"}},["1dc5a337"]={q="Was will Großsteinmetz Marmorstein?",a="Marmorstein beaufsichtigt ein königliches Denkmal und benötigt feine Materialien, um es fertigzustellen. Durch seine Arbeit an 'A King's Tribute' sucht er nach fähigen Abenteurern, die ihm helfen, die wesentlichen Ressourcen für das von König Magni in Auftrag gegebene Denkmal für den gefallenen Soldaten Sully Balloo zu beschaffen.",al={"was will marmorstein","marmorstein ziel","warum braucht marmorstein hilfe"}},["98aae54f"]={q="Warum ist Großsteinmetz Marmorstein in den Commons?",a="Marmorstein hat seine Werkstatt in den geschäftigen Commons von Eisenschmiede eingerichtet, um die Steinmetzarbeiten der großen Bergfestung zu überwachen und die Bauarbeiten für den Thron zu organisieren. Der offene Platz ermöglicht es ihm, Projekte zu koordinieren und Reisende, die durch die Stadt kommen, zu rekrutieren.",al={"warum ist marmorstein in eisenschmiede","warum ist marmorstein hier","marmorstein commons eisenschmiede"}}},fp="22,395,19.426.0,16.312.0,30.247.0,40.154.0,39.182.0,57.184.0,58.210.0,59.176.0"}
P.entries["npc:granis-swiftaxe"] = {n="Granis Flinkaxt",s="Granis Flinkaxt ist ein Kriegerlehrer der Zwerge, der in der Brauerei Donnerbräu in Kharanos stationiert ist. Bekannt für sein schroffes Auftreten und seinen harten Trainingsplan, unterweist er angehende Kämpfer der Allianz, die aus der Eisklamm kommen, bevor er erfahrene Krieger in die Stadt Eisenschmiede schickt.",h="Granis Flinkaxt ist ein Kriegerlehrer der Zwerge, der in der Brauerei Donnerbräu in Kharanos stationiert ist.",kw={"dun morogh","granis flinkaxt","kharanos","muren stormpike","brauerei donnerbräu","kriegerlehrer"},ang={["class:Warrior"]="Für Kämpfer der Zwerge und Gnome, die das Coldridgetal verlassen, bietet Granis wichtige grundlegende Kampfausbildung direkt neben einem frischen Krug in der Brauerei.",["race:Dwarf"]="Granis verkörpert den robusten und sturen Geist der Fußsoldaten von Eisenschmiede und verbindet kriegerische Disziplin mit den Annehmlichkeiten des einheimischen Bieres."},sec={{t="Ein schroffer Mentor in Kharanos",b="Granis Flinkaxt wärmt sich zwischen den Fässern der Brauerei Donnerbräu auf und dient als primärer Kampfausbilder für junge Krieger, die Dun Morogh durchqueren. Er besitzt den unbeugsamen Stolz, der typisch für Zwergenkämpfer ist, und zeigt offene Belustigung sowie Verachtung gegenüber Nicht-Kriegern, die versuchen, Gehör bei ihm zu finden. Sobald ein Schüler ausreichendes Kampfgeschick beweist, schickt Granis ihn den Bergpfad hinauf, um Meisterausbilder Muren Stormpike im Military Ward von Eisenschmiede aufzusuchen."}},faq={{q="Wer ist Granis Flinkaxt?",a="Granis Flinkaxt ist ein Kriegerlehrer der Zwerge, der sich im Erdgeschoss der Brauerei Donnerbräu in Kharanos befindet. Er lehrt junge Zwergen- und Gnomkrieger, die Abenteuer in Dun Morogh erleben, frühe Kampftechniken.",al={"granis flinkaxt","wer ist granis","kriegerlehrer in kharanos"}},{q="Warum verspottet Granis meinen Charakter?",a="Granis hat keine Geduld für jene, die nicht den Pfad des Kriegers beschreiten. Wenn ein Abenteurer einer anderen Klasse mit ihm spricht, spottet er über die Vorstellung, dass dieser auch nur einen einzigen Tag unter seinem harten Trainingsplan überleben könnte.",al={"granis unhöfliches zitat","warum lacht granis über mich","granis text für nicht-krieger"}},{q="Wohin schickt Granis aufstrebende Krieger?",a="Sobald ein Krieger genug Erfahrung in Dun Morogh gesammelt hat, weist Granis ihn an, Muren Stormpike aufzusuchen, einen ranghohen Kriegerlehrer im Military Ward von Eisenschmiede.",al={"muren stormpike quest","granis questreihe","zu wem schickt granis einen"}},{q="Ist Granis mit anderen Flinkäxten in Khaz Modan verwandt?",a="Er teilt den Nachnamen Flinkaxt mit anderen Zwergen, doch eine familiäre Beziehung ist nicht bestätigt.",al={"familie flinkaxt","granis flinkaxt verwandte"}}},fx={b8e95117={q="Auf wessen Seite steht Granis Flinkaxt?",a="Granis steht fest an der Seite der Zwerge von Eisenschmiede und der breiteren Allianz. Er ist in Kharanos stationiert und widmet seine militärische Expertise dem Training der nächsten Generation von Verteidigern gegen die Troggs, Frosttrolle und andere Bedrohungen in der Umgebung von Dun Morogh.",al={"granis flinkaxt fraktion","für wen kämpft granis","granis allianz"}},["760b1803"]={q="Warum ist Granis Flinkaxt in Kharanos?",a="Granis ist in der Brauerei Donnerbräu in Kharanos stationiert, um angehende Krieger der Allianz auszubilden, die von der Eisklamm aufbrechen. Dun Morogh steht unter wachsendem Druck durch einheimische Troggs und Wendigos, was seine rigorosen Kampfübungen für die lokale Verteidigung unerlässlich macht.",al={"warum ist granis hier","granis flinkaxt standort grund","was brachte granis nach kharanos"}},cf3183bb={q="Was will Granis Flinkaxt?",a="Granis will nichts Geringeres als abgehärtete, disziplinierte Krieger, die in der Lage sind, die Linie für Khaz Modan zu halten. Er hat wenig Geduld für Schwache oder Unausgebildete und fordert unerbittliches Engagement von Rekruten, bevor er vielversprechende Veteranen an Meister wie Muren Stormpike in Eisenschmiede weiterleitet.",al={"granis flinkaxt ziele","was will granis","granis zweck"}}},fp="15,285,26.485.0,23.216.0,34.218.0,42.170.0,51.91.0"}
P.entries["npc:great-father-winter"] = {n="Altvater Winter",s="Altvater Winter ist ein älterer Orc, der von der Handelsgesellschaft Kokelwälder angestellt wurde, um in Orgrimmar als die legendäre Festtagsgestalt aufzutreten. Während des Winterhauchfests hat er seinen Platz nahe Grommash Hold im Tal der Stärke bezogen, wo er sich die Wünsche der Kinder anhört, während ihm der kommerzielle Feiertagstrubel zusehends zusetzt. Im Austausch für Festtagsgeschenke und saisonale Aufgaben bittet er Vorbeigehende regelmäßig um Lebkuchen und Eiskalte Milch.",h="Altvater Winter ist ein älterer Orc, der von der Handelsgesellschaft Kokelwälder angestellt wurde, um in...",kw={"lebkuchen","altvater winter","orgrimmar","kokelwälder","tal der stärke","winterhauch"},ang={["faction:Horde"]="Er dient als wichtigste saisonale Identifikationsfigur für die Horde in Orgrimmar und bietet im Namen von Kokelwälder Festtagsgeschenke und Aufgaben an.",["profession:Cooking"]="Köche können nach festlichen Rezepten Lebkuchen backen und diese zusammen mit Milch direkt zu Altvater Winter bringen, um seine Lebensgeister zu wecken.",["race:Orc"]="Obwohl Orcs den Wechsel der Jahreszeiten und die Elemente verehren, stellt der Anblick eines der Ihren als kostümiertes Maskottchen, das Händlerrabatte anpreist, die Geduld von Traditionalisten auf die Probe."},sec={{t="Ein gemieteter Mythos",b="Während alte Überlieferungen von Altvater Winter als einem majestätischen Elementargeist sprechen, der durch das Land zieht und Schnee sowie den Wandel der Jahreszeiten bringt, ist die Gestalt im Tal der Stärke weitaus weltlicher. Er ist ein orcischer Darsteller auf der Gehaltsliste von Kokelwälder, der eigens angeheuert wurde, um den Handel anzukurbeln, Waren der Gesellschaft zu bewerben und die Jugend der Horde zu unterhalten. Kritiker murren, dass dieses kommerzielle Maskottchen echte saisonale Traditionen entwerte, doch kaum jemand kann die festliche Betriebsamkeit leugnen, die er in die Straßen der Stadt bringt."},{t="Schichtarbeit im Tal der Stärke",b="Direkt vor Grommash Hold unter den Zweigen geschmückter Nadelbäume erträgt dieser Vertreter eine zermürbende Schicht, in der Kinder auf seinen Schoß klettern, um ihre Geschenkwünsche vorzubringen. Zwischen eingeworfenen Werbesprüchen für Rabatte von Kokelwälder und halbherzigen Feiertagsgrüßen lässt seine Ausdauer spürbar nach. Er gibt unumwunden zu, eine Flasche hochprozentiger Festtagsstimmung in seinem Rucksack versteckt zu haben, um den Lärm zu ertränken, sobald seine Schicht endet, und ist stark darauf angewiesen, dass durchreisende Abenteurer ihm stärkende Leckereien bringen."}},faq={{q="Ist dies der echte Altvater Winter?",a="Nein. Er ist ein gewöhnlicher Orc, der von Kokelwälder angeheuert wurde, um sich zu verkleiden, die legendäre Winterhauch-Gestalt darzustellen und in Orgrimmar Festtagsangebote zu verteilen.",al={"ist er echt","wer ist altvater winter","ist er ein schauspieler"}},{q="Wo finde ich Altvater Winter in Orgrimmar?",a="Er befindet sich im Tal der Stärke, direkt vor dem Eingang zu Grommash Hold neben dem Winterhauchbaum und den Festtagsständen.",al={"altvater winter standort","wo ist altvater winter","wo findet man den winter-orc"}},{q="Was tut er während des Winterhauchfests?",a="Er unterhält Festtagsbesucher, hört sich die Geschenkwünsche der Kinder an, vergibt Werbeaufgaben für Kokelwälder und überreicht festliche Geschenke unter dem Baum, sobald der Höhepunkt der Feiertage erreicht ist.",al={"was macht er","altvater winter aufgabe","winterhauch quests"}},{q="Warum verlangt er Lebkuchen und Milch?",a="Laute Menschenmengen und ein Kind nach dem anderen auf seinem Schoß zu ertragen, laugt ihn völlig aus. Er bittet Abenteurer darum, ihm frische Lebkuchen und Milch zu bringen, um bei Kräften durch die Schicht zu kommen.",al={"leckereien für altvater winter","warum milch und kekse","lebkuchen quest"}},{q="Wie steht er zu seiner Arbeit?",a="Er empfindet die Rolle als mühselig und kräftezehrend. Er meckert offen über ungeduldige Kinder, leiert Unternehmensparolen herunter und zählt ungeduldig die Minuten, bis er einen Schluck aus der Flasche nehmen kann, die er in seiner Tasche versteckt hat.",al={"mag er seinen job","altvater winter zitate","ist er betrunken"}},{q="Gibt es aufseiten der Allianz eine entsprechende Gestalt?",a="Ja. Die Allianz hat Altvater Winter, einen älteren Zwerg im Dienst von Kokelwälder, der nahe dem Festtagsbaum im The Commons von Eisenschmiede sitzt.",al={"allianz altvater","eisenschmiede weihnachtsmann","allianz gegenstück"}}},fx={["1d43ce2e"]={q="Auf wessen Seite steht Altvater Winter?",a="Dieser Altvater Winter ist ein Orc, der ausschließlich innerhalb von Orgrimmar für die Horde arbeitet, obwohl sein eigentlicher Arbeitgeber Smokywood Pastures ist. Das Goblin-Unternehmen heuerte ihn an, um festliche Stimmung – und festliche Konsumausgaben – ins Tal der Stärke zu bringen. Während er das festliche rote Gewand der Legende trägt, gilt seine wahre Loyalität seinem Gehaltsscheck und dem Überstehen seiner zermürbenden Schicht.",al={"ist altvater winter horde","altvater winter fraktion","für wen arbeitet altvater winter"}},["796ea74c"]={q="Warum ist Altvater Winter hier?",a="Er ist vor Grommash Hold stationiert, weil Smokywood Pastures ihn engagierte, um ihre Feierlichkeiten zum Winterhauchfest in der Hauptstadt der Horde zu verankern. Die kaufmännischen Goblins setzten ihn ein, um die Jugend der Stadt zu unterhalten, sich ihre Geschenkwünsche anzuhören und eifrige Familien zu Feiertagswaren und festlichen Leckereien zu lenken.",al={"warum ist altvater winter in orgrimmar","was brachte altvater winter hierher","grund warum altvater winter hier ist"}},f14772a5={q="Mit wem ist Altvater Winter verbunden?",a="Er ist direkt bei Smokywood Pastures angestellt, dem unternehmerischen Goblin-Betrieb, der für die Vermarktung des Winterhauchfests im ganzen Reich verantwortlich ist. Sie liefern sein festliches Kostüm, legen seine Werbesprüche fest und organisieren die Geschenke und Leckereien, die er rund um Grommash Hold verteilt.",al={"wer hat altvater winter angeheuert","altvater winter verbindungen","smokywood pastures altvater winter"}},["826ac72e"]={q="Warum ist Altvater Winter berühmt?",a="Er beansprucht den Namen und die Gestalt von Altvater Winter, einer alten übernatürlichen Figur, die in ganz Azeroth gefeiert wird, weil sie den Wechsel der Jahreszeiten ankündigt. Während Gelehrte argumentieren, dass dieser kostümierte Orc lediglich ein kommerzielles Maskottchen ist, strömen Kinder und festliche Feiernde immer noch zu ihm als dem lebendigen Gesicht der Freude des Winterhauchfests.",al={"warum kennen leute altvater winter","ist altvater winter legendär","altvater winter ruf"}}},fp="19,438,12.510.0,36.525.0,36.154.0,50.145.0,48.183.0,46.205.0,30.223.0,44.149.0"}
P.entries["npc:greatfather-winter"] = {n="Altvater Winter",s="Altvater Winter ist die legendäre Personifizierung der Wintersaison und die zentrale Gestalt des Winterhauchfests. Während uralte Legenden ihn als mythisches Wesen verehren, das Azeroth mit Schnee bedeckt, damit das Land ruhen und sich erneuern kann, kennen moderne Stadtbewohner ihn vor allem durch das kommerzielle Spektakel, das von den Goblins der Kokelwälder bereitgestellt wird.",h="Altvater Winter ist die legendäre Personifizierung der Wintersaison und die zentrale Gestalt des...",kw={"dun morogh","lebkuchen","altvater winter","eisenschmiede","orgrimmar","kokelwälder","winterhauchfest"},ang={["profession:Cooking"]="Das Fest verlässt sich auf geschickte Köche, um Lebkuchen und andere festliche Leckereien für die Kokelwälder und Altvater Winter selbst zuzubereiten.",["race:Dwarf"]="Zwerge sehen den Altvater als einen Aspekt der Titanen, die die Welt formten, und betrachten die verschneiten Gipfel von Dun Morogh als lebendiges Zeugnis seiner Berührung."},sec={{t="Mythos und Erneuerung",b="Uralten Überlieferungen zufolge ist Altvater Winter ein ätherischer Wanderer, der spät im Jahr die Welt durchstreift und seinen wogenden Schneemantel über das Land breitet, damit die Natur schlummern und wiedergeboren werden kann. Zwerge betrachten ihn als eine Verkörperung oder einen Herold der Titanen und verweisen auf die verschneiten Felsen von Dun Morogh als lebenden Beweis seiner Gunst. Andere Traditionen, wie jene der Tauren, respektieren seine Rolle beim Wandel der Jahreszeiten, schreiben die Kälte und die Stürme jedoch dem elementaren Wirken von Sonne und Mond zu, die der Erdenmutter Zeit zur Ruhe schenken. Wohin die Legende auch gelangte, lernten die Gemeinschaften, zusammenzukommen und gemeinsam gegen die Kälte zu schmausen, um das Versprechen wiederkehrenden Lebens zu feiern."},{t="Die Kokelwälder und städtische Feierlichkeiten",b="In großen Siedlungen wie Eisenschmiede und Orgrimmar wurde der uralte Geist von den geschäftstüchtigen Goblins der Kokelwälder von Grund auf umgestaltet. Das Handelskartell machte die Darstellung von Altvater Winter als fröhlichem, rot gekleidetem Greis mit weißem Bart populär, der auf einem fliegenden Schlitten fährt und festliche Leckereien sowie Spielzeug verteilt. Die Kokelwälder heuern lokale Schauspieler an – einen Zwerg in Eisenschmiede und einen Ork in Orgrimmar –, um die Wunschzettel der Kinder anzuhören, Gaben von Milch und Lebkuchen entgegenzunehmen und unter aufwendig geschmückten Bäumen saisonale Waren anzupreisen."}},faq={{q="Ist der Altvater Winter in Eisenschmiede der echte Geist?",a="Nein, der Altvater Winter, der am Festtagsbaum in Eisenschmiede sitzt, ist ein Schauspieler, der von der Goblin-Handelsgesellschaft Kokelwälder engagiert wurde. Die Gesellschaft inszeniert diese Auftritte, um Kinder zu erfreuen und saisonale Süßwaren zu verkaufen, wenngleich echte Legenden von einem tatsächlichen ätherischen Wesen berichten, das im Winter die Welt durchstreift.",al={"ist altvater winter echt","wer ist der typ in eisenschmiede","ist er ein schauspieler"}},{q="Warum verehren die Zwerge Altvater Winter?",a="Zwerge bringen Altvater Winter mit ihren Schöpfern, den Titanen, in Verbindung. Sie betrachten die Schneedecke, die er über das Land wirft, als Segen und sehen ihre dauerhaft eisige Heimat Dun Morogh als besten Beweis seiner Gunst an.",al={"zwerge winterhauchfest","zwergischer altvater winter","eisenschmiede altvater winter"}},{q="Was macht Altvater Winter mit den Keksen und der Milch, die man ihm bringt?",a="Nach den von den Kokelwäldern verbreiteten Festtagsbräuchen nascht Altvater Winter für sein Leben gern festliche Lebkuchen und eiskalte Milch, während er Wunschzettel durchgeht und Festtagsstimmung verbreitet.",al={"leckereien für altvater winter","warum milch und kekse","lebkuchen quest"}},{q="Wie betrachtet die Horde Altvater Winter?",a="Die Horde nimmt an den Festlichkeiten größtenteils durch die städtischen Aktionen der Kokelwälder in Orgrimmar teil, wo der Altvater als Ork dargestellt wird. Kulturell erkennen die Tauren den Winter als lebenswichtige Zeit des Schlummers und der elementaren Erneuerung für die Erdenmutter an; sie respektieren die Rolle des Altvaters im Kreislauf der Jahreszeiten, meiden jedoch eine buchstäbliche Titanenverehrung.",al={"horde altvater winter","orgrimmar altvater winter","tauren winterhauchfest"}}},fx={["66677a0e"]={q="Auf wessen Seite steht Altvater Winter?",a="Er gehört keiner Fraktion an. Der Legende nach ist Altvater Winter eine uralte, übernatürliche Naturgewalt, die der ganzen Welt saisonale Erneuerung und Reichtum schenkt, ungeachtet der Loyalität der Sterblichen. Die Gestalt, die Ihr in Eisenschmiede sitzen seht, wird von der Goblin-Handelsgesellschaft Raucherdampf gesponsert, die einen streng neutralen, gewinnorientierten Betrieb führt. Tatsächlich heuert Raucherdampf einen Orc an, der in Orgrimmar sitzt und gleichzeitig die Feiertagsstimmung unter der Horde verbreitet.",al={"altvater winter allianz oder horde","gehört altvater winter zur allianz","fraktion altvater winter"}},a8f1de98={q="Was will Altvater Winter?",a="Der uralte Geist des Mythos möchte die Welt nur in Winter hüllen, um dem Land die nötige Zeit für Ruhe, Wiedergeburt und letztendliche Erneuerung zu geben, während er denjenigen, die ihn willkommen heißen, Reichtum gewährt. Der sterbliche Nachahmer, den Ihr in Eisenschmiede trefft, ist jedoch bei Raucherdampf angestellt. Ihr Ziel ist rein festlich und kommerziell: Freude zu bringen, Leckereien an brave Kinder zu verteilen und den Verkauf ihrer Feiertagswaren und Spielzeuge anzukurbeln.",al={"beweggründe altvater winter","was will altvater winter","warum verteilt altvater winter geschenke"}},daa32740={q="Warum ist Altvater Winter in Eisenschmiede?",a="Raucherdampf hat ihn neben dem Altvater-Winter-Baum stationiert, um ihre saisonalen Feierlichkeiten zu verankern. Während der Wochen vor dem Fest trifft sich die fröhliche Gestalt mit Bürgern und Kindern, um ihre Feiertagswünsche zu hören, Briefe zu sammeln und gemeinsam mit seinen Goblin-Helfern guten Willen zu verbreiten – all das, während er Raucherdampf dabei hilft, ihre saisonalen Waren zu bewerben.",al={"warum ist altvater winter in eisenschmiede","warum ist altvater winter hier","standort altvater winter eisenschmiede"}},["8b922b4d"]={q="Mit wem ist Altvater Winter verbunden?",a="Die zwergische Tradition verbindet den uralten Geist eng mit den Titanen und glaubt, dass er ihre formende Kraft über die Jahreszeiten von Azeroth verkörpert. In der täglichen Praxis arbeitet der festliche Altvater, den man in der Stadt sieht, mit Raucherdampf zusammen, umgeben von ihren winzigen Kleinen Helfern und festlichen Schneemännern.",al={"mit wem wird altvater winter in verbindung gebracht","verbindungen altvater winter","wer arbeitet mit altvater winter"}}},fp="18,362,16.674.0,39.571.0,55.303.0,41.228.0,73.202.0,43.359.0"}
P.entries["npc:greatmother-hawkwind"] = {n="Großmutter Falkenwind",s="Großmutter Falkenwind ist eine verehrte Taurenälteste, die am Wasserbrunnen auf der Hochwolkenebene weilt. Als Mutter des Anführers von Camp Narache, Häuptling Falkenwind, verkörpert sie trotz ihres hohen Alters den unerschütterlichen Geist und die gemeinschaftliche Verantwortung des Stammes.",h="Großmutter Falkenwind ist eine verehrte Taurenälteste, die am Wasserbrunnen auf der Hochwolkenebene weilt.",kw={"eine bescheidene bitte","camp narache","häuptling falkenwind","großmutter falkenwind","mulgore","die hochwolkenebene","taurenälteste","unaya"},ang={["race:Tauren"]="Für junge Tauren, die ihre Reise auf der Hochwolkenebene beginnen, verkörpert Großmutter Falkenwind die Grundwerte der Erdenmutter: Respekt vor den Ältesten, Zusammenhalt der Gemeinschaft und Demut im Dienst an anderen."},sec={{t="Älteste der Mesa",b="Großmutter Falkenwind verbringt ihre Tage am Süßwasserbrunnen von Camp Narache und dient jungen Tauren, die ihre Übergangsriten beginnen, als spirituelle Matriarchin. Obwohl die Jahre ihre Schritte verlangsamt haben, weigert sie sich, ihre Pflichten gegenüber dem Dorf aufgrund ihres Alters ruhen zu lassen. Sie glaubt fest daran, dass jedes Stammesmitglied, ob jung oder alt, eine aktive Rolle beim Erhalt der Gemeinschaft spielt, und bittet junge Heranwachsende oft darum, bei einfachen häuslichen Aufgaben wie dem Holen von frischem Wasser zur Hand zu gehen."},{t="Mütterlicher Rat",b="Als Mutter von Häuptling Falkenwind, dem Anführer von Camp Narache, steht Großmutter Falkenwind der Gemeinschaft inmitten der Bedrohungen für die Hochwolkenebene mit besonnenem Rat und stiller Würde zur Seite. Während ihr Sohn Jäger und Krieger gegen die vordringenden Borstennacken-Stacheleber und einheimische Raubtiere mobilisiert, hütet sie das moralische Herz der Siedlung und erinnert die Neuankömmlinge daran, dass Stärke mit Demut und dem Dienst an den eigenen Stammesgeschwistern beginnt."}},faq={{q="Wer ist Großmutter Falkenwind?",a="Großmutter Falkenwind ist eine betagte Taurenmatriarchin, die in Camp Narache auf der Hochwolkenebene lebt. Sie ist die Mutter des Lagerführers, Häuptling Falkenwind, und fungiert als weise Wegweiserin für junge Abenteurer.",al={"großmutter hawkwind lore","wer ist großmutter hawkwind","camp narache älteste"}},{q="Wo ist sie zu finden?",a="Sie sitzt am Wasserbrunnen südöstlich von Camp Narache auf der Hochwolkenebene im südwestlichen Mulgore.",al={"großmutter hawkwind standort","wo ist großmutter hawkwind"}},{q="Welche Aufgaben überträgt sie jungen Tauren?",a="Sie betraut junge Tauren mit der Quest „Eine bescheidene Aufgabe“, bei der sie Wasser aus dem Dorfbrunnen schöpfen und zu anderen im Lager bringen müssen. Diese Pflicht lehrt, dass keine Aufgabe zu gering für einen wahren Diener des Stammes ist.",al={"großmutter hawkwind quest","eine bescheidene bitte"}},{q="In welcher Beziehung steht sie zu Häuptling Falkenwind?",a="Sie ist die Mutter von Häuptling Falkenwind, der die Verteidigung und die Ausbildung der jungen Krieger in Camp Narache leitet.",al={"mutter von häuptling hawkwind","ist sie mit häuptling hawkwind verwandt"}}},fx={f701fe56={q="Auf wessen Seite steht Großmutter Falkenwind?",a="Großmutter Falkenwind widmet sich ihrem Volk, den Tauren der Horde. Als älteste Matriarchin von Camp Narache liegt ihre Loyalität ganz bei ihrem Stamm, ihrer Familie und den jungen Kriegern, die ausziehen, um den Ahnen und der Erdenmutter zu dienen.",al={"fraktion großmutter falkenwind","wem dient großmutter falkenwind","loyalität großmutter falkenwind"}},["8d52ad78"]={q="Was will Großmutter Falkenwind?",a="Trotz ihres hohen Alters besteht Großmutter Falkenwind darauf, ihren Teil zur Versorgung von Camp Narache beizutragen. Sie kümmert sich um die Bedürfnisse der Siedlung, erledigt einfache häusliche Pflichten wie das Heranschaffen von frischem Wasser aus dem Dorfbrunnen und bittet junge Tauren, bei diesen bescheidenen alltäglichen Aufgaben eine Helfende Hand zu reichen.",al={"was braucht großmutter falkenwind","ziel großmutter falkenwind","warum mit großmutter falkenwind sprechen"}},["2db356dc"]={q="Warum ist Großmutter Falkenwind hier?",a="Großmutter Falkenwind lebt als Dorfälteste und Mutter von Häuptling Falkenwind in Camp Narache. Ihr findet sie am zentralen Wasserbrunnen der Siedlung, wo sie fleißig arbeitet, um ihren Stamm zu unterstützen und über die jungen Jäger und Schamanen wacht, die ihre Reise auf der Hochwolkenebene beginnen.",al={"warum ist großmutter falkenwind in camp narache","standort großmutter falkenwind grund","warum ist sie am brunnen"}}},fp="20,247,17.476.0,19.413.0,28.203.0,23.96.0,40.205.0,39.107.0"}
P.entries["npc:grelin-whitebeard"] = {n="Grelin Weißbart",s="Grelin Weißbart ist ein Zwergenspäher, der per königlichem Erlass im Coldridgetal stationiert ist, um die Bedrohung durch die Frostmane-Trolle einzuschätzen. Von einem abgelegenen Lager aus, das er mit einem ungeschickten Lehrling teilt, setzt er auf aufstrebende Abenteurer, um die Trolle in Schach zu halten, während Eisenschmiedes Aufmerksamkeit vollkommen von der Trogg-Krise beansprucht wird.",h="Grelin Weißbart ist ein Zwergenspäher, der per königlichem Erlass im Coldridgetal stationiert ist, um die...",kw={"das coldridgetal","dun morogh","frostmane","grelin weißbart","grik'nir","senat von eisenschmiede","senir weißbart","das gestohlene tagebuch"},ang={["faction:Alliance"]="Grelins missliche Lage verdeutlicht, wie stark die Armeen der Allianz und Eisenschmiedes in Dun Morogh zersplittert sind, was einsame Späher dazu zwingt, stille Kriege gegen Troll-Enklaven zu führen.",["race:Dwarf"]="Im direkten Dienst von König Magni verkörpert Grelin die stille, beharrliche Ausdauer der Späher von Eisenschmiede, die Dun Moroghs Grenzen gegen wachsende innere Bedrohungen zusammenhalten.",["race:Gnome"]="Nach der Tragödie von Gnomeregan treffen gnomische Flüchtlinge, die das Coldridgetal durchqueren, auf Grelin, der in seinem abgelegenen Lager an der Seite eines wandernden Gnoms arbeitet."},sec={{t="Ein königlicher Auftrag",b="Grelin Weißbart und sein Bruder Senir wurden auf direkten Befehl des Senats von Eisenschmiede und König Magni Bronzebarts höchstpersönlich in das Coldridgetal entsandt. Ihre Mission war klar: die von den einheimischen Frostmane-Trollen ausgehende Bedrohung zu beurteilen und zu neutralisieren. Da Eisenschmiedes reguläres Militär durch die Bekämpfung von Trogg-Ausbrüchen in ganz Dun Morogh vollkommen gebunden war, erhielten die Brüder nur sehr wenige Mittel für ihre Aufgabe. Grelin musste einen Außenposten in den verschneiten Hügeln errichten und sich an örtliche Rekruten sowie durchreisende Initianden wenden, um die notwendige Arbeit zu erledigen."},{t="Ärger im Süden",b="Von seinem Lager aus überwacht Grelin den vorrückenden Stamm der Frostmane südlich des Coldridgetals. Die Trolle sind zunehmend aggressiver geworden und wagen kühnere Vorstöße außerhalb ihrer Berghöhlen. Bei einem solchen Überfall schlich sich ein schwer bemalter Hüne namens Grik'nir the Cold in das unbeaufsichtigte Lager und entwendete Grelins Feldbuch, das seine wichtigsten Beobachtungen enthielt. Um den König nicht zu enttäuschen, nutzt Grelin unerschrockene Reisende, um tief in die Höhlen der Frostmane vorzustoßen, seine gestohlenen Aufzeichnungen wiederzubeschaffen und sicherzustellen, dass seine abschließenden Berichte Senir in Kharanos erreichen."}},faq={{q="Warum ist Grelin Weißbart hier draußen im Schnee?",a="Grelin wurde offiziell vom Senat von Eisenschmiede und König Magni Bronzebart beauftragt, die Bedrohung durch die Frostmane-Trolle im Coldridgetal zu untersuchen und einzudämmen. Da das zwergische Militär andernorts durch den Kampf gegen die Trogg-Plage gebunden ist, muss sich Grelin auf unabhängige Freiwillige verlassen.",al={"warum ist grelin hier","grelin weißbart aufgabe","wer ist grelin weißbart"}},{q="Wer hat Grelins Tagebuch gestohlen?",a="Ein Frostmane-Troll namens Grik'nir the Cold überfiel Grelins Lager, als es unbeaufsichtigt war. Grelin erhaschte nur einen flüchtigen Blick auf einen schwer gezeichneten Hünen, der mit seinen Feldnotizen in die südlichen Trollhöhlen floh.",al={"wer hat das tagebuch gestohlen","dieb des gestohlenen tagebuchs","grelin tagebuch"}},{q="Wer ist Grelins Bruder?",a="Sein Bruder ist Senir Weißbart, ein Agent, der weiter unten am Berg in der Ortschaft Kharanos stationiert ist. Grelin fasst seine Erkenntnisse über die Truppenbewegungen der Trolle in Berichten zusammen und schickt vertrauenswürdige Boten, um sie direkt an Senir zu überbringen.",al={"grelin bruder","senir weißbart","wer ist senir"}},{q="Wer ist bei Grelin in seinem Lager?",a="Grelin teilt sein kleines Lager mit einem zerstreuten Zwergenlehrling, weshalb er kaum kompetente Unterstützung hat, bis fähige Rekruten eintreffen.",al={"whitebeard lager npcs","wer ist bei grelin","grelin begleiter"}},{q="Warum schickt Eisenschmiede keine regulären Soldaten, um ihm zu helfen?",a="Eisenschmiedes Verteidiger und die Truppen des Senats sind fast vollständig durch die weit verbreiteten Trogg-Plagen gebunden, die in ganz Dun Morogh ausgebrochen sind. Aus diesem Grund müssen Späher wie Grelin regionale Bedrohungen mithilfe einheimischer Rekruten bewältigen.",al={"warum keine zwergenarmee","wo ist die wache von eisenschmiede","warum keine soldaten"}},{q="Welche Verbindung besteht zwischen Grelin und Jona Ironstock?",a="Jona Ironstock ist ein alter und vertrauter Freund von Grelin. In der Nähe des Startgebiets im Coldridgetal stationiert, weist Jona neuen Zwergen- und Gnom-Rekruten den Weg zu Grelins Lager.",al={"grelin und jona","jona ironstock"}}},fx={bc052fbe={q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein Ermittler, der im Auftrag des Senats von Eisenschmiede und König Magni Bronzebeard in Das Coldridgetal geschickt wurde. Er ist damit beauftragt, die aggressiven Bewegungen der Frostmähneneistrolle zu beurteilen, und unterhält ein abgelegenes Lager im verschneiten Tal, wobei er sich auf frische Rekruten der Gebirgswache verlässt, um die Trolle zurückzudrängen, während die zwergische Hauptarmee anderswo beschäftigt ist.",al={"wer ist grelin","lore grelin weißbart","wer ist weißbart"}},d217c46a={q="Auf wessen Seite steht Grelin Weißbart?",a="Grelin ist dem Königreich Eisenschmiede und der Großen Allianz vollkommen loyal. Er berichtet direkt an den Senat von Eisenschmiede und führt Depeschen bei sich, die von König Magni selbst unterzeichnet wurden, und arbeitet unermüdlich daran, die zwergischen Lande gegen äußere Bedrohungen zu sichern.",al={"fraktion grelin weißbart","für wen arbeitet grelin","ist grelin allianz"}},["6d2fc414"]={q="Was will Grelin Weißbart?",a="Grelin möchte eine schnelle Lösung für das Problem mit den Frostmähneneistrollen im südlichen Coldridgetal. Da die zwergische Wache durch die Bekämpfung von Trogg-Einfällen gebunden ist, benötigt er fähige Abenteurer, die die aggressiven Trolle ausdünnen, sein gestohlenes Tagebuch vom Trollanführer Grik'nir zurückholen und seinen fertigen Aufklärungsbericht an seinen Bruder in Kharanos übermitteln.",al={"was versucht grelin zu tun","ziel grelin weißbart","was benötigt grelin"}}},fp="17,309,15.563.0,20.567.0,46.284.0,27.207.0,24.228.0,31.146.0,56.221.0,46.184.0"}
P.entries["npc:greta-mosshoof"] = {n="Greta Mooshuf",s="Greta Mooshuf ist eine Taurendruidin, die mit dem Smaragdkreis im Smaragdrefugium im südlichen Teufelswald verbündet ist. Seite an Seite mit Nachtelfen und anderen Hütern der Natur untersucht sie das üble Verderben, das durch den uralten Wald kriecht, und schickt Späher in die Festung des Schattenrats in Jaedenar.",h="Greta Mooshuf ist eine Taurendruidin, die mit dem Smaragdkreis im Smaragdrefugium im südlichen Teufelswald...",kw={"verderbtes wasser","smaragdkreis","das smaragdrefugium","teufelswald","greta mooshuf","islen wasserdeuter","jaedenar"},ang={["class:Druid"]="Für Druiden, die daran arbeiten, die Narben der Brennenden Legion zu tilgen, verkörpert Greta Mooshuf den Geist der Zusammenarbeit des Zirkels des Cenarius, der fraktionelle Bindungen beiseiteschiebt, um die Wildnis von Kalimdor wiederherzustellen.",["race:Tauren"]="Greta zeigt die Hingabe der Tauren an die Heilung der Wunden der Erdenmutter – selbst weit im Norden in Landen, die einst allein von den Nachtelfen bewacht wurden."},sec={{t="Hüterin des Waldes",b="Im Smaragdrefugium an der südlichen Grenze des Teufelswalds stationiert, arbeitet Greta Mooshuf an der Seite des Smaragdkreises, um die um sich greifende Verderbnis zu bekämpfen, die die uralten Wälder verzehrt. Anstatt die verheerten Lande dem dämonischen Verderben zu überlassen, das im Gefolge des Dritten Krieges zurückblieb, koordiniert sie die Bemühungen, die sich ausbreitende Fäulnis zu verstehen und zurückzudrängen. Ihre Untersuchungen konzentrieren sich auf die vergifteten Gewässer des Teufelswalds und die üblen Kultisten, die sich in Jaedenar eingenistet haben."},{t="Gegen den Schattenrat zuschlagen",b="Greta Mooshuf ist maßgeblich daran beteiligt, die Machenschaften des Schattenrats aufzudecken, der aus den Tiefen von Jaedenar operiert. Da sie erkennt, dass die verderbten Quellen und üblen Schutzsiegel in der Schlucht die Krankheit, die das Land erstickt, direkt nähren, gewinnt sie Reisende dafür, Proben der verunreinigten Gewässer zu nehmen, den Beistand von Schamanen wie Islen Wasserdeuter an der fernen Küste zu suchen und die rituellen Kohlenbecken zu zerstören, die die dämonische Kabale vor Eindringlingen schützen."}},faq={{q="Wer ist Greta Mooshuf?",a="Greta Mooshuf ist ein Tauren-Mitglied des Smaragdkreises, das im Smaragdrefugium im Teufelswald stationiert ist. Sie hilft Reisenden und Druiden dabei, die dämonische Plage, die den Wald vergiftet, zu untersuchen und rückgängig zu machen.",al={"greta mooshuf lore","wer ist greta mooshuf","greta teufelswald"}},{q="Zu welcher Fraktion gehört Greta Mooshuf?",a="Greta Mooshuf ist ein Mitglied des Smaragdkreises, einer neutralen Organisation, die sich der Heilung der Natur widmet. Als solche bietet sie sowohl Abenteurern der Allianz als auch der Horde Führung und Quests an.",al={"ist greta mooshuf horde oder allianz","greta mooshuf ruf","greta fraktion"}},{q="Warum schickt Greta Abenteurer nach Jaedenar?",a="Jaedenar ist die Festung des Schattenrats im Teufelswald, der dafür verantwortlich ist, dämonische Galle in die Gewässer des Landes zu pumpen und Schutzsiegel aufrechtzuerhalten, die Dämonen Unterschlupf gewähren. Greta leitet Angriffe gegen Jaedenar, um deren Rituale zu zerschlagen und die verseuchten Quellen zu reinigen.",al={"warum jaedenar quest","greta mooshuf jaedenar","kräfte von jaedenar grund"}},{q="Welche Verbindung besteht zwischen Greta Mooshuf und Islen Wasserdeuter?",a="Greta ist mit Islen Wasserdeuter befreundet, einer weisen Schamanin, die an der Küste des Brachlands lebt. Als Greta verderbte Wasserproben aus dem Teufelswald entdeckt, weist sie Abenteurer an, Islens spirituelle Meisterschaft zu erbitten, um die Flüssigkeit zu läutern, damit sie die vergifteten Quellen reinigen kann.",al={"greta und islen","islen wasserdeuter verbindung"}}},fp="14,297,22.465.0,30.441.1,22.202.0,43.181.0,47.265.0,55.268.0"}
P.entries["npc:grif-wildheart"] = {n="Grif Wildherz",s="Grif Wildherz ist ein erfahrener Zwergen-Jägerlehrer, der vor der Brauerei Donnerbräu in Kharanos stationiert ist. Unter den einheimischen Gebirgsjägern ist er für seine tiefe Verbundenheit zur Tierwelt bekannt und unterweist angehende Scharfschützen im Fährtenlesen, der Treffsicherheit sowie den Riten der Tierzähmung. Für junge Jäger, die aus dem Coldridgetal hervorgehen, bildet Grif das entscheidende Bindeglied zwischen dem Abfeuern einer Flinte und dem gemeinsamen Beschreiten von Pfaden mit einem treuen tierischen Gefährten.",h="Grif Wildherz ist ein erfahrener Zwergen-Jägerlehrer, der vor der Brauerei Donnerbräu in Kharanos stationiert...",kw={"tierzähmung","dun morogh","grif wildherz","jägerlehrer","kharanos","gebirgsjäger","die zähmung der bestie","brauerei donnerbräu"},ang={["class:Hunter"]="Grif ist der unverzichtbare Lehrmeister, der Allianzjäger in die Tierzähmung einführt und Euch die entscheidenden Quests anbietet, um mit wilden Raubtieren in ganz Dun Morogh ein Band zu knüpfen.",["faction:Alliance"]="In Kharanos stationiert, bereitet Grif die Späher und Scharfschützen der Allianz darauf vor, in der rauen Wildnis rund um das Bergkönigreich Eisenschmiede zu überleben.",["race:Dwarf"]="Als Verkörperung der zwergischen Gebirgsjägertradition beweist Grif, wie die robuste Widerstandskraft eines Zwerges ihn hervorragend dazu befähigt, Seite an Seite mit wilden Bergtieren zu leben."},sec={{t="Ein Leben in der Wildnis",b="Während viele Zwerge aus Eisenschmiede die feurige Wärme einer Schmiede oder das stetige Klingen von Spitzhacken bevorzugen, hat Grif Wildherz sein Leben ganz der eisigen Wildnis von Dun Morogh gewidmet. Einheimische Gebirgsjäger sagen halb im Scherz, dass er ein bisschen zu viel Zeit mit vierbeinigen Biestern verbringt, doch niemand zweifelt an seiner Meisterschaft über die Natur. Nachdem er jahrelang an der Seite erfahrener Jagdgefährten schneebedeckte Kämme durchstreift hat, besitzt Grif ein tiefes Verständnis für die natürlichen Raubtiere, die die Felsen durchstreifen."},{t="Der Weg der Bestie",b="Sobald junge Zwergenjäger ihre einführenden Prüfungen im Coldridgetal beendet haben, werden sie direkt nach Kharanos geschickt, um Grifs Rat zu suchen. Während er ihr Zielfernrohr schärft und ihnen grundlegende Überlebenstricks für die Wildnis beibringt, liegt seine wahre Spezialität darin, Bande zwischen Jäger und Bestie zu schmieden. In einer Reihe anspruchsvoller Prüfungen schickt Grif seine Schüler mit einer Zähmerrute in das eisige Ödland, um ihren Mut an den ikonischen Raubtieren Dun Moroghs zu erproben: Große Klippeneber, Schneeleoparden und Eiskrallenbären."},{t="Reise zum High Seat",b="Sobald ein Jäger den Willen und die Gelassenheit bewiesen hat, drei verschiedene wilde Bestien zu beruhigen, findet Grifs Unterweisung in Kharanos ihren Abschluss. Da er weiß, dass ein Jäger auch lernen muss, seinen neuen Verbündeten zu füttern, zu disziplinieren und auszubilden, schickt er seine Zöglinge den Berghang hinauf nach Eisenschmiede. Dort, unter den gewaltigen Gewölben der Zwergenhauptstadt, melden sich die Jägernovizen bei Meistern der Tierausbildung, um die tiefere Kunst der Fürsorge für ihren ständigen Lebensgefährten zu erlernen."}},faq={{q="Wer ist Grif Wildherz?",a="Grif Wildherz ist ein Zwergen-Jägerlehrer in Kharanos in Dun Morogh. Er dient als wichtigster Lehrmeister für unerfahrene Jäger der Allianz, die ihr Handwerk außerhalb des Coldridgetals erlernen.",al={"wer ist grif","grif wildherz identität","über grif"}},{q="Wo kann ich Grif Wildherz finden?",a="Er steht draußen nahe der Brauerei Donnerbräu im Dorf Kharanos, entlang der verschneiten Straße, die die Eisklamm mit Eisenschmiede verbindet.",al={"grif wildherz aufenthaltsort","wo ist grif","grif in kharanos"}},{q="Was bringt Grif angehenden Jägern bei?",a="Neben allgemeinen Jägerfertigkeiten und Fernkampftechniken leitet Grif junge Jäger durch die Prüfungen der Tierzähmung und lehrt sie, wilde Eber, Leoparden und Bären zu besänftigen und zu meistern.",al={"was lehrt grif","grif jägerausbildung","grif fähigkeiten"}},{q="Welche Bestien lässt Grif die Jäger zähmen?",a="Grif beauftragt seine Schüler damit, drei bestimmte Kreaturen aus Dun Morogh aufzuspüren und zu zähmen: einen Großen Klippeneber, einen Schneeleoparden und einen Eiskrallenbären.",al={"grif zähmungsquests","welche tiere zähmen dun morogh","die zähmung der bestie ziele"}},{q="Wohin schickt Grif die Jäger nach Abschluss ihrer Zähmungsprüfungen?",a="Nachdem sie ihre Fähigkeit bewiesen haben, wilde Tiere zu zähmen, weist Grif die Jäger an, in die Stadt Eisenschmiede zu reisen, um sich bei fortgeschrittenen Tierausbildern über das Füttern und Befehligen ihrer Begleiter zu informieren.",al={"wohin nach grif","die ausbildung des tiers nächster schritt","grif folgequest"}},{q="Was denken die Gebirgsjäger von Eisenschmiede über Grif?",a="Die einheimischen Gebirgsjäger von Eisenschmiede merken an, dass Grif etwas zu viel Zeit in der Gesellschaft von Tieren statt von Menschen verbringt, geben jedoch gerne zu, dass er das Handwerk des Jägers besser versteht als fast jeder andere.",al={"gebirgsjäger meinung über grif","ist grif respektiert","grif ruf"}}},fx={["5a030de6"]={q="Auf wessen Seite steht Grif Wildherz?",a="Grif Wildherz ist fest loyal gegenüber Eisenschmiede und der Großen Allianz. Er dient seinem Volk, indem er junge zwergische Jäger in Kharanos ausbildet und sicherstellt, dass sie die Disziplin und die Überlebensfähigkeiten besitzen, die nötig sind, um das Bergkönigreich und seine Gebiete zu schützen.",al={"fraktion grif wildherz","ist grif allianz","loyalität grif wildherz"}},a3b5e7f5={q="Was will Grif Wildherz?",a="Grif widmet sich der Weitergabe des Handwerks der Wildnis. Er möchte, dass aufstrebende Jäger das Zähmen von Wildtieren und das Überleben in der Wildnis meistern, und schickt Novizen in den Schnee von Dun Morogh, damit sie Respekt, Geduld und den Aufbau lebenslanger Bindungen mit den Kreaturen der zerklüfteten Berge lernen.",al={"ziel grif wildherz","was will grif","motiv grif wildherz"}},["20183458"]={q="Warum ist Grif Wildherz in Kharanos?",a="Grif ist in Kharanos stationiert, um frische Rekruten auszubilden, die aus dem Coldridgetal herabsteigen. Als zentraler Knotenpunkt in Dun Morogh ist Kharanos der ideale Prüfstand für junge Jäger, die bereit sind, ihren Verstand gegen die Eber, Leoparden und Bären des Berges zu testen.",al={"warum ist grif hier","warum ist grif in dun morogh","warum ist grif in kharanos"}}},fp="14,424,19.495.0,20.507.0,24.472.0,22.187.0,32.138.0,36.200.0,43.152.0,66.188.0,49.198.0"}
P.entries["npc:grimbooze-thunderbrew"] = {n="Schnapsbart Donnerbräu",s="Schnapsbart Donnerbräu ist ein exzentrischer zwergischer Brauer des Donnerbräu-Clans, der in den Dolchhügeln von Westfall kampiert. Er verbringt seine Tage damit, hochprozentige Spirituosen zu brauen und fast ausschließlich in Versform zu sprechen.",h="Schnapsbart Donnerbräu ist ein exzentrischer zwergischer Brauer des Donnerbräu-Clans, der in den Dolchhügeln...",kw={"bier","brauer","die dolchhügel","brauerei","grimbooze","kharanos","donnerbräu","westfall"},ang={["profession:Cooking"]="Kulinarische Abenteurer und Spirituosenhandwerker verehren das Vermächtnis der Donnerbräus, was eine Begegnung mit Grimbooze zu einer Lektion in handwerklicher Braukunst macht.",["race:Dwarf"]="Jeder Zwerg kennt den Namen Donnerbräu, und einen ihrer wichtigsten Ältesten dabei zu finden, wie er wilde Rezepte in den Hügeln von Westfall braut, ist ein willkommener Vorgeschmack auf Dun Morogh."},sec={{t="Ein Brauer im Exil",b="Stammend aus der berühmten Donnerbräu-Brauerfamilie aus Kharanos, verließ Grimbooze die schneebedeckten Berggipfel von Dun Morogh für die windgepeitschten Hügel von Westfall. Bekannt für sein fröhliches Gemüt und eine unnachgiebige Leidenschaft für hochprozentige Spirituosen, hat er die eigenartige Angewohnheit, nur in Reimen zu sprechen, und er beantwortet die Fragen eines Reisenden erst, wenn diese eine einfache Aufgabe für ihn erledigt haben. Reisende, die durch die gefährlichen Dolchhügel ziehen, können ihn dabei antreffen, wie er seine privaten Fässer pflegt, stets begierig darauf, den Gaumen eines durstigen Reisenden auf die Probe zu stellen."}},faq={{q="Wo finde ich Schnapsbart Donnerbräu?",a="Schnapsbart Donnerbräu ist in den Dolchhügeln im südlichen Westfall stationiert, wo er inmitten der Hügel mit seiner Brauausrüstung kampiert.",al={"grimbooze standort","wo ist grimbooze","wo findet man grimbooze donnerbräu"}},{q="Warum spricht Grimbooze in Reimen?",a="Niemand kann das mit Sicherheit sagen. Grimbooze hat einfach Freude an Versen und beharrt darauf, dass jeder, der eine Frage an ihn hat, zuerst eine einfache Aufgabe erledigen muss.",al={"warum reimt grimbooze","grimbooze reimt","warum spricht er in versen"}},{q="Was ist seine Verbindung zur Brauerei Donnerbräu?",a="Grimbooze ist ein Mitglied des berühmten Donnerbräu-Clans aus Kharanos in Dun Morogh. Während Verwandte wie Ragnar Donnerbräu zu Hause die Brauerei der Familie pflegen, braut Grimbooze auf eigene Faust in den Hügeln von Westfall.",al={"grimbooze brauerei","ist grimbooze mit ragnar verwandt","donnerbräu familie"}}},fx={["21ebedd0"]={q="Wer ist Schnapsbart Donnerbräu?",a="Schnapsbart ist ein schrulliger, fröhlicher Zwergenbrauer aus dem berühmten Donnerbräu-Clan von Dun Morogh. Bekannt für seine legendäre Liebe zum Bier und seine Neigung, in Rätseln und Versen zu sprechen, verließ er das Zuhause seiner Familie in Kharanos, um in den Hügeln von Westfall sein eigenes Bier zu brauen.",al={"wer ist schnapsbart","schnapsbart donnerbräu","über schnapsbart"}},["182004c2"]={q="Auf wessen Seite steht Schnapsbart Donnerbräu?",a="Schnapsbart ist, wie der Rest des Donnerbräu-Clans, Eisenschmiede und der Allianz treu ergeben. Seine wahre Leidenschaft gilt jedoch eher dem Brauen und guten Getränken als der Politik oder dem Fraktionskrieg, was ihn zu einem freundlichen Gesicht für jeden macht, der ein gutes Bier zu schätzen weiß.",al={"fraktion schnapsbart","ist schnapsbart allianz","seite schnapsbart"}},["9bf66a40"]={q="Was will Schnapsbart Donnerbräu?",a="Schnapsbart ist immer auf der Suche danach, seine Spezialbiere zu brauen und sie mit Mitreisenden zu teilen. Im Austausch für Zutaten oder ein wenig Hilfe bietet er Euch nur allzu gerne Proben des starken Donnerbräu-Lagers an, um Eure Stimmung hochzuhalten.",al={"was will schnapsbart","ziel schnapsbart","warum braucht schnapsbart hopfen"}},d50f3d5e={q="Warum ist Schnapsbart Donnerbräu in Westfall?",a="Schnapsbart hat die kalten Gipfel von Dun Morogh hinter sich gelassen und ist in Die Dolchhügel gezogen, wo er nun seine Tage damit verbringt, weit weg von der familiären Brennerei in Kharanos zu brauen und in Versen zu philosophieren.",al={"warum ist schnapsbart in westfall","schnapsbart westfall grund","was macht schnapsbart in westfall"}}},fp="21,205,17.528.0,39.144.0,36.149.0,53.204.0"}
P.entries["npc:grish-longrunner"] = {n="Grish Fernläufer",s="Grish Fernläufer ist ein Späher und Bote der Tauren, der in der Nähe des Großen Aufzugs stationiert ist – dem lebenswichtigen mechanischen Übergang, der das Südliche Brachland mit den Canyons von Tausend Nadeln verbindet. Im Dienste der Horde an dieser belebten Grenze behält er Reisende im Auge und koordiniert militärische Bewegungen entlang der Front.",h="Grish Fernläufer ist ein Späher und Bote der Tauren, der in der Nähe des Großen Aufzugs stationiert ist – dem...",kw={"brachland","hinzurufen der reserve","der große aufzug","grish","longrunner","tauren","tausend nadeln"},ang={["faction:Horde"]="Für Kuriere und Krieger der Horde, die nach Süden in Richtung Tausend Nadeln reisen oder nach Norden ins Brachland zurückkehren, dient Grish als wichtiger Ausguck und Kontaktpunkt am Aufzug.",["race:Tauren"]="Mit dem stolzen Namen Longrunner verkörpert Grish die Ausdauer und Wachsamkeit der Shu'halo, während sie lebenswichtige Pfade durch ihre angestammten Heimatländer sichern."},sec={{t="Wächter am Aufzug",b="Direkt neben den hoch aufragenden Maschinen des Großen Aufzugs hält Grish Fernläufer Wache an einem der heikelsten Grenzübergänge Zentral-Kalimdors. Der Plattformaufzug ist eine Lebensader, die das karge Südliche Brachland mit den windgepeitschten Hochebenen von Tausend Nadeln darunter verbindet. Zwischen umherstreifenden Stacheleber-Rudeln und konkurrierenden Bedrohungen im Umland ist das Reisen entlang dieser vertikalen Grenze gefährlich. Daher sind Späher wie Grish unerlässlich, um die Horde auf dem Laufenden zu halten und Verstärkung dorthin zu rufen, wo sie dringend gebraucht wird."}},faq={{q="Wer ist Grish Fernläufer?",a="Grish Fernläufer ist ein mit der Horde verbündeter Taurenspäher, der am Rand des Großen Aufzugs stationiert ist, welcher vom Brachland hinab nach Tausend Nadeln führt.",al={"wer ist grish","grish fernläufer identität","was macht grish"}},{q="Wo finde ich Grish Fernläufer?",a="Er befindet sich in den südlichen Weiten des Brachlands, direkt am mechanischen Eingang des Großen Aufzugs, der hinunter nach Tausend Nadeln führt.",al={"grish fernläufer standort","wo ist grish","grish finden"}},{q="Welche Rolle spielt er in diesem Gebiet?",a="Grish dient als Ansprechpartner für Boten und Reisende der Horde und hilft vor allem dabei, örtliche Verstärkungen durch Aufträge wie „Hinzurufen der Reserve“ zu sammeln und zu leiten.",al={"grish zweck","grish quests","hinzurufen der reserve grish"}}},fx={["0053ed11"]={q="Auf wessen Seite steht Grish Fernläufer?",a="Grish ist ein stolzes Mitglied der Taurenstämme und loyal zur Horde. Er operiert an den Grenzen zum Brachland und dem Abstieg nach Tausend Nadeln und dient als Kontaktperson für Reisende der Horde, die die gefährlichen Passagen zwischen den Regionen navigieren.",al={"fraktion grish fernläufer","ist grish horde","loyalität grish fernläufer"}}},fp="16,329,19.537.0,24.164.0,34.140.0,35.180.0"}
P.entries["npc:grub"] = {n="Grub",s="Grub ist ein geschäftstüchtiger Ork, der in einer Hütte am Wegesrand östlich des Wegekreuzes im Brachland lebt. Zusammen mit einem Koch und einem Bäcker betreibt er ein bescheidenes Grenzgasthaus und ist berühmt – oder vielleicht berüchtigt – dafür, Reisenden den kulinarischen Nutzen des einheimischen Ungeziefers näherzubringen.",h="Grub ist ein geschäftstüchtiger Ork, der in einer Hütte am Wegesrand östlich des Wegekreuzes im Brachland...",kw={"brachland","das wegekreuz","grubenratteneintopf","duhng","grub","tarban hearthgrain"},ang={["faction:Horde"]="Direkt vor den Toren des Wegekreuzes gelegen, bietet Grubs Küche am Wegesrand herzhafte Stärkung und eine Lektion in Einfallsreichtum für Reisende der Horde, die in den rauen Ebenen überleben wollen.",["profession:Cooking"]="Grub ist eine unverzichtbare Anlaufstelle für angehende Grenzköche und bereit, das Rezept für Grubenratteneintopf mit jedem zu teilen, der mutig genug ist, die Zutaten zu sammeln."},sec={{t="Appetit an der Grenze",b="Eingebettet an den Felsen östlich des Wegekreuzes wacht Grub über eine rustikale Behausung, die er mit Duhng, seinem Koch, und Tarban Hearthgrain, einem Bäcker, teilt. Während das Leben in den Ebenen einen robusten Magen erfordert, treibt Grub die Selbstversorgung an der Grenze auf die Spitze. Anstatt die reichlich vorhandenen Grubenratten des Brachlands verkommen zu lassen, hat er sie zu einer Hauptzutat gemacht und bietet vorbeiziehenden Wanderern an, ihnen beizubringen, wie man die unterirdischen Nager zu einem herzhaften, wenn auch wenig glamourösen Eintopf verkocht."}},faq={{q="Wer ist Grub?",a="Grub ist ein Ork, der in einer Hütte östlich des Wegekreuzes im Brachland wohnt. Er betreibt zusammen mit seinem Koch Duhng und einem Bäcker namens Tarban Hearthgrain ein kleines Etablissement und verköstigt Reisende, die durch das staubige Grenzland ziehen.",al={"grub","wer ist grub","ork östlich von das wegekreuz"}},{q="Wo finde ich Grub?",a="Grub ist östlich des Wegekreuzes am Fuße der Berge im Brachland zu finden, gelegen in einer kleinen Behausung abseits des Hauptweges.",al={"grub aufenthaltsort","wo ist grub","grubs hütte"}},{q="Wobei benötigt Grub Hilfe?",a="Grub beauftragt Reisende damit, Grubenratten aus dem Brachland zu sammeln, die für die Zubereitung seines unverkennbaren Grubenratteneintopfs verwendet werden. Im Gegenzug teilt er das Rezept mit Köchen, die bereit sind, es zuzubereiten.",al={"grub quest","grubenratteneintopf quest"}}},fx={["1dd1f89b"]={q="Auf wessen Seite steht Grub?",a="Grub ist ein Orc, der mit der Horde verbündet ist und friedlich direkt außerhalb vom Das Wegekreuz im Brachland arbeitet. Er heißt Reisende der Horde in seinem kleinen Gehöft willkommen und treibt Geschäfte mit anderen Köchen, Bäckern und vorbeiziehenden Abenteurern, ohne sich in militärische Konflikte verstricken zu lassen.",al={"fraktion grub","ist grub horde","grub allianz oder horde"}},bef281f8={q="Warum ist Grub hier?",a="Grub hat östlich vom Das Wegekreuz am Fuße der Berge eine kleine häusliche Siedlung errichtet. Anstatt an der Front zu dienen, betreibt er eine kulinarische Wohnstätte zusammen mit seinem Koch Duhng und dem Bäcker Tarban Hearthgrain, wo sie lokale Grenzspeisen beschaffen und zubereiten.",al={"warum ist grub im brachland","grub hütte wegkreuz","was macht grub hier"}},c7807b4d={q="Mit wem ist Grub verbunden?",a="Grub teilt seine Hütte am Wegesrand mit Duhng, der für das Kochen zuständig ist, und Tarban Hearthgrain, der sich um das Backen kümmert. Zusammen führt diese ungewöhnliche Ansammlung von Gefährten ihre kleine Feuerstelle in den rauen Ebenen des Brachlands.",al={"mit wem arbeitet grub","grub gefährten","grub kontakte"}}},fp="4,263,19.477.0,12.229.0,22.144.0,30.181.0"}
P.entries["npc:grull-hawkwind"] = {n="Grull Falkenwind",s="Grull Falkenwind ist ein junger Krieger der Tauren, der im Camp Narache auf der Hochwolkenebene in Mulgore stationiert ist. Als Sohn von Häuptling Falkenwind hilft er dabei, unerfahrene Tauren anzuleiten, die ihre allerersten Schritte in die Welt wagen. Er führt junge Jäger und Krieger durch ihre ersten Prüfungen, um ihre Entschlossenheit auf die Probe zu stellen und ihre Vorfahren zu ehren.",h="Grull Falkenwind ist ein junger Krieger der Tauren, der im Camp Narache auf der Hochwolkenebene in Mulgore...",kw={"camp narache","häuptling falkenwind","grull falkenwind","mulgore","die hochwolkenebene","ritus der kraft","tauren"},ang={["class:Hunter"]="Grull versorgt angehende Jäger mit grundlegenden ersten Aufgaben und stellt ihre Geduld sowie ihr Können im Kampf gegen die Fauna von Mulgore auf die Probe.",["race:Tauren"]="Für junge Tauren, die die Hochwolkenebene betreten, ist Grull Falkenwind oft der allererste Krieger, der ihren Mut auf die Probe stellt und sie in die Traditionen der Shu'halo einführt."},sec={{t="Der Sohn eines Häuptlings",b="Stolz an der Seite der Krieger und Ältesten von Camp Narache stehend, trägt Grull Falkenwind sowohl die stolze Abstammung von Häuptling Falkenwind als auch die Verantwortung, die Jugend des Stammes vorzubereiten. Er dient den Neuankömmlingen auf der Hochwolkenebene als erster Mentor und beurteilt deren Bereitschaft, den Shu'halo zu dienen. Indem er Prüfungen auferlegt, die Ausdauer, Fährtenlesen und das Überleben gegen einheimische Bestien wie Ebenenschreiter und Berggorillas testen, stellt Grull sicher, dass junge Tauren begreifen, dass Gleichgewicht und Respekt vor der Natur das Fundament des Lebens in Mulgore bilden."}},faq={{q="Wer ist Grull Falkenwind?",a="Grull Falkenwind ist ein Questgeber der Tauren, der im Camp Narache auf der Hochwolkenebene weilt. Er ist der Sohn von Häuptling Falkenwind, dem Anführer der Siedlung, und fungiert als einer der wichtigsten Mentoren für junge Tauren, die ihre Reise beginnen.",al={"grull falkenwind rolle","wer ist grull","grull falkenwind lore"}},{q="Welche Rolle spielt Grull Falkenwind für junge Abenteurer?",a="Grull beurteilt die Grundausbildung unerfahrener Tauren, nimmt einführende Schriftstücke von den Stammesältesten entgegen und betraut die Jugend mit ihren ersten Prüfungen der Jagd und des Überlebens in den umliegenden Ebenen.",al={"grull quests","was macht grull","grull falkenwind zweck"}},{q="Ist Grull mit der Führung des Lagers verwandt?",a="Ja, Grull ist der Sohn von Häuptling Falkenwind, dem Häuptling von Camp Narache. Er wahrt die Traditionen seines Vaters und hilft dabei, die Verteidiger des Lagers vorzubereiten.",al={"häuptling hawkwinds sohn","grull falkenwind familie","ist grull mit dem häuptling verwandt"}}},fx={["36d17655"]={q="Auf wessen Seite steht Grull Falkenwind?",a="Grull Falkenwind steht stolz an der Seite der Taurenstämme und der Horde. Er lebt im Camp Narache und dient seinem Volk unter der Führung seines Vaters und des Hochhäuptlings Cairne Bluthuf, wobei er sich der Aufgabe widmet, jungen Tauren dabei zu helfen, zu fähigen Verteidigern ihrer angestammten Heimat in Mulgore heranzuwachsen.",al={"grull falkenwind fraktion","wem dient grull","grull falkenwind loyalität"}},["56962b2d"]={q="Was will Grull Falkenwind?",a="Grull möchte sehen, wie junge Tauren ihre Stärke und ihre Hingabe zum Stamm beweisen. Er prüft die ankommenden Jugendlichen, um sicherzustellen, dass sie über die nötige Standhaftigkeit, Disziplin und die Jagdfähigkeiten verfügen, um in der Wildnis zu überleben und das Camp Narache vor Bedrohungen aus der Nähe zu schützen.",al={"was will grull","grull falkenwind ziele","warum gibt grull quests"}},["379dd378"]={q="Warum ist Grull Falkenwind hier im Camp Narache?",a="Camp Narache ist der angestammte Prüfungsort für die Jugend, die auf der Hochwolkenebene erwachsen wird, und wird von Grulls Vater, Häuptling Falkenwind, geleitet. Grull bleibt hier, um neue Initianden bei ihren ersten Riten zu unterstützen und die Führung seiner Familie über das Lager zu stützen.",al={"warum ist grull hier","grull rolle im camp narache","warum ist grull auf der hochwolkenebene"}}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:grunt-dogran"] = {n="Grunzer Dogran",s="Grunzer Dogran ist ein Orcsoldat der Horde, der tief im Gebiet der Stacheleber des südlichen Brachlands gefangen gehalten wird. Ursprünglich dem Wegekreuz und später Camp Taurajo zugewiesen, ereilte seine Patrouille während eines Überfalls auf Agama'gor ein verhängnisvolles Schicksal.",h="Grunzer Dogran ist ein Orcsoldat der Horde, der tief im Gebiet der Stacheleber des südlichen Brachlands...",kw={"agama'gor","brachland","camp taurajo","das wegekreuz","dogran","dorgran","grunzer dogran","stacheleber"},ang={["faction:Horde"]="Seine Gefangennahme verdeutlicht den hohen Preis, den die Garnisonen der Horde zahlen, um die Handelswege und Grenzen im Brachland gegen aggressive Stacheleberstämme zu sichern.",["race:Orc"]="Dogran verkörpert das traditionelle Ideal der Orcs, dass ein Tod im Kampf mehr Ehre birgt, als ein Überleben als hilfloser Invalide."},sec={{t="Die Pflicht eines Grunzers",b="Nach seiner Beförderung innerhalb des Militärs der Horde wurde Grunzer Dogran vom Wegekreuz entsandt, um Camp Taurajo zu verstärken. Als er eine Abteilung von Grunzer in das dornige Territorium von Agama'gor anführte, stieß seine Einheit heftig mit den Borstennackenstachelebern zusammen. Während des Gefechts schwer verletzt und verkrüppelt, konnte Dogran von seinen sich zurückziehenden Kameraden nicht mitgenommen werden und wurde in die Gefangenschaft verschleppt."},{t="Ein ehrenvolles Schicksal",b="Obwohl er hinter den feindlichen Linien gefangen und durch seine Wunden verkrüppelt ist, bewahrt Dogran den für Orc-Krieger typischen sturen Stolz. Anstatt gebrochen heimzukehren und seiner Gefährtin die Pflege eines Invaliden aufzubürden, entschied er sich für ein letztes Gefecht gegen die Stacheleber und bat lediglich darum, derjenigen, die er liebt, ein Zeichen seiner anhaltenden Hingabe zu überbringen."}},faq={{q="Wo befindet sich Grunzer Dogran?",a="Dogran wird in Agama'gor gefangen gehalten, einem dichten Stacheleberlager im südlichen Brachland, direkt nördlich von Camp Taurajo.",al={"dogran standort","wo ist dogran","dogran finden brachland"}},{q="Warum wurde Dogran von den Stachelebern gefangen genommen?",a="Als er eine Patrouille von Camp Taurajo anführte, um die Stacheleber anzugreifen, erlitt Dogran während des Zusammenstoßes verkrüppelnde Verletzungen. Seine Kameraden konnten ihn nicht rechtzeitig fortschaffen, sodass er den Bestien ausgeliefert war.",al={"warum wurde dogran gefangen genommen","wie wurde dogran gefasst"}},{q="Warum weigert sich Dogran, gerettet zu werden?",a="Dogran wurde im Kampf dauerhaft verkrüppelt und weigert sich, seiner Gefährtin zu Hause zur Last zu fallen. Nach echter Orc-Art zieht er es vor, im Kampf gegen die Stacheleber zu seinen eigenen Bedingungen zu sterben, anstatt seine Tage als Invalide zu fristen.",al={"warum will dogran nicht fliehen","dogran rettung"}},{q="Wer sucht nach Dogran?",a="Die Sorge über sein Verschwinden geht auf das Wegekreuz und Camp Taurajo zurück, wo Späher und Soldaten das Schicksal seiner vermissten Patrouille rekonstruieren.",al={"wer schickte mich zu dogran","dogran questgeber"}}},fx={["3efd280a"]={q="Wer ist Grunzer Dogran?",a="Grunzer Dogran ist ein Orc-Soldat der Horde. Nachdem er befördert wurde, war er im Wegekreuz stationiert, bevor er zum Camp Taurajo versetzt wurde. Während er ein Kontingent von Grunzer in das Südliche Brachland führte, um den Stachelebern entgegenzutreten, wurde er im Kampf schwer verwundet und von den borstigen Bestien gefangen genommen, die ihn nun gefesselt in ihrem Lager bei Agama'gor festhalten.",al={"wer ist dogran","identität von grunzer dogran","dogran hintergrund"}},a7e18655={q="Auf wessen Seite steht Grunzer Dogran?",a="Dogran ist ein loyaler Soldat der Horde. Er dient stolz als Grunzer unter dem Kommando des Kriegshäuptlings und ist im Brachland stationiert, um Außenposten und Siedlungen der Horde vor feindlichen Kräften wie den Stachelebern der Klingenhauer und Borstennacken zu verteidigen.",al={"ist dogran horde","dogran loyalität","dogran fraktion"}}},fp="12,236,14.400.0,17.335.1,30.126.0,40.210.0,37.209.1,26.153.0"}
P.entries["npc:grunt-logmar"] = {n="Grunzer Logmar",s="Grunzer Logmar ist ein Orc-Krieger der Horde, der im südlichen Brachland in Camp Taurajo stationiert ist. Pflichtbewusst und wachsam behält er die Bedrohungen rund um das Lager im Auge und koordiniert die Bemühungen, vermisste Späher der Horde in der Region ausfindig zu machen und ihnen zu helfen.",h="Grunzer Logmar ist ein Orc-Krieger der Horde, der im südlichen Brachland in Camp Taurajo stationiert ist.",kw={"camp taurajo","dogran","grunzer logmar","ken'ziglas trunk","orc-grunzer","taurajo","brachland"},ang={["faction:Horde"]="Logmar verkörpert die militärische Präsenz an vorderster Front zur Unterstützung der Tauren im Brachland und verlässt sich auf die Helden der Horde, um sich um gefallene und gefangene Späher zu kümmern.",["race:Orc"]="Als weit von Orgrimmar entfernter Orc-Grunzer verdeutlicht Logmar die Entschlossenheit der Horde, Seite an Seite mit ihren Verbündeten, den Tauren, zu stehen."},sec={{t="Dienst in Camp Taurajo",b="Unter den Tauren in Camp Taurajo stationiert, dient Grunzer Logmar als wachsamer Orc-Wächter an der Grenze des südlichen Brachlands. Die Siedlung liegt nahe an feindseligen Gebieten der Borstennacken und den Gebirgspässen, die ins Steinkrallengebirge und nach Mulgore führen, was ständige Wachsamkeit erfordert. Logmar koordiniert Spähberichte und wendet sich an fähige Reisende der Horde, wenn seine Kameraden von einheimischen Feinden überfallen oder gefangen genommen werden."}},faq={{q="Wer ist Grunzer Logmar?",a="Grunzer Logmar ist ein Orc-Soldat, der in Camp Taurajo im südlichen Brachland stationiert ist. Er dient der Horde, indem er die Siedlung sichert und Rettungs- sowie Aufklärungsaufgaben überwacht.",al={"grunzer logmar","wer ist logmar","logmar brachland"}},{q="Wo ist Grunzer Logmar zu finden?",a="Er befindet sich in Camp Taurajo, einem Außenposten in den südlichen Ebenen des Brachlands an der Straße, die zum großen Aufzug und nach Tausend Nadeln führt.",al={"wo ist logmar","logmar standort","grunzer logmar finden"}},{q="Welche Angelegenheiten beaufsichtigt Logmar?",a="Logmar kümmert sich um die Sicherheit vermisster Horde-Späher. Vor allem beauftragt er Reisende damit, das Verschwinden und die Gefangennahme seines Kameraden Grunzer Dogran zu untersuchen und lebenswichtige Vorräte wie Ken'ziglas Trunk zu beschaffen.",al={"logmar quests","was will logmar","dogran rettung"}}},fx={ce116068={q="Auf wessen Seite steht Grunzer Logmar?",a="Grunzer Logmar ist ein loyaler Soldat der Horde. Er ist bei den Siedlungen der Tauren stationiert und dient dem Kriegshäuptling, indem er die südlichen Grenzen bewacht und die Operationen der Horde in den Ebenen unterstützt.",al={"ist logmar horde","grunzer logmar fraktion","grunzer logmar seite"}},["1f3f5c49"]={q="Warum ist Grunzer Logmar hier?",a="Logmar ist als Vorpostenwache stationiert, um die Verteidigung zu stärken und die militärische Kommunikation aufrechtzuerhalten. Die umliegende Wildnis stellt eine ständige Bedrohung durch feindliche Wildtiere, Zentaurenplünderer und nahe gelegene Stacheleber dar, was standhafte Soldaten erfordert, um Reisende zu schützen und das Südliche Brachland zu sichern.",al={"warum ist grunzer logmar hier","warum ist logmar in taurajo","logmar posten"}},e7dd0701={q="Was will Grunzer Logmar?",a="Logmar sucht Hilfe bei der Bewältigung dringender militärischer Notlagen in der Region, insbesondere bei der Rettung und Bergung gefangener Kameraden wie Dogran sowie bei der Beschaffung von stärkenden Tränken, die benötigt werden, um seine Mitstreiter im Feld zu versorgen.",al={"was will logmar","grunzer logmar ziel","was braucht grunzer logmar"}}},fp="12,235,20.419.0,20.174.0,32.155.0,33.201.0"}
P.entries["npc:grunth"] = {n="Grunth",s="Grunth ist ein energiegeladenes junges Orc-Waisenkind, das in der Obhut des Waisenhauses von Orgrimmar in der Gasse lebt. Während der Kinderwoche begleitet er eifrig Champions der Horde auf großen Reisen durch Kalimdor und die Östlichen Königreiche, um zu lernen, was es bedeutet, ein Held zu sein.",h="Grunth ist ein energiegeladenes junges Orc-Waisenkind, das in der Obhut des Waisenhauses von Orgrimmar in der...",kw={"kinderwoche","grunth","orc-waisenkind","orgrimmar","waisenmatrone schlachterbe","waisenpfeife","die gasse"},ang={["faction:Horde"]="Die Betreuung von Grunth während der Kinderwoche erinnert die Champions der Horde daran, was ihre Fraktion zu schützen versucht: eine heranwachsende Generation, die in Freiheit statt in dämonischer Knechtschaft geboren wurde.",["race:Orc"]="Grunth verkörpert die Jugend von Durotar, die aufwächst und Stammesere und Überleben kennt, anstatt die finstere Lethargie der Internierungslager."},sec={{t="Ein neugieriges Kind der Horde",b="Grunth lebt in der Gasse von Orgrimmar unter den wachsamen Augen von Waisenmatrone Schlachterbe und repräsentiert die nächste Generation der neu gegründeten Horde. Wie viele junge Grünhäute, die in Durotars rauen roten Einöden aufgewachsen sind, blickt er mit staunenden Augen und einem unerschöpflichen Strom von Fragen zu gerüsteten Abenteurern auf – er fragt sich, ob gerüstete Krieger wirklich furchterregend sind, warum Blitze auf dem Wasser nicht jeden Fisch töten und ob er jemals jemanden gegen einen echten Drachen kämpfen sehen wird."},{t="Reisen während der Kinderwoche",b="Wenn die Festzeit beginnt, blasen Abenteurer eine Pfeife des orcischen Waisenkindes, um Grunth herbeizurufen und ihn auf eine ausgedehnte Reise durch die Welt mitzunehmen. Seine Wunschliste erstreckt sich über das gesamte Gebiet der Horde: eine Audienz bei Oberhäuptling Cairne Bluthuf in Mulgore ersuchen, sich in den zerstörten Thronsaal von Lordaeron wagen und die rauen Grenzländer besuchen, in denen sein Volk für seine Zukunft kämpft."}},faq={{q="Wer ist Grunth?",a="Grunth ist ein Orc-Kind, das im Waisenhaus von Orgrimmar in der Gasse lebt. Er wird von Waisenmatrone Schlachterbe umsorgt und träumt davon, ein legendärer Held der Horde zu werden.",al={"grunth nsc","orc-waisenkind","orgrimmar waisenkind"}},{q="Wo ist Grunth zu finden?",a="Er hält sich mit den anderen Waisenkindern in der Gasse in Orgrimmar auf, doch während der Kinderwoche kann ein Abenteurer ihn überall mit einer Pfeife des orcischen Waisenkindes herbeirufen, die man von Waisenmatrone Schlachterbe erhält.",al={"grunth aufenthaltsort","wo ist grunth","grunth finden"}},{q="Welche Orte möchte Grunth besuchen?",a="Grunth sehnt sich danach, die größten Ikonen der Horde zu sehen. Zu seinen Bitten gehört es, Oberhäuptling Cairne Bluthuf in Donnerfels zu besuchen, die Docks von Ratschet zu besichtigen und den weiten Weg zum zerstörten Thronsaal von Lordaeron zu reisen.",al={"grunth quests","was will das waisenkind","grunth reise"}},{q="Welche Art von Persönlichkeit hat Grunth?",a="Grunth ist laut, neugierig und äußerst fantasievoll. Er stellt den Abenteurern, die ihn begleiten, ständig absurde Rätsel und kindliche Fragen, wie etwa, was „Zug Zug“ eigentlich bedeutet, ob eine flügellose Fliege eine Gehe heißt, und erwähnt beiläufig, dass er sich einen Stein in die Nase gesteckt hat.",al={"grunth zitate","grunth dialoge","was sagt grunth"}}},fx={ec5570c7={q="Auf wessen Seite steht Grunth?",a="Grunth gehört ganz zur Horde. Aufgewachsen in Orgrimmar unter der Obhut von Waisenmatrone Schlachterbe, blickt er zu den Champions der Horde auf und träumt davon, mächtige Taten mitzuerleben, wie etwa einen Helden dabei zu beobachten, wie er gegen einen wilden Drachen kämpft.",al={"grunth horde oder allianz","ist grunth horde","grunth fraktion"}},["06889c57"]={q="Warum ist Grunth in Orgrimmar?",a="Grunth ist ein orcisches Waisenkind, das unter der Obhut des Waisenhauses von Orgrimmar im Tal der Ehre lebt. Während der Kinderwoche darf er die Welt an der Seite eines erfahrenen Abenteurers der Horde erkunden, der seine eifrigen Fragen beantwortet und ihm die weitere Welt zeigt.",al={"warum ist grunth hier","warum ist grunth in orgrimmar","grund für grunths standort"}},["0a265be0"]={q="Mit wem ist Grunth verbunden?",a="Grunth wird von Waisenmatrone Schlachterbe im Waisenhaus in Orgrimmar betreut. Sie kümmert sich um den jungen Orc und vertraut ihn Abenteurern der Horde an, die bereit sind, ihn als Mentor zu begleiten und ihn auf Reisen durch Kalimdor und darüber hinaus mitzunehmen.",al={"wer kümmert sich um grunth","grunth verbindungen","grunth waisenmatrone"}}},fp="6,260,28.483.0,24.393.0,14.169.0,26.194.0,38.226.0,42.291.0"}
P.entries["npc:gryan-stoutmantle"] = {n="Gryan Starkmantel",s="Gryan Starkmantel ist ein Paladin der Silbernen Hand und der Kommandant von The People's Militia, der von der Späherkuppe in Westfall aus operiert. Er wurde in Westfall geboren und kehrte aus dem verwüsteten nördlichen Königreich Lordaeron zurück, um seine Heimat zu beschützen, nachdem Sturmwinds Krone die Region dem Banditentum überlassen hatte.",h="Gryan Starkmantel ist ein Paladin der Silbernen Hand und der Kommandant von The People's Militia, der von der...",kw={"die todesminen","gryan","volksmiliz","späherkuppe","silberne hand","stoutmantle","vancleef","westfall","wiley"},ang={["class:Paladin"]="Starkmantel ist ein lebendiges Beispiel für die Pflicht der Silbernen Hand: Als die Hohen Räte von Kirche und Krone die Armen ignorierten, brachte er den Schutz des Lichts direkt zu den einfachen Bauern, die ihn am dringendsten brauchten.",["faction:Alliance"]="Gryans Vertrauen auf unabhängige Freiwillige offenbart die bitteren Risse im Kernland der Allianz, wo politische Tatenlosigkeit in Sturmwind treue Bürger dazu zwingt, selbst zu den Waffen zu greifen.",["race:Human"]="Der in Westfall geborene Gryan verkörpert die Widerstandskraft der ländlichen Bevölkerung Sturmwinds und bietet sowohl regionalen Banditen als auch der bürokratischen Vernachlässigung durch die Hauptstadt die Stirn."},sec={{t="Ein Ritter kehrt heim",b="Gryan Starkmantel begann seinen Dienst weit entfernt von den ruhigen Feldern des südlichen Azeroths. Als junger Mann reiste er nach Norden nach Lordaeron, legte sein Gelübde als Ritter der Silbernen Hand ab und ertrug die Schrecken des Dritten Krieges; er wurde sogar Zeuge der tragischen Säuberung von Stratholme durch Prinz Arthas Menethil. Als ihn die Nachricht erreichte, dass seine Heimatprovinz Westfall in Gesetzlosigkeit versank, von organisierten Banditen überrannt und von der Krone im Stich gelassen wurde, ließ Gryan die nördlichen Fronten hinter sich. Er tauschte imperiale Schlachtfelder gegen die Verteidigung ehrlicher Bauern ein und schwor, dass seine Heimat nicht so fallen würde wie der Norden."},{t="The People's Militia",b="Nach seiner Rückkehr fand Gryan Westfall praktisch unverteidigt vor. Aufgrund königlicher Vernachlässigung und politischer Lähmung im Haus der Adligen weigerte sich Sturmwind, Garnisonstruppen zu entsenden. Als Reaktion darauf gründete Starkmantel The People's Militia auf der Späherkuppe und scharte einheimische Bauern, Wachen und reisende Mercenaries zu einem freiwilligen Verteidigungskorps um sich. Seine Streitkräfte halten eine prekäre Stellung gegen die Bruderschaft der Defias, Flussflossen-Gnolle und feindselige Mechanoide und können nicht einmal Verstärkung entbehren, wenn benachbarte Siedlungen wie Seenhain um Hilfe flehen."},{t="Die Demaskierung des Drahtziehers",b="Starkmantel weigerte sich, blind zu kämpfen, und wandte sich an ein weitreichendes Informationsnetzwerk, um aufzudecken, wer den Ruin von Westfall orchestrierte. Indem er eine alte Schuld bei dem zwielichtigen Schurken Wiley dem Schwarzen im Rotkammgebirge einforderte und sich mit Mathias Shaw von SI:7 beriet, lüftete Gryan den Schleier: Die Banditen wurden von Edwin van Cleef angeführt, dem gekränkten Meisterarchitekten der Steinmetzgilde. Nachdem die Miliz einen Banditen gefangen genommen hatte, der versuchte, einen einheimischen Wagen zu plündern, nutzte Gryan den Verräter, um das unter Mondbruch in den Todesminen verborgene Hauptquartier der Bruderschaft ausfindig zu machen, und beauftragte erfahrene Champions damit, VanCleef direkt zur Strecke zu bringen."}},faq={{q="Wer ist Gryan Starkmantel?",a="Gryan Starkmantel ist ein Paladin der Silbernen Hand sowie der Gründer und Kommandant von The People's Militia, der freiwilligen Garnison mit Hauptsitz auf der Späherkuppe, die Westfall verteidigt.",al={"wer ist gryan","stoutmantle geschichte","anführer von westfall"}},{q="Warum wird The People's Militia benötigt, wenn Westfall zu Sturmwind gehört?",a="Sturmwinds Haus der Adligen weigerte sich, königliche Soldaten oder Mittel aus der Schatzkammer bereitzustellen, um die abgelegene Provinz zu schützen. Sich selbst überlassen gegen Marodeure und Gnolle, bildete die örtliche Bauernschaft unter Gryans Führung ihre eigene unabhängige Verteidigungsmacht.",al={"warum bürgermiliz","wo ist die armee von sturmwind","warum sturmwind westfall aufgab"}},{q="Welche Geschichte verbindet Gryan mit der Silbernen Hand?",a="Gryan reiste in seiner Jugend nach Lordaeron, um ein heiliger Paladin der Silbernen Hand zu werden. Er diente während des Dritten Krieges auf nördlichen Schlachtfeldern und war beim Ausmerzen von Stratholme zugegen, bevor er nach Süden aufbrach, um seine bedrohte Heimat zu retten.",al={"ist gryan ein paladin","gryan silberne hand","gryan in lordaeron"}},{q="Warum weigert sich Gryan, Seenhain Hilfe zu schicken?",a="Als Magistrat Solomon von Seenhain Verstärkung gegen die Gnolle und Orcs des Rotkammgebirges anforderte, war Gryan gezwungen abzulehnen. The People's Militia ist bis zum Äußersten angespannt, um die Späherkuppe zu halten; die Entsendung selbst einer kleinen Abteilung würde dazu führen, dass Westfall an die Defias fällt.",al={"magistrat solomons bitte","hilfe für das rotkammgebirge","warum keine truppen nach seenhain"}},{q="Wie hat Gryan herausgefunden, wo sich die Defias versteckt hielten?",a="Gryan wendet sich für Informationen an Wiley den Schwarzen und Mathias Shaw und bittet dann Abenteurer, die Bruderschaft zu untersuchen. Die darauf folgenden Entdeckungen werden im Spoiler-Abschnitt beschrieben.",al={"die todesminen finden","wer fand vancleef","geschichte des defias-verräters"}},{q="Wer ist Wiley der Schwarze für Gryan?",a="Wiley der Schwarze ist ein Kontakt im Gasthaus von Seenhain, der Gryan sein Leben verdankte. Obwohl Starkmantel für das anrüchige Wesen des Schurken wenig übrig hat, nutzte er diese Lebensschuld, um entscheidende Informationen über die Operationen der Defias zu erhalten.",al={"wiley und gryan","schuld von wiley dem schwarzen"}}},fx={["7558c158"]={q="Auf wessen Seite steht Gryan Starkmantel?",a="Gryan ist der Allianz, dem Königreich Sturmwind und vor allem dem einfachen Volk von Westfall gegenüber loyal. Während der königliche Hof von Sturmwind die Not der Provinz ignoriert, hat Gryan die Dinge selbst in die Hand genommen und führt die People's Militia an. Er bleibt ein treuer Ritter, der dafür kämpft, das Reich für seine rechtmäßigen Bürger zurückzugewinnen.",al={"gryan starkmantel fraktion","wem dient gryan","welcher fraktion gehört gryan an"}},c0a0d15a={q="Was will Gryan Starkmantel?",a="Gryan versucht, die The Defias Brotherhood auszurotten und Frieden, Recht und Ordnung in Westfall wiederherzustellen. Er will die überrannten Farmen der Provinz zurückgewinnen, die Banditen und Diebe, die ehrliche Siedler terrorisieren, vertreiben und die Sicherheit der Farmer gewährleisten, die von der Krone im Stich gelassen wurden.",al={"gryan starkmantel ziel","was will gryan","gryan motivation"}},d2149791={q="Warum ist Gryan Starkmantel in Westfall?",a="Westfall ist Gryans Heimat. Als ihn während des Dritten Krieges in Lordaeron die Nachricht erreichte, dass kriminelle Wegelagerer seinen Heimatboden überrannten und Farmer von ihrem Land vertrieben, kehrte er in den Süden zurück, um die Provinz zu verteidigen. Stationiert auf der Späherkuppe, führt er die People's Militia vom Herzen des umkämpften Gebiets aus an.",al={"warum ist gryan in westfall","warum kam gryan nach westfall","warum ist gryan auf der späherkuppe"}},["9073fb6b"]={q="Mit wem ist Gryan Starkmantel verbunden?",a="Gryan unterhält Verbindungen zu Mathias Shaw, dem Leiter des Geheimdienstes von Sturmwind SI:7, der ihn mit wichtigen Aufklärungsergebnissen bezüglich der Defias versorgt. Er ist auch mit Wiley der Schwarze im Rotkammgebirge verbunden, einem alten Bekannten, dessen Leben er einst rettete, und koordiniert sich mit lokalen Verteidigern in den benachbarten Ländern.",al={"gryan starkmantel verbündete","mit wem arbeitet gryan","gryan verbindungen"}}},fp="17,298,22.599.0,20.546.0,21.617.1,25.178.0,68.259.0,45.247.0,47.290.0,52.185.1,32.245.0"}
P.entries["npc:guard-berton"] = {n="Wache Berton",s="Wache Berton ist ein menschlicher Stadtwächter, der vor dem Gasthaus von Seenhain im Rotkammgebirge stationiert ist. Frustriert über die bürokratischen Verzögerungen des Rechtssystems von Sturmwind sucht er nach rascher Gerechtigkeit gegen Targorr den Schrecklichen, einen inhaftierten Orc-Anführer.",h="Wache Berton ist ein menschlicher Stadtwächter, der vor dem Gasthaus von Seenhain im Rotkammgebirge...",kw={"berton","wache berton","seenhain","rotkammgebirge","targorr","targorr der schreckliche","das verlies","wie du mir so ich dir"},ang={["faction:Alliance"]="Berton verkörpert die wachsende Frustration in den ländlichen Siedlungen der Allianz, wo die örtlichen Verteidiger mit ansehen müssen, wie die zentrale Bürokratie von Sturmwind die Justiz verzögert, während Grenzdörfer ums Überleben kämpfen."},sec={{t="Ein Wächter auf der Suche nach Gerechtigkeit",b="Während das Rotkammgebirge unter der Bedrohung der Invasion der Blackrockorcs einknickt, verharrt Wache Berton auf seinem Posten vor dem Gasthaus von Seenhain. Obwohl die örtliche Verteidigung an ihre Grenzen stößt, gilt Bertons Aufmerksamkeit einem gefangenen Feind: Targorr dem Schrecklichen. Targorr wurde gefangen genommen und tief im Verlies von Sturmwind eingesperrt, verurteilt zum Tode für seine Verbrechen gegen das Königreich. Doch da Sturmwinds Hinrichtung auf unbestimmte Zeit aufgeschoben wurde, weigert sich Berton, den brutalen Räuber in einer Zelle verweilen zu lassen, während Seenhain blutet. Er nimmt die Dinge selbst in die Hand und heuert willige Abenteurer an, um die königlichen Verzögerungen zu umgehen und den Orc direkt hinzurichten."}},faq={{q="Wer ist Wache Berton?",a="Wache Berton ist eine Wache der Allianz, die vor dem Gasthaus von Seenhain im Rotkammgebirge stationiert ist. Er ist vor allem dafür bekannt, Abenteurer anzuheuern, um an einem berüchtigten gefangenen Orc Gerechtigkeit zu üben.",al={"berton seenhain","wer ist berton"}},{q="Warum will Wache Berton, dass Targorr der Schreckliche getötet wird?",a="Targorr der Schreckliche wurde für seine Verbrechen zur Hinrichtung verurteilt, doch die Führung von Sturmwind setzte das Urteil aus. Frustriert über diese Verzögerung, während das Rotkammgebirge weiterhin belagert wird, arrangiert Berton Targorrs Beseitigung im Verlies.",al={"warum targorr toeten","targorr hinrichtung","lore zur quest wie du mir so ich dir"}},{q="Wo wird Targorr der Schreckliche gefangen gehalten?",a="Targorr wird im Verlies festgehalten, dem Hochsicherheitskerker im Kanalviertel von Sturmwind.",al={"targorr aufenthaltsort","wo ist targorr"}},{q="Wo ist Wache Berton zu finden?",a="Er hält direkt vor dem Eingang zum Gasthaus von Seenhain Wache und überblickt das Stadtzentrum von Seenhain im Rotkammgebirge.",al={"wo ist berton","berton aufenthaltsort"}}},fx={["352370f6"]={q="Auf wessen Seite steht Wache Berton?",a="Wache Berton ist ein loyaler Verteidiger des Königreichs Sturmwind und der Allianz. Er ist im Rotkammgebirge stationiert und hat die Aufgabe, die bedrängte Stadt Seenhain und ihre Bewohner vor den Gefahren der umliegenden Wildnis zu schützen, einschließlich der plündernden Blackrock-Orcs.",al={"berton fraktion","wem dient wache berton","ist berton allianz"}},bd53caa6={q="Mit wem ist Wache Berton verbunden?",a="Berton dient in der Stadtwache von Rotkammgebirge, die in Seenhain stationiert ist, und steht neben seinen Mitstreitern vor dem örtlichen Gasthaus. Über seine örtliche Garnison hinaus binden ihn seine Beschwerden direkt an Targorr der Schreckliche, einen berüchtigten Gefangenen, der in der Stormwind Stockade festgehalten wird.",al={"wache berton verbindungen","berton stadtwache","mit wem arbeitet berton"}}},fp="12,240,23.633.0,20.196.0,52.246.0,32.119.0,32.117.0"}
P.entries["npc:guard-howe"] = {n="Wache Howe",s="Wache Howe ist ein Stadtwächter, der nahe dem südlichen Fuß der Brücke von Seenhain im Rotkammgebirge stationiert ist. Getrieben von einer persönlichen Fehde gegen die Blackrock-Orcs, die in das Tal vordringen, setzt er Kopfgelder für jeden Abenteurer aus, der bereit ist, die Eindringlinge niederzustrecken.",h="Wache Howe ist ein Stadtwächter, der nahe dem südlichen Fuß der Brücke von Seenhain im Rotkammgebirge...",kw={"kopfgeld auf den schwarzfelsklan","blackrock-orcs","wache howe","howe","seenhain","rotkammgebirge"},ang={["faction:Alliance"]="Seenhain erhält wenig direkte Hilfe aus Sturmwind, sodass Frontwächter wie Howe auf durchreisende Champions der Allianz angewiesen sind, um die Blackrock-Orcs daran zu hindern, die Stadt zu überrennen."},sec={{t="Ein Groll auf der Brücke",b="Wache Howe ist direkt südlich der großen Steinbrücke über den Immerruhsee postiert und hält Wache über das Herz von Seenhain. Wie viele in der belagerten Stadt sieht er in den vordringenden Blackrock-Orcs eine existenzielle Bedrohung für das Rotkammgebirge. Howe hegt ein bitteres Verlangen nach Rache an dem Clan und rekrutiert aktiv vorbeiziehende Söldner für die Jagd auf Orcs in den östlichen Hügeln, wobei er als Gegenleistung für greifbare Beweise ihrer Niederlage Bezahlung anbietet."}},faq={{q="Wer ist Wache Howe?",a="Wache Howe ist ein menschlicher Stadtwächter, der direkt südlich der Brücke in Seenhain im Rotkammgebirge stationiert ist. Er hilft beim Schutz der Siedlung und leitet fähige Kämpfer an, gegen die einfallenden Blackrock-Orcs zurückzuschlagen.",al={"wache howe","howe seenhain","wer ist howe"}},{q="Warum will Wache Howe den Tod der Blackrock-Orcs?",a="Howe hegt eine persönliche Fehde gegen den Blackrock-Clan, der tief in das Rotkammgebirge vorgedrungen ist und Seenhain unter unerbittlichen Druck setzt. Er sinnt auf Rache und bietet Kopfgelder für jeden, der ihre Reihen lichtet.",al={"warum kopfgeld auf die blackrocks","howe orcs","warum hasst howe orcs"}},{q="Ist Wache Howe mit jemand anderem in der Region verwandt?",a="Er teilt einen Nachnamen mit Soloman Howe, was darauf hindeutet, dass sie verwandt sein könnten, auch wenn er seinen Fokus strikt auf seine Pflichten bei der Bewachung der Stadt und der Bekämpfung der Orcs richtet.",al={"howe verwandte","soloman howe verwandtschaft"}}},fx={["59b92c48"]={q="Auf wessen Seite steht Wache Howe?",a="Wache Howe dient dem Königreich Sturmwind und steht an der Seite der Stadtwache von Seenhain. Er ist an der Front von Rotkammgebirge stationiert und kämpft dafür, die lokale menschliche Bevölkerung gegen die unerbittlichen Einfälle zu verteidigen, die ihre Grenzen bedrohen.",al={"wache howe fraktion","ist wache howe allianz","wem dient wache howe"}},d5289960={q="Warum ist Wache Howe hier?",a="Wache Howe ist südlich der Brücke von Seenhain stationiert, um den Umfang der Stadt zu bewachen. Das Rotkammgebirge wird von Gnollen und eindringenden Blackrock-Orcs belagert, was die Brücke zu einem wichtigen Übergang und einem wesentlichen Engpass macht, der vor plötzlichen Angriffen geschützt werden muss.",al={"warum ist wache howe in seenhain","wache howe posten","warum wache howe brücke"}}},fp="10,269,22.433.0,18.224.0,47.229.0,51.156.0"}
P.entries["npc:guard-thomas"] = {n="Wache Thomas",s="Wache Thomas ist ein pflichtbewusster Soldat der Armee von Sturmwind, der an der Brücke westlich des Holzfällerlagers des Osttals stationiert ist. Isoliert an der östlichen Grenze des Walds von Elwynn überwacht er die Verteidigung der einheimischen Siedler gegen räuberische Wildtiere und vordringende Murlocs.",h="Wache Thomas ist ein pflichtbewusster Soldat der Armee von Sturmwind, der an der Brücke westlich des...",kw={"osttal","holzfällerlager des osttals","wald von elwynn","wache thomas","verlorene wachen","murloc","armee von sturmwind","thomas"},ang={["class:Warrior"]="Für junge Krieger der Allianz verkörpert Thomas Disziplin an vorderster Front und die unglamouröse Realität der regionalen Grenzverteidigung.",["faction:Alliance"]="Wache Thomas verkörpert den überdehnten Zustand der Armee von Sturmwind, da er mit minimaler Unterstützung durch die Krone einen lebenswichtigen Außenposten an der Grenze hält."},sec={{t="An der Ostgrenze",b="Während ein Großteil der Aufmerksamkeit des Reiches nach innen auf die Hauptstadt oder nach Westen in Richtung Westfall gerichtet ist, hält Wache Thomas einen der ruhigsten und zugleich heikelsten Posten im Wald von Elwynn. Positioniert an der Steinbrücke, die den Fluss zum Holzfällerlager des Osttals überquert, fungiert Thomas als schützende Linie zwischen den einfachen Waldarbeitern und den aggressiven Kreaturen, die durch die Wälder streifen. Da das Militär von Sturmwind stark überdehnt ist, müssen sich Wachen wie Thomas stark auf durchreisende Abenteurer verlassen, um die Ordnung aufrechtzuerhalten und Nachrichten an das Zentralkommando zu übermitteln."},{t="Grenzschwierigkeiten",b="Die östlichen Ausläufer von Elwynn stehen unter ständigem Druck. Aggressive Bären und Pirscher lauern an der Baumgrenze und bedrohen Holzfäller sowie Reisende, während seltsame Murloc-Stämme Lager entlang der Wasserwege errichtet haben. Thomas verfolgt die Bewegungen dieser aquatischen Räuber und setzt Kopfgelder aus, um ihre Zahl zu dezimieren. Schlimmer noch: Spähpatrouillen entlang des Flusses verschwinden gelegentlich spurlos, sodass Thomas versuchen muss, das Schicksal seiner Wachkameraden inmitten der wachsenden regionalen Instabilität aufzuklären."}},faq={{q="Wo finde ich Wache Thomas?",a="Wache Thomas ist auf der Steinbrücke postiert, die den Fluss direkt westlich des Holzfällerlagers des Osttals entlang der östlichen Straße im Wald von Elwynn überspannt.",al={"wache thomas standort","wo ist thomas","wache thomas brücke"}},{q="Was ist die Aufgabe von Wache Thomas im Wald von Elwynn?",a="Er ist ein Soldat der Armee von Sturmwind, der mit dem Schutz der östlichen Grenze von Elwynn beauftragt ist. Zu seinen Aufgaben gehören die Sicherung der Handelsbrücke, die Verteidigung der nahegelegenen Arbeiter vor wilden Raubtieren und die Überwachung feindseliger Murloc-Übergriffe entlang der Flussufer.",al={"was macht thomas","wache thomas aufgabe","thomas osttal"}},{q="Warum bittet Wache Thomas um Hilfe bezüglich verschwundener Wachen?",a="Routinepatrouillen, die in die Flussbecken entsandt wurden, haben sich nicht zurückgemeldet. Ohne ausreichende Verstärkung, um seinen Posten unbesetzt zu lassen, rekrutiert Thomas durchreisende Abenteurer, um die Wasserwege abzusuchen und herauszufinden, was mit seinen vermissten Kameraden geschehen ist.",al={"vermisste wachen elwynn","wache thomas verschwundene späher","was geschah mit den wachen"}},{q="Warum sind Murlocs ein Problem für Wache Thomas?",a="Murloc-Stämme dringen zunehmend in die Flusssysteme des östlichen Elwynn vor. Ihre wachsende Präsenz bedroht sowohl die örtlichen Holzfällarbeiten als auch die Überlandversorgungswege, was Thomas dazu veranlasst hat, Kopfgelder auf ihre Flossen auszusetzen, um die Wasserwege freizuhalten.",al={"murlocs osttal","warum murlocs töten","wache thomas murloc kopfgeld"}},{q="Wem untersteht Wache Thomas?",a="Thomas dient in der Armee von Sturmwind und untersteht über die militärische Hierarchie dem regionalen Kommando in Goldhain und der Hauptstadt. Während sich die Lage an den Grenzen verschlechtert, stimmen sich seine Berichte auch mit der Grenzführung wie Gryan Starkmantel in Westfall ab.",al={"thomas vorgesetzter","befehlskette armee von sturmwind","für wen arbeitet thomas"}},{q="Wohin schickt Wache Thomas die Abenteurer, sobald ihre Arbeit in Elwynn erledigt ist?",a="Sobald die unmittelbaren Bedrohungen rund um das Osttal und den östlichen Fluss gebannt sind, stellt Thomas Berichte zur Verfügung, die erfahrene Reisende nach Westfall leiten, um Gryan Starkmantel und der kämpfenden Volksmiliz beizustehen.",al={"nach wache thomas","wohin nach dem osttal","bericht für westfall"}}},fx={["2ef4fdb3"]={q="Wer ist Wache Thomas?",a="Wache Thomas ist ein Offizier der Armee von Sturmwind, der an der östlichen Grenze vom Wald von Elwynn stationiert ist. Während die Streitkräfte von Sturmwind im gesamten Königreich dünn gesät sind, hält Thomas die Stellung nahe dem Holzfällerlager des Osttals und schützt Reisende und Arbeiter entlang der Brücke vor Gnollen und eindringenden Murlocs.",al={"wer ist thomas","identität von wache thomas","wer ist wache thomas"}},["26bccfb6"]={q="Auf wessen Seite steht Wache Thomas?",a="Thomas dient dem Königreich Sturmwind und der Allianz. Als loyaler Soldat der Armee von Sturmwind handelt er unter der Autorität des Throns und arbeitet direkt daran, die Grenzen des Reiches für dessen Bürger und Arbeiter zu sichern.",al={"fraktion von wache thomas","wem dient wache thomas","wache thomas allianz"}},["8313e011"]={q="Was will Wache Thomas?",a="Thomas benötigt fähige Hände, um den östlichen Rand von Elwynn zu schützen. Zwischen aggressiven Flussmurlocs und feindseligen Gnollen, die die Holzfäller des Osttals bedrohen, möchte er die umliegende Wildnis gesichert wissen, das Schicksal vermisster Patrouillen aufklären und regelmäßige Informationen an das Oberkommando in Sturmwind und Westfall senden.",al={"was will thomas","ziele von wache thomas","was braucht wache thomas"}},c7700b23={q="Warum ist Wache Thomas hier?",a="Thomas ist an der östlichen Brücke stationiert, um den Hauptübergang zum Holzfällerlager des Osttals und die dahinter liegenden Grenzgebiete zu bewachen. Da das Osttal für die Holzversorgung Sturmwinds lebenswichtig ist und lokale Bestien aus den Flüssen und Hügeln vordringen, ist eine militärische Präsenz notwendig, um den Weg offen zu halten.",al={"warum ist wache thomas an der brücke","warum ist thomas hier","standortgrund von wache thomas"}}},fp="12,261,21.542.0,17.495.1,30.142.0,45.258.0,53.251.0,43.251.0,32.275.0,75.208.0"}
P.entries["npc:gubber-blump"] = {n="Gubber Blump",s="Gubber Blump ist ein Zwergenfischer und -lehrer, der an den Ufern von Auberdine an der Dunkelküste stationiert ist. Im Sand zwischen den Docks und dem Flugmeister gelegen, ist er ein begeisterter Liebhaber des Angelhandwerks und von Meeresfrüchten, insbesondere von frischem Krabbenfleisch.",h="Gubber Blump ist ein Zwergenfischer und -lehrer, der an den Ufern von Auberdine an der Dunkelküste...",kw={"auberdine","blump","dunkelküste","angeln","graun blump","gubber","riffkriecher","glänzender schatz"},ang={["profession:Cooking"]="Gubber begeistert sich leidenschaftlich für Küstenkost, insbesondere für frisches Fleisch von Riffkriechern, was ihn zu einem Gleichgesinnten für Köche macht, die Zutaten aus den Gewässern der Dunkelküste suchen.",["race:Dwarf"]="Einen Zwerg zu sehen, der sich glücklich an einer nebligen Küste von Kalimdor anstatt in Khaz Modan niedergelassen hat, ist ein ungewöhnlicher Anblick, doch seine unverblümten Neckereien über die Verwandtschaft beweisen, dass er seine Wurzeln in Eisenschmiede nicht verloren hat."},sec={{t="Der Angler von Auberdine",b="Während die meisten Zwerge Trost unter Stein oder neben einer tosenden Schmiede finden, bevorzugt Gubber Blump die neblige Küste der Dunkelküste. Am Strand von Auberdine zwischen dem Flugmeister und dem Fähranleger stationiert, lehrt Gubber die Kunst des Angelns und verkauft grundlegende Angelausrüstung an vorbeikommende Reisende. Er hegt eine tiefe kulinarische Vorliebe für Krabbenfleisch, verlässt sich jedoch häufig auf Abenteurer, die ihm dabei helfen, seinen Fang an der gefährlichen Küste zu sichern sowie sentimentales Angelgerät seiner Familie zurückzuholen."},{t="Familienbande und Gefälligkeiten am Meer",b="Gubber ist dafür bekannt, offenherzige Geschichten über seine Familie zu erzählen, insbesondere über seine Kusine Graun Blump, von der er behauptet, dass sie sowohl einen Bart als auch einen ungewöhnlichen Geruch besitzt. Reisende, die ihm bei seinen Besorgungen an der Küste zur Hand gehen – sei es beim Einholen von Kriecherbeinen oder beim Bergen seiner Familienangel –, erhalten von Gubber oft einen aufmerksamen handgeschriebenen Dankesbrief, meist begleitet von einem glänzenden Angelköder, um ihre zukünftigen Auswürfe zu fördern."}},faq={{q="Wer ist Gubber Blump?",a="Gubber Blump ist ein zwergischer Angellehrer und Händler am Strand von Auberdine, direkt zwischen den Docks des Dorfes und dem Hippogryphenmeister gelegen.",al={"wer ist gubber blump","gubber blump nsc","wo ist gubber blump"}},{q="Was lehrt oder verkauft Gubber Blump?",a="Er bildet Neulinge im Angelberuf aus und führt grundlegende Ausrüstung für angehende Angler, darunter einfache Angeln und Glänzende Schätze.",al={"was verkauft gubber","gubber blump lehrer","dunkelküste angellehrer"}},{q="Welche Aufgaben vergibt Gubber Blump?",a="Gubber bittet Reisende, seine verlorene Familienangel wiederzubeschaffen und feines Krabbenfleisch von der Küste zu sammeln, etwa in den Quests 'Die Familie und die Angelrute' und 'Meeresfrüchte'.",al={"gubber blump quests","meeresfrüchte","die familie und die angelrute"}},{q="Wer ist Graun Blump?",a="Graun Blump ist Gubbers Zwergenkusine. Gubber bemerkt freimütig, dass sie einen beachtlichen Bart zur Schau trägt und einen ziemlich ungewöhnlichen Geruch hat.",al={"graun blump","gubber blump kusine"}}},fx={["0ab58c9b"]={q="Auf wessen Seite steht Gubber Blump?",a="Gubber Blump ist ein Zwerg der Allianz, der friedlich an der Seite der Nachtelfen von Auberdine stationiert ist. Obwohl er sich größtenteils um seine eigenen Angelegenheiten kümmert und auf sein Handwerk konzentriert, heißt er Reisende der Allianz willkommen, um mit ihnen zu handeln, zu trainieren und den Fang von der Küste zu teilen.",al={"ist gubber blump allianz","fraktion von gubber blump","wem dient gubber blump"}},["09bb4e46"]={q="Was will Gubber Blump?",a="Gubber ist leidenschaftlicher Angler und liebt kulinarische Köstlichkeiten; er hat eine besondere Vorliebe für frisches Krabbenfleisch aus den örtlichen Gewässern. Vor allem möchte er die Schätze des Meeres genießen, das verlorene Angelgerät seiner Familie wiederfinden und anderen Anglern die Feinheiten des Berufs beibringen.",al={"was ist gubber blumps ziel","was braucht gubber blump","beweggründe von gubber blump"}},["77301056"]={q="Warum ist Gubber Blump in Dunkelküste?",a="Gubber hat sein Zuhause an der Küste von Auberdine aufgeschlagen, eingebettet zwischen den Docks und dem Flugmeister. Die neblige Küste bietet reichhaltige Angelgründe und einen stetigen Fang an Riffkrabben, was sie zu einem idealen Posten für einen zwergischen Angler macht, der in Frieden fischen möchte.",al={"warum ist gubber blump hier","warum ist ein zwerg in dunkelküste","warum ist gubber in auberdine"}}},fp="12,256,23.502.0,28.409.0,20.153.0,37.142.0,38.178.0,19.127.0"}
P.entries["npc:gunther-arcanus"] = {n="Gunther Arkanus",s="Gunther Arkanus ist ein außergewöhnlich mächtiger Nekromant, der auf einer abgelegenen Insel im Blendwassersee haust. Im Dritten Krieg erschlagen und in den Untod erhoben, gelang es ihm, den geistigen Griff des Lichkönigs gänzlich aus eigener Kraft zu brechen. Lange Zeit glaubte er, der einzige Untote mit freiem Willen zu sein, und verteidigte seinen Zufluchtsort gegen alle Außenstehenden, bis die Verlassenen ihn entdeckten.",h="Gunther Arkanus ist ein außergewöhnlich mächtiger Nekromant, der auf einer abgelegenen Insel im...",kw={"arcanus","bethor","blendwassersee","dalaran","gunther","iceshard","kirin tor","lich","nekromant","thule","tirisfal"},ang={["class:Mage"]="In Dalaran ausgebildet, repräsentiert Gunther jene Magier der Kirin Tor, die sich vor der Invasion Lordaerons durch die Geißel heimlich mit verbotenen nekromantischen Zaubern beschäftigten.",["class:Warlock"]="Gunthers befehlshabende Beherrschung der dunklen Künste und der Reanimation zeigt, wie weit verbotene Studien außerhalb der wachsamen Augen der Führung von Dalaran gedeihen konnten.",["race:Undead"]="Gunthers Selbstbefreiung macht ihn zu einer Anomalie unter den Verlassenen und beweist, dass intensive arkane Ausbildung und eiserner Wille allein mitunter ausreichten, um die geistige Beherrschung des Lichkönigs zu zerschlagen."},sec={{t="Ein Schüler Dalarans",b="Vor dem Fall von Lordaeron war Gunther ein vielversprechender Lehrling der Kirin Tor in Dalaran. Gemeinsam mit seinen engen Freunden Bethor Eismacht und Thule Rabenklaue studierte er die arkanen Künste und vertiefte sich heimlich in die Nekromantie, ungeachtet der strengen Verbote der Kirin Tor bezüglich dunkler Magie. Zum Gedenken an ihre Bruderschaft band das Trio einst ihre Lehrlingszauberstäbe zu einem einzigen Erbstück zusammen."},{t="Sprengen der Fesseln",b="Als die Geißel während des Dritten Krieges über den Norden fegte, erlag Gunther der Seuche des Untods und wurde in die Knechtschaft erhoben. Anders als die meisten, die auf eine Schwächung der Macht des Lichkönigs angewiesen waren oder darauf, dass Fürstin Sylvanas ihre Ketten brach, erlaubten Gunthers rohe arkane Meisterschaft und seine schiere Willenskraft es ihm, die geistige Beherrschung des Lichkönigs vollkommen allein abzuschütteln. Überzeugt davon, dass jeder andere wandelnde Leichnam ein geistloser Knecht der Geißel geblieben war, zog er sich auf eine Insel in Tirisfal zurück, umgab sich mit schlurfenden Wächtern und brach jeden Kontakt zu den Lebenden wie auch den Toten ab."},{t="Der abtrünnige Lich",b="Auf der Suche nach mächtigen Verbündeten gegen die Geißel sandten die Verlassenen Abgesandte aus, um das Zauberbuch des geheimnisvollen Nekromanten zu beschaffen. Bei der Untersuchung des arkanen Wälzers in Unterstadt erkannte Bethor Eismacht die unverwechselbare Handschrift seines lang verschollenen Weggefährten. Durch das Verzaubern des zurückgebrachten Grimoires und die Forderung nach der Vernichtung örtlicher Geißelkommandanten erkannte Gunther schließlich, dass er mit seiner Freiheit nicht allein war. Überzeugt davon, dass Sylvanas' Fraktion eine echte Rebellion gegen die Geißel darstellt, schloss er einen Pakt mit seinem ehemaligen Mitschüler, um den Verlassenen beizustehen."}},faq={{q="Wer ist Gunther Arkanus?",a="Er ist ein ehemaliger Magier der Kirin Tor aus Dalaran, der während des Dritten Krieges umkam. In den Untod erhoben, befreite er sich aus eigener Kraft von der Beherrschung des Lichkönigs und zog sich auf eine Insel im Blendwassersee in Tirisfal zurück.",al={"wer ist gunther","gunther lore","gunther arkanus geschichte"}},{q="Warum sieht Gunther wie ein gewöhnlicher Verlassener aus und nicht wie ein skelettartiger Lich?",a="Während traditionelle Liche ihren Geist in ein Phylakterium transferieren und monströse, schwebende Skelettgestalten annehmen, erlangte Gunther seinen lichähnlichen nekromantischen Status, ohne seinen ursprünglichen wiederbelebten Leichnam aufzugeben, wodurch seine physische, sterbliche Erscheinung erhalten blieb.",al={"warum sieht gunther menschlich aus","gunther kein skelett","warum ist gunther ein lich"}},{q="Warum lebte Gunther allein auf einer Insel?",a="Nachdem er die mentale Kontrolle des Lichkönigs gebrochen hatte, glaubte Gunther, er sei der einzige existierende Untote mit freiem Willen. In der Annahme, alle anderen wandelnden Toten seien noch immer geistlose Sklaven der Geißel, isolierte er sich und befahl seinen Dienern, jeden niederzustrecken, der sich näherte.",al={"warum ist gunther allein","gunther insel isolation","warum versteckt sich gunther"}},{q="Woher kennt Gunther Bethor Eismacht?",a="Sie waren Mitschüler und enge Freunde in Dalaran, die gemeinsam unter den Kirin Tor lernten, zusammen mit einem dritten Magier namens Thule Rabenklaue. Die drei Freunde flochten sogar ihre Lehrlingszauberstäbe als Symbol ihres Bundes zusammen.",al={"bethor und gunther","woher kennt gunther bethor","bethor eismacht geschichte"}},{q="Schließt sich Gunther den Verlassenen an?",a="Ja. Sobald Abenteurer sein verzaubertes Zauberbuch zurückbringen und die lokale Geißelagentin Lillith Nefara hinrichten, um ihre Unabhängigkeit vom Lichkönig zu beweisen, schwört Gunther Bethor und der Sache der Verlassenen seine Gefolgschaft.",al={"schließt sich gunther der horde an","gunther fraktion","ist gunther ein verlassener"}},{q="Wer ist Lillith Nefara?",a="Lillith Nefara ist eine Agentin der Geißel, die in Tirisfal stationiert ist. Gunther verlangt ihren Tod als Beweis dafür, dass der Abenteurer wahrhaftig einem Feind des Lichkönigs dient und nicht der Geißel selbst.",al={"lillith nefara","nefara","gunther ziel"}}},fx={["3744b38d"]={q="Was will Gunther Arkanus?",a="Vor allem schätzt Gunther seine Unabhängigkeit vom Lichkönig. Nachdem er sich durch schiere Willenskraft befreit hatte, verbrachte er Jahre in Isolation und bewachte sich vor dem, was er für Sklaven der Geißel hielt. Er begehrt Einsamkeit vor der Geißel und sucht nach Beweisen, bevor er jemandem vertraut, der behauptet, seine Freiheit zu teilen, und möchte die Gewissheit haben, dass Ihr der Herrschaft des Lichkönigs wirklich entgegensteht.",al={"was will gunther","ziel von gunther arkanus","motivation von gunther arkanus"}},["2466094b"]={q="Warum ist Gunther Arkanus berühmt oder gefürchtet?",a="Selbst als sterblicher Magier von Dalaran meisterte Gunther die verbotene Kunst der Nekromantie. Im Untod erreichte er den seltenen Status eines Lichs, während er seine ursprüngliche sterbliche Form behielt. Am beängstigendsten ist jedoch, dass er die psychische Kontrolle des Lichkönigs ganz aus eigener Kraft zerschlug und nun untote Diener unter seinem absoluten Willen befehligt.",al={"ist gunther arkanus mächtig","warum ist gunther arkanus gefürchtet","ruf von gunther arkanus"}}},fp="15,371,20.392.0,21.596.0,17.549.1,23.229.0,73.258.0,42.272.0,38.213.0,31.216.1,22.198.1"}
P.entries["npc:gurda-ragescar"] = {n="Gurda Zornnarbe",s="Gurda Zornnarbe war eine Orcin, die an einem kleinen Außenposten der Horde südwestlich vom Splitterholzposten in Eschental stationiert war. An der Seite von Feran Strongwind fiel sie bei der Verteidigung ihres Lagers gegen örtliche Gefahren im schattigen Wald.",h="Gurda Zornnarbe war eine Orcin, die an einem kleinen Außenposten der Horde südwestlich vom Splitterholzposten...",kw={"eschental","feran strongwind","gurda","orc","ragescar","splintertree","die verlorenen seiten"},ang={["faction:Horde"]="Das gefallene Lager dient als düstere Mahnung an den hohen Preis, den die Horde zahlt, um in den heiligen Wäldern von Eschental Fuß zu fassen."},sec={{t="Ein zerschlagener Außenposten",b="Direkt südwestlich der befestigten Mauern des Splitterholzpostens unterhielt Gurda Zornnarbe ein bescheidenes Lager der Horde unter dem dichten Blätterdach von Eschental. Tief in einem Gebiet, das von nachtelfischen Verteidigern und wilden Tieren umkämpft wird, ist das Halten solch isolierter Stellungen ein gefährliches Unterfangen. Gurda wurde zusammen mit Feran Strongwind und ihrer Abteilung von Wachen letztlich an ihrem Posten überrannt und getötet, sodass vorüberziehenden Verbündeten nur die Überreste ihres letzten Gefechts blieben."},{t="Die gefallenen Späher",b="Reisende, die nahe des Pfades unterwegs sind, stoßen womöglich auf den tragischen Schauplatz von Gurdas Niederlage. Selbst im Tod bieten die Besitztümer und Aufgaben ihres Lagers Hinweise auf die Unternehmungen der Horde in den Wäldern, darunter vermisste Dokumente und durch den Hinterhalt vereitelte Befehle."}},faq={{q="Wer ist Gurda Zornnarbe?",a="Gurda Zornnarbe ist eine Orc-Späherin und Questgeberin an einem kleinen Lager direkt südwestlich vom Splitterholzposten in Eschental, die zusammen mit ihren Gefährten am Außenposten ein gewaltsames Ende fand.",al={"wer ist gurda","gurda zornnarbe lore"}},{q="Wo ist Gurda Zornnarbe zu finden?",a="Ihr Leichnam liegt in einem überrannten Lager südwestlich vom Splitterholzposten, abseits des Weges, der durch das zentrale Eschental führt.",al={"gurda standort","wo ist gurda zornnarbe"}},{q="Wer wurde an ihrer Seite getötet?",a="Sie kam an der Seite von Feran Strongwind und ihrem Gefolge aus Wachen während eines Angriffs auf ihr kleines Lager ums Leben.",al={"wer starb mit gurda","feran strongwind"}},{q="Welche Quest steht mit Gurda Zornnarbe in Verbindung?",a="Gurda ist mit der Quest Die verlorenen Seiten verknüpft, bei der es um die Wiederbeschaffung verstreuter Dokumente in der Wildnis von Eschental geht.",al={"gurda quests","die verlorenen seiten"}}},fx={["28561f13"]={q="Welcher Fraktion gehört Gurda Zornnarbe an?",a="Gurda Zornnarbe war der Horde gegenüber loyal. Stationiert in einem kleinen Außenposten südwestlich vom Splitterholzposten, repräsentierte sie zusammen mit ihren Gefährten die befestigte Präsenz der Horde tief innerhalb der umstrittenen Grenzen vom Eschental.",al={"fraktion von gurda zornnarbe","ist gurda horde oder allianz","für wen kämpft gurda"}},e9ae8f07={q="Warum war Gurda Zornnarbe südwestlich vom Splitterholzposten stationiert?",a="Gurda Zornnarbe unterhielt zusammen mit Feran Strongwind und einem Kontingent von Wachen ein vorgeschobenes Lager der Horde südwestlich vom Splitterholzposten. Ihr Posten befand sich an den umstrittenen Waldwegen und diente dazu, die Operationen der Horde zu unterstützen und verlorene Güter in den feindseligen Wäldern vom Eschental zurückzuholen.",al={"warum ist gurda zornnarbe hier","zweck von gurdas lager","warum war gurda im eschental"}}},fp="14,208,15.473.0,17.266.0,22.179.0,34.115.0,29.108.0,35.117.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="Gwennyth Bly'Leggonde",s="Gwennyth Bly'Leggonde ist eine Nachtelfe, die in der Hafenstadt Auberdine an der Küste lebt. An der nebelverhangenen Küste der Dunkelküste stationiert, beobachtet sie die Gezeiten und schickt Reisende aus, um die seltsamen Überreste zu untersuchen, die an Land gespült werden. Ihre Sorge gilt den geheimnisvollen Meereskreaturen und riesigen Schildkröten, deren Kadaver begonnen haben, die nördlichen Strände zu übersäen.",h="Gwennyth Bly'Leggonde ist eine Nachtelfe, die in der Hafenstadt Auberdine an der Küste lebt.",kw={"auberdine","gestrandete meereskreatur","gestrandete meeresschildkröte","blyleggonde","dunkelküste","gwennyth","kaldorei","verhülltes meer","an land gespült"},ang={["class:Druid"]="Druiden, die sich der Bewahrung der natürlichen Harmonie Kalimdors verschrieben haben, sehen in Gwennyths Berichten über gestrandetes Meeresleben einen alarmierenden Hinweis auf Störungen im Küstenökosystem.",["faction:Alliance"]="Auberdine dient als primärer Küstenhafen der Allianz im nördlichen Kalimdor; seine Wasserwege und Strände vor verborgenen Bedrohungen zu schützen, ist für alle verbündeten Völker, die das Gebiet bereisen, von entscheidender Bedeutung.",["race:NightElf"]="Für die Kaldorei ist der unnatürliche Tod großer Meeresbestien vor den Ufern der Dunkelküste ein beunruhigendes Zeichen eines Ungleichgewichts in ihren angestammten Ländern, was Gwennyths Wache am Strand besonders dringlich macht."},sec={{t="Wächterin des treibenden Sandes",b="Gwennyth Bly'Leggonde hat ihr Zuhause in Auberdine, der geschäftigen Küstenzuflucht an der Dunkelküste. Während sich viele in der Stadt mit dem Wald oder der Schifffahrt über das Verhüllte Meer befassen, richtet Gwennyth ihren Blick fest auf die Küstenlinie. Die Gezeiten haben in letzter Zeit eine düstere Wendung genommen und spülen die Überreste kolossalen Meereslebens an die Brandung. Um zu verstehen, was in den Gewässern vor der Küste geschieht, verlässt sie sich auf hilfsbereite Abenteurer, die den Sand absuchen, Skelettproben bergen und Antworten zurückbringen."},{t="Die gestrandeten Riesen",b="Die Strände nördlich und südlich von Auberdine verzeichnen einen besorgniserregenden Zustrom gestrandeter Meereskreaturen und uralter Meeresschildkröten. Anstatt deren Tod unbemerkt verstreichen zu lassen, beauftragt Gwennyth Reisende damit, diese gefallenen Titanen zu untersuchen. Indem sie die Knochen studiert und herausfindet, was diese Bestien an Land trieb oder ihnen das Leben nahm, hofft sie, die verborgenen Gefahren aufzudecken, die vor den Küsten des nördlichen Kalimdor lauern."}},faq={{q="Wer ist Gwennyth Bly'Leggonde?",a="Sie ist eine Nachtelfen-Bewohnerin von Auberdine an der Dunkelküste, die die jüngsten ökologischen Störungen entlang der Küstenlinie erforscht. Sie bittet Reisende darum, den Strand zu untersuchen und seltsames Angespültes aus dem Meer zu begutachten.",al={"wer ist gwennyth","gwennyth auberdine","gwennyth lore"}},{q="Wo kann ich Gwennyth Bly'Leggonde finden?",a="Ihr könnt sie in der Küstensiedlung Auberdine finden, nahe dem Strand und den Docks an der nebelverhangenen Küste der Dunkelküste gelegen.",al={"wo ist gwennyth","gwennyth standort","gwennyth finden"}},{q="Warum interessiert sie sich für gestrandete Kreaturen?",a="Das plötzliche Sterben und Stranden gewaltiger Meeresschildkröten sowie mysteriöser Meeresungeheuer weist auf ein Ungleichgewicht oder ein ungesehenes Raubtier in den Gewässern vor der Dunkelküste hin. Gwennyth versucht, die Ursache zu ergründen, indem sie die entlang der Küste geborgenen Überreste untersucht.",al={"warum gestrandete schildkröten","warum will sie knochen","quest an land gespült"}},{q="Welche Quests bietet Gwennyth an?",a="Sie schickt Abenteurer auf die Quest 'An Land gespült' und dient als Abgabepunkt für verschiedene Entdeckungen im Zusammenhang mit den gestrandeten Meereskreaturen und gestrandeten Meeresschildkröten, die entlang der Küstenlinie der Dunkelküste gefunden werden.",al={"gwennyth quests","was gibt sie"}},{q="Gehört sie zum Zirkel des Cenarius oder zu den Schildwachen?",a="Weder noch. Sie ist eine Mondpriesterin im Dienste der Schwesternschaft von Elune in Auberdine und keine Druidin des Zirkels oder Schildwachen-Kommandantin, teilt jedoch die tiefe Besorgnis ihres Volkes über den Zustand und das Gleichgewicht der natürlichen Umwelt der Dunkelküste.",al={"gwennyth fraktion","ist gwennyth ein druide"}},{q="Was bedeutet ihr Name?",a="Obwohl er zum rhythmischen Namensstil der Kaldorei passt, ist ihr ungewöhnlicher Nachname 'Bly'Leggonde' ein Anagramm von 'Leggy Blonde' – ein verspieltes Detail der Schöpfer der Spielwelt.",al={"bly leggonde bedeutung","gwennyth name easter egg"}}},fx={["9c9d3ff5"]={q="Warum ist Gwennyth Bly'Leggonde in Dunkelküste?",a="Gwennyth hat ihr Zuhause im Küstenhafen Auberdine und hält Wache über die nebelverhangenen Strände von Dunkelküste. Beunruhigt von der unnatürlichen Fäulnis, die an die Küste gespült wird, überwacht sie das Ufer auf gestrandete Meerestiere und rekrutiert vorbeiziehende Reisende, um gestrandete Meeresbewohner und Schildkröten zu untersuchen, die unter der seltsamen Verderbnis leiden, die die Gewässer befällt.",al={"warum ist gwennyth hier","warum ist gwennyth bly'leggonde in auberdine","warum ist gwennyth in dunkelküste"}}},fp="21,348,29.489.0,19.409.0,29.212.0,39.134.0,43.248.0,32.196.0,52.234.0,24.167.0"}
P.entries["npc:hagar-lightninghoof"] = {n="Hagar Blitzhuf",s="Hagar Blitzhuf ist ein Tauren-Späher, der hoch oben im Freiwindposten im Tausend Nadeln stationiert ist. Angetrieben von Gerüchten über ein seltsames Gelege, das in den Tiefen der Schlucht verborgen liegt, untersucht er Berichte über ein fremdartiges Ei, das von örtlichen Windschlangen erbittert bewacht wird.",h="Hagar Blitzhuf ist ein Tauren-Späher, der hoch oben im Freiwindposten im Tausend Nadeln stationiert ist.",kw={"fremdartiges ei","arikara","freiwindposten","hagar","lightninghoof","motega feuermähne","tausend nadeln","windschlange"},ang={["faction:Horde"]="Hoch über dem Schluchtboden im Freiwindposten stationiert, verlässt sich Hagar auf fähige Krieger der Horde, um gefährliche Höhlen zu trotzen, die normale Späher nicht sicher betreten können.",["race:Tauren"]="Für Reisende der Tauren führt die Unterstützung von Hagar zu der aufwühlenden Erkenntnis, dass die uralten Legenden von Arikara, der geflügelten Manifestation der Rache, in den Schluchten darunter lebendige Realität sind."},sec={{t="Das seltsame Gelege",b="Während seines Dienstes inmitten der hoch aufragenden Felsen des Freiwindpostens vernahm Hagar Blitzhuf Gerüchte über ein unnatürliches Ei, das tief in einer Höhle darunter verborgen liegt. Die örtlichen Windschlangen bewachten das Nest mit ungewöhnlicher Heftigkeit und hielten neugierige Späher auf Abstand. Auf der Suche nach einem Abenteurer, der mutig genug ist, sich in das Nest der Schlangen zu wagen, hofft Hagar, das Exemplar aus erster Hand untersuchen zu können, um herauszufinden, welche Art von Bestie solche Verteidigungsinstinkte bei den natürlichen Raubtieren der Schlucht hervorrufen kann."},{t="Ein Mythos schlüpft",b="Als ein Abenteurer das Ei schließlich birgt und zum Freiwindposten bringt, schlüpft es direkt vor Hagars Augen und enthüllt eine junge Windschlange, die der legendären Arikara ähnelt – einem verehrten Geist, der in der Folklore der Tauren als die Verkörperung der Rache bekannt ist. Da er sich der gravierenden kulturellen und spirituellen Bedeutung der Rückkehr der Kreatur bewusst ist, zögert Hagar nicht lange und schickt den Reisenden los, um den Ältesten Motega Feuermähne zu konsultieren."}},faq={{q="Wer ist Hagar Blitzhuf?",a="Hagar Blitzhuf ist ein Tauren-Questgeber, der im Freiwindposten im Tausend Nadeln wohnt. Er untersucht anomale Wildtiere in den Schluchten, insbesondere ein ungewöhnliches Windschlangenei, das tief in einer nahegelegenen Höhle gemeldet wurde.",al={"wer ist hagar","hagar blitzhuf rolle","hagar lore"}},{q="Wo ist Hagar Blitzhuf zu finden?",a="Er befindet sich oben auf dem Freiwindposten, dem zentralen Außenposten der Horde, der auf den massiven Felsnadeln im Zentrum des Tausend Nadeln thront.",al={"wo ist hagar","hagar blitzhuf standort","freiwindposten hagar"}},{q="Was ist das 'fremdartige Ei', nach dem Hagar sucht?",a="Das fremdartige Ei ist ein ungewöhnliches Ei, das von Windschlangen in einem unterirdischen Bau bewacht wird. Hagar bittet Abenteurer, es zu bergen, damit er seine Natur untersuchen kann.",al={"fremdartiges ei","was ist das ei","windschlangenei"}},{q="Wen konsultiert Hagar bezüglich des Eies?",a="Hagar schickt den Abenteurer zu Motega Feuermähne, einem Ältesten im Freiwindposten, der über tieferes Wissen bezüglich der Traditionen der Tauren verfügt.",al={"bei wem gebe ich wilde schlange ab","hagar folgequest","wohin nach hagar"}}},fx={d173f224={q="Auf wessen Seite steht Hagar Blitzhuf?",a="Hagar Blitzhuf ist der Horde und seinen Tauren-Gefährten treu ergeben. Stationiert auf den hoch aufragenden Spitzen vom Freiwindposten, vertraut er seine Aufgaben nur Champions der Horde an, die beweisen, dass sie es wagen, die gefährlichen Schluchten darunter zu durchqueren.",al={"fraktion von hagar blitzhuf","ist hagar horde"}},c809f2c7={q="Warum ist Hagar Blitzhuf hier am Freiwindposten?",a="Hagar reiste nach Tausend Nadeln, nachdem er Gerüchte über ein seltsames, fremdartiges Ei gehört hatte, das in den Nestern der Windschlangen gesichtet wurde. Fasziniert von dem seltsamen Fund, schlug er sein Lager am Freiwindposten auf, um jemanden zu finden, der mutig genug ist, es an den Schlangenwachen vorbei zu bergen.",al={"warum ist hagar hier","warum kam hagar nach tausend nadeln"}},a74332ba={q="Mit wem ist Hagar Blitzhuf verbunden?",a="Hagar arbeitet mit den Tauren-Verteidigern vom Freiwindposten zusammen und berät sich eng mit Motega Feuermähne. Wenn seine Untersuchungen Angelegenheiten offenbaren, die tief in alten Tauren-Legenden und heiligen Omen verwurzelt sind, wendet er sich an Motega, um Rat zu suchen.",al={"verbindungen von hagar","mit wem arbeitet hagar zusammen"}}},fp="19,239,18.474.0,14.425.1,27.220.0,39.126.0,45.151.1,37.140.1"}
P.entries["npc:halaan-hawk-eye"] = {n="Halaan Hawk-Eye",s="Halaan Hawk-Eye ist ein Ausguck der Skyborne, der auf der Spitze des Wachturms von Thendal auf der Insel Zephras stationiert ist. Da ihm sowohl das magische Gespür als auch die mystische Himmelssicht seiner Artgenossen fehlen, verlässt er sich stattdessen auf seine scharfe weltliche Sehkraft, um die umliegende Insel zu überwachen. Von seinem Hochsitz aus behält er die fernen Ankerpylone im Auge und warnt Besucher vor deren schwindender arkaner Stabilität.",h="Halaan Hawk-Eye ist ein Ausguck der Skyborne, der auf der Spitze des Wachturms von Thendal auf der Insel...",kw={"ankerpylon","halaan","hawk-eye","skyborne","himmelssicht","thendal","insel zephras"},ang={["race:Skyborne"]="Halaan repräsentiert jene unter den Skyborne, denen die natürliche Affinität zur Manipulation von Leylinien oder die Himmelssicht fehlt, und die ihrer Gemeinschaft stattdessen durch unerschütterliche Wachsamkeit und kriegerische Pflichterfüllung dienen."},sec={{t="Ein Wächter ohne Magie",b="Hoch über Thendal dient Halaan Hawk-Eye seinem Volk ohne die Gaben, die vielen Skyborne gemein sind. Er kann weder die arkane Macht nutzen, die durch die Leylinien unter der Insel Zephras fließt, noch kann er durch die mystische Himmelssicht zwischen die Welten blicken. Stattdessen verlässt sich Halaan vollkommen auf seine scharfen natürlichen Sinne. Von seinem Aussichtspunkt auf dem Wachturm aus sucht er den Horizont ab, um die Ankerpylone der Insel zu beobachten, und macht auf deren zunehmend unberechenbare und unbeständige arkane Energien aufmerksam."}},faq={{q="Wer ist Halaan Hawk-Eye?",a="Halaan Hawk-Eye ist ein Wachposten der Skyborne, der auf dem Wachturm über Thendal auf der Insel Zephras stationiert ist. Er beobachtet das umliegende Land und warnt Abenteurer vor der unberechenbaren Magie, von der die Ankerpylone der Insel befallen sind.",al={"halaan hawkeye","wer ist halaan","thendal wachturm nsc"}},{q="Was unterscheidet Halaan von anderen Skyborne?",a="Im Gegensatz zu vielen seiner Artgenossen besitzt Halaan weder die mystische Himmelssicht, die den Schleier zwischen den Welten durchdringt, noch die angeborene Fähigkeit, die unterirdischen Leylinien der Insel Zephras zu nutzen. Er verlässt sich stattdessen auf seine scharfe physische Sehkraft und natürliche Beobachtungsgabe.",al={"halaan fähigkeiten","kann halaan magie wirken","halaan himmelssicht"}},{q="Warum macht sich Halaan Sorgen um die Ankerpylone?",a="Halaan wacht über die fernen Ankerpylone und hat bemerkt, dass ihr magischer Ausstoß sprunghaft und unbeständig geworden ist, was eine unbekannte Gefahr für die Stabilität der Insel Zephras darstellt.",al={"was stimmt mit den pylonen nicht","anker von zephras problem"}},{q="Wo kann ich Halaan Hawk-Eye finden?",a="Er befindet sich auf der Spitze des hölzernen Wachturms in Thendal auf der Insel Zephras und blickt über den Horizont.",al={"wo ist halaan","halaan aufenthaltsort"}}},fx={d6a0f6c4={q="Auf wessen Seite steht Halaan Hawk-Eye?",a="Halaan ist einer der Himmelsgeborenen und steht auf der Insel Zephras an der Seite seiner Sippe. Da ihm die angeborene Leylinien-Zauberei und die überirdische Fernsicht seiner Artgenossen fehlen, dient er seinem Volk dennoch treu, indem er über Thendal wacht und Reisende vor der schleichenden Instabilität warnt, die ihre Heimat bedroht.",al={"fraktion von halaan","seite von halaan hawk-eye","wem dient halaan"}},e8313a77={q="Warum ist Halaan Hawk-Eye am Wachturm stationiert?",a="Halaan hält oben auf dem Turm von Thendal Wache, weil er nicht auf die örtlichen Leylinien zurückgreifen oder magische Fernsicht wie andere Himmelsgeborene nutzen kann. Stattdessen nutzt er seine scharfe natürliche Sehkraft, um die Insel Zephras zu überblicken und die fernen Ankerpylone zu überwachen, während deren magische Stabilität zu schwanken beginnt.",al={"warum ist halaan hawk-eye hier","warum ist halaan am wachturm","standortgrund von halaan"}}},fp="15,358,24.509.0,23.227.0,48.260.0,46.185.0,33.117.0"}
P.entries["npc:hamhock"] = {n="Hamhock",s="Hamhock ist ein gewaltiger zweiköpfiger Oger, der in den Tiefen des Verlieses von Sturmwind eingesperrt ist. Unter der Hauptstadt neben abgebrühten Defias-Aufständischen und Halsabschneidern weggesperrt, ragt er als besonders brutaler und unerwarteter Insasse inmitten des Gefängnisaufstands hervor.",h="Hamhock ist ein gewaltiger zweiköpfiger Oger, der in den Tiefen des Verlieses von Sturmwind eingesperrt ist.",kw={"dämmerwald","hamhock","oger","gefängnis","splinter fist","das verlies","sturmwind","zweiköpfig"},ang={["class:Warrior"]="Um Hamhock zu bezwingen, muss man seiner rohen, wuchtigen Kraft in den engen Korridoren des Gefängnisses direkt entgegentreten.",["faction:Alliance"]="Einen ungebundenen zweiköpfigen Oger direkt unter den Straßen der Hauptstadt vorzufinden, unterstreicht, wie katastrophal die Stadtwachen die Kontrolle über das Verlies verloren haben."},sec={{t="Ein Rohling hinter Gittern",b="Das Verlies von Sturmwind wurde erbaut, um Kleindiebe, Mörder und politische Dissidenten festzuhalten, was einen hoch aufragenden zweiköpfigen Oger zu einer furchterregenden Erscheinung zwischen den Zellen macht. Als die Gefangenen aufbegehrten und die Kontrolle über die Einrichtung übernahmen, verschanzte sich Hamhock inmitten des Chaos und zerschmettert jeden, der töricht genug ist, in seinen Zellentrakt einzudringen."},{t="Dunkle Herkunft",b="Die Behörden von Sturmwind führen kaum öffentliche Aufzeichnungen darüber, wie Hamhock gefangen genommen wurde. Unter den Wachen und Stadtbewohnern wird weitgehend vermutet, dass er vom Clan der Splinter Fist aus dem Ogerhort Vul'Gol im Dämmerwald nach Norden geschleppt worden sein könnte. Andere vermuten, dass er als Söldnermuskel in die Bruderschaft der Defias rekrutiert wurde, bevor er der Stadtwache in die Hände fiel."}},faq={{q="Wer ist Hamhock?",a="Hamhock ist ein elitärer zweiköpfiger Oger-Gefangener, der im Verlies von Sturmwind festgehalten wird. Inmitten des von den Sträflingen der Defias angeführten Aufstands fungiert er als gefährliches Hindernis tief in den Gefängniskorridoren.",al={"hamhock","wer ist der oger im verlies","oger boss verlies"}},{q="Wie landete ein Oger im Verlies von Sturmwind?",a="Offizielle Aufzeichnungen enthalten keine Einzelheiten zu seiner Gefangennahme, aber es wird weithin angenommen, dass er entweder ein gefangener Rohling des im Dämmerwald ansässigen Clans der Splinter Fist ist oder ein von der Bruderschaft der Defias angeheuerter Schläger, der bei ungesetzlichen Umtrieben erwischt wurde.",al={"warum sitzt hamhock im gefängnis","wie wurde hamhock gefangen genommen","warum ist ein oger im verlies"}},{q="Ist Hamhock mit den aufständischen Defias verbündet?",a="Obwohl die gesamte Einrichtung unter den Rädelsführern der Defias in Aufruhr geraten ist, bleibt unklar, ob Hamhock sich wirklich mit ihnen abspricht oder einfach nur das ungezügelte Chaos der aufgebrochenen Zellen genießt.",al={"gehört hamhock zur defias","hamhock bruderschaft der defias","arbeitet hamhock für bazil"}},{q="Ist Hamhock mit den Ogern im Dämmerwald verwandt?",a="Viele glauben, dass er aus dem Ogerhort Vul'Gol im Dämmerwald stammt, womit er vor seiner Gefangennahme und Überführung nach Sturmwind zum von Zzarc'Vul angeführten Clan der Splinter Fist gehört hätte.",al={"ist hamhock splinter fist","hamhock vulgol","vul'gol oger verlies"}},{q="Ist Hamhock an ein bestimmtes Kopfgeld oder eine Quest gebunden?",a="Es sind weder offizielle Kopfgelder noch städtische Haftbefehle speziell auf Hamhocks Kopf ausgesetzt. Er ist eine beiläufige Bedrohung, auf die Abenteurer stoßen, während sie die aufrührerische Festung säubern.",al={"hamhock quest","gibt es eine quest für hamhock","hamhock kopfgeld"}},{q="Warum sind zweiköpfige Oger von Bedeutung?",a="Zweiköpfige Oger besitzen unterschiedliche Persönlichkeiten in ihren Köpfen und sind oft gerissener oder magisch begabter als ihre einköpfigen Artgenossen, was Hamhock für gewöhnliche Gefängniswärter außergewöhnlich gefährlich macht.",al={"zweiköpfiger oger lore","warum zwei köpfe"}}},fp="7,255,19.324.0,13.366.0,15.192.0,49.243.0,42.197.0,44.185.0,48.179.0,37.209.0"}
P.entries["npc:hana-zua"] = {n="Hana'zua",s="Hana'zua ist ein Späher der Dunkelspeertrolle, der im Tal der Prüfungen stationiert ist und den giftigen Bestien zum Opfer fiel, die auf den Schluchtenkämmen lauern. Geschwächt und verwundet durch den monströsen Skorpiden Sarkoth liegt er da und wartet auf die Hilfe junger Initianden der Horde, die ihren Mut beweisen wollen.",h="Hana'zua ist ein Späher der Dunkelspeertrolle, der im Tal der Prüfungen stationiert ist und den giftigen...",kw={"dunkelspeere","durotar","hana'zua","hanazua","sarkoth","skorpid","das tal der prüfungen"},ang={["faction:Horde"]="Hana'zuas Überleben und seine Vergeltung dienen als eine der ersten Prüfungen der Loyalität und Kampfbereitschaft für angehende Champions der Horde.",["race:Troll"]="Für Initianden der Dunkelspeere, die ihre Reise in Durotar gerade erst beginnen, unterstreicht das Auffinden eines verwundeten Volksgenossen die tödliche Natur der hiesigen Tierwelt und die Notwendigkeit, ihre neugewonnenen Verbündeten zu beschützen."},sec={{t="Ein dem Gift erlegener Späher",b="Als er die trockenen Anhöhen über dem Tal der Prüfungen durchquerte, stieß Hana'zua auf Sarkoth, einen außergewöhnlich bösartigen und giftigen Skorpiden, der die Klippen heimsucht. Von der Bestie überwältigt und gestochen, überlebte der Troll die Begegnung nur knapp. Unfähig, sich zu bewegen oder aus eigener Kraft ins Lager zurückzukehren, siecht er im Staub dahin und hofft darauf, dass vorbeikommende Rekruten die Kreatur zur Strecke bringen und Nachricht über seine Notlage zum Höhlenbau überbringen."}},faq={{q="Wer ist Hana'zua?",a="Hana'zua ist ein Dunkelspeertroll, der verletzt im Tal der Prüfungen in Durotar aufgefunden wird. Er geriet in einen Hinterhalt und wurde vergiftet, als er Bestien auf den Kämmen aufspürte.",al={"hanazua","wer ist hanazua","verletzter troll tal der prüfungen"}},{q="Was ist mit Hana'zua geschehen?",a="Er wurde von Sarkoth niedergestreckt, einem großen und tödlichen Skorpiden, der auf den Felsen über dem Übungsgelände lauert. Dessen wirksames Gift setzte ihn außer Gefecht, sodass er nicht mehr an einen sicheren Ort zurückkehren konnte.",al={"warum ist hanazua verletzt","wer hat hanazua vergiftet","hanazua verletzung"}},{q="Worum bittet er Reisende?",a="Hana'zua bittet fähige Abenteurer darum, seine Verwundung zu rächen, indem sie Sarkoth erschlagen, die Klaue der Bestie als Beweis sammeln und den Ausbildern im Höhlenbau von seinem Zustand berichten.",al={"hanazua quest","was will hanazua"}}},fx={eb2d80d7={q="Auf wessen Seite steht Hana'zua?",a="Hana'zua ist der Horde und seinen Darkspear-Trollen treu ergeben. Wie andere junge Orcs und Trolle, die durch das Tal der Prüfungen kommen, wagte er sich in die Proving Grounds, um seine Stärke und seine Bereitschaft zu demonstrieren, Thralls neuer Nation zu dienen.",al={"fraktion von hanazua","wem dient hanazua","ist hanazua horde"}}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="Hands Federspross",s="Hands Federspross ist ein geschäftiger Gnom, der am Eingang der Eisklamm in Dun Morogh stationiert ist. Er koordiniert Lieferungen zwischen den abgelegenen Übungsgeländen des Coldridgetals und dem Ort Kharanos, auch wenn die jüngsten Überfälle der Troggs seine Bemühungen schwer beeinträchtigt haben.",h="Hands Federspross ist ein geschäftiger Gnom, der am Eingang der Eisklamm in Dun Morogh stationiert ist.",kw={"coldridgepass","das coldridgetal","dun morogh","hands federspross","kharanos","springsprocket","vorräte für tannok"},ang={["faction:Alliance"]="Hands sorgt dafür, dass die lebenswichtigen internen Nachschublinien zwischen den zwergischen Rekruten im Coldridgetal und den Siedlungen tiefer in Dun Morogh aufrechterhalten werden.",["race:Gnome"]="Für gnomische Flüchtlinge, die aus Gnomeregan vertrieben wurden, verkörpert Hands die stille Entschlossenheit der Gnome, sich an der Seite ihrer zwergischen Verbündeten in den lokalen Handel und die Logistik von Dun Morogh einzubringen."},sec={{t="Ein Engpass im Pass",b="Am Eingang der Eisklamm gelegen, sieht Hands Federspross seine regelmäßigen Nachschublieferungen völlig zum Erliegen gebracht. Normalerweise liefert er Vorräte an die Brauerei Donnerbräu und das Gasthaus in Kharanos, doch feindselige Felsbackentroggs haben den unterirdischen Tunnel überrannt, der aus dem Tal hinausführt. Da Handel und Fußverkehr durch die Bestien lahmgelegt wurden, ist Hands darauf angewiesen, dass fähige Reisende wichtige Kisten durch den gefährlichen Gebirgskorridor tragen."}},faq={{q="Wer ist Hands Federspross?",a="Er ist ein der Allianz angehörender Gnom, der im Coldridgetal direkt vor dem Eingang zur Eisklamm stationiert und dafür zuständig ist, Vorräte in die tiefer gelegenen Gebiete von Dun Morogh zu befördern.",al={"wer ist hands federspross","hands federspross lore","wer ist dieser gnom"}},{q="Warum braucht er Hilfe beim Transport von Vorräten?",a="Der Pass, der das Coldridgetal mit dem Rest von Dun Morogh verbindet, wird von bösartigen Felsbackentroggs heimgesucht, was Routinetransporte ohne bewaffnete Eskorte oder fähige Abenteurer zu gefährlich macht.",al={"warum braucht hands hilfe","coldridgepass vorräte","warum stecken die vorräte fest"}},{q="Wohin sollen seine Vorräte geliefert werden?",a="Er organisiert regelmäßige Lieferungen nach Kharanos, darunter Waren für Tannok Frosthammer und die örtlichen Gastwirte, die auf regelmäßigen Nachschub von jenseits der schneebedeckten Gipfel angewiesen sind.",al={"wohin gehen die vorräte","hands versorgungsroute","wer bekommt die kiste"}}},fx={d7333ab8={q="Auf wessen Seite steht Hands Federspross?",a="Hands ist ein loyales Mitglied der Allianz und ein Freund des Zwergenvolkes von Dun Morogh. Wie viele Gnome, die durch die Tragödie in Gnomeregan vertrieben wurden, arbeitet er eng mit seinen Verbündeten aus Eisenschmiede zusammen, kümmert sich um Logistik und Lieferungen, um lokale Gemeinschaften wie Kharanos zu unterstützen.",al={"fraktion von hands federspross","ist hands federspross allianz"}},["8576a218"]={q="Was will Hands Federspross?",a="Hands möchte, dass seine Lieferungen sicher durch die Eisklamm zu Tannok Frosthammer in der Brauerei Donnerbräu in Kharanos gebracht werden. Der jüngste Ansturm feindseliger Felskiefertrogge im gesamten Tunnel hat seine Lieferungen völlig zum Erliegen gebracht, weshalb er verzweifelt einen Abenteurer sucht, der bereit ist, die Kiste durch die Gefahr zu tragen.",al={"was will hands","ziel von hands federspross"}},d21580a2={q="Mit wem ist Hands Federspross verbunden?",a="Hands treibt regelmäßig Geschäfte mit Tannok Frosthammer, dem Gastwirt der Brauerei Donnerbräu in Kharanos. Wann immer im Tiefland Vorräte benötigt werden, koordiniert Hands die Lieferungen durch die Passstraße und verlässt sich auf Reisende, um die Lücke zu schließen, wenn die Straße gefährlich wird.",al={"mit wem arbeitet hands zusammen","verbindungen von hands federspross"}}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:hansel-heavyhands"] = {n="Hansel Bleihand",s="Hansel Bleihand ist ein ungewöhnlich massiger Dunkeleisenzwerg, der bei der Thoriumbruderschaft auf der Thoriumspitze in der Sengenden Schlucht stationiert ist. Von den Aufsehern des Außenpostens mit gefährlicher Feldarbeit betraut, delegiert er gefährliche Aufträge mit einer bunten Reihe kleinlicher körperlicher Beschwerden stets an vorbeikommende Abenteurer. Seine gewaltige Statur sticht unter seinen Artgenossen hervor, auch wenn seine Begeisterung für die Feldarbeit nicht seiner Größe entspricht.",h="Hansel Bleihand ist ein ungewöhnlich massiger Dunkeleisenzwerg, der bei der Thoriumbruderschaft auf der...",kw={"der kessel","dunkeleisenzwerg","hansel bleihand","incendosaurier","lavaspinne","sengende schlucht","thoriumbruderschaft","thoriumspitze"},ang={["faction:Alliance"]="Obwohl die Allianz gewöhnlich mit den Loyalisten der Dunkeleisenzwerge aneinandergerät, heißt die Thoriumbruderschaft jeden mit starken Armen willkommen, was Hansel zu einer praktischen Quelle für lokale Kopfgelder macht.",["faction:Horde"]="Reisende der Horde werden durch Hansels bloße Masse an einen Orc oder Tauren erinnert, doch sein Widerwille gegenüber ehrenhaftem Kampf dürfte sicherlich für Verwunderung sorgen.",["race:Dwarf"]="Bronzebeard- und Wildhammerzwerge mögen über Hansels kolossalen Körperbau staunen – oder spotten – und sich fragen, wie ein Dunkeleisenzwerg zu solch gewaltigen Ausmaßen heranwachsen konnte, während er seine Tage damit verbringt, echter Arbeit aus dem Weg zu gehen."},sec={{t="Ein Riese unter Zwergen",b="Selbst für die breitschultrigen Maßstäbe des Dunkeleisen-Clans ist Hansel Bleihand eine Ausnahmeerscheinung. Er überragt seine Brüder mit einem massiven Körperbau, der in Breite und Höhe fast an einen Orc heranreicht, und seine schiere physische Präsenz lässt auf einen Krieger schließen, der für das Gemetzel an vorderster Front geschaffen ist. Doch trotz seines imposanten Körpers und seines ehrfurchtgebietenden Namens scheint Hansel an unnötiger körperlicher Anstrengung gänzlich uninteressiert zu sein und zieht die relative Sicherheit des Lagers der Thoriumbruderschaft hoch über der Vulkanasche vor."},{t="Meister der Ausreden",b="Taskmaster Scrange und Master Smith Burninate weisen Hansel häufig die unliebsame Pflicht zu, die feurigen Bestien zu dezimieren, die in den Schlackegruben darunter lauern. Wird er angewiesen, die räuberischen Incendosaurier zu beseitigen, die durch den Kessel kriechen, weigert sich Hansel unter Verweis auf schmerzende Füße. Wenn ihm befohlen wird, die Greater Lava Spiders auszurotten, die das sengende Ödland heimsuchen, behauptet er, der verfluchte Vulkankamm leide unter einem 'eisigen Klima', das ihm eine elende Erkältung eingebracht habe. Folglich findet jeder Söldner, der bereit ist, den Magmaströmen zu trotzen, in Hansel jemanden mit einem offenen Auftrag."}},faq={{q="Wer ist Hansel Bleihand?",a="Hansel Bleihand ist ein Dunkeleisenzwerg, der der Thoriumbruderschaft angehört. Er ist auf der Thoriumspitze in der Sengenden Schlucht stationiert und für seine verblüffend enorme Körpergröße sowie sein unheimliches Geschick bekannt, gefährlicher Feldarbeit aus dem Weg zu gehen.",al={"wer ist hansel","hansel bleihand lore","hansel zwerg"}},{q="Warum ist Hansel so viel größer als andere Zwerge?",a="Für seine Masse gibt es keine eindeutige Erklärung. Hansel ist schlicht ein abnormal gigantischer Dunkeleisenzwerg mit breiten Schultern, kräftigen Gliedmaßen und einer Gesamtstatur, die fast an die eines Orcs heranreicht.",al={"warum ist hansel so groß","riesiger zwerg sengende schlucht","orcgroßer zwerg"}},{q="Welche Aufgaben überträgt Hansel Abenteurern?",a="Hansel heuert vorbeikommende Reisende an, um die Aufgaben seiner Vorgesetzten zu erledigen. Konkret bezahlt er Söldner dafür, Greater Lava Spiders in der gesamten Sengenden Schlucht zu vernichten und Incendosaurier tief im Kessel zu jagen.",al={"hansel bleihand quests","welche quests gibt hansel"}},{q="Warum erledigt Hansel seine Pflichten nicht selbst?",a="Hansel erfindet Ausreden, wann immer Gefahr droht. Er schiebt schmerzende Füße vor, um nicht in den Kessel hinabzusteigen und gegen Incendosaurier zu kämpfen, und klagt darüber, dass die glühend heiße Sengende Schlucht kalt genug sei, um ihm eine Erkältung zu verpassen, wenn er Lavaspinnen jagen soll.",al={"warum kämpft hansel nicht","hansel ausreden"}},{q="Ist Hansel dem Dunkeleisenkaiser treu ergeben?",a="Hansel gehört der Thoriumbruderschaft an, einer abtrünnigen Fraktion von Dunkeleisenzwergen, die sich von Imperator Dagran Thaurissan und Ragnaros losgesagt hat. Er verhält sich gegenüber Reisenden von Allianz und Horde, die die Thoriumspitze besuchen, neutral.",al={"ist hansel schattenschmiede treu","ist hansel ein feind"}},{q="Wo ist Hansel Bleihand zu finden?",a="Er befindet sich auf der Thoriumspitze, dem felsigen Außenposten auf dem nördlichen Kamm mit Blick auf die Sengende Schlucht.",al={"hansel standort","wo ist hansel"}}},fp="17,420,21.485.0,17.557.0,25.235.0,48.192.0,43.232.0,37.254.0,41.227.0,37.110.0"}
P.entries["npc:harb-clawhoof"] = {n="Harb Klauenhuf",s="Harb Klauenhuf ist ein Tauren-Reittierzüchter, der direkt außerhalb des Dorfes der Bluthufe in Mulgore stationiert ist. Er kümmert sich um die robusten Kodos des Stammes und bietet sie würdigen Tauren-Reitern und vertrauenswürdigen Champions von Donnerfels an.",h="Harb Klauenhuf ist ein Tauren-Reittierzüchter, der direkt außerhalb des Dorfes der Bluthufe in Mulgore...",kw={"bloodhoof","harb klauenhuf","kodotrainer","kodohändler","reittierhändler","kodo in mulgore","reittiere in donnerfels"},ang={["faction:Horde"]="Für Orcs, Trolle und Verlassene ist der Erhalt eines Kodos von Harb das ultimative Zeichen von Ehre und Freundschaft, das von den Ältesten von Donnerfels anerkannt wird.",["race:Tauren"]="Harb Klauenhuf stellt das klassische Reittier Eurer Herkunft bereit und bietet sowohl praktische Transportmöglichkeiten durch Mulgore als auch ein Symbol Eurer nomadischen Traditionen."},sec={{t="Züchter der Großen Kodos",b="In der Nähe der Gehege des Dorfes der Bluthufe verbringt Harb Klauenhuf seine Tage damit, die riesigen Kodobestien zu pflegen, die das Rückgrat der taurischen Fortbewegung und Arbeit bilden. Diese robusten Tiere sind darauf ausgelegt, enorme Lasten über weite Strecken zu tragen, und sind für das Leben in der Steppe unerlässlich. Harb stellt sicher, dass jedes Tier gut versorgt und diszipliniert ist und nur an Reiter abgegeben wird, die den Respekt des Volkes der Tauren genießen."},{t="Reittiere der Steppe",b="Während Tauren das Vertrauen, das zum Reiten von Harbs Kodos erforderlich ist, natürlicherweise erlangen, müssen sich Außenstehende einer strengeren Prüfung unterziehen. Aufgrund ihrer enormen Größe und ihres Temperaments lassen sich Kodos nicht so leicht von jemandem lenken, der nicht mit ihrem Wesen vertraut ist. Nicht-Tauren-Verbündete, die auf einem von Harbs geschätzten Reittieren davonreiten möchten, müssen zuerst ihre Loyalität beweisen und einen ehrfürchtigen Ruf bei Donnerfels erlangen."}},faq={{q="Wo finde ich Harb Klauenhuf?",a="Harb Klauenhuf ist neben dem Kodogehege am Rande des Dorfes der Bluthufe im zentralen Mulgore stationiert, südlich von Donnerfels.",al={"standort von harb klauenhuf","wo ist harb klauenhuf","standort kodohändler"}},{q="Was verkauft Harb Klauenhuf?",a="Harb verkauft verschiedene Arten von Kodo-Reittieren, darunter normale braune und graue Kodos sowie schwer gepanzerte Große Kodos für erfahrene Reiter.",al={"was verkauft harb","harb reittiere","waren des kodohändlers"}},{q="Können Nicht-Tauren Kodos bei Harb kaufen?",a="Ja, aber nur, wenn sie einen ehrfürchtigen Ruf bei Donnerfels erlangt haben. Tauren können sie direkt erwerben, aber andere Völker der Horde müssen sich erst vor dem Stamm beweisen, bevor Harb ihnen einen Kodo anvertraut.",al={"können orcs kodos kaufen","können trolle auf kodos reiten","voraussetzung ruf für kodo"}},{q="Warum sind Kodos so wichtig für die Tauren?",a="Kodos sind kraftvolle, widerstandsfähige Kreaturen, die perfekt für die nomadische Lebensweise und die offenen Steppen im zentralen Kalimdor geeignet sind. Sie dienen als zuverlässige Lasttiere, Kriegsreittiere und für den Warentransport in der rauen Landschaft.",al={"kodo-lore der tauren","warum kodos"}}},fx={["2e2e2604"]={q="Wer ist Harb Klauenhuf?",a="Harb Klauenhuf ist ein Tauren-Kodo-Züchter und Reittierhändler, der im Dorf der Bluthufe stationiert ist. Da er bei seinem Volk dafür respektiert wird, die mächtigen Bestien von Mulgore aufzuziehen und zu pflegen, stellt er sicher, dass fähige Recken standhafte Reittiere haben, die für die Strapazen von Reisen und Schlachten in ganz Kalimdor geeignet sind.",al={"wer ist harb","hintergrund von harb klauenhuf","wer ist harb klauenhuf"}},ceacb5fa={q="Auf wessen Seite steht Harb Klauenhuf?",a="Harb ist Donnerfels und der Horde gegenüber loyal ergeben. Während er seinen Tauren-Gefährten gerne Reittiere zur Verfügung stellt, müssen Außenseiter anderer Völker der Horde ihre Hingabe beweisen und sich hohes Ansehen in Donnerfels verdienen, bevor er ihnen einen seiner geschätzten Kodos anvertraut.",al={"fraktion von harb klauenhuf","ist harb klauenhuf bei der horde","loyalität von harb klauenhuf"}},["0020906d"]={q="Was will Harb Klauenhuf?",a="Harb möchte starke, zuverlässige Kodos züchten und sie nur Reitern anvertrauen, die sie wirklich respektieren. Für die Tauren ist der Kodo nicht nur ein Lasttier, sondern das Rückgrat ihrer Zivilisation, und Harb arbeitet daran, diese heilige Partnerschaft zu bewahren.",al={"was will harb","ziel von harb klauenhuf","zweck von harb klauenhuf"}},efcee9d4={q="Warum ist Harb Klauenhuf im Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist ein zentraler Treffpunkt für junge Tauren und Reisende, die von Camp Narache aus in die weiteren Ebenen von Mulgore ziehen. Harb unterhält hier seine Ställe, wo es ausreichend offene Weideflächen gibt, um starke Kodoherden für die Verteidigung und den Wohlstand der Stämme aufzuziehen.",al={"warum ist harb in bloodhoof","warum ist harb hier","harb im dorf bloodhoof"}}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="Harken Windtotem",s="Harken Windtotem ist ein Jäger der Tauren, der im Dorf der Bluthufe in Mulgore lebt. Den Traditionen seines Volkes verschrieben, beauftragt er junge Jäger und Reisende damit, ihre Fähigkeiten im Spurenlesen und Nahrungssammeln in den goldenen Ebenen unter Beweis zu stellen.",h="Harken Windtotem ist ein Jäger der Tauren, der im Dorf der Bluthufe in Mulgore lebt.",kw={"bloodhoof","harken windtotem","mulgore","sturzfliegerjagd","tauren","windtotem"},ang={["class:Hunter"]="Für Wildnisfährtenleser, die durch das Dorf der Bluthufe ziehen, bietet Harkens Aufgabe, fliegende Sturzflieger zu erlegen, eine grundlegende frühe Prüfung der Treffsicherheit und des Sammelns von Beute.",["race:Tauren"]="Harken Windtotem verkörpert die uralte Jagdphilosophie der Tauren: Disziplin und Selbstständigkeit in den Ebenen zu beweisen und zugleich die Bestien der Erdenmutter zu ehren."},sec={{t="Jäger des Dorfes der Bluthufe",b="Nahe dem Herzen des Dorfes der Bluthufe gelegen, dient Harken Windtotem als Ausbilder und Führer für jene, die die Jagdtraditionen der Tauren erlernen. Das Leben in den Ebenen von Mulgore verlangt Respekt vor der Natur sowie das praktische Geschick, den eigenen Stamm zu ernähren. Harken prüft junge Abenteurer, indem er sie ausschickt, die einheimischen Sturzflieger zu jagen, die über den Mesas kreisen, und deren Federn zu sammeln, um die Geduld, Treffsicherheit und Fähigkeit des Jägers zur restlosen Verwertung zu beurteilen."}},faq={{q="Wer ist Harken Windtotem?",a="Harken ist ein Jäger der Tauren, der im Dorf der Bluthufe im Zentrum von Mulgore lebt. Er leitet Reisende und angehende Abenteurer beim Erlernen der grundlegenden Traditionen des Spurenlesens und der Jagd der Tauren an.",al={"harken windtotem lore","wer ist harken"}},{q="Wo ist Harken Windtotem zu finden?",a="Harken hält sich im Dorf der Bluthufe auf, einer Siedlung südlich von Donnerfels im Zentrum von Mulgore.",al={"harken aufenthaltsort","wo ist harken windtotem"}},{q="Welche Aufgaben überträgt Harken den Abenteurern?",a="Er bietet die Aufgabe Sturzfliegerjagd an, bei der er die Jäger bittet, in das Grasland von Mulgore aufzubrechen, um wilde Sturzflieger zu erlegen und deren kräftige Schwungfedern zu beschaffen.",al={"harken windtotem quests","quest sturzfliegerjagd"}},{q="Ist Harken mit Bovan Windtotem verwandt?",a="Sie teilen den Klannamen Windtotem, was auf eine Verwandtschaft innerhalb des Stammes oder der Familie hindeutet, auch wenn Harken sich weiterhin auf die lokalen Jagden des Dorfes in Mulgore konzentriert.",al={"ist harken mit bovan verwandt","verwandtschaft mit bovan windtotem"}}},fx={b6c1a716={q="Auf wessen Seite steht Harken Windtotem?",a="Harken Windtotem steht loyal zu den Tauren-Stämmen und der Horde. Er ist im Dorf der Bluthufe ansässig und konzentriert sich ganz darauf, die lokale Siedlung zu unterstützen und junge Jäger anzuleiten, während diese daran arbeiten, ihr Volk in Mulgore zu ernähren.",al={"fraktion von harken windtotem","wem dient harken","ist harken bei der horde"}},fffafcb2={q="Was will Harken Windtotem?",a="Harken sucht nach fähigen Jägern, die die lokale Population der Swoops ausdünnen und ihre Federn sammeln. Die Ebenen von Mulgore erfordern Eigenständigkeit, und indem er Jungspunde auf die Probe stellt, hilft er dabei, nützliche Materialien zu beschaffen und gleichzeitig die Fähigkeiten junger Reisender zu schulen.",al={"was will harken","ziel von harken windtotem","warum gibt harken quests"}},["4b75134c"]={q="Warum ist Harken Windtotem im Dorf der Bluthufe?",a="Als Mitglied des Windtotem-Stammes, das im Dorf der Bluthufe lebt, beaufsichtigt Harken die Jagdbemühungen in den zentralen Ebenen. Er bleibt im Dorf, um vorbeiziehende Jäger anzuleiten und sicherzustellen, dass die Tierwelt im Gleichgewicht bleibt und die Siedlung über die nötigen Ressourcen verfügt.",al={"warum ist harken hier","zweck von harken windtotem","warum ist harken in bloodhoof"}}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:harlan-bagley"] = {n="Harlan Bagley",s="Harlan Bagley ist ein menschlicher Rüstungsschmied und Händler, der aus der Lionheart Armory im belebten Handelsdistrikt von Sturmwind heraus tätig ist. Er führt seinen Laden an der Nordseite des Distriktzentrums und versorgt Bürger sowie durchreisende Abenteurer mit Waffen und Ausrüstung.",h="Harlan Bagley ist ein menschlicher Rüstungsschmied und Händler, der aus der Lionheart Armory im belebten...",kw={"rüstungsschmied","harlan bagley","lionheart armory","händler","sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Händler wie Harlan Bagley versorgen die wichtigste Hauptstadt der Allianz mit Ausrüstung und Waren, während die regulären Versorgungslinien in den umliegenden Gebieten bedroht sind."},sec={{t="Die Lionheart Armory",b="An der Nordseite des Handelsdistrikts gelegen, dient die Lionheart Armory als beständige geschäftliche Anlaufstelle im Herzen von Sturmwind. Hinter seinem Tresen verwaltet Harlan Bagley das Inventar und handelt mit Defensivausrüstung, wobei er auf ankommenden Handel und regionale Kuriere angewiesen ist, um seine Regale gefüllt zu halten, während die Hauptstadt mit fernen Grenzkonflikten und Versorgungsengpässen zu kämpfen hat."}},faq={{q="Wer ist Harlan Bagley?",a="Harlan Bagley ist ein menschlicher Ladenbesitzer und Händler, der die Lionheart Armory leitet, ein Ausrüstungsgeschäft im Handelsdistrikt von Sturmwind.",al={"wer ist harlan","harlan bagley lore","lionheart armory händler"}},{q="Wo kann ich Harlan Bagley finden?",a="Er befindet sich in der Lionheart Armory an der Nordseite des zentralen Platzes im Handelsdistrikt von Sturmwind.",al={"harlan bagley aufenthaltsort","wo ist harlan","lionheart armory standort"}},{q="Welche Rolle spielt er im Handel von Sturmwind?",a="Als lokaler Händler in der Hauptstadt des Königreichs versorgt Bagley andere mit Rüstungen sowie Ausrüstung und heuert gelegentlich Abenteurer an, um Lieferaufträge zu erledigen und Nachschublieferungen zu sichern, die für das Offenhalten seiner Rüstkammer unerlässlich sind.",al={"was verkauft harlan","harlan bagley geschäft"}}},fx={["13bd1b18"]={q="Auf wessen Seite steht Harlan Bagley?",a="Harlan Bagley ist ein gewöhnlicher Bürger und Handelskaufmann der Allianz, der dem Königreich Sturmwind treu ergeben ist. Er betreibt seine Geschäfte offen im Handelsdistrikt und bedient die Abenteurer, Wachen und Verteidiger, die durch die Hauptstadt ziehen.",al={"fraktion von harlan bagley","ist harlan bagley bei der allianz"}},d342d373={q="Was will Harlan Bagley?",a="Der Betrieb der Rüstkammer Löwenherz erfordert einen zuverlässigen Fluss an Rohmaterialien und handwerklichem Geschick. Harlan konzentriert sich darauf, seine Rüstkammer voll bestückt und bereit für Kunden zu halten, wobei er häufig Hilfe von Reisenden sucht, um Waren zu sichern und seine Regale aufzufüllen.",al={"was will harlan","beweggrund von harlan bagley","warum braucht harlan nachschub"}},["0eb71712"]={q="Warum ist Harlan Bagley hier?",a="Harlan betreibt die Rüstkammer Löwenherz, die sich auf der Nordseite des belebten Handelsdistrikts von Sturmwind befindet. Er bleibt hier, um den starken Zustrom an Käufern, Schmieden und Soldaten zu versorgen, die sich für Reisen durch Azeroth ausrüsten.",al={"warum ist harlan bagley in sturmwind","warum ist harlan im handelsdistrikt"}}},fp="13,269,20.388.0,21.147.0,31.120.0,47.199.0"}
P.entries["npc:harlo-barnaby"] = {n="Harlo Barnabas",s="Harlo Barnabas ist ein verwundeter Zwergenflüchtling, der sich im Hafen von Menethil aufhält. Nachdem er dem Gemetzel bei der Einnahme von Dun Modr durch den Dunkeleisenzwerge-Clan nur knapp entkommen war, warnt er nun Reisende vor der Tragödie, die sich in den nördlichen Sümpfen abgespielt hat.",h="Harlo Barnabas ist ein verwundeter Zwergenflüchtling, der sich im Hafen von Menethil aufhält.",kw={"dunkeleisenzwerge","dun modr","harlo barnabas","der hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Der Fall von Dun Modr bedroht die wichtige Landbrücke zwischen den Marschen und Arathi, wodurch Harlos Warnungen für die Streitkräfte der Allianz von entscheidender Bedeutung sind.",["race:Dwarf"]="Harlo steht als lebendige Erinnerung an den anhaltenden und blutigen Clankrieg gegen die tückischen Dunkeleisenzwerge, die versuchen, Khaz Modan vom Norden abzuschneiden."},sec={{t="Flucht aus Dun Modr",b="Harlo Barnabas lebte in Dun Modr, bis die nördliche Festung einem plötzlichen, grausamen Angriff der Dunkeleisenzwerge zum Opfer fiel. Im Chaos des Hinterhalts floh Harlo nach Süden in Sicherheit, wurde jedoch von einer verirrten Axt mitten im Rücken getroffen. Durch den Schlag bewusstlos geschlagen, überlebte er die Reise durch das Sumpfland wie durch ein Wunder und erwachte bandagiert im Hafen von Menethil. Obwohl er am Leben ist, hindern ihn seine Wunden und die Erinnerungen an das Massaker an einer Rückkehr, weshalb er Abenteurer der Allianz dazu drängt, die rauchenden Ruinen seiner einstigen Heimat zu untersuchen."}},faq={{q="Wer ist Harlo Barnabas?",a="Harlo Barnabas ist ein Zwerg aus Eisenschmiede, der im Hafen von Menethil lebt und den brutalen Angriff der Dunkeleisenzwerge auf den Außenposten Dun Modr überlebt hat.",al={"harlo barnabas","wer ist harlo","hafen von menethil zwerg"}},{q="Wie gelangte Harlo Barnabas in den Hafen von Menethil?",a="Auf der Flucht vor der Invasion von Dun Modr wurde er von einer geworfenen Axt im Rücken getroffen. Während seines Rückzugs verlor er das Bewusstsein und erwachte in Sicherheit im Hafen von Menethil in der Obhut örtlicher Heiler.",al={"wie kam harlo hierher","harlo barnabas rückenverletzung"}},{q="Was geschah mit Dun Modr?",a="Dun Modr wurde von feindseligen Dunkeleisenzwergen überrannt und verwüstet, die vom Thandol-Übergang nach Süden vordrangen, die örtlichen Zwergenverteidiger auslöschten und Überlebende in das Sumpfland trieben.",al={"fall von dun modr","was geschah in dun modr"}}},fx={["2ef93137"]={q="Auf wessen Seite steht Harlo Barnabas?",a="Harlo Barnabas ist loyal gegenüber Eisenschmiede und der Allianz. Als Überlebender des katastrophalen Angriffs auf den nördlichen Außenposten von Dun Modr steht er an der Seite seiner Zwergenbrüder der Bronzebart-Klans und sucht nach mutigen Abenteurern der Allianz, die ihm helfen, mit den Dunkeleisenzwergen fertig zu werden, die den nördlichen Pass überrannt haben.",al={"fraktion von harlo barnabas","wem dient harlo barnabas","ist harlo barnabas bei der allianz"}},["4a6adfe0"]={q="Was will Harlo Barnabas?",a="Da er immer noch seine Wunden pflegt, möchte Harlo, dass Ihr Nachrichten und Unterstützung bezüglich des Falls von Dun Modr überbringt. Er entkam knapp mit dem Leben, als die Dunkeleisenzwerge die nördliche Festung durchbrachen, und er sucht nach fähigen Kämpfern, um den Verrätern Vergeltung zu üben und das Verlorene zurückzuerobern.",al={"beweggrund von harlo barnabas","was sollst du für harlo tun","ziel von harlo barnabas quest"}}},fp="13,226,20.526.0,21.131.0,48.192.0,26.181.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="Hegnar Schlingerschuss",s="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der an der verschneiten Straße stationiert ist, die von der Eisklamm in Richtung Kharanos führt. Er betreibt einen gut besuchten Schießstand und rüstet einheimische Jäger sowie Bergsteiger mit Schusswaffen und Munition aus.",h="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der an der verschneiten Straße stationiert ist, die...",kw={"munition","coldridgepass","dun morogh","büchsenmacher","hegnar schlingerschuss","kharanos","schießstand"},ang={["class:Hunter"]="Für Schützen, die aus dem Coldridgetal in die weiteren verschneiten Gipfel von Dun Morogh aufbrechen, stellt Hegnar lebenswichtige Schrotkugeln, Munitionsbeutel und Ersatzschusswaffen bereit.",["race:Dwarf"]="Zwerge sind stolz auf ihre Handwerkskunst und Treffsicherheit, was Hegnars Schießplatz am Wegesrand zu einem natürlichen Sammelpunkt für Reisende macht, die ihren Abzugsfinger erproben wollen."},sec={{t="Ein Büchsenmacher an der Straße",b="In einem kleinen Lager zwischen der Eisklamm und Kharanos versorgt Hegnar Schlingerschuss zwergische Scharfschützen, Reisende und die örtliche Miliz. Sein Lager verfügt über einen beliebten Schießstand, an dem die Bergvölker ihre Treffsicherheit gegen die wilden Bestien schulen, die Dun Morogh durchstreifen. Die Versorgung so vieler eifriger Schützen führt dazu, dass Hegnar seine Munitionsvorräte in rasantem Tempo verbraucht, wodurch er ständig auf frische Munitionslieferungen seines Lieferanten, des Zwergeningenieurs Loslor Rudge, angewiesen ist."}},faq={{q="Wer ist Hegnar Schlingerschuss?",a="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der einen Schießstand im Freien und ein Lager am Hauptweg zwischen der Eisklamm und Kharanos betreibt.",al={"wer ist hegnar","hegnar schlingerschuss nsc","büchsenmacher in dun morogh"}},{q="Woher bezieht Hegnar seine Munition?",a="Hegnar verlässt sich auf Loslor Rudge, einen zwergischen Ingenieurslieferanten an einem anderen Ort in Dun Morogh, der die Munition herstellt und liefert, die für den Betrieb seines Schießstands benötigt wird.",al={"hegnars lieferant","wer beliefert rumbleshot","munition für rumbleshot quest"}},{q="Was tut Hegnar für die Zwerge vor Ort?",a="Er rüstet örtliche Jäger und Milizangehörige mit Schusswaffen und Schrot aus und bietet gleichzeitig Scharfschützen, die durch Dun Morogh reisen, einen Übungsplatz.",al={"warum ist hegnar hier","hegnars schießstand","rumbleshot rolle"}}},fx={f158c8ab={q="Auf wessen Seite steht Hegnar Schlingerschuss?",a="Hegnar ist fest loyal gegenüber Eisenschmiede und der Allianz. Er ist entlang der Bergstraße stationiert und rüstet die örtliche Miliz, Verteidiger und Jäger von Dun Morogh mit zuverlässigen Schusswaffen aus, um die verschneiten Pässe des Königreichs vor eindringenden Bedrohungen zu schützen.",al={"fraktion von hegnar schlingerschuss","ist hegnar bei der allianz","wem dient hegnar"}},["932ff4bf"]={q="Was will Hegnar Schlingerschuss?",a="Hegnar benötigt einen stetigen Nachschub an Munition, um seine Werkstatt und seinen Übungsplatz am Laufen zu halten. Da lokale Scharfschützen und Milizionäre ständig in seinem Lager trainieren und sich eindecken, schwinden seine Vorräte schnell, was regelmäßige Lieferungen von seinem Ingenieurspartner Loslor Rudge erfordert.",al={"was braucht hegnar","ziel von hegnar schlingerschuss","hegnar quest"}},["3c40a283"]={q="Warum ist Hegnar Schlingerschuss hier an der Straße?",a="Er hat sein Lager und seinen Schießstand entlang der viel befahrenen Straße zwischen Eisklamm und Kharanos aufgeschlagen. Dieser ideale Standort ermöglicht es ihm, sowohl frische Rekruten, die aus dem Tal kommen, als auch Patrouillen, die die zentralen Schneefelder von Dun Morogh verteidigen, auszustatten.",al={"warum ist hegnar hier draußen","standort von hegnars lager","warum hat hegnar ein lager aufgeschlagen"}}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="Henze Faulk",s="Henze Faulk ist ein zwergischer Abenteurer, der dem Tode nahe auf dem Steinkreis außerhalb von Heldenwache im Wald von Elwynn liegt. Er wurde von der Bruderschaft der Defias niedergestreckt, als er seinen Gefährten beschützte, und dient als entscheidende Prüfung für angehende Paladine, die den Umgang mit der Gabe der Wiederbelebung erlernen.",h="Henze Faulk ist ein zwergischer Abenteurer, der dem Tode nahe auf dem Steinkreis außerhalb von Heldenwache im...",kw={"defias","wald von elwynn","gazin tenorm","henze faulk","heldenwache","wiederbelebung","symbol des lebens","foliant der offenbarung"},ang={["class:Paladin"]="Henze Faulk verkörpert Eure erste wahre Prüfung göttlicher Barmherzigkeit. Ihn mit einem Symbol des Lebens von der Schwelle des Todes zurückzuholen, lehrt einen Paladin, dass das Licht nicht bloß eine Waffe für den Kampf ist, sondern eine feierliche Macht, um dem Tod zu trotzen.",["race:Dwarf"]="Einen zwergischen Volksgenossen in den Ländern der Menschen niedergestreckt zu sehen, ist eine ernüchternde Mahnung daran, dass Defias-Gesetzlose für Reisende aller Völker eine tödliche Bedrohung darstellen, nicht nur für die Einheimischen von Sturmwind."},sec={{t="Ein Opfer bei Heldenwache",b="Nahe dem uralten Steinkreis östlich von Sturmwind liegt Heldenwache, ein Ort, der oft von Defias-Banditen heimgesucht wird, die die Wälder von Elwynn durchstreifen. Henze Faulk und sein Freund Gazin Tenorm gerieten hier in einen Hinterhalt von Defias-Marodeuren. Henze begab sich selbst in Gefahr, um Gazins Überleben zu sichern, und erlag den Klingen der Banditen. Während sein Gefährte überlebte, um Hilfe aus der Kathedrale des Lichts herbeizurufen, verharrt Henzes Körper an der Schwelle zwischen Leben und Tod und wartet auf das göttliche Eingreifen eines Paladins, der ein Symbol des Lebens bei sich trägt."}},faq={{q="Wer ist Henze Faulk?",a="Henze Faulk ist ein Zwerg aus Eisenschmiede, der tödlich verwundet am Steinkreis nahe Heldenwache im Wald von Elwynn liegt. Er geriet in einen Hinterhalt und wurde von Defias-Banditen niedergestreckt, während er seinen Freund Gazin Tenorm rettete.",al={"henze faulk","zwerg bei heldenwache","sterbender zwerg elwynn"}},{q="Warum liegt Henze Faulk am Boden?",a="Henze geriet auf Reisen mit Gazin Tenorm in einen Hinterhalt der Bruderschaft der Defias. Er fing die Hauptlast des Angriffs ab, damit Gazin entkommen konnte, wodurch er tödlich verwundet zurückblieb und auf die Wiederbelebung durch einen Geweihten des Heiligen Lichts wartet.",al={"warum liegt henze im sterben","ist henze tot","henze faulk tot"}},{q="Welche Verbindung hat Henze zu Paladinen?",a="Henze ist die zentrale Gestalt bei einem Übergangsritus für junge Paladine, die sich den Prüfungen des Folianten der Offenbarung stellen. Paladin-Geweihten wird ein Symbol des Lebens anvertraut und sie werden nach Elwynn entsandt, um Henze vom Tode zurückzuholen, womit sie ihre Meisterschaft über den heiligsten Segen der Erlösung des Lichts beweisen.",al={"henze paladinquest","foliant der offenbarung zwerg"}},{q="Wer ist Gazin Tenorm?",a="Gazin Tenorm ist der Gefährte von Henze Faulk. Als die beiden von Defias-Gesetzlosen in die Enge getrieben wurden, beschützte Henze Gazin, wodurch dieser überleben und Hilfe bei der Kirche des Heiligen Lichts suchen konnte.",al={"wer ist gazin","gazin tenorm freund"}}},fx={["162be787"]={q="Auf wessen Seite steht Henze Faulk?",a="Henze Faulk ist fest mit der Allianz und dem Heiligen Licht verbündet. Als loyaler Freund und Zwergengefährte von Gazin Tenorm fiel er, während er tapfer seinen Freund vor den rücksichtslosen Gesetzlosen der Defias-Bruderschaft im Wald von Elwynn verteidigte.",al={"fraktion von henze faulk","ist henze bei der allianz","loyalität von henze faulk"}},["47ed07eb"]={q="Was will Henze Faulk?",a="Nachdem er einem bösartigen Hinterhalt der Defias-Bruderschaft zum Opfer gefallen ist, ist Henze Faulks unmittelbares Bedürfnis das Wunder des Lichts, um sein Leben zu retten. Abgesehen vom Überleben war seine selbstlose Absicht lediglich, seinen Begleiter Gazin Tenorm vor Schaden zu bewahren.",al={"was will henze","ziel von henze faulk","aufgabe von henze faulk"}}},fp="11,281,28.507.0,19.206.0,39.223.0,39.292.0,20.184.0"}
P.entries["npc:heralath-fallowbrook"] = {n="Heralath Bachquell",s="Heralath Bachquell ist ein sterbender Nachtelfendruide, der tief im Kral der Klingenhauer gefangen gehalten wird. Ausgesandt, um das dornige Verderben rund um die Überreste des Urahnen Agamaggan zu untersuchen, wurde er vom Stamm der Razorfen gefangen genommen und misshandelt. Mit seinen letzten Atemzügen versucht er, die Nachricht von seinem Schicksal und einen geliebten Anhänger zurück zu seiner Frau nach Darnassus zu senden.",h="Heralath Bachquell ist ein sterbender Nachtelfendruide, der tief im Kral der Klingenhauer gefangen gehalten...",kw={"agamaggan","fallowbrook","henrig lonebrow","heralath","die sterblichkeit schwindet","borstennacken","kral der klingenhauer","treshala"},ang={["class:Druid"]="Einen Druidengefährten zu sehen, der an den wilden Dornen des Krals der Klingenhauer zerbrach, ist eine deutliche Erinnerung an das wilde, unnachgiebige Verderben, das sich ungehindert im südlichen Brachland ausbreitet.",["race:NightElf"]="Heralaths Anhänger zurück nach Darnassus zu bringen, ehrt einen gefallenen Bruder, der sein Leben bei dem Versuch gab, die verwundeten Länder von Kalimdor zu verstehen und zu heilen."},sec={{t="Eine tragische Mission",b="Von seinem Volk entsandt, um den uralten Ebergott Agamaggan und das wuchernde Gestrüpp zu untersuchen, das das südliche Brachland erstickt, suchte Heralath Bachquell nach der Wurzel des Verderbens im Kral der Klingenhauer. Anstatt Antworten zu finden, wurde der Nachtelf von den Borstennacken gefangen genommen. Eingesperrt in einem elenden Pferch und unerbittlich geschlagen, erlag Heralath seinen schweren Wunden und einem rasenden Fieber. Bevor er gänzlich das Bewusstsein verlor, teilte er sein Wissen mit einem Mitgefangenen, dem Zwerg Henrig Lonebrow, und drängte ihn, den Außenposten der Schildwachen in Thalanaar vor der Aggression zu warnen, die von der Borstennackenvettel Charlga Klingenflanke geschürt wird."},{t="Ein letzter Wunsch",b="Obwohl Lonebrow die Flucht gelang, war Heralath viel zu schwach, um zu fliehen. An der Schwelle des Todes in den verschlungenen Pferchen des Krals klammert sich der Druide nur lange genug an das Bewusstsein, um vorbeikommende Abenteurer anzuflehen. Er bittet nicht um Rettung, sondern darum, den Anhänger seiner Frau Treshala von seinen Peinigern wiederzubeschaffen und zurück nach Darnassus zu bringen, damit sie von seinem Schicksal erfährt und weiß, dass er bis zum Ende an sie gedacht hat."}},faq={{q="Wer ist Heralath Bachquell?",a="Heralath Bachquell ist ein Nachtelfendruide, der im Kral der Klingenhauer gefangen gehalten wird. Er reiste ins Brachland, um das Verderben der Dornen und das Erbe des gefallenen Ebergottes Agamaggan zu erforschen, wurde jedoch von den Borstennacken gefangen genommen und tödlich gefoltert.",al={"wer ist heralath","heralath bachquell","nachtelf im kral von razorfen"}},{q="Was geschah mit Heralath im Kral der Klingenhauer?",a="Nachdem er von den Borstennacken der Razorfen gefangen genommen worden war, wurde Heralath geschlagen und in einer Hütte eingesperrt. Durch die unerbittlichen Misshandlungen und Krankheit versagte sein Körper, sodass er dem Tode nahe war, als Retter ihn erreichen konnten.",al={"warum liegt heralath im sterben","was geschah mit heralath bachquell"}},{q="Worum bittet Heralath Reisende?",a="Im Wissen, dass er nicht überleben wird, fleht Heralath Abenteurer an, den Anhänger seiner Frau von den Borstennacken wiederzubeschaffen und ihn ihr mit der tragischen Nachricht von seinem Tod nach Darnassus zu bringen.",al={"heralath quest","die sterblichkeit schwindet quest"}},{q="Wer war Henrig Lonebrow für Heralath?",a="Henrig Lonebrow war ein zwergischer Gefangener, der im selben Pferch wie Heralath festgehalten wurde. Bevor Henrig die Flucht gelang, teilte Heralath lebenswichtige Informationen über Agamaggan mit ihm und bat darum, den Außenposten Thalanaar über die Umtriebe von Charlga Klingenflanke in Kenntnis zu setzen.",al={"henrig lonebrow heralath","zwerg gefangener kral von razorfen"}}},fx={["4cf4e465"]={q="Auf wessen Seite steht Heralath Bachquell?",a="Heralath ist ein Nachtelf, der Darnassus und der Allianz treu ergeben ist. Als Druide seines Volkes wagte er sich in ihrem Namen tief in das Südliche Brachland, um die seltsame Verderbnis zu verstehen, die unter den Stachelebern Wurzeln schlug, und um Kalimdor vor der Dunkelheit zu schützen, die im Kral rührt.",al={"fraktion von heralath bachquell","ist heralath bei der allianz","loyalität von heralath"}},["6e64ea11"]={q="Warum ist Heralath Bachquell im Kral der Klingenhauer?",a="Er reiste hierher, um beharrlichen Gerüchten über den gefallenen Urtum Agamaggan nachzugehen und die Ursache der Fäulnis aufzudecken, die den Kral der Klingenhauer korrumpiert. Unglücklicherweise endete seine Expedition in einer Katastrophe, als die wilden Stacheleber des Krals der Klingenhauer ihn gefangen nahmen, ihn brutaler Gefangenschaft unterwarfen und ihm tödliche Wunden zufügten.",al={"warum ist heralath hier","heralaths zweck im kral","warum kam heralath zum kral der klingenhauer"}}},fp="20,351,16.596.0,12.413.1,28.252.0,48.213.0,39.174.0,36.262.0"}
P.entries["npc:herod"] = {n="Herod",s="Herod ist ein berühmter Champion und Berserker des Scharlachroten Kreuzzugs, der die Waffenkammer im Scharlachroten Kloster befehligt. Bekannt für sein wildes kriegerisches Können und seinen unerschütterlichen Eifer, bildet er Rekruten im brutalen Nahkampf aus, der für ihren heiligen Krieg erforderlich ist. Sein Tod wird sowohl von Abtrünnigen der Allianz als auch von den Herrschern der Horde in Unterstadt angestrebt, um den militärischen Kern des Kreuzzugs zu schwächen.",h="Herod ist ein berühmter Champion und Berserker des Scharlachroten Kreuzzugs, der die Waffenkammer im...",kw={"waffenkammer","berserker","herod","raleigh der fromme","ravager","scharlachroter kreuzzug","das scharlachrote kloster","varimathras"},ang={["class:Warrior"]="Herod ist ein Paradebeispiel für einen rasenden Krieger, dessen wilde Wirbelwindschläge und rücksichtslose Aggression ihn zu einem gefürchteten kriegerischen Vorbild unter den Rekruten des Scharlachroten Kreuzzugs machen.",["faction:Alliance"]="Helden der Allianz, die dem Ruf von Raleigh dem Frommen folgen, können aus erster Hand miterleben, wie die einst edlen Verteidiger von Lordaeron unter Anführern wie Herod in einen wahnhaften, fanatischen Blutrausch verfallen sind.",["faction:Horde"]="Für die Horde und insbesondere für die Verlassenen erfüllt die Ausschaltung von Herod unmittelbar die Befehle von Varimathras, die Führung zu zerschlagen, die die Grenzen von Tirisfal bedroht."},sec={{t="Der Champion der Waffenkammer",b="In den befestigten Hallen der Waffenkammer des Scharlachroten Klosters steht Herod als Verkörperung der kriegerischen Aggression des Kreuzzugs. Im Gegensatz zu den Zauberwirkern und Paladinen, die in der Kathedrale heilige Magie kanalisieren, verlässt sich Herod auf rohe, blutrünstige körperliche Kraft. Gehüllt in Kettenrüstung und mit einer gewaltigen Zweihandaxt bewaffnet, bildet er persönlich Kohorten von Scharlachroten Auszubildenden aus und pflanzt ihnen die glühende Ergebenheit ein, jeden zu vernichten, der nicht mit ihrer fanatischen Sache verbündet ist."},{t="Ein Ziel hoher Priorität",b="Da Herod die Rüstungsgüter und die militärische Ausbildung der Frontkrieger des Kreuzzugs überwacht, ist sein Untergang für jeden unerlässlich, der den Orden zerschlagen will. Raleigh der Fromme, ein ehemaliger Kreuzfahrer in Süderstade, der von dem Wahnsinn des Ordens desillusioniert ist, fordert Herods Tod, um deren militärische Führung zu brechen. Auf der anderen Seite von Lordaeron trachtet der Schreckenslord Varimathras in Unterstadt gleichermaßen nach seiner Hinrichtung, um eine gefährliche Bastion der Menschen an der Grenze zum Territorium der Verlassenen zu beseitigen."}},faq={{q="Wer ist Herod?",a="Herod ist ein elitärer Krieger der Menschen und Kommandant der Waffenkammer im Scharlachroten Kloster. Er dient als einer der vier Hauptanführer des Klosters und ist für die Ausrüstung und den Drill der fanatischen Nahkämpfer des Kreuzzugs verantwortlich.",al={"herod lore","wer ist herod","herod scharlachrotes kloster"}},{q="Wo befindet sich Herod?",a="Herod befindet sich im Herzen des Flügels der Waffenkammer im Scharlachroten Kloster, das im nordöstlichen Tirisfal liegt. Er erwartet Herausforderer in einem zentralen Trainingsring, der von Zuschauertribünen umgeben ist.",al={"wo ist herod","herod aufenthaltsort","herod finden"}},{q="Warum will die Horde Herod tot sehen?",a="Der Schreckenslord Varimathras, der im Namen der Verlassenen in Unterstadt handelt, fordert die Vernichtung der wichtigsten Kommandanten des Klosters – einschließlich Herod –, um die verbliebene Bedrohung durch den Kreuzzug direkt vor den Toren der Hauptstadt der Verlassenen zu beseitigen.",al={"varimathras herod quest","warum horde herod tötet","ins scharlachrote kloster"}},{q="Warum will die Allianz Herod tot sehen?",a="Raleigh der Fromme, ein ehemaliges Mitglied des Scharlachroten Kreuzzugs im Vorgebirge des Hügellands, erkennt, dass der Orden in fanatischen Eifer verfallen ist. Er bittet Champions der Allianz, Herod zu beseitigen, um dem Kreuzzug seine brutale Kriegerführung zu nehmen.",al={"im namen des lichts","raleigh der fromme herod","warum allianz herod tötet"}},{q="Was geschieht, wenn Herod besiegt wird?",a="Nach Herods Niederlage strömt eine Meute junger Scharlachroter Auszubildender aus den umliegenden Baracken in den Ring, um ihren Meister zu rächen, was die tiefe Ergebenheit verdeutlicht, die er in seinen Schülern weckte.",al={"scharlachrote auszubildende","herod ansturm der auszubildenden","herod todesevent"}},{q="Was für ein Kämpfer ist Herod?",a="Herod ist eher ein Berserker und Krieger als ein traditioneller heiliger Paladin. Er setzt bösartige Sturmangriffe und weitreichende Wirbelwindschläge ein, um Feinde zu zermalmen, und verlässt sich auf puren physischen Rausch anstelle von Zaubern des Heiligen Lichts.",al={"herod kampfstil","ist herod ein paladin"}}},fx={["3c3e6bcb"]={q="Auf wessen Seite steht Herod?",a="Herod ist ein hochrangiger Kommandant der Scharlachroten Kreuzzug und einer der vier Hauptanführer, die im Scharlachroten Kloster stationiert sind. Er ist fanatisch loyal gegenüber der fanatischen Mission des Kreuzzugs und richtet dessen militärische Ausbildung und Waffenkammer gegen jeden, den der Kreuzzug als unrein oder feindselig erachtet.",al={"fraktion von herod","wem dient herod","auf welcher seite steht herod"}},["78320a40"]={q="Was will Herod?",a="Herod widmet sich der Ausbildung der nächsten Generation von Kriegern des Scharlachroten Kreuzzugs, um deren Feinde auszurotten. Er überwacht die Waffenkammer, drillt Rekruten, damit sie seinem eigenen unerbittlichen kriegerischen Eifer nacheifern, und versucht, jeden zu vernichten, der töricht genug ist, das heilige Gelände des Klosters zu betreten.",al={"herods ziel","herods zweck","was versucht herod zu tun"}},["60fea3ae"]={q="Warum ist Herod hier?",a="Herod befehligt den Flügel der Waffenkammer im Scharlachroten Kloster. Als Champion und Ausbilder der Rekruten des Kreuzzugs überwacht er dessen Arsenal und prüft persönlich jeden, der es wagt, das Kernland des Kreuzzugs herauszufordern.",al={"warum ist herod in der waffenkammer","warum ist herod im scharlachroten kloster","rolle von herod in der waffenkammer"}},f73350c1={q="Mit wem ist Herod verbunden?",a="Herod steht an der Seite der inneren Führung des Scharlachroten Klosters, zu der Hochinquisitorin Weißsträhne, Scharlachroter Kommandant Mograine und Hundemeister Loksey gehören. Gemeinsam regieren sie die Bastion des Kreuzzugs im Tirisfal.",al={"wer führt herod","verbündete von herod","mit wem arbeitet herod zusammen"}},["9c060a47"]={q="Warum ist Herod berühmt oder gefürchtet?",a="Bekannt als der Scharlachrote Champion, ist Herod für seinen wilden Berserker-Kampfstil berühmt. Er schwingt eine massive Streitaxt und ist berüchtigt dafür, sich in einen verheerenden, unaufhaltsamen Wirbel aus Stahl zu drehen, der alle nahen Feinde in Stücke reißt.",al={"warum wird herod gefürchtet","herods ruf","was macht herod gefährlich"}}},fp="5,373,26.452.0,22.488.0,13.228.0,23.200.0,35.239.0,38.254.0,36.201.1,30.210.0"}
P.entries["npc:high-executor-darthalia"] = {n="Hochexekutorin Darthalia",s="Hochexekutorin Darthalia ist eine hochrangige militärische Befehlshaberin der Verlassenen, die in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Unter der direkten Autorität von Fürstin Sylvanas Windläufer und Varimathras leitet sie die Operationen der Verlassenen gegen die Menschenfeste Süderstade und die örtlichen Banditen des Syndikats. Ihre Führung ist entscheidend für die Sicherung der südlichen Flanke der Horde in Lordaeron.",h="Hochexekutorin Darthalia ist eine hochrangige militärische Befehlshaberin der Verlassenen, die in Tarrens...",kw={"darthalia","hochexekutor","hillsbrad","vorgebirge des hügellands","süderstade","sylvanas","syndikat","tarrens mühle","varimathras"},ang={["faction:Alliance"]="Für die Menschen von Süderstade und ihre Verbündeten ist Darthalia die unbarmherzige Planerin hinter den unerbittlichen Angriffen, die ihren letzten Stützpunkt in Lordaeron bedrohen.",["faction:Horde"]="Abenteurer der Horde erstatten Darthalia Bericht, um der Aggression der Allianz Einhalt zu gebieten und die umkämpfte Grenzregion im Vorgebirge des Hügellands zu halten.",["race:Undead"]="Für die Verlassenen verkörpert Darthalia den eisernen Willen von Unterstadt und stellt sicher, dass Lordaeron fest in den Händen der Untoten mit freiem Willen bleibt."},sec={{t="Kommandantin von Tarrens Mühle",b="Von Tarrens Mühle aus dient Hochexekutorin Darthalia als operative Kommandantin für die Streitkräfte der Verlassenen im gesamten Vorgebirge des Hügellands. Ihr vorrangiges strategisches Anliegen ist es, die Ausbreitung des menschlichen Widerstands aufzuhalten, die Streitkräfte der Allianz in Süderstade in Schach zu halten und die gesetzlosen Schurken des Syndikats zur Strecke zu bringen, die das Umland heimsuchen. Jeder Offensivvorstoß in das südliche Hillsbrad unterliegt direkt ihrem Befehl."},{t="Der Krieg um Hillsbrad",b="Auf direkte Befehle der Führung von Unterstadt – der Bansheekönigin und ihres Schreckenslord-Leutnants Varimathras – überwacht Darthalia den unerbittlichen Zermürbungskrieg in Hillsbrad. Sie koordiniert Späheinsätze, gezielte Angriffe gegen die Führung der Menschen sowie Kopfgelder auf gefährliche Gesetzlose, die die Herrschaft der Verlassenen über das nördliche Lordaeron bedrohen."}},faq={{q="Wer ist Hochexekutorin Darthalia?",a="Hochexekutorin Darthalia ist eine militärische Anführerin der Verlassenen, die im Vorgebirge des Hügellands stationiert ist. Sie ist dafür verantwortlich, die militärischen Anstrengungen der Horde und der Verlassenen gegen die Menschenstadt Süderstade zu leiten und feindliche regionale Bedrohungen zu beseitigen.",al={"wer ist darthalia","darthalia identität","exekutorin darthalia"}},{q="Wo ist Darthalia zu finden?",a="Sie befehligt die Streitkräfte der Verlassenen von Tarrens Mühle aus, organisiert Truppen und koordiniert Vorstöße in der gesamten zentralen Region von Lordaeron.",al={"darthalia aufenthaltsort","wo ist darthalia","exekutorin darthalia karte"}},{q="Wem untersteht Darthalia?",a="Darthalia operiert innerhalb der direkten Militärhierarchie von Unterstadt und untersteht Fürstin Sylvanas Windläufer sowie dem Schreckenslord Varimathras, während diese die Verteidigung und Ausdehnung des Territoriums der Verlassenen koordinieren.",al={"darthalia vorgesetzter","darthalia fraktion","wer befehligt darthalia"}},{q="Welche Aufgaben überträgt Darthalia Abenteurern?",a="Darthalia beauftragt die Champions der Horde damit, direkte Angriffe gegen menschliche Siedlungen durchzuführen, gefährliche Gesetzlose hinzurichten und Mitglieder des Syndikats zu jagen, die im Vorgebirge des Hügellands ihr Unwesen treiben.",al={"darthalia quests","quests von darthalia","was will darthalia"}},{q="Warum kämpft Darthalia gegen die Menschen von Süderstade?",a="Süderstade stellt den primären militärischen Stützpunkt der Allianz in Lordaeron dar. Darthalias Mission besteht darin, die menschliche Präsenz zu unterdrücken, Tarrens Mühle zu schützen und zu verhindern, dass die Allianz nach Norden in Richtung Unterstadt vorstößt.",al={"warum süderstade angreifen","krieg um süderstade","hillsbrad konflikt"}},{q="Welchen Rang hat Darthalia im Militär der Verlassenen inne?",a="Als Hochexekutorin bekleidet Darthalia einen der höchsten Ränge der Feldkommandoebene innerhalb der Militärhierarchie der Verlassenen, was ihr das operative Kommando über die regionalen Streitkräfte, Außenposten und die Kriegsstrategie in der Zone verleiht.",al={"rang hochexekutor","darthalia titel"}}},fx={c2c985e7={q="Auf wessen Seite steht Hochexekutorin Darthalia?",a="Hochexekutorin Darthalia dient den Verlassenen und der Horde. Sie fungiert als hochrangige militärische Kommandantin unter dem Befehl von Fürstin Sylvanas Windläufer und Varimathras und leitet die Operationen der Horde im Vorgebirge des Hügellands, um die Region gegen Übergriffe der Allianz zu sichern.",al={"fraktion von darthalia","für wen kämpft darthalia","ist darthalia horde"}},["77f4a495"]={q="Was will Hochexekutorin Darthalia?",a="Darthalia will die Ausbreitung der Menschheit aufhalten und den Einfluss der Allianz im gesamten Vorgebirge des Hügellands ausrotten. Sie koordiniert Angriffe gegen nahegelegene menschliche Festungen wie Süderstade und eliminiert rivalisierende Bedrohungen wie das Syndikat, um eine unangefochtene Kontrolle der Verlassenen über das Gebiet zu gewährleisten.",al={"darthalias ziele","was versucht darthalia zu tun","darthalias zweck"}},f4963853={q="Warum ist Hochexekutorin Darthalia hier?",a="Sie ist in Tarrens Mühle stationiert, um den Feldzug der Verlassenen im Vorgebirge des Hügellands zu beaufsichtigen. Von diesem zentralen Vorposten aus organisiert sie Kriegsanstrengungen gegen die feindseligen menschlichen Siedlungen im Süden und sichert die südlichen Zugänge nach Tirisfal und zur Unterstadt.",al={"warum ist darthalia in tarrens mühle","darthalia hügelland warum","grund warum darthalia hier ist"}}},fp="23,385,24.440.0,21.364.0,31.235.0,29.129.0,29.208.0,46.198.0,51.216.0,50.207.0"}
P.entries["npc:high-executor-derrington"] = {n="Hochexekutor Derrington",s="Hochexekutor Derrington befehligt die Vorhut der Verlassenen, die am Bollwerk an der östlichen Grenze von Tirisfal stationiert ist. Als pragmatischer Militäroffizier leitet er die vorderste Verteidigungslinie der Horde gegen die Bedrohungen durch die Geißel und den Scharlachroten Kreuzzug, die von den Westlichen Pestländern ausgehen. Von dieser befestigten Barrikade aus entsendet er erfahrene Champions zu umkämpften Ruinen wie Andorhal und Scholomance.",h="Hochexekutor Derrington befehligt die Vorhut der Verlassenen, die am Bollwerk an der östlichen Grenze von...",kw={"andorhal","das bollwerk","derrington","verlassene","hochexekutor derrington","geißel","tirisfal","westliche pestländer"},ang={["class:Warrior"]="Derrington verkörpert die düstere, praktische Härte eines Frontsoldaten, der kriegerische Kompetenz und greifbare Ergebnisse auf dem Schlachtfeld über höfische Ränkespiele stellt.",["faction:Horde"]="Für Reisende der Horde, die in Tirisfal ankommen, ist Derrington der wichtigste militärische Befehlshaber, der Truppen in die gefährlichen Konflikte der Westlichen Pestländer lenkt.",["race:Undead"]="Derrington stellt das kriegerische Rückgrat des Militärs der Verlassenen dar und konzentriert sich ganz darauf, ihr zurückerobertes Land vor der Rückeroberung durch die Geißel und dem scharlachroten Fanatismus zu bewahren."},sec={{t="Kommandant an der Schwelle",b="Direkt vor den befestigten Barrikaden des Bollwerks stehend dient Hochexekutor Derrington als Torwächter zwischen der gespenstischen Sicherheit von Tirisfal und den verrottenden Schrecken der Westlichen Pestländer. Derrington hat wenig Geduld für politische Ränkespiele in Unterstadt und betrachtet die Front als Schmelztiegel des nackten Überlebens. Soldaten und Söldnern der Horde, die ihren Mut auf die Probe stellen wollen, erteilt Derrington direkte militärische Befehle und schickt Späher sowie Angriffstrupps tief in verseuchtes Gebiet, um feindliche Vorstöße abzuwehren, bevor sie Tirisfal erreichen."},{t="Ein Zweifrontenkrieg",b="Derringtons Verteidigungsposition wird von mehreren Seiten bedrängt. Im Osten lauert die Geißel, die sich in der zerstörten Stadt Andorhal verschanzt hat und sich über verseuchende Kessel über das Land ausbreitet. Gleichzeitig fechten die fanatischen Eiferer des Scharlachroten Kreuzzugs nördliche Befestigungen an und liefern sich unerbittliche Scharmützel mit Patrouillen der Verlassenen. Derrington koordiniert gezielte Gegenangriffe, Sabotageakte gegen die scharlachroten Stellungen und die systematische Zerstörung von Kesselfeldern der Geißel, um die Ostgrenze zu sichern."}},faq={{q="Wer ist Hochexekutor Derrington?",a="Hochexekutor Derrington ist der ranghöchste Kommandant der Verlassenen am Bollwerk, dem militärischen Außenposten, der Tirisfal von den Westlichen Pestländern trennt. Er koordiniert den strategischen Vorstoß der Horde nach Osten gegen die Geißel und den Scharlachroten Kreuzzug.",al={"derrington","wer ist derrington","hochexekutor derrington geschichte"}},{q="Wo befindet sich Derrington?",a="Er ist am Bollwerk stationiert, dem befestigten Engpass am äußersten östlichen Rand von Tirisfal an der Straße, die in die Westlichen Pestländer führt.",al={"wo ist derrington","derrington aufenthaltsort","hochexekutor derrington finden"}},{q="Was ist Derringtons Ziel am Bollwerk?",a="Derringtons Ziel ist es, das Überleben der Verlassenen zu sichern, indem er einen starken Verteidigungsgürtel gegen die Geißel aufrechterhält und Angriffe nach Osten in die Westlichen Pestländer führt. Er beauftragt Abenteurer damit, Andorhal auszukundschaften, Pestkessel zu deaktivieren und Operationen des Scharlachroten Kreuzzugs zu neutralisieren.",al={"was will derrington","das bollwerk zweck","derrington aufgabe"}},{q="Interessiert sich Derrington für die Politik in Unterstadt?",a="Nein. Derrington hegt offene Verachtung für höfische Ränkeschmiede und Politiker und betont, dass an der Frontlinie, wo man täglich um das Überleben kämpfen muss, kein Platz für solchen Luxus ist.",al={"derrington persönlichkeit","ist derrington politisch"}},{q="Gegen welche Hauptbedrohungen entsendet Derrington Soldaten?",a="Derrington zielt vor allem auf die Geißel ab, welche die Ruinen von Andorhal besetzt hält, auf die finsteren Nekromanten in Scholomance sowie auf nahegelegene Garnisonen des Scharlachroten Kreuzzugs, die die östlichen Nachschubwege der Horde gefährden.",al={"derrington quests","was bekämpft derrington"}},{q="Warum ist Das Bollwerk so schwer befestigt?",a="Das Bollwerk dient als wichtigster Engpass zwischen der relativen Sicherheit von Tirisfal und den aktiven Kampfzonen der Pestländer. Derringtons Truppen halten den Pass, um zu verhindern, dass gewaltige Schwärme der Geißel oder Vorstöße des Scharlachroten Kreuzzugs direkt auf Unterstadt zuströmen.",al={"warum gibt es das bollwerk","das bollwerk geschichte"}}},fx={["895ac470"]={q="Auf wessen Seite steht Hochexekutor Derrington?",a="Hochexekutor Derrington steht fest an der Seite der Verlassenen und der Horde. Als hochrangiger militärischer Kommandant unter der Dunklen Fürstin widmet er sich der Verteidigung ihres Reiches und der Sicherung ihres Platzes in Lordaeron gegen alle, die ihre Ausrottung wünschen.",al={"fraktion von derrington","wem dient derrington","ist derrington horde"}},e8355a95={q="Warum ist Hochexekutor Derrington am Bollwerk stationiert?",a="Derrington befehligt die Frontverteidigung von Tirisfal. Stationiert an der Grenze zwischen Tirisfal und den Westlichen Pestländern, überwacht er die Befestigung, die Einfälle der Geißel aufhält und den Vormarsch der Verlassenen nach Osten in das Herz der verpesteten Länder vorbereitet.",al={"warum ist derrington hier","derrington am bollwerk","warum ist derrington an der grenze"}}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:high-executor-hadrec"] = {n="Hochexekutor Hadrec",s="Hochexekutor Hadrec ist der militärische Kommandant der Garnison der Verlassenen, die im Grabmal im Silberwald stationiert ist. Von dieser zentralen Gruft aus überwacht er die Verteidigung gegen regionale Bedrohungen wie die Gnolle des Rot Hide-Klans und untersucht das Verschwinden von Spähern in der gesamten Zone. Er fungiert als leitender Offizier, der die Operationen der Horde im gesamten Silberwald lenkt.",h="Hochexekutor Hadrec ist der militärische Kommandant der Garnison der Verlassenen, die im Grabmal im...",kw={"todespirscher","insel fenris","hadrec","hochexekutor","rot hide","das grabmal","shadowfang","silberwald"},ang={["class:Rogue"]="Hadrec verlässt sich bei der Informationsbeschaffung stark auf die Todespirscher und setzt häufig heimliche Agenten ein, um vermisste Kameraden zu bergen sowie feindliches Ichor und Dokumente zu beschaffen.",["faction:Horde"]="Verbündete der Verlassenen, die aus Kalimdor eintreffen, machen bei Hadrec Meldung, um bei der Stabilisierung des Silberwalds zu helfen, und erfahren aus erster Hand, wie unsicher die Stellung der Horde im nördlichen Lordaeron nach wie vor ist.",["race:Undead"]="Für Verlassene, die aus Todesend nach Süden reisen, verkörpert Hadrec die Stimme des Oberkommandos von Unterstadt, die neugeborene Untote zu organisierten Verteidigern von Lordaeron formt."},sec={{t="Kommandant im Grabmal",b="Inmitten der Düsternis des Grabmals stationiert, leitet Hochexekutor Hadrec die militärischen Operationen der Verlassenen im gesamten Silberwald. Während Tirisfal von den Streitkräften der Dunklen Fürstin fest gesichert ist, bleibt der Silberwald voller Gefahren, umgeben von feindseligen Magiern aus Dalaran, wilden Worgen und eindringenden Gnollen. Hadrec trägt die düstere Verantwortung, das Territorium der Verlassenen zu festigen und alles auszulöschen, was die Autorität von Unterstadt südlich der Hauptstadt anfechtet."},{t="Die Rot Hide-Geißel",b="Ein Großteil von Hadrecs unmittelbarer Sorge gilt den Rot Hide-Gnollen und der Insel Fenris. Diese von der Untoten-Seuche verdorbenen Bestien haben das Todesfeld und die Ufer des Lordameresees heimgesucht und stellen eine unberechenbare und grausame Bedrohung für die Patrouillen der Verlassenen dar. Hadrec entsendet Agenten, um die verfallenen Fähren und verrottenden Gehöfte nach Hinweisen abzusuchen, festzustellen, was die Bestien stärkt, und einen direkten Angriff auf ihre Inselfestung vorzubereiten."},{t="Ein wachsames Auge auf Shadowfang",b="Neben der Gnollplage beobachtet Hadrec aufmerksam die Berichte der Todespirscher, dem verschwiegenen Spionagezweig der Verlassenen. Wenn verdeckte Ermittler in der Nähe der unheimlichen Türme von Burg Shadowfang verschwinden, beauftragt Hadrec Abenteurer damit, ihr Schicksal aufzuklären, um sicherzustellen, dass die Dunkle Fürstin über den finsteren Erzmagier Arugal und seine verfluchten Worgen informiert bleibt."}},faq={{q="Wer ist Hochexekutor Hadrec?",a="Hadrec ist ein militärischer Offizier der Verlassenen im Rang eines Hochexekutors. Er befehligt die im Grabmal stationierte Garnison, was ihn zur obersten Autorität der Verlassenen für die Operationen im Silberwald macht.",al={"hadrec lore","wer ist hadrec","kommandant des grabmals"}},{q="Wo ist Hochexekutor Hadrec zu finden?",a="Er befindet sich im Grabmal, der Siedlung der Verlassenen im zentralen Silberwald an der nördlich-südlichen Hauptstraße.",al={"hadrec aufenthaltsort","wo ist hadrec","hadrec finden"}},{q="Gegen welche Bedrohungen führt Hadrec die Spieler?",a="Hadrec führt Soldaten und Abenteurer gegen die Rot Hide-Gnolle, die das Todesfeld und die Insel Fenris heimsuchen. Er überwacht außerdem Einsätze, um vermisste Spione der Todespirscher aufzuspüren und herauszufinden, was sich im Inneren von Burg Shadowfang abspielt.",al={"hadrec quests","was macht hadrec","silberwald missionen"}},{q="Was tut ein Hochexekutor in der militärischen Struktur der Verlassenen?",a="Ein Hochexekutor ist ein hochrangiger Feldkommandant im Militär der Verlassenen, der mit der vollständigen strategischen Aufsicht über einen gesamten regionalen Außenposten oder eine Frontlinie unter der Autorität von Fürstin Sylvanas Windläufer betraut ist.",al={"hochexekutor der verlassenen","rang hochexekutor","hadrec rang"}},{q="Warum interessiert sich Hadrec für die Insel Fenris?",a="Die Insel Fenris ist zum Hauptbau der Rot Hide-Gnolle geworden. Um den Lordameresee und die umliegenden Wasserwege für die Nachschublinien der Verlassenen zu sichern, koordiniert Hadrec die Aufklärung und einen anschließenden Angriff, um die Führung der Gnolle zu zerschlagen.",al={"insel fenris hadrec","warum insel fenris angreifen","rot hide fenris"}},{q="Welche Verbindung hat Hadrec zu Burg Shadowfang?",a="Hadrec stimmt sich mit den Todespirschern ab, dem Spionageorden der Verlassenen. Wenn Späher, die in Richtung Burg Shadowfang geschickt wurden, keine Rückmeldung mehr geben, beauftragt Hadrec vertrauenswürdige Agenten damit, die Burg zu untersuchen und herauszufinden, was ihnen zugestoßen ist.",al={"burg shadowfang hadrec","hadrec arugal","todespirscher in burg schattenfang"}}},fx={["82ec3fb8"]={q="Auf wessen Seite steht Hochexekutor Hadrec?",a="Hochexekutor Hadrec dient den Verlassenen und der Dunklen Fürstin, Königin Sylvanas Windläufer, als Teil der Horde. Von seinem Posten im Grabmal aus befehligt er die militärischen Operationen der Verlassenen im Silberwald und handelt direkt im Interesse der Unterstadt.",al={"fraktion von hadrec","wem dient hadrec","hadrec horde"}},["3524c842"]={q="Was will Hochexekutor Hadrec?",a="Hadrec strebt danach, den Silberwald für die Verlassenen zu sichern und die südliche Flanke der Unterstadt zu schützen. Er koordiniert Bemühungen, um Informationen über feindliche Bewegungen zu sammeln, die Geißel der Rotfell-Gnolle, die die Region heimsucht, auszurotten und rivalisierende Bedrohungen zu eliminieren, die im gesamten Wald von der Insel Fenris bis zu den Außenbezirken von Burg Shadowfang lauern.",al={"was ist das ziel von hadrec","hadrecs motive","hadrecs ziele im silberwald"}},ed357496={q="Warum ist Hochexekutor Hadrec hier im Grabmal?",a="Hadrec ist im Grabmal stationiert, weil es als die zentrale militärische und operative Festung der Verlassenen im Silberwald dient. Als Hochexekutor überwacht er regionale Operationen, koordiniert Feldberichte der Deathstalkers und entsendet Champions, um aufkommende Bedrohungen zu neutralisieren und die Herrschaft der Verlassenen über das Gebiet zu gewährleisten.",al={"warum ist hadrec am grabmal","hadrecs standort silberwald","warum ist hadrec im silberwald"}},["4117c6ac"]={q="Mit wem ist Hochexekutor Hadrec verbunden?",a="Hadrec arbeitet eng mit der verdeckten Nachrichtendienst-Abteilung der Verlassenen zusammen, den Deathstalkers, empfängt Feldberichte und entsendet Verstärkung, um versteckte Gefahren aufzudecken. Er arbeitet auch mit lokalen Spezialisten wie Apotheker Renferrel zusammen, um regionale Bedrohungen wie die Rotfell-Gnolle zu untersuchen.",al={"verbündete von hadrec","hadrecs verbindungen","mit wem arbeitet hadrec zusammen"}}},fp="20,377,26.464.0,20.432.0,17.369.1,28.201.0,40.130.0,48.229.0,60.208.0,40.233.0,47.226.0"}
P.entries["npc:high-inquisitor-fairbanks"] = {n="Hochinquisitor Schönufer",s="Hochinquisitor Schönufer war einst ein verehrter Priester der Ritter der Silbernen Hand und ein vertrauter Berater von Hochlord Alexandros Mograine. Als ehemals bedeutender geistlicher Anführer unter den überlebenden Verteidigern von Lordaeron war sein Schicksal eng mit dem dunklen Abstieg der The Scarlet Crusade verknüpft.",h="Hochinquisitor Schönufer war einst ein verehrter Priester der Ritter der Silbernen Hand und ein vertrauter...",kw={"aschenbringer","kathedrale","schönufer","herdweiler","inquisitor","mograine","renault","das scharlachrote kloster","silberne hand","stratholme"},ang={["class:Paladin"]="Schönufer wurde Zeuge der dunkelsten Stunde der Silbernen Hand: der Tag, an dem ein geehrter Paladin eine legendäre heilige Klinge gegen seinen eigenen Vater richtete.",["class:Priest"]="Vor seinem Fall kanalisierte Schönufer zusammen mit Mograine das Heilige Licht, um die dunkle Kugel zu reinigen, die zum Aschenbringer wurde.",["faction:Alliance"]="Schönufers Tragödie lässt sich auf das gefallene Königreich Lordaeron zurückführen, wo sich die Überreste der Großen Allianz in Eiferer und Ausgestoßene aufspalteten.",["race:Undead"]="Schönufer beweist die ultimative Heuchelei der The Scarlet Crusade: Sie verstecken einen ihrer eigenen Toten hinter einem Altar, während sie unschuldige Verlassene verbrennen."},sec={{t="Berater des Aschenbringers",b="Vor dem Fall von Lordaeron war Schönufer ein respektierter heiliger Mann unter den Rittern der Silbernen Hand. Als Hochlord Alexandros Mograine eine schicksalhafte Zusammenkunft im Gasthaus von Süderstade einberief, stand Schönufer an seiner Seite und half dabei, heilige Macht in den rätselhaften Kristall zu kanalisieren, der schließlich zum Herzen des legendären Aschenbringers werden sollte. Als Prinz Arthas den Paladinorden auflöste, begleitete Schönufer Mograine zur Eisenschmiede und war Zeuge, als König Magni Bronzebeard die große Klinge schmiedete, um die Geißel zu bekämpfen."},{t="Verrat in Stratholme",b="Schönufer begleitete Alexandros Mograine, als der älteste Sohn des Hochlords, Renault, sie in einen schrecklichen Hinterhalt der Geißel vor Stratholme führte. Schönufer fiel früh unter dem Druck untoter Klauen, begraben unter Haufen verrottender Leichen. Von diesem entsetzlichen Standpunkt aus wurde er stiller Zeuge, wie Renault den gefallenen Aschenbringer ergriff und ihn in das Herz seines eigenen Vaters stieß, wodurch die heilige Klinge durch Vatermord befleckt wurde. Er überlebte das Gemetzel, kämpfte sich aus den Toten heraus und floh zurück nach Herdweiler, um Renaults Verrat aufzudecken."},{t="Hinrichtung und Verbannung",b="Schönufers verzweifelte Warnungen erschütterten die verbliebenen Verteidiger von Lordaeron. Diejenigen, die seinen entsetzlichen Bericht glaubten, verließen den fanatischen Orden, um die Argentumdämmerung zu gründen. Diejenigen, die Renault und Saidan Dathrohan treu blieben, brandmarkten Schönufer als Gotteslästerer und Wahnsinnigen. Schönufer wurde im Stillen von der The Scarlet Crusade hingerichtet. Anstatt ihm ein heiliges Begräbnis zu gewähren, entsorgten die Kreuzfahrer seinen Körper in einer versteckten Kammer hinter dem Altar der Kathedrale, wo er schließlich als genau jene Monstrosität wiederauferstand, die sie zu säubern geschworen hatten."}},faq={{q="Wo finde ich Hochinquisitor Schönufer?",a="Schönufer ist im Kathedralenflügel von Das Scharlachrote Kloster versteckt. Um ihn zu erreichen, betretet die Seitenkapelle rechts vom Hauptaltar und zieht an einer verborgenen Wandfackel, woraufhin sich ein geheimer Steindurchgang öffnet, der in eine abgelegene Krypta führt.",al={"wo ist schönufer","wie finde ich schönufer","schönufers geheimraum","geheimtür kloster"}},{q="Warum ist Schönufer ein Untoter?",a="Niemand hat genau erklärt, wie er wiederauferstand. Während des Hinterhalts bei Stratholme lag Schönufer begraben unter Haufen von Leichen der Geißel, und nachdem die The Scarlet Crusade ihn aufgrund seiner Anschuldigungen gegen ihre Anführer hinrichtete, blieb sein beiseite geworfener Körper in einer geheimen Kammer zurück, wo er schließlich als Untoter wiederauferstand.",al={"warum ist schönufer ein zombie","ist schönufer geißel","warum ist schönufer untoter"}},{q="Wer war Schönufer, bevor er hingerichtet wurde?",a="Schönufer war ein gläubiger Priester der Ritter der Silbernen Hand und der Chefberater von Hochlord Alexandros Mograine. Er half bei der Reinigung des Kristalls, der den Aschenbringer formte, und war einer der ursprünglichen geistlichen Anführer der überlebenden Verteidiger von Lordaeron.",al={"schönufers hintergrundgeschichte","wer ist hochinquisitor schönufer","schönufer lore"}},{q="Was verursachte die Spaltung zwischen der The Scarlet Crusade und der Argentumdämmerung?",a="Als Schönufer aus Stratholme zurückkehrte und berichtete, was er dort gesehen hatte, zerbrach der Orden. Diejenigen, die Schönufer glaubten und Renaults Fanatismus ablehnten, gingen fort, um die Argentumdämmerung zu gründen, während Renaults Eiferer bei der The Scarlet Crusade blieben.",al={"ursprung argentumdämmerung","warum spaltete sich die argentumdämmerung","schönufer argentumdämmerung"}},{q="Warum tötete die The Scarlet Crusade Schönufer?",a="Die Führung der The Scarlet Crusade brandmarkte seine Aussage über die Ereignisse in Stratholme als böswillige Gotteslästerung. Die Kreuzfahrer richteten ihn hin, um die Wahrheit zum Schweigen zu bringen.",al={"warum töteten die scharlachroten schönufer","wer tötete schönufer","schönufers hinrichtung"}},{q="Wer ersetzte Schönufer als Hochinquisitor?",a="Nach Schönufers Hinrichtung und heimlicher Inhaftierung stieg Sally Whitemane zur Hochinquisitorin auf und leitete zusammen mit Kommandant Renault Mograine die inquisitorischen Verhöre von Das Scharlachrote Kloster.",al={"wer ist jetzt hochinquisitor","nachfolge schönufer","wer folgte auf schönufer"}}},fx={["14cc9219"]={q="Auf wessen Seite steht Hochinquisitor Schönufer jetzt?",a="Schönufer gehört keiner Fraktion mehr an. Obwohl er einst ein verehrter Priester der Silbernen Hand und der engste Vertraute von Hochlord Alexandros Mograine war, haben sein Mord und seine anschließende Wiedererhebung als Untoter ihm seinen Verstand und seine früheren Loyalitäten geraubt. Verzehrt von der Pest des Untodes und von denselben Eiferern weggesperrt, die er einst leitete, ist er völlig feindselig gegenüber jedem Lebenden, der sein verstecktes Grab betritt, und schlägt in gedankenloser Qual und Wahnsinn um sich.",al={"fraktion von schönufer","ist schönufer feindselig","schönufers seite"}},d718e02e={q="Warum ist Schönufer im Scharlachroten Kloster versteckt?",a="Nachdem er den Verrat von Renault Mograine in Stratholme überlebt hatte, kehrte Schönufer zurück, um Renaults Vatermord vor den Eiferern in Herdweiler aufzudecken. Als Ketzer und Lügner von Renault und Saidan Dathrohan gebrandmarkt, wurde Schönufer hingerichtet, um die Wahrheit zu begraben. Die Kreuzfahrer entsorgten seinen Körper dann in einer versteckten Kammer hinter dem Altar der Kathedrale und ließen seinen wiederbelebten Leichnam heimlich versiegelt zurück.",al={"warum ist schönufer im kloster","warum in der versteckten kammer","schönufers geheime kammer"}},["46917251"]={q="Mit wem war Hochinquisitor Schönufer verbunden?",a="Schönufer war der engste Berater und Begleiter von Hochlord Alexandros Mograine, dem legendären Aschenbringer. Zusammen mit Mograine, Abbendis und Isillien half er dabei, den dunklen Kristall zu reinigen, aus dem die Klinge des Aschenbringers geschmiedet wurde. Er begleitete Alexandros nach Stratholme, wo er mit ansah, wie Mograines eigener Sohn, Renault, seinen Vater ermordete. Seine verzweifelten Bemühungen, die anderen Ritter vor Renaults Verrat zu warnen, inspirierten direkt das rechtschaffene Schisma, das sich abspaltete, um die Argentumdämmerung zu gründen.",al={"schönufers verbindungen","schönufer mograine","wem diente schönufer"}}},fp="25,278,25.520.0,22.541.1,19.526.2,43.243.0,36.317.2,41.263.0,70.264.2,43.163.2,42.219.0"}
P.entries["npc:high-priest-rohan"] = {n="Hohepriester Rohan",s="Hohepriester Rohan ist der herausragende Anführer der Kirche des Heiligen Lichts in Eisenschmiede, der in der Hall of Mysteries seine Bahnen zieht. Er überwacht die spirituelle Entwicklung angehender Priester in der gesamten Allianz und steht jenen bei, die nach Meisterschaft über das Heilige Licht streben. Durch seine Führung und heilige Relikte pflegt er spirituelle Bande zwischen dem Bergkönigreich, Sturmwind und fernen Verbündeten.",h="Hohepriester Rohan ist der herausragende Anführer der Kirche des Heiligen Lichts in Eisenschmiede, der in der...",kw={"kirche des heiligen lichts","weihrauchschwenker","grayson shadowbreaker","hall of mysteries","hohepriester rohan","eisenschmiede","mystic ward","priesterlehrer","rohan"},ang={["class:Paladin"]="Heilige Ritter, die von Lord Grayson Schattenbruch entsandt wurden, müssen Rohan aufsuchen, um seinen berühmten Weihrauchschwenker im Austausch gegen Hilfe für die Bedürftigen von Eisenschmiede zu erhalten.",["class:Priest"]="Hohepriester Rohan bietet grundlegende Führung und frühe Fähigkeiten-Ausbildung, bevor er Euch schließlich an renommierte Mentoren in Sturmwind oder Darnassus verweist, um einzigartige volksspezifische Andachten freizuschalten.",["faction:Alliance"]="Durch seine enge Zusammenarbeit mit der Kathedrale des Lichts, dem Tempel des Mondes und dem Zirkel des Cenarius hält Rohan die Geistlichkeit von Eisenschmiede eng mit der restlichen Allianz verwoben.",["race:Dwarf"]="Rohan verkörpert die zwergische Hingabe an das Heilige Licht und zeigt, dass das standhafte Volk von Khaz Modan neben seinem Titanenerbe auch eine tiefe spirituelle Überzeugung besitzt."},sec={{t="Hirte der Hall of Mysteries",b="Während er über die stillen Steinplatten der Hall of Mysteries im Mystic Ward schreitet, agiert Hohepriester Rohan als ranghöchster Vertreter der Kirche des Heiligen Lichts in Eisenschmiede. Obwohl die Zwerge historisch die Titanen verehrten, haben zwergische Priester die Tugenden des Lichts – Weisheit, Mitgefühl und Gerechtigkeit – tief verinnerlicht. Rohan dient jungen Akolythen als geduldiger Lehrer, der ihnen die Disziplin beibringt, die nötig ist, um heilige Magie zu kanalisieren und ihren Geist gegen Verzweiflung zu stählen."},{t="Brücken in der Allianz",b="Rohan weiß, dass spirituelle Erkenntnis in der Allianz viele Formen annimmt. Sobald die Priester unter seiner Vormundschaft die Grundlagen beherrschen, schickt er sie hinaus – er sendet menschliche und zwergische Schüler zu Hohepriesterin Laurena in Sturmwind oder entsendet Nachtelfen-Jünger zu Priesterin Alathea in den Tempel des Mondes in Darnassus, um schwer fassbare Mysterien wie Elunes Anmut zu meistern. Über die Hauptstädte hinaus drängt er Gläubige dazu, überall dort Hilfe zu leisten, wo Not herrscht, und schickt sogar Heiler in die Ferne, um den Druiden des Zirkels des Cenarius im entlegenen Azshara beizustehen."},{t="Der Weihrauchschwenker",b="Zusätzlich zu seinen Lehren verwahrt Rohan heilige Relikte, die für die Priesterschaft und die Paladin-Bruderschaften der gesamten Allianz unverzichtbar sind. Zu seinen Besitztümern gehört ein gesegneter Weihrauchschwenker, erprobt durch jahrelange Läuterung verruchter Geister. Wenn der Orden der Silbernen Hand und Lord Grayson Schattenbruch das Gefäß benötigen, um die heilige Berufung ihrer Ritter zu festigen, überlässt Rohan es ihnen bereitwillig – und bittet im Gegenzug lediglich um wohltätige Gaben, um Eisenschmiedes schwindende Nahrungsvorräte für die Bedürftigen der Stadt aufzustocken."}},faq={{q="Wo finde ich Hohepriester Rohan?",a="Hohepriester Rohan befindet sich in der Hall of Mysteries, die im Mystic Ward im nördlichen Teil von Eisenschmiede liegt. Er geht zwischen der heiligen Bibliothek und dem Altar auf und ab.",al={"rohan aufenthaltsort","wo ist der priesterlehrer in eisenschmiede","rohan karte","hall of mysteries priesterlehrer"}},{q="Welche Rolle hat Rohan in Eisenschmiede inne?",a="Er ist der ranghöchste Priesterlehrer in Eisenschmiede und der führende zwergische Vertreter der Kirche des Heiligen Lichts in Khaz Modan. Er bildet neue Priester aus, spendet spirituellen Rat und leitet Gläubige zu weiterführenden Studien in ganz Azeroth an.",al={"wer ist rohan","was tut rohan","rohan lore"}},{q="Warum schickt Rohan Priester nach Darnassus oder Sturmwind?",a="Rohan glaubt, dass spirituelles Wachstum das Lernen aus unterschiedlichen Traditionen erfordert. Er schickt menschliche und zwergische Initianden zur Kathedrale des Lichts in Sturmwind, um spezialisierte Gebete wie Verzweifeltes Gebet zu erlernen, und leitet Nachtelfen zurück in Darnassus' Tempel des Mondes, damit sie sich auf Elunes Anmut einstimmen können.",al={"rohan klassenquests","verzweifeltes gebet rohan","tempel des mondes quest"}},{q="Warum suchen Paladine Rohan auf?",a="Paladine, die von Lord Grayson Schattenbruch entsandt wurden, besuchen Rohan, um seinen gesegneten Weihrauchschwenker zu erhalten. Rohan überlässt das Relikt, um dem Orden der Silbernen Hand bei der Vollendung ihrer Riten zu helfen, und bittet im Gegenzug um eine bescheidene Spende an Vorräten, um die Bedürftigen von Eisenschmiede zu ernähren.",al={"paladinquest rohan","weihrauchschwenker","schwerpunkt auf opferbereitschaft"}},{q="Warum schickt Rohan Priester nach Azshara?",a="Geleitet von den Grundsätzen des Lichts bezüglich Nächstenliebe und Hilfsbereitschaft entsendet Rohan Heiler, um den Nachtelfen-Druiden des Zirkels des Cenarius beizustehen, die in den wilden, rauen Ländern von Azshara wirken.",al={"cenarushilfe rohan","rohan zirkel des cenarius"}},{q="Bildet Rohan nur Zwerge aus?",a="Rohan leitet jeden Anhänger der Allianz an, der den Pfad des Priestertums beschreitet, darunter Zwerge, Menschen und Nachtelfen. Er bietet frühe Unterweisung, bevor er sie an Mentoren weiterleitet, die auf ihre spezifischen Traditionen abgestimmt sind.",al={"können menschen bei rohan trainieren","wen bildet rohan aus"}}},fx={["077c3151"]={q="Wer ist Hohepriester Rohan?",a="Hohepriester Rohan ist das ranghöchste Mitglied der Kirche des Heiligen Lichts, das in Eisenschmiede residiert. Ein ehrwürdiger und frommer Zwerg, der als geistiger Hauptmentor für Priester innerhalb des Bergkönigreichs dient und Novizen in den Wegen der Hingabe, der Heilung und des heiligen Zorns unterweist.",al={"wer ist rohan","hohepriester rohan","hintergrund von rohan"}},["940e11c6"]={q="Auf wessen Seite steht Hohepriester Rohan?",a="Rohan steht fest an der Seite des Königreichs Eisenschmiede, der Großen Allianz und der Kirche des Heiligen Lichts. Er arbeitet eng mit dem menschlichen Klerus in Sturmwind, den Nachtelfen von Darnassus zusammen und sendet sogar Hilfe an neutrale Gruppen wie den Zirkel des Cenarius, wenn Leben gerettet werden müssen.",al={"rohans fraktion","ist rohan allianz","rohans loyalität"}},["90c6beb0"]={q="Was will Hohepriester Rohan?",a="Rohan widmet sich der Verbreitung der Tugenden des Heiligen Lichts und der Versorgung der Bedürftigen. Er versucht, Weisheit und Widerstandsfähigkeit bei jungen Priestern zu kultivieren, sich um die verarmten Bewohner von Eisenschmiede zu kümmern und überall dort Hilfe zu leisten, wo Leid unschuldige Leben in ganz Azeroth bedroht.",al={"was will rohan","rohans ziele","rohans motivationen"}},["88d280c0"]={q="Warum ist Hohepriester Rohan hier in der Hall of Mysteries?",a="Die Hall of Mysteries dient Eisenschmiede als Zufluchtsort für göttliche Studien und arkane Kontemplation. Rohan durchschreitet ihre heiligen Hallen, um das spirituelle Wohlbefinden der Stadt zu überwachen, sich um besuchte Bittsteller zu kümmern und angehende Priester persönlich zu unterweisen, bevor er sie in die weite Welt aussendet.",al={"warum ist rohan in eisenschmiede","warum ist rohan hier","rohan hall of mysteries"}}},fp="17,395,33.472.0,27.561.0,19.496.0,35.189.0,40.249.0,54.304.0,31.267.0,39.182.0,30.217.0"}
P.entries["npc:high-priestess-laurena"] = {n="Hohepriesterin Laurena",s="Hohepriesterin Laurena ist eine angesehene Priesterlehrerin der Menschen, die hinter dem großen Altar in der Kathedrale des Lichts in Sturmwind stationiert ist. Nachdem sie während des Dritten Krieges als Flüchtling der Zerstörung von Lordaeron entkommen war, unterweist sie nun angehende Priester der Allianz in spiritueller Hingabe und arkanen Schutzschutzzaubern.",h="Hohepriesterin Laurena ist eine angesehene Priesterlehrerin der Menschen, die hinter dem großen Altar in der...",kw={"arkane rückkopplung","benedictus","kathedrale des lichts","verzweifeltes gebet","hohepriesterin","das heilige licht","laurena","lordaeron","priesterlehrer","sturmwind"},ang={["class:Priest"]="Hohepriesterin Laurena fungiert als eine der wichtigsten Priesterlehrmeisterinnen in Sturmwind, führt menschliche Akolythen durch heilige Prüfungen, segnet sie mit Verzweifeltes Gebet und lehrt Methoden, feindliche Zauberwirker zu stören.",["faction:Alliance"]="Aus der Kathedrale des Lichts heraus stärkt Laurena das geistige Rückgrat der Allianz und stellt sicher, dass ihre Streiter dunkler Magie und den Schrecken der Untoten widerstehen können.",["race:Human"]="Wie viele Menschen in Sturmwind trägt auch Laurena die Trauer über das gefallene nördliche Reich Lordaeron in sich, nachdem sie sich als spirituelle Stütze für andere Überlebende ein neues Leben aufgebaut hat."},sec={{t="Ein Flüchtling aus Lordaeron",b="Bevor sie ihren Dienst in den hoch aufragenden Hallen der Kathedrale des Lichts antrat, lebte Laurena im nördlichen Königreich Lordaeron. Als die Geißel während des Dritten Krieges über das Land hinwegfegte, hatten sie und ihre gesamte Familie das Glück zu überleben und nach Süden zu fliehen, wo sie als vertriebene Flüchtlinge in Sturmwind ankamen. Trotz der unermesslichen Trauer und des Chaos, die ihre Heimat zerstörten, blieb Laurena standhaft in ihrer Hingabe und stieg schließlich im Dienst der Kirche des Heiligen Lichts zu einer Hohepriesterin auf."},{t="Die Fürsorge für die Gläubigen",b="Direkt hinter dem zentralen Altar im Heiligtum der Kathedrale widmet sich Hohepriesterin Laurena der Unterweisung aufstrebender Priester. Wenn vielversprechende Akolythen ausreichend Hingabe und Frömmigkeit zeigen, werden sie zu ihr geschickt, um ihre Studien zu vertiefen. Laurena leitet sie beim Wirken heiliger Gaben wie Verzweifeltes Gebet an und unterrichtet sie in Verteidigungskünsten, darunter Zauber, die feindliche arkane Magie auf diejenigen zurückwerfen sollen, die sie wirken. Sobald ein Initiand alles gelernt hat, was sie lehren kann, schickt sie ihn zu anderen Meisterpriestern in der gesamten Allianz weiter."}},faq={{q="Wo kann ich Hohepriesterin Laurena finden?",a="Sie steht hinter dem Hauptaltar in der Kathedrale des Lichts, die sich am Kathedralenplatz in Sturmwind befindet.",al={"laurena standort","wo ist priesterin laurena","laurena finden"}},{q="Was lehrt Hohepriesterin Laurena?",a="Laurena ist eine Priesterlehrerin. Sie vermittelt Menschenpriestern grundlegende Unterweisungen und lehrt spezialisierte Volksgebete wie Verzweifeltes Gebet sowie Schutzzauber wie Arkane Rückkopplung zur Abwehr feindlicher Zauberwirker.",al={"laurena zauber","priesterlehrer laurena","was lehrt laurena"}},{q="Woher stammte Laurena vor ihrer Zeit in Sturmwind?",a="Laurena lebte ursprünglich im Königreich Lordaeron. Während des Dritten Krieges gelang es ihrer Familie, den Schrecken der Geißel zu entkommen, und sie floh als Flüchtling nach Sturmwind, wo sie ihre religiöse Berufung fortsetzte.",al={"laurena hintergrundgeschichte","ist laurena aus sturmwind","laurena lordaeron"}},{q="Dient sie unter Erzbischof Benedictus?",a="Ja. Erzbischof Benedictus ist das geistliche Oberhaupt der Kirche des Heiligen Lichts und leitet die Kathedrale des Lichts, in der Laurena als Hohepriesterin dient.",al={"laurena und benedictus","wer ist laurenas vorgesetzter","benedictus laurena"}},{q="Warum verweist sie mich an andere Priesterlehrer?",a="Verschiedene Völker und Kulturen innerhalb der Allianz treten auf einzigartige Weise mit dem Göttlichen in Verbindung. Sobald Laurena ihren Schülern die grundlegenden Gebete des Heiligen Lichts beigebracht hat, schickt sie sie zu Meisterpriestern anderer Disziplinen – wie Zwergenmeistern in Eisenschmiede oder Nachtelfenpriesterinnen in Darnassus –, um ihren spirituellen Horizont zu erweitern.",al={"laurena schickt mich weg","furchtlos quest","elunes grace quest"}},{q="Hat Laurena ihre Familie an die Untoten verloren?",a="Bemerkenswerterweise hat ihre engste Familie den Fall von Lordaeron überlebt. Sie gehörten zu den glücklichen Flüchtlingen, denen es gelang, der Geißel unversehrt zu entkommen und die lange Reise nach Süden in die Sicherheit von Sturmwind anzutreten.",al={"laurena familie tot","was geschah mit laurenas familie"}}},fx={["22c2ed0f"]={q="Wer ist Hohepriesterin Laurena?",a="Hohepriesterin Laurena ist eine bedeutende hochrangige Priesterin innerhalb der Kirche des Heiligen Lichts. Nachdem sie während des Dritten Krieges als Flüchtling mit ihrer Familie der Zerstörung von Lordaeron entkommen ist, lebt sie nun in Sturmwind, dient hinter dem Hauptaltar in der Kathedrale des Lichts und führt vielversprechende Akolythen in ihren heiligen Pflichten.",al={"wer ist laurena","hohepriesterin laurena identität","wer ist hohepriesterin laurena"}},f0ff80a5={q="Auf wessen Seite steht Hohepriesterin Laurena?",a="Sie ist voll und ganz der Kirche des Heiligen Lichts und der Allianz ergeben. Stationiert in der Kathedrale des Lichts in Sturmwind, arbeitet sie daran, die Gläubigen des Königreichs zu betreuen, neue Priester auszubilden und die überlebenden Völker zu unterstützen, die vor der Verwüstung in ganz Azeroth Zuflucht gesucht haben.",al={"laurena loyalität","welcher fraktion gehört laurena an","wem dient laurena"}},["67770999"]={q="Was will Hohepriesterin Laurena?",a="Laurena strebt danach, die Gläubigen zu behüten und neu geweihte Priester darauf vorzubereiten, dunkler Magie und den Bedrohungen, die Azeroth plagen, zu widerstehen. Sie versucht außerdem, das Erbe und die Relikte der gefallenen nördlichen Königreiche zu bewahren, in der Hoffnung, dass die heiligen Überreste der Vergangenheit dazu beitragen können, die Lebenden vor der Geißel zu schützen.",al={"laurenas ziele","was versucht laurena zu erreichen","laurenas beweggrund"}},["7e792d03"]={q="Warum ist Hohepriesterin Laurena in der Kathedrale des Lichts?",a="Nachdem sie mit ihrer Familie dem Untergang von Lordaeron entkommen war, fand Laurena als Flüchtling Zuflucht in Sturmwind. Aufgrund ihres tiefen Glaubens und ihrer Beherrschung des Heiligen Lichts anerkannt, ließ sie sich in der Kathedrale des Lichts nieder, um vielversprechende Initiierten zu unterweisen und der Kirche dabei zu helfen, das Reich zu schützen.",al={"warum ist laurena hier","warum ist laurena in sturmwind","warum kathedrale des lichts laurena"}}},fp="22,297,22.515.0,20.585.0,40.123.0,39.227.0,45.214.0,43.166.0,48.338.0,42.203.0"}
P.entries["npc:highlord-demitrian"] = {n="Hochlord Demitrian",s="Hochlord Demitrian ist ein einsamer menschlicher Eremit, der inmitten der seltsamen Kristalle im nordwestlichen Silithus lebt. Er bezeichnet sich selbst als treuen Diener von Prinz Thunderaan und besitzt das esoterische Wissen, das erforderlich ist, um den schlummernden Elementarlord zu wecken. Abenteurer, die im Besitz alter Elementarfesseln sind, suchen ihn auf, um die Macht des Windsuchers freizuschalten.",h="Hochlord Demitrian ist ein einsamer menschlicher Eremit, der inmitten der seltsamen Kristalle im...",kw={"das kristalltal","demitrian","hochlord demitrian","silithus","thunderaan","thunderfury","gefäß der wiedergeburt","windsucher"},ang={["class:Rogue"]="Schurken, die die legendäre Klinge des Windsuchers jagen, müssen mit Demitrian in Silithus verhandeln, um den zerbrochenen Prinzen wiederherzustellen.",["class:Warrior"]="Krieger, die die legendäre Klinge Thunderfury suchen, müssen Demitrian aufsuchen, um die Prüfung der Entfesselung und Erweckung des Windsuchers einzuleiten.",["profession:Blacksmithing"]="Demitrians Forderungen für Thunderaans Wiedergeburt erfordern umfassende Meisterschaft in der Schmiedekunst, um Verzauberte Elementiumbarren aus Roherz und feurigen Essenzen zu schmieden."},sec={{t="Eremit des Kristalltals",b="Demitrian wurde in einem verlassenen Lager im Kristalltal entdeckt und wirkt in den trostlosen Einöden von Silithus deplatziert. Obwohl er mit dem Twilight's Hammer verbunden ist, deren verwüstetes Lager er bewohnt, agiert Demitrian vor allem als Herold für Prinz Thunderaan, den Windsucher. Er behandelt Besucher mit distanzierter Gleichgültigkeit, es sei denn, sie führen den Beweis für die zerbrochene Essenz des Windsuchers mit sich."},{t="Das Gefäß der Wiedergeburt",b="Demitrians Daseinszweck ist vollständig mit Thunderaans Wiederauferstehung verknüpft. Sollte ihm ein Abenteurer die Fesseln des Windsuchers präsentieren – Relikte, die Feuerelementaren im Geschmolzenen Kern entrissen wurden –, überreicht Demitrian das Gefäß der Wiedergeburt. Er verlangt seltene Elementarreagenzien, darunter große Mengen an Verzaubertem Elementium und die Essenz des Feuerfürsten, um die physische Form seines Prinzen wiederherzustellen."},{t="Verrat des Windsuchers",b="Demitrians Ritual ruft Prinz Thunderaan in das Kristalltal, wo Abenteurer sich dem wiederhergestellten Windsucher im Kampf stellen müssen. Sobald sie den Elementarlord besiegt haben, bergen sie die Schlummernde vom Wind berührte Klinge und bringen sie zum verängstigten Demitrian, der im Austausch dafür Thunderfury erweckt."}},faq={{q="Wo finde ich Hochlord Demitrian?",a="Er befindet sich in der weit entfernten nordwestlichen Ecke von Silithus, in der Nähe des Verwüsteten Twilight-Stützpunkts innerhalb des Kristalltals.",al={"demitrian standort","wo ist demitrian","demitrian silithus punkt"}},{q="Warum gibt Demitrian nur eine allgemeine Antwort?",a="Demitrian bietet seine legendäre Questreihe nicht an, sofern Ihr nicht mindestens eine Hälfte der Fesseln des Windsuchers bei Euch tragt, bei denen es sich um seltene Schätze handelt, die Baron Geddon und Garr im Geschmolzenen Kern bei sich tragen.",al={"demitrian spricht nicht mit mir","wie erhalte ich die demitrian quest","demitrian gelaber"}},{q="In welcher Beziehung steht Demitrian zu Prinz Thunderaan?",a="Demitrian ist der geschworene sterbliche Diener von Prinz Thunderaan. Er hat sich der Aufgabe verschrieben, die abgetrennten Fesseln des Prinzen zu finden und den Elementarlord auf die physische Ebene zurückzubringen.",al={"wem dient demitrian","demitrian thunderaan verbindung","ist demitrian twilight hammer"}},{q="Was passiert, wenn Ihr ihm alle Materialien für das Gefäß bringt?",a="Demitrian führt ein Ritual durch, das Prinz Thunderaan in das Kristalltal ruft und den Windsucher auf die physische Ebene zurückbringt.",al={"thunderaan beschwören","was macht demitrian mit dem gefäß","kristalltal beschwörung"}},{q="Ist Demitrian mit dem Kult des Twilight's Hammer verbunden?",a="Er ist mit dem Twilight's Hammer verbunden, bewohnt deren verwüstetes Lager und spricht voller Ehrfurcht von den Alten Göttern. Dennoch gilt seine geschworene Hingabe seinem Meister, Prinz Thunderaan.",al={"ist demitrian ein kultist","demitrian twilight stützpunkt","demitrian fraktion"}},{q="Wie erhaltet Ihr Thunderfury von ihm?",a="Demitrians Aufgabe beinhaltet die Fesseln des Windsuchers und seltene Materialien, die mit Thunderaan verbunden sind. Sie führt Abenteurer in ein Unterfangen, das in der Gefangenschaft des Elementarprinzen wurzelt.",al={"wie erhalte ich thunderfury","thunderfury quest abschluss","demitrian klinge"}}},fp="18,351,26.385.0,21.400.1,26.289.1,36.122.0,48.202.0,54.181.0,65.133.1,56.178.0,36.188.1"}
P.entries["npc:hogger"] = {n="Hogger",s="Hogger ist der bösartige Häuptling der Flusstatzen-Gnolle, die im südwestlichen Wald von Elwynn ihr Unwesen treiben. Er überragt seine Artgenossen bei Weitem, ist bemerkenswert aggressiv und berüchtigt dafür, einheimische Bauernhöfe zu überfallen und ahnungslose Reisende abzuschlachten. Seine gewalttätigen Streifzüge haben ihm ein offizielles Kopfgeld der Marschälle von Sturmwind eingebracht.",h="Hogger ist der bösartige Häuptling der Flusstatzen-Gnolle, die im südwestlichen Wald von Elwynn ihr Unwesen...",kw={"kopfgeld","defias","dughan","elwynn","gnoll","goldhain","hogger","flusstatzen"},ang={["faction:Alliance"]="Hoggers Überfälle zeigen, wie überlastet die Armee von Sturmwind ist, was die Marschälle dazu zwingt, sich auf umherziehende Abenteurer zu verlassen, um die Ordnung nahe der Hauptstadt aufrechtzuerhalten.",["race:Human"]="Für junge Verteidiger von Sturmwind ist die Konfrontation mit Hogger eine frühe Feuertaufe und eine direkte Antwort auf die Bedrohungen, die das Kernland von Elwynn destabilisieren."},sec={{t="Der Schrecken der Flusstatzen",b="Hogger lauert auf dem Hogger Hill im südwestlichen Wald von Elwynn und befehligt das dortige Rudel der Flusstatzen mit unübertroffener Grausamkeit. In den Jahren nach dem Dritten Krieg wurden die Raubzüge der Gnolle auf die örtlichen Gehöfte immer dreister und koordinierter. Hinter diesem Anstieg der Gewalt verbirgt sich ein beunruhigendes Bündnis: Die Flusstatzen haben begonnen, mit der Bruderschaft der Defias zu konspirieren, und tauschen rohe Wildheit gegen Waffen, taktische Führung und magische Unterstützung ein. Um die Grenzen von Elwynn zu sichern und die Handelswege vor weiterem Blutvergießen zu schützen, hat Marschall Dughan ein großzügiges Kopfgeld auf Hoggers Kopf ausgesetzt."}},faq={{q="Wer ist Hogger?",a="Hogger ist ein riesiger, außergewöhnlich gefährlicher Gnoll, der das Rudel der Flusstatzen im südwestlichen Wald von Elwynn anführt. Er ist bekannt für seine Überfälle auf nahegelegene Gehöfte und wird von den Behörden von Sturmwind wegen seiner brutalen Angriffe auf menschliche Siedlungen tot gesucht.",al={"hogger lore","wer ist hogger","anführer der flusstatzen"}},{q="Warum ist ein Kopfgeld auf Hogger ausgesetzt?",a="Marschall Dughan und die Wache von Sturmwind haben ein offizielles Kopfgeld auf Hogger ausgesetzt, da seine Überfälle auf ländliche Höfe und Reisende eskaliert sind. Jeder, der kühn genug ist, seinem Treiben ein Ende zu setzen, muss seine gewaltige Klaue als Beweis für die Tat nach Goldhain zurückbringen.",al={"gesucht hogger","warum hogger töten","hogger kopfgeld"}},{q="Arbeiten die Flusstatzen-Gnolle mit der Bruderschaft der Defias zusammen?",a="Ja. Die Bruderschaft der Defias konspiriert mit dem Rudel der Flusstatzen und versorgt die brutalen Gnolle mit besseren Waffen, taktischer Führung und mystischer Unterstützung, um Sturmwinds Kontrolle über die Region weiter zu schwächen.",al={"hogger defias","gnolle defias verbindung","flusstatzen defias"}},{q="Wo schlägt Hogger sein Lager auf?",a="Hogger haust auf dem Hogger Hill in den südwestlichen Ausläufern des Walds von Elwynn, umgeben von seinen treuen Flusstatzen-Rudelgefährten nahe der Grenze zu Westfall.",al={"hogger aufenthaltsort","wo ist hogger","hogger hill"}}},fx={cd1f1084={q="Auf wessen Seite steht Hogger?",a="Hogger führt die Riverpaw-Gnolle des südlichen Waldes von Elwynn an, aber sein Rudel handelt nicht allein. Sie verschwören sich mit The Defias Brotherhood und tauschen Chaos in den Wäldern gegen Waffen, taktische Führung und arkane Unterstützung. Während Gnolle hauptsächlich für Beute und Territorium kämpfen, stellt Hoggers Bündnis mit den Defias sein Rudel direkt gegen das Königreich Sturmwind und dessen Bevölkerung.",al={"hoggers seite","für wen arbeitet hogger","mit wem ist hogger verbündet"}},["3ddc17ac"]={q="Warum ist Hogger im Wald von Elwynn?",a="Hogger hat seine Festung auf einem Hügel im südwestlichen Wald von Elwynn errichtet, um die aggressive Expansion seines Rudels zu beaufsichtigen. Von diesem Lager aus überfallen die Riverpaw-Gnolle nahegelegene menschliche Farmen und Siedlungen und nutzen die überlasteten Verteidigungsanlagen des Königreichs aus, während sie sich unter dem Einfluss und der Unterstützung von The Defias Brotherhood koordinieren.",al={"warum ist hogger hier","grund für hogger im wald von elwynn","warum kam hogger hierher"}},d88533c5={q="Warum ist Hogger so gefürchtet?",a="Hogger ist im gesamten Wald von Elwynn für seine bösartige Stärke und seine gerissene Führung gefürchtet. Im Gegensatz zu gewöhnlichen umherstreifenden Gnollen ist er ein außergewöhnlich furchterregender Häuptling, der einsame Reisende und unerfahrene Abenteurer leicht überwältigt. Seine Überfälle auf lokale Gehöfte haben sich als so zerstörerisch erwiesen, dass die Marschälle von Sturmwind ihn als vorrangige Bedrohung für das Reich betrachten.",al={"warum ist hogger berühmt","warum ist hogger gefürchtet","warum ist hogger berüchtigt"}}},fp="6,312,22.569.0,14.234.0,32.237.0,60.218.0,32.149.0"}
P.entries["npc:holt-thunderhorn"] = {n="Holt Donnerhorn",s="Holt Donnerhorn ist ein Tauren-Jägerlehrer, der auf der Anhöhe der Jäger in der hochgelegenen Stadt Donnerfels stationiert ist. Er unterweist Anfänger und erfahrene Fährtenleser in ihrer Kunst, bietet grundlegende kriegerische Anleitungen und weist heranreifende Scharfschützen auf spezialisierte Prüfungen in Mulgore und darüber hinaus hin.",h="Holt Donnerhorn ist ein Tauren-Jägerlehrer, der auf der Anhöhe der Jäger in der hochgelegenen Stadt...",kw={"holt donnerhorn","die anhöhe der jäger","jägerlehrer","mulgore","donnerfels"},ang={["class:Hunter"]="Holt Donnerhorn dient als zentraler Mentor in Donnerfels und bietet Waffentechniken, Training im Fährtenlesen sowie Empfehlungen zur Tierzähhmung an.",["race:Tauren"]="Auf der Anhöhe der Jäger stationiert, verkörpert Holt die traditionelle Jagdkultur der Tauren, die die nomadischen Stämme lange bevor sie ein dauerhaftes Zuhause auf den Klippen errichteten, ernährte und beschützte."},sec={{t="Meister der Anhöhe",b="Auf der Anhöhe der Jäger hoch über den weiten Ebenen von Mulgore gelegen, dient Holt Donnerhorn der Horde als erfahrener Ausbilder in Fernkampf, Fährtenlesen und Überlebenskunst. Wie viele Älteste seines Handwerks führt er junge Tauren auf ihrem Weg vom umherziehenden Jäger hin zu disziplinierten Verteidigern ihrer neuen Hauptstadt."}},faq={{q="Wo kann Holt Donnerhorn gefunden werden?",a="Holt Donnerhorn steht auf der Anhöhe der Jäger, dem südöstlichen Hochplateau innerhalb der Taurenhauptstadt Donnerfels in Mulgore.",al={"holt donnerhorn standort","wo ist holt","jägerlehrer donnerfels"}},{q="Was lehrt Holt Donnerhorn?",a="Er ist ein Jägerlehrer, der Spielern grundlegende Treffsicherheit, Wildnisüberleben und Techniken zur Tierzähhmung beibringt sowie Neulinge an spezialisierte Tierherrschaftsprüfungen verweist.",al={"was lehrt holt","holt donnerhorn lehrer","welche fähigkeiten holt"}},{q="Welche Rolle spielen Jäger in Donnerfels?",a="Jäger bilden das traditionelle Rückgrat der Taurengesellschaft. Sie sorgen für Nahrung, patrouillieren an den territorialen Grenzen gegen Zentauren-Überfallkommandos und ehren die Erdenmutter durch ausgewogenes, ehrfürchtiges Fährtenlesen.",al={"zweck der anhöhe der jäger","tauren jäger lore"}}},fx={c3f17fe5={q="Wer ist Holt Donnerhorn?",a="Holt Donnerhorn ist ein angesehener Tauren-Jägerausbilder, der in Donnerfels auf Die Anhöhe der Jäger stationiert ist. Er widmet sich der Weitergabe der Wildniskünste der Shu'halo und unterweist junge Jäger in Treffsicherheit, Überlebenskunst und dem uralten Band zwischen Jäger und Tier.",al={"wer ist holt","holt donnerhorn lore","wer ist holt donnerhorn"}},d59405da={q="Auf wessen Seite steht Holt Donnerhorn?",a="Holt dient den Taurenstämmen von Donnerfels und der größeren Horde unter der Führung von Cairne Bluthuf. Er unterstützt jeden Jäger, der der Horde gegenüber loyal ist und danach strebt, seine Instinkte zu schärfen und die Ebenen zu ehren.",al={"holt donnerhorn fraktion","wem dient holt","ist holt bei der horde"}},["03eb281d"]={q="Warum ist Holt Donnerhorn hier?",a="Holt bleibt auf Die Anhöhe der Jäger, um neue Generationen von Spurenlesern, Schützen und Tierbändigern anzuleiten. Da die Tauren nun in Mulgore angesiedelt sind, sind geschickte Jäger unerlässlich, um die Stadt zu versorgen und die Plateaus vor feindseligen Wildtieren und Eindringlingen zu schützen.",al={"warum ist holt in donnerfels","was macht holt hier","holt donnerhorn zweck"}}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:houndmaster-loksey"] = {n="Hundemeister Loksey",s="Hundemeister Loksey ist der Offizier, der mit der Zucht und Ausbildung der furchterregenden Kriegshunde des Scharlachroten Kreuzzugs betraut ist. In den Zwingern der Waffenkammer im Scharlachroten Kloster stationiert, befehligt er Hundemeuten, um Untote, Eindringlinge und vermeintliche Ketzer zur Strecke zu bringen. Seine erbarmungslose Disziplin hat die Bestien des Klosters in ganz Tirisfal berüchtigt gemacht.",h="Hundemeister Loksey ist der Offizier, der mit der Zucht und Ausbildung der furchterregenden Kriegshunde des...",kw={"waffenkammer","hundemeister loksey","hunde","jäger leopold","zwinger","loksey","scharlachroter kreuzzug","das scharlachrote kloster"},ang={["class:Hunter"]="Loksey verkörpert einen brutalen, aggressiven Ansatz bei der Tierausbildung, der wilde Hunde durch Zwang dem Fanatismus unterwirft, anstatt ein Band gegenseitigen Respekts zu knüpfen.",["race:Undead"]="Infiltratoren der Verlassenen müssen sich vor Lokseys Hunden in Acht nehmen, da sie eigens darauf abgerichtet sind, die Witterung toten Fleisches aufzunehmen und die Garnisonen des Kreuzzugs zu alarmieren."},sec={{t="Herr der Zwinger",b="Hinter den schwer befestigten Mauern des Scharlachroten Klosters befehligt Hundemeister Loksey die Ausbildung bösartiger Spür- und Angriffshunde. Der Scharlachrote Kreuzzug verlässt sich auf diese abgerichteten Hunde, um pestverseuchte Leichen aufzuspüren, verborgene Infiltratoren zu enttarnen und jeden Überlebenden zu hetzen, der vor dem Zorn der Eiferer flieht. Loksey besitzt die uneingeschränkte Autorität über den Zwingerflügel der Waffenkammer und sorgt dafür, dass seine Schützlinge stets bereit sind, Eindringlinge Glied für Glied zu zerreißen."},{t="Familiäre Rivalität",b="Loksey ist nicht der einzige Tierführer in seiner Familie, der der Sache dient. Sein Bruder, Jäger Leopold, fungiert an der Kapelle des hoffnungsvollen Lichts als Gesandter des Scharlachroten Kreuzzugs bei der Argentumdämmerung. Leopold hält wenig von seinem Bruder und behauptet insgeheim, Loksey könne kaum seine eigenen Hunde bändigen, geschweige denn den Orden in hochrangiger Diplomatie vertreten. Trotz Leopolds Verachtung bleibt Loksey ein entscheidender Offizier in der inneren Hierarchie des Klosters."}},faq={{q="Wo ist Hundemeister Loksey zu finden?",a="Hundemeister Loksey befindet sich im Flügel der Waffenkammer des Scharlachroten Klosters im nordöstlichen Tirisfal, umgeben von seinen Angriffshunden in den Zwingern.",al={"loksey aufenthaltsort","wo ist loksey","hundemeister loksey aufenthaltsort"}},{q="Welche Rolle spielt Loksey im Scharlachroten Kreuzzug?",a="Er ist der oberste Tierführer und Hundemeister des Scharlachroten Kreuzzugs im Kloster und verantwortlich für die Zucht, Konditionierung und Führung der Kriegshunde, die eingesetzt werden, um Untote aufzuspüren und Eindringlinge zu jagen.",al={"was macht loksey","lokseys aufgabe","hundemeister pflicht"}},{q="In welcher Beziehung steht Jäger Leopold zu Loksey?",a="Jäger Leopold ist Lokseys Bruder. Leopold vertritt den Scharlachroten Kreuzzug an der Kapelle des hoffnungsvollen Lichts und blickt auf Loksey herab; er behauptet, Loksey könne weder seine Hunde ordentlich führen noch diplomatische Aufgaben bewältigen.",al={"leopold lokseys bruder","wer ist leopold","lokseys bruder"}},{q="Warum setzt der Scharlachrote Kreuzzug Hunde ein?",a="Der Kreuzzug bildet bösartige Hunde aus, um die Geißel und Verlassene über deren Geruch aufzuspüren, das Klostergelände zu bewachen und fliehende Feinde in Stücke zu reißen.",al={"warum hunde","zweck scharlachroter hunde","kreuzzug hunde"}},{q="Gilt Loksey als ein Anführer des Scharlachroten Klosters?",a="Ja, Loksey gilt als eine der zentralen Befehlsgestalten in der militärischen Struktur des Scharlachroten Klosters und überwacht den entscheidenden Zwingerbetrieb in der Waffenkammer.",al={"ist loksey ein boss","lokseys rang","wie wichtig ist loksey"}},{q="Sind die Hunde für sich genommen gefährlich?",a="Ja. Auf Aggressivität gezüchtet und von Loksey konditioniert, sind die Kriegshunde des Klosters wilde Raubtiere, die imstande sind, einen gepanzerten Eindringling innerhalb von Augenblicken Glied für Glied zu zerreißen.",al={"sind hunde stark","gefahr durch scharlachrote hunde","lokseys begleiter"}}},fx={["92e01b8b"]={q="Wer ist Hundemeister Loksey?",a="Hundemeister Loksey ist ein menschlicher Hauptmann und einer der vier Kommandanten, die sich im Das Scharlachrote Kloster aufhalten. Bekannt für seine brutale Disziplin, dient er als Zwingermeister, der für die Zucht, Konditionierung und das Hetzen der bösartigen Hunde des Kreuzzugs auf Eindringlinge und vermutete Träger der Untoten-Fäule verantwortlich ist.",al={"wer ist loksey","hundemeister loksey identität","wer ist hundemeister loksey"}},["6cbd929d"]={q="Auf wessen Seite steht Hundemeister Loksey?",a="Loksey ist dem The Scarlet Crusade unerschütterlich ergeben und dient als Frontkommandant in deren Klosterfestung. Er teilt den fanatischen Hass des Kreuzzugs auf die Untoten und jeden außerhalb ihres Zelotenordens und betrachtet jeden, der in ihre Hallen eindringt, als Eindringling, der nur dazu taugt, seinen Zwinger zu füttern.",al={"loksey fraktion","hundemeister loksey allianz","wem dient loksey"}},["1361b0af"]={q="Was will Hundemeister Loksey?",a="Loksey strebt danach, das Das Scharlachrote Kloster zu verteidigen, indem er rücksichtslose Jagdrudel ausbildet, die in der Lage sind, jeden Feind Glied für Glied zu zerreißen. Er möchte jede Spur der Untoten tilgen und das Territorium des Kreuzzugs vor Außenstehenden schützen, wobei er seine Bestien einsetzt, um Eindringlinge ohne Zögern oder Gnade zu jagen.",al={"lokseys ziel","was versucht loksey zu erreichen","hundemeister loksey beweggrund"}},["58572016"]={q="Warum ist Hundemeister Loksey hier?",a="Loksey ist im Library-Flügel des Klosters stationiert, um die Zwinger des Kreuzzugs zu beaufsichtigen. Als Hundemeister muss er sicherstellen, dass die Hunde scharf, aggressiv konditioniert und jederzeit bereit sind, losgelassen zu werden, um das Gelände zu patrouillieren und Eindringlinge abzuschlachten.",al={"warum ist loksey im kloster","warum ist hundemeister loksey hier","loksey zweck"}},["264719ea"]={q="Warum ist Hundemeister Loksey berühmt oder gefürchtet?",a="Loksey ist für sein Rudel abgerichteter Hunde gefürchtet, Bestien, die dafür bekannt sind, Opfer innerhalb von Minuten zu überwältigen und in Stücke zu reißen. Jeder, der sich in das Kloster wagt, fürchtet die Begegnung mit seinem Zwinger, da er weiß, dass Lokseys bösartiges Kommando seine Tiere in unerbittliche Maschinen des Gemetzels verwandelt.",al={"warum ist loksey gefürchtet","lokseys ruf","warum ist hundemeister loksey gefährlich"}}},fp="18,355,21.443.0,14.441.0,38.160.0,51.205.0,34.214.0,40.167.0,55.170.0,38.165.0"}
P.entries["npc:huldar"] = {n="Huldar",s="Huldar ist ein Zwergenfuhrmann, der an der südlichen Straße von Loch Modan nahe dem Seeufer stationiert ist. Mit dem Transport von wichtigem Sprengpulver zur Ausgrabungsstätte im Süden beauftragt, sieht sich seine Lieferkarawane unerbittlichen Angriffen durch lokale Bedrohungen und Dunkeleisensaboteure ausgesetzt.",h="Huldar ist ein Zwergenfuhrmann, der an der südlichen Straße von Loch Modan nahe dem Seeufer stationiert ist.",kw={"sprengpulver","karawane","dunkeleisen","ausgrabung","huldar","loch modan","wagen"},ang={["profession:Engineering"]="Jeder Ingenieur kennt den Wert – und die Flüchtigkeit – von rohem Sprengpulver, das ungeschützt in gestrandeten Holzfässern lagert.",["race:Dwarf"]="Huldar zu helfen unterstützt direkt die Ausgrabungsstätte der Explorer's League und stellt sicher, dass Eure Verwandten das nötige Pulver haben, um uralte Geheimnisse der Titanen ans Licht zu bringen."},sec={{t="Ein Sprengstofftransport in Gefahr",b="Der Transport von Sprengstoff durch Loch Modan ist keine einfache Handelsroute. Huldar wurde damit beauftragt, Wagenladungen voller Bergbausprengpulver nach Süden zur Ausgrabungsstätte zu fahren, wo Zwergenarchäologen und Prospektoren dringend Nachschub benötigen. Allerdings sind die Straßen durch die Wildnis zunehmend gefährlicher geworden. Da einheimische Wildtiere, Troggs und Dunkeleiseninfiltratoren in der Nähe der südlichen Biegung des Sees lauern, sitzt Huldar bei seinem beschädigten Wagen fest und ist auf umherreisende Wanderer angewiesen, um die verbliebenen Pulverfässer zu sichern und dafür zu sorgen, dass die Lieferung die Grabungsstätte erreicht."}},faq={{q="Wer ist Huldar?",a="Huldar ist ein Zwergenfuhrmann, der an seinem Wagen am Südufer des Sees in Loch Modan festsitzt. Er hatte den Auftrag, Sprengpulver zur nahegelegenen Ausgrabungsstätte zu transportieren, bevor sein Versorgungszug in Schwierigkeiten geriet.",al={"wer ist huldar","huldar loch modan","wagen zwerg"}},{q="Was befindet sich in Huldars Wagen?",a="Sein Wagen transportiert Fässer voller Sprengpulver. Die Sprengstoffe werden von Zwergenprospektoren und Archäologen, die an der Ausgrabungsstätte im Süden arbeiten, dringend benötigt.",al={"was transportiert huldar","huldar wagenladung","was sind die fässer"}},{q="Warum sitzt Huldar auf der Straße fest?",a="Die Straßen durch das südliche Loch Modan sind aufgrund feindseliger Bestien, Troggs und Dunkeleisenzwergsaboteuren gefährlich geworden. Huldars Lieferung geriet in einen Hinterhalt, was ihn dazu zwang anzuhalten und Hilfe zu suchen, um die verbliebenen Vorräte zu sichern und abzuliefern.",al={"warum sitzt huldar fest","huldar hinterhalt"}},{q="Warum interessiert sich die Dunkeleisenzwerge für seine Fracht?",a="Der Dunkeleisenklan versucht aktiv, die Präsenz und die historischen Forschungen von Eisenschmiede in ganz Loch Modan zu untergraben. Das Abschneiden der Sprengpulverversorgung stoppt die Ausgrabungsarbeiten und entzieht zwergischen Operationen defensive und industrielle Ressourcen.",al={"dunkeleisen sprengpulver","warum dunkeleisen huldar angreifen"}}},fx={ff7033f4={q="Auf wessen Seite steht Huldar?",a="Huldar ist loyal gegenüber Eisenschmiede und der Allianz. Er arbeitet direkt im Dienst der Zwergenprospektoren und Bergleute, die in Loch Modan tätig sind, transportiert lebenswichtige Munition durch das Gebiet und behauptet sich dabei gegen den feindseligen Dunkeleisen-Clan, der in die Region eindringt.",al={"ist huldar bei der allianz","wem dient huldar","huldar fraktion"}},["9f03f8e3"]={q="Was will Huldar?",a="Huldar möchte seine Lieferung von Sprengpulver sicher zur Ausgrabungsstätte der Zwerge bringen. Dunkeleisenzwerge haben seinen Karawanenzug entlang der südlichen Straße des Lochs überfallen, was ihn dazu zwingt, standhafte Reisende zu suchen, die die Fracht beschützen und die Saboteure zurückschlagen.",al={"was versucht huldar zu erreichen","huldar ziel","was braucht huldar"}},["577cb64e"]={q="Mit wem ist Huldar verbunden?",a="Huldar ist mit den Zwergenausgräbern verbunden, die in Loch Modan stationiert sind. Sein Team hat die Aufgabe, lebenswichtige Vorräte und Sprengpulver direkt zu ihren Ausgrabungsstätten zu transportieren und sicherzustellen, dass ihre Operationen trotz der wachsenden Bedrohung durch Dunkeleisen-Überfälle fortgesetzt werden können.",al={"für wen arbeitet huldar","huldar verbindungen","wen beliefert huldar"}}},fp="6,268,21.566.0,14.208.0,26.167.0,32.232.0,50.234.0"}
P.entries["npc:illiyana"] = {n="Illiyana",s="Illiyana ist eine uralte Dryade, die im südwestlichen Eschental stationiert ist und sich dem Schutz des Waldlands vor uralter Verderbnis widmet. Sie streift nahe dem Schrein von Aessina umher und versammelt Streiter der Allianz, um die bösartigen Satyrn zurückzudrängen, die die uralten Haine heimsuchen. Ihre Wachsamkeit steht für das dauerhafte Bündnis zwischen den Töchtern des Cenarius und der Wildnis der Nachtelfen.",h="Illiyana ist eine uralte Dryade, die im südwestlichen Eschental stationiert ist und sich dem Schutz des...",kw={"eschental","zweig des cenarius","cenarius","dryade","illiyana","satyr","der schrein von aessina"},ang={["class:Druid"]="Druiden schätzen Dryaden als Verkörperungen der Wildnis hoch ein, und Illiyana bei der Bewahrung der geheiligten Lichtungen zu helfen, entspricht direkt der Pflicht des Cenarius, das Land zu heilen.",["faction:Alliance"]="Illiyana stellt eine wichtige Verbündete des Waldlands im südwestlichen Eschental dar und bietet den Streitkräften der Allianz, die die Wildnis gegen das vordringende Unheil sichern, Zuflucht und Führung.",["race:NightElf"]="Für die Kaldorei sind Dryaden wie Illiyana heilige Verwandte des Cenarius – verehrte Beschützerinnen, deren Ruf zu den Waffen gegen dämonische Satyrn ohne Zögern gefolgt wird."},sec={{t="Tochter des Waldes",b="Wie alle Dryaden ist Illiyana eine der Töchter des Halbgottes Cenarius. Friedfertig und doch grimmig darauf bedacht, die wilden Länder zu beschützen, durchstreift sie die Wälder des südwestlichen Eschentals. Während sich finstere Mächte regen und die Waldlande unter schleichender Verderbnis leiden, wacht Illiyana über heilige Relikte sowie Haine und dient als Hüterin der ursprünglichen Unantastbarkeit der Natur."},{t="Die Bedrohung durch die Satyrn",b="Illiyanas Hauptanliegen in der Region ist die anhaltende Plage der Satyrn. Diese verzerrten, dämonischen Kreaturen trachten unablässig danach, die Lichtungen zu verderben und ihre Dryadenschwestern zu gefährden. Illiyana verpflichtet regelmäßig vorbeiziehende Reisende, um diese abscheulichen Missgeburten niederzustrecken und verlorene Artefakte, darunter die Zweig des Cenarius, zu bergen, damit die Wälder vor dämonischer Befleckung geschützt bleiben."}},faq={{q="Wer ist Illiyana?",a="Illiyana ist eine Dryade, die das südwestliche Eschental nahe dem Schrein von Aessina durchstreift. Als Tochter des Cenarius widmet sie ihr Dasein dem Wachen über das wilde Land und dem Schutz ihrer Schwestern vor dämonischen Kräften.",al={"wer ist diese dryade","illiyana eschental","was ist illiyana"}},{q="Warum läuft Illiyana weiter, während ich mit ihr spreche?",a="Illiyana behält eine aktive Patrouillenroute durch das Waldland bei. Anders als stationäre Questgeber setzt sie ihr wachsames Schreiten durch den Hain selbst dann fort, wenn sie Gespräche mit Reisenden führt.",al={"illiyana bewegt sich","warum geht sie weg","illiyana quest laufen"}},{q="Welche Aufgaben bietet Illiyana an?",a="Sie ruft Abenteurer dazu auf, bösartige Satyrn zu jagen, die die Region bedrohen, und heilige Relikte wie die Zweig des Cenarius zu bergen, um ihre Mitschwestern unter den Dryaden zu schützen.",al={"illiyana quests","forest song quests"}},{q="Wo befindet sich Illiyana?",a="Sie patrouilliert nahe dem Schrein von Aessina im südwestlichen Eschental und hält entlang der Pfade und nahegelegenen Haine Wache.",al={"illiyana standort","wo man illiyana findet","forest song dryade standort"}},{q="Warum sind die Dryaden durch die Satyrn in Gefahr?",a="Satyrn sind uralte Nachtelfen, die durch dämonische Verderbnis entstellt wurden und Freude daran finden, die Natur zu schänden und die Kinder des Cenarius zu unterjochen. Dryaden verkörpern die reine, unberührte Schönheit des Waldes, was sie zu vorrangigen Zielen für die Bosheit der Satyrn macht.",al={"warum hassen satyrn dryaden","dryaden und satyrn lore"}},{q="Hilft Illiyana der Horde?",a="Nein. Illiyana ist mit den Nachtelfen und der weiteren Allianz verbündet. Mitglieder der Horde, die sich in ihre Lichtung wagen, werden sie und ihre Verbündeten als feindselig vorfinden.",al={"ist illiyana der horde feindlich gesinnt","kann horde mit illiyana sprechen"}}},fx={f493742a={q="Was will Illiyana?",a="Illiyana widmet sich dem Schutz des Eschental und ihrer Mit-Dryaden vor dem korrumpierenden Einfluss der Satyrn. Sie sucht nach tapferen Champions der Allianz, um die bösen Satyrn in der Nähe zu jagen, die heiligen Haine zu verteidigen und dabei zu helfen, The Branch of Cenarius zurückzugewinnen, um den Wald zu reinigen.",al={"illiyana ziel","was will illiyana","illiyana zweck"}},["925d87c3"]={q="Warum ist Illiyana am Schrein von Aessina?",a="Illiyana wacht über den Schrein von Aessina im südwestlichen Eschental, einem Zufluchtsort, der den Waldgeistern und den Töchtern des Cenarius am Herzen liegt. Von diesem heiligen Boden aus überwacht sie die um sich greifende Verderbnis der Satyrn und koordiniert Verteidigungsmaßnahmen mit Nachtelfen und Verbündeten der Allianz.",al={"warum ist illiyana hier","illiyana schrein von aessina","warum ist illiyana im eschental"}},abbc4abe={q="Mit wem ist Illiyana verbunden?",a="Als Dryade ist Illiyana eine der Töchter des Halbgottes Cenarius und teilt eine tiefe spirituelle und familiäre Verwandtschaft mit ihren Dryadenschwestern, wie Shael'dryn, und den Hütern des Hains. Sie teilt auch starke Bande mit den Nachtelfen, die Aessina und Cenarius verehren.",al={"illiyana verbindungen","illiyana cenarius","mit wem ist illiyana verwandt"}}},fp="8,384,22.345.0,23.388.0,16.218.0,51.198.0,31.163.0,26.114.0,41.230.0,29.146.0"}
P.entries["npc:illiyana-moonblaze"] = {n="Illiyana Mondflamm",s="Illiyana Mondflamm ist eine unkonventionelle Späherin und Rüstmeisterin der Nachtelfen, die im Hain der Silberschwingen in Eschental stationiert ist. An der Seite der Schildwachen der Silberschwingen versorgt sie die Champions der Allianz, die gegen die Vorhut des Kriegshymnenklans in den Krieg ziehen. Trotz ihres formellen Offiziersranges heben ihre scharfen Instinkte und ihr schurkisches Auftreten sie von den traditionellen militärischen Rängen der Kaldorei ab.",h="Illiyana Mondflamm ist eine unkonventionelle Späherin und Rüstmeisterin der Nachtelfen, die im Hain der...",kw={"eschental","hilfspaket","illiyana mondflamm","schurke","schildwache","hain der silberschwingen","warsongschlucht"},ang={["class:Rogue"]="Illiyana stellt einen seltenen Anblick unter den Kaldorei dar: eine erfahrene Schattengängerin und Fährtenleserin, die trotz traditioneller gesellschaftlicher Geringschätzung offen an der Seite regulärer Streitkräfte arbeitet.",["faction:Alliance"]="Für Kämpfer der Allianz, die nach Süden an die umkämpfte Grenze der Kriegshymnenschlucht marschieren, ist Illiyana die wichtigste Rüstmeisterin für Waffen, Rüstung und Rationen.",["race:NightElf"]="Ihre schurkische Präsenz bietet einen deutlichen Kontrast zu typischen Priesterinnen und Schildwachen und zeigt, wie Späher der Kaldorei eigenständige Methoden adaptieren, um Eschental zu schützen."},sec={{t="Eine Späherin außerhalb der Ränge",b="Illiyana Mondflamm dient als primäre Nachschuboffizierin für die im Hain der Silberschwingen gelegenen Schildwachen der Silberschwingen. Doch ein einziger Blick verrät, dass sie alles andere als eine gewöhnliche Schildwache ist. Mit zwei Klingen bewaffnet und in ein dunkles Korsett gekleidet, strahlt sie eher die Verwegenheit einer Schurkin oder Freibeuterin aus als die disziplinierte Haltung von Elunes treuen Kriegerinnen. Die traditionelle Hierarchie der Schildwachen begegnete Angehörigen ihres Gewerbes historisch stets mit Argwohn und stellte sie beinahe vogelfreien Schurken gleich. Dennoch machen ihre unübertroffene Gerissenheit und ihr Talent fürs Fährtenlesen sie in den umkämpften Wäldern unersetzlich."},{t="Nachschub für die Front",b="Über ihre unkonventionellen Späherpflichten hinaus rüstet Illiyana Freiwillige der Allianz aus, die sich auf den Kampf gegen den Kriegshymnenklan in der Kriegshymnenschlucht vorbereiten. Sobald Champions bei den Schildwachen der Silberschwingen Gunst erlangen, belohnt sie deren Dienste mit maßgeschneiderten Rationen, speziellen Tränken und meisterhafter Rüstung, die eigens für Scharmützel im Unterholz entworfen wurde. Zudem repariert sie Waffen und Rüstung für erschöpfte Kämpfer, die von der Frontlinie zurückkehren, und hält so die Kriegsanstrengungen der Schildwachen versorgt und einsatzbereit."}},faq={{q="Wo kann ich Illiyana Mondflamm finden?",a="Sie befindet sich im Hain der Silberschwingen im südöstlichen Eschental, nahe den Aufmarschgebieten und dem Portal, das in die Kriegshymnenschlucht führt.",al={"illiyana mondflamm standort","wo ist illiyana","standort rüstmeister der silverwing"}},{q="Ist Illiyana Mondflamm ein Mitglied der Schildwachen?",a="Formal besitzt sie den Rang einer Offizierin zur Koordination der Logistik, doch sie ist keine traditionelle Schildwache. Ihr Hintergrund entspricht dem von Spähern und Schurken der Kaldorei – einer Berufung, der die herkömmliche Gesellschaft der Schildwachen historisch mit Misstrauen begegnete.",al={"ist illiyana eine schildwache","illiyana rang","illiyana fraktion"}},{q="Was bietet Illiyana Champions der Allianz an?",a="Sie agiert als Rüstmeisterin der Schildwachen der Silberschwingen und bietet jenen, die bei der Fraktion Ruf erlangen, Hilfspakete, Schlachtfeldrüstung, Ringe, Wappenröcke und Verbrauchsgüter an, die auf das Ringen in der Kriegshymnenschlucht zugeschnitten sind.",al={"was verkauft illiyana","warsongschlucht belohnungen eschental","illiyana händlerin"}},{q="Warum sieht sie wie eine Schurkin aus und verhält sich auch so?",a="Ihre Fähigkeiten beruhen auf Heimlichkeit, List und tödlicher Fährtensuche statt auf priesterlicher Frömmigkeit oder soldatischer Disziplin einer Schildwache. Während die Gesellschaft der Nachtelfen solche schurkischen Wege oft als ehrlos oder der Piraterie ähnlich erachtete, erweisen sich ihre praktischen Wildnis-Überlebenskünste in verzweifelten Zeiten als unverzichtbar.",al={"illiyana schurke lore","warum ist sie wie eine piratin gekleidet","illiyana piratin"}},{q="Bietet sie Ausrüstungsreparaturen an?",a="Ja, neben der Ausgabe spezialisierter militärischer Ausrüstung bietet sie Verteidigern der Allianz, die im Hain rasten, standardmäßige Waffen- und Rüstungsreparaturen an.",al={"kann illiyana reparieren","silverwing reparaturhändlerin","reparieren im hain der silverwing"}},{q="Welche Hilfspakete gibt sie aus?",a="Sie unterstützt Kämpfer der Allianz durch logistische Quests rund um einfache, standardmäßige und fortgeschrittene Hilfspakete der Schildwachen und versorgt die Verteidiger an der Front mit lebenswichtigen Schlachtfeldvorräten.",al={"hilfspaket der schildwachen","illiyana quests","warsongschlucht pakete"}}},fx={fb6ea018={q="Wer ist Illiyana Mondflamm?",a="Illiyana Mondflamm ist eine Nachtelfen-Späherin, Fährtensucherin und Quartiermeisterin, die im Hain der Silberschwingen im Eschental stationiert ist. Obwohl sie als Offizierin und deren Hauptlieferantin an der Seite der Schildwachen der Silberschwingen operiert, gehört sie nicht streng zu deren Reihen. Mit ihrer korsettartigen dunklen Kleidung, den zwei Langschwertern und ihrem schurkischen Auftreten bringt sie unkonventionelle Fähigkeiten – Verstohlenheit, Fährtensuche und scharfsinniges Kampfgeschick – in eine Armee ein, die ihre Kunst traditionell mit Misstrauen betrachtet.",al={"wer ist illiyana","illiyana mondflamm hintergrundwissen","wer ist illiyana mondflamm"}},a931fa98={q="Auf wessen Seite steht Illiyana Mondflamm?",a="Illiyana steht fest auf der Seite der Allianz und der Schildwachen der Silberschwingen. Obwohl ihre schurkenhaften Methoden und ihr unabhängiger Geist sie an den Rand der traditionellen Nachtelfengesellschaft stellen, widmet sie ihren Scharfsinn und ihre Späherkünste der Verteidigung des Eschentals gegen die Einfälle der Horde in die Kriegshymnenschlucht.",al={"illiyana mondflamm fraktion","ist illiyana allianz","welcher fraktion gehört illiyana an"}},["6b49a832"]={q="Warum ist Illiyana Mondflamm im Eschental?",a="Illiyana ist im Hain der Silberschwingen stationiert, um den andauernden Krieg gegen die Vorhut des Kriegshymnenklans zu unterstützen. Sie nutzt ihre erfahrenen Fähigkeiten als Fährtensucherin, um den Wald zu überwachen, und dient als leitende Versorgerin und Quartiermeisterin für die Schildwachen der Silberschwingen, indem sie die Champions der Allianz ausrüstet und versorgt, die den Kampf um die Kriegshymnenschlucht aufnehmen.",al={"warum ist illiyana mondflamm hier","illiyana mondflamm hain der silberschwingen","warum ist illiyana im eschental"}},["5a1f5e67"]={q="Was will Illiyana Mondflamm?",a="Illiyana versucht, die Schildwachen der Silberschwingen gegen die Horde zu stärken und gleichzeitig ihre persönliche Unabhängigkeit zu bewahren. Sie möchte, dass engagierte Kämpfer der Allianz den Kriegshymnenklan aus den uralten Wäldern des Eschentals vertreiben, und sie belohnt diejenigen, die ihren Mut in der Kriegshymnenschlucht beweisen, mit spezieller Bewaffnung, Vorräten und Ausrüstung aus ihren Beständen.",al={"was will illiyana","illiyana mondflamm ziele","illiyana zweck"}},["1a70c897"]={q="Mit wem ist Illiyana Mondflamm verbunden?",a="Illiyana arbeitet eng mit den Schildwachen der Silberschwingen zusammen, die das Eschental verteidigen, rüstet deren Champions aus und liefert wertvolle Aufklärung. Sie könnte auch mit Aurine Mondflamm verwandt sein, obwohl ihre beruflichen Verbindungen weiterhin mit den Verteidigern an der Front im Hain der Silberschwingen verknüpft sind.",al={"illiyana mondflamm verbindungen","mit wem ist illiyana in verbindung","illiyana schildwachen der silverwing"}}},fp="18,371,25.572.0,28.478.0,36.125.0,48.241.0,47.221.0,39.282.0,35.148.0,37.188.0"}
P.entries["npc:ilthalaine"] = {n="Ilthalaine",s="Ilthalaine ist ein Wächter der Nachtelfen, der über die heilige Lichtung des Laubschattentals auf Teldrassil wacht. Er dient als erster Begrüßer und Mentor für junge Nachtelfen, die ihre allerersten Schritte in die Welt wagen. Wachsam und mit der Wildnis verbunden, leitet er unerfahrene Abenteurer an, das empfindliche Gleichgewicht der Natur in den Ästen des Weltenbaums zu wahren.",h="Ilthalaine ist ein Wächter der Nachtelfen, der über die heilige Lichtung des Laubschattentals auf Teldrassil...",kw={"aldrassil","das gleichgewicht der natur","ilthalaine","kaldorei","questgeber","laubschattental","siegel","teldrassil"},ang={["class:Druid"]="Für angehende Druiden bieten Ilthalaines Lehren über Bestandsregulierung und natürliches Gleichgewicht ihre allerersten praktischen Lektionen in Cenarion-Prinzipien.",["faction:Alliance"]="Er verkörpert die ruhige, beständige Wachsamkeit der Kaldorei und heißt neue Streiter im Dienst von Darnassus und der weiteren Allianz willkommen.",["race:NightElf"]="Ilthalaine ist der erste Mentor, dem jeder junge Nachtelf begegnet, und vermittelt grundlegende Weisheiten über die Bewahrung und das heilige Gleichgewicht ihrer neu gefundenen Heimat auf Teldrassil."},sec={{t="Wächter des Tals",b="Direkt vor dem Herzen des Laubschattentals positioniert, ist Ilthalaine oft das erste Gesicht, das ein angehender Nachtelf zu Beginn seiner Reise sieht. Er beobachtet die Waldpfade und bemerkt die feinen Veränderungen im Wald, die gewöhnlichen Augen verborgen bleiben. Seine Pflicht ist es, zurückkehrende Verwandte willkommen zu heißen und sicherzustellen, dass neu erwachte Verteidiger in den Traditionen ihres Volkes verwurzelt sind, bereit, sich den Pflichten zu stellen, die mit der Pflege von Teldrassil einhergehen."},{t="Das Gleichgewicht der Natur",b="Starke Frühlingsregenfälle haben dazu geführt, dass die Populationen der Nachtsäbler und Disteleber im Laubschattental über das hinaus gewachsen sind, was die Lichtung ernähren kann. Ilthalaine bittet junge Verteidiger, ihre Zahl zu verringern, damit die anderen Kreaturen des Waldes gedeihen können und das Gleichgewicht der Natur bewahrt wird."},{t="Ein Wegweiser zur Disziplin",b="Über die Erprobung des kriegerischen Könnens eines Abenteurers gegen die einheimische Tierwelt hinaus weist Ilthalaine junge Elfen ihren gewählten Berufungen zu. Indem er jedem Reisenden ein Klassensiegel anvertraut, weist er ihnen den direkten Weg zu ihren Mentoren im Sanktum von Aldrassil – ganz gleich, ob sie dem Pfad des Kriegers, Druiden, Schurken, Priesters oder Jägers folgen. Durch ihn erfährt jeder Novize, wo sein Dienst für die Kaldorei beginnt."}},faq={{q="Wer ist Ilthalaine?",a="Ilthalaine ist ein Aufseher der Kaldorei im Laubschattental, der geschützten Anfangslaube von Teldrassil. Er dient als erster Questgeber für neu erstellte Nachtelfenabenteurer und führt sie in ihre Pflichten sowie den Zustand des Waldes ein.",al={"ilthalaine lore","wer ist dieser nachtelf","laubschattental questgeber"}},{q="Welche Rolle spielt Ilthalaine im Laubschattental?",a="Er wacht über die Tierwelt im Laubschattental und sorgt dafür, dass neue Nachtelfen die Bedeutung des Gleichgewichts der Natur verstehen. Er schickt junge Initianden auf einfache Jagden und weist ihnen den Weg zu ihren jeweiligen Klassenlehrern im großen Baum Aldrassil.",al={"was macht ilthalaine","warum ist er hier","ilthalaine zweck"}},{q="Warum möchte Ilthalaine, dass die jungen Nachtsäbler und Eber dezimiert werden?",a="Starke Frühlingsregenfälle haben die Populationen der Nachtsäbler und Disteleber über das Maß hinaus anwachsen lassen, das das Laubschattental ernähren kann. Ilthalaine bittet um eine Dezimierung, um das Gleichgewicht der Natur zu bewahren.",al={"das gleichgewicht der natur quest","warum nachtsäbler töten","warum eber töten"}},{q="Was sind die Siegel, die er verteilt?",a="Ilthalaine gibt Novizen klassenspezifische beschriftete Siegel und weist sie an, ihre Ausbilder – wie etwa Priesterinnen, Druiden, Krieger und Schurken – aufzusuchen, die in den Wurzeln von Aldrassil Schutz finden.",al={"geätztes siegelzeichen","einfaches siegelzeichen","tiefgrünes siegelzeichen","verschlüsseltes siegelzeichen","geheiligtes siegelzeichen"}},{q="Wo ist Ilthalaine zu finden?",a="Er steht direkt auf dem zentralen Pfad des Laubschattentals, südlich des gewaltigen hohlen Astes von Aldrassil auf Teldrassil.",al={"ilthalaine standort","wo ist ilthalaine","ilthalaine koordinaten"}},{q="Ist Ilthalaine mit den Druiden oder den Sentinels verbunden?",a="Ilthalaine fungiert als allgemeiner Pfleger und Vertreter der Kaldorei im Laubschattental. Obwohl er tief mit der Natur und dem druidischen Ethos der Harmonie verbunden ist, arbeitet er im Auftrag der gesamten Führung von Darnassus, um Novizen aller Disziplinen anzuleiten.",al={"ist er ein druide","welche fraktion ist ilthalaine"}}},fx={e95b9493={q="Warum ist Ilthalaine im Laubschattental?",a="Ilthalaine hält im Laubschattental Wache, um neue Nachtelfen-Verteidiger zu begrüßen und das empfindliche Gleichgewicht von Teldrassils heiliger Baumschule zu bewahren. Während die lokale Tierwelt unruhig wird und Anzeichen von Verderbnis in die Zweige sickern, bleibt er in der Nähe von Aldrassil stationiert, um Neuankömmlinge anzuleiten und erste Bemühungen zur Heilung und zum Schutz des Großen Baums zu steuern.",al={"warum ist ilthalaine hier","ilthalaine laubschattental zweck","warum ist ilthalaine in teldrassil"}}},fp="10,368,20.455.0,21.274.0,21.405.0,18.238.0,40.249.0,64.170.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-allison"] = {n="Gastwirtin Allison",s="Gastwirtin Allison leitet die Gilded Rose, eines der belebtesten und zentralsten Gasthäuser in Sturmwind. Im Herzen des Handelsdistrikts direkt zwischen der Bank und dem Auktionshaus gelegen, versorgt sie erschöpfte Reisende und einheimische Händler mit Ruhesteinbindungen, erfrischenden Getränken und einer Unterkunft.",h="Gastwirtin Allison leitet die Gilded Rose, eines der belebtesten und zentralsten Gasthäuser in Sturmwind.",kw={"allison","gilded rose","ruhestein","gastwirtin allison","sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Als Inhaberin des am leichtesten erreichbaren Gasthauses im Handelszentrum von Sturmwind ist Allison eines der vertrautesten Gesichter für Champions der Allianz, die von Kampagnen an vorderster Front zurückkehren, um sich auszuruhen und ihre Beute auf die Bank zu bringen."},sec={{t="Gastfreundschaft im Handelsdistrikt",b="Genau zwischen dem geschäftigen Auktionshaus und den Tresorgewölben der Stadt gelegen, dient die Gilded Rose als Epizentrum für in Sturmwind eintreffende Abenteurer. Gastwirtin Allison steht hinter dem Haupttresen im Erdgeschoss und sorgt inmitten eines stetigen Stroms von Hausierern, Söldnern und gastierenden Diplomaten für Ordnung. Neben Unterkünften und Ruhesteindiensten nimmt sie regelmäßig an lokalen Feiertagsfeierlichkeiten teil und koordiniert kleine Besorgungen für reisende Helden, die in der Hauptstadt Erholung suchen."}},faq={{q="Wo kann ich Gastwirtin Allison finden?",a="Gastwirtin Allison steht hinter dem Tresen im Erdgeschoss der Gilded Rose. Das Gasthaus befindet sich direkt im Handelsdistrikt von Sturmwind, zwischen der Zentralbank und dem Auktionshaus.",al={"allison standort","wo ist gastwirtin allison","gilded rose gastwirt"}},{q="Welche Dienste bietet Gastwirtin Allison an?",a="Sie bietet die typischen Dienste einer Gastwirtin: Spieler können ihren Ruhestein an die Gilded Rose binden, Speisen und Getränke zur Erholung kaufen und im Rahmen stadtweiter saisonaler Events und Feiertage mit ihr interagieren.",al={"was macht allison","allison dienste","kann man hier ruhestein binden"}},{q="Bietet Gastwirtin Allison Quests an?",a="Ja, Allison nimmt das ganze Jahr über an verschiedenen saisonalen Feierlichkeiten wie Feiertagsevents teil und kann gelegentlich in städtische Botengänge für Reisende verwickelt sein, die Hilfe im Reich suchen.",al={"allison quests","gastwirtin allison quest"}}},fx={["681a398f"]={q="Wer ist Gastwirtin Allison?",a="Allison ist die Inhaberin und Gastwirtin der \"Gilded Rose\", einem der bekanntesten Ruheplätze in Sturmwind. Sie arbeitet direkt im Herzen des geschäftigen Handelsdistrikts und heißt erschöpfte Abenteurer, Händler und Reisende willkommen, die inmitten der überfüllten Hauptstadt nach Ruhe und Komfort suchen.",al={"wer ist allison","gastwirtin allison hintergrundwissen","wer ist gastwirtin allison"}},["4fce5435"]={q="Auf wessen Seite steht Gastwirtin Allison?",a="Allison ist eine treue Untertanin des Königreichs Sturmwind und der Allianz ergeben. Ihr Gasthaus dient als sicherer Hafen und Heimatbasis für Champions der Allianz und Bürger, die durch die Stadt reisen.",al={"gastwirtin allison fraktion","ist allison allianz","wem dient gastwirtin allison"}},["3063ebee"]={q="Warum ist Gastwirtin Allison hier?",a="Allison leitet die \"Gilded Rose\", die direkt zwischen Stürmwinds belebter Bank und dem Auktionshaus liegt. Sie bleibt an ihrem Posten im Erdgeschoss, um Zimmer anzubieten, Ruhesteine zu binden und sich um den endlosen Strom von Reisenden zu kümmern, die im Distrikt Handel treiben und Geschäfte abwickeln.",al={"warum ist gastwirtin allison im handelsdistrikt","gastwirtin allison zweck hier","warum ist allison hier"}},["735a1673"]={q="Was will Gastwirtin Allison?",a="Allison will nichts weiter, als ein erfolgreiches, gastfreundliches Etablissement zu führen und den reibungslosen Betrieb der \"Gilded Rose\" sicherzustellen. Neben der Betreuung ihrer täglichen Gäste nimmt sie gerne an städtischen Festivitäten und saisonalen Feierlichkeiten in der ganzen Hauptstadt teil.",al={"gastwirtin allison beweggründe","was will allison","was sind die ziele von gastwirtin allison"}}},fp="17,295,33.512.0,35.204.0,43.210.0,40.201.0"}
P.entries["npc:innkeeper-farley"] = {n="Gastwirt Farley",s="Gastwirt Fredrik Farley leitet das Gasthaus \"Zur Höhle des Löwen\" in Goldhain und versorgt Reisende, die den Wald von Elwynn durchqueren, mit Speisen, Unterkünften und Ruhesteinen. Er ist allseits beliebt und aufmerksam; oft verwahrt er verlegte Post und hört sich die Sorgen reisender Abenteurer an.",h="Gastwirt Fredrik Farley leitet das Gasthaus \"Zur Höhle des Löwen\" in Goldhain und versorgt Reisende, die den...",kw={"wald von elwynn","frandis","fredrik farley","goldhain","gastwirt farley","gasthaus \"zur höhle des löwen\"","stalvan"},ang={["faction:Alliance"]="Für neue Rekruten, die aus dem Nordhaintal aufbrechen, ist Farleys Theke im Lion's Pride oft die allererste Anlaufstelle, um ihren Ruhestein zu binden und Rationen zu erwerben."},sec={{t="Eine feste Größe in Goldhain",b="Die Familie Farley betreibt das Gasthaus \"Zur Höhle des Löwen\" bereits seit der Herrschaft von König Llane Wrynn I. Gemeinsam mit seiner Frau Verina und der gemeinsamen Tochter Anna führt Fredrik den Betrieb mit gastfreundlicher Hand und wachem Auge. Mit seinen großen, kräftigen Händen, die wie geschaffen dafür sind, Wirtshausschlägereien zu beenden oder Raufbolde vor die Tür zu setzen, sorgt er in einer der geschäftigsten Zwischenstationen des Reiches für Ordnung. Obwohl seine Tage damit ausgefüllt sind, Bier auszuschenken und Käse zu servieren, trägt er die stille Trauer um seinen Bruder Frandis in sich – eine Wache, die während der Seuche der Geißel in Lordaeron ums Leben kam."},{t="Die zurückgelassene Kiste des Boten",b="Da Goldhain an der Kreuzung zwischen Sturmwind, Westfall und dem Dämmerwald liegt, schnappt Farley viele Gerüchte auf und hat mit merkwürdigen Reisenden zu tun. Bemerkenswerterweise nahm er einst einen Boten auf, der voller Panik in die Nacht floh und seine Tasche zurückließ. Farley verstaute die verbliebenen Schriftstücke sicher in einer Kiste im Obergeschoss – darunter ein niemals zugestellter Brief, der an den ehemaligen Schulmeister Stalvan Dunstmantel adressiert war und Ermittlern später als entscheidender Hinweis dient, um die Spuren des gefallenen Hauslehrers zu verfolgen."}},faq={{q="Wer ist Gastwirt Farley?",a="Fredrik Farley ist der Inhaber des Gasthaus \"Zur Höhle des Löwen\" in Goldhain. Seine Familie führt das Gasthaus seit Generationen, zurückreichend bis in die Zeit von König Llane Wrynn I. Er leitet den Betrieb gemeinsam mit seiner Frau Verina und bietet Reisenden, die den Wald von Elwynn durchqueren, Rast und Vorräte.",al={"gastwirt farley","fredrik farley","wer ist der gastwirt von goldhain"}},{q="Was weiß Farley über Stalvan Dunstmantel?",a="Farley erinnert sich an einen verängstigten Boten, der mitten in der Nacht aus dem Gasthaus \"Zur Höhle des Löwen\" floh und mehrere Lieferungen zurückließ. Farley bewahrte die verlassenen Briefe in einer Kiste im oberen Stockwerk auf, darunter ein an Stalvan Dunstmantel adressierter, niemals zugestellter Brief, den Ermittler an sich nehmen können.",al={"farley stalvan","stalvan brief goldhain","die legende von stalvan farley"}},{q="Wo ist Farleys Bruder?",a="Fredriks Bruder, Frandis Farley, verließ den Süden, um als Karawanenwache im nördlichen Königreich Lordaeron zu arbeiten. Während des Dritten Krieges kam die Nachricht, dass Frandis durch die Seuche des Untodes getötet wurde, was Fredrik tief erschütterte.",al={"farley bruder","frandis farley lore","was geschah mit farleys bruder"}},{q="Welche Dienste bietet Farley im Gasthaus an?",a="Farley weist Reisenden Heimat-Ruhesteine zu, vermietet Zimmer und verkauft eine breite Auswahl an Getränken, Säften und Käsesorten aus der gesamten Allianz – von Alteraclochkäse und Pikantem Dalarankäse bis hin zu einheimischem Brie aus Sturmwind.",al={"lion's pride dienste","farley speisen und getränke","goldhain ruhestein"}}},fx={["9ece1a2f"]={q="Auf wessen Seite steht Gastwirt Farley?",a="Gastwirt Farley ist ein treuer Untertan des Königreichs Sturmwind und ein stolzes Mitglied der Allianz. Seine Familie betreibt das Gasthaus \"Zur Höhle des Löwen\" seit der Herrschaft von König Llane Wrynn I. und bietet Schutz, Nahrung und Gastfreundschaft für Mitbürger der Allianz, Reisende und Soldaten, die durch das Kernland von Wald von Elwynn ziehen.",al={"gastwirt farley fraktion","wem dient farley","farley allianz"}},["8af50736"]={q="Was will Gastwirt Farley?",a="Farleys Hauptanliegen ist es, das Gasthaus \"Zur Höhle des Löwen\" zusammen mit seiner Frau Verina am Laufen zu halten. Zwischen dem Schlichten von Schlägereien im Gasthaus und dem Einschenken von Bier möchte er müden Reisenden einen warmen Zufluchtsort bieten. Auf persönlicher Ebene trauert er um den Verlust seines Bruders Frandis, der in Lordaeron an der Seuche umgekommen ist.",al={"was will farley","farley ziele","gastwirt farley beweggründe"}},f394dd82={q="Warum ist Gastwirt Farley hier?",a="Das Gasthaus \"Zur Höhle des Löwen\" ist ein Familienerbe. Farley hat das Etablissement geerbt und Goldhain zu seinem Lebenswerk gemacht, wo er mit seiner Frau Verina und ihrer Tochter Anna lebt. Da Goldhain an der Kreuzung von Wald von Elwynn liegt, bleibt Farley, um den Herd zu hüten und das belebteste Gasthaus des Reiches zu verwalten.",al={"warum ist farley im gasthaus","warum ist gastwirt farley hier"}},["3c5ba4a0"]={q="Mit wem ist Gastwirt Farley verbunden?",a="Farley hat tiefe Wurzeln in Wald von Elwynn. Er betreibt das Gasthaus zusammen mit seiner Frau Verina und zieht ihre Tochter Anna groß. Sein Bruder Frandis Farley war ein Karawanenwächter, der während der Seuche von Lordaeron verloren ging. Neben seiner Familie zählt Farley den reisenden Barden Falkhaan Isenstrider zu seinen engsten persönlichen Freunden.",al={"farley familie","mit wem ist gastwirt farley verwandt","farley beziehungen"}}},fp="16,265,19.550.0,29.508.1,24.280.0,47.282.0,26.219.0,45.209.0"}
P.entries["npc:innkeeper-firebrew"] = {n="Gastwirt Feuerbräu",s="Gastwirt Feuerbräu leitet die Stonefire Tavern im belebten Handelsdistrikt von Eisenschmiede. Als freundlicher Gastgeber für müde Bergsteiger wie auch für hochrangige Besucher serviert er herzhafte Zwergenspezialitäten und sorgt dafür, dass Reisende unter dem Berg ausgeruht bleiben.",h="Gastwirt Feuerbräu leitet die Stonefire Tavern im belebten Handelsdistrikt von Eisenschmiede.",kw={"handelsdistrikt","zwerg","firebrew","ruhestein","gastwirt","eisenschmiede","stonefire tavern"},ang={["faction:Alliance"]="Als primärer Gastwirt in der Nähe der Vordertore bietet Firebrew fremden Reisenden der Allianz einen zentralen, sicheren Zufluchtsort zum Ausruhen, wenn sie die Hauptstadt von König Magni Bronzebart besuchen.",["race:Dwarf"]="Für Zwerge, die von Patrouillen durch Khaz Modan zurückkehren, bietet Firebrews Taverne die behagliche Wärme von zu Hause und einen verlässlichen Krug Zwergenstout."},sec={{t="Hüter der Stonefire",b="Die Einrichtung von Gastwirt Feuerbräu befindet sich im zentralen Ring des Handelsdistrikts und ist oft der erste Zufluchtsort, den Reisende finden, wenn sie durch die Tore von Eisenschmiede eintreten. Hinter einem Tresen, der mit Bierkrügen, Stout-Schläuchen und gebratenen Fleischstücken beladen ist, bietet Firebrew Abenteurern Gastfreundschaft, die auf dem Weg zu den schneebedeckten Pässen von Dun Morogh oder tiefer in das Bergkönigreich sind. Seine Taverne bleibt ein lebhafter Knotenpunkt, an dem Bergleute, Schützen und Abgesandte zusammenkommen, um den zugigen Tunneln zu entfliehen und am Kamin Geschichten auszutauschen."}},faq={{q="Wo finde ich Gastwirt Feuerbräu?",a="Gastwirt Feuerbräu befindet sich in der Stonefire Tavern, die am südlichen Rand des Handelsdistrikts in Eisenschmiede liegt.",al={"standort firebrew","wo ist gastwirt firebrew","tavernenwirt eisenschmiede"}},{q="Welche Waren verkauft Firebrew?",a="Er bietet die üblichen Vorräte eines Gastwirts an, wobei er sich auf deftige Zwergenrationen spezialisiert hat. Reisende können Getränke erwerben, die von lokalem Dwarven Stout und Met bis hin zu importierten Weinen reichen, sowie Fleisch und herzhafte Mahlzeiten, die für lange Reisen geeignet sind.",al={"was verkauft firebrew","getränke bei firebrew","essen in der stonefire tavern"}},{q="Gehört Firebrew zu einer Zwergenbrauerfamilie?",a="Er trägt den Nachnamen Firebrew, aber seine familiären Beziehungen sind nicht bestätigt.",al={"familie firebrew","mit wem ist firebrew verwandt"}},{q="Welche Dienste bietet er Reisenden an?",a="Als Tavernenwirt ermöglicht Firebrew Reisenden der Allianz, ihren Ruhestein an die Stonefire Tavern zu binden, und bietet ein warmes Bett, um sich unter dem Berg auszuruhen und zu erholen.",al={"kann ich hier meinen ruhestein binden","ruhestein gasthaus eisenschmiede"}}},fx={["9fc434fc"]={q="Wer ist Gastwirt Feuerbräu?",a="Gastwirt Feuerbräu ist der zwergische Inhaber der Stonefire Tavern, die sich in den belebten Gemeinen von Eisenschmiede befindet. Als gastfreundliche Figur innerhalb der Bergstadt hütet er das Feuer, schenkt Bier aus und bietet Einheimischen sowie müden Reisenden gleichermaßen Nahrung und Unterkunft.",al={"wer ist feuerbräu","gastwirt feuerbräu","gastwirt der stonefire tavern"}},["3dd110f9"]={q="Auf wessen Seite steht Gastwirt Feuerbräu?",a="Feuerbräu ist dem Königreich Eisenschmiede gegenüber loyal und steht fest auf der Seite der Allianz. Er hält sein Gasthaus für alle verbündeten Abenteurer offen, die Zuflucht vor den kalten Winden von Dun Morogh suchen oder sich nach langen Reisen durch Azeroth ausruhen möchten.",al={"feuerbräu fraktion","feuerbräu allianz","ist feuerbräu allianz"}},e30bdb86={q="Was will Gastwirt Feuerbräu?",a="Feuerbräu konzentriert sich darauf, ein lebhaftes und gastfreundliches Gasthaus zu führen. Er möchte den Herd der Stonefire Tavern zum Brennen bringen, die Krüge der Gäste mit starkem zwergischem Bier füllen und sicherstellen, dass Besucher der großen Schmiedestadt einen warmen Ort zum Ausruhen und Binden ihrer Ruhesteine haben.",al={"was will feuerbräu","feuerbräu beweggründe","feuerbräu ziele"}},b21a7171={q="Warum ist Gastwirt Feuerbräu hier?",a="Feuerbräu leitet die Stonefire Tavern in den Gemeinen, was ihn zum zentralen Gastgeber für Reisende macht, die in das Herz von Eisenschmiede kommen. Er bleibt direkt am Herd, um Unterkunft anzubieten, Vorräte und Getränke zu verkaufen und einen einladenden Ankerpunkt für Abenteurer zu bieten, die in der Hauptstadt eintreffen.",al={"warum ist feuerbräu in eisenschmiede","warum ist feuerbräu in der stonefire tavern"}}},fp="18,235,23.540.0,36.117.0,38.230.0,47.78.0,43.178.0"}
P.entries["npc:innkeeper-grosk"] = {n="Gastwirt Grosk",s="Gastwirt Grosk leitet das Gasthaus in Klingenhügel und versorgt müde Reisende im zentralen Durotar mit Speis, Trank und einem Ort zum Ausruhen. An der belebten Straße zwischen dem Tal der Prüfungen und Orgrimmar gelegen, dient seine Gaststätte als wichtigster Rastplatz für junge Abenteurer der Horde, die in die weite Welt aufbrechen.",h="Gastwirt Grosk leitet das Gasthaus in Klingenhügel und versorgt müde Reisende im zentralen Durotar mit Speis...",kw={"durotar","grosk","gastwirt","gastwirt grosk","orgrimmar","peon's burden","klingenhügel"},ang={["faction:Horde"]="Für frischgebackene Orcs, Trolle und zu Besuch weilende Tauren, die aus dem Tal der Prüfungen oder von Sen'jin nach Norden reisen, markiert Grosks Gasthaus die erste richtige Siedlung und den ersten Heimatort auf dem Weg nach Orgrimmar."},sec={{t="Gastfreundschaft in den roten Einöden",b="Klingenhügel dient als lebenswichtige Kreuzungssiedlung, die die südlichen Übungsplätze von Durotar mit den hohen Mauern von Orgrimmar verbindet. Im Zentrum dieser Raststation steht Gastwirt Grosk, ein Orc, dessen Aufgabe es ist, Kriegern, Spähern und Kumpeln gleichermaßen Zuflucht zu gewähren. Sein Gasthaus bietet Erholung von der unbarmherzigen Wüstenhitze und ist für jeden Reisenden, der unter sein stabiles Gebälk tritt, mit einfachen Vorräten, herzhaftem Fleisch und kühlem Wasser ausgestattet."},{t="Die Erholung eines Kumpels",b="Neben der Bewirtung durchreisender Abenteurer unterstützt Grosk die lokalen Arbeitskräfte, die Durotar am Laufen halten. In der Quest 'A Peon's Burden' bittet der ängstliche Kumpel Ukor, der Nahrungsmittel den weiten Weg bis in das Tal der Prüfungen geschleppt hat, nur um festzustellen, dass sie nicht gebraucht werden, Reisende darum, die Last zurück zu Grosks Gasthaus in Klingenhügel zu tragen."}},faq={{q="Wo befindet sich Gastwirt Grosk?",a="Gastwirt Grosk steht im Gasthaus von Klingenhügel, genau im Zentrum von Durotar an der Hauptstraße, die nach Norden in Richtung Orgrimmar führt.",al={"gastwirt grosk standort","wo ist grosk","klingenhügel gastwirt"}},{q="Welche Dienste bietet Gastwirt Grosk an?",a="Grosk fungiert als Gastwirt, bei dem Abenteurer der Horde ihren Ruhestein an Klingenhügel binden können. Er verkauft zudem einfache Nahrungsmittel, Wasser und Fleisch, um Gesundheit und Mana zwischen den Reisen wieder aufzufüllen.",al={"was macht grosk","grosk händler","kann ich ruhestein an klingenhügel binden"}},{q="Bietet Gastwirt Grosk Quests an?",a="Er ist an der Quest 'A Peon's Burden' beteiligt und nimmt die Ladung Nahrung entgegen, vor deren Rücktransport nach Klingenhügel der Kumpel Ukor aus Furcht vor den Bestien Durotars zu große Angst hatte.",al={"gastwirt grosk quests","a peons burden abgabe"}}},fx={["490d29ee"]={q="Wer ist Gastwirt Grosk?",a="Gastwirt Grosk ist der Orc, der die Taverne in Klingenhügel betreibt. Da Reisende, Grunzer und wandernde Abenteurer auf ihrem Weg von oder nach Orgrimmar durch Durotar ziehen, bietet Grosk ihnen Unterkunft, Proviant und einen Herd, um ihre müden Knochen auszuruhen.",al={"wer ist grosk","gastwirt grosk","wer ist gastwirt grosk"}},["10a7c15b"]={q="Auf wessen Seite steht Gastwirt Grosk?",a="Grosk ist ein standhaftes Mitglied der Horde und heißt Orcs, Trolle, Tauren und Verlassene in seinem Etablissement willkommen. Er stellt sicher, dass diejenigen, die für das neue Reich von Kriegshäuptling Thrall kämpfen, einen verlässlichen Stützpunkt für Ruhe und Nachschub in Durotar haben.",al={"ist grosk horde","gastwirt grosk zugehörigkeit","gastwirt grosk fraktion"}},["29305f72"]={q="Was will Gastwirt Grosk?",a="Grosk will, dass seine Gaststätte reibungslos läuft, während er Reisende auf den trockenen Ebenen von Durotar versorgt. Er handelt mit herzhaftem Essen und Trinken, bindet wandernde Abenteurer an seinen Ruhestein und kümmert sich gelegentlich um die Bedürfnisse der Arbeiter und Wachen der Stadt.",al={"was will grosk","grosk motiv","gastwirt grosk ziele"}},["7fe37467"]={q="Warum ist Gastwirt Grosk in Klingenhügel?",a="Klingenhügel dient als wichtigster Knotenpunkt und Garnisonsstadt zwischen dem Tal der Prüfungen, Sen'jin und der Hauptstadt Orgrimmar. Grosk errichtete seine Taverne hier, um am pulsierenden Herzen des Grenzerlebens in Durotar lebensnotwendige Unterkunft und Vorräte bereitzustellen.",al={"warum ist grosk hier","warum klingenhügel gastwirt","grosk klingenhügel rolle"}}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-gryshka"] = {n="Gastwirtin Gryshka",s="Gastwirtin Gryshka ist eine orcische Gastgeberin, die das Gasthaus Broken Tusk im Tal der Stärke von Orgrimmar leitet. Als erste Anlaufstelle für Reisende, die durch die Stadttore eintreffen, bietet sie anreisenden Abenteurern der Horde Ruhesteinbindungen, Speisen und Getränke an. Sie pflegt enge Beziehungen zu Jägern und Spähern in Durotar und dem Brachland, um ihre Taverne stets mit erlesenen Fleischstücken zu versorgen.",h="Gastwirtin Gryshka ist eine orcische Gastgeberin, die das Gasthaus Broken Tusk im Tal der Stärke von...",kw={"broken tusk","doras","gryshka","ruhestein","gastwirt","orgrimmar","tal der stärke","zargh"},ang={["faction:Horde"]="Für jeden Reisenden der Horde, der in Durotar eintrifft, ist Gryshkas Gasthaus im Tal der Stärke oft der wichtigste Knotenpunkt, um den Ruhestein zu binden und Vorräte aufzustocken, bevor die Reise tiefer nach Kalimdor führt.",["profession:Cooking"]="Köche werden Gryshkas anspruchsvollen Gaumen zu schätzen wissen, da sie keine Mühen scheut, erstklassige Fleischstücke von Jägern zu beschaffen, die bis ins Brachland hinaus stationiert sind."},sec={{t="Der Herd des Tal der Stärke",b="Hinter dem Tresen des Broken Tusk führt Gryshka eines der meistbesuchten Gasthäuser der Horde. Direkt hinter den Haupttoren von Orgrimmar im Tal der Stärke gelegen, dient ihre Schänke als erste Raststätte für Krieger, Boten und frisch eingetroffene Champions, die unter Thralls Banner Schutz suchen."},{t="Eine Vorliebe für frisches Fleisch",b="Eine belebte Taverne in einem trockenen Canyon zu führen, erfordert verlässliche Nachschubwege. Gryshka pflegt eine wohlbekannte Vorliebe für frisches Fleisch und verlässt sich auf vertrauenswürdige Jäger in den Gebieten der Horde, um ihre Küche zu beliefern. Gefährten wie Zargh im Wegekreuz und Grimtak in Durotar schicken regelmäßig ihre feinsten Wildfleischstücke an das Broken Tusk, um ihren anspruchsvollen kulinarischen Maßstäben gerecht zu werden."}},faq={{q="Wer ist Gastwirtin Gryshka?",a="Gastwirtin Gryshka ist die orcische Gastwirtin, die die Taverne Broken Tusk im Tal der Stärke von Orgrimmar führt. Sie heißt Reisende der Horde willkommen, legt Ruhesteinbindungen fest und verkauft Speisen und Getränke an ermattete Abenteurer.",al={"wer ist gryshka","gryshka orgrimmar","gastwirt broken tusk"}},{q="Wo ist Gastwirtin Gryshka zu finden?",a="Sie befindet sich in der Taverne Broken Tusk im Tal der Stärke, dem ersten großen Viertel, das Ihr nach dem Durchqueren der südlichen Haupttore von Orgrimmar betretet.",al={"wo ist gryshka","broken tusk gasthaus standort","tal der stärke gastwirt"}},{q="Woher bezieht Gryshka ihre Fleischvorräte?",a="Gryshka verlässt sich auf Freunde und Späher in den Ländern der Horde, um ihre Vorratskammer zu füllen, darunter Zargh, der im Wegekreuz im Brachland stationiert ist, sowie Grimtak in Durotar, die ihr erlesene Fleischstücke von Wildtieren schicken.",al={"gryshka lebensmittelquellen","wer beliefert das broken tusk","zargh fleischlieferung"}},{q="Welche Dienste bietet Gryshka an?",a="Gryshka kann Euren Ruhestein an das Broken Tusk binden, sodass Ihr Euch direkt nach Orgrimmar teleportieren könnt. Außerdem verkauft sie verschiedene Speisen, Brote und Getränke zur Wiederherstellung von Gesundheit und Mana.",al={"kann ich hier meinen ruhestein binden","broken tusk ruhestein","gryshka händlerwaren"}},{q="Hat Gryshka eine Verbindung zum Windreiterhorst?",a="Reisende, die mit Flugaufträgen aus dem Brachland entsandt werden, überbringen Gryshka oft direkt Pakete, bevor sie zu Doras weitergeleitet werden, dem Windreitermeister, der hoch oben auf der Hochebene über der Stadt weilt.",al={"doras quest","windreitermeister broken tusk","flug nach orgrimmar gasthaus"}},{q="Was für eine Persönlichkeit hat Gryshka?",a="Gryshka ist eine pragmatische, herzhafte orcische Gastgeberin, die gutes Fleisch, offene Worte und eine wohlgeordnete, gut gefüllte Taverne für den steten Strom an Hordekriegern schätzt, die durch die Hauptstadt ziehen.",al={"ist gryshka freundlich","wie ist gryshka so"}}},fx={ad24947b={q="Auf wessen Seite steht Gastwirtin Gryshka?",a="Gryshka ist eine treue Tochter der Horde. Sie arbeitet im Tal der Stärke in Orgrimmar und versorgt direkt die Krieger, Jäger und Reisenden, die Kriegshäuptling Thrall dienen, und stellt sicher, dass sie unter dem Banner der Horde Rast und herzhafte Stärkung finden.",al={"gryshka fraktion","wem dient gryshka","ist gryshka horde"}},f36e4eb0={q="Was will Gastwirtin Gryshka?",a="Vor allem anderen will Gryshka, dass der „Zum gespaltenen Hauer“ gut versorgt und lebhaft bleibt. Sie besitzt einen legendären Appetit auf Qualitätsfleisch und verlässt sich ständig auf Freunde in ganz Durotar und dem Brachland, damit diese frische, erstklassige Stücke liefern, um sie selbst und ihre hungrige Kundschaft zufrieden zu stellen.",al={"was will gryshka","gryshka ziele","wonach sucht gryshka"}},edbe4e1f={q="Warum ist Gastwirtin Gryshka hier?",a="Gryshka leitet den „Zum gespaltenen Hauer“, die geschäftige Taverne im Herzen des Tals der Stärke in Orgrimmar. Sie bleibt hier, um Reisenden, die durch die Hauptstadt ziehen oder aus der rauen Wildnis zurückkehren, Gastfreundschaft, Essen, starkes Getränk und Unterkunft zu bieten.",al={"warum ist gryshka in orgrimmar","warum ist gryshka beim gespaltenen hauer","gryshka zweck"}}},fp="17,404,32.337.0,22.381.0,25.213.0,37.166.0,41.195.0,35.172.0,57.190.0,43.196.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="Gastwirt Keldamyr",s="Gastwirt Keldamyr kümmert sich um den Herd und die Unterkünfte des zentralen Gasthauses in Dolanaar auf Teldrassil. Er bietet Speis, Trank und eine Ruhestatt für junge Nachtelfen, die sich von Laubschattental aus in die weiteren Äste des Weltenbaums wagen.",h="Gastwirt Keldamyr kümmert sich um den Herd und die Unterkünfte des zentralen Gasthauses in Dolanaar auf...",kw={"dolanaar","ruhestein","gasthaus","gastwirt","keldamyr","nachtelf","teldrassil"},ang={["race:NightElf"]="Für Nachtelfen, die gerade erst aus den Ausbildungsstätten von Laubschattental aufbrechen, ist Keldamyrs Gasthaus gewöhnlich das allererste zweite Zuhause, an das sie ihre Ruhesteine binden."},sec={{t="Herd von Dolanaar",b="Dolanaar ist das erste Dorf, das Neuankömmlinge erreichen, nachdem sie die geschützte Lichtung von Aldrassil verlassen haben. Gastwirt Keldamyr pflegt diese zentrale Zuflucht der Gemeinschaft und versorgt Reisende unter dem Blätterdach von Teldrassil mit Brot, Quellwasser und weichen Betten. Wanderer, Schildwachen und junge Novizen auf dem Weg nach Darnassus halten regelmäßig an seinem Tresen inne, um zu Kräften zu kommen, ihre Ruhesteine zu binden und Rationen für die Reise durch das Geäst aufzustocken."},{t="Lieferungen ins Dorf",b="Der Betrieb eines Gasthauses hoch oben in den Zweigen erfordert stetige Nachschubwege von nahegelegenen Siedlungen und Händlern. Einheimische Boten werden oft direkt an Keldamyrs Tresen verwiesen, um Waren abzugeben, wodurch er unmittelbar in den täglichen Handel und die Logistik eingebunden ist, die das Leben in Dolanaar aufrechterhalten."}},faq={{q="Wo finde ich Gastwirt Keldamyr?",a="Keldamyr befindet sich im Hauptgebäude des Gasthauses im Herzen von Dolanaar, der ersten größeren Siedlung südlich von Laubschattental auf den Ästen von Teldrassil.",al={"keldamyr aufenthaltsort","wo ist keldamyr","dolanaar gastwirt aufenthaltsort"}},{q="Welche Dienste bietet Gastwirt Keldamyr an?",a="Er dient als örtlicher Gastwirt, was bedeutet, dass Ihr Euren Ruhestein an seinen Herd binden, grundlegenden Proviant wie Wasser, Milch, Saft und Brot kaufen oder Euch unter seinem Dach erholt ausloggen könnt.",al={"keldamyr waren","was verkauft keldamyr","dolanaar gasthaus essen"}},{q="An welchen Quests ist Gastwirt Keldamyr beteiligt?",a="Er ist der Empfänger des lokalen Kurierauftrags „Lieferung für Dolanaar“ und nimmt Pakete entgegen, die für den Erhalt und die Versorgung des Gasthauses der Siedlung bestimmt sind.",al={"keldamyr quests","dolanaar-lieferung abgeben"}}},fx={cc228f0e={q="Wer ist Gastwirt Keldamyr?",a="Gastwirt Keldamyr ist ein Nachtelf-Gastgeber, der das Gasthaus in Dolanaar leitet. Während Reisende zwischen den schattigen Lichtungen des Laubschattentals und den weitläufigeren Bereichen von Teldrassil unterwegs sind, bietet Keldamyr eine ruhige Feuerstelle, erfrischende Getränke und Vorräte für müde Abenteurer, die sich durch die großen Äste wagen.",al={"wer ist keldamyr","gastwirt keldamyr hintergrund"}},["1430db47"]={q="Auf wessen Seite steht Gastwirt Keldamyr?",a="Gastwirt Keldamyr ist Darnassus und der Allianz gegenüber loyal. Er dient der Nachtelfengemeinschaft von Dolanaar und öffnet seine Türen für seine elfischen Gefährten sowie besuchende Verbündete der Allianz, die unter dem Blätterdach von Teldrassil Ruhe suchen.",al={"keldamyr fraktion","ist keldamyr allianz"}},ff7bce47={q="Was möchte Gastwirt Keldamyr?",a="Keldamyr möchte das Gasthaus von Dolanaar gut ausgestattet und einladend halten. Er kümmert sich um eingehende Vorräte, koordiniert lokale Lieferungen und stellt sicher, dass jeder vorbeikommende Reisende Nahrung, Wasser und einen sicheren Ort hat, an dem er seinen Ruhestein binden kann, bevor er sich in die Wildnis begibt.",al={"keldamyrs ziele","was möchte keldamyr"}},dbe1a8c8={q="Warum ist Gastwirt Keldamyr hier in Dolanaar?",a="Dolanaar ist das wichtigste Wegekreuz und die Siedlung für junge Nachtelfen, die ihr Training im Laubschattental abschließen. Keldamyr unterhält das Gasthaus des Dorfes direkt an der Straße, um an diesem entscheidenden Knotenpunkt auf Teldrassil Unterkunft und Verpflegung zu bieten.",al={"warum ist keldamyr hier","keldamyr dolanaar"}}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:innkeeper-norman"] = {n="Gastwirt Norman",s="Gastwirt Norman hütet den Herd im Hauptgasthaus im Handwerksviertel von Unterstadt. Als ruhiger, pflichtbewusster Verlassener bietet er Reisenden der Horde Rast, das Festlegen von Hearthstones sowie Verpflegung, die auf die unterschiedlichen Geschmäcker von Lebenden und Toten abgestimmt ist.",h="Gastwirt Norman hütet den Herd im Hauptgasthaus im Handwerksviertel von Unterstadt.",kw={"bates","hallow's end","hearthstone","gastwirt","norman","handwerksviertel","unterstadt"},ang={["faction:Horde"]="Für lebende Verbündete der Horde, die Unterstadt besuchen, ist Normans Gasthaus einer der wenigen Orte, die inmitten einer ansonsten unwirtlichen unterirdischen Festung einen sicheren Platz zum Ausruhen und Erholen bieten.",["race:Undead"]="Norman bietet anderen Verlassenen im Herzen des Handwerksviertel einen zentralen Sammelpunkt, um zwischen ihren Aufträgen für die Dark Lady die müden Knochen auszuruhen."},sec={{t="Gastfreundschaft in den Abwasserkanälen",b="Im belebten Handwerksviertel unter den Ruinen der Capital City von Lordaeron gelegen, bietet Gastwirt Norman Abgesandten, Söldnern und Abenteurern auf der Durchreise durch die Festung der Verlassenen eine Bleibe. Trotz der feuchten Kälte und der alchemistischen Ausdünstungen von Unterstadt bleibt Normans Gasthaus ein geschäftiger Knotenpunkt für Reisende, die ihren Hearthstone binden, Neuigkeiten aus ganz Azeroth austauschen oder sich auf Expeditionen in die Plaguelands vorbereiten möchten."},{t="Festliche Eigenheiten",b="Während Norman für gewöhnlich seinen Pflichten nachgeht, Vorräte verkauft und Zimmer verwaltet, bringt die jährliche Ankunft von Hallow's End eine eigenwilligere Seite zum Vorschein. Während der Feiertage nimmt Norman am festlichen Treiben teil und verlangt von abenteuerlustigen Gästen, die festliche Leckereien wie Pfefferminzbonbons aus Unterstadt ergattern wollen, sonderbare Darbietungen – etwa wie ein Huhn zu gackern."}},faq={{q="Wo finde ich Gastwirt Norman?",a="Gastwirt Norman befindet sich im Hauptgasthaus im Handwerksviertel von Unterstadt, gelegen am südlichen Bogen des inneren Rings.",al={"norman standort","unterstadt gastwirt standort","wo ist norman"}},{q="Welche Dienste bietet Gastwirt Norman an?",a="Er dient als einer der primären Gastwirte für Unterstadt. Spieler können ihren Hearthstone an sein Gasthaus binden, Speisen und Getränke für Lebende und Untote kaufen oder sich sicher ausloggen, um sich auszuruhen.",al={"norman dienste","unterstadt hearthstone"}},{q="Warum verlangt Norman von Gästen, wie ein Huhn zu gackern?",a="Während des Festes Hallow's End beteiligt sich Norman an den traditionellen Festtagsstreichen. Abenteurer, die besondere Feiertags-Minzbonbons ergattern möchten, müssen ihren Stolz herunterschlucken und wie ein Huhn gackern, um sich seine Gunst zu verdienen.",al={"huhn gackern minzbonbons","norman huhn quest"}},{q="Ist Norman mit Innkeeper Bates verwandt?",a="Obwohl sie einander weder im Leben noch im Untod direkt erwähnen, ist keine Verwandtschaft zwischen ihnen bekannt. Ihre Namen zusammen sind eine augenzwinkernde Anspielung der Schöpfer der Welt auf den Gastwirt Norman Bates aus dem Film Psycho.",al={"norman bates verbindung","innkeeper bates norman"}}},fx={["543a0ebc"]={q="Wer ist Gastwirt Norman?",a="Gastwirt Norman ist ein Gastwirt der Verlassenen, der die geschäftige Taverne im Handwerksviertel der Unterstadt betreut. Während viele Untote die Annehmlichkeiten ihres sterblichen Lebens aufgegeben haben, versorgt Norman müde Reisende, Soldaten und Gesandte, die ihren Weg durch die unterirdische Festung von Lady Sylvanas finden, mit Speis, Trank und einem Ort zum Ausruhen.",al={"wer ist norman","hintergrundgeschichte gastwirt norman","norman unterstadt"}},bc99de77={q="Auf wessen Seite steht Gastwirt Norman?",a="Norman ist den Verlassenen und der Dunklen Fürstin treu und dient damit auch der gesamten Horde. Er befindet sich im Herzen des Handwerksviertels und öffnet seine Türen für besuchende Orcs, Trolle und Tauren. Er bietet ihnen unter den Ruinen von Lordaeron Unterschlupf, während er seinen untoten Artgenossen gegenüber zutiefst ergeben bleibt.",al={"fraktion norman","loyalität norman","gehört norman zur horde"}},["58ea57aa"]={q="Warum ist Gastwirt Norman hier?",a="Norman leitet die Haupteinkehr der Unterstadt und ist direkt im Handwerksviertel stationiert, wo sich Handel, Reisen und Politik kreuzen. Selbst im untoten Zustand benötigen Besucher und Bürger einen Treffpunkt, um Gerüchte auszutauschen, Ruhesteine zu binden und sich mit Vorräten einzudecken, und Norman sorgt dafür, dass die Taverne inmitten der Düsternis reibungslos läuft.",al={"warum ist norman in der unterstadt","norman handwerksviertel","was macht norman hier"}}},fp="16,256,25.440.0,22.353.0,34.140.0,44.201.0,52.197.0,37.216.0"}
P.entries["npc:innkeeper-pala"] = {n="Gastwirtin Pala",s="Gastwirtin Pala leitet die Cat and the Schamane, die geschäftige Taverne auf der unteren Ebene von Donnerfels. Sie bietet reisenden Abenteurern eine Ruhesteinbindung, kalte Getränke und einen Ort zum Ausruhen zwischen Reisen durch Mulgore und darüber hinaus.",h="Gastwirtin Pala leitet die Cat and the Schamane, die geschäftige Taverne auf der unteren Ebene von Donnerfels.",kw={"cat and the schamane","ruhestein","gastwirt","gastwirtin pala","mulgore","pala","donnerfels"},ang={["faction:Horde"]="Orcs, Trolle und Verlassene, die Mulgore besuchen, finden in Palas Gasthaus eine angenehme Operationsbasis direkt an den Aufzügen.",["race:Tauren"]="Für Tauren, die von den Grenzen Kalimdors heimkehren, bietet Pala ein vertrautes, einladendes Gesicht unter den hoch aufragenden Totems der zentralen Mesas."},sec={{t="Gastfreundschaft auf der unteren Anhöhe",b="Auf der unteren Anhöhe der weitläufigen Mesas von Donnerfels hütet Gastwirtin Pala den Herd in der Cat and the Schamane. Die Taverne dient als einer der zentralen Treffpunkte für Reisende, die von den zentralen Aufzügen steigen oder aus den weiten Ebenen von Mulgore ankommen. Pala wacht beständig über ihren Schankraum und sorgt dafür, dass müde Krieger, wandernde Druiden und reisende Verbündete der Horde eine verlässliche Zuflucht, ein warmes Getränk und ein vertrautes zweites Zuhause finden."}},faq={{q="Wo kann ich Gastwirtin Pala finden?",a="Pala befindet sich in der Taverne Cat and the Schamane, die auf der unteren Anhöhe von Donnerfels nahe den Hauptaufzügen der Stadt liegt.",al={"pala aufenthaltsort","wo ist pala","gastwirtin pala karte"}},{q="Welche Dienste bietet sie Reisenden an?",a="Wie andere Gastwirte in ganz Kalimdor kann Pala Euren Ruhestein an die Cat and the Schamane binden, sodass Ihr sofort dorthin zurückkehren könnt. Zudem verkauft sie einfache Speisen und Getränke zur Wiederherstellung von Gesundheit und Mana.",al={"pala dienste","kann ich ruhestein donnerfels binden","was verkauft pala"}},{q="Wie heißt ihre Taverne?",a="Ihre Taverne heißt Cat and the Schamane – eine Gaststätte, die dem stetigen Strom von Horde-Reisenden dient, die die untere Ebene der Stadt passieren.",al={"cat and the schamane","donnerfels unteres gasthaus name","pala gasthaus name"}}},fx={["18c94984"]={q="Wer ist Gastwirtin Pala?",a="Gastwirtin Pala ist eine Tauren-Gastgeberin, die sich im „Zur Katze und zum Schamanen“ auf der unteren Ebene von Donnerfels um Reisende und müde Wanderer kümmert. Sie pflegt den Herd, kehrt die Böden und bietet Essen, Trinken und einen erholsamen Ort für diejenigen, die die hohen Mesas der Tauren-Hauptstadt besuchen.",al={"wer ist pala","gastwirtin pala","wer ist gastwirtin pala"}},["3afadd2e"]={q="Auf wessen Seite steht Gastwirtin Pala?",a="Gastwirtin Pala ist den Taurenstämmen und der Horde unter Oberhäuptling Cairne Bluthuf treu. Da sie einladend im Herzen von Donnerfels steht, versorgt sie gerne Tauren, Orcs, Trolle und die besuchenden Verlassenen, die Gastfreundschaft in der Stadt suchen.",al={"gastwirtin pala fraktion","gastwirtin pala zugehörigkeit","ist pala horde"}},["0c2271e0"]={q="Was will Gastwirtin Pala?",a="Pala will nicht viel mehr, als dass „Zur Katze und zum Schamanen“ reibungslos läuft. Ihr Fokus liegt darauf, herzliche Gastfreundschaft anzubieten, Proviant zu servieren und einen sauberen, friedlichen Zufluchtsort bereitzustellen, an dem müde Reisende ihre Geister binden und sich zwischen beschwerlichen Reisen durch Kalimdor ausruhen können.",al={"was will pala","pala ziel","gastwirtin pala zweck"}},["1c871847"]={q="Warum ist Gastwirtin Pala hier?",a="Die weitläufigen Ebenen von Donnerfels sehen einen stetigen Verkehr von Jägern, Schamanen und Gesandten durch Mulgore. Gastwirtin Pala bleibt auf der unteren Ebene stationiert, um die Taverne zu führen und sicherzustellen, dass ankommende Abenteurer und Händler immer einen einladenden Herd und Proviant in der Nähe haben.",al={"warum ist pala hier","warum ist pala in donnerfels","gastwirtin pala rolle"}}},fp="14,243,29.485.0,32.134.0,44.192.0,31.146.0"}
P.entries["npc:interrogator-vishas"] = {n="Befrager Vishas",s="Befrager James Vishas ist der Foltermeister des Scharlachroten Kreuzzugs und tief im Friedhofsflügel vom Scharlachroten Kloster stationiert. Berüchtigt für seine schrille Stimme und schiere Grausamkeit, findet er ein verdrehtes Vergnügen daran, Gefangene zu brechen und die Grenzen sterblichen Fleisches auszutesten. Nur wenige, die seine Folterkammern betreten, verlassen sie jemals mit intaktem Verstand oder Körper.",h="Befrager James Vishas ist der Foltermeister des Scharlachroten Kreuzzugs und tief im Friedhofsflügel vom...",kw={"friedhof","befrager vishas","james vishas","der lordameresee","nancy vishas","das scharlachrote kloster","folter","vorrel sengutz"},ang={["class:Priest"]="Zu sehen, wie Vishas Eifer heraufbeschwört, um entsetzliche Verstümmelung zu heiligen, bietet eine erschreckende Demonstration dessen, wie ein heiliger Zweck in verdrehten Wahnsinn umschlagen kann.",["faction:Alliance"]="Helden der Allianz, die Vishas' Werk entdecken, erkennen schnell, dass der Scharlachrote Kreuzzug nicht länger zwischen Monstern der Geißel und unschuldigen lebenden Reisenden unterscheidet.",["race:Undead"]="Für die Verlassenen verkörpert Vishas die heuchlerische Bosheit der lebenden Eiferer, die gefangene Untote aus reiner Gehässigkeit foltern, während sie behaupten, dem Heiligen Licht zu dienen."},sec={{t="Das Skalpell des Großinquisitors",b="In den dunklen Krypten und Grabstätten vom Scharlachroten Kloster kümmert sich Befrager Vishas um die gefangenen Feinde des Kreuzzugs. Während die Eiferer draußen in glänzender Rüstung unter den Bannern der Reinheit marschieren, repräsentiert Vishas die düstere Realität hinter ihrem Kreuzzug: ungezügelter Sadismus, getarnt als religiöser, rechtschaffener Zorn. Er betrachtet das Verhör nicht bloß als eine Pflicht zur Informationsbeschaffung, sondern als eine geschätzte Handwerkskunst, wobei er in der Qual der gefangenen Verlassenen, gefangenen Geißel-Kreaturen und jeglicher lebender Reisender schwelgt, die das Unglück haben, als Ketzer gebrandmarkt zu werden."},{t="Ein Leben in stiller Häuslichkeit",b="Hinter den blutigen Schürzen und den Schreien der Folterkammer führt Vishas ein bizarr häusliches Doppelleben. Außerhalb der Klostermauern lebt seine Familie – einschließlich seiner Frau Nancy Vishas und seines älteren Verwandten Opa Vishas – friedlich in einem abgelegenen Häuschen an den östlichen Ufern vom Lordameresee im Alteracgebirge. Vishas trägt sogar grausige Andenken seiner Opfer zurück in sein Privatleben; so hat er einem gefangenen Verlassenen namens Vorrel Sengutz seinen geschätzten Ehering abgenommen, um ihn Nancy als Geschenk zu überreichen."}},faq={{q="Wo kann Befrager Vishas gefunden werden?",a="Befrager Vishas befindet sich tief im Friedhofsflügel vom Scharlachroten Kloster, in Tirisfal. Er beaufsichtigt eine düstere Folterkammer, die mit Eisenkäfigen und blutverschmierten Streckbänken ausgekleidet ist.",al={"standort von vishas","wo ist befrager vishas","raum von vishas"}},{q="Warum foltert Vishas seine Gefangenen?",a="Während der Scharlachrote Kreuzzug die Quälerei von Gefangenen damit rechtfertigt, die Verderbnis der Geißel auszumerzen und Informationen zu erlangen, erfreut sich Vishas persönlich an dem Schmerz, den er verursacht. Er ist ungemein stolz auf seine Grausamkeit und betrachtet Folter als seine künstlerische Handwerkskunst.",al={"warum foltert vishas leute","motivation von vishas"}},{q="Wer ist Vorrel Sengutz?",a="Vorrel Sengutz ist ein Gefangener, der im Friedhof des Klosters von Vishas inhaftiert und brutal gefoltert wird. Vishas unterzog Vorrel wochenlanger Qual und stahl seinen Ehering, mit der Absicht, ihn seiner Frau zu schenken.",al={"gefangener vorrel sengutz","wer ist der gefangene im käfig"}},{q="Wo lebt die Familie von Vishas?",a="Seine Familie lebt weit weg vom Kloster, in einem unscheinbaren Häuschen am östlichen Ufer vom Lordameresee im Alteracgebirge. Seine Frau Nancy und Opa Vishas wohnen dort in aller Stille, scheinbar losgelöst von seinen Gräueltaten.",al={"standort nancy vishas","opa vishas","haus von vishas familie"}},{q="Wen hält Vishas gefangen?",a="Der Scharlachrote Kreuzzug betrachtet die Untoten als Feinde. Unter Vishas' Gefangenen befindet sich der Verlassene Vorrel Sengutz, den er seit Wochen foltert.",al={"gefangene von vishas","wen foltert vishas","vishas gefangener vorrel"}},{q="Wie ist Vishas' Stimme und Gebaren?",a="Vishas ist bei jenen, die ihm gegenüberstehen, für seine schneidende, hohe Stimme, sein gackerndes Lachen und seine verstörende Begeisterung berüchtigt, wann immer sich eine Gelegenheit bietet, einem unwilligen Opfer Geheimnisse zu entlocken.",al={"stimme von vishas","persönlichkeit von vishas"}}},fx={["518fe48c"]={q="Wer ist Befrager Vishas?",a="James Vishas ist der Hauptbefrager des Scharlachroten Kreuzzugs und in den Tiefen des Friedhofs vom Scharlachroten Kloster stationiert. Fanatisch und berüchtigt für seine Grausamkeit, ist er sehr stolz darauf, Gefangene zu brechen, die vor ihn gebracht werden. Bewaffnet mit Folterinstrumenten und einem geistesgestörten Eifer, entlockt er jedem, der das Unglück hat, in seine Hände zu fallen, Geständnisse und peinigt ihn gleichermaßen.",al={"wer ist vishas","befrager vishas hintergrund","wer ist james vishas"}},cadee917={q="Auf wessen Seite steht Befrager Vishas?",a="Vishas ist dem Scharlachroten Kreuzzug voll und ganz ergeben. Er dient ihrem fanatischen Kreuzzug, indem er verdächtige Agenten der Geißel, gefangene Verlassene und jeden anderen foltert, der als beschmutzt oder feindselig gegenüber der fanatischen Reinheit des Ordens angesehen wird.",al={"vishas fraktion","für wen arbeitet vishas","vishas scharlachroter kreuzzug"}},e1510cf6={q="Warum ist Befrager Vishas hier?",a="Vishas ist in den Folterkammern des Friedhofs vom Scharlachroten Kloster stationiert, um Gefangene zu verhören, die in ganz Tirisfal gefangen genommen wurden. Er verbringt seine Tage und Nächte damit, Informationen zu erpressen, sadistischen Drängen freien Lauf zu lassen und die Geister von Gefangenen wie Vorrel Sengutz im Namen des Kreuzzugs zu brechen.",al={"warum ist vishas auf dem friedhof","vishas kloster rolle","was macht vishas hier"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
P.entries["npc:islen-waterseer"] = {n="Islen Wasserdeuter",s="Islen Wasserdeuter ist eine angesehene Schamanin der Tauren, die neben einer ruhigen Fischerhütte an der Tidusstaffel mit Blick auf das östliche Meer des Brachlands verweilt. Dank ihrer innigen Zwiesprache mit den Geistern des Wassers leitet sie Initianden durch die Prüfungen, die für den Einklang mit diesem Element nötig sind. Schamanennovizen aus der gesamten Horde suchen ihre Weisheit, um sich ihr Wassertotem zu verdienen.",h="Islen Wasserdeuter ist eine angesehene Schamanin der Tauren, die neben einer ruhigen Fischerhütte an der...",kw={"brachland","ruf des wassers","greta mooshuf","islen","schamane","die tidusstaffel","wassersapta","waterseer"},ang={["class:Shaman"]="Islen ist eine unverzichtbare Mentorin auf Eurer Reise, die Euch durch die elementaren Riten führt, die erforderlich sind, um die Geister des Wassers an Euch zu binden, Zwiesprache mit ihnen zu halten und Euer Wassertotem zu erlangen.",["faction:Horde"]="An der Küste des Brachlands stationiert, dient Islen als friedvoller geistiger Anker der Horde und heißt Reisende aus Orgrimmar und Donnerfels gleichermaßen willkommen.",["race:Tauren"]="Islen verkörpert die traditionelle Ehrfurcht der Tauren vor den Gaben der Erdenmutter und wählte ein einsames Leben am Meer, um im Einklang mit den feinen Strömungen der Wildnis zu verweilen."},sec={{t="Der Einsiedler der Tidusstaffel",b="Fernab der geschäftigen Kreuzwege und Lagerplätze des Brachlands lebt Islen Wasserdeuter an der zerklüfteten Küste, die als die Tidusstaffel bekannt ist. Hier, wo die kargen Ebenen an das große Meer branden, ist die Gegenwart der Wassergeister unverfälscht und allgegenwärtig. Statt in donnernden Hallen oder geschäftigen Städten zu weilen, zieht Islen diesen ruhigen Außenposten vor und widmet ihre Tage dem Lauschen der Gezeiten sowie der Unterstützung von Schamanen, die nach Zwiesprache mit dem flüssigen Element streben."},{t="Meisterin des Wassersapta",b="Das Verständnis des Wassers erfordert mehr als bloßes Studium; es verlangt innere Harmonie und geistige Wahrnehmung. Islen leitet Suchende bei der Zubereitung des Wassersapta an, einem heiligen Gebräu, das den Schleier zwischen den sterblichen Sinnen und elementaren Manifestationen lüftet. Ihre Lehren erinnern Schamanen daran, dass Wasser ebenso unnachgiebig und tiefgründig wie fließend und heilsam ist – und von jedem, der auf seinen Beistand hofft, tiefsten Respekt verlangt."},{t="Bande über die Wildnis hinweg",b="Obgleich Islen ein ruhiges Leben an der Küste führt, reichen ihr geistiger Einfluss und ihre Verbindungen über ganz Kalimdor. Sie pflegt eine enge, dauerhafte Freundschaft mit Greta Mooshuf, einer weiteren weisen Tauren, die in den heilenden Künsten bewandert ist. Durch diese Bande berührt Islens Wissen um das reinigende Wesen des Wassers Angelegenheiten weit jenseits des Brachlands und spendet selbst Landstrichen geistigen Beistand, die von tiefer Verderbnis geplagt sind."}},faq={{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine weise Schamanin der Tauren, die an der Küste des Brachlands bei der Tidusstaffel weilt. Sie besitzt eine seltene, tiefe Bindung zu den Elementargeistern des Wassers und dient Schamanen, die sich ihr Wassertotem verdienen wollen, als geistige Mentorin.",al={"islen wasserdeuter geschichte","wer ist islen","tidusstaffel tauren"}},{q="Warum reisen Schamanen zu ihr?",a="Schamanen der Horde werden während der Prüfungen um den Ruf des Wassers von ihren Lehrern in Durotar, Orgrimmar und Donnerfels zu Islen gesandt. Sie prüft deren Verständnis des Elements und leitet sie bei der Herstellung des Wassersapta an, um Wasserelementare direkt wahrzunehmen.",al={"warum islen aufsuchen","ruf des wassers nsc","schamanenquest brachland küste"}},{q="Wo befindet sich Islen Wasserdeuter?",a="Man findet sie vor einer kleinen Fischerhütte an der Tidusstaffel, gelegen an der östlichen Küste des Brachlands südlich der Händlerküste.",al={"islen standort","wo ist islen wasserdeuter","islen finden"}},{q="Was ist das Wassersapta, von dem sie spricht?",a="Das Wassersapta ist ein eigens gebrauter geistiger Trank, der aus elementaren Bestandteilen hergestellt wird. Sein Verzehr ermöglicht es dem Blick eines Schamanen, die physische Ebene zu durchdringen und die verborgenen Wassergeister zu erblicken, die in heiligen Quellen und Fluten weilen.",al={"wassersapta bedeutung","was bewirkt das sapta"}},{q="Wer ist Islens Freundin Greta Mooshuf?",a="Greta Mooshuf ist eine alte Gefährtin der Tauren und eine Mitschülerin der geistigen Künste. Die beiden verbindet eine langjährige Freundschaft, und sie beraten einander bezüglich geistiger Reinigung und der heilenden Natur des Wassers.",al={"verbindung zu greta mooshuf","islens freundin"}},{q="Gehört Islen einer bestimmten Fraktion oder einem Stamm an?",a="Islen ist mit der Horde und den vereinten Taurenstämmen unter Cairne Bluthuf verbündet. Obwohl sie zurückgezogen an der Küste lebt, steht sie Orc-, Troll- und Taurenschamanen bereitwillig zur Seite, die von den Ältesten der Horde entsandt werden.",al={"islen fraktion","gehört islen zur horde"}}},fx={["5f8885ca"]={q="Warum ist Islen Wasserdeuter hier?",a="Islen lebt am Ufer des Südflutstroms und des großen Meeres entlang der Tidusstaffel und führt ein ruhiges Leben in der Abgeschiedenheit nahe dem offenen Wasser. Hier, direkt auf die Gezeiten und natürlichen Strömungen eingestimmt, dient sie als spiritueller Anker für junge Schamanen der Horde, die lernen müssen, sich auf die flüchtigen Geister des Wassers einzustimmen.",al={"warum ist islen hier","warum ist islen beim ozean","islen wasserdeuter tidusstaffel"}}},fp="15,354,25.454.0,27.423.0,22.406.0,23.251.0,33.258.0,33.151.0,38.240.0,37.207.0,49.206.0"}
P.entries["npc:iverron"] = {n="Iverron",s="Iverron ist ein junger Nachtelf, der sich im Laubschattental befindet, dem geschützten Anfangsast von Teldrassil. Gezeichnet vom Gift der zunehmend unruhigen Spinnentiere des Waldlands dient seine Notlage als frühe Warnung vor dem wachsenden Verderben im Weltenbaum.",h="Iverron ist ein junger Nachtelf, der sich im Laubschattental befindet, dem geschützten Anfangsast von...",kw={"gegengift","dentaria","iverron","kaldorei","laubschattental","spinne","teldrassil","gift"},ang={["class:Druid"]="Druiden, die im Laubschattental studieren, betrachten Iverrons Vergiftung als Symptom eines tiefergehenden Leidens, das die Natur erfasst hat und das Heilmittel erfordert, die direkt aus der Flora und Fauna der Lichtung gewonnen werden.",["profession:Herbalism"]="Iverrons Überleben hängt vom zügigen Sammeln der lokalen Flora des Laubschattentals ab, was den entscheidenden Wert von Kräuterwissen für den Erhalt des Lebens hervorhebt.",["race:NightElf"]="Für junge Nachtelfen, die ihre ersten Schritte außerhalb von Aldrassil wagen, ist Iverrons Missgeschick eine frühe Lektion darüber, wie rasch die Wildnis von Teldrassil aus dem Gleichgewicht gerät."},sec={{t="Ein bitterer Biss",b="Als er durch das ruhige Blätterdach des Laubschattentals wanderte, geriet Iverron mit den im Tal nistenden Waldweberspinnen aneinander. Der junge Elf erlag rasch ihrem giftigen Biss und blieb handlungsunfähig zurück, unfähig, aus eigener Kraft in Sicherheit zurückzukehren. Sein hilfloser Zustand unterstreicht die plötzliche Aggression, die Kreaturen erfasst hat, welche einst friedlich die Lichtung teilten."},{t="Verzweifelte Heilmittel",b="Iverrons Überleben hängt vom schnellen Handeln seiner Gefährten und der hiesigen Heiler ab, die wirkungsvolle Zutaten aus den Wäldern benötigen – wie etwa Hyazinthenpilze, Mondblumenlilien und Waldwebersekret –, um ein Gegengift zu brauen. Seine Begegnung mit dem Tod ist eine ernüchternde Mahnung für alle jungen Kaldorei im Laubschattental, dass die Äste von Teldrassil längst keine unbefleckte Zuflucht mehr sind."}},faq={{q="Wer ist Iverron?",a="Iverron ist ein junger Nachtelf, der im Laubschattental auf Teldrassil weilt. Auf seinen Reisen durch das Waldland fiel er der giftigen Fauna zum Opfer, die die Äste heimsucht, und benötigte dringende Hilfe zum Überleben.",al={"iverron hintergrund","wer ist iverron","iverron nachtelf"}},{q="Wodurch wurde Iverron vergiftet?",a="Er wurde von den aggressiven Waldweberspinnen gebissen, die das Dickicht des Laubschattentals bewohnen, und leidet unter einem lähmenden Gift, das sich nicht durch gewöhnliche Rast heilen ließ.",al={"warum ist iverron krank","was hat iverron gebissen","iverron gift"}},{q="Wie wird Iverron geheilt?",a="Er wird durch ein Gebräu aus einheimischen Pflanzen von Teldrassil geheilt, darunter Hyazinthenpilze und Mondblumenlilien, vermengt mit Waldwebersekret von den Spinnen, um ein gezieltes Gegengift herzustellen.",al={"iverron heilen","iverron gegengift","iverron retten"}},{q="Wo ist Iverron zu finden?",a="Er befindet sich im Laubschattental, der abgelegenen Anfangslichtung in der Krone von Teldrassil, wo unerfahrene Nachtelfen ihre Ausbildung beginnen.",al={"iverron aufenthaltsort","wo ist iverron","iverron finden"}},{q="Wer hilft Iverron?",a="Iverron schickt Abenteurer zu seiner Freundin Dirania Silberschein, die die Zutaten für ein Gegengift sammelt und es ihm zurückbringt, bevor es seine Wirkung verliert.",al={"wer rettet iverron","iverron freunde","dentaria silverglade iverron"}},{q="Warum sind die Spinnen im Laubschattental so feindselig?",a="Die plötzliche Aggressivität der Spinnen im Laubschattental ist Teil einer unnatürlichen Plage, die sich in Teldrassil ausbreitet und normalerweise zurückgezogen lebende Bestien in gewalttätige Raubtiere verwandelt.",al={"warum spinnen angreifen","teldrassil spinnen verderbnis"}}},fx={["7be6aac6"]={q="Auf wessen Seite steht Iverron?",a="Iverron ist ein gewöhnlicher Nachtelf, der seinem Volk und der Allianz treu ist. Er lebt friedlich in den geschützten Zweigen von Laubschattental auf Teldrassil und verlässt sich auf die Hilfe von Mit-Kaldorei wie seiner engen Freundin Dirania Silberschein, die sich um ihn kümmert, wenn ihm ein Missgeschick widerfährt.",al={"iverron fraktion","ist iverron allianz","wem dient iverron"}},["9c5ce7fc"]={q="Was will Iverron?",a="Im Moment will Iverron einfach nur überleben. Er wurde bei einem Ausflug durch Laubschattental von tödlichem Spinnengift niedergestreckt, ist handlungsunfähig und braucht dringend ein starkes Gegengift, bevor das Gift sein Leben fordert.",al={"iverron ziel","was braucht iverron","iverron motiv"}},b06694b4={q="Warum ist Iverron in Laubschattental?",a="Iverron wohnt in Laubschattental, dem geschützten Starttal von Teldrassil. Er wagte sich in die umliegenden Wälder, nur um dort den aggressiven Webholzspinnen in die Quere zu kommen. Vom Gift überwältigt, brach er zusammen und liegt nun niedergeschlagen auf dem Waldboden.",al={"warum ist iverron hier","iverron laubschattental grund","was ist mit iverron passiert"}},e299821e={q="Mit wem ist Iverron verbunden?",a="Iverron ist eng befreundet mit Dirania Silberschein, einer Wächterin, die in Aldrassil stationiert ist. Als er schwer am Spinnengift erkrankte, suchte Dirania sofort Hilfe bei vorbeiziehenden Abenteurern und Druiden, um ein Gegenmittel zu brauen und sein Leben zu retten.",al={"iverron verbindungen","wer sind iverrons freunde","iverron dirania"}}},fp="7,253,13.356.0,18.356.1,15.205.0,22.159.0,21.195.0,27.130.0,23.158.0,45.160.0"}
P.entries["npc:jahan-hawkwing"] = {n="Jahan Falkenschwinge",s="Jahan Falkenschwinge ist ein Tauren-Rüstungsmacher, der im Wegekreuz im Brachland stationiert ist. Er versorgt Reisende, die sich den rauen, von Raubtieren wimmelnden Ebenen stellen, mit grundlegender Leder- und Kettenausrüstung.",h="Jahan Falkenschwinge ist ein Tauren-Rüstungsmacher, der im Wegekreuz im Brachland stationiert ist.",kw={"rüstungsmacher","bündel mit bälgen","kettenrüstung","das wegekreuz","jahan falkenschwinge","lederrüstung","tauren","brachland"},ang={["faction:Horde"]="Stationiert an der Kreuzung der wichtigsten Pfade von Kalimdor sorgt Jahan dafür, dass Krieger und Späher der Horde gegen die unerbittlichen Angriffe der Zentauren und die einheimische Tierwelt gerüstet bleiben.",["race:Tauren"]="Jahan verkörpert die praktische, eigenständige Natur der Shu'halo und nutzt Fellhandwerk sowie robuste Materialien, um Reisende in den angestammten Ländern des Brachlands zu schützen."},sec={{t="Rüstungsmacher vom Wegekreuz",b="Am geschäftigen Knotenpunkt des Wegekreuzes gelegen, kümmert sich Jahan Falkenschwinge um die Ausrüstungsbedürfnisse von Wanderern und Verteidigern der Horde. Das Brachland ist ein gnadenloses Weideland, in dem widerstandsfähige Schutzausrüstung oft den Unterschied zwischen Überleben und dem Tod durch Zentauren, Borstennacken oder wilde Bestien ausmacht. Jahan arbeitet mit lokalen Lederverarbeitern zusammen und kümmert sich um Lieferungen von gegerbten Fellen, um seinen Laden mit verlässlichem gegerbtem Leder und robuster Kettenrüstung zu versorgen."}},faq={{q="Wer ist Jahan Falkenschwinge?",a="Jahan Falkenschwinge ist ein Tauren-Händler und Rüstungsmacher, der im Wegekreuz im Brachland lebt. Er versorgt durchreisende Abenteurer und Wachen der Horde mit schützender Leder- und Kettenausrüstung.",al={"jahan falkenschwinge lore","wer ist jahan","das wegekreuz rüstungshändler"}},{q="Welche Waren verkauft er?",a="Jahan verkauft einfache Sets aus gegerbtem Leder und Kettenrüstung, darunter Wämser, Stiefel, Gürtel, Armschienen und Handschuhe, die für unerfahrene Krieger, Jäger und Späher geeignet sind.",al={"was verkauft jahan","jahan falkenschwinge inventar","jahan rüstung"}},{q="Welche Aufgaben bietet er Reisenden an?",a="Jahan verlässt sich auf nahegelegene Handwerker, um seine Waren zu beziehen. Er bittet hilfsbereite Reisende darum, Lieferungen roher oder vorbereiteter Materialien zu übernehmen, schickt Bündel mit Bälgen an lokale Gerber und erwartet im Gegenzug fertige Waren.",al={"jahan quests","quest bündel mit bälgen","das wegekreuz bälgerlieferung"}}},fx={["31c7a7fc"]={q="Auf wessen Seite steht Jahan Falkenschwinge?",a="Jahan Falkenschwinge steht fest zur Horde und zu seinen Tauren-Gefährten. Er ist am Wegekreuz stationiert, einem wichtigen Knotenpunkt, der die Gebiete der Horde im zentralen Kalimdor verbindet, und stellt denjenigen, die diese Ländereien gegen Zentauren, Stacheleber und rivalisierende Fraktionen verteidigen, wichtigen Proviant und robuste Rüstungen zur Verfügung.",al={"jahan falkenschwinge fraktion","ist jahan falkenschwinge horde","jahan falkenschwinge allianz oder horde"}},f61d6720={q="Warum ist Jahan Falkenschwinge im Wegekreuz?",a="Jahan Falkenschwinge verdient seinen Lebensunterhalt als Händler für Leder- und Kettenrüstung im Wegekreuz. Da der Außenposten jeden Tag zahllose Kundschafter, Jäger und Reisende sieht, die durch das Brachland ziehen, versorgt sie sein Handwerk mit robuster Ausrüstung, die nötig ist, um in der rauen Wildnis zu überleben.",al={"warum ist jahan falkenschwinge hier","standort von jahan falkenschwinge","jahan falkenschwinge wegekreuz"}}},fp="14,183,25.437.0,22.183.0,24.165.0,38.206.0"}
P.entries["npc:jaina-proudmoore"] = {n="Jaina Prachtmeer",s="Lady Jaina Prachtmeer ist die Herrscherin über die Insel Theramore und die mächtigste lebende menschliche Zauberin. Einst eine Musterschülerin der Kirin Tor von Dalaran, führte sie die Überlebenden von Lordaeron über das Große Meer und bemüht sich nun darum, einen zerbrechlichen Frieden zwischen der Allianz und der Neuen Horde aufrechtzuerhalten.",h="Lady Jaina Prachtmeer ist die Herrscherin über die Insel Theramore und die mächtigste lebende menschliche...",kw={"antonidas","arthas","marschen von dustwallow","jaina","kirin tor","proudmoore","theramore","thrall"},ang={["class:Mage"]="Unter Erzmagier Antonidas persönlich ausgebildet, gilt Lady Jaina weithin als die mächtigste lebende menschliche Zauberin, die den Gipfel der arkanen Meisterschaft Dalarans verkörpert.",["faction:Alliance"]="Jaina sichert der Allianz ihren entscheidenden Stützpunkt im südlichen Kalimdor und balanciert die Loyalität gegenüber Hochlord Bolvars Regentschaft in Sturmwind mit ihrem Wunsch aus, einen Krieg mit der benachbarten Horde zu verhindern."},sec={{t="Flucht nach Kalimdor",b="Als Tochter von Großadmiral Daelin Prachtmeer von Kul Tiras zeigte Jaina schon früh eine bemerkenswerte Begabung für das Arkane und lernte in Dalaran unter Erzmagier Antonidas. Während des Dritten Krieges untersuchte sie an der Seite von Prinz Arthas Menethil die mysteriöse Seuche des Untods und erlebte den tragischen Untergang von Lordaeron aus erster Hand mit. Geleitet von den Warnungen des Propheten Medivh scharte sie eine Expedition menschlicher Überlebender um sich und segelte gen Westen zum vergessenen Kontinent Kalimdor. Dort schlossen ihre Streitkräfte ein beispielloses Bündnis mit Thralls Horde und den Nachtelfen und standen auf dem Hyjal Seite an Seite, um Archimonde zu bezwingen und die Invasion der Brennenden Legion zunichtezumachen."},{t="Die Herrin von Theramore",b="Nach der Niederlage der Legion gründete Jaina vor der Küste der Düstermarschen die Inselfestung Theramore und errichtete damit die wichtigste Bastion der Allianz im südlichen Kalimdor. Ihre Hingabe an die Diplomatie wurde auf eine harte Probe gestellt, als ihr Vater eintraf, um Rache an den Orcs zu nehmen; Jaina weigerte sich, seinen Krieg zu unterstützen, und trat beiseite, als Thralls Streitkräfte den Großadmiral erschlugen, um zu verhindern, dass Kalimdor in einen weiteren verheerenden Konflikt stürzte. Heute regiert sie Theramore als standhafte Verfechterin der Koexistenz, arbeitet eng mit Kriegshäuptling Thrall zusammen und festigt gleichzeitig die Präsenz der Allianz gegen die zunehmenden lokalen Spannungen."}},faq={{q="Wer ist Lady Jaina Prachtmeer?",a="Jaina ist die Herrscherin über die Insel Theramore und wohl die begabteste lebende menschliche Magierin. Sie ist die Tochter des verstorbenen Großadmirals Daelin Prachtmeer von Kul Tiras und eine ehemalige Schülerin von Erzmagier Antonidas in Dalaran.",al={"wer ist jaina","jaina prachtmeer lore","theramore anführer"}},{q="Warum ist Jaina in Kalimdor statt in den Östlichen Königreichen?",a="Vor dem Fall von Lordaeron im Dritten Krieg warnte der Prophet Medivh Jaina davor und riet ihr, so viele Menschen wie möglich über das Meer nach Kalimdor zu führen. Ihre Expedition überlebte die Reise, kämpfte am Hyjal und errichtete die Hafenfestung Theramore in den Düstermarschen.",al={"warum verließ jaina lordaeron","jaina kalimdor","warum ist theramore hier"}},{q="Wie ist Jainas Verhältnis zur Horde?",a="Jaina pflegt eine ungewöhnliche, vorsichtige Freundschaft mit Kriegshäuptling Thrall. Nachdem sie am Hyjal gemeinsam gegen die Brennende Legion gekämpft hatten, bemühen sich beide Anführer darum, den Frieden zwischen ihren Völkern zu wahren – trotz des erbitterten Widerstands von Hardlinern auf beiden Seiten.",al={"ist jaina mit thrall befreundet","jaina und horde","hasst jaina orcs"}},{q="Was geschah zwischen Jaina und Prinz Arthas Menethil?",a="Jaina und Arthas waren Freunde aus Kindheitstagen, deren Bindung im jungen Erwachsenenalter zu einer Romanze heranwuchs. Sie untersuchten gemeinsam die Seuche, die sich über Lordaeron ausbreitete, doch Jaina war entsetzt über Arthas' Abgleiten in die Skrupellosigkeit – was im Ausmerzen von Stratholme gipfelte, wo sie sich weigerte, am Abschlachten der infizierten Bürger teilzunehmen.",al={"jaina und arthas","liebte jaina arthas"}}},fp="16,283,18.679.0,21.631.0,29.218.0,57.265.0,44.259.0,55.332.0"}
P.entries["npc:james-halloran"] = {n="James Halloran",s="James Halloran ist ein menschlicher Gerber, der im Sumpfland arbeitet, um die östlichen Königreiche mit feinen Häuten zu versorgen. Er lebt im Hafen von Menethil und verdient seinen Lebensunterhalt mit der Ernte der zähen, wertvollen Häute der heimischen Krokilisken der Region. Er ist auf durchreisende Abenteurer und nahe Handelswege angewiesen, um Rohmaterialien zu sammeln und seine fertigen Lederwaren zum Markt zu transportieren.",h="James Halloran ist ein menschlicher Gerber, der im Sumpfland arbeitet, um die östlichen Königreiche mit...",kw={"krokilisken","halloran","james halloran","lederverarbeitung","der hafen von menethil","gerber","sumpfland"},ang={["class:Hunter"]="Jäger, die durch die durchnässten Sümpfe navigieren, werden Gemeinsamkeiten mit Halloran finden, dessen Lebensunterhalt davon abhängt, die aggressiven Reptilienräuber des Sumpflands aufzuspüren und zu ernten.",["faction:Alliance"]="Hallorans Handel trägt dazu bei, die kommerzielle Präsenz der Allianz im rauen Sumpfland aufrechtzuerhalten, indem er Städte im ganzen Königreich mit wertvollem, handgefertigtem Leder versorgt."},sec={{t="Ein Gerber im Sumpf",b="Von seinem Zuhause im Hafen von Menethil aus verdient James Halloran seinen Lebensunterhalt mit dem Sumpfgebiet direkt vor der Stadt. Als unternehmungslustiger Gerber erkannte Halloran, dass die gefährlichen Moore eine lukrative Ware bieten: Krokiliskenhäute. Die Verarbeitung der rauen Haut von Sumpfreptilien zu hochwertigem Leder erfordert seltenes Handwerk, und Hallorans fertige Waren werden über lokale Handelswege an Käufer in ganz Azeroth verschifft."},{t="Häute, Lehrlinge und täglicher Handel",b="Die Arbeit so nah am Sumpf ist mit ständiger Gefahr verbunden. Halloran kann nicht einfach jedes Biest selbst jagen, während er sich um Gerbfässer und Handelslogistik kümmert. Er heuert häufig abgehärtete Reisende an, um die gröberen Arbeiten wie das Häuten junger Sumpfbestien und die Abwicklung der routinemäßigen Lieferungen zwischen seinem Arbeitsplatz und den umliegenden Siedlungen zu erledigen, damit sein geschäftiges Lederhandwerk stets ausreichend versorgt bleibt."}},faq={{q="Wer ist James Halloran?",a="James Halloran ist ein menschlicher Gerber, der im Hafen von Menethil im Sumpfland ansässig ist. Er ist darauf spezialisiert, die heimischen Krokilisken der Region zu jagen und zu häuten und ihre zähen Häute zu Lederwaren zu gerben, die in die ganze Welt exportiert werden.",al={"james halloran","halloran","wer ist halloran","gerber sumpfland"}},{q="Wo verkauft James Halloran sein Leder?",a="Halloran verarbeitet rohe Krokiliskenhäute zu feinem Leder und verschifft es in ganz Azeroth. Er ist stark auf den Seehandel angewiesen, der durch den Hafen von Menethil führt, um seine Waren über die Meere zu vertreiben.",al={"halloran lederhandel","wohin gehen krokiliskenhäute","halloran geschäft"}},{q="Warum benötigt Halloran Abenteurer, um Häute junger Krokilisken zu sammeln?",a="Das Gerben von Leder ist eine zeitaufwendige und arbeitsintensive Arbeit. Halloran beschäftigt reisende Abenteurer, um die lokalen Sumpfkrokilisken zu dezimieren und ihre Häute abzuziehen, damit er einen stetigen Vorrat an Rohmaterial hat, ohne seine Werkstatt verlassen zu müssen.",al={"warum junge krokilisken töten","quest häute junger krokilisken","krokiliskenhäute halloran"}},{q="Was verbindet Halloran mit dem Hafen von Menethil?",a="Der Hafen von Menethil dient als wichtigster Handels- und Versorgungsknotenpunkt der Region. Halloran verlässt sich auf den Hafen und seine Schifffahrtsrouten, um seine gegerbten Häute auf entfernte Märkte zu exportieren und sein Gerberhandwerk lebensfähig zu halten.",al={"halloran menethil","halloran hafenverbindung","wohnt halloran in menethil"}},{q="Wo ist James Halloran zu finden?",a="Halloran lebt und arbeitet im Hafen von Menethil, dem geschäftigen Hafen an der Westküste des Sumpflands, mit den Krokilisken-Sümpfen direkt vor der Stadt.",al={"halloran standort","wo ist james halloran","halloran finden"}},{q="Hat Halloran einen Lehrling?",a="Ja. Halloran schickte seinen Lehrling, den er wie einen Sohn betrachtet, in die Sümpfe, um riesige Krokilisken zu häuten, aber der junge Mann wurde zerfleischt und verlor ein Bein. Während sich der Lehrling erholt, verlässt sich Halloran auf abgehärtete Reisende, um die Häute zu sammeln, von denen sein Handwerk abhängt.",al={"halloran lehrling","aufgaben lehrling halloran","wer arbeitet für halloran"}}},fx={["21c95e2f"]={q="Auf wessen Seite steht James Halloran?",a="James Halloran ist mit der Allianz verbündet. Als menschlicher Handwerker, der im Sumpfland arbeitet, unterhält er Verbindungen zur Hafenstadt Hafen von Menethil, um seine Waren in den Gebieten der Allianz bereitzustellen.",al={"ist halloran allianz","fraktion von james halloran","wem dient halloran"}},b76d5522={q="Warum ist James Halloran hier im Sumpfland?",a="Halloran verdient seinen Lebensunterhalt als Gerber und Fallensteller. Die Sümpfe und Wasserwege des Sumpflands wimmeln nur so vor Krokolisken, was ihm einen stetigen Vorrat an Häuten liefert, die er gerbt und weit und breit exportiert.",al={"warum ist halloran im sumpfland","zweck von james halloran","warum ist halloran hier"}}},fp="14,354,23.426.0,35.394.0,22.229.0,43.205.0,68.243.0,49.210.0,34.143.0,33.260.0"}
P.entries["npc:jannok-breezesong"] = {n="Jannok Windsang",s="Jannok Windsang ist ein Nachtelfenschurkenlehrer, der im Dorf Dolanaar auf Teldrassil stationiert ist. Er unterweist junge Kaldoreischurken, die sich in das Geäst des Weltenbaums hinauswagen, in Heimlichkeit, List und Klingenkunst.",h="Jannok Windsang ist ein Nachtelfenschurkenlehrer, der im Dorf Dolanaar auf Teldrassil stationiert ist.",kw={"breezesong","dolanaar","erion schattenflüsterer","jannok","nachtelf","schurkenlehrer","teldrassil"},ang={["class:Rogue"]="Für junge Nachtelfenschurken, die auf Teldrassil anfangen, ist Jannok Euer entscheidender Mentor in Dolanaar, bevor Ihr Euch in die Hauptstadt begebt.",["race:NightElf"]="Während die Kultur der Kaldorei oft die Schildwachen und das Druidentum hervorhebt, bereiten Ausbilder wie Jannok jene vor, die Heimlichkeit, Gifte und Dolche bevorzugen."},sec={{t="Ein Wegweiser in den Schatten",b="Unter den Ästen von Dolanaar anzutreffen, dient Jannok Windsang als primärer Ausbilder für angehende Nachtelfenschurken. Anders als die förmlichen Schildwachen oder die zurückgezogenen Druiden von Teldrassil leitet Jannok jene an, die lautlos am Rande der Gesellschaft agieren. Er lehrt sie, durch die Schatten zu schleichen, aus dem Hinterhalt zuzuschlagen und ungesehen im Geäst zu überleben. Sobald ein Schurke die ersten Lektionen in Dolanaar hinter sich gelassen hat, schickt Jannok ihn weiter zu erfahreneren Meistern in der Hauptstadt Darnassus."}},faq={{q="Wer ist Jannok Windsang?",a="Jannok Windsang ist ein Nachtelfenschurkenlehrer mit Wohnsitz in Dolanaar auf Teldrassil. Er bringt jungen Kaldorei grundlegende Schurkenfähigkeiten und -techniken bei.",al={"wer ist jannok","jannok windsang rolle","schurkenlehrer dolanaar"}},{q="Wohin schickt Jannok aufstrebende Schurken?",a="Sobald ein Schurke seine frühe Ausbildung in Dolanaar abgeschlossen hat, weist Jannok ihn an, nach Darnassus zu reisen, um bei Erion Schattenflüsterer, einem höherrangigen Schurkenlehrer in der Enklave des Cenarius der Stadt, weiteren Unterricht zu nehmen.",al={"jannok quest","erion schattenflüsterer quest","dolanaar schurke naechster schritt"}},{q="Wo finde ich Jannok in Dolanaar?",a="Jannok befindet sich in Dolanaar, der zentralen Siedlung von Teldrassil außerhalb von Laubschattental, platziert bei den Ausbilderpavillons des Ortes.",al={"jannok aufenthaltsort","wo ist jannok","jannok windsang finden"}}},fx={f606b9db={q="Auf wessen Seite steht Jannok Windsang?",a="Jannok dient Darnassus und der Allianz. Als Ausbilder für Nachtelf-Schurken, der im Dorf Dolanaar stationiert ist, gilt seine Loyalität der Nation der Kaldorei und der Verteidigung von Teldrassil.",al={"fraktion von jannok windsang","wem dient jannok","loyalität von jannok"}},b07dd258={q="Warum ist Jannok Windsang hier?",a="Jannok ist in Dolanaar stationiert, um angehende Nachtelf-Schurken auszubilden, die aus dem Laubschattental kommen. Er bietet Training in Verstohlenheit und List an und schickt vielversprechende Kundschafter schließlich an Mentoren wie Erion Shadewhisper in Darnassus weiter.",al={"warum ist jannok in dolanaar","zweck von jannok windsang","warum ist jannok hier"}}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jasper-fel"] = {n="Jasper Teufel",s="Jasper Teufel ist ein diskreter Händler, der vom Hauptquartier des SI:7 in Sturmwinds Altstadt aus operiert. Er versorgt Agenten mit Dolchen und verschiedenen Phiolen, behält Besucher scharf im Auge und ermahnt sie, ihre Zungen zu hüten. Sein stiller Handel unterstützt den verdeckten Arm des Königreichs hinter verschlossenen Türen.",h="Jasper Teufel ist ein diskreter Händler, der vom Hauptquartier des SI:7 in Sturmwinds Altstadt aus operiert.",kw={"dolche","jasper teufel","morbent teufel","die altstadt","schurkenbedarf","der si:7","sturmwind","phiolen"},ang={["class:Rogue"]="Jasper Teufel bietet die unverzichtbaren Phiolen und Ersatzklingen, die von verdeckten Agenten bei der Ausübung ihres Handwerks in Sturmwind benötigt werden.",["faction:Alliance"]="Aus dem Hauptquartier des SI:7 stellt Fel sicher, dass die Agenten, die das Königreich aus den Schatten heraus verteidigen, stets zuverlässigen Nachschub haben."},sec={{t="Vorräte für die Schatten",b="Versteckt in der Kaserne des SI:7 in der Altstadt bedient Jasper Teufel eine ganz bestimmte Klientel. Anstatt Standardwaffen an die Stadtwache zu verkaufen, bietet er unverzichtbare Werkzeuge des Spionagehandwerks: einfache Dolche und die empfindlichen Phiolen, die zum Brauen und Auftragen von Giften benötigt werden. Fel arbeitet unter der strengen Disziplin von Mathias Shaws Geheimdienstabteilung und ermahnt jeden, der sich ihm nähert, kurz angebunden, auf seine Worte zu achten. In einer Festung, die der Spionage und der lautlosen Tödlichkeit gewidmet ist, kann leichtsinniges Geplauder schnell zu einem frühen Ende führen."}},faq={{q="Wo kann ich Jasper Teufel finden?",a="Jasper Teufel ist im Hauptquartier des SI:7 im östlichen Teil von der Altstadt in Sturmwind stationiert.",al={"jasper teufel standort","wo ist jasper teufel","jasper teufel sturmwind"}},{q="Was verkauft Jasper Teufel?",a="Er liefert einfache Dolche und leere Phiolen verschiedener Güteklassen, was ihn zu einer nützlichen Anlaufstelle für Agenten macht, die sich mit Giftkomponenten eindecken möchten.",al={"jasper teufel händler","was verkauft fel","jasper teufel waren"}},{q="Ist Jasper Teufel mit Morbent Teufel verwandt?",a="Sie teilen denselben Nachnamen, was zu Spekulationen über eine familiäre Verbindung zu dem Nekromanten Morbent Teufel im Dämmerwald geführt hat, wenngleich Jasper selbst zu persönlichen Angelegenheiten schweigt.",al={"jasper teufel morbent teufel","ist jasper teufel mit morbent verwandt","familie fel dämmerwald"}},{q="Warum warnt Jasper Teufel Besucher davor, leise zu sprechen?",a="Er arbeitet direkt im SI:7, dem Herzen von Sturmwinds Spionageapparat. Unbedachte Worte gelten in einer Organisation voller Attentäter und Spione als gefährlich, und Fel stellt sicher, dass Besucher dem Hauptquartier mit der gebotenen Vorsicht begegnen.",al={"warum leise sprechen","jasper teufel warnung","falsches wort kehle durchgeschnitten"}}},fx={["4d6e97a5"]={q="Wer ist Jasper Teufel?",a="Jasper Teufel ist ein diskreter menschlicher Händler, der von Sturmwind aus operiert. Eingebettet in die geheimen Grenzen der Altstadt und in engem Kontakt mit Agenten des SI:7, stellt er verdeckte Vorräte, Phiolen und einfache Waffen für Schurken und geheime Agenten bereit, die sich durch die zwielichtige Unterwelt der Stadt bewegen.",al={"geschichte von jasper teufel","wer ist jasper teufel","identität von jasper teufel"}},["0dbc34cf"]={q="Auf wessen Seite steht Jasper Teufel?",a="Jasper Teufel ist loyal gegenüber Sturmwind und der Allianz und arbeitet in enger Abstimmung mit dem verdeckten Geheimdienstnetzwerk des SI:7. Während seine zwielichtige Persönlichkeit und seine gefährlichen Warnungen auf ein abtrünniges Element hindeuten könnten, unterstützt sein Handel direkt Agenten, die aus der Altstadt heraus den Interessen des Königreichs dienen.",al={"jasper teufel allianz","wem dient jasper teufel","fraktion von jasper teufel"}},["50a88541"]={q="Warum ist Jasper Teufel hier?",a="Jasper Teufel ist im Gebiet des SI:7 in der Altstadt stationiert und dient als unauffälliger Lieferant für Agenten, die Tools of the Trade benötigen. Ob er nun leere Phiolen für das Brauen von Giften oder einfache Klingen für stille Arbeit bereitstellt, er steht bereit, um verdeckte Aktivitäten abseits neugieriger Blicke zu unterstützen.",al={"warum ist jasper teufel in der altstadt","zweck von jasper teufel","warum ist jasper teufel hier"}}},fp="10,297,24.536.0,28.115.0,26.134.0,37.178.0,49.240.0"}
P.entries["npc:je-neu-sancrea"] = {n="Je'neu Sancrea",s="Je'neu Sancrea ist ein Dunkelspeertroll und ein Mitglied des Irdenen Rings, der am Außenposten von Zoram'gar an der Küste von Eschental stationiert ist. Da er finstere Erschütterungen tief unter dem Ufer spürt, leitet er Abenteurer der Horde an, die Verderbnis zu untersuchen, die den uralten, versunkenen Tempel der Tiefschwarzen Grotte heimsucht.",h="Je'neu Sancrea ist ein Dunkelspeertroll und ein Mitglied des Irdenen Rings, der am Außenposten von Zoram'gar...",kw={"aku'mai","tiefschwarze grotte","der irdene ring","je'neu sancrea","jeneu","schattenhammer","der zoramstrand","außenposten von zoram'gar"},ang={["class:Shaman"]="Als prominentes Mitglied der Dunkelspeer im Irdenen Ring verkörpert Je'neu die schamanische Pflicht, verderbte Elementare ins Gleichgewicht zu bringen und die Gewässer Kalimdors wiederherzustellen.",["faction:Horde"]="Je'neu dient als wichtigster Questknotenpunkt und geschichtlicher Führer der Horde für den Vorstoß in die Tiefschwarze Grotte von Eschental aus.",["race:Troll"]="Je'neu zeigt, wie die Dunkelspeertrolle an der Seite ihrer Verbündeten unter den Tauren und Orcs die spirituellen Pfade des Irdenen Rings angenommen haben."},sec={{t="Ein Schamane am Strand",b="Während sich der Großteil des Irdenen Rings auf die elementare Harmonie in ganz Kalimdor konzentriert, wacht Je'neu Sancrea über den abgelegenen und gefährlichen Zoramstrand. Vom Außenposten von Zoram'gar aus beobachtet er die finsteren Erschütterungen und unnatürlichen Gezeiten, die sich nahe dem verfallenen Tempel der Tiefschwarzen Grotte regen. Obwohl er an die schamanischen Pflichten seines Zirkels gebunden ist, arbeitet er aufgrund seiner tiefen Loyalität zum Stamm der Dunkelspeer und Thralls Horde ausschließlich mit Streitern der Horde zusammen."},{t="Schatten der Tiefe",b="Je'neu versucht, die wahre Ursache hinter der schleichenden Verderbnis an der Küste aufzudecken. Mithilfe kühner Abenteurer sammelt er besudelte Saphirkerne, untersucht die abscheulichen Überreste von Wasserelementaren wie Baron Aquanis und entlarvt den heimtückischen Einfluss des Schattenhammerkults. Die finsteren Rituale, die sich unter den Wellen abspielen, bedrohen nicht nur das Gleichgewicht der lokalen Elemente, sondern künden auch von der düsteren Rückkehr jener Mächte, die den Alten Göttern die Treue geschworen haben."}},faq={{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Schamane der Dunkelspeertrolle, der dem Irdenen Ring angehört. Er ist am Außenposten von Zoram'gar an der Küste von Eschental stationiert, wo er die wachsende Verderbnis überwacht, die aus der Tiefschwarzen Grotte dringt.",al={"wer ist jeneu","jeneu sancrea lore","was ist jeneu"}},{q="Warum interagiert Je'neu nur mit Abenteurern der Horde, wenn er dem Irdenen Ring angehört?",a="Obwohl der Irdene Ring als Organisation eher das elementare Gleichgewicht anstrebt als den Krieg der Fraktionen, sind Je'neus persönliche Bande fest im Stamm der Dunkelspeer und der Horde verwurzelt. Da er sich in einem militärischen Vorposten der Horde an vorderster Front in Eschental aufhält, heißt er Reisende der Allianz nicht willkommen.",al={"warum nur horde","kann allianz mit jeneu sprechen","ist jeneu neutral"}},{q="Was untersucht Je'neu in der Tiefschwarzen Grotte?",a="Je'neu untersucht die unnatürlichen Unruhigen Elemente und die dunkle Magie, die aus der Tiefschwarzen Grotte aufsteigen. Er beauftragt Streiter damit, verderbte Wasserkerne zu beschaffen, Kultisten des Schattenhammers zu töten und Gerüchte zu überprüfen, wonach eine uralte Hydra namens Aku'mai bösartigen Meistern tief unter dem Meer dient.",al={"jeneu questziele","was will jeneu","warum spieler in die bfd schicken"}},{q="Wo befindet sich Je'neu Sancrea?",a="Je'neu befindet sich am Außenposten von Zoram'gar, einer befestigten Siedlung der Horde an der äußersten Nordwestküste von Eschental, direkt am Zoramstrand, kurz südlich der Tiefschwarzen Grotte.",al={"wo ist jeneu","jeneu sancrea standort","jeneu finden"}},{q="Was ist der Irdene Ring?",a="Der Irdene Ring ist ein uralter Zirkel von Schamanen, der sich dem Verstehen und Besänftigen der Elementargeister der Welt widmet und immer dann einschreitet, wenn dunkle Mächte oder chaotische Wesenheiten die natürliche elementare Harmonie stören.",al={"der irdene ring lore","was ist der irdene ring","schamanenorganisation"}},{q="Welche Gefahr geht vom Schattenhammer in den Tiefen aus?",a="Der Kult des Schattenhammers hat die Tiefschwarze Grotte infiltriert, um die Bestie Aku'mai zu verehren und Rituale abzuhalten, die den Alten Göttern geweiht sind. Je'neu beauftragt Abenteurer der Horde damit, ihre Anführer niederzustrecken, um ihr finsteres Werk aufzuhalten.",al={"schattenhammer bfd","schattenhammerkult eschental","wer sind die kultisten in bfd"}}},fx={["1670a3c0"]={q="Warum ist Je'neu Sancrea hier?",a="Je'neu hat sich am Außenposten von Zoram'gar entlang der Küste des Eschentals stationiert, um die finstere Verderbnis zu beobachten, die sich in den nahen Ruinen der Tiefschwarzen Grotte regt. Der Irdene Ring spürte üble Störungen im natürlichen Gleichgewicht der Gewässer, was ihn an diese Grenze zog, um die sich versammelnden Kultisten zu überwachen und erfahrene Champions der Horde anzuwerben, um die Tiefen zu durchkämmen.",al={"warum ist jeneu im eschental","warum ist jeneu sancrea in zoramgar","was führt jeneu sancrea hierher"}}},fp="14,300,22.452.0,19.449.1,22.215.0,71.296.0,50.299.0,32.174.0,25.212.0,57.225.0"}
P.entries["npc:jen-shan"] = {n="Jen'shan",s="Jen'shan ist eine Dschungeltrollin der Dunkelspeer und eine Jägerlehrerin, die im Tal der Prüfungen in Durotar stationiert ist. Sie leitet angehende Schützen der Orcs und Trolle an, während diese ihre ersten Schritte in die Wildnis der Horde wagen. Junge Jäger werden zu ihr geschickt, um die Grundlagen des Fährtenlesens, des Fernkampfs und des Überlebens zu erlernen.",h="Jen'shan ist eine Dschungeltrollin der Dunkelspeer und eine Jägerlehrerin, die im Tal der Prüfungen in...",kw={"dunkelspeer","durotar","geätztes pergament","geätzte schrifttafel","jägerlehrer","jen'shan","jenshan","troll","das tal der prüfungen"},ang={["class:Hunter"]="Für junge Jäger der Orcs und Trolle ist Jen'shan die allererste Lehrmeisterin, der Ihr begegnet. Sie lehrt grundlegende Fernkampftechniken, bevor Ihr Euch über die roten Schluchten des Höhlenbaus hinauswagt.",["race:Troll"]="Jen'shan verkörpert das berühmte Können des Dunkelspeerstammes im Fährtenlesen und Kundschaften und stellt sicher, dass junge Trolle ihre angestammten Jagdtraditionen in ihrer neuen Heimat auf dem Festland bewahren."},sec={{t="Lehrmeisterin des roten Sandes",b="Inmitten der verwitterten Lager des Tals der Prüfungen dient Jen'shan als wichtigste Jägerlehrmeisterin für neue Rekruten, die ihren Wert für die Horde beweisen wollen. Junge Orcs und Trolle der Dunkelspeer treffen gleichermaßen ein, während sie beschriftete Tafeln und Pergamente umklammern, die sie geradewegs zu ihr führen. Mit scharfen Augen, die durch Jahre in der ungezähmten Wildnis geschärft wurden, vermittelt sie grundlegende Techniken des Bogenschießens, der Treffsicherheit und des Überlebens in der Wildnis, um sicherzustellen, dass kein Neuling den Skorpionen und Ebern zum Opfer fällt, die den Grund der Schlucht durchstreifen."}},faq={{q="Wer ist Jen'shan?",a="Jen'shan ist eine Dschungeltrollin der Dunkelspeer und Jägerlehrerin, die sich im Tal der Prüfungen in Durotar befindet. Sie unterweist neue Jäger der Horde in grundlegender Wildniskunde, Fährtenlesen und Fernkampfwaffen.",al={"jenshan geschichte","wer ist jenshan","jägerlehrer tal der prüfungen"}},{q="Welche Quests drehen sich um Jen'shan?",a="Neue Jäger werden über einführende Ausbildungsquests zu ihr geschickt. Junge Orcjäger werden angewiesen, bei ihr eine Geätzte Schrifttafel abzugeben, während junge Trolljäger sie mit einem Geätzten Pergament aufsuchen.",al={"jenshan quests","geätzte schrifttafel jenshan","geätztes pergament jenshan"}},{q="Warum bildet ein Troll Jäger auf einem orcischen Prüfungsfeld aus?",a="Das Tal der Prüfungen dient sowohl orcischen Rekruten als auch den vertriebenen Dunkelspeertrollen, die sich Durotar teilen, als gemeinsame Ausbildungsstätte. Als meisterhafte Kundschafter und Pirschjäger spielen Trolle wie Jen'shan eine entscheidende Rolle dabei, neue Krieger und Jäger beider Völker auf den Dienst für die Horde vorzubereiten.",al={"warum ist ein troll im tal der prüfungen","troll-lehrer in durotar"}}},fx={["9968b478"]={q="Auf wessen Seite steht Jen'shan?",a="Jen'shan ist der Horde und ihrem Volk, dem Darkspear tribe, loyal. Sie ist im Tal der Prüfungen stationiert und dient an der Seite der Orcs, um sicherzustellen, dass neue Rekruten, egal ob Troll oder Orc, angemessen auf die raue Realität des Überlebens in Durotar und den Kampf für den Kriegshäuptling vorbereitet sind.",al={"fraktion von jenshan","ist jenshan horde","loyalität von jenshan"}},f50adc74={q="Was möchte Jen'shan?",a="Jen'shan versucht, angehenden Jägern Treffsicherheit, Überlebenskunst und die wilden Instinkte beizubringen, die sie zum Durchhalten brauchen. Sie möchte, dass vielversprechende junge Kundschafter ihr Handwerk schnell verfeinern, damit sie mit den wilden Bestien, die durch die roten Einöden streifen, fertig werden und die junge Horde vor ihren Feinden schützen können.",al={"motiv von jenshan","ziel von jenshan","was braucht jenshan"}},ece1555d={q="Mit wem ist Jen'shan verbunden?",a="Jen'shan gehört zu den Darkspear-Trollen, die von Sen'jins Sohn Vol'jin angeführt werden. Da sich die Darkspear Durotar mit Thralls Orcs teilen, arbeitet sie eng mit den Ausbildern des Tals der Prüfungen zusammen, um frische Rekruten beider Völker in die Reihen der Horde zu führen.",al={"verbindungen von jenshan","jenshan darkspear verbindungen","wem dient jenshan"}}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jennea-cannon"] = {n="Jennea Haubitz",s="Jennea Haubitz ist eine angesehene menschliche Magierlehrerin, die im Magiersanktum im Magierviertel von Sturmwind residiert. Sie überwacht die Ausbildung von Zaubernovizen, führt sie durch grundlegende Studien und untersucht Störungen im Fluss der lokalen arkanen Energien. Durch ihre Aufgaben prüft sie, ob die Lehrlinge die nötige Disziplin besitzen, um Magie zu beherrschen, ohne von ihr verzehrt zu werden.",h="Jennea Haubitz ist eine angesehene menschliche Magierlehrerin, die im Magiersanktum im Magierviertel von...",kw={"andromath","zur blauen einsiedlerin","jennea haubitz","das magierviertel","magierlehrer","spiegelsee","sturmwind","sanktum der magier"},ang={["class:Mage"]="Jennea ist eine unverzichtbare frühe Mentorin für Magier der Allianz, die Eure ersten Nachforschungen im Feld leitet und Euch dabei hilft, Eure formelle Zaubererrobe und Euren ersten Stab herzustellen.",["faction:Alliance"]="Aus dem Herzen von Sturmwind Magierviertel sorgt Jennea dafür, dass die neuen Zauberwirker des Königreichs diszipliniert und fähig sind, der Allianz auf sichere Weise zu dienen."},sec={{t="Eine Führerin im Sanktum",b="Oben auf dem spiralförmigen Aufgang des Magiersanktums positioniert, steht Jennea Haubitz als eine der primären Mentorinnen für arkane Praktizierende bereit, die nach Sturmwind kommen. Anstatt den Schülern lediglich Zaubersprüche einzubläuen, betont sie Vorsicht und Selbstbeherrschung. Nicht-Magiern, die den Turm durchqueren, erteilt sie eine deutliche Warnung: Unkontrollierte Magie verbrennt die Ungeübten – eine Wahrheit, die angehende Zauberwirker unter ihrer Anleitung schnell lernen."},{t="Feldarbeit und Grundlagen",b="Jennea ist davon überzeugt, dass magische Theorie durch praktische Beobachtung erprobt werden muss. Häufig schickt sie vielversprechende Lehrlinge vor die Tore der Stadt, beispielsweise um Orte wie den Spiegelsee im Wald von Elwynn zu untersuchen und zu verstehen, wie natürliche Wasserquellen mit arkaner Resonanz interagieren. Schreiten die Schüler voran, prüft sie deren Entschlossenheit, indem sie sie damit beauftragt, Störungen in der Taverne Zur Blauen Einsiedlerin nachzugehen oder unbeständige Reagenzien für die Herstellung ihrer ersten echten Zaubererwerkzeuge zu sammeln."},{t="Verbindungen zu höheren Meistern",b="Während Jennea den grundlegenden Unterricht und lokale Angelegenheiten betreut, erkennt sie genau, wann ein Lehrling ihren Lehrplan hinter sich gelassen hat. Sobald ein Initiand wahres Potenzial zeigt, schickt sie ihn in der Hierarchie des Sanktums weiter hinauf zu Zaubermeister Andromath oder gar über die Grenzen des Königreichs hinaus zu zurückgezogen lebenden Zauberkundigen wie Tabetha tief in den Düstermarschen."}},faq={{q="Wer ist Jennea Haubitz?",a="Sie ist eine menschliche Magierlehrerin im Magiersanktum im Magierviertel von Sturmwind, die für die Unterweisung neuer Magier und die Leitung früher magischer Forschungen verantwortlich ist.",al={"jennea haubitz","wer ist jennea","magierlehrer sturmwind"}},{q="Wo finde ich Jennea Haubitz?",a="Sie befindet sich im Magiersanktum, dem gewundenen arkanen Turm im Zentrum des Magierviertels in Sturmwind.",al={"jennea haubitz standort","wo ist jennea","jennea finden"}},{q="Welche Quests bietet Jennea Haubitz an?",a="Sie vergibt Klassenquests für Magier der Allianz, darunter die Untersuchung des Spiegelsees im Wald von Elwynn, das Nachforschen merkwürdiger Vorfälle in der Taverne Zur Blauen Einsiedlerin sowie die Materialsammlung zur Herstellung von Magierausrüstung für Novizen.",al={"jennea quests","jennea haubitz questreihe"}},{q="Warum schickt sie Magier zum Spiegelsee?",a="Sie beauftragt Lehrlinge damit, eine Probe aus dem Spiegelsee unterhalb der Wasserfälle von Elwynn zu beschaffen, um sie zu lehren, wie man subtile magische Strömungen der Umgebung wahrnimmt und mit ihnen interagiert.",al={"warum spiegelsee","spiegelsee quest jennea"}},{q="Interagiert Jennea Haubitz mit Klassen, die keine Magier sind?",a="Nicht-Magier können mit ihr sprechen, doch sie erteilt ihnen lediglich den ernsten Ratschlag, im Umgang mit Magie vorsichtig zu sein, und warnt davor, dass sie jeden verbrennt, dem es an der richtigen Ausbildung fehlt.",al={"können nicht magier mit jennea sprechen","jennea für andere klassen"}},{q="Wem untersteht Jennea Haubitz?",a="Sie wirkt innerhalb der Hierarchie des Magiersanktums und leitet Schüler an, bis sie bereit sind, unter hochrangigen Persönlichkeiten wie Zaubermeister Andromath zu lernen.",al={"jenneas vorgesetzter","anführer im sanktum der magier"}}},fx={b57d5dda={q="Auf welcher Seite steht Jennea Haubitz?",a="Jennea dient dem Königreich Sturmwind und der Allianz. Sie ist im Magiersanktum stationiert und arbeitet dort gemeinsam mit dem Zirkel der Zauberer von Sturmwind daran, die magischen Verteidigungsanlagen der Stadt zu stärken und junge, dem Reich treue Magier auszubilden.",al={"jennea haubitz fraktion","wem dient jennea haubitz","jennea haubitz zugehörigkeit"}},d154dff8={q="Was möchte Jennea Haubitz?",a="Jennea widmet sich der Anleitung und Vorbereitung angehender Zauberwirker. Sie möchte sicherstellen, dass Neulinge die gefährliche, unbeständige Natur der arkanen Magie verstehen, und warnt Reisende davor, dass rohe Magie Ungeübte verbrennen kann, während sie vielversprechende Schüler auf wichtige Studien im gesamten Reich hinweist.",al={"jennea haubitz ziel","was möchte jennea","jennea haubitz zweck"}},d5352518={q="Warum ist Jennea Haubitz hier?",a="Sie residiert im Magiersanktum im Magierviertel von Sturmwind, um als Mentorin für Magier der Allianz zu fungieren. Von diesem Turm aus überwacht sie die erste arkane Ausbildung, untersucht Störungen in der Nähe und verweist Praktizierende an höhere Autoritäten wie High Sorcerer Andromath oder Tutoren im Ausland.",al={"warum ist jennea haubitz in sturmwind","jennea haubitz magiersanktum","warum ist jennea im magierviertel"}}},fp="13,395,22.415.0,24.475.0,23.342.0,21.174.0,31.132.0,37.210.0,39.175.0,50.162.0,33.156.0"}
P.entries["npc:jergosh-the-invoker"] = {n="Jergosh der Herbeirufer",s="Jergosh der Herbeirufer ist ein verräterischer Orc-Hexenmeister, der sich tief im Flammenschlund unter Orgrimmar verbirgt. Als hochrangiger Anführer unter den Kultisten der Searing Blade praktiziert er dämonische Künste direkt vor den Augen des Kriegshäuptlings und verschwört sich gegen die Horde.",h="Jergosh der Herbeirufer ist ein verräterischer Orc-Hexenmeister, der sich tief im Flammenschlund unter...",kw={"herbeirufer","jergosh","orgrimmar","der flammenschlund","searing blade","schattenrat","hexenmeister"},ang={["class:Warlock"]="Für Hexenmeister ist Jergosh ein mächtiger Anwender der dämonischen Künste, dessen Pläne die Horde bedrohen.",["faction:Horde"]="Eine Zelle des Schattenrats zu haben, die unter dem Thronsaal des Häuptlings floriert, ist eine unerträgliche Sicherheitsbedrohung, welche die Horde sich nicht leisten kann zu ignorieren.",["race:Orc"]="Jergosh verkörpert das verweilende Gift der alten Horde – die Verlockung von Dämonenblut und Zauberei, die Thrall aus der orcischen Kultur zu tilgen bestrebt ist."},sec={{t="Ein Kult unter der Stadt",b="Während Thrall unermüdlich daran arbeitet, die Orcs auf einen Pfad der Ehre und des Schamanismus zu führen, wies Jergosh diese Ideale zugunsten roher dämonischer Macht zurück. Indem er sich im unterirdischen Labyrinth des Flammenschlunds unter Orgrimmar verbarg, scharte er Anhänger in der Searing Blade um sich, einer heimtückischen Sekte, die mit den Überresten des Schattenrats verbündet ist. In den Schatten direkt unter der Hauptstadt der Horde agierend, arbeitet Jergosh daran, alles zunichtezumachen, wofür The New Horde steht."},{t="Dämonische Ambitionen",b="Jergoshs Anwesenheit in der Kluft ist keineswegs zielloses Umherwandern. Seine dunklen Rituale und gefährlichen Pläne wurden schließlich dreist genug, um die direkte Aufmerksamkeit von Thrall persönlich auf sich zu ziehen. Jergosh stellt eine existenzielle Infektion innerhalb von Durotar dar und erinnert die Horde an die dunklen Pakte, für deren Hinterlassung sie so verzweifelt gekämpft hat."}},faq={{q="Wer ist Jergosh der Herbeirufer?",a="Jergosh der Herbeirufer ist ein mächtiger Orc-Hexenmeister und ein Anführer der Kultisten der Searing Blade, die im Flammenschlund operieren. Anstatt Thralls ehrenhaftem Weg zu folgen, entschied er sich dafür, sich dämonischer Zauberei hinzugeben.",al={"wer ist jergosh","jergosh lore","jergosh flammenschlund"}},{q="Warum versteckt sich Jergosh im Flammenschlund?",a="Der Flammenschlund bietet der Searing Blade ein abgeschiedenes Netzwerk feuriger Höhlen direkt unter Orgrimmar. Von dort aus können Jergosh und seine Kultisten verbotene dunkle Magie praktizieren und sich unentdeckt gegen die Horde verschwören.",al={"warum ist jergosh unter orgrimmar","jergosh aufenthaltsort lore"}},{q="Welcher Fraktion gehört Jergosh an?",a="Jergosh ist ein Anführer innerhalb der Searing Blade, eines Kults, der mit dem Schattenrat in Verbindung steht und sich dem Dienen dämonischer Interessen wie der Brennenden Legion verschrieben hat.",al={"jergosh fraktion","ist jergosh schattenrat","anführer der searing blade"}},{q="Weiß Thrall, dass Jergosh sich unter Orgrimmar befindet?",a="Ja. Jergoshs Pläne wurden gefährlich genug, dass Gerüchte Thrall erreichten, was den Kriegshäuptling dazu veranlasste, vertrauenswürdige Abenteurer in den Flammenschlund zu entsenden, um die Bedrohung durch die Kultisten zu beseitigen.",al={"thrall jergosh","weiß thrall vom flammenschlund"}},{q="Warum praktiziert Jergosh Teufelsmagie anstelle von Schamanismus?",a="Jergosh kehrte dem spirituellen Wiederaufleben seines Volkes bereitwillig den Rücken und lehnte schamanische Harmonie ab, um der berauschenden Macht nachzujagen, die von der Brennenden Legion und den dunklen Künsten versprochen wurde.",al={"warum hexenmeister","jergosh teufelsmagie"}}},fx={["3ff8bf73"]={q="Was möchte Jergosh der Herbeirufer?",a="Jergosh zielt darauf ab, die Horde aus ihrer eigenen Hauptstadt heraus zu untergraben. Er lehnt Thralls erneuerte schamanistische Ideale ab und versucht, dunkle dämonische Praktiken wiederzubeleben und die niederträchtigen Ambitionen des Schattenrats voranzutreiben. Er lauert im Abgrund und heckt subversive Pläne aus, die gefährlich genug sind, um die Stabilität von Orgrimmar selbst zu bedrohen.",al={"ziel von jergosh","was möchte jergosh","motiv von jergosh"}},["752417a2"]={q="Mit wem ist Jergosh der Herbeirufer verbunden?",a="Jergosh ist ein führender Anführer unter den Kultisten der Klinge des Brennenden Messers, einem unterirdischen Zirkel, der direkt unter Orgrimmar operiert. Der Kult ist insgeheim ein Arm des größeren Schattenrats, was Jergosh direkt an das schattenhafte Netzwerk von Hexenmeistern und Dämonenanbetern bindet, die versuchen, das orcische Volk zurück in die Verderbnis zu ziehen.",al={"verbündete von jergosh","für wen arbeitet jergosh","jergosh schattenrat"}},baae249b={q="Warum wird Jergosh der Herbeirufer gefürchtet?",a="Jergosh wird gefürchtet, weil er verbotene Teufelsmagie direkt unter den Füßen der Führung der Horde einsetzt. Seine dunklen Rituale, dämonischen Beschwörungen und seine radikale Ablehnung des Weges der neuen Horde stellen eine existenzielle interne Bedrohung dar, die die direkte Aufmerksamkeit und Besorgnis von Kriegshäuptling Thrall selbst auf sich zieht.",al={"warum wird jergosh gefürchtet","ist jergosh gefährlich","ruf von jergosh"}}},fp="19,250,23.465.0,17.321.1,27.205.0,40.224.0,36.147.0,46.171.0,57.184.0"}
P.entries["npc:jern-hornhelm"] = {n="Jern Hornhelm",s="Jern Hornhelm ist ein Zwergenbergmann der Forscherliga, der in der Stadt Thelsamar stationiert ist. Er koordiniert wichtige Logistik und Kommunikation zwischen der Siedlung, Eisenschmiede und der archäologischen Ausgrabungsstätte tiefer in Loch Modan. Abenteurer unterstützen ihn häufig beim Transport von Bergbaugütern und Fortschrittsberichten durch die Region.",h="Jern Hornhelm ist ein Zwergenbergmann der Forscherliga, der in der Stadt Thelsamar stationiert ist.",kw={"sprengpulver","ausgrabung","forscherliga","ironband","jern hornhelm","loch modan","bergmann","thelsamar"},ang={["faction:Alliance"]="Reisende der Allianz, die Loch Modan durchqueren, finden in Jern einen unverzichtbaren Ansprechpartner, um die Region zu sichern und die zwergische Infrastruktur aufrechtzuerhalten.",["profession:Mining"]="Bergleute werden Jerns handwerklichen Hintergrund und sein praktisches Verständnis für unterirdische Logistik, Sprengungen und den Transport von Ressourcen zu schätzen wissen.",["race:Dwarf"]="Für Zwerge treibt die Unterstützung Jerns direkt die heilige Quest voran, das uralte Erbe der Titanen ihres Volkes tief in den Bergen freizulegen."},sec={{t="Logistik in Thelsamar",b="Stationiert in der rustikalen Stadt Thelsamar, spielt Jern Hornhelm eine wichtige logistische Rolle für die Operationen der Zwerge in ganz Loch Modan. Während Gelehrte und Außenteams der Zwerge in die Wildnis vordringen, um ihre uralte Vergangenheit freizulegen, bleibt die Aufrechterhaltung beständiger Versorgungsketten unerlässlich. Jern sorgt dafür, dass lebenswichtige Ressourcen, Werkzeuge und Nachrichten die aktiven Ausgrabungsstätten sicher erreichen."},{t="Im Dienst der Forscherliga",b="Als Mitglied der Forscherliga schlägt Jern die Brücke zwischen den Archäologen vor Ort und der Führung der Liga in der Hall of Explorers in Eisenschmiede. Stätten wie Eisenbands Ausgrabungsstätte sind stark auf Sprengpulver, Ausrüstung und regelmäßige Depeschen angewiesen, damit die Arbeit voranschreitet. Jern heuert verlässliche Reisende an, um die von Troggs heimgesuchten Straßen zu bewältigen und den Betrieb der Ausgrabung vollständig aufrechtzuerhalten."}},faq={{q="Wer ist Jern Hornhelm?",a="Jern Hornhelm ist ein Zwergenbergmann und Logistikkoordinator mit Sitz in Thelsamar in Loch Modan. Er arbeitet im Auftrag der Forscherliga, um die örtlichen Ausgrabungsarbeiten reibungslos am Laufen zu halten.",al={"wer ist jern","jern hornhelm identität","thelsamar zwerg jern"}},{q="Wo kann ich Jern Hornhelm finden?",a="Er hält sich im Freien in der Stadt Thelsamar auf, die zentral in Loch Modan an der Hauptstraße liegt.",al={"jern hornhelm standort","wo ist jern","jern hornhelm karte"}},{q="Welcher Fraktion gehört Jern Hornhelm an?",a="Jern gehört der Allianz an und vertritt insbesondere die Zwergen-Forscherliga, wobei er die Verlegung von Personal und Bergbaugütern koordiniert.",al={"jern hornhelm fraktion","für wen arbeitet jern","gehört jern zur forscherliga"}},{q="Warum benötigt Jern Sprengpulver für die Ausgrabung?",a="Archäologische Grabungen im bergigen Gelände erfordern kontrollierte Sprengungen, um hartnäckige Felswände zu durchbrechen. Jern koordiniert die Lieferung von speziellem Sprengpulver zu Ausgrabungsleiter Eisenbands Grabungsstätte, damit das Team sicher Relikte der Titanen und uralte Steinhallen freilegen kann.",al={"pulver für ironband lore","warum ausgrabung pulver braucht","sprengpulver loch modan"}},{q="Welche Verbindung hat Jern Hornhelm zu Eisenschmiede?",a="Jern dient als wichtige Kommunikationsverbindung zwischen den abgelegenen Grabungen in Loch Modan und der obersten Führung der Forscherliga in der Hall of Explorers in Eisenschmiede, indem er regelmäßig Fortschrittsberichte aus dem Feld in die Hauptstadt schickt.",al={"jern hornhelm eisenschmiede","meldung in eisenschmiede jern"}},{q="Vor welchen Problemen stehen die Ausgrabungsstätten in Loch Modan?",a="Das plötzliche Auftauchen aggressiver Troggs, die aus dem Erdinneren vertrieben wurden, hat die Ausgrabungsarbeiten schwer gefährdet und Handelswege blockiert, was regelmäßige Lieferungen ohne bewaffnete Abenteurer zum Schutz der Vorräte gefährlich macht.",al={"ironbands ausgrabungsstätte probleme","loch modan grabungsgefahren","warum jern hilfe braucht"}}},fx={["1cf890d8"]={q="Warum ist Jern Hornhelm in Thelsamar?",a="Jern Hornhelm ist in Thelsamar stationiert, um die Logistik für lokale archäologische Ausgrabungen in ganz Loch Modan zu verwalten. Er arbeitet zur Unterstützung der Forscherliga und koordiniert kritische Vorräte, Berichte und Sprengstoffe zwischen Eisenschmiede und abgelegenen Grabungsstätten wie Ironband's Excavation, um sicherzustellen, dass die Operationen der Liga finanziert und ausgerüstet bleiben.",al={"warum ist jern hornhelm hier","zweck von jern hornhelm in loch modan","warum ist jern in thelsamar"}}},fp="13,350,22.390.0,29.391.0,21.187.0,31.113.0,42.148.0,58.279.0,48.234.0,53.223.0"}
P.entries["npc:jitters"] = {n="Bibbers",s="Bibbers ist ein zitternder, zurückgezogen lebender Mensch, der sich in den Ruinen von Rabenflucht im westlichen Dämmerwald versteckt hält. Verzehrt von ständiger Paranoia und Angst überlebt er allein am gefährlichen westlichen Rand des Dämmerwaldes. Dabei ist er auf die Hilfe vorbeikommender Abenteurer angewiesen, während er die näher rückenden Schatten beobachtet.",h="Bibbers ist ein zitternder, zurückgezogen lebender Mensch, der sich in den Ruinen von Rabenflucht im...",kw={"amtmann daltry","dark riders","dämmerwald","jitters","rabenflucht","rolands verdammnis","die sense von elune","sven yorgen","worgen"},ang={["class:Rogue"]="Bibbers besitzt schnelle Instinkte, um Gefahren zu vermeiden, aber sie haben ihn nicht vor dem Terror und der Isolation im Dämmerwald bewahrt.",["faction:Alliance"]="Bibbers steht für das menschliche Gesicht der Tragödie im Dämmerwald; er lebt in Angst, während die Nachtwache darum kämpft, die Bewohner zu schützen."},sec={{t="Ein heimgesuchter Einsiedler",b="Bibbers zittert inmitten der baufälligen Häuser von Rabenflucht und lebt in ständiger Angst vor den Raubtieren, die die westlichen Pfade des Dämmerwaldes durchstreifen. Er ist auf vorbeikommende Abenteurer angewiesen, die ihm einfache Nahrung geben, da er verzweifelt Hunger leidet, während er die näher rückenden Schatten ängstlich im Auge behält. Seine nervösen Manierismen und sein unheimlicher Reflex, plötzlicher Gefahr auszuweichen, brachten ihm vor langer Zeit seinen Spitznamen ein, doch seine hektische Paranoia ist das Ergebnis seiner Begegnungen mit schrecklichen Monstern."},{t="Das Erwachen bei Rolands Verdammnis",b="Bibbers gehörte ursprünglich zur Bruderschaft der Defias, als diese in den Dämmerwald vordrang. Während er in der Mine namens Rolands Verdammnis grub, entdeckte er Die Sense von Elune, die aus dem Gestein ragte. Das Artefakt entfesselte wilde, blutrünstige Worgen im Wald. Bibbers sah voller Entsetzen zu, wie seine Kameraden zerfetzt wurden, und entkam dem Massaker nur mit knapper Not."},{t="Flucht und der Bauernhof",b="Auf der Flucht aus der Mine zog sich Bibbers nach Dunkelhain zurück, kaufte ein leeres Buch bei Amtmann Daltry und hielt den Albtraum fieberhaft fest, während er sich in der Scarlet Raven Tavern versteckte. In Panik suchte er Zuflucht in einer Scheune auf Yorgens Bauernhof. Dort musste er mitansehen, wie schwarz gewandete Dark Riders Sven Yorgens Familie auf der Suche nach der Sense abschlachteten. Aus Angst, beschuldigt oder gefunden zu werden, vergrub Bibbers die Seiten seines Tagebuchs in der Erde und floh nach Rabenflucht, verfolgt von lähmenden Schuldgefühlen und unaufhörlicher Furcht."}},faq={{q="Wer ist Bibbers?",a="Bibbers ist ein verängstigter Mensch, der in den Ruinen von Rabenflucht lebt. Er ist hungrig, isoliert und wird von seinen Erlebnissen im Dämmerwald heimgesucht.",al={"wer ist dieser typ","jitters hintergrundgeschichte","jitters hintergrund"}},{q="Warum wird er Bibbers genannt?",a="Sein Spitzname stammt von seinem vorsichtigen Wesen, insbesondere von seiner instinktiven Angewohnheit, vor Schlägen zurückzuzucken und plötzlichen Gefahren auszuweichen. Seine lange Isolation und die schiere Angst im Dämmerwald haben seine Nervosität nur noch verschlimmert.",al={"warum jitters","woher kommt sein name","jitters namensherkunft"}},{q="Welche Gefahr stellen die Worgen im Dämmerwald dar?",a="Worgen durchstreifen die Wälder und Straßen des Dämmerwaldes und bedrohen Reisende sowie isolierte Siedlungen.",al={"worgenbedrohung dämmerwald","bestien bei jitters","worgengefahr dämmerwald"}},{q="Was ist mit Sven Yorgens Familie passiert?",a="Sven Yorgens Familie wurde auf ihrem Bauernhof ermordet, was ihn dazu veranlasste, herauszufinden, wer dafür verantwortlich war.",al={"sven bauernhof massaker","wer tötete svens familie","yorgens bauernhof morde"}},{q="Wie kann Bibbers Sven Yorgens Untersuchung helfen?",a="Bibbers' Tagebuch hält seine Erlebnisse im Dämmerwald fest und könnte Sven dabei helfen, zu untersuchen, was seiner Familie zugestoßen ist.",al={"jitters und svens untersuchung","wie kann jitters sven helfen","jitters bericht über dämmerwald"}},{q="Was ist Bibbers' Tagebuch?",a="Sein Tagebuch zeichnet seine Erlebnisse im Dämmerwald auf und ist Teil der Untersuchungen rund um Rabenflucht und Sven Yorgens Familie.",al={"jitters tagebuch","jitters vollständiges tagebuch","daltry buch"}}},fx={["9934be9b"]={q="Auf wessen Seite steht Bibbers?",a="Bibbers ist ein verängstigter, hungriger Überlebender, der sich in Raven Hill versteckt und dessen beunruhigende Erfahrungen ihn isoliert und tief erschüttert haben.",al={"fraktion von bibbers","ist bibbers böse","für wen arbeitet bibbers","loyalität von bibbers"}},["3395ed32"]={q="Was möchte Bibbers?",a="Bibbers möchte Essen und Sicherheit. Sein Hunger bringt ihn in Kontakt mit Abenteurern, die die Probleme um Raven Hill untersuchen.",al={"was braucht bibbers","motiv von bibbers","warum schickt bibbers einen"}},af0d9be3={q="Warum ist Bibbers hier in Raven Hill?",a="Raven Hill bietet Bibbers ein Versteck zwischen den verlassenen Gebäuden des Dämmerwalds, obwohl es ihm wenig Trost oder Schutz bietet.",al={"warum ist bibbers in raven hill","wie kam bibbers hierher","warum versteckt sich bibbers hier"}},b49992e9={q="Mit wem ist Bibbers verbunden?",a="Seine Geschichte überschneidet sich mit Sven Yorgens Ermittlungen und den Berichten, die in seinem Tagebuch bewahrt werden.",al={"verbindungen von bibbers","mit wem ist bibbers verbunden","bibbers defias"}}},fp="7,282,16.468.0,30.388.1,24.493.1,15.132.1,25.244.0,43.88.1,38.108.1,49.111.1,25.132.1"}
P.entries["npc:jocaste"] = {n="Jocaste",s="Jocaste ist eine Nachtelfen-Jägerlehrerin, die in der grünen Enklave des Cenarius in Darnassus weilt. An der Seite des Zirkels des Cenarius unterweist sie junge Scharfschützen und Bestienmeister der Nachtelfen, die aus der Wildnis von Teldrassil eintreffen.",h="Jocaste ist eine Nachtelfen-Jägerlehrerin, die in der grünen Enklave des Cenarius in Darnassus weilt.",kw={"die enklave des cenarius","darnassus","jägerlehrer","jocaste","nachtelfenjäger","teldrassil"},ang={["class:Hunter"]="Für Jäger der Nachtelfen, die zum ersten Mal Darnassus betreten, ist Jocaste eine wichtige Lehrerin, die Eure Kampftechniken verfeinert und dabei hilft, das Band zu Euren tierischen Begleitern zu festigen.",["race:NightElf"]="Verwurzelt in der Enklave des Cenarius spiegelt Jocaste den tiefen Einklang zwischen den Wanderern der Nachtelfen, den wilden Tieren von Teldrassil und den Lehren des Zirkels des Cenarius wider."},sec={{t="Eine Mentorin in der Enklave",b="Inmitten der friedvollen Haine der Enklave des Cenarius in Darnassus dient Jocaste als Ausbilderin für Jäger der Nachtelfen. Wenn angehende Fährtenleser ihre erste Ausbildung in Laubschattental abschließen und in die Hauptstadt aufbrechen, leitet Jocaste ihren Wandel zu erfahrenen Überlebenskünstlern an. Sie lehrt die Kunst der Treffsicherheit, das Überleben in der Wildnis sowie die heilige Verbindung zwischen einem Jäger und den wilden Tieren von Kalimdor."}},faq={{q="Wer ist Jocaste?",a="Jocaste ist eine Jägerlehrerin der Nachtelfen in der Enklave des Cenarius in der Hauptstadt Darnassus, die Ausübenden der Jagd Unterricht und Führung bietet.",al={"jocaste lore","wer ist jocaste","jocaste darnassus"}},{q="Wo kann ich Jocaste finden?",a="Sie ist zwischen den Bäumen und Pavillons der Enklave des Cenarius im nordwestlichen Bezirk von Darnassus auf den Ästen von Teldrassil zu finden.",al={"jocaste aufenthaltsort","wo ist jocaste","jocaste standort"}},{q="Welche Rolle spielt sie für junge Jäger?",a="Jäger, die nach Darnassus geschickt werden, suchen sie auf, um ihre Disziplin durch Aufgaben wie „Der Weg des Jägers“ voranzubringen und zu lernen, wie man wilde Bestien richtig zähmt und meistert.",al={"jocaste quests","der weg des jägers jocaste","die ausbildung des tiers"}},{q="Gehört Jocaste zum Zirkel des Cenarius?",a="Ja. Obwohl sie Jäger und keine Druiden ausbildet, wirkt sie in der Enklave des Cenarius und heißt reisende Jäger ausdrücklich in der Gegenwart des Zirkels des Cenarius willkommen.",al={"gehört jocaste zum zirkel des cenarius","jocaste fraktion"}}},fx={["42c501de"]={q="Auf wessen Seite steht Jocaste?",a="Jocaste steht fest an der Seite von Darnassus, der Nachtelfen und der Allianz im Allgemeinen. Stationiert bei dem Zirkel des Cenarius in ihrer Enklave, teilt sie deren Hingabe, die Natur zu schützen und diejenigen zu leiten, die im Einklang mit der Wildnis leben.",al={"fraktion von jocaste","wem dient jocaste","loyalität von jocaste"}},["05567dfb"]={q="Was will Jocaste?",a="Jocaste widmet sich der Weitergabe der Traditionen der Jagd. Sie möchte angehende Jäger in Darnassus fördern und sicherstellen, dass sie die Disziplin, das Treffsicherheitsvermögen und die spirituelle Bindung erlernen, die erforderlich sind, um Bestien im Dienste der Natur und ihres Volkes zu zähmen und zu befehligen.",al={"motiv von jocaste","was ist das ziel von jocaste","zweck von jocaste"}},["1febd3fe"]={q="Warum ist Jocaste hier in Darnassus?",a="Jocaste residiert in der Enklave des Cenarius, um Jägern, die die Hauptstadt besuchen, ihre Weisheit und Ausbildung anzubieten. Inmitten der uralten Bäume von Teldrassil bietet sie sowohl angehenden Kundschaftern als auch erfahrenen Wildnispirschern wichtige Unterweisungen.",al={"warum ist jocaste in darnassus","warum ist jocaste in der enklave des cenarius"}}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:john-j-keeshan"] = {n="John J. Keeshan",s="Korporal John J. Keeshan ist ein menschlicher Soldat der Armee von Sturmwind, der im Rotkammgebirge gegen die Orcs des Schwarzfelsens kämpfte. Nachdem er während der Kämpfe um Steinwacht gefangen genommen wurde, wurde er als Kriegsgefangener tief in Renders Fels verschleppt.",h="Korporal John J.",kw={"john j keeshan","keeshan","missing in action","renders fels","steinwacht"},ang={["class:Warrior"]="Für Krieger ist Keeshan ein düsteres Zeugnis der Gefahren an der Front des Rotkammgebirges, wo selbst abgehärtete Soldaten vom Schwarzfelsclan überwältigt und verschleppt werden können.",["faction:Alliance"]="Keeshan repräsentiert den hohen menschlichen Preis des Krieges der Allianz gegen die Orcs des Schwarzfelsens im Rotkammgebirge: ein Soldat, der gefangen genommen wurde, während er für Sturmwind die Stellung hielt."},sec={{t="Ein Soldat des Rotkammgebirges",b="John J. Keeshan ist ein Korporal im Dienste Sturmwinds, der im Rotkammgebirge stationiert war, als die Orcs des Schwarzfelsens auf Seenhain und dessen Verteidiger vorrückten. Als die Kämpfe um Burg Steinwacht aufflammten, war Keeshan inmitten des Geschehens und hielt zusammen mit den anderen Soldaten die Stellung für das Königreich."},{t="Gefangenschaft in Renders Fels",b="Als der Schwarzfelsclan aus der Brennenden Steppe nach Norden in das Rotkammgebirge vordrang, stand Keeshan unter den Verteidigern, die um Burg Steinwacht kämpften. Von dem Angriff der Orcs überwältigt, wurde er lebend gefangen genommen, anstatt auf dem Schlachtfeld getötet zu werden. Die Invasoren des Schwarzfelsens verschleppten ihn als Gefangenen in die Tiefen von Renders Fels, wo der Veteran hinter feindlichen Linien eingesperrt blieb, bis Rettungstrupps der Allianz sich einen Weg bahnen konnten, um ihn zu befreien."}},faq={{q="Wer ist John J. Keeshan?",a="John J. Keeshan ist ein Korporal der Armee von Sturmwind, der im Rotkammgebirge gegen die Orcs des Schwarzfelsens kämpfte. Während der Schlacht um Burg Steinwacht wurde er gefangen genommen und nach Renders Fels verschleppt.",al={"keeshan lore","wer ist keeshan","corporal keeshan"}},{q="Warum ist Keeshan in Renders Fels gefangen?",a="Während der Schlacht gegen den Schwarzfelsclan um Burg Steinwacht wurde Keeshan überwältigt, von den Orcs lebend gefangen genommen und zurück zu ihrem Lager in den Höhlen von Renders Fels geschleppt.",al={"warum ist keeshan gefangen","gefangener in renders fels","wie wurde keeshan gefangen genommen"}}},fp="15,241,21.304.0,26.444.1,23.198.0,43.192.0"}
P.entries["npc:jonathan-carevin"] = {n="Jonathan Treuwein",s="Jonathan Treuwein ist ein entschlossener menschlicher Jäger, der in Dunkelhain lebt und sich der Auslöschung der Dunkelheit verschrieben hat, die den Dämmerwald heimsucht. Im Gegensatz zur defensiven Nachtwache jagen er und seine Familie aktiv die Untoten, Worgen und jegliche ketzerischen Bedrohungen, die unter dem finsteren Blätterdach lauern.",h="Jonathan Treuwein ist ein entschlossener menschlicher Jäger, der in Dunkelhain lebt und sich der Auslöschung...",kw={"calor","familie carevin","dunkelhain","dämmerwald","jonathan treuwein","die nachtwache","untote","worgen"},ang={["class:Hunter"]="Jäger finden Gemeinsamkeiten mit Carevins proaktivem Aufspüren und methodischem Ausdünnen der nächtlichen Raubtiere des Dämmerwalds.",["class:Paladin"]="Carevins Eifer und die Anrufung des Lichts gegen dämonische und untote Verderbnis stehen in tiefem Einklang mit den heiligen Gelübden eines Paladins.",["faction:Alliance"]="Für Champions der Allianz, die versuchen, den Dämmerwald zu stabilisieren, führt Jonathan Treuwein gezielte Schläge gegen die übernatürlichen Bedrohungen, die durch die Vernachlässigung seitens Sturmwinds unkontrolliert blieben."},sec={{t="Der Kreuzzug der Carevins",b="Während Dunkelhain sich auf die Nachtwache verlässt, um die Straßen zu bewachen und die Ortschaft zu schützen, glaubt Jonathan Treuwein, dass eine bloße Verteidigungslinie unzureichend ist. Zusammen mit seiner Familie und Verbündeten wie Calor geht Jonathan in die Offensive. Er nimmt gezielt die unheiligen Unholde ins Visier, die den Dämmerwald durchstreifen, und führt einen persönlichen Kreuzzug, um alle Dämonen, Untoten und Ketzer im Lichte der Gnade aus der Region zu tilgen."},{t="Der Schatten der Worgen",b="Jonathans Wachsamkeit beschränkt sich nicht nur auf schlurfende Skelette und Ghule. Er achtet auch genau auf die wilden, wolfsähnlichen Bestien, die als Worgen bekannt sind und die Tiefen des Waldes durchstreifen. Da er weiß, welche Gefahr sie für eine ohnehin belagerte Siedlung darstellen, koordiniert Jonathan Untersuchungen über ihre mysteriöse Anwesenheit, um herauszufinden, woher diese gottlosen Raubtiere stammen, und ihrem nächtlichen Treiben ein Ende zu setzen."}},faq={{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein ist ein grimmiger Jäger, der in Dunkelhain im Dämmerwald lebt. Er führt die Familie Carevin in einem aktiven Kampf gegen die abscheulichen Monster an, die den Wald heimsuchen.",al={"wer ist carevin","jonathan treuwein lore","carevin dunkelhain"}},{q="Wie unterscheidet er sich von der Nachtwache?",a="Während sich die Nachtwache in erster Linie darauf konzentriert, die Grenzen von Dunkelhain zu bewachen und die Straßen passierbar zu halten, spüren Jonathan und seine Anhänger die Untoten und andere Abscheulichkeiten aktiv auf und jagen sie, um sie an ihrem Ursprung auszumerzen.",al={"ist er bei der nachtwache","carevin vs nachtwache"}},{q="Welche Bedrohungen bekämpft er?",a="Jonathan jagt aktiv die Untoten, unersättliche Worgenrudel, Dämonen und jeden, der solchen unheiligen Abscheulichkeiten Unterschlupf oder Hilfe gewährt.",al={"was jagt carevin","carevin ziele"}},{q="Gehört Jonathan zum Scharlachroten Kreuzzug?",a="Seine harte Rhetorik, seine inbrünstige Hingabe an das Licht und sein strikter Null-Toleranz-Ansatz gegenüber Verderbnis spiegeln die Überzeugungen der Scharlachroten wider, doch offiziell operiert er unabhängig an der Seite seiner Familie in Dunkelhain.",al={"carevin scharlachroter kreuzzug","ist carevin scharlachrot"}},{q="Wer unterstützt Jonathan bei seiner Mission?",a="Neben seiner engsten Familie erhält Jonathan direkte Unterstützung von sympathisierenden Kämpfern wie Calor, der ihm hilft, monströse Übergriffe im gesamten Wald nachzuverfolgen.",al={"carevin verbündete","wer hilft carevin"}},{q="Was ist seine Verbindung zu den Worgen?",a="Jonathan betrachtet die Worgen als eine unnatürliche Bedrohung, die die Bevölkerung des Dämmerwalds terrorisiert, und beauftragt Reisende damit, die Ursache für ihr plötzliches Auftauchen in der Wildnis aufzudecken.",al={"carevin worgen","warum hasst carevin worgen"}}},fx={["8aa9d9d7"]={q="Was will Jonathan Treuwein?",a="Jonathan Treuwein strebt nichts Geringeres an als die vollständige Ausrottung des Bösen, der Häresie und der Untoten, die den Dämmerwald plagen. Im Gegensatz zur örtlichen Nachtwache, die sich darauf konzentriert, Dunkelhain hinter Verteidigungslinien sicher zu halten, glaubt Jonathan daran, in die Offensive zu gehen. Er möchte aktiv dämonische und untote Streitkräfte jagen und die Region unter der rechtschaffenen Macht des Lichts von Verderbnis reinigen.",al={"ziele von jonathan treuwein","was ist das ziel von treuwein","mission von treuwein"}},["24497d50"]={q="Warum ist Jonathan Treuwein in Dunkelhain?",a="Dunkelhain ist die Frontlinie eines schattendurchfluteten Landes, das von Ghulen, Skeleten und dunkleren Schrecken überrannt wird. Jonathan Treuwein und seine Familie haben es sich zur persönlichen Aufgabe gemacht, hier standzuhalten, Angriffe gegen die Untoten zu koordinieren und jeden fähigen Abenteurer zu versammeln, der bereit ist, gegen die Schrecken, die unter den verdunkelten Ästen des Dämmerwaldes lauern, zu den Waffen zu greifen.",al={"warum ist treuwein in dunkelhain","warum ist jonathan treuwein hier","grund für treuweins präsenz im dämmerwald"}}},fp="16,277,19.410.0,24.412.1,24.160.0,40.231.0,27.137.0,48.203.0,36.171.0,37.170.0"}
P.entries["npc:jorah-annison"] = {n="Jorah Annison",s="Jorah Annison ist ein Kartograf der Verlassenen, der im Magieviertel von Unterstadt stationiert ist. Obwohl sich sein Beruf um Karten und Geografie dreht, erweist sich sein Fachwissen für reisende Zauberwirker auf der Suche nach verborgenem, verstreutem Wissen in ganz Azeroth als unschätzbar wertvoll.",h="Jorah Annison ist ein Kartograf der Verlassenen, der im Magieviertel von Unterstadt stationiert ist.",kw={"annison","kartograf","jorah","magieviertel","karten","foliant der kabale","unterstadt","hexenmeister"},ang={["class:Warlock"]="Jorah ist ein wesentlicher Kontakt für Hexenmeister der Horde, die den Folianten der Kabale zusammenstellen, und liefert wichtige Koordinaten zur Bergung verlorener Seiten in der ganzen Welt.",["faction:Horde"]="Durch seine Fachkenntnisse im Kartenzeichnen hilft Jorah Abenteurern der Horde dabei, sich auf unbekannten Kontinenten zurechtzufinden und wertvolle Relikte zu bergen.",["race:Undead"]="Als Bürger von Unterstadt zeigt Jorah, wie intellektuelle Bestrebungen der Verlassenen wie die Kartografie dem allgemeinen Überleben seines Volkes dienen."},sec={{t="Ein Gelehrter verdunkelter Lande",b="Inmitten der alchemistischen Dämpfe und arkanen Echos im Magieviertel von Unterstadt geht Jorah Annison dem Handwerk der Kartografie nach. Während viele Gelehrte der Verlassenen ihr Unleben rein der Seuche oder zerstörerischen Magien widmen, konzentriert sich Jorah auf die präzise Kartierung von Gelände, Grenzen und vergessenen Stätten auf den Kontinenten und liefert der Horde lebenswichtige logistische Einblicke."},{t="Die Spur der Kabale",b="Jorahs Wissen über das Land reicht weit über die Ruinen von Lordaeron hinaus. Hexenmeister, die den schwer fassbaren Folianten der Kabale suchen, werden häufig an ihn verwiesen, um herauszufinden, wo alte Texte und Überreste dunkler Sekten geborgen werden können, was die Kluft zwischen historischem Wissen und entfernter Geografie überbrückt."}},faq={{q="Wer ist Jorah Annison?",a="Jorah Annison ist ein untoter Kartograf, der im Magieviertel von Unterstadt weilt und Horde-Reisenden mit geografischem Wissen und historischen Schauplätzen behilflich ist.",al={"jorah annison wer","wer ist jorah","unterstadt kartograf"}},{q="Wo finde ich Jorah Annison?",a="Er befindet sich im Magieviertel von Unterstadt, der unterirdischen Hauptstadt der Verlassenen unter den Ruinen von Lordaeron.",al={"jorah annison aufenthaltsort","wo ist jorah annison","jorah finden"}},{q="Warum müssen Hexenmeister mit ihm sprechen?",a="Hexenmeister, die dem uralten Folianten der Kabale nachgehen, ziehen Jorah wegen seiner kartografischen Meisterschaft zu Rate, da er sie zu den weit entfernten Orten führen kann, an denen verstreute Fragmente des Textes geborgen werden können.",al={"jorah hexenmeisterquest","foliant der kabale jorah","warum mit jorah sprechen"}},{q="Welcher Fraktion gehört Jorah Annison an?",a="Er ist ein Mitglied der Verlassenen und loyal gegenüber der Horde; er dient seinen Brüdern und Schwestern aus ihrer Hauptstadt heraus.",al={"ist jorah horde","jorah annison fraktion"}},{q="Verkauft Jorah Annison Spielern direkt Karten?",a="Jorah fungiert in erster Linie als Berater und Questkontakt bezüglich vergessener Orientierungspunkte und nicht als aktiver Händler von Waren.",al={"verkauft jorah karten","jorah händler"}},{q="Findet man Jorah Annison jemals außerhalb von Unterstadt?",a="Obwohl seine Kartenherstellung und seine Führung bei Quests ferne Orte wie das Brachland betreffen, bleibt Jorah selbst im Magieviertel von Unterstadt stationiert.",al={"jorah im brachland","jorah außerhalb von unterstadt"}}},fp="13,263,27.382.0,17.292.0,21.169.0,31.134.0,39.201.0,42.107.0,49.123.0,50.157.0"}
P.entries["npc:jordan-stilwell"] = {n="Jordan Stillbrunn",s="Jordan Stillbrunn ist ein geschickter menschlicher Waffenschmied, der vor den verschneiten Toren von Eisenschmiede in Dun Morogh stationiert ist. Obwohl er ursprünglich dazu bestimmt war, ein Paladin des Heiligen Lichts zu werden, folgte er dem Handwerk seines Vaters und wurde zu einem Kunstschmied, dessen Werk Paladinen der gesamten Allianz dient. Am bekanntesten ist er für das Schmieden von Verigans Faust zu Ehren seines alten Freundes Bosch Verigan.",h="Jordan Stillbrunn ist ein geschickter menschlicher Waffenschmied, der vor den verschneiten Toren von...",kw={"bailor steinhand","bosch verigan","daphne stillbrunn","dun morogh","eisenschmiede","jordan stillbrunn","burg shadowfang","foliant der ehre","verigans faust"},ang={["class:Paladin"]="Jordan Stillbrunn ist eine zentrale Gestalt in den frühen Prüfungen eines Paladins, den er damit beauftragt, ganz Azeroth nach seltenen Bestandteilen abzusuchen, um dessen charakteristischen Kriegshammer, Verigans Faust, zu schmieden.",["faction:Alliance"]="Nachdem er den Schrecken von Arugals Worgen im Silberwald entkommen war, fand Jordan Zuflucht bei den Zwergen von Dun Morogh und stellt sein Handwerk nun direkt in den Dienst der Streiter der Allianz.",["profession:Blacksmithing"]="Ausgebildet von dem Zwerg Bailor Steinhand und ausgerüstet mit einem verzauberten Hammer, den er von seinem Vater erbte, verkörpert Jordan den Gipfel der sterblichen heiligen Schmiedekunst."},sec={{t="Eine Berufung am Amboss",b="Obwohl von Jordan Stillbrunn erwartet wurde, die heiligen Gelübde abzulegen und ein Paladin der Kirche des Heiligen Lichts zu werden, wählte er letztlich den Weg der Schmiede. Er trat in die Fußstapfen seines Vaters und ergriff dessen verzauberten Schmiedehammer. Jordan verfeinerte sein Handwerk unter der Anleitung des Zwergenschmieds Bailor Steinhand. Obwohl er das Gewand eines gesalbten heiligen Kriegers ablegte, bleibt Jordan dem Licht tief verbunden und widmet seine außergewöhnliche Handwerkskunst der Ausrüstung von Streitern, die in seinem Namen kämpfen."},{t="Die Flucht aus dem Silberwald",b="Lange bevor er seine Werkstatt in der schneidenden Kälte von Dun Morogh einrichtete, diente Jordan als Schmied auf der Feste von Baron Silberlein im Silberwald. Als Erzmagier Arugal die wilden Worgen auf die Festung losließ und sie in die verfluchte Bastion namens Burg Shadowfang verwandelte, gelang Jordan die Flucht vor dem Blutvergießen. Gezwungen, seine Schmiede und seine frühere Heimat aufzugeben, fand er schließlich Zuflucht bei den Zwergen von Dun Morogh."},{t="Das Schmieden von Verigans Faust",b="Jordan betreibt seine Schmiede im Freien nahe den Toren von Eisenschmiede und zieht die frische Alpenluft der erstickenden Hitze der Großen Schmiede im Inneren des Berges vor. Wenn die Kirche des Heiligen Lichts würdige Paladine zu ihm entsendet, beauftragt Jordan sie damit, seltene Materialien aus der ganzen Welt zu beschaffen, um einen legendären zweihändigen Kriegshammer zu fertigen. Benannt als Verigans Faust zu Ehren seines alten Freundes Bosch Verigan, steht die Waffe als Zeugnis für das unvergängliche Band zwischen tiefem Glauben und meisterhaftem Stahl."}},faq={{q="Wer ist Jordan Stillbrunn?",a="Jordan Stillbrunn ist ein menschlicher Meisterschmied, der vor den Toren von Eisenschmiede in Dun Morogh arbeitet. Er fertigt heilige Rüstungen und Waffen für Paladine der Kirche des Heiligen Lichts an, vor allem den legendären Kriegshammer Verigans Faust.",al={"wer ist jordan stillbrunn","jordan stillbrunn geschichte","wer ist der schmied vor eisenschmiede"}},{q="Warum arbeitet Jordan Stillbrunn draußen im Schnee statt im Inneren von Eisenschmiede?",a="Laut Duthorian Rall in Sturmwind zieht Jordan die kühle, klare Bergluft von Dun Morogh dem stickigen Inneren der Großen Schmiede in Eisenschmiede vor.",al={"warum ist jordan vor eisenschmiede","warum arbeit in dun morogh","warum steht er im schnee"}},{q="Welche Verbindung hat Jordan Stillbrunn zu Burg Shadowfang?",a="Jordan war einst Rüstungsschmied und Grobschmied auf dem Anwesen von Baron Silberlein im Silberwald. Es gelang ihm, vor oder während des verheerenden Aufstands aus der Burg zu fliehen, als Erzmagier Arugal und seine wilden Worgen die Besatzung niedermachten und die Festung einnahmen.",al={"jordan stillbrunn burg shadowfang","jordan stillbrunn silberwald","lebte er in pyrewood"}},{q="Was ist Verigans Faust?",a="Verigans Faust ist ein mächtiger zweihändiger heiliger Hammer, der von Jordan Stillbrunn für Allianz-Paladine geschmiedet wird. Er ist zu Ehren von Jordans altem Freund Bosch Verigan benannt.",al={"verigans faust","verigan hammer","wer ist verigan"}},{q="Wer bildete Jordan Stillbrunn im Schmieden aus?",a="Jordan erbte sein Handwerk und einen verzauberten Schmiedehammer von seinem Vater und verfeinerte seine Fertigkeiten anschließend unter der Unterweisung des Zwergenschmieds Bailor Steinhand.",al={"wer bildete jordan stillbrunn aus","jordan stillbrunn lehrer","wo lernte er schmieden"}},{q="Wer ist die Frau von Jordan Stillbrunn?",a="Jordan ist mit Daphne Stillbrunn verheiratet. Gemeinsam hat das Paar der Kirche des Heiligen Lichts über die Jahre hinweg immens beigestanden, und beide werden als zutiefst fromme Diener des Glaubens verehrt.",al={"jordan stillbrunn ehefrau","daphne stillbrunn ehemann","daphne stillbrunn"}}},fx={["49deb919"]={q="Auf wessen Seite steht Jordan Stillbrunn?",a="Jordan ist der Allianz und der Kirche des Heiligen Lichts treu ergeben. Obwohl er unter den Zwergen in Dun Morogh lebt und sein Handwerk außerhalb von Eisenschmiede ausübt, bleibt er eng mit den Paladinen von Sturmwind verbunden und widmet sein Handwerk der Bewaffnung der Gläubigen gegen die Dunkelheit, die das Reich bedroht.",al={"fraktion von jordan stillbrunn","ist jordan stillbrunn allianz","loyalität von jordan stillbrunn"}},["4c63667e"]={q="Was will Jordan Stillbrunn?",a="Jordan möchte seinen alten Freund Bosch Verigan ehren, indem er eine außergewöhnliche Waffe für würdige Paladine schmiedet. Um den heiligen Kriegshammer Verigans Faust herzustellen, benötigt er seltene Materialien, die in ganz Azeroth gesammelt werden müssen: veredeltes Erz, verzaubertes Holz und einen mit Reinheit durchdrungenen Edelstein.",al={"was benötigt jordan stillbrunn","ziel von jordan stillbrunn","zweck von jordan stillbrunn"}},["35033531"]={q="Warum ist Jordan Stillbrunn berühmt?",a="Jordan ist als außergewöhnlicher Waffenschmied bekannt, dessen Hingabe an das Heilige Licht seiner Fertigkeit an der Esse ebenbürtig ist. Ursprünglich für das Priestertum oder den Paladinstand vorgesehen, entschied er sich, in die Fußstapfen seines Vaters zu treten, und erwarb sich immensen Respekt bei den Rittern der Silbernen Hand für seine Fähigkeit, meisterhafte heilige Bewaffnung herzustellen.",al={"ist jordan stillbrunn berühmt","bekanntheit von jordan stillbrunn","warum ist jordan stillbrunn bekannt"}}},fp="15,358,22.527.0,22.418.0,22.491.1,23.230.0,78.181.0,56.266.0,23.160.0,45.178.0,30.192.0"}
P.entries["npc:jorgen"] = {n="Jorgen",s="Jorgen ist ein diskreter menschlicher Informant, der in Sturmwind ansässig ist, verborgen am Wasser direkt im Tal der Helden. Trotz seines bescheidenen und abgelegenen Postens ist er in heikle Angelegenheiten verwickelt, an denen prominente Persönlichkeiten der Hauptstadt beteiligt sind, darunter Elling Trias und Bischof DeLavey.",h="Jorgen ist ein diskreter menschlicher Informant, der in Sturmwind ansässig ist, verborgen am Wasser direkt im...",kw={"bischof delavey","elling trias","informant","jorgen","der vermisste diplomat","sturmwind","das tal der helden"},ang={["class:Rogue"]="Jorgen verkörpert das Straßennetzwerk aus Gerüchten, das unter dem makellosen Marmor von Sturmwind floriert und eng mit den heimlichen Machenschaften rund um Trias' Cheese verknüpft ist.",["faction:Alliance"]="Wenn offizielle Kanäle in Sturmwind auf bürokratische Mauern stoßen, sind verlässliche Informanten auf der Straße wie Jorgen unverzichtbar, um Bedrohungen für das Königreich aufzuspüren."},sec={{t="Augen am Wasser",b="Unten am Wasser unmittelbar rechts des monumentalen Eingangs von Sturmwind positioniert, hält Jorgen sich abseits der belebten Durchgangsstraßen der Stadt bedeckt. Während die überragenden Heldenstatuen die Brücke über ihm überblicken, beobachtet Jorgen das Kommen und Gehen aus den Schatten darunter und dient als stiller Kontakt für jene, die inoffizielle Informationen benötigen."},{t="Eine verstrickte Vergangenheit",b="Jorgens diskrete Anwesenheit ist kein Zufall. Er teilt eine unruhige Vergangenheit mit dem Meister-Käsehändler und Informationsbeschaffer Elling Trias sowie mit Bischof DeLavey von der Kathedrale des Lichts. Wenn heikle Ermittlungen anstehen – wie etwa die Aufklärung des Verschwindens eines nach Theramore entsandten Diplomaten –, ist Jorgen einer der wenigen lokalen Kontakte, die Ermittler in die richtige Richtung weisen können, sofern man weiß, wie man an ihn herantritt."}},faq={{q="Wo kann ich Jorgen finden?",a="Jorgen befindet sich in Sturmwind im Tal der Helden. Sobald Ihr die Stadttore aus dem Wald von Elwynn durchquert, geht rechts der Hauptbrücke hinab zum Wasser.",al={"jorgen aufenthaltsort","wo ist jorgen","jorgen finden"}},{q="Mit wem steht Jorgen in Sturmwind in Verbindung?",a="Jorgen blickt auf eine bewegte Geschichte mit Elling Trias zurück, dem prominenten Käsehändler im Handelsdistrikt mit verdeckten Verbindungen, sowie mit Bischof DeLavey von der Kathedrale des Lichts.",al={"jorgen verbindungen","jorgen kontakte","wen kennt jorgen"}},{q="Welche Rolle spielt Jorgen bei den Ermittlungen um den vermissten Diplomaten?",a="Während der Suche nach dem vermissten Gesandten dient Jorgen als wichtiger Informant. Suchende werden an ihn verwiesen, um herauszufinden, wer heimliche Treffen und verdeckte Operationen im Königreich ermöglicht haben könnte.",al={"jorgen der vermisste diplomat","jorgen quest"}},{q="Gehört Jorgen zur Stadtwache von Sturmwind?",a="Nein. Jorgen agiert unabhängig und lauert abseits der offiziellen Patrouillen der Wache unten an den Kanalufern, wo diskrete Gespräche außer Hörweite stattfinden können.",al={"ist jorgen eine wache","jorgen fraktion"}}},fx={["536f8488"]={q="Wer ist Jorgen?",a="Jorgen ist eine zwielichtige Gestalt, die sich ruhig unten am Wasser im Tal der Helden aufhält, gleich hinter den großen Vordertoren von Sturmwind. Anstatt in irgendeiner offiziellen zivilen Funktion zu dienen, agiert er am Rande der Angelegenheiten der Hauptstadt und besitzt tiefe Verbindungen und eine nicht enthüllte Vergangenheit, die eng mit Meister Elling Trias und Bischof DeLavey verknüpft ist.",al={"wer ist jorgen","jorgen in sturmwind","identität von jorgen"}},["846a3fb1"]={q="Warum ist Jorgen hier?",a="Jorgen hält sich am Rande des Tals der Helden auf, um als diskreter Kontaktpunkt innerhalb von Sturmwind zu fungieren. Direkt in der Nähe der Stadttore und fernab von neugierigen Blicken positioniert, bleibt er verfügbar, um vertrauenswürdigen Kontakten wie Elling Trias zu helfen, wann immer heikle, verdeckte Nachforschungen diskret gehandhabt werden müssen.",al={"warum ist jorgen hier","grund für jorgens standort","warum ist jorgen in sturmwind"}}},fp="6,292,17.374.0,17.434.1,24.180.0,40.174.0,72.198.0,51.161.0"}
P.entries["npc:josef-gregorian"] = {n="Josef Gregorian",s="Josef Gregorian ist ein Schneidereilehrer der Verlassenen, der im Magieviertel von Unterstadt arbeitet. Er leitet ehrgeizige Schneider der Horde an, die verzauberte Stoffe weben wollen, teilt sein Fachwissen mit ihnen und weist ihnen den Weg zu spezialisierten Gewändern.",h="Josef Gregorian ist ein Schneidereilehrer der Verlassenen, der im Magieviertel von Unterstadt arbeitet.",kw={"materialsammlung","josef gregorian","magieviertel","roben des zauberfeuers","schneidereilehrer","unterstadt"},ang={["profession:Tailoring"]="Für Tuchmacher der Horde ist Josef Gregorian eine erstklassige Anlaufstelle in Lordaeron; er unterrichtet Schneider und fertigt Roben für junge Magier, die ihm die nötigen Materialien bringen.",["race:Undead"]="Gregorian beweist, dass die feine Kunst der menschlichen Schneiderei trotz Tod und Untod den Fall von Lordaeron überstanden hat, um nun der neuen Gesellschaft der Verlassenen zu dienen."},sec={{t="Weber des Magieviertels",b="Inmitten der trüben alchemistischen Laternen und feuchten Gewölbe des Magieviertels pflegt Josef Gregorian das feine Handwerk der Schneiderei für die Verlassenen und ihre Verbündeten der Horde. Auch wenn das Leben im unterirdischen Königreich kalt geworden ist, bleibt die Stoffverarbeitung für Hexenmeister, Magier und Priester, die rohe Energien durch gewebte Fasern leiten, unverzichtbar. Gregorian dient in der Hauptstadt als verlässlicher Ausbilder, stets bereit, grundlegende Schnittmuster zu lehren und die ersten Roben junger Magier zu nähen, die ihm die passenden Materialien bringen."}},faq={{q="Wo kann ich Josef Gregorian finden?",a="Josef Gregorian befindet sich im Magieviertel von Unterstadt, wo er inmitten der Zauberwirker und Gelehrten der Stadt das Schneiderhandwerk ausübt und lehrt.",al={"josef gregorian aufenthaltsort","wo ist gregorian","unterstadt schneidereilehrer"}},{q="Welche Rolle spielt Josef Gregorian in Unterstadt?",a="Er ist ein Schneidereilehrer, der Handwerkern der Horde Schneiderrezepte und Techniken beibringt. Zudem näht er die ersten Roben junger Magier, die von Anastasia Hirschbrunn zu ihm geschickt werden.",al={"was macht josef gregorian","josef gregorian lehrer","unterstadt schneiderei"}},{q="Welche Quests bietet Josef Gregorian an?",a="Gregorian nimmt an einer Questreihe für Magier teil: Anastasia Hirschbrunn schickt junge Magier mit Leinenstoff und in Silberwald erbeuteten Dalaran-Manasteinen zu ihm (Materialsammlung), woraufhin er ihnen Roben des geringen Zauberfeuers näht (Roben des Zauberfeuers).",al={"josef gregorian quests","roben quests unterstadt"}}},fx={d179720d={q="Wer ist Josef Gregorian?",a="Josef Gregorian ist ein untoter Handwerker, der als Schneiderlehrer im Magieviertel der Unterstadt dient. Wie viele Handwerker der Verlassenen hat er die feinen Fertigkeiten seines früheren Lebens bewahrt und setzt sein Wissen über Fäden, Stoffe und verzauberte Gewänder für das Volk von Königin Sylvanas und deren Verbündete der Horde ein.",al={"wer ist josef gregorian","hintergrund von josef gregorian","wer ist der schneider josef gregorian"}},["057f78ac"]={q="Auf wessen Seite steht Josef Gregorian?",a="Er ist den Verlassenen und der Horde loyal. Tief in der Unterstadt stationiert, bietet er sein Wissen über Schneiderei, Schnittmuster und handwerkliche Weisheit ausschließlich denjenigen an, die im Dienste der Dunklen Fürstin und der Horde stehen.",al={"fraktion von josef gregorian","ist josef gregorian horde","wem dient josef gregorian"}},["3b87a245"]={q="Warum ist Josef Gregorian in der Unterstadt?",a="Josef bleibt in der Unterstadt, um das Schneiderhandwerk auszuüben und andere darin zu unterrichten. Sein Workshop inmitten der Zauberwirker und Gelehrten des Magieviertels ermöglicht es ihm, Roben, verzauberte Gewänder und Stoffrüstungen für Abenteurer zu weben, die sich in die Pestländer und darüber hinaus wagen.",al={"warum ist josef gregorian hier","was brachte josef gregorian in die unterstadt","warum ist josef im magieviertel"}}},fp="15,238,27.506.0,33.148.0,54.169.0,39.241.0"}
P.entries["npc:kaal-soulreaper"] = {n="Kaal Seelentod",s="Kaal Seelentod ist ein Orc-Hexenmeisterlehrer, der tief im Magieviertel von Unterstadt stationiert ist. Obwohl er unter den Verlassenen weilt, pflegt er enge Bande zu anderen Anwendern der dunklen Künste in der gesamten Horde und schickt Lehrlinge regelmäßig zu Mentoren in fernen Ländern.",h="Kaal Seelentod ist ein Orc-Hexenmeisterlehrer, der tief im Magieviertel von Unterstadt stationiert ist.",kw={"dämonologie","felsteed","kaal seelentod","magieviertel","menara leerbringer","unterstadt","hexenmeisterlehrer"},ang={["class:Warlock"]="Kaal Seelentod bietet grundlegendes Training in dämonischen Künsten und weist ehrgeizigen Hexenmeistern den Weg zur Erschaffung der Orb of Orahil und der Bindung eines Felsteed.",["race:Orc"]="Anders als der verborgene Zirkel in der Kluft der Schatten agiert Kaal offen in der Hauptstadt der Verlassenen, fernab der wachsamen Blicke von Orgrimmars schamanischer Führung."},sec={{t="Ein Anwender in den Schatten",b="Während Thralls Horde die Teufelsmagie in Orgrimmar streng reguliert und überwacht, finden Anwender wie Kaal Seelentod reichlich Zuflucht in den unterirdischen Sankten von Lordaeron. Kaal, der im Magieviertel von Unterstadt residiert, teilt seine Meisterschaft über dämonische Wesenheiten und Flüche mit lernwilligen Hexenmeistern der Horde. Über die grundlegende Unterweisung hinaus fungiert er als wichtiger Kontakt für Anwender, die nach größerer Macht streben, und schickt ehrgeizige Schüler über das Meer zu Mentoren wie Menara Leerbringer im Brachland."}},faq={{q="Wer ist Kaal Seelentod?",a="Kaal Seelentod ist ein Orc-Hexenmeisterlehrer, der im Magieviertel von Unterstadt residiert. Er lehrt Hexenmeisterzauber und bietet Anwendern Führung, die nach spezialisierten dunklen Artefakten und Ritualen suchen.",al={"wer ist kaal","kaal seelentod geschichte","kaal unterstadt"}},{q="Warum lebt ein Orc-Hexenmeister in Unterstadt?",a="Hexenmeister sehen sich in der orcischen Gesellschaft unter Kriegshäuptling Thrall großem Argwohn und genauer Beobachtung ausgesetzt. Unterstadt bietet ein weitaus toleranteres Umfeld, um an der Seite der Verlassenen Schattenmagie und Dämonologie zu studieren.",al={"warum ist ein orc in unterstadt","warum ist kaal in unterstadt"}},{q="Wohin schickt Kaal Seelentod seine Lehrlinge?",a="Sobald seine Schüler ein ausreichendes Können erlangt haben, schickt Kaal sie über das große Meer ins Brachland, um bei Menara Leerbringer zu lernen, oder macht sie mit anderen prominenten Hexenmeistern der Horde bekannt.",al={"kaal quests","zu wem schickt einen kaal"}}},fx={["17865f78"]={q="Auf wessen Seite steht Kaal Seelentod?",a="Kaal Seelentod steht fest an der Seite der Horde. Obwohl er ein Orc ist, der neben den Verlassenen in der Unterstadt lebt, bildet er Hexenmeister aus, die der Sache der Horde die Treue schwören. Er unterhält direkte Verbindungen zu anderen Praktizierenden der Horde in ganz Kalimdor und den Östlichen Königreichen, einschließlich Hexenmeistern im Brachland und Ratschet, und stellt sicher, dass diejenigen, die dunkle Künste ausüben, ihre Teufelsmacht weiterhin darauf ausrichten, ihren Verbündeten zu helfen.",al={"fraktion von kaal seelentod","wem dient kaal seelentod","ist kaal seelentod horde"}},["78b7a2d4"]={q="Was will Kaal Seelentod?",a="Kaal versucht, angehende Hexenmeister auf dem gefährlichen Pfad der dämonischen Meisterschaft zu leiten. Anstatt unerfahrene Praktizierende den verderbenden Mächten des Wirbelnden Nether erliegen zu lassen, stellt er sicher, dass sie die notwendigen Riten erlernen, um Dämonen wie das Teufelsross zu beschwören und zu binden, und verweist vielversprechende Schüler an erfahrene Meister wie Menara Leerbringer, um ihr Handwerk zu vertiefen.",al={"motiv von kaal seelentod","ziel von kaal seelentod","was tut kaal seelentod"}},a46613eb={q="Mit wem ist Kaal Seelentod verbunden?",a="Kaal unterhält enge Verbindungen zu anderen Hexenmeister-Mentoren auf den Kontinenten. Er arbeitet regelmäßig mit Menara Leerbringer im Brachland und dem Hexenmeister Kazak Darkscream zusammen und verweist fähige Praktizierende für spezialisierte Ausbildung, fortgeschrittene Rituale und die Beschaffung von Artefakten wie dem Orb of Orahil an sie.",al={"verbindungen von kaal seelentod","mit wem arbeitet kaal seelentod zusammen","verbündete von kaal seelentod"}}},fp="15,279,29.516.0,23.195.0,46.201.0,48.185.0"}
P.entries["npc:kadrak"] = {n="Kadrak",s="Kadrak ist ein erfahrener Orc-Kommandant, der am Mor'shan-Schutzwall an der Grenze zwischen dem Brachland und dem Eschental stationiert ist. Er hat die Aufgabe, die nördliche Grenze zu sichern und koordiniert den Fluss von Depeschen und Verstärkungen in den umkämpften Wald. Für Abenteurer der Horde, die über die trockenen Ebenen hinausziehen, dient Kadrak als Tor zum laufenden Kampf gegen die Nachtelfen.",h="Kadrak ist ein erfahrener Orc-Kommandant, der am Mor'shan-Schutzwall an der Grenze zwischen dem Brachland und...",kw={"eschental","brachland","kadrak","der mor'shan-schutzwall","orc","schutzwall","splitterholzposten","warsong"},ang={["class:Warrior"]="Kadrak verkörpert die Disziplin an der Front und verlässt sich auf rohen Stahl und militärische Stärke, um einen befestigten Engpass gegen feindselige Waldläufer und Guerillaangriffe zu halten.",["faction:Alliance"]="Für die Streitkräfte der Allianz, die versuchen, vom Eschental aus in das Brachland vorzudringen, stellen Kadrak und sein Schutzwall ein befestigtes Hindernis dar, das das Kernland der Horde bewacht.",["faction:Horde"]="Kadrak ist Euer Zugangspunkt zu den Feldzügen im Eschental und lenkt den Strom der Krieger nach Norden, um die Holzfällarbeiten zu verteidigen und das Territorium der Horde zu erweitern.",["race:Orc"]="Als standhafter Veteran, der das Vermächtnis der Bemühungen des Kriegshymnenklans um das Territorium aufrechterhält, steht Kadrak für die unbeugsame Entschlossenheit der Orcs an der Grenze zum Eschental."},sec={{t="Wächter des Schutzwalls",b="Auf den befestigten Holzbarrikaden des Mor'shan-Schutzwalls stehend, wacht Kadrak über die Hauptroute, die das Brachland mit dem Eschental verbindet. Die Grenze ist ein heikler Grenzposten: Im Süden liegen die sonnenverbrannten Ebenen, die von der Horde beansprucht werden, während im Norden die uralten Wälder aufragen, die erbittert von den Nachtelfen verteidigt werden. Kadrak stellt sicher, dass der Verteidigungswall gegen eindringende Sentinels und feindselige Waldkreaturen intakt bleibt."},{t="Logistik an der Front",b="Neben der Verteidigung der Linie verwaltet Kadrak wichtige militärische Informationen zwischen dem Brachland und den vorgerückten Holzfällerlagern tiefer im Wald. Er empfängt Kuriere mit kritischen Kampfberichten der Vorhut des Kriegshymnenklans und koordiniert den Transport von Nachschub und frischen Kräften in Außenposten wie den Splitterholzposten. Diejenigen, die sich bei ihm melden, werden umgehend in das Herz des Gebietskrieges geschickt."}},faq={{q="Wer ist Kadrak?",a="Kadrak ist ein Orc-Offizier, der am Mor'shan-Schutzwall stationiert ist. Er überwacht die Grenzsicherheit und dirigiert die Truppen der Horde, die zwischen dem Brachland und den Kriegszonen im Eschental reisen.",al={"kadrak identität","wer ist der orc am wall","mor'shan-schutzwall kommandant"}},{q="Wo ist Kadrak zu finden?",a="Kadrak steht am Mor'shan-Schutzwall, der befestigten hölzernen Barrikade am äußersten nördlichen Rand des Brachlandes, die den Übergang zum Eschental markiert.",al={"kadrak standort","kadrak finden","wo ist kadrak"}},{q="Was ist Kadraks Rolle in der Horde?",a="Er kommandiert den Verteidigungswall an der Grenze, sammelt militärische Informationen von Spähern und briefre Reisende der Horde, die nach Norden ziehen, um Außenposten wie den Splitterholzposten zu verstärken.",al={"kadraks pflichten","was tut kadrak","kadrak rolle"}},{q="Warum ist der Mor'shan-Schutzwall stark verteidigt?",a="Der Schutzwall schützt die nördlichen Zugänge des Brachlandes und Durotar vor Vergeltungsschlägen der Nachtelfen, die durch die Holzfällarbeiten der Horde im Eschental ausgelöst wurden.",al={"warum ist mor'shan-schutzwall befestigt","zweck des schutzwalls","warum die grenze zum eschental bewachen"}},{q="Welche Quests bietet oder schließt Kadrak ab?",a="Kadrak nimmt Berichte entgegen, die aus dem Brachland gebracht werden, und schickt Abenteurer auf Missionen bezüglich der Spähberichte des Kriegshymnenklans und dem Aufbau einer stärkeren Präsenz der Horde entlang der Waldgrenze.",al={"kadrak quests","report to kadrak","bericht des kriegshymnenklans"}},{q="Hat Kadrak Verbindungen zu anderen bedeutenden Figuren der Horde?",a="Kadrak unterhält eine regelmäßige Kommunikation mit der Vorhut des Kriegshymnenklans, die im Eschental operiert, und nimmt deren Spähberichte am Schutzwall entgegen.",al={"kadrak verbindungen"}}},fx={e1636f20={q="Auf wessen Seite steht Kadrak?",a="Kadrak ist ein loyaler Krieger der Horde. Stationiert an der zerklüfteten Grenze zwischen dem Brachland und den umkämpften Wäldern des Eschentals, dient er unter dem Banner des Kriegshäuptlings, bestrebt, die Interessen der Orcs zu sichern und Außenposten der Horde gegen Einfälle der Nachtelfen zu verteidigen.",al={"fraktion von kadrak","ist kadrak horde","wem dient kadrak"}},["4dfee007"]={q="Was will Kadrak?",a="Kadrak zielt darauf ab, die nördliche Grenze des Brachlands zu halten und die Präsenz der Horde tiefer in das Eschental voranzutreiben. Angesichts heftigen Widerstands der Nachtelfen sucht er nach fähigen Champions der Horde, um Berichte zu überbringen, bedrängte Kundschafter abzulösen und wichtige Versorgungslinien über den Mor'shan-Schutzwall zu schützen.",al={"was ist das ziel von kadrak","motiv von kadrak","was benötigt kadrak"}},["86a4d862"]={q="Warum ist Kadrak hier am Mor'shan-Schutzwall?",a="Kadrak hält Wache am Mor'shan-Schutzwall, weil er der entscheidende Engpass ist, der das Brachland vor den feindseligen Wäldern des Eschentals schützt. Während die Feindseligkeiten mit den Nachtelfen aufflammen, koordiniert er die Verteidigung, überwacht feindliche Aktivitäten und weist Kundschafter an, die Außenposten der Kriegshymnenklans im Norden zu verstärken.",al={"warum ist kadrak am schutzwall","grund für kadraks standort","warum ist kadrak hier stationiert"}}},fp="6,379,23.446.0,19.406.0,14.173.0,26.155.0,35.187.0,45.165.0,44.190.0,53.142.0"}
P.entries["npc:kaela-shadowspear"] = {n="Kaela Schattenspeer",s="Kaela Schattenspeer ist eine Nachtelfenschildwache, die südwestlich der Scherwindklippe im Steinkrallengebirge stationiert ist. Von ihrem kleinen Vorposten aus koordiniert sie sich mit anderen Schildwachen, um eskalierende Spannungen und regionale Störungen in der Wildnis zu überwachen. Sie verlässt sich auf mutige Reisende, um gefährliches Terrain auszukundschaften und den verwundeten Verteidigern des Landes Hilfe zu bringen.",h="Kaela Schattenspeer ist eine Nachtelfenschildwache, die südwestlich der Scherwindklippe im...",kw={"urtume","kaela","rustfizzle","schildwache","shadowspear","geister","steinkrallengebirge","thenysil","scherwindklippe"},ang={["class:Druid"]="Druiden werden ein gemeinsames Anliegen in Kaelas Bemühungen finden, verletzte Urtume wieder gesundzupflegen und die Qualen der verstörten Naturgeister zum Schweigen zu bringen.",["faction:Alliance"]="Kaela Schattenspeer dient als entscheidende Anlaufstelle für Abenteurer der Allianz, die sich in die umkämpften Gebiete des Steinkrallengebirges vorwagen, und koordiniert Informationen zwischen weit entfernten Vorposten.",["race:NightElf"]="Für die Nachtelfen steht Kaela für die standhafte Verteidigung heiligen Bodens, die sich dafür einsetzt, aufgebrachte Geister zu besänftigen und die verehrten Urtume von Kalimdor zu beschützen."},sec={{t="Eine Kundschafterin an der Front",b="Gleich südwestlich der industriellen Zerstörung der Scherwindklippe wacht Kaela Schattenspeer aufmerksam über die umliegenden Pässe. Das Steinkrallengebirge birgt große Gefahren, da die Horde immer weiter vordringt und Goblinoperationen die natürlichen Reichtümer des Landes ausbeuten. Gemeinsam mit dem Gnom Gaxim Rostknirsch agiert Kaela als unverzichtbare Verbindungsperson für die Nachtelfen und spürt Bedrohungen nach, die tiefer in das angestammte Territorium vordringen."},{t="Die Heilung des Landes",b="Die Unruhen im Steinkrallengebirge reichen weit über territoriale Scharmützel hinaus. Die gewaltsame Störung der Natur hat die Elementare aufgewiegelt und den uralten Wächtern des Waldes Schaden zugefügt. Kaela arbeitet unermüdlich daran, Abenteurer gegen wütende Elementargeister auszusenden und die verletzten Urtume zu versorgen, die im Kreuzfeuer der regionalen Konflikte leiden, um den Frieden wiederherzustellen, bevor das Land unwiderruflich gezeichnet ist."}},faq={{q="Wer ist Kaela Schattenspeer?",a="Kaela Schattenspeer ist eine Nachtelfen-Questgeberin, die in einem Grenzposten südwestlich der Scherwindklippe im Steinkrallengebirge stationiert ist. Sie überwacht die regionale Erkundung und hilft beim Schutz der einheimischen Wildtiere und Geister.",al={"wer ist kaela","kaela schattenspeer identität","kaela nsc"}},{q="Wo ist Kaela Schattenspeer zu finden?",a="Sie befindet sich in einem kleinen Allianz-Lager südwestlich der Scherwindklippe an der Straße im Steinkrallengebirge, das sie sich mit dem Gnomen-Ingenieur Gaxim Rostknirsch teilt.",al={"kaela schattenspeer aufenthaltsort","wo ist kaela","kaela steinkrallengebirge lager"}},{q="Wem untersteht Kaela?",a="Kaela stimmt sich eng mit Schildwache Thenysil ab und sendet sowie empfängt regelmäßig Aufklärungsberichte über feindliche Bewegungen und lokale Bedrohungen im gesamten Steinkrallengebirge.",al={"wem untersteht kaela","kaela thenysil","kaelas befehlshaber"}},{q="Warum ist Kaela wegen der Elementare besorgt?",a="Intensive Abholzung, Bergbau und militärische Vorstöße im Steinkrallengebirge haben das natürliche Gleichgewicht tief erschüttert, was dazu geführt hat, dass Elementargeister in Wut geraten sind und jeden in der Nähe angreifen.",al={"wütende geister quest","warum sind geister wütend","kaela elementargeister"}},{q="Was geschieht mit den Urtumen nahe der Scherwindklippe?",a="Die regionalen Konflikte und die rasante Abholzung haben uralte Beschützer verwundet und leidend zurückgelassen. Kaela sucht die Hilfe von Reisenden, um diese gefallenen Beschützer der Wildnis zu finden und zu heilen.",al={"verletzte urtume quest","kaela urtume","steinkrallengebirge verletzte urtume"}},{q="Warum ist ein Gnom bei Kaela stationiert?",a="Kaela teilt ihr Lager mit Gaxim Rostknirsch, einem Gnom der Allianz. Während Kaela sich auf das spirituelle und taktische Gleichgewicht der Wildnis konzentriert, ist Gaxim bestrebt, den feindlichen Goblin-Maschinen und deren Operationen in der Nähe entgegenzuwirken.",al={"gaxim rostknirsch kaela","warum ist gaxim bei kaela","gnomen- und nachtelfenlager"}}},fx={["62b8f918"]={q="Was will Kaela Schattenspeer?",a="Kaela hat es sich zum Ziel gesetzt, das Steinkrallengebirge vor der Verwüstung zu schützen. Sie versucht, die erzürnten Elementargeister zu besänftigen, sich um die verwundeten Uralten zu kümmern, die in diesem Gebiet leiden, und ihre Kommandanten über regionale Bedrohungen auf dem Laufenden zu halten.",al={"ziel von kaela schattenspeer","was will kaela","kaela ziele"}},bb8cec73={q="Warum ist Kaela Schattenspeer hier?",a="Kaela ist südwestlich der Scherwindklippe als Wachposten-Späherin stationiert. Von diesem Außenposten aus überwacht sie Störungen im gesamten Steinkrallengebirge, insbesondere das Schicksal der verderbten lokalen Geister und die Not der nahegelegenen Uralten.",al={"warum ist kaela schattenspeer im steinkrallengebirge","mission von kaela schattenspeer","warum ist kaela hier"}},e879ebe3={q="Auf wessen Seite steht Kaela Schattenspeer?",a="Kaela steht fest an der Seite der Nachtelfen und der Allianz. Stationiert im Steinkrallengebirge, dient sie Darnassus und dem Kommando der Sentinel, wobei sie sich eng mit anderen Kundschaftern der Allianz abstimmt, um das Land gegen eindringende Gegner zu verteidigen.",al={"fraktion von kaela schattenspeer","ist kaela allianz","loyalität von kaela schattenspeer"}}},fp="17,351,23.446.0,16.414.0,25.216.0,37.179.0,25.158.0,44.178.0,54.185.0,36.230.0"}
P.entries["npc:kali-remik"] = {n="Kali Remik",s="Kali Remik ist eine Jägerin der Dunkelspeertrolle, die ihre Zeit damit verbringt, Reisenden im Kerngebiet der Horde mit Rat und Tat zur Seite zu stehen. Da sie mit den Methoden der Fährtenleserei und des Überlebens in Durotar bestens vertraut ist, verweist sie junge Jäger an Thotar in Klingenhügel, damit diese dort die Zähmung von Wildtieren erlernen.",h="Kali Remik ist eine Jägerin der Dunkelspeertrolle, die ihre Zeit damit verbringt, Reisenden im Kerngebiet der...",kw={"dunkelspeer","durotar","kali remik","sen'jin","der weg des jägers","fährtenleser","tal der geister"},ang={["class:Hunter"]="Für junge Orc- und Trollschützen fungiert Kali als Sprungbrett; sie erkennt, wenn Eure Fähigkeiten über die Übungen im Dorf hinausgehen und schickt Euch weiter zu Thotar nach Klingenhügel.",["race:Troll"]="Als Mitglied des Dunkelspeerstamms hält Kali Wache über ihr Volk, während dieses sein Leben entlang der Küste von Durotar wieder aufbaut und sich im Tal der Geister von Orgrimmar niederlässt."},sec={{t="Ein Leitfaden für die Jagd",b="Kali Remik ist eine erfahrene Dschungeltroll-Späherin, die mit den trockenen Einöden von Durotar und den geschäftigen Zentren der Horde bestens vertraut ist. In Küstensiedlungen wie Sen'jin wacht sie über junge Späher, die ihre ersten Schritte außerhalb vom Tal der Prüfungen unternehmen. Wenn sie erkennt, dass ein Neuling den örtlichen Trainingsgeländen entwachsen ist, greift sie ein und weist vielversprechende Schützen den Weg zu Thotar in Klingenhügel, damit diese dort ihre Ausbildung zum Tierherrscher beginnen können, um so sicherzustellen, dass die Reihen der Grenzschützer der Horde scharf und diszipliniert bleiben."}},faq={{q="Wer ist Kali Remik?",a="Kali Remik ist eine Späherin der Dunkelspeertrolle und eine Questgeberin. Sie hilft dabei, junge Abenteurer der Horde anzuleiten, insbesondere Jäger, die bereit sind, ihre Ausbildung über die örtlichen Außenposten hinaus fortzusetzen.",al={"kali remik hintergrundgeschichte","wer ist kali remik","kali remik npc"}},{q="Wo kann man Kali Remik finden?",a="Sie kann dabei angetroffen werden, wie sie ihrem Volk in Durotar beisteht, vor allem in der Umgebung von Sen'jin.",al={"wo ist kali remik","kali remik standort","kali remik finden"}},{q="Welche Anleitung bietet sie Jägern?",a="Durch 'Der Pfad des Jägers' weist Kali junge Orc- und Trolljäger, die ihre grundlegenden Fähigkeiten unter Beweis gestellt haben, an, nach Klingenhügel zu reisen, wo Thotar sie auf den Pfad bringt, ein eigenes Wildtier als Begleiter zu zähmen.",al={"quest der pfad des jägers","kali remik jägerquest","was lehrt kali"}}},fx={f072d80b={q="Auf welcher Seite steht Kali Remik?",a="Kali Remik ist dem Darkspear tribe treu ergeben und steht fest zur Horde von Thrall. Sie unterstützt ihr Volk und dessen Verbündete, indem sie junge Kundschafter der Wildnis und Schützen anleitet, damit diese eine angemessene Ausbildung erhalten und ihrem neuen Zuhause dienen können.",al={"fraktion von kali remik","wem dient kali remik","kali remik horde"}},bd47d9e0={q="Warum ist Kali Remik im Sen'jin?",a="Kali Remik bleibt im Sen'jin, um über die aufstrebenden Verteidiger des Darkspear tribe zu wachen. In diesen Küstengewässern hilft sie dabei, vielversprechende junge Jäger unter den Orcs und Trollen zu identifizieren, die den Ort passieren, und verweist sie an die Ausbilder, die ihre Überlebensfertigkeiten verfeinern können.",al={"warum ist kali remik hier","rolle von kali remik im sen'jin","was brachte kali remik hierher"}},a3912784={q="Was will Kali Remik?",a="Kali Remik möchte, dass Durotar von fähigen Kundschaftern und Stalkern geschützt wird. Sie sucht nach angehenden Jägern, um sicherzustellen, dass sie nicht unvorbereitet umherirren, und weist ihnen den richtigen Weg zu den Ausbildern, die ihnen die Wege der Wildnis lehren können.",al={"was will kali remik","motivation von kali remik","was ist das ziel von kali remik"}},["528bbb7d"]={q="Wem ist Kali Remik verbunden?",a="Sie ist eng mit den Darkspear der Darkspear-Trolle im Sen'jin verbunden und arbeitet eng mit den Jägerausbildern in Durotar zusammen. Ihre Pflichten verknüpfen sie mit dem breiteren Überlebensnetzwerk der Horde, wodurch sichergestellt wird, dass neue Rekruten Kontakt zu etablierten Mentoren in ihrem gesamten Gebiet aufnehmen.",al={"wem ist kali remik verbunden","verbindungen von kali remik","verbündete von kali remik"}}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="Kaltunk",s="Kaltunk ist ein Orc-Aufseher, der im Herzen vom Tal der Prüfungen in Durotar stationiert ist. Er dient als allererste Anlaufstelle für junge Orcs, die ihre ersten Schritte in die Welt wagen. Es ist seine Pflicht, diese aufstrebenden Champions willkommen zu heißen und sie zu ihren anfänglichen Aufgaben im Dienst der Horde zu leiten.",h="Kaltunk ist ein Orc-Aufseher, der im Herzen vom Tal der Prüfungen in Durotar stationiert ist.",kw={"durotar","gornek","kaltunk","orc-startgebiet","das tal der prüfungen","your place in the world"},ang={["faction:Horde"]="Kaltunk hilft dabei, die praktische Disziplin aufrechtzuerhalten, die nötig ist, um die Ordnung auf dem rauen Übungsgelände von Durotar zu wahren.",["race:Orc"]="Für jeden Orc, der hinaus nach Kalimdor zieht, sind Kaltunks barsche Anweisungen die ersten Worte, die er hört, während er beginnt, sich seine Ehre zu verdienen."},sec={{t="Der erste Schritt",b="Unter der sengenden Sonne vom Tal der Prüfungen wacht Kaltunk über die neu eingetroffenen Hoffnungsträger, die sich der Horde als würdig erweisen wollen. Während andere Ausbilder und Älteste zermürbende Prüfungen und Jagdriten zuweisen, sorgt Kaltunk dafür, dass kein Rekrut ziellos durch den roten Staub irrt. Er erteilt unmissverständliche Befehle und weist Neulinge direkt an Gornek und auf den Pfad der Disziplin."},{t="Hüter des Tals",b="Das Tal der Prüfungen ist kein einfaches Übungsgelände; es wurde eigens ausgewählt, um die Stärke und Widerstandskraft jedes Jugendlichen zu schmieden, der seine Schluchtböden betritt. Kaltunk verkörpert diese raue Zweckmäßigkeit. Er hält keine großen Reden und verhätschelt niemanden, sondern erwartet von jedem Orc, dass er rasch seinen Platz in der Welt findet und seinen Teil für den Kriegshäuptling beiträgt."}},faq={{q="Wer ist Kaltunk?",a="Kaltunk ist ein Orc-Aufseher, der im Tal der Prüfungen stationiert ist. Er ist die allererste Person, der neu erwachte Orc-Abenteurer begegnen, und hat die Aufgabe, sie an ihre Mentoren zu verweisen und ihre Ausbildung in Gang zu setzen.",al={"kaltunk rolle","wer ist dieser orc","kaltunk nsc"}},{q="Was tut Kaltunk für neue Abenteurer?",a="Er gibt neuen Rekruten ihre erste Aufgabe und schickt sie los, um mit Gornek an einem anderen Ort im Tal zu sprechen, damit ihr eigentliches Training beginnen kann.",al={"kaltunk quest","was will kaltunk","erste quest tal der prüfungen"}},{q="Wo kann ich Kaltunk finden?",a="Er steht direkt beim zentralen Ausbildungszelt und dem Lagerfeuer im Tal der Prüfungen, dem abgelegenen Startgebiet im südlichen Durotar.",al={"kaltunk aufenthaltsort","kaltunk finden","wo ist kaltunk"}},{q="Warum ist er im Tal der Prüfungen stationiert?",a="Er fungiert als empfangender Aufseher, um sicherzustellen, dass eintreffende Orc-Rekruten organisiert und unverzüglich auf ihren Pfad im Dienst für Thralls Horde geleitet werden.",al={"warum ist kaltunk hier","kaltunk zweck"}}},fx={["7b0fd1f8"]={q="Auf wessen Seite steht Kaltunk?",a="Kaltunk dient der Horde und steht fest unter dem Befehl von Kriegshäuptling Thrall. Er ist im Tal der Prüfungen stationiert, speziell um neue Orc-Rekruten willkommen zu heißen und ihre ersten Schritte in den Dienst für die neue Nation Durotar zu lenken.",al={"kaltunk fraktion","wem dient kaltunk","ist kaltunk horde"}},["5cbb3fad"]={q="Was will Kaltunk?",a="Kaltunk will, dass Ihr Euch vor der Horde beweist. Er stellt sicher, dass untätige Neuankömmlinge nicht herumlungern, und weist Euch umgehend an Gornek und die Aufseher im Tal der Prüfungen weiter, damit Eure Ausbildung und Euer Dienst für Durotar ohne Verzögerung beginnen können.",al={"was braucht kaltunk","kaltunk ziel","kaltunk motiv"}}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:kam-deepfury"] = {n="Kam Tiefenzorn",s="Kam Tiefenzorn ist ein berüchtigter Saboteur der Dunkeleisenzwerge, der in den Tiefen des Verlieses von Sturmwind eingekerkert ist. Anders als die Mehrheit der Insassen des Gefängnisses hegt er keinerlei Loyalität gegenüber der Bruderschaft der Defias; er wurde gefangen genommen, weil er weit im Norden eine verheerende Explosion am Thandol-Übergang inszeniert hatte.",h="Kam Tiefenzorn ist ein berüchtigter Saboteur der Dunkeleisenzwerge, der in den Tiefen des Verlieses von...",kw={"dunkeleisenzwerge","deepfury","dun modr","garmason","kam tiefenzorn","longbraid","das verlies","sturmwind","thandol-übergang"},ang={["faction:Alliance"]="Während die meisten Blicke in Sturmwind auf den Defias-Aufstand gerichtet sind, ist Deepfury eine Mahnung an die umfassendere Bedrohung durch die Dunkeleisenzwerge, welche die nördlichen Grenzen der Allianz heimsucht.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede ist Kam Tiefenzorn ein verhasster Feind, dessen Sabotage den Thandol-Übergang zerstörte und die Sippe von Langzopf dem Grimmigen ermordete. Diesen Verlust zu rächen, ist eine Frage der persönlichen Ehre."},sec={{t="Ein Saboteur fern der Heimat",b="Während das Verlies überwiegend mit unzufriedenen Steinmetzen und Defias-Rebellen gefüllt ist, sticht Kam Tiefenzorn heraus. Als gerissener und gewalttätiger Dunkeleisenzwerg wurde Deepfury gefasst und nach Sturmwind gebracht, nachdem er eine Operation geleitet hatte, die lebenswichtige nördliche Infrastruktur lahmlegte. Er sitzt tief in den Zellen des Gefängnisses ein, isoliert von seiner Sippe unter dem Schwarzfels, doch der Allianz gegenüber ebenso feindselig gesinnt wie jeder rebellische Aufrührer, der die Korridore mit ihm teilt."},{t="Die Sabotage am Thandol-Übergang",b="Die in Dun Modr nahe der nördlichen Grenze des Sumpflands stationierten Aufklärer der Allianz identifizierten Deepfury als den Haupturheber der Explosion, die den Thandol-Übergang zerriss. Die Detonation zerstörte eine der gewaltigen Steinbrücken, die das Sumpfland mit dem Arathihochland verbinden. Neben der Zerstörung einer für Eisenschmiede und die Allianz entscheidenden Handels- und Militärroute forderte der Sabotageakt das Leben eines Verwandten des Zwergenkommandanten Langzopf der Grimmige."},{t="Eine offene Rechnung",b="Der Aufständische der Dunkeleisenzwerge konnte der Vergeltung nicht lange entgehen, wenngleich die Inhaftierung in Sturmwind ihm vorübergehenden Schutz vor den Verwandten seiner Opfer bot. Zurück im Sumpfland haben Motley Garmason und der trauernde Langzopf der Grimmige Söldner gesucht, die bereit sind, das von Aufständen erschütterte Gefängnis zu infiltrieren und Deepfurys Kopf abzutrennen, um eine blutige Fehde beizulegen, die hunderte Meilen weiter nördlich ihren Anfang nahm."}},faq={{q="Wer ist Kam Tiefenzorn?",a="Kam Tiefenzorn ist ein gefangener Elite-Dunkeleisenzwerg, der im Verlies von Sturmwind eingesperrt ist. Er ist dafür bekannt, die Sabotage am Thandol-Übergang im Norden angezettelt zu haben, und hat keinerlei Verbindungen zu den neben ihm inhaftierten Defias-Rebellen.",al={"wer ist deepfury","kam tiefenzorn lore","wer ist der zwerg im verlies"}},{q="Warum sitzt ein Dunkeleisenzwerg im Verlies von Sturmwind ein?",a="Deepfury wurde gefasst, nachdem er einen Angriff koordiniert hatte, der eine der Brücken am Thandol-Übergang sprengte, zwergische Verteidiger tötete und einen lebenswichtigen Landweg zwischen dem Sumpfland und Arathi abschnitt. Er wurde in das Hochsicherheitsgefängnis von Sturmwind überstellt, um seiner Strafe harrte.",al={"warum ist er im verlies","was hat kam tiefenzorn getan","warum ist er eingesperrt"}},{q="Gehört Kam Tiefenzorn zur Bruderschaft der Defias?",a="Nein. Obwohl er während ihres Aufstands im Verlies an der Seite der Bruderschaft der Defias gefangen gehalten wird, gehört Deepfury zum feindseligen Dunkeleisen-Klan. Er handelt gänzlich nach den aggressiven Plänen seines eigenen Klans gegen die Allianz und Eisenschmiede.",al={"gehört er zu den defias","kam tiefenzorn defias","arbeitet deepfury mit vancleef zusammen"}},{q="Wer will Kam Tiefenzorn tot sehen?",a="Motley Garmason und die in Dun Modr stationierten Zwergentruppen aus Eisenschmiede wollen seinen Tod. Langzopf der Grimmige verlor bei Deepfurys Sprengung des Thandol-Übergangs einen Verwandten, weshalb sie Abenteurer in Sturmwind dazu aufriefen, seinen Kopf zu fordern.",al={"wer vergibt die quest für deepfury","wer will deepfury tot sehen"}},{q="Wo hat Kam Tiefenzorn sein Verbrechen begangen?",a="Deepfury organisierte die Sabotage am Thandol-Übergang, dem kolossalen Brückenkomplex, der das Sumpfland weit nördlich von Sturmwind mit dem Arathihochland verbindet.",al={"wo wurde die brücke gesprengt","deepfury brückensprengung","angriff auf thandol-übergang"}},{q="Wo ist Kam Tiefenzorn im Verlies zu finden?",a="Kam Tiefenzorn wird in den Zellenblöcken des Verlieses von Sturmwind gefangen gehalten, welches sich unter dem Kanalviertel von Sturmwind befindet.",al={"wo ist deepfury im verlies","kam tiefenzorn standort"}}},fx={["1bde1b20"]={q="Mit wem ist Kam Tiefenzorn verbündet?",a="Kam Tiefenzorn gehört dem feindseligen Clan der Dunkeleisenzwerge an. Obwohl er zusammen mit rebellischen Taschendieben und Sträflingen in der Stormwind Stockade festgehalten wird, hat er keine Verbindungen zur The Defias Brotherhood. Seine Loyalität gilt ausschließlich seinem eigenen zwielichtigen Clan, der weit nördlich seiner Heimat operiert, um tief in das von der Allianz kontrollierte Gebiet einzudringen.",al={"verbindungen von kam tiefenzorn","für wen arbeitet kam tiefenzorn","kam tiefenzorn fraktion"}},["45416a5d"]={q="Warum ist Kam Tiefenzorn berüchtigt?",a="Kam Tiefenzorn erlangte seine düstere Berühmtheit, indem er die katastrophale Explosion anführte, die eine der massiven Steinbrücken über The Thandol Span zertrümmerte. Die gewaltsame Sabotage gefährdete nicht nur eine entscheidende Verbindung zwischen dem Sumpfland und dem Arathihochland, sondern forderte auch das Leben eines Zwergenverwandten von Langzopf der Grimmigen.",al={"ruf von kam tiefenzorn","warum wird kam tiefenzorn gefürchtet","was hat kam tiefenzorn getan"}}},fp="12,301,24.459.0,25.447.0,17.404.1,20.226.0,58.266.0,47.242.0,28.238.0,40.154.0,52.125.0"}
P.entries["npc:kanati-greycloud"] = {n="Kanati Grauwolke",s="Kanati Grauwolke ist ein Taurenjäger, der am Weißgipfelposten in Tausend Nadeln stationiert ist. Zusammen mit seinen Jagdgefährten leistet er den bestmöglichen Widerstand gegen die ständigen Feindseligkeiten der einheimischen Zentauren der Galak.",h="Kanati Grauwolke ist ein Taurenjäger, der am Weißgipfelposten in Tausend Nadeln stationiert ist.",kw={"attentatsplan","zentauren","galak","greycloud","kanati","tausend nadeln","weißgipfelposten"},ang={["faction:Horde"]="Der Weißgipfelposten dient als entscheidender Aussichtspunkt über die Canyons; Kanati am Leben zu halten sichert den Spähern der Horde den Überblick über die Truppenbewegungen der Zentauren.",["race:Tauren"]="Für Tauren, die Tausend Nadeln durchqueren, ist die Unterstützung von Kanati am Weißgipfelposten ein wichtiger Dienst zur Verteidigung ihrer Stammesbrüder gegen ihre uralten, erbitterten Feinde, die Zentauren."},sec={{t="Ein gefährlicher Hochsitz",b="Kanati Grauwolke hat sein Lager am Weißgipfelposten aufgeschlagen, hoch oben auf den Sandsteinnadeln im Westen von Tausend Nadeln. Obwohl der Canyon reichlich Wild und weite Ausblicke bietet, ist er von den Galakzentauren eingekesselt, deren Kriegstrupps um jeden Zentimeter der kargen Ebenen kämpfen. Zusammen mit anderen Taurenjägern wacht Kanati über den Grund des Canyons und versucht, den Posten vor den brutalen Überfällen der umliegenden Marodeure zu schützen."},{t="Hinterhalt der Zentauren",b="Die Zentauren der Galak wollen den Weißgipfelposten nicht bloß isolieren; sie planen, seine Verteidiger vollständig zu vernichten. Boten, die zwischen den Lagern der Zentauren verkehren, überbringen ausdrückliche Befehle, die auf die Ermordung von Kanati und seinen Gefährten abzielen. Es liegt an durchreisenden Abenteurern, diese Marschbefehle abzufangen und Kanati Seite an Seite beizustehen, wenn die Überfallkommandos der Galak über die Hochebene herfallen, um die Jäger des Außenpostens niederzustrecken."}},faq={{q="Wer ist Kanati Grauwolke?",a="Kanati Grauwolke ist ein Taurenjäger, der am Weißgipfelposten im Westen von Tausend Nadeln stationiert ist, wo er ein Lager unterhält und sich gegen die Bedrohungen der Umgebung verteidigt.",al={"wer ist kanati","kanati grauwolke lore","weißgipfelposten tauren"}},{q="Wo finde ich Kanati Grauwolke?",a="Kanati befindet sich am Weißgipfelposten, einem hochgelegenen Taurenlager an den nördlichen Klippen im westlichen Teil von Tausend Nadeln.",al={"kanati aufenthaltsort","wo ist kanati","wo ist greycloud"}},{q="Warum versuchen die Galakzentauren, ihn zu töten?",a="Die Galakzentauren streben nach der völligen Vorherrschaft über die Canyons von Tausend Nadeln und greifen gezielt Außenposten der Horde an. Abgefangene Befehle enthüllen ein koordiniertes Komplott der Zentauren, um Kanati zu ermorden und die Verteidigung des Postens zu brechen.",al={"warum zentauren kanati angreifen","galak attentatsplan","kanati beschützen grund"}},{q="Ist Kanati mit anderen Greyclouds verwandt?",a="Er teilt seinen Nachnamen mit Tor Greycloud und Kar Greycloud, zwei Tauren, die an anderen Orten in der Wildnis von Kalimdor anzutreffen sind, auch wenn das genaue Verwandtschaftsverhältnis zwischen ihnen nicht näher beschrieben wird.",al={"familie greycloud","tor greycloud verwandter","kar greycloud"}}},fx={["35c73e38"]={q="Auf wessen Seite steht Kanati Grauwolke?",a="Kanati Grauwolke ist ein Tauren-Jäger, der der Horde loyal gegenübersteht. Er heißt Reisende der Horde willkommen, die Weißgipfelposten besuchen, und verlässt sich darauf, dass sie ihm helfen, sein Lager vor feindlichen Bedrohungen in der Schlucht zu verteidigen.",al={"kanati fraktion","ist kanati horde","kanati allianz oder horde"}},cf857b32={q="Was will Kanati Grauwolke?",a="Kanati möchte einfach nur sein Jagdlager in Frieden aufrechterhalten und sicherstellen, dass seine Gefährten überleben. Da die örtlichen Galak-Zentauren darauf aus sind, alle Eindringlinge zu vertreiben oder abzuschlachten, ist seine Hauptsorge die Verteidigung gegen ihre Attentatsversuche.",al={"was braucht kanati","kanati grauwolke ziele","warum kanati helfen"}},["10a1bee5"]={q="Warum ist Kanati Grauwolke hier?",a="Kanati errichtete zusammen mit seinen Gefährten ein Jagdlager bei Weißgipfelposten, um in Tausend Nadeln auf die Jagd zu gehen. Leider brachte ihn der Aufbau des Lagers in der Schlucht genau in das Gebiet, das von den feindseligen Galak-Zentauren umkämpft wird.",al={"warum ist kanati bei weißgipfelposten","was macht kanati hier","zweck von kanati grauwolke"}}},fp="16,218,18.433.0,14.426.1,24.160.0,34.146.0,45.224.0,38.175.0"}
P.entries["npc:kaplak"] = {n="Kaplak",s="Kaplak ist ein Orc-Schurkenlehrer, der in Klingenhügel im zentralen Durotar stationiert ist. Er unterweist junge Orcs und Trolle in den Künsten der Täuschung, der Heimlichkeit und der Klingenführung, um sie auf ihren Dienst für die Horde vorzubereiten, bevor er sie nach Orgrimmar weiterschickt.",h="Kaplak ist ein Orc-Schurkenlehrer, der in Klingenhügel im zentralen Durotar stationiert ist.",kw={"durotar","kaplak","orc","orgrimmar","klingenhügel","schurkenlehrer","verstohlenheit","therzok"},ang={["class:Rogue"]="Für junge Orc- und Trollschurken, die das Tal der Prüfungen verlassen, bietet Kaplak eine frühe fachliche Ausbildung und führt sie an die verdeckten Netzwerke heran, die in Orgrimmar operieren.",["faction:Horde"]="Kaplak sorgt im Verborgenen dafür, dass die Horde über fähige Späher, Spione und Attentäter verfügt, die Durotar schützen und jenseits der regulären Frontlinien agieren können."},sec={{t="Ein Mentor in den Schatten",b="Verborgen in der Siedlung Klingenhügel dient Kaplak als grundlegender Ausbilder für angehende Schurken der Horde, die aus dem Tal der Prüfungen kommen. Wo die traditionelle Kultur der Orcs den offenen Kampf und brüllende Sturmangriffe verherrlicht, lehrt Kaplak die kühleren, leiseren Disziplinen, die fürs Überleben notwendig sind: ungesehenes Schleichen, das Knacken von Schlössern und tödliche Schläge aus dem Hinterhalt. Sobald seine Schüler seiner Unterweisung in den staubigen roten Schluchten von Durotar entwachsen sind, schickt er sie nach Norden in die Hauptstadt Orgrimmar, um ihr Handwerk bei erfahrenen Agenten der Gilde zu vertiefen."}},faq={{q="Wer ist Kaplak?",a="Kaplak ist ein Orc-Schurkenlehrer, der in Klingenhügel in Durotar stationiert ist. Er bildet unerfahrene Orc- und Trollschurken aus, die das Tal der Prüfungen verlassen haben, bringt ihnen frühe Schurkenfähigkeiten bei und verweist sie an höherrangige Lehrer in Orgrimmar weiter.",al={"wer ist kaplak","kaplak lore","kaplak klingenhügel"}},{q="Wo ist Kaplak zu finden?",a="Kaplak befindet sich in Klingenhügel, der zentralen Siedlung von Durotar, wo er sich für gewöhnlich in oder nahe der örtlichen Kaserne an der Seite anderer Klassenlehrer aufhält.",al={"wo ist kaplak","kaplak aufenthaltsort","kaplak finden"}},{q="Welche Quests bietet Kaplak an?",a="Kaplak unterstützt Schurkenabenteurer bei ihren Fortschritten und weist ihnen den Weg zu fortgeschrittenen Ausbildern sowie Aufgaben, wie etwa dem Auftrag, Therzok in Orgrimmar aufzusuchen.",al={"kaplak quests","quests von kaplak"}}},fx={c5a92913={q="Auf wessen Seite steht Kaplak?",a="Kaplak ist loyal zur Horde und dient den Orcs von Durotar. In Klingenhügel stationiert, leitet er die jungen Stalker und Späher von Thralls Reich an und schult ihre Fähigkeiten, damit sie orcisches Land vor Zentaurenüberfällen, Infiltratoren aus Kul Tiras und anderen Bedrohungen für die wachsende Nation verteidigen können.",al={"kaplak fraktion","kaplak allianz oder horde","wem dient kaplak"}},d6e62700={q="Warum ist Kaplak in Klingenhügel?",a="Kaplak ist in Klingenhügel stationiert, um junge Orcs und Trolle auszubilden, die die subtilen Künste der Heimlichkeit, des Vergiftens und des Hinterhalts praktizieren. Wenn Rekruten aus dem Tal der Prüfungen aufbrechen, schärft er ihre Schurkenfertigkeiten, bevor er fähige Späher in die Hauptstadt Orgrimmar weiterleitet.",al={"warum ist kaplak hier","zweck von kaplak in durotar","was macht kaplak in klingenhügel"}},["044206c1"]={q="Was will Kaplak?",a="Kaplak möchte die Reihen der Schurken der Horde stärken. Er sucht bei den neu angekommenen Rekruten nach List, Disziplin und schnellen Klingen und weist vielversprechende Späher an erfahrenere Mentoren wie Therzok in Orgrimmar weiter, sobald ihre grundlegende Ausbildung abgeschlossen ist.",al={"kaplak motive","kaplak ziele","was braucht kaplak"}}},fp="6,241,23.544.0,14.236.0,26.156.0,30.161.0"}
P.entries["npc:karang-amakkar"] = {n="Karang Amakkar",s="Karang Amakkar ist ein Orc-Späher, der am Außenposten von Zoram'gar entlang der felsigen Küste des Eschentals stationiert ist. Er operiert am Rande des Gebiets der Horde und konzentriert sich darauf, die gewalttätigen Furbolgstämme einzudämmen, die die Nachschubwege und Grenzen des Außenpostens bedrohen. Abenteurer, die durch den Außenposten reisen, verlassen sich auf seine örtlichen Informationen, um die gefährlichen Spannungen des Waldes zu meistern.",h="Karang Amakkar ist ein Orc-Späher, der am Außenposten von Zoram'gar entlang der felsigen Küste des Eschentals...",kw={"eschental","foulweald","furbolg","karang amakkar","der zoramstrand","außenposten von zoram'gar"},ang={["faction:Horde"]="Karang Amakkar leistet Reisenden der Horde, die sich in die westlichen Gebiete des Eschentals wagen, lebenswichtige Hilfe und bietet Arbeit an, um die feindseligen Kreaturen rund um den Außenposten von Zoram'gar zurückzudrängen.",["race:Orc"]="An einem abgelegenen Außenposten weit weg von Durotar stationiert, verkörpert Karang die entschlossene Härte von Orc-Wachen, die gefährliche Grenzgebiete halten."},sec={{t="An der Küste des Eschentals",b="Am Außenposten von Zoram'gar am The Zoram Strand gelegen, dient Karang Amakkar der Horde an einem ihrer verwundbarsten Grenzaußenposten. Das Lager ist ständigem Druck von der See, den Nachtelfen und wilden Bestien im Landesinneren ausgesetzt. Karang behält die feindseligen einheimischen Populationen, die die Straße nach Osten umgeben, genau im Auge, um sicherzustellen, dass Kuriere und Spähtrupps der Horde nicht von territorialen indigenen Stämmen aus dem Hinterhalt angegriffen werden."},{t="Umgang mit den Furbolgs",b="Karang konzentriert einen Großteil seiner Aufmerksamkeit auf die Furbolg-Populationen, die in den uralten Wäldern beheimatet sind, insbesondere auf den Stamm der Foulweald. Da Verderbnis und ursprüngliche Feindseligkeit diese Bärenmenschen in Raserei versetzen, beauftragt Karang fähige Krieger damit, ihren Anführer auszuschalten und ihre Höhlen zu säubern, bevor die Stämme organisierte Angriffe gegen Zoram'gar starten können."}},faq={{q="Wer ist Karang Amakkar?",a="Karang Amakkar ist ein Orc-Questgeber, der am Außenposten von Zoram'gar an der Küste des Eschentals stationiert ist. Er arbeitet im Auftrag der Horde, um regionale Bedrohungen zu bewältigen, insbesondere feindselige Furbolgclans.",al={"karang","wer ist karang","karang amakkar lore"}},{q="Wo finde ich Karang Amakkar?",a="Er befindet sich am Außenposten von Zoram'gar, an der nordwestlichen Küste des Eschentals entlang des The Zoram Strand.",al={"karang standort","wo ist karang amakkar","karang amakkar fundort"}},{q="Welche Aufgaben bietet Karang Amakkar an?",a="Karang beauftragt Abenteurer der Horde damit, sich den aggressiven Furbolgstämmen in der Nähe entgegenzustellen, und leitet einen Angriff gegen den King of the Foulweald.",al={"karang quests","karang aufgaben","was will karang"}},{q="Warum ist Karang wegen der Furbolgs besorgt?",a="Die Furbolgs im Eschental sind zunehmend wilder und verdorbener geworden. Sie greifen Reisende an und drohen, den Außenposten von Zoram'gar vom Rest der Festungen der Horde in der Region abzuschneiden.",al={"warum furbolgs töten","furbolg bedrohung eschental","foulweald bedrohung"}},{q="Ist Karang Amakkar mit Initiate Amakkar verwandt?",a="Obwohl sie einen Clannamen oder Familiennamen teilen, bleibt eine genaue familiäre Beziehung zwischen Karang und Initiate Amakkar unbestätigt.",al={"amakkar familie","initiate amakkar verwandtschaft","karang familie"}},{q="Kämpft Karang direkt gegen die Nachtelfen?",a="Karangs Pflichten in Zoram'gar konzentrieren sich in erster Linie auf die territoriale Verteidigung und den Umgang mit wilden Bedrohungen wie den Foulweald-Furbolgs, während er offenere militärische Manöver gegen die Nachtelfen anderen Befehlshabern der Horde überlässt.",al={"karang vs nachtelfen","karang allianz"}}},fx={b0298d21={q="Auf wessen Seite steht Karang Amakkar?",a="Karang Amakkar ist loyal zur Horde und dient ihren Interessen direkt in den dichten Wäldern von Eschental. Er operiert zusammen mit anderen Orcs vom Außenposten von Zoram'gar an der Küste aus und konzentriert seine Bemühungen darauf, Außenposten der Horde zu schützen und regionale Bedrohungen wie feindselige Furbolgs zu unterwerfen.",al={"karang amakkar fraktion","ist karang horde","karang loyalität"}},["481f1d87"]={q="Was will Karang Amakkar?",a="Karang möchte die gefährlichen einheimischen Stämme von Eschental niederschlagen, die den Stützpunkt der Horde bedrohen. Er sucht aktiv nach fähigen Abenteurern, um aggressive Furbolgstämme, insbesondere den Stamm der Rostpfoten und ihren König, zu bekämpfen, bevor sie nahegelegene Lager überrennen können.",al={"karang amakkar ziel","was will karang","karang motiv"}},["7b1509e6"]={q="Warum ist Karang Amakkar hier in Eschental?",a="Karang ist in Eschental stationiert, um die Expansion und Verteidigung der Horde in einem äußerst feindseligen Gebiet zu unterstützen. Vom Außenposten von Zoram'gar aus überwacht er die Wildnis und leitet Krieger dazu an, feindselige Bestienstämme zu neutralisieren, die die Präsenz der Horde entlang der Zoram-Strand bedrohen.",al={"warum ist karang hier","zweck von karang amakkar im eschental","warum ist karang in zoram'gar"}}},fp="14,367,25.418.0,25.342.0,22.190.0,32.102.0,37.135.0,41.190.0,46.136.0,43.210.0"}
P.entries["npc:kargal-battlescar"] = {n="Kargal Schlachtnarbe",s="Kargal Schlachtnarbe ist ein erfahrener Orc-Krieger, der an der Fernwacht an der östlichen Grenze des Brachlands stationiert ist. Mit der Bewachung des Übergangs von Durotar betraut, mustert er eintreffende Rekruten und schickt fähige Kämpfer tiefer in das Territorium, um die Verteidigung der Horde zu verstärken.",h="Kargal Schlachtnarbe ist ein erfahrener Orc-Krieger, der an der Fernwacht an der östlichen Grenze des...",kw={"brachland","battlescar","rekrut","das wegekreuz","durotar","fernwacht","kargal"},ang={["class:Warrior"]="Als kampferprobter Veteran, der die Narben unzähliger Gefechte trägt, verkörpert Kargal die unverwüstliche Widerstandskraft, die von den Frontkämpfern der Horde in ungezähmten Grenzlanden erwartet wird.",["faction:Horde"]="Für frische Horde-Abenteurer, die Durotar verlassen, dient Kargal Schlachtnarbe als Einführung in die größeren militärischen Konflikte von Kalimdor, indem er Rekruten für die im Brachland schwelenden Auseinandersetzungen aufstellt."},sec={{t="Wächter der Grenze",b="Kargal Schlachtnarbe hält an der Fernwacht Wache und überblickt den strategischen Übergang, der die rauen roten Ebenen von Durotar von der weiten Savanne des Brachlands trennt. Wenn Reisende und frischgebackene Abenteurer die Brücke über den Südstrom überqueren, sorgt Kargal dafür, dass sie begreifen, dass die friedlichen Tage des Trainings im Tal der Prüfungen vorbei sind. Das Brachland ist ein umkämpftes und gefährliches Gebiet, heimgesucht von aggressiver Tierwelt, Raubzügen der Zentauren und Stämmen der Borstennacken. Kargal mustert die Vorbeiziehenden, zieht willige Rekruten für den Dienst der Horde ein und schickt sie weiter zum Wegekreuz, um den örtlichen Befehlshabern bei der Sicherung der Grenze beizustehen."}},faq={{q="Wer ist Kargal Schlachtnarbe?",a="Kargal Schlachtnarbe ist ein Orc-Krieger und Außenposten-Kommandant, der an der Fernwacht stationiert ist, gelegen an der östlichen Straße, die von Durotar ins Brachland führt.",al={"kargal schlachtnarbe","kargal","wer ist kargal"}},{q="Was ist der Zweck der Fernwacht?",a="Die Fernwacht dient als Frühwarnstation und vorderste Verteidigungslinie für das Brachland gegen Bedrohungen, die nahe der Grenze zu Durotar und entlang des Südstroms auftreten.",al={"zweck farwatch-posten","warum farwatch-posten","was ist dieser aussenposten"}},{q="Wohin schickt Kargal neue Rekruten?",a="Kargal rekrutiert Reisende, die den Außenposten passieren, und schickt sie westwärts entlang der Hauptstraße zum Wegekreuz, dem zentralen militärischen Knotenpunkt des Brachlands.",al={"kargal questziel","wohin nach kargal","wohin schickt kargal euch"}}},fx={["81d05e56"]={q="Auf wessen Seite steht Kargal Schlachtnarbe?",a="Kargal Schlachtnarbe steht fest auf der Seite der Horde. Er bewacht die östliche Grenze des Brachlands, wo Durotar auf die offenen Ebenen trifft, und stellt sicher, dass ankommende Rekruten und Reisende sicher unter dem Banner des Kriegshäuptlings die Grenze passieren.",al={"kargal schlachtnarbe fraktion","ist kargal horde"}},ffbc81ca={q="Was will Kargal Schlachtnarbe?",a="Kargal möchte, dass fähige Krieger die Grenze sichern und die wachsende Siedlung am Das Wegekreuz unterstützen. Er leitet frische Wehrpflichtige, die aus Durotar ankommen, an, um die Verteidigung des Brachlands gegen die Bedrohungen entlang der Ebenen zu verstärken.",al={"kargal schlachtnarbe ziel","was will kargal"}},e589e5e9={q="Warum ist Kargal Schlachtnarbe hier stationiert?",a="Kargal beaufsichtigt die Fernwacht, den befestigten Eingang, der Durotar und das Brachland über den Der Südstrom verbindet. Er ist hier stationiert, um neue Wehrpflichtige zu empfangen, die nach Westen reisen, und sie dorthin zu leiten, wo die Horde sie am dringendsten benötigt.",al={"warum ist kargal bei der fernwacht","kargal schlachtnarbe standortzweck"}}},fp="17,276,22.656.0,25.157.0,42.171.0,36.161.0"}
P.entries["npc:karos-razok"] = {n="Karos Razok",s="Karos Razok ist der Fledermausführer der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er beaufsichtigt den Nistplatz der untoten Flieger, die diesen umkämpften Grenzaußenposten direkt mit Unterstadt und anderen Festungen der Horde verbinden.",h="Karos Razok ist der Fledermausführer der Verlassenen, der im Grabmal im Silberwald stationiert ist.",kw={"fledermausführer","flugmeister","karos razok","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Für Reisende der Horde, die nach Süden in Richtung des Vorgebirges des Hügellands vorstoßen, ist Razoks Fledermausnistplatz ein unverzichtbarer Wegpunkt am westlichen Rand von Lordaeron.",["race:Undead"]="Karos Razok stellt Eure Lebensader zurück nach Unterstadt dar und stellt sicher, dass die Einsätze an der Front im Silberwald fest an Fürstin Sylvanas' Hauptstadt angebunden bleiben."},sec={{t="Hüter der Schwingen des Grabmals",b="Auf der Holzplattform über den Grüften des Grabmals versorgt Karos Razok die skelettartigen Fledermäuse, die für die Kommunikation der Verlassenen unerlässlich sind. Da der Silberwald von Worgen der Mondrast, abtrünnigen Magiern aus Dalaran und den menschlichen Überresten von Mühlenbern heimgesucht wird, ist das Reisen über Land entlang der nördlichen Straße tückisch. Razok stellt sicher, dass Boten, frische Rekruten und lebenswichtige Vorräte das verfluchte Blätterdach überfliegen können, wodurch die Frontlinie direkt mit der Hauptstadt in Tirisfal verbunden bleibt."}},faq={{q="Wer ist Karos Razok?",a="Karos Razok ist der Flugmeister der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er betreut den Nistplatz ausgebildeter vampirischer Fledermäuse, die von Abenteurern und Boten der Horde für Reisen durch Lordaeron genutzt werden.",al={"karos razok rolle","wer ist der flugmeister im grabmal","fledermausführer grabmal"}},{q="Wohin kann Karos Razok Reisende schicken?",a="Razok verbindet Das Grabmal direkt mit Unterstadt in Tirisfal sowie mit Tarrens Mühle im Vorgebirge des Hügellands und ermöglicht so eine schnelle Durchquerung des nördlichen Lordaeron.",al={"flugrouten grabmal","wohin fliegt die fledermaus vom grabmal","flugwege vom grabmal"}},{q="Welche Kreaturen betreut Karos?",a="Er kümmert sich um große, skelettartige Flugfledermäuse. Diese untoten Bestien sind zähe, unermüdliche Flieger, die an die verseuchten Himmel von Lordaeron angepasst sind und von den Verlassenen wegen ihrer Stille und Ausdauer geschätzt werden.",al={"welche reittiere hat razok","flugtiere der verlassenen","was sind die flugtiere am grabmal"}},{q="Warum ist ein Flugmeister im Grabmal wichtig?",a="Die Straßen des Silberwalds sind von feindlichen Kräften verstopft, vom Worgenfluch von Pyrewood bis hin zu menschlichen Zauberern in Mühlenbern. Razok stellt eine Rettungsleine aus der Luft dar, die es den Verlassenen ermöglicht, diesen Vorposten zu versorgen, ohne auf der Hauptstraße Hinterhalten zum Opfer zu fallen.",al={"warum fledermausmeister am grabmal gebraucht wird","reisebedeutung grabmal"}}},fx={db08745b={q="Auf wessen Seite steht Karos Razok?",a="Karos Razok dient den Verlassenen und der Horde. Er ist im Silberwald stationiert und schwört seine Treue Fürstin Sylvanas Windläufer und der Unterstadt, wobei er Kuriere, Späher und Abenteurer der Verlassenen unterstützt, die durch die Region reisen.",al={"karos razok fraktion","wem dient karos razok","karos razok horde"}},["6a9fc34a"]={q="Was will Karos Razok?",a="Karos möchte einfach nur die Flugrouten offen halten und den Lufttransport für die Verlassenen reibungslos gestalten. Die Verwaltung des Flugpunkts am Das Grabmal stellt sicher, dass Vorräte, Nachrichten und Verstärkungen zuverlässig zwischen dem Silberwald und anderen Bastionen der Horde fließen können.",al={"karos razok ziel","was macht karos razok","karos razok motive"}}},fp="11,227,31.485.0,19.205.0,37.171.0,33.190.0,50.245.0"}
P.entries["npc:katie-hunter"] = {n="Katie Hunter",s="Katie Hunter ist eine Pferdezüchterin, die in den Stallungen im Holzfällerlager des Osttals im östlichen Wald von Elwynn stationiert ist. Sie stellt Bürgern von Sturmwind und vertrauenswürdigen Streitern der Allianz ausgebildete Reitpferde und Rösser zur Verfügung. An der Seite von Randal Weidmann sorgt sie dafür, dass Reisende und Soldaten über verlässliche Reittiere verfügen, um die Straßen des Königreichs zu bereisen.",h="Katie Hunter ist eine Pferdezüchterin, die in den Stallungen im Holzfällerlager des Osttals im östlichen Wald...",kw={"osttal","wald von elwynn","pferdehändlerin","katie hunter","holzfällerlager","reittiere","stallungen","sturmwind"},ang={["faction:Alliance"]="Verbündete Völker, die sich hohes Ansehen und Respekt am Hof von Sturmwind verdienen, können das Privileg erlangen, Katies geschätzte Rösser in die Schlacht zu reiten.",["race:Human"]="Für menschliche Reisende stellen Katies Stallungen einen ganz natürlichen Übergangsritus dar, da sie klassische Pferde aus Sturmwind anbieten, sobald Ihr die Grundlagen der Reitkunst gemeistert habt."},sec={{t="Stallungen des Osttals",b="Versteckt in den ruhigen, bewaldeten Lichtungen des Holzfällerlagers des Osttals verwaltet Katie Hunter den primären Pferdebestand des Königreichs für angehende Reiter im Wald von Elwynn. Während die Holzfäller Holz für den Wiederaufbau von Sturmwind schlagen, kümmert sich Katie um die Stallungen und züchtet eine Vielzahl verlässlicher Rassen, darunter Schecken, Stuten und schnelle Rösser. Ihr Bestand verkörpert die klassische Reitertradition des Königreichs und bietet treue Gefährten, die den gefährlichen Straßen im Süden Azeroths trotzen können."}},faq={{q="Wer ist Katie Hunter?",a="Katie Hunter ist die Pferdezüchterin und Reittierhändlerin des Königreichs Sturmwind und befindet sich an den Stallungen des Holzfällerlagers des Osttals im Wald von Elwynn.",al={"katie hunter elwynn","wer ist katie hunter","katie hunter pferdehändlerin"}},{q="Wo finde ich Katie Hunter?",a="Sie befindet sich im nördlichen Teil des Holzfällerlagers des Osttals und kümmert sich im östlichen Wald von Elwynn um die Koppel und die Stallungen in der Nähe des Reitlehrers Randal Weidmann.",al={"katie hunter aufenthaltsort","wo ist katie hunter","katie hunter finden"}},{q="Können Nicht-Menschen Pferde bei ihr kaufen?",a="Ja, allerdings nur, wenn sie einen ehrfürchtigen Ruf beim Königreich Sturmwind erlangt haben. Menschliche Abenteurer können ihre Pferde ohne besonderen Ruf erwerben.",al={"zwerg pferd kaufen","nachtelf pferdereittier","sturmwind ruf reittier"}},{q="Welche Pferde verkauft sie?",a="Katie bietet Standard-Reitpferde an – darunter gescheckte, braune und fuchsfarbene Varianten – sowie schnelle, gepanzerte Rösser wie das Schnelle Palomino, den Schnellen Braunen und das Schnelle weiße Ross.",al={"welche reittiere verkauft katie","katie hunter pferdearten"}}},fx={d7735dfa={q="Auf wessen Seite steht Katie Hunter?",a="Katie Hunter ist eine loyale Untertanin des Königreichs Sturmwind und Mitglied der Allianz. Sie arbeitet vom Holzfällerlager des Osttals aus und versorgt direkt die Bürger Sturmwinds, indem sie verlässliche Reittiere an Reisende und Champions bereitstellt, die ihre Treue gegenüber der Krone bewiesen haben.",al={"katie hunter fraktion","gehört katie hunter zur allianz","wem dient katie hunter"}},d5257f59={q="Was möchte Katie Hunter?",a="Katie Hunter konzentriert sich auf die Pflege und den Verkauf der berühmten Pferde aus dem Osttal. Sie möchte fähige Reittiere an verlässliche Abenteurer liefern und sicherstellen, dass nur vertrauenswürdige Verbündete Sturmwinds ihren geschätzten Bestand erwerben, um ihre Reisen durch das Königreich zu unterstützen.",al={"was möchte katie hunter","zweck von katie hunter","ziel von katie hunter"}},["5cab52df"]={q="Warum ist Katie Hunter hier im Holzfällerlager des Osttals?",a="Katie Hunter hat ihr Zuhause im Holzfällerlager des Osttals im östlichen Wald von Elwynn, um die Ställe des Lagers zu betreiben. In Zusammenarbeit mit Randal Weidmann verwaltet sie die Zucht und Pflege der Reitpferde fernab vom Trubel der Stadt Sturmwind und nutzt dafür die offene Weide des Lagers.",al={"warum ist katie hunter im osttal","warum ist katie hunter hier","was macht katie hunter in elwynn"}},["85933b18"]={q="Mit wem ist Katie Hunter verbunden?",a="Katie Hunter arbeitet eng mit Randal Weidmann zusammen, der ebenfalls die Ställe im Holzfällerlager des Osttals beaufsichtigt. Gemeinsam verwalten sie den Pferdehandel des Lagers und dienen als Hauptquelle für Pferde für die Verbündeten Sturmwinds.",al={"verbindungen von katie hunter","mit wem ist katie hunter verwandt","katie hunter und randal weidmann"}}},fp="12,339,19.503.0,20.150.0,30.159.0,35.158.0,26.191.0"}
P.entries["npc:katrana-prestor"] = {n="Lady Katrana Prestor",s="Lady Katrana Prestor ist eine Adlige aus Sturmwind und eine der einflussreichsten Stimmen bei Hofe. Da König Varian verschollen ist, steht sie dem Knabenkönig Anduin und Hochlord Bolvar Fordragon in Burg Sturmwind als vertraute Beraterin zur Seite.",h="Lady Katrana Prestor ist eine Adlige aus Sturmwind und eine der einflussreichsten Stimmen bei Hofe.",kw={"katrana","prestor","katrana prestor","lady prestor","beraterin","burg sturmwind","hof"},sec={{t="Stimme des Hofes",b="Lady Prestor erschien vor einigen Jahren bei Hofe und stieg rasch zu einer seiner angesehensten Persönlichkeiten auf. Die Adligen von Sturmwind buhlen um ihre Gunst, und ihr Rat prägt viele der Entscheidungen, die im Namen des jungen Königs getroffen werden, während Hochlord Bolvar Fordragon als Regent herrscht. Bittsteller, die nach Burg Sturmwind kommen, um Soldaten oder Hilfe zu erbitten, stellen oft fest, dass ihre Meinung ebenso viel Gewicht hat wie die des Regenten."}},faq={{q="Wer ist Lady Katrana Prestor?",a="Lady Katrana Prestor ist eine Adlige aus Sturmwind und eine vertraute Beraterin bei Hofe. Da König Varian verschollen ist, steht sie dem Knabenkönig Anduin und Hochlord Bolvar Fordragon in Burg Sturmwind zur Seite, und ihre Stimme hat bei den Adligen großes Gewicht.",al={"wer ist katrana prestor","wer ist lady prestor","katrana prestor geschichte"}},{q="Warum berät sie den König?",a="Das Verschwinden von König Varian ließ seinen jungen Sohn Anduin auf dem Thron zurück, während Hochlord Bolvar Fordragon als Regent regiert. Lady Prestor steht ihnen als Beraterin zur Seite. Viele Entscheidungen des Hofes, einschließlich der Frage, wie Sturmwind auf Hilfegesuche aus seinen umliegenden Gebieten reagiert, werden von ihrem Rat beeinflusst.",al={"warum ist prestor bei hofe","was tut katrana"}},{q="Wo kann ich Lady Prestor finden?",a="Sie hält sich üblicherweise im Thronsaal von Burg Sturmwind auf und steht dort in der Nähe von Hochlord Bolvar Fordragon und dem jungen König Anduin.",al={"wo ist katrana prestor","katrana prestor aufenthaltsort"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="Kaymard Kupferzwick",s="Kaymard Kupferzwick ist ein Goblinhändler, der während des Feast of Winter Veil Smokywood Pastures in Orgrimmar vertritt. Im Tal der Stärke preist er festliche Waren an und weist Reisende auf weihnachtliche Freuden sowie fehlende Festtagsgüter hin. Sein reges Geschäft bringt saisonale Fröhlichkeit – und goblinische Handelskunst – in die Hauptstadt der Horde.",h="Kaymard Kupferzwick ist ein Goblinhändler, der während des Feast of Winter Veil Smokywood Pastures in...",kw={"copperpinch","goblin","kaymard","metzen","orgrimmar","smokywood pastures","tal der stärke","winter veil"},ang={["faction:Horde"]="Für die Horde vertritt Kaymard die kommerzielle Seite des Feast of Winter Veil in Orgrimmar, indem er traditionelle Winterfeierlichkeiten mit goblinischem Unternehmergeist verbindet.",["profession:Cooking"]="Kaymard und seine Gefährten von Smokywood Pastures bieten saisonale Rezepte und spezielle Zutaten an, die für das Backen traditioneller Festtagsleckereien unverzichtbar sind."},sec={{t="Das Winterhauchfest eines Goblins",b="Wenn das Feast of Winter Veil beginnt, schlägt Smokywood Pastures seine Zelte direkt im belebten Tal der Stärke in Orgrimmar auf, angeführt vom geschäftstüchtigen Kaymard Kupferzwick. Während Altvater Winter ganz in der Nähe Besucher empfängt, sorgt Kaymard dafür, dass die Jahreszeit gewinnbringend bleibt. Mit dem Verkauf von erlesenen Leckereien, festlichem Geschenkpapier und unverzichtbaren Festtagsartikeln verkörpert er die goblinsche Ansicht, dass kein großes Kulturfest ohne einen lebhaften Münzwechsel vollkommen ist."},{t="Festtagskomplikationen",b="Neben dem Feilbieten festlicher Waren dient Kaymard oft als Ansprechpartner für die saisonalen Missgeschicke, die Smokywood Pastures heimsuchen. Von gestohlenen Lieferungen festlicher Süßwaren bis hin zum rätselhaften Verschwinden von Metzen the Reindeer heuert Kaymard eifrig Abenteurer der Horde an, um den Ärger im Schnee zu beseitigen und für einen reibungslosen Ablauf des Festes zu sorgen."}},faq={{q="Wer ist Kaymard Kupferzwick?",a="Kaymard Kupferzwick ist ein Goblinhändler, der Smokywood Pastures angehört. Während des Feast of Winter Veil agiert er im Tal der Stärke in Orgrimmar, verkauft erstklassige saisonale Waren und vergibt festliche Aufgaben an Vorbeireisende.",al={"wer ist kaymard","kaymard kupferzwick lore","was macht kaymard"}},{q="Was ist Smokywood Pastures?",a="Smokywood Pastures ist ein Händlerkonsortium, das auf ganz Azeroth für Speisen, Leckereien und saisonale Waren des Feast of Winter Veil zuständig ist. Sie versorgen sowohl die Horde als auch die Allianz mit Festtagsartikeln und erwirtschaften dabei einen stattlichen Gewinn.",al={"was ist smokywood pastures","für wen arbeitet er","smokywood pastures lore"}},{q="Wo kann ich Kaymard Kupferzwick finden?",a="Er steht im Tal der Stärke in Orgrimmar, nahe dem zentralen Festtagsbereich platziert, an dem Altvater Winter während des Feast of Winter Veil Hof hält.",al={"kaymard standort","wo ist kaymard kupferzwick","wo ist er in orgrimmar"}},{q="Warum bittet er Abenteurer während der Feiertage um Hilfe?",a="Smokywood Pastures erlebt während des Feast of Winter Veil regelmäßig logistische Katastrophen, darunter gestohlene Festtagssüßigkeiten und die Entführung ihres geschätzten Rentiers Metzen. Kaymard heuert willige Abenteurer an, um ihre Güter zurückzubringen und die Gewinne der Saison zu sichern.",al={"kaymard quests","winter veil leckereien quest","metzen quest horde"}}},fx={["10a0163d"]={q="Auf wessen Seite steht Kaymard Kupferzwick?",a="Kaymard arbeitet ausschließlich für Smokywood Pastures, ein gewerbliches Goblin-Unternehmen. Während er sein Urlaubsgeschäft im Herzen von Orgrimmar einrichtet, um Gönner der Horde zu bedienen und das Fest des Winterhauchs zu versorgen, liegt seine wahre Loyalität beim Unternehmen und dem Streben nach ehrlichem Gewinn, anstatt bei der Politik der Horde.",al={"kaymard kupferzwick fraktion","gehört kaymard zur horde","für wen arbeitet kaymard"}},["699a38fb"]={q="Warum ist Kaymard Kupferzwick hier?",a="Kaymard hat im Tal der Stärke in Orgrimmar ein Geschäft eröffnet, um das Fest des Winterhauchs zu feiern. Smokywood Pastures entsendet in jeder Festtagssaison Händler in die großen Hauptstädte, um Leckereien, Geschenkpapier, Rezepte und saisonale Spezialwaren an feiernde Bürger zu verkaufen.",al={"warum ist kaymard in orgrimmar","was macht kaymard hier","zweck von kaymard in orgrimmar"}}},fp="19,352,22.459.0,21.345.0,27.228.0,27.234.0,37.172.0,57.259.0"}
P.entries["npc:keeper-albagorm"] = {n="Bewahrer Albagorm",s="Bewahrer Albagorm ist ein Hüter des Hains, der in der idyllischen Zuflucht des Steinkrallengipfels stationiert ist. Zutiefst besorgt über die Verwüstung, die die südlichen Ausläufer der Berge verdirbt, wirbt er Reisende an, um bei der Heilung der versengten Wildnis des verbrannten Tals zu helfen.",h="Bewahrer Albagorm ist ein Hüter des Hains, der in der idyllischen Zuflucht des Steinkrallengipfels...",kw={"cenarius","das verbrannte tal","bewahrer albagorm","hüter des hains","steinkralle","der steinkrallengipfel"},ang={["class:Druid"]="Als Hüter des Hains hat Albagorm eine direkte Verbindung zur cenarischen Blutlinie, was seine Bemühungen zur Läuterung des verbrannten Tals für Druiden zu einer zutiefst persönlichen Angelegenheit macht.",["faction:Alliance"]="Albagorm bietet Streitkräften der Allianz, die die Zuflucht der Nachtelfen am Steinkrallengipfel durchqueren, Zuflucht und Führung."},sec={{t="Ein Wächter auf dem Gipfel",b="Inmitten der friedlichen Zweige des Steinkrallengipfels wacht Bewahrer Albagorm über eine der heiligen Zufluchten der Elfen in Kalimdor. Wie viele Söhne von Cenarius spürt er den Schmerz der natürlichen Welt überaus deutlich. Seine Aufmerksamkeit richtet sich nach Süden auf die schwelenden Ruinen des verbrannten Tals, die von einer gierigen mechanisierten Armee von Industriellen in Brand gesteckt wurden und nun von den Harpyien der Bloodfury beherrscht werden, die jedes Nachwachsen verhindern. Von seiner Zuflucht aus arbeitet Albagorm unermüdlich daran, die Ausbreitung des Verfalls aufzuhalten und das Gleichgewicht im verwundeten Wald wiederherzustellen."}},faq={{q="Wer ist Bewahrer Albagorm?",a="Er ist ein Hüter des Hains – einer der halbgöttlichen Nachkommen von Cenarius –, der am Steinkrallengipfel im Steinkrallengebirge stationiert ist. Er dient als Verbündeter der Nachtelfen und natürlichen Beschützer Kalimdors.",al={"bewahrer albagorm","wer ist albagorm","albagorm steinkrallen"}},{q="Wo finde ich Bewahrer Albagorm?",a="Er weilt am Steinkrallengipfel, einer der Allianz wohlgesinnten druidischen Zuflucht, die hoch im nordwestlichen Winkel des Steinkrallengebirges liegt.",al={"bewahrer albagorm aufenthaltsort","wo ist albagorm","albagorm koordinaten"}},{q="Wobei möchte Bewahrer Albagorm Hilfe?",a="Albagorm versucht, die Verwüstung des verbrannten Tals zu heilen. Er schickt fähige Abenteurer in das ascheerstickte Becken, um die verseuchte Landschaft zu läutern und die Harpyien der Bloodfury zu vertreiben, die das natürliche Nachwachsen verhindern.",al={"bewahrer albagorm quests","was will albagorm","die rückeroberung des verbrannten tals"}}},fx={["23205c35"]={q="Auf wessen Seite steht Bewahrer Albagorm?",a="Bewahrer Albagorm ist auf die Seite der Nachtelfen und der Cenarion-Druiden vom Steinkrallengipfel ausgerichtet und bietet Champions der Allianz seinen Rat und seine Führung an. Wie alle Söhne des Cenarius liegt seine tiefere Loyalität beim Gleichgewicht der Natur; er sucht nach Verbündeten, die bereit sind, bei der Heilung der vernarbten Landschaften Kalimdors zu helfen.",al={"bewahrer albagorm fraktion","albagorm allianz oder horde","ist albagorm freundlich"}},["28024e4a"]={q="Warum ist Bewahrer Albagorm hier am Steinkrallengipfel?",a="Bewahrer Albagorm wacht über das Heiligtum des Steinkrallengipfels, eine lebenswichtige Bastion der Natur, die hoch oben in den Bergen liegt. Von diesem Zufluchtsort aus beobachtet er die Verderbnis und Zerstörung, die sich in der Region ausbreiten, und weist vertrauenswürdige Reisende an, die Plage zurückzudrängen und die Verwüstung zu beheben, die das nahegelegene verbrannte Tal bedroht.",al={"warum ist albagorm am steinkrallengipfel","zweck von albagorm am steinkrallengipfel","rolle von bewahrer albagorm"}},["7aa8d5e1"]={q="Mit wem ist Bewahrer Albagorm verbunden?",a="Als Bewahrer des Hains ist Albagorm einer der verehrten Söhne des Cenarius, was ihn durch eine heilige Blutlinie direkt mit dem Halbgott des Mondes und der natürlichen Ordnung verbindet. Im Steinkrallengebirge steht er eng an der Seite der dortigen Nachtelfen-Schildwachen und Cenarion-Beschützer, die auf dem Gipfel des Berges stationiert sind.",al={"verbindungen von bewahrer albagorm","albagorm kontakte","wem untersteht albagorm"}}},fp="15,260,22.526.0,23.205.0,33.134.0,41.213.0"}
P.entries["npc:keeper-bel-dugur"] = {n="Bewahrer Bel'dugur",s="Bewahrer Bel'dugur ist ein gelehrter Verlassener, der tief im Apothekarium von Unterstadt residiert. Er dient seinem Volk, indem er Expeditionen zur Bergung dunkler Wälzer und magischer Artefakte aus ganz Azeroth in Auftrag gibt.",h="Bewahrer Bel'dugur ist ein gelehrter Verlassener, der tief im Apothekarium von Unterstadt residiert.",kw={"das apothekarium","bel'dugur","bewahrer beldugur","shadowfang","das buch von ur","unterstadt"},ang={["class:Warlock"]="Hexenmeister kreuzen häufig die Wege von Bel'dugurs Anfragen, da seine Interessen stark mit gefährlichen Grimoires, extraplanarer Beschwörung und dunklem Okkultismus übereinstimmen.",["race:Undead"]="Bel'dugur wirkt wie jeder andere gelehrte Verlassene, der nach verbotenem Wissen strebt, um Euer Königreich zu stärken, doch seine wahren Ambitionen liegen außerhalb der Überlebenspläne der Bansheekönigin."},sec={{t="Ein Sammler dunkler Relikte",b="Inmitten der Bottiche und Forscher des Apothekariums beauftragt Bewahrer Bel'dugur Abenteurer damit, gefährliche arkane und okkulte Relikte aus ganz Azeroth zu beschaffen. Zu seinen bedeutendsten Interessen gehört Das Buch von Ur, eine legendäre Abhandlung über extradimensionale Wesen, die in Burg Shadowfang weggeschlossen liegt. Während viele in Unterstadt nach magischem Wissen suchen, um den Zustand der Untoten zu heilen oder als Waffe einzusetzen, scheinen Bel'dugurs gezielte Beschaffungen darauf ausgerichtet zu sein, uralte, verbotene Mächte freizulegen."},{t="Verborgene Loyalitäten",b="Hinter seinem ruhigen Auftreten als Forscher von Unterstadt verbirgt sich eine geheime Loyalität zum apokalyptischen Kult des Schattenhammers. Die Quests und Forschungsaufgaben, die Bel'dugur vergibt, treiben im Stillen die esoterischen Pläne des Kults voran, indem grundlegende Grimoires der Beschwörungs- und Leerenmagie direkt vor den ahnungslosen Augen der Königlichen Apothekervereinigung und Fürstin Sylvanas beschafft werden."}},faq={{q="Wo kann ich Bewahrer Bel'dugur finden?",a="Bewahrer Bel'dugur befindet sich im Apothekarium, dem alchemistischen Viertel im südlichen unteren Ring von Unterstadt.",al={"bewahrer bel'dugur aufenthaltsort","wo ist beldugur","beldugur karte"}},{q="Warum will Bel'dugur Das Buch von Ur?",a="Das Buch von Ur enthält die grundlegenden Forschungen des Dalaran-Magiers Ur über andere Dimensionen und die wilden Worgen. Bel'dugur versucht, diese verbotenen Beschwörungsprinzipien für die finsteren Pläne seiner wahren Meister zu nutzen.",al={"warum buch von ur","was macht beldugur mit dem buch von ur"}},{q="Ist Bewahrer Bel'dugur Fürstin Sylvanas treu ergeben?",a="Nach außen hin fungiert er als Archivar und Forscher für die Verlassenen, doch subtile Hinweise in seinen Untersuchungen deuten darauf hin, dass seine Loyalität woanders liegen könnte.",al={"ist beldugur böse","beldugur fraktion","wem dient beldugur"}},{q="Welche anderen Aufgaben gibt er Abenteurern?",a="Über das Buch von Ur aus Burg Shadowfang hinaus leitet Bel'dugur Reisende zu vergessener Kunde und verbotenen Wälzern, einschließlich dunkler Abhandlungen, die mit uralten Ritualen und verbotenem Wissen verknüpft sind.",al={"beldugur quests","bewahrer beldugur quests"}}},fx={f8b2616f={q="Wer ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur ist ein Gelehrter der Verlassenen, der im Apothekarium innerhalb der Unterstadt stationiert ist. Während er sich als stiller Archivar präsentiert, der obskure Folianten und vergessenes Wissen für die Königliche Apothekergesellschaft sammelt, verfolgt er gefährliches esoterisches Wissen, das weit über das gewöhnliche Handwerk der Apotheker hinausgeht.",al={"wer ist bel'dugur","hintergrund von bewahrer beldugur","wer ist bewahrer beldugur"}},["3453eee6"]={q="Was möchte Bewahrer Bel'dugur?",a="Bel'dugur sucht nach verbotenen arkanen Texten, okkulten Geheimnissen und Relikten dunkler Macht. Er beauftragt Abenteurer mit der Bergung gefährlicher Folianten wie dem Buch von Ur aus Burg Shadowfang und anderen versteckten Sammelbänden, um gefährliche antike Magie freizuschalten.",al={"was möchte beldugur","motive von bewahrer beldugur","ziel von beldugur"}},["43763d0f"]={q="Warum ist Bewahrer Bel'dugur in der Unterstadt?",a="Bel'dugur wohnt im Apothekarium der Unterstadt, einem idealen Zufluchtsort für diejenigen, die dunkle Studien abseits neugieriger Blicke verfolgen. Von der Sicherheit der Hauptstadt der Verlassenen aus weist er Wanderer zu gefährlichen Ecken der Welt, um verlorene Schriften für seine Sammlung zu bergen.",al={"warum ist bel'dugur in der unterstadt","warum ist bewahrer beldugur hier","standort von beldugur"}},["5a26a87f"]={q="Mit wem ist Bewahrer Bel'dugur verbunden?",a="Unter seiner Rolle bei den Verlassenen im Apothekarium deuten subtile Hinweise und Dialoge zu seiner verbotenen Forschung auf Verbindungen zum geheimnisvollen Kult des Schattenhammers hin, der nach weltverändernder Macht und apokalyptischem Wissen giert.",al={"verbindungen von bewahrer bel'dugur","für wen arbeitet beldugur","beldugur und der kult des schattenhammers"}}},fp="16,211,26.501.0,16.349.2,34.129.0,39.227.1,43.155.2,42.181.0"}
P.entries["npc:keeper-bel-varil"] = {n="Bewahrer Bel'varil",s="Bewahrer Bel'varil ist ein Betreuer und Forscher der Verlassenen, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. In enger Zusammenarbeit mit Wordeen Voidglare leitet er Abenteurer der Horde an, magische Relikte und bindende Materialien aus den umliegenden Landen zu beschaffen, um ihre okkulten Studien voranzutreiben.",h="Bewahrer Bel'varil ist ein Betreuer und Forscher der Verlassenen, der in Tarrens Mühle im Vorgebirge des...",kw={"bel'varil","armschienen der bindung","vorgebirge des hügellands","bewahrer bel'varil","steinmarken","tarrens mühle","wordeen voidglare"},ang={["faction:Horde"]="Für Champions der Horde, die im Vorgebirge des Hügellands kämpfen, bietet Bel'varil praktische Belohnungen im Austausch für die Bezwingung elementarer Bedrohungen und die Bergung bindender Amulette.",["race:Undead"]="Bel'varils Arbeit spiegelt das Streben der Verlassenen nach arkaner Meisterschaft und Einfallsreichtum wider, um sich durch die sorgfältige Erforschung regionaler Relikte einen Vorteil in Lordaeron zu sichern."},sec={{t="Studien in Tarrens Mühle",b="Inmitten des belagerten Dorfes Tarrens Mühle unterstützt Bewahrer Bel'varil im Stillen die magische und alchemistische Forschung der Verlassenen. Während königliche Apotheker und Soldaten sich mit der Garnison der Allianz die Straße hinab bei Süderstade beschäftigen, konzentriert sich Bel'varil auf praktische Zauberei und entsendet Reisende, um Steinmarken und bindende Armschienen von nahen elementaren und verzauberten Bedrohungen zu bergen."}},faq={{q="Wer ist Bewahrer Bel'varil?",a="Bewahrer Bel'varil ist ein Gelehrter der Verlassenen, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er unterstützt den Forscherkollegen Wordeen Voidglare bei der Untersuchung magischer Artefakte und Reagenzien, die im umkämpften Gebiet gefunden werden.",al={"bewahrer belvaril","wer ist belvaril","belvaril tarrens mühle"}},{q="Wo kann ich Bewahrer Bel'varil finden?",a="Er befindet sich in der Siedlung der Verlassenen in Tarrens Mühle, gelegen im nördlichen Vorgebirge des Hügellands.",al={"belvaril aufenthaltsort","wo ist bewahrer bel'varil","bewahrer bel'varil finden"}},{q="Welche Aufgaben bietet Bewahrer Bel'varil an?",a="Er heuert Abenteurer der Horde an, um magische Überreste wie Steinmarken und Armschienen der Bindung zu sammeln, was seinem Zirkel dabei hilft, elementare Mächte zu verstehen und zu manipulieren.",al={"belvaril quests","bewahrer bel'varil aufgaben"}}},fx={["07ee922c"]={q="Auf wessen Seite steht Bewahrer Bel'varil?",a="Bewahrer Bel'varil ist loyal gegenüber den Verlassenen und der größeren Horde. Er ist in Tarrens Mühle stationiert und arbeitet an der Seite seiner untoten Brüder, um das Vorgebirge des Hügellands gegen die Aggression der Allianz zu sichern und bei der strategischen Forschung zu helfen, die von seinen Mitstreitern der Verlassenen durchgeführt wird.",al={"bel'varil fraktion","gehört bel'varil zur horde","treue von bel'varil"}},["19ba277e"]={q="Was möchte Bewahrer Bel'varil?",a="Bel'varil sucht nach mystischen Komponenten und Artefakten, um bei der spezialisierten arkanen Forschung zu helfen. Um die Arbeit von Wordeen Voidglare in Tarrens Mühle zu unterstützen, rekrutiert er Reisende, um verzauberte Überreste, wie Stone Tokens und Armschienen der Bindung, von den Elementaren und Ruinen in den umliegenden Regionen zu bergen.",al={"ziel von bel'varil","was benötigt bel'varil","warum bel'varil helfen"}},["4541a85d"]={q="Warum ist Bewahrer Bel'varil hier in Tarrens Mühle?",a="Bewahrer Bel'varil bleibt in Tarrens Mühle stationiert, um die territorialen und arkanen Interessen der Verlassenen im Vorgebirge des Hügellands zu unterstützen. In Zusammenarbeit mit Forschern wie Wordeen Voidglare koordiniert er die Beschaffung magischer Vorräte, die benötigt werden, um ihren Halt gegen nahegelegene Feinde zu stärken.",al={"warum ist bel'varil in tarrens mühle","zweck von bel'varil im hügelland","warum ist bewahrer bel'varil hier"}},b0435467={q="Mit wem ist Bewahrer Bel'varil verbunden?",a="Bewahrer Bel'varil arbeitet eng mit Wordeen Voidglare zusammen, einem weiteren Gelehrten der Verlassenen, der in Tarrens Mühle stationiert ist. Bel'varil fungiert als Assistent und Koordinator, der Abenteurer organisiert, um die spezifischen Materialien und Marken zu sammeln, die Wordeen für seine laufenden Studien benötigt.",al={"verbündete von bel'varil","für wen arbeitet bel'varil","kontakte von bel'varil"}}},fp="16,289,20.386.0,24.217.0,34.109.0,39.164.0"}
P.entries["npc:keldran"] = {n="Keldran",s="Keldran ist ein orcischer Agent, der knapp nördlich des Tal der Geister in Orgrimmar stationiert ist. Er hat es sich zur Aufgabe gemacht, den Weg für eine spätere Diplomatie mit der Allianz zu ebnen, und koordiniert verdeckte Schläge gegen dämonische Überreste, um zu beweisen, dass die moderne Horde der Brennenden Legion wahrhaftig abgeschworen hat.",h="Keldran ist ein orcischer Agent, der knapp nördlich des Tal der Geister in Orgrimmar stationiert ist.",kw={"allianz-beziehungen","burning blade","desolace","keldran","maurin knochenspalter","orgrimmar","takata stahlklinge","tal der geister"},ang={["class:Warlock"]="Keldrans verdeckter Krieg gegen die Burning Blade unterstreicht, wie vehement sich die Führung der Horde von unkontrollierter dämonischer Verderbnis distanzieren möchte.",["faction:Horde"]="Keldran repräsentiert den vorausschauenden Teil der Horde, der die dringende Notwendigkeit erkennt, ihren dämonischen Ruf abzulegen, wenn jemals ein dauerhafter Frieden auf Kalimdor gesichert werden soll."},sec={{t="Ein diplomatischer Kreuzzug",b="Während Thrall vom Valley of Wisdom aus regiert, arbeitet Keldran von den roten Felsterrassen der Stadt aus daran, eine schwelende diplomatische Katastrophe zu lösen. Die Allianz betrachtet alle Orcs noch immer als blutrünstige Marionetten dämonischer Herren – ein Ruf, der sich während der ersten Kriege festigte. Keldran ist überzeugt, dass selbst Thrall des endlosen Konflikts überdrüssig ist, und glaubt, dass echte Friedensverhandlungen niemals stattfinden können, solange dämonenanbetende Kulte in Kalimdor fortbestehen. Ohne formelle Genehmigung des Kriegshäuptlings ergreift er selbst die Initiative und lenkt vertrauenswürdige Agenten gegen ferne Bedrohungen, um den dämonischen Makel ein für alle Mal zu beseitigen."},{t="Der Krieg in Desolace",b="Um sein Anliegen gegenüber der Allianz zu untermauern, nimmt Keldran die düstere Ödnis von Desolace ins Visier. Er entsandte Takata Stahlklinge und Maurin Knochenspalter, um die Operationen gegen die dortigen dämonischen Heimsuchungen anzuführen, wobei er besonderen Wert auf die Vernichtung der Kultisten der Burning Blade legte. Indem er diese dämonischen Praktiker ausmerzt und handfeste Beweise nach Orgrimmar zurückbringt, hofft Keldran unmissverständlich zu demonstrieren, dass die neue Horde ebenso ein Feind der Legion ist wie die Menschen und Nachtelfen."}},faq={{q="Wer ist Keldran?",a="Keldran ist ein Orc nördlich des Tal der Geister in Orgrimmar, der Bestrebungen organisiert, dämonischen Einfluss zu beseitigen und einen Weg zu diplomatischen Allianz-Beziehungen zu ebnen.",al={"wer ist keldran","keldran lore","keldran npc"}},{q="Warum liegen Keldran die Allianz-Beziehungen am Herzen?",a="Keldran glaubt, dass Thrall des ständigen Krieges mit der Allianz müde wird. Er weiß, dass Friedensgespräche unmöglich bleiben werden, solange die Allianz annimmt, die Horde stünde noch immer im Bunde mit der Brennenden Legion.",al={"warum allianz-beziehungen","keldrans motive","warum will er frieden"}},{q="Handelt Keldran auf Thralls offizielle Befehle hin?",a="Nein. Keldran besitzt keine offizielle Autorisierung von Kriegshäuptling Thrall für seine Operation und entscheidet sich dazu, unabhängig zu handeln, um den Namen der Horde reinzuwaschen und das Fundament für zukünftigen Frieden zu legen.",al={"hat thrall keldran geschickt","thralls befehle keldran","ist keldran autorisiert"}},{q="Was tut Keldran in Desolace?",a="Er entsandte Takata Stahlklinge und Maurin Knochenspalter nach Desolace, um die dortigen dämonischen Streitkräfte zu säubern und die Präsenz des Kults der Burning Blade entscheidend auszumerzen.",al={"desolace operation","warum desolace","keldran burning blade"}}},fx={b49902f3={q="Mit wem ist Keldran verbunden?",a="Keldran arbeitet an der Seite loyaler Horde-Agenten, die seine Vision von Frieden teilen. Um seine Strategie gegen Dämonenanbeter in Desolace auszuführen, verlässt er sich auf Takata Stahlklinge und Maurin Knochenspalter und weist sie an, die dämonische Bedrohung zu bekämpfen und die Burning Blade aus der Region zu vertreiben.",al={"keldran verbündete","mit wem arbeitet keldran zusammen","kontakte von keldran"}}},fp="7,277,20.591.0,19.487.1,15.181.0,56.212.0,49.177.0,34.166.0"}
P.entries["npc:kelm-hargunth"] = {n="Kelm Hargunth",s="Kelm Hargunth ist der primäre Nachschuboffizier und Rüstmeister der Vorhut des Kriegshymnenklans und im Mor'shan-Stützpunkt an der nördlichen Grenze des Brachlands stationiert. Er rüstet die Champions der Horde aus, die in den umkämpften Wäldern der Kriegshymnenschlucht gegen die Nachtelfen kämpfen. Durch seine Hilfspakete und Rationen stellt er sicher, dass die Kriegsanstrengungen an der Front stets voll versorgt bleiben.",h="Kelm Hargunth ist der primäre Nachschuboffizier und Rüstmeister der Vorhut des Kriegshymnenklans und im...",kw={"brachland","hilfspaket","kelm hargunth","mor'shan-stützpunkt","pvp-händler","rüstmeister","warsongschlucht","warsongvorhut"},ang={["class:Warrior"]="Frontkrieger verlassen sich in hohem Maße auf Hargunths robuste Plattenbeinlinge, schwere Klingen und Kampfrationen, um die Linie gegen die Allianz zu halten.",["faction:Horde"]="Kelm Hargunth liefert das Rüstzeug des Krieges für jeden Hordensoldaten, der bereit ist, in der Kriegshymnenschlucht die Waffen gegen die Nachtelfen zu erheben.",["race:Orc"]="Für die Orcs stellt Hargunth sicher, dass Grom Hellscreams Vermächtnis in Eschental fortbesteht, indem er den Kriegshymnenklan bewaffnet und ernährt hält."},sec={{t="Rüstmeister von Mor'shan",b="Auf den irdenen Wällen mit Blick auf Eschental überwacht Kelm Hargunth die logistischen Operationen der Vorhut des Kriegshymnenklans im Mor'shan-Stützpunkt. Während Späher und Plünderer jenseits der Palisade scharmützeln, leitet Hargunth den Fluss von Waffen, Rüstungen und Rationen, die zur Aufrechterhaltung eines langwierigen Grenzkriegs erforderlich sind. Für ihn hängt der Sieg gegen die Schildwachen der Silberschwingen ebenso sehr von beständigem Nachschub ab wie von roher Kampfwut."},{t="Nachschub für die Front",b="Hargunth verteilt spezialisierten Nachschub an Krieger, die ihren Mut in der Schlucht bewiesen haben. Von maßgeschneiderten Hilfspaketen voller Verbandszeug und eisernen Rationen bis hin zu meisterhaft gefertigter Rüstung mit dem purpurnen Wappen des Kriegshymnenklans: Seine Vorräte sind strikt jenen vorbehalten, die für die territorialen Ambitionen der Horde in den holzreichen Wäldern des Nordens bluten."}},faq={{q="Wer ist Kelm Hargunth?",a="Kelm Hargunth ist ein orkischer Nachschuboffizier, der die Vorhut des Kriegshymnenklans vertritt. Er ist im Mor'shan-Stützpunkt im nördlichen Brachland stationiert und verteilt Waffen, Rüstungen sowie Kampfproviant an die Soldaten der Horde, die in der Kriegshymnenschlucht kämpfen.",al={"kelm hargunth","wer ist kelm","mor'shan händler","warsong händler"}},{q="Wo befindet sich Kelm Hargunth?",a="Er ist im Mor'shan-Stützpunkt stationiert, der am äußersten nördlichen Rand des Brachlands direkt an der Wallgrenze liegt, die nach Eschental führt.",al={"kelm aufenthaltsort","wo ist kelm hargunth","standort nachschuboffizier mor shan"}},{q="Welcher Fraktion dient Kelm Hargunth?",a="Er dient der Vorhut des Kriegshymnenklans, der Vorhut der Horde, die sich der Sicherung von Holz und der Beanspruchung von Territorien im südlichen Eschental gegen die Nachtelfen verschrieben hat.",al={"kelm fraktion","rüstmeister der warsongvorhut","für wen arbeitet kelm"}},{q="Was sind die Hilfspakete, die Kelm anbietet?",a="Hargunth gibt einfache, gewöhnliche und hochentwickelte Hilfspakete an Frontkämpfer aus. Diese Versorgungspakete enthalten unverzichtbare Schlachtfeldutensilien, Verbände und Rationen, um die Kämpfer der Horde in der Schlucht versorgt zu halten.",al={"hilfspaket der vorhut","kelm hilfspaket","warsong hilfspaket"}},{q="Warum ist der Mor'shan-Stützpunkt für den Kriegshymnenklan so wichtig?",a="Der Mor'shan-Stützpunkt dient als befestigter Sammelplatz und Kontrollpunkt zwischen dem Brachland und Eschental, wodurch der Kriegshymnenklan Nachschub, Verstärkung und geschlagenes Holz sicher in die Gebiete der Horde transportieren kann.",al={"warum mor'shan-stützpunkt","mor'shan zweck","hintergrund stützpunkt"}},{q="Welche Art von Ausrüstung stellt Kelm Hargunth bereit?",a="Er stattet bewährte Kämpfer mit Schlachtwappenröcken des Kriegshymnenklans, Spezialwaffen wie der Klinge des Spähers und dem Schwert des Legionärs, angepassten Rüstungssets, Ringen und Schlachtfeldtränken für den Nahkampf aus.",al={"kelm pvp-ausrüstung","warsong belohnungen","was verkauft kelm"}}},fx={["1810d113"]={q="Warum ist Kelm Hargunth im Mor'shan-Stützpunkt stationiert?",a="Kelm Hargunth dient als Versorgungsoffizier für die Vorhut des Kriegshymnenklans direkt an der Grenze zum Eschental. Er ist im Mor'shan-Stützpunkt stationiert und stellt sicher, dass Champions der Horde, die in die Kriegshymnenschlucht aufbrechen, ordnungsgemäß ausgerüstet sind, um gegen die Schildwachen der Silberschwingen zu kämpfen und lebenswichtiges Holz und Territorium zu sichern.",al={"warum ist kelm hargunth hier","zweck von kelm hargunth","warum ist kelm bei morshan"}},c16a55e1={q="Was möchte Kelm Hargunth?",a="Kelm will nichts Geringeres als den totalen Sieg der Horde gegen die Nachtelfen in der Kriegshymnenschlucht. Als Quartiermeister der Vorhut verlangt er Beweise Eurer Tapferkeit auf dem Schlachtfeld und bietet denjenigen, die hart gegen die Allianz zuschlagen, Rüstungen, Vorräte und Versorgungspakete an.",al={"was möchte kelm hargunth","ziel von kelm hargunth","was möchte kelm"}},bced0f9b={q="An wen ist Kelm Hargunth gebunden?",a="Kelm untersteht direkt der Vorhut des Kriegshymnenklans, der Vorhut der Horde, die um die dichten Wälder des Eschentals kämpft. Er operiert unter dem Banner des Kriegshymnenklans sowie der Horde und arbeitet Hand in Hand mit den Fronttruppen, die den Mor'shan-Stützpunkt verteidigen.",al={"kelm hargunth zugehörigkeit","für wen arbeitet kelm hargunth","kelm hargunth fraktion"}}},fp="13,368,25.422.0,19.376.0,21.229.0,31.145.0,38.150.0,39.217.0,54.220.0,45.216.0"}
P.entries["npc:kerlonian-evershade"] = {n="Kerlonian Schattenspiel",s="Kerlonian Schattenspiel ist ein Nachtelf-Druide, der im Grove of the Ancients an der Dunkelküste ruht. Da er erst kürzlich aus dem langen Schlummer im Smaragdgrünen Traum erwacht ist, benötigt er Hilfe bei der Durchquerung der verderbten Wildnis, um die Sicherheit von Maestras Posten zu erreichen.",h="Kerlonian Schattenspiel ist ein Nachtelf-Druide, der im Grove of the Ancients an der Dunkelküste ruht.",kw={"dunkelküste","druide der klaue","smaragdgrüner traum","schattenspiel","grove of the ancients","kerlonian","the sleeper has awakened"},ang={["class:Druid"]="Druiden-Abenteurer werden Kerlonians missliche Lage sehr gut verstehen, da alle Jünger des Zirkels des Cenarius mit dem schweren Tribut der tiefen Zwiesprache mit dem Smaragdgrünen Traum zu kämpfen haben.",["race:NightElf"]="Für Nachtelfen-Reisende bedeutet die Führung von Kerlonian den Schutz eines ihrer uralten Verteidiger, der frisch in eine Welt zurückgekehrt ist, die sich seit dem Dritten Krieg gewaltig verändert hat."},sec={{t="Erwachen an der Dunkelküste",b="Kerlonian Schattenspiel gehört zu den Druids of the Claw, Anhängern des Bärentotems, die Jahrhunderte schlafend in Grabhügeln und in Gemeinschaft mit dem Smaragdgrünen Traum verbrachten. Die Druids of the Claw wurden während des Dritten Krieges aus ihrem Schlummer gerufen. Kerlonian, der unter den uralten Bäumen des Grove of the Ancients ruhend angetroffen wird, schüttelt noch immer die übernatürliche Benommenheit seiner langen Ruhe ab. Sein unmittelbares Anliegen ist es, sicher durch die unruhigen Wälder der Dunkelküste nach Maestras Posten an der Grenze zum Eschental zu reisen."},{t="Eine tückische Reise",b="Der Weg aus dem Grove of the Ancients ist alles andere als sicher. Die sich ausbreitende Fäulnis an der Dunkelküste hat die einheimische Tierwelt aufgeschreckt und feindselige Pirscher sowie Grells nahe an die heiligen Lichtungen herangeführt. Geschwächt vom Schlaf und mit plötzlichen Anfällen von Erschöpfung kämpfend, verlässt sich Kerlonian auf wohlgesinnte Reisende der Allianz, die ihn beschützen, während er sich auf den Weg nach Süden macht, um sich seinen Nachtelfenbrüdern wieder anzuschließen."}},faq={{q="Wer ist Kerlonian Schattenspiel?",a="Kerlonian Schattenspiel ist ein Nachtelf-Druide, der nahe dem Grove of the Ancients an der Dunkelküste stationiert ist. Er ist kürzlich aus dem Smaragdgrünen Traum erwacht und benötigt Unterstützung, um sicher durch die Wälder zu reisen.",al={"wer ist kerlonian","kerlonian schattenspiel lore","druide im grove of the ancients"}},{q="Warum schläft Kerlonian beim Gehen ein?",a="Wie viele Druids of the Claw, die jahrhundertelang in Grabhügelbauten schliefen, leidet Kerlonian noch immer unter der anhaltenden Benommenheit des Smaragdgrünen Traums. Sein Körper und sein Geist haben sich noch nicht vollständig an die wache Realität angepasst, was zu plötzlichen Schläfrigkeitsschüben führt.",al={"warum schläft kerlonian","der schläfer ist erwacht quest druide","kerlonian schläfrig"}},{q="Wohin versucht er zu gelangen?",a="Er sucht sicheres Geleit nach Süden zu Maestras Posten, einem Außenposten der Nachtelfen an der Grenze zwischen der Dunkelküste und dem Eschental, wo er sich sicher erholen kann.",al={"kerlonian zielort","wohin geht kerlonian","grove of the ancients eskortierung zielort"}},{q="Was ist ein Druide der Klaue?",a="Druids of the Claw sind Nachtelfen-Druiden, die den Bären-Urvater Ursoc verehren. Sie bündeln Stärke, Zähigkeit und wilde Macht und bewachen traditionell Grabhügel sowie die Länder der Nachtelfen, während sie Zeitalter schlafend im Smaragdgrünen Traum verbringen.",al={"was ist ein druide der klaue","druids of the claw lore"}}},fx={["62482562"]={q="Auf wessen Seite steht Kerlonian Schattenspiel?",a="Kerlonian ist ein Nachtelf-Druid of the Claw, der dem Zirkel des Cenarius und den Nachtelfen der Allianz aus Darnassus angehört. Seine Hingabe gilt der Natur, dem Smaragdgrünen Traum und seinen druidischen Brüdern, die die uralten Haine in ganz Kalimdor beschützen.",al={"kerlonian fraktion","ist kerlonian allianz","kerlonian schattenspiel seite"}},["9e991c8a"]={q="Was will Kerlonian Schattenspiel?",a="Da er kürzlich aus seinem langen Schlaf im Smaragdgrünen Traum erwacht ist, wünscht sich Kerlonian nichts sehnlicher als eine sichere Rückkehr zu seinen Nachtelfen-Gefährten bei Maestras Posten. Seine tiefe Trance macht ihn schläfrig, was selbst einfache Reisen durch die Dunkelküste zu einem gefährlichen Unterfangen macht.",al={"kerlonian ziel","was will kerlonian schattenspiel","kerlonian zweck"}},["4cb7152a"]={q="Warum ist Kerlonian Schattenspiel hier?",a="Kerlonian hat am Grove of the Ancients für ein kurzes Nickerchen angehalten, während er auf dem Weg war, um Liladris Moonriver bei Maestras Posten zu treffen. Er ist nach dem Erwachen aus dem Smaragdgrünen Traum immer noch schläfrig und bittet um Hilfe, um sie sicher zu erreichen.",al={"warum ist kerlonian in der dunkelküste","kerlonian grove of ancients","warum schläft kerlonian hier"}},["0418b012"]={q="An wen ist Kerlonian Schattenspiel gebunden?",a="Kerlonian gehört zu den Druid of the Claw, einem Orden innerhalb des Zirkel des Cenarius, der dem Bärengeist gewidmet ist und die Aufgabe hat, die Wildnis zu bewachen. Er ist außerdem durch Verwandtschaft und Pflicht an die Nachtelfen gebunden, die bei Maestras Posten an der Grenze zum Eschental stationiert sind.",al={"kerlonian orden","kerlonian verbindungen","wem dient kerlonian"}}},fp="19,262,22.522.0,21.395.0,27.204.0,45.243.0,25.154.0,28.229.0"}
P.entries["npc:kernobee"] = {n="Kernobee",s="Kernobee ist ein Goblin-Ingenieur, der tief in den verfallenen Hallen von Gnomeregan gefangen ist. Nachdem er auf gefährliche Geheimnisse über die Sabotage der Dunkeleisenzwerge gestoßen war, wurde er gefangen genommen, bewusstlos geschlagen und bei den Troggs in den Schlafsälen zum Sterben zurückgelassen.",h="Kernobee ist ein Goblin-Ingenieur, der tief in den verfallenen Hallen von Gnomeregan gefangen ist.",kw={"dunkeleisenzwerge","schlafsaal","gnomeregan","kernobee","ratschet","superbohrer","tinkerwiz"},ang={["profession:Engineering"]="Ingenieure können die schiere Gefahr nachvollziehen, die das Herumschnüffeln an experimentellen Untertagemaschinen wie den Dunkeleisen-Bohrern birgt, wenn es um konkurrierende Baupläne geht.",["race:Gnome"]="Für Gnome, die um die Rückeroberung ihrer Heimat kämpfen, ist Kernobees Information ein alarmierender Beweis dafür, dass ihre Katastrophe aus dem Verborgenen durch die Einmischung der Dunkeleisenzwerge begünstigt wurde."},sec={{t="Eine tödliche Entdeckung",b="Während er in der gefallenen Gnomenhauptstadt Geschäfte abwickelte oder nach Brauchbarem suchte, deckte Kernobee ein schwerwiegendes Geheimnis auf: Die Dunkeleisenzwerge waren direkt am Bau und Betrieb der gewaltigen Superbohrer beteiligt, die sich unter der Stadt hindurchgruben. Da er den immensen Wert – und die Tödlichkeit – dieser Informationen erkannte, versuchte er sofort nach Ratschet zu fliehen, um seinem Partner Tinkerwiz Bericht zu erstatten. Unglücklicherweise schnappten ihn die Dunkeleisenzwerge, bevor ihm die Flucht gelang."},{t="Den Troggs überlassen",b="Anstatt ihn auf der Stelle zu töten, schlugen seine Entführer Kernobee bewusstlos und warfen ihn in einen kleinen Raum entlang des Schlafsalkorridors, gegenüber der Clean Zone. Gestrandet zwischen wilden Troggs und radioaktivem Niederschlag, ist der geschundene Goblin vollkommen darauf angewiesen, dass vorbeikommende Abenteurer ihn wiederbeleben und beschützen, bis er sich in Sicherheit bringen kann."}},faq={{q="Wer ist Kernobee?",a="Kernobee ist ein Goblin-Agent, der bewusstlos im Schlafsaalsektor von Gnomeregan aufgefunden wird. Er arbeitet eng mit Tinkerwiz in Ratschet zusammen und wagte sich in die Ruinen, bevor er in einen Hinterhalt geriet.",al={"wer ist dieser goblin","kernobee lore","über kernobee"}},{q="Warum wurde Kernobee in Gnomeregan gefangen gehalten?",a="Kernobee entdeckte, dass der Dunkeleisenclan heimlich beim Bau der unterirdischen Superbohrer-Maschinen in der Stadt half. Um ihre Anwesenheit und Sabotage geheim zu halten, setzten die Dunkeleisenzwerge ihn außer Gefecht und warfen ihn in den Schlafsaal, damit er dort umkommt.",al={"warum ist er hier","warum nahmen die dunkeleisenzwerge ihn gefangen","warum im schlafsaal"}},{q="Wem untersteht Kernobee?",a="Er untersteht Tinkerwiz, einem Goblin-Ingenieur, der jenseits des Meeres in der neutralen Hafenstadt Ratschet im Brachland stationiert ist.",al={"wer ist tinkerwiz","wohin geht er","verbindung nach ratschet"}},{q="Wo in Gnomeregan befindet sich Kernobee?",a="Er liegt zusammengesunken und bewusstlos in einem kleinen Nebenraum auf der unteren Ebene des Schlafsaals, auf der Westseite direkt gegenüber der Clean Zone.",al={"kernobee standort","wo ist kernobee","kernobee finden"}}},fx={["3c758521"]={q="Auf wessen Seite steht Kernobee?",a="Kernobee gehört zum Steamwheedle Cartel und untersteht Tinkerwiz im neutralen Hafen von Ratschet. Anstatt der Allianz oder der Horde zu dienen, kümmert er sich um Goblin-Geschäfte – was ihn direkt gegen die Dunkeleisenzwerge stellte, die in Gnomeregan lauerten, sobald er ihre Pläne aufdeckte.",al={"ist kernobee allianz oder horde","kernobee fraktion","für wen arbeitet kernobee"}},b63dca8d={q="Was will Kernobee?",a="Kernobee will nichts sehnlicher, als Gnomeregan lebend zu entkommen. Nachdem er entdeckt hat, dass Dunkeleisenzwerge am Bau der massiven Superbohranlage beteiligt waren, muss er dringend das Wohnheim verlassen und aus der verstrahlten Stadt fliehen, um seine Erkenntnisse Tinkerwiz in Ratschet melden zu können.",al={"was versucht kernobee zu tun","kernobee ziel","warum kernobee helfen"}}},fp="8,253,18.470.0,19.335.0,16.180.0,42.247.0,28.119.0,40.149.0"}
P.entries["npc:keryn-sylvius"] = {n="Keryn Sylvius",s="Keryn Sylvius ist eine menschliche Schurkenlehrerin, die sich im zweiten Stock des Gasthauses \"Zur Höhle des Löwen\" in Goldhain aufhält. Zurückgezogen im Lesezimmer des Gasthauses bringt sie angehenden Halunken die Grundlagen der Verstohlenheit und Klingenkunst bei und fungiert zugleich als stilles Bindeglied zum Geheimdienst von Sturmwind.",h="Keryn Sylvius ist eine menschliche Schurkenlehrerin, die sich im zweiten Stock des Gasthauses \"Zur Höhle des...",kw={"wald von elwynn","goldhain","keryn sylvius","gasthaus \"zur höhle des löwen\"","schurkenlehrer","der si:7"},ang={["class:Rogue"]="Sylvius ist die primäre Mentorin für aufstrebende Schurken, die den Wald von Elwynn durchstreifen, und weist ihnen schließlich den Weg zum Hauptquartier des SI:7 in Sturmwind.",["faction:Alliance"]="Über der Kreuzung von Goldhain stationiert, hilft sie dabei, die verborgenen Augen der Allianz entlang der Hauptverkehrswege von Elwynn offenzuhalten."},sec={{t="Eine ruhige Gestalt in Goldhain",b="Während das Erdgeschoss des Gasthauses \"Zur Höhle des Löwen\" von lauten Reisenden und erschöpften Stadtwachen wimmelt, hält sich Keryn Sylvius im ruhigen Lesezimmer im Obergeschoss auf. Äußerlich unauffällig, beobachtet sie den stetigen Strom an Gerüchten von der Straße und dient als örtliche Mentorin für Schurken, die im Wald von Elwynn ihre ersten Erfahrungen sammeln. Sobald vielversprechende Agenten den lokalen kleinen Diebereien und Gaunereien am Wegesrand entwachsen sind, schickt Sylvius sie diskret weiter nach Sturmwind, um Kontakt mit dem SI:7 aufzunehmen."}},faq={{q="Wo kann ich Keryn Sylvius finden?",a="Sie befindet sich im zweiten Stock des Gasthauses \"Zur Höhle des Löwen\" in Goldhain, abgeschieden im kleinen Lesezimmer.",al={"keryn sylvius aufenthaltsort","wo ist keryn","goldhain schurkenlehrer aufenthaltsort"}},{q="Welche Dienste bietet sie an?",a="Keryn Sylvius ist eine Schurkenlehrerin, die neue Fähigkeiten lehrt, Talentspezialisierungen zurücksetzt und aufstrebenden Schurken den Weg weist.",al={"was tut keryn","kann sie mich ausbilden","keryn sylvius rolle"}},{q="Welche Verbindung hat sie zum SI:7?",a="Sylvius dient als frühe Anlaufstelle für Sturmwinds geheimes Spionagenetzwerk und schickt fähige Agenten zu Meister Mathias Shaw und dem SI:7 in der Altstadt, sobald sie ihr Können unter Beweis gestellt haben.",al={"keryn der si:7","gehört sie zum si:7","arbeitet sie für sturmwind"}}},fx={["74741391"]={q="Wer ist Keryn Sylvius?",a="Keryn Sylvius ist eine Schurkenlehrerin, die ihr Zuhause im oberen Stockwerk des Gasthauses \"Zur Höhle des Löwen\" in Goldhain hat. Versteckt im ruhigen Leseraum beobachtet sie das Kommen und Gehen im Wald von Elwynn, während sie aufstrebenden Schurken unter dem Banner der Allianz die subtilen Künste der Verstohlenheit, des Schlösserknackens und der Täuschung vermittelt.",al={"wer ist keryn","keryn sylvius hintergrund","wer ist sylvius"}},["017a68dc"]={q="Auf wessen Seite steht Keryn Sylvius?",a="Keryn steht fest hinter dem Königreich Sturmwind und der Allianz. Ihr Handwerk dient den Interessen des Reiches, indem sie talentierte Agenten stillschweigend an das geheime Geheimdienstnetzwerk von Sturmwind verweist, damit diese das Königreich gegen interne Unruhen und äußere Bedrohungen unterstützen können.",al={"keryn sylvius allianz oder horde","keryn sylvius loyalität","wem dient keryn sylvius"}},["90e34396"]={q="Was will Keryn Sylvius?",a="Keryn zielt darauf ab, junge Talente im ruhigen Herzen von Elwynn auszukundschaften und anzuleiten, bevor sie mit dem Gesetz in Konflikt geraten oder ihre tödlichen Fähigkeiten missbrauchen. Sobald sich ein Lehrling als fähig erweist, besteht ihr Ziel darin, seine Fähigkeiten in geordnete Bahnen zu lenken, indem sie ihn an das Hauptquartier von SI:7 in der Altstadt verweist.",al={"was will keryn","keryn sylvius ziele","warum schurken ausbilden"}},f8e496c4={q="Warum ist Keryn Sylvius hier in Goldhain?",a="Das Gasthaus \"Zur Höhle des Löwen\" dient als geschäftiger Knotenpunkt im Wald von Elwynn und ist daher ein idealer Ort, um unauffällig Schurken zu identifizieren, die außerhalb des Nordhaintals ihre ersten Schritte machen. Ihr Posten im Obergeschoss bietet ihr einen diskreten Ort, um Anfänger auszubilden, ohne unnötige Aufmerksamkeit von den örtlichen Wachen oder den Stadtbewohnern unter ihr zu erregen.",al={"warum ist keryn im gasthaus zur höhle des löwen","warum ist keryn sylvius in goldhain","keryn goldhain grund"}}},fp="13,279,29.470.0,31.108.0,29.135.0,38.201.0"}
P.entries["npc:khelden-bremen"] = {n="Khelden Bremen",s="Khelden Bremen ist ein menschlicher Magier und Ausbilder, der sich im oberen Stockwerk der Abtei von Nordhain im Wald von Elwynn aufhält. Er beaufsichtigt die allererste Ausbildung von Zauberwirker-Neulingen, die im Dienste von Sturmwind die arkanen Künste erlernen.",h="Khelden Bremen ist ein menschlicher Magier und Ausbilder, der sich im oberen Stockwerk der Abtei von Nordhain...",kw={"arkan","wald von elwynn","glyphenbrief","khelden bremen","magierlehrer","abtei von nordhain"},ang={["class:Mage"]="Für menschliche Magier stellt Khelden Bremen den ersten formellen Schritt in die arkane Gelehrsamkeit dar, bevor sie ihre fortgeschrittene Ausbildung in den Türmen von Sturmwind fortsetzen."},sec={{t="Lehrer des Arkanen",b="Inmitten der ruhigen Steinmauern der Abtei von Nordhain fungiert Khelden Bremen als primärer Ausbilder für angehende menschliche Magier. Während sich die Geistlichen und Verteidiger unten den kriegerischen und spirituellen Belangen widmen, unterhält Bremen im Obergeschoss ein ruhiges Studierzimmer. Hier führt er Novizen an die Disziplin, die Konzentration und die grundlegenden Techniken heran, die erforderlich sind, um rohe magische Energie sicher zu weben, bevor sie in den Wald von Elwynn und weiter in das Magierviertel von Sturmwind hinausziehen."}},faq={{q="Wer ist Khelden Bremen?",a="Khelden Bremen ist der ansässige Magierlehrer in der Abtei von Nordhain im Wald von Elwynn. Er leitet neu erwachte Magier bei ihren ersten Zaubern und den grundlegenden arkanen Studien an.",al={"wer ist khelden","bremen","magierlehrer nordhain"}},{q="Wo finde ich Khelden Bremen?",a="Er befindet sich im zweiten Stock der Abtei von Nordhain. Betretet die Abtei und geht die Treppe im zweiten Raum auf der linken Seite hinauf.",al={"wo ist khelden","khelden bremen aufenthaltsort","nordhain magierlehrer standort"}},{q="Welche Rolle spielt er für neue Abenteurer?",a="Angehende menschliche Magier werden nach ihrer Ankunft in Nordhain an Khelden verwiesen, oft mit einem Glyphenbrief als Empfehlungsschreiben. Er lehrt wichtige Anfangszauber und hilft Novizen dabei, ihre magische Begabung zu nutzen.",al={"was macht khelden","bremen quests","empfänger von glyphen-brief"}}},fx={["7cfd66d2"]={q="Auf wessen Seite steht Khelden Bremen?",a="Khelden Bremen steht fest an der Seite des Königreichs Sturmwind und der Allianz. Er ist in der Abtei von Nordhain stationiert und dient dem Reich, indem er die nächste Generation von Zauberwirkern unterweist und sie darauf vorbereitet, die Ländereien der Menschheit gegen aufkommende Gefahren zu verteidigen.",al={"fraktion khelden bremen","wem dient khelden","ist khelden bremen bei der allianz"}},["032606f2"]={q="Was möchte Khelden Bremen?",a="Kheldens Ziel ist es, angehende Magier in den arkanen Künsten zu unterrichten. Er sucht engagierte Lehrlinge, die bereit sind, grundlegende Zauber zu erlernen, ihren wachsenden Intellekt zu meistern und ihre Macht verantwortungsbewusst für die Sicherheit des Waldes von Elwynn und Sturmwind einzusetzen.",al={"ziel von khelden bremen","was will khelden"}},["8660ec47"]={q="Warum ist Khelden Bremen hier in der Abtei von Nordhain?",a="Die Abtei von Nordhain dient als Zufluchtsort für Rekrutierung und Ausbildung junger Verteidiger, die dem Ruf Sturmwinds folgen. Bremen hält sich im oberen Stockwerk der Abtei auf, speziell um angehende menschliche Praktizierende zu empfangen und ihre ersten Schritte in der Magie zu lenken, bevor sie sich tiefer in das weitere Reich vorwagen.",al={"warum ist khelden in nordhain","warum ist khelden bremen hier"}}},fp="14,225,19.459.0,22.172.0,32.134.0,43.205.0"}
P.entries["npc:kil-hala"] = {n="Kil'hala",s="Kil'hala ist ein Dschungeltroll-Lehrer für Schneiderei, der beim Wegekreuz im Brachland stationiert ist. Er ist geschickt im Umgang mit alltäglichem Stoff sowie exotischen Webmaterialien und unterweist Handwerker der Horde, die ihre Nadelarbeit verfeinern möchten. Über gewöhnliche Fäden hinaus schickt er ehrgeizige Schneider nach Norden ins Eschental, um seltene Reagenzien wie Netherspitze zu beschaffen.",h="Kil'hala ist ein Dschungeltroll-Lehrer für Schneiderei, der beim Wegekreuz im Brachland stationiert ist.",kw={"brachland","das wegekreuz","kil'hala","lachende schwestern","netherspitze","schneiderei","lehrer"},ang={["faction:Horde"]="Kil'hala stellt Textilwaren und Handwerksausbildung am Wegekreuz bereit und hilft so dabei, die Kriegsschar sowie Reisende auszurüsten, die im Brachland Fuß fassen wollen.",["profession:Tailoring"]="Kil'hala ist eine wesentliche Anlaufstelle für Schneidergesellen der Horde, die Kalimdor durchqueren; er lehrt Handwerkstechniken und vergibt Quests, um exotische magische Roben zu weben."},sec={{t="Schneider des Brachlands",b="Kil'hala befindet sich am geschäftigen Knotenpunkt des Wegekreuzes und bietet durchreisenden Reisenden sowie Rekruten der Horde sein Schneiderwissen an. Während ein Großteil seines Handwerks aus gewöhnlichen gewebten Ballen und Kleidungsstücken besteht, die für das Leben in den trockenen Ebenen geeignet sind, reicht sein Wissen bis hin zu seltenen magischen Textilien. Um wahrhaft bemerkenswerte Roben herzustellen, fordert Kil'hala die Weber dazu auf, sich in das ungezähmte Blätterdach von Eschental zu wagen, wo ätherische Materialien wie Netherspitze von magischen Dryaden gewonnen werden können."}},faq={{q="Wer ist Kil'hala?",a="Kil'hala ist ein Dunkelspeertroll und ein Lehrer für Schneiderei, der sich beim Wegekreuz im Brachland aufhält. Er hilft Hordenhandwerkern dabei, die Grundlagen des Stoffwebens und der Bekleidungsherstellung zu erlernen.",al={"kil'hala identität","wer ist kil'hala","das wegekreuz schneider"}},{q="Wo kann ich Kil'hala finden?",a="Er befindet sich im Brachland in der zentralen Siedlung des Wegekreuzes, platziert neben anderen Handwerkslehrern der Horde.",al={"kil'hala standort","wo ist kil'hala","kil'hala aufenthaltsort"}},{q="Welche Aufgaben gibt Kil'hala Schneidern?",a="Er schickt Weber, die fortgeschrittenes Stoffhandwerk anstreben, nach Eschental, um Dryaden zu jagen, die als die Lachenden Schwestern bekannt sind. Kil'hala verwendet ihre ätherischen Locken, um ein einzigartiges Netherspitzengewand herzustellen.",al={"kil'hala quests","lachende schwestern quest","netherspitzengewand"}}},fx={["5b372e18"]={q="Auf wessen Seite steht Kil'hala?",a="Kil'hala ist der Horde und seinem Volk, den Dunkelspeertrollen, treu. Im Herzen des Wegekreuzes dient er als Schneidereilehrer, um Reisende, Krieger und angehende Handwerker, die durch Kalimdor ziehen, auszurüsten.",al={"kil'hala horde oder allianz","kil'hala fraktion","wem dient kil'hala"}},["79a7457d"]={q="Was will Kil'hala?",a="Kil'hala möchte sein Fachwissen im Weben und in der Stoffverarbeitung mit anderen Mitgliedern der Horde teilen. Er bildet angehende Schneider aus und schickt erfahrene Handwerker auf Quests, um seltene, mystische Materialien wie das Haar der Laughing Sisters zu beschaffen und daraus feine Kleidungsstücke zu fertigen.",al={"kil'hala ziel","kil'hala zweck","was benötigt kil'hala"}},["218c0279"]={q="Warum ist Kil'hala hier?",a="Kil'hala hat sein Zuhause am Wegekreuz, einem wichtigen Knotenpunkt, der Durotar, Mulgore und die nördliche Wildnis verbindet. Durch seine Stationierung hier kann er den stetigen Strom von Horde-Abenteurern, die das Brachland durchqueren, seine Handwerkskunst und Beratung anbieten.",al={"warum ist kil'hala am wegekreuz","warum ist kil'hala im brachland","kil'hala standort grund"}}},fp="8,339,21.461.0,16.189.0,26.124.0,41.197.0"}
P.entries["npc:kin-weelay"] = {n="Kin'weelay",s="Kin'weelay ist ein renommierter Hexendoktor der Dunkelspeere, der im Basislager von Grom'gol im Schlingendorntal stationiert ist. Direkt aus Orgrimmar entsandt, bietet er der Vorhut der Horde im Dschungel mystischen Beistand und Rat. Seine spirituelle Expertise ist unerlässlich, um dunkles Mojo zu brechen und bei der Rettung des jungen Yenniku zu helfen.",h="Kin'weelay ist ein renommierter Hexendoktor der Dunkelspeere, der im Basislager von Grom'gol im...",kw={"dunkelspeer","grom'gol","kin'weelay","kinweelay","gedankenauge","schlingendorntal","hexendoktor","yenniku"},ang={["faction:Horde"]="Kin'weelay demonstriert den Wert des Troll-Spiritualismus für die Kriegsanstrengungen der Horde, indem er magische Gegenstrategien gegen Bedrohungen liefert, die mit reiner Stärke nicht bezwungen werden können.",["race:Troll"]="Für die Dunkelspeere verkörpert Kin'weelay eine der angesehensten spirituellen Autoritäten des Stammes, die sich der Aufhebung der grausamen Flüche ihrer Dschungelverwandten verschrieben hat."},sec={{t="Ein Meister des Dunkelspeer-Mojo",b="Unter den Dunkelspeeren als einer ihrer mächtigsten Ausüber traditioneller Hexendoktorkunst anerkannt, verfügt Kin'weelay über tiefes Wissen über Geister, Flüche und Seelenmagie. Wenn Angelegenheiten rund um Ahnengeister oder feindselige Troll-Verzauberungen auftreten, wenden sich die Späher der Horde im Schlingendorntal an ihn, um den magischen Schleier zu durchdringen."},{t="Die Mission nach Grom'gol",b="Kin'weelay wurde aus den staubigen Straßen von Orgrimmar nach Süden geschickt, um Nimboya im Basislager von Grom'gol gezielt zu unterstützen. Seine Bestimmung geht über einfache militärische Hilfe hinaus; sein Fokus liegt darauf, die unheilvollen Bande zu zerbrechen, die dem entführten Yenniku auferlegt wurden, dem Sohn aus der vertrauten Blutlinie von Häuptling Vol'jin. Um solch dunkles Handwerk rückgängig zu machen, sucht Kin'weelay nach mächtigen Reagenzien – allen voran dem Gedankenauge –, um einen Seelenedelstein anzufertigen, der gefangene Geister befreien kann."}},faq={{q="Wer ist Kin'weelay?",a="Kin'weelay ist ein hochgeschätzter Hexendoktor der Dunkelspeer, der im Basislager von Grom'gol im nördlichen Schlingendorntal stationiert ist. Bekannt für seine Meisterschaft über Geist- und Seelenmagie, wurde er von der Führung der Horde aus Orgrimmar entsandt.",al={"kinweelay lore","wer ist kin'weelay","grom'gol hexendoktor"}},{q="Warum ist Kin'weelay im Schlingendorntal?",a="Er wurde in das Basislager Grom'gol geschickt, um Nimboya und der dortigen Dunkelspeer-Expedition seine mystischen Talente zur Verfügung zu stellen, insbesondere bei der Suche und Rettung des jungen Yenniku aus den Klauen feindseliger Dschungeltrolle.",al={"warum ist kinweelay in grom'gol","kinweelay aufgabe"}},{q="Was versucht Kin'weelay herzustellen?",a="Kin'weelay versucht, ein Relikt namens Gedankenauge in seinen Besitz zu bringen. Mit seiner Hexenkunst beabsichtigt er, es zu einem Seelenedelstein zu verarbeiten, der die Seele von Yenniku einfangen und sicher bewahren kann, um die finstere Beherrschung des Jungen zu brechen.",al={"kinweelay gedankenauge","was stellt kinweelay her"}},{q="Woher stammt Kin'weelay?",a="Er reiste aus Orgrimmar an, wo der Stamm der Dunkelspeer seit seinem Beitritt zur Horde und der Besiedlung der Echoinseln eine starke Verbindung und Präsenz aufrechterhält.",al={"kinweelay hintergrund","woher kommt kinweelay"}},{q="Wie sieht er die anderen Trollstämme des Schlingendorntals?",a="Er betrachtet feindliche Dschungelstämme wie die Bloodscalp und Schädelspalter als gefährliche Rivalen, die in gewalttätigen, verderbten Ritualen versunken sind. Er setzt seine Künste aktiv ein, um ihren Bannzaubern entgegenzuwirken und die geraubte Jugend der Dunkelspeer zurückzuholen.",al={"kinweelay andere trolle","kinweelay und bloodscalp"}},{q="Welche Arten von Gegenständen erforscht Kin'weelay?",a="Kin'weelay untersucht lokale Kuriositäten mit natürlicher oder verhexter Resonanz, darunter die geheimnisvollen singenden Kristalle und Knochenhalsketten feindlicher Dschungeltrolle, und studiert deren Mojo, um Gegenmaßnahmen zu entwickeln.",al={"kinweelay gegenstände","singende kristalle kinweelay"}}},fp="10,308,26.324.0,23.444.1,18.227.0,40.201.0,36.222.0,32.146.0,57.216.0,41.219.0"}
P.entries["npc:kindal-moonweaver"] = {n="Kindal Mondweber",s="Kindal Mondweber ist eine Nachtelfe, die zurückgezogen in einem verborgenen Winkel in den schroffen Bergen von Feralas lebt, direkt nördlich des Truppenlagers der Grimmtotem. Tief besorgt über die Misshandlung der Tierwelt in der Wildnis beobachtet sie den aggressiven Taurenstamm in der Tiefe und sucht nach Hilfe, um gefangene Tiere zu befreien. Sie ist mit Jer'kai Moonweaver verwandt und teilt deren Mission, die unschuldigen Kreaturen des Waldes zu beschützen.",h="Kindal Mondweber ist eine Nachtelfe, die zurückgezogen in einem verborgenen Winkel in den schroffen Bergen...",kw={"düsterbruch","feralas","freiheit für alle kreaturen","truppenlager der grimmtotem","verborgener pfad","jer'kai moonweaver","kindal mondweber"},ang={["class:Druid"]="Druiden werden sich mit Kindals unermüdlichem Einsatz für den Schutz des Waldlebens und der Befreiung gefangener Naturgeister aus grausamen Eisenkäfigen tief verbunden fühlen.",["class:Hunter"]="Jäger, die im Einklang mit den Tieren von Kalimdor stehen, können Kindals Bemühungen respektieren, die Jungen der Wildnis zu schützen und diejenigen zu bestrafen, die Wild zum Vergnügen oder aus Bosheit jagen.",["race:NightElf"]="Kindal verkörpert die traditionelle Hingabe der Kaldorei an die Natur und wacht als einsame Beschützerin über die Tiere, die durch Eindringlinge von außerhalb bedroht werden."},sec={{t="Eine Wächterin auf den Klippen",b="Auf einem schmalen, gewundenen Bergpfad gelegen, der östlich von Düsterbruch teilweise hinter Gehölz verborgen ist, hält Kindal Mondweber eine geheime Wacht über das Tal unter sich. Während weite Teile von Feralas zwischen der Horde, den Nachtelfen der Mondfederfeste und den uralten Ruinen von Eldre'Thalas umkämpft sind, konzentriert sich Kindal auf eine lokalere und unmittelbarere Grausamkeit. Unten in der Senke unterhält der Stamm der Grimmtotem ein befestigtes Lager, wo er einheimische Tiere aus keineswegs harmlosen Gründen einfängt und einpfercht. Von ihrem verborgenen Ausguck späht Kindal nach jedem aus, der bereit ist, sich in das feindliche Lager zu wagen und dem dortigen Leiden ein Ende zu setzen."},{t="Mitgefühl für die Wildnis",b="Kindals Hauptanliegen gilt dem heiligen Gleichgewicht und den sanften Kreaturen von Feralas, die sich nicht selbst gegen brutale Peiniger verteidigen können. Gemeinsam mit ihrer Verwandten Jer'kai Moonweaver strebt sie die Befreiung eingekerkerter Tiere an und kümmert sich um junge Geschöpfe, die durch gewaltsame Wilderei hilflos zurückgelassen wurden. Statt sich an großen territorialen Kriegen zu beteiligen, gilt ihr ganzes Mitgefühl der Rettung: gefangene Waldgeister zu befreien und für einen verwaisten Grimmlingflitzer ein neues Zuhause zu finden."}},faq={{q="Wo befindet sich Kindal Mondweber?",a="Kindal versteckt sich entlang der nördlichen Klippen von Feralas, direkt östlich von Düsterbruch und oberhalb des Truppenlagers der Grimmtotem. Ihr erreicht sie über einen schmalen, verborgenen Bergpfad, der sich hinter einer Baumgruppe den Hang hinaufwindet.",al={"kindal mondweber aufenthaltsort","kindal finden","wo ist kindal"}},{q="Wer ist Kindal Mondweber?",a="Sie ist eine einsame Nachtelfe, die sich dem Schutz der Tiere und der Bewahrung der Natur in Feralas verschrieben hat. Sie überwacht das Truppenlager der Grimmtotem, um das Einfangen der einheimischen Tierwelt zu unterbinden.",al={"kindal lore","wer ist kindal"}},{q="Was ist Kindals Ziel in Feralas?",a="Kindal möchte gefangene Kreaturen befreien, die im nahe gelegenen Truppenlager der Grimmtotem in Käfigen gehalten werden, und dafür sorgen, dass verwaiste Wildtiere gerettet werden und eine sichere Zuflucht finden.",al={"kindal quest zweck","warum ist kindal hier"}},{q="Ist Kindal Mondweber mit Jer'kai Moonweaver verwandt?",a="Ja, Kindal ist mit Jer'kai Moonweaver verwandt. Beide tragen den Familiennamen Moonweaver und arbeiten zusammen, um misshandelte und vertriebene Waldkreaturen im zentralen Kalimdor zu retten.",al={"verbindung zu jer'kai moonweaver","kindal und jerkai"}},{q="Warum stellt sich Kindal den Grimmtotem entgegen?",a="Der Grimmtotem-Klan, der das Lager unterhalb ihres Bergpostens besetzt hält, fängt und pfercht wilde Tiere aus Feralas in Käfige ein. Kindal will diese Wesen aus der Gefangenschaft befreien und ihre Peiniger bestrafen.",al={"kindal grimmtotem","truppenlager der grimmtotem kindal"}},{q="Bietet Kindal Mondweber Quests für beide Fraktionen an?",a="Nein. Kindals Quests werden nur der Allianz angeboten, deren Abenteurer sie dafür einspannt, die eingesperrten Kreaturen vor den Grimmtotem zu retten.",al={"ist kindal freundlich zur horde","kann horde mit kindal sprechen"}}},fp="17,391,26.598.0,23.447.0,35.210.0,25.182.0,33.174.0,51.184.0,37.191.0,53.131.0"}
P.entries["npc:kirge-sternhorn"] = {n="Kirge Sternhorn",s="Kirge Sternhorn ist ein Taure, der an der rauen Grenze des Brachlands stationiert ist. Als verlässlicher Ansprechpartner für Reisende, die das zentrale Kalimdor durchqueren, weist er unerfahrenen Abenteurern der Horde den Weg nach Norden zum wichtigen Außenposten Das Wegekreuz.",h="Kirge Sternhorn ist ein Taure, der an der rauen Grenze des Brachlands stationiert ist.",kw={"brachland","das wegekreuz","kirge","südliches brachland","sternhorn","taurajo","tauren"},ang={["faction:Horde"]="Für Reisende, die aus den südlichen Gebieten kommen, dient Kirge als früher Wegpunkt, der sie zur größeren Gemeinschaft der Horde im Wegekreuz leitet.",["race:Tauren"]="Kirge verkörpert den bodenständigen, gastfreundlichen Geist der Shu'halo und führt Stammesverwandte sowie Verbündete durch die raue Grenzregion ihrer Wahlheimat."},sec={{t="Ein Wanderer im Brachland",b="Die weiten, sonnenverbrannten Ebenen des Brachlands wirken auf neu eingetroffene Wanderer entmutigend, und Kirge Sternhorn steht ihnen als hilfsbereiter Wegweiser zur Seite. Südlich der zentralen Pfade postiert, wacht er über Reisende, die zwischen den südlichen Lagern und dem Herzen von Kalimdor unterwegs sind. Im Bewusstsein der Gefahren durch marodierende Borstennacken und wilde Raubtiere, welche die Savanne durchstreifen, sorgt Kirge dafür, dass junge Abenteurer Fuß fassen und die größere Hordenpräsenz aufsuchen, die sich im Norden sammelt."}},faq={{q="Wer ist Kirge Sternhorn?",a="Kirge Sternhorn ist ein taurischer Wanderer und Wegweiser, der in den südlichen Weiten des Brachlands stationiert ist und Reisenden der Horde dabei hilft, die staubigen Ebenen zu durchqueren.",al={"kirge sternhorn lore","wer ist kirge","kirge nsc"}},{q="Wohin schickt Kirge Reisende?",a="Kirge schickt Reisende nach Norden in Richtung Das Wegekreuz, dem zentralen Knotenpunkt im Brachland, an dem die Streitkräfte der Horde die Verteidigung und Erkundung der Region koordinieren.",al={"kirge quest","reise zum wegekreuz kirge","wohin schickt kirge euch"}},{q="Welcher Fraktion dient Kirge Sternhorn?",a="Kirge ist der Horde und seinen taurischen Brüdern und Schwestern treu ergeben und bietet allen Mitgliedern der Fraktion, die durch das Gebiet reisen, Führung und Hilfe an.",al={"ist kirge horde","kirge fraktion"}}},fp="15,248,25.483.0,23.150.0,32.161.0,40.146.0"}
P.entries["npc:klannoc-macleod"] = {n="Klannoc Macleod",s="Klannoc Macleod ist ein abgehärteter menschlicher Krieger, der auf Prügel-Eiland vor den östlichen Gestaden des Brachlands lebt. Bekannt als Prüfer kriegerischer Fähigkeiten, testet er aufstrebende Raufbolde sowohl der Allianz als auch der Horde, die die Kampfhaltungen meistern wollen. Jene, die sich seinen Respekt verdienen, schickt er weiter ins Landesinnere zu noch größeren Prüfungen der Stärke.",h="Klannoc Macleod ist ein abgehärteter menschlicher Krieger, der auf Prügel-Eiland vor den östlichen Gestaden...",kw={"brachland","berserker","prügel-eiland","insulaner","klannoc","macleod","der ringkampf","krieger"},ang={["class:Warrior"]="Klannoc Macleod ist eine Schlüsselfigur auf der Reise eines Kriegers; er testet Eure Ausdauer und Wildheit im Ringkampf, bevor er Euch auf den Weg zur Beherrschung der Berserkerhaltung führt.",["faction:Alliance"]="Krieger der Allianz müssen weit in Kalimdors Gewässer vor der Küste des Brachlands vordringen, um Klannoc zu finden und ihre Kampfbereitschaft auf Prügel-Eiland zu beweisen.",["faction:Horde"]="Obwohl er ein Mensch ist, schert sich Klannoc nicht um Fraktionsrivalitäten und heißt Kämpfer der Horde willkommen, die auf seiner abgelegenen Insel nach Prüfung und Ehre suchen."},sec={{t="Der Meister von Prügel-Eiland",b="Abgeschieden auf Prügel-Eiland vor der Händlerküste im Brachland überwacht Klannoc Macleod einen brutalen Richtplatz für erfahrene Kämpfer. Obwohl er ein Mensch ist, hält sich Klannoc aus den typischen politischen Streitigkeiten von Allianz und Horde heraus und beurteilt Herausforderer einzig nach ihrem Schneid, ihrer Klingenführung und ihrer Entschlossenheit im Gefecht."},{t="Der Ringkampf",b="Krieger, die nach Prügel-Eiland entsandt werden, müssen sich Macleods Prüfung stellen: dem Ringkampf. Die Anwärter betreten ein erhöhtes Eisengitter, um unbarmherzigen Wellen eifriger Raufbolde zu trotzen, während Klannoc zusieht. Jene, die dem Ansturm standhalten und seinen auserwählten Champion besiegen, verdienen sich seine Anerkennung und beweisen, dass sie das nötige Temperament für die Ausbildung zum Berserker besitzen."}},faq={{q="Wer ist Klannoc Macleod?",a="Klannoc Macleod ist ein erfahrener menschlicher Krieger, der auf Prügel-Eiland direkt vor der Küste des Brachlands haust. Er dient als Ausbilder und Prüfungsmeister für Krieger, die ihre Grenzen austesten und neue Techniken erlernen wollen.",al={"wer ist klannoc","klannoc macleod geschichte","prügel-eiland typ"}},{q="Wo finde ich Klannoc Macleod?",a="Klannoc befindet sich auf Prügel-Eiland, einer felsigen Insel vor der Ostküste des Brachlands, südöstlich der Händlerküste und von Ratschet. Ihr müsst durch das offene Wasser schwimmen, um sein Lager zu erreichen.",al={"klannoc aufenthaltsort","wo ist prügel-eiland","weg zu klannoc"}},{q="Warum spricht ein Mensch auf Prügel-Eiland mit Horde-Spielern?",a="Klannoc steht außerhalb des traditionellen Konflikts zwischen Allianz und Horde. Als unabhängiger Kampfmeister schert er sich nur um kriegerische Disziplin und den Kriegerkodex und stellt jeden Herausforderer auf die Probe, der mit einer angemessenen Empfehlung anreist.",al={"ist klannoc der horde feindlich","warum ist klannoc neutral","horde klannoc"}},{q="Was ist der Ringkampf?",a="Der Ringkampf ist eine Ausdauerprüfung, die auf Prügel-Eiland stattfindet. Ein Krieger muss auf Klannocs Kampfplattform stehen und Wellen von Herausforderern besiegen, was in einem Kampf gegen Big Will gipfelt, um zu beweisen, dass er die nötige Wildheit für fortgeschrittene Kriegertechniken besitzt.",al={"der ringkampf quest","prügel-eiland prüfung","klannoc prüfung"}},{q="Warum werden Krieger zu Klannoc Macleod geschickt?",a="Kriegerausbilder in ganz Azeroth verweisen ihre vielversprechendsten Schüler an Klannoc, damit sie sich einer Prüfung kriegerischer Standhaftigkeit unterziehen, die nötig ist, um sie auf den wilden Fokus der Berserkerhaltung vorzubereiten.",al={"kriegerquest prügel-eiland","warum zu klannoc","berserkerhaltung quest"}},{q="Zu wem schickt Klannoc einen nach dem Ringkampf?",a="Nachdem Ihr Euren Mut im Ringkampf bewiesen habt, schickt Klannoc die Krieger nach Norden ins Alteracgebirge nahe Tarrens Mühle, um Bath'rah den Windbehüter für weitere Unterweisungen aufzusuchen.",al={"nach klannoc","der windbehüter quest","wer ist der windbehüter"}}},fx={bf19a78f={q="Was will Klannoc Macleod?",a="Klannoc beaufsichtigt die Kampfprüfungen auf dem Prügel-Eiland und sucht nur nach fähigen Schlägern, die es wert sind, für The Affray in den Ring zu steigen. Er kümmert sich nicht um Fraktionspolitik oder die Herkunft der Kämpfer, sondern fordert nur, dass diejenigen, die seinen Rat suchen, ihren Mut und ihre Ausdauer in einem harten Kampf unter Beweis stellen, bevor er sie an eine weiterführende Kampfausbildung verweist.",al={"was will klannoc macleod","was will klannoc","klannoc zweck"}}},fp="15,346,25.330.0,10.352.0,23.214.0,33.185.0,54.232.0,19.252.0,37.191.0,46.174.1"}
P.entries["npc:kor-ghan"] = {n="Kor'ghan",s="Kor'ghan ist ein Dschungeltroll der Dunkelspeere, der sich in den düsteren Höhlen der Kluft der Schatten in Orgrimmar aufhält. Direkt vor Rekkul's Poisons bittet er um Unterstützung bei der Zubereitung von Heilmitteln gegen giftige Raubtiere der Wildnis.",h="Kor'ghan ist ein Dschungeltroll der Dunkelspeere, der sich in den düsteren Höhlen der Kluft der Schatten in...",kw={"gegengift","die kluft der schatten","kor'ghan","korghan","orgrimmar","rekkul's poisons","skorpiongift","sen'jin"},ang={["class:Rogue"]="Direkt vor Rekkul's Poisons in der Kluft der Schatten postiert, ist Kor'ghan ein vertrauter Anblick für Schurken, die die Schattenseiten von Orgrimmar auf der Suche nach Reagenzien und Giften aufsuchen.",["race:Troll"]="Wie viele seiner Dunkelspeer-Verwandten, die Sen'jin verlassen haben, nutzt Kor'ghan sein praktisches Wissen über die wilden Gefahren Durotars in der befestigten Hauptstadt der Horde."},sec={{t="Ein Troll in den Schatten",b="Vor Rekkul's Poisons in den höhlenartigen Tiefen der Kluft der Schatten wacht Kor'ghan sowohl über Heilmittel als auch über Toxine. Von der Hauptstadt aus entsendet er Abenteurer durch die roten Schluchten, um giftige Bestandteile von den Skorpione Durotars zu sammeln und so lebenswichtige Gegengifte herzustellen."}},faq={{q="Wer ist Kor'ghan?",a="Kor'ghan ist ein Dunkelspeer-Troll in der Kluft der Schatten in Orgrimmar, der vor Rekkuls Giftladen steht.",al={"kor'ghan","wer ist kor'ghan","korghan nsc"}},{q="Wo kann ich Kor'ghan finden?",a="Er befindet sich in der unterirdischen Kluft der Schatten unter dem Zentrum von Orgrimmar, direkt vor Rekkul's Poisons.",al={"kor'ghan aufenthaltsort","wo ist korghan","korghan finden"}},{q="Wobei benötigt Kor'ghan Hilfe?",a="Er bittet Reisende darum, Giftbeutel von den Giftschwanzskorpionen zu sammeln, die nahe dem Eingang von Orgrimmar umherstreifen, um bei der Herstellung von Gegengiften zu helfen.",al={"kor'ghan quest","suche nach dem gegengift quest","korghan gift"}},{q="War Kor'ghan jemals in Durotar anzutreffen?",a="Er selbst nicht. Kor'ghan bleibt an seinem Platz nahe den Giftlieferanten in Orgrimmar, doch er schickt Abenteurer nach Durotar hinaus, um Giftbeutel von den Giftschwanzskorpionen nahe dem Stadttor zu beschaffen.",al={"kor'ghan sen'jin","korghan alter aufenthaltsort"}}},fx={["8434b88c"]={q="Auf wessen Seite steht Kor'ghan?",a="Kor'ghan gehört zur Horde. Als Dschungeltroll der Dunkelspeere, der tief in der Kluft der Schatten in Orgrimmar lebt, gilt seine Loyalität fest seinem Volk und der neuen Heimat, die sie unter Kriegshäuptling Thrall teilen.",al={"kor'ghan fraktion","ist kor'ghan horde","kor'ghan allianz oder horde"}},["041d8a17"]={q="Warum ist Kor'ghan hier?",a="Kor'ghan hat seinen Platz direkt vor Rekkuls Gifte in den schattigen Tiefen der Kluft der Schatten. Er hält sich bei den Schurken und Alchemisten der Stadt auf und sucht bei denjenigen, die mit gefährlichen Mixturen handeln, nach spezieller Hilfe und giftigen Heilmitteln.",al={"warum ist kor'ghan in orgrimmar","warum ist kor'ghan in der kluft der schatten","was brachte kor'ghan hierher"}}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:korran"] = {n="Korran",s="Korran ist ein Forscher der Dunkelspeertrolle, der im Wegekreuz im Brachland stationiert ist. Im Dienste von Belgrom Rockmaul in Orgrimmar überwacht er merkwürdige Vorkommnisse im gesamten Buschland und erforscht die aufkeimende Bedrohung durch die insektoiden Silithiden.",h="Korran ist ein Forscher der Dunkelspeertrolle, der im Wegekreuz im Brachland stationiert ist.",kw={"brachland","belgrom rockmaul","das wegekreuz","eierjagd","feld der riesen","korran","silithid"},ang={["faction:Horde"]="Korran verkörpert das wachsame Auge der Horde auf die sich wandelnde Ökologie Kalimdors und stellt sicher, dass neue Bedrohungen wie die Silithiden Orgrimmar nicht unvorbereitet treffen, während es seine Grenzen sichert.",["race:Troll"]="Als Dunkelspeertroll bringt Korran scharfe Späher- und Überlebensinstinkte in das trockene Brachland ein und setzt pragmatische Schläue ein, um seltsame, fremdartige Bestien zu analysieren."},sec={{t="Ein Späher im Wegekreuz",b="Während sich die meisten im Wegekreuz mit aggressiven Borstennacken und lokalen Zentaurenklans befassen, hält Korran ein wachsames Auge auf subtilere, heimtückischere Gefahren gerichtet. Auf Befehl von Belgrom Rockmaul in Orgrimmar stationiert, beobachtet der Trollspäher das sich verändernde Land und koordiniert das Sammeln von Informationen für die Führung der Horde."},{t="Der Silithideneinfall",b="Korrans Hauptaugenmerk hat sich nach Süden zum Feld der Riesen verlagert, wo seltsame insektoide Kreaturen, bekannt als Silithiden, damit begonnen haben, sich in die Erde einzugraben. Beunruhigt über ihre aggressive Natur und ihr rasches Vordringen wirbt er vorbeiziehende Abenteurer an, um mithilfe seines Klauenwerkzeugs intakte Eier auszugraben, in dem Versuch zu entschlüsseln, woher der Schwarm stammt und welche Gefahr er für die junge Horde darstellt."}},faq={{q="Wer ist Korran?",a="Korran ist ein Dunkelspeertroll, der im Wegekreuz im Brachland stationiert ist. Er fungiert als Beobachter und Forscher, der Belgrom Rockmaul in Orgrimmar Bericht erstattet.",al={"wer ist korran","korran troll","das wegekreuz troll"}},{q="Was untersucht Korran im Brachland?",a="Er untersucht die seltsamen, aggressiven insektoiden Kreaturen, die als Silithiden bekannt sind und im Südlichen Brachland am Feld der Riesen aufgetaucht sind, sowie ähnliche Schwärme, die weiter südlich in Tausend Nadeln gemeldet wurden.",al={"was erforscht korran","korran forschung","feld der riesen insekten"}},{q="Für wen arbeitet Korran?",a="Korran dient Belgrom Rockmaul, einem erfahrenen Krieger, der im Tal der Ehre in Orgrimmar stationiert ist und für die Horde aufkommende Bedrohungen in ganz Kalimdor überwacht.",al={"wer schickte korran","korrans vorgesetzter","belgrom rockmaul"}},{q="Warum braucht Korran Silithideneier?",a="Er benötigt intakte Eier, um den Lebenszyklus und die Ursprünge des Silithidenschwarms zu untersuchen. Durch das Studium früher Exemplare hofft Korran zu verstehen, worum es sich bei diesen Kreaturen handelt, und festzustellen, wie groß die Bedrohung für das Territorium der Horde ist.",al={"warum silithideneier","eierjagd quest","korrans klaue"}}},fx={b07b8377={q="Auf wessen Seite steht Korran?",a="Korran ist ein treuer Späher der Horde, der am Wegekreuz stationiert ist. Er berichtet direkt an Belgrom Felsenhauer, einen bedeutenden Offizier in Orgrimmar, und hält das Kommando des Kriegshäuptlings über seltsame Unruhen im Brachland auf dem Laufenden.",al={"korran fraktion","ist korran horde","korran loyalität"}}},fp="6,229,25.335.0,22.389.0,14.158.0,44.220.0,25.157.0,35.226.0"}
P.entries["npc:kravel-koalbeard"] = {n="Kravel Kohlebart",s="Kravel Kohlebart ist ein intrigantes Zwergen-Schlitzohr und Gauner, der auf der Illusionenrennbahn in der schimmernden Ebene stationiert ist. Anstatt rein aus Liebe zum Sport mitzufiebern, betrachtet er die erbitterte Rennrivalität zwischen Gnomen und Goblins als goldene Gelegenheit, sich die Taschen vollzustopfen. Vom Bergen herrenloser Maschinenteile bis hin zur Manipulation von Rennergebnissen durch Erpressung und Alkohol ist Kravel stets auf der Jagd nach seinem nächsten profitablen Coup.",h="Kravel Kohlebart ist ein intrigantes Zwergen-Schlitzohr und Gauner, der auf der Illusionenrennbahn in der...",kw={"erpressung","koalbeard","kravel","illusionenrennbahn","raketenwagen","sabotage","die schimmernde ebene","tausend nadeln"},ang={["class:Rogue"]="Schurken wird Kravels Metier vertraut sein: Diebstahl, Sabotage, Erpressung und das Manipulieren gieriger Zielpersonen aus den Schatten heraus.",["race:Dwarf"]="Im Gegensatz zu den ehrlichen Bergleuten, Prospektoren und Gebirgsjägern von Eisenschmiede ist Kravel ein unverfrorener Gauner und Betrüger, der traditionelle Zwergentugenden mit Füßen tritt.",["race:Gnome"]="Gnome sollten in Kravels Nähe ihre Getränke und Baupläne gut im Auge behalten, da er ebenso erpicht darauf ist, Gnomenpiloten zu betäuben, wie ihre Maschinen zu sabotieren."},sec={{t="Ein Gauner in der Ebene",b="Während die meisten Zuschauer und Crewmitglieder auf der Illusionenrennbahn ganz von mechanischen Rivalitäten und dem Dröhnen der Raketenmotoren eingenommen sind, hat Kravel Kohlebart ein wachsames Auge auf die Geldbeutel aller Beteiligten geworfen. Er ist ein Opportunist, der in den staubigen Winkeln des Rennlagers agiert und stets bereit ist, Verträge und Gefälligkeiten anzubieten, die selten lautere Motive haben. Kravel sieht in den brisanten Spannungen zwischen gnomischen und goblinischen Ingenieuren keinen inspirierenden Wettstreit, sondern einen fruchtbaren Nährboden für Erpressung, Sabotage und Diebstahl."},{t="Manipulation an der Rennstrecke",b="Kravels Machenschaften reichen weit über das Auflesen von weggeworfenem Schrott auf den Salzebenen hinaus. Um die Quoten zu manipulieren und sicherzustellen, dass die Ergebnisse zu seinen Gunsten ausfallen, schickt Kravel bereitwillige Abenteurer auf illegale Botengänge – er streut Gerüchte, fädelt Erpressungen ein und betrinkt Boxencrews sogar kurz vor einem Showdown. Ob er nun Goblinmechaniker mit hochprozentigen Spirituosen abfüllt oder Gnomenpiloten starke Drinks unterjubelt – Kravel schreckt vor keinem hinterhältigen Trick zurück, wenn es darum geht, sich am Renntag die Taschen zu füllen."}},faq={{q="Wer ist Kravel Kohlebart?",a="Kravel Kohlebart ist ein zwergischer Ränkeschmied und Opportunist, der auf der Illusionenrennbahn in der schimmernden Ebene anzutreffen ist. Er nutzt die Rivalität zwischen Gnomen und Goblins aus, um sich durch Schrottverwertung, Rennmanipulation und Erpressung die Taschen vollzuschlagen.",al={"wer ist kravel","identität von kravel kohlebart","illusionenrennbahn zwerg"}},{q="Was tut Kravel Kohlebart auf der Illusionenrennbahn?",a="Kravel heuert Reisende an, um zwielichtige Besorgungen rund um die Rennstrecke zu erledigen. Zu seinen Plänen gehört das Sammeln geborgener Raketenwagenteile, das Aufspüren von Erpressungsmaterial und das Sabotieren von Rennteams, indem er deren Mechaniker und Piloten betrinkt, um die Rennergebnisse zu beeinflussen.",al={"kravel zweck","was will kravel","kravel pläne"}},{q="Warum versucht Kravel, die Renncrews betrunken zu machen?",a="Kravel setzt hohe Wetteinsätze auf den Ausgang der Raketenwagenrennen. Indem er entweder die Gnome oder die Goblins vor dem Rennen betrunken macht, manipuliert er den Wettbewerb zugunsten des Ergebnisses, das ihm den größten Profit einbringt.",al={"gnome betrinken quest","goblins betrinken","kravel sabotage"}},{q="Wo ist Kravel Kohlebart zu finden?",a="Er befindet sich in der schimmernden Ebene in Tausend Nadeln, wo er sich direkt bei den geschäftigen Lagern an den Boxengassen der Illusionenrennbahn herumtreibt.",al={"kravel aufenthaltsort","wo ist kravel","kravel tausend nadeln"}},{q="Hat Kravel Verbindungen außerhalb von Tausend Nadeln?",a="Ja. Seine zwielichtigen Geschäfte schließen Kontakte in den Goblinhäfen Ratschet und Beutebucht ein, darunter Abmachungen mit Werftmeister Flunkerblick aus Ratschet, Gerüchtehändlern und Händlern exotischer Gebräue aus dem Schlingendorntal.",al={"kravel beutebucht","kravel verbindungen"}},{q="Arbeitet Kravel sowohl mit der Allianz als auch mit der Horde zusammen?",a="Wie viele Persönlichkeiten an neutralen Schauplätzen wie der Illusionenrennbahn ist Kravel an Gold statt an Fraktionstreue interessiert. Er heuert mit Freuden sowohl Abenteurer der Allianz als auch der Horde an, um seine Vorhaben in die Tat umzusetzen.",al={"ist kravel nur allianz","kann horde mit kravel sprechen"}}},fx={["33aea695"]={q="Was will Kravel Kohlebart?",a="Kravel ist ausschließlich von Profit und Eigennutz getrieben. Er versucht, sich auf dem Brachland in der schimmernden Ebene durch alle verfügbaren Methoden die Taschen zu füllen, von der Beschaffung von Teilen und dem Feilbieten von Gefälligkeiten bis hin zur Organisation von Erpressungen. Sein kühnster Ehrgeiz ist die Manipulation der Illusionenrennbahn selbst, wobei er plant, die Wettbewerbe zu sabotieren und zu manipulieren, indem er die Boxencrews und Fahrer gründlich betrunken macht.",al={"was will kravel","kravel kohlebart ziele","kravel beweggründe"}},["97572808"]={q="Warum ist Kravel Kohlebart in Tausend Nadeln?",a="Die Illusionenrennbahn in der schimmernden Ebene ist ein gesetzloses Zentrum für Glücksspiele mit hohen Einsätzen, erbitterte Rivalität und rücksichtslose Ingenieurskunst, was sie zu einem erstklassigen Jagdrevier für einen Betrüger macht. Kravel hat sein Lager neben den konkurrierenden Gnomen und Goblins aufgeschlagen, weil ihre bittere Besessenheit, einander zu besiegen, sie blind für Opportunisten und leichte Opfer seiner Machenschaften macht.",al={"warum ist kravel hier","warum ist kravel an der illusionenrennbahn","kravel schimmernde ebene"}}},fp="16,424,25.509.0,17.494.1,24.220.0,52.252.0,45.208.0,36.127.0,47.201.0,46.215.0"}
P.entries["npc:kreldig-ungor"] = {n="Kreldig Ungor",s="Kreldig Ungor ist ein geschäftstüchtiger Zwergenagent, der Reclaimers Inc. vertritt und hoch oben in den Klippen der Nijelspitze in Desolace stationiert ist. Mit der Leitung von Feldeinsätzen im kargen Ödland betraut, heuert er Abenteurer der Allianz an, um verlorene Fracht zu bergen und wertvolle lokale Reagenzien zu sichern. Seine Bergungs- und Beschaffungsaufträge machen ihn zu einer zentralen Anlaufstelle für Reisende, die sich durch die feindselige Region bewegen.",h="Kreldig Ungor ist ein geschäftstüchtiger Zwergenagent, der Reclaimers Inc.",kw={"allianz","desolace","zwerg","karnitol schiffswrack","kreldig ungor","die nijelspitze","reclaimers inc","bergung"},ang={["faction:Alliance"]="Auf der Nijelspitze stationiert, ist Kreldig vollkommen auf Reisende der Allianz angewiesen, um seine Bergungsaufträge in einem ansonsten feindseligen Gebiet voranzutreiben.",["race:Dwarf"]="Kreldig verkörpert die klassische Vorliebe der Zwerge für unerschrockene Grenzlandexpeditionen und wirtschaftlichen Ehrgeiz, indem er sich fernab der heimischen Berghallen niederlässt."},sec={{t="Feldagent im Ödland",b="Die Nijelspitze bietet der Allianz eine seltene Zuflucht inmitten der verheerten Schluchten von Desolace, was sie zu einer idealen Operationsbasis für wirtschaftliche Opportunisten wie Kreldig Ungor macht. Als Vertreter von Reclaimers Inc. hat sich Kreldig weit aus der Sicherheit von Khaz Modan in eine trostlose Wildnis gewagt, die von Zentaurenklans, Dämonen und der Horde umkämpft wird. Wo andere nur Ruinen und Asche sehen, erkennt Kreldig ungenutzten Profit und verlorene Güter, die nur darauf warten, geborgen zu werden."},{t="Der Karnitol-Auftrag",b="Eines der Hauptunterfangen, die Kreldig nach Desolace führen, dreht sich um das verschollene Schiff von Karnitol, das an der tückischen Westküste zerschellte. Karnitols Ladung enthielt kostbare Waren, und Kreldig koordiniert die Bemühungen, die Trümmer aufzuspüren und das verstreute Frachtgut zu bergen, bevor Plünderer oder Meeresriesen der Küste alles an sich reißen können."},{t="Beschaffung lokaler Reagenzien",b="Neben der Bergung von Schiffsgütern überwacht Kreldig für Reclaimers Inc. die Beschaffung von Desolaces seltsamen biologischen und mineralischen Schätzen. Die raue Umgebung bringt eine einzigartige Flora und Fauna hervor, deren Bestandteile bei Alchemisten und Ingenieuren in den Östlichen Königreichen hohe Preise erzielen. Abenteurer, die bereit sind, den Raubtieren des Ödlands zu trotzen, finden in Kreldigs Auftragsbuch eine verlässliche Einnahmequelle."}},faq={{q="Wer ist Kreldig Ungor?",a="Kreldig Ungor ist ein Zwergenagent, der für Reclaimers Inc. arbeitet und seinen Stützpunkt im Außenposten der Allianz auf der Nijelspitze in Desolace hat. Er koordiniert Bergungsmissionen und das Sammeln von Proben im gesamten Gebiet.",al={"kreldig ungor geschichte","wer ist kreldig","kreldig ungor"}},{q="Was ist Reclaimers Inc.?",a="Reclaimers Inc. ist ein unternehmerisches Projekt, das darauf ausgerichtet ist, verlorene Fracht zu bergen, Wracks auszuschlachten und seltene Reagenzien in gefährlichen Grenzgebieten gewinnbringend zu sammeln.",al={"reclaimers inc","wer sind reclaimers inc","reclaimers unternehmen"}},{q="Wo ist Kreldig Ungor zu finden?",a="Er befindet sich in der Allianzsiedlung auf der Nijelspitze, hoch oben in den felsigen Bergen im Nordosten von Desolace.",al={"kreldig ungor standort","wo ist kreldig","kreldig ungor finden"}},{q="Was bezweckt Kreldig mit dem Schiffswrack von Karnitol?",a="Ein Schiff mit wertvollen Gütern von Karnitol erlitt an der Küste von Desolace Schiffbruch. Kreldig heuert Abenteurer an, um das Wrack aufzuspüren und die verlorene Fracht zu sichern, bevor sie geplündert oder zerstört wird.",al={"karnitol schiffswrack","kreldig karnitol","desolace schiffswrack"}},{q="Warum sammelt Kreldig Reagenzien in Desolace?",a="Die raue Umgebung von Desolace bringt seltene Kreaturen und einzigartige natürliche Substanzen hervor. Kreldig sammelt diese Proben, um Alchemisten, Handwerker und Käufer in den großen Städten der Allianz zu beliefern.",al={"reagenzien für reclaimers inc","desolace reagenzien","warum reagenzien sammeln"}},{q="Arbeitet Kreldig für Eisenschmiede oder ein Privatunternehmen?",a="Obwohl er von einem Allianzaußenposten aus operiert und ausschließlich Reisende der Allianz anheuert, vertritt Kreldig Reclaimers Inc. – ein kommerzielles Unternehmen, das auf Bergung und Handel setzt, statt offizielle königliche Militärziele zu verfolgen.",al={"kreldig allianz oder privat","reclaimers inc eisenschmiede"}}},fx={ad7684ca={q="Warum ist Kreldig Ungor in der Nijelspitze stationiert?",a="Kreldig Ungor hat sich hoch oben in der Nijelspitze niedergelassen, um für Reclaimers Inc. in der rauen Weite von Desolace geschäftliche Unternehmungen zu verfolgen. Von diesem befestigten Zufluchtsort der Allianz aus überwacht er Bergungs- und Beschaffungsoperationen in relativer Sicherheit und nutzt ihn als Basis, um zähe Abenteurer für Unternehmungen in die gefährlichen Einöden anzuheuern.",al={"warum ist kreldig ungor hier","kreldig ungor nijelspitze","warum ist kreldig in desolace"}}},fp="13,399,25.429.0,21.323.0,25.373.0,21.203.0,24.163.0,33.120.0,51.197.0,47.195.0,56.219.0"}
P.entries["npc:krolg"] = {n="Krolg",s="Krolg ist ein nicht korrumpierter Furbolg, der in einer isolierten Hütte südlich des Mystralsees im Eschental lebt. Er war früher ein Mitglied des Stammes der Foulweald, hat sich jedoch von seinen Verwandten losgesagt, die dem dämonischen Wahnsinn anheimfielen, und spricht nur mit denjenigen, die ihm in Furbolggestalt entgegentreten.",h="Krolg ist ein nicht korrumpierter Furbolg, der in einer isolierten Hütte südlich des Mystralsees im Eschental...",kw={"furbolg im eschental","häuptling murgut","dartols rute","foulweald","krolg","krolgs hütte","mystralsee","raenes säuberung"},ang={["class:Druid"]="Druiden, die das Gleichgewicht im Eschental wiederherstellen wollen, finden in Krolg eine unschätzbare, klare Stimme inmitten einer Landschaft, die von korrumpierter Tierwelt überrannt wird.",["faction:Alliance"]="Kundschafter der Allianz, die Raene Wolfsläufer unterstützen, verlassen sich auf Krolg, um die Führung der feindseligen Furbolgs der Foulweald auszuschalten.",["race:NightElf"]="Für die Nachtelfen von Astranaar stellt Krolg eine bittersüße Erinnerung an ihre alten Furbolg-Verbündeten dar, bevor die dämonische Verderbnis die Stämme zerrüttete."},sec={{t="Ein ungebrochener Geist",b="Während die meisten Furbolgs der Foulweald im Eschental der dämonischen Verderbnis der Brennenden Legion zum Opfer gefallen sind, bleibt Krolg klar bei Verstand und unberührt vom Wahnsinn. Er lebt in einer abgeschiedenen Zuflucht südlich des Mystralsees und hält vorsichtig Wache über den Wald. Da er den tragischen Abstieg seiner Brüder in sinnloses Gewaltverbrechen miterlebt hat, weigert er sich, mit Außenstehenden auf den ersten Blick zu interagieren, und spricht nur mit Wesen, die wie seinesgleichen erscheinen."},{t="Dartols Vermächtnis",b="Durch die magische Verzauberung von Dartols Rute der Transformation können sich Reisende der Allianz die Gestalt eines Furbolgs geben. Wenn Krolg sieht, was wie ein freundlicher, gleichgesinnter Geist erscheint, öffnet er sich und enthüllt entscheidende Erkenntnisse zur Säuberung des Landes. Er weist Helden an, gegen Ran Bloodtooth und seine Wachen vorzugehen, deren Verderbnis und Hass den Wald bedrohen."}},faq={{q="Warum will Krolg nicht mit mir sprechen?",a="Krolg ist gegenüber Außenstehenden zutiefst misstrauisch und hat Angst vor dem gewaltsamen Chaos, das den Wald verzehrt. Er wird Euch völlig ignorieren, es sei denn, Ihr befindet Euch unter der Wirkung der Furbolg-Verwandlung, die Ihr durch Dartols Rute der Transformation während der Questreihe „Raenes Säuberung“ erhaltet.",al={"krolg spricht nicht","kann nicht mit krolg sprechen","warum schweigt krolg"}},{q="Wo kann man Krolg finden?",a="Er lebt in einer kleinen Zuflucht, bekannt als Krolgs Hütte, die sich direkt südlich des Mystralsees im südlich-zentralen Eschental befindet.",al={"krolg standort","wo ist krolg","krolgs hütte"}},{q="Zu welchem Stamm gehört Krolg?",a="Krolg war ursprünglich Teil des Stammes der Foulweald. Im Gegensatz zum Rest seiner Verwandten, die der Verderbnis und dem dämonischen Rausch verfielen, bewahrte er seinen Verstand und brach alle Verbindungen zu ihnen ab.",al={"krolg stamm","ist krolg ein foulweald"}},{q="Ist Krolg Spielern gegenüber feindselig?",a="Krolg greift Außenstehende an, die sich ihm nähern, ohne die Furbolg-Verwandlung zu benutzen. Abenteurer müssen Dartols Rute der Transformation verwenden, bevor sie sich ihm nähern.",al={"greift krolg an","ist krolg feindlich"}},{q="Warum will Krolg, dass Ran Bloodtooth stirbt?",a="Krolg sieht Ran Bloodtooth als machtgierig an, der durch die Verderbnis gestärkt wurde. Obwohl Krolg die Nachtelfen für das Leid seiner Verwandten verantwortlich macht, lässt er nicht zu, dass Ran deren Kinder oder die anderen Kreaturen des Waldes bedroht.",al={"krolg ran bloodtooth","warum ran bloodtooth töten"}},{q="Wer war Dartol, dessen Rute es Abenteurern erlaubt, mit Krolg zu sprechen?",a="Dartol erschuf die verzauberte Rute der Transformation, die es ihrem Träger erlaubt, die Gestalt eines Furbolgs anzunehmen. Abenteurer nutzen die bereits wiederhergestellte Rute, um sich Krolg während „Raenes Säuberung“ zu nähern.",al={"wer ist dartol","hintergrund zu dartols rute"}}},fx={["4c25d8d9"]={q="Wer ist Krolg?",a="Krolg ist ein nicht korrumpierter Furbolg, der in selbstgewähltem Exil südlich des Mystralsees im Eschental lebt. Als ehemaliges Mitglied des Stammes der Foulweald gelang es ihm, der dunklen Verderbnis zu widerstehen, die seine Brüder befiel. Nun isoliert in seiner einfachen Hütte bewahrt er seinen Verstand und seine Weisheit, während er um das trauert, was aus seinem Volk geworden ist, und ist bereit, Außenstehenden zu helfen, die ihn in Furbolggestalt aufsuchen.",al={"wer ist krolg","krolg identität","wer ist der furbolg an krolgs hütte"}},["19bbdb38"]={q="Auf wessen Seite steht Krolg?",a="Krolg hat sich weder der Allianz noch der Horde verschrieben; er steht als einer der wenigen vernünftigen, nicht korrumpierten Furbolgs, die in der Region verblieben sind, allein. Er verhandelt jedoch nur mit Abenteurern der Allianz, die sich ihm mit Dartols Stab als Artgenossen getarnt nähern, und bietet ihnen im Kampf gegen die korrumpierten Foulweald Führung und rituelles Wissen an.",al={"ist krolg allianz oder horde","krolg fraktion","auf wessen seite steht krolg"}},["39fdb4f1"]={q="Was will Krolg?",a="Krolg sucht ein Ende für den Wahnsinn, der seine ehemaligen Verwandten zerstört. Er bittet transformierte Abenteurer, Ran Bloodtooth und seine Wachen zu erschlagen, da ihre Verderbnis die Nachtelfen und die anderen Kreaturen des Waldes bedroht.",al={"was will krolg","krolg beweggründe","krolg ziel"}},c40435aa={q="Warum ist Krolg hier?",a="Krolg floh von seinem Stamm und ließ sich südlich des Mystralsees nieder, weil er sich weigerte, sich der Verderbnis zu ergeben, die die Foulweald verformte. Das Leben in Isolation ermöglicht es ihm, sicher vor seinen wahnsinnig gewordenen ehemaligen Brüdern zu bleiben, während er ihr Territorium im Auge behält.",al={"warum ist krolg hier","warum hat krolg die foulweald verlassen","warum lebt krolg beim mystralsee"}}},fp="5,261,15.439.0,15.374.1,27.256.0,25.113.0,32.173.0,28.158.0,40.214.1,60.177.0"}
P.entries["npc:krom-stoutarm"] = {n="Krom Starkarm",s="Krom Starkarm ist ein zwergischer Gelehrter und Hexenmeister, der tief in der Library der Hall of Explorers in Eisenschmiede zu finden ist. Anders als die meisten seiner Artgenossen, die sich ausschließlich mit uraltem Gestein und Titanenrelikten befassen, studiert Krom dunklere, arkane Texte und dämonische Rituale. Er dient Hexenmeistern der Allianz, die in Kalimdor und den Östlichen Königreichen nach esoterischem Wissen suchen, als unverzichtbare Anlaufstelle.",h="Krom Starkarm ist ein zwergischer Gelehrter und Hexenmeister, der tief in der Library der Hall of Explorers...",kw={"hall of explorers","eisenschmiede","krom starkarm","library","starkarm","tome of the cabal","hexenmeister"},ang={["class:Warlock"]="Hexenmeister der Allianz müssen Krom bei der Ausübung dunkler Bindungen zu Rate ziehen, insbesondere bei der gefährlichen Aufgabe, den Tome of the Cabal zusammenzutragen.",["faction:Alliance"]="Krom bietet den verdeckten Praktizierenden der Allianz eine sichere geistige Zuflucht in den mächtigen Bergfestungen von Eisenschmiede.",["race:Dwarf"]="Zwerge verleugnen für gewöhnlich die finsteren Künste, weshalb Kroms Stellung inmitten der ehrwürdigen Regale der Hall of Explorers eine bemerkenswerte Seltenheit darstellt."},sec={{t="Eine dunklere Ecke der Halle",b="Die Hall of Explorers ist typischerweise für zwergische Archäologen bekannt, die von Spitzhacken, Schaufeln und Titanenartefakten besessen sind. Krom Starkarm gibt unter ihnen eine ungewöhnliche Gestalt ab. Umgeben von wuchtigen Wälzern hält er sich in der Library auf und widmet sich okkulten Überlieferungen sowie den Bindungsriten dämonischer Beschwörer. Seine Anwesenheit in Eisenschmiede beweist, dass Gelehrte und Praktizierende der verbotenen Künste nach wie vor in den Hallen der Bergstadt wirken, auch wenn die Hexenmeisterkünste weithin misstrauisch beäugt werden."},{t="The Tome of the Cabal",b="Wenn Hexenmeister der Allianz mächtige dämonische Diener wie den Teufelsjäger an sich binden wollen, kreuzt ihr Weg unweigerlich den von Krom. Da er über Wissen um verstreute okkulte Bände verfügt, schickt er angehende Beschwörer weit über die Meere – einschließlich gefährlicher Vorstöße in feindselige Gebiete wie das Brachland –, um zerrissene Seiten und Fragmente des berüchtigten Tome of the Cabal zu bergen."}},faq={{q="Wo kann ich Krom Starkarm finden?",a="Krom Starkarm befindet sich im Library-Flügel der Hall of Explorers in der Zwergenhauptstadt Eisenschmiede.",al={"krom starkarm aufenthaltsort","wo ist krom starkarm","krom starkarm eisenschmiede"}},{q="Welche Rolle spielt Krom Starkarm für die Spieler?",a="Krom dient Hexenmeistern der Allianz als entscheidender Quest-Kontakt bei ihren klassenprägenden dämonischen Ritualen und leitet sie insbesondere bei der Beschaffung des Tome of the Cabal an.",al={"was macht krom","krom starkarm aufgabe","krom starkarm quests"}},{q="Ist Krom Starkarm mit anderen Starkarms verwandt?",a="Mehrere Zwerge tragen den Nachnamen Starkarm, aber ein Verwandtschaftsverhältnis zwischen Krom und den anderen ist unbestätigt.",al={"krom verwandte","sten starkarm verwandt"}},{q="Warum ist ein Hexenmeister in der Hall of Explorers geduldet?",a="Krom ist sowohl ein Hexenmeister als auch ein Gelehrter, der in der Hall of Explorers tätig ist. Die Quelle erklärt nicht, unter welchen Bedingungen seine Arbeit gestattet ist.",al={"warum ist krom in hall of explorers","eisenschmiede hexenmeister erlaubt"}},{q="Warum steht Krom mit dem Brachland in Verbindung?",a="Bei seinen Nachforschungen über dunkle Manuskripte entsendet Krom Hexenmeister, um verlorene Teile des Tome of the Cabal zu bergen, wobei ein solches wichtiges Fragment in einer Truhe tief im von Stachelebern heimgesuchten Brachland verborgen liegt.",al={"krom starkarm brachland","warum brachland quest krom"}},{q="Bildet Krom Starkarm Zauber aus?",a="Krom ist eher ein gelehrter Questgeber als ein gewöhnlicher Klassenlehrer. Er leitet Hexenmeister bei bestimmten Übergangsriten an, anstatt alltägliche Zauberbücher zu lehren.",al={"kann krom mich ausbilden","krom hexenmeisterlehrer"}}},fx={["6ca19015"]={q="Wer ist Krom Starkarm?",a="Krom Starkarm ist ein Hexenmeister der Zwerge, der in der Library der Hall of Explorers in Eisenschmiede dunkles Wissen studiert. Im Gegensatz zu vielen Praktizierenden der Teufelsmagie, die sich in schattigen Kellern und abgelegenen Zirkeln verstecken, operiert Krom offen unter den Gelehrten und Ausgräbern der Forscherliga und vertieft sich in alte Relikte, obskure Arkana und okkulte Folianten.",al={"wer ist krom","krom starkarm lore","wer ist krom starkarm"}},["23fb54c2"]={q="Auf wessen Seite steht Krom Starkarm?",a="Krom Starkarm ist Eisenschmiede und der Allianz gegenüber loyal. Obwohl er Hexenmeisterkünste praktiziert, die bei vielen seiner Verwandten Argwohn und Unbehagen hervorrufen, bleibt er ein respektierter Gelehrter in der Hall of Explorers und bietet seine esoterische Expertise und sein arkanes Wissen ausschließlich an, um Champions der Allianz bei ihren Unternehmungen zu unterstützen.",al={"krom starkarm fraktion","krom starkarm allianz oder horde","wem dient krom"}}},fp="13,374,27.471.0,21.373.0,31.110.0,46.181.0,44.113.0,56.145.0,37.214.0,32.162.0"}
P.entries["npc:krusk"] = {n="Krusk",s="Krusk ist ein orkischer Späher, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Auf direkten Befehl von Kriegshäuptling Thrall entsandt, um das Syndikat zu untersuchen und Relikte aus den Ruinen von Burg Durnholde zu bergen, koordiniert er nun Aufklärungs- und Rettungsmaßnahmen, nachdem seine ursprüngliche Infiltration in einen Hinterhalt geriet.",h="Krusk ist ein orkischer Späher, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist.",kw={"drull","burg durnholde","gol'dir","hillsbrad","krusk","syndikat","tarrens mühle","thrall","tog'thar"},ang={["faction:Horde"]="Krusk vertritt Kriegshäuptling Thralls direkte Interessen in Lordaeron, wobei der Schwerpunkt auf der Sicherung von Durnholdes Geschichte liegt und darauf, keinen gefangenen Ork in den Händen des Syndikats zu lassen.",["race:Orc"]="Krusk bei der Rettung seiner Späherkameraden zu helfen, berührt die Ehre und die schmerzhafte Geschichte der orkischen Internierungslager – insbesondere jener Festung, in der Thrall die Ketten seines Volkes sprengte."},sec={{t="Eine schiefgelaufene Mission",b="Als Kriegshäuptling Thrall seine Aufmerksamkeit wieder den Ruinen von Burg Durnholde zuwandte, entsandte er Krusk und einen kleinen Stoßtrupp, um die Aktivitäten des Syndikats auszukundschaften und Relikte zu bergen, die mit der düsteren Vergangenheit der Festung verbunden sind. Die menschlichen Gesetzlosen erwiesen sich jedoch als verschanzter und koordinierter als erwartet. Ein Hinterhalt innerhalb der verfallenden Mauern von Durnholde überwältigte den orkischen Spähtrupp. Krusk gelang es, sich freizukämpfen, doch seine drei Gefährten – Gol'dir, Drull und Tog'thar – wurden gefangen genommen und tief in den Ruinen eingesperrt. Nachdem er sich in Tarrens Mühle neu formiert hat, leitet Krusk nun Abenteurer der Horde an, in Durnholde einzudringen, die verlorenen Gegenstände zu bergen und seine gefangenen Kameraden zu befreien."},{t="Das Syndikat im Visier",b="Neben der Rettung seiner Späher konzentriert sich Krusk weiterhin darauf, die Kontrolle des Syndikats über Hillsbrad zu brechen. Die gefallenen Adligen von Alterac stellen eine unberechenbare Bedrohung dar; sie operieren von Burg Durnholde aus und schmieden Ränke sowohl gegen die Außenposten der Horde als auch gegen ihre einstigen Brüder der Allianz. Von Tarrens Mühle aus verfolgt Krusk die Bewegungen von Anführern des Syndikats wie Lord Aliden Perenolde in der Hoffnung, deren Führung auszuschalten, bevor sie den unsicheren Stützpunkt der Horde in Lordaeron gefährden können."}},faq={{q="Wer ist Krusk?",a="Krusk ist ein orkischer Späher, der von Kriegshäuptling Thrall nach Tarrens Mühle geschickt wurde. Er wurde damit beauftragt, die Operationen des Syndikats rund um die Ruinen von Burg Durnholde zu untersuchen und historische Relikte zu bergen.",al={"krusk","wer ist krusk","krusk tarrens mühle"}},{q="Was geschah mit Krusks Trupp?",a="Krusk und sein Team gerieten in Burg Durnholde in einen Hinterhalt des Syndikats. Während Krusk entkommen konnte, wurden seine Gefährten Gol'dir, Drull und Tog'thar gefangen genommen und in der zerstörten Festung eingesperrt.",al={"krusk trupp","was geschah mit krusk","hinterhalt durnholde"}},{q="Warum interessiert sich die Horde für Burg Durnholde?",a="Durnholde besitzt eine tiefe persönliche und historische Bedeutung für Kriegshäuptling Thrall, der dort von Aedelas Blackmoore als gefangener Gladiator aufgezogen wurde, bevor er die orkische Rebellion anführte, die die Festung dem Erdboden gleichmachte.",al={"warum durnholde","thrall durnholde","durnholde relikte"}},{q="Wo kann ich Krusk finden?",a="Krusk befindet sich im Freien in der Hordesiedlung Tarrens Mühle im nördlichen Vorgebirge des Hügellands.",al={"krusk standort","wo ist krusk"}}},fx={["86db3c10"]={q="Auf wessen Seite steht Krusk?",a="Krusk ist ein loyaler Agent der Horde. Er wurde direkt unter dem Befehl von Kriegshäuptling Thrall ausgesandt und operiert von Tarrens Mühle aus, um die strategischen Interessen von Orgrimmar im gesamten Vorgebirge des Hügellands zu wahren.",al={"krusk fraktion","ist krusk horde","wem dient krusk"}},["943a1bb4"]={q="Was will Krusk?",a="Krusk benötigt fähige Champions, um seine gefangenen Gefährten – Gol'dir, Drull und Tog'thar – aus den Händen des Syndikats in den Ruinen von Burg Durnholde zu befreien. Er versucht außerdem, die Operationen des Syndikats aufzudecken und einen Gegenstand von großer Bedeutung zu sichern, der mit der Geschichte von Durnholde verbunden ist.",al={"was braucht krusk","krusk ziele","wonach sucht krusk"}},["2e7680ba"]={q="Warum ist Krusk hier in Tarrens Mühle?",a="Kriegshäuptling Thrall schickte Krusk und seinen Trupp persönlich in das Hügelland, um die Aktivitäten des Syndikats rund um Burg Durnholde zu untersuchen. Nachdem ein Hinterhalt seine Späher gefangen genommen hatte, zog sich Krusk nach Tarrens Mühle zurück, um sich neu zu formieren und Hilfe für den Abschluss der Mission anzuwerben.",al={"warum ist krusk im hügelland","krusk tarrens mühle warum","warum hat thrall krusk geschickt"}},cd66e870={q="Mit wem ist Krusk verbunden?",a="Krusk untersteht direkt Kriegshäuptling Thrall und führt eine Vorhut aus Orc-Spähern an, die aus Gol'dir, Drull und Tog'thar besteht. Von Tarrens Mühle aus koordiniert er seine Bemühungen zusammen mit der lokalen Garnison der Horde.",al={"krusk gefährten","krusk verbündete","mit wem arbeitet krusk zusammen"}}},fp="5,305,20.659.0,21.475.0,13.182.0,31.194.0,46.200.0,23.99.0"}
P.entries["npc:kuray-bin"] = {n="Kuray'bin",s="Kuray'bin ist ein Dschungeltroll-Späher der Dunkelspeer, der an einem Wachposten außerhalb vom Splitterholzposten in Eschental stationiert ist. Er behält die umliegenden Waldpfade im Auge, um nach Spähern der Nachtelfen Ausschau zu halten, die sich an das Lager der Horde heranschleichen.",h="Kuray'bin ist ein Dschungeltroll-Späher der Dunkelspeer, der an einem Wachposten außerhalb vom...",kw={"die kundschafter von eschental","dunkelspeer","kuray'bin","kuraybin","schildwachen der silberschwingen","splintertreeposten"},ang={["faction:Horde"]="Kuray'bin verkörpert die Wachsamkeit an vorderster Front, die erforderlich ist, damit der Splitterholzposten nicht von Guerillakämpfern der Nachtelfen umzingelt und überrannt wird.",["race:Troll"]="Wie viele Späher der Dunkelspeere im Dienst der Horde nutzt Kuray'bin seine Dschungel-Fährtenleserinstinkte, um Infiltratoren der Nachtelfen dort aufzuspüren, wo andere nur Bäume sehen."},sec={{t="Wachsame Augen am Waldrand",b="Gleich außerhalb vom Splitterholzposten stationiert, hält Kuray'bin Wache gegen Infiltrationen der Allianz in den tiefen Wäldern von Eschental. Die Schildwachen der Silberschwingen patrouillieren unablässig durch das umgebende Blätterdach und schicken wendige Kundschafter über die Grenze, um Informationen über die Holzfälleraktivitäten und Verteidigungsanlagen der Horde zu sammeln. Da er weiß, dass unbeobachtete Späher schnell zu Hinterhaltstruppen werden, weist Kuray'bin fähige Kämpfer der Horde an, die Kundschafter zur Strecke zu bringen, bevor sie den Silberschwingen Bericht erstatten können."}},faq={{q="Wer ist Kuray'bin?",a="Kuray'bin ist ein Wächter der Dunkelspeertrolle, der vor dem Splitterholzposten in Eschental stationiert ist. Er beauftragt Abenteurer der Horde damit, feindselige Späher der Nachtelfen zu dezimieren, die im umliegenden Wald lauern.",al={"kuraybin","wer ist kuraybin","splintertree trollspäher"}},{q="Wo kann ich Kuray'bin finden?",a="Er befindet sich direkt vor den Palisadentoren vom Splitterholzposten und bewacht die Zugangsstraßen im zentralen Osten von Eschental.",al={"kuraybin aufenthaltsort","wo ist kuraybin"}},{q="Warum will Kuray'bin die Kundschafter der Silberschwingen tot sehen?",a="Die Kundschafter sind Schildwachen der Silberschwingen, die sich nah an den Splitterholzposten heranschleichen. Kuray'bin will sie ausschalten, bevor sie taktische Informationen über die Stellungen der Horde sammeln oder Überraschungsangriffe koordinieren können.",al={"warum kundschafter töten","die kundschafter von eschental quest lore"}},{q="Bietet Kuray'bin noch weitere Aufgaben an?",a="Nein. Seine einzige Pflicht an den Außenbezirken des Außenpostens besteht darin, die Aufklärung gegen die schwer fassbaren Kundschafter der Nachtelfen zu überwachen.",al={"kuraybin quests","kuray bin aufgabe"}}},fx={["65134a3b"]={q="Auf wessen Seite steht Kuray'bin?",a="Kuray'bin dient der Horde. Er ist direkt außerhalb des Splitterholzpostens stationiert, arbeitet daran, die Siedlung gegen Einfälle der Allianz zu sichern und hält Wache über die umkämpften Grenzen des Eschentals.",al={"kuraybin fraktion","wem dient kuraybin","ist kuraybin horde"}},bfddbb0e={q="Warum ist Kuray'bin hier im Eschental stationiert?",a="Kuray'bin hält an einem Außenposten direkt außerhalb des Splitterholzpostens Wache, um feindliche Bewegungen zu beobachten. Da Späher der Nachtelfen tief in das Territorium der Horde eindringen, ist es seine Aufgabe, Bedrohungen zu erkennen, bevor sie die Siedlung angreifen.",al={"warum ist kuraybin hier","kuraybin zweck eschental","warum ist kuraybin am splitterholzposten"}},["189aca6f"]={q="Mit wem ist Kuray'bin verbunden?",a="Kuray'bin ist direkt mit der Garnison der Horde am Splitterholzposten verbunden. Als Späher der Dschungeltrolle arbeitet er in Abstimmung mit den Orcs und anderen Verteidigern, die diesen unsicheren Stützpunkt im Eschental gegen die Nachtelfen halten.",al={"kuraybin verbindungen","kuraybin verbündete","mit wem arbeitet kuraybin zusammen"}}},fp="9,211,23.484.0,17.191.0,27.126.0,55.211.0,37.117.0"}
P.entries["npc:kzan-thornslash"] = {n="Kzan Dornenhieb",s="Kzan Dornenhieb ist ein Orc-Waffenhändler, der im Tal der Prüfungen in Durotar stationiert ist. Er versorgt neue Rekruten, die ihre Ausbildung bei der Horde beginnen, mit grundlegenden Anfangswaffen und Vorräten.",h="Kzan Dornenhieb ist ein Orc-Waffenhändler, der im Tal der Prüfungen in Durotar stationiert ist.",kw={"durotar","horde","kzan","orc","thornslash","das tal der prüfungen","waffenhändler","waffen"},ang={["class:Warrior"]="Für junge Krieger, die mit schartigen Klingen beginnen, bietet Kzan eine sofortige Auswahl an Hieb- und Klingenwaffen, passend für verschiedene Kampfdisziplinen.",["faction:Horde"]="Die Versorgung von Thralls heranwachsenden Streitkräften beginnt ganz unten, wo Händler wie Kzan dafür sorgen, dass jede fähige Hand Stahl für die Horde führen kann."},sec={{t="Rüstmeister der Rekruten",b="In der staubigen roten Schlucht des Tals der Prüfungen dient Kzan Dornenhieb als wichtigster Waffenhändler für junge Orcs und Dunkelspeere, die ihre ersten Schritte als Krieger der Horde machen. Mit einem Sortiment an grundlegenden Rüstgütern – von einfachen Handäxten und Kurzschwertern bis hin zu Knüppeln und Wurfmessern – sorgt Kzan dafür, dass die frisch erwachten Anwärter angemessen bewaffnet sind, um der einheimischen Tierwelt und den regionalen Gefahren zu trotzen."}},faq={{q="Wer ist Kzan Dornenhieb?",a="Kzan Dornenhieb ist ein Orc-Händler, der im Tal der Prüfungen stationiert ist. Seine Aufgabe ist es, neue Rekruten der Horde mit Standardwaffen zu versorgen, die für ihre ersten Kampfprüfungen geeignet sind.",al={"kzan dornenhieb","wer ist kzan","waffenhändler tal der prüfungen"}},{q="Wo kann ich Kzan Dornenhieb finden?",a="Er steht auf den offenen Übungsplätzen im Tal der Prüfungen im südwestlichen Durotar, umgeben von angehenden Abenteurern und Ausbildern.",al={"kzan standort","wo ist kzan dornenhieb","karte kzan dornenhieb"}},{q="Welche Art von Ausrüstung verkauft Kzan?",a="Kzan bietet grundlegende Anfangswaffen an, darunter Äxte, Schwerter, Dolche, Stäbe, Keulen und Wurfwaffen für Rekruten, die verlässliches Eisen benötigen, bevor sie geschmiedete oder gefundene Ausrüstung erlangen.",al={"was verkauft kzan","kzan gegenstände","kzan waffen"}}},fx={feb30cb2={q="Auf wessen Seite steht Kzan Dornenhieb?",a="Kzan Dornenhieb steht fest auf der Seite der Horde. Er operiert innerhalb des Tals der Prüfungen, untersteht der Autorität von Orgrimmar und Thralls neuer Nation und rüstet die jungen Orcs und Trolle aus, die ankommen, um ihre Stärke und Loyalität in Durotar unter Beweis zu stellen.",al={"kzan dornenhieb fraktion","wem dient kzan","ist kzan horde"}},["1bbcac80"]={q="Warum ist Kzan Dornenhieb im Tal der Prüfungen?",a="Kzan bleibt im Tal der Prüfungen, um aufstrebende Rekruten und Krieger auszurüsten, die sich auf ihre ersten Prüfungen begeben. In einem rauen, ariden Übungsgelände, das von Skorpionen, Ebern und Vile Familiars überrannt wird, benötigt ein unerprobter Kämpfer zuverlässigen Stahl, Keulen und Klingen, um seine Tests zu überleben.",al={"warum ist kzan dornenhieb hier","kzan tal der prüfungen rolle","was macht kzan"}},c4565150={q="Was will Kzan Dornenhieb?",a="Kzan möchte die Rekruten mit den Waffen versorgen, die sie benötigen, während er seinen Handel in Durotar aufrechterhält. Durch seine Geschäfte mit jungen Kriegern stellt er sicher, dass die jungen Verteidiger der Horde angemessen mit grundlegenden Waffen ausgestattet sind, um ihre neu besiedelten Länder zu verteidigen.",al={"was will kzan","kzan dornenhieb beweggrund","kzan dornenhieb ziel"}}},fp="15,199,23.433.0,23.172.0,33.161.0,38.192.0"}
P.entries["npc:lady-anacondra"] = {n="Lady Anakondra",s="Lady Anakondra ist eine der Giftzahnfürsten, die die Druiden des Giftzahns in den Höhlen des Wehklagens anführen. Einst eine Nachtelfenakolytin namens Scarletleaf, meldete sie sich als Erste freiwillig für Naralex' ehrgeiziges Vorhaben, das Brachland zu heilen. Als die Zwiesprache ihres Meisters mit dem Smaragdgrünen Traum in einen Albtraum umschlug, zerbrach ihr Geist, was ihre Hingabe in den giftigen Drang verwandelte, Kalimdor von Schlangen überrennen zu sehen.",h="Lady Anakondra ist eine der Giftzahnfürsten, die die Druiden des Giftzahns in den Höhlen des Wehklagens...",kw={"anacondra","brachland","druiden des giftzahns","giftzahnfürst","edelstein von anacondra","lady anakondra","naralex","scarletleaf","die höhlen des wehklagens"},ang={["class:Druid"]="Anacondra verkörpert eine mahnende Tragödie für die Druiden des Cenarius: eine aufrichtige Akolytin, deren Eifer bei der Heilung des Landes sie anfällig für den Albtraum machte, der ihre Zwiesprache in den Wahnsinn trieb.",["faction:Horde"]="Die Horde kann nicht zulassen, dass Anacondra und die Giftzahnfürsten die empfindlichen Lebensadern des Brachlands bedrohen, weshalb ihre Beseitigung unerlässlich ist, um das Wegekreuz und die nahegelegenen Oasen zu sichern.",["race:NightElf"]="Zu sehen, wie eine Schwester der Kaldorei ihr Erbe und ihre Gestalt im Streben nach einem finsteren, schlangenhaften Traum aufgibt, ist eine ernüchternde Mahnung an die Gefahren, die im Smaragdgrünen Traum lauern."},sec={{t="Von Scarletleaf zur Schlange",b="Bevor sie ihren Schlangentitel annahm, war Lady Anakondra als Scarletleaf bekannt. Als der ältere Druide Naralex den Plan fasste, über den Smaragdgrünen Traum die unterirdischen Quellen des Brachlands anzuzapfen, trat sie als seine allererste Freiwillige vor. Ihre eifrige Loyalität sollte sich jedoch als ihr Verderben erweisen. Als Naralex' Geist von finsteren Visionen ergriffen wurde, sickerte der Albtraum aus dem Traumreich und verdarb seine Jünger, wodurch Scarletleafs Verstand zerbrach und ihre Träumerei zu einer kalten, reptilischen Besessenheit umgeformt wurde."},{t="Eine Giftzahnfürstin in der Tiefe",b="Nun nennt sie sich Lady Anakondra und hält in den ersten unterirdischen Kammern der Höhlen des Wehklagens Wache. Wie ihre Mitfürsten der Giftzähne gab sie die traditionellen Grundsätze des Zirkels des Cenarius zugunsten der bösartigen Aspekte der Viper auf. Indem sie Blitze, Naturmagie und Schlummertrancen kanalisiert, erzwingt sie Naralex' verzerrten Schlaf und arbeitet daran, die Verderbnis des Albtraums in das dörre Land darüber auszubreiten."}},faq={{q="Wer war Lady Anakondra ursprünglich?",a="Sie war ursprünglich eine junge Nachtelfenakolytin namens Scarletleaf. Sie meldete sich als allererste Jüngerin freiwillig, um den Druiden Naralex auf seiner Mission ins Brachland zu begleiten.",al={"anacondra wahrer name","wer ist scarletleaf","scarletleaf hintergrundgeschichte"}},{q="Warum wandte sie sich gegen den Zirkel des Cenarius?",a="Als Naralex versuchte, unter dem Brachland eine Verbindung zum Smaragdgrünen Traum herzustellen, wurden seine Gedanken von einem Albtraum überwältigt. Derselbe Albtraum infizierte den Geist seiner Akolythen, verdarb Scarletleaf und brachte sie dazu, ihr altes Leben hinter sich zu lassen, um dem verzerrten Traum zu dienen.",al={"warum ist anacondra böse","wie wurde sie druidin des giftzahns","warum scarletleaf fiel"}},{q="Was ist ihre Rolle in den Höhlen des Wehklagens?",a="Sie dient als eine der vier Giftzahnfürsten, die die Druiden des Giftzahns anführen. Sie bewacht die oberen Bereiche der Höhlen und sorgt dafür, dass Naralex in seinem verdorbenen Schlaf gefangen bleibt, während sie von einer reptilischen Zukunft für die Welt träumt.",al={"was tut anacondra","lady anakondra zweck","warum anacondra töten"}},{q="Wo ist sie in den Höhlen zu finden?",a="Lady Anakondra streift durch das erste große Höhlennetzwerk nahe dem Eingang der Höhlen des Wehklagens. Sie patrouilliert zwischen den Raptoren und Schlangen der Höhle und wechselt oft zwischen einigen Rastplätzen.",al={"anacondra aufenthaltsort","wo ist lady anakondra","anacondra spawn"}},{q="Welcher Gegenstand wird ihr für den Zirkel des Cenarius abgenommen?",a="Sie trägt den Edelstein von Anacondra bei sich. Sie zu erschlagen und den Edelstein an sich zu nehmen, wird von der Druidin Nara Wildmähne in Donnerfels verlangt, um den Einfluss der Giftzahnfürsten auf das Brachland zu brechen.",al={"edelstein von anacondra","anführer der giftzähne anacondra","anacondra questgegenstand"}},{q="Welche Kräfte setzt sie im Kampf ein?",a="Sie greift auf Naturmagie zurück, attackiert ihre Feinde aus der Ferne mit sengenden Blitzen und wirkt magischen Schlaf, um Eindringlinge außer Gefecht zu setzen, während ihre reptilischen Verbündeten angreifen.",al={"anacondra fähigkeiten","anacondra zauber","anacondra angriffe"}}},fx={["6f9b72fe"]={q="Mit wem ist Lady Anakondra verbunden?",a="Lady Anakondra ist direkt mit Naralex verbunden, dem mächtigen Druiden, dem sie als Akolythin diente, bevor sein Albtraum ihren Verstand zerrüttete. Sie ist zudem an die anderen Fanglords gebunden – wie etwa Cobrahn und Serpentis –, die gemeinsam mit ihr den verdrehten Kult der Druiden des Giftzahns anführen.",al={"wer ist anakondras meister","verbindung anakondra naralex","wer führt anakondra an"}},["1a1ef870"]={q="Auf wessen Seite steht Lady Anakondra?",a="Lady Anakondra steht auf der Seite der Druiden des Giftzahns, nachdem sie ihre frühere Loyalität zum Zirkel des Cenarius aufgegeben hat. Korrumpiert durch den Smaragdgrünen Alptraum, der ihren Meister Naralex verschlang, stellt sie sich nun gegen ihre ehemaligen Verwandten und verteidigt den Wahnsinn, der in den Höhlen des Wehklagens schwärt.",al={"anakondra fraktion","wem dient lady anakondra","lady anakondra loyalität"}},["13dcdd34"]={q="Was will Lady Anakondra?",a="Nachdem sie ihre alte Identität zusammen mit ihrem Verstand abgelegt hat, stellt sich Lady Anakondra eine düstere reptilische Zukunft für Azeroth vor. Sie versucht, die Ausbreitung des Alptraums zu fördern und die natürliche Welt zusammen mit ihren Mitstreitern, den Giftzahnlords, in eine giftige, schlangenartige Domäne umzugestalten.",al={"was versucht anakondra zu tun","anakondra ziel","anakondra beweggründe"}},["04976b9c"]={q="Warum ist Lady Anakondra hier?",a="Ursprünglich eine junge Akolytin namens Scarletleaf, war sie die erste, die sich freiwillig meldete, als der Druide der Nachtelfen Naralex seine Mission startete, das trockene Brachland wiederherzustellen. Sie folgte ihm in die Höhlen des Wehklagens, um die unterirdischen Quellen anzuzapfen, nur um gefangen und verdreht zu werden, als sein Traum zum Alptraum wurde.",al={"warum ist anakondra in den höhlen des wehklagens","wie kam anakondra hierher","anakondra brachland mission"}}},fp="14,388,27.516.0,22.419.0,34.172.0,45.267.0,40.229.0,42.196.0,52.169.0,37.176.0"}
P.entries["npc:lady-sarevess"] = {n="Lady Sarevess",s="Lady Sarevess ist eine verkrüppelte Naga-Zauberin, die in den überfluteten Ruinen der Tiefschwarzen Grotte haust, wo sie sich mit dunklen Zaubern befasst.",h="Lady Sarevess ist eine verkrüppelte Naga-Zauberin, die in den überfluteten Ruinen der Tiefschwarzen Grotte...",kw={"aku'mai","tiefschwarze grotte","lady sarevess","naga","pool of ask'ar","sarevess","meerhexe","schattenhammer"},ang={["class:Mage"]="Sarevess zeigt, wie die magischen Praktiken der Hochgeborenen unter Jahrhunderten ozeanischer Verderbnis zu roher, chaotischer Blitz- und Gezeitenzauberei verfielen.",["race:NightElf"]="Die Ruinen, die Lady Sarevess bewohnt, waren einst ein heiliger Tempel von Elune. Zu sehen, wie ihre verkrüppelten Naga-Artgenossen die Gewässer von Ask'ar entweihen, ist eine bittere Erinnerung an die Zerschlagung."},sec={{t="Eine Grotte in der Tiefe",b="Im Pool of Ask'ar vollzieht Lady Sarevess ihre Rituale in einer überfluteten Grotte des zerstörten Tempels. Als zutiefst verdorbene Zauberin befasst sie sich mit dunkler Magie, während die Kultisten des Schattenhammers, die den versunkenen Tempel ebenfalls heimsuchen, tiefer in der Höhle ihren eigenen Kult praktizieren."},{t="Zauberei der Gezeiten",b="Ganz ähnlich wie eine Meerhexe der tiefen Ozeane gebietet Sarevess über elementare Strömungen und knisternde Blitze. Umgeben von loyalen Naga-Schildwachen und beschworenen Wasserelementaren verteidigt sie ihr Heiligtum erbittert gegen alle Eindringlinge, die ihr finsteres Werk bedrohen."}},faq={{q="Wer ist Lady Sarevess?",a="Lady Sarevess ist eine Naga-Zauberin, die sich im unterirdischen Pool of Ask'ar innerhalb der Tiefschwarzen Grotte niedergelassen hat. Sie ist eine zutiefst verdorbene Zauberin, die sich mit dunkler Magie befasst.",al={"wer ist sarevess","sarevess lore","lady sarevess hintergrundgeschichte"}},{q="Wo ist Lady Sarevess zu finden?",a="Sie haust im Pool of Ask'ar, einer überfluteten Kammer in den vorderen Bereichen des Tempelkomplexes der Tiefschwarzen Grotte an der Küste von Eschental.",al={"sarevess aufenthaltsort","wo ist lady sarevess","pool of askar"}},{q="Über welche Kräfte gebietet Lady Sarevess?",a="In der Tradition der Naga-Meerhexen wirkt Sarevess mächtige Wasser- und Elementarmagie, insbesondere heftige Entladungen von Gabelblitzen, um jeden niederzustrecken, der ihre Bucht betritt.",al={"sarevess magie","sarevess fähigkeiten"}}},fx={["75d3f337"]={q="Auf wessen Seite steht Lady Sarevess?",a="Lady Sarevess dient ihrem eigenen Volk, den Naga, und nicht der Allianz oder der Horde. Als überaus verdorbene Zauberwirkerin haust sie im überfluteten Pool of Ask'ar in der Tiefschwarzen Grotte und verteidigt ihre Grotte erbittert gegen jeden Eindringling.",al={"fraktion lady sarevess","wem dient sarevess","loyalität sarevess"}},["67d48548"]={q="Was will Lady Sarevess?",a="Sarevess strebt danach, ihre Meisterschaft über verdrehte magische Künste auszuweiten. Sie führt dunkle Rituale in ihrer überfluteten Grotte tief in der Tiefschwarzen Grotte durch und streckt jeden Eindringling nieder, der ihre Arbeit stört.",al={"was tut sarevess","ziel von lady sarevess","zweck von sarevess"}},["6008d570"]={q="Warum ist Lady Sarevess hier in der Tiefschwarzen Grotte?",a="Lady Sarevess hat den Pool of Ask'ar, eine überflutete Grotte im Ruinentempel der Tiefschwarzen Grotte, zu ihrem Versteck erkoren. Dort befasst sie sich mit dunkler Magie, bewacht von Naga-Wachposten und beschworenen Wasserelementaren.",al={"warum ist lady sarevess in der tiefschwarzen grotte","grund für sarevess in tiefschwarzer grotte","warum ist sarevess hier"}},d8505f38={q="Mit wem ist Lady Sarevess verbunden?",a="Sarevess ist mit den Naga verbunden, die die überfluteten Ruinen der Tiefschwarzen Grotte heimsuchen. Sie befehligt loyale Naga-Wachposten und beschworene Wasserelementare in ihrer Grotte. Die Kultisten des Schattenhammers, die ebenfalls den versunkenen Tempel heimsuchen, verfolgen tief in der Höhle ihren eigenen Kult.",al={"verbündete von sarevess","mit wem arbeitet sarevess zusammen","sarevess schattenhammer"}}},fp="13,134,21.274.0,20.262.0,21.188.0,33.156.0,39.192.0"}
P.entries["npc:laird"] = {n="Laird",s="Laird ist ein Fischverkäufer der Nachtelfen, den man im Gasthaus an der Küste von Auberdine antrifft. Bei seiner Arbeit an der nebelverhangenen Küste der Dunkelküste versorgt er Reisende und Angler, die sich an die raue Küste wagen, mit Handelsgütern und Kochrezepten.",h="Laird ist ein Fischverkäufer der Nachtelfen, den man im Gasthaus an der Küste von Auberdine antrifft.",kw={"auberdine","dunkelküste","frenzyfilet","fischverkäufer","laird","nessa schattensang"},ang={["profession:Cooking"]="Kulinarisch interessierte Reisende, die Dunkelküste besuchen, suchen Laird oft wegen seines Rezepts auf, wie man die wilden Frenzy-Fische aus den Gewässern von Kalimdor richtig filetiert und zubereitet.",["race:NightElf"]="Laird steht stellvertretend für die alltäglichen Handwerker und Händler der Nachtelfen, die sich an den Küsten des Festlands niedergelassen haben, um das wachsende Küstennetzwerk von Kalimdor zu unterstützen."},sec={{t="Ein Hafenhändler",b="Im geschäftigen Gasthaus von Auberdine verkauft Laird frischen Fisch und Vorräte an Seeleute, Einheimische und reisende Abenteurer. Die Gewässer der Dunkelküste sind im Vergleich zu den geschützten Ufern von Teldrassil berüchtigt für ihre Unruhe und voller Gefahren, doch Laird weiß genau, dass Risiken auch Belohnungen bringen. Für wagemutige Angler, die bereit sind, ihre Leinen an den nebligen Stränden auszuwerfen, verspricht der örtliche Fang einen stattlichen Gewinn."},{t="Verbindungen über das Wasser",b="Laird pflegt weiterhin enge Verbindungen zu den Fischereibetrieben jenseits des Kanals in Teldrassil. Er dient als wichtige Anlaufstelle für Kurierfahrten zwischen den Inselzweigen von Rut'theran und dem Hafen auf dem Festland, nimmt Lieferungen seiner Fischerkollegin Nessa Schattensang entgegen und sorgt dafür, dass die Küstenhandelswege offen bleiben."}},faq={{q="Wo kann ich Laird finden?",a="Laird befindet sich im Erdgeschoss des Gasthauses in Auberdine, der Hauptsiedlung der Allianz an der Küste der Dunkelküste.",al={"laird aufenthaltsort","wo ist laird","laird auberdine"}},{q="Was verkauft Laird?",a="Er verkauft verschiedene gefangene Fische und Kochzutaten sowie die kulinarische Anleitung zur Zubereitung von Frenzyfilet.",al={"laird händler","was verkauft laird","laird waren"}},{q="Welche Quests haben mit Laird zu tun?",a="Laird ist in der Quest Ein unerwartetes Geschenk der Empfänger einer Lieferung von Nessa Schattensang aus Rut'theran; anschließend bittet er Abenteurer, eine Nachricht zurück über das Meer zu bringen.",al={"laird quests","auberdine fischquest"}},{q="Warum lohnt sich das Angeln in Dunkelküste laut Laird trotz der Gefahren?",a="Laird merkt an, dass die neblige Küste der Dunkelküste zwar weit mehr Gefahren birgt als die ruhigen Gewässer von Teldrassil, die reiche und exotische Meeresfauna den Handel für geschäftstüchtige Angler jedoch weitaus profitabler macht.",al={"laird gerede","ist dunkelküste gut zum angeln"}}},fx={["47d7af55"]={q="Wer ist Laird?",a="Laird ist ein Nachtelf-Fischer und Fischhändler, der seinen Lebensunterhalt in der Dunkelküste verdient. Er hat seinen Stützpunkt im belebten Gasthaus von Auberdine und handelt mit Reisenden und Fischern, die die nebligen Gewässer entlang der Küste befahren. Er bietet Vorbeigehenden Kochrezepte und frischen Fisch an.",al={"wer ist laird","laird auberdine","identität von laird"}},f4a4a12e={q="Auf wessen Seite steht Laird?",a="Laird ist mit den Nachtelfen und der Allianz verbündet. Da er friedlich in Auberdine lebt, heißt er Abenteurer der Allianz und einheimische Fischer willkommen, damit sie sich im Gasthaus ausruhen und seine Waren durchstöbern können.",al={"fraktion von laird","ist laird allianz","wem dient laird"}},["90f5a883"]={q="Warum ist Laird hier?",a="Laird bleibt im Gasthaus von Auberdine, um Küstenfänge zu kaufen und zu verkaufen. Obwohl die Küste der Dunkelküste Gefahren birgt, die es in Teldrassil nicht gibt, erkennt er, dass wagemutige Fischer beträchtliche Gewinne aus den örtlichen Gewässern erzielen können, was den Hafen zu einem erstklassigen Ort für seinen Handel macht.",al={"warum ist laird in auberdine","zweck von laird in der dunkelküste"}},d47e4f81={q="Was will Laird?",a="Laird strebt einen florierenden Küstenfischhandel an. Er fördert lokale Fischereiunternehmen trotz der Gefahren an den Küsten der Dunkelküste und freut sich, hungrige Reisende mit Meeresfrüchten und kulinarischen Rezepten zu versorgen.",al={"was will laird","ziele von laird","motive von laird"}}},fp="5,224,17.404.0,21.323.0,23.128.0,21.123.0,26.193.0,72.215.0"}
P.entries["npc:lakota-windsong"] = {n="Lakota Windweise",s="Lakota Windweise ist eine junge Tauren, die auf den Klippen des Düsterwolkengipfels in Tausend Nadeln gefangen gehalten wird. Nachdem sie einen unerwünschten Heiratsantrag von Arnak Grimtotem abgelehnt hatte, wurde sie gewaltsam entführt und wartet nun auf Rettung aus den Klauen des Klans der Grimtotem.",h="Lakota Windweise ist eine junge Tauren, die auf den Klippen des Düsterwolkengipfels in Tausend Nadeln...",kw={"arnak grimtotem","düsterwolkengipfel","endlich frei","freiwindposten","lakota windweise","thalia bernhaut","tausend nadeln"},ang={["faction:Horde"]="Die Rettung von Lakota versetzt der Vorherrschaft der Grimtotem in Tausend Nadeln einen Schlag und sichert Reisenden, die am Freiwindposten rasten, freies Geleit.",["race:Tauren"]="Lakotas Tortur ist eine deutliche Mahnung an den Verrat, der unter den Grimtotem schwelt, deren Auflehnung gegen die Führung von Cairne Bluthuf regelmäßig in Gewalt umschlägt."},sec={{t="Ein tödliches Werben",b="Nicht lange nach dem Dritten Krieg wurde Lakota Windweise von Arnak Grimtotem umworben. Da sie weder seinem Klan beitreten noch sein Werben erwidern wollte, lehnte sie seinen Antrag ab. Arnak weigerte sich, ein Nein zu akzeptieren; er kehrte im Schutz der Nacht zurück, ermordete Lakotas Bruder, als dieser einzuschreiten versuchte, und verschleppte sie in die zerklüfteten Höhen von Tausend Nadeln. Gefangen hoch über dem Schluchtboden auf dem Düsterwolkengipfel, verbleibt sie unter strenger Bewachung, während Arnak noch immer darauf beharrt, sie zu seiner Braut zu machen."},{t="Abstieg in die Sicherheit",b="Umringt von verräterischen Banditen der Grimtotem kann sich Lakota den Weg die Klippen hinab nicht alleine freikämpfen. Nur eine mutige Eskorte kann sie über die Hängebrücken und die gewundenen Pfade hinab in den Schluchtgrund führen. Sobald sie sich vom Düsterwolkengipfel befreit hat, flieht Lakota in die Sicherheit des Freiwindpostens und überbringt Thalia Bernhaut sowie den dort stationierten Verteidigern die Nachricht von ihrer Rettung."}},faq={{q="Warum wird Lakota Windweise auf dem Düsterwolkengipfel festgehalten?",a="Sie lehnte einen Heiratsantrag von Arnak Grimtotem ab. Anstatt ihre Absage zu akzeptieren, ermordete Arnak ihren Bruder und entführte Lakota in die Festung der Grimtotem auf dem Düsterwolkengipfel, in der Hoffnung, sie zur Heirat zu zwingen.",al={"warum ist lakota gefangen","wer hat lakota entführt","warum ist lakota auf dem düsterwolkengipfel"}},{q="Wohin geht Lakota, sobald sie gerettet ist?",a="Nachdem sie den Fuß des Düsterwolkengipfels sicher erreicht hat, macht sich Lakota auf den Weg zum Freiwindposten, wo sie Zuflucht bei den Verteidigern der Horde findet und Thalia Bernhaut von ihrem Martyrium berichten kann.",al={"wohin rennt lakota","wohin geht sie nach der begleitung","lakota zielort"}},{q="Wer ist Arnak Grimtotem?",a="Arnak ist ein gewalttätiger Krieger des verräterischen Klans der Grimtotem, der Lakotas Bruder ermordete und sie entführte, als sie sich weigerte, ihn zu heiraten.",al={"wer ist arnak","wer hat sie entführt","arnak geschichte"}}},fx={e2861ac8={q="Wer ist Lakota Windweise?",a="Lakota Windweise ist eine Taurenfrau, die gefangen auf dem Düsterwolkengipfel festgehalten wird. Als Arnak Grimmtotem um ihre Hand anhielt, wies Lakota ihn ab. Außer sich vor Wut über ihre Zurückweisung ermordete Arnak ihren Bruder und verschleppte sie in die Festung der Grimmtotem in Tausend Nadeln, um die Vereinigung gegen ihren Willen zu erzwingen.",al={"wer ist lakota windweise","wer ist lakota","identität von lakota"}},["412850e2"]={q="Auf wessen Seite steht Lakota Windweise?",a="Lakota steht auf der Seite der friedlichen Tauren der Horde und hofft auf den Schutz der Recken am Freiwindposten. Sie hegt tiefen Groll gegen den Grimmtotem-Clan, der ihrem Bruder brutal das Leben nahm und sie entführte.",al={"fraktion von lakota windweise","ist lakota horde","loyalität von lakota"}},["2c16a924"]={q="Was will Lakota Windweise?",a="Lakota wünscht sich nichts sehnlicher, als vom Düsterwolkengipfel zu entkommen und in Sicherheit, fernab der Grimmtotem-Banditen, zu gelangen. Da ihr Bruder bei ihrer Verteidigung erschlagen wurde, ist sie auf jemanden angewiesen, der mutig genug ist, sich an ihren Entführern vorbeizukämpfen und sie sicher die gewundenen Pfade hinunter zum Freiwindposten zu geleiten.",al={"ziel von lakota windweise","was braucht lakota","wünsche von lakota"}},["3261173c"]={q="Mit wem ist Lakota Windweise verbunden?",a="Lakota wurde erbittert von ihrem Bruder beschützt, der sein Leben verlor, als er versuchte, sie vor Arnak Grimmtotem zu verteidigen. Sie setzt ihr Vertrauen auch in Thalia Bernhaut und die Verteidiger, die am Freiwindposten stationiert sind.",al={"familie von lakota","verbindungen von lakota","mit wem ist lakota verwandt"}}},fp="15,245,18.504.0,17.388.1,56.226.0,41.187.1,23.139.0"}
P.entries["npc:lanka-farshot"] = {n="Lanka Weitschuss",s="Lanka Weitschuss ist ein Jägerlehrer der Tauren, der im Camp Narache auf der Hochwolkenebene stationiert ist. Er leitet unerfahrene Taurenjäger an, während sie ihre ersten Schritte im Fährtenlesen, der Treffsicherheit und dem Überleben in den Ebenen von Mulgore unternehmen.",h="Lanka Weitschuss ist ein Jägerlehrer der Tauren, der im Camp Narache auf der Hochwolkenebene stationiert ist.",kw={"camp narache","jägerlehrer","lanka weitschuss","mulgore","die hochwolkenebene","taurenjäger"},ang={["class:Hunter"]="Für Taurenjäger, die ihre Ausbildung in Mulgore beginnen, ist Lanka Weitschuss der allererste Mentor, dem sie begegnen; er lehrt grundlegende Treffsicherheit und das Überleben in der Wildnis.",["race:Tauren"]="Lanka verkörpert die traditionelle Jagdphilosophie der Tauren, in der Treffsicherheit und Fährtenlesen als lebenswichtige Pflichten zum Schutz des Stammes und für ein Leben im Einklang mit den Ebenen gelten."},sec={{t="Mentor der Hochwolkenebene",b="Lanka Weitschuss wacht über Camp Narache und begrüßt neue Tauren, die zum Pfad des Jägers berufen wurden. Frische Rekruten treffen mit einer geätzten Notiz ein, die sie anweist, seinen Rat zu suchen. Unter seinem wachsamen Auge erlernen Lehrlinge die Grundlagen des Fernkampfs, das Aufspüren von Beute und den Respekt vor den wilden Tieren, die die grasbewachsenen Ebenen von Mulgore durchstreifen. Seine Lehren stellen sicher, dass jeder junge Jäger dem Stamm als fähiger Späher und Versorger dient."}},faq={{q="Wer ist Lanka Weitschuss?",a="Lanka Weitschuss ist der Jägerlehrer der Tauren, der im Camp Narache auf der Hochwolkenebene in Mulgore stationiert ist. Er bietet jungen Jägern, die ihre Reise beginnen, erste Ausbildung und Anleitung.",al={"wer ist lanka","lanka weitschuss nsc","camp narache jäger"}},{q="Welche Quests bietet Lanka Weitschuss an?",a="Lanka empfängt junge Taurenjäger, die bei ihrer Ankunft im Camp Narache über eine geätzte Notiz zu ihm geschickt werden, und führt sie auf den Weg des Jägers, während sie die Grundlagen ihres Handwerks erlernen.",al={"lanka weitschuss quests","jägerquests camp narache"}},{q="Ist Lanka Weitschuss mit Mixie Farshot verwandt?",a="Obwohl sie denselben Nachnamen tragen, gibt es keinen Hinweis darauf, dass Lanka Weitschuss mit der Goblindame Mixie Farshot verwandt ist.",al={"ist lanka mit mixie verwandt","verwandtschaft mixie farshot"}}},fx={["3509322d"]={q="Auf wessen Seite steht Lanka Weitschuss?",a="Lanka Weitschuss ist den Taurenstämmen und der Horde treu ergeben. Er ist im sicheren Zufluchtsort Camp Narache stationiert und dient seinem Volk, indem er junge Taurenjäger anleitet, während sie lernen, unter der Führung des Hochhäuptlings Cairne Bluthuf zu überleben und zu den vereinigten Stämmen beizutragen.",al={"fraktion von lanka weitschuss","wem dient lanka weitschuss","ist lanka horde"}},fd40a21a={q="Warum ist Lanka Weitschuss hier in Camp Narache?",a="Lanka wohnt in Camp Narache, um angehende Jäger zu unterweisen, die ihre Prüfungen auf der Hochwolkenebene beginnen. Die Ebenen von Mulgore erfordern scharfe Sinne und ein ruhiges Zielwasser, und Lanka steht bereit, die wesentlichen Künste des Aufspürens und der Treffsicherheit an die nächste Generation weiterzugeben.",al={"warum ist lanka hier","standort und zweck von lanka weitschuss","was führt lanka nach camp narache"}},["2df75887"]={q="Was will Lanka Weitschuss?",a="Lanka möchte sicherstellen, dass jeder aufstrebende Taurenjäger die Wege der Wildnis meistert. Er möchte, dass Ihr Eure Beute respektiert, Eure Treffsicherheit schärft und die stolzen Traditionen fortführt, die notwendig sind, um Euer Volk auf dem Grasland zu ernähren und zu verteidigen.",al={"ziel von lanka weitschuss","was versucht lanka zu tun","zweck von lanka weitschuss"}}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="Lar Lauerzahn",s="Lar Lauerzahn ist ein Schildwache-Troll der Dunkelspeer, der südwestlich von Sen'jin in Durotar stationiert ist. Von seinem Außenposten an der Grenze aus wacht er über herannahende Bedrohungen für die junge Trollsiedlung und weist Abenteurer an, das Vorrücken nahegelegener Feinde aufzuhalten.",h="Lar Lauerzahn ist ein Schildwache-Troll der Dunkelspeer, der südwestlich von Sen'jin in Durotar stationiert...",kw={"dunkelspeer","durotar","kolkar","lar lauerzahn","northwatch","sen'jin","troll"},ang={["faction:Horde"]="Lar Lauerzahn verkörpert den Kampf der Horde, die Grenzen von Durotar direkt vor den Toren ihrer noch jungen Hauptstadt gegen äußere Bedrohungen zu sichern.",["race:Troll"]="Für die Dunkelspeere sind Späher wie Lar Lauerzahn von entscheidender Bedeutung, um die zerbrechliche neue Heimat des Stammes in Durotar vor aggressiven Zentaurenclans und vordringenden Streitkräften der Menschen zu schützen."},sec={{t="Wächter an der Küste",b="Südwestlich von Sen'jin an der zerklüfteten Küste von Durotar gelegen, dient Lar Lauerzahn als einer der vorderen Vorpostenposten des Dunkelspeer-Stammes. Da die Trolle nach ihrer Flucht von ihrer versunkenen Inselkette immer noch daran arbeiten, sich eine dauerhafte Heimat zu sichern, ist Sen'jin ständigen Übergriffen feindlicher Nachbarn ausgesetzt. Lar koordiniert Späher und Krieger, um die Küstenbewegungen zu überwachen und die Aggression feindlicher Mächte einzudämmen – insbesondere der Kolkar-Zentauren –, damit die fragile Siedlung Raum zum Atmen hat."}},faq={{q="Wer ist Lar Lauerzahn?",a="Lar Lauerzahn ist ein Questgeber der Dunkelspeer-Trolle, der direkt südwestlich von Sen'jin in Durotar stationiert ist. Er hilft bei der Bewachung der Außenbezirke der Siedlung, indem er fähige Reisende der Horde anheuert, um regionale Bedrohungen zu bekämpfen, bevor sie das eigentliche Dorf erreichen.",al={"lar lauerzahn","wer ist lar lauerzahn","lar lauerzahn durotar"}},{q="Auf welche Bedrohungen konzentriert sich Lar Lauerzahn?",a="Lar konzentriert sich auf Grenzgefahren, die das südliche Durotar bedrohen, insbesondere auf die marodierenden Rudel der Kolkar-Zentauren, die in das Territorium der Trolle vordringen.",al={"lar lauerzahn quests","was will lar lauerzahn"}},{q="Wo ist Lar Lauerzahn zu finden?",a="Er befindet sich im südlichen Durotar und hält entlang der Pfade südwestlich von Sen'jin Wache.",al={"lar lauerzahn aufenthaltsort","wo ist lar lauerzahn"}}},fx={["7aeb1fbe"]={q="Auf wessen Seite steht Lar Lauerzahn?",a="Lar Lauerzahn ist dem Darkspear-Stamm und der Horde treu ergeben. Er ist an der rauen Küste von Durotar südwestlich von Sen'jin stationiert und handelt zur Verteidigung der neuen Heimat seines Volkes. Er hält Ausschau nach vordringenden Feinden, die die Sicherheit der Darkspear-Trolle und ihrer orkischen Verbündeten bedrohen.",al={"fraktion von lar lauerzahn","wem dient lar lauerzahn","lar lauerzahn horde oder allianz"}},ffd46d6a={q="Warum ist Lar Lauerzahn hier draußen?",a="Lar Lauerzahn hält südwestlich von Sen'jin Wache, um die Darkspear-Siedlung vor regionalen Gefahren zu schützen. Die südlichen Ausläufer von Durotar sind ständig dem Druck aggressiver Nachbarn ausgesetzt, und Lar bleibt in der Nähe der wilden Küste stationiert, um dabei zu helfen, Verteidiger gegen diese lokalen Bedrohungen zu lenken, bevor sie das Dorf angreifen.",al={"warum ist lar lauerzahn in durotar","grund für den standort von lar lauerzahn","warum ist lar südwestlich von sen'jin"}},["9e56c7c1"]={q="Mit wem ist Lar Lauerzahn verbunden?",a="Lar Lauerzahn ist eng mit der Trollsiedlung Sen'jin verbunden und koordiniert sich mit den Dorfverteidigern und wandernden Abenteurern der Horde, um das Territorium der Trolle zu schützen.",al={"verbündete von lar lauerzahn","beziehungen von lar lauerzahn","partner von lar lauerzahn"}}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laris-geardawdle"] = {n="Laris Bummelritzel",s="Laris Bummelritzel ist ein exzentrischer gnomischer Forscher, der in der Bibliothek der Hall of Explorers in Eisenschmiede stationiert ist. Er widmet sein akademisches Leben der Erforschung der bizarren Natur und der Ursprünge von Schlämmen in ganz Azeroth. Abenteurer, die bereit sind, übelriechende Schleimproben zu sammeln, finden in ihm einen eifrigen, wenn auch leicht verschrobenen Förderer.",h="Laris Bummelritzel ist ein exzentrischer gnomischer Forscher, der in der Bibliothek der Hall of Explorers in...",kw={"gnom","hall of explorers","eisenschmiede","laris bummelritzel","bibliothek","schlamm","schleim"},ang={["faction:Alliance"]="Stationiert in der Hall of Explorers arbeitet Laris unter dem weiten Schirm der von der Allianz geförderten Wissenschaft und bereichert die historischen Ausgrabungen der Liga um exzentrische Naturwissenschaften.",["race:Gnome"]="Laris verkörpert den urtypischen gnomischen Drang, an Orten nach Wissen zu suchen, die alle anderen übersehen – selbst wenn man dafür seine Hände in übel riechenden Sumpfschlick tauchen muss."},sec={{t="Gelehrter des Schleims",b="Versteckt zwischen den hoch aufragenden Bücherregalen und uralten Relikten der Hall of Explorers widmet sich Laris Bummelritzel einer eher unrühmlichen Nische der Naturphilosophie: der Entstehung von Schlämmen. Während seine zwergischen Kollegen über Titanentafeln und uralten Steinmetzarbeiten brüten, ist Laris davon überzeugt, dass Azeroths abscheuliche, gallertartige Schrecken faszinierende alchemistische und biologische Geheimnisse bergen. Er beauftragt umherreisende Entdecker damit, ätzende Proben aus entlegenen Winkeln der Welt zu sammeln, voller Eifer, seine seltsamen Hypothesen darüber zu testen, wie diese geistlosen Pfützen der Bosheit zum Leben erwachen."}},faq={{q="Wer ist Laris Bummelritzel?",a="Laris Bummelritzel ist ein Gnomforscher, der in der Bibliothek der Hall of Explorers in Eisenschmiede verweilt. Er konzentriert seine unkonventionellen Studien auf Schlämme, Schleime und die bizarren Mechanismen hinter ihrer Spontanzeugung.",al={"laris","geardawdle","wer ist laris"}},{q="Wo kann ich Laris Bummelritzel finden?",a="Er befindet sich im Nordflügel von Eisenschmiede innerhalb der Hall of Explorers, genauer gesagt zurückgezogen in den ruhigen Winkeln der Bibliothek.",al={"laris aufenthaltsort","wo ist laris","laris bummelritzel finden"}},{q="Warum erforscht er Schlämme?",a="Laris besitzt einen scharfen, exzentrischen wissenschaftlichen Verstand und hat ganz eigene Theorien über das Wesen und die Entstehung lebenden Schleims entwickelt. Er glaubt, dass die Analyse ätzender Rückstände verschiedener Schlämme ein tieferes Verständnis dafür eröffnen wird, wie sich diese bizarren Organismen bilden und vermehren.",al={"warum schlämme","laris schleimforschung","schlammstudie"}},{q="Welche Aufgaben bietet er Abenteurern an?",a="Laris rekrutiert kühne Reisende, die sich in gefährliche Lande wagen, um reine Schlammproben zu sammeln. Im Rahmen seiner Aufgabe 'A Little Slime Goes a Long Way' stellt er leere Sammelgläser bereit und bittet Abenteurer darum, zähflüssige Rückstände von lebenden Schleimen in der Wildnis zu erbeuten.",al={"laris quests","schlamm auf abwegen"}}},fx={a960bc4a={q="Auf wessen Seite steht Laris Bummelritzel?",a="Laris Bummelritzel steht fest auf der Seite der Allianz und der Gnomeregangnome. Er arbeitet von der Hall of Explorers in Eisenschmiede aus, zusammen mit zwergischen Gelehrten und Forschern, und trägt seinen scharfen Verstand und seine exzentrischen biologischen Theorien dazu bei, das Wissen und Verständnis der Allianz über seltsame Phänomene in der ganzen Welt voranzubringen.",al={"fraktion von laris bummelritzel","laris bummelritzel allianz","ist laris bummelritzel freundlich"}},["114e8ed2"]={q="Warum ist Laris Bummelritzel in Eisenschmiede?",a="Nach dem Fall von Gnomeregan suchten viele Gnome Zuflucht bei ihren zwergischen Verbündeten in Eisenschmiede. Laris Bummelritzel hat sein Zuhause in der Library innerhalb der Hall of Explorers gefunden, einem idealen Zufluchtsort, wo er seine exzentrische akademische Forschung verfolgen und seine Theorien über den Ursprung von Schlämmen katalogisieren kann, mit vollem Zugang zu umfangreichen historischen und natürlichen Archiven.",al={"warum ist laris bummelritzel hier","laris bummelritzel hall of explorers","warum ist laris in eisenschmiede"}}},fp="16,316,16.558.0,24.220.0,34.139.0,25.279.0,37.260.0"}
P.entries["npc:lars"] = {n="Lars",s="Lars ist ein bedrängter menschlicher Überlebender, der in der Wildnis von Dämmerwald lagert. Gemeinsam mit seinem Gefährten Sven Yorgen kämpft er am nördlichen Rand des stillen Ufers darum, sich gegen die Schrecken zu behaupten, die durch den Wald streifen.",h="Lars ist ein bedrängter menschlicher Überlebender, der in der Wildnis von Dämmerwald lagert.",kw={"lager","dämmerwald","das stille ufer","lars","sven yorgen","wölfe","wölfe sind uns auf den fersen"},ang={["faction:Alliance"]="Lars ist ein bedrängter menschlicher Zivilist, der außerhalb der Reichweite der Stadtwache überlebt und froh ist, Recken der Allianz zu finden, die bereit sind, die sein Lager umkreisenden Wölfe niederzustrecken."},sec={{t="Ein heikler Zufluchtsort",b="In einem bescheidenen Lager am nördlichen Rand des stillen Ufers fristet Lars fernab der zweifelhaften Sicherheit von Dunkelhain ein unsicheres Dasein. Dämmerwald ist selbst in den besten Zeiten tückisch, doch die umliegenden Wälder wimmeln von wilden Bestien, unerbittlichen Untoten und schleichenden Worgen. Lars weicht Sven Yorgen nicht von der Seite und versucht schlichtweg, in einer zunehmend feindseligen Wildnis am Leben zu bleiben."},{t="Gefahr aus der Wildnis",b="Das Überleben im Lager erfordert ständige Wachsamkeit gegenüber den ansässigen Raubtieren. Lars sieht sich durch die unerbittlichen Rudel hungernder Terrorwölfe, die in den Schatten um ihr Feuer lauern, schwer bedrängt. Da er seine Wachsamkeit nicht nachlassen lassen und sie nicht allein zurückdrängen kann, ist er auf fähige Reisende angewiesen, um die hungrigen Raubtiere auszudünnen, bevor sein kleines Lager vollkommen überrannt wird."}},faq={{q="Wer ist Lars?",a="Lars ist ein menschlicher Überlebender, der in der Wildnis von Dämmerwald lagert. Er lebt an der Seite seines Freundes und Gefährten Sven Yorgen an der nördlichen Grenze des stillen Ufers und tut, was er kann, um die Schrecken des Waldes zu überstehen.",al={"lars dämmerwald","wer ist lars","lars nsc"}},{q="Wo ist Lars zu finden?",a="Lars befindet sich in einem kleinen Wildnislager am nördlichen Rand des stillen Ufers im westlichen Dämmerwald.",al={"wo ist lars","lars aufenthaltsort","lars lager"}},{q="Vor welchem Problem steht Lars?",a="Lars und Sven werden ständig von den unersättlichen Wölfen und Raubtieren heimgesucht, die in den nahegelegenen Wäldern lauern. Mit der Aufgabe 'Wölfe sind uns auf den Fersen' bittet Lars vorbeikommende Abenteurer darum, die Raubtiere zu jagen, bevor sie sein Lager zerfleischen.",al={"lars quest","wölfe auf den fersen quest","warum braucht lars hilfe"}},{q="In welcher Beziehung steht Lars zu Sven Yorgen?",a="Lars und Sven Yorgen sind Gefährten, die gemeinsam in der Wildnis überleben. Sven hat in der Region seine eigene finstere Vergangenheit und eine Blutrache auszutragen, während Lars hilft, ihren rauen, abgelegenen Außenposten aufrechtzuerhalten.",al={"lars und sven","wer ist sven für lars"}}},fx={["05f5e77d"]={q="Auf wessen Seite steht Lars?",a="Lars ist ein unabhängiger menschlicher Überlebender, der mit der Allianz verbündet ist. Anstatt direkt der The Night Watch oder dem Militär von Sturmwind zu dienen, ist er einfach ein gewöhnlicher Mann, der versucht, die Gefahren des Dämmerwaldes an der Seite seines Gefährten Sven Yorgen zu überstehen.",al={"lars fraktion","ist lars bei der allianz","wem dient lars"}},["2eb2df94"]={q="Warum schlägt Lars im Dämmerwald sein Lager auf?",a="Lars hat in einem rauen Lager am nördlichen Rand des Stillen Ufers Zuflucht gesucht. Er bleibt dort und versucht, im dunklen Wald Tag für Tag in der Gesellschaft von Sven Yorgen zu überleben, während er gegen die vordringenden Raubtiere und Schrecken des Waldes ausharrt.",al={"warum ist lars hier","grund für lars im dämmerwald","warum kam lars hierher"}}},fp="4,232,18.391.0,21.358.0,12.212.0,24.118.0,28.233.0,43.188.0"}
P.entries["npc:laurna-morninglight"] = {n="Laurna Morgenglanz",s="Laurna Morgenglanz ist eine Priesterlehrerin der Nachtelfen, die in der beschaulichen Siedlung Dolanaar auf Teldrassil lebt. Sie ist der Schwesternschaft von Elune ergeben und unterweist angehende Akolythen, die aus Laubschattental kommen, in den spirituellen Riten und heilenden Gaben der Mondgöttin. Ihre Lehren bereiten junge Priester der Nachtelfen auf die wachsenden Gefahren vor, die die Äste des Weltenbaums bedrohen.",h="Laurna Morgenglanz ist eine Priesterlehrerin der Nachtelfen, die in der beschaulichen Siedlung Dolanaar auf...",kw={"dolanaar","elune","kaldorei","laurna","morninglight","priesterlehrer","schwesternschaft von elune","teldrassil"},ang={["class:Priest"]="Für Priester der Nachtelfen, die aus Laubschattental eintreffen, ist Laurna Morgenglanz Eure erste wichtige Mentorin außerhalb des Starttals; sie lehrt grundlegende Zauber und leitet Eure frühe Hingabe an Elune.",["race:NightElf"]="Laurna verkörpert die traditionelle Hingabe der Kaldorei an die Mondgöttin und erinnert Abenteurer daran, dass das Priestertum auf Teldrassil aus Elune und nicht aus dem Heiligen Licht schöpft."},sec={{t="Eine Wegweiserin in Dolanaar",b="Inmitten der Äste von Dolanaar dient Laurna Morgenglanz als eine der wichtigsten Lehrmeisterinnen für junge Priester, die ihre anfänglichen Riten in Laubschattental abgeschlossen haben. Wenn neue Initianden die weiteren Gefilde von Teldrassil betreten, leitet sie sie an, ihre Verbindung zu Elune zu vertiefen und das Licht der Heilung mit defensiven Riten in Einklang zu bringen, die für das Überleben in einer zunehmend feindseligen Wildnis unerlässlich sind."},{t="Hingabe an die Mondgöttin",b="Das Priestertum der Kaldorei ist eng mit der Verehrung Elunes verbunden und unterscheidet sich vom abstrakten Heiligen Licht, das von Menschen und Zwergen verehrt wird. Laurna überträgt ihren Schülern spirituelle Aufgaben, wie etwa den Empfang geweihter Roben und die Heilung einer verwundeten Schildwache. Durch diese Bräuche lernen die Akolythen, dass ihre Kräfte direkte Geschenke von Mutter Mond sind, die der Bewahrung und Genesung des Volkes der Kaldorei dienen."}},faq={{q="Wo finde ich Laurna Morgenglanz?",a="Laurna Morgenglanz hält sich im Dorf Dolanaar auf, das im Herzen von Teldrassil liegt, gleich die Straße hinab von Laubschattental.",al={"laurna aufenthaltsort","wo ist laurna","dolanaar priesterlehrer"}},{q="Welche Funktion erfüllt Laurna Morgenglanz?",a="Sie ist eine Priesterlehrerin für Charaktere der Nachtelfen. Sie lehrt neue Zauber, verbessert die Ränge bekannter Fähigkeiten und bietet erste Orientierung bei klassenspezifischen Riten.",al={"was macht sie","laurna rolle","laurna priesterlehrerin"}},{q="Welche Quests bietet sie an?",a="Sie leitet Klassenquests für angehende Priester ein und schickt sie aus, um verwundeten Verbündeten zu helfen und durch zeremonielle Gewänder und Gebete die göttliche Gunst Elunes zu erbitten.",al={"laurna quests","priesterquests dolanaar"}},{q="Bildet sie auch andere Völker aus?",a="Obwohl sie kulturell in der Schwesternschaft von Elune verwurzelt ist, unterweisen Priesterlehrer der Allianz jeden verbündeten Priester, der nach spiritueller Disziplin strebt.",al={"können menschen hier trainieren","priesterlehrer jedes volk"}},{q="Gehört sie zum Tempel des Mondes?",a="Ja, als Priesterin der Kaldorei sind ihre Gelübde und ihre Magie ganz der Göttin Elune und den weiteren Traditionen gewidmet, die vom Tempel des Mondes in Darnassus überwacht werden.",al={"gehört sie zur schwesterngemeinschaft von elune","laurna tempel des mondes"}},{q="Teilt sie ihren Familiennamen mit anderen Nachtelfen?",a="Unter den Kaldorei von Teldrassil sind keine Verwandten von Laurna bekannt.",al={"morninglight familie","laurna verwandte"}}},fx={["3c87933c"]={q="Wer ist Laurna Morgenglanz?",a="Laurna Morgenglanz ist eine Nachtelfenpriesterin und Mentorin, die im Dorf Dolanaar lebt. Sie widmet sich der Verehrung von Elune und leitet junge Akolythen und Initianden an, die ihre ersten Schritte in Teldrassil machen. Sie lehrt sie, die lindernde Ausstrahlung der Göttin zu kanalisieren und göttlichen Schutz zu erbitten.",al={"wer ist laurna morgenglanz","wer ist laurna","laurna morgenglanz hintergrundgeschichte"}},["5c82db11"]={q="Auf wessen Seite steht Laurna Morgenglanz?",a="Sie ist den Nachtelfen von Darnassus, der Schwesternschaft der Elune und der Allianz treu ergeben. Als Akolythin der Mondgöttin liegt ihr Herz beim Schutz ihres Volkes und der spirituellen Führung der Kaldorei auf Teldrassil.",al={"laurna morgenglanz fraktion","wem dient laurna morgenglanz","laurna morgenglanz allianz"}},["6a7a4981"]={q="Was möchte Laurna Morgenglanz?",a="Ihre hauptsächliche Hingabe gilt der Ausbildung von Priesterneulingen in den Wegen von Elune. Sie möchte, dass vielversprechende Akolythen ihre göttliche Verbindung kultivieren, Heilgebete meistern und heilige Gewänder tragen, um ihre Verwandten in den Zweigen von Teldrassil zu unterstützen.",al={"laurna morgenglanz beweggründe","was tut laurna morgenglanz"}},["65cf8731"]={q="Warum ist Laurna Morgenglanz hier in Dolanaar?",a="Dolanaar ist der wichtigste Knotenpunkt und Sammelplatz für junge Abenteurer, die die abgelegenen Lichtungen von Laubschattental verlassen. Laurna ist hier stationiert, um sicherzustellen, dass angehende Priester angemessene Führung, Unterweisung und heilige Riten erhalten, während sie größere Aufgaben in Teldrassil übernehmen.",al={"warum ist laurna in dolanaar","warum ist laurna morgenglanz hier"}}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lelanai"] = {n="Lelanai",s="Lelanai ist eine Nachtelf-Reittierhändlerin, die in der Enklave des Cenarius in Darnassus lebt. Sie stellt den würdigen Reitern die wilden Säbler-Reittiere der Nachtelfen zur Verfügung und bietet sowohl gewöhnliche Nachtsäbler als auch schnelle Kriegsbestien für ihr Volk und vertrauenswürdige Verbündete von Darnassus an.",h="Lelanai ist eine Nachtelf-Reittierhändlerin, die in der Enklave des Cenarius in Darnassus lebt.",kw={"die enklave des cenarius","darnassus","frostsäbler","jartsam","lelanai","reittierhändler","nachtsäbler"},ang={["faction:Alliance"]="Helden der Allianz, die den Ruf ehrfürchtig bei Darnassus erlangen, können Lelanai aufsuchen, um an der Seite ihrer Kaldorei-Verbündeten auf den ikonischen Säblern in die Schlacht zu reiten.",["race:NightElf"]="Für Nachtelfen ist der Besuch bei Lelanai ein wesentlicher Initiationsritus beim Erwerb ihrer traditionellen Katzen-Reittiere."},sec={{t="Züchterin der Enklave des Cenarius",b="Stationiert neben dem Reitlehrer Jartsam inmitten der hoch aufragenden Bäume der Enklave des Cenarius, kümmert sich Lelanai um einige der feinsten Großkatzen, die in Kalimdor gezüchtet werden. Nachtelfen haben seit Langem tiefe Bindungen zu den wilden Raubtieren der nördlichen Wälder aufgebaut und trainieren Nachtsäbler und Frostsäbler, um Wächter und Späher mit raubtierhafter Anmut durch unwegsames Gelände zu tragen. Lelanai dient als Hauptanbieterin dieser verehrten Reittiere in der Hauptstadt."},{t="Bindungen über das eigene Volk hinaus",b="Während Säbler-Reittiere jedem Nachtelf mit entsprechender Fertigkeit frei angeboten werden, müssen Außenstehende eine viel strengere Hürde nehmen. Angesichts der heiligen Natur der Katzen und der natürlichen Zurückhaltung der Kaldorei wird Lelanai einem Nicht-Nachtelfen nur dann ein Tier anvertrauen, wenn dieser sich den höchsten Grad an Respekt und Ansehen bei der Stadt Darnassus verdient hat."}},faq={{q="Wo finde ich Lelanai?",a="Lelanai befindet sich in der Enklave des Cenarius in Darnassus und steht direkt neben dem Tigerreitlehrer Jartsam.",al={"lelanai standort","wo ist lelanai","lelanai karte"}},{q="Was verkauft Lelanai?",a="Sie verkauft Zügel für verschiedene Arten von Frostsäbler- und Nachtsäbler-Reittieren, einschließlich schneller, gepanzerter Varianten für erfahrene Reiter.",al={"lelanai waren","welche reittiere hat sie","nachtelfen reittiere"}},{q="Können Nicht-Nachtelfen Reittiere bei Lelanai kaufen?",a="Ja, aber nur, wenn Ihr Eure außergewöhnliche Loyalität durch den Ruf ehrfürchtig bei Darnassus bewiesen habt. Andernfalls wird sie sich weigern, ihre Bestien an Außenstehende zu verkaufen.",al={"können menschen säbler kaufen","können zwerge auf nachtsäblern reiten","benötigter ruf für säbler"}},{q="Können Spieler der Horde mit Lelanai interagieren?",a="Nein. Lelanai ist der Fraktion Darnassus der Allianz treu ergeben. Mitglieder der Horde werden von ihr und den Wachen der nahegelegenen Enklave als feindliche Eindringlinge behandelt.",al={"kann die horde säbler kaufen","ist lelanai der horde gegenüber freundlich"}}},fx={["8575cac4"]={q="Wer ist Lelanai?",a="Lelanai ist eine Nachtelfen-Reittierzüchterin und Händlerin, die in Darnassus lebt. Stationiert in der üppigen Die Enklave des Cenarius, kümmert sie sich um die majestätischen Säbler, die für die Kaldorei gezüchtet werden, und bietet sie vertrauenswürdigen Champions an, die in der Lage sind, diese wilden katzenartigen Raubtiere zu bändigen.",al={"wer ist lelanai","lelanai identität","lelanai hintergrundgeschichte"}},["4b3049f5"]={q="Auf wessen Seite steht Lelanai?",a="Lelanai ist Darnassus und der gesamten Allianz treu. Sie vertraut ihre ausgebildeten Säbler bereitwillig ihren Nachtelfen-Mitbürgern an, obwohl sie nur dann in Erwägung zieht, sie anderen Mitgliedern der Allianz anzubieten, wenn diese sich höchstes Ansehen und Vertrauen bei ihrem Volk verdient haben.",al={"lelanai fraktion","ist lelanai bei der allianz","wem dient lelanai"}},["18fb2d04"]={q="Warum ist Lelanai hier in Darnassus?",a="Sie hat ihr Zuhause in der Die Enklave des Cenarius von Darnassus, zusammen mit Jartsam, dem Reitlehrer. Dort, inmitten der friedlichen Zweige von Teldrassil, zieht sie Frostsäbler- und Nachtsäbler-Reittiere auf und pflegt sie, die für die Wächterinnen der Kaldorei und Reisende unerlässlich sind.",al={"warum ist lelanai in darnassus","lelanai zweck der die enklave des cenarius","warum ist lelanai hier"}},["14c3da8f"]={q="Was möchte Lelanai?",a="Lelanai möchte sicherstellen, dass ihre wertvollen Nachtsäbler- und Frostsäbler-Reittiere würdige Reiter finden. Sie besteht darauf, dass jeder, der eines ihrer Tiere reiten möchte, über das richtige Training verfügt und wahre Hingabe und Ehrfurcht gegenüber Darnassus zeigt.",al={"was möchte lelanai","lelanai ziel","lelanai motivation"}},ec77c23e={q="An wen ist Lelanai gebunden?",a="Lelanai arbeitet eng mit Jartsam, dem Nachtelfen-Reitlehrer in der Die Enklave des Cenarius, zusammen. Während Jartsam angehenden Reitern die heikle Kunst des Tigerreitens beibringt, stellt Lelanai die verbundenen Säbler bereit, die sie durch ganz Kalimdor tragen.",al={"lelanai verbindungen","mit wem arbeitet lelanai zusammen","lelanai jartsam"}}},fp="7,257,31.437.0,20.352.0,25.112.0,23.126.0,44.160.0,40.150.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="Leutnant Farren Orinelle",s="Leutnant Farren Orinelle ist ein Offizier der Armee von Sturmwind, der derzeit im Gasthaus von Süderstade im Vorgebirge des Hügellands stationiert ist. Zutiefst unglücklich über seine Stationierung an der Grenze verbringt er die meiste Zeit mit Trinken, während er seine Pflichten an vorbeireisende Reisende auslagert. Sein primärer militärischer Auftrag besteht darin, sich um die vordringenden Murlocs entlang der Küste zu kümmern – eine lästige Pflicht, die er nur allzu gern delegiert, in der Hoffnung, sich eine Versetzung zurück in den Süden zu sichern.",h="Leutnant Farren Orinelle ist ein Offizier der Armee von Sturmwind, der derzeit im Gasthaus von Süderstade im...",kw={"farren","hillsbrad","marshal redpath","murloc","orinelle","versetzung","süderstade","sturmwind"},ang={["faction:Alliance"]="Für die Champions der Allianz repräsentiert Orinelle die verärgerten Truppen des Südens, die einen einsamen Außenposten im Norden halten und jedem Münzen und Belobigungen bieten, der seine Aufgaben übernimmt.",["race:Human"]="Als Soldat aus Sturmwind, der weit weg vom Wald von Elwynn festsitzt, verdeutlicht Orinelles Verachtung für den Dienst an der nördlichen Grenze die Kluft zwischen dem komfortablen Leben in der Hauptstadt und den harten Einsätzen in Übersee."},sec={{t="Exil in Süderstade",b="Leutnant Farren Orinelle hat sich Süderstade nicht ausgesucht. Weit weg von Sturmwind entsandt, empfindet der Lieutenant die feuchten, umkämpften Küsten von Hillsbrad als miserablen Abstieg gegenüber den zivilisierten Annehmlichkeiten der Hauptstadt. Anstatt die Felder zu patrouillieren oder die Verteidigung mit seinem kommandierenden Offizier, Marshal Redpath, zu koordinieren, hat Orinelle praktisch einen ständigen Wohnsitz im Gasthaus von Süderstade bezogen. Seine Tage verbringt er damit, zu schmollen, zu trinken und von einem offiziellen Versetzungsbefehl zu träumen, der ihn in den Süden zurückbringen wird."},{t="Auslagerung der Pflichten",b="Trotz seines bequemen Platzes in der Taverne untersteht Orinelle weiterhin Marshal Redpath, der den Lieutenant damit beauftragte, die Murlocs zu beseitigen, die die nahe gelegene Küste bevölkern. Nicht gewillt, sich die Stiefel im Schlamm der Küste zu beschmutzen, verlässt sich Orinelle auf umherziehende Abenteurer, um die Kreaturen zu dezimieren und Beweise für ihr Ableben zu sammeln. Er hofft, dass die Vorlage greifbarer Ergebnisse gegenüber seinen Vorgesetzten beweist, dass seine Pflicht erfüllt ist, und seine schließliche Rückberufung nach Sturmwind beschleunigt."}},faq={{q="Wer ist Leutnant Farren Orinelle?",a="Er ist ein Offizier des Militärs von Sturmwind, der in Süderstade stationiert ist, einer Stadt im Vorgebirge des Hügellands. Man findet ihn trinkend im Gasthaus von Süderstade, wo er über seinen Posten mürrt.",al={"farren orinelle","wer ist orinelle","süderstade lieutenant"}},{q="Warum ist er in Süderstade?",a="Er wurde aus Sturmwind nach Norden versetzt, um die örtliche Garnison zu verstärken und Marshal Redpath zu unterstützen. Er verabscheut diesen Auftrag zutiefst und sehnt sich danach, nach Hause zurückzukehren.",al={"warum ist farren in süderstade","orinelle versetzung"}},{q="Was ist sein offizieller Auftrag?",a="Marshal Redpath befahl ihm, sich um die feindseligen Murlocs zu kümmern, die die Küste von Hillsbrad heimsuchen, doch Orinelle zieht es vor, reisende Söldner dafür zu bezahlen, die Kämpfe für ihn auszutragen.",al={"farren pflicht","orinelle mission","farren murlocs"}},{q="Verlässt er jemals das Gasthaus von Süderstade?",a="Nein. Orinelle verbringt fast seine gesamte Zeit damit, an der Bar des Gasthauses herumzulungern, da er davor zurückschreckt, den schlammigen Stränden oder den feindseligen Elementen draußen zu trotzen.",al={"wo man farren findet","farren aufenthaltsort","orinelle gasthaus"}},{q="Was ist Farrens eigentliches Ziel?",a="Er wünscht sich nichts sehnlicher als eine offizielle Versetzung zurück nach Sturmwind, weit weg von den Gefahren und der Trostlosigkeit der Küste Lordaerons.",al={"was will farren","versetzung"}},{q="Wer ist Orinelles Kommandant?",a="Er untersteht Marshal Redpath, der die militärische Abteilung der Allianz kommandiert, die Süderstade verteidigt.",al={"farren vorgesetzter","farren boss","wer befehligt farren"}}},fx={["7d023078"]={q="Auf wessen Seite steht Leutnant Farren Orinelle?",a="Leutnant Orinelle dient der Großen Allianz und berichtet direkt an die Streitkräfte von Sturmwind. Obwohl er sein derzeitiges Kommando im Vorgebirge des Hügellands verabscheut, stellt ihn sein Posten unter Marshal Redpath direkt auf die Seite der Verteidiger von Süderstade gegen regionale Schrecken und die Aggression der Horde.",al={"orinelle fraktion","farren orinelle allianz","wem dient farren"}}},fp="26,423,19.515.0,16.458.0,34.183.0,24.167.0,32.172.0,38.136.0,31.143.0,28.98.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="Leutnant Haggerdin",s="Leutnant Haggerdin ist ein Zwergenoffizier, der auf dem Headland im Alteracgebirge stationiert ist. Er hält Wache vor dem befestigten Tor zum Alteractal und fungiert als primärer Rekrutierungs- und Verbindungsoffizier für die Stormpikegarde. Er beurteilt aufstrebende Champions der Allianz und belohnt jene, die ihren Mut gegen den Frostwolfklan unter Beweis stellen.",h="Leutnant Haggerdin ist ein Zwergenoffizier, der auf dem Headland im Alteracgebirge stationiert ist.",kw={"alterac","zwerg","frostwolf","haggerdin","headland","eisenschmiede","leutnant","proving grounds","stormpike"},ang={["faction:Alliance"]="Leutnant Haggerdin ist Euer primärer Ansprechpartner außerhalb des Alteractals und bietet die Ausweise und offiziellen Ehren an, die Ihr Euch im Kampf gegen den Frostwolfklan verdient habt.",["faction:Horde"]="Als standhafter Posten, der das Portal der Allianz in das Alteractal bewacht, leitet Haggerdin die Verstärkung an, die entsandt wurde, um die Frostwolforcs zu zerschlagen.",["race:Dwarf"]="Als stolzer Offizier des Stormpike-Klans verkörpert Haggerdin Eisenschmiedes unerschütterliche Entschlossenheit, ihr titanisches Erbe in den verschneiten Klüften von Alterac aufzudecken."},sec={{t="Torwächter des Headland",b="In den verschneiten Höhen des Headland oberhalb des Vorgebirges des Hügellands gelegen, überwacht Leutnant Haggerdin den Sammelpunkt für den anhaltenden Feldzug der Allianz im Alteractal. Zwergische Banner flattern neben dem massiven Holztor, während sich Rekruten und Veteranen unter seinen wachsamen Augen versammeln und sich darauf vorbereiten, in das eisige Kriegsgebiet vorzudringen."},{t="Stimme der Stormpikegarde",b="Im Dienst der Stormpike-Expedition stellt Haggerdin sicher, dass nur erprobte Krieger Eisenschmiede und die Große Allianz im Tal vertreten. Durch Herausforderungen wie die Proving Grounds beauftragt er Rekruten mit der Bergung von Bannern und Relikten und verleiht offizielle Belobigungen, Abzeichen und Ranganerkennungen, während die Soldaten in den Rängen der Stormpikegarde aufsteigen."}},faq={{q="Wer ist Leutnant Haggerdin?",a="Leutnant Haggerdin ist ein Zwergenoffizier, der die Stormpikegarde vertritt. Am Eingang zum Alteractal auf dem Headland im Alteracgebirge stationiert, überwacht er die Rekrutierung der Allianz und verleiht Schlachtfeldehren.",al={"haggerdin","wer ist haggerdin","leutnant haggerdin alterac"}},{q="Wo finde ich Leutnant Haggerdin?",a="Er befindet sich im nördlichen Alteracgebirge auf dem Headland, direkt vor dem Portal und den Toren, die unmittelbar in das Alteractal führen.",al={"haggerdin standort","wo ist leutnant haggerdin","alteractal eingang allianz"}},{q="Welche Rolle spielt Haggerdin in der Stormpikegarde?",a="Er dient als Feldverbindungs- und Quartiermeisteroffizier, der Rekrutierungsprüfungen wie die Proving Grounds leitet und Kämpfer der Allianz mit höheren Rängen und Abzeichen belohnt, während ihr Ruf bei der Stormpikegarde wächst.",al={"was macht haggerdin","haggerdin quests","offizier der stormpikegarde"}},{q="Warum kämpft die Allianz im Alteractal?",a="Die Stormpike-Expedition reiste in das Tal, um uralte Relikte und die Geschichte der Zwerge auszugraben, doch ihre Ankunft entfachte einen erbitterten territorialen Konflikt mit den dort ansässigen Frostwolforcs und ihren Verbündeten der Horde.",al={"warum alteractal","ziel der stormpike-expedition","alterackonflikt"}},{q="Können Spieler der Horde mit Leutnant Haggerdin interagieren?",a="Nein. Leutnant Haggerdin ist ein aktiver Offizier der Allianz und wird jeden Champion der Horde angreifen, der sich in die Nähe des Tors am Headland wagt.",al={"ist haggerdin feindselig gegenüber der horde","horde haggerdin","kann horde mit haggerdin sprechen"}},{q="Was ist die Prüfung der Proving Grounds?",a="Die Proving Grounds sind ein einführender Auftrag, den Haggerdin angehenden Soldaten der Allianz erteilt, um deren Kompetenz und Entschlossenheit zu prüfen, bevor sie sich voll und ganz den Kriegsanstrengungen im Alteractal verschreiben.",al={"quest proving grounds","proving grounds alterac","haggerdin proving grounds"}}},fx={["1d45d886"]={q="Auf wessen Seite steht Leutnant Haggerdin?",a="Leutnant Haggerdin ist der Allianz absolut treu ergeben und dient speziell in der Stormpikegarde. Er operiert am nördlichen Rand des Vorgebirges nahe dem Alteractal und fungiert als Offizier und Musterungsbeauftragter für Allianzstreitkräfte, die sich gegen die Frostwolf-Orks sammeln.",al={"haggerdin fraktion","ist haggerdin bei der allianz","haggerdin zugehörigkeit"}},["5fb68a23"]={q="Was möchte Leutnant Haggerdin?",a="Haggerdin möchte fähige Allianz-Champions, um die Reihen der Stormpikegarde im Alteractal zu verstärken. Er testet neue Rekruten, um sicherzustellen, dass sie die eisige Wildnis überleben können, erkennt erfahrene Veteranen mit Rängen und Abzeichen an, wenn ihre Taten wachsen, und strebt den Untergang von Bedrohungen wie dem Winterax-Trollchampion Korrak an.",al={"was möchte haggerdin","haggerdin ziele","haggerdin zweck"}},["96f37aaa"]={q="Warum ist Leutnant Haggerdin hier im Alterac-Vorgebirge?",a="Leutnant Haggerdin ist am Headland stationiert, das das Tor zum Alteractal überblickt, um eintreffende Allianzstreitkräfte zu organisieren und zu überprüfen. Da der anhaltende Zusammenstoß zwischen der Stormpike-Expedition und dem Frostwolfklan ständige Verstärkung erfordert, hält er an den Bereitstellungsplätzen Wache, um diejenigen zu rekrutieren und zu ehren, die bereit sind, im Schnee zu kämpfen.",al={"warum ist haggerdin hier","warum ist haggerdin im alterac","haggerdin posten"}},["9b7a183a"]={q="An wen ist Leutnant Haggerdin gebunden?",a="Haggerdin ist direkt an die Stormpikegarde gebunden, den militärischen Arm der Stormpike-Expedition von Eisenschmiede unter der Führung von General Vanndar Sturmlanze. Er dient als Offizier, der Allianz-Rekruten, die durch das Alteracgebirge ankommen, mit dem Regiment verbindet, das tief im Alteractal kämpft.",al={"haggerdin verbindungen","haggerdin stormpikegarde","wem dient haggerdin"}}},fp="20,345,26.335.0,28.362.0,28.224.0,38.145.0,53.231.0,47.211.0,53.126.0,34.195.0"}
P.entries["npc:lieutenant-lisande"] = {n="Leutnant Lisande",s="Leutnant Lisande ist eine Gesandte der Argentumdämmerung, die auf den hohen Hochebenen von Donnerfels stationiert ist. Als Mensch, der sich offen in den Ländern der Tauren aufhält, dient sie als Verbindungsperson gegen die gemeinsame existenzielle Bedrohung durch die Geißel.",h="Leutnant Lisande ist eine Gesandte der Argentumdämmerung, die auf den hohen Hochebenen von Donnerfels...",kw={"argentumdämmerung","leutnant lisande","lisande","mulgore","geißel","invasion der geißel","donnerfels"},ang={["faction:Horde"]="Lisande dient als Erinnerung daran, dass der Krieg gegen die Geißel Pragmatismus und gelegentliche Zusammenarbeit mit neutralen menschlichen Orden erfordert.",["race:Tauren"]="Obwohl Lisande eine Außenstehende ist, respektieren die Tauren die Hingabe der Argentumdämmerung, das Land von der abscheulichen Verderbnis der Untoten zu reinigen."},sec={{t="Eine ungewöhnliche Gesandte",b="Während menschliche Gesichter auf den windgepeitschten Höhen von Donnerfels eine Seltenheit sind, steht die Argentumdämmerung über den traditionellen Feindseligkeiten der Fraktionen. Leutnant Lisande dient dem heiligen Orden, indem sie selbst im fernen Kalimdor nach Anzeichen für das Verderben des Lichkönigs Ausschau hält. Wenn sich untote Streitkräfte in den Ebenen darunter regen, ruft sie tapfere Champions der Horde zusammen, um auszureiten und der herannahenden Bedrohung nachzugehen, bevor sie die heilige Erde entweihen kann."}},faq={{q="Warum steht ein Mensch in Donnerfels?",a="Lisande vertritt die Argentumdämmerung, eine neutrale Organisation, die sich einzig der Vernichtung der Geißel verschrieben hat. Da die Dämmerung sowohl Völker der Allianz als auch der Horde in ihren Reihen willkommen heißt, wird ihren Verbindungspersonen diplomatischer Zutritt zu den Hauptstädten gewährt, um die Verteidigung gegen die Untoten zu koordinieren.",al={"mensch in donnerfels","warum ist lisande hier","ist sie feindselig"}},{q="Welches Interesse hat die Argentumdämmerung an Mulgore?",a="Die Reichweite des Lichkönigs bedroht jeden Winkel von Azeroth, nicht nur die Östlichen Königreiche. Lisande überwacht jegliche Anzeichen nekromantischer Aktivitäten oder einfallender Streitkräfte der Geißel, die den Frieden von Mulgore gefährden, und sorgt dafür, dass die örtlichen Verteidiger vor der Gefahr gewarnt sind.",al={"geißel in mulgore","warum donnerfels","untote im taurenland"}},{q="Welche Aufgaben vergibt Leutnant Lisande?",a="Lisande weist Abenteurer an, von den Klippen herabzusteigen, um Übergriffen der Geißel nachzugehen, die im Umland gesichtet wurden, und beauftragt sie damit, Bericht zu erstatten, damit die Dämmerung das Ausmaß der Bedrohung einschätzen kann.",al={"lisande quest","was tut lisande","untersuchungsquest"}}},fx={["0fde76ad"]={q="An wen ist Leutnant Lisande gebunden?",a="Sie ist direkt an die Argentumdämmerung gebunden, einen unabhängigen Orden aus heiligen Kriegern, Magiern und Spähern verschiedenster Völker, der gegründet wurde, um die Geißel überall dort zu bekämpfen, wo die untote Bedrohung ihr Haupt erhebt.",al={"lisande fraktion","mit wem arbeitet lisande zusammen","lisande verbindungen"}},["986453a4"]={q="Wer ist Leutnant Lisande?",a="Leutnant Lisande ist eine Offizierin, die der Argentumdämmerung dient. Obwohl sie ein Mensch im Herzen des Territoriums der Horde ist, steht sie offen in Donnerfels, um tapfere Verteidiger gegen eine Bedrohung zu versammeln, die alles Lebendige gefährdet.",al={"wer ist lisande","leutnant lisande identität","wer ist leutnant lisande"}},b5328b2a={q="Auf wessen Seite steht Leutnant Lisande?",a="Lisande ist der Argentumdämmerung treu und nicht der Allianz. Die Dämmerung ist ein neutrales Bündnis, das sich vollständig dem Kampf gegen die Geißel widmet, was es ihr ermöglicht, ohne fraktionsbedingte Feindseligkeiten direkt mit den Tauren und Champions der Horde zusammenzuarbeiten.",al={"lisande allianz oder horde","wem dient lisande","ist lisande bei der allianz"}},["9158bc2a"]={q="Was möchte Leutnant Lisande?",a="Lisande möchte wachsame Abenteurer, die die Streitkräfte der Geißel untersuchen und bekämpfen, die auf das Land außerhalb von Donnerfels übergreifen. Ihr Ziel ist es, die Bedrohung durch die Untoten einzudämmen, bevor sie die Ebenen von Mulgore überrennen kann.",al={"was möchte lisande","lisande ziele","warum braucht lisande hilfe"}}},fp="18,223,17.412.0,41.280.0,46.253.0,44.211.0"}
P.entries["npc:lieutenant-nevell"] = {n="Leutnant Nevell",s="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der vor den Toren von Eisenschmiede in Dun Morogh stationiert ist. Als Bollwerk gegen die sich ausbreitende Dunkelheit der Geißel koordiniert er die örtlichen Verteidiger und warnt eintreffende Abenteurer vor untoten Bedrohungen, die die Grenzen des Zwergenreichs auskundschaften.",h="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der vor den Toren von Eisenschmiede in Dun Morogh...",kw={"argentumdämmerung","dun morogh","eisenschmiede","leutnant nevell","nevell","geißel"},ang={["faction:Alliance"]="Für Champions der Allianz, die nach Eisenschmiede reisen, dient Nevell als Mahnung, dass der Krieg gegen die Geißel nicht auf den Norden beschränkt ist.",["race:Dwarf"]="Die Zwerge schätzen das wachsamen Auge der Argentumdämmerung vor ihrer bergigen Heimat wohlwissend, dass Wachsamkeit gegenüber Nekromantie selbst an den kalten Hängen von Dun Morogh geboten ist."},sec={{t="Eine Wacht im Schnee",b="Während die Argentumdämmerung vor allem dafür bekannt ist, die Stellung in den zerrütteten Pestländern von Lordaeron zu halten, reicht ihre Wachsamkeit weit in den Süden. In den eisigen Winden vor Eisenschmiede stationiert, verkörpert Leutnant Nevell die vorausschauende Verteidigung des Ordens gegen nekromantische Übergriffe. Wenn sich Geißelaktivitäten in den Bergpässen von Dun Morogh regen, weist Nevell Rekruten und fähige Abenteurer an die Frontlinien ein, um sicherzustellen, dass Eisenschmiedes schneebedeckte Schwelle sicher bleibt."}},faq={{q="Wer ist Leutnant Nevell?",a="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der nahe Eisenschmiede in Dun Morogh stationiert ist. Seine Mission besteht darin, lokale Verteidiger zu sammeln und Hinweisen auf eine Präsenz der Geißel nachzugehen, die auf das Zwergenreich übergreift.",al={"nevell rolle","wer ist nevell","leutnant nevell"}},{q="Warum befindet sich die Argentumdämmerung vor Eisenschmiede?",a="Obwohl sie hauptsächlich in Lordaeron ansässig ist, überwacht die Argentumdämmerung den gesamten Kontinent auf Übergriffe der Untoten. Sollte der Lichkönig versuchen, tief in verbündete Gebiete wie Dun Morogh vorzustoßen, werden Offiziere wie Nevell entsandt, um die Stadtverteidigung zu koordinieren und feindliche Truppenbewegungen auszuspähen.",al={"argentumdämmerung in dun morogh","argentumdämmerung eisenschmiede"}},{q="Worum bittet Leutnant Nevell die Abenteurer?",a="Nevell beauftragt fähige Helden damit, hinter die Tore von Eisenschmiede vorzudringen, um nahe Streitkräfte der Geißel aufzuklären und zurückzuschlagen, wodurch die untote Bedrohung neutralisiert wird, bevor sie in den Bergpässen Fuß fassen kann.",al={"nevell quests","die geißel untersuchen"}}},fx={["4853a4a6"]={q="Auf wessen Seite steht Leutnant Nevell?",a="Leutnant Nevell dient der Argentumdämmerung, einem entschlossenen neutralen Orden, der sich dem Schutz Azeroths vor der Geißel verschrieben hat. Obwohl er ein Mensch ist, steht er als Verbündeter aller Gegner der untoten Bedrohung vor den Toren von Eisenschmiede und koordiniert die Verteidigung gemeinsam mit den Zwergen, anstatt direkt dem Militär der Allianz zu dienen.",al={"leutnant nevell fraktion","für wen kämpft leutnant nevell","ist nevell argentumdämmerung"}},["5e43a7a7"]={q="An wen ist Leutnant Nevell gebunden?",a="Nevell berichtet direkt an die Führung der Argentumdämmerung. Stationiert an den Hängen von Dun Morogh, fungiert er als Verbindungsperson zwischen dem Orden und den Verteidigern von Eisenschmiede und versammelt lokale Abenteurer und Gebirgswachen, um jede schleichende Bedrohung durch die Geißel in der Region zu bekämpfen.",al={"nevell verbindungen","leutnant nevell argentumdämmerung bindungen","wem untersteht nevell"}}},fp="17,292,19.476.0,25.208.0,41.278.0,50.205.0"}
P.entries["npc:lieutenant-orrin"] = {n="Leutnant Orrin",s="Leutnant Orrin ist ein Offizier der Argentumdämmerung, der an den Toren von Sturmwind stationiert ist. Im Tal der Helden positioniert, koordiniert er die lokale Verteidigung gegen Übergriffe der Geißel und weist neue Rekruten an, untote Bedrohungen außerhalb der Mauern der Hauptstadt zu untersuchen.",h="Leutnant Orrin ist ein Offizier der Argentumdämmerung, der an den Toren von Sturmwind stationiert ist.",kw={"argentumdämmerung","leutnant orrin","nekrotischer kristall","orrin","geißel","sturmwind","untote","das tal der helden"},ang={["class:Paladin"]="Paladine, die das Licht hochhalten, finden oft eine natürliche Gemeinsamkeit mit den Bemühungen der Argentumdämmerung, die Nekromantie überall dort auszumerzen, wo sie schwelt.",["faction:Alliance"]="Für Champions der Allianz, die in die Hauptstadt zurückkehren, dient Orrin als deutliche Mahnung, dass selbst das südliche Kernland nicht gänzlich vor der Reichweite des Lichkönigs sicher ist."},sec={{t="Ein Wächter an den Toren",b="Obwohl die Argentumdämmerung vor allem dafür bekannt ist, die Frontlinien im zerstörten Norden zu halten, reicht ihre Präsenz bis in den Süden, um lebenswichtige Festungen wie Sturmwind zu schützen. Leutnant Orrin steht nahe den hoch aufragenden Statuen im Tal der Helden und beobachtet die Straße auf Anzeichen von Verderbnis. Wenn sich außerhalb der Hauptstadt nekromantische Magie regt, obliegt es ihm, Alarm zu schlagen und Abenteurer zu sammeln, bevor finstere Mächte die Bevölkerung bedrohen können."},{t="Ein wachsames Auge auf die Untoten",b="Orrin fungiert als wichtiges Bindeglied zwischen dem unabhängigen Orden und Freiwilligen im südlichen Königreich. Wenn jenseits der Stadttore Anzeichen der Geißel auftauchen, stellt er fähige Späher zusammen und schickt sie aus, um Informationen zu sammeln und gefährliche Artefakte wie gesprungene nekrotische Kristalle zu sichern, um die Bedrohung durch die Untoten besser zu verstehen und abzuwehren."}},faq={{q="Wer ist Leutnant Orrin?",a="Leutnant Orrin ist ein menschlicher Offizier im Dienst der Argentumdämmerung. Er ist im Tal der Helden am Eingang von Sturmwind stationiert und damit beauftragt, die Verteidigung zu koordinieren und Späher anzuwerben, wann immer die Geißel das Umland bedroht.",al={"wer ist orrin","leutnant orrin lore","wer ist der offizier der argentumdämmerung"}},{q="Warum befindet sich die Argentumdämmerung in Sturmwind?",a="Obwohl die Argentumdämmerung ihren Krieg gegen die Geißel hauptsächlich in den Plaguelands führt, unterhält sie Außenposten und Verbindungsoffiziere in bedeutenden Zentren der Allianz und der Horde. An den Toren der Hauptstadt stationiert, halten Offiziere wie Orrin Ausschau nach nekromantischen Übergriffen und rekrutieren fähige Kämpfer, um die Ausbreitung der Untoten einzudämmen.",al={"warum ist die argentumdämmerung in sturmwind","argentumdämmerung sturmwind","was macht die argentumdämmerung hier"}},{q="Worum bittet Leutnant Orrin die Abenteurer?",a="Orrin weist Rekruten an, die Umgebung außerhalb von Sturmwind auszukundschaften, Anzeichen von Aktivitäten der Geißel nachzugehen und Artefakte wie gesprungene nekrotische Kristalle zu bergen, um die unheilige Magie hinter den Übergriffen zu erforschen.",al={"orrin quests","erforscht die geißel von sturmwind","was will orrin"}}},fx={["3ede5d84"]={q="Auf wessen Seite steht Leutnant Orrin?",a="Leutnant Orrin dient der Argentumdämmerung, einem entschlossenen neutralen Bündnis, das geformt wurde, um die Geißel überall dort zu bekämpfen, wo sie Azeroth bedroht. Obwohl er innerhalb des Tals der Helden von Sturmwind inmitten menschlicher Verteidiger stationiert ist, bleibt seine primäre Loyalität der heiligen Mission der Dämmerung und nicht der Politik der Allianz gewidmet.",al={"leutnant orrin fraktion","wem dient orrin","ist leutnant orrin allianz"}}},fp="16,276,23.446.0,20.352.0,24.244.0,41.313.0,49.210.0"}
P.entries["npc:loganaar"] = {n="Loganaar",s="Loganaar ist ein Nachtelf und Ausbilder der Druiden, der in der Zuflucht Nachthafen in Mondlichtung weilt. Er widmet sich der Führung von Initianden sowohl der Allianz als auch der Horde und unterweist junge Druiden, während sie sich auf die Wildnis einstimmen und sich auf den Ruf des Smaragdgrünen Traums vorbereiten.",h="Loganaar ist ein Nachtelf und Ausbilder der Druiden, der in der Zuflucht Nachthafen in Mondlichtung weilt.",kw={"zirkel des cenarius","druidenlehrer","smaragdgrüner traum","loganaar","mondlichtung","nachthafen"},ang={["class:Druid"]="Sowohl für Druiden aus Darnassus als auch aus Donnerfels ist Loganaar einer der ersten Mentoren, denen sie nach der Teleportation nach Mondlichtung begegnen, und er bietet fortgeschrittene Ausbildung sowie spirituellen Rat.",["race:NightElf"]="Loganaar spiegelt die uralten Traditionen der Druiden der Kaldorei wider, die Jahrtausende damit verbrachten, Zwiesprache mit der Natur zu halten und unter Malfurion Sturmgrimm in den Smaragdgrünen Traum einzutreten."},sec={{t="Hüter der heiligen Kunst",b="Inmitten der ruhigen Baumkronen von Nachthafen dient Loganaar als ein zentraler Mentor für frisch initiierte Druiden, die nach Mondlichtung reisen. Unabhängig davon, ob ein Novize aus Darnassus oder Donnerfels stammt, vermittelt Loganaar Weisheit über Gleichgewicht, Gestaltwandlung und die Ehrfurcht vor der Natur. Er erinnert seine Schüler daran, dass wahre Seelenruhe selbst inmitten kalter Steine und fremder Lande im eigenen Inneren gefunden werden muss. Zudem fungiert er als einladender Wegweiser für jene, die tiefer in die Belange des Zirkels des Cenarius eintauchen, und schickt vielversprechende Schüler zu Wanderern wie Torwa Pfadfinder im Krater von Un'Goro oder tiefer in uralte Waldriten."},{t="Der Ruf des Traums",b="Über die grundlegende Zauberkunst hinaus bereitet Loganaar die Schüler auf die höchste Bestimmung vor, die alle traditionellen Beschützer Kalimdors teilen: den tiefen Schlummer des Smaragdgrünen Traums. Er lehrt die Initianden über die heilige Verbindung zwischen Azeroths urzeitlicher Geisterwelt und der wachenden Welt und erinnert sie daran, dass wahre Meisterschaft eines Tages einen jahrhundertelangen Winterschlaf erfordern wird, um unter der Führung der Halbgötter inmitten der reinsten, unberührten Formen der Natur zu wandeln."}},faq={{q="Wer ist Loganaar?",a="Loganaar ist ein Nachtelf-Druidenlehrer in Nachthafen, der zentralen Siedlung von Mondlichtung. Er heißt Druiden jeder Herkunft willkommen, um sie in ihren Künsten zu unterweisen, und führt sie an die tieferen Traditionen des Zirkels des Cenarius heran.",al={"loganaar nsc","wer ist loganaar","loganaar lore"}},{q="Bildet Loganaar Horde-Druiden aus?",a="Ja. Mondlichtung ist heiliger, neutraler Boden unter der Obhut des Zirkels des Cenarius. Als Mitglied des Zirkels legt Loganaar den Konflikt zwischen der Allianz und der Horde beiseite, um Tauren- und Nachtelfen-Druiden gleichermaßen zu unterrichten.",al={"können tauren bei loganaar trainieren","loganaar horde","druidenlehrer mondlichtung horde"}},{q="Was lehrt Loganaar über den Smaragdgrünen Traum?",a="Loganaar lehrt, dass jeder wahre Druide letztlich den Ruf des Smaragdgrünen Traums spüren wird. Er erklärt, dass während eines langen, tiefen Winterschlafs inmitten seiner unberührten Formen die eigentliche, vollendete Ausbildung eines Druiden stattfindet.",al={"loganaar traum","smaragdgrüner traum zitat"}},{q="Wohin schickt Loganaar erfahrene Druiden?",a="Sobald Druiden an Erfahrung gewinnen, weist Loganaar ihnen den Weg hinaus in die Welt, um Azeroths ursprüngliche Ökosysteme zu beobachten und zu heilen. Unter anderem entsendet er erfahrene Schüler, um Naturforschern wie Torwa Pfadfinder in der ungezähmten Wildnis des Un'Goro-Kraters beizustehen.",al={"loganaar quests","torwa pfadfinder quest loganaar"}}},fp="8,261,24.626.0,21.439.0,16.225.0,33.211.0,49.225.0,41.245.0"}
P.entries["npc:lomac-gearstrip"] = {n="Lomac Ritzeldreh",s="Lomac Ritzeldreh ist ein ehrgeiziger Gnomen-Erfinder, der in Tüftlerstadt in Eisenschmiede ansässig ist. Bekannt für die Entwicklung des verheerenden NG-5-Sprengstoffs, steht er in Verbindung mit anderen Gnomenforschern, die in ganz Kalimdor tätig sind.",h="Lomac Ritzeldreh ist ein ehrgeiziger Gnomen-Erfinder, der in Tüftlerstadt in Eisenschmiede ansässig ist.",kw={"ein alter kollege","gnomen-ingenieur","stümperhaftigkeit + chemikalien = riesenspaß!","eisenschmiede","lomac ritzeldreh","ng-5 sprengstoff","steinkrallengebirge","tüftlerstadt"},ang={["faction:Alliance"]="Allianz-Agenten, die zwischen Eisenschmiede und Expeditionsaußenposten in Kalimdor reisen, transportieren im Auftrag von Lomac häufig heikle Munition und flüchtige Formeln.",["profession:Engineering"]="Lomacs NG-5-Sprengstoff repräsentiert den neuesten Stand der Gnomen-Pyrotechnik und dient Tüftlern, die sich für Sprengstoffe mit enormer Wirkung interessieren, als Vorbild.",["race:Gnome"]="Lomac verkörpert den unermüdlichen Tatendrang der Gnome von Tüftlerstadt und führt anspruchsvolle technische Forschungen selbst im Exil fernab von Gnomeregan fort."},sec={{t="Ein Funke in Tüftlerstadt",b="Inmitten der klappernden Zahnräder und zischenden Rohre von Eisenschmiedes Tüftlerstadt widmet sich Lomac Ritzeldreh den Feinheiten der Gnomen-Artillerie. Wie viele exilierte Gnom, die vor der Tragödie in Gnomeregan flohen, hat Lomac seine Tüfteleien direkt in die Zwergenhauptstadt verlegt. Seine Werkstatt konzentriert sich auf flüchtige chemische Gemische und Spezialmunition, die darauf ausgelegt sind, schwer verteidigte feindliche Festungen zu überwinden."},{t="Der NG-5-Sprengstoff",b="Lomacs stolzester Beitrag zur modernen Kampftechnik ist der NG-5-Sprengstoff. Für maximale Zerstörungskraft entwickelt, verlangt das Gemisch präzise Handhabung und seltene chemische Reagenzien. Um derart gefährliche Erfindungen im Feld zu verfeinern und einzusetzen, hält Lomac Kontakt zu alten Kollegen, die auf fernen Kriegsschauplätzen stationiert sind, und tauscht technische Aufträge und gefährliche Lieferungen über das große Meer hinweg aus."}},faq={{q="Wo kann ich Lomac Ritzeldreh finden?",a="Lomac Ritzeldreh befindet sich in Tüftlerstadt, dem Gnomenviertel im östlichen Teil der Bergstadt Eisenschmiede.",al={"lomac ritzeldreh standort","wo ist lomac","lomac ritzeldreh finden"}},{q="Wofür ist Lomac Ritzeldreh als Erfinder berühmt?",a="Lomac ist vor allem als Schöpfer des NG-5-Sprengstoffs bekannt, einer mächtigen Geschützformel, die den Unternehmungen der Gnome verheerende Feuerkraft verleihen soll.",al={"was hat lomac gebaut","lomac erfindung","ng-5 sprengstoff entwickler"}},{q="Warum hat Lomac Kontakte in Kalimdor?",a="Lomac hält Kontakt zu früheren Forscherkollegen, die in Grenzregionen wie dem Steinkrallengebirge arbeiten, koordiniert die Beschaffung gefährlicher chemischer Zutaten und testet seine Sprengstoffe mit hoher Sprengkraft in aktiven Operationen.",al={"lomac steinkrallengebirge","warum steinkrallengebirge quest","lomac kollegen"}},{q="Welche Aufgaben überträgt Lomac Abenteurern?",a="Lomac beauftragt vertrauenswürdige Kuriere der Allianz damit, Bestellungen und flüchtige chemische Reagenzien zwischen Eisenschmiede und im Ausland stationierten Forschern zu transportieren, oft im Zusammenhang mit Experimenten an seinem NG-5-Sprengstoff.",al={"lomac quests","chemikalien ungeschicklichkeit spaß","ein alter kollege quest"}},{q="Was ist die mit Lomac verbundene Purchase Order Receipt?",a="Lomac hat die Purchase Order Receipt verfasst, ein Dokument, das dazu dient, Lieferungen von Spezialausrüstung und gefährlichen, flüchtigen Reagenzien zwischen Tüftlern zu organisieren und festzuhalten.",al={"purchase order receipt","lomac beleg"}},{q="Gehört Lomac zu den Flüchtlingen aus Gnomeregan?",a="Ja. Wie die übrigen Bewohner von Tüftlerstadt gehört Lomac zur vertriebenen Gemeinschaft von Gnomeregan, die die Gastfreundschaft der Zwerge von Eisenschmiede genießt, während er seine Ingenieursarbeiten fortsetzt.",al={"stammt lomac aus gnomeregan","lomac fraktion"}}},fx={e46167fb={q="Wer ist Lomac Ritzeldreh?",a="Lomac Ritzeldreh ist ein ehrgeiziger gnomischer Erfinder und Tüftler, der in der Tüftlerstadt innerhalb der Zwergenfestung Eisenschmiede operiert. Er ist tief in unbeständige Experimente und Chemieingenieurwesen vertieft und vor allem für die Entwicklung potenter Kampfmittel wie des NG-5-Sprengsatzes bekannt. Trotz der Entfernung über das große Meer unterhält er Kontakte und geschäftliche Vereinbarungen bis hin nach Kalimdor, um seltene Materialien und Feldtests für seine Arbeit zu erhalten.",al={"wer ist lomac","wer ist ritzeldreh","lomac ritzeldreh hintergrund"}},["6618560a"]={q="Was will Lomac Ritzeldreh?",a="Lomac Ritzeldreh wird von seinen explosiven Ingenieursprojekten angetrieben, allen voran der Verfeinerung seines geschätzten NG-5-Sprengsatzes. Um seine chemischen Versuche voranzutreiben, benötigt er Kuriere, flüchtige Verbindungen und Feldtests, die mit seinen Gebräuen durchgeführt werden. Er verlässt sich auf Reisende und alte Bekannte in aller Welt, um Bestellungen auszuführen und die seltenen Reagenzien zu beschaffen, die nötig sind, um seine instabilen Erfindungen zu perfektionieren.",al={"was will lomac","lomac ritzeldreh ziele","warum braucht lomac hilfe"}},ca50cdb6={q="An wen ist Lomac Ritzeldreh gebunden?",a="Lomac unterhält Beziehungen zu weit entfernten Mitarbeitern und anderen Tüftlern, einschließlich eines alten Kollegen im Ausland, der ihn bei Bestellungen und spezialisierten Tests unterstützt. Von der Tüftlerstadt aus arbeitet er komfortabel sowohl mit den Gnomeregangnome als auch mit den ansässigen Handwerkern von Eisenschmiede zusammen und weist Kuriere und Abenteurer an, zwischen seiner Werkbank in den Östlichen Königreichen und den Testgeländen in ganz Kalimdor zu vermitteln.",al={"mit wem arbeitet lomac zusammen","lomac ritzeldreh mitarbeiter","lomac alter kollege"}}},fp="15,212,22.406.0,18.398.0,33.125.0,45.148.0,46.240.0,51.206.0,49.169.0,47.196.0"}
P.entries["npc:longbraid-the-grim"] = {n="Langzopf der Grimmige",s="Langzopf der Grimmige ist ein Zwergenkommandant aus Eisenschmiede, der direkt vor der gefallenen Festung Dun Modr im nördlichen Sumpfland stationiert ist. Er betrauert den Verlust seines Bruders sowie die Einnahme des Thandol-Übergangs und koordiniert die überlebenden Zwergentruppen gegen den eindringenden Dunkeleisenzwerge-Clan.",h="Langzopf der Grimmige ist ein Zwergenkommandant aus Eisenschmiede, der direkt vor der gefallenen Festung Dun...",kw={"dunkeleisenzwerge","dun modr","longbraid","thandol-übergang","der grimmige","sumpfland","whelgar"},ang={["faction:Alliance"]="Longbraid hält die dünne Verteidigungslinie am Nordtor von Khaz Modan und kämpft dafür, die wichtige Landverbindung über den Thandol-Übergang nach Arathi wieder zu öffnen.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede verkörpert Longbraid die erbitterte, anhaltende Blutfehde gegen ihre verräterischen Dunkeleisen-Vettern, die direkt an ihrer nördlichen Pforte zuschlugen."},sec={{t="Eine bittere Wacht",b="In Sichtweite der Brücke zum Arathihochland sammelt Langzopf der Grimmige die Reste der Zwergengarnison, nachdem der Dunkeleisenclan Dun Modr eingenommen hat. Der überraschende Angriff vernichtete die regionalen Verteidiger und forderte während der Belagerung des Thandol-Übergangs das Leben von Longbraids eigenem Bruder. Gezeichnet von Trauer und Hass weigert sich Longbraid, die nördliche Grenze aufzugeben, und leitet Reisende sowie überlebende Gebirgsjäger bei gezielten Vorstößen an, um das Vordringen der Dunkeleisenzwerge einzudämmen."},{t="Die Stellung halten",b="Über die Verteidigung des Zugangs zur Brücke hinaus beaufsichtigt Longbraid weiter reichende Zwergenoperationen im gesamten Sumpfland. Er entsandte unverzichtbare Soldaten zur Eskorte von Ausgrabungsleiter Whelgar in den Marschen und arbeitet unermüdlich daran, die verlorenen Befestigungen von Dun Modr zurückzuerobern, während er den Saboteuren der Dunkeleisenzwerge Vergeltung schwört."}},faq={{q="Wer ist Langzopf der Grimmige?",a="Langzopf der Grimmige ist ein Zwergenkommandant, der vor Dun Modr im nördlichen Sumpfland stationiert ist. Er führt den lokalen Widerstand der Allianz gegen die Dunkeleisenzwerge an, die das Gebiet überrannt haben.",al={"wer ist longbraid","identität von longbraid","dun modr zwerg"}},{q="Warum wird Longbraid 'der Grimmige' genannt?",a="Er erhielt sein grimmiges Wesen, nachdem sein Bruder während des verheerenden Angriffs der Dunkeleisenzwerge auf den Thandol-Übergang getötet wurde. Seither ist er von dem Verlangen getrieben, seinen gefallenen Verwandten zu rächen.",al={"warum ist er grimmig","longbraids bruder","longbraid hintergrundgeschichte"}},{q="Was geschah mit Dun Modr?",a="Dun Modr wurde vom Dunkeleisenclan überrannt und besetzt, der die Zwergengarnison überfiel und versuchte, den Thandol-Übergang zu zerstören, um die Hauptroute zwischen dem Sumpfland und dem Arathihochland abzuschneiden.",al={"der fall von dun modr","was geschah mit der brücke","angriff auf den thandol-übergang"}},{q="Was verbindet Longbraid mit Ausgrabungsleiter Whelgar?",a="Longbraid stellte Soldaten seiner Truppen ab, um Ausgrabungsleiter Whelgar zu begleiten und zu beschützen, als das zwergische Ausgrabungsteam tiefer in das gefährliche Sumpfland vordrang.",al={"whelgar longbraid","merrins brief"}}},fx={d54d2b61={q="Auf wessen Seite steht Langzopf der Grimmige?",a="Langzopf der Grimmige dient Eisenschmiede und der Allianz. Im nördlichen Sumpfland stationiert, befehligt er zwergische Streitkräfte, die versuchen, die Stellung gegen den Dunkeleisenclan zu halten, der Dun Modr besetzt und The Thandol Span beschädigt hat.",al={"langzopf fraktion","wem dient langzopf","langzopf allianz"}},["40b05609"]={q="Was will Langzopf der Grimmige?",a="Langzopf sucht Rache an den Dunkeleisenzwergen, die Dun Modr überrannt und seinen Bruder während des Angriffs auf The Thandol Span getötet haben. Er will ihre Streitkräfte zerschlagen und die Nordgrenze für Eisenschmiede sichern.",al={"langzopf der grimmige ziel","was will langzopf","langzopf beweggründe"}},["0c91256b"]={q="Warum ist Langzopf der Grimmige hier?",a="Langzopf lagert direkt vor Dun Modr im hohen Norden des Sumpflands, um die Ruinen zu überwachen und die Verteidigung zu koordinieren. Nach der brutalen Dunkeleisen-Invasion, die die Stadt und die Brücke zerstörte, bleibt er an der Front, um Gegenangriffe gegen den vordringenden Feind zu leiten.",al={"warum ist langzopf im sumpfland","warum ist langzopf vor dun modr","langzopf standort grund"}}},fp="18,280,14.492.0,16.312.0,26.184.0,35.189.0,26.205.0,53.161.0"}
P.entries["npc:loramus-thalipedes"] = {n="Loramus Thalipedes",s="Loramus Thalipedes ist ein zurückgezogen lebender Nachtelf-Dämonenjäger auf einer abgelegenen Insel vor der Küste von Azshara. Flankiert von treuen Teufelshunden widmet er sein Dasein der Vernichtung von Razelikh the Defiler und leitet erfahrene Champions durch Rituale an, um den Schreckenslord zur Strecke zu bringen.",h="Loramus Thalipedes ist ein zurückgezogen lebender Nachtelf-Dämonenjäger auf einer abgelegenen Insel vor der...",kw={"azshara","dämonenjäger","felbane","teufelshund","hetaeras gelege","loramus","razelikh","thalipedes"},ang={["class:Warlock"]="Hexenmeister werden seine kontrollierten Teufelshunde als Beweis für eine außergewöhnliche dämonische Unterwerfung erkennen, wenngleich Loramus Dämonen ausschließlich bindet, um deren eigene Art abzuschlachten.",["race:NightElf"]="Nachtelfen betrachten Dämonenjäger traditionell mit tiefem Entsetzen und Misstrauen; sie sehen in deren ritueller Selbstverstümmelung und dämonischen Pakten einen unverzeihlichen Weg, der den Verrat der Illidari widerspiegelt."},sec={{t="Der Blinde Jäger der Inseln",b="Auf einer einsamen, sturmgepeitschten Insel südöstlich von Hetaeras Gelege steht Loramus Thalipedes abseits vom Rest seines Volkes. Er ist ein Dämonenjäger – ein Exilant, der sich unter der Anleitung seines Meisters dem qualvollen Ritual der Selbstblendung unterzog, um die Geistersicht zu erlangen. Umgeben von drei hochgewachsenen Teufelshunden namens Raytaf, Shahiar und Zaman beobachtet Loramus die unsichtbaren Ströme dämonischer Verderbnis auf ganz Azeroth, während er zugleich eine wachsame Wacht über die zerschlagenen Ruinen von Azshara hält."},{t="Eine Kontinente überspannende Vendetta",b="Loramus' Fixierung liegt jenseits des Meeres in den Verwüsteten Landen und gilt ganz dem Schreckenslord Razelikh the Defiler. Im Wissen, dass herkömmlicher Stahl einen gerissenen Dämon nicht dauerhaft vernichten kann, leitet Loramus Reisende durch uralte Rituale an, bei denen sie verzauberten Azsharit sammeln und die legendäre Waffe Felbane neu schmieden müssen. Durch diese esoterischen Vorbereitungen versucht er, Razelikhs Schutzwälle zu brechen, den wahren Namen des Dämons zu bannen und die Vendetta ein für alle Mal zu beenden."}},faq={{q="Wer ist Loramus Thalipedes?",a="Loramus Thalipedes ist ein Nachtelf-Dämonenjäger, der auf einer isolierten Insel vor der Küste von Azshara lebt. Er hat sich dem Ziel verschrieben, mächtige Dämonen zu vereiteln, allen voran den Schreckenslord Razelikh the Defiler.",al={"loramus identität","wer ist der dämonenjäger in azshara","wer ist loramus"}},{q="Warum trägt Loramus eine Augenbinde?",a="Wie andere Dämonenjäger entfernte sich Loramus unter Anleitung seines Meisters die eigenen Augen. Im Tausch gegen die gewöhnliche sterbliche Sehkraft verlieh ihm dieses Ritual die Geistersicht, die nötig ist, um dämonische Energien aufzuspüren.",al={"warum hat loramus keine augen","loramus blind","augenbinde dämonenjäger"}},{q="Warum wird er von Teufelshunden bewacht?",a="Loramus hat drei mächtige Teufelshunde unterworfen und gebunden – Raytaf, Shahiar und Zaman –, wodurch er ihre eigenen räuberischen Instinkte in den Dienst seiner Dämonenjagden stellt, anstatt der Brennenden Legion zu dienen.",al={"loramus teufelshunde","warum hat loramus dämonen","raytaf shahiar zaman"}},{q="Was verbindet ihn mit den Verwüsteten Landen?",a="Er leitet den Feldzug zur Vernichtung des Schreckenslords Razelikh the Defiler, der die Höhen der Verwüsteten Lande beherrscht. Loramus liefert das entscheidende Wissen, die Riten und die Waffen, die erforderlich sind, um Razelikhs Schutzschilde zu durchdringen.",al={"loramus verwüstete lande","razelikh quest","warum interessieren ihn die verwüsteten lande"}}},fp="18,274,29.484.0,28.473.1,26.193.0,27.208.0,37.189.0,44.216.0"}
P.entries["npc:lord-arkkoroc"] = {n="Lord Arkkoroc",s="Lord Arkkoroc ist ein uralter, gewaltiger Meeresriese, der in den Ruinen des Tempels von Arkkoran an der zerklüfteten Küste von Azshara weilt. Vom Dämonenjäger Loramus Thalipedes als niedere Gottheit beschrieben, gebietet er über die umliegenden Gewässer und befehligt niedere Meeresriesen, die als seine Söhne dienen.",h="Lord Arkkoroc ist ein uralter, gewaltiger Meeresriese, der in den Ruinen des Tempels von Arkkoran an der...",kw={"arkkoran","arkkoroc","azshara","hetaera","loramus","lord arkkoroc","meeresriese"},ang={["race:NightElf"]="Die Ruinen des Tempels von Arkkoran stehen auf einstigen Ländereien der Hochgeborenen, wo nun eine uralte Meeresentität über die gefallene Erhabenheit des alten Kalimdor herrscht."},sec={{t="Herr der Versunkenen Küste",b="Inmitten der salzverkrusteten Ruinen des Tempels von Arkkoran ruhend, ist Lord Arkkoroc weit mehr als ein gewöhnlicher Meeresriese. Für Einsiedler wie Loramus Thalipedes gilt dieses kolossale Wesen als niedere Gottheit, deren göttlicher Wille die umliegenden Gewässer formt. Seine Söhne patrouillieren durch die Klippen und Untiefen rund um das Heiligtum und setzen seine stille Herrschaft über Azsharas stürmische Küsten durch."},{t="Vergeltung gegen die Tiefe",b="Trotz seiner immensen göttlichen Macht erleidet Arkkoroc persönliche Verluste unter den Gezeiten. Eine furchterregende, vielköpfige Hydra namens Hetaera hat viele seiner Söhne entlang der Klippen gejagt und niedergemetzelt. Da er die Bestie nicht selbst jagen kann oder will, bietet Arkkoroc jedem umherziehenden Abenteurer wertvolles Wissen und okkulte Hilfe an, der stark genug ist, ihm die Köpfe des Mörders seiner Nachkommen zu bringen."}},faq={{q="Wer ist Lord Arkkoroc?",a="Lord Arkkoroc ist ein gewaltiger Meeresriese, der im Tempel von Arkkoran in Azshara residiert. Er wird als niedere Gottheit der Meere verehrt und herrscht über eine Brut von Meeresriesen, die er als seine Söhne betrachtet.",al={"wer ist arkkoroc","arkkoroc geschichte","tempel meeresriese"}},{q="Wo finde ich Lord Arkkoroc?",a="Ihr findet ihn inmitten der Ruinen des Tempels von Arkkoran an der östlichen Küste und den felsigen Riffen von Azshara.",al={"arkkoroc aufenthaltsort","wo ist arkkoroc","arkkoroc finden"}},{q="Warum schickt Loramus Thalipedes Abenteurer zu Arkkoroc?",a="Loramus Thalipedes schickt Reisende zu Arkkoroc, um arkane Erkenntnisse über einen mächtigen Dämon einzuholen. Als niedere Meeresgottheit verfügt Arkkoroc über uraltes Wissen, verlangt jedoch, dass Abenteurer die Hydra Hetaera erschlagen, bevor er seine Geheimnisse preisgibt.",al={"loramus arkkoroc quest","name der bestie"}},{q="Warum ist Arkkoroc zornig auf die Hydra Hetaera?",a="Die wilde Meeresbestie Hetaera hat mehrere von Arkkorocs Söhnen abgeschlachtet, die entlang der Küste patrouillierten. Um Rache für seine getöteten Nachkommen zu nehmen, fordert der Meeresriese ihre Köpfe.",al={"warum hetaera toeten","arkkoroc hydra groll"}}},fp="13,294,24.378.0,26.398.1,21.195.0,31.129.0,57.247.0,45.170.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="Lord Baurles K. Wischock",s="Lord Baurles K. Wischock ist ein Adliger, der sich in der Petitioner's Chamber von Burg Sturmwind aufhält. Bei Barkeepern ist er für seine unbezahlten Rechnungen und seine Vorliebe für starke Getränke berüchtigt, doch in den Schatten der Stadt stieß er auf weitaus finsterere Machenschaften als bloße Trunkenheit.",h="Lord Baurles K.",kw={"baurles","house of nobles","petitioner's chamber","slaughtered lamb","burg sturmwind","wishock","zardeth"},ang={["class:Warlock"]="Wishocks neugierige Nachforschungen rund um das Gasthaus Zum Geschlachteten Lamm stellen eine unmittelbare Bedrohung für Sturmwinds Schattenzirkel dar, weshalb sein stilles Ableben für die praktizierenden Hexenmeister oberste Priorität hat.",["race:Human"]="Seine Anwesenheit in der Petitioner's Chamber spiegelt den dekadenten, eigennützigen Ruf des House of Nobles während der frühen Regentschaft des Knabenkönigs Anduin wider."},sec={{t="Die gefährliche Neugier eines Adligen",b="Inmitten der Bittsteller und Würdenträger in Burg Sturmwind hält Lord Baurles K. Wischock Hof, der ein Mitglied des einflussreichen House of Nobles ist. Trotz seines hohen Standes pflegte Wishock die Gewohnheit, die zwielichtigen Schänken des Magierviertels aufzusuchen – allen voran das Gasthaus Zum Geschlachteten Lamm –, wobei er beträchtliche unbezahlte Rechnungen hinterließ. Während er dort trank, bekam er jedoch Wind von dem Hexenmeisterzirkel, der in den Kellern unter den Dielen dunkle Künste praktizierte. Entschlossen, die Taverne schließen zu lassen, begann Wishock, bei anderen Adligen eine formelle Untersuchung zu erbitten – unwissend, dass das Aufdecken dämonischer Kulte in Sturmwind selten ungestraft bleibt."},{t="Ein vergifteter Becher",b="Wishocks Bemühungen rückten ihn direkt ins Visier der verborgenen Hexenmeister der Stadt. Anstatt eine königliche Überprüfung oder eine Untersuchung ihres unterirdischen Heiligtums zu riskieren, fädelte der Hexenmeister Zardeth der Schwarzen Klaue die heimliche Beseitigung des Adligen ein. Der Zirkel nutzte Wishocks berüchtigten Durst nach edlen Tropfen aus, braute ein tödliches Gebräu, das als feines Bier getarnt war, und arrangierte es so, dass ein angeheuerter Abenteurer das verhängnisvolle Getränk direkt vor den Augen der Wachen der Feste überbrachte."}},faq={{q="Wer ist Lord Baurles K. Wischock?",a="Lord Baurles K. Wischock ist ein dem House of Nobles angehörender Aristokrat. Er verbringt seine Tage in der Petitioner's Chamber in Burg Sturmwind, ist im Magierviertel jedoch dafür berüchtigt, hohe, unbezahlte Zechen anzuhäufen.",al={"baurles wishock","wer ist wishock","adliger bittsteller"}},{q="Wo ist Lord Wishock zu finden?",a="Er steht in der Petitioner's Chamber auf der Ostseite von Burg Sturmwind, umgeben von anderen Höflingen, Diplomaten und Bittstellern, die auf eine königliche Audienz warten.",al={"wishock aufenthaltsort","wo ist wishock","lord wishock finden"}},{q="Warum wollen die Hexenmeister unter dem Gasthaus Zum Geschlachteten Lamm seinen Tod?",a="Während seiner nächtlichen Zechtouren im Gasthaus Zum Geschlachteten Lamm erfuhr Wishock, dass ein Zirkel von Hexenmeistern unter der Taverne operierte. Er begann, beim House of Nobles für eine formelle Untersuchung und die Schließung des Etablissements zu werben, was die geheimen Aktivitäten der Hexenmeister auffliegen zu lassen drohte.",al={"warum wishock töten","zardeth wishock","warum wishock vergiften"}},{q="Wie wird er ermordet?",a="Zardeth der Schwarzen Klaue braut ein tödliches Gift und tarnt es als erlesenes Getränk. Da Wishocks Schwäche für feinen Alkohol und Freibier bekannt ist, überbringt ihm ein Agent das vergiftete Fässchen direkt in Burg Sturmwind.",al={"wie stirbt wishock","wishock gift","ein nobles bräu"}}},fx={["255656dc"]={q="Auf wessen Seite steht Lord Baurles K. Wischock?",a="Lord Wischock dient dem Königreich Sturmwind als sitzendes Mitglied des Hauses der Adligen. Er operiert strikt innerhalb der königlichen Aristokratie und nutzt seinen politischen Einfluss, um die bürgerliche und adlige Autorität gegen subversive Elemente zu verteidigen, die sich innerhalb der Stadtgrenzen verbergen.",al={"lord wischock seite","lord wischock fraktion","wem dient wischock"}},["59c1fa27"]={q="Was will Lord Baurles K. Wischock?",a="Lord Wischock ist entschlossen, den dunklen Zirkel, der im Keller unter dem The Slaughtered Lamb operiert, aufzudecken und zu zerschlagen. Nachdem er ihre abscheulichen Riten entdeckt hat, setzt er sich bei seinen Kollegen im Haus der Adligen aktiv dafür ein, eine umfassende offizielle Untersuchung der Taverne einzuleiten und die Hexenmeister aus Sturmwind zu vertreiben.",al={"wischock ziel","was will wischock","lord wischock plan"}},["3d37be28"]={q="Warum befindet sich Lord Baurles K. Wischock in Burg Sturmwind?",a="Ihr findet Lord Wischock in der Petitioner's Chamber innerhalb von Burg Sturmwind, wo er seinen adligen Pflichten nachgeht. Als Mitglied des Hauses der Adligen hält er sich häufig in der Burg auf, um sich mit anderen Lords zu beraten und Petitionen an den königlichen Hof zu richten.",al={"warum ist wischock in burg sturmwind","warum ist lord wischock hier","wischock petitioners chamber"}},["83d2fff3"]={q="Mit wem ist Lord Baurles K. Wischock verbunden?",a="Lord Wischock gehört dem Haus der Adligen an, der einflussreichen Regierungsversammlung von Sturmwinds Aristokratie. Außerhalb des Hofes war er ein regelmäßiger Gast im The Slaughtered Lamb im Magierviertel – wo er eine enorme unbezahlte Rechnung anhäufte, bevor er den Hexenmeister-Zirkel entdeckte, der in dessen verborgenen Krypten dunkle Künste praktizierte.",al={"wischock verbindungen","lord wischock beziehungen","wischock haus der adligen"}}},fp="23,241,32.635.0,14.479.1,31.233.0,32.179.0,63.276.1,23.222.1"}
P.entries["npc:lord-cobrahn"] = {n="Lord Kobrahn",s="Lord Kobrahn, ehemals der Nachtelfendruide Jarlaxla, ist einer der verderbten Druiden des Giftzahns, die tief in den Höhlen des Wehklagens lauern. Einst im Zirkel des Cenarius für seine Meisterschaft des Gestaltwandelns gerühmt, erlag er dem Alptraum, der die Quellen der Höhle infizierte. Nach seiner neuen, tödlichen Gestalt umbenannt, befehligt Kobrahn nun Gelege von Deviatschlangen und verteidigt das gewundene Labyrinth.",h="Lord Kobrahn, ehemals der Nachtelfendruide Jarlaxla, ist einer der verderbten Druiden des Giftzahns, die tief...",kw={"kobrahn","deviatpython","druiden des giftzahns","giftzahnfürst","edelstein von kobrahn","jarlaxla","lord kobrahn","die höhlen des wehklagens"},ang={["class:Druid"]="Kobrahn dient als düstere Mahnung daran, wie das druidische Gestaltwandeln pervertiert werden kann, wenn es mit dem Alptraum statt mit dem natürlichen Gleichgewicht verbunden ist.",["faction:Horde"]="Abenteurer der Horde suchen Kobrahn auf, um die üble Verderbnis zu beenden, die ins Brachland sickert, und das fragile Ökosystem der Ebenen von Kalimdor zu schützen.",["race:NightElf"]="Für Nachtelfen ist Kobrahns Fall eine bittere Tragödie: Ein fähiger Bruder des Zirkels des Cenarius gab sein Erbe auf, um Monster in den unterirdischen Tiefen anzuführen."},sec={{t="Ein verderbter Meister der Gestalten",b="Bevor er den Namen Lord Kobrahn annahm, war Jarlaxla ein angesehenes Mitglied des Zirkels des Cenarius, das unter seinen Druidenbrüdern für sein außergewöhnliches Geschick beim Kanalisieren von Tiergestalten gefeiert wurde. Als Naralex in die Höhlen des Wehklagens unter dem Brachland vordrang, in der Hoffnung, deren unterirdische Quellen anzuzapfen und den kargen Ödlanden üppiges Leben zurückzubringen, begleitete ihn Jarlaxla. Doch als Naralex' Zwiesprache mit dem Smaragdgrünen Traum zu einem gewundenen Alptraum verkam, zerbrach Jarlaxlas Verstand an der Seite seiner Brüder."},{t="Die Umarmung der Schlange",b="Statt die traditionellen Totemtiere der Cenarius-Tradition zu kanalisieren, verzerrte der Alptraum Jarlaxlas Fähigkeiten des Gestaltwandelns zu etwas Räuberischem und Reptilienhaftem. Unter dem Namen Lord Kobrahn entwickelte er eine tödliche Schlangengestalt, die er im Kampf entfesselt. Flankiert von giftigen Deviatpythons und mit einer bösartigen Klauenhand an der Rechten wacht er über seinen Abschnitt der Grotten und merzt jeden gewaltsam aus, der den Griff des Alptraums über die Höhlen brechen will."}},faq={{q="Wer war Lord Kobrahn, bevor er böse wurde?",a="Lord Kobrahn hieß ursprünglich Jarlaxla. Er war ein prominenter Nachtelfendruide im Zirkel des Cenarius, der für sein seltenes Talent und seine tiefe Verbundenheit mit tierischen Wandelgestalten weithin geschätzt wurde.",al={"kobrahn wahrer name","wer ist kobrahn","jarlaxla"}},{q="Warum heißt er Lord Kobrahn?",a="Als Jarlaxla dem Alptraum in den Höhlen des Wehklagens zum Opfer fiel, vervollkommnete er eine tödliche Schlangenform des Gestaltwandelns. Er legte seinen früheren Namen ab und nahm den Titel Lord Kobrahn an, um seine gefährliche neue Macht und seine Beherrschung der Schlangen widerzuspiegeln.",al={"warum kobrahn","lord kobrahn bedeutung des namens"}},{q="Wo ist Lord Kobrahn zu finden?",a="Lord Kobrahn haust tief in den Höhlen des Wehklagens, einem verschlungenen unterirdischen Netzwerk im zentralen Brachland, umgeben von Deviatpythons und anderen alptraumverderbten Bestien.",al={"kobrahn aufenthaltsort","wo ist lord kobrahn","kobrahn raum"}},{q="Warum müssen Abenteurer ihn besiegen?",a="Er ist einer der primären Giftzahnfürsten, die die Druiden des Giftzahns anführen. Er trägt den Edelstein von Kobrahn bei sich, den die Druidin Nara Wildmähne aus Donnerfels benötigt, um den Einfluss der Anführer der Giftzähne über das Brachland zu brechen.",al={"warum kobrahn töten","anführer der giftzähne kobrahn"}},{q="Welche einzigartigen körperlichen Merkmale besitzt er?",a="Im Gegensatz zu gewöhnlichen Nachtelfen ist Kobrahn von merklich größerer Statur, trägt eine scharfe Klaue an seiner rechten Hand und kann sich im Kampf vollständig in eine übergroße, giftige Schlange verwandeln.",al={"wie sieht kobrahn aus","kobrahn erscheinung"}},{q="Welche Verbindung hat er zu den anderen Druiden des Giftzahns?",a="Kobrahn ist neben Lady Anakondra und ihrer Verwandtschaft einer der vier wichtigsten Giftzahnfürsten. Sie sind ehemalige Druiden des Zirkels des Cenarius, die mit Naralex die Höhlen betraten und gemeinsam der verderbenden Macht des Alptraums verfielen.",al={"anführer der druiden des giftzahns","kobrahn und anacondra"}}},fx={["197957cb"]={q="Wer ist Lord Kobrahn?",a="Lord Kobrahn, früher bekannt als Jarlaxla, ist einer der korrumpierten Anführer der Druiden des Giftzahns, die tief in den Höhlen des Wehklagens lauern. Einst ein angesehener Nachtelf-Druide, der im Zirkel des Cenarius für seine Meisterschaft der Gestaltwandlung gefeiert wurde, fiel er dem dunklen Albtraum zum Opfer, der die Höhlen verschlang. Zu einem monströsen, schlangenanbetenden Eremiten verzerrt, schwingt er nun giftige Magie und nimmt die Gestalt einer massiven schlangenartigen Bestie an.",al={"wer ist kobrahn","lord kobrahn hintergrund","jarlaxla"}},["3feb6d50"]={q="Auf wessen Seite steht Lord Kobrahn?",a="Lord Kobrahn dient den Druiden des Giftzahns und dem sich ausbreitenden Albtraum innerhalb der Höhlen des Wehklagens. Er hat alle Loyalität gegenüber dem Zirkel des Cenarius und dem Volk der Nachtelfen aufgegeben und steht an der Seite von Naralex' gefallenen Schülern gegen jeden, der es wagt, einzudringen, um die Verderbnis zu reinigen.",al={"kobrahn fraktion","wem dient kobrahn","lord kobrahn loyalitäten"}},["55d9f433"]={q="Warum ist Lord Kobrahn hier?",a="Er betrat die Höhlen des Wehklagens ursprünglich gemeinsam mit Erzdruide Naralex mit der Absicht, die unterirdischen Gewässer anzuzapfen und das Brachland in ein üppiges Paradies zu verwandeln. Als sich die Verbindung von Naralex zum Smaragdgrüner Traum in einen Albtraum verwandelte, vergifteten die Energien die Geister seiner Schüler. Kobrahn erlag dem völlig und blieb in den Höhlen, um den schlummernden Erzdruiden zu bewachen und die giftigen Ausgeburten des Albtraums zu fördern.",al={"warum ist kobrahn in den höhlen des wehklagens","warum kam kobrahn hierher"}}},fp="12,399,27.496.0,21.465.0,43.193.0,30.242.0,32.184.0,38.209.0,44.186.0,55.218.0"}
P.entries["npc:lord-ello-ebonlocke"] = {n="Lord Ello Schwarzhaupt",s="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und das Oberhaupt seines Stadtrates, stationiert im Rathaus von Dunkelhain. Umgeben von Dunkelheit und schleichendem Grauen kämpft er täglich darum, die Ordnung aufrechtzuerhalten und seine belagerten Bürger zu beschützen, obwohl er kaum Hilfe aus Sturmwind erhält.",h="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und das Oberhaupt seines Stadtrates, stationiert...",kw={"calvinius","althea","rat","dunkelhain","dämmerwald","ebonlocke","ello","seenhain","bürgermeister"},ang={["faction:Alliance"]="Lord Schwarzhaupt steht für die vergessenen Grenzlande der Allianz, in denen isolierte Bürgermeister ihr Volk ohne kaiserliche Unterstützung durch albtraumhafte Zustände führen müssen.",["race:Human"]="Für Menschen, die aus Sturmwind anreisen, ist das Gespräch mit Lord Schwarzhaupt eine ernüchternde Erinnerung daran, wie tief die südlichen Provinzen in Ruin und Verlassenheit gestürzt sind."},sec={{t="Ein bedrängter Bürgermeister",b="In der Düsternis des Rathauses von Dunkelhain trägt Lord Ello Schwarzhaupt die schwere Bürde, eine Siedlung am Rande des Ruins zu regieren. Einst Teil der wohlhabenden ländlichen Zuflucht namens Grand Hamlet, ist Dunkelhain nun in ewigen Schatten gehüllt und wird von unersättlichen Ghulen, untoten Monstrositäten und wilden Bestien belagert. Ello führt den Vorsitz über den Rat von Dunkelhain und müht sich gegen aussichtslose Chancen ab, die Reste der Zivilisation aufrechtzuerhalten, während Sturmwind vor ihrer Notlage die Augen verschließt."},{t="Eine geteilte Grenze",b="Da die Garnison von Sturmwind sich weigert, Soldaten für die Grenzlande abzustellen, ist Dunkelhain fast gänzlich auf einheimische Freiwilligenmilizen wie die Nachtwache angewiesen, die von seiner Verwandten Althea Schwarzhaupt befehligt wird. Wenn benachbarte Anführer wie Magistrat Solomon aus Seenhain um Verstärkung im Kampf gegen die Schwarzfelsorcs flehen, muss Lord Schwarzhaupt quälende Entscheidungen treffen. Wie er Boten aus dem Rotkammgebirge feierlich erklärt, kann Dunkelhain keine einzige Klinge entbehren: Würden die Wachen über den Waldrand hinaus entsandt, fielen die eigenen Heime augenblicklich dem umgebenden Unheil anheim."},{t="Blind für die Pläne des Einsiedlers",b="Neben dem Patrouillieren der Straßen verlässt sich Lord Schwarzhaupt häufig auf umherziehende Abenteurer, um sich um merkwürdige Vorkommnisse in den Wäldern zu kümmern. In seinem aufrichtigen Wunsch, allen Bewohnern des Dämmerwalds beizustehen, koordiniert er die Kommunikation mit einsamen Gestalten wie dem Einsiedler Calvinius. Bedauerlicherweise sorgt Schwarzhaupts Mangel an echtem Verständnis für die kryptischen Schriften des Einsiedlers dafür, dass er für den grauenhaften, zusammengenähten Albtraum blind bleibt, der sich knapp hinter den Stadtgrenzen zusammenbraut – bis es beinahe zu spät ist."}},faq={{q="Wer ist Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und das Oberhaupt des Rates von Dunkelhain. Von seinem Sitz im Rathaus aus wacht er über die Verteidigung, die zivilen Angelegenheiten und das Überleben der verbliebenen menschlichen Bevölkerung des Dämmerwalds.",al={"wer ist ello","bürgermeister von dunkelhain","ello ebonlocke lore"}},{q="In welcher Beziehung steht er zu Kommandantin Althea Schwarzhaupt?",a="Kommandantin Althea Schwarzhaupt, die unerschütterliche Anführerin der Nachtwache, ist eine nahe Verwandte von Lord Ello. Während er die zivilen und diplomatischen Belange von Dunkelhain lenkt, befehligt sie die Miliz, die die Siedlung aktiv beschützt.",al={"althea schwarzhaupt verwandtschaft","ist althea ellos tochter"}},{q="Warum weigert sich Lord Schwarzhaupt, Truppen nach Seenhain zu entsenden?",a="Als Magistrat Solomon um Hilfe gegen die Schwarzfelsorcs im Rotkammgebirge bittet, ist Lord Schwarzhaupt gezwungen abzulehnen. Dunkelhain wird von Untoten und Ungeheuern so stark bedrängt, dass das Abziehen von Wachen die Stadt völlig überrennen ließe, noch bevor die Miliz überhaupt die Waldgrenze erreicht hätte.",al={"warum keine hilfe für rotkamm","botschaft nach dunkelhain","magistrat solomon ello ebonlocke"}},{q="Wo ist Lord Ello Schwarzhaupt zu finden?",a="Er befindet sich im Rathaus von Dunkelhain, das im Zentrum von Dunkelhain im östlichen Dämmerwald steht.",al={"ello ebonlocke standort","wo ist bürgermeister ebonlocke"}},{q="Warum sendet Sturmwind keine Truppen, um Lord Schwarzhaupt zu helfen?",a="Sturmwind ist nach dem Verschwinden von König Varian Wrynn in interne politische Konflikte verstrickt. Angesichts der knappen Ressourcen des Königreichs hat das Adelsgeschlecht die südlichen Regionen weitgehend im Stich gelassen, was lokale Anführer wie Lord Schwarzhaupt dazu zwingt, ihre Verteidigung selbst zu organisieren.",al={"warum hilft sturmwind dämmerwald nicht","vernachlässigung durch sturmwind"}},{q="Welche Verbindung hat Lord Schwarzhaupt zu Calvinius?",a="Lord Schwarzhaupt hilft bei der Kommunikation mit dem Einsiedler Calvinius und veranlasst die Übersetzung sonderbarer Notizen.",al={"ello calvinius notiz","übersetzung von calvinius' notiz"}}},fx={["0007fc63"]={q="Auf wessen Seite steht Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist der Große Allianz loyal ergeben und dient als Bürgermeister von Dunkelhain, wo er den Stadtrat leitet. Obwohl er dem Königreich Sturmwind verpflichtet ist, muss er das Überleben seiner eigenen verängstigten Bürger über breitere regionale Hilferufe stellen.",al={"lord schwarzhaupt fraktion","wem dient ello schwarzhaupt","ist schwarzhaupt allianz"}},["48b49947"]={q="Was will Lord Ello Schwarzhaupt?",a="Bürgermeister Schwarzhaupt will vor allem verhindern, dass die bedrängte Stadt Dunkelhain der heraufziehenden Finsternis zum Opfer fällt. Von der Krone im Stich gelassen, liegt sein einziger Fokus darauf, sein Volk zu beschützen und die örtliche Nachtwache gegen die umliegenden Schrecken einsatzbereit zu halten.",al={"was will lord ello","schwarzhaupt ziel","ello schwarzhaupt zweck"}},["26db90ba"]={q="Warum ist Lord Ello Schwarzhaupt in Dunkelhain?",a="Lord Schwarzhaupt leitet Dunkelhain vom Rathaus aus, da er das Oberhaupt des Rats von Dunkelhain ist. Als ziviler Anführer des letzten überlebenden Bollwerks der Zivilisation im Dämmerwald überwacht er die lokale Verteidigung und Verwaltung aus dem Herzen der Siedlung heraus.",al={"warum ist lord schwarzhaupt im dämmerwald","warum ist schwarzhaupt in dunkelhain","ello schwarzhaupt standort grund"}}},fp="19,289,19.500.0,18.576.0,29.465.1,27.208.0,48.218.0,59.294.0,39.106.0,57.276.0,54.125.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {n="Lord Grayson Schattenbruch",s="Lord Grayson Schattenbruch ist ein erfahrener Paladinkommandant der Ritter der Silbernen Hand, der in Sturmwinds Kathedrale des Lichts stationiert ist. Erkennbar an seiner hochgewachsenen Gestalt und seinem fehlenden rechten Auge bildet er angehende Streiter des Lichts aus und leitet die heiligen, beschwerlichen Prüfungen, die ältere Paladine ablegen müssen, um ihre heiligen Streitrosse zu erlangen.",h="Lord Grayson Schattenbruch ist ein erfahrener Paladinkommandant der Ritter der Silbernen Hand, der in...",kw={"kathedrale des lichts","streitross","grayson","grimand elmore","jubeka","paladin","scholomance","shadowbreaker","silberne hand"},ang={["class:Paladin"]="Grayson fungiert als einer Eurer höchsten geistlichen Mentoren in der Allianz, weist Euch den Weg gegen die Geißel in Lordaeron und leitet die anspruchsvollen Prüfungen, die zur Beschwörung eines echten Streitrosses erforderlich sind.",["faction:Alliance"]="Als stoischer Veteran der Silbernen Hand trägt Lord Grayson dazu bei, Sturmwinds Verteidigung zu stärken, und forciert die Unterstützung für Expeditionen in die umkämpften nördlichen Königreiche."},sec={{t="Meister der Silbernen Hand",b="Lord Grayson Schattenbruch zählt zu den vordersten Verteidigern der Allianz und verankert die Präsenz des Ordens in Sturmwind. Als kampferprobter Krieger, der sein rechtes Auge in der Schlacht verlor, unterweist Grayson Rekruten nicht bloß in kriegerischem Geschick; er prüft ihre spirituelle Überzeugung. Sobald vielversprechende Ritter ihre Reife beweisen, schickt Grayson sie nach Norden an die umkämpften Frontlinien der Westlichen Pestländer, um Commander Ashlam Valorfist im Zugwindlager beizustehen."},{t="Die Prüfungen des heiligen Streitrosses",b="Von Paladinen, die ihr heiliges Kriegspferd erlangen wollen, verlangt Shadowbreaker tiefgreifende Opfer und unzweifelhafte Tugend. Seine Prüfungen erfordern demütige Akte der Barmherzigkeit – wie etwa die Unterstützung von Eisenschmiedes Bedürftigen über Hohepriester Rohan – sowie gefahrvolle Reisen, um Schreckenstal zu exorzieren und uralte Geister in Düsterbruch zu läutern. Die Prüfung gipfelt in den finsteren Tiefen von Scholomance, wo sich ein Initiant dem Todesritter Darkreaver stellen und ein unheiliges Ross durch das Licht aus seiner Knechtschaft erlösen muss."}},faq={{q="Wo finde ich Lord Grayson Schattenbruch?",a="Lord Grayson Schattenbruch hält sich in der Kathedrale des Lichts auf, die sich am Kathedralenplatz von Sturmwind befindet. Er steht in den Haupthallen und wacht über die Paladine der Silbernen Hand.",al={"wo ist grayson shadowbreaker","shadowbreaker aufenthaltsort","wo ist lord grayson"}},{q="Welche Rolle spielt Lord Grayson für Paladine?",a="Er dient als hochrangiger Paladinlehrer der Allianz. Neben der Entsendung junger Ritter an die Front gegen die Geißel in Lordaeron leitet er die heilige rituelle Questreihe an, die erforderlich ist, um ein heiliges Pferdegeschirr zu schmieden und ein Streitross der Paladine zu beanspruchen.",al={"was macht grayson","aufgabe von grayson shadowbreaker","warum lord grayson aufsuchen"}},{q="Wie verlor Lord Grayson sein rechtes Auge?",a="Grayson verlor sein rechtes Auge im Kampf auf dem Schlachtfeld während seines langen Dienstes für die Allianz und den Orden der Silbernen Hand; die Narbe zeugt von jahrzehntelangem Krieg.",al={"wie verlor grayson sein auge","warum fehlt grayson ein auge","grayson augenklappe"}},{q="Was verbindet ihn mit den Verlassenen?",a="Seine Schwester Jubeka kam während der Verheerung von Lordaeron ums Leben und wurde als eine der Verlassenen wiedererweckt. Als sie ihn später in der Hoffnung auf Versöhnung aufsuchte, wies Grayson sie als unheilige Monstrosität ab und beharrte unerbittlich darauf, dass seine wahre Schwester mit Lordaeron gestorben sei.",al={"grayson schwester","jubeka shadowbreaker","hat grayson untote verwandte"}},{q="Warum schickt Grayson Paladine zu Grimand Elmore?",a="Grimand Elmore schmiedete vor Jahren das Pferdegeschirr für Graysons eigenes Streitross. Da ein heiliges Streitross makellose Handwerkskunst erfordert, die körperliche Widerstandskraft mit spiritueller Harmonie vereint, schickt Grayson alle würdigen Initianten zu Grimand, um ihr Arkanitpferdegeschirr anfertigen zu lassen.",al={"grayson und grimand elmore","wer stellt das paladingeschirr her","arkanitpferdegeschirr quest"}}},fx={["18aad189"]={q="Wer ist Lord Grayson Schattenbruch?",a="Lord Grayson Schattenbruch ist einer der bedeutendsten Paladine von Sturmwind und der Allianz. Als hochgewachsener, kampferprobter Veteran der Ritter der Silbernen Hand, der im Kampf sein rechtes Auge verlor, dient er als hochrangiger Meister des heiligen Ordens und bildet vielversprechende Ritter in den Wegen von das Licht aus.",al={"wer ist grayson schattenbruch","wer ist lord grayson","über grayson schattenbruch"}},["2db8c97e"]={q="Auf wessen Seite steht Lord Grayson Schattenbruch?",a="Lord Grayson steht fest an der Seite der Großen Allianz, des Königreichs Sturmwind und des Ordens der Silbernen Hand. Er widmet sich voll und ganz das Heilige Licht und der Verteidigung der Lebenden gegen die Geißel und andere dunkle Bedrohungen.",al={"grayson schattenbruch fraktion","wem dient grayson","ist grayson allianz"}},["88e74201"]={q="Was will Lord Grayson Schattenbruch?",a="Lord Grayson versucht, die nächste Generation heiliger Krieger zu schmieden, um die Finsternis zurückzudrängen, die Azeroth verschlingt. Er testet Paladine durch beschwerliche geistige und kampfbezogene Prüfungen, schickt sie aus, um die Geißel in den Pestländern zu bekämpfen, und beweist ihre Würdigkeit, ein gesegnetes Streitross zu erhalten.",al={"grayson schattenbruch ziele","was will grayson","grayson motiv"}},a5a2c568={q="Warum ist Lord Grayson Schattenbruch in der Kathedrale des Lichts?",a="Er ist innerhalb der Kathedrale des Lichts von Sturmwind stationiert, um die Entwicklung der Paladine der Stadt zu beaufsichtigen. Von diesem zentralen Bollwerk des Glaubens aus koordiniert er Missionen gegen die Geißel und leitet hochrangige Champions durch die anspruchsvollen Prüfungen, die erforderlich sind, um ihre heiligen Schlachtrösser zu beschwören.",al={"warum ist grayson in sturmwind","warum ist grayson hier","grayson kathedrale des lichts"}},c41cec02={q="Mit wem ist Lord Grayson Schattenbruch verbunden?",a="Schattenbruch arbeitet eng mit Hohepriester Rohan von Eisenschmiede, dem Schmied Grimand Elmore und Befehlshabern zusammen, die im Norden gegen die Geißel kämpfen, wie zum Beispiel Ashlam Valorfist.",al={"verbündete von grayson schattenbruch","wen kennt grayson","knappen von grayson"}}},fp="26,338,25.479.0,30.494.1,44.193.0,41.263.0,40.179.0,39.260.0,49.261.0"}
P.entries["npc:lord-jorach-ravenholdt"] = {n="Lord Jorach Rabenholdt",s="Lord Jorach Rabenholdt ist das Oberhaupt von Rabenholdt, einer Elitegilde von Schurken und Attentätern, die von einem abgelegenen Anwesen im Alteracgebirge aus operiert. Er leitet die geheimen Operationen des Bundes, bildet vielversprechende Agenten aus und führt einen erbitterten Krieg gegen die regionalen Banditen des Syndikats.",h="Lord Jorach Rabenholdt ist das Oberhaupt von Rabenholdt, einer Elitegilde von Schurken und Attentätern, die...",kw={"alterac","assassin's league","azurblauer schlüssel","jorach","rabenholdt","schurke","syndikat","xylem"},ang={["class:Rogue"]="Lord Rabenholdt ist der bedeutendste Schutzpatron für Meisterschurken in ganz Azeroth und bietet Eliteausbildung, Gifte und prestigeträchtige Aufträge für jene, die sein Vertrauen gewinnen."},sec={{t="Meister der Assassin's League",b="Lord Jorach Rabenholdt herrscht über die Assassin's League von seinem verborgenen Anwesen aus, das in den zerklüfteten Felsen zwischen Alterac und Hillsbrad liegt. Als Adliger von geheimnisvoller Abstammung öffnet er seine Hallen für Gesetzlose, Beutelschneider und Attentäter ungeachtet ihrer Zugehörigkeit, sofern sie außergewöhnliches Geschick an den Tag legen und seine Autorität respektieren. Unter seinem Befehl fungiert der Bund sowohl als Bruderschaft für Meisterdiebe als auch als unabhängiges Syndikat für Auftragsmorde und Spionage. Rabenholdt hegt einen tiefen Hass auf das Syndikat – die Schar in Ungnade gefallener Alterac-Adliger, die zu Gesetzlosen wurden – und beauftragt seine Untergebenen sowie reisende Freiberufler regelmäßig damit, deren Lager zu sabotieren und ihre Vorräte zu plündern."},{t="Geheimnisse in den Schatten",b="Während er scheinbar mit lokalen Scharmützeln beschäftigt ist, leitet Lord Rabenholdt weitreichende Operationen in ganz Azeroth. Schurken, die ihre Loyalität unter Beweis stellen, werden für knifflige, kontinentübergreifende Aufgaben rekrutiert, um wohlbehütete Artefakte zu beschaffen. Darunter war die Bergung einer geheimnisvollen Versiegelten azurblauen Tasche, die ihm gestohlen und zu Furbolgs nach Azshara gebracht worden war; dies erforderte die arkane Entschlüsselung durch Erzmagier Xylem und einen Azurblauen Schlüssel, der dem Versunkenen Tempel entrissen werden musste. Rabenholdt koordiniert zudem die Entwicklung tödlicher neuer Substanzen und entsendet seine Späher, um tödliches Gift von uralten Schrecken im gesamten Reich zu sammeln."}},faq={{q="Wer ist Lord Jorach Rabenholdt?",a="Er ist der aristokratische Anführer der Assassin's League, einer geheimen Vereinigung von Schurken mit Hauptsitz im Rabenholdtanwesen in den Bergen über dem Vorgebirge des Hügellands. Er bildet Meister der Tarnung aus und koordiniert diskrete Attentate sowie das Beschaffen von Informationen.",al={"wer ist jorach","rabenholdt anführer","jorach lore"}},{q="Warum hasst Rabenholdt das Syndikat?",a="Rabenholdts Anwesen liegt direkt in einem vom Syndikat beanspruchten Gebiet – einem Netzwerk ehemaliger Alterac-Adliger, die zu skrupellosen Gesetzlosen wurden. Er betrachtet ihr primitives Banditentum als Seuche im Hochland und setzt die Attentäter seiner Gilde aktiv ein, um deren Hochburgen zu säubern.",al={"warum syndikat feind","rabenholdt gegen syndikat","syndikat rivalität"}},{q="Gehört Lord Rabenholdt zur Allianz oder zur Horde?",a="Rabenholdt agiert streng als unabhängige Organisation. Lord Jorach empfängt sowohl Schurken der Allianz als auch der Horde auf seinem Anwesen; ihm geht es einzig um professionelles Können, Disziplin im Verborgenen und absolute Diskretion, nicht um Völkerpolitik.",al={"ist rabenholdt allianz","ist jorach horde","rabenholdt fraktion"}},{q="Was befindet sich in der Versiegelten azurblauen Tasche, nach der Jorach sucht?",a="Der Inhalt bleibt ein streng gehütetes Geheimnis. Als ihm der Azurblaue Schlüssel überreicht wurde, um den verzauberten Beutel endlich zu öffnen, wurde Lord Jorach von einem unheimlichen goldenen Licht umhüllt; er starrte voller Erstaunen hinein, bevor er ihn rasch verstaute.",al={"versiegelte azurblaue tasche inhalt","azurblaue tasche geheimnis","was hat jorach bekommen"}}},fp="22,302,31.670.0,22.600.1,30.264.0,39.273.0,57.249.0,49.237.1"}
P.entries["npc:lord-maxwell-tyrosus"] = {n="Lord Maxwell Tyrosus",s="Lord Maxwell Tyrosus ist der Oberste Kommandant der Argentumdämmerung und in ihrer vorgeschobenen Bastion, der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern, stationiert. Als erfahrener Paladin der Silbernen Hand aus dem Dritten Krieg leitet er den Kreuzzug der Koalition gegen die Geißel und plant Vorstöße in verseuchte Festungen wie Stratholme.",h="Lord Maxwell Tyrosus ist der Oberste Kommandant der Argentumdämmerung und in ihrer vorgeschobenen Bastion...",kw={"argentumdämmerung","kirkessen","kapelle des hoffnungsvollen lichts","paladin","geißel","silberne hand","stratholme","tyrosus"},ang={["class:Paladin"]="Tyrosus verkörpert den ungebrochenen Geist der Silbernen Hand und wahrt die Tugenden von Mitgefühl, Einheit und Disziplin nach Uthers Tod und dem tragischen Verfall der Splitterfraktionen des Ordens.",["faction:Alliance"]="Obwohl er als Adliger von Lordaeron und Held der Allianz geboren wurde, verschreibt Tyrosus seine Streitkräfte nun einem unabhängigen Orden, der jeden willkommen heißt, der bereit ist, gegen die Geißel zu kämpfen.",["faction:Horde"]="Anders als die Fanatiker in Herdweiler und im Scharlachroten Kloster setzt sich Tyrosus seit Langem für die Zusammenarbeit mit Nichtmenschen ein und sorgt dafür, dass Krieger und Schamanen der Horde in der Kapelle des hoffnungsvollen Lichts als Gleichberechtigte akzeptiert werden."},sec={{t="Ein Veteran von Lordaeron",b="Maxwell Tyrosus ritt während des verheerenden Dritten Krieges an der Seite von Uther der Lichtbringer und bewachte die Ausgänge von Andorhal, als die Geißel durch das Königreich wütete. Nach dem Fall von Lordaeron schloss er sich Hochlord Alexandros Mograine in Herdweiler an, um den Widerstand gegen die Untoten aufrechtzuerhalten. Schon damals setzte sich Tyrosus für die Einheit aller Völker ein und griff ein, als eifernde Gefährten wie Brigitte Abbendis versuchten, Außenstehende wie den Trollpriester Zabra Hexx hinzurichten. Als Alexandros verraten wurde und die Überreste der Silbernen Hand zum fanatischen Scharlachroten Kreuzzug verkamen, weigerte sich Tyrosus, deren Abstieg in den Fremdenhass zu folgen, und spaltete sich ab, um beim Aufbau der Argentumdämmerung zu helfen."},{t="Kommandant der Dämmerung",b="Nach dem Tod von Lord Raymond George übernahm Tyrosus die Führung der Argentumdämmerung. Er hieß Darion Mograine an der Zugwindspitze willkommen und überwachte später die Verteidigungsanlagen der Kapelle des hoffnungsvollen Lichts. Während der brutalen Siege of the Sanguine versetzte Tyrosus Kirkessen the Zealous einen verheerenden Schlag, der die körperliche Hülle des Leichnams für immer zerschmetterte. Von seinem Kommandoposten in der Kapelle aus leitet er weitreichende militärische Operationen in den Pestländern, darunter taktische Angriffe unter Herzog Nicholas Zverenhoff gegen Baron Rivendare in den Ruinen von Stratholme."}},faq={{q="Wer ist Lord Maxwell Tyrosus?",a="Lord Maxwell Tyrosus ist ein erfahrener menschlicher Paladin und der oberste Anführer der Argentumdämmerung. Nachdem er im Dritten Krieg unter Uther der Lichtbringer und Alexandros Mograine gekämpft hatte, befehligt er nun die Verteidigung der Kapelle des hoffnungsvollen Lichts und leitet den Feldzug der Koalition zur Säuberung der Pestländer.",al={"wer ist maxwell tyrosus","tyrosus geschichte","anführer der argentumdämmerung","argentumdämmerung boss"}},{q="Warum verließ Tyrosus den Scharlachroten Kreuzzug?",a="Nach der Ermordung von Alexandros Mograine wurden die Überreste der Silbernen Hand in Lordaeron zunehmend radikaler und fremdenfeindlicher und säuberten jeden, der kein reiner Mensch war. Tyrosus hatte stets an die Zusammenarbeit mit anderen Völkern geglaubt, um die Geißel zu besiegen; daher wandte er sich von den Fanatikern ab und schloss sich der Argentumdämmerung an.",al={"warum tyrosus den scharlachroten kreuzzug verließ","tyrosus scharlachroter kreuzzug","gehört tyrosus zum scharlachroten kreuzzug"}},{q="Wo ist Maxwell Tyrosus zu finden?",a="Er befindet sich im Sanktum der Kapelle des hoffnungsvollen Lichts, der befestigten Hochburg der Argentumdämmerung im äußersten Osten der Östlichen Pestländer.",al={"tyrosus aufenthaltsort","wo ist maxwell tyrosus","tyrosus karte"}},{q="Welche Rolle spielt Tyrosus im Krieg gegen Stratholme?",a="Tyrosus stimmt die übergeordnete militärische Strategie mit Herzog Nicholas Zverenhoff ab und beauftragt bewährte Abenteurer und Stoßtrupps damit, in die gefallene Stadt Stratholme einzudringen und Baron Rivendare, den Kommandanten des Lichkönigs in der Region, auszuschalten.",al={"tyrosus stratholme","tyrosus rivendare"}},{q="Empfängt Tyrosus jeden Besucher?",a="Tyrosus gewährt Außenstehenden nur selten eine Audienz, da er seit Jahren in Kriegsräten zurückgezogen den Fronteinsatz leitet. Abenteurer müssen sich in der Regel den tiefen Respekt der Argentumdämmerung verdienen oder entscheidende Informationen vorlegen, um seine Aufmerksamkeit zu erlangen.",al={"kann man mit tyrosus sprechen","tyrosus audienz"}},{q="Welche Rolle spielte Tyrosus bei der Siege of the Sanguine?",a="Während dieser Schlacht stellte sich Tyrosus Kirkessen the Zealous, einem hochrangigen Lich im Dienste des Lichkönigs. Tyrosus versetzte ihm einen entscheidenden Schlag, der Kirkessen dauerhaft seines physischen Körpers beraubte und den untoten Zauberer daran hinderte, sich jemals wieder in körperlicher Gestalt zu manifestieren.",al={"tyrosus kirkessen","siege of the sanguine"}}},fp="20,330,22.695.0,21.592.0,28.295.0,42.313.0,35.161.0,53.230.0,43.245.0,53.273.0"}
P.entries["npc:lord-pythas"] = {n="Lord Pythas",s="Lord Pythas, einst ein Nachtelfenkrieger namens Aryn, ist einer der vier verdorbenen Anführer der Druiden des Giftzahns in den Höhlen des Wehklagens. Ursprünglich ein Jugendfreund und eingeschworener Beschützer des Erzdruiden Naralex, fiel er dem Alptraum zum Opfer, der den unterirdischen Teil der Oase verseucht. Nun setzt er sowohl kriegerische Macht als auch verdrehte Schlangenmagie gegen jeden ein, der versucht, seinen schlummernden Meister zu erreichen.",h="Lord Pythas, einst ein Nachtelfenkrieger namens Aryn, ist einer der vier verdorbenen Anführer der Druiden des...",kw={"aryn","druiden des giftzahns","edelstein von pythas","anführer der giftzähne","lord pythas","naralex","pythas","die höhlen des wehklagens"},ang={["class:Druid"]="Pythas steht für das tragische Schicksal eines vielversprechenden Akolythen, der sich aus Hingabe der Naturmagie verschrieb, nur um mitzuerleben, wie die Verderbnis des Smaragdgrünen Traums seine Lehren in eine giftige Ketzerei verwandelte.",["class:Warrior"]="Bevor er zu einem Schlangenkultisten verdorben wurde, war Pythas ein disziplinierter Nachtelfenkrieger und persönlicher Beschützer – eine düstere Mahnung, dass kriegerisches Können allein den geistigen Wahnsinn nicht abwenden kann.",["race:NightElf"]="Zu sehen, wie ein geachteter Beschützer wie Aryn dem dunklen Wahnsinn verfällt, ist ein bitterer Schmerz für jeden Nachtelfen, der das Gleichgewicht auf den gezeichneten Böden Kalimdors wiederherstellen will."},sec={{t="Der Fall eines Wächters",b="Bevor er den Namen Pythas annahm, war dieser Nachtelf als Aryn bekannt. Als erfahrener Krieger und vertrauter Jugendgefährte von Naralex diente er als persönliche Leibwache des Erzdruiden, als die Expedition in die trockenen Weiten des Brachlands vordrang. Eifrig bestrebt, Naralex' ehrgeizigem Traum, das karge Land wieder mit üppigem Leben zu erfüllen, besser zu dienen, begann Aryn das Studium des Druidentums und erwies sich als außergewöhnlich schneller Lerner. Doch physische Disziplin und kriegerischer Mut boten keinen Schutz gegen die tückische Verderbnis, die tief in den unterirdischen Klüften lauerte."},{t="Die tödliche Schildwache",b="Als Naralex' Verbindung zum Smaragdgrünen Traum von dunklen Alpträumen gekapert wurde, erlag Aryns Geist gemeinsam mit dem seiner Akolythenkollegen. Er legte seinen früheren Namen sowie seine Loyalität ab und wurde zu Lord Pythas, einem Anführer unter den Druiden des Giftzahns. Während seine Schlangenlord-Gefährten listiges Zauberwirken oder Bestiengestalten bevorzugen, verbindet Pythas nahtlos tödliches Kampfgeschick mit Naturmagie. Nun durchstreift er die gewundenen Tunnel der Höhlen, entschlossen, den verqueren Griff des Alptraums über die Höhlenquelle zu verteidigen."}},faq={{q="Wer ist Lord Pythas?",a="Lord Pythas war ursprünglich ein Nachtelfenkrieger namens Aryn. Er war ein Jugendfreund und persönlicher Leibwächter von Erzdruide Naralex, der das Druidentum erlernte, um das Werk seines Meisters im Brachland zu unterstützen.",al={"wer ist pythas","lord pythas lore","wer war aryn"}},{q="Warum wandte er sich gegen Naralex?",a="Pythas verriet Naralex nicht freiwillig. Als Naralex versuchte, den Smaragdgrünen Traum anzuzapfen, um das Brachland zu heilen, ergriff ein Alptraum die Gedanken des Erzdruiden. Der verderbende Traum sickerte in die Geister seiner Akolythen, raubte Aryn den Verstand und machte ihn zu einem Schlangenlord.",al={"warum ist pythas böse","wie wurde pythas wahnsinnig","warum wurde er druide des giftzahns"}},{q="Was unterscheidet Pythas von den anderen Giftzahnanführern?",a="Anders als die anderen Anführer, die sich rein auf Naturmagie und Bestiengestalten verlassen, war Pythas ein erfahrener Krieger, bevor er zum Druiden ausgebildet wurde. Er kombiniert kriegerisches Kampfgeschick mit druidischer Magie, was ihn zu einem der körperlich beeindruckendsten Verteidiger in den Höhlen macht.",al={"pythas kampfstil","pythas im vergleich zu anderen anführern"}},{q="Warum müssen Abenteurer ihn besiegen?",a="Pythas trägt einen der vier verzauberten Edelsteine bei sich, die zum Abschluss der Quest Anführer der Giftzähne benötigt werden. Die Quest wird von der Druidin Nara Wildmähne in Donnerfels vergeben, welche die Edelsteine aller vier Giftzahnanführer verlangt, um das Brachland von ihren verdrehten Träumen zu befreien.",al={"anführer der giftzähne quest","edelstein von pythas"}},{q="Wo ist Lord Pythas zu finden?",a="Lord Pythas lauert in den tiefen inneren Kammern der Höhlen des Wehklagens, umgeben von verdorbenen Bestien und verbündeten Giftzahn-Kultisten.",al={"pythas aufenthaltsort","wo ist pythas"}},{q="Was geschieht mit seinem Edelstein?",a="Nach seinem Tod wird der Edelstein von Pythas aus seinen Überresten geborgen. Abenteurer bringen ihn zusammen mit den Edelsteinen der anderen drei Schlangenlords zu Nara Wildmähne in Donnerfels, um zu beweisen, dass die Führung der Giftzähne gebrochen ist.",al={"edelstein von pythas nutzen","was ist edelstein von pythas"}}},fx={be91010a={q="Auf wessen Seite steht Lord Pythas?",a="Lord Pythas dient den Leaders of the Fang. Einst ein ergebener Beschützer und Akolyth von Naralex, hat der Alptraum Besitz von seinem Verstand ergriffen und seine Loyalität verzerrt. Nun steht er fest auf der Seite dieser abtrünnigen Sekte und setzt seine Klinge sowie Naturmagie ein, um den Alptraum zu beschützen, anstatt den Meister zu verteidigen, den er einst zu beschützen schwor.",al={"fraktion von pythas","allianz von pythas","wem dient pythas"}},a058df7c={q="Was will Lord Pythas?",a="Vom Alptraum, der Naralex' Schlaf infiziert hat, in den Wahnsinn getrieben, versucht Pythas, Die Höhlen des Wehklagens vor jedem zu verteidigen, der sie reinigen will. Seines Verstandes beraubt, wünscht er sich nur, Eindringlinge zu vernichten, die den Griff des Alptraums bedrohen, und richtet seine kriegerische Disziplin und druidische Macht vollständig darauf aus, die korrumpierte Domäne zu bewahren.",al={"ziele von pythas","was versucht pythas zu tun","motive von pythas"}},["03b88a66"]={q="Warum ist Lord Pythas in den Höhlen des Wehklagens?",a="Pythas reiste ursprünglich unter seinem wahren Namen, Aryn, in die Höhlen, als Kindheitsfreund und persönlicher Leibwächter von Naralex während des Rituals zur Wiederherstellung des Brachlands. Als Naralex' Trance sich in einen unentrinnbaren Alptraum verwandelte, erlag Pythas zusammen mit den anderen Jüngern diesem Schicksal und blieb tief in den Höhlen als korrumpierter Wächter des Giftzahns zurück.",al={"warum ist pythas in den höhlen des wehklagens","grund für pythas aufenthaltsort","wie kam pythas hierher"}},["8f1c0566"]={q="Mit wem ist Lord Pythas verbunden?",a="Vor seinem Abstieg in den Wahnsinn war Pythas als Aryn bekannt, ein enger Kindheitsfreund und persönlicher Beschützer des Erzdruiden Naralex. Er reiste zu den unterirdischen Quellen, um Naralex zu schützen, während er Druidentum erlernte, doch die alles durchdringende Verderbnis brach seinen Verstand und band ihn an die übrigen verdrehten Leaders of the Fang.",al={"pythas und naralex","verbindungen von pythas","wen kennt pythas"}},eb0bbb13={q="Warum wird Lord Pythas gefürchtet?",a="Lord Pythas gilt als der furchterregendste der Leaders of the Fang. Im Gegensatz zu vielen Akolythen, die sich nur auf Naturzauber verlassen, war Pythas ein erfahrener Krieger, bevor er Druide wurde. Seine Kombination aus tödlicher Nahkampfkraft, schierer physischer Widerstandsfähigkeit und dunkler druidischer Magie macht ihn für jede Expedition außerordentlich gefährlich.",al={"ist pythas gefährlich","warum ist pythas stark","stärke von pythas"}}},fp="11,387,16.558.0,19.501.0,19.193.0,32.286.0,56.259.0,38.253.0,31.132.0,24.228.0"}
P.entries["npc:lord-serpentis"] = {n="Lord Serpentis",s="Lord Serpentis ist ein korrumpierter Nachtelfendruide, der als einer der vier Anführer der abtrünnigen Druiden des Giftzahns in den Höhlen des Wehklagens weilt. Einst ein Druide von großer Macht und hohem Ansehen im Orden von Naralex, verfiel er dem Wahnsinn, als Naralex' Traum in den unterirdischen Quellen zu einem Albtraum wurde. Nun befehligt er die Schlangen verehrende Sekte tief in den Höhlen, wo der korrumpierte Naralex im Schlummer liegt.",h="Lord Serpentis ist ein korrumpierter Nachtelfendruide, der als einer der vier Anführer der abtrünnigen...",kw={"druiden des giftzahns","edelstein von serpentis","anführer der giftzähne","lord serpentis","naralex","serpentis","die höhlen des wehklagens"},ang={["class:Druid"]="Serpentis verkörpert die tragische Gefahr, die im Smaragdgrünen Traum lauert, und veranschaulicht, wie selbst ein Druide von großer Macht verzerrt werden kann, wenn eine edle Vision zum Albtraum wird.",["race:NightElf"]="Für Nachtelfen sind Serpentis und seine Anhänger eine schmerzhafte Schande – Gelehrte der Kaldorei von großem Renommee, die ihre heilige Pflicht gegenüber der Natur wegwarfen, um zu monströsen Schlangenlords zu werden.",["race:Tauren"]="Tauren sehen in der Verderbnis von Serpentis eine abscheuliche Entweihung des Gleichgewichts der Erdenmutter, die das empfindliche Ökosystem des Brachlands mit unnatürlichem Wahnsinn bedroht."},sec={{t="Vom edlen Druiden zum Schlangenlord",b="Bevor die Finsternis die Quellen der Höhle einnahm, war Serpentis ein Druide von großer Macht und hohem Ansehen, Teil des edlen Ordens unter der Führung von Naralex, der hoffte, die Quellen der Höhlen und den Smaragdgrünen Traum zu nutzen, um das Brachland zu heilen. Doch als Naralex' Vision zu einem verderblichen Albtraum wurde, gehörte Serpentis zu den Druiden, deren Geist dem aufkeimenden Wahnsinn anheimfiel."},{t="Ein Lord der Giftzähne",b="Der Verderbnis, die von Naralex' verzerrten Träumen ausging, gänzlich erlegen, wurden Serpentis und seine Druidengefährten zu den Druiden des Giftzahns. Sie sagten sich vom traditionellen cenarischen Gleichgewicht und den Totemtieren vergangener Tage los und trachten nun danach, das Brachland nach ihren eigenen verzerrten Träumen umzugestalten, anstatt es zu heilen. Serpentis herrscht über die Sekte als einer ihrer vier Anführer, an der Seite von Lady Anakondra, Lord Kobrahn und Lord Pythas."},{t="Das letzte Hindernis",b="Tief in den verwinkelten Höhlen thronend, ist Lord Serpentis einer der vier Anführer der abtrünnigen Sekte, von denen jeder einen Traumedelstein bei sich trägt. Jene, die den gefangenen Meister erwecken oder die Gewässer der Oase zurückfordern wollen, müssen Serpentis niederstrecken und den Edelstein an sich bringen, den er trägt, um den Griff der Schlange über das Labyrinth zu brechen."}},faq={{q="Wer ist Lord Serpentis?",a="Lord Serpentis ist einer der vier Anführer der Druiden des Giftzahns tief in den Höhlen des Wehklagens. Einst ein Nachtelfendruide von großer Macht und hohem Ansehen in Naralex' Orden, wurde er zusammen mit seinen Druidengefährten von Naralex' Albtraum korrumpiert.",al={"wer ist serpentis","lord serpentis lore","serpentis hintergrund"}},{q="Warum wurde Serpentis böse?",a="Als Naralex' Versuch, das Brachland durch den Smaragdgrünen Traum zu heilen, in einen Albtraum umschlug, griff seine Verderbnis auf die Druiden über, die ihm folgten, und trieb Serpentis' Geist in den Wahnsinn und die Schlangenverehrung.",al={"warum serpentis böse wurde","serpentis verderbnis","warum serpentis böse ist"}},{q="Was ist seine Beziehung zu Naralex?",a="Serpentis war einst einer der edlen Druiden, die Naralex in die Höhlen folgten. Anstatt seinem Meister bei der Genesung beizustehen, wurde er zu einem Anführer der Druiden des Giftzahns, die nun versuchen, das Brachland nach ihren eigenen verzerrten Träumen umzugestalten.",al={"serpentis und naralex","ist serpentis mit naralex verwandt","naralex lehrling"}},{q="Warum müssen Spieler ihn töten?",a="Serpentis ist einer der vier Anführer der Druiden des Giftzahns. Ihn zu beseitigen ist unerlässlich, um die Herrschaft der Sekte über die Höhlen des Wehklagens zu brechen, sich seinen Edelstein für die Quest Anführer der Giftzähne zu sichern und einen Pfad zur Erweckung von Naralex freizumachen.",al={"warum serpentis töten","anführer der giftzähne serpentis","edelstein von serpentis"}},{q="Wer sind die Druiden des Giftzahns?",a="Sie sind eine abtrünnige Fraktion von Nachtelfendruiden, die Naralex in die Höhlen des Wehklagens folgten. Vom Smaragdgrünen Albtraum korrumpiert, gaben sie die traditionellen druidischen Gestalten auf, um unter dem Befehl von Serpentis und ihren anderen Giftzahnfürsten die Aspekte, Gifte und Verhaltensweisen von Schlangen anzunehmen.",al={"druiden des giftzahns lore","was sind druiden des giftzahns","giftzahndruiden"}}},fx={["1f07cf4d"]={q="Auf wessen Seite steht Lord Serpentis?",a="Lord Serpentis ist der Anführer der Druiden des Giftzahns. Korrumpiert durch den Alptraum, der seinen Mentor Naralex verzehrt, hat er den Zirkel des Cenarius und die Ideale der Nachtelfen aufgegeben und ist allen gegenüber, die die Höhlen betreten, vollkommen feindselig eingestellt.",al={"fraktion von lord serpentis","wem dient serpentis","loyalität von serpentis"}},["961c3dfc"]={q="Was will Lord Serpentis?",a="Ursprünglich angetrieben von einem tiefen Ehrgeiz, ein Shan'do zu werden – ein geehrter Lehrer wie sein Mentor Naralex – wurden seine Wünsche durch den Smaragdgrünen Alptraum in Wahnsinn verkehrt. Nun geistesgestört, versucht er, mit seinen verdrehten Anhängern die Herrschaft über die Höhlen zu halten, und proklamiert sich selbst zum obersten Meister der Schlangen.",al={"ziel von serpentis","was will serpentis","motive von serpentis"}},["54e444da"]={q="Warum ist Lord Serpentis in den Höhlen des Wehklagens?",a="Serpentis kam ursprünglich als bester Schüler von Naralex in die Höhlen des Wehklagens und half seinem Mentor, die unterirdischen Quellen anzuzapfen, um das Brachland wiederherzustellen. Als Naralex die Kontrolle über seinen Traum verlor und Alptraum-Verderbnis ausbrach, wurde Serpentis Opfer der psychischen Qualen und blieb zurück, um die Höhlen als Herrscher der Druiden des Giftzahns zu beanspruchen.",al={"warum ist serpentis hier","warum ist lord serpentis in den höhlen des wehklagens","grund für lord serpentis aufenthaltsort"}}},fp="14,426,32.350.0,18.412.0,18.316.1,22.250.0,28.208.0,36.242.0,32.234.0,31.285.0"}
P.entries["npc:lord-shalzaru"] = {n="Lord Shalzaru",s="Lord Shalzaru ist der tyrannische Anführer der Naga der Hatecrest, die von der Insel des Schreckens vor der Küste von Feralas aus operieren. Er herrscht mit absoluter Grausamkeit über seine schlangenartigen Anhänger und beaufsichtigt umfangreiche Ausgrabungen inmitten der versunkenen und verfallenen elfischen Siedlungen. Seine jüngste Entdeckung eines seltsamen, uralten Relikts hat die Aufmerksamkeit außenstehender Ermittler geweckt, die es ihm unbedingt entreißen wollen.",h="Lord Shalzaru ist der tyrannische Anführer der Naga der Hatecrest, die von der Insel des Schreckens vor der...",kw={"feralas","hatecrest","die insel des schreckens","lord shalzaru","geheimnisvolles relikt","naga","shalzaru"},ang={["faction:Alliance"]="Die Sicherung von Shalzarus Relikt und das Neutralisieren des Kriegsfürsten der Hatecrest trägt dazu bei, die abgelegenen Vorposten der Allianz an der ungezähmten Küste von Feralas zu schützen.",["faction:Horde"]="Späher der Horde haben ein wachsames Auge auf Bedrohungen an der Küste von Feralas, und das Niederschlagen des Nagafürsten beseitigt eine unberechenbare Gefahr nahe der Interessensphäre von Camp Mojache.",["race:NightElf"]="Die Naga der Hatecrest entweihen die antiken Ruinen des alten Kalimdor; das Zurückholen von Relikten von Shalzaru verhindert, dass das dunkle Erbe der Hochgeborenen seine schlangenartige Sippe stärkt."},sec={{t="Meister der Hatecrest",b="Lord Shalzaru befehligt die Naga der Hatecrest und lenkt deren Präsenz entlang der Südküste von Feralas. Aus seinem unterirdischen Unterschlupf in einer Höhle auf der Insel des Schreckens setzt er seine Herrschaft mit Grausamkeit und unbarmherziger Autorität durch. Unter seinem Befehl durchkämmen die Hatecrest die antiken Ruinen des alten Kalimdor auf der Suche nach vergessenen Schätzen und mächtigen Relikten, die von der Zerschlagung zurückgeblieben sind."},{t="Das geheimnisvolle Relikt",b="Bei Ausgrabungen südlich der primären Ruinen auf der Insel des Schreckens barg Shalzaru persönlich ein seltsames, uraltes Relikt. Zweck und Macht dieses Artefakts bleiben ein Rätsel, doch seine Bergung durch einen solch mächtigen Kriegsfürsten der Naga stellt eine eindeutige Bedrohung dar. Ermittler auf dem Festland suchen tapfere Streiter, die sich in die Schlangenhöhle wagen, Shalzarus Herrschaft beenden und das sonderbare Relikt sichern, bevor die Hatecrest es für dunklere Zwecke nutzen können."}},faq={{q="Wer ist Lord Shalzaru?",a="Lord Shalzaru ist der grausame königliche Anführer der Naga der Hatecrest. Er beaufsichtigt die Streitkräfte und Ausgrabungen der Naga auf der Insel des Schreckens vor der Küste von Feralas.",al={"lord shalzaru lore","shalzaru","wer ist shalzaru"}},{q="Wo ist Lord Shalzaru zu finden?",a="Er haust in einer Höhle südlich der elfischen Hauptruinen jenseits des Wassers auf der Insel des Schreckens, vor der südwestlichen Küste von Feralas.",al={"shalzaru standort","wo ist lord shalzaru","insel des schreckens höhle"}},{q="Wer sind die Hatecrest?",a="Die Hatecrest sind ein feindseliger Stamm von Naga, der die Küstenlinie und Inseln von Feralas besetzt und dafür bekannt ist, unter Shalzarus Befehl antike Ruinen zu durchkämmen und die Küstengewässer zu terrorisieren.",al={"hatecrest naga","hatecrest stamm"}},{q="Welches Relikt besitzt Lord Shalzaru?",a="Bei einer kürzlichen Ausgrabung auf der Insel des Schreckens legte Shalzaru ein geheimnisvolles, uraltes Relikt unbekannter Herkunft und Macht frei, was Fraktionen des Festlands dazu veranlasste, Abenteurer auszusenden, um es einzufordern.",al={"shalzaru relikt","geheimnisvolles relikt feralas"}},{q="Warum muss Lord Shalzaru bezwungen werden?",a="Die Ausschaltung von Shalzaru bricht die Führung der Hatecrest auf der Insel des Schreckens und erlaubt es Abenteurern, das geheimnisvolle Relikt zu bergen, das er kürzlich ausgegraben hat, bevor die Naga es sich zunutze machen können.",al={"gegen lord shalzaru","lord shalzaru töten"}},{q="Wonach graben die Hatecrest in Feralas?",a="Die Hatecrest graben in den zerstörten Siedlungen der Nachtelfen, die während der Großen Zerschlagung zertrümmert wurden, und suchen nach mächtigen magischen Relikten und Überresten der Geschichte der Hochgeborenen, die unter der Erde und den Wellen verborgen liegen.",al={"hatecrest ausgrabung","warum sind naga in feralas"}}},fp="13,392,23.394.0,20.439.0,21.159.0,33.135.0,22.183.0,38.189.0,35.182.0,46.194.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="Hüter des Wissens Raintotem",s="Hüter des Wissens Raintotem ist ein Ältester der Tauren, der im nördlichen Mulgore direkt südlich der Teufelsfelsen stationiert ist. Er kümmert sich um die heiligen Begräbnisstätten und bittet Abenteurer, die dort störenden Stachelborstenquillboar zu vertreiben.",h="Hüter des Wissens Raintotem ist ein Ältester der Tauren, der im nördlichen Mulgore direkt südlich der...",kw={"hüter des wissens raintotem","mulgore","raintotem","teufelsfelsen","heilige bestattung"},ang={["class:Shaman"]="Raintotems Wachsamkeit über die ruhelosen Toten an den Teufelsfelsen betrifft direkt schamanische Pflichten und stellt sicher, dass die Geister der Ahnen den gebührenden Frieden und Respekt erhalten.",["race:Tauren"]="Raintotem bei der Verteidigung der Teufelsfelsen zu helfen, ehrt die Ahnen und bewahrt die Begräbnistraditionen Eures Volkes."},sec={{t="Wächter der Teufelsfelsen",b="Nahe den heiligen Klippen der Teufelsfelsen in Mulgore stationiert, kümmert sich Hüter des Wissens Raintotem um die spirituellen Verpflichtungen seines Volkes. Er bittet Abenteurer, die Stachelborsten-Eindringlinge von der Begräbnisstätte zu vertreiben und den Frieden an der Ruhestätte der Ahnen wiederherzustellen."},{t="Verteidiger der Ahnenstätten",b="Über das Prüfen junger Helden hinaus wacht Hüter des Wissens Raintotem über die heiligen Begräbnisstätten bei den Teufelsfelsen. Wenn Stachelborstenquillboar die geweihten Ruhestätten verstorbener Taurenhäuptlinge und Schamanen stören, rekrutiert Raintotem Reisende, um die Würde wiederherzustellen und die gestörten Toten zu beruhigen."}},faq={{q="Wo finde ich Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem ist im nördlichen Mulgore stationiert, direkt südlich der Teufelsfelsen an dem Pfad gelegen, der zu den Ahnenklippen hinaufführt.",al={"standort raintotem","wo ist hüter des wissens raintotem","raintotem mulgore finden"}},{q="Warum bittet Raintotem um Hilfe bei den Begräbnisstätten?",a="Er bittet Abenteurer, die Stachelborsten-Eindringlinge von den Teufelsfelsen zu vertreiben, wo die Quillboar die heilige Begräbnisstätte der Tauren verwüsten.",al={"raintotem heilige bestattung","warum raintotem helfen","teufelsfelsen begräbnisstätten"}},{q="Warum benötigt Raintotem Hilfe bei den Teufelsfelsen?",a="Die Teufelsfelsen dienen als heilige Begräbnisstätte der Tauren, doch Stachelborsten-Eindringlinge verwüsten den Friedhof. Raintotem beauftragt fähige Abenteurer damit, die entweihten Ahnenstätten wieder in Ordnung zu bringen.",al={"problem teufelsfelsen","warum quest heilige bestattung"}}},fx={["4ada6d87"]={q="Wer ist Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem dient seiner Tauren-Gemeinschaft, bewahrt die Traditionen der Ahnen und stellt sicher, dass die Gefallenen ein heiliges Begräbnis erhalten.",al={"wer ist raintotem","infos zu hüter des wissens raintotem","über raintotem"}},["29f679b7"]={q="Auf wessen Seite steht Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem ist den Tauren-Stämmen von Mulgore und der Horde unter Hochhäuptling Cairne Bluthuf vollkommen loyal. Er dient als geehrter kultureller Ältester und unterstützt jeden Abenteurer der Horde, der Respekt vor den heiligen Riten und den Ahnen seines Volkes zeigt.",al={"fraktion von raintotem","gehört raintotem zur horde","loyalität von raintotem"}},["6a12fd3c"]={q="Warum ist Hüter des Wissens Raintotem hier?",a="Raintotem hält südlich der Teufelsfelsen Wache, da dies die heilige Ahnenbegräbnisstätte der Tauren-Stämme ist. Er bleibt in der Nähe stationiert, um das geheiligte Land zu schützen, Pilger zu führen, die den Segen der Ahnen suchen, und Bedrohungen entgegenzutreten, die die Geister stören, welche innerhalb der roten Felsenklippen ruhen.",al={"warum ist raintotem bei den teufelsfelsen","grund für raintotems aufenthaltsort","warum ist hüter des wissens raintotem in mulgore"}},["88640b34"]={q="Was will Hüter des Wissens Raintotem?",a="Er kümmert sich um die Ahnenbegräbnisstätten bei den Teufelsfelsen und bittet Abenteurer, die Borstennacken-Eindringlinge zu vertreiben, die dort stören.",al={"was will raintotem","ziele von raintotem","worum bittet raintotem"}}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:lorgus-jett"] = {n="Lorgus Jett",s="Lorgus Jett ist ein menschliches Mitglied des Kults des Schattenhammers, das in den überfluteten Korridoren der Tiefschwarzen Grotte operiert. Während er die Moonshrine Ruins durchstreift, dient er als skrupelloser Kommandant im Dienste des Kults für die Alten Götter. Anführer der Horde haben ihn als vorrangiges Ziel auserkoren, um die vordringende Präsenz des Kults entlang der Küste des Eschentals zu zerschlagen.",h="Lorgus Jett ist ein menschliches Mitglied des Kults des Schattenhammers, das in den überfluteten Korridoren...",kw={"allegiance to the old gods","tiefschwarze grotte","lorgus jett","moonshrine ruins","twilight's hammer"},ang={["class:Shaman"]="Jett führt die Elemente nicht in Harmonie oder Ehrerbietung, sondern durch die verderbten, gewaltsamen Methoden, die der Schattenhammer lehrt.",["faction:Horde"]="Lorgus Jett niederzustrecken erfüllt eine dringende Bitte, die Führung des Schattenhammers zu zerschlagen, die sich unter der Küste des Eschentals festsetzt.",["race:Human"]="Einen Menschen so weit westlich in Kalimdor im Dienst kosmischer Schrecken zu sehen, ist eine erschreckende Mahnung daran, wie weit die Verderbnis des Schattenhammers bereits reicht."},sec={{t="Ein Schänder in den Ruinen",b="Während viele Mitglieder des Schattenhammers, die in der Tiefschwarzen Grotte arbeiten, orkischer oder Tauren-Abstammung sind, sticht Lorgus Jett als Mensch in den tiefen Winkeln uralter Nachtelfenruinen hervor. Jett streift überall zwischen den oberen Moonshrine Ruins und den höhlenartigen Tunneln jenseits des Murloc-Schänders Gelihast umher und koordiniert die finsteren Rituale und gewaltsamen Ambitionen des Kults."}},faq={{q="Wer ist Lorgus Jett?",a="Lorgus Jett ist ein menschlicher Agent des Kults des Schattenhammers, der in der Tiefschwarzen Grotte stationiert ist. Er beaufsichtigt die Aktivitäten des Kults in den Moonshrine Ruins und dient den Alten Göttern.",al={"lorgus jett lore","wer ist lorgus","lorgus jett hintergrund"}},{q="Wo ist Lorgus Jett in der Tiefschwarzen Grotte zu finden?",a="Lorgus Jett hat ein wechselndes Patrouillengebiet innerhalb der Moonshrine Ruins. Er kann in der Nähe der ersten Gruppen von Schattenhammer-Kultisten auftauchen oder weiter hinten in den überfluteten Gängen kurz hinter Gelihasts Schrein.",al={"lorgus jett aufenthaltsort","wo ist lorgus jett","lorgus jett finden"}},{q="Warum will die Horde Lorgus Jett tot sehen?",a="Die Horde trachtet im Rahmen der Mission „Allegiance to the Old Gods“ nach seinem Tod. Seine Präsenz im Eschental bedroht die regionale Stabilität und stellt ein heimtückisches Bündnis dar, das sich der Entfesselung uralter, weltenzerstörender Wesenheiten verschrieben hat.",al={"warum lorgus toeten","allegiance to the old gods quest"}},{q="Warum nutzt ein Mensch schamanistische Kräfte?",a="Der Schattenhammer kommuniziert direkt mit chaotischen Elementarkräften und Alten Göttern statt mit traditionellen Geistern der Ahnen, was es untypischen Völkern wie Menschen ermöglicht, elementare Verwüstung zu entfesseln.",al={"lorgus jett magie","mensch schamane lorgus"}},{q="Was verbindet Lorgus Jett mit Gelihast?",a="Beide hausen in den Moonshrine Ruins der Tiefschwarzen Grotte, vereint in ihrer Knechtschaft gegenüber den dunklen Mächten, die unter dem Meer schlummern, wobei Jett regelmäßig die Gänge jenseits von Gelihasts Altar patrouilliert.",al={"lorgus und gelihast","gelihast verbindung"}}},fx={["647bfdae"]={q="Auf wessen Seite steht Lorgus Jett?",a="Lorgus Jett dient dem Schattenhammer, dem apokalyptischen Kult, der sich den Alten Göttern verschrieben hat. Obwohl er ein Mensch ist, hat er seine Verwandten verlassen, um sich den dunklen Ritualisten und Elementarkräften anzuschließen, die sich in den vergessenen Tiefen des Eschentals versammeln.",al={"fraktion von lorgus jett","wem dient lorgus jett","welcher fraktion gehört lorgus jett an"}},ba0235c4={q="Warum ist Lorgus Jett in der Tiefschwarzen Grotte?",a="Er lauert zusammen mit seinen Kultistenkollegen in den unterirdischen Moonshrine Ruins und führt den Willen des Schattenhammers aus. Tief im Inneren des alten Elbentempels kümmert sich der Kult um dunkle Schrecken und verehrt die uralten Mächte, die sich unter den Wassern regen.",al={"warum ist lorgus jett in der tiefschwarzen grotte","zweck von lorgus jett in der tiefschwarzen grotte","warum ist lorgus jett hier"}}},fp="11,350,22.373.0,19.179.0,52.199.0,41.223.0,40.200.0,45.198.0"}
P.entries["npc:loslor-rudge"] = {n="Loslor Rudge",s="Loslor Rudge ist ein geschäftstüchtiger zwergischer Ingenieursbedarfshändler, der in Stahlrosts Depot in Dun Morogh stationiert ist. Er versorgt Tüftler in den verschneiten Gebirgszügen mit mechanischen Teilen, Werkzeugen und Munition und hält wichtige Verbindungen zu Büchsenmachern wie Hegnar Schlingerschuss aufrecht.",h="Loslor Rudge ist ein geschäftstüchtiger zwergischer Ingenieursbedarfshändler, der in Stahlrosts Depot in Dun...",kw={"munition","dun morogh","ingenieurskunst","der altgediente bau","hegnar schlingerschuss","loslor rudge","stahlrosts depot"},ang={["profession:Engineering"]="Loslor führt wichtige Vorräte für das frühe Handwerk – wie etwa Flussmittel, Sprengpulver, Röhren und Tüftlersätze –, was seinen Posten im Depot zu einer praktischen Anlaufstelle für jeden angehenden Ingenieur auf der Reise durch Dun Morogh macht.",["race:Dwarf"]="Wie bei vielen Handwerkern in Dun Morogh hängt Loslors Lebensunterhalt von verlässlichen Karawanenrouten zwischen den verstreuten Zwergenlagern ab, was zeigt, wie selbst einheimische Raubtiere wie Wendigos den Handel im Gebirge stören können."},sec={{t="Ein Lieferant im Schnee",b="Von seinem Stützpunkt in Stahlrosts Depot gleich die Straße hinunter von Kharanos aus führt Loslor Rudge einen stetigen Vorrat an unverzichtbarem Ingenieursbedarf – von Kupfermodulatoren und Bronzeröhren bis hin zu Sprengpulver und Schraubenschlüsseln. Das raue Wetter in Dun Morogh und die ausgedehnten Tüftelarbeiten bedeuten, dass praktische Teile ständig gefragt sind, und Loslor ist stolz darauf, die einheimischen Schrauber zu versorgen. Die Wildnis zwischen den Außenposten ist jedoch tückisch; als ein Kurier, der eine Abkürzung in der Nähe des altgedienten Baus nahm, von Wendigos verjagt wurde, blieb eine wichtige Munitionslieferung für seinen geschätzten Kunden, den Büchsenmacher Hegnar Schlingerschuss, im Schnee zurück."}},faq={{q="Wer ist Loslor Rudge?",a="Loslor Rudge ist ein zwergischer Ingenieursbedarfshändler, der sein Geschäft in Stahlrosts Depot in Dun Morogh betreibt. Er verkauft Tüftlerwerkzeuge, Teile und Munition an Abenteurer und Handwerker in der gesamten Region.",al={"loslor rudge","wer ist rudge","steelgrills depot ingenieur"}},{q="Bei welchem Problem braucht Loslor Hilfe?",a="Er hat kürzlich einen Kurier entsandt, um eine Munitionslieferung zum Büchsenmacher Hegnar Schlingerschuss zu bringen. Der Kurier nahm eine Abkürzung am altgedienten Bau vorbei, geriet an wilde Wendigos und floh, wobei er die Kiste im Schnee zurückließ. Loslor braucht jemanden, der die Lieferung birgt, bevor er seinen geschätzten Kunden verliert.",al={"munition für rumbleshot quest","was will rudge","rudge kurier"}},{q="Wo befindet sich Stahlrosts Depot?",a="Stahlrosts Depot ist ein geschäftiger zwergischer Sammelplatz und eine Maschinenwerkstatt, die direkt östlich von Kharanos an der Hauptstraße nach Loch Modan liegt.",al={"wo ist steelgrills depot","steelgrill standort"}},{q="Wer ist Hegnar Schlingerschuss?",a="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der von einem Lager in Dun Morogh aus arbeitet und für frische Munitionslieferungen und mechanische Bauteile auf Loslor Rudge angewiesen ist.",al={"wer ist hegnar","rumbleshot"}}},fx={["774accc1"]={q="Auf wessen Seite steht Loslor Rudge?",a="Loslor Rudge ist ein loyales Mitglied der Zwergengemeinschaft von Eisenschmiede und der Allianz. Von Stahlrosts Depot aus betreibt er Geschäfte, die zwergische Scharfschützen, Handwerker und nahegelegene Siedlungen in ganz Dun Morogh direkt unterstützen.",al={"fraktion von loslor rudge","gehört loslor rudge zur allianz","wem dient loslor rudge"}},["1a06e65e"]={q="Warum ist Loslor Rudge in Stahlrosts Depot?",a="Loslor arbeitet von Stahlrosts Depot aus als Ingenieurslieferant und Händler. Das Depot dient als geschäftiger Knotenpunkt für zwergische Maschinerie, Reparaturen und Industrie außerhalb von Eisenschmiede, was es zu einem idealen Ort für ihn macht, um Bastlerteile und Pulver zu verkaufen und Munition für regionale Büchsenmacher herzustellen.",al={"warum ist loslor rudge hier","rolle von loslor rudge in stahlrosts depot","warum ist loslor im depot"}}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
P.entries["npc:lotwil-veriatus"] = {n="Lotwil Veriatus",s="Lotwil Veriatus ist ein exzentrischer gnomischer Gelehrter, der in den staubigen Weiten des Ödlands gefährliche Elementarexperimente durchführt. Östlich von Kargath mit seinem sarkastischen Lehrling Lucien Tosselwrench und einem mechanischen Diener namens Servo stationiert, widmet er sich der Verschmelzung von arkaner Theorie, Alchemie und Ingenieurskunst zu einer einheitlichen Disziplin.",h="Lotwil Veriatus ist ein exzentrischer gnomischer Gelehrter, der in den staubigen Weiten des Ödlands...",kw={"ödland","elementar","fam'retor","kargath","lotwil","lucien","servo","veriatus"},ang={["profession:Engineering"]="Ingenieure werden Lotwils Bestreben wiedererkennen, mechanische Gyros und Zahnräder in arkane Eindämmungsfelder zu integrieren, ebenso wie die klassische ingenieurstechnische Tücke einer plötzlichen, gewaltsamen Fehlfunktion.",["race:Gnome"]="Lotwil ist ein Paradebeispiel für gnomischen intellektuellen Ehrgeiz, der bis ins Waghalsige getrieben wird, indem er versucht, Ingenieurskunst und das Arkane ungeachtet der katastrophalen Risiken miteinander zu verbinden."},sec={{t="Ein vereintes Feld des Chaos",b="Ursprünglich aus Kharanos in Dun Morogh stammend, träumt Lotwil von einer großen Universität für seine Erleuchtete Vereinigung für Arkanologie, Alchemie und Ingenieurswissenschaften. Er glaubt, dass diese drei Disziplinen nicht isoliert voneinander ausgeübt, sondern harmonisiert werden sollten. Um diesen Traum zu verwirklichen, wählte er das raue Ödland als sein Laboratorium, um einheimische Felselementare zu erforschen und bindende Fesseln zu konstruieren, die elementare Kräfte beherrschen können. Obwohl er ein versierter Forscher ist – der in der Vergangenheit Elementarmaschinen untersuchte und Dunkeleisenkonstrukte bezwang –, macht ihn sein unerschütterlicher Fokus oft blind für die explosiven Gefahren seiner Feldforschung."},{t="Die Elementarfesseln",b="Lotwils großes Bestreben im Ödland konzentriert sich darauf, seine Fesseln der Elementarbindung zu testen. Indem er Abenteurer damit beauftragt, Felselementarkerne, Kühlmittel und Gyrochronatome zu sammeln, bereitet er ein aufwendiges Ritual vor, das einen elementaren Diener unterwerfen soll. Doch als die Bindungsvorrichtung schließlich aktiviert wird, geht das Zusammenspiel aus unbeständiger Magie, unberechenbarer Ingenieurskunst und instabilen alchemistischen Reagenzien katastrophal schief und beschwört ein gewaltiges, rasendes Elementarmonstrum namens Fam'retor herauf, das sich gegen seinen Schöpfer wendet."}},faq={{q="Wer ist Lotwil Veriatus?",a="Lotwil Veriatus ist ein gnomischer Gelehrter, der in einem abgelegenen Lager östlich von Kargath im Ödland weilt. Er ist ein Gründungsmitglied der Erleuchteten Vereinigung für Arkanologie, Alchemie und Ingenieurswissenschaften und versucht, alle drei Gebiete zu einer einzigen akademischen Disziplin zu verschmelzen.",al={"wer ist lotwil","lotwil veriatus lore","gnom im ödland"}},{q="Warum hält sich Lotwil im Ödland auf?",a="Lotwil kam ins Ödland, um die dortige dichte Ansammlung wilder Felselementare zu erforschen. Die offene Wüste bietet sowohl rohes Elementarmaterial als auch genügend Raum, um unberechenbare Bindungsexperimente durchzuführen, ohne größere Bevölkerungszentren zu gefährden.",al={"warum ist lotwil im ödland","lotwil ödland lager","was macht lotwil"}},{q="Wer ist Lucien Tosselwrench?",a="Lucien Tosselwrench ist Lotwils leidgeprüfter gnomischer Assistent. Völlig zynisch und erschöpft von den exzentrischen Ausführungen seines Meisters, kümmert sich Lucien um die Logistik, repariert den mechanischen Diener Servo und warnt Unbeteiligte regelmäßig vor Lotwils gefährlicher Sorglosigkeit.",al={"lucien tosselwrench","lotwil assistent","lotwil lehrling"}},{q="Was geschieht, wenn Lotwil sein Experiment beendet?",a="Lotwil versucht, seine eigens angefertigten Fesseln der Elementarbindung zu nutzen, um ein Elementarkonstrukt zu versklaven. Die Hybridtechnologie scheitert spektakulär und beschwört ein riesiges, erzürntes Felselementar namens Fam'retor herauf, das getötet werden muss, bevor es sein Lager zerstört.",al={"lotwil experiment gescheitert","fesseln der elementarbindung","fam'retor"}}},fp="15,338,24.619.0,22.526.1,23.268.0,34.248.0,27.269.0,49.259.1"}
P.entries["npc:lucius"] = {n="Lucius",s="Lucius ist ein Zwergenagent, der in der Nähe der Docks von Seenhain im Rotkammgebirge zu finden ist. Er fungiert als verdeckter Feldkontakt für den Geheimdienst Der SI:7 aus Sturmwind und unterstützt Agenten mit spezialisierter Aufklärung sowie handwerklichen Fertigkeiten.",h="Lucius ist ein Zwergenagent, der in der Nähe der Docks von Seenhain im Rotkammgebirge zu finden ist.",kw={"docks","zwerg","seenhain","schlossknacken","lucius","rotkammgebirge","schurke","der si:7"},ang={["class:Rogue"]="Für Schurken, die von Sturmwind ins Feld geschickt werden, fungiert Lucius als unverzichtbarer Kontakt und Ausbilder zur Verfeinerung von Schlossknack- und Aufklärungsfertigkeiten.",["race:Dwarf"]="Lucius erinnert daran, dass zwergische Talente weit über Schmiede und Frontlinie hinausgehen und auch in den verdeckten Operationen von Sturmwind ihren Platz finden."},sec={{t="Augen im Gebirge",b="Während Lucius an der Uferpromenade von Seenhain einen unauffälligen Eindruck erweckt, ist er in Wirklichkeit ein verdeckter Agent, der direkt dem Geheimdienstapparat von Sturmwind, dem SI:7, untersteht. Von seinem Posten an den Docks aus überwacht er den Handel, ungewöhnliche Truppenbewegungen und regionale Bedrohungen, die das Rotkammgebirge gefährden. Agenten, die von Sturmwind nach Osten entsandt werden, werden an ihn verwiesen, um verdeckte Aufträge zu koordinieren und praktische Fertigkeiten der Feldarbeit wie das Schlossknacken zu verfeinern, damit die Krone ihren Einfluss weit über den Wald von Elwynn hinaus sichert."}},faq={{q="Wer ist Lucius?",a="Lucius ist ein in Seenhain stationierter Zwergenagent, der für den SI:7, den Geheimdienst des Königreichs Sturmwind, arbeitet.",al={"lucius identität","wer ist der zwerg an den docks","lucius nsc"}},{q="Was tut Lucius in Seenhain?",a="Er dient als Feldkontakt für verdeckte Agenten, erteilt vor Ort Unterweisung in Diebeskunst und Schlossknacken und behält die regionalen Bewegungen im Rotkammgebirge im Auge.",al={"was macht lucius hier","lucius zweck","warum ist lucius an den docks"}},{q="Welche Quests schließen Lucius ein?",a="Lucius ist die Ansprechperson für die SI:7-Mission „Rendezvous im Rotkammgebirge“ und schickt junge Schurken aus, um die Schlösser von Truhen bei Althers Mühle zu knacken und sich ihr Zertifikat der Diebeskunst zu verdienen.",al={"lucius quests","quest rendezvous im rotkammgebirge","althers mühle"}}},fx={f414b59e={q="Auf wessen Seite steht Lucius?",a="Lucius steht fest auf der Seite der Allianz und untersteht speziell dem SI:7, Sturmwinds Elite-Geheimdienst- und Geheimoperationsagentur. Während er ein bescheidenes Profil wahrt, während er am Pier in Seenhain arbeitet, gelten seine Loyalitäten direkt den Spionagemeistern in der Hauptstadt.",al={"fraktion von lucius","loyalität von lucius","wem dient lucius"}},db7d3191={q="Was will Lucius?",a="Lucius dient als unauffälliger Feldagent für das SI:7. Er behält die Aktivitäten rund um den Immerruhsee und die Grenze des Rotkammgebirges scharf im Auge, verbindet sich mit besuchenden Agenten und leitet vielversprechende Agenten an, die ausgesandt wurden, um sensible Aufgaben in den Bergen auszuführen.",al={"was macht lucius","was braucht lucius","ziele von lucius"}},["2f7f1e59"]={q="Mit wem ist Lucius verbunden?",a="Lucius ist direkt mit dem SI:7 verbunden, dem Geheimdienstnetzwerk mit Sitz in Sturmwind. Er fungiert als ihr ruhiger lokaler Kontakt im Rotkammgebirge und arbeitet mit anderen Agenten zusammen, die in die Region entsandt wurden, um verdeckte Aufklärung und spezialisierte Operationen durchzuführen.",al={"mit wem ist lucius verbunden","verbindungen von lucius","lucius und das si7"}}},fp="6,244,21.490.0,14.127.0,33.178.0,28.171.0"}
P.entries["npc:lyria-du-lac"] = {n="Lyria Du Lac",s="Lyria Du Lac ist eine menschliche Kriegerlehrerin, die in Goldhain im Wald von Elwynn stationiert ist. Versteckt direkt hinter der Schmiede des Dorfes drillt sie kampfunerfahrene Rekruten und weist junge Krieger an, während sie beginnen, ihre Haltungen und den Umgang mit ihren Waffen zu meistern.",h="Lyria Du Lac ist eine menschliche Kriegerlehrerin, die in Goldhain im Wald von Elwynn stationiert ist.",kw={"die ausbildung eines kriegers","schmied","wald von elwynn","goldhain","lyria du lac","kriegerlehrer"},ang={["class:Warrior"]="Für Krieger, die frisch aus der Abtei von Nordhain kommen, ist Lyria Du Lac die erste wichtige Lehrmeisterin, der Ihr im Wald von Elwynn begegnet, und sie hilft Euch dabei, die Beherrschung Eurer Haltungen und Eure Nahkampftaktiken zu schärfen.",["faction:Alliance"]="Hinter der Schmiede in Goldhain positioniert, stellt Lyria sicher, dass lokale Rekruten in der Lage sind, das Kernland von Sturmwind gegen Defias-Banditen und Gnoll-Plünderer zu verteidigen."},sec={{t="Kriegerlehrerin von Goldhain",b="Während das Gasthaus \"Zur Höhle des Löwen\" in Goldhain vor Reisenden nur so wimmelt und der Schmied fleißig an lokalen Handelswaren hämmert, hält sich Lyria Du Lac auf dem Hof hinter der Schmiede auf. Erfahren in militärischer Disziplin dient sie der Allianz, indem sie frisch aus der Abtei von Nordhain kommende, unerfahrene Krieger ausbildet. Sie bewertet deren Bereitschaft und führt sie in spezialisierte Kampftechniken ein, um sicherzustellen, dass diejenigen, die für Sturmwind zu Schild und Klinge greifen, sich gegen die drohenden Gefahren im Wald von Elwynn behaupten können."}},faq={{q="Wo kann ich Lyria Du Lac finden?",a="Lyria Du Lac steht draußen direkt hinter der Schmiede in Goldhain, gleich westlich des Gasthaus \"Zur Höhle des Löwen\" im Wald von Elwynn.",al={"lyria du lac standort","wo ist lyria","kriegerlehrer goldhain"}},{q="Welchen Dienst bietet Lyria Du Lac an?",a="Sie ist eine Kriegerlehrerin. Sie bringt unerfahrenen Kriegern grundlegende Kampfmanöver, die Grundlagen der Kampfhaltungen und Kampfdisziplinen bei, während diese ihre Fähigkeiten verbessern.",al={"was macht lyria","lyria du lac rolle","was bringt lyria bei"}},{q="Welche Quests beinhalten Lyria Du Lac?",a="Lyria gibt aufstrebenden Kriegern die Quest 'Die Ausbildung eines Kriegers' und schickt sie zu dem Veteranen Harry Burlguard in die Gaststätte Pig and Whistle in der Altstadt von Sturmwind.",al={"lyria du lac quests","kriegerquest goldhain"}}},fx={f698c0e4={q="Wer ist Lyria Du Lac?",a="Lyria Du Lac ist eine erfahrene menschliche Kriegerin, die im Wald von Elwynn als Kampfausbilderin dient. Sie ist hinter der Schmiede in Goldhain stationiert, wo sie angehende Kämpfer auf ihrem Weg in das Königreich begutachtet und unterweist. Dabei bringt sie ihnen bei, ihr kriegerisches Können zu nutzen und die Bedrohungen zu überleben, die an die Grenzen von Sturmwind drängen.",al={"wer ist lyria","lyria du lac lore","wer ist lyria du lac"}},["34434421"]={q="Auf wessen Seite steht Lyria Du Lac?",a="Lyria steht fest an der Seite des Königreichs Sturmwind und der Allianz. Indem sie frische Rekruten darauf vorbereitet, den Wald von Elwynn vor lokalen Gefahren wie Banditen und Gnollen zu verteidigen, hilft sie dabei, die militärische Bereitschaft des Königreichs zu stärken, während die regulären Garnisonstruppen überlastet sind.",al={"fraktion von lyria du lac","loyalität von lyria du lac","wem dient lyria"}},afd6a9c2={q="Warum ist Lyria Du Lac hier in Goldhain?",a="Goldhain ist der natürliche Sammelpunkt für Reisende, die das Nordhaintal verlassen, was es zum idealen Posten macht, um vielversprechende Abenteurer im Umgang mit Waffen zu schulen. Direkt hinter dem Schmied stationiert, stellt Lyria sicher, dass jeder junge Krieger, der in der Stadt ankommt, ordentlich konditioniert und diszipliniert ist, bevor er sich größeren Gefahren stellt.",al={"warum ist lyria in goldhain","zweck des standorts von lyria du lac","was brachte lyria hierher"}},["277e5774"]={q="Was will Lyria Du Lac?",a="Lyria sucht fähige Schüler, die bereit sind, die Kunst des Kampfes zu meistern. Sie möchte sehen, wie junge Krieger ihre Disziplin schärfen, die Kampfhaltungen und -techniken beherrschen und ihr Training nutzen, um das Reich vor jeglichem Chaos zu verteidigen, das seinen Frieden bedroht.",al={"was will lyria","ziel von lyria du lac","beweggrund von lyria du lac"}}},fp="12,231,28.500.0,30.129.0,39.154.0,33.164.0"}
P.entries["npc:ma-stonefield"] = {n="Mutter Steinfeld",s="Mutter Steinfeld ist eine menschliche Matriarchin, die auf dem Hof der Steinfelds im westlichen Wald von Elwynn lebt. Direkt vor dem Gehöft der Familie steht sie an der Seite von Tantchen Bernice und meistert die alltäglichen Härten des ländlichen Farmlebens inmitten von Nachbarschaftsfehden und Plagen.",h="Mutter Steinfeld ist eine menschliche Matriarchin, die auf dem Hof der Steinfelds im westlichen Wald von...",kw={"bernice stonefield","wald von elwynn","mutter steinfeld","prinzessin","prinzessin muss sterben","hof der steinfelds"},ang={["faction:Alliance"]="Für Abenteurer der Allianz, die den Wald von Elwynn erkunden, trägt die Hilfe für fleißige Siedler wie Mutter Steinfeld dazu bei, Sturmwinds landwirtschaftliches Rückgrat zu bewahren."},sec={{t="Probleme auf dem Gehöft",b="Neben ihrem Familienhäuschen im südwestlichen Wald von Elwynn wacht Mutter Steinfeld an der Seite von Tantchen Bernice Steinfeld über das Gehöft. Das Leben zwischen dem benachbarten Maclure-Hof und den nahegelegenen Kürbisfeldern ist selten friedlich. Einheimische Wildschweine bedrohen fortwährend die Ernte der Familie, und keines stellt ein größeres Ärgernis dar als Prinzessin, eine riesige Preissau, die berüchtigt dafür ist, Felder zu zertrampeln und die mühsam erarbeitete Ernte zu verschlingen."}},faq={{q="Wer ist Mutter Steinfeld?",a="Mutter Steinfeld ist eine der Ältesten der Familie Steinfeld und lebt auf deren Gehöft im südwestlichen Wald von Elwynn an der Seite von Verwandten wie Tantchen Bernice.",al={"wer ist mutter stonefield","mutter steinfeld","stonefield mutter"}},{q="Wo kann ich Mutter Steinfeld finden?",a="Sie steht im Freien direkt vor dem Haupthaus auf dem Hof der Steinfelds, westlich von Goldhain im Wald von Elwynn.",al={"mutter stonefield standort","wo ist mutter stonefield","hof der stonefields standort"}},{q="Welches Problem muss Mutter Steinfeld gelöst haben?",a="Mutter Steinfeld sucht Abenteurer, die Prinzessin ein Ende bereiten – einem riesigen Preisschwein, das wiederholt durch die umliegenden Felder tobt und die Ernte verschlingt.",al={"mutter stonefield quest","prinzessin sau quest","questgeber prinzessin muss sterben"}}},fx={["51af3003"]={q="Auf wessen Seite steht Mutter Steinfeld?",a="Mutter Steinfeld ist eine loyale Untertanin des Königreichs Sturmwind und Mitglied der Allianz. Wie die meisten Landleute, die im Herzen des Walds von Elwynn leben, konzentriert sie sich ganz auf den Hof ihrer Familie, wenngleich sie sich auf Abenteurer der Allianz verlässt, um einzugreifen, wenn örtliche Probleme für einfache Farmer zu groß werden.",al={"ist mutter steinfeld allianz","fraktion von mutter steinfeld"}},["02537c40"]={q="Warum ist Mutter Steinfeld hier?",a="Der Hof der Steinfelds ist das lebenslange Zuhause von Mutter Steinfeld. Sie lebt und bewirtschaftet das Land im Wald von Elwynn an der Seite ihrer Verwandten und kümmert sich um die täglichen Aufgaben des Landlebens direkt vor dem Gehöft der Familie nahe bei Tantchen Bernice Steinfeld.",al={"warum ist mutter steinfeld auf dem hof","was macht mutter steinfeld hier"}},ae4d5db0={q="Mit wem ist Mutter Steinfeld verbunden?",a="Mutter Steinfeld ist eine Matriarchin des Steinfeld-Clans und lebt zusammen mit Verwandten wie Tantchen Bernice Steinfeld auf ihrem Gehöft im Wald von Elwynn. Ihre Familie hat langjährige Wurzeln im Tal, obwohl sie auch eine bittere, andauernde Fehde mit ihren Nachbarn, den Maclures, verbindet.",al={"familie von mutter steinfeld","mit wem ist mutter steinfeld verwandt"}}},fp="13,264,18.438.0,21.166.0,31.138.0,44.163.0"}
P.entries["npc:mad-magus-tirth"] = {n="Magus Tirth",s="Magus Tirth ist ein exzentrischer menschlicher Zauberer, der auf den Salzebenen der Illusionenrennbahn in Tausend Nadeln haust. Lokal bekannt für das Züchten von Hühnern und das Quälen seines verwandelten Lehrlings, ist er zugleich ein Gelehrter von beachtlichem arkanem Wissen, der wertvolle Wälzer bei Rennwetten durchgebracht hat.",h="Magus Tirth ist ein exzentrischer menschlicher Zauberer, der auf den Salzebenen der Illusionenrennbahn in...",kw={"ancona chicken","magus tirth","illusionenrennbahn","plucky","plucky johnson","rituale der macht","die schimmernde ebene","tausend nadeln","tirth"},ang={["class:Mage"]="Tirth ist eine wichtige Gestalt für Magier, die ihr Verständnis arkaner Macht vertiefen wollen, da er die bedeutende Abhandlung 'Rituale der Macht' verfasst hat."},sec={{t="Ein Zauberer im Staub",b="Während die meisten Magier seines Kalibers in den Bibliotheken von Dalaran oder Sturmwind studieren, hat sich Magus Tirth inmitten des Schmiers und Dröhnens der Schimmernden Ebene niedergelassen. Umgeben von heranrasenden Raketenwagen preist Tirth Passanten Hühner an und verbringt seine Tage damit, 'Plucky' Johnson Befehle zuzubrüllen – seinem unglücklichen ehemaligen Lehrling, den er in Hühnergestalt gefangen hält. Trotz dieses exzentrischen Auftretens verfügt Tirth über echte arkane Meisterschaft, da er esoterische Schriften über magische Macht verfasste, bevor er sie bei leichtsinnigen Wetten auf der Rennstrecke verlor."},{t="Rituale und Schulden",b="Zu Tirths wissenschaftlichem Erbe gehört 'Rituale der Macht', ein arkanes Handbuch, das von praktizierenden Magiern begehrt wird. Zum Unglück für aufstrebende Zauberwirker besitzt Tirth sein eigenes Meisterwerk nicht mehr. Erdrückt von Spielschulden, die er auf der Illusionenrennbahn anhäufte, verkaufte der Magier den Wälzer an einen Agenten des Scharlachroten Kreuzzugs, um seine Verluste auszugleichen, was Lehrlinge und Wissenssuchende dazu zwingt, das Buch in feindlichem Gebiet aufzuspüren."}},faq={{q="Warum befindet sich Magus Tirth in der Wüste?",a="Tirth lebt auf der Schimmernden Ebene neben der Illusionenrennbahn, angezogen vom Spektakel und dem Glücksspiel. Anstatt dem akademischen Leben in einer Großstadt nachzugehen, beobachtet er die Gnom- und Goblin-Rennfahrer, verkauft Hühner und frönt seinen Lastern.",al={"warum ist tirth hier","magus tirth die schimmernde ebene","tirth aufenthaltsort"}},{q="Wer ist das Huhn neben ihm?",a="Das Huhn ist 'Plucky' Johnson, Magus Tirths ehemaliger Lehrling. Tirth verwandelte Johnson magisch in ein Huhn und verbringt einen Großteil seiner Zeit damit, ihn zu quälen und ihm zu befehlen, draußen auf den Salzebenen zu tanzen.",al={"wer ist plucky","plucky johnson","tirth huhn lehrling"}},{q="Was ist das Buch Rituale der Macht?",a="Rituale der Macht ist eine fortgeschrittene Abhandlung über arkane Energie aus der Feder von Magus Tirth. Es ist ein unverzichtbarer Text für Magier, die ihr Handwerk verfeinern wollen, wenngleich sich Tirth von ihm trennte, um seine wachsenden Wettschulden zu begleichen.",al={"rituale der macht","tirth buch","magier quest buch"}},{q="Warum ist sein Buch schwer zu beschaffen?",a="Tirth besitzt sein Exemplar von Rituale der Macht nicht mehr. Magier, die danach suchen, müssen seinem Bericht darüber nachgehen, wie er sich von dem Wälzer trennte.",al={"wer hat rituale der macht","tirth schulden","scharlachroter kreuzzug buch"}}},fx={cfb6b161={q="Wer ist Magus Tirth?",a="Magus Tirth ist ein exzentrischer menschlicher Zauberwirker, der auf der Illusionenrennbahn in der schimmernden Ebene lebt. Obwohl er offensichtlich über Kenntnisse esoterischer arkaner Lehren verfügt – er hat ein bemerkenswertes magisches Buch namens Rituale der Macht verfasst –, verbringt er seine Tage nun damit, Anconahühner zu verkaufen und die polymorphierte Kreatur an seiner Seite zu quälen.",al={"wer ist mad magus tirth","wer ist tirth","geschichte von magus tirth"}},f085518f={q="Auf wessen Seite steht Magus Tirth?",a="Magus Tirth bleibt strikt neutral. Er verdient seinen Lebensunterhalt auf den Salzebenen der schimmernden Ebene an der Seite von Goblin- und Gnom-Ingenieuren und bietet Reisenden der Allianz wie auch der Horde bereitwillig seine Waren und magischen Ratschläge an, ohne an ihrem größeren Krieg teilzunehmen.",al={"ist magus tirth allianz oder horde","fraktion von tirth","ist magus tirth neutral"}},["77039c48"]={q="Was will Magus Tirth?",a="Abgesehen davon, dass er von Rennzuschauern durch den Verkauf von Anconahühnern Münzen zusammenkratzt, amüsiert sich Tirth hauptsächlich damit, das verzauberte Huhn an seiner Seite, Plucky, zu quälen. Einst suchte er nach schnellem Geld, um seine hohen Spielschulden zu begleichen, was ihn dazu veranlasste, seine eigene wissenschaftliche Forschungsarbeit zu verkaufen.",al={"was will tirth","motive von magus tirth","warum verkauft tirth hühner"}}},fp="11,290,20.541.0,17.418.1,37.236.0,31.207.0,34.214.0,36.128.0"}
P.entries["npc:madame-eva"] = {n="Madame Eva",s="Madame Eva ist eine verehrte Wahrsagerin und Matriarchin, die in Dunkelhain im schattigen Wald des Dämmerwalds lebt. Sie praktiziert ältere, mystische Künste der Weissagung und des Kartenlegens und spürt oft als erste Bewohnerin der Stadt unnatürliche Erschütterungen im gesamten Wald auf. Reisende suchen sie häufig auf, um düstere Geheimnisse zu lüften oder okkulte Amulette gegen die heraufziehende Finsternis zu beschaffen.",h="Madame Eva ist eine verehrte Wahrsagerin und Matriarchin, die in Dunkelhain im schattigen Wald des...",kw={"alyssa eva","kartenlegen","dunkelhain","dämmerwald","wahrsagerin","geisterhaarfaden","madame eva","stalvan"},ang={["class:Priest"]="Während das Heilige Licht den Lebenden Trost spendet, werden Priester Evas Vertrauen auf Kartenlegen und Geisterreste als ein kurioses, bodenständiges Gegenstück zur traditionellen Kirchenliturgie empfinden.",["faction:Alliance"]="Für die Streiter der Allianz, die in den erdrückenden Schatten des Dämmerwalds treten, ist Madame Eva eine unverzichtbare Führerin, deren Vorahnungen die tödliche Verwirrung des Waldes durchdringen.",["profession:Tailoring"]="Schneider werden Evas Kenntnisse über bizarre Webmaterialien zu schätzen wissen, insbesondere ihre Fähigkeit, Geisterfäden zu verarbeiten, die direkt von den Geistern der Region gepflückt wurden."},sec={{t="Die Wahrsagerin von Dunkelhain",b="Madame Eva lebt zurückgezogen in der Düsternis von Dunkelhain und praktiziert Kartenlegen sowie alte Volksrituale, die viele in Sturmwinds Kathedrale mit Argwohn betrachten würden. In einer verlassenen Region, die von wilden Bestien, den Untoten und noch dunkleren Schrecken heimgesucht wird, werden ihre unheimlichen Einsichten von verzweifelten Bürgern und reisenden Abenteurern gleichermaßen geduldet und geschätzt."},{t="Bande des Blutes und der Prophezeiung",b="Über ihre Rolle als okkulte Seherin hinaus widmet sich Madame Eva voll und ganz ihrer Familie und kümmert sich als Großmutter um Alyssa Eva und den jungen Lohgan. Als ihr Kartenlegen dunkle Omen enthüllt, die ihre Enkelin bedrohen, zögert Eva nicht, die Hilfe durchreisender Wanderer in Anspruch zu nehmen, um die Wälder zu durchkämmen und längst vergrabene Tragödien aufzudecken, bevor sich die Geschichte wiederholen kann."},{t="Schutzgewebe gegen die Nacht",b="Evas Wissen reicht über das Kartenlegen hinaus bis hin zur rituellen Handwerkskunst und Schutzmagie. Vom Weben übernatürlicher Gewänder aus Geisterfäden bis hin zum Erschaffen bizarrer Volksrelikte wie dem Totem des Gegenschlages versteht sie die seltsame, dämmerige Logik, die die rastlosen Geister des Dämmerwalds beherrscht, besser als fast jeder andere im Ort."}},faq={{q="Wer ist Madame Eva?",a="Madame Eva ist eine ältere menschliche Wahrsagerin und Hellseherin, die in Dunkelhain lebt. Sie praktiziert Kartenlegen und alte Volksbräuche, um die unsichtbaren Gefahren zu erblicken, die im Dämmerwald lauern.",al={"madame eva","wer ist eva","wahrsagerin von dunkelhain"}},{q="Welche Rolle spielt Madame Eva im Geheimnis um Stalvan?",a="Madame Eva legt die Karten und spürt eine drohende, übernatürliche Gefahr, die ihre Enkelin Alyssa umgibt. Ihre Lesungen weisen Abenteurern den Weg, vergessene Dokumente und Spuren zu untersuchen, die die düstere Geschichte von Stalvan Dunstmantel ans Licht bringen.",al={"eva stalvan","legende von stalvan eva","warum kümmert sich eva um stalvan"}},{q="Ist Madame Eva eine Hexe oder eine Magierin?",a="Eva ist in erster Linie eine Seherin und Anwenderin älterer mystischer Künste wie Kartenlegen, das Weben von Geisterfäden und das Herstellen traditioneller Abbilder. Ihre Magie ähnelt eher dem traditionellen Wahrsagen und okkultem Wissen als dem strukturierten Arkanum von Dalaran oder dem Heiligen Licht.",al={"ist eva eine hexe","eva magieart","welche magie wirkt eva"}},{q="Wer ist in Dunkelhain mit Madame Eva verwandt?",a="Sie ist die Großmutter von Alyssa Eva und Lohgan Eva. Zur Nachtwache der Stadt gehört auch Wächterin Eva, von der man annimmt, dass sie Verbindungen zu ihrer Familie hat.",al={"eva familie","madame eva enkel","alyssa eva großmutter"}},{q="Wofür wird Geisterhaarfaden verwendet?",a="Madame Eva sammelt ätherische Stränge von Geisterhaarfaden von ruhelosen Geistern, um speziell vorbereitete Ritualgewänder zu weben und Nachschub bereitzustellen, den Verbündete im ganzen Reich benötigen.",al={"geisterhaarfaden","eva faden quest"}},{q="Warum stellt Madame Eva das Totem des Gegenschlages her?",a="Madame Eva fertigt das Totem des Gegenschlages als dunkles, sympathisches Bildnis an. Indem man ihm bestimmte Teile von Kreaturen beifügt, lenkt das Totem Flüche und Schaden auf die finsteren Bestien zurück, die den Wald terrorisieren.",al={"totem des gegenschlages","eva totem"}}},fx={b3bc0c21={q="Auf wessen Seite steht Madame Eva?",a="Madame Eva steht fest auf der Seite der Bewohner von Dunkelhain und der Allianz. Obwohl sie sich mit Kartenlegen und den obskuren ‚alten Künsten‘ befasst, bleiben ihre Loyalitäten bei ihren bedrängten Nachbarn und ihrer Familie; sie nutzt ihre Weissagungen und Rituale, um die Stadt vor den dunklen Gefahren zu schützen, die durch den Dämmerwald kriechen.",al={"loyalität von madame eva","wem dient eva","ist madame eva allianz"}},d6f73346={q="Was will Madame Eva?",a="Madame Eva versucht, ihre Gemeinschaft und Verwandten vor den dunklen Mächten zu schützen, die im Dämmerwald umgehen. Mithilfe ihrer Kartenlegetechnik sieht sie verborgene Bedrohungen voraus – etwa das lauernde Unheil, das das Geheimnis um Stalvan Dunstmantel umgibt – und weist Reisende an, rituelle Reagenzien zu sammeln, um das Böse abzuwehren und ihre Familie zu beschützen.",al={"was versucht eva zu tun","ziele von eva","warum braucht madame eva hilfe"}},["6bf59259"]={q="Warum ist Madame Eva hier in Dunkelhain?",a="Dunkelhain ist das angestammte Zuhause von Madame Eva. Sie lebt in ihrem Häuschen als Matriarchin für ihre Enkelkinder Alyssa und Lohgan Eva und bietet den verängstigten Leuten, die versuchen, das Leben inmitten der schattenhaften Wälder zu ertragen, Führung, Wahrsagerei und mystischen Beistand.",al={"warum lebt eva im dämmerwald","warum ist madame eva in dunkelhain","zuhause von madame eva"}}},fp="10,372,31.351.0,26.353.0,36.319.0,18.177.0,52.237.0,32.252.0,42.149.0,35.178.0,50.201.0"}
P.entries["npc:magatha-grimtotem"] = {n="Magatha Grimmtotem",s="Magatha Grimmtotem ist die Matriarchin des Stammes der Grimmtotem und die Ältestengreisin von Donnerfels. Als furchterregende Schamanin und politische Ränkeschmiedin residiert sie auf der Anhöhe der Ältesten, während sie Cairne Bluthufs Vision für das Volk der Tauren unablässig herausfordert.",h="Magatha Grimmtotem ist die Matriarchin des Stammes der Grimmtotem und die Ältestengreisin von Donnerfels.",kw={"arikara","bloodhoof","cairne","die ältestengreisin","die anhöhe der ältesten","grimmtotem","magatha","ragefire","donnerfels","zamah"},ang={["class:Shaman"]="Magatha ist unbestreitbar eine der mächtigsten Schamaninnen auf Kalimdor und befehligt die Urgewalten der Elemente mit einer Autorität, die nur wenige lebende Tauren erreichen können.",["faction:Horde"]="Obwohl Magatha wertvolle Hilfe und Ratschläge gegen regionale Bedrohungen bietet, machen ihre erbitterte Loyalität zu ihrem Clan und ihre offene Verachtung für andere Völker sie zu einer unzuverlässigen Gefährtin.",["race:Tauren"]="Jeder Taure kennt den finsteren Ruf der Grimmtotem, wodurch Magathas Anwesenheit auf der Anhöhe der Ältesten eine beunruhigende Erinnerung an die ideologische Kluft darstellt, die ihre vereinten Stämme bedroht.",["race:Undead"]="Reisende der Verlassenen werden von der Ältestengreisin überraschend herzlich empfangen, die sich regelmäßig mit der Königlichen Apothekervereinigung in den Teichen der Visionen berät."},sec={{t="Die Matriarchin der Anhöhe der Ältesten",b="Magatha erlangte die absolute Herrschaft über die Grimmtotem durch eine arrangierte Verbindung, auf die der plötzliche, tödliche Kletterunfall ihres Gefährten folgte. Von der Anhöhe der Ältesten aus agiert sie mit ihrem persönlichen Gefolge und Leibwächtern als unangefochtene politische und spirituelle Anführerin ihres zurückgezogenen Stammes. Im Gegensatz zu Cairne Bluthuf predigt Magatha die Vorherrschaft der Tauren und betrachtet andere sterbliche Völker als Eindringlinge auf Kalimdor, die vernichtet oder beiseitegefegt werden sollten."},{t="Ein sonderbares Bündnis",b="Trotz ihrer offenen Verachtung für Nicht-Tauren gehörte Magatha zu den frühesten Fürsprechern für die Aufnahme der Verlassenen in die Horde. Sie behauptet, die Tauren könnten den Untoten spirituelles Gleichgewicht lehren und sie dabei anleiten, ihre Menschlichkeit wiederzuerlangen. In der Praxis arbeitet Magatha jedoch direkt mit der Königlichen Apothekervereinigung unter Donnerfels zusammen und berät sich mit Persönlichkeiten wie Apothekerin Zamah über angewandte Alchemie und das Studium arkaner Relikte."},{t="Politische Machenschaften",b="Hinter einer Fassade weisen Rats arbeitet Magatha aktiv daran, Cairnes Autorität zu schwächen, während sie die Verteidigung potenzieller Bedrohungen auf die Probe stellt. Sie entsendet Abenteurer in große Gefahren – von der Erkundung der Trogg-Streitkräfte im Flammenschlund bis hin zur Jagd auf den rachsüchtigen Geist Arikara. Jede von ihr gestellte Aufgabe dient entweder dazu, den Einfluss der Grimmtotem zu festigen, oder bereitet den Tag vor, an dem sie die Bluthuf-Dynastie vollständig verdrängen kann."}},faq={{q="Wer ist Magatha Grimmtotem?",a="Magatha ist die Ältestengreisin und Matriarchin des Stammes der Grimmtotem. Seit ihrer Kindheit eine begabte Schamanin, übernahm sie die uneingeschränkte Herrschaft über ihren Clan, nachdem ihr Gefährte bei einem Kletterunfall ums Leben kam. Sie residiert auf der Anhöhe der Ältesten in Donnerfels, wo sie als Cairne Bluthufs größte politische Rivalin fungiert.",al={"magatha hintergrundgeschichte","wer ist die ältestengreisin","ältestengreisin donnerfels"}},{q="Warum unterstützt Magatha die Verlassenen?",a="Vordergründig glaubt Magatha, dass die Traditionen der Tauren und schamanisches Verständnis die Verlassenen zurück zur Menschlichkeit führen können. Viele vermuten jedoch, dass ihre Freundschaft mit der Königlichen Apothekervereinigung vom Wunsch nach esoterischen alchemistischen Geheimnissen und politischen Verbündeten außerhalb von Cairnes loyalem engsten Kreis angetrieben wird.",al={"magatha und untote","warum magatha verlassene mag","magatha apothekerin zamah"}},{q="Wie ist Magathas Beziehung zu Cairne Bluthuf?",a="Magatha hält Cairne für weich, naiv und unfähig, die vereinten Tauren anzuführen. Während Cairne für die Koexistenz innerhalb der Horde und Frieden auf ganz Kalimdor eintritt, glaubt Magatha, dass die Grimmtotem das Land ihrer Ahnen mit Gewalt zurückfordern und fremde Eindringlinge beseitigen sollten.",al={"magatha gegen cairne","hasst magatha cairne","cairne und magatha"}},{q="Was war der Auftrag im Flammenschlund?",a="Magatha schickte einen Abgesandten namens Maur in den Flammenschlund unter Orgrimmar, um mit den dort ansässigen Troggs zu verhandeln. Stattdessen töteten die Troggs Maur, was Magatha dazu veranlasste, Abenteurer der Horde in die Höhle zu schicken, um Maurs Ranzen zu bergen und die Troggs zur Vergeltung abzuschlachten.",al={"magatha ragefire quest","warum schickte magatha maur","verlorener ranzen magatha"}},{q="Wer ist Arikara?",a="Arikara ist der Geist einer rachsüchtigen Windnatter, von dem es heißt, er suche Vergeltung am Volk der Tauren. Magatha behauptet, Arikara trachte direkt nach Rache an Cairne Bluthuf, und beauftragt fähige Recken damit, das Biest mithilfe verzauberter Agaven zu beschwören und zu erschlagen.",al={"schlange der vergeltung","arikara quest","magatha arikara"}},{q="Wo ist Magatha Grimmtotem zu finden?",a="Magatha residiert im großen Hauptzelt auf der Anhöhe der Ältesten in Donnerfels, begleitet von ihrem Diener Rahauro und zwei stoischen Grimmtotem-Wachen.",al={"magatha aufenthaltsort","wo ist magatha","magatha anhöhe der ältesten"}}},fx={ebac2d3c={q="Auf wessen Seite steht Magatha Grimmtotem?",a="Magatha dient vor allem sich selbst und dem Grimmtotem-Stamm. Während sie einen ehrenvollen Sitz auf der Anhöhe der Ältesten in Donnerfels innehat und offiziell zur Horde gehört, ist ihre Loyalität rein geschäftsmäßig. Sie fordert offen die Vision von Hochhäuptling Cairne Bluthuf für ihr Volk heraus, bevorzugt rücksichtslose Vorherrschaft der Tauren gegenüber Frieden und verfolgt private Bündnisse – vor allem mit den Verlassenen –, um den Einfluss ihrer eigenen Fraktion auszubauen.",al={"loyalitäten von magatha","wem dient magatha","ist magatha der horde gegenüber loyal"}},b26ae613={q="Was will Magatha Grimmtotem?",a="Magatha glaubt, dass nur sie dazu geeignet ist, die Tauren anzuführen. Sie versucht, Cairne Bluthuf die Autorität zu entziehen, alle niederen Rassen aus Kalimdor zu vertreiben und die angestammten Gebiete ihres Volkes zurückzufordern. Um die Macht zu sammeln, die sie dafür benötigt, sammelt sie ständig uralte Relikte, testet potenzielle Feinde und pflegt kontroverse Beziehungen, die Cairne und die anderen Ältesten niemals billigen würden.",al={"ziele von magatha","was plant magatha","motivationen von magatha"}},["0cc6173c"]={q="Warum ist Magatha Grimmtotem hier?",a="Als The Elder Crone und Matriarchin der Grimmtotem residiert Magatha auf der Anhöhe der Ältesten, um ihren grimmigen Stamm innerhalb der vereinten Taurennation zu vertreten. Von diesem erhabenen Standpunkt aus berät sie Reisende, gibt der Stadt Rat und behält die Herrschaft von Cairne Bluthuf im Auge, um sicherzustellen, dass ihr Clan eine mächtige Stimme in der Regierung von Donnerfels behält.",al={"warum ist magatha in donnerfels","warum ist magatha hier"}},["4e6ef5c4"]={q="Mit wem ist Magatha Grimmtotem verbunden?",a="Magatha befehligt die grimmigen Krieger des Grimmtotem-Stamms, die ständig von ihren persönlichen Wachen und Dienern flankiert werden. Außerhalb ihres Clans unterhält sie eine ungewöhnlich enge, aktive Partnerschaft mit den Verlassenen – sie arbeitet an der Seite von Figuren der Königlichen Apothekervereinigung wie Apothecary Zamah – und unterhält private Verbindungen zu Sehern und Agenten in ganz Kalimdor, die außerhalb von Cairnes engem Kreis operieren.",al={"verbündete von magatha","mit wem verkehrt magatha","verbindungen von magatha"}},["92d0808b"]={q="Warum ist Magatha Grimmtotem berühmt oder gefürchtet?",a="Magatha war von Kindheit an mit immensem schamanischen Talent gesegnet und hat ein Leben lang damit verbracht, diese Macht in absolute Autorität über die Grimmtotem umzusetzen. Viele in Donnerfels fürchten ihre rücksichtslose Ambition und tuscheln, dass sie ihre eigene Heirat arrangiert habe, um die Führung ihres Clans zu gewinnen. Ihre Bereitschaft, dunkle Heilmittel einzusetzen, sich mit rachsüchtigen Geistern einzulassen und sich Cairne zu widersetzen, macht sie zu einer der einschüchterndsten Figuren in Mulgore.",al={"warum wird magatha gefürchtet","ist magatha mächtig","ruf von magatha"}}},fp="17,243,27.449.0,18.431.0,22.412.1,25.284.0,38.301.0,53.256.0,39.270.0,15.251.0,37.140.0"}
P.entries["npc:magga"] = {n="Magga",s="Magga ist eine Orc-Bewohnerin, die in der staubigen Siedlung Klingenhügel in Durotar lebt. Sie hält sich in der Nähe des belebten Gasthauses der Stadt auf und ist ein freundliches Gesicht für frisch angekommene Abenteurer der Horde, die gerade das Tal der Prüfungen verlassen haben.",h="Magga ist eine Orc-Bewohnerin, die in der staubigen Siedlung Klingenhügel in Durotar lebt.",kw={"durotar","horde","gastwirt grosk","magga","orc","klingenhügel","willkommen"},ang={["faction:Horde"]="Für frische Rekruten, die die harten Prüfungen des Tals der Prüfungen hinter sich gelassen haben, bietet Magga einen beruhigenden Empfang in der ersten richtigen Siedlung in Durotar."},sec={{t="Ein freundliches Gesicht in Klingenhügel",b="Klingenhügel ist für junge Orcs und Darkspear, die aus dem Tal der Prüfungen kommen, der erste echte Vorgeschmack auf die Welt da draußen. Magga hat ihren Platz direkt neben dem örtlichen Gasthaus und begrüßt Neuankömmlinge im Außenposten. Obwohl sie sich unter den geschäftigen Soldaten und Handwerkern des Außenpostens eher im Hintergrund hält, trägt sie dazu bei, die kleine Siedlung zusammenzuhalten."}},faq={{q="Wer ist Magga?",a="Magga ist eine zivile Orc, die in Klingenhügel in Durotar stationiert ist. Sie steht in der Nähe des Gasthauses, heißt neue Reisende der Horde willkommen und weist ihnen den Weg zu Unterkunft und Rast.",al={"magga durotar","magga klingenhügel","wer ist magga"}},{q="Welche Verbindung hat Magga zu Gastwirt Grosk?",a="Es ist keine besondere Verbindung zwischen ihnen verzeichnet. Magga hält sich in der Nähe des Gasthauses von Klingenhügel auf, wo Gastwirt Grosk Reisenden Speis, Trank und einen Ort bietet, an den sie ihren Ruhestein binden können.",al={"magga und grosk","magga gastwirt"}},{q="Bietet Magga Quests an?",a="Magga ist für die Besorgung 'Willkommen!' zuständig: Abenteurer, die einen Gutschein für Klingenhügel bei sich tragen, überreichen ihn ihr, woraufhin sie sie mit einem kleinen Begleiter als Geschenk in Azeroth willkommen heißt.",al={"magga quests","willkommensquest"}}},fx={["65fbd604"]={q="Auf wessen Seite steht Magga?",a="Magga ist ein loyales Mitglied der Horde und lebt an der Seite ihrer orcischen Mitstreiter in der Siedlung Klingenhügel. Sie heißt Reisende willkommen, die durch das Wegekreuz kommen, und unterstützt stolz das Volk und die Verteidigung von Durotar unter Thralls Führung.",al={"fraktion von magga","ist magga horde","loyalität von magga"}}},fp="5,239,30.339.0,13.156.0,46.168.0,28.168.0"}
P.entries["npc:maggran-earthbinder"] = {n="Maggran Erdbinder",s="Maggran Erdbinder ist ein ergrauter Taurenveteran, der von Oberhäuptling Cairne Bluthuf ernannt wurde, um das Lager der Horde in Sonnenfels anzuführen. Abgehärtet durch ein Leben voller brutaler Konflikte überwacht er die Verteidigung der schroffen Täler des Steinkrallengebirges gegen unersättliche Bestien und aggressive Harpyienzirkel. Obwohl er von zahllosen Schlachten gezeichnet ist, bleibt er ein unerschütterlicher Wächter der Siedlung.",h="Maggran Erdbinder ist ein ergrauter Taurenveteran, der von Oberhäuptling Cairne Bluthuf ernannt wurde, um das...",kw={"besseleth","bloodfury","cairne bluthuf","earthbinder","harpyien","maggran","steinkrallengebirge","sonnenfels"},ang={["faction:Horde"]="Für Reisende, die die steilen Anstiege des Steinkrallengebirges durchqueren, ist Maggran die zentrale Autorität, die lokale Patrouillen der Horde koordiniert und Versorgungsrouten frei von Bestien und Harpyien hält.",["race:Tauren"]="Maggran verkörpert den schweren Tribut, den der Krieg vom Geist der Shu'halo fordert, und dient als Mahnung dafür, wie Konflikte selbst die bodenständigsten Kinder der Erdenmutter verhärten können."},sec={{t="Die Zuflucht eines Veteranen",b="Maggran Erdbinder wurde von Oberhäuptling Cairne Bluthuf persönlich in das Steinkrallengebirge entsandt. Als Veteran zahlloser Scharmützel und blutiger Feldzüge gibt Maggran zu, dass Alter und Gewalt sein Herz verhärtet und ihm die für sein Volk typische Sanftmut genommen haben. Sonnenfels sollte sowohl ein Außenposten unter seinem besonnenen Kommando als auch ein Ort der Erholung sein, an dem warme Winde und der Sonnenschein der Berge seinen kampfesmüden Geist besänftigen könnten."},{t="Gefahren in den Klippen",b="Selbst im Steinkrallengebirge findet Maggran wenig Ruhe. Als Aufseher von Sonnenfels koordiniert er die Verteidigungsbemühungen gegen die Bloodfury-Harpyien, die in den Gipfeln nisten, und stellt Krieger auf, um den Gefahren durch Raubtiere in den schroffen Felsen zu begegnen. Da er einst selbst einen Hinterhalt der riesigen Spinne Besseleth überlebte, gibt sich Maggran keinen Illusionen über die tödliche Wildnis um sie herum hin und rekrutiert regelmäßig Reisende, um gefährliche Raubtiere der Region zu beseitigen, bevor sie den Außenposten überrennen."}},faq={{q="Wer ist Maggran Erdbinder?",a="Maggran Erdbinder ist der befehligende Taurenältester in Sonnenfels im Steinkrallengebirge. Gehärtet durch unzählige Schlachten wurde er von Cairne Bluthuf hierher beordert, um über die Siedlung zu wachen und ihre Versorgungswege sowie Grenzen zu sichern.",al={"maggran","wer ist maggran","anführer von sonnenfels"}},{q="Warum wurde Maggran nach Sonnenfels geschickt?",a="Cairne Bluthuf ernannte ihn teils wegen seiner erfahrenen militärischen Führung und teils als Rückzugsort zum Leiter von Sonnenfels. Maggrans Körper und Geist wurden durch ein Leben voller Kämpfe schwer gezeichnet, und die ruhige Bergsonne schenkt ihm ein gewisses Maß an Genesung.",al={"warum ist maggran hier","maggran hintergrund","cairne und maggran"}},{q="Mit welchen Bedrohungen bittet Maggran Abenteurer fertigzuwerden?",a="Maggran leitet Verteidigungsmaßnahmen gegen die wilden Bloodfury-Harpyien, die die Berge heimsuchen, und entsendet Krieger, um die riesige Spinnenmatriarchin Besseleth zu eliminieren – ein furchterregendes Raubtier, dem er früher auf seinen Reisen nur knapp entkam.",al={"maggran quests","was will maggran","harpyien steinkrallengebirge"}},{q="Was geschah zwischen Maggran und Besseleth?",a="Maggran wurde einst von der kolossalen Spinne Besseleth gebissen. Obwohl es ihm gelang, sie abzuwehren und mit dem Leben davonzukommen, schickt er fähige Abenteurer aus, um die Bestie zu erschlagen, damit niemand sonst ihrem Netz zum Opfer fällt.",al={"maggran besseleth","spinnenquest maggran","arachnophobie hintergrund"}},{q="Hat Maggran eine Rolle in Donnerfels?",a="Maggran dient direkt auf Geheiß von Donnerfels' Oberhäuptling Cairne Bluthuf. Während er draußen im Feld in Sonnenfels stationiert ist, stammen seine Autorität und seine Befehle direkt aus der Hauptstadt.",al={"maggran donnerfels","maggran cairne"}},{q="Ist Maggran Erdbinder Spielern der Allianz freundlich gesinnt?",a="Nein. Maggran ist ein loyaler Anführer der Horde und verhält sich allen Allianz-Abenteurern gegenüber, die nach Sonnenfels stolpern, vollkommen feindselig.",al={"kann allianz mit maggran sprechen","maggran feindselig"}}},fp="19,387,17.455.0,20.472.0,27.247.0,41.256.0,55.228.0,44.210.0,42.201.0,52.133.0"}
P.entries["npc:magis-sparkmantle"] = {n="Magis Funkelmantel",s="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in der Brauerei Donnerbräu in Kharanos stationiert ist. Er bietet jungen Zauberwirkern Anleitung und Ausbildung, wenn sie sich aus dem Coldridgetal in das Herz von Dun Morogh wagen.",h="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in der Brauerei Donnerbräu in Kharanos stationiert ist.",kw={"dun morogh","gnomenmagier","kharanos","magierlehrer","magis","magis funkelmantel","sparkmantle","brauerei donnerbräu"},ang={["class:Mage"]="Für Magier der Allianz, die Dun Morogh durchqueren, ist Sparkmantle ein unverzichtbarer örtlicher Ansprechpartner für die Zauberausbildung und die Weitervermittlung an größere arkane Netzwerke.",["race:Gnome"]="Aus Gnomeregan vertriebene Gnome verlassen sich oft auf Mentoren wie Sparkmantle, um ihre gelehrten und arkanen Traditionen während des Lebens unter den Zwergen aufrechtzuerhalten."},sec={{t="Ein Zauberwirker in der Brauerei",b="Während sich die Zwerge in der Brauerei Donnerbräu für deftiges Bier versammeln, sorgt Magis Funkelmantel zwischen den Fässern und Fässchen von Kharanos für eine arkane Präsenz. Gnomische Magier leben überall in Dun Morogh oft eng mit ihren zwergischen Verbündeten zusammen, und Sparkmantle dient als wichtiger Mentor für angehende Zauberwirker, die bereit sind, ihr theoretisches und praktisches Verständnis der arkanen Künste zu erweitern."},{t="Wegweisung für junge Arkanisten",b="Neben der Unterweisung von Neulingen in grundlegenden Beschwörungsformeln sorgt Magis dafür, dass vielversprechende Schüler Anschluss an größere magische Zirkel finden. Sobald Magier der anfänglichen lokalen Ausbildung entwachsen sind oder spezialisierte Anleitung benötigen, weist Sparkmantle ihnen den weiteren Weg und schickt sie zu befreundeten Praktizierenden wie Bink oder zu Mentoren, die in den Hauptzentren der Allianz stationiert sind."}},faq={{q="Wer ist Magis Funkelmantel?",a="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in Kharanos in Dun Morogh weilt. Er unterweist angehende Zauberwirker in den arkanen Grundlagen.",al={"magis funkelmantel","wer ist magis","kharanos magierlehrer"}},{q="Wo ist Magis Funkelmantel zu finden?",a="Er befindet sich im Inneren der Brauerei Donnerbräu, dem Hauptgasthaus und Versammlungsort des Ortes Kharanos.",al={"magis aufenthaltsort","wo ist magis","sparkmantle finden"}},{q="Warum hält sich ein Gnom-Magierlehrer in einer Zwergenbrauerei auf?",a="Nach dem Fall von Gnomeregan ließen sich viele Gnome bei ihren zwergischen Vettern in Dun Morogh nieder. Die Brauerei Donnerbräu dient als zentraler Knotenpunkt von Kharanos und ist damit ein idealer Posten, um umherreisende Zauberwirker anzuleiten.",al={"warum in brauerei","gnom in brauerei","warum brauerei donnerbräu"}},{q="Bietet Magis Funkelmantel Quests an?",a="Magis weist heranwachsenden Magiern im Laufe ihres Fortschritts den Weg zu anderen arkanen Mentoren, unter anderem schickt er Praktizierende zum Gespräch mit Bink oder weist sie an, sich bei Ausbildern in den Gebieten der Menschen zu melden.",al={"sparkmantle quests","magis quests"}}},fx={["1189c3a2"]={q="Auf wessen Seite steht Magis Funkelmantel?",a="Magis Funkelmantel steht fest auf der Seite von Gnomeregan und der Großen Allianz. Wie viele Exilgnome, die vor der Katastrophe in ihrer Heimatstadt geflohen sind, lebt und arbeitet er an der Seite der Zwerge von Eisenschmiede und bietet den Verteidigern der Allianz sein arkanes Wissen an.",al={"fraktion von magis funkelmantel","ist magis allianz","wem dient funkelmantel"}},e3e37731={q="Was will Magis Funkelmantel?",a="Magis widmet sich der Ausbildung aufstrebender Magier in den arkanen Künsten. Während er in der Destillerie untergebracht ist, bereitet er unerfahrene Zauberwirker auf den vor ihnen liegenden Weg vor, unterweist sie in grundlegender Magie, bevor er sie an erfahrene Meister wie Jennea Haubitz in Sturmwind verweist.",al={"was will magis","ziele von magis funkelmantel","warum bildet magis magier aus"}},["318a77dd"]={q="Mit wem ist Magis Funkelmantel verbunden?",a="Als Teil des weiteren Netzwerks der Magier der Allianz unterhält Magis Verbindungen zu anderen Ausbildern im gesamten Reich, darunter Bink in den Zwergenlanden und Jennea Haubitz im Mage Quarter von Sturmwind, um sicherzustellen, dass vielversprechende Schüler fortgeschrittenen Unterricht finden.",al={"verbündete von magis funkelmantel","mit wem ist funkelmantel verbunden","verbindungen von funkelmantel"}}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="Magistrat Henry Maleb",s="Magistrat Henry Maleb beaufsichtigt die zivile Verwaltung in der Hafenstadt Süderstade, der wichtigsten Küstenbastion der Allianz im Vorgebirge des Hügellands. Mit der Aufgabe betraut, inmitten ständiger Bedrohungen die Ordnung aufrechtzuerhalten, richtet er einen Großteil seiner Autorität darauf, die Verschwörer des Syndikats zur Strecke zu bringen, die es auf die Führung der Stadt abgesehen haben.",h="Magistrat Henry Maleb beaufsichtigt die zivile Verwaltung in der Hafenstadt Süderstade, der wichtigsten...",kw={"alterac","attentäter","henry maleb","hillsbrad","magistrat maleb","süderstade","syndikat"},ang={["class:Rogue"]="Schurken werden feststellen, dass Maleb die Künste der Täuschung und des Meuchelmords mit großer Sorge betrachtet und auf scharfsinnige Agenten setzt, um die verborgenen Mörder des Syndikats auszumanövrieren.",["faction:Alliance"]="Für Recken der Allianz, die in Hillsbrad eintreffen, verkörpert Magistrat Maleb die rechtmäßige weltliche Autorität in einem gesetzlosen Grenzland und setzt Kopfgelder auf die Halsabschneider des Syndikats aus, welche die Stadt destabilisieren."},sec={{t="Hüter der Ordnung von Süderstade",b="Vom Rathaus in Süderstade aus leitet Magistrat Henry Maleb die zivile Verwaltung einer der letzten wahren Siedlungen der Allianz in Lordaeron. Die Stadt steht unter ständiger Bedrängnis durch die Verlassenen im Norden und Westen, während skrupellose Wegelagerer das Vorgebirge unsicher machen. Maleb trat sein derzeitiges Amt nach der rätselhaften Ermordung des vorherigen Magistrats an – eine Tat, die er direkt dem Syndikat zuschreibt. Entschlossen, nicht dasselbe Schicksal zu erleiden, koordiniert er aktive Ermittlungen, um verborgene Attentäter aufzuspüren, die Versorgungsnetzwerke des Syndikats zu zerschlagen und die abtrünnigen Adligen zu entlarven, die aus den Ruinen von Alterac die Fäden ziehen."},{t="Ein Netz adligen Verrats",b="Malebs Nachforschungen über das Syndikat offenbaren einen erbitterten regionalen Konflikt. Bei den Attentätern, die durch die Obstgärten vor Süderstade schleichen, handelt es sich nicht um bloße Banditen, sondern um bezahlte Handlanger im Auftrag gefallener alteracischer Aristokraten. Maleb weist vertrauenswürdige Späher der Allianz an, ihre verschlüsselten Pläne abzufangen und ihre Anführer auszuschalten, wobei er unermüdlich daran arbeitet, den Einfluss des Syndikats zu brechen, bevor dessen Komplotte die Verteidigung der Stadt gänzlich lahmlegen können."}},faq={{q="Wer ist Magistrat Henry Maleb?",a="Er ist der oberste zivile Magistrat von Süderstade im Vorgebirge des Hügellands und dafür verantwortlich, die bürgerliche Ordnung aufrechtzuerhalten und die Zuflucht der Allianz an der Küste vor Gefahren aus dem Inneren zu schützen.",al={"henry maleb","süderstade magistrat","wer ist maleb"}},{q="Warum ermittelt Maleb gegen das Syndikat?",a="Maleb übernahm sein Amt nach der Ermordung des vorherigen Magistrats von Süderstade. Seine Nachforschungen weisen auf gedungene Attentäter des Syndikats hin, die von gefallenen Adligen aus Alterac entsandt wurden, und er beauftragt aktiv Abenteurer der Allianz, um einem weiteren Mordanschlag auf sein Leben zuvorzukommen.",al={"warum syndikat","maleb syndikat","süderstade attentäter"}},{q="Wo ist Magistrat Maleb zu finden?",a="Er hält sich im Rathaus von Süderstade auf, das im südlichen Teil des Vorgebirges des Hügellands liegt.",al={"maleb standort","wo ist henry maleb","magistrat maleb finden"}},{q="Welchen Bedrohungen sieht sich Maleb in Hillsbrad gegenüber?",a="Neben der allgegenwärtigen Gefahr einer Expansion der Verlassenen aus dem Norden und Westen wird Maleb insbesondere von finsteren Mördern des Syndikats bedroht, die die Grenzen der Stadt belauern und den Untergang der Führung von Süderstade planen.",al={"süderstade bedrohungen","maleb feinde"}}},fx={a611609c={q="Warum ist Magistrat Henry Maleb in Süderstade?",a="Maleb wurde kürzlich nach der Ermordung des früheren Anführers der Stadt zum Magistrat von Süderstade ernannt. Er residiert im Rathaus von Süderstade, um die Siedlung zu verwalten, die Verteidigung der Stadt zu überwachen und die Untersuchungen der Allianz zu den Bedrohungen im Vorgebirge des Hügellands zu koordinieren.",al={"warum ist maleb in süderstade","grund für maleb in süderstade","magistrat maleb rathaus"}},["078ca783"]={q="Auf wessen Seite steht Magistrat Henry Maleb?",a="Magistrat Henry Maleb ist voll und ganz der Allianz ergeben. Als ziviler Magistrat von Süderstade dient er der örtlichen Gemeinde und ist den Behörden der Allianz verantwortlich; er arbeitet daran, die verbliebenen freien Menschen von Hillsbrad vereint und sicher vor den umliegenden Feinden zu halten.",al={"fraktion von magistrat maleb","maleb allianz oder horde","ist henry maleb allianz"}},b9806b6f={q="Was will Magistrat Henry Maleb?",a="Maleb will Süderstade vor der Zerstörung bewahren und den Raubzügen des Syndikats ein Ende setzen. Nachdem er sein Amt angetreten hat, nachdem sein Vorgänger ermordet wurde, ist er entschlossen, die Verschwörer zu identifizieren, ihre schattenhaften Attentäter aufzuspüren und die Alteraci-Adligen zu bestrafen, die die Komplotte gegen die Stadt leiten.",al={"ziele von henry maleb","was braucht maleb","ziel von magistrat maleb"}}},fp="22,313,30.640.0,24.434.1,30.175.0,41.278.0,36.121.0,42.222.0"}
P.entries["npc:magistrate-sevren"] = {n="Magistrat Sevren",s="Magistrat Sevren ist der oberste Verwaltungsbeamte, der die Siedlung Brill in Tirisfal leitet. Er steht im Rathaus, organisiert die frühe Verteidigung der Verlassenen und weist eintreffende Champions an, das Gebiet rund um Unterstadt zu stabilisieren.",h="Magistrat Sevren ist der oberste Verwaltungsbeamte, der die Siedlung Brill in Tirisfal leitet.",kw={"agamand","brill","verlassene","magistrat","sevren","tirisfal","rathaus","unterstadt"},ang={["faction:Horde"]="Verbündete der Horde, die in Tirisfal eintreffen, werden Sevren dabei antreffen, wie er die Befriedung an vorderster Front in Tirisfal gegen Banditen, Überreste der Geißel und Rebellengruppierungen koordiniert.",["race:Undead"]="Für neu befreite Verlassene, die Todesend verlassen, stellt Magistrat Sevren das bürgerliche Gesicht von Sylvanas' Reich dar und erteilt Euch Eure ersten großen Aufgaben zum Schutz Eurer Heimat."},sec={{t="Stadtmagistrat von Brill",b="Aus dem Rathaus in Brill heraus koordiniert Magistrat Sevren die Zivilbehörde und strategische Bemühungen in den Ländereien unmittelbar nördlich von Unterstadt. Wenn neue Verlassene nach Tirisfal heraustreten, beurteilt Sevren örtliche Krisen und entsendet Abenteurer, um die Ordnung wiederherzustellen, ruinierte Infrastruktur zu sichern und anhaltende Bedrohungen zu unterdrücken, die in den umliegenden Hügeln lauern."},{t="Sicherung der Gräber",b="Sevrens Hauptaugenmerk liegt auf der Bewahrung und Bergung der Toten von Tirisfal. Lokale Graverobbers, Rotfelle und abtrünnige Untote stören die Grabstätten und bedrohen die entstehende Herrschaft von Sylvanas Windläufer. Sevren stellt sicher, dass uralte Gräber – wie die Gruft der Familie Agamand – zurückgefordert werden und dass Deserteure oder unkooperative Kräfte die Autorität der Verlassenen in der Region nicht untergraben."}},faq={{q="Wer ist Magistrat Sevren?",a="Magistrat Sevren ist das Verwaltungsoberhaupt von Brill und im Rathaus stationiert. Er dient als Aufseher für die Gebietsverwaltung der Verlassenen und vergibt Aufgaben an Abenteurer, die aus Todesend eintreffen, um dem jungen Reich beizustehen.",al={"magistrat sevren","wer ist sevren","magistrat von brill"}},{q="Wo ist Magistrat Sevren zu finden?",a="Er befindet sich im Rathaus im Zentrum von Brill in Tirisfal.",al={"sevren aufenthaltsort","wo ist magistrat sevren","sevren finden"}},{q="Mit welchen Bedrohungen befasst sich Magistrat Sevren?",a="Sevren kämpft gegen lokale Bedrohungen für Tirisfal an, darunter mit der Geißel verbündete Rotfellgnolle, die Gräber plündern, Überreste der Geißel, die örtliche Grüfte entweihen, und abtrünnige untote Gestalten, die Fürstin Sylvanas die Gefolgschaft verweigern.",al={"sevren quests","was will sevren","probleme in brill"}},{q="Wem gilt Magistrat Sevrens Loyalität?",a="Er ist den Verlassenen treu ergeben und regiert Brill im Namen von Fürstin Sylvanas Windläufer und Unterstadt.",al={"sevren fraktion","wem dient sevren"}},{q="Warum schickt Sevren Abenteurer zur Familiengruft?",a="Die Grüfte der alten Agamand-Dynastie werden von Untoten und plündernden Bedrohungen überrannt. Sevren verlangt von Abenteurern, die Ruhestätten der Ahnen zu sichern, um zu verhindern, dass Feinde sie ausnutzen.",al={"agamand-gruft","sevren gruft-quest"}},{q="Hat Sevren Verbindungen zur Führung von Unterstadt?",a="Ja. Als örtlicher Magistrat steht er regelmäßig in Verbindung mit Agenten und Beamten aus Unterstadt, entsendet Boten und schickt Abenteurer tiefer in die Hauptstadt, sobald sie ihre Fähigkeiten in Brill unter Beweis gestellt haben.",al={"sevren unterstadt","sevren raleigh"}}},fx={["54ff886a"]={q="Was will Magistrat Sevren?",a="Als oberste zivile Autorität von Brill will Sevren das Tirisfal für die Verlassenen sichern. Er koordiniert die Bemühungen, die verbliebene Geißel auszurotten, Grabräuber zu stoppen, die die Ruhestätten der Verlassenen entweihen, und klare Befehls- und Versorgungslinien tiefer in das Königreich aufrechtzuerhalten.",al={"ziele von magistrat sevren","motive von sevren","was will sevren"}},["2465c638"]={q="Warum ist Magistrat Sevren in Brill?",a="Sevren leitet das Rathaus von Brill, um die lokale Verwaltung und Rechtsprechung direkt vor den Toren der Unterstadt zu beaufsichtigen. Er dient als primäre kommunale Autorität, die frisch erwachte und ankommende Verlassene in den Dienst leitet, um das Reich zu schützen und zu organisieren.",al={"warum ist sevren in brill","magistrat sevren rathaus","zweck von sevrens aufenthaltsort"}}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.220.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magistrate-solomon"] = {n="Magistrat Solomon",s="Magistrat Solomon ist das gewählte Oberhaupt und der oberste Magistrat von Seenhain, der die lokalen Angelegenheiten vom Rathaus aus leitet. Von den Orcs des Schwarzfelsclans und unerbittlichen Gnollclans belagert, verbringt er seine Tage damit, verzweifelt um militärische Hilfe aus einem gleichgültigen und abgelenkten Sturmwind zu flehen.",h="Magistrat Solomon ist das gewählte Oberhaupt und der oberste Magistrat von Seenhain, der die lokalen...",kw={"schwarzfels","bolvar","seenhain","magistrat solomon","marris","prestor","rotkamm","solomon","rathaus"},ang={["faction:Alliance"]="Solomons politische Isolation verdeutlicht die tiefen Risse innerhalb der Allianz von Sturmwind und zeigt, wie äußere Provinzen vollkommen darauf angewiesen sind, sich auf freischaffende Helden zu verlassen.",["race:Dwarf"]="Zwergische Besucher könnten eine tragische Verbindung in Solomons Geschichte entdecken, da der Versuch Eisenschmiedes, seinem Hilferuf zu folgen, im Hinterhalt und der Gefangennahme von Prinzessin Moira Bronzebeard endete.",["race:Human"]="Für menschliche Reisende offenbart das Gespräch mit Solomon den düsteren Zustand des Königreichs jenseits der sicheren inneren Grenzen des Waldes von Elwynn."},sec={{t="Eine Stadt unter Belagerung",b="Magistrat Solomon regiert Seenhain in der dunkelsten Stunde seiner jüngeren Geschichte. Die beschauliche Siedlung am See ist von Feindseligkeit umgeben: Gnolle des Rotkammgebirges und der Schattenfelle streifen durch die umliegenden Hügel, während Orcs des Schwarzfelsclans in organisierten Kriegstrupps aus dem Norden herabsteigen. Solomon arbeitet mit Marschall Marris zusammen, um die öffentliche Ordnung aufrechtzuerhalten und eine Verteidigung zu organisieren, doch Seenhains örtliche Wachen und Milizen sind bis an ihre absolute Belastungsgrenze gefordert."},{t="Appelle an taube Ohren",b="Verzweifelt bemüht, Verstärkung zu sichern, hat Solomon Boten durch das gesamte Königreich entsandt – und um Hilfe aus Westfall, Dunkelhain und der Hauptstadt Sturmwind selbst gefleht. Seine Bitten brachten bittere Enttäuschung. Westfall leidet unter dem Griff der Bruderschaft der Defias, der Dämmerwald wird von seinen eigenen schleichenden Schrecken heimgesucht, und Sturmwind weigert sich, Truppen an die östliche Grenze zu entsenden, wodurch Seenhain völlig auf sich allein gestellt ist."},{t="Die Weigerung des Hofes",b="Als Beweise auftauchen, dass die Orcs des Schwarzfelsclans mit dem Schwarzen Drachenschwarm verbündet sind, leitet Solomon die Warnung direkt an Hochlord Bolvar Fordragon weiter. Trotz des Ausmaßes der Bedrohung tut die königliche Beraterin Lady Katrana Prestor Solomons Bitten als wilde Übertreibung ab. Gebunden an ihren Rat und Sturmwinds dünn verteilte Streitkräfte lehnt Bolvar es ab, die Armee von Sturmwind einzusetzen, und bietet Solomon lediglich die königliche Genehmigung an, unabhängige Söldner zu bevollmächtigen."}},faq={{q="Wer ist Magistrat Solomon?",a="Magistrat Solomon ist der gewählte zivile Anführer von Seenhain und vorsitzende Richter des Gerichts von Seenhain. Vom Rathaus aus leitet er lokale Verwaltungsangelegenheiten und koordiniert die verzweifelte Verteidigung der Stadt gegen einfallende Gnolle und Orcs.",al={"magistrat solomon lore","wer ist solomon","anführer seenhain"}},{q="Warum kann Sturmwind keine Truppen schicken, um ihm zu helfen?",a="Sturmwinds Militär ist bereits über mehrere unruhige Regionen hinweg dünn verteilt. Als Solomon um Hilfe fleht, steht Hochlord Bolvar Fordragon unter starkem Einfluss der königlichen Beraterin Lady Katrana Prestor, die Solomons Berichte anzweifelt und aktiv davon abrät, reguläre Truppen des Königreichs ins Rotkammgebirge zu entsenden.",al={"warum keine armee aus sturmwind","warum hilft sturmwind seenhain nicht","bolvar hilfe rotkamm"}},{q="Hat Eisenschmiede versucht, Hilfe zu schicken?",a="Ja. Auf Solomons Bitten hin entsandte König Magni Bronzebart ein Hilfskontingent unter der Leitung von Prinzessin Moira Bronzebeard. Die Expedition erreichte das Rotkammgebirge jedoch nie, da sie in der Brennenden Steppe überfallen und gefangen genommen wurde.",al={"zwergenverstärkung seenhain","eisenschmiede hilfe rotkamm","moira bronzebeard seenhain"}},{q="Welche Bedrohungen plagen Seenhain?",a="Seenhain sieht sich gleichzeitigem Druck durch die Rotkamm- und Schattenfellgnolle ausgesetzt, die die Hügel und Straßen unsicher machen, sowie den aggressiven Orcs des Schwarzfelsclans, die von Burg Steinwacht und der Brennenden Steppe aus nach Süden vordringen.",al={"was greift seenhain an","feinde im rotkamm","warum sorgt sich solomon"}},{q="Wer arbeitet mit Solomon zusammen, um die Stadt zu verteidigen?",a="Solomon stimmt sich hauptsächlich mit Marschall Marris ab, der die örtliche Stadtwache befehligt. Da reguläre Verstärkung niemals eintrifft, sind die beiden Beamten gezwungen, durchreisende Abenteurer anzuheuern und zu beauftragen, um die vordringenden Bedrohungen zurückzuschlagen.",al={"verteidiger von seenhain","marschall marris und solomon"}},{q="Warum schickt Solomon Kuriere nach Dunkelhain und Westfall?",a="Da der Hof von Sturmwind untätig bleibt, versucht Solomon, Beistandspakte mit benachbarten Siedlungen der Allianz zu schließen. Leider ist Westfall durch die Bruderschaft der Defias gelähmt und Dunkelhain von Untoten und wilden Bestien überwältigt, sodass keine von beiden auch nur einen einzigen Verteidiger entbehren kann.",al={"botschaft nach dunkelhain","botschaft nach westfall","solomon hilfe andere städte"}}},fx={["85afa026"]={q="Auf wessen Seite steht Magistrat Solomon?",a="Solomon ist dem Königreich Sturmwind und der Großen Allianz loyal ergeben. Als zivile Autorität in Seenhain ist er dem königlichen Hof in Sturmwind unterstellt und bittet Hochlord Bolvar Fordragon um militärische Unterstützung, um sein Volk zu schützen.",al={"fraktion von magistrat solomon","wem dient solomon","loyalität von solomon"}},c7aa651d={q="Was will Magistrat Solomon?",a="Solomon sucht verzweifelt nach militärischer Hilfe und Ressourcen, um Seenhain vor der drohenden Vernichtung zu verteidigen. Eingekesselt von aggressiven Gnollrudeln und den vordringenden Schwarzfelsorks wünscht er sich Verstärkung aus Sturmwind und den benachbarten Siedlungen – oder fähige Abenteurer, die bereit sind, den Kampf zum Feind zu tragen.",al={"ziel von solomon","was braucht solomon","motivation von magistrat solomon"}},de97db78={q="Warum ist Magistrat Solomon hier in Seenhain?",a="Solomon leitet das Rathaus von Seenhain, da er der gewählte Herrscher der Stadt und Richter am Gericht von Seenhain ist. Trotz der wachsenden Gefahr bleibt er auf seinem Posten, verwaltet lokale Angelegenheiten und organisiert die Verteidigung des Rotkammgebirges.",al={"warum ist solomon im rotkammgebirge","rolle von solomon in seenhain","aufgabe von magistrat solomon"}}},fp="18,281,18.445.0,20.447.0,19.458.1,26.257.0,44.300.1,31.224.1,37.213.0,42.241.0,57.292.0"}
P.entries["npc:magni-bronzebeard"] = {n="Magni Bronzebart",s="Magni Bronzebart ist der Herr von Eisenschmiede, Thane des Bronzebeard-Clans und Herrscher über Khaz Modan. Als unvergleichlicher Schmied und erfahrener Kommandant des Zweiten Krieges führt er sein Gebirgskönigreich durch Trauer und politische Spannungen, während er sich auf ganz Azeroth für die zwergische Archäologie einsetzt.",h="Magni Bronzebart ist der Herr von Eisenschmiede, Thane des Bronzebeard-Clans und Herrscher über Khaz Modan.",kw={"aschenbringer","brann","bronzebeard","forscherliga","eisenschmiede","khaz modan","magni","moira","muradin"},ang={["faction:Alliance"]="Als standhafter Gründer der Großen Allianz an der Seite von Lordaeron und Sturmwind steuert Magni militärische Stärke, ingenieurstechnisches Können und unerschütterliche Loyalität zum Bündnis bei.",["profession:Blacksmithing"]="Magni gilt als einer der größten lebenden Schmiede Azeroths; er schuf den sagenumwobenen Aschenbringer am Großen Amboss von Eisenschmiede aus einem jenseitigen Kristall.",["race:Dwarf"]="Magni ist Euer unbestrittener Herrscher und der Beschützer von Khaz Modan, der den Bronzebeard-Clan durch äußere Kriege und die innere Suche nach dem irdenen Erbe Eures Volkes führt.",["race:Gnome"]="König Magni bot den Überlebenden von Gnomeregan seine Stadt als Zufluchtsort an und pflegt eine enge Freundschaft sowie ein technologisches Bündnis mit Hochtüftler Mekkatorque."},sec={{t="Herr des Berges",b="Als ältester von drei Brüdern wuchs Magni im ständigen Bewusstsein um die Last auf, die ihn unter dem Berg erwartete. Als die Horde während des Zweiten Krieges einfiel, hielt er Eisenschmiede hinter seinen undurchdringlichen Toren, trat nach dem Brechen der Belagerung hervor und schwor der Allianz von Lordaeron die Treue von Khaz Modan. In den darauf folgenden Friedensjahren hieß Magni nach dem Fall von Gnomeregan seine gnomischen Verbündeten in der Stadt willkommen und bot Hochtüftler Gelbin Mekkadrill und seinen Flüchtlingen Zuflucht im Berg. Um die zersplitterten südlichen und nördlichen Königreiche zu einen, bat Magni Mekkatorque darum, ein beispielloses unterirdisches Wunderwerk zu konstruieren: Die Tiefenbahn, die Eisenschmiede direkt mit Sturmwind verbindet."},{t="Ein Hammer der Vergeltung",b="Hinter Magnis königlicher Haltung verbirgt sich eine tiefe persönliche Tragödie. Während des Dritten Krieges traf aus Nordend die Nachricht ein, dass Prinz Arthas Menethil Magnis geliebten jüngeren Bruder Muradin verraten und ermordet habe. Überwältigt von Trauer und Zorn ergriff Magni am Großen Amboss seinen Hammer, als Hochinquisitor Schönufer und Alexandros Mograine ihm einen Kristall aus reinem, strahlendem Licht brachten. Drei unermüdliche Tage lang floss der gesamte Schmerz, die Wut und das Verlangen nach Rache des Zwergenkönigs in das Metall. Die daraus entstandene Klinge – der Aschenbringer – ist das größte Meisterwerk seines Lebens, geschmiedet, um Arthas und die Geißel ins Verderben zu stürzen."},{t="Ausgrabung der Vergangenheit",b="Auf Magnis Geheiß hat die Gesellschaft der Zwerge ihren Schwerpunkt größtenteils vom traditionellen Bergbau abgewandt und der Freilegung uralter Geschichte gewidmet. Angespornt durch die Entdeckung seltsamer Titanenrelikte tief unter der Erde gründete Magni gemeinsam mit seinem überlebenden Bruder, Brann Bronzebeard, die Forscherliga. Zwergische Ausgrabungsstätten säumen nun die Kontinente, von Dun Morogh bis Kalimdor, und versuchen das Geheimnis zu lüften, wie die Irrenen zu den modernen Zwergen wurden. Doch der innere Frieden bleibt brüchig: Magnis Tochter, Prinzessin Moira, ist verschwunden und wurde vermutlich vom verhassten Dunkeleisenzwerg-Clan entführt."}},faq={{q="Wer ist Magni Bronzebart?",a="Magni Bronzebart ist der König von Khaz Modan, Thane von Eisenschmiede und Häuptling des Bronzebeard-Clans. Er regiert das Gebirgskönigreich vom High Seat in Eisenschmiede aus und ist eine der standhaftesten Säulen der Großen Allianz.",al={"könig von eisenschmiede","zwergenkönig","wer ist magni"}},{q="Wer hat den Aschenbringer geschmiedet?",a="König Magni schmiedete das legendäre Schwert selbst am Großen Amboss in Eisenschmiede. Alexandros Mograine und Hochinquisitor Schönufer brachten ihm einen rätselhaften Kristall aus lebendigem Licht, und Magni goss in drei Tagen ununterbrochener Schmiedearbeit seine Trauer und Wut über Muradins gemeldeten Tod in die Klinge.",al={"hat magni den aschenbringer geschmiedet","schöpfer des aschenbringers","wer hat den aschenbringer geschmiedet"}},{q="Was geschah mit Magnis Brüdern?",a="Magni ist der älteste von drei Brüdern. Sein Bruder Muradin diente als Botschafter der Allianz in Lordaeron und wurde Berichten zufolge von Prinz Arthas in Nordend getötet. Sein jüngster Bruder Brann ist ein renommierter Forscher, der als Anführer der Forscherliga in die entlegensten Winkel der Welt reist.",al={"muradin und brann","magnis brüder","schicksal von muradin bronzebeard"}},{q="Wo ist Prinzessin Moira?",a="Prinzessin Moira Bronzebeard, Magnis einziges Kind, ist aus Eisenschmiede verschwunden. Offiziellen Berichten im Berg zufolge wurde sie von den feindseligen Dunkeleisenzwergen entführt und wird tief im Inneren des Schwarzfels gefangen gehalten.",al={"magnis tochter","wo ist moira","was geschah mit moira bronzebeard"}},{q="Warum leben Gnom in Eisenschmiede?",a="Nach der Invasion der Troggs und der verheerenden Verstrahlung von Gnomeregan öffnete König Magni Hochtüftler Gelbin Mekkadrill und den überlebenden Gnomen die Tore von Eisenschmiede. Magni sprach ihnen ein ganzes Stadtviertel zu, das heute als Tüftlerstadt bekannt ist.",al={"tüftlerstadt","warum sind gnom in der zwergenstadt","gnomenflüchtlinge eisenschmiede"}},{q="Was ist die Forscherliga?",a="Die Forscherliga ist eine archäologische Organisation, die von König Magni und seinem Bruder Brann gegründet wurde. Nach der Entdeckung uralter Titanenruinen richtete Magni die Industrien der Zwerge darauf aus, die Wahrheit über die Ursprünge ihres Volkes aufzudecken, und entsandte Expeditionsteams über ganz Azeroth.",al={"forschergilde","zwergenarchäologen","warum graben die zwerge"}}},fp="17,280,20.683.0,21.631.0,19.597.0,25.222.0,26.296.0,34.283.0,24.239.0,35.242.0,30.267.0"}
P.entries["npc:magus-rimtori"] = {n="Magus Rimtori",s="Magus Rimtori ist eine abtrünnige Blutelfen-Zauberin, die eine Expedition durch die uralten Ruinen von Azshara anführt. Bekannt für ihre skrupellose Täuschung, manipulierte sie die Horde, um ihre Reise durch Kalimdor abzusichern, bevor sie ihre orkische Eskorte niedermetzelte.",h="Magus Rimtori ist eine abtrünnige Blutelfen-Zauberin, die eine Expedition durch die uralten Ruinen von...",kw={"azshara","belgrom","blutelf","hawkhelm","kim'jael","magus rimtori","rimtori","thalassischer stützpunkt"},ang={["class:Mage"]="Rimtori zeigt, wie weit thalassische Magi bei ihrer verzweifelten Suche nach arkaner Macht gehen, indem sie die Ruinen und dämonischen Relikte Kalimdors durchkämmen.",["faction:Horde"]="Rimtori manipulierte Belgrom und schlachtete die zu ihrem Schutz abkommandierte Orkwache ab, wodurch ihre Beseitigung zu einer obersten Priorität für Krieger der Horde wurde, die ihre gefallenen Brüder rächen wollen."},sec={{t="Eine tödliche Täuschung",b="Magus Rimtori führte eine Expedition adliger Blutelfen über das Meer an die uralten Küsten von Azshara. Um das Überleben ihrer Gruppe in den Gefahren Kalimdors zu sichern, manipulierte sie den Ork Belgrom, betörte und hinterging ihn, bis er einwilligte, eine bewaffnete Eskorte bereitzustellen. Sobald die Soldaten sie sicher an ihr Ziel geleitet hatten, zeigte Rimtori ihr wahres Gesicht, wandte sich gegen ihre Beschützer und massakrierte die gesamte Garnison. Nachdem sie ihre Streitkräfte im Thalassischen Stützpunkt eingerichtet hatte, brach sie in die Wildnis der Küste auf, begleitet von Eliteleibwächtern, um nach vergessenen magischen Artefakten zu suchen."},{t="Geheimnisse der Ruinen",b="Das wahre Motiv hinter Rimtoris Expedition bleibt im Dunkeln, doch ihre skrupellosen Methoden haben ihr zahllose Feinde eingebracht. Neben dem Verrat an der Horde hinterging sie auch einheimische Mietlinge, darunter den Goblin-Landvermesser Kim'jael, der behauptet, sie sei von der Entdeckung einer uralten Rune besessen gewesen. Umgeben von Relikten wie einem Folianten der Dämonenbeschwörung, der in ihrem Lager zurückgelassen wurde, hat Rimtoris Jagd nach Macht die erbitterte Vergeltung der Horde heraufbeschworen, die sie so kaltblütig hintergangen hat."}},faq={{q="Warum will die Horde Rimtori tot sehen?",a="Rimtori betörte und manipulierte den Ork Belgrom, damit er ihrer Expedition eine militärische Eskorte durch Kalimdor zur Verfügung stellte. Sobald sie sicher in Azshara angekommen waren, verriet und schlachtete sie jeden einzelnen orkischen Soldaten unter Belgroms Befehl ab.",al={"warum rimtori töten","belgrom rimtori lore","was tat rimtori der horde an"}},{q="Wo ist Magus Rimtori zu finden?",a="Während ihre Expedition den Thalassischen Stützpunkt errichtete, durchstreift Rimtori selbst in Begleitung ihrer persönlichen Blutelfen-Leibwächter die Wildnis von Azshara auf der Suche nach uralten Relikten.",al={"rimtori aufenthaltsort","wo ist magus rimtori","rimtori azshara aufenthaltsort"}},{q="Wonach suchte Rimtori in Azshara?",a="Dem Goblin Kim'jael zufolge, den sie anheuerte und daraufhin verriet, jagte Rimtori wie besessen nach einer geheimnisvollen uralten Rune, neben anderen mächtigen Relikten wie einem kaldoreischen Folianten der Beschwörung.",al={"was will rimtori","rimtoris ziel azshara","rimtori rune"}},{q="Wer ist Magister Hawkhelm?",a="Magister Hawkhelm ist ein Blutelfenoffizier, dem von Magus Rimtori die Leitung und Aufsicht über den Thalassischen Stützpunkt anvertraut wurde, während sie die umliegenden Ruinen untersucht.",al={"hawkhelm","thalassischer stützpunkt anführer","magister hawkhelm rimtori"}}},fp="13,241,18.585.0,20.485.1,37.236.0,33.191.0,42.198.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="Mai'ah",s="Mai'ah ist eine Dschungeltroll-Magierausbilderin, die im sonnenverbrannten Becken des Tal der Prüfungen in Durotar stationiert ist. Sie unterweist angehende Zauberwirker unter den Dunkelspeer, die in die roten Schluchten treten, um ihre Beherrschung der arkanen Künste zu schulen. Jungen Trollen, die den Pfad der Zauberei beginnen, bietet sie frühe Anleitung und Unterweisung in den grundlegenden Künsten der Magie.",h="Mai'ah ist eine Dschungeltroll-Magierausbilderin, die im sonnenverbrannten Becken des Tal der Prüfungen in...",kw={"dunkelspeer","durotar","magierausbilder","mai'ah","maiah","troll","das tal der prüfungen"},ang={["class:Mage"]="Für Dunkelspeer-Zauberwirker repräsentiert Mai'ah den Beginn ihrer magischen Reise und lehrt die Disziplin, die nötig ist, um unter der harten Sonne von Durotar Feuer, Frost und arkane Energie zu weben.",["race:Troll"]="Mai'ah bietet Dunkelspeer-Jugendlichen im Tal der Prüfungen kulturelle Mentorenschaft in einer Kunst, die von ihren orcischen Verbündeten selten praktiziert wird."},sec={{t="Arkanmentorin des Höhlenbaus",b="Während Orcs überwiegend dem urtümlichen Ruf der Elemente oder der physischen Dominanz des Kriegers den Vorzug geben, besitzen Dunkelspeer eine seltene Affinität für das arkane Studium. Mai'ah steht im Tal der Prüfungen und dient als Ausbilderin für junge Trollmagier, die eintreffen, um ihre Riten des Erwachsenwerdens zu vollziehen. Sie nimmt Kandidaten entgegen, die Glyphic Parchment mit sich führen, und beginnt damit, ihre chaotische rohe Macht in disziplinierte Zauber zu formen, wobei sie sicherstellt, dass sie die Kontrolle erlernen, die zum Überleben der Gefahren in Durotar erforderlich ist."}},faq={{q="Wer ist Mai'ah?",a="Mai'ah ist eine Dunkelspeer-Trollmagierausbilderin, die sich im Tal der Prüfungen in Durotar befindet. Sie bietet neu eingetroffenen Trollzauberwirkern erste Anleitung, Training und grundlegende Zauber, bevor diese in die weiteren Länder der Horde aufbrechen.",al={"wer ist maiah","maiah lore","trollmagierausbilderin"}},{q="Warum gibt es eine Trollmagierausbilderin in einem Orc-Startgebiet?",a="Nachdem die Dunkelspeer ihre sinkende Inselheimat flohen und sich an der Seite von Thralls Orcs in Durotar neu ansiedelten, vollziehen junge Dunkelspeer ihre Prüfungen des Erwachsenwerdens zusammen mit Orc-Jugendlichen. Da die Orc-Kultur aufgrund früherer Dämonenkorruption arkane Magie weitgehend meidet, springen Trollmagier wie Mai'ah ein, um ihre eigene Art anzuleiten.",al={"warum trollmagier hier","trollausbilder tal der prüfungen","trollmagier durotar"}},{q="Welche Rolle spielt sie bei der Ausbildung neuer Magier?",a="Mai'ah heißt neue Trollmagier willkommen, die schriftliche Anweisungen wie Glyphic Parchment mit sich führen. Sie initiiert ihre formale Ausbildung und lehrt die Grundlagen des Zauberwirkens, damit sie das Tal der Prüfungen vor heimischen Bestien und abtrünnigen Infiltratoren der Burning Blade verteidigen können.",al={"was macht maiah","glyphic parchment maiah","maiah quests"}}},fx={["4a36b72a"]={q="Auf wessen Seite steht Mai'ah?",a="Mai'ah ist dem Darkspear tribe und der Horde loyal ergeben. Stationiert im Tal der Prüfungen arbeitet sie unter dem neuen Regime von Thrall, um die zukünftigen Zauberkundigen der Horde zu fördern, und widmet ihr arkanes Wissen der Stärkung junger Trolle und verbündeter Magier.",al={"loyalität von mai'ah","wem dient mai'ah","ist mai'ah bei der horde"}},["648de549"]={q="Was will Mai'ah?",a="Mai'ah möchte angehende Praktizierende in den Grundlagen der arkanen Magie ausbilden. Sie versucht, junge Novizen durch ihre einleitenden Zauber und Glyphen zu führen und sicherzustellen, dass sie über die Disziplin und die magische Kraft verfügen, die nötig sind, um in Durotar zu überleben und der Horde zu dienen.",al={"was braucht mai'ah","ziele von mai'ah","warum unterrichtet mai'ah"}}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:major-mattingly"] = {n="Major Mattingly",s="Major Mattingly ist ein erfahrener Offizier der Armee von Sturmwind, der an den großen Toren im Tal der Helden stationiert ist. Unter dem Befehl von General Marcus Jonathan hilft er dabei, den Haupteingang der Hauptstadt zu sichern und fähige Handwerker dabei zu beraten, wie sie Helden vor drakonischen Gefahren schützen können.",h="Major Mattingly ist ein erfahrener Offizier der Armee von Sturmwind, der an den großen Toren im Tal der...",kw={"drachenschuppenumhang","marcus jonathan","major mattingly","mattingly","armee von sturmwind","das tal der helden"},ang={["class:Warrior"]="Als disziplinierter Veteran, der an den Stadttoren sein Langschwert führt, verkörpert Mattingly die standhafte Entschlossenheit der Infanterieoffiziere der Armee von Sturmwind.",["faction:Alliance"]="Für Champions der Allianz, die es wagen, mächtige Drachen wie Onyxia herauszufordern, liefert Major Mattingly die entscheidende Anleitung zur Herstellung von schützenden Umhängen aus Drachenschuppen."},sec={{t="Schildwache der Tore der Hauptstadt",b="Major Mattingly hält Wache im Tal der Helden und ist einer der hochrangigen Offiziere, die direkt für Sturmwinds wichtigste landseitige Verteidigung verantwortlich sind. Als ergrauter Veteran, dessen Gesicht die Züge hart erkämpfter Erfahrung trägt, dient er an der Seite der ständigen Garnison der Stadt unter General Marcus Jonathan. Neben seinen täglichen Pflichten bei der Überwachung der Torpatrouillen und ankommenden Reisenden verfügt Mattingly über spezielles taktisches Wissen über die tödliche Natur von Drachen. Erfahrenen Abenteurern gilt er als unverzichtbarer Ansprechpartner, wenn es darum geht, schützende Drachenschuppenausrüstung herzustellen, die für das Betreten der gefährlichsten Horte des Reiches erforderlich ist."}},faq={{q="Wo ist Major Mattingly zu finden?",a="Major Mattingly ist nahe dem Eingang von Sturmwind im Tal der Helden stationiert, wo er direkt hinter den Haupttoren an der Seite anderer Truppen der Garnison Wache hält.",al={"mattingly standort","wo ist major mattingly","major mattingly finden"}},{q="Welchen Rang und welche Rolle hat Major Mattingly in Sturmwind?",a="Er ist ein Offizier der Armee von Sturmwind, der unter General Marcus Jonathan dient. Er hilft bei der Überwachung der Verteidigung der Stadttore und steht Abenteurern mit militärischem Rat zur Seite.",al={"wer ist mattingly","mattingly beruf","was macht mattingly"}},{q="Warum suchen Lederverarbeiter Major Mattingly auf?",a="Mattingly besitzt Anleitungen zur Behandlung und Herstellung von Schuppenumhängen aus der Haut schwarzer Drachen und leitet erfahrene Handwerker an, die ihre Verbündeten vor drakonischen Flammen schützen wollen.",al={"onyxiaschuppenumhang mattingly","mattingly quest","die reise beginnt erst mattingly"}},{q="Ist Major Mattingly in größere Konflikte verwickelt?",a="Er ist ein kampferprobter Veteran des Königreichs Sturmwind, der sich der Verteidigung des Reiches verschrieben hat, während König Varian Wrynn weiterhin vermisst wird und das Königreich mit anhaltenden Bedrohungen ringt.",al={"mattingly hintergrund","mattingly lore"}}},fx={["3133ea98"]={q="Auf wessen Seite steht Major Mattingly?",a="Major Mattingly ist dem Königreich Sturmwind und der Allianz vollkommen ergeben. Als Offizier der Armee von Sturmwind ist er General Marcus Jonathan unterstellt und hält Wache am Haupteingang der Hauptstadt, loyal zum Thron und der Verteidigung des Reiches.",al={"fraktion von mattingly","wem dient mattingly","loyalität von major mattingly"}},["3a90c3f3"]={q="Warum ist Major Mattingly im Tal der Helden stationiert?",a="Er ist an den Toren im Tal der Helden stationiert, um die vorderste Verteidigungslinie der Hauptstadt zu überwachen. Unter den hoch aufragenden Monumenten für die Helden des Zweiten Krieges hilft Mattingly, die Wache am Torhaus zu befehligen und sicherzustellen, dass keine feindlichen Kräfte ungehindert durch die Tore marschieren.",al={"warum ist mattingly hier","warum ist mattingly im tal der helden","was macht mattingly in sturmwind"}},["728996ed"]={q="Mit wem ist Major Mattingly verbunden?",a="Major Mattingly dient direkt unter General Marcus Jonathan innerhalb der Befehlskette der Armee von Sturmwind. Er teilt zudem den Nachnamen mit Janice Mattingly, einer Bewohnerin der Stadt, obwohl seine täglichen Pflichten strikt an seinen militärischen Posten und seinen kommandierenden Offizier gebunden bleiben.",al={"kommandant von mattingly","wem untersteht mattingly","verbindungen von major mattingly"}}},fp="15,284,29.642.0,35.165.0,53.173.0,47.173.0,53.187.0"}
P.entries["npc:major-samuelson"] = {n="Major Samuelson",s="Major Samuelson ist ein hochrangiger Offizier der Stadtwache von Sturmwind, der im Thronsaal von Burg Sturmwind stationiert ist. Als erfahrener militärischer Kommandant beaufsichtigt er wichtige Personalangelegenheiten und diente zuvor jüngeren Offizieren wie Leutnant Farren Orinelle als Mentor.",h="Major Samuelson ist ein hochrangiger Offizier der Stadtwache von Sturmwind, der im Thronsaal von Burg...",kw={"farren orinelle","major samuelson","versetzung","samuelson","süderstade","wache von sturmwind","burg sturmwind"},ang={["faction:Alliance"]="Im königlichen Thronsaal dient Major Samuelson als administratives Rückgrat des Militärs von Sturmwind und koordiniert das Personal in umkämpften Gebieten wie Hillsbrad."},sec={{t="Eine Stütze der Wache von Sturmwind",b="Major Samuelson steht in Burg Sturmwind vor dem königlichen Hof und repräsentiert die Führung der Stadtwache von Sturmwind. Er überwacht Offiziersposten und administrative Militärbefehle im gesamten Reich. Insbesondere war er der Mentor von Leutnant Farren Orinelle, einem Offizier, der weit im Norden in Süderstade im Vorgebirge des Hügellands stationiert ist. Wenn jüngere Befehlshaber überfordert sind oder eine Versetzung aus fernen Grenzgarnisonen anstreben, gelangen ihre Gesuche und offiziellen Berichte quer durch das Königreich direkt auf den Schreibtisch von Major Samuelson in der Hauptstadt."}},faq={{q="Wer ist Major Samuelson?",a="Major Samuelson ist ein Offizier der Stadtwache von Sturmwind, der im Thronsaal von Burg Sturmwind stationiert ist. Er dient als administrativer Kommandant, der sich um Truppenstationierungen und Personalfragen von Offizieren kümmert.",al={"samuelson","major samuelson identität","wer ist der major in der feste"}},{q="Wo ist Major Samuelson zu finden?",a="Er befindet sich in Burg Sturmwind in Sturmwind und steht im Thronsaal in der Nähe des Kindkönigs Anduin Wrynn und von Hochlord Bolvar Fordragon.",al={"samuelson aufenthaltsort","wo ist major samuelson","samuelson finden"}},{q="Was verbindet ihn mit Süderstade?",a="Major Samuelson diente als Mentor von Leutnant Farren Orinelle, einem in Süderstade im Vorgebirge des Hügellands stationierten Offizier. Orinelle versucht über Samuelson, eine Versetzung von dem anstrengenden nördlichen Posten zu erwirken.",al={"samuelson süderstade","leutnant farren orinelle mentor","samuelson hillsbrad"}},{q="Warum suchen Abenteurer ihn auf?",a="Abenteurer, die von der nördlichen Front in Hillsbrad anreisen, überbringen Leutnant Farren Orinelles offizielles Versetzungsgesuch an Major Samuelson in Burg Sturmwind.",al={"sturmwind hq questabgabe","versetzungsquest","warum mit samuelson sprechen"}}},fx={["75428c69"]={q="Auf wessen Seite steht Major Samuelson?",a="Major Samuelson dient dem Königreich Sturmwind und der Allianz. Als Offizier innerhalb der Stadtwache von Sturmwind, der direkt in der Burg Sturmwind stationiert ist, besteht seine Pflicht darin, die Hauptstadt zu verteidigen, die militärische Ordnung aufrechtzuerhalten und die Befehle der Führung der Stadt auszuführen.",al={"fraktion von samuelson","wem dient major samuelson","ist samuelson bei der allianz"}}},fp="15,271,29.546.0,23.190.0,35.148.0,37.215.0,32.165.0"}
P.entries["npc:makaba-flathoof"] = {n="Makaba Flachhuf",s="Makaba Flachhuf ist ein überlebender Taure aus Camp Aparaje im Steinkrallengebirge. Nachdem er die Verwüstung seiner Heimat und seines Volkes durch die Hände des Grimtotem-Clans mitansehen musste, sucht er nach tapferen Streitern der Horde, um Rache an den Angreifern zu nehmen und die Sicherheit seiner Familie zu gewährleisten.",h="Makaba Flachhuf ist ein überlebender Taure aus Camp Aparaje im Steinkrallengebirge.",kw={"camp aparaje","flachhuf","grimtotem","grundig darkcloud","kaya","makaba","steinkrallengebirge"},ang={["faction:Horde"]="Makabas Hilferufe ermöglichen es den Streitern der Horde, ihre Loyalität gegenüber ihren Taurenverbündeten zu beweisen, indem sie diejenigen bestrafen, die friedliche Lager abschlachten.",["race:Tauren"]="Für Taurenhelden verdeutlicht Makabas Not die bittere Treulosigkeit der Grimtotem und dient als Mahnung, dass nicht alle Angehörigen ihres Volkes die Wege des Friedens und der Einheit ehren."},sec={{t="Tragödie in Camp Aparaje",b="Makaba Flachhuf verkörpert den tragischen Tribut der internen Konflikte unter den Tauren. Seine Heimat, Camp Aparaje im Steinkrallengebirge, fiel einem rücksichtslosen Überraschungsangriff des Grimtotem-Clans zum Opfer. Während viele Tauren unter der Führung von Cairne Bluthuf nach Frieden und Einigkeit streben, säen die verräterischen Grimtotem fortwährend Zwietracht und Gewalt, wodurch Überlebende wie Makaba vertrieben und trauernd zurückbleiben."},{t="Ein Flehen um Rache",b="Unfähig, seine gefallene Siedlung allein zurückzuerobern, ruft Makaba Reisende der Horde auf, zurückzuschlagen. Er leitet entschlossene Vergeltung gegen die abtrünnigen Grimtotem an, die seine Heimat überrannten, und fordert Gerechtigkeit für das Abschlachten seines Volkes. Seine dringlichsten Anliegen drehen sich darum, den verantwortlichen Kriegsherrn Grundig Darkcloud zu stellen und Gewissheit über seine vermisste Tochter Kaya zu erlangen."}},faq={{q="Wer ist Makaba Flachhuf?",a="Makaba Flachhuf ist ein Taurenflüchtling aus Camp Aparaje im Steinkrallengebirge. Sein Dorf wurde vom Grimtotem-Clan überrannt und geplündert, was ihn dazu trieb, die Hilfe von Abenteurern der Horde zu suchen.",al={"makaba","wer ist makaba flachhuf","makaba flachhuf lore"}},{q="Woher kam Makaba?",a="Makaba stammt aus Camp Aparaje, einer kleinen Taurensiedlung im Steinkrallengebirge, die von den Grimtotem angegriffen und verwüstet wurde.",al={"makaba herkunft","woher stammt makaba","camp aparaje makaba"}},{q="Wer griff Makabas Dorf an?",a="Camp Aparaje wurde vom Grimtotem-Clan geplündert, einer aggressiven und tückischen Fraktion der Tauren, die vor Ort von Gestalten wie Grundig Darkcloud angeführt wird.",al={"wer griff camp aparaje an","makaba feinde","wer plünderte aparaje"}},{q="Was verlangt Makaba von Abenteurern der Horde?",a="Makaba sucht Rache für seine gefallene Heimat und bittet fähige Krieger darum, die Streitkräfte der Grimtotem in Camp Aparaje niederzustrecken, ihren Anführer Grundig Darkcloud auszuschalten und das Schicksal von Kaya Flathoof aufzudecken.",al={"makaba quests","worum bittet makaba","makaba aufgaben"}},{q="Wer ist Kaya für Makaba?",a="Kaya Flathoof ist Makabas Tochter, die während des Angriffs auf Camp Aparaje verschwand. Makaba hofft verzweifelt zu erfahren, ob sie den Überfall überlebt hat.",al={"kaya flathoof","wer ist kaya","makaba verwandte kaya"}},{q="Ist Makaba mit Dim Flathoof verwandt?",a="Makaba und Dim teilen den Nachnamen Flathoof, doch eine familiäre Verwandtschaft zwischen ihnen ist unbestätigt.",al={"dim flathoof","makaba und dim","familie flachhuf"}}},fx={["586aa360"]={q="Auf wessen Seite steht Makaba Flachhuf?",a="Makaba Flachhuf ist ein loyales Mitglied der Horde und des Taurenvolkes. Nachdem er vor der Gewalt geflohen ist, die seine Heimat traf, sucht er ausschließlich Unterstützung bei Reisenden und Champions der Horde, um seine Sippe zu schützen und gegen ihre Angreifer zurückzuschlagen.",al={"fraktion von makaba flachhuf","ist makaba bei der horde","wem dient makaba"}},["6e0e5223"]={q="Warum ist Makaba Flachhuf hier?",a="Makaba hat im Steinkrallengebirge Zuflucht gesucht, nachdem ihn im Camp Aparaje eine Tragödie heimgesucht hat. Von gewalttätigen Plünderern aus seiner Siedlung vertrieben, hält er sich nun hier auf und sucht Hilfe, um seine gefallenen Verwandten zu rächen und die Sicherheit von Überlebenden wie Kaya zu gewährleisten.",al={"warum ist makaba flachhuf hier","warum ist makaba im steinkrallengebirge","zweck von makaba flachhuf"}}},fp="15,291,23.401.0,20.373.1,23.189.0,27.144.0,30.141.0,46.199.0,22.149.0,34.97.0"}
P.entries["npc:malfurion-stormrage"] = {n="Malfurion Sturmgrimm",s="Malfurion Sturmgrimm ist der erste sterbliche Druide und an der Seite von Hohepriesterin Tyrande Wisperwind der verehrte Anführer der Nachtelfen. Berühmt für den Sieg über die Brennende Legion sowohl im Krieg der Ahnen als auch im Dritten Krieg, wird er als Shan'do oder geehrter Lehrer verehrt. Derzeit liegt er in einem komatösen Schlummer im Smaragdgrünen Traum gefangen, sodass die Kaldorei ohne seine wache Führung auskommen müssen.",h="Malfurion Sturmgrimm ist der erste sterbliche Druide und an der Seite von Hohepriesterin Tyrande Wisperwind...",kw={"erzdruide","cenarius","smaragdgrüner traum","furion","hyjal","illidan","malfurion","shan'do","stormrage","tyrande"},ang={["class:Druid"]="Jeder Druide führt seine Lehren auf Malfurion zurück, der direkt von Cenarius lernte. Seine Abwesenheit im Smaragdgrünen Traum wirft einen schweren Schatten auf den Zirkel des Cenarius.",["class:Priest"]="Malfurion ist der geliebte Gefährte von Hohepriesterin Tyrande Wisperwind und vereint die spirituelle Hingabe an Elune mit der heiligen Wacht über die Natur.",["race:NightElf"]="Malfurion wird als uralter Beschützer und Retter Eures Volkes verehrt, wenngleich sein anhaltender Schlummer die Führung gänzlich Tyrande und Erz Druide Fandral Hirschhaupt überlässt."},sec={{t="Der erste Druide",b="Vor zehntausend Jahren, bevor die Große Zerschlagung das uralte Kalimdor zerbrach, lernte Malfurion unter dem Halbgott Cenarius. Während Königin Azshara und ihre Kaste der Hochgeborenen sich gefährlich tief in die arkanen Energien des Brunnens der Ewigkeit vertieften, wandte sich Malfurion den Urkräften der Natur zu und wurde Azeroths erster sterblicher Druide. Sein Misstrauen gegenüber den Hochgeborenen erwies sich auf tragische Weise als begründet, als Azsharas rücksichtslose Zauberei den Schleier durchstieß und Sargeras sowie die Brennende Legion nach Azeroth beschwor, was den verheerenden Krieg der Ahnen entfesselte."},{t="Retter von Kalimdor",b="Gemeinsam mit Cenarius, Tyrande Wisperwind und seinem Zwillingsbruder Illidan führte Malfurion den Widerstand an, der den Ansturm der Dämonen aufhielt und das Portal über dem Brunnen der Ewigkeit schloss. Nach der Zerschlagung der Welt verpflichtete Malfurion die Druiden dem Smaragdgrünen Traum, um Azeroths lebendiges Gefüge wieder aufzubauen und zu beschützen. Zehntausend Jahre später erweckte ihn Tyrande während des Dritten Krieges aus seinem langen Hügelgrab-Schlaf, um Archimonde die Stirn zu bieten, wo er am Hyjal die Waldgeister versammelte, um die Brennende Legion erneut zu zerschlagen."},{t="Im Traum verloren",b="Nach dem Dritten Krieg kehrte Malfurion in seinen Schlummer in der Mondlichtung zurück, um mit dem Smaragdgrünen Traum zu kommunizieren und seine erschöpfte Macht wieder aufzufüllen. Sein Geist konnte jedoch nicht in seinen physischen Körper zurückkehren, was ihn in einen unnatürlichen, komatösen Zustand stürzte. In Darnassus hat Erz Druide Fandral Hirschhaupt die weltlichen Führungsaufgaben im Zirkel des Cenarius übernommen, während Tyrande und die Schwesternschaft bangend auf Zeichen des Erwachens ihres großen Shan'do warten."}},faq={{q="Wo befindet sich Malfurion Sturmgrimm derzeit?",a="Malfurions Körper schläft in den Hügelgräbern der Mondlichtung, während sein Bewusstsein tief im Geistreich des Smaragdgrünen Traums gefangen bleibt. Er kann in Darnassus nicht als aktiver NSC besucht werden, da sein Körper komatös und für die meisten Abenteurer unzugänglich ist.",al={"wo ist malfurion","wo findet man malfurion","malfurion aufenthaltsort","ist malfurion im spiel"}},{q="Warum schläft Malfurion?",a="Druiden begeben sich regelmäßig in einen Winterschlaf im Smaragdgrünen Traum, um mit der Natur zu kommunizieren, die Flora und Fauna der Welt zu erhalten und ihre spirituellen Kräfte zu regenerieren. Nach der gewaltigen magischen Anstrengung beim Sieg über Archimonde am Hyjal trat Malfurion in den Traum ein, um sich zu erholen, doch ein unnatürliches Leiden hat seinen Geist von seinem Körper getrennt.",al={"warum schläft malfurion","warum ist er im koma","was geschah mit malfurion"}},{q="Wer regiert die Nachtelfen, während Malfurion schläft?",a="Hohepriesterin Tyrande Wisperwind regiert das Volk der Kaldorei vom Tempel des Mondes in Darnassus aus und führt die Schildwachen sowie die Schwesternschaft von Elune an. Unterdessen werden der Zirkel des Cenarius und die druidischen Angelegenheiten von Erz Druide Fandral Hirschhaupt beaufsichtigt.",al={"wer führt nachtelfen an","wer ist der nachtelfenanführer","nachtelfenherrscher"}},{q="Was bedeutet „Shan'do“?",a="Im Darnassischen bedeutet „Shan'do“ übersetzt „geehrter Lehrer“. Es ist ein Titel höchster Ehrfurcht, der Meisterdruiden vorbehalten ist – allen voran Malfurion Sturmgrimm, der den sterblichen Völkern unter der Führung von Cenarius erstmals das Druidentum brachte.",al={"bedeutung shando","was ist shando","shan'do"}},{q="Wer ist Malfurions Bruder?",a="Malfurions Zwillingsbruder ist Illidan Stormrage. Trotz ihrer gemeinsamen Jugend in Suramar sorgten Illidans Besessenheit von arkaner Magie und sein rücksichtsloses Streben nach dämonischer Macht während des Kriegs der Ahnen für ein bitteres Zerwürfnis zwischen ihnen, was Malfurion dazu veranlasste, ihn für Jahrtausende einzusperren.",al={"malfurions bruder","wer ist illidan für malfurion","stormrage brüder"}},{q="Was tat Malfurion in der Schlacht um den Hyjal?",a="Auf dem Höhepunkt des Dritten Krieges stieß Malfurion am Weltenbaum Nordrassil in das Horn des Cenarius und rief Tausende uralter Waldgeister (Irrlichter) herbei. Diese Geister umschwärmten den Dämonenlord Archimonde und detonierten, wodurch der Dämon vernichtet und der Weltenbaum verzehrt wurde, um Kalimdor zu retten.",al={"malfurion hyjal","schlacht um den hyjal malfurion","wie besiegte malfurion archimonde"}}},fx={["65d9a7b2"]={q="Wer ist Malfurion Sturmgrimm?",a="Malfurion Sturmgrimm ist der erste sterbliche Druide auf Azeroth und der oberste Erzdruide der Nachtelfen. Vor zehntausend Jahren vom Halbgott Cenarius ausgebildet, führte er sein Volk durch den kataklysmischen Krieg der Ahnen gegen Königin Azshara und die Brennende Legion. An der Seite seiner Geliebten, der Hohepriesterin Tyrande Wisperwind, führt er die Kaldorei seit Jahrtausenden und dient ihnen sowohl als geistiger Führer als auch als größter Verteidiger der natürlichen Welt.",al={"wer ist malfurion","wer ist furion","geschichte von malfurion sturmgrimm"}},af86ea6f={q="Auf wessen Seite steht Malfurion Sturmgrimm?",a="Malfurion steht an vorderster Front für sein Volk, die Kaldorei, und den Zirkel des Cenarius, der sich dem Erhalt der natürlichen Ordnung Azeroths verschrieben hat. Durch die jüngsten Pakte der Nachtelfen ist sein Volk mit der Großen Allianz verbündet, obwohl Malfurions ultimative Hingabe über kleinliche politische Streitigkeiten hinausgeht – seine lebenslange Pflicht ist es, das Gleichgewicht der Natur zu schützen und den Smaragdgrünen Traum vor Verderbnis zu bewahren.",al={"fraktion von malfurion","ist malfurion bei der allianz","welcher fraktion gehört malfurion an"}},["1592db0d"]={q="Was will Malfurion Sturmgrimm?",a="Über alles andere stellt Malfurion das Streben, das empfindliche natürliche Gleichgewicht Azeroths zu schützen und den Smaragdgrünen Traum vor dunklen Mächten sicher zu halten. Da er zehntausend Jahre lang so viel geopfert hat, um die vernarbte Erde zu heilen und dämonische Einfälle zu besiegen, ist sein Leben an den Schutz der Wildnis, die Pflege des Weltenbaums und das Leiten der Nachtelfen auf einem Pfad im Einklang mit der Natur gebunden.",al={"ziel von malfurion","was sind malfurions ziele","zweck von malfurion"}}},fp="19,403,15.549.0,18.530.0,17.461.0,39.270.0,24.330.0,49.248.0,25.229.0,27.276.0,51.294.0"}
P.entries["npc:mangletooth"] = {n="Quetschzahn",s="Quetschzahn ist ein gefangener Stacheleber der Razormane, der von der Horde in Camp Taurajo festgehalten wird. Vor seiner Hinrichtung stehend, tauscht er strategische Informationen über seine Rivalen und das uralte Wissen über Agamaggan mit Abenteurern aus, die bereit sind, seine Befehle auszuführen.",h="Quetschzahn ist ein gefangener Stacheleber der Razormane, der von der Horde in Camp Taurajo festgehalten wird.",kw={"agamaggan","brachland","blutscherben","bristleback","camp taurajo","quetschzahn","stacheleber","razormane"},ang={["faction:Horde"]="Die Wachen von Camp Taurajo halten Quetschzahn unter strenger Bewachung eingesperrt, doch die Horde ist bereit, den bitteren Groll des Gefangenen zu nutzen, um die Hochburgen der Stacheleber im gesamten Brachland zu zerschlagen.",["race:Tauren"]="Taurenjäger geraten in den Ebenen ständig mit den Stachelebern aneinander, weshalb Quetschzahns Bereitschaft, sich gegen seine eigene Art zu wenden, ein wertvoller, wenn auch beunruhigender militärischer Vorteil ist."},sec={{t="Eine Geisel in Ketten",b="In einem Käfig in Camp Taurajo von Taurenjägern und Orc-Schildwachen bewacht, wartet der gefangene Razormane-Stacheleber Quetschzahn auf seine Hinrichtung. Anstatt sich in den Tod zu fügen, versucht er, seine Wärter und durchreisende Horde-Abenteurer dazu zu manipulieren, die Feinde seines Stammes niederzustrecken, in der Hoffnung, dass seine Schläue seinen Wert beweist oder seine Rettung sichert."},{t="Verräter in den eigenen Reihen",b="Quetschzahn plant zunächst, sich die Dankbarkeit seines Clans zu verdienen, indem er die Muskelkraft der Horde auf den verfeindeten Stamm der Bristleback lenkt. Bald muss er jedoch erkennen, dass seine Mit-Anführer der Razormane – Nak, Kuz und Lok Orcbane – ihn völlig im Stich gelassen haben. Wütend über diesen Verrat wendet der gefangene Stacheleber seine Rache gegen das eigene Volk und beauftragt Abenteurer damit, seine ehemaligen Verbündeten hinzurichten."},{t="Die Macht der Blutscherben",b="Quetschzahn ist bestens mit der religiösen Geschichte seines Volkes vertraut und weiß, dass die riesigen Dornen im Brachland einst aus dem vergossenen Blut von Agamaggan während des uralten Kriegs der Ahnen emporwuchsen. Indem er rote, kristalline Blutscherben von gefallenen Bristleback sammelt, kanalisiert Quetschzahn die verbliebene göttliche Energie des gefallenen Ebergottes und verleiht jenen, die ihm beistehen, gewaltige uralte Segen."}},faq={{q="Wer ist Quetschzahn?",a="Quetschzahn ist ein gefangener Stacheleber der Razormane, der in einem Käfig in Camp Taurajo festgehalten wird. Angesichts seiner bevorstehenden Hinrichtung durch die Horde feilscht er mit Abenteurern und bietet Führung sowie uralte Segen im Austausch für die Beseitigung seiner Rivalen.",al={"quetschzahn","wer ist quetschzahn","eingesperrter stacheleber taurajo"}},{q="Warum sitzt Quetschzahn in einem Käfig?",a="Er wurde während der Zusammenstöße zwischen der Horde und den Stachelebern im Südlichen Brachland gefangen genommen. Die Tauren und Orcs in Camp Taurajo halten ihn bis zu seiner Hinrichtung gefangen.",al={"warum ist quetschzahn gefangen","warum im käfig","warum taurajo gefangener"}},{q="Warum verlangt Quetschzahn den Angriff auf andere Razormane-Stacheleber?",a="Quetschzahn hat erkannt, dass seine Clangefährten Nak, Kuz und Lok Orcbane ihn dem Tod überließen, anstatt eine Rettung zu wagen. Erzürnt über ihren Verrat beauftragt er Reisende aus reiner Rachsucht mit ihrer Hinrichtung.",al={"warum razormane angreifen","verräter in den eigenen reihen lore","warum nak kuz töten"}},{q="Was sind Blutscherben?",a="Blutscherben sind kristalline Mineralien, die dort entstanden sind, wo das Blut des Großen Halbgottes Agamaggan in die Erde sickerte, als er während des Kriegs der Ahnen fiel. Bristleback-Stacheleber tragen sie oft bei sich.",al={"blutscherben","blutscherben lore","agamaggan blut"}},{q="Was kann man mit Blutscherben bei Quetschzahn tun?",a="Bringt Ihr Quetschzahn Blutscherben, kanalisiert er Agamaggans heilige Macht in temporäre Segen, die erhöhte Stärke, Beweglichkeit, Ausdauer, Willenskraft oder Schnelligkeit gewähren.",al={"blutscherben buffs","blutscherben abgeben","was gibt quetschzahn"}},{q="Wo starb Agamaggan laut Quetschzahn?",a="Quetschzahn berichtet, dass Agamaggan in der Schlacht während des Kriegs der Ahnen fiel. Sein vergossenes Blut ließ die gewaltigen Dornenranken sprießen, und sein kolossaler Schädel überwölbt eine Höhle im Süden.",al={"agamaggan lore","wo fiel agamaggan","ebergott schädel"}}},fx={d88e6e26={q="Auf wessen Seite steht Quetschzahn?",a="Quetschzahn dient nur sich selbst. Obwohl er von den Stachelmähnen-Ebermenschen abstammt, hegt er keine wahre Liebe für die Horde, die ihn gefangen nahm, noch anhaltende Loyalität gegenüber seinem eigenen Stamm, als er erkennt, dass seine Stammesgenossen ihn im Stich gelassen haben. Er kooperiert nur als verzweifeltes Mittel zum Überleben mit den Abenteurern der Horde, um zu überleben und gegen seine Rivalen zurückzuschlagen.",al={"seite von quetschzahn","wem gegenüber ist quetschzahn loyal","ist quetschzahn bei der horde"}},["7791b01e"]={q="Was will Quetschzahn?",a="Da ihm im Camp Taurajo die Hinrichtung droht, zielt Quetschzahn zunächst darauf ab, zu überleben und die Vorherrschaft seines Stammes über seine Borstennacken-Rivalen zu beweisen, in der Hoffnung, dass sein Volk ihn retten wird. Als er erkennt, dass seine Anführer der Stachelmähnen – Nak, Kuz und Lok Orcbane – ihn im Stich gelassen haben, wandeln sich seine Wünsche in bittere Rache und das Sammeln der heiligen Macht von Blutsplittern.",al={"was will quetschzahn","ziel von quetschzahn","was versucht quetschzahn zu tun"}},["1234667b"]={q="Mit wem ist Quetschzahn verbunden?",a="Quetschzahn gehört zu den Stachelmähnen-Ebermenschen des Südlichen Brachlands. Sein Schicksal ist mit seinen Stammesrivalen Nak, Kuz und Lok Orcbane verflochten, deren Verrat seinen Zorn antreibt. Er verehrt zudem den uralten Eber-Gott Agamaggan, dessen verstreute Essenz es Quetschzahn erlaubt, denjenigen Segnungen zu verleihen, die ihm Relikte des Blutes des gefallenen Gottes bringen.",al={"verbindungen von quetschzahn","wen kennt quetschzahn","stamm von quetschzahn"}}},fp="11,237,19.339.0,20.389.1,25.399.0,19.213.0,29.171.0,64.201.1,22.209.0,49.182.0,42.201.0"}
P.entries["npc:mankrik"] = {n="Mankrik",s="Mankrik ist ein von Trauer überwältigter Orc-Krieger, der im Wegekreuz im Brachland stationiert ist. Nachdem ihn ein heimtückischer Hinterhalt der Quilboar von seiner Frau Olgra getrennt hatte, widmete er sein Leben der Rache und der Vernichtung jeder borstigen Bestie, die er finden kann.",h="Mankrik ist ein von Trauer überwältigter Orc-Krieger, der im Wegekreuz im Brachland stationiert ist.",kw={"brachland","das wegekreuz","goldstraße","mankrik","olgra","quilboar","thork"},ang={["faction:Horde"]="Für Reisende, die im Wegekreuz ankommen, dient Mankriks Not als eindringliche Warnung vor der unerbittlichen Bedrohung durch die borstigen Quilboar-Rudel im gesamten Brachland.",["race:Orc"]="Mankrik verkörpert den verheerenden Preis für die Besiedlung der wilden Grenzlande von Kalimdor, wo Familie und Ehre ständig gegen brutale einheimische Gefahren auf die Probe gestellt werden."},sec={{t="Hinterhalt im Staub",b="Auf ihrer Reise durch das Buschland des Brachlands wurden Mankrik und seine Frau Olgra während eines Scharmützels in einer kleinen Taurensiedlung von Scharen von Quilboar überrannt. Im Chaos und den erbitterten Kämpfen getrennt, sah Mankrik mit an, wie Olgra unter einer Flut von Hauern und dornenbewehrten Waffen verschwand. Von Wut übermannt, kämpfte er rücksichtslos, bis er bewusstlos niedergeschlagen wurde. Er überlebte nur, weil ein vorbeiziehender Tauren-Druide ihn verblutend an der Goldstraße fand und seine Wunden verband."},{t="Von Rache zerfressen",b="Während er sich im Wegekreuz erholte, war Mankrik gelähmt von Trauer und einer alles verzehrenden Blutgier. Obwohl örtliche Anführer wie Thork warnen, dass sein blinder Hass sein Urteilsvermögen trübt, und sich weigern, offizielle Kriegstrupps aufzustellen, lässt Mankrik nicht von seinem Vorhaben ab. Geplagt von der Ungewissheit über Olgras Schicksal, heuert er jeden hilfsbereiten Reisenden der Horde an, das Brachland nach Spuren seiner verlorenen Gefährtin abzusuchen und jeden Quilboar abzuschlachten, der ihren Weg kreuzt."}},faq={{q="Wer ist Mankrik?",a="Mankrik ist ein Orc-Krieger, der sich im Wegekreuz im Brachland aufhält. Er überlebte einen brutalen Hinterhalt der Quilboar, der ihn von seiner Frau trennte, und ist seither von Zorn zerfressen und auf Rache für sie aus.",al={"mankrik lore","wer ist mankrik","mankrik geschichte"}},{q="Was geschah mit Mankriks Frau?",a="Während eines Gefechts in einer Taurensiedlung wurden Mankrik und Olgra durch eine Übermacht an Quilboar voneinander abgeschnitten. Mankrik wurde im Chaos niedergestreckt, und Olgra ging in den Wirren der Kämpfe verloren.",al={"mankriks frau","wo ist mankriks frau","was geschah mit olgra","olgras schicksal"}},{q="Wie überlebte Mankrik den Kampf?",a="Nachdem er unter Scharen von Quilboar das Bewusstsein verloren hatte, wurde Mankrik von einem umherziehenden Tauren-Druiden zusammengebrochen auf der Goldstraße gefunden, der seine schweren Wunden versorgte und ihn in Sicherheit brachte.",al={"wie überlebte mankrik","wer rettete mankrik"}},{q="Warum weigert sich Thork, Mankrik zu helfen?",a="Thork, der Anführer im Wegekreuz, glaubt, dass Mankriks maßlose Wut und sein Rachedurst sein Urteilsvermögen vollkommen vernebelt haben und ihn daran hindern, vernünftig zu handeln.",al={"warum hilft thork nicht","thork und mankrik"}}},fx={["63979fed"]={q="Auf wessen Seite steht Mankrik?",a="Mankrik ist der Horde gegenüber loyal. Von Das Wegekreuz im Brachland aus operierend, verlässt er sich auf Reisende und Abenteurer der Horde, die ihm bei seiner verzweifelten Suche helfen und gegen die Stacheleber zurückschlagen, die ihr Land bedrohen.",al={"mankrik fraktion","ist mankrik horde","mankrik allianz oder horde"}},["20b8339c"]={q="Was will Mankrik?",a="Mankrik möchte das Schicksal seiner verschollenen Frau Olgra erfahren und so viele Stacheleber wie möglich töten. Nachdem er bei einem Hinterhalt von ihr getrennt wurde, ist er von Trauer, Wut und einem Bedürfnis nach Rache gegen die borstigen Plünderer erfüllt.",al={"wonach sucht mankrik","mankrik ziel","was braucht mankrik"}},["5eb75604"]={q="Warum ist Mankrik hier am Wegekreuz?",a="Nach einem Angriff der Stacheleber, bei dem er schwer verwundet wurde, zog ein vorbeikommender Taurendruide Mankrik die Goldstraße entlang in Sicherheit. Mankrik bleibt nun am Wegekreuz, da ihn seine Verletzungen und die anhaltende Ungewissheit in der Nähe des Ortes halten, an dem er seine Frau zuletzt gesehen hat.",al={"warum ist mankrik am wegekreuz","grund für mankriks aufenthaltsort","warum ist mankrik im brachland"}},d34d6f35={q="Mit wem ist Mankrik verbunden?",a="Mankrik ist durch Liebe und Trauer mit seiner Frau Olgra verbunden, an deren Seite er kämpfte, bevor sie von Stachelebern überrannt wurden. Er verdankt sein Leben zudem dem umherwandernden Taurendruiden, der seine Wunden auf der Goldstraße versorgte.",al={"mankriks beziehungen","mit wem ist mankrik verbunden","mankriks familie"}}},fp="7,244,18.488.0,21.432.0,15.194.0,32.198.0,35.186.0,38.175.0"}
P.entries["npc:marcus-redpath"] = {n="Marcus Redpath",s="Marshal Marcus Redpath ist die höchste militärische Autorität, die die Allianz-Stadt Süderstade im Vorgebirge des Hügellands verteidigt. Er dient der Stadt bereits seit der Zeit vor dem Zweiten Krieg und organisiert nun Patrouillen und Kopfgeldaufträge, um die umliegenden Oger, Murlocs und Naga abzuwehren. Seine Führung ist entscheidend, um Lordaerons letzte südliche Bastion an der Küste zu halten.",h="Marshal Marcus Redpath ist die höchste militärische Autorität, die die Allianz-Stadt Süderstade im Vorgebirge...",kw={"anduin lothar","crushridge","dorfvorsteher","hillsbrad","marcus redpath","marshal","süderstade","terenas"},ang={["faction:Alliance"]="Marshal Redpath versorgt die Champions der Allianz mit wichtigen Aufgaben, um Hillsbrad gegen eindringende Oger und Gefahren an der Küste zu sichern.",["race:Human"]="Redpath ist eine lebende Verbindung zu den Anfängen der Großen Allianz, da er Anduin Lothar und die Flüchtlinge aus Sturmwind begrüßte, als sie zum ersten Mal nach Norden flohen."},sec={{t="Ein Wächter von Süderstade",b="Marcus Redpaths Dienste für Süderstade umspannen Jahrzehnte. Vor Jahren, bevor der Zweite Krieg den Norden verschlang, diente er als Dorfvorsteher, der Lord Anduin Lothar, den jungen Magier Khadgar und Tausende erschöpfte Flüchtlinge empfing, die vor der Plünderung von Sturmwind flohen. Da er den Ernst ihrer Lage erkannte, schickte er seinen schnellsten Kurier nach Norden, um König Terenas Menethil II. zu alarmieren, und spielte damit eine frühe Rolle bei der Schmiedung der Großen Allianz von Lordaeron. Während des Falls der Hauptstadt und der verheerenden Invasion der Geißel blieb Redpath auf seinem Posten und wechselte vom zivilen Verwalter zum militärischen Marshal, um die bedrängten Überlebenden des Hafens zu beschützen."},{t="Die Küste halten",b="Nach dem Dritten Krieg steht Süderstade praktisch allein gegen feindliche Streitkräfte, die von allen Seiten andrängen. Marshal Redpath koordiniert Verteidigungsoperationen im gesamten Vorgebirge des Hügellands und rekrutiert erfahrene Abenteurer, um die Crushridge-Oger zurückzudrängen, die aus Alterac herabkriechen, und um gefährliche Lager der Naga und Murlocs entlang der Küste zu säubern. Da die Verlassenen den Norden besetzen und Tarrens Mühle in der Nähe schwer befestigt ist, ist Redpaths Wachsamkeit eines der wenigen Bollwerke, das verhindert, dass die regionale Präsenz der Allianz vollständig zusammenbricht."}},faq={{q="Wer ist Marcus Redpath?",a="Marcus Redpath ist der Marshal und militärische Kommandant von Süderstade im Vorgebirge des Hügellands. Er war ursprünglich der Dorfvorsteher während des Zweiten Krieges und beaufsichtigt nun die lokale Verteidigung gegen Bedrohungen aus der umliegenden Wildnis und feindselige Nachbarn.",al={"lore über marcus redpath","wer ist der marshal in süderstade","informationen zu marcus redpath"}},{q="Welche Rolle spielte er im Zweiten Krieg?",a="Als das Königreich Sturmwind an die Orcische Horde fiel, landeten Flüchtlinge unter der Führung von Anduin Lothar und Khadgar in Süderstade. Redpath hieß sie willkommen und sandte sofort seinen Reiter Willem aus, um König Terenas Menethil II. in Capital City zu benachrichtigen.",al={"marcus im zweiten krieg","traf marcus redpath lothar"}},{q="Auf welche Bedrohungen konzentriert er sich bei der Verteidigung?",a="Redpath organisiert militärische Anstrengungen gegen lokale Raubtiere und Eindringlinge, die Süderstade bedrohen. Er setzt Kopfgelder aus und vergibt Missionen, die auf den Ogerstamm der Crushridge im Vorgebirge von Alterac, Murlocs an der Küste und plündernde Naga abzielen.",al={"quests von marcus redpath","was soll laut redpath getötet werden"}},{q="Ist er mit den Redpaths aus Darrowshire verwandt?",a="Obwohl er den Nachnamen Redpath teilt, der durch Hauptmann Joseph Redpath aus Darrowshire in den Östlichen Pestländern berühmt wurde, konnte keine direkte Verwandtschaft nachgewiesen werden, die über ihre gemeinsame Herkunft im Königreich Lordaeron hinausgeht.",al={"familie redpath","ist marcus mit joseph redpath verwandt","verwandte von redpath"}},{q="Wo ist Marcus Redpath zu finden?",a="Marshal Redpath ist im Zentrum von Süderstade stationiert, einem Zufluchtsort der Allianz an der Südküste des Vorgebirges des Hügellands.",al={"wo ist marcus redpath","standort von marcus redpath"}}},fx={["0aeeadbf"]={q="Auf wessen Seite steht Marcus Redpath?",a="Marschall Marcus Redpath dient der Allianz und den Überlebenden von Lordaeron, die sich unter dem Banner von Süderstade versammelt haben. Als Stadtmarschall von Süderstade steht er fest an der Seite der menschlichen Verteidiger, die die Hillsbrad-Front gegen feindliche Bedrohungen in den Ausläufern halten.",al={"marcus redpath fraktion","welcher fraktion gehört marcus redpath an","wem dient redpath"}},["43107ef7"]={q="Was will Marcus Redpath?",a="Redpath möchte Süderstade und das umliegende Land vor eindringenden Gefahren schützen. Er leitet aktiv Soldaten und Abenteurer an, regionale Bedrohungen zu beseitigen, die Ogerstämme der Crushridge aus den nördlichen Bergen zurückzudrängen und die Murloc- und Naga-Plagen auszurotten, die die Küste heimsuchen.",al={"marcus redpaths ziele","was braucht redpath","marcus redpaths aufgabe"}},d9a0669f={q="Warum ist Marcus Redpath hier?",a="Marcus Redpath betrachtet Süderstade schon lange als sein Zuhause und dient seit den Tagen des Zweiten Krieges als dessen Hauptmann. Nach dem Fall von Lordaeron im Dritten Krieg übernahm er die Aufgaben des Stadtmarschalls, um die örtliche Verteidigung zu organisieren und in einer der letzten Bastionen der Allianz in der Region für Ordnung zu sorgen.",al={"warum ist marcus redpath in süderstade","grund für redpaths aufenthalt in süderstade","was macht redpath hier"}}},fp="14,364,24.648.0,17.550.0,22.246.0,40.247.0,39.227.0,45.222.0,34.134.0"}
P.entries["npc:mardant-strongoak"] = {n="Mardant Starkeiche",s="Mardant Starkeiche ist ein Druidenlehrer der Nachtelfen, der in Aldrassil im Herzen von Teldrassil weilt. Er leitet angehende Druiden bei der Zwiesprache mit den Geistern der Natur an und weiht sie in die Geheimnisse des Smaragdgrünen Traums ein.",h="Mardant Starkeiche ist ein Druidenlehrer der Nachtelfen, der in Aldrassil im Herzen von Teldrassil weilt.",kw={"aldrassil","druide","smaragdgrüner traum","mardant","laubschattental","strongoak","teldrassil","lehrer"},ang={["class:Druid"]="Für junge Nachtelfen-Druiden ist Mardant Starkeiche die erste Brücke zwischen dem weltlichen Dasein und den heiligen Pflichten des Zirkels des Cenarius.",["race:NightElf"]="Im Herzen von Aldrassil stationiert, verkörpert Mardant die Hingabe der Kaldorei, mit Teldrassils aufblühendem Ökosystem in Einklang zu leben."},sec={{t="Ausbilder der Wildnis",b="In den Ästen von Aldrassil wenden sich junge Nachtelfen, die den Ruf der Wildnis vernehmen, an Mardant Starkeiche. Seine Hauptaufgabe besteht darin, Novizen beizubringen, ihre Sinne für die Naturgeister zu öffnen, deren Flüstern zu deuten und verjüngende Magie zu wirken. Für jene, die ihre ersten Schritte als Beschützer der Wildnis wagen, ist er oft der erste Meister, der die gewaltigen Tiefen und uralten Gefahren des Smaragdgrünen Traums enthüllt."}},faq={{q="Wer ist Mardant Starkeiche?",a="Mardant Starkeiche ist ein Druidenlehrer der Nachtelfen, der in Laubschattental in Aldrassil stationiert ist. Er unterweist neu erwachte Druiden auf Teldrassil in den grundlegenden Künsten der Zwiesprache und des Zauberwirkens.",al={"mardant starkeiche lore","wer ist mardant","mardant aldrassil"}},{q="Was lehrt er neue Druiden?",a="Er lehrt Novizen, wie sie die Botschaften der wilden Geister entschlüsseln, grundlegende Zauber wie Mondfeuer und Heilkünste wirken und das Wesen des Smaragdgrünen Traums erfassen.",al={"was lehrt mardant","mardant fähigkeiten","druidenlehrer laubschattental"}},{q="Wo kann ich Mardant Starkeiche finden?",a="Er befindet sich innerhalb oder nahe Aldrassil in Laubschattental, dem Starttal für Nachtelfen-Abenteurer auf Teldrassil.",al={"mardant aufenthaltsort","wo ist mardant starkeiche"}},{q="Was ist das Tiefgrüne Siegelzeichen?",a="Das Tiefgrüne Siegelzeichen ist ein Lehrabzeichen, das angehenden Nachtelfen-Druiden in Laubschattental überreicht wird und sie anweist, Mardant Starkeiche für ihre frühe Ausbildung aufzusuchen.",al={"quest tiefgrünes siegelzeichen","siegelzeichen für mardant"}}},fx={a3bbc1b2={q="Auf wessen Seite steht Mardant Starkeiche?",a="Mardant Starkeiche ist den Nachtelfen, der Allianz und den heiligen Grundsätzen des Zirkels des Cenarius ergeben. Er steht fest im Laubschattental, um den jungen Weltenbaum zu schützen und sicherzustellen, dass die Traditionen der Kaldorei-Druiden in diesen unsicheren Zeiten fortbestehen.",al={"mardant starkeiche fraktion","wem dient mardant","ist mardant allianz"}},ff8559f4={q="Was will Mardant Starkeiche?",a="Mardant möchte, dass junge Nachtelfen-Initianden ihre Verbindung zur Natur vertiefen. Er versucht, neue Druiden durch ihre ersten Prüfungen zu führen und ihnen dabei zu helfen, das Flüstern der Geister zu entschlüsseln sowie die tiefgreifenden Geheimnisse und Gefahren des Smaragdgrünen Traums zu meistern.",al={"was will mardant","mardant starkeiches ziele","was ist mardants ziel"}},b78651d9={q="Warum ist Mardant Starkeiche hier?",a="Stationiert in den hohlen Ästen von Aldrassil, dient Mardant als Mentor für neu erwachte Druiden, die ihre ersten Schritte in Teldrassil machen. Er bleibt im Laubschattental, um über die Novizen zu wachen, sie in ihren angeborenen Kräften zu unterweisen und sie zu denjenigen zu schicken, die Hilfe benötigen.",al={"warum ist mardant in aldrassil","warum ist mardant starkeiche hier","grund für mardant starkeiches aufenthaltsort"}},dec3bef7={q="Mit wem ist Mardant Starkeiche verbunden?",a="Mardant ist eng mit dem Zirkel des Cenarius und seinen Mitlehrenden in Aldrassil verbunden, wie etwa den Priesterinnen der Elune und den Wächterinnen, die das Sanktuarium beschützen. Gemeinsam leiten und fördern sie die jungen Verteidiger der Nachtelfen.",al={"mardant starkeiches verbündete","mit wem ist mardant verbunden","mardants verbindungen"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marek-ironheart"] = {n="Marek Eisenherz",s="Marek Eisenherz ist ein erfahrener zwergischer Jäger, der in der Weitschreiter-Lodge im südöstlichen Loch Modan stationiert ist. Er ist den Traditionen der Wildnis verpflichtet und prüft sowohl wandernde Reisende als auch Schützen, bevor er sie in die Reihen der angesehenen Jäger der Lodge aufnimmt.",h="Marek Eisenherz ist ein erfahrener zwergischer Jäger, der in der Weitschreiter-Lodge im südöstlichen Loch...",kw={"krokiliskenjagd","die weitschreiter-lodge","jäger","jagd","ironheart","loch modan","marek eisenherz"},ang={["class:Hunter"]="Für Waldläufer und Bestienjäger repräsentiert Marek Eisenherz die rauen Traditionen der Weitschreiter-Lodge und fordert Jäger dazu auf, ihre Treffsicherheit und ihre Fähigkeiten als Fährtenleser an der lokalen Tierwelt unter Beweis zu stellen.",["race:Dwarf"]="Marek verkörpert die Kultur der Naturfreunde, die von vielen Zwergen in Khaz Modan geschätzt wird, indem er die stille Wache in den Bergen dem lärmenden Schmiedefeuer von Eisenschmiede vorzieht."},sec={{t="Meister der Jagd",b="Die auf dem malerischen Grat mit Blick auf den See gelegene Weitschreiter-Lodge dient als Außenposten für die besten Schützen und Fährtenleser in den Zwergenlanden. Marek Eisenherz verkörpert diesen Pioniergeist. Marek ist von Titeln oder Gerede unbeeindruckt und verlangt von jedem, der den Respekt der Lodge sucht, dass er sein praktisches Können an den verschiedenen Bestien beweist, die Loch Modan durchstreifen, um zu beweisen, dass er die Geduld und die Nerven besitzt, die von einem wahren Jäger der Wildnis gefordert werden."}},faq={{q="Wer ist Marek Eisenherz?",a="Marek Eisenherz ist ein zwergischer Jäger, der in der Weitschreiter-Lodge in Loch Modan lebt. Er prüft Besucher, die Anerkennung in der Gemeinschaft der Fährtenleser und Naturfreunde der Lodge suchen.",al={"marek eisenherz","wer ist marek"}},{q="Wo finde ich Marek Eisenherz?",a="Er befindet sich in der Weitschreiter-Lodge, die in den Hügeln am südöstlichen Ufer von Loch Modan liegt.",al={"standort marek eisenherz","wo ist marek"}},{q="Welche Art von Aufgaben bietet Marek an?",a="Marek weist Jäger an, verschiedene lokale Wildtiere rund um den Loch aufzuspüren und zu dezimieren, wobei er ihre Überlebensfähigkeiten gegen gefährliche Krokolisken testet.",al={"marek eisenherz quests","marek quests"}},{q="Ist Marek mit anderen bekannten Zwergen verwandt?",a="Da er einen bekannten zwergischen Nachnamen trägt, könnte er mit dem Archäologen Adamant Ironheart und Imme Ironheart verwandt sein, obwohl Marek sein Leben der Jagd widmet und nicht der Ausgrabung von Relikten.",al={"familie ironheart","marek verwandte"}}},fx={ac3880c9={q="Auf wessen Seite steht Marek Eisenherz?",a="Marek steht an der Seite der Allianz und der Zwergenklans von Eisenschmiede. Von der Die Weitschreiter-Lodge in der südöstlichen Wildnis von Loch Modan aus operierend, heißt er andere Abenteurer der Allianz willkommen, damit sie ihr Können beweisen, indem sie die umliegende Wildnis meistern.",al={"marek eisenherz fraktion","marek eisenherz allianz","ist marek eisenherz allianz"}},["2928b65a"]={q="Was will Marek Eisenherz?",a="Marek arbeitet von der Die Weitschreiter-Lodge in Loch Modan aus, wo er Jäger dazu einlädt, Jagd auf die Krokoliske rund um den Loch zu machen.",al={"was will marek","marek eisenherz ziele","warum sollte man mit marek eisenherz sprechen"}},ddec60fb={q="Warum ist Marek Eisenherz bei der Die Weitschreiter-Lodge?",a="Marek hat sein Zuhause in der Die Weitschreiter-Lodge, um Waldläufer in den ungezähmten Hügeln von Loch Modan zu prüfen und auszubilden. Von diesem abgelegenen Außenposten aus wacht er über die lokale Tierwelt und führt Jäger, die ihre Fähigkeiten in der Wildnis der Hochlande verfeinern wollen.",al={"warum ist marek in loch modan","marek eisenherz zweck der die weitschreiter-lodge","warum ist marek hier"}}},fp="15,264,18.444.0,23.177.0,33.104.0,36.144.0,44.176.0"}
P.entries["npc:marisa-du-paige"] = {n="Marisa du'Paige",s="Marisa du'Paige ist eine seltene abtrünnige menschliche Zauberin, die im weitläufigen Höhlennetzwerk vor dem Eingang zu den Todesminen im südwestlichen Westfall lauert. Verbündet mit den Gesetzlosen, die unter Mondbruch operieren, wirkt sie arkane Magie an der Seite der Arbeiter und Wegelagerer, die die Tunnel bewachen.",h="Marisa du'Paige ist eine seltene abtrünnige menschliche Zauberin, die im weitläufigen Höhlennetzwerk vor dem...",kw={"die todesminen","mensch","magier","marisa du'paige","marisa dupaige","mondbruch","selten","westfall"},ang={["class:Mage"]="Marisa du'Paige ist eine Erinnerung daran, dass arkane Ausbildung im Königreich nicht auf die Türme der Kirin Tor oder das Magiersanktum von Sturmwind beschränkt ist; abtrünnige Zauberwirker verkaufen ihre Talente bereitwillig an kriminelle Netzwerke.",["faction:Alliance"]="Abenteurer der Allianz, die die Tunnel unter Mondbruch auskundschaften, müssen vor du'Paige auf der Hut sein, da eine unerwartete Zauberin inmitten von Horden von Beutelschneidern ein Scharmützel schnell tödlich enden lassen kann."},sec={{t="Arkanes Talent in den Tunneln",b="Tief in den verwinkelten Höhlen, die zu den Todesminen unter Mondbruch führen, sind die meisten Verteidiger raubeinige Beutelschneider, abtrünnige Minenarbeiter und Schläger. Marisa du'Paige sticht unter ihnen als geschickte menschliche Magierin hervor. Während die meisten Zauberwirker des Königreichs in den sanktionierten Hallen von Sturmwinds Magierviertel trainieren oder den Kirin Tor dienen, hat sich du'Paige den Gesetzlosen und Banditen angeschlossen, die sich in den unterirdischen Tiefen von Westfall verstecken."}},faq={{q="Wer ist Marisa du'Paige?",a="Marisa du'Paige ist eine seltene menschliche Magierin, die im äußeren Höhlensystem lauert, das in die Todesminen führt. Im Gegensatz zu den typischen gewöhnlichen Dieben und Arbeitern, die diese Gänge patrouillieren, setzt sie arkane Zauber zur Verteidigung des unterirdischen Netzwerks ein.",al={"marisa dupaige","wer ist marisa","selten in todesminen-höhle"}},{q="Wo ist sie zu finden?",a="Sie erscheint unregelmäßig im öffentlichen Höhlensystem unter Mondbruch in Westfall, in den Tunneln kurz vor der Portalschwelle der Instanz Die Todesminen.",al={"marisa du'paige aufenthaltsort","wo ist marisa dupaige","marisa spawn"}},{q="Warum versteckt sich eine menschliche Magierin in den Höhlen der Todesminen?",a="Nicht jeder arkan Kundige bleibt den hohen Türmen von Sturmwind treu. Deserteure, Abtrünnige und sympathisierende Bürgerliche haben sich überall in Westfall der Sache der Gesetzlosen angeschlossen und stellen ihren Befestigungen unter Mondbruch sowohl Stahl als auch Zauberei zur Verfügung.",al={"warum ist sie hier","marisa lore","marisa dupaige fraktion"}}},fx={["5e8e0d23"]={q="Auf welcher Seite steht Marisa du'Paige?",a="Marisa du'Paige trägt die Gewänder der The Defias Brotherhood und wandelt durch die unterirdischen Hallen der Organisation. Sie lauert tief in den Höhlen von Mondbruch, die zu den Todesminen führen, und unterstützt die aufrührerische Bruderschaft von Edwin van Cleef, indem sie ihre arkanen Zauber gegen jeden Eindringling einsetzt, der ihre Festung bedroht.",al={"marisa dupaige fraktion","ist marisa dupaige defias","für wen arbeitet marisa dupaige"}}},fp="15,299,28.436.0,23.241.0,23.162.0,50.248.0"}
P.entries["npc:marleth-barleybrew"] = {n="Marleth Gerstenbräu",s="Marleth Gerstenbräu ist eine ehrgeizige Zwergenbrauerin, die in Bräuhall stationiert ist. Frustriert über die Dominanz des Donnerbräu-Klans auf dem lokalen Biermarkt schmiedet sie ständig Pläne, um zu beweisen, dass das Gebräu ihrer Familie Kharanos' berühmtem Donnerbier überlegen ist.",h="Marleth Gerstenbräu ist eine ehrgeizige Zwergenbrauerin, die in Bräuhall stationiert ist.",kw={"bittere rivalen","brewnall","zwergenbrauer","kharanos","marleth gerstenbräu","donnerbier","donnerbräu"},ang={["race:Dwarf"]="Für Zwerge ist das Brauen eine Kunstform, die eng mit dem Prestige des Klans verknüpft ist, was Marleths Fehde mit den Donnerbräus zu einer Frage heftigen Familienstolzes macht."},sec={{t="Die Brau-Rivalität",b="In Dun Morogh nimmt man Alkohol so ernst wie Stahl, und die Rivalität zwischen den Familien Gerstenbräu und Donnerbräu ist legendär. Marleth Gerstenbräu ärgert sich über das Beinahe-Monopol, das Ragnar Donnerbräu und seine Sippe von der Brauerei Donnerbräu in Kharanos aus aufrechterhalten. Überzeugt davon, dass ihr eigenes Handwerk genauso robust ist, sucht sie nach cleveren Wegen, den Tavernenbesuchern Fässer der Gerstenbräus unterzuschieben. Anstatt sich auf einen offenen Konflikt einzulassen, entscheidet sie sich für kleine Sabotageakte und heuert durchreisende Abenteurer an, um die geschätzten Bierfässer von Kharanos heimlich gegen ihre eigenen auszutauschen."}},faq={{q="Wer ist Marleth Gerstenbräu?",a="Marleth ist eine Zwergenbraumeisterin, die in Bräuhall im westlichen Dun Morogh lebt. Sie vertritt die Familie Gerstenbräu und arbeitet aktiv daran, den Würgegriff der rivalisierenden Familie Donnerbräu auf die lokale Trinkerszene zu brechen.",al={"wer ist marleth","marleth lore","marleth gerstenbräu"}},{q="Wo finde Ich Marleth Gerstenbräu?",a="Sie befindet sich in Bräuhall, gelegen in den westlichen Gefilden von Dun Morogh nahe dem Eiswellensee.",al={"marleth standort","wo ist marleth","marleth finden"}},{q="Warum möchte Marleth das Bier von Donnerbräu austauschen?",a="Marleth glaubt, dass das Bier ihrer Familie genauso gut, wenn nicht sogar besser als Donnerbier ist. Da die Donnerbräus den Handel in Kharanos dominieren, heuert sie Abenteurer an, um heimlich die Fässer der Taverne durch Gerstenbräu-Vorräte zu ersetzen, damit die Zecher ihr Produkt kosten, und ihr zugleich eine Probe des Donnerbiers zur Analyse mitzubringen.",al={"warum das bier austauschen","bittere rivalen quest grund","warum hass auf donnerbräus"}},{q="Wer sind die anderen Mitglieder der Gerstenbräu-Familie?",a="Zu ihrem erweiterten Klan gehören weitere bekannte Brauer und Handwerker wie Malgin, Rejold, Wellart und Yorus Gerstenbräu, die sich alle der traditionellen Zwergenbraukunst verschrieben haben.",al={"familie gerstenbräu","marleth verwandte"}}},fx={c401045b={q="Auf wessen Seite steht Marleth Gerstenbräu?",a="Marleth ist eine stolze Zwergin aus Eisenschmiede und der Allianz gegenüber loyal, obwohl sich ihr unmittelbarer täglicher Fokus rein auf das Geschäftliche richtet. Sie gehört zur Brauerfamilie Gerstenbräu und setzt sich vehement für ihr Handwerk gegen ihre lokalen Konkurrenten ein.",al={"marleth gerstenbräu zugehörigkeit","wem dient marleth gerstenbräu","marleth fraktion"}},["716c9dd7"]={q="Warum ist Marleth Gerstenbräu in Bräuhall?",a="Bräuhall dient als regionaler Brauaußenposten in den verschneiten Hügeln von Dun Morogh. Marleth operiert von hier aus, um ihr Handwerksbier zu produzieren und Pläne zu schmieden, wie sie in die größeren Märkte vordringen kann, die von den Thunderbrews monopolisiert werden.",al={"warum ist marleth hier","marleth gerstenbräu bräuhall","warum ist marleth gerstenbräu in dun morogh"}}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="Marryk Nurribit",s="Marryk Nurribit ist der ansässige Gnom-Magierlehrer in Ambossar im Coldridgetal. Er schätzt die lokalen Gebräue etwas mehr als disziplinierte Pädagogik und führt angehende gnomische Arkanisten in ihr Handwerk ein, während er sie häufig um ein paar Münzen für ein Getränk anhaut.",h="Marryk Nurribit ist der ansässige Gnom-Magierlehrer in Ambossar im Coldridgetal.",kw={"ambossar","bier","coldridge","gnom","magier","marryk","nurribit","lehrer"},ang={["class:Mage"]="Für angehende Gnom-Magier, die ihre Reise im Coldridgetal beginnen, ist Marryk der erste Lehrer, an den Ihr Euch für grundlegende Zauber und Euer Glyphenmemorandum wendet.",["race:Gnome"]="Flüchtlinge, die in Dun Morogh Zuflucht suchen, kennen Marryk als ein Beispiel für einen gnomischen Gelehrten, der sich ein wenig zu gut an die zwergische Gastfreundschaft in Tavernen gewöhnt hat."},sec={{t="Arkanstudien und Bier",b="Eingekuschelt am warmen Herd von Ambossar bietet Marryk Nurribit jungen Gnomen, die ihre allerersten Schritte in die Magie wagen, arkane Führung. Obwohl er in den arkanen Künsten bewandert ist, wirkt sein Auftreten ausgesprochen lässig – oft scheint er weit mehr daran interessiert zu sein, einen Humpen Zwergenbier zu leeren und seinen neuen Schülern etwas Kleingeld abzuluchsen, als sie in komplexen Theoremen zu unterrichten. Trotz seiner Laster ist sich Marryk der Gefahren außerhalb des Coldridgetals vollkommen bewusst und warnt angehende Zauberwirker regelmäßig vor den anhaltenden radioaktiven und von Troggs heimgesuchten Schrecken des gefallenen Gnomeregan."}},faq={{q="Wer ist Marryk Nurribit?",a="Marryk Nurribit ist ein Gnom-Magierlehrer in Ambossar im Coldridgetal von Dun Morogh. Er unterweist neu angekommene Gnom-Magier in den Grundlagen der Arkanmagie.",al={"marryk nurribit","wer ist marryk","ambossar magierlehrer"}},{q="Warum fragt Marryk ständig nach Geld für Bier?",a="Marryk ist dafür bekannt, die lokalen Spirituosen weit mehr zu genießen als strikte professionelle Zurückhaltung zu wahren. Er bedrängt seine Schüler regelmäßig um Kleingeld, um seine Trinkgewohnheiten in der Taverne zu finanzieren.",al={"marryk trinken","marryk bier","warum fragt er nach münzen"}},{q="Was sagt Marryk über Gnomeregan?",a="Trotz seiner entspannten Haltung gegenüber der Ausbildung erkennt Marryk echte Gefahren und warnt frische Magier wiederholt davor, die Gefahren zu unterschätzen, die in den verstrahlten Ruinen von Gnomeregan lauern.",al={"marryk gnomeregan","gnomeregan warnung"}}},fx={["42f80152"]={q="Auf wessen Seite steht Marryk Nurribit?",a="Marryk ist loyal gegenüber den Gnomeregangnomen und steht voll und ganz an der Seite der Allianz. Er sucht Schutz bei seinen zwergischen Gastgebern in Dun Morogh und bietet den jungen Gnomen, die das Das Coldridgetal betreten, seine arkanen Unterweisungen an.",al={"marryk nurribit fraktion","wem dient marryk","marryk zugehörigkeit"}},["241b0acf"]={q="Warum ist Marryk Nurribit in Ambossar?",a="Nach dem tragischen Fall von Gnomeregan durch die Trogg-Invasion und den giftigen radioaktiven Niederschlag flohen Marryk und seine überlebenden Verwandten nach Dun Morogh. Er hält sich nun in Ambossar im Das Coldridgetal auf und hat nominell die Aufgabe, angehende Gnom-Magier in den arkanen Künsten zu unterrichten.",al={"warum ist marryk hier","marryk nurribit ambossar","marryks zweck in dun morogh"}}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {n="Marschall Dughan",s="Marschall Dughan ist der kommandierende Offizier der in Goldhain stationierten Abteilung der Armee von Sturmwind. Mit dem Schutz des Herzens des Walds von Elwynn betraut, muss er erleben, wie seine örtliche Garnison angesichts wachsender Übergriffe von Kobolden, Gnollen und Banditen an ihre Grenzen stößt. Um die Kreuzungsstadt und die umliegenden Gehöfte zu schützen, verlässt er sich stark auf unabhängige Abenteurer.",h="Marschall Dughan ist der kommandierende Offizier der in Goldhain stationierten Abteilung der Armee von...",kw={"wald von elwynn","tiefenschacht","goldhain","hogger","jaspis","marschall dughan","armee von sturmwind","weststromgarnison"},ang={["class:Warrior"]="Für kriegerische Kämpfer verkörpert Dughan die mustergültige Disziplin und die logistische Belastung der Fußsoldaten von Sturmwind, die gegen eine überwältigende Übermacht die Stellung halten.",["faction:Alliance"]="Marschall Dughan verkörpert die vorderste Verwaltungsgewalt der Allianz in Elwynn und erteilt neu eingetroffenen Rekruten ihre ersten militärischen Aufträge im Namen von Sturmwind."},sec={{t="Kommandant des Wegekreuzes",b="Marschall Dughan, der gut sichtbar vor dem Gasthaus \"Zur Höhle des Löwen\" in Goldhain postiert ist, trägt die schwere Last, den Wald von Elwynn zu sichern, während die militärischen Ressourcen von Sturmwind andernorts gebunden sind. Der Zustand der umliegenden Wälder verschlechtert sich zusehends: Ungeziefer verstopft die Minen, Gnolle rotten sich an den Flussufern zusammen und Wegelagerer überfallen Reisende auf dem King's Road. Da ihm zu wenige Fußsoldaten unterstehen, organisiert Dughan die örtliche Verteidigung, indem er frische Rekruten aussendet, um Außenposten zu verstärken und umkämpftes Gebiet auszukundschaften."},{t="Bedrohungen an jeder Grenze",b="Dughans größte Sorge gilt den Koboldplagen, die die Tiefenschachtmine und die Jaspismine überrennen und Goldhains lebenswichtige Erzförderung gefährden. Im Westen setzen Flusstatzen-Gnolle unter der Führung des berüchtigten Hogger der Weststromgarnison hart zu. Im Osten muss sich Dughan mit Berichten von Wache Thomas über grausame Murlocs auseinandersetzen, die Patrouillen entlang des Flusses abschlachten. Die Bewältigung dieser gleichzeitigen Krisen mit begrenzter Mannstärke sorgt dafür, dass der Marschall ständig fähige Söldner benötigt."}},faq={{q="Wer ist Marschall Dughan?",a="Marschall Dughan ist ein Offizier der Armee von Sturmwind, der in Goldhain stationiert ist. Er überwacht die militärische Sicherheit im zentralen Wald von Elwynn und koordiniert die Verteidigungsmaßnahmen gegen lokale Gefahren wie Diebe, Gnolle und Kobolde.",al={"dughan","marschall dughan lore","goldhain marshal"}},{q="Warum schickt Dughan nicht mehr Wachen zur Weststromgarnison oder in den Osten?",a="Die Armee von Sturmwind ist überdehnt, sodass Dughan kaum genug Wachen zur Verfügung hat, um in Goldhain selbst für Ordnung zu sorgen. Da ihm die nötige Truppenstärke fehlt, um jeden abgelegenen Bauernhof und Grenzposten zu bemannen, ist er auf durchreisende Abenteurer angewiesen, die Brennpunkte auskundschaften, Depeschen überbringen und regionale Gefahren beseitigen.",al={"warum keine wachen","stärke der garnison goldhain","dughan truppen"}},{q="Wie steht Dughan zur Murloc-Bedrohung in Elwynn?",a="Anfangs tat Dughan die Warnungen von Remy „Zweimal“ ab, dass Murlocs eine ernsthafte Bedrohung für die Region darstellten. Die wahre Gefahr erkannte er erst, nachdem Wache Thomas tragische Berichte übermittelte, die den Tod der Wachmänner Rolf Hartford und Malakai Stone an den östlichen Wasserläufen bestätigten.",al={"dughan murlocs","remy zweimal murloc","dughan fischmenschen"}},{q="Wie geht Dughan mit lokaler Kriminalität und ungebärdigen Bürgern um?",a="Dughan setzt das Recht streng durch, spricht aber eine faire Warnung aus, bevor er Bürger hinter Gitter bringt. Wenn Einheimische oder Reisende in Goldhain für Unruhe sorgen, warnt er sie davor, dass fortgesetzte Raufereien sie direkt in das Verlies von Sturmwind bringen werden – und er sie unerbittlich jagen wird, falls sie einen Mord begehen.",al={"dughan verbrechen","goldhain recht","verlies drohung"}},{q="Warum bereiten Dughan die Minen Sorgen?",a="Die Tiefenschachtmine und die Jaspismine sind unverzichtbare Gold- und Erzquellen für Sturmwind. Kobolde haben beide unterirdischen Komplexe überrannt, die Bergleute vertrieben und drohen, ihre Stollen direkt unter die Siedlungen von Elwynn vorzutreiben.",al={"tiefenschachtmine dughan","jaspismine dughan","koboldplage"}},{q="Arbeitet Marschall Dughan mit Westfall zusammen?",a="Ja. Sobald ein Abenteurer sein Können im Wald von Elwynn unter Beweis gestellt hat, schickt Marschall Dughan ihn nach Westfall mit der Meldung bei Gryan Starkmantel auf der Späherkuppe, wo die Volksmiliz dringend erfahrene Hilfe gegen die Bruderschaft der Defias benötigt.",al={"dughan gryan","meldung in westfall","dughan späherkuppe"}}},fx={["72888056"]={q="Auf wessen Seite steht Marschall Dughan?",a="Marschall Dughan dient dem Königreich Sturmwind und der Allianz. Als Offizier in der Armee von Sturmwind untersteht er direkt der militärischen Hierarchie des Reiches und führt die Befehle der Krone aus, um die Ordnung aufrechtzuerhalten und das Kernland trotz schwindender königlicher Verstärkung zu schützen.",al={"dughan fraktion","wem dient dughan","marschall dughan zugehörigkeit"}},["9141816c"]={q="Was will Marschall Dughan?",a="Dughan zielt darauf ab, den Wald von Elwynn zu sichern und Goldhain vor zunehmenden Bedrohungen zu bewahren. Da seine Garnison überstrapaziert ist, sucht er nach fähigen Abenteurern, die die befallenen Fargodeep- und Jasperlode-Minen auskundschaften, die Defias-Banditen und Gnolle im Westen eindämmen und die wachsende Gefahr entlang der Flussufer einschätzen können.",al={"dughan ziel","was braucht dughan","dughan ziele"}},["8808e7de"]={q="Warum ist Marschall Dughan in Goldhain stationiert?",a="Dughan ist als Befehlshaber des örtlichen Abkommandos der Armee von Sturmwind in Goldhain stationiert. Er ist mit der Verteidigung des zentralen Wald von Elwynn betraut und beaufsichtigt die Friedenssicherung der Stadt, koordiniert Außenposten wie die Weststromgarnison und leitet die Verteidigung gegen eindringende Bestien, Kobolde und Kriminelle, die die Kornkammer der Hauptstadt bedrohen.",al={"warum ist dughan in goldhain","marschall dughan zweck hier","dughan posten"}},["156c33b1"]={q="Mit wem ist Marschall Dughan verbunden?",a="Dughan arbeitet eng mit örtlichen Außenpostenkommandanten im gesamten Wald von Elwynn zusammen, wie beispielsweise Stellvertreter Rainer in der Weststromgarnison und Wache Thomas entlang der östlichen Brücken. Außerhalb von Elwynn pflegt er die Kommunikation mit militärischen Kollegen wie Gryan Starkmantel in Westfall, um Informationen über kriminelle Aktivitäten in der Region auszutauschen.",al={"dughan verbindungen","mit wem arbeitet dughan zusammen","dughan verbündete"}}},fp="14,358,27.516.0,23.494.0,22.220.0,75.308.0,53.277.1,55.311.0,40.237.0,45.244.0"}
P.entries["npc:marshal-marris"] = {n="Marschall Marris",s="Marschall Marris ist der schwer bedrängte Militäroffizier, der die Stadtwache von Seenhain befehligt. Er ist nahe der Stadtbrücke stationiert und koordiniert die Verteidigungsoperationen gegen die gewaltige Invasion der Schwarzfelsorcs, die von den Höhen des Rotkammgebirges herabdrängen. Da Sturmwinds Armee abwesend ist, verlässt er sich auf durchreisende Abenteurer, um den Vormarsch der Horde abzuwehren.",h="Marschall Marris ist der schwer bedrängte Militäroffizier, der die Stadtwache von Seenhain befehligt.",kw={"schwarzfels","brücke","seenhain","marris","marschall marris","rotkammgebirge","steinwacht","tharil'zun"},ang={["class:Warrior"]="Marris schätzt geradlinige soldatische Disziplin und schickt fähige Frontkämpfer direkt in den Schlund von Steinwacht, um sich mit gestählten Schwarzfelsveteranen zu messen.",["faction:Alliance"]="Marschall Marris verkörpert die Notlage der ländlichen Gebiete der Allianz, die durch Sturmwinds politische Lähmung verwundbar zurückgelassen wurden und gezwungen sind, auf sich allein gestellt ums Überleben zu kämpfen.",["race:Human"]="Für die Menschen des Königreichs repräsentiert Marris die stoische, bedrängte Grenzwache, die gegen die Überreste der Alten Horde die Stellung hält."},sec={{t="Eine Stadt unter Belagerung",b="Seenhain steht am Rande des Zusammenbruchs, eingeklemmt zwischen den Gnollen im Westen und der furchterregenden militärischen Macht des Schwarzfelsklans im Osten. Marschall Marris überwacht die Verteidigungslinie an der Hauptbrücke der Stadt, doch seine Ressourcen sind erschöpft und seine Soldaten hoffnungslos überdehnt. Da das Königreich Sturmwind königliche Verstärkung zurückhält, trägt Marris die schwere Bürde, die Ortschaft davor zu bewahren, von schierer Gewalt überrannt zu werden."},{t="Die Vorhut des Schwarzfels brechen",b="In der Erkenntnis, dass Verteidigung allein das Rotkammgebirge nicht retten wird, plant Marris entschlossene offensive Schläge gegen die Lager der Orcs. Er beauftragt Söldner damit, die Krieger des Schwarzfelsklans auszudünnen, ihre Schattenzauberer auszuschalten und letztlich Tharil'zun zur Strecke zu bringen, den bedrohlichen Kommandanten, der sich in den Ruinen von Burg Steinwacht verschanzt hat. Seine Befehle zielen darauf ab, die Kommandostruktur der Orcs zu zerschlagen, bevor ein Großangriff Seenhain vollständig vernichtet."}},faq={{q="Wer ist Marschall Marris?",a="Marschall Marris ist der ranghöchste militärische Befehlshaber, der mit der Verteidigung von Seenhain betraut ist. Man findet ihn Wache haltend nahe dem westlichen Ende der Stadtbrücke, wo er versucht, die Siedlung gegen feindliche Übergriffe zu befestigen.",al={"marris","marschall marris lore","wer ist die wache an der brücke von seenhain"}},{q="Warum heuert Marschall Marris unabhängige Abenteurer an?",a="Das Königreich Sturmwind hat es versäumt, adäquate Garnisonsverstärkung in das Rotkammgebirge zu entsenden, wodurch die örtliche Wache von Seenhain hoffnungslos in der Unterzahl ist. Angesichts von Gnoll-Kriegstrupps und einer verschanzten Invasion von Schwarzfelsorcs ist Marris gezwungen, heldenhafte Söldner für entscheidende Angriffe anzuheuern.",al={"warum braucht marris hilfe","warum keine armee aus sturmwind"}},{q="Gegen welche Bedrohungen kämpft Marschall Marris?",a="Während Gnolle die Außenbezirke heimsuchen, konzentriert sich Marris in erster Linie auf die Schwarzfelsorcs, die Burg Steinwacht eingenommen haben. Diese Orcs, befehligt von Tharil'zun und durch Schattenmagie gestärkt, stellen eine unmittelbare existenzielle Bedrohung für Seenhain und das gesamte Königreich dar.",al={"marris feinde","wer greift seenhain an"}},{q="Ist Marschall Marris mit Nathanos Marris verwandt?",a="Sie teilen einen in den Menschenkönigreichen Lordaeron und Sturmwind verbreiteten Nachnamen, aber es gibt keine offiziellen Aufzeichnungen, die eine direkte familiäre Verbindung zwischen Marschall Marris im Rotkammgebirge und dem berühmten Waldläufer Nathanos Marris aus dem Norden belegen.",al={"ist marris mit nathanos verwandt","marris familie"}},{q="Wie lautet Marris' Plan, um den Schwarzfelsklan zu besiegen?",a="Marris setzt auf einen Zermürbungs- und Enthauptungskrieg. Er beauftragt Kämpfer damit, die Infanterie des Schwarzfelsklans zu dezimieren, magische Komponenten von ihren Nutzern von Schattenmagie zu beschaffen und Burg Steinwacht zu stürmen, um deren Anführer Tharil'zun hinzurichten.",al={"marris plan","wie man schwarzfelsorcs besiegt"}},{q="Wo ist Marschall Marris zu finden?",a="Marris ist in Seenhain im Rotkammgebirge stationiert und steht weithin sichtbar an der Brücke nahe der Stadtmitte.",al={"marris aufenthaltsort","wo ist marschall marris"}}},fx={["4fad023e"]={q="Auf wessen Seite steht Marschall Marris?",a="Marschall Marris ist ein loyaler Offizier des Königreichs Sturmwind und der Allianz. Als stationierter Offizier an der Front in Seenhain repräsentiert er die lokale militärische Autorität, die verzweifelt versucht, das Rotkammgebirge und seine Bürger vor eindringenden Feinden zu schützen.",al={"marschall marris fraktion","wem dient marris","marris allianz oder sturmwind"}},["4230d686"]={q="Warum ist Marschall Marris hier in Seenhain?",a="Marschall Marris ist in der Nähe der Brücke von Seenhain stationiert, um die Verteidigung gegen die Schwarzfelsorks zu koordinieren, die aus den Bergen strömen. Da offizielle Verstärkungen aus Sturmwind knapp sind, hält er Wache im Rotkammgebirge, um alle fähigen Abenteurer zu sammeln, die bereit sind, den Kampf in die feindliche Festung zu tragen.",al={"warum ist marschall marris im rotkammgebirge","warum ist marris hier","marschall marris standort grund"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="Marschall Maxwell",s="Marschall Maxwell ist ein hochrangiger Offizier der Armee von Sturmwind, der in Morgans Wacht in der Brennenden Steppe stationiert ist. Mit der Aufgabe betraut, den nördlichsten befestigten Grat der Allianz oberhalb des Rotkammgebirges gegen den Blackrockclan und die Dunkeleisenzwerge zu halten, leitet er Spähmissionen in die feindseligen Klippen darunter. Zudem spielt er eine entscheidende Rolle bei der Koordination von Bemühungen, das Schicksal seines gefangenen Kameraden Marshal Reginald Windsor aufzudecken.",h="Marschall Maxwell ist ein hochrangiger Offizier der Armee von Sturmwind, der in Morgans Wacht in der...",kw={"blackrocktiefen","brennende steppe","general drakkisath","marschall maxwell","maxwell","morgans wacht","reginald windsor","armee von sturmwind"},ang={["class:Warrior"]="Maxwell verkörpert die Disziplin des Frontmilitärs von Sturmwind, trotzt aufrecht der vulkanischen Asche und koordiniert gezielte Vorstöße tief hinter den feindlichen Linien.",["faction:Alliance"]="Für Recken der Allianz, die der sengenden Hitze der Brennenden Steppe trotzen, verkörpert Marschall Maxwell die Autorität von Sturmwind und die Speerspitze des Feldzugs gegen den Schwarzfels."},sec={{t="Ein einsamer Posten in der Steppe",b="Morgans Wacht dient als prekärer Vorposten am Südrand der Brennenden Steppe mit Blick auf ein Ödland voller Asche, Drachkin und Blackrockorcs. Marschall Maxwell befehligt das hier stationierte Militärkontingent aus Sturmwind und bietet Reisenden, die den feurigen Klippen trotzen, einen seltenen vertrauten Anblick. Von dieser felsigen Bastion aus überwacht er defensive Manöver, um die feindlichen Streitkräfte des Berges in Schach zu halten, bevor sie nach Süden in das Rotkammgebirge und nach Elwynn vordringen können."},{t="Die Wahrheit im Berg aufdecken",b="Über die reine Eindämmung hinaus dient Maxwell als primäre Verbindungsstelle im Feld für Operationen, die auf das Herz der Schwarzfelsspitze und der Schwarzfelstiefen abzielen. Als Gerüchte aufkommen, dass der gefangene Marshal Reginald Windsor möglicherweise noch in den Kerkern der Dunkeleisenzwerge lebt, ist es Maxwell, der Berichte sichtet und vertrauenswürdige Recken mit einer Rettung betraut. Sein Vorposten bildet die entscheidende Brücke zwischen der Aufklärung an vorderster Front und den politischen Unruhen, die sich hinter den Toren von Sturmwind zusammenbrauen."}},faq={{q="Wer ist Marschall Maxwell?",a="Marschall Maxwell ist ein Kommandant in der Armee von Sturmwind, der in Morgans Wacht in der Brennenden Steppe stationiert ist. Er führt die örtlichen Allianzstreitkräfte an, die die Blackrockorcs, die schwarzen Drachen und die Dunkeleisenzwerge im Auge behalten.",al={"marschall maxwell geschichte","wer ist maxwell"}},{q="Warum ist Marschall Maxwell in Morgans Wacht stationiert?",a="Morgans Wacht ist das Frontlager der Allianz an der Grenze zur Brennenden Steppe. Maxwell ist hier stationiert, um den Gebirgspass zu sichern, der hinab in das Rotkammgebirge führt, und Bedrohungen zu überwachen, die aus dem Schwarzfels strömen.",al={"warum ist maxwell in brennende steppe","morgans wacht kommandant"}},{q="Welche Verbindung hat Maxwell zu Marshal Windsor?",a="Maxwell ist der wichtigste Kommandant, der bei der Suche nach Marshal Reginald Windsor hilft, welcher gefangen genommen und in die Schwarzfelstiefen verschleppt wurde. Maxwell koordiniert die Rettungsbemühungen und leitet entscheidende Informationen über Windsor zurück nach Sturmwind.",al={"maxwell und windsor","abandoned hope quest geschichte"}},{q="Hilft Marschall Maxwell bei der Organisation von Angriffen auf die Schwarzfelsspitze?",a="Ja. Maxwell weist erfahrene Recken der Allianz an, die Führungsriege des Blackrockclans zu zerschlagen, und erteilt Direktiven, die auf General Drakkisath und seine Truppen auf den Höhen der Schwarzfelsspitze abzielen.",al={"maxwell drakkisath","maxwells mission"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="Marschall McBride",s="Marshal Douglas McBride ist der Kommandant der Garnison von Sturmwind, die in der Abtei von Nordhain stationiert ist. Betraut mit der Verteidigung des Nordhaintals, befehligt er frisch eingetroffene Rekruten gegen die zunehmende Koboldplage, die die örtlichen Höfe und Minen bedroht. Er fungiert als wichtigste militärische Autorität für Neuankömmlinge, die ihren Dienst für das Königreich Sturmwind antreten.",h="Marshal Douglas McBride ist der Kommandant der Garnison von Sturmwind, die in der Abtei von Nordhain...",kw={"douglas mcbride","echokamm","elwynn","kobold","marschall mcbride","nordhain","abtei von nordhain"},ang={["class:Warrior"]="McBride sucht aktiv nach robusten Kämpfern für den Dienst am Königreich und verlässt sich auf Krieger an vorderster Front, um die Stollen von Echokamm zu säubern.",["faction:Alliance"]="McBride repräsentiert den anfänglichen Grenzposten der Großen Allianz im Kernland der Menschheit und nimmt Rekruten in den Dienst der Krone auf.",["race:Human"]="Für Menschen, die ihre Abenteuer in Nordhain beginnen, ist Marschall McBride der erste Vertreter der königlichen Autorität von Sturmwind, dem sie begegnen."},sec={{t="Kommandant von Nordhain",b="Direkt vor der Abtei von Nordhain stationiert, repräsentiert Marshal Douglas McBride die unmittelbare Autorität der Armee von Sturmwind in diesem ruhigen Tal. Während die Abtei selbst eine Enklave des Glaubens und der Gelehrsamkeit ist, haben die wachsenden Unruhen im gesamten Königreich die militärischen Garnisonen stark ausgedünnt. McBride muss den Frieden wahren und die Nahrungs- sowie Ressourcenversorgung des Tals mit nur einer Handvoll vereidigter Wachen und einem stetigen Zustrom unerfahrener Rekruten sichern, die eine Ausbildung unter den Meistern der Abtei suchen."},{t="Der Überfall der Kobolde",b="McBrides größtes Problem ist die plötzliche Aggressivität des örtlichen Ungeziefers. Kobolde, einst nur ein Ärgernis, haben die umliegenden Wälder überrannt und die Echokammmine besetzt – eine wichtige örtliche Ressource. Da ihm die regulären Soldaten fehlen, um sie zu vertreiben, zieht McBride Paladine, Krieger und andere Neulinge heran, um die grabenden Plagegeister zurückzuschlagen und das Ausmaß des Befalls aufzudecken, bevor das Tal vollständig abgeschnitten wird."}},faq={{q="Wer ist Marschall McBride?",a="Marshal Douglas McBride ist ein Offizier der Armee von Sturmwind, der als Garnisonskommandant in der Abtei von Nordhain stationiert ist. Er ist für die Verteidigung des Nordhaintals und die Einteilung neuer Rekruten in den Dienst zuständig.",al={"marschall mcbride","wer ist mcbride","kommandant von nordhain"}},{q="Warum lässt McBride Rekruten gegen Kobolde kämpfen?",a="Kobolde haben die Wälder rund um Nordhain heimgesucht und die Kontrolle über die Echokammmine übernommen. Da das Militär von Sturmwind stark überlastet ist, verlässt sich McBride auf neu eingetroffene Abenteurer, um das Ungeziefer zu beseitigen und das Gebiet zu sichern.",al={"warum kobolde toeten","koboldproblem","echokamm problem"}},{q="Wohin schickt McBride Rekruten als Nächstes?",a="Sobald ein Rekrut seine Fähigkeiten unter Beweis gestellt hat, indem er die Bedrohungen im Nordhaintal beseitigt hat, schickt McBride ihn über die südliche Straße nach Goldhain, um Marschall Dughan zu unterstützen.",al={"wohin nach mcbride","nach nordhain","naechste stadt"}},{q="Was ist die Echokammmine?",a="Die Echokammmine ist eine mineralienreiche Höhle am nördlichen Rand des Nordhaintals. Sie wurde vor Kurzem von grabenden Kobolden überrannt, was McBride dazu veranlasste, mehrere Einsätze zu ihrer Rückeroberung anzuordnen.",al={"echokamm","die mine in nordhain"}},{q="Befehligt McBride die Abtei selbst?",a="Nein. Die Abtei von Nordhain wird von den heiligen Orden und den Priestern des Lichts geführt. McBride beaufsichtigt die Militärgarnison, die mit der Verteidigung der Abtei und des umliegenden Tals beauftragt ist.",al={"leitet mcbride die abtei von nordhain","wer leitet die abtei"}},{q="Sorgt sich McBride um Bedrohungen abseits der Kobolde?",a="Während Kobolde das unmittelbarste Ärgernis darstellen, hält McBride Ausschau nach tiefergehender Instabilität. Banditen und Gesetzlose treiben sich an den Rändern des Tals herum, was auf weiterreichende Unruhen hindeutet, die sich im Wald von Elwynn zusammenbrauen.",al={"defias in nordhain","ist nordhain sicher"}}},fx={["05ea779e"]={q="Auf wessen Seite steht Marschall McBride?",a="Marschall McBride ist ein loyaler Offizier der Armee von Sturmwind und der Großen Allianz. Er untersteht der Krone von Sturmwind und hält Wache über das Nordhaintal, um die Sicherheit der Bürger des Königreichs zu gewährleisten und Rekruten auszubilden.",al={"wem dient mcbride","mcbride loyalität","welcher fraktion gehört mcbride an"}},b6028054={q="Was will Marschall McBride?",a="McBride will das Nordhaintal gegen wachsende lokale Bedrohungen sichern. Da die Armee von Sturmwind nur dünn gesät ist, versucht er, neue Rekruten, Paladine und Freiwillige zu mobilisieren, um die aggressiven Kobolde, die das Tal befallen, zu vertreiben und die Echokammmine zurückzuerobern.",al={"mcbride ziel","was versucht mcbride zu tun","mcbride pläne"}},cc66b2df={q="Warum ist Marschall McBride hier?",a="McBride ist als Befehlshaber der militärischen Garnison des Tals außerhalb der Abtei von Nordhain stationiert. Sturmwind hat ihn damit beauftragt, die Ordnung aufrechtzuerhalten, die Verteidigung zu organisieren und Neuankömmlinge auszubilden, bevor er bewährte Soldaten in den Wald von Elwynn und darüber hinaus entsendet.",al={"warum ist mcbride in nordhain","mcbride posten","warum ist marschall mcbride an der abtei"}},["307fdf7d"]={q="Mit wem ist Marschall McBride verbunden?",a="McBride ist an das Oberkommando der Armee von Sturmwind gebunden und koordiniert sich mit den örtlichen Behörden im gesamten Wald von Elwynn; schließlich leitet er fähige Kämpfer an Marschall Dughan in Goldhain weiter. Er arbeitet mit dem Klerus und den Ausbildern der Abtei zusammen, um neue Verteidiger auf das Königreich vorzubereiten.",al={"mcbride verbindungen","wem untersteht mcbride","mcbride armee von sturmwind"}}},fp="15,363,23.465.0,20.415.0,23.204.0,45.217.0,38.181.0,24.203.0,38.178.0,50.197.0"}
P.entries["npc:martie-jainrose"] = {n="Martie Jainrose",s="Martie Jainrose ist die ansässige Kräuterkundige von Seenhain und pflegt ihren Garten am Ufer des Immerruhsees im Rotkammgebirge. Neben dem Anbau von Heilmitteln und Blumen für die bedrängte Stadt kämpft sie gegen wilde Bestien an, die ihre Beete niedertrampeln, und hegt eine stille Zuneigung zu Wache Parker.",h="Martie Jainrose ist die ansässige Kräuterkundige von Seenhain und pflegt ihren Garten am Ufer des...",kw={"bellygrub","narzissen","wache parker","kräuterkundige","seenhain","martie jainrose","rotkamm"},ang={["faction:Alliance"]="Marties Beharrlichkeit in Seenhain spiegelt die Widerstandskraft der Bevölkerung des Rotkammgebirges wider, die sich um die Aufrechterhaltung eines gewöhnlichen häuslichen Lebens bemüht, selbst während Sturmwind die Stadt weitgehend sich selbst überlässt.",["profession:Herbalism"]="Für praktizierende Kräuterkundige, die durch das Rotkammgebirge reisen, verkörpert Martie eine vertraute Seelenverwandtschaft, da sie trotz der harschen Übergriffe wilder Eber und herandrängender Feinde fragile Pflanzen hegt."},sec={{t="Ein Garten am See",b="Martie Jainrose lebt in Seenhain und arbeitet emsig als Kräuterkundige der Siedlung. Selbst als Schwarzfelsorcs, Gnolle und örtliche Banditen die Region bedrohen, konzentriert sich Martie darauf, die Stadt mit frischen Kräutern und Blumenarrangements zu versorgen. Ihre tägliche Arbeit wird oft von der örtlichen Tierwelt gestört – allen voran von dem monströsen Eber Bellygrub, der regelmäßig ihre geschätzten Gartenbeete verwüstet. Abseits ihrer kräuterkundigen Bestrebungen ist Martie dafür bekannt, eine sanfte Zuneigung zu Wache Parker zu hegen, dem sie gelegentlich Sträuße handgepflückter Narzissen schickt, um seine aufmerksame Wache über die Stadt zu erhellen."}},faq={{q="Wer ist Martie Jainrose?",a="Martie Jainrose ist eine menschliche Kräuterkundige, die in Seenhain im Rotkammgebirge lebt. Sie pflegt einen Garten am Immerruhsee, baut Pflanzen an und bereitet pflanzliche Heilmittel für die örtlichen Bewohner zu.",al={"martie jainrose","wer ist martie","seenhain kräuterkundige"}},{q="Welche Probleme hat Martie mit der örtlichen Tierwelt?",a="Ein gewaltiger und berüchtigt eigensinniger Wildbrecher namens Bellygrub hat begonnen, ihre Gartenbeete zu plündern, ihre zarten Anpflanzungen niederzutrampeln und ihre Kräuter zu fressen, noch ehe sie diese ernten kann.",al={"martie eber problem","bellygrub garten","wer zerstört ihren garten"}},{q="Für wen schwärmt Martie in Seenhain?",a="Martie hegt romantische Gefühle für Wache Parker, eine der in der Nähe stationierten Stadtwachen. Sie lässt ihm regelmäßig Sträuße frischer Narzissen überbringen, während er Wache hält.",al={"martie schwarm","martie wache parker","narzissen für eine dame romanze"}}},fx={["4d2b4277"]={q="Auf wessen Seite steht Martie Jainrose?",a="Martie ist eine loyale Bürgerin der Allianz, die friedlich in Seenhain lebt. Obwohl sie nicht an der Front kämpft oder Waffen trägt, unterstützt sie die Stadt und ihre Verteidiger durch ihren Beruf als Kräuterkundige.",al={"martie jainrose fraktion","ist martie allianz"}},e745a8a7={q="Was will Martie Jainrose?",a="Martie möchte ihren Garten in Frieden pflegen und ihr Kräuterhandwerk ohne Einmischung ausüben. Ihr unmittelbares Ärgernis ist ein riesiger Eber namens Bellygrub, der ständig ihre wertvolle Ernte zertrampelt, und sie begrüßt gerne jeden Reisenden, der bereit ist, das Biest zu vertreiben.",al={"martie jainrose ziel","was braucht martie"}},["6d429f48"]={q="Warum ist Martie Jainrose in Seenhain?",a="Seenhain ist Marties Zuhause, wo sie ihren Lebensunterhalt damit verdient, Kräuter anzubauen und ihren Garten entlang der ruhigen Ufer des Immerruhsees zu pflegen, trotz der wachsenden Probleme, die das umliegende Rotkammgebirge heimsuchen.",al={"warum ist martie im rotkammgebirge","warum ist martie jainrose hier"}}},fp="15,293,20.588.0,23.202.0,54.182.0,35.184.0"}
P.entries["npc:marukai"] = {n="Marukai",s="Marukai ist eine Dschungeltrollin der Dunkelspeer, die im Außenposten von Zoram'gar an der nebligen Küste des nordwestlichen Eschental stationiert ist. Sie widmet sich dem Halten dieses abgelegenen Brückenkopfs für die Horde und koordiniert die Bemühungen, die vordringenden Wrathtail-Naga auszudünnen, welche den Außenposten bedrohen.",h="Marukai ist eine Dschungeltrollin der Dunkelspeer, die im Außenposten von Zoram'gar an der nebligen Küste des...",kw={"eschental","dunkelspeer","dschungeltroll","marukai","naga","wrathtail","der zoramstrand","außenposten von zoram'gar"},ang={["faction:Horde"]="Marukai stützt eines der heikelsten Küstenlager der Horde im Gebiet der Nachtelfen und verlässt sich auf verbündete Champions, um zu verhindern, dass die einheimischen Naga ihre Stellung überrennen.",["race:Troll"]="Fernab der warmen Klänge von Sen'jin verkörpert Marukai die Unbeugsamkeit des Dunkelspeer-Stammes, während sie auf ganz Kalimdor befestigte Stützpunkte für die Horde errichten."},sec={{t="Den Strand halten",b="Der Außenposten von Zoram'gar liegt isoliert am nördlichen Rand des Zoramstrands, umgeben von uralten Ruinen, feindseligem Nachtelfengebiet und dem unruhigen Meer. Während die Wrathtail-Naga in großer Zahl aus den Gewässern und alten Elfenruinen emportauchen, um die Küste für sich zu beanspruchen, setzt Marukai alles daran, das Lager vor dem Überranntwerden zu bewahren. Sie weist Streiter der Horde an, das Schlangenvolk zurück in die Fluten zu treiben und ihre Köpfe zu sammeln, um sicherzustellen, dass der Außenposten eine überlebensfähige Küstenfestung bleibt."}},faq={{q="Wer ist Marukai?",a="Marukai ist eine Dschungeltroll-Questgeberin, die den Außenposten von Zoram'gar verteidigt, das isolierte Küstenlager der Horde an den nordwestlichen Ufern von Eschental.",al={"marukai lore","wer ist marukai","marukai nsc"}},{q="Warum bekämpft Marukai die Naga?",a="Die Wrathtail-Naga haben den nahe gelegenen Zoramstrand und die umliegenden Ruinen heimgesucht. Um die Grenzen des Außenpostens zu sichern und das Überleben der Horde an der Küste zu gewährleisten, heuert Marukai Abenteurer an, um ihre Reihen durch direkte Jagd zu lichten.",al={"warum naga töten","marukai naga quest","zoramstrand naga"}},{q="Wo befindet sich Marukai?",a="Sie ist an der Seite ihrer Sippe im Außenposten von Zoram'gar anzutreffen, der an der Mündung des Zoramstrands im nordwestlichen Eschental liegt, direkt südlich der versunkenen Ruinen der Tiefschwarzen Grotte.",al={"wo ist marukai","marukai aufenthaltsort","marukai finden"}}},fx={["53dc13db"]={q="Auf wessen Seite steht Marukai?",a="Marukai ist der Horde treu. Von ihrem Stützpunkt im Außenposten von Zoram'gar an der Küste des Eschentals aus hält sie Wache über die Interessen der Horde und verlässt sich auf Reisende der Horde, um die Siedlung gegen örtliche Gefahren zu verteidigen.",al={"marukai fraktion","ist marukai horde","wem dient marukai"}},["1bf5ddde"]={q="Warum ist Marukai hier im Außenposten von Zoram'gar?",a="Marukai ist im Außenposten von Zoram'gar stationiert, um den Stützpunkt der Horde am The Zoram Strand zu verteidigen. Da die aggressiven Wrathtail-Naga an die Strände zurückkehren und die Grenzen des Lagers bedrohen, koordiniert sie Bemühungen, den Umkreis zu sichern und den Außenposten sicher zu halten.",al={"warum ist marukai im eschental","marukai zweck","was bringt marukai hierher"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="Apothekermeister Faranell",s="Apothekermeister Faranell ist das Oberhaupt der Königlichen Apothekervereinigung und hat seinen Sitz in den Tiefen des Apothekariums in Unterstadt. Zu Lebzeiten ein angesehener Gelehrter aus Dalaran, leitet er im Untod die Suche der Verlassenen nach einer verheerenden Neuen Seuche, um sowohl die Geißel als auch die Lebenden zu vernichten.",h="Apothekermeister Faranell ist das Oberhaupt der Königlichen Apothekervereinigung und hat seinen Sitz in den...",kw={"monstrosität","das apothekarium","seuche","faranell","apothekermeister faranell","neue seuche","renferrel","königliche apothekervereinigung","sylvanas","unterstadt"},ang={["faction:Horde"]="Obwohl Verbündete der Orcs, Trolle und Tauren durch den grünen Schleim und die eingesperrten Versuchsobjekte des Apothekariums beunruhigt sein mögen, werden Faranells Forschungen als unverzichtbare Kriegsführung gegen die gemeinsame Bedrohung durch die Geißel geduldet.",["profession:Herbalism"]="Faranells Bottiche verschlingen endlose Mengen seltener Flora, Moose und Pilzextrakte – ein düsteres Zeugnis botanischer Studien, die zur Zerstörung militarisiert wurden.",["race:Undead"]="Für die Verlassenen verkörpert Faranell die Vorhut biologischer Souveränität, die im Verborgenen schuftet, um sicherzustellen, dass ihr Volk über Waffen verfügt, die den Lichkönig zerschmettern können."},sec={{t="Ein vom Tode zerrütteter Geist",b="Vor dem Dritten Krieg war Faranell ein geschätzter Alchemist, der jahrzehntelang an der Seite der gelehrten Magier von Dalaran forschte. Er verbrachte seine sterblichen Tage damit, Heilmittel, Kuren und Tränke zu erforschen, um die Gesundheit der Sterblichen zu verbessern. Als die Seuche der Geißel sein Leben forderte und er als Verlassener mit freiem Willen auferstand, schlug seine einstige wissenschaftliche Neugierde in Grausamkeit um. Mit seinem enzyklopädischen Verstand tauschte er Heilsalben gegen verheerende Reagenzien ein und stieg in den Tiefen von Lordaerons gefallener Hauptstadt rasch zu einem der geschätztesten Forscher von Königin Sylvanas Windläufer auf."},{t="Der Meister des Apothekariums",b="Von den giftigen Laboratorien des Apothekariums aus koordiniert Faranell die weitverzweigten Forschungen der Königlichen Apothekervereinigung. Er beaufsichtigt den Bau schwerfälliger Monstrositäten und leitet die untergeordneten Apotheker an, die in ganz Lordaeron und darüber hinaus stationiert sind. Jede Ladung seltsamer Gifte, verdorbenen Blutes und verfluchter Flora, die von Feldforschern auf den Kontinenten gesammelt wird, landet schließlich in seinen Bottichen zur Destillation und Verfeinerung."},{t="Erschaffung der Neuen Seuche",b="Faranells einzige treibende Obsession ist die Erfüllung des Auftrags der Dunklen Fürstin: die Entdeckung der Neuen Seuche. Um eine Seuche zu brauen, die in der Lage ist, Arthas und seine willenlosen Legionen der Geißel zu vernichten, koordiniert Faranell eine umfassende Beschaffung von Reagenzien. Er entsendet Abenteurer, um die Forschungsaufzeichnungen seines gefallenen Kollegen Apotheker Berard aus Lohenscheit zu bergen, beschafft Fledermausguano aus den tiefen Höhlen im Kral der Klingenhauer und testet ätzende Kolloide an den Organen von Eiferern aus dem Scharlachroten Kloster."}},faq={{q="Wer ist Apothekermeister Faranell?",a="Faranell ist das Oberhaupt der Königlichen Apothekervereinigung, der alchemistischen Gilde im Dienste von Fürstin Sylvanas Windläufer in Unterstadt. Er überwacht sämtliche Forschungen bezüglich Toxinen, zusammengenähten Monstrositäten und der Entwicklung der Neuen Seuche.",al={"wer ist faranell","faranell lore","anführer der apotheker"}},{q="Wo ist Faranell zu finden?",a="Er hält sich im Apothekarium auf, dem alchemistischen Viertel im westlichen Teil von Unterstadt, umgeben von brodelnden Kesseln, Testkäfigen und seinen untergeordneten Apothekern.",al={"faranell aufenthaltsort","wo ist apothekermeister faranell","faranell finden"}},{q="Was war Faranells Hintergrund, bevor er starb?",a="Zu Lebzeiten war Faranell ein anerkannter Alchemist und Arzt, der bei den Zauberern von Dalaran lernte. Er verbrachte seine lebenden Jahre damit, Heilmittel gegen Krankheiten zu erfinden, bis die Seuche ihn tötete und seine Neugierde auf tödliche Gifte lenkte.",al={"faranell geschichte","war faranell in dalaran","faranell sterbliches leben"}},{q="Was versucht die Königliche Apothekervereinigung zu erschaffen?",a="Auf Befehl von Königin Sylvanas stellt die Vereinigung Eine neue Seuche her. Ihr Ziel ist es, eine Waffe zu erschaffen, die virulent genug ist, um die Geißel zu vernichten und Rache am Lichkönig zu nehmen, während sie die Verlassenen gleichzeitig vor sterblichen Feinden schützt.",al={"was ist die neue seuche","was stellen apotheker her","ziele der apotheker"}},{q="Warum schickt Faranell Abenteurer nach Lohenscheit?",a="Er sucht nach dem Forschungstagebuch seines ehemaligen Kollegen, Apotheker Berard, der in Pyrewood dem Wahnsinn und dem Worgenfluch verfiel. Berards Feldaufzeichnungen enthalten entscheidende Daten über giftige Stoffe, die zur Verfeinerung ihrer Seuchenexperimente benötigt werden.",al={"rezept für den tod quest faranell","warum pyrewood","apotheker berard tagebuch"}},{q="Warum benötigt er Reagenzien aus dem Kral der Klingenhauer und dem Scharlachroten Kloster?",a="Faranell testet, wie gegensätzliche, flüchtige Verbindungen miteinander interagieren. Er verwendet Kralguano aus den Höhlen der Borstennacken von Razorfen zusammen mit den frisch entnommenen Herzen von Eiferern des Scharlachroten Kreuzzugs, um ätzende Kolloide und biologische Kontamination zu untersuchen.",al={"kralguano faranell","herzen des eifers","scharlachrotes kloster herzen"}}},fx={["90cc21c1"]={q="Auf wessen Seite steht Apothekermeister Faranell?",a="Faranell ist voll und ganz Fürstin Sylvanas Windläufer und den Verlassenen ergeben. Als Meister der Königlichen Apothekergesellschaft richtet er seine Forschung direkt an den Ambitionen der Dunklen Fürstin aus und mobilisiert seine Alchemisten, um ihre Feinde auszurotten und das Überleben der untoten Nation zu sichern, ungeachtet der moralischen Kosten.",al={"faranell loyalität","wem dient faranell","ist faranell loyal zu sylvanas"}},b168fd3d={q="Warum ist Apothekermeister Faranell in der Unterstadt?",a="Faranell beaufsichtigt Das Apothekarium, das alchemistische Herz der Unterstadt. Von diesem weitläufigen Labor aus, erfüllt von blubbernden Bottichen und giftigen Dämpfen, leitet er die Forschung der Königlichen Apothekergesellschaft, testet gefährliche Gebräue und koordiniert die Synthese mächtiger neuer Seuchen und Monstrositäten für die Verlassenen.",al={"warum ist faranell hier","faranell apothekarium","warum ist faranell in unterstadt"}},["79d7ca05"]={q="Mit wem ist Apothekermeister Faranell verbunden?",a="Faranell dient direkt Königin Sylvanas Windläufer und leitet die Königliche Apothekergesellschaft, wobei er untergeordnete Forscher wie Apotheker Renferrel im Silberwald und Apotheker Lydon im Vorgebirge des Hügellands anleitet. Er pflegt auch Verbindungen zu anderen Forschern und setzt die Arbeiten ehemaliger Kollegen wie Apotheker Berard zusammen.",al={"faranell verbindungen","wer arbeitet mit faranell","faranell verbündete"}},d3e005f3={q="Warum wird Apothekermeister Faranell gefürchtet?",a="Einst ein angesehener Gelehrter in Dalaran, wandelte sich Faranells intellektuelle Brillanz nach seinem Aufstieg im Untod in tiefgründigen Sadismus. Er ist berüchtigt als der dunkle Architekt hinter den tödlichsten Giften und Seuchen der Verlassenen und testet schreckliche neue Gebräue an Lebenden wie Toten gleichermaßen, ohne einen Funken Reue.",al={"warum ist faranell berühmt","faranell ruf","ist faranell gefährlich"}}},fp="26,293,24.557.0,30.456.0,23.496.1,34.230.0,28.184.0,46.234.0,54.242.0,55.235.0,72.238.0"}
P.entries["npc:master-apothecary-lydon"] = {n="Apotheker Lydon",s="Apotheker Lydon ist ein morbider Forscher der Königlichen Apothekervereinigung, der in Tarrens Mühle stationiert ist. Chronisch deprimiert und zu Tode gelangweilt, findet er Freude nur darin, tödliche Gebräue zu verfeinern und den Lebenden beim Leiden zuzusehen. Er leitet die Forschung an wirkungsvollen neuen Giften, die darauf abzielen, Hillsbrad für die Verlassenen zu sichern und Sylvanas' Neue Seuche voranzutreiben.",h="Apotheker Lydon ist ein morbider Forscher der Königlichen Apothekervereinigung, der in Tarrens Mühle...",kw={"apotheker","elixir of agony","faranell","hillsbrad","lydon","königliche apothekervereinigung","tarrens mühle","umpi"},ang={["faction:Alliance"]="Für die Menschen von Süderstade ist Lydon ein schreckliches Monster, das tödliche Krankheiten braut und diese wahllos an gefangenen Bauern aus Hillsbrad und Wildtieren testet.",["profession:Herbalism"]="Lydons Werkstatt ist vollgestopft mit Reagenzien, Kesseln und verrottender Flora, was zeigt, wie traditionelle Sammelkünste von der Apothekervereinigung als Waffe eingesetzt werden.",["race:Undead"]="Lydon verkörpert die einzige Mission der Königlichen Apothekervereinigung: die Entwicklung der Neuen Seuche, um eine Zukunft für die Verlassenen zu sichern und die Lebenden auszurotten."},sec={{t="Der Einsiedler von Tarrens Mühle",b="In der zur Kapelle umfunktionierten Werkstatt in Tarrens Mühle stationiert, repräsentiert Apotheker Lydon das kalte, berechnende Ethos der Königlichen Apothekervereinigung. Er leidet an einer tiefen, trägen Melancholie und ist angewidert von den blühenden Blumen und der frischen Luft im Vorgebirge des Hügellands. Die einzige Ablenkung, die seine beständige Düsternis vertreibt, ist die Kunst des Todeshandwerks. Wenn er unbeaufsichtigt ist, vertreibt er sich die Zeit damit, seinen unglücklichen Frosch Umpi zu vergiften, zu sezieren und wiederzubeleben, während er immer wieder darauf wartet, dass neue Reagenzien eintreffen."},{t="Gebräue des Leidens",b="In Zusammenarbeit mit Apothekermeister Faranell in der Unterstadt führt Lydon umfangreiche Feldexperimente im gesamten Hillsbrad durch. Seine Arbeit steigert sich vom Elixier des Leidens bis hin zum virulenten Elixir of Agony. Um deren Wirksamkeit zu überprüfen, entsendet Lydon Abenteurer, um die Gebräue an lokalen Zielen zu testen, angefangen bei unschuldigen Wildtieren und Haustieren bis hin zu gefangenen menschlichen Bauern. Seine unbedingte Loyalität gehört allein der Dunklen Fürstin; er sehnt den Tag herbei, an dem ihre fertige Neue Seuche die Welt der Lebenden säubert."},{t="Gift des Loa",b="Über seine Standardgebräue hinaus erstreckt sich Lydons intellektuelle Neugier auf esoterische Gifte. Als mysteriöse Giftfläschchen in der Region auftauchen, berät er sich mit Trollmystikern wie Meister Gadrin, um deren Ursprung zurückzuverfolgen. Diese Untersuchung deckt eine Spur auf, die direkt zur Spinnengöttin Shadra im Hinterland führt. Sobald es gesichert ist, wird solch urzeitliches Gift direkt an das Apothekarium in der Unterstadt verschifft, um die Seucheninitiative der Verlassenen weiter voranzutreiben."}},faq={{q="Wer ist Apotheker Lydon?",a="Er ist ein Alchemist der Königlichen Apothekervereinigung, der von Tarrens Mühle im Vorgebirge des Hügellands aus operiert. Er überwacht die Entwicklung verschiedener experimenteller Seuchen und Gifte im Auftrag von Fürstin Sylvanas Windläufer.",al={"wer ist lydon","lydon tarrens mühle","apotheker lydon lore"}},{q="Warum ist Lydon so deprimiert?",a="Lydon leidet unter tiefer Melancholie und findet die natürliche Schönheit und die frische Luft von Hillsbrad abstoßend. Die einzigen Dinge, die seine Stimmung heben, sind grausame Experimente, das Leiden der Lebenden und der Geruch von alchemistischen Einbalsamierungsflüssigkeiten.",al={"warum ist er traurig","lydon depression","warum ist lydon düster"}},{q="Wer ist Umpi?",a="Umpi ist ein Frosch, den Lydon in seiner Werkstatt hält und den er ironisch als seine Assistentin bezeichnet. In Wirklichkeit vertreibt er sich seine extreme Langeweile damit, das hilflose Amphibium wiederholt zu vergiften, zu töten und wiederzubeleben.",al={"lydon frosch","wer ist der frosch","umpi lore"}},{q="Was ist das Elixir of Agony?",a="Es ist ein starkes experimentelles Gift, das von Lydon unter Verwendung von Zutaten aus den Östlichen Königreichen gebraut wird, darunter Anhänger des Syndikats, Zwergenbier und Spinnengift. Lydon testet es schließlich an gefangenen Menschen in Hillsbrad, um seine tödliche Wirkung zu bestätigen.",al={"elixir of agony quest","was ist elixir of agony","lydon elixier"}},{q="Wie wurde Lydon zu einem Verlassenen?",a="Er war ein junger menschlicher Alchemist in Lordaeron, der während des Dritten Krieges der Geißel zum Opfer fiel. Als Sylvanas die Kontrolle des Lichkönigs brach, schloss sich Lydon ihr an und legte seine frühere menschliche Identität vollständig ab, um sein untotes Dasein der Dunklen Fürstin zu widmen.",al={"lydons vergangenheit","war lydon ein mensch","lydon dritter krieg"}},{q="Was schickt Lydon an die Unterstadt?",a="Nachdem er uralte Giftgefäße im Hinterland entdeckt und den Untergang des Troll-Spinnengottes Shadra koordiniert hat, sammelt Lydon deren konzentriertes, göttliches Gift und verschifft es direkt an Apothekermeister Faranell, um die Seuchenforschung der Vereinigung zu stärken.",al={"lydon unterstadt gift","shadra gift quest"}}},fx={["4ad88718"]={q="Auf wessen Seite steht Apotheker Lydon?",a="Apotheker Lydon ist Fürstin Sylvanas Windläufer, den Verlassenen und der Horde gegenüber äußerst loyal. Er ist ein leitender Forscher in der Königlichen Apothekergesellschaft und nimmt direkte Anweisungen von Apothekermeister Faranell in der Unterstadt entgegen. Alles, was er braut, dient Sylvanas' großen Plänen, das Reich für die Untoten zu sichern.",al={"lydon fraktion","wem dient lydon","ist lydon verlassener"}},["64f2c0db"]={q="Was will Apotheker Lydon?",a="Lydon ist besessen von der Erschaffung und Perfektionierung der Neuen Seuche für die Dunkle Fürstin. Er sucht nach wirksamen Toxinen, Raubtierblut und tödlichen Giften aus der gesamten Region, um seine Gebräue zu verfeinern – einschließlich des Elixier des Leidens und Elixir of Agony –, mit dem Ziel, den Lebenden Elend und Tod zu bringen.",al={"was versucht lydon zu tun","lydon ziel","warum will lydon gifte"}},["26e1a5a5"]={q="Warum ist Apotheker Lydon in Tarrens Mühle?",a="Lydon ist im Apothekenlabor von Tarrens Mühle stationiert, um regionale Reagenzien zu sammeln und tödliche alchemistische Formeln in der Nähe von feindlichem Gebiet zu testen. Das Vorgebirge des Hügellands bietet fruchtbare Testgelände gegen lokale Wildtiere, feindliche Zwergeneinfälle und die Menschenstadt Süderstade gleich die Straße hinunter.",al={"warum ist lydon im hügelland","lydon tarrens mühle zweck","warum ist apotheker lydon hier"}},["7699f577"]={q="Mit wem ist Apotheker Lydon verbunden?",a="Lydon berichtet direkt an Apothekermeister Faranell und die Königliche Apothekergesellschaft. Er arbeitet eng mit Kollegen in ganz Azeroth zusammen, versorgt Apothecary Zamah im Steinkrallengebirge mit starken Giften und koordiniert die Forschung mit anderen Apothekern der Verlassenen, die überall in Lordaeron stationiert sind.",al={"verbindungen von lydon","wer arbeitet mit lydon","verbündete von lydon"}}},fp="16,354,26.508.0,20.517.1,16.465.1,24.213.0,26.245.0,12.207.0,28.256.1,30.254.0,38.260.1"}
P.entries["npc:master-gadrin"] = {n="Meister Gadrin",s="Meister Gadrin ist ein ältlicher Dschungeltroll und ein ehrwürdiger Hexendoktor des Dunkelspeer-Stammes, der derzeit in Sen'jin lebt. Nachdem er einst an der Seite des abtrünnigen Hexendoktors Zalazane die Priester und Magier des Stammes ausgebildet hatte, koordiniert er nun die Bemühungen, seinem vertriebenen Volk beizustehen und den finsteren Fluch zu brechen, der ihre geraubte Heimat auf den Echoinseln im Griff hält.",h="Meister Gadrin ist ein ältlicher Dschungeltroll und ein ehrwürdiger Hexendoktor des Dunkelspeer-Stammes, der...",kw={"dunkelspeer","durotar","die echoinseln","gadrin","meister gadrin","minshina","sen'jin","vol'jin","hexendoktor","zalazane"},ang={["class:Mage"]="Gadrin beschritt neue Wege, indem er Dunkelspeer-Trolle nach dem Dritten Krieg in den arkanen Künsten unterwies, womit er bewies, dass trollische Magie weit über rohes Ritual-Mojo hinausreichen konnte.",["class:Priest"]="Als Ältester, der die Priester der Dunkelspeer in der Zwiesprache mit den Geistern und den Loa unterwies, verkörpert Gadrin die Schatten- und Glaubenstraditionen der Dschungeltrolle.",["faction:Horde"]="Meister Gadrin ist einer der vertrautesten Berater von Vol'jin; er behält die Küste von Durotar wachsam im Auge und warnt Klingenhügel, wenn finstere Kulte die noch junge Nation Durotar bedrohen.",["race:Troll"]="Für die Dunkelspeer ist Meister Gadrin eine lebendige Verbindung zu Eurer angestammten Heimat und den Traditionen von Sen'jin. Er hat die spirituelle Führung Eures Stammes über Generationen hinweg geprägt und empfindet väterliche Trauer über die Tragödie der Echoinseln."},sec={{t="Mentor der Dunkelspeer",b="Lange bevor die Dunkelspeer auf Kalimdor ankamen, diente Meister Gadrin seinem Stamm als Hexendoktor auf ihren angestammten Inseln in den südlichen Meeren, wo er die mystische Ausbildung ganzer Generationen von Dunkelspeer-Trollen anleitete."},{t="Der Verrat von Zalazane",b="Als sich die Dunkelspeer an der Seite der Horde auf den Echoinseln niederließen, leiteten Gadrin und der junge Hexendoktor Zalazane gemeinsam die mystische Ausbildung der Priester und Magier des Stammes. Tragischerweise verfiel Zalazane dem Wahnsinn, berauscht von den dunklen Voodoo-Kräften, die er zu beherrschen suchte. Der abtrünnige Ausübende versklavte den Geist seiner Brüder und vertrieb Vol'jin und die unberührten Dunkelspeer auf das Festland von Durotar. Nun in Sen'jin ansässig, trägt Gadrin den persönlichen Schmerz in sich, mitansehen zu müssen, wie ein einstiger Gefährte zu einem tyrannischen Ungeheuer wurde; unermüdlich arbeitet er daran, erschlagene Stammesangehörige zur Ruhe zu betten und Zalazanes Herrschaft zu beenden."},{t="Hüter uralten Wissens",b="Über die Krise auf den Echoinseln hinaus gilt Gadrin als eine der größten lebenden Autoritäten der Horde in puncto Troll-Spiritualismus und Loa-Kunde. Gelehrte, Schamanen und sogar die Königliche Apothekervereinigung suchen seinen Rat bei arkanen und alchemistischen Rätseln. Wenn seltsame Bedrohungen wie die Burning Blade an Durotar heranrücken oder weit entfernte Forscher vergessene Rituale benötigen – wie das Entziffern uralter Tafeln in Zul'Farrak zur Anrufung der Spinnen-Loa Shadra –, besitzt Gadrin das Wissen, um die notwendigen Bannsprüche zu weben."}},faq={{q="Wer ist Meister Gadrin?",a="Meister Gadrin ist ein Hexendoktor und ein älterer spiritueller Anführer der Dunkelspeer. An der Küste Durotars in Sen'jin gelegen, dient er Häuptling Vol'jin als ranghoher Berater.",al={"meister gadrin lore","wer ist gadrin","gadrin nsc"}},{q="Welche gemeinsame Geschichte verbindet Gadrin mit Zalazane?",a="Auf den Echoinseln leiteten Gadrin und der junge Hexendoktor Zalazane gemeinsam die mystische Ausbildung der Priester und Magier der Dunkelspeer, nur dass Gadrin mit Entsetzen mitansehen musste, wie Zalazane dunkler Magie verfiel, dem Wahnsinn anheimfiel und die Dunkelspeer aus ihrer Inselheimat vertrieb.",al={"gadrin und zalazane","woher kennt gadrin zalazane","zalazane mentor"}},{q="Warum hält sich Gadrin in Sen'jin auf?",a="Als Zalazanes Fluch die Dunkelspeer von den Echoinseln vertrieb, errichteten die Überlebenden an der Südküste von Durotar Sen'jin als Zuflucht. Gadrin bleibt in dem Dorf, um Flüchtlinge zu beraten, lokale Bedrohungen zu überwachen und Schläge gegen Zalazanes Streitkräfte zu lenken.",al={"warum ist gadrin hier","was macht gadrin in senjin"}},{q="Wer ist Minshina?",a="Minshina war Meister Gadrins Bruder. Er kam während der Unruhen auf den Echoinseln ums Leben, und sein unruhiger Geist begann, Gadrin in Träumen zu rufen. Gadrin bittet vertrauenswürdige Abenteurer darum, den Schädel seines Bruders zu bergen, damit dessen Seele endlich Frieden finden kann.",al={"minshina bruder","minshinas schädel quest lore","wer war minshina"}},{q="Hilft Gadrin gegen den Kult der Burning Blade?",a="Ja. Nachdem er von Zureetha Fernblick Nachricht über die Infiltration des Tals der Prüfungen durch die Burning Blade erhalten hat, überwacht Gadrin die Präsenz des Kults nahe Sen'jin. Da er die größere Gefahr für Durotar erkennt, schickt er Rekruten nach Norden, um Orgnil Narbenseele in Klingenhügel Bericht zu erstatten.",al={"burning blade durotar gadrin","orgnil narbenseele gadrin"}},{q="Was weiß Gadrin über die Loa Shadra?",a="Gadrin ist ein Meister uralter trollischer Theologie. Als der Verlassene Apotheker Lydon nach einem wirkungsvollen Gift sucht, das von den Witherbark-Trollen im Hinterland verwendet wird, identifiziert Gadrin es als Gabe der Spinnen-Loa Shadra; er schickt Abenteurer nach Zul'Farrak, um die Tafel mit ihrem wahren Namen zu entziffern, die er benötigt, um einen Beschwörungszauber zu verfassen.",al={"shadra spinnen loa gadrin","gadrin spinnengott"}}},fx={["48c543c3"]={q="Auf wessen Seite steht Meister Gadrin?",a="Meister Gadrin ist dem Darkspear tribe und der Horde gegenüber loyal. Nachdem er von den Darkspear Islands gereist war, nachdem Thrall sein Volk vor der Meerhexe gerettet hatte, dient er als hochrangiger Ältester, mystischer Lehrer und vertrauter Berater von Häuptling Vol'jin.",al={"fraktion von gadrin","ist gadrin horde","wem dient gadrin"}},d3faca51={q="Was will Meister Gadrin?",a="Meister Gadrin sucht den Tod des verräterischen Hexendoktors Zalazane und die Befreiung der Die Echoinseln. Er möchte seine verfluchten Verwandten von Zalazanes Gedankenkontrolle befreien, den Schädel seines verstorbenen Bruders Minshina zurückgewinnen, damit die Geister ruhen können, und Sen'jin vor aufkommenden Gefahren in ganz Durotar schützen.",al={"was will gadrin","ziel von gadrin","motiv von meister gadrin"}}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {n="Meister Vornal",s="Meister Vornal ist ein ältlicher Dschungeltroll der Dunkelspeer, der in Sen'jin an der Südküste von Durotar lebt. Trotz seines fortgeschrittenen Alters und seines umfassenden Wissens über alchemistische Gebräue weigert er sich hartnäckig, Lehrlinge auszubilden.",h="Meister Vornal ist ein ältlicher Dschungeltroll der Dunkelspeer, der in Sen'jin an der Südküste von Durotar...",kw={"ein geistvolles getränk","dunkelspeer","durotar","meister vornal","sen'jin","troll","vornal"},ang={["profession:Herbalism"]="Wer im Umgang mit wilder Flora bewandert ist, wird Vornals scharfen Blick für seltene Katalysatoren und herbe natürliche Reagenzien erkennen, die für seine Lösungsmittel benötigt werden.",["race:Troll"]="Für die Dunkelspeer verkörpert Meister Vornal die eigensinnigen, älteren Handwerker, die beim Aufbau von Sen'jin halfen, nachdem der Stamm aus seiner Inselheimat geflohen war."},sec={{t="Der sture Brauer von Sen'jin",b="Meister Vornal ist eine feste Größe in Sen'jin, bekannt für das Brauen potenter Tränke und Geister für seine Dunkelspeer-Mitstreiter. Obwohl ihm das Alter zusehends zusetzt, bleibt Vornal ausgesprochen unabhängig und weigert sich beharrlich, Lehrlinge anzulernen; er zieht es vor, seine Heilmittel und flüchtigen Mixturen gänzlich mit eigener Hand anzumischen."},{t="Ein geistvolles Getränk",b="Gelegentlich beauftragt Vornal junge Abenteurer damit, herbe oder eigenwillige Zutaten aus den umliegenden Landen zu sammeln, wie etwa wirksame Materialien, die für Lösungsmittel und Mixturen benötigt werden. Während er bereit ist, jene zu belohnen, die ihm beistehen, hütet er seine genauen Methoden und Rezepte streng und betrachtet sein Handwerk als ein einsames Unterfangen."}},faq={{q="Wer ist Meister Vornal?",a="Meister Vornal ist ein ältlicher Dschungeltroll der Dunkelspeer, der in Sen'jin lebt. Er braut wirkungsvolle Geister und Heilmittel für den Stamm, besteht jedoch darauf, ohne Lehrling zu arbeiten.",al={"meister vornal","vornal","sen'jin meister vornal","wer ist vornal"}},{q="Wo kann ich Meister Vornal finden?",a="Er ist zwischen den Hütten in Sen'jin anzutreffen, an der Südküste von Durotar, direkt nördlich der Echoinseln.",al={"vornal aufenthaltsort","wo ist meister vornal","meister vornal finden"}},{q="Warum weigert sich Meister Vornal, Lehrlinge aufzunehmen?",a="Vornal ist für seine Sturheit berüchtigt. Trotz seines hohen Alters und des Bedarfs der Gemeinschaft an seinem Handwerk zieht er es vor, seine Gebräue allein herzustellen, anstatt seine Geheimnisse an eigensinnige Neulinge weiterzugeben.",al={"vornal lehrling","warum kein lehrling","vornal schüler"}},{q="Welche Aufgaben bietet er Abenteurern an?",a="Vornal schickt Wanderer los, um in der Region Rohstoffe für seine Lösungsmittelmischungen zu sammeln; dabei verlässt er sich für die Materialien auf Reisende, behält den Brauprozess jedoch strikt für sich.",al={"meister vornal quest","ein geistvolles getränk","vornal quest"}}},fx={e0bd334a={q="Auf wessen Seite steht Meister Vornal?",a="Meister Vornal ist dem Darkspear tribe und der Horde gegenüber loyal. Er hat sein Zuhause in Sen'jin und stellt sein Handwerk und seine Erfahrung zur Verfügung, um die junge Siedlung vor Gefahren aus der Umgebung zu schützen.",al={"loyalität von vornal","wem dient meister vornal","fraktion von meister vornal"}},["27223be8"]={q="Warum ist Meister Vornal in Sen'jin?",a="Meister Vornal lebt an der Küste von Durotar, um seinen Verwandten zu helfen, während sie sich im Exil ein neues Dasein aufbauen. Von seinem Zuhause in Sen'jin aus übt er sein Handwerk aus und beauftragt Reisende damit, die starken Reagenzien zu sammeln, die er benötigt.",al={"warum ist meister vornal hier","warum ist vornal in senjin","zweck von vornal in durotar"}},faf3afd9={q="Was will Meister Vornal?",a="Obwohl er altert, arbeitet Meister Vornal lieber unabhängig und weigert sich, sich mit Lehrlingen zu belasten. Stattdessen sucht er fähige Abenteurer, die seine Besorgungen erledigen und seltene Destillate und Lösungsmittel in ganz Durotar sammeln.",al={"was will vornal","ziel von meister vornal","wonach sucht vornal"}}},fp="13,247,30.334.0,16.319.0,21.176.0,31.134.0,50.193.0,37.181.0"}
P.entries["npc:mastok-wrilehiss"] = {n="Mastok Wutfauch",s="Mastok Wutfauch ist ein Ork-Offizier, der im Splitterholzposten im östlichen Eschental stationiert ist. Als entscheidender Verteidigungskoordinator für die Horde in dem umkämpften Wald weist er Späher und Krieger an, nahegelegene Grenzen zu sichern und gegen verderbende elementare Bedrohungen vorzugehen. Seine Anwesenheit ist unerlässlich, um den prekären Stützpunkt der Horde inmitten der ständigen Feindseligkeit der Nachtelfen zu halten.",h="Mastok Wutfauch ist ein Ork-Offizier, der im Splitterholzposten im östlichen Eschental stationiert ist.",kw={"eschental","der irdene ring","mastok","ork","splintertree","steinkralle","wrilehiss"},ang={["class:Shaman"]="Mastoks Sorge über verdorbene Elementare im Wald veranlasst Abenteurer oft dazu, Rat beim Irdenen Ring am Zoram'gar Strand zu suchen.",["faction:Alliance"]="Mastok Wutfauch repräsentiert die verschanzte militärische Präsenz der Orks in Eschental und verteidigt die befestigte Siedlung Splintertree gegen die Schildwachen der Nachtelfen.",["faction:Horde"]="Für Champions der Horde, die darum kämpfen, einen Vorposten in Eschental zu behaupten, ist Mastok ein maßgeblicher Kommandant, der Euch zu entscheidenden Aufgaben in der gesamten Region leiten kann."},sec={{t="Ein Bollwerk in den uralten Wäldern",b="Der Splitterholzposten liegt tief im Schatten des hoch aufragenden Blätterdachs von Eschental, vollständig umgeben von feindseligem Nachtelfengebiet. Mastok Wutfauch dient als einer der wichtigsten Verteidiger des Postens und überwacht Nachschubwege sowie Aktivitäten im Wald. Die Lage ist heikel; jedes Zeichen von Schwäche zieht rasche Angriffe der Schildwachen nach sich, die die Siedlung als frevelhaften Eingriff betrachten."},{t="Koordination der Front",b="Von seinem Posten innerhalb der Palisade aus betraut Mastok vorbeikommende Abenteurer aktiv mit entscheidenden strategischen Aufgaben. Er behält die Grenzen zu benachbarten Gebieten wie dem Steinkrallengebirge wachsam im Auge und entsendet Späher, um Schamanen wie Je'neu Sancrea vom Irdenen Ring am Zoram'gar Strand zu Rate zu ziehen. Seine Pflichten verbinden militärische Verteidigung mit der Beobachtung der seltsamen, verderbenden Kräfte, die den örtlichen Elementaren zusetzen."}},faq={{q="Wer ist Mastok Wutfauch?",a="Mastok Wutfauch ist ein Elite-Ork, der im Splitterholzposten in Eschental stationiert ist. Er fungiert als Offizier und Questgeber mit der Aufgabe, den Außenposten gegen Übergriffe der Nachtelfen zu verteidigen und nahegelegene regionale Bedrohungen zu untersuchen.",al={"wer ist mastok","mastok wutfauch rolle","wer ist dieser ork"}},{q="Wo ist Mastok Wutfauch zu finden?",a="Er befindet sich im Splitterholzposten, einem befestigten Außenposten der Horde im zentral-östlichen Eschental an der Hauptwaldstraße.",al={"mastok aufenthaltsort","wo ist mastok wutfauch","mastok karte"}},{q="Welche Aufgaben überträgt Mastok den Abenteurern?",a="Mastok betraut Horde-Abenteurer mit strategischen Aufgaben, darunter die Untersuchung verdorbener elementarer Bedrohungen im Wald, die Sicherung der Pässe ins Steinkrallengebirge und die Entsendung von Boten zu Je'neu Sancrea vom Irdenen Ring.",al={"mastok quests","quests von mastok"}},{q="Warum steht der Splitterholzposten unter ständigem Druck?",a="Der Außenposten dient als zentrales Holzfällerlager und als Festung der Horde in Eschental. Die einheimischen Nachtelfen betrachten die Anwesenheit der Orks und ihren Holzschlag als schwere Entweihung heiligen Landes, was zu unablässigen Scharmützeln führt.",al={"warum greifen nachtelfen splintertree an","splintertreeposten konflikt"}},{q="Warum schickt Mastok Reisende zu Je'neu Sancrea?",a="Die Schamanen des Irdenen Rings, darunter Je'neu am Zoram'gar Strand, erforschen und heilen die elementare Instabilität, die Eschental heimsucht. Mastok verbindet die Kämpfer an vorderster Front mit deren spiritueller Expertise, um gegen verdorbene Wasserelementare und seltsame Störungen vorzugehen.",al={"warum irdenen ring kontaktieren","mastok und jeneu"}},{q="Ist Mastok Wutfauch Spielern der Allianz feindlich gesinnt?",a="Ja. Mastok ist ein loyales Mitglied der Horde und ein Elite-Verteidiger des Splitterholzpostens, was bedeutet, dass er Spieler der Allianz sofort angreift, sobald sie sich dem Lager nähern.",al={"kann allianz mit mastok sprechen","kann man mastok toeten"}}},fx={["414a3ea9"]={q="Warum ist Mastok Wutfauch im Eschental?",a="Mastok Wutfauch ist im Splitterholzposten stationiert, um dabei zu helfen, den Stützpunkt der Horde in den umkämpften Wäldern des Eschentals zu sichern. Als erfahrener Verteidiger unter den Streitkräften des Kriegshymnenklans überwacht er lokale Verteidigungsbemühungen, verfolgt Störungen, die die umliegende Wildnis betreffen, und rekrutiert fähige Reisende, um mit verderblichen Elementarbedrohungen und den Feindseligkeiten der benachbarten Nachtelfen umzugehen.",al={"warum ist mastok hier","mastok wutfauch splitterholzposten","warum ist mastok am splitterholzposten"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {n="Mathias Shaw",s="Meister Mathias Shaw ist der Anführer des SI:7, des verdeckten Geheimdienstes des Königreichs Sturmwind. Aus den Schatten von der Altstadt heraus befehligt er Spione und Kundschafter, um das Reich vor internen Verschwörungen wie auch vor externen Schrecken zu schützen.",h="Meister Mathias Shaw ist der Anführer des SI:7, des verdeckten Geheimdienstes des Königreichs Sturmwind.",kw={"attentäter","pestrufer","kearnen","mathias shaw","die altstadt","der si:7","meisterspion","sturmwind","vancleef"},ang={["class:Rogue"]="Mathias Shaw verkörpert den absoluten Gipfel des menschlichen Schurkenhandwerks. Allianzschurken werden oft für fortgeschrittene taktische Aufträge und Spezialspezialgifte zu ihm geschickt.",["faction:Alliance"]="Als Meisterspion des Königreichs dient Shaw als erste Verteidigungslinie gegen Umsturzversuche und sammelt wichtige militärische Aufklärungsdaten für Hochlord Bolvar Fordragon und den Knabenkönig Anduin.",["race:Human"]="Shaws tragischer Bruch mit seinem Jugendfreund Edwin van Cleef spiegelt die tiefere, verbitterte Spaltung wider, die das Königreich Sturmwind nach seinem Wiederaufbau erfasste."},sec={{t="Meister des SI:7",b="Mathias Shaw gilt als Sturmwinds führender Meisterspion und Attentäter. Aus dem diskreten Hauptquartier des SI:7, das hinter den Kasernen in der Altstadt verborgen liegt, koordiniert Shaw ein verdecktes Netzwerk, das die Östlichen Königreiche und die Gebiete darüber hinaus umspannt. Pragmatisch, berechnend und dem Haus Wrynn treu ergeben, folgt er dem Grundsatz, dass die Sicherheit Sturmwinds von ungesehenen Dolchen und gestohlenen Botschaften genauso abhängt wie von glänzenden Rüstungen und Palastgarnisonen."},{t="Der Schatten von VanCleef",b="Shaw verbindet eine zutiefst persönliche Geschichte mit Edwin van Cleef, dem Anführer der rebellischen Bruderschaft der Defias. Die beiden waren Jugendfreunde, und Shaw bildete VanCleef persönlich in den Künsten der Heimlichkeit und des Attentats aus, in der Hoffnung, der begabte Steinmetz würde seine Talente künftig an seiner Seite in den Dienst des Königreichs stellen. Doch als die Steinmetzgilde nach dem Wiederaufbau von Sturmwind verstoßen wurde, richtete VanCleef diese tödlichen Lektionen gegen die Krone. Heute leitet Shaw die Überwachungs- und Infiltrationsoperationen in ganz Westfall, um den Aufstand seines alten Freundes niederzuschlagen."},{t="Augen in allen Königreichen",b="Während Westfall und Elwynn von heimischen Aufständen zerrissen werden, richtet sich Shaws Aufmerksamkeit unentwegt auch nach außen auf tödliche Unbekannte. Als ihn Berichte über bizarre Operationen der Verlassenen in den Östlichen Pestländern erreichten, entsandte er fünf seiner besten Agenten zur Untersuchung. Nur ein einziger kehrte lebend zurück – voller Entsetzen vor sich hin faselnd über „Nathanos“ und einen „Pestrufer“, ehe er im Schlaf starb. Shaw verlässt sich auf vertrauenswürdige, unabhängige Champions, wenn es darum geht, dorthin vorzudringen, wo seine Späher spurlos verschwinden, um das Dunkel an den Grenzen des Königreichs zu durchdringen."}},faq={{q="Wer ist Mathias Shaw?",a="Mathias Shaw ist der Anführer des SI:7, Sturmwinds Geheimdienst und Attentätergilde. Von der Altstadt aus koordiniert er die Spionage und verdeckte Verteidigung des Königreichs unter der Autorität des Throns.",al={"wer ist shaw","anführer des si7","mathias shaw geschichte","meisterspion sturmwind"}},{q="Wo ist Mathias Shaw zu finden?",a="Er befindet sich im Hauptquartier des SI:7 im Viertel Die Altstadt von Sturmwind, abgeschirmt hinter den Militärkasernen.",al={"shaw aufenthaltsort","wo ist mathias shaw","mathias shaw finden"}},{q="Welche Verbindung hat er zu Edwin van Cleef?",a="Shaw und Edwin van Cleef waren Freunde aus Kindertagen. Shaw bildete VanCleef persönlich im Schurkenhandwerk und der Spionage aus, in der Hoffnung, sie würden Seite an Seite arbeiten. Nachdem der Konflikt mit den Steinmetzen in Gewalt umschlug, nutzte VanCleef genau diese Fähigkeiten zur Gründung der Bruderschaft der Defias.",al={"shaw und vancleef","vancleef freund","mathias und edwin"}},{q="Wofür steht Der SI:7?",a="Der SI:7 ist die oberste Geheimdienstorganisation von Sturmwind, spezialisiert auf Überwachung, Aufklärung, Spionage und verdeckte Attentate zum Schutz des Königreichs und der Interessen der Allianz.",al={"was ist der si:7","was bedeutet si7","geheimdienst sturmwind"}},{q="Warum interessiert sich Mathias Shaw für Westfall?",a="Westfall ist die Hochburg der Bruderschaft der Defias. Shaw unterhält aktive Agenten in der Region, um die Aktivitäten der Rebellen auszuspionieren und ihre Pläne gegen Sturmwind zu vereiteln.",al={"shaw westfall","si7 westfall","klavens turm"}},{q="Was geschah mit den Agenten, die Shaw in die Pestländer schickte?",a="Shaw entsandte fünf Agenten, um verdächtige Bewegungen der Verlassenen in den Östlichen Pestländern auszukundschaften. Vier von ihnen kehrten nie zurück, und der einzige Überlebende faselte wirr über „Nathanos“ und einen „Pestrufer“, ehe er Tage später im Schlaf starb.",al={"shaw pestländer quest","fünf kundschafter shaw","marris' siedlung kundschafter"}}},fx={ad27d291={q="Auf wessen Seite steht Mathias Shaw?",a="Meister Mathias Shaw dient der Allianz, dem Haus Wrynn und dem Königreich Sturmwind mit unerschütterlicher Loyalität. Als Anführer des Geheimdienstbüros des Reiches ist jede verdeckte Mission, die er beaufsichtigt, und jeder Spion, den er leitet, der Sicherung Sturmwinds vor innerer Unterwanderung und ausländischen Bedrohungen gewidmet.",al={"fraktion von mathias shaw","wem dient shaw","ist mathias shaw loyal"}},["14719004"]={q="Was will Mathias Shaw?",a="Shaws Hauptanliegen ist es, existenzielle Bedrohungen für Sturmwind zu beseitigen, bevor sie zuschlagen. Er leitet das verdeckte Netzwerk von SI:7, um die Pläne der The Defias Brotherhood zu vereiteln, gefährliche Bewegungen der Verlassenen im Norden zu überwachen und die Informationen zu sammeln, die notwendig sind, um die Sicherheit des Königreichs in einer Ära tiefgreifender politischer Verwundbarkeit zu bewahren.",al={"ziel von mathias shaw","was will shaw","motive von shaw"}},a0b783f7={q="Warum ist Mathias Shaw berühmt oder gefürchtet?",a="Shaw ist im gesamten Königreich als der Meister der Spione und der Meister der Assassinen bekannt. Berühmt für seine überragenden Fähigkeiten in Verstohlenheit, Infiltration und lautloser Tödlichkeit, bedeutet sein weitreichendes Spionagenetzwerk, dass nur sehr wenig im Königreich ohne sein Wissen geschieht – oder ohne das Eingreifen seiner Klingen.",al={"warum ist mathias shaw berühmt","warum ist shaw gefürchtet","meister der assassinen"}}},fp="12,246,14.449.0,18.587.1,24.517.0,20.212.0,32.125.0,41.254.0,25.191.0,43.166.0,57.235.0"}
P.entries["npc:mathredis-firestar"] = {n="Mathredis Feuerstern",s="Mathredis Feuerstern ist ein exzentrischer Blutelfenmagier, der auf dem Flammenkamm in der Brennenden Steppe residiert. Er fertigt mächtige Verzauberungen an, die als geringe Arkanums bekannt sind, und stützt sich dabei auf die Arkanforschungen seines verstorbenen Meisters. Dabei nährt er sich von den Restenergien, die während des Bindungsprozesses freigesetzt werden, um seine Magiesucht zu stillen.",h="Mathredis Feuerstern ist ein exzentrischer Blutelfenmagier, der auf dem Flammenkamm in der Brennenden Steppe...",kw={"arkanum","brennende steppe","dreamseeker","firestar","flammenkamm","buchband","mathredis","telmius"},ang={["class:Mage"]="Magier werden Mathredis' Arkanumsynthese als eine verzweifelte, unberechenbare Methode erkennen, rohe magische Nahrung aus dem Prozess der Gegenstandsbindung zu ziehen."},sec={{t="Das Erbe eines Meisters und Magiesucht",b="Mathredis Feuerstern erlernte das Handwerk der Herstellung von Arkanums – konzentrierten Edelsteinen arkaner Ermächtigung – von seinem Mentor Telmius Dreamseeker. Telmius fand in den uralten Ruinen von Düsterbruch ein grausiges Ende, als er versuchte, den Shen'dralar magische Geheimnisse zu entreißen. Obwohl Telmius diese magischen Bindungen erfand, fehlt Mathredis die Meisterschaft, um die mächtigsten von ihnen herzustellen. Stattdessen spezialisiert er sich auf geringe Arkanums. Für Mathredis ist diese Arbeit weit mehr als eine akademische Übung: Wie alle Blutelfen nach dem Fall des Sonnenbrunnens leidet er unter einem nagenden Hunger nach arkaner Macht. Das Binden von Materialien an uralte Buchbände setzt heftige Entladungen magischer Energie frei, die Mathredis absaugt, um sich selbst zu erhalten."},{t="Die Kunst des Arkanums",b="Abenteurer, die Mathredis die richtigen Wälzer – wie die Buchbände der Konstitution, der Zähigkeit, des Nachsinnens, der Beharrlichkeit oder der Gier – zusammen mit seltenen Reagenzien bringen, werden feststellen, dass er sein Handwerk nur zu gern anbietet. Der Vorgang bindet flüchtige magische Reagenzien direkt an den Text und konzentriert deren Essenz in einem Arkanum, das Kopfbedeckungen oder Beinrüstungen dauerhaft verzaubern kann. Solange Abenteurer die Komponenten liefern, erhält Mathredis sowohl eine Bezahlung als auch die flüchtige arkane Nahrung, nach der er sich so verzweifelt sehnt."}},faq={{q="Wer ist Mathredis Feuerstern?",a="Mathredis Feuerstern ist ein Blutelfenmagier, der am neutralen Außenposten Flammenkamm in der Brennenden Steppe stationiert ist. Er ist ein Arkanist, der in der Lage ist, geringe Arkanums zur Verzauberung von Rüstung zu schmieden.",al={"mathredis lore","wer ist mathredis feuerstern","firestar blutelf"}},{q="Warum erschafft Mathredis Arkanums?",a="Nach der Zerstörung des Sonnenbrunnens leiden Blutelfen unter schweren magischen Entzugserscheinungen. Mathredis ernährt sich von den rohen, verbleibenden magischen Energien, die bei der Erschaffung und Bindung von Arkanums freigesetzt werden, um seine völkische Sucht zu lindern.",al={"warum arkanums herstellen","mathredis motivation","warum buchbände"}},{q="Wer war Telmius Dreamseeker?",a="Telmius Dreamseeker war Mathredis' verstorbener Meister und der ursprüngliche Erfinder der Arkanums. Telmius wagte sich in die Ruinen von Düsterbruch, um Wissen von den Shen'dralar zu erlangen, wurde dort jedoch ermordet, bevor er sein gesamtes Wissen vollständig weitergeben konnte.",al={"telmius","mathredis meister","wer war sein meister"}},{q="Welche Arten von Arkanums kann Mathredis herstellen?",a="Mathredis kann geringe Arkanums der Konstitution, der Zähigkeit, des Nachsinnens, der Beharrlichkeit und der Gier schmieden. Die mächtigsten Arkanums waren nur seinem Meister Telmius bekannt und bleiben außerhalb von Mathredis' Reichweite.",al={"welche arkanums","geringe arkanums","buchband liste"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="Mathrengyl Bärenfährte",s="Mathrengyl Bärenfährte ist ein meisterhafter Druidenlehrer und angesehener Ältester des Zirkels des Cenarius, der in Darnassus in der Enklave des Cenarius weilt. Einst diente er als direkter Assistent von Erzdruide Fandral Hirschhaupt und führt nun junge Allianz-Druiden durch ihre spirituellen Prüfungen, Gestaltwandlungsriten und Pflichten in ganz Kalimdor.",h="Mathrengyl Bärenfährte ist ein meisterhafter Druidenlehrer und angesehener Ältester des Zirkels des Cenarius...",kw={"wassergestalt","bärengestalt","bearwalker","zirkel des cenarius","die enklave des cenarius","darnassus","druide der klaue","druidenlehrer","fandral hirschhaupt","mathrengyl bärenfährte","morrowgrain","teldrassil"},ang={["class:Druid"]="Für Druiden der Allianz ist Mathrengyl ein unverzichtbarer Mentor, der Darnassus mit Mondlichtung verbindet und die Geheimnisse der Bärengestalt, der Wassergestalt sowie heilsamer Kuren gegen tödliche Gifte offenbart.",["faction:Alliance"]="Mathrengyl repräsentiert die besonnene, traditionelle Führung des Zirkels des Cenarius in Darnassus und bildet ein gemäßigtes Gegengewicht zu Fandral Hirschhaupts aggressivem Auftreten.",["race:NightElf"]="Als Vorbild des druidischen Weges der Kaldorei verkörpert Mathrengyl die Hingabe an die Natur und das Gleichgewicht in den Nachwehen des Dritten Krieges und des Wachstums von Teldrassil."},sec={{t="Mentor der Enklave des Cenarius",b="Inmitten der grünen Weiten der Enklave des Cenarius in Darnassus gilt Mathrengyl Bärenfährte als einer der ehrwürdigsten und ausgeglichensten Druiden auf Teldrassil. Er dient als primärer Wegweiser für angehende Allianz-Druiden, beaufsichtigt ihre Zwiesprache mit Mondlichtung und prüft ihre Bereitschaft, die urtümlichen Tiergestalten zu meistern. Da er in seiner eigenen Jugend die intensive, verwirrende Zwiesprache mit dem Großen Bärengeist durchlebt hat, versteht Mathrengyl die Tragweite dieser Riten; persönlich fordert er Initianden dazu auf, ihren Geist gegen den heiligen Mondkin Lunaclaw zu beweisen, ehe er sie auf den Pfad der Druiden der Klaue führt."},{t="Dienst am Erzdruiden",b="Mathrengyl fungiert seit langem als Stellvertreter von Fandral Hirschhaupt, leitet die alltäglichen Angelegenheiten des Zirkels und übernimmt die Rekrutierung für die ehrgeizigen Unternehmungen des Erzdruiden. Als Fandral gewaltige Mengen an Morrowgrain forderte, organisierte Mathrengyl dessen Beschaffung von heimkehrenden Abenteurern, obwohl er insgeheim ein leises Unbehagen über das unnatürliche Wesen der seltsamen Pflanze äußerte. Zudem koordiniert er die Reaktionen der Allianz auf Vorladungen aus Mondlichtung und navigiert die heiklen politischen Verhältnisse des Zirkels des Cenarius, während Fandral seinen Blick auf das südliche Kalimdor und die Pestländer richtet."},{t="Eine weitsichtigere Perspektive",b="Während Staghelm für seinen heftigen Stolz und seine Verachtung gegenüber anderen Völkern berüchtigt ist, beweist Mathrengyl oft einen nachdenklicheren, offeneren Geist. Als Relikte des gefallenen Druiden Mulgris Deepriver in Darnassus eintrafen – der im Kampf gegen die Geißel in den Westlichen Pestländern umgekommen war –, war Mathrengyl zutiefst bewegt, als er erfuhr, dass der Forscher ein Taure war. Im Nachdenken über die gemeinsame Mission des Zirkels des Cenarius sinnierte er im Stillen darüber nach, dass die Tauren sich womöglich gar nicht so weit von den Lehren des Cenarius entfernt hatten, wie der Erzdruide behauptet."}},faq={{q="Wer ist Mathrengyl Bärenfährte?",a="Mathrengyl Bärenfährte ist ein erfahrener Druidenlehrer der Nachtelfen, der in der Enklave des Cenarius in Darnassus stationiert ist. Er wird als einer der ausgeglichensten Weisen Teldrassils verehrt und unterweist Initianden im Gestaltwandeln, in der Beseitigung von Giften und in Pflichten im Auftrag des Zirkels des Cenarius.",al={"wer ist mathrengyl","mathrengyl rolle","bearwalker"}},{q="In welcher Beziehung steht er zu Fandral Hirschhaupt?",a="Mathrengyl diente als direkter Assistent und Stellvertreter von Erzdruide Fandral Hirschhaupt. Während er Fandrals Anweisungen pflichtbewusst ausführte – einschließlich des Sammelns von Morrowgrain und der Delegierung von Aufgaben –, hegt Mathrengyl leise Zweifel an einigen von Fandrals schroffen Ansichten und exzentrischen Vorhaben.",al={"fandral assistent","staghelm und mathrengyl"}},{q="Welche Gestalten hilft Mathrengyl den Druiden zu erlernen?",a="Mathrengyl unterweist junge Druiden nach ihren spirituellen Pilgerreisen nach Mondlichtung, überwacht ihre Zwiesprache mit Lunaclaw zur Erlangung der Bärengestalt und schließt ihre Prüfungen an der Dunkelküste und in Westfall zum Meistern der Wassergestalt ab.",al={"bärengestalt quest darnassus","wassergestalt quest darnassus","druidengestalten mathrengyl"}},{q="Warum sammelt Mathrengyl Morrowgrain?",a="Er unterstützt Erzdruide Fandral Hirschhaupt bei fortlaufenden botanischen Forschungen auf Teldrassil, indem er von Abenteurern angebautes Morrowgrain sammelt. Dennoch hat Mathrengyl zugegeben, sich in Gegenwart der Pflanze zutiefst unwohl zu fühlen.",al={"morrowgrain quest","warum morrowgrain darnassus"}},{q="Wie denkt Mathrengyl über Tauren-Druiden?",a="Im Gegensatz zu Fandral Hirschhaupt, der Tauren-Druiden mit offener Skepsis betrachtet, zeigt sich Mathrengyl nachdenklicher. Nachdem er das Opfer eines Tauren-Druiden im Kampf gegen die Geißel in den Westlichen Pestländern gewürdigt hatte, räumte er ein, dass die Tauren den Lehren von Cenarius womöglich näher stehen, als Fandral wahrhaben will.",al={"tauren druiden","mathrengyl tauren"}},{q="Was tut er mit dem Alptraumsplitter?",a="Wenn Abenteurer Falla Weisenwind einen verderbten Alptraumsplitter bringen, schickt sie sie weiter zu Mathrengyl, der ihn voller Beunruhigung untersucht, da er die schleichende Verderbnis spürt, die den Smaragdgrünen Traum bedroht.",al={"alptraumsplitter mathrengyl","alptraum quest"}}},fx={d00fa4f6={q="Auf wessen Seite steht Mathrengyl Bärenfährte?",a="Mathrengyl ist dem Zirkel des Cenarius und den Nachtelfen von Darnassus gegenüber loyal. Als prominenter Druid of the Claw, der in der Die Enklave des Cenarius residiert, dient er sowohl den Kaldorei als auch dem breiteren druidischen Orden und strebt danach, das Gleichgewicht der Natur in ganz Kalimdor aufrechtzuerhalten.",al={"fraktion von mathrengyl","wem dient mathrengyl","ist mathrengyl allianz"}},["88f66b3d"]={q="Warum ist Mathrengyl Bärenfährte in Darnassus?",a="Mathrengyl lebt in der Die Enklave des Cenarius, um junge Nachtelfdruiden bei ihren heiligen Pflichten anzuleiten und zu unterrichten. Im Herzen der Kaldorei-Gesellschaft auf Teldrassil stehend, hilft er Initianden, Tierformen zu erlernen, sich mit den Geistern der Wildnis zu verbinden und natürliche Krisen anzugehen, die das Reich bedrohen.",al={"warum ist mathrengyl hier","grund für mathrengyl in darnassus","was bringt mathrengyl nach darnassus"}}},fp="21,314,30.623.0,24.566.0,21.521.0,29.262.0,47.285.0,45.226.0,40.234.0,45.289.0,41.199.0"}
P.entries["npc:maur-grimtotem"] = {n="Maur Grimmtotem",s="Maur Grimmtotem war ein Abgesandter, der von The Elder Crone Magatha Grimmtotem in die Tiefen des Flammenschlunds entsandt wurde. Er wurde auf eine zum Scheitern verurteilte diplomatische Mission zu den Troggs geschickt, die die unterirdischen Tunnel unter Orgrimmar bevölkern, und fand durch ihre Hände ein grausames Ende. Heute zeugen nur noch seine Überreste und seine persönliche Tasche in der Dunkelheit von diesem törichten Unterfangen.",h="Maur Grimmtotem war ein Abgesandter, der von The Elder Crone Magatha Grimmtotem in die Tiefen des...",kw={"grimmtotem","magatha","maur","flintauge","orgrimmar","flammenschlund","tasche","trogg"},ang={["faction:Horde"]="Ein tödliches unterirdisches Höhlensystem direkt unter Orgrimmar zu haben ist schon schlimm genug; einzelne Abgesandte loszuschicken, um mit Troggs zu verhandeln, erwies sich als absolut verhängnisvoll für die Sicherheit der Horde.",["race:Tauren"]="Der Grimmtotem-Clan unterhält ein schwieriges Verhältnis zu den anderen Stämmen in Donnerfels, und Maurs bizarres, tödliches Unterfangen in den Trogg-Tunneln verstärkt nur den Argwohn gegenüber Magathas wahren Absichten."},sec={{t="Eine verhängnisvolle Diplomatie",b="Während die meisten in der Horde Troggs als gedankenlose, wilde Bestien betrachten, die unter ihrer Würde stehen, um mit ihnen zu verhandeln, sah The Elder Crone Magatha Grimmtotem dies anders – oder behauptete es zumindest. Sie entsandte Maur Grimmtotem tief in die verschlungenen Höhlen des Flammenschlunds unter Orgrimmar, um einen Friedensversuch mit den unterirdischen Bestien zu wagen. Wie zu erwarten war, scheiterte die Diplomatie. Maur wurde schnell getötet und seine Leiche unter den wachsamen Augen des Trogg-Häuptlings Flintauge in den Höhlen zurückgelassen."},{t="Die Interessen von The Elder Crone",b="Nach Maurs Ableben suchte Magatha Abenteurer, nicht nur um ihn zu rächen, sondern auch, um die persönliche Tasche zu bergen, die er in die Tiefen mitgenommen hatte. Ob Maur wirklich glaubte, dass Frieden mit den Troggs möglich sei, oder ob er nur ein entbehrlicher Spielball in den zwielichtigen Plänen der Grimmtotem-Matriarchin war, bleibt eine offene Frage für diejenigen, die seine Habseligkeiten bergen."}},faq={{q="Wer war Maur Grimmtotem?",a="Maur war ein Taure, der dem Grimmtotem-Clan angehörte. Auf Befehl von Magatha Grimmtotem wagte er sich als Abgesandter zu den Troggs in die Höhlen des Flammenschlunds unter Orgrimmar, wo er getötet wurde.",al={"wer ist maur","maur grimmtotem hintergrundgeschichte","was tat maur"}},{q="Warum versuchte er, mit Troggs zu verhandeln?",a="The Elder Crone Magatha behauptete, sie habe ihn geschickt, um Frieden zu suchen und die Stärke dieser unterirdischen Feinde zu testen. Angesichts der wilden Natur der Troggs vermuten viele, dass Magatha Hintergedanken hatte oder Maur einfach benutzte, um die Tiefen des Flammenschlunds zu erkunden.",al={"warum frieden mit troggs","trogg-diplomatie","warum mit troggs sprechen"}},{q="Wer tötete Maur Grimmtotem?",a="Maur wurde von dem Trogg-Stamm getötet, der im Flammenschlund lebt. Seine Leiche wurde streng bewacht von Flintauge gefunden, dem Häuptling der Troggs im Flammenschlund.",al={"wie starb maur","wer tötete ihn","maurs tod"}},{q="Was geschah mit seinem Körper und seinen Habseligkeiten?",a="Maurs Körper wurde im Flammenschlund in der Nähe von Flintauge zurückgelassen. Abenteurer werden von Rahauro in Donnerfels beauftragt, Maurs verlorene Tasche zu bergen und sie ihm auf der Anhöhe der Ältesten für Magatha Grimmtotem zurückzubringen.",al={"maurs leiche","verlorene tasche","maurs tasche"}}},fx={c7d44e51={q="Auf wessen Seite stand Maur Grimmtotem?",a="Maur antwortete direkt der Ältestenmatrone Magatha Grimmtotem und diente den Interessen des Grimmtotem-Clans. Während die Grimmtotem technisch gesehen zur Horde zählen, aufgrund ihrer unbehaglichen Präsenz auf der Die Anhöhe der Ältesten in Donnerfels, gehörten Maurs Loyalitäten und seine geheime Mission ausschließlich seinem Clan.",al={"fraktion von maur grimmtotem","wem dient maur grimmtotem","maur grimmtotem allianz horde"}},["565aa8ac"]={q="Was wollte Maur Grimmtotem?",a="Maur versuchte, ein Bündnis oder ein friedliches Abkommen mit den Troggs zu schließen, die die Schluchten unter Orgrimmar befallen. Den Anweisungen von Magatha Grimmtotem folgend, wagte er sich in den Der Flammenschlund in der Hoffnung, mit den Kreaturen zu verhandeln, ohne zu wissen, dass ihre wilde und gewalttätige Natur jegliche diplomatische Einigung unmöglich machte.",al={"was hat maur grimmtotem getan","mission von maur grimmtotem","ziel von maur grimmtotem"}},bfc0472b={q="Mit wem war Maur Grimmtotem verbunden?",a="Maur war ein Abgesandter, der von Magatha Grimmtotem entsandt wurde, der Matriarchin des Grimmtotem-Clans, die derzeit auf der Die Anhöhe der Ältesten in Donnerfels residiert. Er führte ihre privaten Pläne unter Orgrimmar aus und hielt seine Mission von der regulären Führung der Horde getrennt.",al={"wer hat maur grimmtotem entsandt","verbindungen von maur grimmtotem","maur grimmtotem magatha"}}},fp="14,352,18.458.0,27.345.1,23.209.0,40.232.0,26.149.0,41.208.0"}
P.entries["npc:maur-raincaller"] = {n="Maur Regenrufer",s="Maur Regenrufer ist ein Tauren, der im Dorf der Bluthufe in Mulgore ansässig ist. Verbunden mit dem natürlichen und spirituellen Leben der Ebenen unterstützt er die Dorfältesten und wacht über lokale Belange, die die Herden und wilden Bestien betreffen.",h="Maur Regenrufer ist ein Tauren, der im Dorf der Bluthufe in Mulgore ansässig ist.",kw={"bloodhoof","maur regenrufer","mazzranache","mulgore","ebenenschreiter","tauren"},ang={["class:Hunter"]="Maur stellt Euch vor eine frühe Jagdprüfung und schickt Euch los, um von den Wölfen, Pumas, Eitsträußen und Sturzfliegern der offenen Ebenen die Teile zu beschaffen, die er zur Heilung von Mazzranaches giftigem Biss benötigt.",["race:Tauren"]="Jungen Tauren, die aus Camp Narache aufbrechen, bietet Maur eine Gelegenheit, das angestammte Land Eures Volkes vor umherstreifenden Raubtieren und unruhigen Bestien zu schützen."},sec={{t="Ein Bewohner des Dorfes der Bluthufe",b="Nahe dem Herzen des Dorfes der Bluthufe an den Ufern des Lake Stonebull gelegen, dient Maur Regenrufer seiner Gemeinschaft, indem er sich um regionale ökologische Belange und Tierangelegenheiten kümmert. Wie viele, die den Namen Raincaller tragen, achtet er aufmerksam auf das Gleichgewicht der Elemente und der Tierwelt in den fruchtbaren Ebenen von Mulgore. Nachdem die Wunde durch den Biss des furchterregenden Schreiters Mazzranach sich entzündet hat, wendet sich Maur an fähige junge Reisende, um die Tierbestandteile zu sammeln, die er für ein Heilmittel benötigt."}},faq={{q="Wer ist Maur Regenrufer?",a="Maur Regenrufer ist ein Taure, der im Dorf der Bluthufe in den saftigen Graslanden von Mulgore lebt. Er fungiert als lokaler Questgeber und beauftragt Abenteurer damit, die unbändige Tierwelt im Umland in Schach zu halten.",al={"maur regenrufer rolle","wer ist maur","maur regenrufer lore"}},{q="Wo kann ich Maur Regenrufer finden?",a="Er steht unter freiem Himmel zwischen den Tipi-Zelten und Herdfeuern des Dorfes der Bluthufe, südlich von Donnerfels am Ostufer des Lake Stonebull gelegen.",al={"maur regenrufer aufenthaltsort","wo ist maur","maur koordinaten"}},{q="Mit welchen Problemen schlägt sich Maur herum?",a="Maur wurde von Mazzranach gebissen, einem furchterregenden Schreiter aus den Geschichten seines Großvaters, und die Wunde hat sich entzündet. Er bittet Abenteurer darum, ihm Teile von den Wölfen, Pumas, Eitsträußen und Sturzfliegern von Mulgore zu bringen, damit er ein Heilmittel herstellen kann.",al={"maur regenrufer quest","mazzranache problem","was will maur"}}},fx={fd24c378={q="Auf wessen Seite steht Maur Regenrufer?",a="Maur Regenrufer ist ein loyaler Tauren des Stammes der Bluthufe und ein Anhänger der Horde. Da er im Dorf der Bluthufe lebt, liegt seine Loyalität fest bei Häuptling Cairne Bluthuf und der Sicherheit der Ebenen von Mulgore.",al={"fraktion von maur regenrufer","ist maur regenrufer horde","wem dient maur"}},["3f2bbb12"]={q="Warum ist Maur Regenrufer hier im Dorf der Bluthufe?",a="Maur lebt im Dorf der Bluthufe, um über die umliegenden Ebenen zu wachen und die Harmonie mit den einheimischen Tieren des Landes zu bewahren. Da die lokale Tierwelt unnatürlich aggressiv und gefährlich wird, bleibt er, um nach Reisenden und Jägern zu suchen, die in der Lage sind, mit Bedrohungen für die Siedlung umzugehen.",al={"warum ist maur in bloodhoof","zweck von maur regenrufer in mulgore","was macht maur hier"}}},fp="15,241,31.493.0,23.204.0,33.168.0,34.243.0"}
P.entries["npc:maurin-bonesplitter"] = {n="Maurin Knochenspalter",s="Maurin Knochenspalter ist ein Gelehrter und Zauberwirker der Verlassenen, der im Geistwandlerposten in Desolace stationiert ist. Er wurde von Keldran ernannt, um die Aktivitäten des Dämonenkults zu überwachen, und nutzt sein tiefes Verständnis antiker Überlieferungen, um die Burning Blade zu zerschlagen. Maurin begegnet den Kultisten mit bloßer Verachtung und betrachtet sie als Narren, die blind gegenüber den dunklen Wesen sind, die ihre Fäden ziehen.",h="Maurin Knochenspalter ist ein Gelehrter und Zauberwirker der Verlassenen, der im Geistwandlerposten in...",kw={"burning blade","verderber","desolace","verlassene","geistwandlerposten","keldran","maurin knochenspalter"},ang={["class:Mage"]="Magier, die den Geistwandlerposten besuchen, können Maurins berechnenden, intellektuellen Ansatz zu schätzen wissen, dunkle Rituale mit spezialisierten Kontern zu entwirren.",["class:Warlock"]="Hexenmeister werden Maurins ausgeprägtes Verständnis für dämonische Pakte erkennen, obwohl seine Verachtung als scharfe Erinnerung an die Gefahr dient, die mit dem Dienen größerer Unholde einhergeht.",["faction:Horde"]="Maurin repräsentiert die spezialisierte Unterstützung der Unterstadt für die westlichen Außenposten der Horde und bringt akademisches Wissen über dunkle Künste ein, um Tauren-Verbündete gegen dämonische Verderbnis zu unterstützen.",["race:Undead"]="Maurin demonstriert, dass die Stärke der Verlassenen ebenso auf listiger arkaner Forschung und dem Ausnutzen von Schwächen des Feindes beruht wie auf schierer nekromantischer Macht."},sec={{t="Ein Gelehrter unter Ausgestoßenen",b="Während der Geistwandlerposten primär als Außenposten der Tauren und der Horde inmitten der trockenen Einöde von Desolace dient, sticht Maurin Knochenspalter als einer seiner wenigen untoten Bewohner hervor. Anstatt eines brutalen Soldaten ist Maurin ein gelehrter Zauberwirker, der über umfassendes Wissen über verbotene Geschichten und okkulte Kräfte verfügt. Seine arkane Begabung und sein scharfer Intellekt erregten die Aufmerksamkeit von Keldran, der ihn in die Region schickte, um die wachsende dämonische Präsenz zu beobachten und gezielte Schläge gegen sie zu koordinieren."},{t="Verachtung für die Burning Blade",b="Maurin richtet den Großteil seiner Bosheit gegen den Kult der Burning Blade, der sich in ganz Desolace festgesetzt hat. Er hegt tiefste Abscheu für deren leichtsinnigen Ehrgeiz und verspottet die Kultisten dafür, dass sie nicht verstehen, dass ihre geliehene Macht sie lediglich als Sklaven an ihre dämonischen Meister bindet. Durch Zauber zum Hellsehen und rituelles Wissen rekrutiert Maurin Abenteurer der Horde, um systematisch die Beschwörungen des Kults zu stören und ihre Operationen in der kargen Landschaft zu untergraben."}},faq={{q="Wer ist Maurin Knochenspalter?",a="Maurin Knochenspalter ist ein Magier und Gelehrter der Verlassenen, der im Geistwandlerposten in Desolace lebt. Er wurde von Keldran ernannt und nutzt sein Wissen über antike Überlieferungen und dunkle Magie, um den Kult der Burning Blade, der in der Region operiert, ausfindig zu machen und zu zerschlagen.",al={"maurin knochenspalter hintergrundwissen","wer ist maurin","maurin desolace"}},{q="Warum hält sich ein Untoter an einem Posten der Tauren auf?",a="Der Geistwandlerposten fungiert als wichtiger Stützpunkt der Horde in Desolace. Maurin wurde dort speziell von Keldran stationiert, da der Außenposten einen idealen Ausgangspunkt bietet, um die Kultisten der Burning Blade, die das umliegende Land durchziehen, zu beobachten und zu bekämpfen.",al={"warum ist maurin am geistwandlerposten","untote in desolace"}},{q="Was ist Maurins Meinung über die Burning Blade?",a="Maurin betrachtet die Burning Blade mit tiefer Verachtung. Er sieht sie als erbärmliche, unwissende Bauern, die wahnhaft glauben, sie würden wahre Macht ausüben, während sie völlig ignorieren, dass sie lediglich Marionetten dämonischer Meister sind.",al={"maurin burning blade","warum hasst maurin die burning blade"}},{q="Wer hat Maurin Knochenspalter nach Desolace geschickt?",a="Maurin wurde von Keldran für seine Rolle in Desolace ernannt. Da Keldran Maurins umfassendes Wissen über Kultpraktiken und antike Überlieferungen erkannte, beauftragte er ihn damit, die Burning Blade aktiv zu behindern und schließlich aus der Zone zu eliminieren.",al={"wer hat maurin geschickt","maurin keldran","maurin vorgesetzter"}},{q="Welche Art von Aufgaben gibt Maurin Abenteurern?",a="Maurin bittet Abenteurer, die Burning Blade zu untersuchen und einen Hatefury Shadowstalker-Skalp sowie einen Orakelkristall zu sammeln. Er nutzt diese Reagenzien, um Sichtschutz-Schutzsprüche zu brechen und den Dämonenfürsten hinter dem Kult zu lokalisieren.",al={"maurin quests","was will maurin"}},{q="Ist Maurin mit dem Zirkel des Cenarius oder der Horde verbunden?",a="Maurin ist ein loyales Mitglied der Verlassenen und dient der Horde. Er operiert strikt vom Lager der Horde im Geistwandlerposten aus und unterstützt Helden der Horde dabei, die Einöden von den Aktivitäten der Kultisten zu reinigen.",al={"ist maurin horde","maurin fraktion"}}},fp="19,361,24.495.0,30.459.0,27.228.0,42.252.0,46.222.0,41.236.0,48.214.0,59.199.0"}
P.entries["npc:maxan-anvol"] = {n="Maxan Anvol",s="Maxan Anvol ist ein Zwergenpriesterlehrer, der in der Brauerei Donnerbräu in Kharanos stationiert ist. Dem Heiligen Licht verschrieben, führt er angehende Zwergenpriester an, während sie lernen, inmitten der eisigen Gefilde von Dun Morogh göttliche Macht zu kanalisieren. Er prüft junge Akolythen, um sicherzustellen, dass sie würdig sind, die Gewänder der Kirche zu tragen.",h="Maxan Anvol ist ein Zwergenpriesterlehrer, der in der Brauerei Donnerbräu in Kharanos stationiert ist.",kw={"desperate prayer","dun morogh","gewänder des lichts","heiliges licht","kharanos","maxan anvol","priesterlehrer","brauerei donnerbräu"},ang={["class:Priest"]="Maxan dient als Euer früher Wegweiser in Dun Morogh, gewährt Euch Zugang zu grundlegender heiliger Disziplin, lehrt Volk-spezifische Gebete wie Desperate Prayer und verleiht Eure ersten formellen Kirchengewänder.",["faction:Alliance"]="Maxan kümmert sich um die körperliche und geistige Bereitschaft der Bergsteiger und Kundschafter der Allianz, die Dun Morogh vor Troggs, Frosttrollen und Bestien der Wildnis schützen.",["race:Dwarf"]="Maxan verkörpert die pragmatische Frömmigkeit von Eisenschmiede und verankert den Glauben der Zwerge dort, wo sich das Volk tatsächlich versammelt: direkt neben den Bierfässern von Kharanos."},sec={{t="Ein Priester in der Kneipe",b="Auch wenn es seltsam erscheinen mag, einen ordinierten Geistlichen des Heiligen Lichtes innerhalb der Brauerei Donnerbräu stationiert zu sehen, passt dies gut zur Zwergenkultur. Kharanos dient als wichtigster Knotenpunkt zwischen dem Coldridgetal und Eisenschmiede, und das örtliche Gasthaus ist der Ort, an dem sich Reisende, Bergsteiger und Akolythen ganz natürlich versammeln. Maxan kümmert sich neben Maßkrügen voller Starkbier um das geistliche Wohlergehen des Weilers und bietet jedem, der durch die Türen tritt, Gebete und Rat an."},{t="Die Gläubigen prüfen",b="Maxan Anvol ist dafür verantwortlich, Novizen unter den Priestern zu prüfen, bevor sie sich in die weite Welt hinauswagen. Er beauftragt Initianden damit, ihre Beherrschung grundlegender heilender Gebete an verwundeten Verteidigern von Dun Morogh unter Beweis zu stellen. Diejenigen, die ihre Hingabe und praktische Kompetenz beweisen, erhalten ihre ersten richtigen Priestergewänder, was formell ihren anerkannten Stand innerhalb der Kirche des Heiligen Lichtes kennzeichnet."}},faq={{q="Wo finde ich Maxan Anvol?",a="Maxan Anvol befindet sich in der Brauerei Donnerbräu, dem wichtigsten Gasthaus und Versammlungsort in der Stadt Kharanos, eingebettet in die zentralen Schneewehen von Dun Morogh.",al={"standort maxan anvol","wo ist maxan","priesterlehrer kharanos"}},{q="Was lehrt Maxan Anvol?",a="Er ist ein Priesterlehrer, der Novizen und fortgeschrittene Priester in Zaubern der heiligen Besserung, Schattenkontrolle und göttlichen Schutz unterweist. Er weist Zwergenpriester außerdem in spezialisierte Anrufungen wie Desperate Prayer ein.",al={"was lehrt er","zauber maxan anvol"}},{q="Warum hält sich ein heiliger Priester in einer Brauerei auf?",a="In der Zwergengesellschaft drehen sich Leben, Gemeinschaft und Feiern um das Brauen und Tavernen. Die Brauerei Donnerbräu fungiert als öffentliches Forum, Rathaus und Rastplatz für Reisende von Kharanos. Maxan bleibt dort, wo er die einfachen Leute, Wachen und vorbeiziehenden Reisende erreichen kann, die geistlichen Trost benötigen.",al={"warum brennerei","priester in einer bar"}},{q="Bietet Maxan Anvol besondere Aufgaben an?",a="Ja. Er prüft angehende Priester mit Aufgaben wie 'Dem Licht geneigt' und 'Gewänder des Lichts' und schickt sie los, um verletzte Bergsteiger im Schnee zu heilen. Der erfolgreiche Abschluss dieser Aufgaben bringt dem Initianden seine offiziellen Akolythengewänder ein.",al={"maxan quests","gewänder des lichts"}},{q="Was sagt er zu Nicht-Priestern?",a="Er warnt andere Abenteurer davor, dem Heiligen Licht niemals den Rücken zu kehren, und erinnert sie daran, dass göttliche Gnade eines Tages vielleicht genau das Einzige ist, das ihnen im Kampf das Leben rettet.",al={"maxan dialog","maxan zitat"}},{q="Können Gnome von Maxan Anvol lernen?",a="Obwohl sich Gnome als Kultur nicht von Natur aus als Priester ausbilden lassen, heißt Maxan alle Mitglieder der Allianz willkommen, die Weisheit suchen, und bildet jeden Priester aus, der sich dem Licht verschrieben hat.",al={"können gnome mit ihm sprechen","gnom priesterlehrer"}}},fx={["32034ea0"]={q="Wer ist Maxan Anvol?",a="Maxan Anvol ist ein Zwergenpriester des Heiligen Lichts, der in Kharanos stationiert ist. Er dient als Ausbilder für angehende Anhänger in Dun Morogh und testet junge Akolythen auf ihre Disziplin und Gemeinschaft mit dem Licht, bevor er ihnen Gewänder gewährt, die ihrem Stand in der Kirche entsprechen.",al={"wer ist maxan","geschichte von maxan anvol","priesterausbilder kharanos"}},["310c3ecc"]={q="Auf wessen Seite steht Maxan Anvol?",a="Er steht loyal zum Königreich Eisenschmiede, dem Heiligen Licht und der Großen Allianz. Er widmet seinen Dienst dem Schutz der lokalen Bevölkerung von Dun Morogh und der Vorbereitung neuer Priester darauf, den Glauben in den Ländern der Allianz aufrechtzuerhalten.",al={"fraktion von maxan","ist maxan allianz","loyalität von maxan anvol"}},["1141108e"]={q="Was will Maxan Anvol?",a="Maxan versucht, die Hingabe an das Heilige Licht zu fördern und sicherzustellen, dass unerfahrene Priester gründlich auf die Prüfungen der Welt vorbereitet sind. Er testet aufstrebende Schüler, um sicherzustellen, dass sie ihrer heiligen Gewänder würdig sind, während er alle Passanten daran erinnert, niemals die Gnade des Lichts aufzugeben.",al={"ziel von maxan anvol","was will maxan","motiv von maxan anvol"}}},fp="11,322,19.445.0,20.399.0,29.164.0,28.218.0,49.282.0,41.243.0,32.178.0,34.188.0"}
P.entries["npc:maybell-maclure"] = {n="Maybell Maclure",s="Maybell Maclure ist eine junge Frau, die in den Weinbergen der Maclures im Wald von Elwynn lebt. Trotz einer erbitterten, langjährigen Fehde zwischen ihrer Familie und den benachbarten Steinfelds hat sie sich heimlich in Tommy Joe Steinfeld verliebt.",h="Maybell Maclure ist eine junge Frau, die in den Weinbergen der Maclures im Wald von Elwynn lebt.",kw={"liebende","maclure","maybell","steinfeld","tommy joe","weinberge"},ang={["faction:Alliance"]="Für Abenteurer der Allianz, die durch den Wald von Elwynn reisen, ist Maybells Romanze eine Erinnerung daran, dass persönliche Sorgen und uralter Groll selbst in den Kernlanden des Königreichs fortbestehen."},sec={{t="Unglücklich verliebt in den Weinbergen",b="Das Leben in den Weinbergen der Maclures ist von endloser Arbeit und einem anhaltenden Groll gegen die benachbarte Familie Steinfeld geprägt. Mittendrin steht Maybell Maclure, die sich unsterblich in Tommy Joe Steinfeld verliebt hat, den jungen Erben des rivalisierenden Hofes. Getrennt durch wachsame Verwandte und alte familiäre Ressentiments sehnt sich Maybell nach jeder Gelegenheit, abseits der neugierigen Blicke ihrer Sippe mit Tommy Joe in Kontakt zu treten."},{t="Ein Gebräu für die wahre Liebe",b="Da Maybell die Grenze zwischen den Höfen nicht offen überqueren kann, ist sie auf mitfühlende Reisende und die Führung von Oma Steinfeld angewiesen. Mit der Hilfe des örtlichen Alchemisten von Goldhain, William Pestle, wird ein Unsichtbarkeitsschnaps gebraut. Durch das Trinken dieses verbotenen Tranks kann Maybell unbemerkt vom Gehöft der Maclures entkommen und unten am Flussufer kostbare Momente mit Tommy Joe verbringen."}},faq={{q="Warum können Maybell und Tommy Joe einander nicht sehen?",a="Die Familien Maclure und Steinfeld hegen seit Jahren eine erbitterte Rivalität. Da beide Haushalte jeglichen Kontakt zwischen den Sippen verbieten, müssen Maybell und Tommy Joe ihre Romanze absolut geheim halten, um nicht den Zorn ihrer Verwandten auf sich zu ziehen.",al={"warum familienfehde","maclure steinfeld fehde","warum können sie nicht zusammen sein"}},{q="Was hindert Maybell daran, das Weingut zu verlassen?",a="Ihre Familie bewacht sie wegen der Fehde mit den Steinfelds streng. Sie braucht Hilfe, um einen Weg zu finden, Tommy Joe zu treffen, ohne deren Aufmerksamkeit zu erregen.",al={"wie schleicht maybell sich heraus","unsichtbarkeitstrank elwynn","wie trifft sie tommy"}},{q="Wo trifft Maybell Tommy Joe?",a="Tommy Joe wartet am Flussufer an der Grenze zwischen den Weinbergen der Maclures und dem Hof der Steinfelds, verborgen vor dem direkten Blick beider Gehöfte.",al={"treffpunkt","wo treffen sie sich","wo ist tommy joe"}},{q="Wer hilft Maybell bei ihrer Romanze?",a="Oma Steinfeld erweist sich als verständnisvoll gegenüber der Not der Liebenden und schickt hilfsbereite Abenteurer zu William Pestle, dem Alchemisten in Goldhain, der die Mittel für ihr heimliches Stelldichein bereitstellt.",al={"wer hilft maybell","steinfeld helfer"}}},fx={c4338ded={q="Wer ist Maybell Maclure?",a="Maybell Maclure ist eine junge menschliche Frau, die in den Weinbergen der Maclures im Wald von Elwynn lebt. Sie steckt inmitten einer erbitterten, langjährigen Fehde zwischen ihrer Familie und deren Nachbarn, den Steinfelds, nachdem sie sich unsterblich in Tommy Joe Steinfeld verliebt hat.",al={"wer ist maybell","wer ist maybell maclure","maybell maclure hintergrundgeschichte"}},["9f94442c"]={q="Auf wessen Seite steht Maybell Maclure?",a="Sie ist eine loyale Untertanin der Allianz und eine Tochter des Hauses Maclure. Wenn es jedoch um die kleinliche, bittere Rivalität zwischen den Maclures und den Steinfelds geht, lehnt sie diesen Hass völlig ab und stellt ihre Liebe zu Tommy Joe über den Groll ihrer Familie.",al={"ist maybell allianz","auf wessen seite steht maybell","maybell fraktion"}},cbd5fa72={q="Was möchte Maybell Maclure?",a="Maybell möchte nichts sehnlicher, als mit Tommy Joe Steinfeld zusammen zu sein. Da ihre Familien einen intensiven gegenseitigen Hass hegen, sucht sie die Hilfe von verständnisvollen Reisenden und vertrauten Verbündeten, um Wege zu finden, ihn heimlich zu treffen, ohne dabei erwischt zu werden.",al={"was möchte maybell","maybell maclure ziel","warum braucht maybell hilfe"}},b079e731={q="Warum ist Maybell Maclure hier?",a="Maybell wohnt in den Weinbergen der Maclures, dem Anwesen ihrer Familie im südlichen Wald von Elwynn. Sie bleibt unter den wachsamen Augen ihrer Verwandten auf dem Gelände des Weinguts beschränkt und hofft auf eine Gelegenheit, sich davonzuschleichen und ihren Geliebten zu sehen.",al={"warum ist maybell maclure hier","warum ist maybell in den weinbergen"}},["26be6d7a"]={q="Mit wem ist Maybell Maclure verbunden?",a="Maybell ist Teil der Winzerfamilie Maclure. Sie ist romantisch mit Tommy Joe Steinfeld verbunden, dem Erben der rivalisierenden Farm der Steinfelds, und pflegt geheime Verbindungen zu Oma Steinfeld, die die heimliche Romanze des jungen Paares unterstützt.",al={"beziehungen von maybell maclure","mit wem ist maybell verwandt","maybell verbindungen"}}},fp="15,230,29.425.0,26.383.1,47.236.0,48.155.1,34.152.0,35.189.1"}
P.entries["npc:mebok-mizzyrix"] = {n="Mebok Mizzyrix",s="Mebok Mizzyrix ist ein geschäftstüchtiger Goblin-Unternehmer, der in der Hafenstadt Ratschet ansässig ist. Stets darauf bedacht, bizarre Reagenzien aus der Wildnis zu Geld zu machen, heuert er durchreisende Abenteurer an, um ungewöhnliche Flora und Fauna aus dem gesamten Brachland und darüber hinaus zu sammeln. Sein berüchtigtstes Projekt besteht darin, aus Raptorhörnern ein kommerzielles, intelligenzsteigerndes Getränk zu brauen.",h="Mebok Mizzyrix ist ein geschäftstüchtiger Goblin-Unternehmer, der in der Hafenstadt Ratschet ansässig ist.",kw={"brachland","blaulaubknollen","mebok","mizzyrix","raptorhörner","ratschet","klugheitstränke","steamwheedle"},ang={["faction:Alliance"]="Wer das Schiff von Beutebucht ins neutrale Ratschet verlässt, erhält als Entdecker der Allianz Zugang zu Meboks Aufgaben, ohne feindselige Wachen fürchten zu müssen.",["faction:Horde"]="Bei der Durchreise durch Ratschet auf dem Weg durch das Brachland bietet sich Hordereisenden eine einfache Einnahmequelle durch die Beseitigung gefährlicher Bestien in der Nähe.",["profession:Cooking"]="Kulinarisch interessierte Abenteurer dürften Meboks Essens- und Getränkerezepturen bestenfalls fragwürdig finden, angesichts seines Beharrens darauf, gemahlenes Raptorhorn zu brauen.",["profession:Herbalism"]="Meboks Faszination für sonderbare Exemplare wie Blaulaubknollen veranschaulicht die wildere, kommerzielle Seite beim Sammeln der einzigartigen Flora Kalimdors."},sec={{t="Ein geschäftstüchtiger Alchemist",b="Von der geschäftigen, neutralen Hafenstadt Ratschet aus agierend, verkörpert Mebok Mizzyrix den klassischen Geist des rastlosen Opportunismus des Steamwheedle-Kartells. Während Ratschet Seefahrer, Piraten und Händler jeder Couleur bedient, richtet Mebok seinen scharfen Blick auf die Wildnis Kalimdors. Statt gewöhnliches Erz abzubauen oder alltägliche Stoffe zu handeln, sucht er nach seltenen biologischen Kuriositäten, von denen er glaubt, dass sie sich zu äußerst lukrativen Gebräuen und Handelsgütern verarbeiten lassen."},{t="Das Streben nach Klugheitstränken",b="Meboks wichtigstes kommerzielles Vorhaben ist ein firmeneigener 'Klugheitstrank', der den Intellekt jedes Konsumenten künstlich steigern soll. Überzeugt davon, dass die natürliche List und Wildheit der einheimischen Raptoren von den Hörnern herrührt, die ihre Schnauzen krönen, beauftragt Mebok Jäger damit, im gesamten Brachland intakte Hörner zu erbeuten. Für ihn stehen Ethik und Geschmack hinter dem reinen Marktpotenzial zurück – solange zahlende Kunden glauben, dass das Gebräu Wirkung zeigt."},{t="Exotische Reagenzien und Flora",b="Neben Elixieren aus Raptorenteilen besteht bei Mebok eine ständige Nachfrage nach weiteren bizarren Exemplaren. Von der Beschaffung flüchtiger Eier der Kluftmoosspinnen bis hin zum Auftrag, seltene, tief im Dornengestrüpp vom Kral der Klingenhauer vergrabene Blaulaubknollen zu bergen, führen seine Unternehmungen unerschrockene Söldner immer wieder in gefährliche Gefilde. Wenn ein Organismus seltsame Eigenschaften besitzt, ist sich Mebok sicher, dass es einen Weg gibt, ihn in Flaschen abzufüllen und zu verkaufen."}},faq={{q="Wer ist Mebok Mizzyrix?",a="Mebok Mizzyrix ist ein Goblinhändler und alchemistischer Ränkeschmied in der neutralen Hafenstadt Ratschet im Brachland. Er heuert Abenteurer an, um seltsame Wildtiere und Pflanzenteile zu beschaffen, um seine kommerziellen Projekte voranzutreiben.",al={"wer ist mebok","mebok mizzyrix lore","ratschet goblin mebok"}},{q="Was sind Klugheitstränke?",a="Klugheitstränke sind experimentelle, intelligenzsteigernde Stärkungsmittel, die Mebok Mizzyrix brauen und verkaufen möchte. Er glaubt, dass das Zermahlen der Hörner kluger Raptoren aus dem Brachland deren scharfe Instinkte und List auf den Trinker überträgt.",al={"klugheitstrank","klugheitstränke quest","raptorhorn trank"}},{q="Wo ist Mebok Mizzyrix zu finden?",a="Er steht zwischen den Gebäuden in der Hafenstadt Ratschet an der Ostküste des Brachlands und ist sowohl für Reisende der Horde als auch der Allianz zugänglich.",al={"mebok standort","wo ist mebok","mebok mizzyrix finden"}},{q="Warum will Mebok Raptorhörner haben?",a="Mebok stellt die Hypothese auf, dass die schlaue Intelligenz der im Brachland umherstreifenden Raptoren in ihren Hörnern konzentriert ist. Er plant, sie zu pulverisieren und als primären Wirkstoff in seinen intelligenzsteigernden Getränken einzusetzen.",al={"warum raptorhörner","raptorhorn zweck","was macht mebok mit hörnern"}},{q="Warum schickt Mebok Leute in den Kral der Klingenhauer?",a="Er wirbt Abenteurer an, um in den Kral der Klingenhauer vorzudringen und mithilfe eines ausgebildeten Schnüfflers Blaulaubknollen auszugraben, da er die seltene Pflanze wegen ihrer wertvollen und ungewöhnlichen botanischen Eigenschaften begehrt.",al={"warum der kral von razorfen","mebok kral quest","blaulaubknollen kral"}},{q="Arbeitet Mebok für die Horde oder die Allianz?",a="Mebok ist ein unabhängiges Mitglied des Steamwheedle-Kartells im neutralen Ratschet. Er ist allein dem Profit verpflichtet und handelt sowie verhandelt gerne mit Mitgliedern beider Fraktionen.",al={"ist mebok horde","ist mebok allianz","mebok fraktion"}}},fx={["55f078f0"]={q="Was möchte Mebok Mizzyrix?",a="Mebok ist davon angetrieben, seltsame neue alchemistische Kreationen zu brauen – vor allem sein experimentelles \"schlaues Getränk\". Um seine bizarren Rezepte zu perfektionieren, schickt er Abenteurer auf die Suche nach eigenartigen Zutaten durch das Brachland und seine gefährlichen Tiefen, von intakten Raptor Horns bis hin zu seltenen Wurzelproben und Spinneneiern.",al={"mebok möchte","was braucht mebok","mebok mizzyrix ziel"}},c521482b={q="Warum ist Mebok Mizzyrix in Ratschet?",a="Ratschet ist die wichtigste Hafenstadt für ehrgeizige Goblins, die schnellen Zugang zu den wilden Ressourcen von Kalimdor benötigen. Von seiner Basis aus kann Mebok leicht ankommende Söldner beider Fraktionen anheuern, um sich in die gefährliche Savanne zu wagen und die wilden Exemplare zu ernten, die er für seine Experimente benötigt.",al={"warum ist mebok hier","mebok ratschet grund","mebok mizzyrix brachland"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {n="Melithar Hirschhaupt",s="Melithar Hirschhaupt ist ein Nachtelf, der direkt außerhalb von Aldrassil in Laubschattental, der Startlichtung von Teldrassil, stationiert ist. Er unterstützt junge Nachtelfen-Abenteurer bei ihren ersten Schritten ihrer Ausbildung, indem er sie zu nahegelegenen Ausbildern schickt und sich um kleinere örtliche Störungen kümmert. Obwohl er den prominenten Nachnamen Staghelm mit Erzdrude Fandral Hirschhaupt teilt, bleibt seine genaue Verbindung zu dem herrschenden Druiden unbestätigt.",h="Melithar Hirschhaupt ist ein Nachtelf, der direkt außerhalb von Aldrassil in Laubschattental, der...",kw={"aldrassil","melithar","laubschattental","siegel","staghelm","teldrassil","lehrer"},ang={["race:NightElf"]="Für Nachtelfen, die ihre Reise in Laubschattental antreten, ist Melithar eines der allerersten Gesichter, denen sie nach Verlassen des schützenden Aldrassil begegnen."},sec={{t="Ein Führer bei Aldrassil",b="Direkt vor dem Eingang zum gewaltigen Geäst von Aldrassil stehend, dient Melithar als erste Anlaufstelle für Nachtelfen, die in die Welt hinausziehen. Er leitet die neu erwachten Jugendlichen, die verschiedene Siegel bei sich tragen, zu ihren jeweiligen Klassenlehrern weiter, um sicherzustellen, dass sie eine angemessene Ausbildung in den kriegerischen und mystischen Künsten erhalten. Über diese verwaltende Führung hinaus wacht Melithar über das unmittelbare Gebiet von Laubschattental und bittet um Hilfe, um sich um schelmische einheimische Wildtiere und kleinere wichtelhafte Übergriffe zu kümmern, die den Frieden des Heiligtums bedrohen."},{t="Der Name Staghelm",b="Den Nachnamen Staghelm zu tragen erregt unweigerlich Aufmerksamkeit, da Erzdruide Fandral Hirschhaupt derzeit nach dem Verschwinden von Malfurion Sturmgrimm in den Smaragdgrünen Traum den Zirkel des Cenarius in Darnassus anführt. Dennoch prahlt Melithar nicht nach außen hin mit einem erhabenen Erbe, noch spricht er aktiv über seine Abstammung. Ob er ein entfernter Verwandter der ehrwürdigen Familie des Erzdruiden ist oder lediglich einen alten Kaldorei-Familiennamen teilt, Melithar gibt sich damit zufrieden, bescheidene Pflichten an den Wurzeln von Aldrassil zu erfüllen."}},faq={{q="Wer ist Melithar Hirschhaupt?",a="Melithar Hirschhaupt ist ein Nachtelfen-Questgeber, der auf dem Pfad außerhalb des Geästs von Aldrassil in Laubschattental stationiert ist. Er hilft neu angekommenen Nachtelfen-Abenteurern, sich zu orientieren, und weist ihnen den Weg zu ihren Mentoren.",al={"melithar","wer ist melithar","melithar laubschattental"}},{q="Ist Melithar mit Erzdruide Fandral Hirschhaupt verwandt?",a="Ihre genaue Verwandtschaft ist unbekannt. Obwohl sie den Namen Staghelm teilen, äußert sich Melithar nie dazu, ob er mit Erzdruide Fandral Hirschhaupt oder dessen verstorbenem Sohn Valstann verwandt ist. Es bleibt unklar, ob er ein entfernter Verwandter ist oder einfach einen gebräuchlichen Kaldorei-Nachnamen trägt.",al={"fandral verwandter","fandral bruder","familie staghelm"}},{q="Welche Rolle spielt Melithar für neue Abenteurer?",a="Unerfahrene Nachtelfen werden mit ihren einführenden Siegeln zu Melithar geschickt. Melithar nimmt diese Abzeichen entgegen und weist jeden Neuling an den entsprechenden Ausbilder im Inneren von Aldrassil, um ihre formelle Klassenausbildung zu beginnen.",al={"melithar quests","siegelquests","was macht melithar"}},{q="Wo kann ich Melithar Hirschhaupt finden?",a="Er steht direkt auf dem hölzernen Rampenweg vor dem Eingang von Aldrassil, im Zentrum von Laubschattental auf Teldrassil.",al={"melithar standort","wo ist melithar","melithar hirschhaupt finden"}}},fx={de95e555={q="Auf wessen Seite steht Melithar Hirschhaupt?",a="Melithar steht an der Seite der Nachtelfen von Darnassus und der Allianz. Stationiert im Laubschattental direkt vor Aldrassil, unterstützt er junge Nachtelfen-Verteidiger und Rekruten bei ihren ersten Schritten, um den Weltenbaum zu beschützen.",al={"melithar fraktion","wem dient melithar","melithar loyalität"}},["154c9e4a"]={q="Was möchte Melithar Hirschhaupt?",a="Melithar arbeitet daran, das Laubschattental zu beschützen und Teldrassil von aufkeimenden Bedrohungen zu säubern. Er bittet ankommende Abenteurer, sich um Schädlinge in der Nähe und lästige Wildtiere zu kümmern sowie verlorene Besitztümer wiederzubeschaffen, die von örtlichen Grells und Waldeindringlingen gestohlen wurden.",al={"melithar ziel","was macht melithar","melithar aufgabe"}},f95cde78={q="Warum ist Melithar Hirschhaupt hier?",a="Melithar ist direkt außerhalb von Aldrassil im Laubschattental stationiert, um über den Ast zu wachen und angehende Nachtelfen-Abenteurer anzuleiten. Er bietet erste Führung und beauftragt neue Verteidiger damit, die örtliche Verderbnis einzudämmen und die Harmonie in Teldrassils heiliger Gärtnerei zu bewahren.",al={"warum ist melithar im laubschattental","melithar standortgrund"}}},fp="17,406,20.531.0,17.508.0,25.218.0,50.260.0,49.215.0,35.115.0"}
P.entries["npc:melor-stonehoof"] = {n="Melor Steinhuf",s="Melor Steinhuf ist ein erfahrener Jäger der Tauren, der auf der Anhöhe der Jäger in Donnerfels stationiert ist. Als Mentor in den Wegen der Jagd stellt er das Fährtenlesegeschick und den Mut der Jäger der Horde auf die Probe, indem er sie auf die gefährlichsten Raubtiere im Brachland und in Tausend Nadeln ansetzt.",h="Melor Steinhuf ist ein erfahrener Jäger der Tauren, der auf der Anhöhe der Jäger in Donnerfels stationiert...",kw={"schlammwühler","frostmaw","die anhöhe der jäger","der weg der jäger","melor","sergra dunkeldorn","stahlbiss","stonehoof","donnerfels"},ang={["class:Hunter"]="Melor ist einer der typischen Questgeber für Jäger der Horde und führt Euch durch Riten des Fährtenlesens, die den heiligen Pfad der Jäger verkörpern.",["faction:Horde"]="Melor sorgt dafür, dass Krieger und Pirscher in der gesamten Horde gegen die wilden Bestien gestählt werden, die Siedlungen von Mulgore bis Tausend Nadeln bedrohen.",["race:Tauren"]="Hoch auf der Anhöhe der Jäger stationiert, verkörpert Melor die tiefe Ehrfurcht Eures Volkes vor der Jagd – sowohl als Prüfung der Stärke als auch als Akt des Gleichgewichts mit der Erdenmutter."},sec={{t="Ein Mentor der Wildnis",b="Hoch oben auf der luftigen Weite der Anhöhe der Jäger überblickt Melor Steinhuf die Ebenen darunter mit geübtem Auge. Die Kunst der Jagd ist den Tauren heilig, eng verflochten mit dem Überleben, dem spirituellen Gleichgewicht und dem Respekt vor den größten Raubtieren der Natur. Melor sorgt dafür, dass jene, die im Namen der Horde Bogen und Klinge tragen, dieses Gleichgewicht verstehen, und leitet vielversprechende Pirscher an, ihr Handwerk durch Prüfungen gegen legendäre Bestien zu meistern."},{t="Prüfungen der Jagd",b="Melor fordert Jäger heraus, legendäre und schwer fassbare Bestien aufzuspüren, die die Wildnis terrorisieren. Er schickt Fährtenleser über die Ebenen des Brachlands – von der Unterstützung der Jägerin Sergra Dunkeldorn beim Wegekreuz bis hin zur Jagd auf Stahlbiss, eine gerissene und bösartige Hyäne in Tausend Nadeln. Durch diese Prüfungen beweisen Jäger, dass sie die tödlichsten Kreaturen des zentralen Kalimdor überlisten und bezwingen können."},{t="Die Monster ferner Länder",b="Jene, deren Fähigkeiten über das Brachland hinausreichen, weist Melor den Weg in ferne Lande. Er beauftragt erfahrene Jäger damit, Bestien von furchterregender Stärke zu erlegen, darunter Schlammwühler, ein uraltes Krokiliskenungetüm, das in den Sümpfen der Düstermarschen lauert, und den wilden Yeti Frostmaw aus dem Alteracgebirge. Jede Jagd dient der Prüfung, ob ein Pirscher den Weg der Jäger wahrhaft gemeistert hat."}},faq={{q="Wo kann ich Melor Steinhuf finden?",a="Melor Steinhuf befindet sich auf der Anhöhe der Jäger in der Stadt Donnerfels. Die Anhöhe der Jäger ist die östlichste erhöhte Mesa der Taurenhauptstadt und über Hängebrücken von der zentralen Totem-Mesa aus erreichbar.",al={"melor steinhuf aufenthaltsort","wo ist melor","melor steinhuf koordinaten"}},{q="Welche Quests bietet Melor Steinhuf an?",a="Melor bietet eine Reihe von Jagdherausforderungen für Abenteurer mittlerer Stufen an. Dazu gehört es, Spieler zu Sergra Dunkeldorn ins Brachland zu schicken, die wilde Hyäne Stahlbiss zu jagen und furchterregende Bestien in ferneren Gebieten aufzuspüren, wie etwa das Krokiliskenungetüm Schlammwühler in den Düstermarschen und den Yeti Frostmaw im Alteracgebirge.",al={"melor quests","was macht melor","melor steinhuf questreihe"}},{q="Warum schickt Melor Jäger hinter Stahlbiss her?",a="Stahlbiss ist eine berüchtigt bösartige und gerissene Hyäne, die Tausend Nadeln durchstreift. Melor entsendet fähige Jäger, um sie als Prüfung von Geschicklichkeit, Ausdauer und Mut in der Wildnis aufzuspüren und zu erlegen.",al={"warum stahlbiss töten","stahlbiss quest lore"}},{q="Was ist Schlammwühler?",a="Schlammwühler ist ein ungewöhnlich großes und aggressives Krokiliskenungetüm, das die Sümpfe der Düstermarschen durchstreift. Melor fordert Jäger heraus, es als Ritus ihres Könnens zu erlegen.",al={"wer ist schlammwühler","schlammwühler lore","schlammwühler bestie"}},{q="Muss man der Jägerklasse angehören, um seine Quests anzunehmen?",a="Nein. Obwohl seine Prüfungen die Philosophie des Weges der Jäger verkörpern und thematisch zur Jägerklasse passen, bietet Melor seine Jagdverträge jedem fähigen Abenteurer an, der für die Horde kämpft.",al={"melor nur jäger","können andere klassen melor quests machen"}},{q="Wer ist Sergra Dunkeldorn und warum schickt Melor Euch zu ihr?",a="Sergra Dunkeldorn ist eine Orcjägerin, die beim Wegekreuz im Brachland stationiert ist. Melor leitet vielversprechende Jäger zu ihr, damit sie dabei helfen, die unbändigen Raubtiere der Ebenen zu bändigen und von einer weiteren Veteranin der Wildnis zu lernen.",al={"melor sergra verbindung","sergra dunkeldorn quest"}}},fx={c4d46d44={q="Wer ist Melor Steinhuf?",a="Melor Steinhuf ist ein angesehener Tauren-Jäger, der auf der Anhöhe der Jäger in Donnerfels stationiert ist. Er widmet sich den Traditionen der Jagd und der Bewahrung des Gleichgewichts und leitet vielversprechende Spurensucher durch ganz Kalimdor, wobei er ihre Stärke und Gerissenheit gegen die wildesten Raubtiere des Landes auf die Probe stellt.",al={"wer ist melor steinhuf","melor steinhuf hintergrundgeschichte","wer ist melor"}},d59647ad={q="Auf wessen Seite steht Melor Steinhuf?",a="Melor ist den Tauren-Stämmen und der Horde treu. Von seinem Platz hoch oben in Donnerfels dient er seinem Volk, indem er Jäger der Horde betreut und Maßnahmen gegen gefährliche Bestien koordiniert, die Reisende und Siedlungen im Brachland und darüber hinaus bedrohen.",al={"melor steinhuf fraktion","ist melor horde","melor steinhuf loyalität"}},["2962cc83"]={q="Was möchte Melor Steinhuf?",a="Melor versucht, Jäger in den alten Wegen des Anschleichens, Spurenlesens und des Ehren ihrer Beute zu unterweisen. Er möchte, dass sich geschickte Spurensucher beweisen, indem sie berüchtigte Bestien wie Steelsnap, Deadmire und Frostmaw jagen, und er arbeitet mit Verbündeten wie Sergra Darkthorn zusammen, um ihren Mut auf die Probe zu stellen.",al={"melor steinhuf ziel","was möchte melor","melor steinhuf zweck"}},["6e964c49"]={q="Warum ist Melor Steinhuf hier in Donnerfels?",a="Melor hat sein Zuhause auf der Anhöhe der Jäger, dem natürlichen Versammlungsort für die Scharfschützen, Fallensteller und Spurensucher der Tauren. Von diesem Aussichtspunkt aus kann er ankommende Jäger beobachten, Rat anbieten und erprobte Krieger in die Wildnis entsenden, um das Land zu beschützen.",al={"warum ist melor auf der anhöhe der jäger","warum ist melor in donnerfels","melor steinhuf standortzweck"}}},fp="15,283,21.435.0,18.388.0,29.374.0,33.196.0,39.333.0,44.185.0,17.157.0,52.189.0,60.225.0"}
